# ============================================================
# POWERSHELL LANGUAGE MODE PREFLIGHT
# PAX requires FullLanguage mode for its .NET and runtime features. Stop before
# creating a bootstrap log, loading modules, authenticating, or writing output
# when an endpoint application-control policy places this process in another mode.
# ============================================================
$currentLanguageMode = "$($ExecutionContext.SessionState.LanguageMode)"
if ($currentLanguageMode -ne 'FullLanguage') {
	Microsoft.PowerShell.Utility\Write-Host ''
	Microsoft.PowerShell.Utility\Write-Host 'PAX cannot run in the current PowerShell language mode.' -ForegroundColor Red
	Microsoft.PowerShell.Utility\Write-Host ("Current mode: {0}" -f $currentLanguageMode) -ForegroundColor Yellow
	Microsoft.PowerShell.Utility\Write-Host ''
	Microsoft.PowerShell.Utility\Write-Host 'PAX requires PowerShell running in FullLanguage mode.'
	Microsoft.PowerShell.Utility\Write-Host 'This setting is commonly controlled by your organization through WDAC or AppLocker policy.'
	Microsoft.PowerShell.Utility\Write-Host 'Contact your IT or security team for an approved PowerShell environment or to have PAX allowlisted.'
	Microsoft.PowerShell.Utility\Write-Host 'ExecutionPolicy Bypass does not change PowerShell language mode.'
	Microsoft.PowerShell.Utility\Write-Host ''
	exit 1
}

# ============================================================
# CULTURE GUARD — DO NOT REMOVE
# Pin the main thread to InvariantCulture for the entire run.
# Rationale: .NET's custom date/time format string treats ':' not as a
# literal colon but as the culture's DateTimeFormatInfo.TimeSeparator.
# On da-DK and fi-FI hosts TimeSeparator is '.', so an unscoped
# .ToString('yyyy-MM-ddTHH:mm:ss.fffZ') produces 'T20.35.42.000Z',
# which the Purview audit query endpoint rejects with HTTP 500.
# Setting CurrentCulture here makes every downstream .ToString(format),
# Get-Date -Format, and ParseExact($x,$fmt,$null) call in the main
# thread emit / consume invariant ISO 8601. ThreadJob runspaces get
# their own per-thread guard inside $queryJobScriptBlock because
# PowerShell 5.1 does not inherit parent culture into ThreadJobs.
# ============================================================
[System.Threading.Thread]::CurrentThread.CurrentCulture   = [System.Globalization.CultureInfo]::InvariantCulture
[System.Threading.Thread]::CurrentThread.CurrentUICulture = [System.Globalization.CultureInfo]::InvariantCulture

# ============================================================
# BOOTSTRAP LOG
# Open a deterministic log file IMMEDIATELY after param() so every Write-Host /
# Write-Log call from this point forward lands on disk. The final log location
# (which depends on -OutputPath / -AppendFile / -OutputPathLog / checkpoint state)
# is resolved much later in the script — at that point the bootstrap log is
# renamed/moved to the final path. The in-memory $script:LogBuffer remains as a
# belt-and-braces fallback if the bootstrap file itself cannot be created
# (read-only volume, permissions, etc.).
#
# Path resolution order (durable bootstrap-log location for Azure Container Instances):
#   1. $env:PAX_BOOTSTRAP_LOG_DIR  — operator-supplied durable location.
#      In the PAX.Dockerfile this defaults to "/pax-logs" and is declared as a
#      VOLUME so operators can mount Azure Files at that path. When mounted,
#      pre-flight / auth / param-validation failures leave the bootstrap log
#      on the Azure Files share, retrievable without spinning a new container.
#   2. [System.IO.Path]::GetTempPath() — process temp dir, correct on every
#      supported host: Windows local ($env:TEMP), Linux container (/tmp),
#      macOS dev (/var/folders/.../T/). No host-OS branching required.
#
# The override is validated for write access; if it isn't writable the script
# silently falls back to GetTempPath() so a misconfigured env var never blocks
# a run. Successful migration of the bootstrap log to its final location uses
# Move-Item, which removes the bootstrap source file — the durable directory
# remains for future runs.
# ============================================================
try {
	$candidateDirs = @()
	if (-not [string]::IsNullOrWhiteSpace($env:PAX_BOOTSTRAP_LOG_DIR)) {
		$candidateDirs += $env:PAX_BOOTSTRAP_LOG_DIR
	}
	$candidateDirs += [System.IO.Path]::GetTempPath()

	$script:BootstrapLogDir = $null
	foreach ($cand in $candidateDirs) {
		try {
			if (-not (Test-Path -LiteralPath $cand -PathType Container)) {
				New-Item -Path $cand -ItemType Directory -Force -ErrorAction Stop | Out-Null
			}
			# Probe write access with a zero-byte sentinel.
			$probe = Join-Path $cand (".pax_writeprobe_{0}_{1}" -f $PID, (Get-Date -Format 'yyyyMMddHHmmssfff'))
			Set-Content -LiteralPath $probe -Value '' -ErrorAction Stop
			Remove-Item -LiteralPath $probe -Force -ErrorAction SilentlyContinue
			$script:BootstrapLogDir = $cand
			break
		} catch {
			continue
		}
	}
	if (-not $script:BootstrapLogDir) { throw "No writable bootstrap-log directory available." }

	$script:BootstrapLogName = "PAX_bootstrap_{0}_{1}.log" -f $PID, (Get-Date -Format 'yyyyMMddHHmmss')
	$script:LogFile          = Join-Path $script:BootstrapLogDir $script:BootstrapLogName
	$script:LogFileIsBootstrap = $true
	New-Item -Path $script:LogFile -ItemType File -Force -ErrorAction Stop | Out-Null
	Add-Content -Path $script:LogFile -Value ("[{0}] [INFO] Bootstrap log opened at {1} (PID {2}, source: {3})." -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $script:LogFile, $PID, $(if ($env:PAX_BOOTSTRAP_LOG_DIR -and $script:BootstrapLogDir -eq $env:PAX_BOOTSTRAP_LOG_DIR) { 'PAX_BOOTSTRAP_LOG_DIR' } else { 'system temp' })) -Encoding UTF8 -ErrorAction SilentlyContinue
} catch {
	# Bootstrap log creation failed — leave $script:LogFile null so the existing
	# in-memory $script:LogBuffer path (defined further down) absorbs early entries.
	$script:LogFile = $null
	$script:LogFileIsBootstrap = $false
	Microsoft.PowerShell.Utility\Write-Host ("WARNING: Could not create bootstrap log: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
}

# ============================================================
# DEPRECATED SWITCH GATE
# Any explicit use of these switches on the command line causes an
# immediate graceful exit. These switches are no longer supported.
# ============================================================
$script:DeprecatedSwitchesHit = @()
if ($PSBoundParameters.ContainsKey('ExportWorkbook')) { $script:DeprecatedSwitchesHit += '-ExportWorkbook' }
if ($PSBoundParameters.ContainsKey('RAWInputCSV'))    { $script:DeprecatedSwitchesHit += '-RAWInputCSV' }
if ($PSBoundParameters.ContainsKey('ExplodeArrays'))  { $script:DeprecatedSwitchesHit += '-ExplodeArrays' }
if ($PSBoundParameters.ContainsKey('ExplodeDeep'))    { $script:DeprecatedSwitchesHit += '-ExplodeDeep' }
if ($script:DeprecatedSwitchesHit.Count -gt 0) {
	foreach ($d in $script:DeprecatedSwitchesHit) {
		Microsoft.PowerShell.Utility\Write-Host ("{0} is deprecated and will be removed in a future release." -f $d) -ForegroundColor Yellow
	}
	exit 0
}

# ============================================================
# AISID AVAILABILITY GATE
# The AI Solutions Intelligence Dashboard (AISID) customer entry points are not
# available in this version. The AISID implementation stays in place; only the
# customer entry points are gated. This guard runs before any module load,
# sign-in, destination probe, output directory creation, checkpoint mutation,
# audit query creation, AISID collection, history reconciliation, upload, or
# local publication, so a gated invocation never contacts a service and never
# writes customer output. It is invoked a second time after checkpoint
# restoration so a stored AISID contract cannot reach a gated path either.
# ============================================================
$script:AISIDGateBlocked = $false
function script:Test-AISIDEntryPointGated {
	param(
		[bool]$DashboardIsAISID = $false,
		[bool]$DefenderUsageOutputRequested = $false,
		[bool]$DefenderUsageAppendRequested = $false,
		[bool]$DeltaCacheSwitchRequested = $false
	)
	if (-not ($DashboardIsAISID -or $DefenderUsageOutputRequested -or $DefenderUsageAppendRequested -or $DeltaCacheSwitchRequested)) { return $false }
	if ($script:AISIDGateBlocked) { return $true }
	$script:AISIDGateBlocked = $true
	Microsoft.PowerShell.Utility\Write-Host "The AI Solutions Intelligence Dashboard (AISID) is currently under development and is not available for customer use in this PAX version. The AISID customer entry points will become available in a later PAX script version." -ForegroundColor Yellow
	Microsoft.PowerShell.Utility\Write-Host "Gated entry points: -Dashboard AISID, -OutputPathDefenderUsage, -AppendDefenderUsage, and -DisableAISIDDeltaCache." -ForegroundColor Yellow
	return $true
}
$aisidCliDashboard = ($PSBoundParameters.ContainsKey('Dashboard') -and ([string]$Dashboard).Trim().ToUpperInvariant() -eq 'AISID')
$aisidCliOutput    = $PSBoundParameters.ContainsKey('OutputPathDefenderUsage')
$aisidCliAppend    = $PSBoundParameters.ContainsKey('AppendDefenderUsage')
$aisidCliCache     = ($PSBoundParameters.ContainsKey('DisableAISIDDeltaCache') -and [bool]$DisableAISIDDeltaCache)
if (script:Test-AISIDEntryPointGated -DashboardIsAISID $aisidCliDashboard -DefenderUsageOutputRequested $aisidCliOutput -DefenderUsageAppendRequested $aisidCliAppend -DeltaCacheSwitchRequested $aisidCliCache) {
	exit 1
}

# ============================================================
# MANUAL -Resume PARAMETER PARSING
# Enables: -Resume (auto-discover) and -Resume "path" (explicit)
# ============================================================
$Resume = $null
$ResumeSpecified = $false
if ($RemainingArgs -and $RemainingArgs.Count -gt 0) {
	for ($i = 0; $i -lt $RemainingArgs.Count; $i++) {
		if ($RemainingArgs[$i] -eq '-Resume') {
			$ResumeSpecified = $true
			# Check if next argument exists and is not another parameter
			if (($i + 1) -lt $RemainingArgs.Count -and $RemainingArgs[$i + 1] -notmatch '^-') {
				$Resume = $RemainingArgs[$i + 1]
				$i++  # Skip the path argument
			} else {
				$Resume = ''  # Auto-discover mode
			}
		}
	}
}

# ============================================================
# AISID AVAILABILITY GATE - stored resume contract (read-only pre-scan)
# When -Resume names an unambiguous checkpoint, its stored contract is inspected
# read-only here - before any module load, sign-in, destination probe, checkpoint
# mutation, audit query, collection, or publication - so a stored AISID contract is
# stopped at the same point as an explicit AISID switch. An ambiguous selection is
# left to the post-restoration guard, which still runs before sign-in, collection,
# checkpoint mutation, and publication. Nothing is created, written, or modified here.
# ============================================================
if ($ResumeSpecified) {
	$aisidResumeProbePath = $null
	try {
		if (-not [string]::IsNullOrWhiteSpace($Resume)) {
			if (Test-Path -LiteralPath $Resume -PathType Leaf) { $aisidResumeProbePath = $Resume }
			elseif (Test-Path -LiteralPath $Resume -PathType Container) {
				$aisidProbeFound = @(Get-ChildItem -LiteralPath $Resume -Filter '.pax_checkpoint_*.json' -File -ErrorAction SilentlyContinue)
				if ($aisidProbeFound.Count -eq 1) { $aisidResumeProbePath = $aisidProbeFound[0].FullName }
			}
		} else {
			$aisidProbeDirs = @()
			if (-not [string]::IsNullOrWhiteSpace($OutputPath)) { $aisidProbeDirs += $OutputPath }
			$aisidProbeDirs += (Get-Location).Path
			foreach ($aisidProbeDir in $aisidProbeDirs) {
				if (-not (Test-Path -LiteralPath $aisidProbeDir -PathType Container)) { continue }
				$aisidProbeFound = @(Get-ChildItem -LiteralPath $aisidProbeDir -Filter '.pax_checkpoint_*.json' -File -ErrorAction SilentlyContinue)
				if ($aisidProbeFound.Count -eq 1) { $aisidResumeProbePath = $aisidProbeFound[0].FullName; break }
				if ($aisidProbeFound.Count -gt 1) { break }
			}
		}
	} catch { $aisidResumeProbePath = $null }
	if ($aisidResumeProbePath) {
		$aisidProbeDash = $false; $aisidProbeOut = $false; $aisidProbeApp = $false; $aisidProbeCache = $false
		try {
			$aisidProbeData = Get-Content -LiteralPath $aisidResumeProbePath -Raw -ErrorAction Stop | ConvertFrom-Json -AsHashtable -ErrorAction Stop
			if ($aisidProbeData) {
				if ($aisidProbeData.Contains('aisidWindow') -and $aisidProbeData.aisidWindow) { $aisidProbeDash = $true }
				if ($aisidProbeData.Contains('aisidResumeStateVersion')) { $aisidProbeDash = $true }
				if ($aisidProbeData.Contains('parameters') -and $aisidProbeData.parameters) {
					$aisidProbeParams = $aisidProbeData.parameters
					if ($aisidProbeParams.Contains('dashboard') -and ([string]$aisidProbeParams.dashboard).Trim().ToUpperInvariant() -eq 'AISID') { $aisidProbeDash = $true }
					if ($aisidProbeParams.Contains('rollupDashboard') -and ([string]$aisidProbeParams.rollupDashboard).Trim().ToUpperInvariant() -eq 'AISID') { $aisidProbeDash = $true }
					$aisidProbeOut   = ($aisidProbeParams.Contains('outputPathDefenderUsage') -and -not [string]::IsNullOrWhiteSpace([string]$aisidProbeParams.outputPathDefenderUsage))
					$aisidProbeApp   = ($aisidProbeParams.Contains('appendDefenderUsage') -and -not [string]::IsNullOrWhiteSpace([string]$aisidProbeParams.appendDefenderUsage))
					$aisidProbeCache = ($aisidProbeParams.Contains('disableAISIDDeltaCache') -and [bool]$aisidProbeParams.disableAISIDDeltaCache)
				}
			}
		} catch { }
		if (script:Test-AISIDEntryPointGated -DashboardIsAISID $aisidProbeDash -DefenderUsageOutputRequested $aisidProbeOut -DefenderUsageAppendRequested $aisidProbeApp -DeltaCacheSwitchRequested $aisidProbeCache) {
			exit 1
		}
	}
}

# ============================================================
# PROMOTE AUTH PARAMETERS TO SCRIPT SCOPE
# Enables access from within functions (e.g., Connect-PurviewAudit)
# ============================================================
$script:TenantId = $TenantId
$script:ClientId = $ClientId
$script:ClientSecret = $ClientSecret
$script:ClientCertificateThumbprint = $ClientCertificateThumbprint
$script:ClientCertificateStoreLocation = $ClientCertificateStoreLocation
$script:ClientCertificatePath = $ClientCertificatePath
$script:ClientCertificatePassword = $ClientCertificatePassword

	function Resolve-CommaSeparatedValues {
		param([string[]]$Values)

		if (-not $Values -or $Values.Count -eq 0) {
			return $Values
		}

		$finalActivityTypes = @()
		
		# Step 1: Add explicit -ActivityTypes parameter values (if provided and not default)
		if ($PSBoundParameters.ContainsKey('ActivityTypes') -and $ActivityTypes) {
			foreach ($actType in $ActivityTypes) {
				if ($actType -and $actType -ne '') {
					$finalActivityTypes += $actType
				}
			}
			if ($finalActivityTypes.Count -gt 0) {
				Write-LogHost "Custom ActivityTypes provided: $($finalActivityTypes -join ', ')" -ForegroundColor Gray
			}
		}

	# Step 3: Add CopilotInteraction when explicitly requested
	if ($IncludeCopilotInteraction -and -not ($finalActivityTypes -contains $copilotBaseActivityType)) {
		$finalActivityTypes += $copilotBaseActivityType
		Write-LogHost "IncludeCopilotInteraction: Adding $copilotBaseActivityType (explicit request)" -ForegroundColor Cyan
	}

	# Step 4: Add Microsoft 365 usage bundle when requested
	Write-LogHost ("IncludeM365Usage switch present: {0}" -f $IncludeM365Usage.IsPresent) -ForegroundColor DarkGray
	if ($IncludeM365Usage) {
		$finalActivityTypes += $m365UsageActivityBundle
		Write-LogHost ("M365 Usage bundle: Adding {0} activity types across Exchange/SharePoint/OneDrive/Teams" -f $m365UsageActivityBundle.Count) -ForegroundColor Cyan

		# -IncludeM365Usage always implies -CombineOutput. The M365 usage bundle spans 30+
		# activity types across 4 workloads; per-activity-type splits produce unmanageable file
		# counts and are incompatible with the rollup post-processor (which consumes a single
		# CSV). Auto-enable -CombineOutput once, with a one-line info message (no prompt).
		if (-not $CombineOutput) {
			$CombineOutput = [System.Management.Automation.SwitchParameter]::new($true)
			Write-LogHost "M365 Usage mode: -CombineOutput auto-enabled (M365 bundle always produces a single combined output)." -ForegroundColor Cyan
		}

		$RecordTypes = @(
			if ($RecordTypes) { $RecordTypes }
			$m365UsageRecordBundle
		) | Where-Object { $_ } | Select-Object -Unique
		if ($RecordTypes.Count -eq 0) { $RecordTypes = $null }

		# CRITICAL: Do NOT set ServiceTypes for M365 usage mode - Graph API should get ALL workloads in single pass
		# Multiple serviceFilter values cause unnecessary workload splits (Exchange, SharePoint, OneDrive, Teams)
		# Instead, send NO serviceFilter and let Graph API return all workloads in one query per partition
		$ServiceTypes = $null

		if ($RecordTypes) {
			Write-LogHost "M365 Usage bundle: RecordTypes => $($RecordTypes -join ', ')" -ForegroundColor Gray
		}
		Write-LogHost "M365 Usage mode: ServiceTypes => NULL (single workload pass, all services combined)" -ForegroundColor Cyan
	}

	# Step 5: BASE ACTIVITY TYPE - Add CopilotInteraction as default base type
	# This is the core Microsoft 365 Copilot activity type (FREE, included in M365 Copilot licensing)
	# Captures ALL M365 Copilot usage including Teams meetings, Word, Excel, PowerPoint, Outlook, etc.
	# Auto-add when the user did not explicitly provide -ActivityTypes.
	# Exception: Always respect -ExcludeCopilotInteraction (handled in Step 6)
	$userProvidedCustomTypes = $PSBoundParameters.ContainsKey('ActivityTypes')
	if (-not $ExcludeCopilotInteraction) {
		# Auto-add only when no custom types were provided
		if (-not $userProvidedCustomTypes) {
			# Add CopilotInteraction if not already present
			if (-not ($finalActivityTypes -contains $copilotBaseActivityType)) {
				$finalActivityTypes = @($copilotBaseActivityType) + $finalActivityTypes
			}
		}
	}

	# Step 6: EXCLUSION OVERRIDE - Remove CopilotInteraction if -ExcludeCopilotInteraction is true
	if ($ExcludeCopilotInteraction) {
		$finalActivityTypes = $finalActivityTypes | Where-Object { $_ -ne $copilotBaseActivityType }
	}

	# Step 7: Final deduplication and validation
	$finalActivityTypes = @($finalActivityTypes | Select-Object -Unique)
	
	return $finalActivityTypes
}

# ============================================================
# AI Solutions Catalog (customer-editable dimension table)
# ============================================================
# Single source of truth for AI-app detection and the dashboard's AI_Solutions
# dimension. To extend coverage for your tenant, add a hashtable entry using the
# same keys as the existing entries; the detection-surface lists
# (CloudAppNames / SignInAppNames) may be partial — any non-empty match classifies
# an event. The catalog is also written to the AI solutions catalog CSV so the
# dashboard's AI_Solutions dimension can consume it directly.
# KEY SEMANTICS:
#   AISolution          - Primary key; must be unique; appears in every AISID output.
#   Category            - Enterprise AI | Developer AI | Unmanaged AI
#   Vendor              - Human-readable vendor/publisher name.
#   RiskTier            - Enterprise AI | Low | Medium | High (governance tier)
#   DefaultDataHandling - Short narrative of the product's default data-handling posture.
#   SolutionGroup       - Dashboard grouping key ('Microsoft 365 Copilot', 'ChatGPT',
#                         'Claude', 'Gemini', 'Perplexity', 'Grok', or 'All Other AI').
#   CloudAppNames       - Values matched against Defender CloudAppEvents application names.
#   SignInAppNames      - Values matched against Entra and Graph sign-in application names.
#   NetworkDomains      - AI service hostnames matched against Defender device network event URLs
#                         (empty when no authoritative hostname is known for the entry).
# ============================================================
$script:AISolutionCatalog = @(
	@{ AISolution = 'Microsoft 365 Copilot'; Category = 'Enterprise AI'; Vendor = 'Microsoft';    RiskTier = 'Sanctioned'; DefaultDataHandling = 'Customer controlled, no training on tenant data'; SolutionGroup = 'Microsoft Copilot'; CloudAppNames = @('Microsoft 365 Copilot','Microsoft Copilot','Microsoft 365 Chat'); SignInAppNames = @('Microsoft 365 Copilot','Microsoft Copilot'); NetworkDomains = @('copilot.microsoft.com','copilot.cloud.microsoft') }
	@{ AISolution = 'GitHub Copilot';        Category = 'Developer AI';  Vendor = 'GitHub';       RiskTier = 'Sanctioned'; DefaultDataHandling = 'Per enterprise contract';                           SolutionGroup = 'Microsoft Copilot';     CloudAppNames = @('GitHub Copilot','GitHub.com');                                   SignInAppNames = @('GitHub Copilot','GitHub'); NetworkDomains = @() }
	@{ AISolution = 'Cursor';                Category = 'Developer AI';  Vendor = 'Anysphere';    RiskTier = 'Unresolved'; DefaultDataHandling = 'Code stored per tier';                              SolutionGroup = 'Needs Classification'; CloudAppNames = @('Cursor');                                                         SignInAppNames = @('Cursor'); NetworkDomains = @() }
	@{ AISolution = 'ChatGPT';               Category = 'Unmanaged AI';  Vendor = 'OpenAI';       RiskTier = 'Unresolved'; DefaultDataHandling = 'Training by default on free tier';                  SolutionGroup = 'Needs Classification'; CloudAppNames = @('ChatGPT','ChatGPT Enterprise','OpenAI ChatGPT');                 SignInAppNames = @('ChatGPT Enterprise','OpenAI'); NetworkDomains = @('chat.openai.com','chatgpt.com','api.openai.com') }
	@{ AISolution = 'Claude';                Category = 'Unmanaged AI';  Vendor = 'Anthropic';    RiskTier = 'Unsanctioned'; DefaultDataHandling = 'Not used for training (paid tiers)';                SolutionGroup = 'Shadow AI';             CloudAppNames = @('Claude','Claude for Work','Anthropic Claude');                   SignInAppNames = @('Claude for Work','Anthropic'); NetworkDomains = @('claude.ai','api.anthropic.com') }
	@{ AISolution = 'Gemini';                Category = 'Unmanaged AI';  Vendor = 'Google';       RiskTier = 'Unsanctioned'; DefaultDataHandling = 'Not used for training (Workspace tier)';            SolutionGroup = 'Shadow AI';             CloudAppNames = @('Google Gemini','Gemini');                                        SignInAppNames = @('Google Gemini'); NetworkDomains = @('gemini.google.com','bard.google.com') }
	@{ AISolution = 'Perplexity';            Category = 'Unmanaged AI';  Vendor = 'Perplexity';   RiskTier = 'Unsanctioned'; DefaultDataHandling = 'Not disclosed in detail';                           SolutionGroup = 'Shadow AI';             CloudAppNames = @('Perplexity','Perplexity Enterprise');                             SignInAppNames = @('Perplexity Enterprise','Perplexity'); NetworkDomains = @('perplexity.ai') }
	@{ AISolution = 'Mistral';               Category = 'Unmanaged AI';  Vendor = 'Mistral AI';   RiskTier = 'Unresolved'; DefaultDataHandling = 'EU-hosted';                                         SolutionGroup = 'Needs Classification'; CloudAppNames = @('Mistral','Mistral AI');                                           SignInAppNames = @('Mistral'); NetworkDomains = @() }
	@{ AISolution = 'HuggingFace';           Category = 'Unmanaged AI';  Vendor = 'Hugging Face'; RiskTier = 'Unsanctioned'; DefaultDataHandling = 'Model-dependent';                                   SolutionGroup = 'Shadow AI';             CloudAppNames = @('HuggingFace','Hugging Face');                                     SignInAppNames = @('HuggingFace','Hugging Face'); NetworkDomains = @('huggingface.co') }
	@{ AISolution = 'Poe';                   Category = 'Unmanaged AI';  Vendor = 'Quora';        RiskTier = 'Unresolved'; DefaultDataHandling = 'Per aggregator model';                              SolutionGroup = 'Needs Classification'; CloudAppNames = @('Poe');                                                            SignInAppNames = @('Poe'); NetworkDomains = @() }
	@{ AISolution = 'Grok';                  Category = 'Unmanaged AI';  Vendor = 'xAI';          RiskTier = 'Unresolved'; DefaultDataHandling = 'Training by default';                               SolutionGroup = 'Needs Classification'; CloudAppNames = @('Grok','xAI');                                                     SignInAppNames = @('Grok','xAI'); NetworkDomains = @() }
	@{ AISolution = 'DeepSeek';              Category = 'Unmanaged AI';  Vendor = 'DeepSeek';     RiskTier = 'Unresolved'; DefaultDataHandling = 'PRC data residency';                                SolutionGroup = 'Needs Classification'; CloudAppNames = @('DeepSeek');                                                       SignInAppNames = @('DeepSeek'); NetworkDomains = @() }
	@{ AISolution = 'Character.AI';          Category = 'Unmanaged AI';  Vendor = 'Character.AI'; RiskTier = 'Unresolved'; DefaultDataHandling = 'Public by default';                                 SolutionGroup = 'Needs Classification'; CloudAppNames = @('Character.AI','Character AI');                                    SignInAppNames = @('Character.AI','Character AI'); NetworkDomains = @() }
)

# ---- AI Solutions Catalog helper functions (pure lookups, no I/O) ----

function Get-AISIDFilteredCatalog {
	<#
	.SYNOPSIS
		Returns the AI solutions catalog.
	#>
	[OutputType([System.Collections.IList])]
	param()
	return $script:AISolutionCatalog
}

function Get-AISIDCloudAppNames {
	<#
	.SYNOPSIS
		Returns a de-duplicated flat array of cloud-app detection names.
	#>
	[OutputType([string[]])]
	param()
	$cat = Get-AISIDFilteredCatalog
	return @($cat | ForEach-Object { $_.CloudAppNames } | Where-Object { $_ } | Select-Object -Unique)
}

function Get-AISIDSignInAppNames {
	<#
	.SYNOPSIS
		Returns a de-duplicated flat array of sign-in application detection names.
	#>
	[OutputType([string[]])]
	param()
	$cat = Get-AISIDFilteredCatalog
	return @($cat | ForEach-Object { $_.SignInAppNames } | Where-Object { $_ } | Select-Object -Unique)
}

function Resolve-AISIDFromAppName {
	<#
	.SYNOPSIS
		Resolves an application display name to its AI solutions catalog entry.
		Returns $null when no match is found.
	.NOTES
		Matches against both CloudAppNames and SignInAppNames (case-insensitive).
	#>
	[OutputType([System.Collections.IDictionary])]
	param([Parameter(Mandatory)][string]$AppName)

	if ([string]::IsNullOrWhiteSpace($AppName)) { return $null }
	$needle = $AppName.Trim().ToLowerInvariant()
	$cat = Get-AISIDFilteredCatalog
	foreach ($entry in $cat) {
		$names = @()
		if ($entry.CloudAppNames)  { $names += $entry.CloudAppNames }
		if ($entry.SignInAppNames) { $names += $entry.SignInAppNames }
		foreach ($n in $names) {
			if ($n -and $n.ToLowerInvariant() -eq $needle) { return $entry }
		}
	}
	return $null
}

function Get-AISIDNetworkDomains {
	<#
	.SYNOPSIS
		Returns a de-duplicated flat array of AI service network domains (hostnames) for host/URL
		matching. Built from the catalog's NetworkDomains lists; entries with no known hostname
		contribute nothing.
	#>
	[OutputType([string[]])]
	param()
	$cat = Get-AISIDFilteredCatalog
	return @($cat | ForEach-Object { $_.NetworkDomains } | Where-Object { $_ } | Select-Object -Unique)
}

function Resolve-AISIDFromDomain {
	<#
	.SYNOPSIS
		Resolves a host / FQDN to its AI solutions catalog entry, or $null when no match is found.
	.NOTES
		Matches against the catalog's NetworkDomains using endswith semantics, so a subdomain
		(for example 'api.openai.com') resolves to a catalog entry that lists a parent domain.
	#>
	[OutputType([System.Collections.IDictionary])]
	param([Parameter(Mandatory)][string]$HostName)

	if ([string]::IsNullOrWhiteSpace($HostName)) { return $null }
	$needle = $HostName.Trim().ToLowerInvariant()
	$cat = Get-AISIDFilteredCatalog
	foreach ($entry in $cat) {
		if (-not $entry.NetworkDomains) { continue }
		foreach ($d in $entry.NetworkDomains) {
			if (-not $d) { continue }
			$lc = ([string]$d).ToLowerInvariant()
			if ($needle -eq $lc -or $needle.EndsWith('.' + $lc)) { return $entry }
		}
	}
	return $null
}

# Microsoft advanced hunting keeps data queryable for the last 30 days by default; reaching further
# back requires tenant-side streaming of specific tables into Microsoft Sentinel with extended
# retention, which this script cannot detect or assume. The window is fixed here as the single
# source of truth. Ref: https://learn.microsoft.com/en-us/defender-xdr/advanced-hunting-overview
$script:AISIDLookbackDaysFixed = 30

function Get-AISIDEffectiveLookbackDays {
	<#
	.SYNOPSIS
		Returns the AI Solutions Intelligence Dashboard lookback window, in days.
	#>
	[OutputType([int])]
	param()
	return $script:AISIDLookbackDaysFixed
}

function Resolve-AISIDDateWindow {
	<##SYN Pure resolver for the AISID requested-vs-available date-window intersection.
	Side-effect-free: no Get-Date, no logging, no prompts, no exits, no script-scope reads/writes.
	All inputs are concrete UTC instants; requested and available intervals are half-open [start,end).
	AvailableStartUtc = ReferenceNowUtc - RetentionDays; AvailableEndUtc = ReferenceNowUtc.
	Effective = requested INTERSECT available. Status FULL = effective==requested (no clip);
	PARTIAL = intervals overlap but effective differs; NONE = EffectiveStartUtc >= EffectiveEndUtc
	(no overlap; an empty requested interval is NONE, never FULL). #>
	[CmdletBinding()]
	[OutputType([pscustomobject])]
	param(
		[Parameter(Mandatory)][datetime]$RequestedStartUtc,
		[Parameter(Mandatory)][datetime]$RequestedEndUtc,
		[Parameter(Mandatory)][datetime]$ReferenceNowUtc,
		[int]$RetentionDays = 30
	)
	$reqStart = [datetime]::SpecifyKind($RequestedStartUtc, [System.DateTimeKind]::Utc)
	$reqEnd   = [datetime]::SpecifyKind($RequestedEndUtc,   [System.DateTimeKind]::Utc)
	$refNow   = [datetime]::SpecifyKind($ReferenceNowUtc,   [System.DateTimeKind]::Utc)
	$availStart = $refNow.AddDays(-$RetentionDays)
	$availEnd   = $refNow
	$effStart = if ($reqStart -gt $availStart) { $reqStart } else { $availStart }
	$effEnd   = if ($reqEnd   -lt $availEnd)   { $reqEnd }   else { $availEnd }
	$startClipped = ($effStart -ne $reqStart)
	$endClipped   = ($effEnd   -ne $reqEnd)
	if ($effStart -ge $effEnd) {
		$status = 'NONE'; $wasClipped = $true
		$clipReason = 'Requested interval does not overlap the available retention window.'
	}
	elseif (-not $startClipped -and -not $endClipped) {
		$status = 'FULL'; $wasClipped = $false; $clipReason = ''
	}
	else {
		$status = 'PARTIAL'; $wasClipped = $true
		$parts = @()
		if ($startClipped) { $parts += ("requested start {0:yyyy-MM-ddTHH:mm:ssZ} precedes the {1}-day retention floor {2:yyyy-MM-ddTHH:mm:ssZ}" -f $reqStart, $RetentionDays, $availStart) }
		if ($endClipped)   { $parts += ("requested end {0:yyyy-MM-ddTHH:mm:ssZ} exceeds the current retention ceiling {1:yyyy-MM-ddTHH:mm:ssZ}" -f $reqEnd, $availEnd) }
		$clipReason = ($parts -join '; ') + '.'
	}
	return [pscustomobject][ordered]@{
		RequestedStartUtc = $reqStart
		RequestedEndUtc   = $reqEnd
		ReferenceNowUtc   = $refNow
		AvailableStartUtc = $availStart
		AvailableEndUtc   = $availEnd
		EffectiveStartUtc = $effStart
		EffectiveEndUtc   = $effEnd
		Status            = $status
		WasClipped        = $wasClipped
		ClipReason        = $clipReason
		RetentionDays     = [int]$RetentionDays
	}
}

function Get-AISIDCollectionBounds {
	<##SYN Returns the frozen AISID collection interval [StartUtc, EndUtc) - the resolved
	requested-intersect-available effective window - as a two-key hashtable. Every date-bearing
	AISID collector reads its bounds from here so the whole run shares one window instant. #>
	[CmdletBinding()]
	param()
	if ($script:AISIDWindow -and $script:AISIDWindow.EffectiveStartUtc -and $script:AISIDWindow.EffectiveEndUtc) {
		return @{
			StartUtc = [datetime]::SpecifyKind([datetime]$script:AISIDWindow.EffectiveStartUtc, [System.DateTimeKind]::Utc)
			EndUtc   = [datetime]::SpecifyKind([datetime]$script:AISIDWindow.EffectiveEndUtc,   [System.DateTimeKind]::Utc)
		}
	}
	throw "AISID collection bounds requested before the AISID date window was established (script:AISIDWindow is missing EffectiveStartUtc/EffectiveEndUtc). This is a control-flow invariant violation: every valid fresh or resumed AISID run must resolve and freeze the window before any collector runs."
}

function Write-AISIDWindowSummary {
	<##SYN Prints the one-line AISID collection-window summary (terminal + log) for a completed run.
	FULL/PARTIAL only; a NONE run exits before any collection and never reaches here. #>
	[CmdletBinding()]
	param()
	if (-not $script:AISIDWindow) { return }
	$w = $script:AISIDWindow
	$fmt = 'yyyy-MM-ddTHH:mm:ssZ'
	$reqStr = ('[{0} .. {1})' -f ([datetime]$w.RequestedStartUtc).ToString($fmt), ([datetime]$w.RequestedEndUtc).ToString($fmt))
	$effStr = ('[{0} .. {1})' -f ([datetime]$w.EffectiveStartUtc).ToString($fmt), ([datetime]$w.EffectiveEndUtc).ToString($fmt))
	if ([string]$w.Status -eq 'PARTIAL') {
		Write-LogHost ("AISID collection window: PARTIAL | requested {0} | effective {1} | reason: {2}" -f $reqStr, $effStr, [string]$w.ClipReason) -ForegroundColor Yellow
	}
	else {
		Write-LogHost ("AISID collection window: FULL | requested {0} | effective {1}" -f $reqStr, $effStr) -ForegroundColor Green
	}
}

# ============================================================
# AI Solutions Intelligence Dashboard — Graph hunting rate limiter
# ============================================================
# Microsoft's advanced hunting API guarantees at least 45 calls/min per tenant (higher for
# larger tenants) and enforces a per-tenant CPU budget that returns HTTP 429 when exhausted.
# This limiter paces proactively well under that floor and drains reactively on a rate-limit
# response. Ref: https://learn.microsoft.com/en-us/graph/api/resources/security-api-overview
$script:AISIDTokenBucket = [hashtable]::Synchronized(@{
	IntervalMs        = 2000                 # Proactive floor: 30 calls/min (headroom under the >=45/min guarantee)
	BackoffIntervalMs = 4000                 # Slowed cadence after a rate-limit response: 15 calls/min
	LastEmit          = [DateTime]::MinValue
	BackoffUntil      = [DateTime]::MinValue
	PermitCount       = 0
	Lock              = [object]::new()
})

function Set-AISIDTokenBucketBackoff {
	<#
	.SYNOPSIS
		Slows the hunting-query rate limiter to its backoff cadence for a set duration after a
		rate-limit response.
	#>
	[CmdletBinding()]
	param([int]$BackoffDurationSeconds = 60)
	$script:AISIDTokenBucket.BackoffUntil = (Get-Date).AddSeconds($BackoffDurationSeconds)
	Write-LogHost "[AISID] Rate-limit backoff engaged; hunting-query cadence slowed to $($script:AISIDTokenBucket.BackoffIntervalMs)ms for ${BackoffDurationSeconds}s." -ForegroundColor Yellow
}

function Invoke-WithAISIDTokenBucket {
	<#
	.SYNOPSIS
		Runs a scriptblock through the hunting-query rate limiter, waiting for the next permit
		(base or backoff cadence) before invoking it and returning its result unchanged.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][scriptblock]$ScriptBlock,
		[string]$Description = ''
	)

	$bucket = $script:AISIDTokenBucket
	$gotLock = $false
	try {
		[System.Threading.Monitor]::Enter($bucket.Lock, [ref]$gotLock)
		$now = Get-Date
		$intervalMs = if ($now -lt $bucket.BackoffUntil) { $bucket.BackoffIntervalMs } else { $bucket.IntervalMs }
		if ($bucket.LastEmit -ne [DateTime]::MinValue) {
			$elapsedMs = ($now - $bucket.LastEmit).TotalMilliseconds
			if ($elapsedMs -lt $intervalMs) {
				$waitMs = [int]($intervalMs - $elapsedMs)
				[System.Threading.Monitor]::Exit($bucket.Lock); $gotLock = $false
				if ($waitMs -ge 1000 -and $Description) {
					Write-LogHost "[AISID] Waiting ${waitMs}ms for the next query permit ($Description)..." -ForegroundColor DarkGray
				}
				Start-Sleep -Milliseconds $waitMs
				[System.Threading.Monitor]::Enter($bucket.Lock, [ref]$gotLock)
			}
		}
		$bucket.LastEmit = Get-Date
		$bucket.PermitCount++
		if ($gotLock) { [System.Threading.Monitor]::Exit($bucket.Lock); $gotLock = $false }
	}
	catch {
		if ($gotLock) { [System.Threading.Monitor]::Exit($bucket.Lock); $gotLock = $false }
		throw
	}
	return (& $ScriptBlock)
}

function Invoke-GraphHuntingQuery {
	<#
	.SYNOPSIS
		Runs a Kusto advanced-hunting query through Microsoft Graph and returns a normalized
		result. Single entry point for the dashboard's hunting queries.
	.DESCRIPTION
		Posts to the Microsoft Graph advanced-hunting endpoint over the run's existing Graph
		session (Invoke-MgGraphRequest), paced by the shared rate limiter and backing off
		reactively on a rate-limit response. The collection window is the fixed lookback
		(Get-AISIDEffectiveLookbackDays) expressed as an ISO 8601 timespan.
		Ref: https://learn.microsoft.com/en-us/graph/api/security-security-runhuntingquery
	.OUTPUTS
		Hashtable (never throws): Success, Results, Schema, RowCount, TruncationDetected,
		ErrorMessage, HttpStatusCode, AuthQuit, Elapsed.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$Query,
		[string]$Description = '',
		[int]$MaxTransientRetries = 3
	)

	# Advanced hunting returns at most 100,000 rows (and 50 MB) per query; a result at or near
	# the row ceiling signals possible silent truncation and is surfaced as a warning.
	# Ref: https://learn.microsoft.com/en-us/graph/api/resources/security-api-overview
	$rowCeiling       = 100000
	$truncationWarnAt = 99000

	$result = @{
		Success = $false; Results = $null; Schema = $null; RowCount = 0; TruncationDetected = $false
		ErrorMessage = ''; HttpStatusCode = 0; AuthQuit = $false; Elapsed = [TimeSpan]::Zero
	}

	$lookbackDays = Get-AISIDEffectiveLookbackDays
	$endpoint = 'https://graph.microsoft.com/v1.0/security/runHuntingQuery'
	$body = @{ Query = $Query; Timespan = "P${lookbackDays}D" } | ConvertTo-Json -Compress -Depth 4
	$sw = [System.Diagnostics.Stopwatch]::StartNew()
	$attempt = 0
	$tokenRetryConsumed = $false

	while ($true) {
		$attempt++

		# Keep the shared Graph token fresh through the existing refresh contract.
		$refresh = Refresh-GraphTokenIfNeeded
		if ($refresh -eq 'Quit') {
			$result.AuthQuit = $true; $result.ErrorMessage = 'Graph token refresh returned Quit'
			$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
		}

		$httpStatus = 0; $retryAfter = 0; $errMsg = ''; $payload = $null
		try {
			$payload = Invoke-WithAISIDTokenBucket -Description $Description -ScriptBlock {
				Invoke-MgGraphRequest -Method POST -Uri $endpoint -Body $body -ContentType 'application/json' -OutputType PSObject -ErrorAction Stop
			}
			$httpStatus = 200
		}
		catch {
			$errMsg = $_.Exception.Message
			$httpStatus = try { [int]$_.Exception.Response.StatusCode.value__ } catch { 0 }
			if ($httpStatus -eq 0 -and $errMsg -match '429|Too Many Requests|TooManyRequests') { $httpStatus = 429 }
			$retryAfter = try { [int]$_.Exception.Response.Headers['Retry-After'] } catch { 0 }
		}
		$result.HttpStatusCode = $httpStatus

		if ($payload -and $httpStatus -ge 200 -and $httpStatus -lt 300) {
			$rows = @($payload.results)
			$result.Success = $true; $result.Results = $rows; $result.Schema = $payload.schema; $result.RowCount = $rows.Count
			$result.TruncationDetected = ($rows.Count -ge $truncationWarnAt)
			if ($result.TruncationDetected) {
				Write-LogHost "[AISID] Query '$Description' returned $($rows.Count) rows, at or near the $rowCeiling-row limit; results may be truncated." -ForegroundColor Yellow
			}
			$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
		}

		if ($httpStatus -eq 401 -and -not $tokenRetryConsumed) {
			$tokenRetryConsumed = $true
			$r = Refresh-GraphTokenIfNeeded
			if ($r -eq 'Quit') {
				$result.AuthQuit = $true; $result.ErrorMessage = 'Unauthorized and token refresh returned Quit'
				$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
			}
			continue
		}

		if ($httpStatus -eq 429) {
			$waitSec = if ($retryAfter -gt 0) { $retryAfter } else { 60 }
			Write-LogHost "[AISID] Rate limited (HTTP 429); waiting ${waitSec}s before retrying ($Description)." -ForegroundColor Yellow
			Set-AISIDTokenBucketBackoff -BackoffDurationSeconds 60
			Start-Sleep -Seconds $waitSec
			continue
		}

		$transient = ($httpStatus -ge 500 -or $httpStatus -eq 408 -or $httpStatus -eq 0)
		if ($transient -and $attempt -le $MaxTransientRetries) {
			$backoffSec = [int][Math]::Min(60, [Math]::Pow(2, $attempt))
			Write-LogHost "[AISID] Transient failure (HTTP $httpStatus, attempt $attempt/$MaxTransientRetries); retrying in ${backoffSec}s. $errMsg" -ForegroundColor Yellow
			Start-Sleep -Seconds $backoffSec
			continue
		}

		$result.ErrorMessage = "Graph hunting query failed (HTTP $httpStatus, attempt $attempt): $errMsg"
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}
}

function Get-AISIDHuntingRowEstimate {
	<#
	.SYNOPSIS
		Runs a count-only hunting query and returns the estimated row count for the given KQL, or
		-1 when the probe could not be evaluated. Used to decide whether a result set would exceed
		the advanced-hunting response cap and therefore needs time-window subdivision.
	.OUTPUTS
		[long] estimated row count, or -1 on probe failure / auth quit.
	#>
	[OutputType([long])]
	param(
		[Parameter(Mandatory)][string]$ProbeQuery,
		[string]$Description = 'row-estimate probe'
	)
	$r = Invoke-GraphHuntingQuery -Query $ProbeQuery -Description $Description
	if ($r.AuthQuit -or -not $r.Success) { return -1 }
	$rows = @($r.Results)
	if ($rows.Count -eq 0) { return 0 }
	# The probe ends in `summarize N = count()`, so the single result row must carry a numeric field
	# named exactly 'N'. OData annotation companions ('N@odata.type' = '#Int64', and any top-level
	# '@odata.*') are ignored structurally. The count is read ONLY from a real 'N' property; an unrelated
	# lone numeric property is NEVER accepted. Missing, non-numeric, or duplicate 'N' => unreadable (-1).
	$nProps = @($rows[0].PSObject.Properties | Where-Object { $_.Name -eq 'N' })
	if ($nProps.Count -ne 1) { return -1 }
	$long = [long]0
	if ($null -eq $nProps[0].Value -or -not [long]::TryParse([string]$nProps[0].Value, [ref]$long)) { return -1 }
	return [long]$long
}

function Get-AISIDTimePartitions {
	<#
	.SYNOPSIS
		Plans a set of time sub-windows whose individual estimated row counts stay under the
		advanced-hunting response cap. Probes the given window via -EstimateProvider; if the
		estimate is under the cap the window is returned whole, otherwise it is split into
		ceil(estimate / target) equal sub-windows, each planned recursively (re-probed, so a
		non-uniform distribution is handled by splitting only the ranges that are actually hot).
		Subdivision stops at -FloorMinutes; a floor window still over the cap is returned with
		Truncated set and a warning, consistent with the query-level truncation warning.
	.OUTPUTS
		Array of ordered hashtables @{ StartUtc; EndUtc; Estimate; Truncated }.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][datetime]$StartUtc,
		[Parameter(Mandatory)][datetime]$EndUtc,
		[Parameter(Mandatory)][scriptblock]$EstimateProvider,
		[long]$Cap = 90000,
		[long]$Target = 80000,
		[int]$FloorMinutes = 60
	)

	$estimate    = [long](& $EstimateProvider $StartUtc $EndUtc)
	$spanMinutes = ($EndUtc - $StartUtc).TotalMinutes

	# An unreadable probe (-1) must NEVER be treated as "cannot rule out over-cap" and subdivided: that
	# produced an unbounded recursive fan-out down to the minute floor. Return a single window flagged
	# EstimateFailed so the collector fails this table explicitly instead of silently truncating/emptying.
	if ($estimate -lt 0) {
		return , ([ordered]@{ StartUtc = $StartUtc; EndUtc = $EndUtc; Estimate = $estimate; Truncated = $false; EstimateFailed = $true })
	}

	# Under the cap (and a successful probe): take the window whole.
	if ($estimate -lt $Cap) {
		return , ([ordered]@{ StartUtc = $StartUtc; EndUtc = $EndUtc; Estimate = $estimate; Truncated = $false; EstimateFailed = $false })
	}
	# At/over the cap (or an unreadable probe, treated as "cannot rule out over-cap") but already at
	# the minimum granularity: accept this window and flag possible truncation.
	if ($spanMinutes -le $FloorMinutes) {
		$trunc = ($estimate -ge $Cap)
		if ($trunc) {
			Write-LogHost ("[AISID] FileProximity: window {0:o}..{1:o} still estimates {2} rows at the {3}-minute floor; this window may be truncated at the {4}-row hunting limit." -f $StartUtc, $EndUtc, $estimate, $FloorMinutes, 100000) -ForegroundColor Yellow
		}
		return , ([ordered]@{ StartUtc = $StartUtc; EndUtc = $EndUtc; Estimate = $estimate; Truncated = $trunc; EstimateFailed = $false })
	}

	# Split into enough parts to bring each comfortably under target (at least 2), but never so many
	# that a sub-window would fall below the floor. Each part is re-probed recursively.
	$parts = 2
	if ($estimate -gt 0) { $parts = [Math]::Max(2, [int][Math]::Ceiling($estimate / [double]$Target)) }
	$maxParts = [Math]::Max(2, [int][Math]::Floor($spanMinutes / [double]$FloorMinutes))
	if ($parts -gt $maxParts) { $parts = $maxParts }

	$out = @()
	$totalTicks = ($EndUtc - $StartUtc).Ticks
	for ($i = 0; $i -lt $parts; $i++) {
		$subStart = $StartUtc.AddTicks([long]($totalTicks * $i / $parts))
		$subEnd   = if ($i -eq ($parts - 1)) { $EndUtc } else { $StartUtc.AddTicks([long]($totalTicks * ($i + 1) / $parts)) }
		$out += Get-AISIDTimePartitions -StartUtc $subStart -EndUtc $subEnd -EstimateProvider $EstimateProvider -Cap $Cap -Target $Target -FloorMinutes $FloorMinutes
	}
	return $out
}

function Test-AISIDLicensing {
	<#
	.SYNOPSIS
		Evaluates, independently per table, which AI Solutions Intelligence Dashboard data sets
		this tenant can populate. There is no combined pass/fail — each table stands on its own,
		so a tenant with only Microsoft Entra access still collects the two Entra-sourced tables.
	.DESCRIPTION
		The four advanced-hunting tables (ActivitySessions from CloudAppEvents, OffHoursGeo from
		EntraIdSignInEvents, FileProximity, and ClientChannel) are probed directly with a minimal query; a failed probe marks only
		that table unavailable. The remaining three tables draw on data the full run already produces —
		OAuthConsents and SSOSignIns from the run's Microsoft Entra access, and CopilotUsage from the
		CopilotInteraction rollup — so they are eligible whenever the run is authenticated.
	.OUTPUTS
		Ordered hashtable keyed by table name, each value @{ Eligible; Source; Detail }, plus an
		AuthQuit flag. No early return produces an all-or-nothing verdict.
	#>
	[CmdletBinding()]
	param()

	$verdict = [ordered]@{
		ActivitySessions = @{ Eligible = $false; Source = 'Defender advanced hunting'; Detail = '' }
		OffHoursGeo      = @{ Eligible = $false; Source = 'Defender advanced hunting'; Detail = '' }
		FileProximity    = @{ Eligible = $false; Source = 'Defender advanced hunting (MDE)'; Detail = '' }
		ClientChannel    = @{ Eligible = $false; Source = 'Defender advanced hunting (MDE)'; Detail = '' }
		OAuthConsents    = @{ Eligible = $true;  Source = 'Microsoft Entra audit logs'; Detail = "Available from the run's Entra access." }
		SSOSignIns       = @{ Eligible = $true;  Source = 'Microsoft Entra sign-in logs'; Detail = "Available from the run's Entra access." }
		CopilotUsage     = @{ Eligible = $true;  Source = 'Microsoft Purview (CopilotInteraction rollup)'; Detail = "Available from the run's CopilotInteraction rollup." }
		AuthQuit         = $false
	}

	$huntProbes = [ordered]@{
		ActivitySessions = 'CloudAppEvents | take 1 | project Timestamp'
		OffHoursGeo      = 'EntraIdSignInEvents | take 1 | project Timestamp'
		FileProximity    = 'DeviceNetworkEvents | take 1 | project Timestamp'
		ClientChannel    = 'DeviceNetworkEvents | take 1 | project Timestamp'
	}

	Write-LogHost '[AISID] Checking which data sets this tenant can populate...' -ForegroundColor Cyan
	foreach ($tbl in $huntProbes.Keys) {
		$r = Invoke-GraphHuntingQuery -Query $huntProbes[$tbl] -Description "Eligibility probe: $tbl"
		if ($r.AuthQuit) { $verdict.AuthQuit = $true }
		if ($r.Success) {
			$verdict[$tbl].Eligible = $true
			$verdict[$tbl].Detail   = 'Source data is queryable.'
		}
		else {
			$verdict[$tbl].Detail = "Source data is not available in this tenant (status $($r.HttpStatusCode))."
		}
	}

	return $verdict
}

function Write-AISIDLicensingReport {
	<#
	.SYNOPSIS
		Prints a per-table summary of which AI Solutions Intelligence Dashboard data sets will be
		collected for this tenant and which are unavailable. Reports table by table; it never
		declares the dashboard as a whole unavailable.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)][System.Collections.IDictionary]$Verdict)

	$tables = @('ActivitySessions', 'OffHoursGeo', 'FileProximity', 'ClientChannel', 'OAuthConsents', 'SSOSignIns', 'CopilotUsage')
	$eligibleCount = @($tables | Where-Object { $Verdict[$_].Eligible }).Count

	Write-LogHost ''
	Write-LogHost "[AISID] Data set availability for this tenant ($eligibleCount of $($tables.Count) available):" -ForegroundColor Cyan
	foreach ($tbl in $tables) {
		$v = $Verdict[$tbl]
		$status = if ($v.Eligible) { 'available' } else { 'not available' }
		$color  = if ($v.Eligible) { 'Green' } else { 'Yellow' }
		Write-LogHost ("[AISID]   {0,-18} {1,-14} ({2})" -f $tbl, $status, $v.Source) -ForegroundColor $color
	}
	if ($eligibleCount -lt $tables.Count) {
		Write-LogHost '[AISID] Data sets shown as not available depend on Microsoft Defender or Entra features this tenant does not currently expose. The available data sets are collected normally.' -ForegroundColor Gray
	}
	Write-LogHost ''
}

# ============================================================
# AI Solutions Intelligence Dashboard — table export contract + export/merge infrastructure
# ============================================================
# The dashboard model loads each CSV by a FIXED name from one folder and applies a fixed,
# ordered TransformColumnTypes; a column-order or name mismatch surfaces as a hard Power Query
# refresh error on the customer side, so the header order below is contractual. Column names,
# order, and the merge key grain are sourced from the model schema captured in
# PBIT_GROUND_TRUTH.md (table AI_Activity) and the FileProximity stub contract — never typed
# from memory. The FileProximity entry is the permanent header-only stub (always empty).
$script:AISIDTableSchemas = @{
	ActivitySessions = @{
		FileName = 'ai_activity_sessions.csv'
		Columns  = @('UPN', 'AISolution', 'YearMonth', 'Sessions', 'ActiveDays', 'EstimatedPrompts', 'DistinctDevices', 'Category', 'RiskTier')
		Key      = @('UPN', 'AISolution', 'YearMonth')
	}
	FileProximity = @{
		FileName = 'ai_file_proximity.csv'
		Columns  = @('Timestamp', 'UPN', 'AISolution', 'YearMonth', 'FileName', 'FolderCategory', 'FolderPath', 'SecondsToAI', 'NameMatchesSensitivePattern', 'FolderMatchesSensitive')
		Key      = @('Timestamp', 'UPN', 'FileName')
	}
	OffHoursGeo = @{
		FileName = 'ai_offhours_geo.csv'
		Columns  = @('UPN', 'YearMonth', 'TotalSessions', 'OffHoursSessions', 'OffHoursPct', 'DistinctCountries', 'AnomalousCountryCount', 'AnomalousCountries')
		Key      = @('UPN', 'YearMonth')
	}
	OAuthConsents = @{
		FileName = 'ai_oauth_consents.csv'
		Columns  = @('UPN', 'AppName', 'YearMonth', 'ConsentCount', 'LastConsent', 'PermissionWeight', 'Permissions')
		Key      = @('UPN', 'AppName', 'YearMonth')
	}
	SSOSignIns = @{
		FileName = 'ai_sso_signins.csv'
		Columns  = @('UPN', 'Application', 'YearMonth', 'SignInCount', 'DistinctDays', 'IsGuest', 'Countries', 'HasConditionalAccess', 'LastSignIn')
		Key      = @('UPN', 'Application', 'YearMonth')
	}
	ClientChannel = @{
		FileName = 'ai_client_channel.csv'
		Columns  = @('AISite', 'Channel', 'YearMonth', 'EventCount')
		Key      = @('AISite', 'Channel', 'YearMonth')
	}
	CopilotUsage = @{
		FileName = 'ai_copilot_usage_graph.csv'
		Columns  = @('UserPrincipalName', 'YearMonth', 'TeamsPrompts', 'WordPrompts', 'ExcelPrompts', 'OutlookPrompts', 'PowerPointPrompts', 'ChatPrompts', 'TotalPrompts', 'ActiveDays', 'LastActivityDate')
		Key      = @('UserPrincipalName', 'YearMonth')
	}
	AppGovAlerts = @{
		FileName = 'ai_appgov_alerts.csv'
		Columns  = @('Timestamp', 'YearMonth', 'UPN', 'AppName', 'AlertType', 'Severity', 'Description')
		Key      = @()
	}
	CloudDiscovery = @{
		FileName = 'ai_cloud_discovery.csv'
		Columns  = @('AIDomain', 'AppCategory', 'YearMonth', 'RiskScore', 'UploadVolumeMB', 'DownloadVolumeMB', 'TransactionCount', 'DistinctUsers', 'SanctionStatus')
		Key      = @()
	}
	MDASessions = @{
		FileName = 'ai_mda_sessions.csv'
		Columns  = @('Timestamp', 'YearMonth', 'UPN', 'AppName', 'ActionType', 'PolicyHit', 'PolicyAction', 'IPAddress', 'CountryCode', 'EventCount')
		Key      = @()
	}
	EntraUsers = @{
		FileName = 'EntraUsers.csv'
		Columns  = @('userPrincipalName', 'displayName', 'department', 'jobTitle', 'city', 'country', 'companyName', 'accountEnabled', 'userType', 'manager_displayName', 'manager_userPrincipalName', 'hasLicense', 'assignedLicenses', 'createdDateTime')
		Key      = @()  # Dimension table: whole file regenerated each run (overwrite); no replace-on-key merge.
	}
	SolutionsCatalog = @{
		FileName = 'ai_solutions_catalog.csv'
		Columns  = @('AISolution', 'Category', 'Vendor', 'RiskTier', 'DefaultDataHandling', 'SolutionGroup')
		Key      = @()  # Dimension table: whole file regenerated each run (overwrite); no replace-on-key merge.
	}
}

function script:Get-AISIDScopeUpnSet {
	# Resolved AISID collector scope: a case-insensitive set of the target UPNs, or $null when no
	# user/group scope was requested (an unfiltered whole-directory run). Fail-closed: a REQUESTED
	# scope that resolves to zero users already aborts the run upstream (exit 1), so a non-null empty
	# set never occurs here; $null distinctly means "no scope requested" (do not filter). An empty
	# scope therefore never widens, and a requested scope never leaks a non-target UPN into output.
	$u = @($script:targetUsers)
	if ($u.Count -eq 0) { return $null }
	$set = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
	foreach ($x in $u) { $s = ([string]$x).Trim(); if ($s) { [void]$set.Add($s) } }
	if ($set.Count -eq 0) { return $null }
	# Unary comma: return the HashSet itself (with its OrdinalIgnoreCase comparer) instead of letting
	# PowerShell enumerate it into a case-sensitive object[] on the way out.
	return , $set
}

# Per-table UPN column for AISID client-side scope enforcement. ClientChannel has no per-user grain
# (scoped at its source query) and SolutionsCatalog is intentionally global, so neither appears here;
# the EntraUsers dimension is scoped separately (target set + manager chain).
$script:AISIDScopeUpnColumn = @{
	ActivitySessions = 'UPN'
	FileProximity    = 'UPN'
	OffHoursGeo      = 'UPN'
	OAuthConsents    = 'UPN'
	SSOSignIns       = 'UPN'
	CopilotUsage     = 'UserPrincipalName'
}

function script:Get-AISIDScopeKqlFilter {
	# Server-side scope clause for a collector's hunting query: a KQL '| where <col> in~ (dynamic([...]))'
	# fragment. With -Users it covers exactly that batch (used by the batched runner); without -Users it
	# covers the full resolved target set. Returns '' when no scope was requested (unfiltered run,
	# unchanged behavior). The UPN literals are lower-cased and JSON-escaped.
	param([Parameter(Mandatory)][string]$UpnColumn, [string[]]$Users)
	$scope =
		if ($PSBoundParameters.ContainsKey('Users')) { @($Users) }
		else { $set = script:Get-AISIDScopeUpnSet; if ($null -eq $set) { @() } else { @($set) } }
	if ($scope.Count -eq 0) { return '' }
	$json = ($scope | ForEach-Object { '"' + (([string]$_).ToLowerInvariant() -replace '"', '\"') + '"' }) -join ','
	return ("| where {0} in~ (dynamic([{1}]))" -f $UpnColumn, $json)
}

function script:Get-AISIDScopeBatches {
	# Partitions the resolved target user set into deterministic batches sized by safe serialized request
	# length, so a large scope never produces a single oversized KQL 'in~ (dynamic([...]))' array. EVERY
	# target user appears in EXACTLY ONE batch (no cap, no first-N, no sampling, no truncation, no
	# duplicates); batches are ordered and their union equals the full scope. Returns @() when no scope
	# was requested (collectors then run one unfiltered query).
	param([int]$MaxSerializedChars = 8000)
	$set = script:Get-AISIDScopeUpnSet
	if ($null -eq $set) { return @() }
	# Deterministic order; force a clean [string[]] so no PSObject-wrapped element leaks into the batches.
	[string[]]$users = @(@($set) | ForEach-Object { ([string]$_).ToLowerInvariant() } | Sort-Object -Unique)
	$batches = New-Object System.Collections.Generic.List[object]
	$start = 0
	while ($start -lt $users.Length) {
		$len = 0; $count = 0
		for ($i = $start; $i -lt $users.Length; $i++) {
			$add = $users[$i].Length + 3
			if ($count -gt 0 -and ($len + $add) -gt $MaxSerializedChars) { break }
			$len += $add; $count++
		}
		if ($count -lt 1) { $count = 1 }
		[string[]]$batch = $users[$start..($start + $count - 1)]
		[void]$batches.Add($batch)
		$start += $count
	}
	return $batches.ToArray()
}

function script:Invoke-AISIDBatchedHuntingQuery {
	# Runs a hunting query once per target-user batch and returns a combined result hashtable
	# (Success/AuthQuit/TruncationDetected/Results/ErrorMessage). The QueryBuilder receives the per-batch
	# server-side scope clause and returns the full KQL for that batch, so every target user is queried
	# exactly once across the batches. When no scope was requested a single unfiltered query runs
	# (QueryBuilder called with ''), preserving the original one-query behavior. Any batch AuthQuit or
	# failure short-circuits and is surfaced to the caller (fail-closed). Rows are concatenated in batch
	# order; per-table dedup/aggregation is the caller's existing responsibility.
	param(
		[Parameter(Mandatory)][string]$UpnColumn,
		[Parameter(Mandatory)][scriptblock]$QueryBuilder,
		[Parameter(Mandatory)][string]$Description
	)
	$acc = New-Object System.Collections.Generic.List[object]
	$out = @{ Success = $true; AuthQuit = $false; TruncationDetected = $false; Results = @(); ErrorMessage = '' }
	$batches = @(script:Get-AISIDScopeBatches)
	$clauses = if ($batches.Count -eq 0) { @('') } else { @($batches | ForEach-Object { script:Get-AISIDScopeKqlFilter -UpnColumn $UpnColumn -Users $_ }) }
	foreach ($clause in $clauses) {
		$kql = & $QueryBuilder $clause
		$api = Invoke-GraphHuntingQuery -Query $kql -Description $Description
		if ($api.AuthQuit) { $out.AuthQuit = $true; $out.Success = $false; return $out }
		if (-not $api.Success) { $out.Success = $false; $out.ErrorMessage = [string]$api.ErrorMessage; return $out }
		if ($api.TruncationDetected) { $out.TruncationDetected = $true }
		foreach ($r in @($api.Results)) { [void]$acc.Add($r) }
	}
	$out.Results = @($acc.ToArray())
	return $out
}

function script:Select-AISIDScopedRows {
	# Client-side scope enforcement (defense-in-depth behind the server-side KQL filter): drops any row
	# whose UPN-column value is not in the resolved target set. Tables with no per-user grain
	# (ClientChannel is scoped at its source query; SolutionsCatalog is intentionally global) and the
	# EntraUsers dimension (scoped separately, incl. manager chain) are returned unchanged. When no
	# scope was requested the rows are returned unchanged.
	param([Parameter(Mandatory)][string]$Table, [object[]]$Rows = @())
	$set = script:Get-AISIDScopeUpnSet
	if ($null -eq $set) { return @($Rows) }
	if (-not $script:AISIDScopeUpnColumn.ContainsKey($Table)) { return @($Rows) }
	$col  = $script:AISIDScopeUpnColumn[$Table]
	$kept = New-Object System.Collections.Generic.List[object]
	foreach ($r in @($Rows)) {
		if (-not $r) { continue }
		$v = ([string]$r.$col).Trim()
		if ($v -and $set.Contains($v)) { [void]$kept.Add($r) }
	}
	return $kept.ToArray()
}

function script:Get-AISIDContainmentSet {
	# The set of allowed UPN-column VALUES for a table's FINAL post-merge scope containment. When
	# -Deidentify is on the raw target UPNs are mapped through the SAME deterministic Get-PaxDeidUpn
	# helper the rows are hashed with, so already-deidentified history compares against deidentified
	# scope keys (never raw-vs-hashed). Returns $null when no scope was requested or the table has no
	# per-user grain (ClientChannel / SolutionsCatalog / EntraUsers).
	param([Parameter(Mandatory)][string]$Table)
	$set = script:Get-AISIDScopeUpnSet
	if ($null -eq $set) { return $null }
	if (-not $script:AISIDScopeUpnColumn.ContainsKey($Table)) { return $null }
	$out = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
	foreach ($u in @($set)) {
		$val = if ($script:PaxDeidEnabled) { Get-PaxDeidUpn -Value ([string]$u) } else { [string]$u }
		$v = ([string]$val).Trim()
		if ($v) { [void]$out.Add($v) }
	}
	return , $out
}

function script:Select-AISIDContainedRows {
	# Splits merged rows into in-scope and out-of-scope by the table's UPN column, using the deid-aware
	# containment set. Returns a hashtable @{ InScope; OutOfScope; Applies }. Applies=$false for
	# unscoped runs or non-user-grain tables (rows all treated as in-scope).
	param([Parameter(Mandatory)][string]$Table, [object[]]$Rows = @())
	$cs = script:Get-AISIDContainmentSet -Table $Table
	if ($null -eq $cs) { return @{ Applies = $false; InScope = @($Rows); OutOfScope = @() } }
	$col = $script:AISIDScopeUpnColumn[$Table]
	$in = New-Object System.Collections.Generic.List[object]
	$offList = New-Object System.Collections.Generic.List[object]
	foreach ($r in @($Rows)) {
		if (-not $r) { continue }
		$v = ([string]$r.$col).Trim()
		if ($v -and $cs.Contains($v)) { [void]$in.Add($r) } else { [void]$offList.Add($r) }
	}
	return @{ Applies = $true; InScope = $in.ToArray(); OutOfScope = $offList.ToArray() }
}

function script:Test-PaxZeroRecordHeaderOnlyPath {
	# Decides whether the zero in-memory-record path enters the header-only-Purview-CSV emit block. TRUE
	# when there are no records AND it is neither -OnlyUserInfo (Entra-only) nor a streaming-merge export
	# (records stream from JSONL). -Dashboard AISID IS included here (it still needs the header-only
	# Purview CSV), but the AISID case CONTINUES past the block (see
	# Test-PaxZeroRecordContinuesAfterHeaderOnly) instead of returning, so a zero-record AISID run flows
	# through the SAME downstream finalization (Rollup empty Fact + Users -> Entra -> AISID export ->
	# completion/roster -> truthful exit) as a populated run. Zero Purview records are a valid empty
	# result, never a failure.
	param([int]$AllLogsCount, [bool]$OnlyUserInfo, [bool]$UseStreamingMergeForExport)
	if ($AllLogsCount -ne 0) { return $false }
	if ($OnlyUserInfo) { return $false }
	if ($UseStreamingMergeForExport) { return $false }
	return $true
}

function script:Test-PaxZeroRecordContinuesAfterHeaderOnly {
	# After the zero-record header-only Purview CSV is emitted, decides whether the run CONTINUES to the
	# common downstream finalization (Rollup -> Entra -> AISID -> completion/roster) instead of taking the
	# early return. TRUE only for -Dashboard AISID: a zero-record AISID run must still produce the empty
	# Rollup Fact, the Rollup Users dimension, the normal Entra output, all twelve AISID CSVs (incl.
	# EntraUsers.csv), the completion summary and the output roster. FALSE for every other mode, whose
	# zero-record behavior (emit header-only and return) is unchanged.
	param([string]$Dashboard)
	return ($Dashboard -eq 'AISID')
}

function Export-AISIDTable {
	<#
	.SYNOPSIS
		Writes one dashboard CSV in the exact contractual column order, with the header row always
		present. A table with zero rows still produces a valid header-only file (never omitted,
		never an error) so the dashboard model loads it cleanly as empty.
	.DESCRIPTION
		Folder/destination resolution is the caller's responsibility: the caller passes the already
		resolved effective directory (e.g. from Resolve-DataTypePaths for the dashboard destination),
		so this writer performs no tier inference or collision handling of its own. Only the columns
		named in OrderedColumns are emitted, so incidental provenance fields on the input rows never
		leak into the model.
	.OUTPUTS
		The full path of the file written.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$DestinationDir,
		[Parameter(Mandatory)][string]$FileName,
		[Parameter(Mandatory)][string[]]$OrderedColumns,
		[object[]]$Rows = @()
	)

	if (-not (Test-Path -LiteralPath $DestinationDir)) {
		New-Item -ItemType Directory -Path $DestinationDir -Force | Out-Null
	}
	$target = Join-Path $DestinationDir $FileName

	$sb = [System.Text.StringBuilder]::new()
	# Header row is written unconditionally — this is the safe-empty-table fallback.
	[void]$sb.AppendLine(($OrderedColumns -join ','))
	foreach ($row in @($Rows)) {
		if (-not $row) { continue }
		$fields = foreach ($col in $OrderedColumns) {
			$raw = if ($row -is [System.Collections.IDictionary]) { $row[$col] } else { $row.$col }
			$sVal = if ($null -eq $raw) { '' } else { [string]$raw }
			if ($sVal -match '[",\r\n]') { '"' + ($sVal -replace '"', '""') + '"' } else { $sVal }
		}
		[void]$sb.AppendLine(($fields -join ','))
	}
	[System.IO.File]::WriteAllText($target, $sb.ToString(), (New-Object System.Text.UTF8Encoding($false)))
	return $target
}

function Merge-AISIDTableOnKey {
	<#
	.SYNOPSIS
		Merges new rows into existing rows using replace-on-key semantics: a new row with the same
		key overwrites the existing one; counts are never summed. Table-agnostic — the key grain is
		supplied by the caller via KeyColumns, not hardcoded to any table.
	.OUTPUTS
		The merged row set (existing rows whose keys were not re-supplied, plus every new row).
	#>
	[CmdletBinding()]
	param(
		[object[]]$ExistingRows = @(),
		[object[]]$NewRows = @(),
		[Parameter(Mandatory)][string[]]$KeyColumns
	)

	$keyOf = {
		param($r)
		($KeyColumns | ForEach-Object {
			$val = if ($r -is [System.Collections.IDictionary]) { $r[$_] } else { $r.$_ }
			([string]$val).ToLowerInvariant()
		}) -join '|'
	}

	$index = [ordered]@{}
	foreach ($r in @($ExistingRows)) { if ($r) { $index[(& $keyOf $r)] = $r } }
	foreach ($r in @($NewRows))      { if ($r) { $index[(& $keyOf $r)] = $r } }
	return @($index.Values)
}

function Merge-AISIDTableAppendDedup {
	<#
	.SYNOPSIS
		Merges new event rows into existing event rows using append-and-deduplicate semantics: every
		distinct key is kept exactly once, existing history is preserved, and a re-observed event (a new
		row whose key already exists) is dropped rather than duplicated or overwritten. Used for
		event-grain tables where each row is an immutable observation and history accumulates across runs.
		Table-agnostic — the key grain is supplied by the caller via KeyColumns, not hardcoded.
	.OUTPUTS
		The merged row set: all existing rows, plus each new row whose key was not already present.
	#>
	[CmdletBinding()]
	param(
		[object[]]$ExistingRows = @(),
		[object[]]$NewRows = @(),
		[Parameter(Mandatory)][string[]]$KeyColumns
	)

	$keyOf = {
		param($r)
		($KeyColumns | ForEach-Object {
			$val = if ($r -is [System.Collections.IDictionary]) { $r[$_] } else { $r.$_ }
			([string]$val).ToLowerInvariant()
		}) -join '|'
	}

	# Existing history is added first; a re-observed event (a NewRows entry whose key already exists) is
	# neither re-added nor overwritten, so event history only ever grows and never double-counts.
	$index = [ordered]@{}
	foreach ($r in @($ExistingRows)) { if ($r) { $k = & $keyOf $r; if (-not $index.Contains($k)) { $index[$k] = $r } } }
	foreach ($r in @($NewRows))      { if ($r) { $k = & $keyOf $r; if (-not $index.Contains($k)) { $index[$k] = $r } } }
	return @($index.Values)
}

# ─────────────────────────────────────────────────────────────────────────────
# AISID bounded staged history reconciliation (Blocker 2)
# The array-based merges above receive the ENTIRE prior history as an in-memory
# array (Get-AISIDExistingRows loads the whole CSV) held simultaneously with the
# keyed index — multiple copies of accumulated history. The streamed variants
# below reconcile against the prior history WITHOUT materializing it as an array:
# the prior CSV is read one row at a time through the pipeline and only one row
# per key (the output grain) is retained. Semantics are byte-for-byte identical to
# the array merges (replace-on-key = last wins; append-dedup = first wins;
# first-appearance output order), so callers see the same result set. A read that
# fails (locked / permission / malformed — as opposed to a confirmed-absent file)
# propagates so the caller preserves the prior file rather than overwriting it.
# ─────────────────────────────────────────────────────────────────────────────
function Test-AISIDCsvHasDataRow {
	<#
	.SYNOPSIS
		Returns $true when a local CSV exists and has at least one data row (header + >=1), reading at
		most the first two lines. Bounded — never loads the file. A confirmed-absent file returns $false;
		any other read failure propagates so the caller can preserve prior state.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)][string]$Path)
	if (-not (Test-Path -LiteralPath $Path)) { return $false }
	$reader = $null
	try {
		$reader = [System.IO.StreamReader]::new($Path, [System.Text.UTF8Encoding]::new($false))
		$null = $reader.ReadLine()                 # header
		$second = $reader.ReadLine()               # first data row (if any)
		return ($null -ne $second)
	}
	finally {
		if ($reader) { $reader.Dispose() }
	}
}

function Merge-AISIDTableOnKeyStreamed {
	<#
	.SYNOPSIS
		Bounded replace-on-key merge: streams the prior history CSV row-by-row into a keyed index (one
		row per key), then applies the new rows (a new row overwrites the existing one on the same key).
		Identical result to Merge-AISIDTableOnKey, but the full prior-history array is never held. When
		the prior file is absent or header-only (no data rows), the new rows are returned unchanged —
		matching the caller's "merge only when prior history exists" guard exactly.
	#>
	[CmdletBinding()]
	param(
		[string]$ExistingCsvPath,
		[object[]]$NewRows = @(),
		[Parameter(Mandatory)][string[]]$KeyColumns
	)
	$keyOf = {
		param($r)
		($KeyColumns | ForEach-Object {
			$val = if ($r -is [System.Collections.IDictionary]) { $r[$_] } else { $r.$_ }
			([string]$val).ToLowerInvariant()
		}) -join '|'
	}
	$index = [ordered]@{}
	$existingCount = 0
	if ($ExistingCsvPath -and (Test-Path -LiteralPath $ExistingCsvPath)) {
		Import-Csv -LiteralPath $ExistingCsvPath | ForEach-Object { $index[(& $keyOf $_)] = $_; $existingCount++ }
	}
	if ($existingCount -eq 0) { return @($NewRows) }
	foreach ($r in @($NewRows)) { if ($r) { $index[(& $keyOf $r)] = $r } }
	try { Write-PaxMemoryObservation -Stage 'AISIDHistoryReconcile' -RowsProcessed ([long]$index.Count) -Force } catch {}
	return @($index.Values)
}

function Merge-AISIDTableAppendDedupStreamed {
	<#
	.SYNOPSIS
		Bounded append-and-dedup merge: streams the prior history CSV row-by-row into a keyed index
		(first occurrence wins), then applies each new row only if its key is not already present.
		Identical result to Merge-AISIDTableAppendDedup, but the full prior-history array is never held.
		Whether to merge-vs-stub remains the caller's decision (prior history present OR a collected run).
	#>
	[CmdletBinding()]
	param(
		[string]$ExistingCsvPath,
		[object[]]$NewRows = @(),
		[Parameter(Mandatory)][string[]]$KeyColumns
	)
	$keyOf = {
		param($r)
		($KeyColumns | ForEach-Object {
			$val = if ($r -is [System.Collections.IDictionary]) { $r[$_] } else { $r.$_ }
			([string]$val).ToLowerInvariant()
		}) -join '|'
	}
	$index = [ordered]@{}
	if ($ExistingCsvPath -and (Test-Path -LiteralPath $ExistingCsvPath)) {
		Import-Csv -LiteralPath $ExistingCsvPath | ForEach-Object { $k = & $keyOf $_; if (-not $index.Contains($k)) { $index[$k] = $_ } }
	}
	foreach ($r in @($NewRows)) { if ($r) { $k = & $keyOf $r; if (-not $index.Contains($k)) { $index[$k] = $r } } }
	try { Write-PaxMemoryObservation -Stage 'AISIDHistoryReconcile' -RowsProcessed ([long]$index.Count) -Force } catch {}
	return @($index.Values)
}

function Get-AISIDExistingRows {
	<#
	.SYNOPSIS
		Reads the rows already present in a dashboard CSV so a replace-on-key export can merge new rows
		into the accumulated history instead of overwriting it. Resolves the destination tier (local,
		SharePoint, or Fabric/OneLake) and returns the parsed rows.
	.DESCRIPTION
		Critically distinguishes a genuinely absent file (a normal first-run condition -> empty set) from a
		read that FAILED for another reason on a file that may well exist (locked/permission-denied/partial
		or malformed CSV locally; auth/throttle/network or corrupt download remotely). Only a confirmed
		absence returns empty; any other failure is thrown so the caller can preserve the existing file
		rather than overwrite it with an empty-merge result (which would reproduce the original data-loss
		bug from a different cause). Remote not-found is detected as an HTTP 404 via the same
		$_.Exception.Response.StatusCode.value__ inspection used elsewhere for remote 404 handling.

		The reader is merge-mode-agnostic: it only returns the existing rows. The caller decides how to
		combine them, so a future grain (for example event-level append-and-dedup) can reuse it unchanged.
	.OUTPUTS
		An array of existing rows (one object per CSV row), or an empty array when the file is confirmed
		absent. Throws on any non-not-found read failure.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$DestinationDir,
		[Parameter(Mandatory)][string]$FileName,
		[string]$ParentOverride
	)

	$mode = $script:RemoteOutputMode

	if (-not $mode -or $mode -eq 'None') {
		# Local tier. A genuinely absent file is a normal first-run condition -> empty. Any OTHER failure
		# (locked file, permission denied, malformed/partial CSV) must NOT masquerade as "no history" --
		# Import-Csv is left uncaught so it propagates to the caller, which preserves the existing file.
		$path = Join-Path $DestinationDir $FileName
		if (-not (Test-Path -LiteralPath $path)) { return @() }
		return @(Import-Csv -LiteralPath $path)
	}

	# Remote tier (SharePoint / Fabric-OneLake). Download to a temp path via the established remote-read
	# functions, then parse. Only a confirmed HTTP 404 (file not yet present) is treated as an empty
	# first-run set; every other failure (401/403/429/5xx/network, or an unparseable status) propagates so
	# the caller preserves prior state rather than merging as if empty.
	$tmp = Join-Path ([System.IO.Path]::GetTempPath()) ("aisid_read_" + [System.Guid]::NewGuid().ToString('N') + ".csv")
	try {
		try {
			switch ($mode) {
				'SharePoint' { Get-RemoteFile-SharePoint -RelativeName $FileName -DestinationPath $tmp -ParentOverride $ParentOverride }
				'Fabric'     { Get-RemoteFile-OneLake    -RelativeName $FileName -DestinationPath $tmp -ParentOverride $ParentOverride }
			}
		}
		catch {
			$status = try { [int]$_.Exception.Response.StatusCode.value__ } catch { 0 }
			if ($status -eq 404) {
				Write-Verbose ("Get-AISIDExistingRows: remote '{0}' not found (404); treating as first run." -f $FileName)
				return @()
			}
			# Not a confirmed absence -- surface the real failure; the caller preserves prior state.
			throw
		}
		if (-not (Test-Path -LiteralPath $tmp)) { return @() }
		return @(Import-Csv -LiteralPath $tmp)
	}
	finally {
		if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
	}
}

function Get-AISIDExistingCsvToScratch {
	<#
	.SYNOPSIS
		Downloads the remote (SharePoint / Fabric-OneLake) prior-history CSV to a local scratch file and
		returns the scratch path so it can be streamed through the bounded merge — the downloaded file is
		never parsed into an in-memory array. Returns $null when the remote file is confirmed absent
		(HTTP 404 -> first run). Any other failure (401/403/429/5xx/network/unparseable status) throws so
		the caller preserves prior remote state. The CALLER owns cleanup of the returned scratch path
		(removed on success, preserved for recovery on failure) — this mirrors the memory-safe
		download-to-local behavior of Get-AISIDExistingRows without the whole-file Import-Csv.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$FileName,
		[string]$ParentOverride
	)
	$mode = $script:RemoteOutputMode
	if (-not $mode -or $mode -eq 'None') { return $null }
	$tmp = Join-Path ([System.IO.Path]::GetTempPath()) ("aisid_hist_" + [System.Guid]::NewGuid().ToString('N') + ".csv")
	try {
		switch ($mode) {
			'SharePoint' { Get-RemoteFile-SharePoint -RelativeName $FileName -DestinationPath $tmp -ParentOverride $ParentOverride }
			'Fabric'     { Get-RemoteFile-OneLake    -RelativeName $FileName -DestinationPath $tmp -ParentOverride $ParentOverride }
		}
	}
	catch {
		$status = try { [int]$_.Exception.Response.StatusCode.value__ } catch { 0 }
		if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
		if ($status -eq 404) {
			Write-Verbose ("Get-AISIDExistingCsvToScratch: remote '{0}' not found (404); treating as first run." -f $FileName)
			return $null
		}
		throw
	}
	if (-not (Test-Path -LiteralPath $tmp)) { return $null }
	try { Write-PaxMemoryObservation -Stage 'AISIDRemoteHistoryDownloaded' -Force } catch {}
	return $tmp
}

function Export-AISIDCompatibilityTable {
	<#
	.SYNOPSIS
		Publishes a required dashboard compatibility table without collecting new rows. A valid prior
		file is copied byte-for-byte into the new run bundle; only a confirmed-absent prior file becomes
		a header-only table. Read or header failures throw so prior data is never replaced by a false empty.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$Table,
		[Parameter(Mandatory)][string]$DestinationDir,
		[hashtable]$ExistingRows = @{},
		[string]$HistoryDir = '',
		[string]$ParentOverride = ''
	)
	$schema = $script:AISIDTableSchemas[$Table]
	if (-not $schema) { throw "Unknown AISID compatibility table: $Table" }
	if ($ExistingRows.ContainsKey($Table) -and @($ExistingRows[$Table]).Count -gt 0) {
		return Export-AISIDTable -DestinationDir $DestinationDir -FileName $schema.FileName -OrderedColumns $schema.Columns -Rows @($ExistingRows[$Table])
	}

	$source = $null
	$remoteScratch = $false
	if ($script:RemoteOutputMode -and $script:RemoteOutputMode -ne 'None' -and $ParentOverride) {
		$source = Get-AISIDExistingCsvToScratch -FileName $schema.FileName -ParentOverride $ParentOverride
		$remoteScratch = [bool]$source
	}
	elseif ($HistoryDir) {
		$candidate = Join-Path $HistoryDir $schema.FileName
		if (Test-Path -LiteralPath $candidate -PathType Leaf) { $source = $candidate }
	}

	if (-not $source) {
		return Export-AISIDTable -DestinationDir $DestinationDir -FileName $schema.FileName -OrderedColumns $schema.Columns -Rows @()
	}

	$expectedHeader = $schema.Columns -join ','
	$actualHeader = Get-Content -LiteralPath $source -TotalCount 1 -ErrorAction Stop
	if ($actualHeader -cne $expectedHeader) {
		throw ("{0}: prior compatibility file has an invalid header; prior file left unchanged" -f $Table)
	}
	if (-not (Test-Path -LiteralPath $DestinationDir)) { New-Item -ItemType Directory -Path $DestinationDir -Force | Out-Null }
	$target = Join-Path $DestinationDir $schema.FileName
	[System.IO.File]::Copy($source, $target, $true)
	if ($remoteScratch -and (Test-Path -LiteralPath $source)) { Remove-Item -LiteralPath $source -Force -ErrorAction SilentlyContinue }
	return $target
}

function ConvertTo-AISIDInvariantUtcTimestamp {
	<#
	.SYNOPSIS
		Serializes a timestamp value to an invariant, culture-independent ISO-8601 UTC string ending in
		'Z' (round-trip 7-digit fractional form, e.g. 2026-07-01T08:47:59.0000000Z). Format-only: the
		instant is preserved, only its textual representation is normalized. Unparseable input is
		returned as its original string so no value is silently dropped.
	.OUTPUTS
		[string]
	#>
	[CmdletBinding()]
	param([Parameter()] $Value)

	$inv = [System.Globalization.CultureInfo]::InvariantCulture
	$fmt = 'yyyy-MM-ddTHH:mm:ss.fffffffZ'
	if ($null -eq $Value) { return '' }
	if ($Value -is [datetime]) { return ([datetime]$Value).ToUniversalTime().ToString($fmt, $inv) }
	if ($Value -is [System.DateTimeOffset]) { return ([System.DateTimeOffset]$Value).UtcDateTime.ToString($fmt, $inv) }
	$s = [string]$Value
	if ([string]::IsNullOrWhiteSpace($s)) { return '' }
	$parsed = [datetime]::MinValue
	$styles = [System.Globalization.DateTimeStyles]::AdjustToUniversal -bor [System.Globalization.DateTimeStyles]::AssumeUniversal
	if ([datetime]::TryParse($s, $inv, $styles, [ref]$parsed)) { return $parsed.ToString($fmt, $inv) }
	return $s
}

function Get-AISIDFileProximity {
	<#
	.SYNOPSIS
		Collects the File Proximity data set: files created or changed within five minutes of an AI
		website visit on the same device — a temporal-proximity signal (temporal correlation only; not
		proof of exfiltration). Sourced from Defender
		DeviceNetworkEvents (AI site visits) joined to DeviceFileEvents (file activity). Event-grain; the
		collection window is subdivided automatically so no single hunting query approaches the
		advanced-hunting response cap.
	.OUTPUTS
		Hashtable: Success, Rows, RawRowCount, TruncationDetected, AuthQuit, ErrorMessage, Elapsed.
	#>
	[CmdletBinding()]
	param()

	$result = @{
		Success = $false; Rows = @(); RawRowCount = 0; TruncationDetected = $false
		AuthQuit = $false; ErrorMessage = ''; Elapsed = [TimeSpan]::Zero
	}
	$sw = [System.Diagnostics.Stopwatch]::StartNew()

	$domains = @(Get-AISIDNetworkDomains)
	if ($domains.Count -eq 0) {
		Write-LogHost '[AISID] FileProximity: no AI network domains in catalog; skipping query.' -ForegroundColor Yellow
		$result.Success = $true; $sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}

	$domainJson   = ($domains | ForEach-Object { '"' + ($_ -replace '"', '\"') + '"' }) -join ','
	# Collection window: the frozen requested-intersect-available effective interval (half-open).
	$fpBounds = Get-AISIDCollectionBounds
	$startUtc = $fpBounds.StartUtc
	$endUtc   = $fpBounds.EndUtc

	# Builds the DeviceNetworkEvents x DeviceFileEvents 5-minute-proximity join for one time window.
	# The API Timespan already caps the source at the fixed lookback; the window bounds here subdivide
	# that lookback so no single response approaches the row cap. -CountOnly returns the post-join row
	# count for the estimate probe; the full form emits the contractual columns (with the visited URL,
	# which is resolved to an AI solution client-side below).
	# Target-user scope pushed server-side onto the joined events (before the tail projects/aggregates).
	$fpScope = script:Get-AISIDScopeKqlFilter -UpnColumn 'InitiatingProcessAccountUpn'
	$buildQuery = {
		param([datetime]$WinStart, [datetime]$WinEnd, [switch]$CountOnly, [string]$ScopeClause = $fpScope)
		$ws = $WinStart.ToString('yyyy-MM-ddTHH:mm:ss.fffffffZ')
		$we = $WinEnd.ToString('yyyy-MM-ddTHH:mm:ss.fffffffZ')
		$tail = if ($CountOnly) {
			'| summarize N = count()'
		}
		else {
@'
| extend SecondsToAI = datetime_diff('second', FileTimestamp, AITimestamp)
| extend UPN = tolower(InitiatingProcessAccountUpn)
| extend YearMonth = format_datetime(AITimestamp, 'yyyy-MM')
| extend FolderCategory = case(
    FolderPath has 'Desktop', 'Desktop',
    FolderPath has 'Downloads', 'Downloads',
    FolderPath has 'Documents', 'Documents',
    FolderPath has 'OneDrive', 'OneDrive',
    FolderPath has 'SharePoint', 'SharePoint',
    'Other')
| extend NameMatchesSensitivePattern = iff(FileName has_any (SensitiveNamePatterns), 1, 0)
| extend FolderMatchesSensitive = iff(FolderPath has_any (SensitiveFolderPatterns), 1, 0)
| project Timestamp = AITimestamp, RemoteUrl, UPN, YearMonth, FileName, FolderCategory, FolderPath,
          SecondsToAI, NameMatchesSensitivePattern, FolderMatchesSensitive
'@
		}
@"
let AIDomains = dynamic([$domainJson]);
let SensitiveNamePatterns = dynamic(["confidential","secret","password","credential","private","restricted","internal","draft","salary","ssn","pii","financial","budget","forecast","strategy","merger","acquisition","termination","layoff","patent"]);
let SensitiveFolderPatterns = dynamic(["confidential","restricted","hr","legal","finance","executive","board","compliance","audit","security"]);
let WinStart = datetime($ws);
let WinEnd   = datetime($we);
let AIVisits =
    DeviceNetworkEvents
    | where Timestamp between (WinStart .. WinEnd)
    | where ActionType == 'ConnectionSuccess'
    | where RemoteUrl has_any (AIDomains)
    | project AITimestamp = Timestamp, DeviceId, RemoteUrl;
let FileAccess =
    DeviceFileEvents
    | where Timestamp between (WinStart .. (WinEnd + 5m))
    | where ActionType in ('FileCreated', 'FileModified', 'FileRenamed', 'FileCopied')
    | where FileName !endswith '.tmp' and FileName !endswith '.log'
    | project FileTimestamp = Timestamp, DeviceId, FileName, FolderPath, InitiatingProcessAccountUpn;
AIVisits
| join kind=inner FileAccess on DeviceId
| where FileTimestamp between (AITimestamp .. (AITimestamp + 5m))
$ScopeClause
$tail
"@
	}

	# Plan sub-windows so no single query approaches the response cap; each range is re-probed, so a
	# non-uniform distribution only subdivides the ranges that are actually hot.
	$estimateProvider = {
		param($a, $b)
		$probe = & $buildQuery -WinStart $a -WinEnd $b -CountOnly
		Get-AISIDHuntingRowEstimate -ProbeQuery $probe -Description 'FileProximity row-estimate'
	}
	$partitions = @(Get-AISIDTimePartitions -StartUtc $startUtc -EndUtc $endUtc -EstimateProvider $estimateProvider)

	# A partition flagged EstimateFailed means the row-estimate probe was unreadable; fail the table
	# explicitly rather than silently emitting an empty/truncated file (and never retry unbounded).
	if (@($partitions | Where-Object { $_.EstimateFailed }).Count -gt 0) {
		$result.ErrorMessage = 'FileProximity row-estimate probe returned an unreadable result; collection aborted to avoid an unbounded estimate retry and a false-empty output.'
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}
	Write-LogHost ("[AISID] FileProximity: planned {0} time partition(s) for collection." -f $partitions.Count) -ForegroundColor DarkGray

	$rawRows = New-Object System.Collections.Generic.List[object]
	foreach ($p in $partitions) {
		if ($p.Truncated) { $result.TruncationDetected = $true }
		# Batched per partition: for a large scope the source events are filtered per user-batch so every
		# target user's events are queried exactly once; event-grain rows are concatenated (each event's
		# InitiatingProcessAccountUpn belongs to exactly one batch, so there is no cross-batch duplication).
		$__pStart = $p.StartUtc; $__pEnd = $p.EndUtc
		$api = script:Invoke-AISIDBatchedHuntingQuery -UpnColumn 'InitiatingProcessAccountUpn' -Description 'FileProximity' -QueryBuilder ({ param($__scope) & $buildQuery -WinStart $__pStart -WinEnd $__pEnd -ScopeClause $__scope }.GetNewClosure())
		if ($api.AuthQuit) {
			$result.AuthQuit = $true; $result.ErrorMessage = 'Graph token refresh returned Quit'
			$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
		}
		if (-not $api.Success) {
			$result.ErrorMessage = "FileProximity query failed: $($api.ErrorMessage)"
			$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
		}
		if ($api.TruncationDetected) { $result.TruncationDetected = $true }
		foreach ($row in @($api.Results)) { if ($row) { $rawRows.Add($row) } }
	}
	$result.RawRowCount = $rawRows.Count

	# Client-side: resolve each event's AI solution from the visited host (catalog-driven, mirroring how
	# ActivitySessions resolves its application name), then emit the contractual event-grain columns.
	$rows = New-Object System.Collections.Generic.List[object]
	foreach ($r in $rawRows) {
		$hostName = $null
		$ru = [string]$r.RemoteUrl
		if (-not [string]::IsNullOrWhiteSpace($ru)) {
			$parsed = $null
			if ([Uri]::TryCreate($ru, [UriKind]::Absolute, [ref]$parsed)) { $hostName = $parsed.Host }
			else { $hostName = ((($ru -replace '^[A-Za-z][A-Za-z0-9+.\-]*://', '') -replace '/.*$', '') -replace ':\d+$', '') }
		}
		$entry = if ($hostName) { Resolve-AISIDFromDomain -HostName $hostName } else { $null }
		$solution = if ($entry) { [string]$entry.AISolution } else { 'Other AI' }
		$rows.Add([pscustomobject][ordered]@{
			Timestamp                   = (ConvertTo-AISIDInvariantUtcTimestamp -Value $r.Timestamp)
			UPN                         = [string]$r.UPN
			AISolution                  = $solution
			YearMonth                   = [string]$r.YearMonth
			FileName                    = [string]$r.FileName
			FolderCategory              = [string]$r.FolderCategory
			FolderPath                  = [string]$r.FolderPath
			SecondsToAI                 = [int]$r.SecondsToAI
			NameMatchesSensitivePattern = [int]$r.NameMatchesSensitivePattern
			FolderMatchesSensitive      = [int]$r.FolderMatchesSensitive
		})
	}

	$result.Rows    = $rows.ToArray()
	$result.Success = $true
	$sw.Stop(); $result.Elapsed = $sw.Elapsed
	return $result
}

function Get-AISIDClientChannel {
	<#
	.SYNOPSIS
		Collects the Client Channel data set: AI website activity split by access channel — browser vs.
		scripted/API client vs. desktop app — per AI site per month. Sourced from Defender
		DeviceNetworkEvents; the AI sites are filtered by the catalog's network domains, and each event's
		site and channel are labelled server-side (the channel is inferred from initiating-process
		metadata, not a definitive client attribution). Aggregate-grain (one row per site/channel/month), so a
		single hunting query stays well under the advanced-hunting response cap.
	.OUTPUTS
		Hashtable: Success, Rows, RawRowCount, TruncationDetected, AuthQuit, ErrorMessage, Elapsed.
	#>
	[CmdletBinding()]
	param()

	$result = @{
		Success = $false; Rows = @(); RawRowCount = 0; TruncationDetected = $false
		AuthQuit = $false; ErrorMessage = ''; Elapsed = [TimeSpan]::Zero
	}
	$sw = [System.Diagnostics.Stopwatch]::StartNew()

	$domains = @(Get-AISIDNetworkDomains)
	if ($domains.Count -eq 0) {
		Write-LogHost '[AISID] ClientChannel: no AI network domains in catalog; skipping query.' -ForegroundColor Yellow
		$result.Success = $true; $sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}
	$domainJson = ($domains | ForEach-Object { '"' + ($_ -replace '"', '\"') + '"' }) -join ','

	# The catalog's network domains drive the AI-site filter (mirroring FileProximity). The site and
	# channel labels use the authoritative source mapping — visited host -> canonical site, initiating
	# process -> Browser/API/Desktop — applied server-side. The shared hunting-query timespan bounds the
	# collection window; the aggregate collapses to one row per site/channel/month, so no subdivision is
	# needed. (The site case() carries the full source mapping; only catalog-filtered hosts reach it.)
		$ccBounds = Get-AISIDCollectionBounds
	$ccStart  = $ccBounds.StartUtc.ToString('yyyy-MM-ddTHH:mm:ss.fffffffZ')
	$ccEnd    = $ccBounds.EndUtc.ToString('yyyy-MM-ddTHH:mm:ss.fffffffZ')
	# Target-user scope pushed server-side onto the source events BEFORE the site/channel aggregate
	# collapses UPN away (ClientChannel has no per-user output grain, so this is its only scope point).
	$ccScope = script:Get-AISIDScopeKqlFilter -UpnColumn 'InitiatingProcessAccountUpn'
	# Batched: a large scope is split into size-bounded batches; the source events are filtered per batch
	# (every target user's events queried exactly once) and the per-batch aggregates are RE-AGGREGATED
	# below by (AISite, Channel, YearMonth) so counts sum deterministically without duplicate keys.
	$null = $ccScope
	$api = script:Invoke-AISIDBatchedHuntingQuery -UpnColumn 'InitiatingProcessAccountUpn' -Description 'ClientChannel' -QueryBuilder ({
		param($__scope)
@"
let AIDomains = dynamic([$domainJson]);
let WinStart = datetime($ccStart);
let WinEnd   = datetime($ccEnd);
DeviceNetworkEvents
| where Timestamp >= WinStart and Timestamp < WinEnd
| where ActionType == 'ConnectionSuccess'
| where RemoteUrl has_any (AIDomains)
$__scope
| extend AISite = case(
    RemoteUrl has 'copilot.microsoft.com' or RemoteUrl has 'copilot.cloud.microsoft', 'copilot.microsoft.com',
    RemoteUrl has 'chat.openai.com' or RemoteUrl has 'chatgpt.com', 'chatgpt.com',
    RemoteUrl has 'api.openai.com', 'api.openai.com',
    RemoteUrl has 'claude.ai', 'claude.ai',
    RemoteUrl has 'api.anthropic.com', 'api.anthropic.com',
    RemoteUrl has 'gemini.google.com' or RemoteUrl has 'bard.google.com', 'gemini.google.com',
    RemoteUrl has 'perplexity.ai', 'perplexity.ai',
    RemoteUrl has 'midjourney.com', 'midjourney.com',
    RemoteUrl has 'huggingface.co', 'huggingface.co',
    RemoteUrl has 'stability.ai', 'stability.ai',
    RemoteUrl has 'jasper.ai', 'jasper.ai',
    RemoteUrl has 'grammarly.com', 'grammarly.com',
    RemoteUrl has 'notion.so', 'notion.so',
    RemoteUrl has 'firefly.adobe.com', 'firefly.adobe.com',
    RemoteUrl has 'runwayml.com', 'runwayml.com',
    RemoteUrl has 'canva.com', 'canva.com',
    RemoteUrl has 'app.synthesia.io', 'app.synthesia.io',
    RemoteUrl)
| extend Channel = case(
    InitiatingProcessFileName has_any ('chrome.exe', 'msedge.exe', 'firefox.exe', 'brave.exe', 'safari', 'opera.exe', 'iexplore.exe', 'Chrome', 'Safari', 'Firefox'), 'Browser',
    InitiatingProcessFileName has_any ('python', 'node', 'java', 'curl', 'powershell', 'pwsh', 'cmd.exe', 'bash', 'dotnet', 'go'), 'API',
    'Desktop')
| extend YearMonth = format_datetime(Timestamp, 'yyyy-MM')
| summarize EventCount = count() by AISite, Channel, YearMonth
"@
	}.GetNewClosure())
	if ($api.AuthQuit) {
		$result.AuthQuit = $true; $result.ErrorMessage = 'Graph token refresh returned Quit'
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}
	if (-not $api.Success) {
		$result.ErrorMessage = "ClientChannel query failed: $($api.ErrorMessage)"
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}

	$rawRows = @($api.Results)
	$result.RawRowCount = $rawRows.Count
	$result.TruncationDetected = [bool]$api.TruncationDetected

	# Re-aggregate across batches: the same (AISite, Channel, YearMonth) can appear in multiple batches
	# (disjoint user subsets), so EventCount is SUMMED per key — deterministic, no duplicate aggregation.
	$ccAgg = [ordered]@{}
	foreach ($r in $rawRows) {
		if (-not $r) { continue }
		$k = '{0}|{1}|{2}' -f [string]$r.AISite, [string]$r.Channel, [string]$r.YearMonth
		if (-not $ccAgg.Contains($k)) {
			$ccAgg[$k] = [pscustomobject][ordered]@{ AISite = [string]$r.AISite; Channel = [string]$r.Channel; YearMonth = [string]$r.YearMonth; EventCount = 0 }
		}
		$ccAgg[$k].EventCount = [int]$ccAgg[$k].EventCount + [int]$r.EventCount
	}

	$result.Rows    = @($ccAgg.Values)
	$result.Success = $true
	$sw.Stop(); $result.Elapsed = $sw.Elapsed
	return $result
}

function ConvertTo-AISIDUtcInstant {
	<#
	.SYNOPSIS
		Converts an audit event timestamp to a Kind=Utc [datetime] WITHOUT any machine-timezone
		dependency, for AISID window filtering and per-instant (YearMonth / ActiveDays / LastActivityDate)
		grouping.
	.DESCRIPTION
		An explicit Z or numeric offset is authoritative. A [datetime]'s Kind is honored: Utc is returned
		as-is; Local is converted with .ToUniversalTime(); Unspecified (offset-free) is treated as UTC under
		one explicit, documented policy -- NEVER silently as host-local time. A [datetimeoffset] uses its own
		offset (.UtcDateTime). Strings are parsed with the INVARIANT culture and AssumeUniversal|AdjustToUniversal
		styles so a trailing Z or offset governs and an offset-free string is taken as UTC. A [datetime] is
		NEVER stringified and reparsed through the current culture (the prior defect: that produced a
		host-timezone-dependent shift). Malformed/empty input fails clearly.
	.OUTPUTS
		[bool] -- $true and sets [ref]$Utc to a Kind=Utc [datetime] on success; $false on null/malformed input.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)][AllowNull()]$Value, [Parameter(Mandatory)][ref]$Utc)

	if ($null -eq $Value) { return $false }
	if ($Value -is [datetimeoffset]) { $Utc.Value = $Value.UtcDateTime; return $true }
	if ($Value -is [datetime]) {
		switch ([string]$Value.Kind) {
			'Utc'   { $Utc.Value = $Value; return $true }
			'Local' { $Utc.Value = $Value.ToUniversalTime(); return $true }
			default { $Utc.Value = [datetime]::SpecifyKind($Value, [System.DateTimeKind]::Utc); return $true }
		}
	}
	$s = [string]$Value
	if ([string]::IsNullOrWhiteSpace($s)) { return $false }
	$dto = [datetimeoffset]::MinValue
	$styles = [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal
	if ([datetimeoffset]::TryParse($s, [System.Globalization.CultureInfo]::InvariantCulture, $styles, [ref]$dto)) {
		$Utc.Value = $dto.UtcDateTime
		return $true
	}
	return $false
}

function Get-AISIDCopilotUsage {
	<#
	.SYNOPSIS
		Builds the Copilot Usage data set (per-user, per-month prompt counts across the six MODELED
		surfaces: Teams / Word / Excel / Outlook / PowerPoint / Chat) from the CURRENT run's RAW Purview
		CopilotInteraction CSV. No second audit search and no Graph call: it streams the raw CSV, parses
		each AuditData JSON, and pivots AuditData.CopilotEventData.AppHost against a fixed, case-insensitive
		allowlist. This is deliberately the six modeled surfaces ONLY - it is NOT comprehensive Microsoft 365
		Copilot usage; any AppHost that cannot map to one of the six columns (Security Copilot, Copilot Studio,
		M365 Admin Center, and other unmodeled hosts) is excluded from every surface AND from TotalPrompts, so
		TotalPrompts always reconciles to the six-surface sum.
	.NOTES
		Source path is passed explicitly (-RawPurviewCsv = the current run's raw Purview CSV, still present and
		identified at the post-rollup AISID call). AuditData.CreationTime is the CopilotUsage event timestamp.
		Fails gracefully (Success=$false) only for CopilotUsage when the source is absent/unreadable or every
		record is unusable, so the export falls that one table back to a header-only file.
	.OUTPUTS
		Hashtable: Success, Rows, RawRowCount, TruncationDetected, AuthQuit, ErrorMessage, Elapsed.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)][string]$RawPurviewCsv)

	$result = @{
		Success = $false; Rows = @(); RawRowCount = 0; TruncationDetected = $false
		AuthQuit = $false; ErrorMessage = ''; Elapsed = [TimeSpan]::Zero
	}
	$sw = [System.Diagnostics.Stopwatch]::StartNew()

	if ([string]::IsNullOrWhiteSpace($RawPurviewCsv) -or -not (Test-Path -LiteralPath $RawPurviewCsv -PathType Leaf)) {
		$result.ErrorMessage = 'CopilotUsage: raw Purview CopilotInteraction CSV not available; cannot build the Copilot Usage data set.'
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}

	# AISID effective collection window (frozen). Records outside [start, end) are excluded before grouping.
	$cuBounds   = Get-AISIDCollectionBounds
	$cuStartUtc = $cuBounds.StartUtc
	$cuEndUtc   = $cuBounds.EndUtc

	# AppHost -> surface (six modeled surfaces ONLY). Case-insensitive exact match after trim. Any AppHost
	# absent here is EXCLUDED from every surface AND from TotalPrompts (so Total reconciles to the six-surface
	# sum). No wildcards; no unknown-to-Chat. Keys are lowercase for case-insensitive lookup.
	$surfaceOf = @{
		'teams' = 'TeamsPrompts'
		'word' = 'WordPrompts'; 'wordoncanvas' = 'WordPrompts'
		'excel' = 'ExcelPrompts'
		'outlook' = 'OutlookPrompts'; 'outlookoncanvas' = 'OutlookPrompts'; 'outlooksidepane' = 'OutlookPrompts'
		'powerpoint' = 'PowerPointPrompts'; 'powerpointoncanvas' = 'PowerPointPrompts'
		'bizchat' = 'ChatPrompts'; 'bing' = 'ChatPrompts'; 'office' = 'ChatPrompts'; 'edge' = 'ChatPrompts'
		'm365app' = 'ChatPrompts'; 'm365chat' = 'ChatPrompts'; 'officecopilotnotebook' = 'ChatPrompts'
		'officecopilotsearchanswer' = 'ChatPrompts'; 'onenotecopilotnotebook' = 'ChatPrompts'
	}

	$agg = [ordered]@{}
	$rawCount = 0; $skipped = 0; $included = 0; $outOfWindow = 0; $responseOnly = 0
	$exSec = 0; $exStudio = 0; $exAdmin = 0; $exOther = 0
	try {
		Import-Csv -LiteralPath $RawPurviewCsv | ForEach-Object {
			$rawCount++
			$d = $null
			try { $d = $_.AuditData | ConvertFrom-Json -ErrorAction Stop } catch { $d = $null }
			if (-not $d) { $skipped++; return }
			$upnRaw = [string]$d.UserId
			if ([string]::IsNullOrWhiteSpace($upnRaw)) { $skipped++; return }
			$dtU = [datetime]::MinValue
			# Convert the audit event timestamp to a UTC instant with NO machine-timezone dependency (an explicit
			# Z/offset is authoritative; a DateTime Kind is honored; offset-free => UTC by documented policy).
			# Never stringify-and-reparse through the current culture (the prior host-timezone-dependent defect).
			if (-not (ConvertTo-AISIDUtcInstant -Value $d.CreationTime -Utc ([ref]$dtU))) { $skipped++; return }
			# AISID window filter: keep only records whose UTC instant is in the frozen half-open interval.
			if ($dtU -lt $cuStartUtc -or $dtU -ge $cuEndUtc) { $outOfWindow++; return }
			$appHostRaw = ([string]$d.CopilotEventData.AppHost).Trim()
			$key = $appHostRaw.ToLowerInvariant()
			if (-not $surfaceOf.ContainsKey($key)) {
				if     ($appHostRaw -like 'SecurityCopilot-*') { $exSec++ }
				elseif ($key -eq 'copilot studio')             { $exStudio++ }
				elseif ($key -eq 'm365admincenter')            { $exAdmin++ }
				else                                            { $exOther++ }
				return
			}
			$surface = $surfaceOf[$key]
			$included++
			# Count actual user-prompt messages in this record (CopilotEventData.Messages[].isPrompt === $true). A
			# response-only record (zero prompt messages) contributes NOTHING to any surface, TotalPrompts, ActiveDays,
			# or LastActivityDate; a record with N prompt messages contributes N (no one-prompt-per-record assumption).
			$promptCount = 0
			$msgs = $d.CopilotEventData.Messages
			if ($null -ne $msgs) { foreach ($m in @($msgs)) { if ($m -and $m.isPrompt -eq $true) { $promptCount++ } } }
			if ($promptCount -le 0) { $responseOnly++; return }
			$upn = $upnRaw.ToLowerInvariant()
			$ym  = $dtU.ToString('yyyy-MM')
			$day = $dtU.ToString('yyyy-MM-dd')
			$aggKey = '{0}|{1}' -f $upn, $ym
			if (-not $agg.Contains($aggKey)) {
				$agg[$aggKey] = @{
					UserPrincipalName = $upn; YearMonth = $ym
					TeamsPrompts = 0; WordPrompts = 0; ExcelPrompts = 0; OutlookPrompts = 0; PowerPointPrompts = 0; ChatPrompts = 0
					TotalPrompts = 0; Days = (New-Object 'System.Collections.Generic.HashSet[string]'); LastDay = ''
				}
			}
			$b = $agg[$aggKey]
			$b[$surface]    = [int]$b[$surface] + $promptCount
			$b.TotalPrompts = [int]$b.TotalPrompts + $promptCount
			[void]$b.Days.Add($day)
			if ($day -gt [string]$b.LastDay) { $b.LastDay = $day }
		}
	}
	catch {
		$result.ErrorMessage = "CopilotUsage: failed to stream raw Purview CSV: $($_.Exception.Message)"
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}

	$result.RawRowCount = $rawCount

	if ($rawCount -gt 0 -and ($rawCount - $skipped) -eq 0) {
		$result.ErrorMessage = "CopilotUsage: all $rawCount raw record(s) were malformed/unusable; falling back to header-only for this table."
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}

	$rows = New-Object System.Collections.Generic.List[object]
	foreach ($b in $agg.Values) {
		$rows.Add([pscustomobject][ordered]@{
			UserPrincipalName = [string]$b.UserPrincipalName
			YearMonth         = [string]$b.YearMonth
			TeamsPrompts      = [int]$b.TeamsPrompts
			WordPrompts       = [int]$b.WordPrompts
			ExcelPrompts      = [int]$b.ExcelPrompts
			OutlookPrompts    = [int]$b.OutlookPrompts
			PowerPointPrompts = [int]$b.PowerPointPrompts
			ChatPrompts       = [int]$b.ChatPrompts
			TotalPrompts      = [int]$b.TotalPrompts
			ActiveDays        = [int]$b.Days.Count
			LastActivityDate  = [string]$b.LastDay
		})
	}

	if ($skipped -gt 0) {
		Write-LogHost ("[AISID] CopilotUsage: skipped {0} malformed/incomplete record(s)." -f $skipped) -ForegroundColor DarkYellow
	}
	$exTotal = $exSec + $exStudio + $exAdmin + $exOther
	Write-LogHost ("[AISID] CopilotUsage: raw={0} in-scope={1} response-only={9} out-of-window={8} excluded={2} (SecurityCopilot-<GUID>={3}, Copilot Studio={4}, M365AdminCenter={5}, Other unmodeled={6}); user-month rows={7}." -f $rawCount, $included, $exTotal, $exSec, $exStudio, $exAdmin, $exOther, $rows.Count, $outOfWindow, $responseOnly) -ForegroundColor DarkGray

	$result.Rows    = $rows.ToArray()
	$result.Success = $true
	$sw.Stop(); $result.Elapsed = $sw.Elapsed
	return $result
}

function New-AISIDFileProximityStub {
	<#
	.SYNOPSIS
		Emits the permanent header-only file-proximity CSV. This table is always empty by design:
		the dashboard model loads the file on every refresh, but no query, licensing check, or Graph
		call is involved — the header alone satisfies the model's fixed schema.
	.OUTPUTS
		The full path of the stub file written.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)][string]$DestinationDir)

	$schema = $script:AISIDTableSchemas['FileProximity']
	return Export-AISIDTable -DestinationDir $DestinationDir -FileName $schema.FileName -OrderedColumns $schema.Columns -Rows @()
}

function Get-AISIDActivitySessions {
	<#
	.SYNOPSIS
		Collects the Activity Sessions data set from cloud-app activity and returns enriched rows in
		the contractual column shape. Server-side aggregation keeps the result small; catalog-driven
		enrichment (application name -> AI solution / category / risk tier) is applied client-side and
		collapsed to one row per (UPN, AISolution, YearMonth).
	.OUTPUTS
		Hashtable: Success, Rows, RawRowCount, TruncationDetected, AuthQuit, ErrorMessage, Elapsed.
	#>
	[CmdletBinding()]
	param()

	$result = @{
		Success = $false; Rows = @(); RawRowCount = 0; TruncationDetected = $false
		AuthQuit = $false; ErrorMessage = ''; Elapsed = [TimeSpan]::Zero
	}
	$sw = [System.Diagnostics.Stopwatch]::StartNew()

	$cloudAppNames = @(Get-AISIDCloudAppNames)
	if ($cloudAppNames.Count -eq 0) {
		Write-LogHost '[AISID] ActivitySessions: no cloud-app names in catalog; skipping query.' -ForegroundColor Yellow
		$result.Success = $true; $sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}

	# The collection window is bounded by the shared hunting-query timespan; the query filters to the
	# catalog's cloud-app names, resolves each event's canonical user principal name from the directory
	# identity data (falling back to the raw account object id when the directory has no match for that
	# identity), and aggregates per user/app/month server-side.
	$appFilterJson = ($cloudAppNames | ForEach-Object { '"' + ($_ -replace '"', '\"') + '"' }) -join ','
		$asBounds = Get-AISIDCollectionBounds
	$asStart  = $asBounds.StartUtc.ToString('yyyy-MM-ddTHH:mm:ss.fffffffZ')
	$asEnd    = $asBounds.EndUtc.ToString('yyyy-MM-ddTHH:mm:ss.fffffffZ')
	$asScope  = script:Get-AISIDScopeKqlFilter -UpnColumn 'UPN'
	# Batched: a large target scope is split into deterministic size-bounded batches; the query runs once
	# per batch (every target user queried exactly once) and the rows are concatenated. $asScope is
	# retained for structural parity but the per-batch clause ($__scope) is what the runner injects.
	$null = $asScope
	$api = script:Invoke-AISIDBatchedHuntingQuery -UpnColumn 'UPN' -Description 'ActivitySessions' -QueryBuilder ({
		param($__scope)
@"
let AppFilter = dynamic([$appFilterJson]);
let UserUpns = IdentityInfo
    | summarize take_any(AccountUpn) by AccountObjectId;
let WinStart = datetime($asStart);
let WinEnd   = datetime($asEnd);
CloudAppEvents
| where Timestamp >= WinStart and Timestamp < WinEnd
| where Application in~ (AppFilter)
| lookup kind=leftouter UserUpns on AccountObjectId
| extend UPN = tolower(coalesce(AccountUpn, AccountObjectId))
| where isnotempty(UPN)
$__scope
| summarize
    Sessions         = count(),
    ActiveDays       = dcount(format_datetime(Timestamp, 'yyyy-MM-dd')),
    EstimatedPrompts = countif(ActionType in ("MessageSent", "SearchPerformed", "AppAccessedViaAPI")),
    DistinctDevices  = dcount(DeviceType)
  by UPN, AppNameMatched = Application, YearMonth = format_datetime(Timestamp, 'yyyy-MM')
"@
	}.GetNewClosure())

	if ($api.AuthQuit) {
		$result.AuthQuit = $true; $result.ErrorMessage = 'Graph token refresh returned Quit'
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}
	if (-not $api.Success) {
		$result.ErrorMessage = "ActivitySessions query failed: $($api.ErrorMessage)"
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}

	$rawRows = @($api.Results)
	$result.RawRowCount = $rawRows.Count
	$result.TruncationDetected = [bool]$api.TruncationDetected

	# Enrich each raw row and collapse catalog aliases that resolve to the same solution. Distinct-count
	# metrics (ActiveDays, DistinctDevices) cannot be re-derived exactly once aliases collapse, so take
	# the max as a safe upper bound; additive count metrics (Sessions, EstimatedPrompts) sum, since each
	# raw app alias contributes a disjoint set of events.
	$agg = [ordered]@{}
	foreach ($r in $rawRows) {
		if (-not $r) { continue }
		$appName  = [string]$r.AppNameMatched
		$resolved = Resolve-AISIDFromAppName -AppName $appName
		$solution = if ($resolved) { $resolved.AISolution } else { $appName }
		$category = if ($resolved) { $resolved.Category }   else { 'Unknown' }
		$riskTier = if ($resolved) { $resolved.RiskTier }   else { 'Unknown' }
		$key = '{0}|{1}|{2}' -f ([string]$r.UPN).ToLowerInvariant(), $solution, [string]$r.YearMonth

		if (-not $agg.Contains($key)) {
			$agg[$key] = [ordered]@{
				UPN = [string]$r.UPN; AISolution = $solution; YearMonth = [string]$r.YearMonth
				Sessions = 0; ActiveDays = 0; EstimatedPrompts = 0; DistinctDevices = 0
				Category = $category; RiskTier = $riskTier
			}
		}
		$b = $agg[$key]
		$b.Sessions         = [int]$b.Sessions + [int]$r.Sessions
		$b.ActiveDays       = [Math]::Max([int]$b.ActiveDays,      [int]$r.ActiveDays)
		$b.DistinctDevices  = [Math]::Max([int]$b.DistinctDevices, [int]$r.DistinctDevices)
		$b.EstimatedPrompts = [int]$b.EstimatedPrompts + [int]$r.EstimatedPrompts
	}

	$result.Rows    = @($agg.Values | ForEach-Object { [pscustomobject]$_ })
	$result.Success = $true
	$sw.Stop(); $result.Elapsed = $sw.Elapsed
	return $result
}

function script:Get-AISIDScratchRoot {
	# ONE run-specific internal AISID scratch root under OS temp. Unique per run — its leaf carries the
	# global ScriptRunTimestamp, the process id, a per-run random nonce, AND a hash of the resolved user
	# scope — so no two runs, and no two user scopes, ever share a scratch root or an off-hours/geography
	# cache. Created on first use; deleted wholesale after a successful publication
	# (Remove-AISIDScratchRoot). It is NEVER placed under the customer output folder, so a successful run
	# leaves no cache/scratch behind.
	if (-not $script:AISIDScratchNonce) { $script:AISIDScratchNonce = [System.Guid]::NewGuid().ToString('N').Substring(0, 12) }
	$scopeSrc  = (@($script:targetUsers) | ForEach-Object { ([string]$_).Trim().ToLowerInvariant() } | Where-Object { $_ } | Sort-Object -Unique) -join '|'
	$scopeHash = ([BitConverter]::ToString([System.Security.Cryptography.SHA256]::Create().ComputeHash([System.Text.Encoding]::UTF8.GetBytes($scopeSrc)))).Replace('-', '').Substring(0, 8)
	$leaf = 'PAX_AISID_{0}_{1}_{2}_{3}' -f $global:ScriptRunTimestamp, $PID, $script:AISIDScratchNonce, $scopeHash
	return (Join-Path ([System.IO.Path]::GetTempPath()) $leaf)
}

function script:Get-AISIDCacheDir {
	# The off-hours/geography delta cache lives beneath the run-specific scratch root
	# (Get-AISIDScratchRoot) in OS temp, NEVER in the customer output folder. Because the scratch root is
	# unique per run, the cache is intra-run only — it is never reused between independent runs, and one
	# scope can never read another scope's cache. The '.aisid_cache' leaf is created under the returned
	# directory by Save-AISIDOffHoursGeoCache. The DestinationDir parameter is retained for call-site
	# compatibility but intentionally ignored (the cache location is no longer destination-keyed).
	param([Parameter()][AllowEmptyString()][string]$DestinationDir = '')
	return (script:Get-AISIDScratchRoot)
}

function script:Remove-AISIDScratchRoot {
	# Recursively delete the run-specific AISID scratch root after a successful publication and twelve-CSV
	# verification. Returns $true only when the root no longer exists on disk. A residual scratch root is a
	# completed-with-gaps condition (the caller sets AISIDHadGaps -> exit 40 and logs the residual path) —
	# a successful AISID run leaves no cache or scratch directory anywhere.
	param([Parameter()][AllowEmptyString()][string]$Root = '')
	if ([string]::IsNullOrWhiteSpace($Root)) { return $true }
	if (-not (Test-Path -LiteralPath $Root)) { return $true }
	try { [System.GC]::Collect(); [System.GC]::WaitForPendingFinalizers() } catch {}
	try { Remove-Item -LiteralPath $Root -Recurse -Force -ErrorAction Stop } catch {}
	return (-not (Test-Path -LiteralPath $Root))
}

function script:Get-AISIDFabricRunFolderUrl {
	# Defect-3: build the CANONICAL Fabric AISID run-folder URL from Resolve-FabricTarget's structured
	# result so the twelve fixed-name CSV bundle ALWAYS lives under Files/ (never Tables/) and the produced
	# URL round-trips through Resolve-FabricTarget. Root, GUID-root, /Files[/<sub>], and /Tables[/<schema>]
	# parents all resolve to '<FilesystemBase>/<ItemFull>/Files/[<FilesPath>/]<Leaf>'. Tables inputs route
	# the operational CSV bundle under Files/ (TablesPath is intentionally ignored), consistent with the
	# established operational-artifact routing policy (Send-FileToOneLake). Never appends the leaf to the
	# raw parent URL. Returns '' when the parent cannot be parsed (caller treats '' as no remote target).
	param([Parameter(Mandatory)][string]$ParentUrl, [Parameter(Mandatory)][string]$Leaf)
	if ([string]::IsNullOrWhiteSpace($ParentUrl)) { return '' }
	try {
		$r = Resolve-FabricTarget -Url $ParentUrl
		$filesBase = "$($r.FilesystemBase)/$($r.ItemFull)/Files"
		$rel = if ($r.FilesPath) { "$($r.FilesPath)/$Leaf" } else { [string]$Leaf }
		return "$filesBase/$rel"
	}
	catch { return '' }
}

function script:Resolve-AISIDRunFolder {
	# Canonical AISID run-folder resolver: every AISID run publishes the twelve fixed-name CSVs into a
	# per-run 'AISID_<ScriptRunTimestamp>' child folder beneath the DefenderUsage destination, on ALL
	# tiers (Local / SharePoint / Fabric). One resolver drives writes, existing-history reads, completion
	# checks, upload destination construction, upload registration, roster, metrics/snapshots, checkpoint/
	# resume, recovery, and AppendDefenderUsage, so every consumer agrees on one location. The twelve
	# filenames inside are NEVER renamed. Optional test-injection of the resolved DefenderUsage dir and
	# remote parent keeps the resolver pure for focused tests.
	param(
		[string]$ParentOverride = '',
		[string]$EffectiveDirOverride = $null,
		[string]$RemoteParentOverride = $null
	)
	$leaf = 'AISID_' + $global:ScriptRunTimestamp
	$mode = if ($script:RemoteOutputMode) { [string]$script:RemoteOutputMode } else { 'None' }
	$effDir =
		if (-not [string]::IsNullOrEmpty($EffectiveDirOverride)) { [string]$EffectiveDirOverride }
		else { $du = script:Resolve-DataTypePaths -DataType 'DefenderUsage'; if ($du -and $du.EffectiveDir) { [string]$du.EffectiveDir } else { '' } }
	$localFolder = if ($effDir) { Join-Path $effDir $leaf } else { $leaf }
	$remoteParent =
		if ($ParentOverride) { [string]$ParentOverride }
		elseif (-not [string]::IsNullOrEmpty($RemoteParentOverride)) { [string]$RemoteParentOverride }
		elseif ($script:DestParentUrl -and $script:DestParentUrl['DefenderUsage']) { [string]$script:DestParentUrl['DefenderUsage'] }
		else { '' }
	# Defect-3: on Fabric the AISID bundle URL is built from Resolve-FabricTarget's structured result so
	# it ALWAYS lands under Files/ and round-trips through Resolve-FabricTarget (a root/Tables parent
	# appended raw would be an invalid third segment). SharePoint / other tiers keep the folder-URL join.
	$remoteUrl =
		if ($mode -eq 'None' -or -not $remoteParent) { '' }
		elseif ($mode -eq 'Fabric') { script:Get-AISIDFabricRunFolderUrl -ParentUrl $remoteParent -Leaf $leaf }
		else { (($remoteParent -replace '/+$', '') + '/' + $leaf) }
	$staging = Join-Path (script:Get-AISIDScratchRoot) $leaf
	$writeDir = if ($mode -ne 'None') { $staging } else { $localFolder }
	$display  = if ($mode -ne 'None') { $remoteUrl } else { $localFolder }
	return [pscustomobject][ordered]@{
		RunLeaf              = $leaf
		Mode                 = $mode
		LocalRunFolder       = $localFolder
		RemoteRunFolderUrl   = $remoteUrl
		RemoteScratchStaging = $staging
		WriteDir             = $writeDir
		DisplayPath          = $display
	}
}

function script:Get-AISIDUploadPlan {
	# Blocker-1: builds the AUTHORITATIVE remote AISID upload set from the run-specific staging directory
	# ($script:AISIDRunFolder.RemoteScratchStaging) — never from the general run scratch dir. For each
	# expected fixed-name leaf it REQUIRES the staged file to exist under $StagingDir and takes its full
	# path from there, so an unrelated same-named file elsewhere can never impersonate an AISID artifact.
	# Returns the resolved staged file objects (exactly one per present leaf, deduped case-insensitively),
	# the set of missing leaves, and Complete=$true only when every expected leaf was found in staging.
	param(
		[Parameter(Mandatory)][AllowEmptyString()][string]$StagingDir,
		[Parameter(Mandatory)][AllowEmptyCollection()][string[]]$ExpectedLeafs
	)
	$files   = New-Object System.Collections.Generic.List[object]
	$missing = New-Object System.Collections.Generic.List[string]
	$seen    = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
	foreach ($leaf in @($ExpectedLeafs)) {
		if (-not $leaf) { continue }
		if (-not $seen.Add($leaf)) { continue }
		$full = if ($StagingDir) { Join-Path $StagingDir $leaf } else { '' }
		if ($full -and (Test-Path -LiteralPath $full -PathType Leaf)) { $files.Add((Get-Item -LiteralPath $full)) }
		else { [void]$missing.Add($leaf) }
	}
	return [pscustomobject][ordered]@{
		Files        = @($files.ToArray())
		MissingLeafs = @($missing.ToArray())
		Complete     = ($missing.Count -eq 0 -and $files.Count -gt 0)
	}
}

function script:Resolve-AISIDUploadParentUrl {
	# Blocker-1: the per-run AISID child URL ($script:AISIDRemoteRunFolderUrl) is the upload parent for
	# every AISID fixed-name leaf on every remote tier (SharePoint / Fabric); all other artifacts keep
	# their default per-data-type parent. Isolated so the upload sweep's AISID routing is behaviorally
	# testable without reconstructing the sweep.
	param([Parameter(Mandatory)][string]$Leaf, [Parameter()][AllowEmptyString()][string]$DefaultParentUrl = '')
	if ($script:AISIDUploadLeafs -and $script:AISIDUploadLeafs.Contains($Leaf) -and $script:AISIDRemoteRunFolderUrl) {
		return [string]$script:AISIDRemoteRunFolderUrl
	}
	return [string]$DefaultParentUrl
}

function script:New-AISIDRunFolderOwnership {
	# Blocker-5: acquire EXCLUSIVE ownership of a local AISID run folder atomically. A one-second run
	# timestamp cannot distinguish two concurrent processes, so Test-Path+CreateDirectory is not a valid
	# ownership decision (both can win the race). This uses an atomic FileMode.CreateNew marker in the
	# PARENT folder — the OS guarantees exactly one creator — as the ownership gate, THEN creates the run
	# folder. Returns { Acquired=[bool]; Reason=[string]; MarkerPath=[string] }. An already-existing run
	# folder (a prior non-resume run) or an existing marker (a concurrent/failed run) is a collision and
	# fails closed — this never deletes or overwrites another run's folder or marker.
	param([Parameter(Mandatory)][string]$RunFolder)
	$parent = Split-Path -Parent $RunFolder
	$leaf   = Split-Path -Leaf   $RunFolder
	if ([string]::IsNullOrWhiteSpace($parent)) { $parent = (Get-Location).Path }
	try { [void][System.IO.Directory]::CreateDirectory($parent) }
	catch { return [pscustomobject]@{ Acquired = $false; Reason = ('parent-uncreatable: ' + $_.Exception.Message); MarkerPath = '' } }
	# An existing run folder is a collision (no resume-identity verification is available here).
	if (Test-Path -LiteralPath $RunFolder) { return [pscustomobject]@{ Acquired = $false; Reason = 'run-folder-exists'; MarkerPath = '' } }
	$marker = Join-Path $parent ('.aisid_own_' + $leaf)
	$fs = $null
	try {
		$fs = [System.IO.File]::Open($marker, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
		$bytes = [System.Text.Encoding]::UTF8.GetBytes(('{0}|{1}|{2}' -f $PID, $global:ScriptRunTimestamp, ((Get-Date).ToUniversalTime().ToString('o'))))
		$fs.Write($bytes, 0, $bytes.Length)
	}
	catch [System.IO.IOException] {
		if ($fs) { $fs.Dispose() }
		return [pscustomobject]@{ Acquired = $false; Reason = 'ownership-marker-exists'; MarkerPath = $marker }
	}
	catch {
		if ($fs) { $fs.Dispose() }
		return [pscustomobject]@{ Acquired = $false; Reason = ('marker-uncreatable: ' + $_.Exception.Message); MarkerPath = $marker }
	}
	finally { if ($fs) { $fs.Dispose() } }
	# Marker acquired exclusively — create the run folder now.
	try { [void][System.IO.Directory]::CreateDirectory($RunFolder) }
	catch {
		# Defect-3 fail-closed: the marker was acquired but the run folder could not be created. Remove the
		# marker immediately and verify its absence so NO unregistered/orphan marker is left behind. If the
		# marker itself cannot be removed, surface a structured cleanup failure that still names it.
		$__rfErr = $_.Exception.Message
		$__removed = $false
		try { Remove-Item -LiteralPath $marker -Force -ErrorAction Stop; $__removed = -not (Test-Path -LiteralPath $marker) } catch { $__removed = $false }
		if ($__removed) { return [pscustomobject]@{ Acquired = $false; Reason = ('run-folder-uncreatable: ' + $__rfErr); MarkerPath = ''; CleanupFailed = $false } }
		return [pscustomobject]@{ Acquired = $false; Reason = ('run-folder-uncreatable; marker cleanup FAILED: ' + $__rfErr); MarkerPath = $marker; CleanupFailed = $true }
	}
	return [pscustomobject]@{ Acquired = $true; Reason = 'acquired'; MarkerPath = $marker; CleanupFailed = $false }
}

function script:Get-AISIDRemoteFolderProbe {
	# Blocker-4: read-only existence probe for a remote AISID run-folder URL. Returns
	# { Accessible=[bool]; Exists=[bool] }. A confirmed HTTP 404 is Accessible=$true/Exists=$false (normal
	# first run); a 2xx is Exists=$true; any auth/throttle/network/5xx/unparseable failure is
	# Accessible=$false so the caller fails closed. NEVER creates or modifies the folder — a metadata GET
	# (SharePoint driveItem) / directory HEAD (Fabric DFS) only. Uses the established target resolution
	# and transport. Isolated so the collision decision is behaviorally testable via injection.
	param(
		[Parameter(Mandatory)][string]$Url,
		[Parameter(Mandatory)][ValidateSet('SharePoint', 'Fabric')][string]$Mode
	)
	try {
		if ($Mode -eq 'SharePoint') {
			$resolved = Resolve-SharePointTarget -Url $Url
			$folderPath = if ($resolved.FolderPath) { $resolved.FolderPath } else { '' }
			$metaUri = if ($folderPath) {
				$esc = ($folderPath -split '/' | ForEach-Object { [System.Uri]::EscapeDataString($_) }) -join '/'
				"https://graph.microsoft.com/v1.0/drives/$($resolved.DriveId)/root:/${esc}"
			}
			else { "https://graph.microsoft.com/v1.0/drives/$($resolved.DriveId)/root" }
			$graphToken = Get-GraphAccessToken
			if (-not $graphToken) { return [pscustomobject]@{ Accessible = $false; Exists = $false } }
			try {
				$null = Invoke-WebRequest -Uri $metaUri -Method GET -Headers @{ Authorization = "Bearer $graphToken" } -UseBasicParsing -ErrorAction Stop
				return [pscustomobject]@{ Accessible = $true; Exists = $true }
			}
			catch {
				$status = try { [int]$_.Exception.Response.StatusCode.value__ } catch { 0 }
				if ($status -eq 404) { return [pscustomobject]@{ Accessible = $true; Exists = $false } }
				return [pscustomobject]@{ Accessible = $false; Exists = $false }
			}
		}
		else {
			$resolved = Resolve-FabricTarget -Url $Url
			$dirPath = "$($resolved.FilesystemBase)/$($resolved.ItemFull)/Files/$($resolved.FilesPath)"
			try {
				$null = Invoke-FabricWebRequest -Uri $dirPath -Method HEAD
				return [pscustomobject]@{ Accessible = $true; Exists = $true }
			}
			catch {
				$status = try { [int]$_.Exception.Response.StatusCode.value__ } catch { 0 }
				if ($status -eq 404) { return [pscustomobject]@{ Accessible = $true; Exists = $false } }
				return [pscustomobject]@{ Accessible = $false; Exists = $false }
			}
		}
	}
	catch { return [pscustomobject]@{ Accessible = $false; Exists = $false } }
}

function script:Test-AISIDRemoteRunFolderState {
	# Blocker-4: classify a remote AISID run-folder URL as 'Absent' | 'Exists' | 'Inaccessible' from the
	# read-only probe, distinguishing a confirmed absence (safe to create/upload) from a confirmed
	# existing folder (collision -> fail closed, never touched) and from a lookup/transport/authorization
	# failure (fail closed instead of assuming absence). The caller blocks on 'Exists' and 'Inaccessible'.
	param(
		[Parameter(Mandatory)][string]$Url,
		[Parameter(Mandatory)][ValidateSet('SharePoint', 'Fabric')][string]$Mode
	)
	try {
		$probe = script:Get-AISIDRemoteFolderProbe -Url $Url -Mode $Mode
		if ($null -eq $probe -or $probe.Accessible -ne $true) { return 'Inaccessible' }
		if ($probe.Exists -eq $true) { return 'Exists' }
		return 'Absent'
	}
	catch { return 'Inaccessible' }
}

function script:New-AISIDRemoteRunFolderSharePoint {
	# Defect-1/2: EXCLUSIVELY create the exact timestamped SharePoint AISID child folder via a single POST
	# to the parent's /children with '@microsoft.graph.conflictBehavior'='fail'. The POST is the
	# AUTHORITATIVE ownership decision (2xx = exclusive create; 409 / nameAlreadyExists = collision), so
	# two same-second runs cannot both proceed. NEVER uses 'replace'/'rename'; NEVER treats an existing
	# folder as success; NEVER modifies or deletes an existing folder. Not routed through
	# Test-RemoteDestination (which targets the parent destination, not this timestamped child). Returns
	# { State='Acquired'|'Collision'|'Inaccessible'; Reason }.
	param([Parameter(Mandatory)][string]$Url)
	$resolved = Resolve-SharePointTarget -Url $Url
	$folderPath = if ($resolved.FolderPath) { [string]$resolved.FolderPath } else { '' }
	if (-not $folderPath) { return [pscustomobject]@{ State = 'Inaccessible'; Reason = 'resolved child URL carries no folder path' } }
	# Defect-2: Resolve-SharePointTarget derives FolderPath from Uri.AbsolutePath, whose segments are
	# ALREADY percent-encoded (e.g. 'PAX%20Exports/Sub%20Folder'). Re-escaping them would double-encode
	# ('%2520'). Canonicalize each segment EXACTLY ONCE: decode to its display value, then encode that
	# once. The Graph colon-path is built from the single-encoded parent segments; the POST body child
	# 'name' is the DECODED display value (Graph stores the literal name). This round-trip preserves
	# spaces, '#', '%', apostrophes, Unicode, '+', and nested paths without ever creating a literal '%20'.
	$segs = @($folderPath -split '/' | Where-Object { $_ -ne '' })
	if ($segs.Count -eq 0) { return [pscustomobject]@{ State = 'Inaccessible'; Reason = 'resolved child URL carries no folder path' } }
	$leafDisplay = [System.Uri]::UnescapeDataString($segs[-1])
	$parentSegs  = if ($segs.Count -gt 1) { $segs[0..($segs.Count - 2)] } else { @() }
	$childrenUri = if ($parentSegs.Count -gt 0) {
		$parentEnc = ($parentSegs | ForEach-Object { [System.Uri]::EscapeDataString([System.Uri]::UnescapeDataString($_)) }) -join '/'
		"https://graph.microsoft.com/v1.0/drives/$($resolved.DriveId)/root:/${parentEnc}:/children"
	}
	else { "https://graph.microsoft.com/v1.0/drives/$($resolved.DriveId)/root/children" }
	$body = @{ name = $leafDisplay; folder = @{}; '@microsoft.graph.conflictBehavior' = 'fail' }
	try {
		$null = Invoke-MgGraphRequest -Method POST -Uri $childrenUri -Body $body -ErrorAction Stop
		return [pscustomobject]@{ State = 'Acquired'; Reason = 'exclusive create (conflictBehavior=fail)' }
	}
	catch {
		$status = 0
		try { $status = [int]$_.Exception.Response.StatusCode.value__ } catch {}
		if ($status -eq 0) { try { if ($_.Exception.Response.StatusCode -is [System.Net.HttpStatusCode]) { $status = [int]$_.Exception.Response.StatusCode } } catch {} }
		$detail = ''
		try { if ($_.ErrorDetails -and $_.ErrorDetails.Message) { $detail = [string]$_.ErrorDetails.Message } } catch {}
		if ([string]::IsNullOrEmpty($detail)) { $detail = [string]$_.Exception.Message }
		if ($status -eq 409 -or $detail -match 'nameAlreadyExists') { return [pscustomobject]@{ State = 'Collision'; Reason = ('folder already exists (HTTP {0})' -f $status) } }
		return [pscustomobject]@{ State = 'Inaccessible'; Reason = ('create failed (HTTP {0}): {1}' -f $status, $detail) }
	}
}

function script:New-AISIDRemoteRunFolderFabric {
	# Defect-2: EXCLUSIVELY create the exact timestamped Fabric AISID child directory via ADLS Gen2
	# "Create Path" (PUT ?resource=directory) with a conditional 'If-None-Match: *' header, so an
	# already-present directory is a CONFLICT (fail closed) rather than an idempotent success. The PUT is
	# the authoritative ownership decision — a prior read-only HEAD is never relied upon. NEVER overwrites
	# or reuses an existing directory. Returns { State='Acquired'|'Collision'|'Inaccessible'; Reason }.
	param([Parameter(Mandatory)][string]$Url)
	$resolved = Resolve-FabricTarget -Url $Url
	$dirUri = "$($resolved.FilesystemBase)/$($resolved.ItemFull)/Files/$($resolved.FilesPath)?resource=directory"
	try {
		$null = Invoke-FabricWebRequest -Uri $dirUri -Method PUT -Headers @{ 'If-None-Match' = '*' }
		return [pscustomobject]@{ State = 'Acquired'; Reason = 'exclusive create (If-None-Match:*)' }
	}
	catch {
		$status = 0
		try { $status = [int]$_.Exception.Response.StatusCode.value__ } catch {}
		$detail = [string]$_.Exception.Message
		if ($status -eq 409 -or $status -eq 412 -or $detail -match 'PathAlreadyExists') { return [pscustomobject]@{ State = 'Collision'; Reason = ('directory already exists (HTTP {0})' -f $status) } }
		return [pscustomobject]@{ State = 'Inaccessible'; Reason = ('create failed (HTTP {0}): {1}' -f $status, $detail) }
	}
}

function script:Acquire-AISIDRemoteRunFolderOwnership {
	# Defect-3: single dispatcher that acquires EXCLUSIVE ownership of the remote AISID run folder BEFORE
	# any upload. The read-only probe (Test-AISIDRemoteRunFolderState) runs first as an early diagnostic
	# only; the tier-specific exclusive CREATE is authoritative — if the probe reports Absent but the
	# create reports Collision, the result is Collision (fail closed). Returns
	# { Acquired=[bool]; State='Acquired'|'Collision'|'Inaccessible'; Mode; Url; Reason; ProbeState }.
	# The caller proceeds (stages/uploads) only when Acquired is $true.
	param(
		[Parameter(Mandatory)][string]$Url,
		[Parameter(Mandatory)][ValidateSet('SharePoint', 'Fabric')][string]$Mode
	)
	$probeState = try { script:Test-AISIDRemoteRunFolderState -Url $Url -Mode $Mode } catch { 'Inaccessible' }
	$create = if ($Mode -eq 'SharePoint') { script:New-AISIDRemoteRunFolderSharePoint -Url $Url } else { script:New-AISIDRemoteRunFolderFabric -Url $Url }
	return [pscustomobject]@{
		Acquired   = ($create.State -eq 'Acquired')
		State      = $create.State
		Mode       = $Mode
		Url        = $Url
		Reason     = $create.Reason
		ProbeState = $probeState
	}
}

function script:Resolve-AISIDHistorySource {
	# Blocker-3: the AISID history-read source, SEPARATE from the new output run folder. Prior history is
	# read ONLY from an explicitly supplied -AppendDefenderUsage prior bundle; a plain
	# -OutputPathDefenderUsage run (or no destination) reads NO prior history (never the fresh output
	# folder). Returns { LocalDir=[string]; RemoteParentUrl=[string] } with at most one non-empty per tier
	# (Local -> LocalDir; SharePoint/Fabric -> RemoteParentUrl). The supplied prior bundle is only READ;
	# the reconciled result is written into the new AISID_<ts> child. Overrides keep it testable.
	param(
		[Nullable[bool]]$AppendBoundOverride = $null,
		[string]$EffectiveDirOverride = $null,
		[string]$RemoteParentOverride = $null
	)
	$mode  = if ($script:RemoteOutputMode) { [string]$script:RemoteOutputMode } else { 'None' }
	$bound =
		if ($null -ne $AppendBoundOverride) { [bool]$AppendBoundOverride }
		elseif ($script:AppendIsBound -and $script:AppendIsBound.ContainsKey('DefenderUsage')) { [bool]$script:AppendIsBound['DefenderUsage'] }
		else { $false }
	if (-not $bound) { return [pscustomobject]@{ LocalDir = ''; RemoteParentUrl = '' } }
	if ($mode -eq 'None') {
		$eff =
			if (-not [string]::IsNullOrEmpty($EffectiveDirOverride)) { [string]$EffectiveDirOverride }
			else { $du = try { script:Resolve-DataTypePaths -DataType 'DefenderUsage' } catch { $null }; if ($du -and $du.EffectiveDir) { [string]$du.EffectiveDir } else { '' } }
		return [pscustomobject]@{ LocalDir = $eff; RemoteParentUrl = '' }
	}
	$rp =
		if (-not [string]::IsNullOrEmpty($RemoteParentOverride)) { [string]$RemoteParentOverride }
		elseif ($script:DestParentUrl -and $script:DestParentUrl['DefenderUsage']) { [string]$script:DestParentUrl['DefenderUsage'] }
		else { '' }
	return [pscustomobject]@{ LocalDir = ''; RemoteParentUrl = $rp }
}

function Get-AISIDOffHoursGeoCache {
	<#
	.SYNOPSIS
		Returns cached off-hours/geography raw rows when a same-day cache for the same collection
		window exists; otherwise returns $null. This delta cache is scoped to the off-hours/geography
		signal alone — no other data set reads or writes it.
	.OUTPUTS
		The cached raw row set, or $null on any miss / unreadable cache.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$DestinationDir,
		[Parameter(Mandatory)][int]$LookbackDays,
		[string]$WindowStartUtc = '',
		[string]$WindowEndUtc = ''
	)

	$cacheFile = Join-Path (Join-Path $DestinationDir '.aisid_cache') 'offhoursgeo.json'
	if (-not (Test-Path -LiteralPath $cacheFile)) { return $null }
	try { $payload = Get-Content -LiteralPath $cacheFile -Raw | ConvertFrom-Json } catch { return $null }
	if (-not $payload) { return $null }
	if ([int]$payload.LookbackDays -ne $LookbackDays) { return $null }
	# Cache identity includes the exact effective window bounds: same day + different bounds = miss,
	# and a legacy LookbackDays-only cache (no WindowStartUtc/WindowEndUtc) is always a miss. Both sides
	# are normalized to the invariant UTC ISO-8601 form first, because ConvertFrom-Json auto-parses an
	# ISO-8601 'Z' string back into a [datetime] whose culture-formatted [string] would never string-equal
	# the ISO literal (a same-run cache would otherwise always false-miss).
	if ((ConvertTo-AISIDInvariantUtcTimestamp -Value $payload.WindowStartUtc) -ne (ConvertTo-AISIDInvariantUtcTimestamp -Value $WindowStartUtc)) { return $null }
	if ((ConvertTo-AISIDInvariantUtcTimestamp -Value $payload.WindowEndUtc)   -ne (ConvertTo-AISIDInvariantUtcTimestamp -Value $WindowEndUtc))   { return $null }
	$cachedUtc = $null
	try { $cachedUtc = [datetime]$payload.CachedUtc } catch { return $null }
	# Same-window reuse is valid only within the same UTC calendar day.
	if ($cachedUtc.ToUniversalTime().Date -ne (Get-Date).ToUniversalTime().Date) { return $null }
	return @($payload.Rows)
}

function Save-AISIDOffHoursGeoCache {
	<#
	.SYNOPSIS
		Persists off-hours/geography raw rows to the off-hours/geography-scoped delta cache. Failures
		are non-fatal (a run must never break because the cache could not be written).
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$DestinationDir,
		[Parameter(Mandatory)][int]$LookbackDays,
		[string]$WindowStartUtc = '',
		[string]$WindowEndUtc = '',
		[object[]]$Rows = @()
	)

	$cacheDir = Join-Path $DestinationDir '.aisid_cache'
	try {
		if (-not (Test-Path -LiteralPath $cacheDir)) { New-Item -ItemType Directory -Path $cacheDir -Force | Out-Null }
		$payload = [ordered]@{
			LookbackDays = $LookbackDays
			WindowStartUtc = $WindowStartUtc
			WindowEndUtc   = $WindowEndUtc
			CachedUtc    = (Get-Date).ToUniversalTime().ToString('o')
			Rows         = @($Rows)
		}
		$json = $payload | ConvertTo-Json -Depth 6
		[System.IO.File]::WriteAllText((Join-Path $cacheDir 'offhoursgeo.json'), $json, (New-Object System.Text.UTF8Encoding($false)))
	}
	catch {
		Write-LogHost "[AISID] OffHoursGeo cache write failed (non-fatal): $($_.Exception.Message)" -ForegroundColor Yellow
	}
}

function Get-AISIDCountryCountMap {
	<#
	.SYNOPSIS
		Converts an advanced-hunting CountryCounts bag into a hashtable of country-key -> integer
		session count. OData annotation properties emitted by the Graph security hunting API
		('@odata.type' = '#microsoft.graph.security.dynamicColumnValue', and any per-field
		'<field>@odata.type' companion) are structurally ignored, never cast; any entry whose
		value is not a whole number is skipped rather than guessed. Metadata therefore can never
		enter the map and can never raise an Int32 conversion error.
	.OUTPUTS
		[hashtable] of [string] country -> [int] count (possibly empty).
	#>
	[CmdletBinding()]
	param([Parameter()][AllowNull()]$CountryCounts)

	$map = @{}
	if ($null -eq $CountryCounts) { return $map }

	if ($CountryCounts -is [System.Collections.IDictionary]) {
		$pairs = @($CountryCounts.Keys | ForEach-Object { [pscustomobject]@{ Name = [string]$_; Value = $CountryCounts[$_] } })
	}
	else {
		$pairs = @($CountryCounts.PSObject.Properties | ForEach-Object { [pscustomobject]@{ Name = $_.Name; Value = $_.Value } })
	}

	foreach ($p in $pairs) {
		$key = [string]$p.Name
		if ([string]::IsNullOrWhiteSpace($key)) { continue }
		if ($key -like '*@odata*') { continue }
		$parsed = [long]0
		if ([long]::TryParse([string]$p.Value, [ref]$parsed)) { $map[$key] = [int]$parsed }
	}
	return $map
}

function Get-AISIDOffHoursGeo {
	<#
	.SYNOPSIS
		Collects the off-hours / geography data set from Entra sign-in hunting events and returns rows
		in the contractual column order. Uses the off-hours/geography-scoped delta cache unless
		DisableDeltaCache is set, in which case a full fresh query always runs and the cache is neither
		read nor written.
	.OUTPUTS
		Hashtable: Success, Rows, RawRowCount, CacheHit, TruncationDetected, AuthQuit, ErrorMessage, Elapsed.
	#>
	[CmdletBinding()]
	param(
		[switch]$DisableDeltaCache,
		[string]$CacheDir
	)

	$result = @{
		Success = $false; Rows = @(); RawRowCount = 0; CacheHit = $false
		TruncationDetected = $false; AuthQuit = $false; ErrorMessage = ''; Elapsed = [TimeSpan]::Zero
	}
	$sw = [System.Diagnostics.Stopwatch]::StartNew()

	$signInAppNames = @(Get-AISIDSignInAppNames)
	if ($signInAppNames.Count -eq 0) {
		Write-LogHost '[AISID] OffHoursGeo: no sign-in app names in catalog; skipping query.' -ForegroundColor Yellow
		$result.Success = $true; $sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}

	$lookbackDays  = Get-AISIDEffectiveLookbackDays
	$appFilterJson = ($signInAppNames | ForEach-Object { '"' + ($_ -replace '"', '\"') + '"' }) -join ','
	# The collection window is bounded by the shared hunting-query timespan; the query filters to the
	# catalog's sign-in app names and aggregates per user/month, with a per-country breakdown so the
	# "primary country vs. anomalous" split can be computed client-side without a second round-trip.
		$ohgBounds = Get-AISIDCollectionBounds
	$ohgStart = $ohgBounds.StartUtc.ToString('yyyy-MM-ddTHH:mm:ss.fffffffZ')
	$ohgEnd   = $ohgBounds.EndUtc.ToString('yyyy-MM-ddTHH:mm:ss.fffffffZ')
	$ohgScope = script:Get-AISIDScopeKqlFilter -UpnColumn 'UPN'
	# Batched: a large scope is split into size-bounded batches; both the outer and the joined subquery
	# receive the SAME per-batch scope clause so every target user is queried exactly once and the
	# per-user rows are concatenated across batches. $ohgScope retained for structural parity.
	$null = $ohgScope
	$ohgQueryBuilder = ({
		param($__scope)
@"
let AppFilter = dynamic([$appFilterJson]);
let WinStart = datetime($ohgStart);
let WinEnd   = datetime($ohgEnd);
EntraIdSignInEvents
| where Timestamp >= WinStart and Timestamp < WinEnd
| where Application in~ (AppFilter)
| extend UPN = tolower(AccountUpn)
| where isnotempty(UPN)
$__scope
| extend YearMonth = format_datetime(Timestamp, 'yyyy-MM')
| extend CountryKey = iff(isempty(Country), 'Unknown', Country)
| summarize CountryCount = count() by UPN, YearMonth, CountryKey
| summarize
    TotalSessions     = sum(CountryCount),
    DistinctCountries = dcount(CountryKey),
    CountryCounts     = make_bag(pack(CountryKey, CountryCount), 200)
  by UPN, YearMonth
| join kind=inner (
    EntraIdSignInEvents
    | where Timestamp >= WinStart and Timestamp < WinEnd
    | where Application in~ (AppFilter)
    | extend UPN = tolower(AccountUpn)
    | where isnotempty(UPN)
$__scope
    | extend Hour = datetime_part('hour', Timestamp)
    | extend IsOffHours = iff(Hour < 7 or Hour > 19, 1, 0)
    | extend YearMonth = format_datetime(Timestamp, 'yyyy-MM')
    | summarize OffHoursSessions = sum(IsOffHours) by UPN, YearMonth
  ) on UPN, YearMonth
| project UPN, YearMonth, TotalSessions, OffHoursSessions, DistinctCountries, CountryCounts
"@
	}.GetNewClosure())


	$rawRows = $null
	# A resumed AISID run whose stored cache-window identity cannot be trusted forces a guaranteed cache miss on READ (the original
	# run's destination/cache identity cannot be trusted to match), so the window is re-queried fresh.
	# The switch semantics of -DisableAISIDDeltaCache are unchanged; the cache WRITE below still runs.
	if (-not $DisableDeltaCache -and -not $script:AISIDResumeForceCacheMiss -and $CacheDir) {
		$cached = Get-AISIDOffHoursGeoCache -DestinationDir $CacheDir -LookbackDays $lookbackDays -WindowStartUtc $ohgStart -WindowEndUtc $ohgEnd
		if ($null -ne $cached) {
			$rawRows = @($cached); $result.CacheHit = $true
			Write-LogHost "[AISID] OffHoursGeo: delta cache hit ($($rawRows.Count) rows)." -ForegroundColor DarkGray
		}
	}

	if ($null -eq $rawRows) {
		$api = script:Invoke-AISIDBatchedHuntingQuery -UpnColumn 'UPN' -Description 'OffHoursGeo' -QueryBuilder $ohgQueryBuilder
		if ($api.AuthQuit) {
			$result.AuthQuit = $true; $result.ErrorMessage = 'Graph token refresh returned Quit'
			$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
		}
		if (-not $api.Success) {
			$result.ErrorMessage = "OffHoursGeo query failed: $($api.ErrorMessage)"
			$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
		}
		$rawRows = @($api.Results)
		$result.TruncationDetected = [bool]$api.TruncationDetected
		if (-not $DisableDeltaCache -and $CacheDir) {
			Save-AISIDOffHoursGeoCache -DestinationDir $CacheDir -LookbackDays $lookbackDays -WindowStartUtc $ohgStart -WindowEndUtc $ohgEnd -Rows $rawRows
		}
	}

	$result.RawRowCount = @($rawRows).Count

	# Client-side enrichment: off-hours percentage, and anomalous countries = every non-primary country.
	$rows = New-Object System.Collections.Generic.List[object]
	foreach ($r in $rawRows) {
		if (-not $r) { continue }
		$total = [int]$r.TotalSessions
		$off   = [int]$r.OffHoursSessions
		$pct   = if ($total -gt 0) { [Math]::Round(($off / [double]$total), 4) } else { 0 }

		$countryMap = Get-AISIDCountryCountMap -CountryCounts $r.CountryCounts
		$anomalous = @()
		if ($countryMap.Count -gt 1) {
			# Deterministic primary: highest session count; ties broken by alphabetically-first country key.
			$primary = ($countryMap.GetEnumerator() | Sort-Object @{ Expression = { $_.Value }; Descending = $true }, @{ Expression = { $_.Key }; Descending = $false } | Select-Object -First 1).Key
			$anomalous = @($countryMap.Keys | Where-Object { $_ -ne $primary } | Sort-Object)
		}

		$rows.Add([pscustomobject][ordered]@{
			UPN                   = [string]$r.UPN
			YearMonth             = [string]$r.YearMonth
			TotalSessions         = $total
			OffHoursSessions      = $off
			OffHoursPct           = $pct
			DistinctCountries     = [int]$r.DistinctCountries
			AnomalousCountryCount = $anomalous.Count
			AnomalousCountries    = ($anomalous -join ';')
		})
	}
	$result.Rows = $rows.ToArray()
	$result.Success = $true
	$sw.Stop(); $result.Elapsed = $sw.Elapsed
	return $result
}

# Severity-tier reference for OAuth permission scopes. The tiering signal is anchored on Microsoft's own
# admin-consent-requirement model: application permissions always require admin consent, many high-privilege
# delegated permissions require admin consent, and delegated permissions that do not require admin consent are
# lower-privilege by design. See:
#   https://learn.microsoft.com/en-us/entra/identity-platform/permissions-consent-overview
#   https://learn.microsoft.com/en-us/graph/permissions-overview
#   https://learn.microsoft.com/en-us/graph/permissions-reference
# The admin-consent facts are Microsoft-documented; the specific High/Medium/Low assignment per scope is
# informed practitioner judgment layered on top of that signal, not a Microsoft-official severity ranking.
# Any scope not listed here resolves to 'Unclassified' (never a numeric guess).
$script:AISIDPermissionRiskCatalog = @{
	# High: broad directory/role/app control, tenant-wide write, or mail send/read-write (all admin-consent).
	'Directory.ReadWrite.All'          = 'High'
	'RoleManagement.ReadWrite.Directory' = 'High'
	'Application.ReadWrite.All'        = 'High'
	'AppRoleAssignment.ReadWrite.All'  = 'High'
	'User.ReadWrite.All'               = 'High'
	'Group.ReadWrite.All'              = 'High'
	'Sites.FullControl.All'            = 'High'
	'Files.ReadWrite.All'              = 'High'
	'Mail.ReadWrite'                   = 'High'
	'Mail.Send'                        = 'High'
	'Directory.AccessAsUser.All'       = 'High'
	'full_access_as_app'               = 'High'
	# Medium: tenant-wide read of sensitive data, or scoped write of user content (typically admin-consent).
	'Directory.Read.All'               = 'Medium'
	'User.Read.All'                    = 'Medium'
	'Group.Read.All'                   = 'Medium'
	'Mail.Read'                        = 'Medium'
	'Files.Read.All'                   = 'Medium'
	'Sites.Read.All'                   = 'Medium'
	'Calendars.ReadWrite'              = 'Medium'
	'Contacts.ReadWrite'               = 'Medium'
	'People.Read.All'                  = 'Medium'
	'Chat.Read.All'                    = 'Medium'
	# Low: self-scoped or low-privilege scopes that do not require admin consent by design.
	'User.Read'                        = 'Low'
	'User.ReadBasic.All'               = 'Low'
	'openid'                           = 'Low'
	'profile'                          = 'Low'
	'email'                            = 'Low'
	'offline_access'                   = 'Low'
	'Calendars.Read'                   = 'Low'
	'Contacts.Read'                    = 'Low'
	'Files.Read'                       = 'Low'
	'Mail.ReadBasic'                   = 'Low'
}

function Resolve-AISIDPermissionTier {
	<#
	.SYNOPSIS
		Maps a single Graph permission scope string to a severity tier via the reference catalog. Any scope
		not present in the catalog resolves to 'Unclassified' — this is the only fallback, and it is never a
		numeric guess.
	.OUTPUTS
		One of: 'High', 'Medium', 'Low', 'Unclassified'.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)][AllowEmptyString()][string]$Scope)

	$key = $Scope.Trim()
	if ($key -and $script:AISIDPermissionRiskCatalog.ContainsKey($key)) {
		return $script:AISIDPermissionRiskCatalog[$key]
	}
	return 'Unclassified'
}

function Get-AISIDPermissionWeight {
	<#
	.SYNOPSIS
		Computes the integer PermissionWeight for one consent grant's set of permission scopes. Each scope is
		mapped to a severity tier and scored (High=3, Medium=2, Low=1, Unclassified=0); the row's weight is the
		HIGHEST score across all granted scopes, because one severe scope defines the risk regardless of how
		many trivial scopes accompany it. A grant with no scopes returns 0 without ever entering the tier
		lookup; the companion Permissions column distinguishes 'no scopes' (empty) from 'only unrecognized
		scopes' (populated) at the same weight of 0.
	.OUTPUTS
		[int] weight (0-3).
	#>
	[CmdletBinding()]
	param([string[]]$Permissions = @())

	$tierScore = @{ High = 3; Medium = 2; Low = 1; Unclassified = 0 }

	# A single source value may carry one or several scope tokens; split on common delimiters and strip any
	# surrounding quote/bracket characters so an exact catalog-key match is not defeated by formatting.
	$tokens = New-Object System.Collections.Generic.List[string]
	foreach ($p in @($Permissions)) {
		if (-not $p) { continue }
		foreach ($t in ($p -split '[,;\s]+')) {
			$t = $t.Trim('"', "'", '[', ']')
			if ($t) { $tokens.Add($t) }
		}
	}
	if ($tokens.Count -eq 0) { return 0 }

	$max = 0
	foreach ($t in $tokens) {
		$score = $tierScore[(Resolve-AISIDPermissionTier -Scope $t)]
		if ($score -gt $max) { $max = $score }
	}
	return $max
}

function Get-AISIDOAuthConsents {
	<#
	.SYNOPSIS
		Collects OAuth consent activity from the Entra audit log (directoryAudits) on the existing
		Graph session, correlates it to catalog AI apps, and aggregates to one row per
		(UPN, AppName, YearMonth). This table is cache-free by design (the delta cache is
		off-hours/geography-only) and issues no hunting query.
	.OUTPUTS
		Hashtable: Success, Rows, RawRowCount, TruncationDetected, AuthQuit, ErrorMessage, Elapsed.
	#>
	[CmdletBinding()]
	param()

	$result = @{
		Success = $false; Rows = @(); RawRowCount = 0
		TruncationDetected = $false; AuthQuit = $false; ErrorMessage = ''; Elapsed = [TimeSpan]::Zero
	}
	$sw = [System.Diagnostics.Stopwatch]::StartNew()

	$aiAppNames = @(Get-AISIDSignInAppNames)
	$aiAppLower = @{}
	foreach ($n in $aiAppNames) { $aiAppLower[$n.ToLowerInvariant()] = $true }

	$ocBounds = Get-AISIDCollectionBounds
	$startIso = $ocBounds.StartUtc.ToString('o')
	$endIso   = $ocBounds.EndUtc.ToString('o')
	# Consent-related operations recorded in the Entra audit log.
	$ops = @('Consent to application', 'Add delegated permission grant', 'Add app role assignment to service principal')
	$opClause = ($ops | ForEach-Object { "activityDisplayName eq '$_'" }) -join ' or '
	$filter  = "($opClause) and activityDateTime ge $startIso and activityDateTime lt $endIso"
	$encoded = [System.Uri]::EscapeDataString($filter)
	$uri = "https://graph.microsoft.com/v1.0/auditLogs/directoryAudits?`$filter=$encoded&`$top=200"

	$collected = New-Object System.Collections.Generic.List[object]
	try {
		while ($uri) {
			# Refresh on the existing session before each page to avoid mid-pagination 401s.
			$refresh = Refresh-GraphTokenIfNeeded
			if ($refresh -eq 'Quit') {
				$result.AuthQuit = $true; $result.ErrorMessage = 'Graph token refresh returned Quit'
				$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
			}
			$resp = Invoke-MgGraphRequest -Method GET -Uri $uri -ErrorAction Stop
			if ($resp.value) { foreach ($rec in $resp.value) { $collected.Add($rec) } }
			$uri = $resp.'@odata.nextLink'
		}
	}
	catch {
		$result.ErrorMessage = "OAuthConsents Graph query failed: $($_.Exception.Message)"
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}
	$rawRecords = @($collected.ToArray())
	$result.RawRowCount = $rawRecords.Count

	# Client-side catalog match + aggregate by (UPN, AppName, YearMonth).
	$agg = [ordered]@{}
	foreach ($rec in $rawRecords) {
		if (-not $rec) { continue }
		$target  = if ($rec.targetResources) { @($rec.targetResources)[0] } else { $null }
		$appName = if ($target -and $target.displayName) { [string]$target.displayName } else { $null }
		if (-not $appName) { continue }

		$resolved = Resolve-AISIDFromAppName -AppName $appName
		if (-not ($resolved -or $aiAppLower.ContainsKey($appName.ToLowerInvariant()))) { continue }
		$solution = if ($resolved) { $resolved.AISolution } else { $appName }

		$upn = $null
		if ($rec.initiatedBy -and $rec.initiatedBy.user -and $rec.initiatedBy.user.userPrincipalName) {
			$upn = [string]$rec.initiatedBy.user.userPrincipalName
		}
		if (-not $upn) { continue }
		$upn = $upn.ToLowerInvariant()

		$ts = $null; try { $ts = [datetime]$rec.activityDateTime } catch {}
		if (-not $ts) { continue }
		$tsUtc = $ts.ToUniversalTime()
		$yearMonth = $tsUtc.ToString('yyyy-MM')

		$perms = @()
		# Granted scopes come from the consent event's DelegatedPermissionGrant.Scope modified property
		# (TargetResources[].ModifiedProperties[].NewValue) — the field-tested source for the actual granted
		# scope strings. The value can arrive wrapped in quotes/brackets, so surrounding quote/bracket
		# characters are trimmed before it is stored (the per-token tokenizer strips them again defensively).
		if ($rec.targetResources) {
			foreach ($tr in @($rec.targetResources)) {
				if (-not $tr.modifiedProperties) { continue }
				foreach ($mp in @($tr.modifiedProperties)) {
					$dn = if ($mp.displayName) { [string]$mp.displayName } elseif ($mp.DisplayName) { [string]$mp.DisplayName } else { '' }
					if ($dn -ne 'DelegatedPermissionGrant.Scope') { continue }
					$nv = if ($mp.newValue) { [string]$mp.newValue } elseif ($mp.NewValue) { [string]$mp.NewValue } else { '' }
					$nv = $nv.Trim().Trim('"', "'", '[', ']').Trim()
					if ($nv) { $perms += $nv }
				}
			}
		}

		$key = '{0}|{1}|{2}' -f $upn, $solution, $yearMonth
		if (-not $agg.Contains($key)) {
			$agg[$key] = [ordered]@{
				UPN = $upn; AppName = $solution; YearMonth = $yearMonth
				ConsentCount = 0; LastConsent = $tsUtc
				PermSet = (New-Object System.Collections.Generic.HashSet[string])
			}
		}
		$b = $agg[$key]
		$b.ConsentCount = [int]$b.ConsentCount + 1
		if ($tsUtc -gt [datetime]$b.LastConsent) { $b.LastConsent = $tsUtc }
		foreach ($p in $perms) { [void]$b.PermSet.Add($p) }
	}

	$rows = foreach ($b in $agg.Values) {
		$permArr = @($b.PermSet)
		[pscustomobject][ordered]@{
			UPN              = $b.UPN
			AppName          = $b.AppName
			YearMonth        = $b.YearMonth
			ConsentCount     = [int]$b.ConsentCount
			LastConsent      = ([datetime]$b.LastConsent).ToString('o')
			PermissionWeight = Get-AISIDPermissionWeight -Permissions $permArr
			Permissions      = ($permArr -join ';')
		}
	}
	$result.Rows = @($rows)
	$result.Success = $true
	$sw.Stop(); $result.Elapsed = $sw.Elapsed
	return $result
}

function Get-AISIDSSOSignIns {
	<#
	.SYNOPSIS
		Collects SSO sign-in activity from Entra sign-in hunting events, aggregated per
		(UPN, Application, YearMonth). Cache-free by design (the delta cache is off-hours/geography-only).
	.OUTPUTS
		Hashtable: Success, Rows, RawRowCount, TruncationDetected, AuthQuit, ErrorMessage, Elapsed.
	#>
	[CmdletBinding()]
	param()

	$result = @{
		Success = $false; Rows = @(); RawRowCount = 0
		TruncationDetected = $false; AuthQuit = $false; ErrorMessage = ''; Elapsed = [TimeSpan]::Zero
	}
	$sw = [System.Diagnostics.Stopwatch]::StartNew()

	$signInAppNames = @(Get-AISIDSignInAppNames)
	if ($signInAppNames.Count -eq 0) {
		Write-LogHost '[AISID] SSOSignIns: no sign-in app names in catalog; skipping query.' -ForegroundColor Yellow
		$result.Success = $true; $sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}
	$appFilterJson = ($signInAppNames | ForEach-Object { '"' + ($_ -replace '"', '\"') + '"' }) -join ','
	# Guest is inferred from the external-identity marker in the UPN; conditional-access applicability is
	# inferred from a non-empty conditional-access evaluation status. Both are advisory client-side reads.
		$ssoBounds = Get-AISIDCollectionBounds
	$ssoStart = $ssoBounds.StartUtc.ToString('yyyy-MM-ddTHH:mm:ss.fffffffZ')
	$ssoEnd   = $ssoBounds.EndUtc.ToString('yyyy-MM-ddTHH:mm:ss.fffffffZ')
	$ssoScope = script:Get-AISIDScopeKqlFilter -UpnColumn 'UPN'
	# Batched: a large scope is split into size-bounded batches; the query runs once per batch (every
	# target user queried exactly once) and the per-user rows are concatenated. $ssoScope retained for
	# structural parity; the per-batch clause ($__scope) is what the runner injects.
	$null = $ssoScope
	$api = script:Invoke-AISIDBatchedHuntingQuery -UpnColumn 'UPN' -Description 'SSOSignIns' -QueryBuilder ({
		param($__scope)
@"
let AppFilter = dynamic([$appFilterJson]);
let WinStart = datetime($ssoStart);
let WinEnd   = datetime($ssoEnd);
EntraIdSignInEvents
| where Timestamp >= WinStart and Timestamp < WinEnd
| where Application in~ (AppFilter)
| extend UPN = tolower(AccountUpn)
| where isnotempty(UPN)
$__scope
| extend YearMonth = format_datetime(Timestamp, 'yyyy-MM')
| extend DayKey = format_datetime(Timestamp, 'yyyy-MM-dd')
| extend IsGuestFlag = iff(UPN has '#ext#', 'True', 'False')
| extend CAApplied = iff(ConditionalAccessStatus == 'success' or ConditionalAccessStatus == 'failure', 'Yes', 'No')
| extend CountryKey = iff(isempty(Country), 'Unknown', Country)
| summarize
    SignInCount          = count(),
    DistinctDays         = dcount(DayKey),
    IsGuest              = max(IsGuestFlag),
    HasConditionalAccess = max(CAApplied),
    Countries            = make_set(CountryKey, 100),
    LastSignIn           = max(Timestamp)
  by UPN, Application, YearMonth
"@
	}.GetNewClosure())
	if ($api.AuthQuit) {
		$result.AuthQuit = $true; $result.ErrorMessage = 'Graph token refresh returned Quit'
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}
	if (-not $api.Success) {
		$result.ErrorMessage = "SSOSignIns query failed: $($api.ErrorMessage)"
		$sw.Stop(); $result.Elapsed = $sw.Elapsed; return $result
	}
	$rawRows = @($api.Results)
	$result.RawRowCount = $rawRows.Count
	$result.TruncationDetected = [bool]$api.TruncationDetected

	$rows = foreach ($r in $rawRows) {
		if (-not $r) { continue }
		$countries = @()
		if ($r.Countries) {
			if ($r.Countries -is [System.Array]) { $countries = @($r.Countries | ForEach-Object { [string]$_ }) }
			else { $countries = @([string]$r.Countries) }
		}
		$last = ''
		if ($r.LastSignIn) { try { $last = ([datetime]$r.LastSignIn).ToUniversalTime().ToString('o') } catch { $last = [string]$r.LastSignIn } }
		[pscustomobject][ordered]@{
			UPN                  = [string]$r.UPN
			Application          = [string]$r.Application
			YearMonth            = [string]$r.YearMonth
			SignInCount          = [int]$r.SignInCount
			DistinctDays         = [int]$r.DistinctDays
			IsGuest              = [string]$r.IsGuest
			Countries            = ($countries -join ';')
			HasConditionalAccess = [string]$r.HasConditionalAccess
			LastSignIn           = $last
		}
	}
	$result.Rows = @($rows)
	$result.Success = $true
	$sw.Stop(); $result.Elapsed = $sw.Elapsed
	return $result
}

function Get-AISIDSolutionsCatalogExport {
	<#
	.SYNOPSIS
		Projects the in-memory AI solutions reference catalog to the dashboard's dimension CSV columns.
		This is dimension data — the whole file is regenerated each run (overwrite); there is no
		time-series grain and no per-row key merge.
	.OUTPUTS
		An array of rows in the contractual column order.
	#>
	[CmdletBinding()]
	param()

	$rows = foreach ($entry in $script:AISolutionCatalog) {
		if (-not $entry) { continue }
		[pscustomobject][ordered]@{
			AISolution          = [string]$entry.AISolution
			Category            = [string]$entry.Category
			Vendor              = [string]$entry.Vendor
			RiskTier            = [string]$entry.RiskTier
			DefaultDataHandling = [string]$entry.DefaultDataHandling
			SolutionGroup       = [string]$entry.SolutionGroup
		}
	}
	return @($rows)
}

function Get-AISIDEntraUsersProjection {
	<#
	.SYNOPSIS
		Projects the already-collected general EntraUsers export data down to the dashboard's fixed
		column set, in contractual order. Reads in-memory data only — it performs no directory query of
		its own and leaves the general export untouched. Dimension data: the whole file is regenerated
		each run (overwrite); no per-row key merge.
	.OUTPUTS
		An array of rows in the contractual column order.
	#>
	[CmdletBinding()]
	param([object[]]$SourceRows = @($script:EntraUsersData))

	$SourceRows = @($SourceRows)

	# Target-user scope for the EntraUsers dimension: when a user/group scope was requested, restrict
	# the projection to the target users PLUS their full manager chain (managers of managers, up to the
	# top). No non-target UPN reaches the dimension except those manager-chain rows, which the dashboard
	# hierarchy needs to resolve. Unscoped runs project the source rows unchanged.
	$scope = script:Get-AISIDScopeUpnSet
	if ($null -ne $scope) {
		$byUpn = @{}
		foreach ($u in $SourceRows) {
			if (-not $u) { continue }
			$g = if ($u -is [System.Collections.IDictionary]) { [string]$u['userPrincipalName'] } else { [string]$u.userPrincipalName }
			$g = ([string]$g).Trim()
			if ($g) { $byUpn[$g.ToLowerInvariant()] = $u }
		}
		$keep = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
		foreach ($t in @($scope)) {
			$cur = ([string]$t).Trim()
			$guard = 0
			while ($cur -and $keep.Add($cur) -and $guard -lt 10000) {
				$guard++
				$row = $byUpn[$cur.ToLowerInvariant()]
				if (-not $row) { break }
				$mgr = if ($row -is [System.Collections.IDictionary]) { [string]$row['manager_userPrincipalName'] } else { [string]$row.manager_userPrincipalName }
				$cur = ([string]$mgr).Trim()
			}
		}
		$SourceRows = @($SourceRows | Where-Object {
				$g = if ($_ -is [System.Collections.IDictionary]) { [string]$_['userPrincipalName'] } else { [string]$_.userPrincipalName }
				$g = ([string]$g).Trim()
				$g -and $keep.Contains($g)
			})
	}

	$rows = foreach ($u in @($SourceRows)) {
		if (-not $u) { continue }
		$get = {
			param($n)
			if ($u -is [System.Collections.IDictionary]) { $u[$n] } else { $u.$n }
		}
		[pscustomobject][ordered]@{
			userPrincipalName         = [string](& $get 'userPrincipalName')
			displayName               = [string](& $get 'displayName')
			department                = [string](& $get 'department')
			jobTitle                  = [string](& $get 'jobTitle')
			city                      = [string](& $get 'city')
			country                   = [string](& $get 'country')
			companyName               = [string](& $get 'companyName')
			accountEnabled            = [string](& $get 'accountEnabled')
			userType                  = [string](& $get 'userType')
			manager_displayName       = [string](& $get 'manager_displayName')
			manager_userPrincipalName = [string](& $get 'manager_userPrincipalName')
			hasLicense                = [string](& $get 'hasLicense')
			assignedLicenses          = [string](& $get 'assignedLicenses')
			createdDateTime           = [string](& $get 'createdDateTime')
		}
	}
	return @($rows)
}

function Export-AISIDPilotTables {
	<#
	.SYNOPSIS
		Processes the five query-backed data sets (Activity Sessions, Off-Hours/Geography, File
		Proximity, OAuth Consents, SSO Sign-Ins) through the shared export/merge infrastructure,
		producing the full dashboard output set. Each query-backed table is collected only when its
		per-table licensing verdict is eligible; an ineligible or empty table still yields a valid
		header-only CSV. File Proximity is event-grain (append-and-dedup merge); when it is ineligible
		or its query fails and no prior history exists, the header-only stub is emitted as its fallback.
		The off-hours/geography delta cache is used unless DisableDeltaCache is set.
	.OUTPUTS
		Ordered hashtable of written paths per table, plus AuthQuit.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$DestinationDir,
		[Parameter(Mandatory)][System.Collections.IDictionary]$Verdict,
		[switch]$DisableDeltaCache,
		[hashtable]$ExistingRows = @{},
		[string]$ParentOverride,
		[string]$HistoryDir = '',
		[string]$RawPurviewCsv
	)

	$out = [ordered]@{
		ActivitySessions = $null; OffHoursGeo = $null; OAuthConsents = $null; SSOSignIns = $null
		FileProximity = $null; ClientChannel = $null; CopilotUsage = $null; AppGovAlerts = $null; CloudDiscovery = $null; MDASessions = $null
		EntraUsers = $null; SolutionsCatalog = $null; AuthQuit = $false
		ReadFailures = (New-Object System.Collections.Generic.List[string])
		Failed = (New-Object System.Collections.Generic.List[string])
		TableStatus = [ordered]@{}
	}
	# A1 state contract: every dashboard table gets an EXPLICIT terminal state before completeness is
	# evaluated. Seed each as Incomplete ("collector not reached") so a table skipped by an early exit is
	# never silently treated as clean; per-table processing below overwrites this with the decided state.
	foreach ($t in @('ActivitySessions', 'OffHoursGeo', 'FileProximity', 'OAuthConsents', 'SSOSignIns', 'ClientChannel', 'CopilotUsage', 'AppGovAlerts', 'CloudDiscovery', 'MDASessions', 'SolutionsCatalog', 'EntraUsers')) {
		$out.TableStatus[$t] = [ordered]@{ State = 'Incomplete'; Reason = 'collector not reached' }
	}

	# Table -> collector. Each collector returns the standard result hashtable (Success/Rows/AuthQuit).
	# Off-Hours/Geography is the only cache-aware collector; every other table is cache-free.
	$collect = {
		param($table)
		switch ($table) {
			'ActivitySessions' { Get-AISIDActivitySessions }
			'OffHoursGeo'      { Get-AISIDOffHoursGeo -DisableDeltaCache:$DisableDeltaCache -CacheDir (script:Get-AISIDCacheDir -DestinationDir $DestinationDir) }
			'OAuthConsents'    { Get-AISIDOAuthConsents }
			'SSOSignIns'       { Get-AISIDSSOSignIns }
			'ClientChannel'    { Get-AISIDClientChannel }
			'CopilotUsage'     { Get-AISIDCopilotUsage -RawPurviewCsv $RawPurviewCsv }
		}
	}

	foreach ($table in @('ActivitySessions', 'OffHoursGeo', 'OAuthConsents', 'SSOSignIns', 'ClientChannel', 'CopilotUsage')) {
		$schema = $script:AISIDTableSchemas[$table]
		$rows = @()
		$state = 'Unavailable'; $reason = 'licensing ineligible'
		if ($Verdict[$table] -and $Verdict[$table].Eligible) {
			try {
				$q = & $collect $table
				if ($q.AuthQuit) { $out.AuthQuit = $true }
				if ($q.Success)  { $rows = @($q.Rows); if (@($rows).Count -gt 0) { $state = 'Succeeded'; $reason = 'collected rows' } else { $state = 'Empty'; $reason = 'query succeeded with zero rows' } }
				else { $state = 'Failed'; $reason = 'collector returned Success=false'; [void]$out.Failed.Add($table) }
			}
			catch {
				# Per-table isolation: an UNEXPECTED throw (as opposed to a Success=$false return) is
				# caught here so the remaining tables in the loop still run. $rows stays empty, so the
				# read-before-merge + export below fall this table back to its safe-empty / history-
				# preserving output exactly as an ineligible or Success=$false table does.
				Write-LogHost ("[AISID] {0}: collector threw an unexpected error ({1}); falling back to safe-empty output for this table." -f $table, $_.Exception.Message) -ForegroundColor Yellow
				$state = 'Failed'; $reason = ("collector threw: {0}" -f $_.Exception.Message)
				[void]$out.Failed.Add($table)
			}
		}
		# Ineligible or empty: $rows stays empty; Export-AISIDTable still writes a header-only CSV.

		# Client-side target-user scope enforcement (defense-in-depth behind the server-side KQL
		# filter): when a user/group scope was requested, drop any newly collected row whose UPN is
		# not in the resolved target set so no non-target user reaches this run's output. No-op for
		# unscoped runs and for non-user-grain / global tables (ClientChannel, SolutionsCatalog) and
		# the separately-scoped EntraUsers dimension.
		$rows = script:Select-AISIDScopedRows -Table $table -Rows $rows

		# Deidentify this table's NEW rows BEFORE the read-before-merge below, so on-disk (already
		# deidentified) rows and these newly-collected rows compare on matching keys during merge.
		# No-op when -Deidentify is off. CopilotUsage is now deidentified here too: its source is the
		# IDENTIFIED raw Purview CSV (read before any raw scrub), so its UserPrincipalName must pass once
		# through the shared Get-PaxDeidUpn path to match the deidentified EntraUsers key.
		$rows = ConvertTo-AISIDDeidentifiedRows -Table $table -Rows $rows

		# ClientChannel scope provenance: ClientChannel aggregates away UPN, so a prior ClientChannel
		# bundle cannot be proven to share this run's user scope. For a SCOPED run, refuse to merge
		# ClientChannel history whose scope provenance cannot be established — fail closed (don't merge,
		# don't publish, preserve prior, AISID gap) rather than silently mix tenant-wide and scoped
		# aggregates.
		if ($table -eq 'ClientChannel' -and $null -ne (script:Get-AISIDScopeUpnSet)) {
			$__ccHasPrior =
				($ExistingRows.ContainsKey($table) -and @($ExistingRows[$table]).Count -gt 0) -or
				((-not $script:RemoteOutputMode -or $script:RemoteOutputMode -eq 'None') -and $HistoryDir -and (Test-AISIDCsvHasDataRow -Path (Join-Path $HistoryDir $schema.FileName))) -or
				($script:RemoteOutputMode -and $script:RemoteOutputMode -ne 'None' -and $ParentOverride)
			if ($__ccHasPrior) {
				Write-LogHost "[AISID] ClientChannel: a scoped run cannot prove the prior ClientChannel bundle shares this user scope (aggregates carry no UPN); refusing to merge and leaving the prior file unchanged (AISID gap)." -ForegroundColor Yellow
				[void]$out.Failed.Add($table)
				$out.TableStatus[$table] = [ordered]@{ State = 'Failed'; Reason = 'scoped ClientChannel append: prior scope provenance unprovable; prior file left unchanged' }
				$script:AISIDHadGaps = $true
				continue
			}
		}

		# Read-before-merge for replace-on-key tables: reconcile against the accumulated history already
		# on disk so prior periods are preserved instead of being overwritten with only this run's rows.
		# Overwrite/dimension tables (empty Key) never enter this path. An explicitly injected ExistingRows
		# entry takes precedence over the on-disk read. On the LOCAL tier the prior history is streamed
		# row-by-row through the bounded merge (never materialized as an array); the remote tier still
		# downloads-and-reads (inherent) then array-merges.
		if ($schema.Key -and $schema.Key.Count -gt 0) {
			if ($ExistingRows.ContainsKey($table)) {
				$existing = @($ExistingRows[$table])
				if (@($existing).Count -gt 0) {
					$rows = Merge-AISIDTableOnKey -ExistingRows $existing -NewRows $rows -KeyColumns $schema.Key
				}
			}
			elseif (-not $script:RemoteOutputMode -or $script:RemoteOutputMode -eq 'None') {
				# Blocker-3: prior history comes from the SEPARATE supplied prior-bundle folder ($HistoryDir),
				# never from the fresh output run folder ($DestinationDir). No $HistoryDir
				# (-OutputPathDefenderUsage without -AppendDefenderUsage) => no prior history read; this run's
				# rows stand alone. A read failure (locked/malformed, not a confirmed absence) propagates so the
				# prior file is left untouched this run.
				$__histPath = if ($HistoryDir) { Join-Path $HistoryDir $schema.FileName } else { '' }
				if ($__histPath -and (Test-Path -LiteralPath $__histPath)) {
					try {
						$rows = Merge-AISIDTableOnKeyStreamed -ExistingCsvPath $__histPath -NewRows $rows -KeyColumns $schema.Key
					}
					catch {
						Write-LogHost ("[AISID] {0}: existing data could not be read ({1}); leaving the prior file untouched this run." -f $table, $_.Exception.Message) -ForegroundColor Yellow
						[void]$out.ReadFailures.Add($table)
						$out.TableStatus[$table] = [ordered]@{ State = 'Incomplete'; Reason = 'existing file unreadable; prior file left untouched' }
						continue
					}
				}
			}
			else {
				# Remote tier: prior history from the supplied prior-bundle URL ($ParentOverride); none when
				# empty (no -AppendDefenderUsage). Download prior history to a local scratch file (memory-safe),
				# then stream the scratch through the SAME bounded merge. Scratch is removed on success and
				# preserved for recovery on failure.
				if ($ParentOverride) {
					$scratchPath = $null
					try {
						$scratchPath = Get-AISIDExistingCsvToScratch -FileName $schema.FileName -ParentOverride $ParentOverride
						$rows = Merge-AISIDTableOnKeyStreamed -ExistingCsvPath $scratchPath -NewRows $rows -KeyColumns $schema.Key
					}
					catch {
						if ($scratchPath -and (Test-Path -LiteralPath $scratchPath)) { Write-LogHost ("[AISID] {0}: remote history scratch preserved for recovery: {1}" -f $table, $scratchPath) -ForegroundColor DarkYellow }
						Write-LogHost ("[AISID] {0}: existing data could not be read ({1}); leaving the prior file untouched this run." -f $table, $_.Exception.Message) -ForegroundColor Yellow
						[void]$out.ReadFailures.Add($table)
						$out.TableStatus[$table] = [ordered]@{ State = 'Incomplete'; Reason = 'existing file unreadable; prior file left untouched' }
						continue
					}
					if ($scratchPath -and (Test-Path -LiteralPath $scratchPath)) { Remove-Item -LiteralPath $scratchPath -Force -ErrorAction SilentlyContinue }
				}
			}
		}

		# Final post-merge scope containment (defense-in-depth): after the read-before-merge, verify NO
		# row in the merged result falls outside the effective target scope. History (injected, streamed
		# local, or downloaded remote) that reintroduced a non-target user is caught here; when
		# -Deidentify is on the comparison uses deidentified scope keys. If any out-of-scope row survives,
		# the merged file is NOT published, the prior file is left unchanged, the table is marked
		# Failed/Incomplete, and an AISID gap (exit 40) is flagged — a scoped run never emits a non-target
		# user and never overwrites prior history with a scope it cannot prove.
		$__cont = script:Select-AISIDContainedRows -Table $table -Rows $rows
		if ($__cont.Applies -and @($__cont.OutOfScope).Count -gt 0) {
			Write-LogHost ("[AISID] {0}: {1} row(s) outside the requested user scope survived the history merge; refusing to publish and leaving the prior file unchanged (AISID gap)." -f $table, @($__cont.OutOfScope).Count) -ForegroundColor Yellow
			[void]$out.Failed.Add($table)
			$out.TableStatus[$table] = [ordered]@{ State = 'Failed'; Reason = 'post-merge scope containment failed; prior file left unchanged' }
			$script:AISIDHadGaps = $true
			continue
		}

		$out[$table] = Export-AISIDTable -DestinationDir $DestinationDir -FileName $schema.FileName -OrderedColumns $schema.Columns -Rows $rows
		$out.TableStatus[$table] = [ordered]@{ State = $state; Reason = $reason }
	}

	# File Proximity: event-grain, append-and-dedup. Same licensing-gated pattern as the query-backed
	# tables above (eligibility -> collect -> read-before-merge -> merge -> export), but with the
	# append+dedup merge so accumulated event history only ever grows. The header-only stub is the
	# fallback only when the table is ineligible or its query fails AND no prior history exists.
	$fpSchema = $script:AISIDTableSchemas['FileProximity']
	$fpRows = @()
	$fpCollected = $false
	$fpState = 'Unavailable'; $fpReason = 'licensing ineligible'
	if ($Verdict['FileProximity'] -and $Verdict['FileProximity'].Eligible) {
		try {
			$fpQ = Get-AISIDFileProximity
			if ($fpQ.AuthQuit) { $out.AuthQuit = $true }
			if ($fpQ.Success)  { $fpRows = @($fpQ.Rows); $fpCollected = $true; if (@($fpRows).Count -gt 0) { $fpState = 'Succeeded'; $fpReason = 'collected rows' } else { $fpState = 'Empty'; $fpReason = 'query succeeded with zero rows' } } else { $fpState = 'Failed'; $fpReason = 'collector returned Success=false'; [void]$out.Failed.Add('FileProximity') }
		}
		catch {
			# Per-table isolation: an unexpected throw is caught so the dimension tables still run.
			# $fpCollected stays $false and $fpRows empty -> the append-dedup / stub path below falls
			# back to this table's safe output (stub when no prior history, else history preserved).
			Write-LogHost ("[AISID] {0}: collector threw an unexpected error ({1}); falling back to safe-empty output for this table." -f 'FileProximity', $_.Exception.Message) -ForegroundColor Yellow
			$fpState = 'Failed'; $fpReason = ("collector threw: {0}" -f $_.Exception.Message)
			[void]$out.Failed.Add('FileProximity')
		}
	}
	# Blocker-2: client-side target-user scope enforcement on FileProximity's NEW rows (same order as the
	# generic loop: scope BEFORE deidentify) so no non-target user reaches this run's output. No-op when
	# unscoped. Then deidentify the NEW rows before the append-dedup read/merge (no-op when off).
	$fpRows = script:Select-AISIDScopedRows -Table 'FileProximity' -Rows $fpRows
	$fpRows = ConvertTo-AISIDDeidentifiedRows -Table 'FileProximity' -Rows $fpRows
	$fpExisting = @()
	$fpReadFailed = $false
	$fpHasHistory = $false
	$fpUseStreamed = $false
	$fpStreamedPath = $null
	$fpScratchPath = $null
	if ($ExistingRows.ContainsKey('FileProximity')) {
		$fpExisting = @($ExistingRows['FileProximity'])
		$fpHasHistory = (@($fpExisting).Count -gt 0)
	}
	elseif (-not $script:RemoteOutputMode -or $script:RemoteOutputMode -eq 'None') {
		# Blocker-3: FileProximity prior event history comes from the SEPARATE supplied prior-bundle folder
		# ($HistoryDir), never from the fresh output run folder. No $HistoryDir => no prior history.
		try {
			$fpStreamedPath = if ($HistoryDir) { Join-Path $HistoryDir $fpSchema.FileName } else { '' }
			if ($fpStreamedPath) {
				$fpHasHistory = Test-AISIDCsvHasDataRow -Path $fpStreamedPath
				$fpUseStreamed = $true
			}
		}
		catch {
			Write-LogHost ("[AISID] {0}: existing data could not be read ({1}); leaving the prior file untouched this run." -f 'FileProximity', $_.Exception.Message) -ForegroundColor Yellow
			[void]$out.ReadFailures.Add('FileProximity')
			$fpState = 'Incomplete'; $fpReason = 'existing file unreadable; prior file left untouched'
			$fpReadFailed = $true
		}
	}
	else {
		# Remote tier: prior event history from the supplied prior-bundle URL ($ParentOverride); none when
		# empty (no -AppendDefenderUsage). Download prior history to a local scratch file (memory-safe),
		# then stream the scratch through the bounded append-dedup merge — never parsed into an array.
		if ($ParentOverride) {
			try {
				$fpScratchPath = Get-AISIDExistingCsvToScratch -FileName $fpSchema.FileName -ParentOverride $ParentOverride
				$fpStreamedPath = $fpScratchPath
				$fpHasHistory = ($fpScratchPath -and (Test-AISIDCsvHasDataRow -Path $fpScratchPath))
				$fpUseStreamed = $true
			}
			catch {
				# Not a confirmed absence: leave the prior file untouched this run rather than risk an
				# empty-merge overwrite of accumulated event history.
				if ($fpScratchPath -and (Test-Path -LiteralPath $fpScratchPath)) { Write-LogHost ("[AISID] {0}: remote history scratch preserved for recovery: {1}" -f 'FileProximity', $fpScratchPath) -ForegroundColor DarkYellow }
				Write-LogHost ("[AISID] {0}: existing data could not be read ({1}); leaving the prior file untouched this run." -f 'FileProximity', $_.Exception.Message) -ForegroundColor Yellow
				[void]$out.ReadFailures.Add('FileProximity')
				$fpState = 'Incomplete'; $fpReason = 'existing file unreadable; prior file left untouched'
				$fpReadFailed = $true
			}
		}
	}
	if (-not $fpReadFailed) {
		if ($fpHasHistory -or $fpCollected) {
			if ($fpUseStreamed) {
				try {
					$fpMerged = Merge-AISIDTableAppendDedupStreamed -ExistingCsvPath $fpStreamedPath -NewRows $fpRows -KeyColumns $fpSchema.Key
				}
				catch {
					if ($fpScratchPath -and (Test-Path -LiteralPath $fpScratchPath)) { Write-LogHost ("[AISID] {0}: remote history scratch preserved for recovery: {1}" -f 'FileProximity', $fpScratchPath) -ForegroundColor DarkYellow }
					Write-LogHost ("[AISID] {0}: existing data could not be read ({1}); leaving the prior file untouched this run." -f 'FileProximity', $_.Exception.Message) -ForegroundColor Yellow
					[void]$out.ReadFailures.Add('FileProximity')
					$fpState = 'Incomplete'; $fpReason = 'existing file unreadable; prior file left untouched'
					$fpReadFailed = $true
				}
			}
			else {
				$fpMerged = Merge-AISIDTableAppendDedup -ExistingRows $fpExisting -NewRows $fpRows -KeyColumns $fpSchema.Key
			}
			if (-not $fpReadFailed) {
				# Blocker-2: final post-merge scope containment (deidentify-aware) — history (injected, streamed
				# local, or downloaded remote) that reintroduced a non-target user is caught here. If any
				# out-of-scope row survives, DO NOT publish; mark Failed; preserve the prior file; flag an AISID
				# gap. A scoped run never emits a non-target FileProximity row.
				$__fpCont = script:Select-AISIDContainedRows -Table 'FileProximity' -Rows $fpMerged
				if ($__fpCont.Applies -and @($__fpCont.OutOfScope).Count -gt 0) {
					Write-LogHost ("[AISID] FileProximity: {0} row(s) outside the requested user scope survived the history merge; refusing to publish and leaving the prior file unchanged (AISID gap)." -f @($__fpCont.OutOfScope).Count) -ForegroundColor Yellow
					[void]$out.Failed.Add('FileProximity')
					$fpState = 'Failed'; $fpReason = 'post-merge scope containment failed; prior file left unchanged'
					$script:AISIDHadGaps = $true
				}
				else {
					$out.FileProximity = Export-AISIDTable -DestinationDir $DestinationDir -FileName $fpSchema.FileName -OrderedColumns $fpSchema.Columns -Rows $fpMerged
				}
			}
		}
		else {
			# Ineligible or query-failed with no prior history: emit the header-only stub fallback.
			$out.FileProximity = New-AISIDFileProximityStub -DestinationDir $DestinationDir
		}
	}
	# Remove the downloaded remote history scratch on success; on a read/merge failure it is preserved
	# above for recovery.
	if (-not $fpReadFailed -and $fpScratchPath -and (Test-Path -LiteralPath $fpScratchPath)) {
		Remove-Item -LiteralPath $fpScratchPath -Force -ErrorAction SilentlyContinue
	}
	$out.TableStatus['FileProximity'] = [ordered]@{ State = $fpState; Reason = $fpReason }

	# Dimension tables: always regenerated in full (overwrite), independent of any licensing verdict and
	# with no per-row key merge. Both project already-collected in-memory data. Each collector call is
	# isolated so an unexpected throw falls back to a header-only file and never skips the other table.
	$catSchema = $script:AISIDTableSchemas['SolutionsCatalog']
	$catRows = @()
	$catState = 'Succeeded'; $catReason = 'dimension regenerated'
	try { $catRows = @(Get-AISIDSolutionsCatalogExport) }
	catch { Write-LogHost ("[AISID] {0}: collector threw an unexpected error ({1}); the dimension FAILED (recorded as a gap)." -f 'SolutionsCatalog', $_.Exception.Message) -ForegroundColor Red; $catState = 'Failed'; $catReason = ("collector threw: {0}" -f $_.Exception.Message); [void]$out.Failed.Add('SolutionsCatalog') }
	if ($catState -eq 'Succeeded' -and @($catRows).Count -eq 0) { $catState = 'Empty'; $catReason = 'dimension produced zero rows' }
	$catRows = ConvertTo-AISIDDeidentifiedRows -Table 'SolutionsCatalog' -Rows $catRows
	$out.SolutionsCatalog = Export-AISIDTable -DestinationDir $DestinationDir -FileName $catSchema.FileName -OrderedColumns $catSchema.Columns -Rows $catRows
	$out.TableStatus['SolutionsCatalog'] = [ordered]@{ State = $catState; Reason = $catReason }

	$euSchema = $script:AISIDTableSchemas['EntraUsers']
	$euRows = @()
	$euState = 'Succeeded'; $euReason = 'dimension regenerated'
	try { $euRows = @(Get-AISIDEntraUsersProjection) }
	catch { Write-LogHost ("[AISID] {0}: collector threw an unexpected error ({1}); the dimension FAILED (recorded as a gap)." -f 'EntraUsers', $_.Exception.Message) -ForegroundColor Red; $euState = 'Failed'; $euReason = ("collector threw: {0}" -f $_.Exception.Message); [void]$out.Failed.Add('EntraUsers') }
	if ($euState -eq 'Succeeded' -and @($euRows).Count -eq 0) { $euState = 'Empty'; $euReason = 'dimension produced zero rows' }
	# F3 backstop (defense-in-depth): for a SCOPED AISID run the requested target(s) are REQUIRED in the
	# EntraUsers dimension. The early user-scope gate already fails closed when an explicit target is absent
	# from the directory; this second line of defense catches a resolved target that is nevertheless missing
	# from the projected rows and records it as a real gap (Failed) — NOT a factual Empty. Only the explicit
	# target set is required (manager-chain rows merely accompany it); an unscoped run keeps ordinary Empty.
	if ($euState -ne 'Failed') {
		$euScope = script:Get-AISIDScopeUpnSet
		if ($null -ne $euScope) {
			$euProjected = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
			foreach ($er in @($euRows)) {
				if (-not $er) { continue }
				$eg = if ($er -is [System.Collections.IDictionary]) { [string]$er['userPrincipalName'] } else { [string]$er.userPrincipalName }
				$eg = ([string]$eg).Trim()
				if ($eg) { [void]$euProjected.Add($eg) }
			}
			$euMissingTargets = @(@($euScope) | Where-Object { $t = ([string]$_).Trim(); $t -and -not $euProjected.Contains($t) })
			if ($euMissingTargets.Count -gt 0) {
				Write-LogHost ("[AISID] EntraUsers: required scoped target(s) absent from the directory projection ({0}); the dimension FAILED (recorded as a gap), not a factual empty." -f (@($euMissingTargets) -join ', ')) -ForegroundColor Red
				$euState = 'Failed'; $euReason = ("required scoped target(s) not present in projection: {0}" -f (@($euMissingTargets) -join ', '))
				[void]$out.Failed.Add('EntraUsers')
			}
		}
	}
	$euRows = ConvertTo-AISIDDeidentifiedRows -Table 'EntraUsers' -Rows $euRows
	$out.EntraUsers = Export-AISIDTable -DestinationDir $DestinationDir -FileName $euSchema.FileName -OrderedColumns $euSchema.Columns -Rows $euRows
	$out.TableStatus['EntraUsers'] = [ordered]@{ State = $euState; Reason = $euReason }

	# The dashboard loads these MDA-tier tables unconditionally. Until their collectors are available,
	# preserve valid prior history byte-for-byte; when none exists, publish exact header-only compatibility
	# files so tenants without those data sources refresh cleanly.
	foreach ($stubTable in @('AppGovAlerts', 'CloudDiscovery', 'MDASessions')) {
		try {
			$out[$stubTable] = Export-AISIDCompatibilityTable -Table $stubTable -DestinationDir $DestinationDir -ExistingRows $ExistingRows -HistoryDir $HistoryDir -ParentOverride $ParentOverride
			$out.TableStatus[$stubTable] = [ordered]@{ State = 'Unavailable'; Reason = 'data source not implemented; prior history preserved or header-only compatibility file emitted' }
		}
		catch {
			Write-LogHost ("[AISID] {0}: existing compatibility data could not be preserved ({1}); leaving the prior file unchanged." -f $stubTable, $_.Exception.Message) -ForegroundColor Yellow
			[void]$out.ReadFailures.Add($stubTable)
			$out.TableStatus[$stubTable] = [ordered]@{ State = 'Incomplete'; Reason = 'existing compatibility file unreadable or invalid; prior file left unchanged' }
		}
	}
	return $out
}

function ConvertTo-AISIDDeidentifiedRows {
	<#
	.SYNOPSIS
		Deidentifies the PII columns of an AISID table's newly-collected rows, reusing the shared
		deterministic Get-PaxDeid* helpers (same salt/algorithm as the main pipeline and the Python
		rollup, so a given real identity maps to the identical token everywhere and cross-table joins
		survive). No new hashing logic is introduced.
	.DESCRIPTION
		No-op when -Deidentify is off ($script:PaxDeidEnabled = $false): the input rows are returned
		unchanged (same reference). Only the columns named in the per-table map are transformed; every
		other column is copied verbatim and column order is preserved (the source row is never mutated).
		Tables with NO map entry are returned unchanged: ClientChannel and SolutionsCatalog carry no PII.
		CopilotUsage IS deidentified in this path now: its source is the run's IDENTIFIED raw Purview CSV,
		so its UserPrincipalName is hashed once through the shared Get-PaxDeid* path to the identical token
		used everywhere. Applied to a table's NEW rows BEFORE the read-before-merge/merge so on-disk (already
		deidentified) rows and these rows compare on matching keys. Org/geo attributes (department,
		jobTitle, city, country, companyName, ...) are intentionally retained, matching the main
		pipeline's established Invoke-PaxRawDeidentify policy.
	.OUTPUTS
		The rows with mapped PII columns deidentified, or the input unchanged (off / no map entry).
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$Table,
		[object[]]$Rows = @()
	)
	if (-not $script:PaxDeidEnabled) { return $Rows }

	# Per-table PII column -> Get-PaxDeid* helper kind. Direct identifiers only. ClientChannel and
	# SolutionsCatalog carry no PII and are deliberately absent; CopilotUsage IS mapped here now.
	$deidMap = @{
		ActivitySessions = [ordered]@{ UPN = 'Upn' }
		OffHoursGeo      = [ordered]@{ UPN = 'Upn' }
		OAuthConsents    = [ordered]@{ UPN = 'Upn' }
		SSOSignIns       = [ordered]@{ UPN = 'Upn' }
		FileProximity    = [ordered]@{ UPN = 'Upn'; FileName = 'File'; FolderPath = 'Resource' }
		CopilotUsage     = [ordered]@{ UserPrincipalName = 'Upn' }
		EntraUsers       = [ordered]@{ userPrincipalName = 'Upn'; displayName = 'Name'; manager_userPrincipalName = 'Upn'; manager_displayName = 'Name' }
	}
	$colMap = $deidMap[$Table]
	if (-not $colMap) { return $Rows }

	$out = foreach ($row in $Rows) {
		if (-not $row) { continue }
		# Ordered clone: preserves column order and never mutates the source row object.
		$clone = [ordered]@{}
		foreach ($p in $row.PSObject.Properties) { $clone[$p.Name] = $p.Value }
		foreach ($col in $colMap.Keys) {
			if ($clone.Contains($col) -and -not [string]::IsNullOrEmpty([string]$clone[$col])) {
				$sv = [string]$clone[$col]
				$clone[$col] = switch ($colMap[$col]) {
					'Upn'      { Get-PaxDeidUpn      -Value $sv }
					'Name'     { Get-PaxDeidName     -Value $sv }
					'File'     { Get-PaxDeidFile     -Value $sv }
					'Resource' { Get-PaxDeidResource -Value $sv }
				}
			}
		}
		[pscustomobject]$clone
	}
	return @($out)
}

function Invoke-AISIDPilotExport {
	<#
	.SYNOPSIS
		End-of-run orchestrator for the AI Solutions Intelligence Dashboard (AISID) export: evaluates
		per-table licensing, reports it, and writes all twelve dashboard CSVs through the shared
		export/merge infrastructure. Intended to be called exactly once, only under -Dashboard AISID,
		from the point in the rollup post-processing where the CopilotInteraction Fact CSV has just
		been written and BEFORE any -AppendFile merge/delete can consume it (so Get-AISIDCopilotUsage's
		source is guaranteed present).
	.DESCRIPTION
		Whole-call failure isolation: any unexpected error is caught, logged loudly, and swallowed so
		the AISID export can never abort the run or disturb the Purview/rollup output already on disk.
		Per-table handling (each collector's licensing-ineligible/empty result and each read failure ->
		safe header-only fallback / ReadFailures) is owned by Export-AISIDPilotTables; this outer guard
		covers Test-AISIDLicensing and any orchestration-level error.
	.OUTPUTS
		The Export-AISIDPilotTables result hashtable (written paths per table + AuthQuit), or $null on
		an isolated failure.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$DestinationDir,
		[switch]$DisableDeltaCache,
		[string]$RawPurviewCsv,
		[string]$ParentOverride,
		[string]$HistoryDir = ''
	)
	try {
		$verdict = Test-AISIDLicensing
		Write-AISIDLicensingReport -Verdict $verdict
		return Export-AISIDPilotTables -DestinationDir $DestinationDir -Verdict $verdict -DisableDeltaCache:$DisableDeltaCache -RawPurviewCsv $RawPurviewCsv -ParentOverride $ParentOverride -HistoryDir $HistoryDir
	}
	catch {
		Write-LogHost ("[AISID] Dashboard export failed (non-fatal; the run's Purview/rollup output is unaffected): {0}" -f $_.Exception.Message) -ForegroundColor Red
		return $null
	}
}

function Get-AISIDCompletionStatus {
	<#
	.SYNOPSIS
		Evaluates whether the AISID dashboard export completed truthfully, using the per-table state
		contract (TableStatus: Succeeded / Empty / Unavailable / Failed / Incomplete) produced by
		Export-AISIDPilotTables cross-checked against the twelve contractual dashboard CSVs (each must
		exist with its exact header). A collector Failed/Incomplete state, a missing/invalid required
		file, an auth-quit interruption, or an orchestration-level null result is a GAP and must never
		be reported as clean. Header-only output alone never decides WHY a table is empty — the
		collector's recorded state does.
	.OUTPUTS
		[pscustomobject] with Status, HadGaps, AllTablesTerminal, CleanCompletion, Missing, Failed,
		Incomplete, Unavailable, Empty, Succeeded, AuthQuit, ExportErrored, PerTable.
	#>
	[CmdletBinding()]
	param([object]$Result, [Parameter(Mandatory)][string]$DestinationDir)

	$schemas = $script:AISIDTableSchemas
	$order = @('ActivitySessions', 'OffHoursGeo', 'FileProximity', 'OAuthConsents', 'SSOSignIns', 'ClientChannel', 'CopilotUsage', 'AppGovAlerts', 'CloudDiscovery', 'MDASessions', 'SolutionsCatalog', 'EntraUsers')
	$exportErrored = ($null -eq $Result)
	$ts = if ($Result -and $Result.TableStatus) { $Result.TableStatus } else { $null }

	$missing = @(); $failed = @(); $incomplete = @(); $unavailable = @(); $empty = @(); $succeeded = @()
	$perTable = [ordered]@{}
	$allTerminal = (-not $exportErrored)

	foreach ($t in $order) {
		$sch = $schemas[$t]
		# Collector-recorded state (authoritative for WHY). Absent => the export never decided this table.
		$state = 'Incomplete'; $reason = 'export did not return a state for this table'
		if ($ts -and $ts.Contains($t)) { $state = [string]$ts[$t].State; $reason = [string]$ts[$t].Reason }
		else { $allTerminal = $false }

		# File presence + header validity (the dashboard model binds each CSV by a fixed header).
		$fileOk = $false; $fileNote = 'missing'
		if ($sch) {
			$path = Join-Path $DestinationDir $sch.FileName
			if (Test-Path -LiteralPath $path) {
				$header = $null
				try { $header = (Get-Content -LiteralPath $path -TotalCount 1 -ErrorAction Stop) } catch { $header = $null }
				if (-not [string]::IsNullOrEmpty($header) -and ($header.Trim() -eq ($sch.Columns -join ','))) { $fileOk = $true; $fileNote = 'present' }
				else { $fileNote = 'invalid header' }
			}
		}
		if (-not $fileOk) { $missing += $sch.FileName }

		# A Succeeded/Empty/Unavailable state that lost its file is a contradiction -> treat as a gap.
		$effective = $state
		if (-not $fileOk -and $state -in @('Succeeded', 'Empty', 'Unavailable')) { $effective = 'Failed'; $reason = ("recorded {0} but output file is {1}" -f $state, $fileNote) }

		switch ($effective) {
			'Succeeded'  { $succeeded += $t }
			'Empty'      { $empty += $t }
			'Unavailable' { $unavailable += $t }
			'Failed'     { $failed += $t }
			default      { $incomplete += $t }
		}
		$perTable[$t] = [ordered]@{ State = $effective; Reason = $reason; File = $fileNote }
	}

	$authQuit = [bool]($Result -and $Result.AuthQuit)
	$hadGaps = $exportErrored -or ($failed.Count -gt 0) -or ($incomplete.Count -gt 0) -or ($missing.Count -gt 0) -or $authQuit
	$cleanCompletion = (-not $hadGaps) -and $allTerminal -and (($succeeded.Count + $empty.Count + $unavailable.Count) -eq $order.Count)
	$status = if ($authQuit) { 'interrupted' } elseif ($hadGaps) { 'completed-with-gaps' } elseif ($unavailable.Count -gt 0) { 'complete-with-unavailable' } elseif ($empty.Count -gt 0) { 'complete-with-empty' } else { 'complete' }

	Write-LogHost '[AISID] ===== Dashboard completion summary =====' -ForegroundColor Cyan
	Write-LogHost ("[AISID] Required dashboard files present: {0}/{1}" -f ($order.Count - @($missing | Sort-Object -Unique).Count), $order.Count) -ForegroundColor Gray
	if ($succeeded.Count -gt 0)  { Write-LogHost ("[AISID] Succeeded: {0}" -f ($succeeded -join ', ')) -ForegroundColor Green }
	if ($empty.Count -gt 0)      { Write-LogHost ("[AISID] Empty (query succeeded, zero rows): {0}" -f ($empty -join ', ')) -ForegroundColor Gray }
	if ($unavailable.Count -gt 0) { Write-LogHost ("[AISID] Unavailable (licensing ineligible): {0}" -f ($unavailable -join ', ')) -ForegroundColor Gray }
	if ($failed.Count -gt 0)     { Write-LogHost ("[AISID] FAILED (real data gap, NOT a factual empty): {0}" -f (@($failed | Sort-Object -Unique) -join ', ')) -ForegroundColor Red }
	if ($incomplete.Count -gt 0) { Write-LogHost ("[AISID] Incomplete (collector not reached / existing file unreadable): {0}" -f (@($incomplete | Sort-Object -Unique) -join ', ')) -ForegroundColor Yellow }
	if (@($missing | Sort-Object -Unique).Count -gt 0) { Write-LogHost ("[AISID] Missing/invalid required files: {0}" -f (@($missing | Sort-Object -Unique) -join ', ')) -ForegroundColor Red }
	if ($authQuit)      { Write-LogHost '[AISID] Collection was interrupted (authentication quit) before all data sets finished.' -ForegroundColor Red }
	if ($exportErrored) { Write-LogHost '[AISID] Dashboard export failed at the orchestration level (isolated error); output is incomplete.' -ForegroundColor Red }
	Write-LogHost ("[AISID] Overall AISID status: {0}" -f $status) -ForegroundColor Cyan

	return [pscustomobject]@{
		Status = $status; HadGaps = $hadGaps; AllTablesTerminal = $allTerminal; CleanCompletion = $cleanCompletion
		Missing = @($missing | Sort-Object -Unique); Failed = @($failed | Sort-Object -Unique); Incomplete = @($incomplete | Sort-Object -Unique)
		Unavailable = @($unavailable); Empty = @($empty); Succeeded = @($succeeded); AuthQuit = $authQuit; ExportErrored = $exportErrored; PerTable = $perTable
	}
}

function Send-PromptNotification {
	<#
	.SYNOPSIS
		Plays a system beep to alert user that a prompt requires attention.
	.DESCRIPTION
		Useful when user is working in other windows and needs to be notified
		when a prompt appears that requires input.
	#>
	
	try {
		# Play 3 short beeps to get attention
		[Console]::Beep(800, 200)  # 800Hz for 200ms
		Start-Sleep -Milliseconds 100
		[Console]::Beep(1000, 200) # 1000Hz for 200ms
		Start-Sleep -Milliseconds 100
		[Console]::Beep(1200, 300) # 1200Hz for 300ms (slightly longer final beep)
	}
	catch {
		# Silently fail if beep not supported (e.g., some server environments)
	}
}

# Validate -OnlyUserInfo parameter compatibility
if ($OnlyUserInfo) {
	$incompatibleParams = @()
	
	# Date filtering parameters
	if ($PSBoundParameters.ContainsKey('StartDate')) { $incompatibleParams += "  - StartDate (not applicable for user-only export)" }
	if ($PSBoundParameters.ContainsKey('EndDate')) { $incompatibleParams += "  - EndDate (not applicable for user-only export)" }
	
	# Activity configuration parameters
	if ($PSBoundParameters.ContainsKey('ActivityTypes')) { $incompatibleParams += "  - ActivityTypes (cleared by -OnlyUserInfo)" }
	if ($IncludeM365Usage) { $incompatibleParams += "  - IncludeM365Usage (activity type modifier)" }
	if ($ExcludeCopilotInteraction) { $incompatibleParams += "  - ExcludeCopilotInteraction (activity type modifier)" }
	
	# Audit retrieval settings
	if ($PSBoundParameters.ContainsKey('BlockHours') -and $BlockHours -ne 0.5) { $incompatibleParams += "  - BlockHours (audit query partitioning)" }
	if ($PSBoundParameters.ContainsKey('PartitionHours') -and $PartitionHours -ne 0) { $incompatibleParams += "  - PartitionHours (audit query partitioning)" }
	if ($PSBoundParameters.ContainsKey('MaxPartitions') -and $MaxPartitions -ne 160) { $incompatibleParams += "  - MaxPartitions (audit query limits)" }
	if ($PSBoundParameters.ContainsKey('ResultSize') -and $ResultSize -ne 10000) { $incompatibleParams += "  - ResultSize (audit query page size)" }
	if ($PSBoundParameters.ContainsKey('PacingMs') -and $PacingMs -ne 0) { $incompatibleParams += "  - PacingMs (audit query throttling)" }
	if ($AutoCompleteness) { $incompatibleParams += "  - AutoCompleteness (audit log completeness checks)" }
	if ($PSBoundParameters.ContainsKey('StreamingSchemaSample') -and $StreamingSchemaSample -ne 5000) { $incompatibleParams += "  - StreamingSchemaSample (audit record schema sampling)" }
	if ($PSBoundParameters.ContainsKey('StreamingChunkSize') -and $StreamingChunkSize -ne 5000) { $incompatibleParams += "  - StreamingChunkSize (audit streaming batch size)" }
	if ($PSBoundParameters.ContainsKey('ExportProgressInterval') -and $ExportProgressInterval -ne 10) { $incompatibleParams += "  - ExportProgressInterval (audit export progress)" }
	
	# Filtering parameters
	if ($PSBoundParameters.ContainsKey('AgentId')) { $incompatibleParams += "  - AgentId (audit record filtering)" }
	if ($AgentsOnly) { $incompatibleParams += "  - AgentsOnly (audit record filtering)" }
	if ($ExcludeAgents) { $incompatibleParams += "  - ExcludeAgents (audit record filtering)" }
	if ($PSBoundParameters.ContainsKey('PromptFilter')) { $incompatibleParams += "  - PromptFilter (audit record content filtering)" }
	if ($PSBoundParameters.ContainsKey('RecordTypes')) { $incompatibleParams += "  - RecordTypes (audit record filtering)" }
	if ($PSBoundParameters.ContainsKey('ServiceTypes')) { $incompatibleParams += "  - ServiceTypes (audit record filtering)" }
	
	# Processing mode parameters
	if ($ExplodeArrays) { $incompatibleParams += "  - ExplodeArrays (audit record array expansion)" }
	if ($ExplodeDeep) { $incompatibleParams += "  - ExplodeDeep (audit record deep expansion)" }
	if ($PSBoundParameters.ContainsKey('RAWInputCSV')) { $incompatibleParams += "  - RAWInputCSV (offline audit replay mode)" }
	
	# Parallel processing parameters
	if ($EnableParallel) { $incompatibleParams += "  - EnableParallel (parallel audit query execution)" }
	if ($PSBoundParameters.ContainsKey('MaxConcurrency') -and $MaxConcurrency -ne 10) { $incompatibleParams += "  - MaxConcurrency (concurrent query/partition limit)" }
	if ($PSBoundParameters.ContainsKey('MaxParallelGroups') -and $MaxParallelGroups -ne 8) { $incompatibleParams += "  - MaxParallelGroups (parallel activity group limit)" }
	if ($PSBoundParameters.ContainsKey('ParallelMode') -and $ParallelMode -ne 'Auto') { $incompatibleParams += "  - ParallelMode (parallel processing mode)" }
	if ($DisableAdaptive) { $incompatibleParams += "  - DisableAdaptive (adaptive concurrency controls)" }
	if ($PSBoundParameters.ContainsKey('ProgressSmoothingAlpha') -and $ProgressSmoothingAlpha -ne 0.3) { $incompatibleParams += "  - ProgressSmoothingAlpha (adaptive tuning)" }
	if ($PSBoundParameters.ContainsKey('HighLatencyMs') -and $HighLatencyMs -ne 90000) { $incompatibleParams += "  - HighLatencyMs (adaptive tuning)" }
	if ($PSBoundParameters.ContainsKey('MemoryPressureMB') -and $MemoryPressureMB -ne 1500) { $incompatibleParams += "  - MemoryPressureMB (adaptive tuning)" }
	if ($PSBoundParameters.ContainsKey('LowLatencyMs') -and $LowLatencyMs -ne 20000) { $incompatibleParams += "  - LowLatencyMs (adaptive tuning)" }
	if ($PSBoundParameters.ContainsKey('LowLatencyConsecutive') -and $LowLatencyConsecutive -ne 2) { $incompatibleParams += "  - LowLatencyConsecutive (adaptive tuning)" }
	if ($PSBoundParameters.ContainsKey('ThroughputDropPct') -and $ThroughputDropPct -ne 15) { $incompatibleParams += "  - ThroughputDropPct (adaptive tuning)" }
	if ($PSBoundParameters.ContainsKey('ThroughputSmoothingAlpha') -and $ThroughputSmoothingAlpha -ne 0.3) { $incompatibleParams += "  - ThroughputSmoothingAlpha (adaptive tuning)" }
	if ($PSBoundParameters.ContainsKey('AdaptiveConcurrencyCeiling') -and $AdaptiveConcurrencyCeiling -ne 6) { $incompatibleParams += "  - AdaptiveConcurrencyCeiling (adaptive tuning)" }
	
	# Reliability parameters (audit-specific)
	if ($PSBoundParameters.ContainsKey('CircuitBreakerThreshold') -and $CircuitBreakerThreshold -ne 5) { $incompatibleParams += "  - CircuitBreakerThreshold (block failure circuit breaker)" }
	if ($PSBoundParameters.ContainsKey('CircuitBreakerCooldownSeconds') -and $CircuitBreakerCooldownSeconds -ne 120) { $incompatibleParams += "  - CircuitBreakerCooldownSeconds (circuit breaker cooldown)" }
	if ($PSBoundParameters.ContainsKey('BackoffBaseSeconds') -and $BackoffBaseSeconds -ne 1.0) { $incompatibleParams += "  - BackoffBaseSeconds (block retry backoff)" }
	if ($PSBoundParameters.ContainsKey('BackoffMaxSeconds') -and $BackoffMaxSeconds -ne 45) { $incompatibleParams += "  - BackoffMaxSeconds (block retry max backoff)" }
	
	# Alternative modes
	if ($UseEOM) { $incompatibleParams += "  - UseEOM (Exchange Online Management mode incompatible with Graph Entra enrichment)" }
	
	# Output combination parameters
	if ($CombineOutput) { $incompatibleParams += "  - CombineOutput (only relevant with multiple activity types)" }
	if ($AppendFile) { $incompatibleParams += "  - AppendFile (appending user-only data to existing audit output not supported)" }
	
	if ($incompatibleParams.Count -gt 0) {
		Write-Host ""
		Write-Host "ERROR: The -OnlyUserInfo switch cannot be used with the following parameters:" -ForegroundColor Red
		Write-Host ""
		$incompatibleParams | ForEach-Object { Write-Host $_ -ForegroundColor Yellow }
		Write-Host ""
		Write-Host "The -OnlyUserInfo switch exports only Entra user directory and license information (no audit logs)." -ForegroundColor Cyan
		Write-Host ""
		Write-Host "Compatible parameters:" -ForegroundColor Green
		Write-Host "  - OutputPath (where to save the file)" -ForegroundColor White
		Write-Host "  - UserIds / GroupNames (scope the exported directory to these users / group members)" -ForegroundColor White
		Write-Host "  - Auth (authentication method: WebLogin, DeviceCode, Credential, Silent)" -ForegroundColor White
		Write-Host "  - Force (bypass interactive prompts)" -ForegroundColor White
		Write-Host "  - MaxNetworkOutageMinutes (network resilience for Graph API calls)" -ForegroundColor White
		Write-Host "  - EmitMetricsJson (track Entra retrieval metrics)" -ForegroundColor White
		Write-Host "  - MetricsPath (custom metrics output location)" -ForegroundColor White
		Write-Host "  - SkipDiagnostics (skip pre-query capability checks)" -ForegroundColor White
		Write-Host ""
		Write-Host "Please remove the incompatible parameters and try again." -ForegroundColor Cyan
		Write-Host ""
		exit 1
	}
	
	# If validation passes, configure for user-only export
	Write-Host ""
	Write-Host "INFO: -OnlyUserInfo mode enabled. Skipping all audit log retrieval, exporting only Entra user data." -ForegroundColor Green
	Write-Host ""
	$IncludeUserInfo = $true
	$ActivityTypes = @()
}

# PAX4A-GUARD-BEGIN
# -UserInfoFile / -GroupNames MUTUAL EXCLUSIVITY
# -UserInfoFile supplies the Entra user directory from a customer-provided CSV (bypassing the
# live /users pull). -GroupNames expands audit records against the LIVE directory. Supplying both
# is contradictory. Hard-stop here in the early parameter-validation stage so it fires on EVERY
# entry path (fresh and -Resume) BEFORE any -GroupNames consumer downstream (the RequiredScopes
# builder and the permissions banner). No partial work is done.
if ($PSBoundParameters.ContainsKey('UserInfoFile') -and $PSBoundParameters.ContainsKey('GroupNames')) {
	Write-Host ""
	Write-Host "ERROR: -UserInfoFile and -GroupNames cannot both be supplied." -ForegroundColor Red
	Write-Host "  -UserInfoFile ingests the Entra user directory from a customer-provided CSV." -ForegroundColor Yellow
	Write-Host "  -GroupNames expands audit records against the live Entra directory." -ForegroundColor Yellow
	Write-Host "  Supply exactly ONE: -UserInfoFile for a supplied directory, or -GroupNames for group filtering." -ForegroundColor Yellow
	Write-Host ""
	exit 1
}
# PAX4A-GUARD-END

# PAX4D-AUTOENABLE-BEGIN
# -UserInfoFile auto-enables -IncludeUserInfo (FU6): every -UserInfoFile export path (file naming,
# the multi-tab workbook, and the directory substitution seam) is gated on $IncludeUserInfo, so a
# customer need only pass -UserInfoFile. Mirrors the -OnlyUserInfo auto-enable above; fires on every
# entry path before any $IncludeUserInfo consumer. No effect when -UserInfoFile is unset.
if ($PSBoundParameters.ContainsKey('UserInfoFile') -and -not [string]::IsNullOrWhiteSpace($UserInfoFile) -and -not $IncludeUserInfo) {
	$IncludeUserInfo = $true
}
# PAX4D-AUTOENABLE-END

# PAX-UIS-GUARD-BEGIN
# -UserInfoSupplement is the HYBRID directory-enrichment mode: the live Entra directory is fetched
# normally and the supplemental CSV columns are appended by an Entra-left join. It is distinct from
# -UserInfoFile (which REPLACES the directory), so the two are mutually exclusive. It also requires the
# live /users pull, so it is incompatible with -UseEOM (no Graph directory) and -RAWInputCSV (offline
# replay). Unlike -UserInfoFile, it is COMPATIBLE with -GroupNames. These hard-stops fire on every entry
# path (fresh and -Resume) before any consumer. It auto-enables -IncludeUserInfo.
$script:UserInfoSupplementActive = ($PSBoundParameters.ContainsKey('UserInfoSupplement') -and -not [string]::IsNullOrWhiteSpace($UserInfoSupplement))
if ($script:UserInfoSupplementActive) {
	if ($PSBoundParameters.ContainsKey('UserInfoFile') -and -not [string]::IsNullOrWhiteSpace($UserInfoFile)) {
		Write-Host ""
		Write-Host "ERROR: -UserInfoSupplement and -UserInfoFile cannot both be supplied." -ForegroundColor Red
		Write-Host "  -UserInfoSupplement ENRICHES the live Entra directory (hybrid); -UserInfoFile REPLACES it." -ForegroundColor Yellow
		Write-Host "  Supply exactly ONE." -ForegroundColor Yellow
		Write-Host ""
		exit 1
	}
	if ($UseEOM) {
		Write-Host ""
		Write-Host "ERROR: -UserInfoSupplement requires the Graph /users directory and is not supported with -UseEOM." -ForegroundColor Red
		Write-Host ""
		exit 1
	}
	if ($PSBoundParameters.ContainsKey('RAWInputCSV') -and -not [string]::IsNullOrWhiteSpace($RAWInputCSV)) {
		Write-Host ""
		Write-Host "ERROR: -UserInfoSupplement enriches a live directory fetch and cannot be combined with -RAWInputCSV (offline replay)." -ForegroundColor Red
		Write-Host ""
		exit 1
	}
	if (-not $IncludeUserInfo) { $IncludeUserInfo = $true }
}
# PAX-UIS-GUARD-END

