        row["SiteUrl"] = deid_resource(row["SiteUrl"])
        row["SourceRelativeUrl"] = deid_resource(row["SourceRelativeUrl"])
        row["SourceFileName"] = deid_file(row["SourceFileName"])
    return row


def explode_m365_record(record: dict, audit_data: dict) -> list[dict]:
    """
    Extract a non-Copilot M365 record (Path A).
    Produces exactly 1 row per record with all 153 M code columns.
    No array explosion — M code does not explode non-Copilot arrays.
    """
    return [_build_unified_row(record, audit_data)]


# ═════════════════════════════════════════════════════════════════════════════
# PATH B: COPILOT EXPLOSION
# ═════════════════════════════════════════════════════════════════════════════

def explode_copilot_record(
    record: dict,
    audit_data: dict,
    ced: dict,
    prompt_filter: str | None = None,
) -> list[dict]:
    """
    Explode a Copilot record (Path B).
    Starts from the unified 153-column base row, then overrides CED-specific fields.
    Extracts Messages, Contexts, AccessedResources, AISystemPlugin,
    ModelTransparencyDetails, SensitivityLabels and builds N parallel-indexed rows.
    """
    # Extract array fields from CopilotEventData
    messages = get_array_fast(ced, "Messages")
    contexts = get_array_fast(ced, "Contexts")
    resources = get_array_fast(ced, "AccessedResources")
    plugins_raw = get_array_fast(ced, "AISystemPlugin")
    model_det_raw = get_array_fast(ced, "ModelTransparencyDetails")
    message_ids = get_array_fast(ced, "MessageIds")
    sensitivity_labels = get_array_fast(ced, "SensitivityLabels")

    # Prompt filtering
    if prompt_filter:
        filtered: list = []
        pf_lower = prompt_filter.lower()
        if pf_lower == "null":
            filtered = [m for m in messages if safe_get(m, "isPrompt") is None]
        elif pf_lower == "both":
            filtered = [m for m in messages if safe_get(m, "isPrompt") is not None]
        elif pf_lower == "prompt":
            filtered = [m for m in messages if safe_get(m, "isPrompt") is True]
        elif pf_lower == "response":
            filtered = [m for m in messages if safe_get(m, "isPrompt") is False]
        messages = filtered
        if not messages:
            return []

    # Detect activity type for 2-level explosion
    activity_type = safe_get(audit_data, "Operation") or ""

    # Context items max for CopilotInteraction
    context_items_max: int = 0
    if activity_type == "CopilotInteraction" and contexts:
        for ctx in contexts:
            if ctx:
                items = get_array_fast(ctx, "Items")
                if items and len(items) > context_items_max:
                    context_items_max = len(items)

    # Calculate row count
    if prompt_filter:
        row_count = max(1, len(messages))
    else:
        array_counts = [
            1, len(messages), len(contexts), len(resources),
            len(sensitivity_labels), len(plugins_raw), len(model_det_raw),
        ]
        if context_items_max > 0:
            array_counts.append(context_items_max)
        row_count = max(array_counts)

    row_count = min(row_count, EXPLOSION_PER_RECORD_ROW_CAP)
    if row_count < 1:
        row_count = 1

    # ── Build unified base row with all 153 M code columns ───────────────
    base = _build_unified_row(record, audit_data)

    # ── Override CED-specific scalar fields with deep CED extraction ─────
    # AppHost: prefer CED → audit_data → Workload
    base["AppHost"] = select_first_non_null([
        safe_get(ced, "AppHost"),
        safe_get(audit_data, "AppHost"),
        safe_get(audit_data, "Workload"),
    ]) or ""

    base["ThreadId"] = safe_get(ced, "ThreadId") or ""

    # AgentVersion: prefer audit_data → CED fallbacks
    base["AgentVersion"] = select_first_non_null([
        safe_get(audit_data, "AgentVersion"),
        safe_get(ced, "AgentVersion"),
        safe_get(ced, "Version"),
    ]) or ""

    # ApplicationName: prefer audit_data → CED fallbacks
    base["ApplicationName"] = select_first_non_null([
        safe_get(audit_data, "ApplicationName"),
        safe_get(ced, "HostAppName"),
        safe_get(ced, "ClientAppName"),
    ]) or ""

    # Model fields from CED with fallbacks
    base["ModelId"] = select_first_non_null([
        safe_get(ced, "ModelId"), safe_get(ced, "ModelID"), safe_get(audit_data, "ModelId"),
    ]) or ""
    base["ModelProvider"] = select_first_non_null([
        safe_get(ced, "ModelProvider"), safe_get(ced, "Provider"), safe_get(ced, "ModelVendor"),
    ]) or ""
    base["ModelFamily"] = select_first_non_null([
        safe_get(ced, "ModelFamily"), safe_get(ced, "ModelType"),
    ]) or ""

    # Token usage from CED
    usage_node = select_first_non_null([
        safe_get(ced, "Usage"), safe_get(ced, "TokenUsage"),
        safe_get(ced, "Tokens"), safe_get(audit_data, "Usage"),
    ])
    tokens_total: Any = None
    tokens_input: Any = None
    tokens_output: Any = None
    if usage_node and isinstance(usage_node, dict):
        tokens_total = to_num(select_first_non_null([
            safe_get(usage_node, "Total"), safe_get(usage_node, "TotalTokens"),
            safe_get(usage_node, "TokensTotal"),
        ]))
        tokens_input = to_num(select_first_non_null([
            safe_get(usage_node, "Input"), safe_get(usage_node, "Prompt"),
            safe_get(usage_node, "InputTokens"), safe_get(usage_node, "TokensInput"),
        ]))
        tokens_output = to_num(select_first_non_null([
            safe_get(usage_node, "Output"), safe_get(usage_node, "Completion"),
            safe_get(usage_node, "OutputTokens"), safe_get(usage_node, "TokensOutput"),
        ]))
    if not tokens_total and (tokens_input or tokens_output):
        try:
            tokens_total = (tokens_input or 0) + (tokens_output or 0)
        except Exception:
            pass
    base["TokensTotal"] = tokens_total if tokens_total is not None else ""
    base["TokensInput"] = tokens_input if tokens_input is not None else ""
    base["TokensOutput"] = tokens_output if tokens_output is not None else ""

    # Duration, outcome, conversation from CED
    duration_ms = to_num(select_first_non_null([
        safe_get(ced, "DurationMs"), safe_get(ced, "ElapsedMs"),
        safe_get(ced, "ProcessingTimeMs"), safe_get(ced, "LatencyMs"),
    ]))
    base["DurationMs"] = duration_ms if duration_ms is not None else ""

    outcome_status: Any = select_first_non_null([
        safe_get(ced, "OutcomeStatus"), safe_get(ced, "Outcome"),
        safe_get(ced, "Result"), safe_get(ced, "Status"),
    ])
    if isinstance(outcome_status, bool):
        outcome_status = "Success" if outcome_status else "Failure"
    base["OutcomeStatus"] = outcome_status or ""

    base["ConversationId"] = select_first_non_null([
        safe_get(ced, "ConversationId"), safe_get(ced, "ConversationID"),
        safe_get(ced, "SessionId"),
    ]) or ""

    turn_number = to_num(select_first_non_null([
        safe_get(ced, "TurnNumber"), safe_get(ced, "TurnIndex"),
        safe_get(ced, "MessageIndex"),
    ]))
    base["TurnNumber"] = turn_number if turn_number is not None else ""

    retry_count = to_num(select_first_non_null([
        safe_get(ced, "RetryCount"), safe_get(ced, "Retries"),
    ]))
    base["RetryCount"] = retry_count if retry_count is not None else ""

    base["ClientVersion"] = select_first_non_null([
        safe_get(ced, "ClientVersion"), safe_get(ced, "Version"), safe_get(ced, "Build"),
    ]) or ""
    base["ClientPlatform"] = select_first_non_null([
        safe_get(ced, "ClientPlatform"), safe_get(ced, "Platform"), safe_get(ced, "OS"),
    ]) or ""

    # MessageIds: semicolon-joined (matches M code's Text.Combine)
    base["MessageIds"] = ";".join(str(m) for m in message_ids) if message_ids else ""

    # ── Build rows with indexed array access ─────────────────────────────
    rows: list[dict] = []
    for i in range(row_count):
        row = dict(base)  # shallow copy of all 153 columns

        # Indexed array access — Contexts
        if i < len(contexts) and contexts[i]:
            row["Context_Id"] = safe_get(contexts[i], "Id") or ""
            row["Context_Type"] = safe_get(contexts[i], "Type") or ""
        else:
            row["Context_Id"] = ""
            row["Context_Type"] = ""

        # Messages
        if i < len(messages):
            msg = messages[i]
            if isinstance(msg, dict):
                row["Message_Id"] = safe_get(msg, "Id") or ""
                row["Message_isPrompt"] = bool_tf(safe_get(msg, "isPrompt"))
            else:
                row["Message_Id"] = str(msg) if msg is not None else ""
                row["Message_isPrompt"] = ""
        else:
            row["Message_Id"] = ""
            row["Message_isPrompt"] = ""

        # AccessedResources
        if i < len(resources) and resources[i]:
            res = resources[i]
            row["AccessedResource_Action"] = safe_get(res, "Action") or ""
            row["AccessedResource_PolicyDetails"] = to_json_if_object(safe_get(res, "PolicyDetails"))
            row["AccessedResource_SiteUrl"] = deid_resource(safe_get(res, "SiteUrl") or "")
            row["AccessedResource_Name"] = deid_file(safe_get(res, "Name") or "")
            row["AccessedResource_SensitivityLabel"] = safe_get(res, "SensitivityLabel") or ""
            row["AccessedResource_ResourceType"] = safe_get(res, "ResourceType") or ""
        else:
            row["AccessedResource_Action"] = ""
            row["AccessedResource_PolicyDetails"] = ""
            row["AccessedResource_SiteUrl"] = ""
            row["AccessedResource_Name"] = ""
            row["AccessedResource_SensitivityLabel"] = ""
            row["AccessedResource_ResourceType"] = ""

        # AISystemPlugin
        if i < len(plugins_raw) and plugins_raw[i]:
            row["AISystemPlugin_Id"] = safe_get(plugins_raw[i], "Id") or ""
            row["AISystemPlugin_Name"] = safe_get(plugins_raw[i], "Name") or ""
        else:
            row["AISystemPlugin_Id"] = ""
            row["AISystemPlugin_Name"] = ""

        # ModelTransparencyDetails
        if i < len(model_det_raw) and model_det_raw[i]:
            row["ModelTransparencyDetails_ModelName"] = safe_get(model_det_raw[i], "ModelName") or ""
        else:
            row["ModelTransparencyDetails_ModelName"] = ""

        # SensitivityLabel (from CED SensitivityLabels array)
        if i < len(sensitivity_labels):
            row["SensitivityLabel"] = str(sensitivity_labels[i]) if sensitivity_labels[i] is not None else ""

        # Context_Item — full mode: one item per row across all contexts
        if activity_type == "CopilotInteraction":
            found_item = None
            for ctx in contexts:
                if ctx:
                    items = get_array_fast(ctx, "Items")
                    if items and i < len(items):
                        found_item = items[i]
                        break
            row["Context_Item"] = to_json_if_object(found_item) if found_item else ""
        else:
            row["Context_Item"] = ""

        rows.append(row)

    return rows


# ═════════════════════════════════════════════════════════════════════════════
# ROUTER: Dispatch to Path A or Path B
# ═════════════════════════════════════════════════════════════════════════════

def explode_record(
    record: dict,
    prompt_filter: str | None = None,
) -> list[dict]:
    """
    Parse AuditData and route to appropriate explosion path.
    Returns list of flattened row dicts, or empty list on error.
    """
    audit_data_raw = record.get("AuditData", "")
    if not audit_data_raw or not isinstance(audit_data_raw, str) or not audit_data_raw.strip():
        return []

    try:
        audit_data = json_loads(audit_data_raw)
    except Exception:
        return []

    if not isinstance(audit_data, dict):
        return []

    ced = safe_get(audit_data, "CopilotEventData")
    if ced and isinstance(ced, dict):
        return explode_copilot_record(record, audit_data, ced, prompt_filter=prompt_filter)
    else:
        return explode_m365_record(record, audit_data)


# ═════════════════════════════════════════════════════════════════════════════
# HEADER — Fixed schema, no dynamic discovery needed
# ═════════════════════════════════════════════════════════════════════════════
# Output columns are exactly M365_UNIFIED_HEADER (153 columns in M code order).
# No schema discovery pass is needed because both Path A and Path B produce
# row dicts that contain exactly these keys.


# ═════════════════════════════════════════════════════════════════════════════
# CHUNK PROCESSOR (unit of parallel work)
# ═════════════════════════════════════════════════════════════════════════════

def _process_chunk(args: tuple) -> tuple[list[dict], int, int]:
    """
    Process a chunk of CSV rows → exploded row dicts.
    Returns (exploded_rows, input_count, error_count).
    """
    chunk, prompt_filter = args
    results: list[dict] = []
    errors = 0

    for record in chunk:
        try:
            rows = explode_record(record, prompt_filter=prompt_filter)
            results.extend(rows)
        except Exception:
            errors += 1

    return results, len(chunk), errors


# ═════════════════════════════════════════════════════════════════════════════
# MAIN EXPLOSION ORCHESTRATOR
# ═════════════════════════════════════════════════════════════════════════════

def run_explosion(
    input_csv: str,
    output_csv: str,
    prompt_filter: str | None = None,
    workers: int = 0,
    chunk_size: int = STREAMING_CHUNK_SIZE,
    quiet: bool = False,
) -> dict[str, Any]:
    """
    Main entry point: reads input CSV, explodes all records, writes output CSV.
    Uses multiprocessing for large files, single-process for small ones.

    Returns a stats dict with counts and timing.
    """
    if not os.path.isfile(input_csv):
        print(f"ERROR: Input file not found: {input_csv}", file=sys.stderr)
        sys.exit(1)

    if workers <= 0:
        workers = min(os.cpu_count() or 1, 8)

    t_start = time.perf_counter()
    stats = {
        "input_records": 0,
        "output_rows": 0,
        "errors": 0,
        "chunks_processed": 0,
    }

    if not quiet:
        print(f"Purview M365 Usage Bundle Explosion Processor v{SCRIPT_VERSION}")
        print(f"  JSON engine:    {_JSON_ENGINE}")
        print(f"  Input:          {input_csv}")
        print(f"  Output:         {output_csv}")
        print(f"  Prompt filter:  {prompt_filter or 'None'}")
        print(f"  Workers:        {workers}")
        print(f"  Chunk size:     {chunk_size}")
        print()

    # ── Phase 1: Fixed schema ─────────────────────────────────────────────
    final_header = list(M365_UNIFIED_HEADER)  # 153 columns in M code order
    if not quiet:
        print(f"Phase 1: Using fixed {len(final_header)}-column M code schema")

    # ── Phase 2: Process chunks ──────────────────────────────────────────
    if not quiet:
        print("Phase 2: Processing records...")

    # Streamed explode-and-write: the output header is fixed (final_header),
    # so exploded rows never need to be pooled for column discovery. Input is
    # read in bounded chunks and each chunk's exploded rows are written to the
    # output CSV as soon as the chunk completes, then released. Neither the full
    # input nor the full exploded row set is held in memory; peak usage stays a
    # small window of in-flight chunks regardless of input size or explosion ratio.
    if not quiet:
        print("Phase 3: Writing output CSV...")

    os.makedirs(os.path.dirname(os.path.abspath(output_csv)), exist_ok=True)
    output_rows = 0
    total_input = 0

    def _read_chunks(reader):
        current: list[dict] = []
        for row in reader:
            current.append(row)
            if len(current) >= chunk_size:
                yield current
                current = []
        if current:
            yield current

    with open(input_csv, "r", encoding="utf-8-sig", newline="") as f_in, \
         open(output_csv, "w", encoding="utf-8", newline="") as f_out:
        reader = csv.DictReader(f_in)
        writer = csv.DictWriter(f_out, fieldnames=final_header, extrasaction="ignore", lineterminator="\n")
        writer.writeheader()

        use_parallel = workers > 1

        if use_parallel:
            with ProcessPoolExecutor(max_workers=workers, initializer=_deid_init_worker, initargs=(_DEIDENTIFY,)) as executor:
                inflight: set = set()
                max_inflight = max(1, workers * 2)
                chunk_iter = _read_chunks(reader)
                exhausted = False
                while not exhausted or inflight:
                    while not exhausted and len(inflight) < max_inflight:
                        try:
                            chunk = next(chunk_iter)
                        except StopIteration:
                            exhausted = True
                            break
                        total_input += len(chunk)
                        inflight.add(executor.submit(_process_chunk, (chunk, prompt_filter)))
                    if not inflight:
                        break
                    done, inflight = wait(inflight, return_when=FIRST_COMPLETED)
                    for future in done:
                        try:
                            exploded, _in_count, err_count = future.result()
                            if exploded:
                                writer.writerows(exploded)
                                output_rows += len(exploded)
                            stats["errors"] += err_count
                            stats["chunks_processed"] += 1
                            if not quiet and stats["chunks_processed"] % 5 == 0:
                                print(f"    Chunks completed: {stats['chunks_processed']}")
                        except Exception as exc:
                            stats["errors"] += 1
                            if not quiet:
                                print(f"    Chunk failed: {exc}", file=sys.stderr)
        else:
            for chunk in _read_chunks(reader):
                total_input += len(chunk)
                exploded, _in_count, err_count = _process_chunk((chunk, prompt_filter))
                if exploded:
                    writer.writerows(exploded)
                    output_rows += len(exploded)
                stats["errors"] += err_count
                stats["chunks_processed"] += 1
                if not quiet and stats["chunks_processed"] % 5 == 0:
                    print(f"    Chunks completed: {stats['chunks_processed']}")

    stats["input_records"] = total_input
    stats["output_rows"] = output_rows

    if not quiet:
        print(f"  Loaded {total_input:,} input records")

    t_elapsed = time.perf_counter() - t_start

    # ── Summary ──────────────────────────────────────────────────────────
    if not quiet:
        print()
        print("=== EXPLOSION SUMMARY ===")
        print(f"  Input records:  {stats['input_records']:,}")
        print(f"  Output rows:    {stats['output_rows']:,}")
        if stats["output_rows"] > stats["input_records"] and stats["input_records"] > 0:
            ratio = round(stats["output_rows"] / stats["input_records"], 2)
            extra = stats["output_rows"] - stats["input_records"]
            print(f"  Expansion:      {ratio}x ({extra:,} additional rows from array explosion)")
        elif stats["output_rows"] == stats["input_records"]:
            print("  Expansion:      1:1 (no arrays exploded)")
        elif stats["input_records"] > 0:
            filtered = stats["input_records"] - stats["output_rows"]
            print(f"  Reduction:      {filtered:,} records filtered out")
        if stats["errors"] > 0:
            print(f"  Errors:         {stats['errors']:,} record(s) failed to process")
        print(f"  Columns:        {len(final_header):,}")
        print(f"  Elapsed:        {t_elapsed:.2f}s")
        if stats["output_rows"] > 0 and t_elapsed > 0:
            print(f"  Throughput:     {stats['output_rows'] / t_elapsed:,.0f} rows/sec")
        print(f"  Output file:    {output_csv}")
        print()

    return stats


# ═════════════════════════════════════════════════════════════════════════════
# ROLLUP ORCHESTRATOR (streaming — no exploded rows in memory)
# ═════════════════════════════════════════════════════════════════════════════

def run_rollup(
    input_csv: str | list[str],
    output_csv: str,
    prompt_filter: str | None = None,
    quiet: bool = False,
    session_stats_csv: str | None = None,
) -> dict[str, Any]:
    """
    Streaming rollup: read one or more CSVs row-by-row → parse AuditData → extract
    9 group keys + CreationTime + agent flag → accumulate into
    dict[GroupKey, RollupAccum] → write 13-column CSV.

    `input_csv` accepts a single path (PAX/PowerShell single-file export) or a
    list of paths (manual 4-pull export from Purview Audit). Output schema is
    identical either way — the same PBIT template ingests both modes.

    When `session_stats_csv` is provided, a parallel pass over CopilotEventData
    accumulates per-(UserId, CreationDate, AppHost) DISTINCTCOUNT(ThreadId) +
    prompt/response counts and writes an 8-column SessionStats CSV. This matches
    the AI in One `Sessions` measure unit (one thread = one session).

    No exploded row dicts are ever stored in memory.
    """
    if isinstance(input_csv, (str, Path)):
        input_paths: list[str] = [str(input_csv)]
    else:
        input_paths = [str(p) for p in input_csv]

    for p in input_paths:
        if not os.path.isfile(p):
            print(f"ERROR: Input file not found: {p}", file=sys.stderr)
            sys.exit(1)

    t_start = time.perf_counter()
    rollup: dict[GroupKey, RollupAccum] = {}
    sessions: dict[SessionKey, SessionAccum] = {} if session_stats_csv else {}
    track_sessions: bool = bool(session_stats_csv)
    stats: dict[str, Any] = {
        "input_records": 0,
        "virtual_exploded_event_count": 0,
        "output_rows": 0,
        "parse_errors": 0,
        "session_rows": 0,
        "session_threads": 0,
        "session_prompts": 0,
    }

    if not quiet:
        print(f"Purview M365 Usage Bundle Explosion Processor v{SCRIPT_VERSION} [ROLLUP MODE]")
        print(f"  JSON engine:    {_JSON_ENGINE}")
        if len(input_paths) == 1:
            print(f"  Input:          {input_paths[0]}")
        else:
            print(f"  Inputs ({len(input_paths)}):")
            for p in input_paths:
                print(f"                  {p}")
        print(f"  Output:         {output_csv}")
        if session_stats_csv:
            print(f"  Session stats:  {session_stats_csv}")
        print(f"  Prompt filter:  {prompt_filter or 'None'}")
        print()
        print("Processing records (streaming rollup)...")

    # ── Streaming read + accumulate (across one OR many input files) ─────
    for input_csv_path in input_paths:
        with open(input_csv_path, "r", encoding="utf-8-sig", newline="") as f:
            reader = csv.DictReader(f)
            for record in reader:
                stats["input_records"] += 1

                # Progress indicator
                if not quiet and stats["input_records"] % 500_000 == 0:
                    print(f"  {stats['input_records']:>12,} records processed, "
                          f"{len(rollup):,} groups...")

                # Parse AuditData JSON
                audit_data_raw = record.get("AuditData", "")
                if not audit_data_raw or not isinstance(audit_data_raw, str) or not audit_data_raw.strip():
                    stats["parse_errors"] += 1
                    continue
                try:
                    audit_data = json_loads(audit_data_raw)
                except Exception:
                    stats["parse_errors"] += 1
                    continue
                if not isinstance(audit_data, dict):
                    stats["parse_errors"] += 1
                    continue

                ced = safe_get(audit_data, "CopilotEventData")
                if ced and not isinstance(ced, dict):
                    ced = None

                # Extract rollup keys (lightweight — no row dict built)
                result = _extract_rollup_keys(record, audit_data, ced, prompt_filter)
                if result is None:
                    continue  # filtered out by prompt_filter or non-human UPN

                (group_key, event_count, items_accessed_count,
                 creation_time, original_uid, is_agent) = result
                stats["virtual_exploded_event_count"] += event_count

                # Accumulate into rollup dict
                if group_key in rollup:
                    acc = rollup[group_key]
                    acc.event_count += event_count
                    acc.items_accessed_count += items_accessed_count
                    if is_agent:
                        acc.is_agent_interaction = True
                    if creation_time:
                        if not acc.min_creation_time or creation_time < acc.min_creation_time:
                            acc.min_creation_time = creation_time
                        if not acc.max_creation_time or creation_time > acc.max_creation_time:
                            acc.max_creation_time = creation_time
                else:
                    rollup[group_key] = RollupAccum(
                        event_count=event_count,
                        items_accessed=items_accessed_count,
                        min_ct=creation_time,
                        max_ct=creation_time,
                        original_uid=original_uid,
                        is_agent=is_agent,
                    )

                # ── SessionStats accumulation (AI in One parity) ───
                # Only records with a CopilotEventData payload contribute. Threads
                # without at least one user prompt are excluded (matches AI in One
                # `Message_isPrompt = TRUE` filter).
                if track_sessions and ced:
                    msgs = get_array_fast(ced, "Messages")
                    prompts_here = 0
                    responses_here = 0
                    for m in msgs:
                        ip = safe_get(m, "isPrompt")
                        if ip is True:
                            prompts_here += 1
                        elif ip is False:
                            responses_here += 1
                    thread_id = _norm_key_str(safe_get(ced, "ThreadId"))
                    # group_key layout: (uid_lower, creation_date, op, wl, sfe,
                    # app_host, agent_id, agent_name, context_type)
                    skey: SessionKey = (group_key[0], group_key[1], group_key[5])
                    sacc = sessions.get(skey)
                    if sacc is None:
                        sacc = SessionAccum(original_uid=original_uid)
                        sessions[skey] = sacc
                    sacc.prompt_count += prompts_here
                    sacc.response_count += responses_here
                    if is_agent:
                        sacc.agent_prompt_count += prompts_here  # exact chat/agent split
                    if thread_id and prompts_here > 0:
                        sacc.thread_ids.add(thread_id)
                        if is_agent:
                            sacc.agent_thread_ids.add(thread_id)
                        stats["session_prompts"] += prompts_here

    # ── Write rollup output CSV ──────────────────────────────────────────
    stats["output_rows"] = len(rollup)

    if not quiet:
        print(f"  {stats['input_records']:>12,} records processed (done)")
        print(f"  Writing {stats['output_rows']:,} rollup rows...")

    os.makedirs(os.path.dirname(os.path.abspath(output_csv)), exist_ok=True)
    with open(output_csv, "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f, lineterminator="\n")
        writer.writerow(ROLLUP_HEADER)
        for (uid_lower, cdate, op, wl, sfe, ah, agent_id, agent_name, ctx_type), acc in rollup.items():
            writer.writerow([
                deid_upn(acc.original_user_id),  # output original casing, NOT lowered key
                cdate,
                op,
                wl,
                sfe,
                ah,
                acc.event_count,
                acc.items_accessed_count,
                acc.min_creation_time,   # CreationTime = MIN
                acc.max_creation_time,   # MaxCreationTime = MAX
                agent_id,
                agent_name,
                ctx_type,
                "TRUE" if acc.is_agent_interaction else "FALSE",
            ])

    # ── SessionStats CSV (AI in One parity) ─────────────────────
    if track_sessions:
        os.makedirs(os.path.dirname(os.path.abspath(session_stats_csv)), exist_ok=True)
        with open(session_stats_csv, "w", encoding="utf-8", newline="") as f:
            writer = csv.writer(f, lineterminator="\n")
            writer.writerow(SESSIONSTATS_HEADER)
            for (uid_lower, cdate, ah), sacc in sessions.items():
                session_count = len(sacc.thread_ids)
                if session_count == 0 and sacc.prompt_count == 0:
                    continue  # no signal — skip
                writer.writerow([
                    deid_upn(sacc.original_user_id),
                    cdate,
                    ah,
                    session_count,
                    sacc.prompt_count,
                    sacc.agent_prompt_count,
                    sacc.response_count,
                    len(sacc.agent_thread_ids),
                ])
                stats["session_rows"] += 1
                stats["session_threads"] += session_count

    t_elapsed = time.perf_counter() - t_start

    # ── Summary report ───────────────────────────────────────────────────
    if not quiet:
        pct = 0.0
        if stats["virtual_exploded_event_count"] > 0:
            pct = (1 - stats["output_rows"] / stats["virtual_exploded_event_count"]) * 100
        print()
        print("=== ROLLUP SUMMARY ===")
        print(f"  Input records:              {stats['input_records']:>14,}")
        print(f"  Virtual exploded events:    {stats['virtual_exploded_event_count']:>14,}")
        print(f"  Rollup output rows:         {stats['output_rows']:>14,}")
        print(f"  Row reduction:              {pct:>13.1f}%"
              f"  ({stats['virtual_exploded_event_count']:,} -> {stats['output_rows']:,})")
        if stats["parse_errors"] > 0:
            print(f"  Parse errors:               {stats['parse_errors']:>14,}")
        print(f"  Columns:                    {len(ROLLUP_HEADER):>14}")
        print(f"  Elapsed:                    {t_elapsed:>13.2f}s")
        if stats["input_records"] > 0 and t_elapsed > 0:
            print(f"  Throughput:                 {stats['input_records'] / t_elapsed:>12,.0f} input records/sec")
        print(f"  Output file:                {output_csv}")
        if track_sessions:
            print()
            print("=== SESSIONSTATS SUMMARY (AI in One parity) ===")
            print(f"  SessionStats rows:          {stats['session_rows']:>14,}")
            print(f"  Distinct Copilot sessions:  {stats['session_threads']:>14,}")
            print(f"  User prompts counted:       {stats['session_prompts']:>14,}")
            print(f"  Output file:                {session_stats_csv}")
        print()

    return stats


# ═════════════════════════════════════════════════════════════════════════════
# RECONCILIATION (sample-based validation of rollup correctness)
# ═════════════════════════════════════════════════════════════════════════════

def run_reconcile(
    input_csv: str,
    prompt_filter: str | None = None,
    sample_size: int = RECONCILE_SAMPLE_SIZE,
    quiet: bool = False,
) -> bool:
    """
    Sample-based reconciliation: read a sample of records, run both rollup-key
    extraction and full event-level explosion, compare total and filtered counts.

    Returns True if all checks pass, False otherwise.
    """
    if not os.path.isfile(input_csv):
        print(f"ERROR: Input file not found: {input_csv}", file=sys.stderr)
        return False

    if not quiet:
        print(f"\n=== RECONCILIATION CHECK (sample {sample_size:,} records) ===\n")

    # ── Read sample ──────────────────────────────────────────────────────
    all_records: list[dict] = []
    with open(input_csv, "r", encoding="utf-8-sig", newline="") as f:
        reader = csv.DictReader(f)
        for record in reader:
            all_records.append(record)

    if len(all_records) > sample_size:
        sample = random.sample(all_records, sample_size)
    else:
        sample = all_records
        sample_size = len(sample)

    if not quiet:
        print(f"  Total input records: {len(all_records):,}")
        print(f"  Sample size:         {sample_size:,}")

    # ── Run event-level explosion on sample ──────────────────────────────
    event_rows: list[dict] = []
    event_errors = 0
    for record in sample:
        try:
            rows = explode_record(record, prompt_filter=prompt_filter)
            # Apply same non-human UPN filter as rollup path so totals reconcile
            rows = [r for r in rows if _is_human_upn(r.get("UserId", ""))]
            event_rows.extend(rows)
        except Exception:
            event_errors += 1

    # ── Run rollup-key extraction on same sample ─────────────────────────
    rollup_sample: dict[GroupKey, RollupAccum] = {}
    rollup_errors = 0
    for record in sample:
        audit_data_raw = record.get("AuditData", "")
        if not audit_data_raw or not isinstance(audit_data_raw, str) or not audit_data_raw.strip():
            rollup_errors += 1
            continue
        try:
            audit_data = json_loads(audit_data_raw)
        except Exception:
            rollup_errors += 1
            continue
        if not isinstance(audit_data, dict):
            rollup_errors += 1
            continue

        ced = safe_get(audit_data, "CopilotEventData")
        if ced and not isinstance(ced, dict):
            ced = None

        result = _extract_rollup_keys(record, audit_data, ced, prompt_filter)
        if result is None:
            continue
        (group_key, event_count, items_accessed_count,
         creation_time, original_uid, is_agent) = result

        if group_key in rollup_sample:
            acc = rollup_sample[group_key]
            acc.event_count += event_count
            acc.items_accessed_count += items_accessed_count
            if is_agent:
                acc.is_agent_interaction = True
            if creation_time:
                if not acc.min_creation_time or creation_time < acc.min_creation_time:
                    acc.min_creation_time = creation_time
                if not acc.max_creation_time or creation_time > acc.max_creation_time:
                    acc.max_creation_time = creation_time
        else:
            rollup_sample[group_key] = RollupAccum(
                event_count=event_count,
                items_accessed=items_accessed_count,
                min_ct=creation_time,
                max_ct=creation_time,
                original_uid=original_uid,
                is_agent=is_agent,
            )

    # ── Compare totals ───────────────────────────────────────────────────
    rollup_total = sum(acc.event_count for acc in rollup_sample.values())
    event_total = len(event_rows)
    all_pass = True

    def _check(label: str, rollup_val: Any, event_val: Any) -> bool:
        nonlocal all_pass
        match = rollup_val == event_val
        symbol = "PASS" if match else "FAIL"
        if not quiet:
            print(f"  {label}")
            print(f"    Rollup: {rollup_val}   Event-level: {event_val}   [{symbol}]")
        if not match:
            all_pass = False
        return match

    _check("Total event count (SUM(EventCount) vs COUNTROWS)",
           rollup_total, event_total)

    # ── Filter-specific checks ───────────────────────────────────────────
    # Helper: count event-level rows matching a filter
    def _ev_count(**filters: str | set) -> int:
        count = 0
        for row in event_rows:
            match = True
            for col, val in filters.items():
                row_val = row.get(col, "")
                if isinstance(val, set):
                    if row_val.lower() not in val:
                        match = False
                        break
                else:
                    if row_val != val:
                        match = False
                        break
            if match:
                count += 1
        return count

    # Helper: sum EventCount from rollup for matching groups
    def _ru_count(**filters: str | set) -> int:
        total = 0
        for (uid_l, cdate, op, wl, sfe, ah, agent_id, agent_name, ctx_type), acc in rollup_sample.items():
            match = True
            key_map = {"Operation": op, "Workload": wl,
                       "SourceFileExtension": sfe, "AppHost": ah,
                       "AgentId": agent_id, "AgentName": agent_name,
                       "ContextType": ctx_type}
            for col, val in filters.items():
                key_val = key_map.get(col, "")
                if isinstance(val, set):
                    if key_val.lower() not in val:
                        match = False
                        break
                else:
                    if key_val != val:
                        match = False
                        break
            if match:
                total += acc.event_count
        return total

    # Check 1: Teams MessageSent
    _check("Teams MessageSent (Workload=MicrosoftTeams, Operation=MessageSent)",
           _ru_count(Workload="MicrosoftTeams", Operation="MessageSent"),
           _ev_count(Workload="MicrosoftTeams", Operation="MessageSent"))

    # Check 2: Exchange Send
    _check("Exchange Send (Workload=Exchange, Operation=Send)",
           _ru_count(Workload="Exchange", Operation="Send"),
           _ev_count(Workload="Exchange", Operation="Send"))

    # Check 3: CopilotInteraction + AppHost=Teams
    _check("Copilot Teams (Operation=CopilotInteraction, AppHost=Teams)",
           _ru_count(Operation="CopilotInteraction", AppHost="Teams"),
           _ev_count(Operation="CopilotInteraction", AppHost="Teams"))

    # Check 4: Excel FileAccessed
    _check("Excel FileAccessed (Operation=FileAccessed, SourceFileExtension in xlsx/xls/xlsm/csv)",
           _ru_count(Operation="FileAccessed", SourceFileExtension={"xlsx", "xls", "xlsm", "csv"}),
           _ev_count(Operation="FileAccessed", SourceFileExtension={"xlsx", "xls", "xlsm", "csv"}))

    # ── Temporal checks ──────────────────────────────────────────────────
    rollup_min_ct = min((acc.min_creation_time for acc in rollup_sample.values() if acc.min_creation_time), default="")
    rollup_max_ct = max((acc.max_creation_time for acc in rollup_sample.values() if acc.max_creation_time), default="")
    event_times = [r.get("CreationTime", "") for r in event_rows if r.get("CreationTime")]
    event_min_ct = min(event_times) if event_times else ""
    event_max_ct = max(event_times) if event_times else ""

    _check("MIN(CreationTime)", rollup_min_ct, event_min_ct)
    _check("MAX(CreationTime)", rollup_max_ct, event_max_ct)

    if not quiet:
        print()
        reduction_pct = 0.0
        if event_total > 0:
            reduction_pct = (1 - len(rollup_sample) / event_total) * 100
        print(f"  Event-level rows: {event_total:,}  ->  Rollup groups: {len(rollup_sample):,}"
              f"  ({reduction_pct:.1f}% reduction)")
        print(f"  Overall: {'ALL CHECKS PASSED' if all_pass else 'SOME CHECKS FAILED'}")
        print()

    return all_pass


# ═════════════════════════════════════════════════════════════════════════════
# USERSTATS & SESSION COHORT WRITER
# ═════════════════════════════════════════════════════════════════════════════

def write_userstats_files(
    aggregated_csv_path: str | Path,
    userstats_csv_path: str | Path,
    session_csv_path: str | Path,
    quiet: bool,
    session_stats_csv_path: str | Path | None = None,
) -> tuple[int, int]:
    """
    Read the just-written aggregated rollup CSV and produce two additional files:
      *_UserStats.csv     — one row per unique UserId with pre-computed metrics
      *_SessionCohort.csv — one row per (UserId, AppColumn) with session cohort label

    When `session_stats_csv_path` is provided, the CECopilotPercentile_*
    columns are computed from per-user PromptCount (human interactions) instead of
    raw audit-event counts. This matches the AI in One semantics and prevents
    service-principal / plugin-chain inflation from skewing the CE Quadrant.

    Returns (user_count, session_cohort_row_count).
    """
    agg_path = Path(aggregated_csv_path)
    if not agg_path.is_file():
        if not quiet:
            print(f"[UserStats] WARNING: Aggregated CSV not found: {agg_path} — skipping.",
                  file=sys.stderr)
        return 0, 0

    userstats_path = Path(userstats_csv_path)
    session_path = Path(session_csv_path)

    t_start = time.perf_counter()

    # ── Per-user accumulators ────────────────────────────────────────────
    uid_original: dict[str, str] = {}          # uid_lower → first-seen casing
    cop_ec: dict[str, int] = defaultdict(int)
    m365_ec: dict[str, int] = defaultdict(int)
    ex_cop_ec: dict[str, int] = defaultdict(int)
    ex_m365_ec: dict[str, int] = defaultdict(int)

    t_days: dict[str, set[str]] = defaultdict(set)
    o_days: dict[str, set[str]] = defaultdict(set)
    w_days: dict[str, set[str]] = defaultdict(set)
    x_days: dict[str, set[str]] = defaultdict(set)
    p_days: dict[str, set[str]] = defaultdict(set)

    t_ec: dict[str, int] = defaultdict(int)
    o_ec: dict[str, int] = defaultdict(int)
    off_ec: dict[str, int] = defaultdict(int)

    # ── DAX-aligned per-user raw activity counts, computed per window.
    # Three windows (L30, L60, Full) feed both the LP <App> Weighted measures and the
    # CE percentile ranks. Each is a dict keyed by window code → {uid: count}.
    def _wbuckets() -> dict[str, dict[str, int]]:
        return {w: defaultdict(int) for w in RANK_WINDOWS}
    teams_raw = _wbuckets()
    outlook_raw = _wbuckets()
    word_raw = _wbuckets()
    excel_raw = _wbuckets()
    ppt_raw = _wbuckets()
    copilot_chat_raw = _wbuckets()        # Operation = "CopilotInteraction" (LP)
    ce_copilot_raw = _wbuckets()          # broad: Workload="Copilot" OR Op contains "CopilotInteraction" (CE)

    session_ops: dict[tuple[str, str], set[str]] = defaultdict(set)

    # Track every distinct CreationDate seen in the rollup so we can
    # derive the data-window span (max - min + 1 calendar days) and
    # normalize the engagement segmentation to active-days-per-week.
    all_dates: set[str] = set()

    # ── Pass 1 — determine the trailing-window cutoffs ──────────
    # Scan CreationDate only to find the most-recent date in the rollup. Cutoffs
    # are inclusive lower bounds; a row qualifies for window W iff date_key >= cutoff[W].
    # The "Full" window has no cutoff and always qualifies.
    _d_max_str = ""
    with open(agg_path, "r", encoding="utf-8-sig", newline="") as _f:
        _r = csv.DictReader(_f)
        for _row in _r:
            _dk = (_row.get("CreationDate", "") or "")[:10]
            if _dk and _dk > _d_max_str:
                _d_max_str = _dk
    if _d_max_str:
        try:
            _d_max = date.fromisoformat(_d_max_str)
            cutoff_l30 = (_d_max - timedelta(days=29)).isoformat()
            cutoff_l60 = (_d_max - timedelta(days=59)).isoformat()
        except ValueError:
            # Bad date — fall back to "everything qualifies"
            cutoff_l30 = ""
            cutoff_l60 = ""
    else:
        # No data — sentinel that nothing qualifies for L30/L60 (Full still does)
        cutoff_l30 = "9999-12-31"
        cutoff_l60 = "9999-12-31"
    if not quiet:
        print(f"[UserStats] Window cutoffs: L30 >= {cutoff_l30 or '(all)'}, "
              f"L60 >= {cutoff_l60 or '(all)'}, max date = {_d_max_str or '(none)'}")

    # ── Stream through aggregated CSV ────────────────────────────────────
    row_count = 0
    with open(agg_path, "r", encoding="utf-8-sig", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            row_count += 1

            user_id = row.get("UserId", "")
            uid_lower = user_id.lower()
            if uid_lower not in uid_original:
                uid_original[uid_lower] = user_id

            date_key = row.get("CreationDate", "")[:10]   # YYYY-MM-DD
            op = row.get("Operation", "")
            wl = row.get("Workload", "")
            ext = (row.get("SourceFileExtension", "") or "").lower()
            app_host = (row.get("AppHost", "") or "").lower()

            if date_key:
                all_dates.add(date_key)

            try:
                event_count = int(row.get("EventCount", "1") or "1")
            except (ValueError, TypeError):
                event_count = 1

            copilot = is_copilot(op, wl)
            excel_file = is_excel_file_op(ext, op)

            # Core event counts
            if copilot:
                cop_ec[uid_lower] += event_count
            else:
                m365_ec[uid_lower] += event_count

            # ExCopEC: Copilot interactions in Excel (via AppHost); ExM365EC: Excel file ops by non-Copilot
            if copilot and app_host == "excel":
                ex_cop_ec[uid_lower] += 1        # row count, not EventCount
            if excel_file and not copilot:
                ex_m365_ec[uid_lower] += 1       # row count, not EventCount

            # Active days (distinct CreationDate values)
            if wl == "MicrosoftTeams" and op in TEAMS_OPS:
                t_days[uid_lower].add(date_key)
            if wl == "Exchange" and op in OUTLOOK_OPS:
                o_days[uid_lower].add(date_key)
            if ext in WORD_EXTS and op in FILE_OPS:
                w_days[uid_lower].add(date_key)
            if ext in EXCEL_EXTS and op in FILE_OPS:
                x_days[uid_lower].add(date_key)
            if ext in PPT_EXTS and op in FILE_OPS:
                p_days[uid_lower].add(date_key)

            # Activity event counts
            if wl == "MicrosoftTeams" and op in TEAMS_OPS:
                t_ec[uid_lower] += event_count
            if wl == "Exchange" and op in OUTLOOK_OPS:
                o_ec[uid_lower] += event_count
            if ext in OFFICE_EXTS and op in FILE_OPS:
                off_ec[uid_lower] += event_count

            # ── DAX-aligned raw counts, accumulated per window.
            # Helper closure: write to Full always; to L60/L30 only if the row's
            # date_key satisfies the trailing-window cutoff.
            def _bump(buckets: dict[str, dict[str, int]], n: int) -> None:
                buckets["Full"][uid_lower] += n
                if date_key >= cutoff_l60:
                    buckets["L60"][uid_lower] += n
                if date_key >= cutoff_l30:
                    buckets["L30"][uid_lower] += n

            if wl == "MicrosoftTeams" and op in DAX_TEAMS_OPS:
                _bump(teams_raw, event_count)
            if wl == "Exchange" and op in DAX_OUTLOOK_OPS:
                _bump(outlook_raw, event_count)
            if op in DAX_FILE_OPS:
                if ext in WORD_EXTS:
                    _bump(word_raw, event_count)
                elif ext in EXCEL_EXTS:
                    _bump(excel_raw, event_count)
                elif ext in PPT_EXTS:
                    _bump(ppt_raw, event_count)
            if op == "CopilotInteraction":
                _bump(copilot_chat_raw, event_count)
            # CE Copilot Percentile filter: Workload="Copilot" OR Operation contains "CopilotInteraction"
            if wl == "Copilot" or "CopilotInteraction" in op:
                _bump(ce_copilot_raw, event_count)

            # Session cohort: distinct active dates per (user, app)
            app = app_column(ext, op, wl)
            if app != "M365 All Apps":
                session_ops[(uid_lower, app)].add(date_key)

    if row_count == 0:
        if not quiet:
            print("[UserStats] Aggregated CSV has 0 rows — skipping.")
        return 0, 0

    # ── Data-window span ────────────────────────────────────────────────
    # Calendar-day span between the earliest and latest CreationDate in the
    # rollup, inclusive. Used to normalize per-app engagement segments to
    # active-days-per-week, so labels mean the same thing whether the pull
    # covers 8 days, 30 days, or 6 months.
    if all_dates:
        try:
            d_min = min(all_dates)
            d_max = max(all_dates)
            window_days = (
                date.fromisoformat(d_max) - date.fromisoformat(d_min)
            ).days + 1
        except ValueError:
            window_days = max(len(all_dates), 1)
    else:
        window_days = 1
    if not quiet:
        print(f"[UserStats] Data window: {window_days} calendar day(s) "
              f"({d_min if all_dates else '?'} -> {d_max if all_dates else '?'})")

    # ── Percentile thresholds ────────────────────────────────────────────
    all_uids = sorted(uid_original.keys())
    total_users = len(all_uids)

    cop_vals = [cop_ec.get(u, 0) for u in all_uids]
    m365_vals = [m365_ec.get(u, 0) for u in all_uids]
    ex_cop_vals = [ex_cop_ec.get(u, 0) for u in all_uids]
    ex_m365_vals = [ex_m365_ec.get(u, 0) for u in all_uids]

    cop_p90 = percentile_inc(cop_vals, 0.90)
    cop_p75 = percentile_inc(cop_vals, 0.75)
    cop_p50 = percentile_inc(cop_vals, 0.50)

    m365_p90 = percentile_inc(m365_vals, 0.90)
    m365_p75 = percentile_inc(m365_vals, 0.75)
    m365_p50 = percentile_inc(m365_vals, 0.50)

    exc_p90 = percentile_inc(ex_cop_vals, 0.90)
    exc_p75 = percentile_inc(ex_cop_vals, 0.75)
    exc_p50 = percentile_inc(ex_cop_vals, 0.50)

    exm_p90 = percentile_inc(ex_m365_vals, 0.90)
    exm_p75 = percentile_inc(ex_m365_vals, 0.75)
    exm_p50 = percentile_inc(ex_m365_vals, 0.50)

    # ── Ranks ────────────────────────────────────────────────────────────
    # Copilot rank: computed only among Copilot users so the range maps to [0, 1]
    # within that group. Non-Copilot users are hardcoded to 0.0 downstream.
    copilot_uids = [u for u in all_uids if cop_ec.get(u, 0) > 0]
    copilot_user_count = len(copilot_uids)
    cop_rank = compute_ranks({u: cop_ec.get(u, 0) for u in copilot_uids})
    m365_rank = compute_ranks({u: m365_ec.get(u, 0) for u in all_uids})

    # ── CE percentile ranks per window (integer 0–100, match DAX exactly) ──
    # DAX formula: ROUND( COUNTROWS(users with score <= mine) / COUNTROWS(users with score > 0) * 100 , 0)
    # Users with score 0 / no activity → BLANK (we emit empty string).
    def _ce_rank_pct(scores: dict[str, int]) -> dict[str, str]:
        """Return DAX-exact CE percentile rank per user, as a string ('' for BLANK)."""
        positives = sorted(v for v in scores.values() if v > 0)
        total = len(positives)
        out: dict[str, str] = {}
        if total == 0:
            return {u: "" for u in scores}
        for u, v in scores.items():
            if v <= 0:
                out[u] = ""
            else:
                below = bisect.bisect_right(positives, v)
                out[u] = str(round(below / total * 100))
        return out

    # M365 All Apps raw is derived per window (sum of 5 app raws). LP has no M365-AllApps
    # measure, so we only compute the rank — not stored as a column.
    m365_all_apps_raw = {
        w: {
            u: teams_raw[w].get(u, 0) + outlook_raw[w].get(u, 0) + word_raw[w].get(u, 0)
               + excel_raw[w].get(u, 0) + ppt_raw[w].get(u, 0)
            for u in all_uids
        }
        for w in RANK_WINDOWS
    }
    ce_rank_teams   = {w: _ce_rank_pct({u: teams_raw[w].get(u, 0)   for u in all_uids}) for w in RANK_WINDOWS}
    ce_rank_outlook = {w: _ce_rank_pct({u: outlook_raw[w].get(u, 0) for u in all_uids}) for w in RANK_WINDOWS}
    ce_rank_word    = {w: _ce_rank_pct({u: word_raw[w].get(u, 0)    for u in all_uids}) for w in RANK_WINDOWS}
    ce_rank_excel   = {w: _ce_rank_pct({u: excel_raw[w].get(u, 0)   for u in all_uids}) for w in RANK_WINDOWS}
    ce_rank_ppt     = {w: _ce_rank_pct({u: ppt_raw[w].get(u, 0)     for u in all_uids}) for w in RANK_WINDOWS}
    ce_rank_all     = {w: _ce_rank_pct(m365_all_apps_raw[w])                              for w in RANK_WINDOWS}

    # ── CE Copilot Percentile based on PROMPT COUNT (human interactions) ──
    # Read the SessionStats CSV (if produced by run_rollup) and tally PromptCount per
    # user per window. This is the AI in One semantics: one count per `isPrompt=TRUE`
    # message — resistant to AI-response fanout, plugin chains, retries, and most
    # service-principal noise. Falls back to audit-event tally if SessionStats is
    # missing (older script invocations).
    prompt_raw = _wbuckets()
    if session_stats_csv_path:
        _ss = Path(session_stats_csv_path)
        if _ss.is_file():
            with open(_ss, "r", encoding="utf-8-sig", newline="") as _f:
                _r = csv.DictReader(_f)
                for _row in _r:
                    _uid = (_row.get("UserId") or "").strip().lower()
                    if not _uid:
                        continue
                    _date_key = (_row.get("CreationDate") or "")[:10]
                    try:
                        _pc = int(_row.get("PromptCount") or 0)
                    except ValueError:
                        _pc = 0
                    if _pc <= 0:
                        continue
                    prompt_raw["Full"][_uid] += _pc
                    if cutoff_l60 and _date_key >= cutoff_l60:
                        prompt_raw["L60"][_uid] += _pc
                    if cutoff_l30 and _date_key >= cutoff_l30:
                        prompt_raw["L30"][_uid] += _pc
            if not quiet:
                _tot = sum(prompt_raw["Full"].values())
                print(f"[UserStats] CE Copilot Percentile source: PromptCount "
                      f"({_tot:,} prompts across {len(prompt_raw['Full']):,} users)")
        else:
            if not quiet:
                print(f"[UserStats] WARNING: SessionStats CSV not found: {_ss} — "
                      f"falling back to audit-event count for CE Copilot Percentile.",
                      file=sys.stderr)
            prompt_raw = ce_copilot_raw  # fallback to legacy event-based percentile
    else:
        prompt_raw = ce_copilot_raw  # legacy mode (script invoked without SessionStats)

    ce_copilot_pct  = {w: _ce_rank_pct({u: prompt_raw[w].get(u, 0) for u in all_uids}) for w in RANK_WINDOWS}

    # ── Write *_UserStats.csv ────────────────────────────────────────────
    with open(userstats_path, "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f, lineterminator="\n")
        writer.writerow(USERSTATS_HEADER)

        for uid in all_uids:
            c_ec = cop_ec.get(uid, 0)
            m_ec = m365_ec.get(uid, 0)
            exc_ec = ex_cop_ec.get(uid, 0)
            exm_ec = ex_m365_ec.get(uid, 0)

            is_cop_user = "Copilot User" if c_ec > 0 else "Non-Copilot User"
            cop_tier = tier_fn(c_ec, cop_p90, cop_p75, cop_p50, zero_is_bottom=True)
            m365_tier = tier_fn(m_ec, m365_p90, m365_p75, m365_p50, zero_is_bottom=False)
            priority = priority_fn(m365_tier, cop_tier)

            ex_m365_tier = tier_fn(exm_ec, exm_p90, exm_p75, exm_p50, zero_is_bottom=False)
            ex_cop_tier = tier_fn(exc_ec, exc_p90, exc_p75, exc_p50, zero_is_bottom=False)
            excel_pri = priority_fn(ex_m365_tier, ex_cop_tier)

            cop_rank_val = 0.0 if c_ec == 0 else cop_rank[uid] / max(copilot_user_count, 1)
            m365_rank_val = m365_rank[uid] / total_users

            td = len(t_days.get(uid, set()))
            od = len(o_days.get(uid, set()))
            wd = len(w_days.get(uid, set()))
            xd = len(x_days.get(uid, set()))
            pd_ = len(p_days.get(uid, set()))

            t_act = t_ec.get(uid, 0)
            o_act = o_ec.get(uid, 0)
            off_act = off_ec.get(uid, 0)

            t_seg = "0. No Usage" if td == 0 else seg_fn(td, window_days)
            o_seg = "0. No Usage" if od == 0 else seg_fn(od, window_days)
            w_seg = "0. No Usage" if wd == 0 else seg_fn(wd, window_days)
            x_seg = "0. No Usage" if xd == 0 else seg_fn(xd, window_days)
            p_seg = "0. No Usage" if pd_ == 0 else seg_fn(pd_, window_days)

            office_days = wd + xd + pd_
            off_seg = "0. No Usage" if office_days == 0 else seg_fn(office_days, window_days)

            overall_days = len(
                t_days.get(uid, set()) | o_days.get(uid, set()) |
                w_days.get(uid, set()) | x_days.get(uid, set()) |
                p_days.get(uid, set())
            )
            overall_seg = "0. No Usage" if overall_days == 0 else seg_fn(overall_days, window_days)

            writer.writerow([
                uid_original[uid],
                c_ec, m_ec, exc_ec, exm_ec,
                is_cop_user, cop_tier, m365_tier,
                priority, excel_pri,
                f"{cop_rank_val:.6f}", f"{m365_rank_val:.6f}",
                td, od, wd, xd, pd_,
                t_act, o_act, off_act,
                t_seg, o_seg, w_seg, x_seg, p_seg,
                off_seg, overall_seg,
                # Precomputed raw + CE rank columns per window (order must
                # match USERSTATS_HEADER: 6 raws × 3 windows, then 7 ranks × 3 windows)
                teams_raw["L30"].get(uid, 0),   teams_raw["L60"].get(uid, 0),   teams_raw["Full"].get(uid, 0),
                outlook_raw["L30"].get(uid, 0), outlook_raw["L60"].get(uid, 0), outlook_raw["Full"].get(uid, 0),
                word_raw["L30"].get(uid, 0),    word_raw["L60"].get(uid, 0),    word_raw["Full"].get(uid, 0),
                excel_raw["L30"].get(uid, 0),   excel_raw["L60"].get(uid, 0),   excel_raw["Full"].get(uid, 0),
                ppt_raw["L30"].get(uid, 0),     ppt_raw["L60"].get(uid, 0),     ppt_raw["Full"].get(uid, 0),
                copilot_chat_raw["L30"].get(uid, 0), copilot_chat_raw["L60"].get(uid, 0), copilot_chat_raw["Full"].get(uid, 0),
                ce_rank_teams["L30"][uid],     ce_rank_teams["L60"][uid],     ce_rank_teams["Full"][uid],
                ce_rank_outlook["L30"][uid],   ce_rank_outlook["L60"][uid],   ce_rank_outlook["Full"][uid],
                ce_rank_word["L30"][uid],      ce_rank_word["L60"][uid],      ce_rank_word["Full"][uid],
                ce_rank_excel["L30"][uid],     ce_rank_excel["L60"][uid],     ce_rank_excel["Full"][uid],
                ce_rank_ppt["L30"][uid],       ce_rank_ppt["L60"][uid],       ce_rank_ppt["Full"][uid],
                ce_rank_all["L30"][uid],       ce_rank_all["L60"][uid],       ce_rank_all["Full"][uid],
                ce_copilot_pct["L30"][uid],    ce_copilot_pct["L60"][uid],    ce_copilot_pct["Full"][uid],
            ])

    # ── Write *_SessionCohort.csv ────────────────────────────────────────
    session_count = 0
    with open(session_path, "w", encoding="utf-8", newline="") as f:
        writer = csv.writer(f, lineterminator="\n")
        writer.writerow(SESSIONCOHORT_HEADER)

        for (uid, app), ops in sorted(session_ops.items()):
            n = len(ops)
            if n == 0:
                continue
            if n <= 5:
                cohort = "1-5 sessions"
            elif n <= 10:
                cohort = "6-10 sessions"
            elif n <= 20:
                cohort = "11-20 sessions"
            elif n <= 40:
                cohort = "21-40 sessions"
            elif n <= 60:
                cohort = "41-60 sessions"
            elif n <= 80:
                cohort = "61-80 sessions"
            else:
                cohort = "81+ sessions"
            writer.writerow([uid_original[uid], app, cohort])
            session_count += 1

    t_elapsed = time.perf_counter() - t_start

    if not quiet:
        print(f"[UserStats]     {total_users:,} users \u2192 {userstats_path.name} "
              f"({len(USERSTATS_HEADER)} columns)")
        print(f"[SessionCohort] {session_count:,} (user, app) pairs \u2192 {session_path.name}")
        print(f"[UserStats]     Elapsed: {t_elapsed:.2f}s")

    return total_users, session_count


# ═════════════════════════════════════════════════════════════════════════════
# CLI ENTRY POINT
# ═════════════════════════════════════════════════════════════════════════════

def main() -> None:
    parser = argparse.ArgumentParser(
        prog="purview_m365_processor",
        description=(
            f"Purview M365 Usage Bundle Processor v{SCRIPT_VERSION}\n"
            "Pre-computes the M365 Usage rollup + UserStats + SessionCohort CSVs\n"
            "consumed by the Power BI template. Accepts either layout:\n"
            "  (A) ONE PAX / PowerShell export ............ use --pax\n"
            "  (B) FOUR manual Purview Audit exports ...... use --teams --outlook --files --copilot\n"
            "Output schema is IDENTICAL for both layouts — same PBIT template ingests either."
        ),
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""\
EXAMPLES
========

(A) Single PAX export (PAX tool or PowerShell Search-UnifiedAuditLog):

    python %(prog)s --pax Purview_Export.csv

    python %(prog)s --pax Purview_Export.csv --output-dir ./output


(B) Manual 4-pull export from Purview Audit (validated chip strategy):

      Teams   (7d):  MessageSent, MessageRead, ChatCreated, TeamsSessionStarted,
                     MeetingParticipantDetail
      Outlook (30d): MailItemsAccessed, Send, MailboxLogin
      Files   (60d): FileAccessed, FileModified, FileDownloaded, FileUploaded
      Copilot (30d): CopilotInteraction, AIAppInteraction   (filter by record type)

    python %(prog)s ^
        --teams   Teams_Export.csv ^
        --outlook Outlook_Export.csv ^
        --files   Files_Export.csv ^
        --copilot Copilot_Export.csv ^
        --output-dir ./output


OUTPUT (rollup mode, both layouts produce the same three files):

    <stem>_Rollup_<timestamp>.csv         13 cols  -> M365Usage table
    <stem>_UserStats_<timestamp>.csv      40 cols  -> UserStats table
    <stem>_SessionCohort_<timestamp>.csv   3 cols  -> SessionCohort table

  <stem> defaults to the input file's name (single input) or '<firstInputStem>_Combined'
  (multi-input). Rename the file or use --output-dir if you want a tenant-named folder.


ADVANCED
========
  --reconcile         Sample-based correctness check vs full event-level explosion.
  --debug-events      v1-compatible 153-column event-level CSV (single input only).
  --skip-precompute   Skip UserStats and SessionCohort generation.
  --prompt-filter     Copilot message filter: Prompt | Response | Both | Null.
  --input/-i          Power-user / scripted fallback for one or more CSVs.
""",
    )

    # ── Input layout (mutually exclusive, exactly one required) ──────────
    layout = parser.add_argument_group(
        "INPUT LAYOUT  (choose ONE shape that matches how you exported the data)"
    )
    layout.add_argument(
        "--pax",
        metavar="CSV",
        help="(A) Single CSV from PAX or PowerShell Search-UnifiedAuditLog.",
    )
    layout.add_argument(
        "--teams",
        metavar="CSV",
        help="(B) Teams workload pull from Purview Audit.",
    )
    layout.add_argument(
        "--outlook",
        metavar="CSV",
        help="(B) Outlook / Exchange workload pull from Purview Audit.",
    )
    layout.add_argument(
        "--files",
        metavar="CSV",
        help="(B) Files (SharePoint + OneDrive) workload pull from Purview Audit.",
    )
    layout.add_argument(
        "--copilot",
        metavar="CSV",
        help="(B) Copilot record-type pull (CopilotInteraction + AIAppInteraction).",
    )
    layout.add_argument(
        "--input", "-i",
        nargs="+",
        metavar="CSV",
        help="Power-user fallback: one or more CSV paths (any combination).",
    )

    # ── Output naming & location ─────────────────────────────────────────
    output = parser.add_argument_group("OUTPUT")
    output.add_argument(
        "--output-dir", "-o",
        metavar="DIR",
        default=None,
        help="Directory for output files. Default: same folder as the (first) input.",
    )

    # ── Optional behaviour flags ─────────────────────────────────────────
    advanced = parser.add_argument_group("ADVANCED")
    advanced.add_argument(
        "--skip-precompute",
        action="store_true",
        default=False,
        help="Skip *_UserStats.csv and *_SessionCohort.csv (only the Rollup is written).",
    )
    advanced.add_argument(
        "--no-session-stats",
        action="store_true",
        default=False,
        help="Skip *_SessionStats.csv (the AI in One DISTINCTCOUNT(ThreadId) output).",
    )
    advanced.add_argument(
        "--debug-events",
        action="store_true",
        default=False,
        help="Emit v1-compatible 153-column event-level CSV instead of the rollup (single input only).",
    )
    advanced.add_argument(
        "--reconcile",
        action="store_true",
        default=False,
        help="Run sample-based reconciliation against the first input.",
    )
    advanced.add_argument(
        "--prompt-filter",
        choices=["Prompt", "Response", "Both", "Null"],
        default=None,
        help="Filter Copilot messages by isPrompt value.",
    )
    advanced.add_argument(
        "--quiet", "-q",
        action="store_true",
        default=False,
        help="Suppress progress output (only errors are printed).",
    )
    # Hidden legacy alias (kept for older scripts that referenced --no-userstats).
    advanced.add_argument(
        "--no-userstats",
        dest="skip_precompute",
        action="store_true",
        help=argparse.SUPPRESS,
    )
    advanced.add_argument(
        "--deidentify",
        action="store_true",
        default=False,
        help=(
            "One-way hash all identifying values (UserId, mailbox UPN/GUID/SIDs, "
            "device name, resource URLs/file names) for anonymous reporting. "
            "Deterministic and format-preserving; irreversible (no decode map)."
        ),
    )
    advanced.add_argument(
        "--rebuild-sidecars-from-rollup",
        metavar="ROLLUP_CSV",
        default=None,
        help=(
            "Regenerate UserStats and SessionCohort sidecars from an existing rollup CSV "
            "(no Purview input required). Sidecars are written to --output-dir (default: "
            "the rollup's parent directory) using the rollup's base stem."
        ),
    )
    advanced.add_argument(
        "--session-stats-for-rebuild",
        metavar="SESSIONSTATS_CSV",
        default=None,
        help=(
            "Optional companion to --rebuild-sidecars-from-rollup: when supplied, the "
            "CECopilotPercentile_* columns are computed from this SessionStats CSV's "
            "PromptCount (AI in One semantics). If omitted, the sidecar rebuild falls "
            "back to the audit-event count (legacy behaviour)."
        ),
    )
    parser.add_argument(
        "--version",
        action="version",
        version=f"%(prog)s {SCRIPT_VERSION}",
    )

    args = parser.parse_args()

    global _DEIDENTIFY
    _DEIDENTIFY = bool(args.deidentify)

    # ── Standalone sidecar regeneration mode ─────────────────────────────
    # When --rebuild-sidecars-from-rollup is supplied, ignore every other
    # input/dispatch flag and rebuild UserStats + SessionCohort sidecars
    # from the given rollup CSV. Used by the PAX append-merge workflow
    # after the PowerShell side unions the current run's rollup with a
    # customer-supplied target.
    if args.rebuild_sidecars_from_rollup:
        rollup_in = os.path.abspath(args.rebuild_sidecars_from_rollup)
        if not os.path.isfile(rollup_in):
            print(f"ERROR: Rollup CSV not found: {rollup_in}", file=sys.stderr)
            sys.exit(1)
        session_stats_in: str | None = None
        if args.session_stats_for_rebuild:
            session_stats_in = os.path.abspath(args.session_stats_for_rebuild)
            if not os.path.isfile(session_stats_in):
                print(
                    f"ERROR: SessionStats CSV not found: {session_stats_in}",
                    file=sys.stderr,
                )
                sys.exit(1)
        out_dir = (
            Path(os.path.abspath(args.output_dir))
            if args.output_dir
            else Path(rollup_in).parent
        )
        os.makedirs(out_dir, exist_ok=True)
        rollup_stem = Path(rollup_in).stem
        m = re.match(r"^(.*?)(?:_Rollup(?:_\d{8}_\d{6})?)$", rollup_stem)
        base_stem = m.group(1) if m else rollup_stem
        run_ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        userstats_path = str(out_dir / f"{base_stem}_UserStats_{run_ts}.csv")
        session_path = str(out_dir / f"{base_stem}_SessionCohort_{run_ts}.csv")
        write_userstats_files(
            rollup_in, userstats_path, session_path, args.quiet,
            session_stats_csv_path=session_stats_in,
        )
        sys.exit(0)

    # ── Resolve the input layout into a flat list ────────────────────────
    pax_inputs:  list[str] = [args.pax] if args.pax else []
    workload_inputs: list[tuple[str, str]] = []  # [(label, path), ...] preserves order
    for label in ("teams", "outlook", "files", "copilot"):
        path = getattr(args, label)
        if path:
            workload_inputs.append((label, path))
    legacy_inputs: list[str] = list(args.input) if args.input else []

    if pax_inputs and workload_inputs:
        parser.error("--pax cannot be combined with --teams/--outlook/--files/--copilot. "
                     "Pick the shape that matches your export.")
    if (pax_inputs or workload_inputs) and legacy_inputs:
        parser.error("--input/-i cannot be combined with --pax or the workload flags.")

    if pax_inputs:
        input_paths = [os.path.abspath(pax_inputs[0])]
        layout_label = "pax"
    elif workload_inputs:
        input_paths = [os.path.abspath(p) for _, p in workload_inputs]
        layout_label = "manual_4pull"
    elif legacy_inputs:
        input_paths = [os.path.abspath(p) for p in legacy_inputs]
        layout_label = "legacy_input"
    else:
        parser.error(
            "No input given. Use ONE of:\n"
            "    --pax <CSV>                                                    (single PAX export)\n"
            "    --teams <T> --outlook <O> --files <F> --copilot <C>            (manual 4-pull export)\n"
            "    --input/-i <CSV> [<CSV> ...]                                   (power-user fallback)"
        )

    for p in input_paths:
        if not os.path.isfile(p):
            print(f"ERROR: Input file not found: {p}", file=sys.stderr)
            sys.exit(1)

    # ── Determine output directory & filenames ───────────────────────────
    first_stem = Path(input_paths[0]).stem
    stem = first_stem if len(input_paths) == 1 else f"{first_stem}_Combined"

    output_dir = Path(os.path.abspath(args.output_dir)) if args.output_dir else Path(input_paths[0]).parent
    os.makedirs(output_dir, exist_ok=True)

    run_ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    event_level = args.debug_events

    if not event_level:
        rollup_path = str(output_dir / f"{stem}_Rollup_{run_ts}.csv")
        userstats_path = str(output_dir / f"{stem}_UserStats_{run_ts}.csv")
        session_path = str(output_dir / f"{stem}_SessionCohort_{run_ts}.csv")
        session_stats_path: str | None = (
            None if args.no_session_stats
            else str(output_dir / f"{stem}_SessionStats_{run_ts}.csv")
        )
    else:
        if len(input_paths) > 1:
            print("ERROR: --debug-events accepts only one input CSV.", file=sys.stderr)
            sys.exit(1)
        rollup_path = str(output_dir / f"{stem}_Exploded_{run_ts}.csv")
        session_stats_path = None

    # ── Dispatch ─────────────────────────────────────────────────────────
    if not event_level:
        stats = run_rollup(
            input_csv=input_paths if len(input_paths) > 1 else input_paths[0],
            output_csv=rollup_path,
            prompt_filter=args.prompt_filter,
            quiet=args.quiet,
            session_stats_csv=session_stats_path,
        )
        exit_code = 1 if stats["parse_errors"] > stats["input_records"] * 0.1 else 0

        if not args.skip_precompute:
            write_userstats_files(
                rollup_path, userstats_path, session_path, args.quiet,
                session_stats_csv_path=session_stats_path,
            )
    else:
        stats = run_explosion(
            input_csv=input_paths[0],
            output_csv=rollup_path,
            prompt_filter=args.prompt_filter,
            quiet=args.quiet,
        )
        exit_code = 1 if stats["errors"] > 0 else 0

    if args.reconcile:
        reconcile_passed = run_reconcile(
            input_csv=input_paths[0],
            prompt_filter=args.prompt_filter,
            quiet=args.quiet,
        )
        if not reconcile_passed:
            exit_code = 1

    sys.exit(exit_code)


if __name__ == "__main__":
    main()
'@
# <<< END-EMBEDDED-M365-PROCESSOR

# ============================================================================
# ROLLUP POST-PROCESSOR HELPER FUNCTIONS
# ============================================================================
# Resolve-PythonExe         -> locates a Python 3.10+ interpreter (auto-installs via winget,
#                              falls back to the python.org installer if winget unavailable).
# Install-OrjsonIfMissing   -> installs the optional 'orjson' package; warn-and-continue
#                              on failure (both processors auto-fallback to stdlib json).
# Invoke-EmbeddedProcessor  -> materializes the embedded .py to .pax_incremental,
#                              runs it with the provided argument list, captures stderr,
#                              and deletes the temp file in finally.
# All three functions log via Write-LogHost / Write-Log (defined earlier in the script).
# These functions are only invoked when -Rollup or -RollupPlusRaw is used.
# Minimum required Python version is 3.10 (the embedded processors use PEP 604 unions).
# ============================================================================

$Script:ROLLUP_PYTHON_MIN_MAJOR = 3
$Script:ROLLUP_PYTHON_MIN_MINOR = 10

function Resolve-PythonExe {
	[CmdletBinding()]
	param([switch]$AllowAutoInstall)

	# Returns: hashtable @{ Path=<full path or 'py'>; Args=<launcher args, e.g. '-3.13'>; Version='3.13.1' }
	# Throws on hard failure (no usable interpreter even after install attempts).

	$candidates = @(
		@{ Cmd = 'python';  LauncherArgs = @() }
		@{ Cmd = 'py';      LauncherArgs = @('-3.13') }
		@{ Cmd = 'py';      LauncherArgs = @('-3.12') }
		@{ Cmd = 'py';      LauncherArgs = @('-3.11') }
		@{ Cmd = 'py';      LauncherArgs = @('-3.10') }
		@{ Cmd = 'python3'; LauncherArgs = @() }
	)

	foreach ($c in $candidates) {
		try {
			$cmdInfo = Get-Command -Name $c.Cmd -ErrorAction SilentlyContinue
			if (-not $cmdInfo) { continue }
			$probeArgs = @($c.LauncherArgs) + @('-c', 'import sys; print("{}.{}.{}".format(sys.version_info.major, sys.version_info.minor, sys.version_info.micro))')
			$verOutput = & $c.Cmd @probeArgs 2>$null
			if ($LASTEXITCODE -ne 0 -or -not $verOutput) { continue }
			$verText = ($verOutput | Select-Object -First 1).Trim()
			if ($verText -notmatch '^(\d+)\.(\d+)\.(\d+)') { continue }
			$maj = [int]$Matches[1]
			$min = [int]$Matches[2]
			if ($maj -lt $Script:ROLLUP_PYTHON_MIN_MAJOR) { continue }
			if ($maj -eq $Script:ROLLUP_PYTHON_MIN_MAJOR -and $min -lt $Script:ROLLUP_PYTHON_MIN_MINOR) { continue }
			return @{ Path = $c.Cmd; Args = $c.LauncherArgs; Version = $verText }
		}
		catch { continue }
	}

	if (-not $AllowAutoInstall) {
		throw "No Python $($Script:ROLLUP_PYTHON_MIN_MAJOR).$($Script:ROLLUP_PYTHON_MIN_MINOR)+ interpreter found on PATH."
	}

	# Auto-install path: try winget first, then python.org installer.
	Write-LogHost "Rollup: no Python $($Script:ROLLUP_PYTHON_MIN_MAJOR).$($Script:ROLLUP_PYTHON_MIN_MINOR)+ found. Attempting auto-install..." -ForegroundColor Yellow

	$winget = Get-Command -Name 'winget' -ErrorAction SilentlyContinue
	$installed = $false
	if ($winget) {
		Write-LogHost "Rollup: installing Python 3.13 via winget (Python.Python.3.13)..." -ForegroundColor Cyan
		try {
			$wingetArgs = @('install', '--id', 'Python.Python.3.13', '-e', '--accept-source-agreements', '--accept-package-agreements', '--scope', 'user', '--silent')
			& winget @wingetArgs | Out-Host
			if ($LASTEXITCODE -eq 0) { $installed = $true }
		}
		catch {
			Write-LogHost "Rollup: winget install failed: $($_.Exception.Message)" -ForegroundColor Yellow
		}
	}
	else {
		Write-LogHost "Rollup: winget is not available on this host; falling back to python.org installer." -ForegroundColor Yellow
	}

	if (-not $installed) {
		# python.org per-user silent install
		try {
			$tmpDir = Join-Path ([IO.Path]::GetTempPath()) ("PAX_PythonInstaller_" + [guid]::NewGuid().ToString('N'))
			New-Item -ItemType Directory -Path $tmpDir -Force | Out-Null
			$installerUrl = 'https://www.python.org/ftp/python/3.13.1/python-3.13.1-amd64.exe'
			$installerPath = Join-Path $tmpDir 'python-3.13.1-amd64.exe'
			Write-LogHost "Rollup: downloading $installerUrl ..." -ForegroundColor Cyan
			Invoke-WebRequest -Uri $installerUrl -OutFile $installerPath -UseBasicParsing
			Write-LogHost "Rollup: running silent per-user install (PrependPath=1)..." -ForegroundColor Cyan
			$proc = Start-Process -FilePath $installerPath -ArgumentList @('/quiet', 'InstallAllUsers=0', 'PrependPath=1', 'Include_launcher=1', 'Include_pip=1') -Wait -PassThru
			if ($proc.ExitCode -eq 0) { $installed = $true }
			else { Write-LogHost "Rollup: python.org installer exited with code $($proc.ExitCode)." -ForegroundColor Yellow }
		}
		catch {
			Write-LogHost "Rollup: python.org install failed: $($_.Exception.Message)" -ForegroundColor Yellow
		}
	}

	if (-not $installed) {
		throw "Rollup: failed to auto-install Python $($Script:ROLLUP_PYTHON_MIN_MAJOR).$($Script:ROLLUP_PYTHON_MIN_MINOR)+. Install Python manually from https://www.python.org/downloads/ and re-run."
	}

	# Refresh PATH from process + machine + user scopes so new install is visible without restart.
	$paths = @(
		[Environment]::GetEnvironmentVariable('Path', 'Machine'),
		[Environment]::GetEnvironmentVariable('Path', 'User'),
		$env:Path
	) | Where-Object { $_ }
	$env:Path = ($paths -join ';')

	# Recurse once with auto-install disabled to prevent loops.
	return Resolve-PythonExe -AllowAutoInstall:$false
}

function Write-PaxRollupStage {
	<#
	.SYNOPSIS
		Emit one sanitized rollup stage record (entry, heartbeat, completion, skip, or failure).

	.DESCRIPTION
		Rollup preparation runs several phases that can each take a long time on a large
		append target, and without stage records a run looks idle while it is working. Each
		record names the stage, its status, and the seconds elapsed in that stage, followed
		by caller-supplied AGGREGATE counters only.

		Nothing identifying is accepted or written. Counter values are emitted only when
		they are numeric or boolean; any other value is replaced by a placeholder so a key,
		row, field, package identifier, path, URL, user principal name, tenant or account
		identifier, or credential can never reach the record. Emission is routed through the
		host log helper when it exists and is inert when it does not, so the function is safe
		in isolated unit extraction.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$Stage,
		[ValidateSet('entry', 'heartbeat', 'complete', 'skipped', 'failed')][string]$Status = 'entry',
		[hashtable]$Counters
	)
	if ($null -eq $script:PaxRollupStageStarted) { $script:PaxRollupStageStarted = @{} }
	$nowUtc = [System.DateTime]::UtcNow
	if ($Status -eq 'entry' -or -not $script:PaxRollupStageStarted.ContainsKey($Stage)) {
		$script:PaxRollupStageStarted[$Stage] = $nowUtc
	}
	$elapsed = [double](($nowUtc - [datetime]$script:PaxRollupStageStarted[$Stage]).TotalSeconds)
	$parts = [System.Collections.Generic.List[string]]::new()
	if ($Counters) {
		foreach ($name in @($Counters.Keys | Sort-Object)) {
			$v = $Counters[$name]
			if ($v -is [bool]) { [void]$parts.Add(('{0}={1}' -f $name, $v)); continue }
			if ($v -is [int] -or $v -is [int64] -or $v -is [int16] -or $v -is [uint32] -or $v -is [uint64] -or $v -is [byte]) {
				[void]$parts.Add(('{0}={1:N0}' -f $name, [int64]$v)); continue
			}
			if ($v -is [double] -or $v -is [single] -or $v -is [decimal]) {
				[void]$parts.Add(('{0}={1:N2}' -f $name, [double]$v)); continue
			}
			[void]$parts.Add(('{0}=<non-numeric omitted>' -f $name))
		}
	}
	$detail = if ($parts.Count -gt 0) { ' ' + ($parts.ToArray() -join ' ') } else { '' }
	$color = if ($Status -eq 'failed') { 'Yellow' } else { 'DarkGray' }
	$msg = ('Rollup stage [{0}] {1}: elapsed={2:N1}s{3}' -f $Stage, $Status, $elapsed, $detail)
	$lh = Microsoft.PowerShell.Core\Get-Command -Name 'Write-LogHost' -CommandType Function -ErrorAction SilentlyContinue
	if ($lh) { try { & $lh -Message $msg -ForegroundColor $color } catch { } }
}

function Write-PaxRollupReaderMode {
	<#
	.SYNOPSIS
		Record exactly once which CSV record reader backend serves the bounded rollup pipelines.

	.DESCRIPTION
		The record reader chooses its backend once per process. This helper reports that single
		decision one time so a run states plainly whether the compiled reader or the built-in
		parser is active, without repeating the fact on every stage. Only the mode is recorded.
	#>
	[CmdletBinding()]
	param()
	if ($script:PaxRollupReaderModeLogged) { return }
	$script:PaxRollupReaderModeLogged = $true
	$compiled = $false
	try {
		if ($script:PaxCsvBackendOverride -ne 'Fallback') {
			$compiled = [bool](script:Initialize-PaxCsvCompiledReader)
		}
	}
	catch { $compiled = $false }
	Write-PaxRollupStage -Stage 'csv-reader' -Status 'complete' -Counters @{ compiledReader = $compiled }
}

function Invoke-PaxBoundedProcess {
	<#
	.SYNOPSIS
		Run a child process under a wall-clock bound and never wait on it indefinitely.

	.DESCRIPTION
		Optional package handling contacts an external tool that can stall without ever
		exiting. Waiting on such a child with no bound would hold the whole run. This helper
		starts the child with redirected output, waits at most the supplied number of
		seconds, and on expiry terminates ONLY the process it started (and that process's
		own descendants), then reports the outcome.

		The returned record carries the outcome, the exit code when the child exited on its
		own, and the captured output. Nothing is thrown for a non-zero exit or a timeout, so
		callers decide whether the outcome matters. Only inbox types are used.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $FilePath,
		[Parameter(Mandatory)] [AllowEmptyCollection()] [string[]] $ArgumentList,
		[int] $TimeoutSeconds = 120
	)

	$result = [pscustomobject]@{
		Outcome  = 'Failed'
		ExitCode = $null
		StdOut   = ''
		StdErr   = ''
		Message  = ''
		Seconds  = [double]0
	}

	$psi = [System.Diagnostics.ProcessStartInfo]::new()
	$psi.FileName = $FilePath
	foreach ($a in @($ArgumentList)) { [void]$psi.ArgumentList.Add([string]$a) }
	$psi.UseShellExecute = $false
	$psi.RedirectStandardOutput = $true
	$psi.RedirectStandardError = $true
	$psi.CreateNoWindow = $true

	$proc = $null
	$sw = [System.Diagnostics.Stopwatch]::StartNew()
	try {
		$proc = [System.Diagnostics.Process]::Start($psi)
		if ($null -eq $proc) {
			$result.Message = 'process could not be started'
			return $result
		}
		# Read both streams asynchronously so a full pipe buffer can never deadlock the wait.
		$outTask = $proc.StandardOutput.ReadToEndAsync()
		$errTask = $proc.StandardError.ReadToEndAsync()
		$bound = [int]([math]::Max(1, $TimeoutSeconds)) * 1000
		if ($proc.WaitForExit($bound)) {
			[void]$outTask.Wait(5000)
			[void]$errTask.Wait(5000)
			try { $result.StdOut = [string]$outTask.Result } catch { $result.StdOut = '' }
			try { $result.StdErr = [string]$errTask.Result } catch { $result.StdErr = '' }
			$result.ExitCode = [int]$proc.ExitCode
			$result.Outcome = if ($result.ExitCode -eq 0) { 'Succeeded' } else { 'ExitedNonZero' }
		}
		else {
			$result.Outcome = 'TimedOut'
			$result.Message = ("no exit within {0}s" -f $TimeoutSeconds)
			# Terminate ONLY this cycle-started child and its own descendants.
			try { $proc.Kill($true) } catch { try { $proc.Kill() } catch { } }
			try { [void]$proc.WaitForExit(5000) } catch { }
		}
	}
	catch {
		$result.Outcome = 'Failed'
		$result.Message = $_.Exception.Message
	}
	finally {
		$sw.Stop()
		$result.Seconds = [double]$sw.Elapsed.TotalSeconds
		if ($proc) { try { $proc.Dispose() } catch { } }
	}
	return $result
}

function Install-OrjsonIfMissing {
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string]   $PythonExe,
		[Parameter(Mandatory)] [AllowEmptyCollection()] [string[]] $LauncherArgs,
		[int] $ProbeTimeoutSeconds = 60,
		[int] $InstallTimeoutSeconds = 180
	)

	# Best-effort. Both embedded processors fall back to stdlib json on import failure, so
	# every outcome here is reported and the run continues. Both the probe and the install
	# are bounded so neither can hold the run open, and a child that outlives its bound is
	# terminated before the run moves on.
	Write-PaxRollupStage -Stage 'json-package' -Status 'entry'

	$showArgs = @($LauncherArgs) + @('-m', 'pip', '--disable-pip-version-check', 'show', 'orjson')
	$probe = Invoke-PaxBoundedProcess -FilePath $PythonExe -ArgumentList $showArgs -TimeoutSeconds $ProbeTimeoutSeconds
	if ($probe.Outcome -eq 'Succeeded') {
		Write-PaxRollupStage -Stage 'json-package' -Status 'complete' -Counters @{ alreadyPresent = $true; installAttempted = $false }
		return $true
	}
	if ($probe.Outcome -eq 'TimedOut') {
		Write-LogHost "Rollup: optional JSON package check did not finish within its time limit and was stopped. Continuing with the built-in JSON reader." -ForegroundColor Yellow
		Write-PaxRollupStage -Stage 'json-package' -Status 'failed' -Counters @{ probeTimedOut = $true; installAttempted = $false }
		return $false
	}
	if ($probe.Outcome -eq 'Failed') {
		Write-LogHost "Rollup: optional JSON package check could not run. Continuing with the built-in JSON reader." -ForegroundColor Yellow
		Write-PaxRollupStage -Stage 'json-package' -Status 'failed' -Counters @{ probeFailed = $true; installAttempted = $false }
		return $false
	}

	Write-LogHost "Rollup: 'orjson' not installed; installing for faster JSON parsing (~5-10x). Falls back to stdlib json on failure." -ForegroundColor Cyan
	$installArgs = @($LauncherArgs) + @('-m', 'pip', '--disable-pip-version-check', 'install', '--quiet', '--user', 'orjson')
	$install = Invoke-PaxBoundedProcess -FilePath $PythonExe -ArgumentList $installArgs -TimeoutSeconds $InstallTimeoutSeconds
	if ($install.StdOut) { foreach ($ln in ($install.StdOut -split "`r?`n")) { if ($ln.Trim()) { Write-Log $ln } } }
	if ($install.StdErr) { foreach ($ln in ($install.StdErr -split "`r?`n")) { if ($ln.Trim()) { Write-Log $ln } } }

	if ($install.Outcome -eq 'Succeeded') {
		Write-PaxRollupStage -Stage 'json-package' -Status 'complete' -Counters @{ alreadyPresent = $false; installAttempted = $true; installed = $true }
		return $true
	}
	if ($install.Outcome -eq 'TimedOut') {
		Write-LogHost "Rollup: 'orjson' install did not finish within its time limit and was stopped. Continuing with stdlib json." -ForegroundColor Yellow
		Write-PaxRollupStage -Stage 'json-package' -Status 'failed' -Counters @{ installTimedOut = $true; installAttempted = $true; installed = $false }
		return $false
	}
	if ($install.Outcome -eq 'ExitedNonZero') {
		Write-LogHost "Rollup: 'orjson' install returned exit code $($install.ExitCode). Continuing with stdlib json." -ForegroundColor Yellow
	}
	else {
		Write-LogHost "Rollup: 'orjson' install could not run: $($install.Message). Continuing with stdlib json." -ForegroundColor Yellow
	}
	Write-PaxRollupStage -Stage 'json-package' -Status 'failed' -Counters @{ installAttempted = $true; installed = $false }
	return $false
}

function Install-DeltalakeIfMissing {
	<#
	.SYNOPSIS
		Ensures the Python 'deltalake' package is installed for Fabric Lakehouse Delta-table writes.

	.DESCRIPTION
		Invoked only when the run will write to a Fabric Lakehouse target (Tables/ namespace).
		Performs a quiet per-user install on first use. On failure, returns $false with a clear
		actionable message — the caller must abort the Delta write path rather than continue.

		Unlike Install-OrjsonIfMissing, the deltalake package is NOT optional: the Fabric Tables
		write path cannot fall back to a pure-Python implementation. Callers must check the
		return value and abort the run cleanly if the install fails.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string]   $PythonExe,
		[Parameter(Mandatory)] [AllowEmptyCollection()] [string[]] $LauncherArgs
	)

	$showArgs = @($LauncherArgs) + @('-m', 'pip', 'show', 'deltalake')
	& $PythonExe @showArgs 2>$null | Out-Null
	if ($LASTEXITCODE -eq 0) { return $true }

	Write-LogHost "Fabric: 'deltalake' Python package not installed; installing (required for Lakehouse Tables/ writes)." -ForegroundColor Cyan
	$installArgs = @($LauncherArgs) + @('-m', 'pip', 'install', '--quiet', '--disable-pip-version-check', '--user', 'deltalake>=0.15')
	try {
		& $PythonExe @installArgs 2>&1 | ForEach-Object { Write-Log $_ }
		if ($LASTEXITCODE -eq 0) {
			Write-LogHost "Fabric: 'deltalake' installed successfully." -ForegroundColor Green
			return $true
		}
		Write-LogHost "Fabric: 'deltalake' install returned exit code $LASTEXITCODE. Install manually with 'pip install deltalake' and re-run." -ForegroundColor Red
		return $false
	}
	catch {
		Write-LogHost "Fabric: 'deltalake' install threw: $($_.Exception.Message). Install manually with 'pip install deltalake' and re-run." -ForegroundColor Red
		return $false
	}
}

function ConvertTo-UsersSeedMap {
	<#
	.SYNOPSIS
		Extract {PersonId_Normalized -> UserKey (INT)} from a target Users CSV and write it
		as a compact JSON file the embedded CopilotInteraction processor consumes via
		`--seed-userkey-map`.

	.DESCRIPTION
		Pre-flight helper for -AppendUserInfo. Read the existing target Users CSV produced by a
		prior run, build a dict of PersonId_Normalized -> UserKey, and write JSON. Skips rows
		with empty PersonId_Normalized or non-integer UserKey. First occurrence of any
		PersonId_Normalized wins (target is the source of truth).

	.OUTPUTS
		Int count of entries written.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $TargetUsersCsv,
		[Parameter(Mandatory)] [string] $OutJsonPath,
		# Fixed in-memory buffer budget for the bounded sort (bytes). Governs only
		# WHEN buffered pairs spill; never caps how many rows are processed.
		[int64] $MemoryBudgetBytes = 33554432,
		# Observability-only progress seam, inert by default. It is forwarded verbatim to
		# the bounded sorts, which pass the callback an AGGREGATE snapshot only and swallow
		# any exception it raises. Supplying it cannot change the seed JSON bytes, the key
		# set, the ordering, or the success of the build.
		[scriptblock] $ProgressCallback,
		[double] $ProgressIntervalSeconds = 0
	)
	if (-not (Test-Path -LiteralPath $TargetUsersCsv -PathType Leaf)) {
		throw "ConvertTo-UsersSeedMap: target Users CSV not found: '$TargetUsersCsv'"
	}

	# Bounded seed builder (shared shape with ConvertTo-FactSeedMaps): stream the
	# target once, spill (rawKey, sequence, int-value) pairs, fold to distinct
	# first-occurrence keys via the frozen external-sort machinery, and stream the
	# compact JSON one single-property object at a time so escaping / integer
	# formatting match the prior ConvertTo-Json output byte-for-byte. The complete
	# target is never materialized.
	$buildSeedJson = {
		param([string]$PairsCsvPath, [string]$OutTempJsonPath, [string]$WorkDir, [string]$Tag, [int64]$Budget, [scriptblock]$Progress, [double]$ProgressInterval)
		$u8 = [System.Text.UTF8Encoding]::new($false)
		$byKeyPath = Join-Path $WorkDir ($Tag + '_bykey.csv')
		$firstPath = Join-Path $WorkDir ($Tag + '_first.csv')
		$bySeqPath = Join-Path $WorkDir ($Tag + '_byseq.csv')
		[void](script:Invoke-PaxExternalSort -InputPath $PairsCsvPath -OutputPath $byKeyPath -KeyColumn @('RawKey', 'SeqPad') -Comparer 'OrdinalIgnoreCase' -MemoryBudgetBytes $Budget -FanIn 8 -WorkRoot $WorkDir -ProgressCallback $Progress -ProgressIntervalSeconds $ProgressInterval)
		$cmp = script:Get-PaxComparer -Name 'OrdinalIgnoreCase'
		$r1 = [System.IO.StreamReader]::new($byKeyPath, $true)
		$w1 = [System.IO.StreamWriter]::new($firstPath, $false, $u8)
		$distinct = [int64]0
		try {
			$null = script:Read-PaxCsvRecord -Reader $r1
			script:Write-PaxCsvRecord -Writer $w1 -Fields @('RawKey', 'SeqPad', 'Val')
			$haveLast = $false; $lastKey = $null
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $r1
				if ($null -eq $row) { break }
				$k = if ($row.Length -ge 1) { [string]$row[0] } else { '' }
				if ((-not $haveLast) -or ($cmp.Compare($k, $lastKey) -ne 0)) {
					script:Write-PaxCsvRecord -Writer $w1 -Fields $row
					$distinct++
					$lastKey = $k; $haveLast = $true
				}
			}
		}
		finally { $w1.Flush(); $w1.Dispose(); $r1.Dispose() }
		[void](script:Invoke-PaxExternalSort -InputPath $firstPath -OutputPath $bySeqPath -KeyColumn @('SeqPad') -Comparer 'Ordinal' -MemoryBudgetBytes $Budget -FanIn 8 -WorkRoot $WorkDir -ProgressCallback $Progress -ProgressIntervalSeconds $ProgressInterval)
		$r2 = [System.IO.StreamReader]::new($bySeqPath, $true)
		$w2 = [System.IO.StreamWriter]::new($OutTempJsonPath, $false, $u8)
		try {
			$null = script:Read-PaxCsvRecord -Reader $r2
			$w2.Write('{')
			$wrote = $false
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $r2
				if ($null -eq $row) { break }
				$rawKey = [string]$row[0]
				$valStr = if ($row.Length -ge 3) { [string]$row[2] } else { '0' }
				$obj = [ordered]@{}
				$obj[$rawKey] = [int]::Parse($valStr, [System.Globalization.CultureInfo]::InvariantCulture)
				$oneLine = $obj | ConvertTo-Json -Compress -Depth 2
				$inner = $oneLine.Substring(1, $oneLine.Length - 2)
				if ($wrote) { $w2.Write(',') }
				$w2.Write($inner)
				$wrote = $true
			}
			$w2.Write('}')
		}
		finally { $w2.Flush(); $w2.Dispose(); $r2.Dispose() }
		return $distinct
	}

	$workRootBase = $env:TEMP; if (-not $workRootBase) { $workRootBase = [System.IO.Path]::GetTempPath() }
	$workDir = Join-Path $workRootBase ('pax_usersseed_{0}' -f ([System.Guid]::NewGuid().ToString('N')))
	$outTemp = $OutJsonPath + '.seedtmp'
	$count = 0
	try {
		[void][System.IO.Directory]::CreateDirectory($workDir)
		$pairs = Join-Path $workDir 'pairs.csv'
		$utf8NoBom = [System.Text.UTF8Encoding]::new($false)
		$reader = [System.IO.StreamReader]::new($TargetUsersCsv, $true)
		$pw = [System.IO.StreamWriter]::new($pairs, $false, $utf8NoBom)
		try {
			script:Write-PaxCsvRecord -Writer $pw -Fields @('RawKey', 'SeqPad', 'Val')
			$header = script:Read-PaxCsvRecord -Reader $reader
			if ($null -ne $header) {
				# Match the prior Import-Csv fail-closed behavior on a duplicated member.
				$seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
				foreach ($h in $header) { if (-not $seen.Add([string]$h)) { throw "ConvertTo-UsersSeedMap: duplicate header column '$h' in target Users CSV." } }
				$pidIdx = -1; $ukIdx = -1
				for ($i = 0; $i -lt $header.Length; $i++) {
					$name = [string]$header[$i]
					if ([string]::Equals($name, 'PersonId_Normalized', [System.StringComparison]::OrdinalIgnoreCase)) { $pidIdx = $i }
					elseif ([string]::Equals($name, 'UserKey', [System.StringComparison]::OrdinalIgnoreCase)) { $ukIdx = $i }
				}
				$inv = [System.Globalization.CultureInfo]::InvariantCulture
				$seq = [int64]0
				while ($true) {
					$row = script:Read-PaxCsvRecord -Reader $reader
					if ($null -eq $row) { break }
					$pidRaw = if ($pidIdx -ge 0 -and $pidIdx -lt $row.Length) { [string]$row[$pidIdx] } else { '' }
					if (-not [string]::IsNullOrWhiteSpace($pidRaw)) {
						$ukStr = if ($ukIdx -ge 0 -and $ukIdx -lt $row.Length) { [string]$row[$ukIdx] } else { '' }
						if (-not [string]::IsNullOrWhiteSpace($ukStr)) {
							$ukInt = 0
							if ([int]::TryParse($ukStr, [ref]$ukInt)) {
								script:Write-PaxCsvRecord -Writer $pw -Fields @($pidRaw, $seq.ToString('D19', $inv), $ukInt.ToString($inv))
							}
						}
					}
					$seq++
				}
			}
		}
		finally { $pw.Flush(); $pw.Dispose(); $reader.Dispose() }
		$count = [int](& $buildSeedJson $pairs $outTemp $workDir 'seed' $MemoryBudgetBytes $ProgressCallback $ProgressIntervalSeconds)
		try { $null = (Get-Content -LiteralPath $outTemp -Raw -Encoding UTF8) | ConvertFrom-Json -ErrorAction Stop }
		catch { throw "ConvertTo-UsersSeedMap: seed JSON validation failed for '$outTemp': $($_.Exception.Message)" }
		# Aggregate-only stage record. Routed through a host lookup so the function stays
		# inert when it is extracted and exercised on its own.
		$__paxStage = Microsoft.PowerShell.Core\Get-Command -Name 'Write-PaxRollupStage' -CommandType Function -ErrorAction SilentlyContinue
		if ($__paxStage) {
			$__seedBytes = try { [int64](Get-Item -LiteralPath $outTemp).Length } catch { [int64]0 }
			try { & $__paxStage -Stage 'users-seed-validate' -Status 'complete' -Counters @{ distinctKeys = [int64]$count; seedBytes = $__seedBytes } } catch { }
		}
		$outDir = Split-Path -Parent $OutJsonPath
		if ($outDir -and -not (Test-Path -LiteralPath $outDir -PathType Container)) {
			New-Item -ItemType Directory -Path $outDir -Force | Out-Null
		}
		Move-Item -LiteralPath $outTemp -Destination $OutJsonPath -Force -ErrorAction Stop
	}
	catch {
		if (Test-Path -LiteralPath $outTemp) { try { Remove-Item -LiteralPath $outTemp -Force -ErrorAction SilentlyContinue } catch {} }
		throw
	}
	finally {
		if (Test-Path -LiteralPath $workDir) { try { Remove-Item -LiteralPath $workDir -Recurse -Force -ErrorAction SilentlyContinue } catch {} }
	}
	return $count
}

function ConvertTo-PaxUserKeyContinuity {
	<#
	.SYNOPSIS
		Build one combined {identity -> UserKey} continuity map from whichever existing
		append targets are present and emit the paired continuity seed and audit-only
		identity list.

	.DESCRIPTION
		A Users target on its own describes only the identities that were present in a
		directory export. An identity that appears solely in audit activity lives only in
		the Fact target, so a map built from the Users target alone reserves none of those
		keys and a later run can hand one of them to a different person.

		Either target may be absent. Continuity is then derived from the one that is
		present, so a run that appends only the activity data still keeps every key it
		already handed out.

		Both targets are streamed once through the bounded record reader and the bounded
		external-sort machinery; neither file is held in memory. Identity comparison is
		case-insensitive and culture-independent, matching the rest of the append path.

		The prior mapping is validated BEFORE anything is published. The build fails closed
		when one identity carries more than one key, when one key is claimed by more than
		one identity, when a key is absent or is not a positive whole number where
		continuity would be assumed, when a required identity or key column is missing,
		when either file cannot be read as well-formed CSV, or when the paired outputs
		cannot both be completed. Only aggregate counts are reported; no identity and no
		key value ever reaches a message.

	.OUTPUTS
		Hashtable: SeededKeys, UsersIdentities, AuditOnlyIdentities, MaxReservedUserKey.
	#>
	[CmdletBinding()]
	param(
		[Parameter()]          [string] $TargetUsersCsv,
		[Parameter()]          [string] $TargetFactCsv,
		[Parameter(Mandatory)] [string] $OutJsonPath,
		[Parameter(Mandatory)] [string] $OutAuditOnlyCsvPath,
		# Fixed in-memory buffer budget for the bounded sorts (bytes). Governs only
		# WHEN buffered pairs spill; never caps how many rows are processed.
		[int64] $MemoryBudgetBytes = 33554432,
		# Observability-only progress seam, inert by default and forwarded verbatim to the
		# bounded sorts, which pass an AGGREGATE snapshot and swallow any exception it
		# raises. Supplying it cannot change any output byte.
		[scriptblock] $ProgressCallback,
		[double] $ProgressIntervalSeconds = 0
	)

	$inv = [System.Globalization.CultureInfo]::InvariantCulture
	$u8 = [System.Text.UTF8Encoding]::new($false)
	$cmpId = script:Get-PaxComparer -Name 'OrdinalIgnoreCase'

	# First matching column position for any of the supplied names (BOM strip / trim,
	# case-insensitive), or -1.
	$findCol = {
		param($header, [string[]]$names)
		for ($i = 0; $i -lt $header.Length; $i++) {
			$h = [string]$header[$i]
			if ($i -eq 0) { $h = $h -replace '^\uFEFF', '' }
			$h = $h.Trim()
			foreach ($n in $names) {
				if ([string]::Equals($h, $n, [System.StringComparison]::OrdinalIgnoreCase)) { return $i }
			}
		}
		return -1
	}

	$workRootBase = $env:TEMP; if (-not $workRootBase) { $workRootBase = [System.IO.Path]::GetTempPath() }
	$workDir = Join-Path $workRootBase ('pax_ukcont_{0}' -f ([System.Guid]::NewGuid().ToString('N')))
	$seedTemp = $OutJsonPath + '.conttmp'
	$auditTemp = $OutAuditOnlyCsvPath + '.conttmp'
	$seededKeys = 0; $usersIdentities = 0; $auditOnlyIdentities = 0; $maxReserved = 0

	try {
		[void][System.IO.Directory]::CreateDirectory($workDir)
		$pairs = Join-Path $workDir 'pairs.csv'
		$pw = [System.IO.StreamWriter]::new($pairs, $false, $u8)
		$seq = [int64]0
		try {
			script:Write-PaxCsvRecord -Writer $pw -Fields @('RawKey', 'KeyPad', 'SeqPad', 'Val', 'Side')

			# --- Side 0: the existing Users target, in file order. ---
			if ($TargetUsersCsv -and (Test-Path -LiteralPath $TargetUsersCsv -PathType Leaf)) {
				$ur = [System.IO.StreamReader]::new($TargetUsersCsv, $true)
				try {
					$uh = script:Read-PaxCsvRecord -Reader $ur
					if ($null -ne $uh) {
						$uPid = & $findCol $uh @('PersonId_Normalized')
						$uKey = & $findCol $uh @('UserKey')
						if ($uPid -lt 0 -or $uKey -lt 0) {
							throw 'ConvertTo-PaxUserKeyContinuity: the existing Users target does not carry both the normalized identity column and the UserKey column; refusing to assume key continuity.'
						}
						while ($true) {
							$row = script:Read-PaxCsvRecord -Reader $ur
							if ($null -eq $row) { break }
							$idRaw = if ($uPid -lt $row.Length) { ([string]$row[$uPid]).Trim() } else { '' }
							if (-not [string]::IsNullOrWhiteSpace($idRaw)) {
								$kStr = if ($uKey -lt $row.Length) { ([string]$row[$uKey]).Trim() } else { '' }
								$kInt = 0
								if ((-not [int]::TryParse($kStr, [ref]$kInt)) -or $kInt -lt 1) {
									throw 'ConvertTo-PaxUserKeyContinuity: the existing Users target holds an identity whose UserKey is absent or is not a positive whole number; refusing to assume key continuity.'
								}
								if ($kInt -gt $maxReserved) { $maxReserved = $kInt }
								script:Write-PaxCsvRecord -Writer $pw -Fields @($idRaw, $kInt.ToString('D19', $inv), $seq.ToString('D19', $inv), $kInt.ToString($inv), '0')
								$seq++
							}
						}
					}
				}
				finally { $ur.Dispose() }
			}

			# --- Side 1: the existing Fact target, in file order. ---
			if ($TargetFactCsv -and (Test-Path -LiteralPath $TargetFactCsv -PathType Leaf)) {
				$fr = [System.IO.StreamReader]::new($TargetFactCsv, $true)
				try {
					$fh = script:Read-PaxCsvRecord -Reader $fr
					if ($null -ne $fh) {
						$fId = & $findCol $fh @('User_Id_Normalized', 'Audit_UserId_Normalized')
						$fKey = & $findCol $fh @('UserKey')
						if ($fId -lt 0 -or $fKey -lt 0) {
							throw 'ConvertTo-PaxUserKeyContinuity: the existing Fact target does not carry both the normalized identity column and the UserKey column; refusing to assume key continuity.'
						}
						while ($true) {
							$row = script:Read-PaxCsvRecord -Reader $fr
							if ($null -eq $row) { break }
							$idRaw = if ($fId -lt $row.Length) { ([string]$row[$fId]).Trim() } else { '' }
							if (-not [string]::IsNullOrWhiteSpace($idRaw)) {
								$kStr = if ($fKey -lt $row.Length) { ([string]$row[$fKey]).Trim() } else { '' }
								$kInt = 0
								if ((-not [int]::TryParse($kStr, [ref]$kInt)) -or $kInt -lt 1) {
									throw 'ConvertTo-PaxUserKeyContinuity: the existing Fact target holds an identity whose UserKey is absent or is not a positive whole number; refusing to assume key continuity.'
								}
								if ($kInt -gt $maxReserved) { $maxReserved = $kInt }
								script:Write-PaxCsvRecord -Writer $pw -Fields @($idRaw, $kInt.ToString('D19', $inv), $seq.ToString('D19', $inv), $kInt.ToString($inv), '1')
								$seq++
							}
						}
					}
				}
				finally { $fr.Dispose() }
			}
		}
		finally { $pw.Flush(); $pw.Dispose() }

		# --- Identity view: one group per identity, first appearance first. ---
		$byIdentity = Join-Path $workDir 'by_identity.csv'
		[void](script:Invoke-PaxExternalSort -InputPath $pairs -OutputPath $byIdentity -KeyColumn @('RawKey', 'SeqPad') -Comparer 'OrdinalIgnoreCase' -MemoryBudgetBytes $MemoryBudgetBytes -FanIn 8 -WorkRoot $workDir -ProgressCallback $ProgressCallback -ProgressIntervalSeconds $ProgressIntervalSeconds)

		$identities = Join-Path $workDir 'identities.csv'
		$splitIdentities = 0
		$ir = [System.IO.StreamReader]::new($byIdentity, $true)
		$iw = [System.IO.StreamWriter]::new($identities, $false, $u8)
		try {
			$null = script:Read-PaxCsvRecord -Reader $ir
			script:Write-PaxCsvRecord -Writer $iw -Fields @('RawKey', 'SeqPad', 'Val', 'HasUsers')
			$haveGroup = $false; $gRaw = ''; $gSeq = ''; $gVal = ''; $gHasUsers = '0'; $gSplit = $false
			$rRaw = ''; $rSeq = ''; $rVal = ''; $rSide = ''
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $ir
				$isEnd = ($null -eq $row)
				if (-not $isEnd) {
					$rRaw = [string]$row[0]
					$rSeq = [string]$row[2]
					$rVal = [string]$row[3]
					$rSide = [string]$row[4]
				}
				if ($haveGroup -and ($isEnd -or ($cmpId.Compare($rRaw, $gRaw) -ne 0))) {
					if ($gSplit) { $splitIdentities++ }
					script:Write-PaxCsvRecord -Writer $iw -Fields @($gRaw, $gSeq, $gVal, $gHasUsers)
					if ($gHasUsers -eq '1') { $usersIdentities++ } else { $auditOnlyIdentities++ }
					$haveGroup = $false
				}
				if ($isEnd) { break }
				if (-not $haveGroup) {
					$haveGroup = $true; $gRaw = $rRaw; $gSeq = $rSeq; $gVal = $rVal; $gHasUsers = '0'; $gSplit = $false
				}
				if ($rVal -ne $gVal) { $gSplit = $true }
				if ($rSide -eq '0') { $gHasUsers = '1' }
			}
		}
		finally { $iw.Flush(); $iw.Dispose(); $ir.Dispose() }

		# --- Key view: one group per reserved key. ---
		$byKey = Join-Path $workDir 'by_key.csv'
		[void](script:Invoke-PaxExternalSort -InputPath $pairs -OutputPath $byKey -KeyColumn @('KeyPad', 'SeqPad') -Comparer 'Ordinal' -MemoryBudgetBytes $MemoryBudgetBytes -FanIn 8 -WorkRoot $workDir -ProgressCallback $ProgressCallback -ProgressIntervalSeconds $ProgressIntervalSeconds)

		$sharedKeys = 0
		$kr = [System.IO.StreamReader]::new($byKey, $true)
		try {
			$null = script:Read-PaxCsvRecord -Reader $kr
			$haveK = $false; $kPad = ''; $kFirstId = ''; $kShared = $false
			$rPad = ''; $rId = ''
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $kr
				$isEnd = ($null -eq $row)
				if (-not $isEnd) { $rId = [string]$row[0]; $rPad = [string]$row[1] }
				if ($haveK -and ($isEnd -or ($rPad -ne $kPad))) {
					if ($kShared) { $sharedKeys++ }
					$haveK = $false
				}
				if ($isEnd) { break }
				if (-not $haveK) { $haveK = $true; $kPad = $rPad; $kFirstId = $rId; $kShared = $false }
				if ($cmpId.Compare($rId, $kFirstId) -ne 0) { $kShared = $true }
			}
		}
		finally { $kr.Dispose() }

		if ($splitIdentities -gt 0 -or $sharedKeys -gt 0) {
			Write-PaxRollupStage -Stage 'users-continuity' -Status 'failed' -Counters @{ splitIdentities = [int64]$splitIdentities; sharedUserKeys = [int64]$sharedKeys }
			throw ('ConvertTo-PaxUserKeyContinuity: the existing append targets disagree about user keys ({0} identity group(s) carry more than one key; {1} key(s) are claimed by more than one identity). Refusing to build a continuity map that would corrupt the append.' -f $splitIdentities, $sharedKeys)
		}

		# --- Emit the paired outputs in first-appearance order. ---
		$ordered = Join-Path $workDir 'ordered.csv'
		[void](script:Invoke-PaxExternalSort -InputPath $identities -OutputPath $ordered -KeyColumn @('SeqPad') -Comparer 'Ordinal' -MemoryBudgetBytes $MemoryBudgetBytes -FanIn 8 -WorkRoot $workDir -ProgressCallback $ProgressCallback -ProgressIntervalSeconds $ProgressIntervalSeconds)

		$or = [System.IO.StreamReader]::new($ordered, $true)
		$jw = [System.IO.StreamWriter]::new($seedTemp, $false, $u8)
		$aw = [System.IO.StreamWriter]::new($auditTemp, $false, $u8)
		try {
			$null = script:Read-PaxCsvRecord -Reader $or
			script:Write-PaxCsvRecord -Writer $aw -Fields @('PersonId_Normalized', 'UserKey')
			$jw.Write('{')
			$wrote = $false
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $or
				if ($null -eq $row) { break }
				$rawKey = [string]$row[0]
				$valStr = [string]$row[2]
				$hasUsers = [string]$row[3]
				$obj = [ordered]@{}
				$obj[$rawKey] = [int]::Parse($valStr, $inv)
				$oneLine = $obj | ConvertTo-Json -Compress -Depth 2
				$innerJson = $oneLine.Substring(1, $oneLine.Length - 2)
				if ($wrote) { $jw.Write(',') }
				$jw.Write($innerJson)
				$wrote = $true
				$seededKeys++
				if ($hasUsers -ne '1') { script:Write-PaxCsvRecord -Writer $aw -Fields @($rawKey, $valStr) }
			}
			$jw.Write('}')
		}
		finally { $jw.Flush(); $jw.Dispose(); $aw.Flush(); $aw.Dispose(); $or.Dispose() }

		try { $null = (Get-Content -LiteralPath $seedTemp -Raw -Encoding UTF8) | ConvertFrom-Json -ErrorAction Stop }
		catch { throw "ConvertTo-PaxUserKeyContinuity: continuity seed validation failed: $($_.Exception.Message)" }
		if (-not (Test-Path -LiteralPath $auditTemp -PathType Leaf)) {
			throw 'ConvertTo-PaxUserKeyContinuity: the audit-only identity list was not produced; refusing to publish an incomplete pair.'
		}
		foreach ($outPath in @($OutJsonPath, $OutAuditOnlyCsvPath)) {
			$outDir = Split-Path -Parent $outPath
			if ($outDir -and -not (Test-Path -LiteralPath $outDir -PathType Container)) {
				New-Item -ItemType Directory -Path $outDir -Force | Out-Null
			}
		}
		Move-Item -LiteralPath $seedTemp -Destination $OutJsonPath -Force -ErrorAction Stop
		try { Move-Item -LiteralPath $auditTemp -Destination $OutAuditOnlyCsvPath -Force -ErrorAction Stop }
		catch {
			if (Test-Path -LiteralPath $OutJsonPath) { try { Remove-Item -LiteralPath $OutJsonPath -Force -ErrorAction SilentlyContinue } catch { } }
			throw
		}
		Write-PaxRollupStage -Stage 'users-continuity' -Status 'complete' -Counters @{ reservedKeys = [int64]$seededKeys; directoryIdentities = [int64]$usersIdentities; auditOnlyIdentities = [int64]$auditOnlyIdentities; highestReservedKey = [int64]$maxReserved }
	}
	catch {
		foreach ($tempPath in @($seedTemp, $auditTemp)) {
			if (Test-Path -LiteralPath $tempPath) { try { Remove-Item -LiteralPath $tempPath -Force -ErrorAction SilentlyContinue } catch { } }
		}
		throw
	}
	finally {
		if (Test-Path -LiteralPath $workDir) { try { Remove-Item -LiteralPath $workDir -Recurse -Force -ErrorAction SilentlyContinue } catch { } }
	}

	return @{
		SeededKeys          = [int]$seededKeys
		UsersIdentities     = [int]$usersIdentities
		AuditOnlyIdentities = [int]$auditOnlyIdentities
		MaxReservedUserKey  = [int]$maxReserved
	}
}

function Add-PaxAuditOnlyUserRows {
	<#
	.SYNOPSIS
		Write a copy of the current-run Users CSV that also carries one row for every
		audit-only identity, so every Fact user resolves to a Users row.

	.DESCRIPTION
		An identity that only ever appears in audit activity has no directory row, so the
		current run emits no Users row for it and the Fact rows that carry its key have
		nothing to join to. This helper adds one row per such identity carrying ONLY the
		normalized identity and the key already reserved for it. Every descriptive,
		licensing, organizational, manager, hierarchy and profile value is left blank;
		nothing is invented.

		The missing identities are taken from two sources: the prior audit-only list, and
		the candidate activity data for this run. The second source covers a person seen
		for the very first time in this run's activity, who has no prior row anywhere and
		would otherwise leave the key their Fact rows carry unresolved.

		A real directory row always wins: an audit-only identity that IS present in the
		current run is skipped entirely, and a later run that obtains a real row folds it
		in through the union merge while keeping the same key.

		Both inputs are streamed through the bounded machinery. Publication is refused when
		the audit-only list repeats an identity or repeats a key, when one identity carries
		more than one key in the candidate activity data, or when a reserved key disagrees
		with the key that identity carries in the candidate activity data.

	.OUTPUTS
		Int count of rows added.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $CurrentUsersCsv,
		[Parameter(Mandatory)] [string] $AuditOnlyCsv,
		[Parameter(Mandatory)] [string] $OutputPath,
		[Parameter()]          [string] $CandidateFactCsv,
		[int64] $MemoryBudgetBytes = 33554432
	)
	if (-not (Test-Path -LiteralPath $CurrentUsersCsv -PathType Leaf)) {
		throw "Add-PaxAuditOnlyUserRows: current Users CSV not found: '$CurrentUsersCsv'"
	}

	$inv = [System.Globalization.CultureInfo]::InvariantCulture
	$u8 = [System.Text.UTF8Encoding]::new($false)
	$cmpId = script:Get-PaxComparer -Name 'OrdinalIgnoreCase'
	$findCol = {
		param($header, [string]$name)
		for ($i = 0; $i -lt $header.Length; $i++) {
			$h = [string]$header[$i]
			if ($i -eq 0) { $h = $h -replace '^\uFEFF', '' }
			if ([string]::Equals($h.Trim(), $name, [System.StringComparison]::OrdinalIgnoreCase)) { return $i }
		}
		return -1
	}

	$workRootBase = $env:TEMP; if (-not $workRootBase) { $workRootBase = [System.IO.Path]::GetTempPath() }
	$workDir = Join-Path $workRootBase ('pax_ukplace_{0}' -f ([System.Guid]::NewGuid().ToString('N')))
	$tmpOut = $OutputPath + '.placing'
	$added = 0

	try {
		[void][System.IO.Directory]::CreateDirectory($workDir)

		# --- Header of the current-run Users CSV (bounded: header record only). ---
		$hdr = $null
		$hr = [System.IO.StreamReader]::new($CurrentUsersCsv, $true)
		try { $hdr = script:Read-PaxCsvRecord -Reader $hr } finally { $hr.Dispose() }
		if ($null -eq $hdr) { throw 'Add-PaxAuditOnlyUserRows: the current-run Users CSV has no header record.' }
		$colPidNorm = & $findCol $hdr 'PersonId_Normalized'
		$colUserKey = & $findCol $hdr 'UserKey'
		$colPersonId = & $findCol $hdr 'PersonId'
		if ($colPidNorm -lt 0 -or $colUserKey -lt 0) {
			throw 'Add-PaxAuditOnlyUserRows: the current-run Users CSV does not carry both the normalized identity column and the UserKey column; refusing to add rows.'
		}

		# --- Pair both identity sources into one bounded work file. ---
		$pairs = Join-Path $workDir 'pairs.csv'
		$pw = [System.IO.StreamWriter]::new($pairs, $false, $u8)
		$seq = [int64]0
		try {
			script:Write-PaxCsvRecord -Writer $pw -Fields @('Id', 'Side', 'SeqPad', 'Val')
			$cr = [System.IO.StreamReader]::new($CurrentUsersCsv, $true)
			try {
				$null = script:Read-PaxCsvRecord -Reader $cr
				while ($true) {
					$row = script:Read-PaxCsvRecord -Reader $cr
					if ($null -eq $row) { break }
					$idRaw = if ($colPidNorm -lt $row.Length) { ([string]$row[$colPidNorm]).Trim() } else { '' }
					if (-not [string]::IsNullOrWhiteSpace($idRaw)) {
						script:Write-PaxCsvRecord -Writer $pw -Fields @($idRaw, '0', $seq.ToString('D19', $inv), '')
						$seq++
					}
				}
			}
			finally { $cr.Dispose() }

			if (Test-Path -LiteralPath $AuditOnlyCsv -PathType Leaf) {
				$ar = [System.IO.StreamReader]::new($AuditOnlyCsv, $true)
				try {
					$ah = script:Read-PaxCsvRecord -Reader $ar
					if ($null -ne $ah) {
						$aId = & $findCol $ah 'PersonId_Normalized'
						$aKey = & $findCol $ah 'UserKey'
						if ($aId -lt 0 -or $aKey -lt 0) {
							throw 'Add-PaxAuditOnlyUserRows: the audit-only identity list is missing a required column; refusing to add rows.'
						}
						while ($true) {
							$row = script:Read-PaxCsvRecord -Reader $ar
							if ($null -eq $row) { break }
							$idRaw = if ($aId -lt $row.Length) { ([string]$row[$aId]).Trim() } else { '' }
							$kStr = if ($aKey -lt $row.Length) { ([string]$row[$aKey]).Trim() } else { '' }
							if ([string]::IsNullOrWhiteSpace($idRaw)) { continue }
							$kInt = 0
							if ((-not [int]::TryParse($kStr, [ref]$kInt)) -or $kInt -lt 1) {
								throw 'Add-PaxAuditOnlyUserRows: the audit-only identity list carries a key that is not a positive whole number; refusing to add rows.'
							}
							script:Write-PaxCsvRecord -Writer $pw -Fields @($idRaw, '1', $seq.ToString('D19', $inv), $kInt.ToString($inv))
							$seq++
						}
					}
				}
				finally { $ar.Dispose() }
			}

			# --- Side 2: the candidate activity data, in file order. An identity first ---
			# --- seen in THIS run has no prior audit-only row, so its key is taken here. ---
			if ($CandidateFactCsv -and (Test-Path -LiteralPath $CandidateFactCsv -PathType Leaf)) {
				$fr = [System.IO.StreamReader]::new($CandidateFactCsv, $true)
				try {
					$fh = script:Read-PaxCsvRecord -Reader $fr
					if ($null -ne $fh) {
						$fId = & $findCol $fh 'User_Id_Normalized'
						if ($fId -lt 0) { $fId = & $findCol $fh 'Audit_UserId_Normalized' }
						$fKey = & $findCol $fh 'UserKey'
						if ($fId -lt 0 -or $fKey -lt 0) {
							throw 'Add-PaxAuditOnlyUserRows: the candidate Fact CSV does not carry both the normalized identity column and the UserKey column; refusing to add rows.'
						}
						while ($true) {
							$row = script:Read-PaxCsvRecord -Reader $fr
							if ($null -eq $row) { break }
							$idRaw = if ($fId -lt $row.Length) { ([string]$row[$fId]).Trim() } else { '' }
							if ([string]::IsNullOrWhiteSpace($idRaw)) { continue }
							$kStr = if ($fKey -lt $row.Length) { ([string]$row[$fKey]).Trim() } else { '' }
							if ([string]::IsNullOrWhiteSpace($kStr)) { continue }
							$kInt = 0
							if ((-not [int]::TryParse($kStr, [ref]$kInt)) -or $kInt -lt 1) {
								throw 'Add-PaxAuditOnlyUserRows: the candidate Fact CSV carries a key that is not a positive whole number; refusing to add rows.'
							}
							script:Write-PaxCsvRecord -Writer $pw -Fields @($idRaw, '2', $seq.ToString('D19', $inv), $kInt.ToString($inv))
							$seq++
						}
					}
				}
				finally { $fr.Dispose() }
			}
		}
		finally { $pw.Flush(); $pw.Dispose() }

		# --- Group per identity; keep only identities with no current-run row. ---
		$sorted = Join-Path $workDir 'sorted.csv'
		[void](script:Invoke-PaxExternalSort -InputPath $pairs -OutputPath $sorted -KeyColumn @('Id', 'Side', 'SeqPad') -Comparer 'OrdinalIgnoreCase' -MemoryBudgetBytes $MemoryBudgetBytes -FanIn 8 -WorkRoot $workDir)

		$additions = Join-Path $workDir 'additions.csv'
		$sr = [System.IO.StreamReader]::new($sorted, $true)
		$aw = [System.IO.StreamWriter]::new($additions, $false, $u8)
		try {
			$null = script:Read-PaxCsvRecord -Reader $sr
			script:Write-PaxCsvRecord -Writer $aw -Fields @('Id', 'KeyPad', 'Val')
			$haveGroup = $false; $gId = ''; $gHasCurrent = $false; $gVal = ''; $gAuditRows = 0; $gFactRows = 0; $gFactVal = ''; $gFactSplit = $false
			$rId = ''; $rSide = ''; $rVal = ''
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $sr
				$isEnd = ($null -eq $row)
				if (-not $isEnd) { $rId = [string]$row[0]; $rSide = [string]$row[1]; $rVal = [string]$row[3] }
				if ($haveGroup -and ($isEnd -or ($cmpId.Compare($rId, $gId) -ne 0))) {
					if ($gAuditRows -gt 1) {
						throw 'Add-PaxAuditOnlyUserRows: the audit-only identity list repeats an identity; refusing to add rows.'
					}
					if ($gFactSplit) {
						throw 'Add-PaxAuditOnlyUserRows: one identity carries more than one key in the candidate activity data; refusing to add rows.'
					}
					if ($gAuditRows -eq 1 -and $gFactRows -gt 0 -and $gFactVal -ne $gVal) {
						throw 'Add-PaxAuditOnlyUserRows: an identity''s reserved key disagrees with the key it carries in the candidate activity data; refusing to add rows.'
					}
					if ((-not $gHasCurrent) -and $gAuditRows -eq 1) {
						$kv = [int]::Parse($gVal, $inv)
						script:Write-PaxCsvRecord -Writer $aw -Fields @($gId, $kv.ToString('D19', $inv), $gVal)
						$added++
					}
					elseif ((-not $gHasCurrent) -and $gAuditRows -eq 0 -and $gFactRows -gt 0) {
						$kv = [int]::Parse($gFactVal, $inv)
						script:Write-PaxCsvRecord -Writer $aw -Fields @($gId, $kv.ToString('D19', $inv), $gFactVal)
						$added++
					}
					$haveGroup = $false
				}
				if ($isEnd) { break }
				if (-not $haveGroup) { $haveGroup = $true; $gId = $rId; $gHasCurrent = $false; $gVal = ''; $gAuditRows = 0; $gFactRows = 0; $gFactVal = ''; $gFactSplit = $false }
				if ($rSide -eq '0') { $gHasCurrent = $true }
				elseif ($rSide -eq '1') { $gAuditRows++; $gVal = $rVal }
				else {
					$gFactRows++
					if ($gFactRows -eq 1) { $gFactVal = $rVal }
					elseif ($rVal -ne $gFactVal) { $gFactSplit = $true }
				}
			}
		}
		finally { $aw.Flush(); $aw.Dispose(); $sr.Dispose() }

		# --- Refuse a repeated key across the rows about to be added. ---
		if ($added -gt 0) {
			$byKey = Join-Path $workDir 'additions_bykey.csv'
			[void](script:Invoke-PaxExternalSort -InputPath $additions -OutputPath $byKey -KeyColumn @('KeyPad') -Comparer 'Ordinal' -MemoryBudgetBytes $MemoryBudgetBytes -FanIn 8 -WorkRoot $workDir)
			$dr = [System.IO.StreamReader]::new($byKey, $true)
			try {
				$null = script:Read-PaxCsvRecord -Reader $dr
				$prevPad = $null
				while ($true) {
					$row = script:Read-PaxCsvRecord -Reader $dr
					if ($null -eq $row) { break }
					$pad = [string]$row[1]
					if ($null -ne $prevPad -and $pad -eq $prevPad) {
						throw 'Add-PaxAuditOnlyUserRows: two audit-only identities claim the same key; refusing to add rows.'
					}
					$prevPad = $pad
				}
			}
			finally { $dr.Dispose() }
		}

		# --- Publish: the current rows verbatim, then the added rows. ---
		$width = $hdr.Length
		$ow = [System.IO.StreamWriter]::new($tmpOut, $false, $u8)
		try {
			$cr2 = [System.IO.StreamReader]::new($CurrentUsersCsv, $true)
			try {
				while ($true) {
					$row = script:Read-PaxCsvRecord -Reader $cr2
					if ($null -eq $row) { break }
					script:Write-PaxCsvRecord -Writer $ow -Fields $row
				}
			}
			finally { $cr2.Dispose() }
			if ($added -gt 0) {
				$ar2 = [System.IO.StreamReader]::new($additions, $true)
				try {
					$null = script:Read-PaxCsvRecord -Reader $ar2
					while ($true) {
						$row = script:Read-PaxCsvRecord -Reader $ar2
						if ($null -eq $row) { break }
						$fields = New-Object 'string[]' $width
						for ($j = 0; $j -lt $width; $j++) { $fields[$j] = '' }
						$fields[$colPidNorm] = [string]$row[0]
						$fields[$colUserKey] = [string]$row[2]
						if ($colPersonId -ge 0) { $fields[$colPersonId] = [string]$row[0] }
						script:Write-PaxCsvRecord -Writer $ow -Fields $fields
					}
				}
				finally { $ar2.Dispose() }
			}
		}
		finally { $ow.Flush(); $ow.Dispose() }

		Move-Item -LiteralPath $tmpOut -Destination $OutputPath -Force -ErrorAction Stop
	}
	catch {
		if (Test-Path -LiteralPath $tmpOut) { try { Remove-Item -LiteralPath $tmpOut -Force -ErrorAction SilentlyContinue } catch { } }
		throw
	}
	finally {
		if (Test-Path -LiteralPath $workDir) { try { Remove-Item -LiteralPath $workDir -Recurse -Force -ErrorAction SilentlyContinue } catch { } }
	}

	return [int]$added
}

function Test-PaxUserKeyReferentialIntegrity {
	<#
	.SYNOPSIS
		Validate a candidate Fact file and a candidate Users file TOGETHER, before either
		one is allowed to replace an existing append target.

	.DESCRIPTION
		Runs the joins the dashboard will run. Every check streams through the bounded
		machinery, so file size does not govern memory. Only aggregate counts are
		reported; no identity and no key value ever reaches a message.

		Checks: no key is claimed by more than one identity; no identity carries more than
		one key; every non-blank Fact key resolves to exactly one Users row; the resolved
		Users identity matches the Fact identity on that row.

		The Users candidate is optional. With no Users candidate there is nothing to
		resolve against, so the Fact candidate is validated for identity-to-key uniqueness
		and for keys shared between two identities rather than for orphan resolution.

	.OUTPUTS
		Hashtable: Passed, ConflictingUserKeys, SplitIdentities, OrphanFactKeys,
		MismatchedFactRows, UsersRows, FactRows.
	#>
	[CmdletBinding()]
	param(
		[Parameter()]          [string] $CandidateUsersCsv,
		[Parameter()]          [string] $CandidateFactCsv,
		[int64]                $MemoryBudgetBytes = 33554432
	)
	$hasUsersCandidate = -not [string]::IsNullOrWhiteSpace($CandidateUsersCsv)
	if ($hasUsersCandidate -and -not (Test-Path -LiteralPath $CandidateUsersCsv -PathType Leaf)) {
		throw "Test-PaxUserKeyReferentialIntegrity: candidate Users CSV not found: '$CandidateUsersCsv'"
	}
	if (-not $hasUsersCandidate -and -not ($CandidateFactCsv -and (Test-Path -LiteralPath $CandidateFactCsv -PathType Leaf))) {
		throw 'Test-PaxUserKeyReferentialIntegrity: neither candidate file was supplied; there is nothing to validate.'
	}

	$inv = [System.Globalization.CultureInfo]::InvariantCulture
	$u8 = [System.Text.UTF8Encoding]::new($false)
	$cmpId = script:Get-PaxComparer -Name 'OrdinalIgnoreCase'
	$findCol = {
		param($header, [string[]]$names)
		for ($i = 0; $i -lt $header.Length; $i++) {
			$h = [string]$header[$i]
			if ($i -eq 0) { $h = $h -replace '^\uFEFF', '' }
			$h = $h.Trim()
			foreach ($n in $names) {
				if ([string]::Equals($h, $n, [System.StringComparison]::OrdinalIgnoreCase)) { return $i }
			}
		}
		return -1
	}

	$workRootBase = $env:TEMP; if (-not $workRootBase) { $workRootBase = [System.IO.Path]::GetTempPath() }
	$workDir = Join-Path $workRootBase ('pax_ukgate_{0}' -f ([System.Guid]::NewGuid().ToString('N')))
	$conflictingKeys = 0; $splitIdentities = 0; $orphanFactKeys = 0; $mismatchedFactRows = 0
	$usersRows = [int64]0; $factRows = [int64]0

	try {
		[void][System.IO.Directory]::CreateDirectory($workDir)
		$pairs = Join-Path $workDir 'pairs.csv'
		$pw = [System.IO.StreamWriter]::new($pairs, $false, $u8)
		$seq = [int64]0
		try {
			script:Write-PaxCsvRecord -Writer $pw -Fields @('Id', 'KeyPad', 'Side', 'SeqPad')

			if ($hasUsersCandidate) {
				$ur = [System.IO.StreamReader]::new($CandidateUsersCsv, $true)
				try {
					$uh = script:Read-PaxCsvRecord -Reader $ur
					if ($null -eq $uh) { throw 'Test-PaxUserKeyReferentialIntegrity: the candidate Users CSV has no header record.' }
					$uId = & $findCol $uh @('PersonId_Normalized')
					$uKey = & $findCol $uh @('UserKey')
					if ($uId -lt 0 -or $uKey -lt 0) {
						throw 'Test-PaxUserKeyReferentialIntegrity: the candidate Users CSV does not carry both the normalized identity column and the UserKey column.'
					}
					while ($true) {
						$row = script:Read-PaxCsvRecord -Reader $ur
						if ($null -eq $row) { break }
						$usersRows++
						$idRaw = if ($uId -lt $row.Length) { ([string]$row[$uId]).Trim() } else { '' }
						$kStr = if ($uKey -lt $row.Length) { ([string]$row[$uKey]).Trim() } else { '' }
						if ([string]::IsNullOrWhiteSpace($idRaw) -or [string]::IsNullOrWhiteSpace($kStr)) { continue }
						$kInt = 0
						if (-not [int]::TryParse($kStr, [ref]$kInt)) { continue }
						script:Write-PaxCsvRecord -Writer $pw -Fields @($idRaw, $kInt.ToString('D19', $inv), '0', $seq.ToString('D19', $inv))
						$seq++
					}
				}
				finally { $ur.Dispose() }
			}

			if ($CandidateFactCsv -and (Test-Path -LiteralPath $CandidateFactCsv -PathType Leaf)) {
				$fr = [System.IO.StreamReader]::new($CandidateFactCsv, $true)
				try {
					$fh = script:Read-PaxCsvRecord -Reader $fr
					if ($null -eq $fh) { throw 'Test-PaxUserKeyReferentialIntegrity: the candidate Fact CSV has no header record.' }
					$fId = & $findCol $fh @('User_Id_Normalized', 'Audit_UserId_Normalized')
					$fKey = & $findCol $fh @('UserKey')
					if ($fId -lt 0 -or $fKey -lt 0) {
						throw 'Test-PaxUserKeyReferentialIntegrity: the candidate Fact CSV does not carry both the normalized identity column and the UserKey column.'
					}
					while ($true) {
						$row = script:Read-PaxCsvRecord -Reader $fr
						if ($null -eq $row) { break }
						$factRows++
						$kStr = if ($fKey -lt $row.Length) { ([string]$row[$fKey]).Trim() } else { '' }
						if ([string]::IsNullOrWhiteSpace($kStr)) { continue }
						$idRaw = if ($fId -lt $row.Length) { ([string]$row[$fId]).Trim() } else { '' }
						$kInt = 0
						if (-not [int]::TryParse($kStr, [ref]$kInt)) { continue }
						script:Write-PaxCsvRecord -Writer $pw -Fields @($idRaw, $kInt.ToString('D19', $inv), '1', $seq.ToString('D19', $inv))
						$seq++
					}
				}
				finally { $fr.Dispose() }
			}
		}
		finally { $pw.Flush(); $pw.Dispose() }

		# --- Key view: exactly one Users row per key, and every Fact row agrees. ---
		$byKey = Join-Path $workDir 'by_key.csv'
		[void](script:Invoke-PaxExternalSort -InputPath $pairs -OutputPath $byKey -KeyColumn @('KeyPad', 'Side', 'SeqPad') -Comparer 'Ordinal' -MemoryBudgetBytes $MemoryBudgetBytes -FanIn 8 -WorkRoot $workDir)
		$kr = [System.IO.StreamReader]::new($byKey, $true)
		try {
			$null = script:Read-PaxCsvRecord -Reader $kr
			$haveK = $false; $kPad = ''; $kUsersRows = 0; $kUsersId = ''; $kFactMismatch = 0; $kFactRows = 0; $kFirstFactId = ''; $kFactIdConflict = $false
			$rId = ''; $rPad = ''; $rSide = ''
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $kr
				$isEnd = ($null -eq $row)
				if (-not $isEnd) { $rId = [string]$row[0]; $rPad = [string]$row[1]; $rSide = [string]$row[2] }
				if ($haveK -and ($isEnd -or ($rPad -ne $kPad))) {
					if ($kUsersRows -gt 1) { $conflictingKeys++ }
					elseif ($kUsersRows -eq 0 -and $kFactRows -gt 0) {
						# With no Users candidate there is nothing to resolve against, so the
						# only thing a key group can prove is that one key means one person.
						if ($hasUsersCandidate) { $orphanFactKeys++ }
						elseif ($kFactIdConflict) { $conflictingKeys++ }
					}
					$mismatchedFactRows += $kFactMismatch
					$haveK = $false
				}
				if ($isEnd) { break }
				if (-not $haveK) { $haveK = $true; $kPad = $rPad; $kUsersRows = 0; $kUsersId = ''; $kFactMismatch = 0; $kFactRows = 0; $kFirstFactId = ''; $kFactIdConflict = $false }
				if ($rSide -eq '0') {
					$kUsersRows++
					if ($kUsersRows -eq 1) { $kUsersId = $rId }
				}
				else {
					$kFactRows++
					if ($kUsersRows -ge 1 -and ($cmpId.Compare($rId, $kUsersId) -ne 0)) { $kFactMismatch++ }
					if ($kUsersRows -eq 0) {
						if ($kFactRows -eq 1) { $kFirstFactId = $rId }
						elseif ($cmpId.Compare($rId, $kFirstFactId) -ne 0) { $kFactIdConflict = $true }
					}
				}
			}
		}
		finally { $kr.Dispose() }

		# --- Identity view: exactly one key per identity across the Users candidate. ---
		$byId = Join-Path $workDir 'by_id.csv'
		[void](script:Invoke-PaxExternalSort -InputPath $pairs -OutputPath $byId -KeyColumn @('Id', 'Side', 'SeqPad') -Comparer 'OrdinalIgnoreCase' -MemoryBudgetBytes $MemoryBudgetBytes -FanIn 8 -WorkRoot $workDir)
		$dr = [System.IO.StreamReader]::new($byId, $true)
		try {
			$null = script:Read-PaxCsvRecord -Reader $dr
			$haveI = $false; $iId = ''; $iFirstPad = ''; $iSplit = $false
			$rId2 = ''; $rPad2 = ''; $rSide2 = ''
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $dr
				$isEnd = ($null -eq $row)
				if (-not $isEnd) { $rId2 = [string]$row[0]; $rPad2 = [string]$row[1]; $rSide2 = [string]$row[2] }
				if ($haveI -and ($isEnd -or ($cmpId.Compare($rId2, $iId) -ne 0))) {
					if ($iSplit) { $splitIdentities++ }
					$haveI = $false
				}
				if ($isEnd) { break }
				if (-not $haveI) { $haveI = $true; $iId = $rId2; $iFirstPad = $rPad2; $iSplit = $false }
				if ($rSide2 -eq '0' -or $rSide2 -eq '1') {
					if ($rPad2 -ne $iFirstPad) { $iSplit = $true }
				}
			}
		}
		finally { $dr.Dispose() }
	}
	finally {
		if (Test-Path -LiteralPath $workDir) { try { Remove-Item -LiteralPath $workDir -Recurse -Force -ErrorAction SilentlyContinue } catch { } }
	}

	$passed = (($conflictingKeys -eq 0) -and ($splitIdentities -eq 0) -and ($orphanFactKeys -eq 0) -and ($mismatchedFactRows -eq 0))
	return @{
		Passed              = [bool]$passed
		ConflictingUserKeys = [int]$conflictingKeys
		SplitIdentities     = [int]$splitIdentities
		OrphanFactKeys      = [int]$orphanFactKeys
		MismatchedFactRows  = [int]$mismatchedFactRows
		UsersRows           = [int64]$usersRows
		FactRows            = [int64]$factRows
	}
}

function Invoke-PaxFactSeedAccelerator {
	<#
	.SYNOPSIS
		Prepare and publish the pair of Fact continuity seed maps through the embedded
		disk-backed seed builder.

	.DESCRIPTION
		Continuity seed preparation reads the whole append target once and folds it to
		distinct first-occurrence keys. On a large target that fold dominates the run, so
		this helper hands the fold to a small embedded builder that streams the CSV and
		accumulates keys in a temporary, disk-backed database with a fixed cache bound.
		Peak memory therefore does not grow with the target, and there is no row or key
		limit.

		The builder writes TEMPORARY seed files only and reports a machine-readable result
		file. This function reads that file rather than console text, and it publishes a
		seed only after BOTH temporary seeds exist, are non-empty, parse as JSON objects,
		and report non-negative counts. Any prior published seeds and the append target are
		left byte-for-byte unchanged unless that full validation passes.

		Three outcomes are distinguished. 'Success' means both seeds are published.
		'CompatibilityFallbackRequired' means the target holds a key form the builder is
		not proven to serialize identically; nothing is published, every temporary artifact
		is removed, and the caller runs the accepted implementation instead. 'Failed' means
		seed preparation must be abandoned so continuity is never silently changed.

		Only aggregate numeric progress reaches the log: rows read, key counts, and elapsed
		seconds. No key, row, field, file name, path, URL, identifier, or credential is
		emitted, and the temporary builder script is removed in a finally block.

	.OUTPUTS
		PSCustomObject with .Status, .MidCount, .ThreadCount, .RowsRead, .ElapsedSeconds,
		.ExitCode and .Reason.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $TargetFactCsv,
		[Parameter(Mandatory)] [string] $OutMidJsonPath,
		[Parameter(Mandatory)] [string] $OutThreadJsonPath,
		[Parameter(Mandatory)] [string] $PythonExe,
		[string[]] $LauncherArgs = @(),
		[Parameter(Mandatory)] [string] $ScriptDir,
		[double] $HeartbeatIntervalSeconds = 0
	)

	$pySource = @'
"""PAX Fact Continuity Seed Builder.

Streams a target Fact CSV once and folds it to the two continuity seed maps that
keep Message_Id and thread surrogates stable across runs. Keys accumulate in a
temporary, disk-backed database with a fixed cache bound, so peak memory does not
grow with the target and no row or key limit applies.

Only temporary outputs and one machine-readable result file are written; the
caller validates and publishes the pair.
"""

import csv
import json
import os
import sqlite3
import sys
import time

STATUS_SUCCESS = 'success'
STATUS_COMPAT = 'compatibility-fallback-required'
STATUS_FAILED = 'failed'

EXIT_SUCCESS = 0
EXIT_FAILED = 1
EXIT_COMPAT = 3

MIN_SUPPORTED = 0x20
MAX_SUPPORTED = 0x7E

INT32_MIN = -2147483648
INT32_MAX = 2147483647

BATCH_ROWS = 5000
FIELD_LIMIT = 16777216
CACHE_KIB = 2048
HEARTBEAT_ROW_STRIDE = 1000

_FOLD_TABLE = {c: c + 32 for c in range(0x41, 0x5B)}


def fold(text):
    """Fold ASCII A-Z to a-z and leave every other character untouched."""
    return text.translate(_FOLD_TABLE)


def is_supported(text):
    """Report whether every character lies in the range this builder is proven
    to serialize identically to the accepted implementation. A key outside that
    range is never normalized, rejected, or altered here; the whole build defers
    to the accepted implementation instead."""
    for ch in text:
        code = ord(ch)
        if code < MIN_SUPPORTED or code > MAX_SUPPORTED:
            return False
    return True


def parse_surrogate(text):
    """Accept an optional sign followed by ASCII digits, within signed 32-bit
    range. Every other form is a skip, matching the accepted implementation."""
    if text is None:
        return None
    trimmed = text.strip()
    if not trimmed:
        return None
    start = 0
    negative = False
    if trimmed[0] in '+-':
        negative = trimmed[0] == '-'
        start = 1
    digits = trimmed[start:]
    if not digits:
        return None
    for ch in digits:
        if ch < '0' or ch > '9':
            return None
    value = int(digits)
    if negative:
        value = -value
    if value < INT32_MIN or value > INT32_MAX:
        return None
    return value


def find_column(header, name):
    """Resolve a column index case-insensitively, keeping the last match so the
    resolution order matches the accepted implementation."""
    wanted = fold(name)
    found = -1
    for index, cell in enumerate(header):
        if fold(cell) == wanted:
            found = index
    return found


class Heartbeat(object):
    """Aggregate-only progress, never more often than the requested interval."""

    def __init__(self, interval, started):
        self.interval = interval
        self.started = started
        self.last = started

    def emit(self, rows, mid_keys, thread_keys, now, force=False):
        if self.interval <= 0:
            return
        if not force and (now - self.last) < self.interval:
            return
        self.last = now
        sys.stdout.write(
            'PAXSEED heartbeat rowsRead=%d midKeys=%d threadKeys=%d elapsedSeconds=%.1f\n'
            % (rows, mid_keys, thread_keys, now - self.started))
        sys.stdout.flush()


def remove_quietly(path):
    try:
        if path and os.path.exists(path):
            os.remove(path)
    except OSError:
        pass


_RECORD_BREAKS = ',\r\n'


class QuoteAudit(object):
    """Detect the one malformed quoting form the strict reader accepts but the
    accepted reader rejects: a quote inside an unquoted field. A quoted field may
    span physical lines, so the in-quotes state carries across them; a line that
    holds no quote can neither open nor close one, which keeps the scan off the
    hot path for ordinary rows."""

    def __init__(self):
        self.in_quotes = False
        self.divergent = False

    def scan(self, line):
        if not self.in_quotes and '"' not in line:
            return
        # 0 fresh, 1 unquoted, 2 inside quotes, 3 after a closing quote.
        state = 2 if self.in_quotes else 0
        for ch in line:
            if state == 0:
                if ch == '"':
                    state = 2
                elif ch not in _RECORD_BREAKS:
                    state = 1
            elif state == 1:
                if ch == '"':
                    self.divergent = True
                    return
                elif ch in _RECORD_BREAKS:
                    state = 0
            elif state == 2:
                if ch == '"':
                    state = 3
            else:
                if ch == '"':
                    state = 2
                elif ch in _RECORD_BREAKS:
                    state = 0
        self.in_quotes = state == 2


def audit_lines(handle, audit):
    """Feed the reader while auditing the same characters, so a divergent record
    is known as soon as the reader produces it and always before publication."""
    for line in handle:
        audit.scan(line)
        yield line


def write_seed(connection, table, path):
    """Stream one compact seed map in first-occurrence order, UTF-8 without a
    byte-order mark. An empty map is the literal two-character object."""
    count = 0
    with open(path, 'w', encoding='utf-8', newline='') as handle:
        handle.write('{')
        first = True
        cursor = connection.execute(
            'SELECT raw_key, surrogate_value FROM %s ORDER BY source_sequence' % table)
        for raw_key, surrogate in cursor:
            if not first:
                handle.write(',')
            handle.write(json.dumps(raw_key, ensure_ascii=True))
            handle.write(':')
            handle.write(str(int(surrogate)))
            first = False
            count += 1
        handle.write('}')
    return count


def build(target_csv, mid_temp, thread_temp, work_dir, interval):
    started = time.monotonic()
    beat = Heartbeat(interval, started)
    db_path = os.path.join(work_dir, 'pax_fact_seed.sqlite')
    remove_quietly(db_path)
    connection = sqlite3.connect(db_path, isolation_level=None)
    try:
        connection.execute('PRAGMA journal_mode = OFF')
        connection.execute('PRAGMA synchronous = OFF')
        connection.execute('PRAGMA temp_store = FILE')
        connection.execute('PRAGMA cache_size = -%d' % CACHE_KIB)
        for table in ('mid_seed', 'thread_seed'):
            connection.execute(
                'CREATE TABLE %s ('
                'normalized_key TEXT PRIMARY KEY, '
                'raw_key TEXT NOT NULL, '
                'source_sequence INTEGER NOT NULL, '
                'surrogate_value INTEGER NOT NULL)' % table)

        rows_read = 0
        mid_pairs = 0
        thread_pairs = 0
        with open(target_csv, 'r', encoding='utf-8-sig', newline='') as handle:
            # Strict parsing rejects content after a closing quote and an unterminated
            # quoted field at end of input, matching the accepted reader. The audit
            # closes the remaining divergence: a quote inside an unquoted field, which
            # the accepted reader rejects and the strict reader would accept.
            audit = QuoteAudit()
            reader = csv.reader(audit_lines(handle, audit), strict=True)
            try:
                header = next(reader)
            except StopIteration:
                header = None

            if header is not None:
                if header:
                    header[0] = header[0].lstrip('\ufeff')
                for cell in header:
                    if not is_supported(cell) or '"' in cell:
                        return (STATUS_COMPAT, 'unsupported-header-character',
                                0, 0, 0, time.monotonic() - started)
                seen = set()
                for cell in header:
                    folded = fold(cell)
                    if folded in seen:
                        return (STATUS_FAILED, 'duplicate-header',
                                0, 0, 0, time.monotonic() - started)
                    seen.add(folded)

                mid_raw_index = find_column(header, 'Message_Id_Raw')
                mid_value_index = find_column(header, 'Message_Id')
                thread_raw_index = find_column(header, 'ThreadId_Raw')
                thread_key_index = find_column(header, 'ThreadKey')
                thread_id_index = find_column(header, 'ThreadId')
                if thread_key_index >= 0:
                    thread_value_index = thread_key_index
                else:
                    thread_value_index = thread_id_index

                mid_batch = []
                thread_batch = []
                connection.execute('BEGIN')
                for row in reader:
                    # Every character of this record has already been audited.
                    if audit.divergent:
                        connection.execute('ROLLBACK')
                        return (STATUS_COMPAT, 'unquoted-field-quote',
                                0, 0, rows_read, time.monotonic() - started)
                    if 0 <= mid_raw_index < len(row):
                        raw_mid = row[mid_raw_index]
                    else:
                        raw_mid = ''
                    if raw_mid.strip():
                        if not is_supported(raw_mid):
                            connection.execute('ROLLBACK')
                            return (STATUS_COMPAT, 'unsupported-key-character',
                                    0, 0, rows_read, time.monotonic() - started)
                        if 0 <= mid_value_index < len(row):
                            text = row[mid_value_index]
                        else:
                            text = ''
                        # A quote character inside a consumed value cannot be told apart
                        # from a quote the accepted reader rejects, so adjudication is
                        # left to that reader.
                        if '"' in raw_mid or '"' in text:
                            connection.execute('ROLLBACK')
                            return (STATUS_COMPAT, 'ambiguous-quoting',
                                    0, 0, rows_read, time.monotonic() - started)
                        value = parse_surrogate(text)
                        if value is not None:
                            mid_batch.append((fold(raw_mid), raw_mid, rows_read, value))
                            mid_pairs += 1
                    if 0 <= thread_raw_index < len(row):
                        raw_thread = row[thread_raw_index]
                    else:
                        raw_thread = ''
                    if raw_thread.strip():
                        if not is_supported(raw_thread):
                            connection.execute('ROLLBACK')
                            return (STATUS_COMPAT, 'unsupported-key-character',
                                    0, 0, rows_read, time.monotonic() - started)
                        if 0 <= thread_value_index < len(row):
                            text = row[thread_value_index]
                        else:
                            text = ''
                        if '"' in raw_thread or '"' in text:
                            connection.execute('ROLLBACK')
                            return (STATUS_COMPAT, 'ambiguous-quoting',
                                    0, 0, rows_read, time.monotonic() - started)
                        value = parse_surrogate(text)
                        if value is not None:
                            thread_batch.append((fold(raw_thread), raw_thread, rows_read, value))
                            thread_pairs += 1
                    rows_read += 1
                    if len(mid_batch) >= BATCH_ROWS:
                        connection.executemany(
                            'INSERT OR IGNORE INTO mid_seed VALUES (?, ?, ?, ?)', mid_batch)
                        del mid_batch[:]
                    if len(thread_batch) >= BATCH_ROWS:
                        connection.executemany(
                            'INSERT OR IGNORE INTO thread_seed VALUES (?, ?, ?, ?)', thread_batch)
                        del thread_batch[:]
                    if (rows_read % HEARTBEAT_ROW_STRIDE) == 0:
                        beat.emit(rows_read, mid_pairs, thread_pairs, time.monotonic())
                if mid_batch:
                    connection.executemany(
                        'INSERT OR IGNORE INTO mid_seed VALUES (?, ?, ?, ?)', mid_batch)
                    del mid_batch[:]
                if thread_batch:
                    connection.executemany(
                        'INSERT OR IGNORE INTO thread_seed VALUES (?, ?, ?, ?)', thread_batch)
                    del thread_batch[:]
                connection.execute('COMMIT')

        connection.execute('CREATE INDEX ix_mid_seq ON mid_seed(source_sequence)')
        connection.execute('CREATE INDEX ix_thread_seq ON thread_seed(source_sequence)')
        mid_count = write_seed(connection, 'mid_seed', mid_temp)
        thread_count = write_seed(connection, 'thread_seed', thread_temp)
        elapsed = time.monotonic() - started
        beat.emit(rows_read, mid_count, thread_count, time.monotonic(), True)
        return (STATUS_SUCCESS, '', mid_count, thread_count, rows_read, elapsed)
    finally:
        try:
            connection.close()
        finally:
            remove_quietly(db_path)
            remove_quietly(db_path + '-journal')
            remove_quietly(db_path + '-wal')
            remove_quietly(db_path + '-shm')


def main(argv):
    if len(argv) != 7:
        return EXIT_FAILED
    target_csv = argv[1]
    mid_temp = argv[2]
    thread_temp = argv[3]
    work_dir = argv[4]
    try:
        interval = float(argv[5])
    except ValueError:
        interval = 0.0
    result_path = argv[6]

    status = STATUS_FAILED
    reason = 'unexpected-error'
    mid_count = 0
    thread_count = 0
    rows_read = 0
    elapsed = 0.0
    try:
        csv.field_size_limit(FIELD_LIMIT)
        status, reason, mid_count, thread_count, rows_read, elapsed = build(
            target_csv, mid_temp, thread_temp, work_dir, interval)
    except csv.Error:
        status, reason = STATUS_FAILED, 'csv-error'
    except sqlite3.Error:
        status, reason = STATUS_FAILED, 'sqlite-error'
    except UnicodeDecodeError:
        status, reason = STATUS_FAILED, 'encoding-error'
    except OSError:
        status, reason = STATUS_FAILED, 'io-error'
    except Exception:
        status, reason = STATUS_FAILED, 'unexpected-error'

    if status != STATUS_SUCCESS:
        mid_count = 0
        thread_count = 0
        remove_quietly(mid_temp)
        remove_quietly(thread_temp)

    payload = {
        'status': status,
        'reason': reason,
        'rowsRead': rows_read,
        'midKeyCount': mid_count,
        'threadKeyCount': thread_count,
        'elapsedSeconds': round(elapsed, 3),
    }
    try:
        with open(result_path, 'w', encoding='utf-8', newline='') as handle:
            json.dump(payload, handle)
    except OSError:
        return EXIT_FAILED

    if status == STATUS_SUCCESS:
        return EXIT_SUCCESS
    if status == STATUS_COMPAT:
        return EXIT_COMPAT
    return EXIT_FAILED


if __name__ == '__main__':
    sys.exit(main(sys.argv))
'@

	if (-not (Test-Path -LiteralPath $TargetFactCsv -PathType Leaf)) {
		throw "Invoke-PaxFactSeedAccelerator: target Fact CSV not found: '$TargetFactCsv'"
	}

	$inv = [System.Globalization.CultureInfo]::InvariantCulture
	$workRootBase = $env:TEMP; if (-not $workRootBase) { $workRootBase = [System.IO.Path]::GetTempPath() }
	$workDir = Join-Path $workRootBase ('pax_factseedpy_{0}' -f ([System.Guid]::NewGuid().ToString('N')))
	$midTemp = $OutMidJsonPath + '.pyseedtmp'
	$threadTemp = $OutThreadJsonPath + '.pyseedtmp'
	$resultPath = Join-Path $workDir 'seed_result.json'
	$tempPyPath = Join-Path $ScriptDir ('PAX_FactContinuitySeedBuilder_{0}.py' -f ([System.Guid]::NewGuid().ToString('N')))
	# Stage records are routed through a host lookup so the function stays inert when it
	# is extracted and exercised on its own.
	$__paxStage = Microsoft.PowerShell.Core\Get-Command -Name 'Write-PaxRollupStage' -CommandType Function -ErrorAction SilentlyContinue

	$status = 'Failed'
	$reason = 'not-started'
	$rowsRead = [int64]0
	$midCount = 0
	$threadCount = 0
	$elapsedSeconds = [double]0
	$exitCode = -1

	try {
		[void][System.IO.Directory]::CreateDirectory($workDir)
		if (-not (Test-Path -LiteralPath $ScriptDir -PathType Container)) {
			[void][System.IO.Directory]::CreateDirectory($ScriptDir)
		}
		[System.IO.File]::WriteAllText($tempPyPath, $pySource, [System.Text.UTF8Encoding]::new($false))

		$builderArgs = @($LauncherArgs) + @(
			$tempPyPath
			$TargetFactCsv
			$midTemp
			$threadTemp
			$workDir
			([double]$HeartbeatIntervalSeconds).ToString($inv)
			$resultPath
		)
		$prevPyIoEnc = $env:PYTHONIOENCODING
		try {
			$env:PYTHONIOENCODING = 'utf-8'
			# Only a line matching this exact aggregate shape is forwarded; every other
			# byte the builder writes is dropped, so no key, row, path, or identifier can
			# reach the log through this channel.
			& $PythonExe @builderArgs 2>&1 | ForEach-Object {
				$line = [string]$_
				if ($line -match '^PAXSEED heartbeat rowsRead=(\d+) midKeys=(\d+) threadKeys=(\d+) elapsedSeconds=(\d+(?:\.\d+)?)$') {
					if ($__paxStage) {
						try {
							& $__paxStage -Stage 'fact-seed' -Status 'heartbeat' -Counters @{
								rowsRead       = [int64]$Matches[1]
								midKeys        = [int64]$Matches[2]
								threadKeys     = [int64]$Matches[3]
								elapsedSeconds = [double]::Parse($Matches[4], $inv)
							}
						}
						catch { }
					}
				}
			}
			$exitCode = [int]$LASTEXITCODE
		}
		finally {
			if ($null -eq $prevPyIoEnc) { Remove-Item Env:PYTHONIOENCODING -ErrorAction SilentlyContinue }
			else { $env:PYTHONIOENCODING = $prevPyIoEnc }
		}

		# Machine-readable outcome only; console text is never parsed.
		$payload = $null
		if (Test-Path -LiteralPath $resultPath -PathType Leaf) {
			try { $payload = (Get-Content -LiteralPath $resultPath -Raw -Encoding UTF8) | ConvertFrom-Json -ErrorAction Stop }
			catch { $payload = $null }
		}
		if ($null -eq $payload) {
			$status = 'Failed'
			$reason = 'missing-result'
		}
		else {
			$rowsRead = [int64]$payload.rowsRead
			$elapsedSeconds = [double]$payload.elapsedSeconds
			$reason = [string]$payload.reason
			switch ([string]$payload.status) {
				'success' {
					$status = if ($exitCode -eq 0) { 'Success' } else { 'Failed' }
					if ($status -eq 'Failed') { $reason = 'exit-code-mismatch' }
					$midCount = [int]$payload.midKeyCount
					$threadCount = [int]$payload.threadKeyCount
				}
				'compatibility-fallback-required' { $status = 'CompatibilityFallbackRequired' }
				default { $status = 'Failed' }
			}
		}

		if ($status -eq 'Success') {
			# Paired publication: verify BOTH temporary seeds before either is moved.
			foreach ($tp in @($midTemp, $threadTemp)) {
				if (-not (Test-Path -LiteralPath $tp -PathType Leaf)) {
					$status = 'Failed'; $reason = 'missing-temp-seed'; break
				}
				if ([int64](Get-Item -LiteralPath $tp).Length -le 0) {
					$status = 'Failed'; $reason = 'empty-temp-seed'; break
				}
				$parsed = $null
				try { $parsed = (Get-Content -LiteralPath $tp -Raw -Encoding UTF8) | ConvertFrom-Json -ErrorAction Stop }
				catch { $parsed = $null }
				if ($null -eq $parsed -or -not ($parsed -is [System.Management.Automation.PSCustomObject])) {
					$status = 'Failed'; $reason = 'invalid-temp-seed'; break
				}
			}
		}
		if ($status -eq 'Success' -and (($midCount -lt 0) -or ($threadCount -lt 0))) {
			$status = 'Failed'; $reason = 'negative-count'
		}

		if ($status -eq 'Success') {
			if ($__paxStage) {
				try {
					& $__paxStage -Stage 'fact-seed-validate' -Status 'complete' -Counters @{
						midKeys     = [int64]$midCount
						threadKeys  = [int64]$threadCount
						midBytes    = [int64](Get-Item -LiteralPath $midTemp).Length
						threadBytes = [int64](Get-Item -LiteralPath $threadTemp).Length
					}
				}
				catch { }
			}
			foreach ($pair in @(@($midTemp, $OutMidJsonPath), @($threadTemp, $OutThreadJsonPath))) {
				$outDir = Split-Path -Parent $pair[1]
				if ($outDir -and -not (Test-Path -LiteralPath $outDir -PathType Container)) {
					New-Item -ItemType Directory -Path $outDir -Force -ErrorAction Stop | Out-Null
				}
			}
			# Publish as a pair. If the second move fails the first is rolled back, so a
			# result never leaves one seed published against a stale partner.
			$midRollback = $null
			$midExisted = Test-Path -LiteralPath $OutMidJsonPath -PathType Leaf
			if ($midExisted) {
				$midRollback = $OutMidJsonPath + '.pyseedbak'
				Copy-Item -LiteralPath $OutMidJsonPath -Destination $midRollback -Force -ErrorAction Stop
			}
			try {
				Move-Item -LiteralPath $midTemp -Destination $OutMidJsonPath -Force -ErrorAction Stop
				Move-Item -LiteralPath $threadTemp -Destination $OutThreadJsonPath -Force -ErrorAction Stop
			}
			catch {
				if ($midRollback -and (Test-Path -LiteralPath $midRollback -PathType Leaf)) {
					try { Move-Item -LiteralPath $midRollback -Destination $OutMidJsonPath -Force -ErrorAction Stop } catch { }
				}
				elseif ((-not $midExisted) -and (Test-Path -LiteralPath $OutMidJsonPath -PathType Leaf)) {
					try { Remove-Item -LiteralPath $OutMidJsonPath -Force -ErrorAction SilentlyContinue } catch { }
				}
				throw
			}
			finally {
				if ($midRollback -and (Test-Path -LiteralPath $midRollback)) { try { Remove-Item -LiteralPath $midRollback -Force -ErrorAction SilentlyContinue } catch { } }
			}
		}
	}
	catch {
		$status = 'Failed'
		$reason = 'accelerator-error'
	}
	finally {
		# The temporary builder script, the temporary database, and any unpublished
		# temporary seed are always removed. Published seeds are never touched here.
		if (Test-Path -LiteralPath $tempPyPath) { try { Remove-Item -LiteralPath $tempPyPath -Force -ErrorAction SilentlyContinue } catch {} }
		foreach ($tp in @($midTemp, $threadTemp, ($OutMidJsonPath + '.pyseedbak'))) {
			if (Test-Path -LiteralPath $tp) { try { Remove-Item -LiteralPath $tp -Force -ErrorAction SilentlyContinue } catch {} }
		}
		if (Test-Path -LiteralPath $workDir) { try { Remove-Item -LiteralPath $workDir -Recurse -Force -ErrorAction SilentlyContinue } catch {} }
	}

	if ($status -ne 'Success') { $midCount = 0; $threadCount = 0 }
	return [PSCustomObject]@{
		Status         = $status
		MidCount       = $midCount
		ThreadCount    = $threadCount
		RowsRead       = $rowsRead
		ElapsedSeconds = $elapsedSeconds
		ExitCode       = $exitCode
		Reason         = $reason
	}
}

function ConvertTo-FactSeedMaps {
	<#
	.SYNOPSIS
		Extract {Message_Id_Raw -> Message_Id (INT)} and {ThreadId_Raw -> ThreadKey (INT)}
		from a target CopilotInteraction Fact CSV and write each as a compact JSON file
		the embedded processor consumes via `--seed-mid-map` / `--seed-thread-map`.

	.DESCRIPTION
		Pre-flight helper for -AppendFile (CopilotInteraction rollup mode). Reads the
		existing target Fact CSV produced by a prior run and builds two seed maps keyed
		by the raw GUID columns. First case-insensitive occurrence wins; rows with a
		blank raw GUID or a non-integer surrogate are skipped.

		The target is never materialized in full. Each row streams exactly once through
		the RFC-4180 reader; valid (raw-key, sequence, integer) pairs for each map are
		spilled to bounded temporary CSVs and folded to distinct first-occurrence keys
		using only the frozen external-sort machinery, then the compact seed JSON is
		streamed one property at a time. Peak memory is governed by a fixed byte budget
		rather than by the target size, and no row, key, or JSON property set is held
		whole in memory.

		The seed JSON bytes are identical to the prior in-memory implementation: each
		property is produced by ConvertTo-Json of a single-property ordered object with
		its outer braces removed, so key escaping and integer formatting are unchanged,
		an empty map is the literal '{}', and property order is first-occurrence order.
		Neither seed file is published until both are complete and validated; on any
		failure the function raises a terminating error, leaves any prior seed outputs
		byte-for-byte unchanged, publishes no partial output, and removes its temporary
		work. There is no in-memory fallback.

	.OUTPUTS
		PSCustomObject with .MidCount and .ThreadCount integer fields.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $TargetFactCsv,
		[Parameter(Mandatory)] [string] $OutMidJsonPath,
		[Parameter(Mandatory)] [string] $OutThreadJsonPath,
		# Fixed in-memory buffer budget for the bounded sorts (bytes). It governs only
		# WHEN buffered pairs spill to run files; it never caps how many rows or keys
		# are processed. A small value is used by tests to force multi-run spilling.
		[int64] $MemoryBudgetBytes = 33554432,
		# Observability-only progress seam, inert by default. It is forwarded verbatim to
		# the bounded sorts, which pass the callback an AGGREGATE snapshot only and swallow
		# any exception it raises. Supplying it cannot change either seed JSON's bytes, the
		# key sets, the ordering, or the paired fail-closed publication.
		[scriptblock] $ProgressCallback,
		[double] $ProgressIntervalSeconds = 0
	)
	if (-not (Test-Path -LiteralPath $TargetFactCsv -PathType Leaf)) {
		throw "ConvertTo-FactSeedMaps: target Fact CSV not found: '$TargetFactCsv'"
	}

	# Build one compact seed JSON at $OutTempJsonPath from a normalized pairs CSV
	# (header RawKey,SeqPad,Val; one row per source row). Distinct keys are folded
	# case-insensitively (first original occurrence wins, first casing + first value
	# kept) by two bounded external sorts and a streaming first-per-key pass; the
	# JSON is streamed one single-property object at a time. Returns the distinct
	# key count. Defined inline so the whole streaming contract lives in this one
	# extractable function.
	$buildSeedJson = {
		param([string]$PairsCsvPath, [string]$OutTempJsonPath, [string]$WorkDir, [string]$Tag, [int64]$Budget, [scriptblock]$Progress, [double]$ProgressInterval)
		$u8 = [System.Text.UTF8Encoding]::new($false)
		$byKeyPath = Join-Path $WorkDir ($Tag + '_bykey.csv')
		$firstPath = Join-Path $WorkDir ($Tag + '_first.csv')
		$bySeqPath = Join-Path $WorkDir ($Tag + '_byseq.csv')
		# 1) Sort by (RawKey, SeqPad) case-insensitively so equal keys are adjacent and
		#    ascending by original sequence within each key group.
		[void](script:Invoke-PaxExternalSort -InputPath $PairsCsvPath -OutputPath $byKeyPath -KeyColumn @('RawKey', 'SeqPad') -Comparer 'OrdinalIgnoreCase' -MemoryBudgetBytes $Budget -FanIn 8 -WorkRoot $WorkDir -ProgressCallback $Progress -ProgressIntervalSeconds $ProgressInterval)
		# 2) Emit the first row of each case-insensitive key group (lowest sequence),
		#    keeping that first row's original key casing and value.
		$cmp = script:Get-PaxComparer -Name 'OrdinalIgnoreCase'
		$r1 = [System.IO.StreamReader]::new($byKeyPath, $true)
		$w1 = [System.IO.StreamWriter]::new($firstPath, $false, $u8)
		$distinct = [int64]0
		try {
			$null = script:Read-PaxCsvRecord -Reader $r1
			script:Write-PaxCsvRecord -Writer $w1 -Fields @('RawKey', 'SeqPad', 'Val')
			$haveLast = $false; $lastKey = $null
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $r1
				if ($null -eq $row) { break }
				$k = if ($row.Length -ge 1) { [string]$row[0] } else { '' }
				if ((-not $haveLast) -or ($cmp.Compare($k, $lastKey) -ne 0)) {
					script:Write-PaxCsvRecord -Writer $w1 -Fields $row
					$distinct++
					$lastKey = $k; $haveLast = $true
				}
			}
		}
		finally { $w1.Flush(); $w1.Dispose(); $r1.Dispose() }
		# 3) Restore first-occurrence order (ascending original sequence).
		[void](script:Invoke-PaxExternalSort -InputPath $firstPath -OutputPath $bySeqPath -KeyColumn @('SeqPad') -Comparer 'Ordinal' -MemoryBudgetBytes $Budget -FanIn 8 -WorkRoot $WorkDir -ProgressCallback $Progress -ProgressIntervalSeconds $ProgressInterval)
		# 4) Stream the compact JSON object one property at a time. Each property's
		#    exact bytes come from ConvertTo-Json of a single-property ordered object
		#    with its outer braces removed, so escaping and integer formatting match the
		#    prior implementation byte-for-byte. An empty map emits the literal '{}'.
		$r2 = [System.IO.StreamReader]::new($bySeqPath, $true)
		$w2 = [System.IO.StreamWriter]::new($OutTempJsonPath, $false, $u8)
		try {
			$null = script:Read-PaxCsvRecord -Reader $r2
			$w2.Write('{')
			$wrote = $false
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $r2
				if ($null -eq $row) { break }
				$rawKey = [string]$row[0]
				$valStr = if ($row.Length -ge 3) { [string]$row[2] } else { '0' }
				$obj = [ordered]@{}
				$obj[$rawKey] = [int]::Parse($valStr, [System.Globalization.CultureInfo]::InvariantCulture)
				$oneLine = $obj | ConvertTo-Json -Compress -Depth 2
				$inner = $oneLine.Substring(1, $oneLine.Length - 2)
				if ($wrote) { $w2.Write(',') }
				$w2.Write($inner)
				$wrote = $true
			}
			$w2.Write('}')
		}
		finally { $w2.Flush(); $w2.Dispose(); $r2.Dispose() }
		return $distinct
	}

	$workRootBase = $env:TEMP; if (-not $workRootBase) { $workRootBase = [System.IO.Path]::GetTempPath() }
	$workDir = Join-Path $workRootBase ('pax_factseed_{0}' -f ([System.Guid]::NewGuid().ToString('N')))
	$midTemp = $OutMidJsonPath + '.seedtmp'
	$threadTemp = $OutThreadJsonPath + '.seedtmp'
	$midCount = 0
	$threadCount = 0
	try {
		[void][System.IO.Directory]::CreateDirectory($workDir)
		$midPairs = Join-Path $workDir 'mid_pairs.csv'
		$threadPairs = Join-Path $workDir 'thread_pairs.csv'
		$utf8NoBom = [System.Text.UTF8Encoding]::new($false)

		# --- Single streaming pass over the target: emit normalized (RawKey,SeqPad,Val)
		#     pair rows for each map. The complete target is never materialized. ---
		$reader = [System.IO.StreamReader]::new($TargetFactCsv, $true)
		$mw = [System.IO.StreamWriter]::new($midPairs, $false, $utf8NoBom)
		$tw = [System.IO.StreamWriter]::new($threadPairs, $false, $utf8NoBom)
		try {
			script:Write-PaxCsvRecord -Writer $mw -Fields @('RawKey', 'SeqPad', 'Val')
			script:Write-PaxCsvRecord -Writer $tw -Fields @('RawKey', 'SeqPad', 'Val')
			$header = script:Read-PaxCsvRecord -Reader $reader
			if ($null -ne $header) {
				# Reject duplicate header columns (case-insensitive), matching the prior
				# reader's fail-closed behavior on a duplicated member.
				$seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
				foreach ($h in $header) {
					if (-not $seen.Add([string]$h)) { throw "ConvertTo-FactSeedMaps: duplicate header column '$h' in target Fact CSV." }
				}
				$midRawIdx = -1; $midValIdx = -1; $threadRawIdx = -1; $threadKeyIdx = -1; $threadIdIdx = -1
				for ($i = 0; $i -lt $header.Length; $i++) {
					$name = [string]$header[$i]
					if ([string]::Equals($name, 'Message_Id_Raw', [System.StringComparison]::OrdinalIgnoreCase)) { $midRawIdx = $i }
					elseif ([string]::Equals($name, 'Message_Id', [System.StringComparison]::OrdinalIgnoreCase)) { $midValIdx = $i }
					elseif ([string]::Equals($name, 'ThreadId_Raw', [System.StringComparison]::OrdinalIgnoreCase)) { $threadRawIdx = $i }
					elseif ([string]::Equals($name, 'ThreadKey', [System.StringComparison]::OrdinalIgnoreCase)) { $threadKeyIdx = $i }
					elseif ([string]::Equals($name, 'ThreadId', [System.StringComparison]::OrdinalIgnoreCase)) { $threadIdIdx = $i }
				}
				# ThreadKey overrides ThreadId as the thread surrogate when present.
				$threadValIdx = if ($threadKeyIdx -ge 0) { $threadKeyIdx } else { $threadIdIdx }
				$inv = [System.Globalization.CultureInfo]::InvariantCulture
				$seq = [int64]0
				while ($true) {
					$row = script:Read-PaxCsvRecord -Reader $reader
					if ($null -eq $row) { break }
					$seqPad = $seq.ToString('D19', $inv)
					$midRaw = if ($midRawIdx -ge 0 -and $midRawIdx -lt $row.Length) { [string]$row[$midRawIdx] } else { '' }
					if (-not [string]::IsNullOrWhiteSpace($midRaw)) {
						$midValStr = if ($midValIdx -ge 0 -and $midValIdx -lt $row.Length) { [string]$row[$midValIdx] } else { '' }
						$midInt = 0
						if ([int]::TryParse($midValStr, [ref]$midInt)) {
							script:Write-PaxCsvRecord -Writer $mw -Fields @($midRaw, $seqPad, $midInt.ToString($inv))
						}
					}
					$threadRaw = if ($threadRawIdx -ge 0 -and $threadRawIdx -lt $row.Length) { [string]$row[$threadRawIdx] } else { '' }
					if (-not [string]::IsNullOrWhiteSpace($threadRaw)) {
						$threadValStr = if ($threadValIdx -ge 0 -and $threadValIdx -lt $row.Length) { [string]$row[$threadValIdx] } else { '' }
						$threadInt = 0
						if ([int]::TryParse($threadValStr, [ref]$threadInt)) {
							script:Write-PaxCsvRecord -Writer $tw -Fields @($threadRaw, $seqPad, $threadInt.ToString($inv))
						}
					}
					$seq++
				}
			}
		}
		finally {
			$mw.Flush(); $mw.Dispose(); $tw.Flush(); $tw.Dispose(); $reader.Dispose()
		}

		# --- Build each seed JSON to a temp sibling using only bounded machinery. ---
		$midCount = [int](& $buildSeedJson $midPairs $midTemp $workDir 'mid' $MemoryBudgetBytes $ProgressCallback $ProgressIntervalSeconds)
		$threadCount = [int](& $buildSeedJson $threadPairs $threadTemp $workDir 'thread' $MemoryBudgetBytes $ProgressCallback $ProgressIntervalSeconds)

		# --- Validate both completed temp files parse before either is published. ---
		foreach ($tp in @($midTemp, $threadTemp)) {
			try { $null = (Get-Content -LiteralPath $tp -Raw -Encoding UTF8) | ConvertFrom-Json -ErrorAction Stop }
			catch { throw "ConvertTo-FactSeedMaps: seed JSON validation failed for '$tp': $($_.Exception.Message)" }
		}

		# Aggregate-only stage record for the validated pair, emitted before publication.
		# Routed through a host lookup so the function stays inert when it is extracted and
		# exercised on its own.
		$__paxStage = Microsoft.PowerShell.Core\Get-Command -Name 'Write-PaxRollupStage' -CommandType Function -ErrorAction SilentlyContinue
		if ($__paxStage) {
			$__midBytes = try { [int64](Get-Item -LiteralPath $midTemp).Length } catch { [int64]0 }
			$__thrBytes = try { [int64](Get-Item -LiteralPath $threadTemp).Length } catch { [int64]0 }
			try {
				& $__paxStage -Stage 'fact-seed-validate' -Status 'complete' -Counters @{
					midKeys    = [int64]$midCount
					threadKeys = [int64]$threadCount
					midBytes   = $__midBytes
					threadBytes = $__thrBytes
				}
			} catch { }
		}

		# --- Publish only after both seeds are complete and valid. Prior published
		#     seeds are never touched before this point. ---
		foreach ($pair in @(@($midTemp, $OutMidJsonPath), @($threadTemp, $OutThreadJsonPath))) {
			$outDir = Split-Path -Parent $pair[1]
			if ($outDir -and -not (Test-Path -LiteralPath $outDir -PathType Container)) {
				New-Item -ItemType Directory -Path $outDir -Force | Out-Null
			}
		}
		Move-Item -LiteralPath $midTemp -Destination $OutMidJsonPath -Force -ErrorAction Stop
		Move-Item -LiteralPath $threadTemp -Destination $OutThreadJsonPath -Force -ErrorAction Stop
	}
	catch {
		# Fail closed: remove any unpublished temp siblings so no partial seed is left
		# behind, then re-raise. Prior published seed files are never modified before
		# the paired publication step above.
		foreach ($tp in @($midTemp, $threadTemp)) {
			if (Test-Path -LiteralPath $tp) { try { Remove-Item -LiteralPath $tp -Force -ErrorAction SilentlyContinue } catch {} }
		}
		throw
	}
	finally {
		if (Test-Path -LiteralPath $workDir) { try { Remove-Item -LiteralPath $workDir -Recurse -Force -ErrorAction SilentlyContinue } catch {} }
	}
	return [PSCustomObject]@{
		MidCount    = $midCount
		ThreadCount = $threadCount
	}
}

function ConvertTo-RecordIdExclusion {
	<#
	.SYNOPSIS
		Extract the RecordId column from a target exploded/event-level CSV and write a
		newline-delimited file the embedded M365Bundle processor consumes via
		`--exclude-record-ids` for cross-run dedup.

	.DESCRIPTION
		Pre-flight helper for -AppendFile (M365Bundle event-level mode / -RollupPlusRaw
		raw-CSV append). Streams the target CSV without loading the full row set, finds
		the RecordId column index from the header, and writes one RecordId per line.
		Blank / duplicate RecordIds are skipped.

	.OUTPUTS
		Int count of unique RecordIds written.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $TargetCsv,
		[Parameter(Mandatory)] [string] $OutListPath
	)
	if (-not (Test-Path -LiteralPath $TargetCsv -PathType Leaf)) {
		throw "ConvertTo-RecordIdExclusion: target CSV not found: '$TargetCsv'"
	}
	$utf8NoBom = [System.Text.UTF8Encoding]::new($false)
	$outDir = Split-Path -Parent $OutListPath
	if ($outDir -and -not (Test-Path -LiteralPath $outDir -PathType Container)) {
		New-Item -ItemType Directory -Path $outDir -Force | Out-Null
	}
	$reader = $null
	$writer = $null
	$seen   = [System.Collections.Generic.HashSet[string]]::new()
	try {
		$reader = [System.IO.StreamReader]::new($TargetCsv, [System.Text.Encoding]::UTF8)
		$headerLine = $reader.ReadLine()
		if (-not $headerLine) { return 0 }
		# Tolerate UTF-8 BOM on header
		if ($headerLine.Length -gt 0 -and [int][char]$headerLine[0] -eq 0xFEFF) {
			$headerLine = $headerLine.Substring(1)
		}
		$cols = $headerLine.Split(',')
		$ridIdx = -1
		for ($i = 0; $i -lt $cols.Length; $i++) {
			$name = $cols[$i].Trim().Trim('"')
			if ($name -eq 'RecordId') { $ridIdx = $i; break }
		}
		if ($ridIdx -lt 0) {
			throw "ConvertTo-RecordIdExclusion: 'RecordId' column not found in '$TargetCsv'."
		}
		$writer = [System.IO.StreamWriter]::new($OutListPath, $false, $utf8NoBom)
		while (-not $reader.EndOfStream) {
			$line = $reader.ReadLine()
			if ([string]::IsNullOrEmpty($line)) { continue }
			# Lightweight CSV split that respects double-quoted fields containing commas.
			$fields = [System.Collections.Generic.List[string]]::new()
			$buf = [System.Text.StringBuilder]::new()
			$inQ = $false
			for ($j = 0; $j -lt $line.Length; $j++) {
				$ch = $line[$j]
				if ($ch -eq '"') { $inQ = -not $inQ; continue }
				if ($ch -eq ',' -and -not $inQ) {
					[void]$fields.Add($buf.ToString()); [void]$buf.Clear(); continue
				}
				[void]$buf.Append($ch)
			}
			[void]$fields.Add($buf.ToString())
			if ($ridIdx -ge $fields.Count) { continue }
			$rid = $fields[$ridIdx].Trim()
			if ([string]::IsNullOrEmpty($rid)) { continue }
			if ($seen.Add($rid)) {
				$writer.WriteLine($rid)
			}
		}
	}
	finally {
		if ($writer) { $writer.Dispose() }
		if ($reader) { $reader.Dispose() }
	}
	return $seen.Count
}

function script:Import-CsvDeduped {
	<#
	.SYNOPSIS
		Import-Csv wrapper that tolerates duplicate / BOM-prefixed / whitespace-padded
		header columns. Required when reading Users CSVs that may have round-tripped
		through the embedded Python processor and acquired duplicate header tokens
		(e.g. both 'userPrincipalName' and 'PersonId' present pre-rename).

	.DESCRIPTION
		PowerShell's Import-Csv calls Add-Member internally for each header cell, which
		throws 'The member "X" is already present' when two header cells normalize to
		the same name. This helper rewrites the header line with later duplicates
		suffixed (_dup2, _dup3, …) before parsing, so the file always loads. The first
		occurrence keeps its original name; callers that care can drop the *_dup* extras.

		Also strips a leading BOM from the header line and trims whitespace from each
		header cell. The data rows are passed through unchanged.

	.OUTPUTS
		Array of [pscustomobject]. Empty array if file is missing or contains only a
		header (or only whitespace).
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)][string]$LiteralPath)
	if (-not (Test-Path -LiteralPath $LiteralPath -PathType Leaf)) { return @() }
	$lines = @(Get-Content -LiteralPath $LiteralPath -Encoding UTF8)
	if ($lines.Count -eq 0) { return @() }
	$hdrLine = $lines[0] -replace '^\uFEFF',''
	# Parse header honoring quoted commas using TextFieldParser.
	try { Add-Type -AssemblyName Microsoft.VisualBasic -ErrorAction Stop } catch { }
	$sr = [System.IO.StringReader]::new($hdrLine)
	$tfp = New-Object Microsoft.VisualBasic.FileIO.TextFieldParser($sr)
	$tfp.SetDelimiters(',')
	$tfp.HasFieldsEnclosedInQuotes = $true
	$hdrCells = @()
	try { $hdrCells = @($tfp.ReadFields()) } catch { $hdrCells = @($hdrLine -split ',') }
	finally { $tfp.Dispose(); $sr.Dispose() }
	$seen = [System.Collections.Generic.Dictionary[string,int]]::new([System.StringComparer]::OrdinalIgnoreCase)
	$newHdr = New-Object System.Collections.Generic.List[string]
	foreach ($c in $hdrCells) {
		$n = ($c -as [string])
		if ($null -eq $n) { $n = '' }
		$n = $n.Trim()
		if ([string]::IsNullOrEmpty($n)) { $n = '_blank' }
		if ($seen.ContainsKey($n)) {
			$seen[$n] = $seen[$n] + 1
			$newHdr.Add(('{0}_dup{1}' -f $n, $seen[$n]))
		} else {
			$seen[$n] = 1
			$newHdr.Add($n)
		}
	}
	$newHdrLine = ($newHdr | ForEach-Object { '"' + ($_ -replace '"','""') + '"' }) -join ','
	if ($lines.Count -eq 1) { return @() }
	$rest = $lines | Select-Object -Skip 1
	$rewritten = @($newHdrLine) + @($rest)
	return @($rewritten | ConvertFrom-Csv)
}

function Merge-UsersCsv {
	<#
	.SYNOPSIS
		Union-merge a target Users CSV with the current run's freshly-emitted Users CSV.

	.DESCRIPTION
		Post-Python helper for -AppendUserInfo. Reads both files and writes a single union
		CSV. By default the union is written in place of the current-run CSV (legacy
		behavior). Pass -OutputPath to direct the union to a third path so the current-run
		CSV remains pristine (the pristine-raw separation pattern used by -AppendUserInfo).
		Semantics:
		  - Retained users (in BOTH): keep target's UserKey + Date_Added; In_Latest_Append=TRUE.
		  - New users (only in current run): mint Date_Added=today; In_Latest_Append=TRUE.
		  - Departed users (only in target): carry target row forward; In_Latest_Append=FALSE.
		  - Latest_Append_Date stamped today on every row.
		  - TotalEmployees recomputed across the union and rewritten on every row.

		Atomic rewrite: writes to '<output>.merging' then renames over the output path.

	.OUTPUTS
		Hashtable with stats (Retained / New / Departed / Union).
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $TargetUsersCsv,
		[Parameter(Mandatory)] [string] $CurrentUsersCsv,
		[Parameter()]          [string] $OutputPath,
		[Parameter()]          [string] $RunDate = (Get-Date -Format 'yyyy-MM-dd'),
		# Fixed in-memory buffer budget for the bounded sorts (bytes). Governs only
		# WHEN buffered rows spill; never caps how many rows are processed.
		[int64]                $MemoryBudgetBytes = 33554432,
		# Observability-only progress seam, inert by default. It is forwarded verbatim to
		# the bounded sorts, which pass the callback an AGGREGATE snapshot only and swallow
		# any exception it raises. Supplying it cannot change the merged output, the row
		# order, the classification counts, or the success of the merge.
		[scriptblock]          $ProgressCallback,
		[double]               $ProgressIntervalSeconds = 0
	)
	if (-not (Test-Path -LiteralPath $CurrentUsersCsv -PathType Leaf)) {
		throw "Merge-UsersCsv: current Users CSV not found: '$CurrentUsersCsv'"
	}
	if ([string]::IsNullOrWhiteSpace($OutputPath)) { $OutputPath = $CurrentUsersCsv }

	$inv = [System.Globalization.CultureInfo]::InvariantCulture
	$u8 = [System.Text.UTF8Encoding]::new($false)

	# Read + dedupe a CSV header record (BOM strip / trim / blank->_blank / _dupN)
	# exactly as script:Import-CsvDeduped rewrites it, returning the canonical names.
	$readDedupHeader = {
		param($reader)
		$h = script:Read-PaxCsvRecord -Reader $reader
		if ($null -eq $h) { return $null }
		$seen = [System.Collections.Generic.Dictionary[string, int]]::new([System.StringComparer]::OrdinalIgnoreCase)
		$out = New-Object System.Collections.Generic.List[string]
		for ($i = 0; $i -lt $h.Length; $i++) {
			$n = [string]$h[$i]
			if ($i -eq 0) { $n = $n -replace '^\uFEFF', '' }
			$n = $n.Trim()
			if ([string]::IsNullOrEmpty($n)) { $n = '_blank' }
			if ($seen.ContainsKey($n)) { $seen[$n] = $seen[$n] + 1; $out.Add(('{0}_dup{1}' -f $n, $seen[$n])) }
			else { $seen[$n] = 1; $out.Add($n) }
		}
		return , $out.ToArray()
	}
	# First index of a name in a header (OrdinalIgnoreCase) or -1.
	$findIdx = {
		param($header, $name)
		for ($i = 0; $i -lt $header.Length; $i++) { if ([string]::Equals([string]$header[$i], $name, [System.StringComparison]::OrdinalIgnoreCase)) { return $i } }
		return -1
	}

	$workRootBase = $env:TEMP; if (-not $workRootBase) { $workRootBase = [System.IO.Path]::GetTempPath() }
	$workDir = Join-Path $workRootBase ('pax_usersmerge_{0}' -f ([System.Guid]::NewGuid().ToString('N')))
	$tmpPath = "$OutputPath.merging"
	$retainedCount = 0; $newCount = 0; $departedCount = 0; $unionCount = 0

	try {
		[void][System.IO.Directory]::CreateDirectory($workDir)

		# --- Resolve headers (bounded: only the header record of each file). ---
		$targetExists = Test-Path -LiteralPath $TargetUsersCsv -PathType Leaf
		$curHdrReader = [System.IO.StreamReader]::new($CurrentUsersCsv, $true)
		$currentHeader = $null
		try { $currentHeader = & $readDedupHeader $curHdrReader } finally { $curHdrReader.Dispose() }
		if ($null -eq $currentHeader) { $currentHeader = @() }
		$targetHeader = @()
		if ($targetExists) {
			$tgtHdrReader = [System.IO.StreamReader]::new($TargetUsersCsv, $true)
			try { $th = & $readDedupHeader $tgtHdrReader; if ($null -ne $th) { $targetHeader = $th } } finally { $tgtHdrReader.Dispose() }
		}

		# --- Union header: current cols, PersonId_Normalized (derived-when-absent),
		#     target-only cols, then provenance cols. ---
		$hdrSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
		$hdrOrder = New-Object System.Collections.Generic.List[string]
		foreach ($c in $currentHeader) { if ($hdrSet.Add($c)) { $hdrOrder.Add($c) } }
		if ($hdrSet.Add('PersonId_Normalized')) { $hdrOrder.Add('PersonId_Normalized') }
		foreach ($c in $targetHeader) { if ($hdrSet.Add($c)) { $hdrOrder.Add($c) } }
		foreach ($c in @('Date_Added', 'Latest_Append_Date', 'In_Latest_Append')) { if ($hdrSet.Add($c)) { $hdrOrder.Add($c) } }
		$unionCols = $hdrOrder.ToArray()
		$U = $unionCols.Length
		$uIndex = @{}
		for ($i = 0; $i -lt $U; $i++) { $uIndex[$unionCols[$i]] = $i }
		$idxPidNorm = [int]$uIndex['PersonId_Normalized']
		$idxUserKey = if ($uIndex.ContainsKey('UserKey')) { [int]$uIndex['UserKey'] } else { -1 }
		$idxDateAdded = [int]$uIndex['Date_Added']
		$idxLatest = [int]$uIndex['Latest_Append_Date']
		$idxInLatest = [int]$uIndex['In_Latest_Append']
		$hasTotalEmp = $uIndex.ContainsKey('TotalEmployees')
		$idxTotalEmp = if ($hasTotalEmp) { [int]$uIndex['TotalEmployees'] } else { -1 }

		# Source -> union position maps and PersonId source indices.
		$cToU = New-Object 'int[]' $currentHeader.Length
		for ($s = 0; $s -lt $currentHeader.Length; $s++) { $cToU[$s] = [int]$uIndex[$currentHeader[$s]] }
		$cPN = & $findIdx $currentHeader 'PersonId_Normalized'
		$cUPN = & $findIdx $currentHeader 'userPrincipalName'
		$cPID = & $findIdx $currentHeader 'PersonId'
		$tToU = New-Object 'int[]' $targetHeader.Length
		for ($s = 0; $s -lt $targetHeader.Length; $s++) { $tToU[$s] = [int]$uIndex[$targetHeader[$s]] }
		$tPN = & $findIdx $targetHeader 'PersonId_Normalized'
		$tUPN = & $findIdx $targetHeader 'userPrincipalName'
		$tPID = & $findIdx $targetHeader 'PersonId'

		# Build the union-normalized value vector for one source row; also return the
		# derived normalized PersonId key and whether it was derived (PN absent/blank).
		$normalizeRow = {
			param($row, $srcToU, $iPN, $iUPN, $iPID)
			$vals = New-Object 'string[]' $U
			for ($j = 0; $j -lt $U; $j++) { $vals[$j] = '' }
			for ($s = 0; $s -lt $srcToU.Length; $s++) {
				$vals[$srcToU[$s]] = if ($s -lt $row.Length) { [string]$row[$s] } else { '' }
			}
			$pidVal = ''
			if ($iPN -ge 0 -and $iPN -lt $row.Length -and -not [string]::IsNullOrWhiteSpace([string]$row[$iPN])) { $pidVal = ([string]$row[$iPN]).Trim().ToLowerInvariant() }
			elseif ($iUPN -ge 0 -and $iUPN -lt $row.Length -and -not [string]::IsNullOrWhiteSpace([string]$row[$iUPN])) { $pidVal = ([string]$row[$iUPN]).Trim().ToLowerInvariant() }
			elseif ($iPID -ge 0 -and $iPID -lt $row.Length -and -not [string]::IsNullOrWhiteSpace([string]$row[$iPID])) { $pidVal = ([string]$row[$iPID]).Trim().ToLowerInvariant() }
			$pnBlank = ($iPN -lt 0) -or ($iPN -ge $row.Length) -or [string]::IsNullOrWhiteSpace([string]$row[$iPN])
			if ($pnBlank) { $vals[$idxPidNorm] = $pidVal }
			return [pscustomobject]@{ Vals = $vals; Pid = $pidVal; Derived = ($pnBlank -and -not [string]::IsNullOrWhiteSpace($pidVal)) }
		}

		# --- Stream both inputs to a bounded work file (never materialized whole). ---
		$workPath = Join-Path $workDir 'work.csv'
		$workHdr = @('__PID', '__SEQ', '__SIDE') + $unionCols
		$ww = [System.IO.StreamWriter]::new($workPath, $false, $u8)
		$seq = [int64]0
		$targetDataRows = [int64]0
		$targetDerived = 0; $currentDerived = 0; $anyTargetPid = $false
		try {
			script:Write-PaxCsvRecord -Writer $ww -Fields $workHdr
			if ($targetExists) {
				$tr = [System.IO.StreamReader]::new($TargetUsersCsv, $true)
				try {
					$null = script:Read-PaxCsvRecord -Reader $tr   # skip header
					while ($true) {
						$row = script:Read-PaxCsvRecord -Reader $tr
						if ($null -eq $row) { break }
						$targetDataRows++
						$n = & $normalizeRow $row $tToU $tPN $tUPN $tPID
						if ($n.Derived) { $targetDerived++ }
						if (-not [string]::IsNullOrWhiteSpace($n.Pid)) {
							$anyTargetPid = $true
							$fields = New-Object System.Collections.Generic.List[string]
							$fields.Add($n.Pid); $fields.Add($seq.ToString('D19', $inv)); $fields.Add('0')
							foreach ($v in $n.Vals) { $fields.Add([string]$v) }
							script:Write-PaxCsvRecord -Writer $ww -Fields $fields.ToArray()
						}
						$seq++
					}
				}
				finally { $tr.Dispose() }
			}
			# APPEND SAFETY (data-loss guard): never overwrite a non-empty target that parsed to 0 rows.
			if ($targetDataRows -eq 0 -and $targetExists -and ((Get-Item -LiteralPath $TargetUsersCsv).Length -gt 0)) {
				throw "Merge-UsersCsv: target '$TargetUsersCsv' exists with content but parsed to 0 rows; refusing to overwrite (would discard existing data)."
			}
			$cr = [System.IO.StreamReader]::new($CurrentUsersCsv, $true)
			try {
				$null = script:Read-PaxCsvRecord -Reader $cr   # skip header
				while ($true) {
					$row = script:Read-PaxCsvRecord -Reader $cr
					if ($null -eq $row) { break }
					$n = & $normalizeRow $row $cToU $cPN $cUPN $cPID
					if ($n.Derived) { $currentDerived++ }
					$fields = New-Object System.Collections.Generic.List[string]
					$pidField = $n.Pid   # may be '' (blank-pid current rows are still emitted)
					$fields.Add($pidField); $fields.Add($seq.ToString('D19', $inv)); $fields.Add('1')
					foreach ($v in $n.Vals) { $fields.Add([string]$v) }
					script:Write-PaxCsvRecord -Writer $ww -Fields $fields.ToArray()
					$seq++
				}
			}
			finally { $cr.Dispose() }
		}
		finally { $ww.Flush(); $ww.Dispose() }

		# Auditable derivation log (parity with the prior in-memory path).
		if ($targetDataRows -gt 0 -and -not $anyTargetPid) {
			Write-LogHost (
				("WARNING: Merge-UsersCsv: target Users CSV has no derivable dedup key (PersonId_Normalized / userPrincipalName / PersonId are all empty on every row). " +
				 "Cannot classify Retained / New / Departed; the union will contain only the current-run rows. " +
				 "Target: {0}") -f $TargetUsersCsv
			) -ForegroundColor Yellow
		}
		elseif ($targetDerived -gt 0 -or $currentDerived -gt 0) {
			Write-LogHost (
				"Merge-UsersCsv: derived PersonId_Normalized on the fly (target rows: {0}, current rows: {1}) — column was absent on the seed/raw shape (expected for M365-bundle EntraUsers CSVs)." -f $targetDerived, $currentDerived
			) -ForegroundColor Cyan
		}

		# --- Sort work by (PID, SEQ): equal keys adjacent, target rows before current. ---
		$sortedPath = Join-Path $workDir 'sorted.csv'
		[void](script:Invoke-PaxExternalSort -InputPath $workPath -OutputPath $sortedPath -KeyColumn @('__PID', '__SEQ') -Comparer 'Ordinal' -MemoryBudgetBytes $MemoryBudgetBytes -FanIn 8 -WorkRoot $workDir -ProgressCallback $ProgressCallback -ProgressIntervalSeconds $ProgressIntervalSeconds)

		# --- Join per PID group; emit ordered result rows [__ORD,__SEQ2]+union cols.
		#     __ORD '0' = current-section (current order), '1' = departed (target order). ---
		$resultPath = Join-Path $workDir 'result.csv'
		$sr = [System.IO.StreamReader]::new($sortedPath, $true)
		$rw = [System.IO.StreamWriter]::new($resultPath, $false, $u8)
		$section1 = 0
		try {
			$null = script:Read-PaxCsvRecord -Reader $sr
			script:Write-PaxCsvRecord -Writer $rw -Fields (@('__ORD', '__SEQ2') + $unionCols)
			$emitRow = {
				param($ord, $seq2, $vals)
				$out = New-Object System.Collections.Generic.List[string]
				$out.Add($ord); $out.Add($seq2)
				foreach ($v in $vals) { $out.Add([string]$v) }
				script:Write-PaxCsvRecord -Writer $rw -Fields $out.ToArray()
			}
			$haveGroup = $false; $curPid = $null; $targetFirst = $null; $targetFirstSeq = $null; $sawCurrent = $false
			$flush = {
				if (-not $haveGroup) { return }
				if (-not [string]::IsNullOrEmpty($curPid)) {
					if ($sawCurrent) {
						if ($null -ne $targetFirst) { $script:__uret++ } else { $script:__unew++ }
					}
				}
				if ((-not $sawCurrent) -and ($null -ne $targetFirst)) {
					$dv = $targetFirst.Clone()
					if ([string]::IsNullOrWhiteSpace([string]$dv[$idxDateAdded])) { $dv[$idxDateAdded] = $RunDate }
					$dv[$idxLatest] = $RunDate; $dv[$idxInLatest] = 'FALSE'
					& $emitRow '1' $targetFirstSeq $dv
					$script:__udep++
				}
			}
			$script:__uret = 0; $script:__unew = 0; $script:__udep = 0
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $sr
				if ($null -eq $row) { break }
				$k = [string]$row[0]
				$rseq = [string]$row[1]
				$side = [string]$row[2]
				$vals = New-Object 'string[]' $U
				for ($j = 0; $j -lt $U; $j++) { $vals[$j] = if (($j + 3) -lt $row.Length) { [string]$row[$j + 3] } else { '' } }
				if ((-not $haveGroup) -or (-not [string]::Equals($k, $curPid, [System.StringComparison]::Ordinal))) {
					& $flush
					$curPid = $k; $targetFirst = $null; $targetFirstSeq = $null; $sawCurrent = $false; $haveGroup = $true
				}
				if ($side -eq '0') {
					if ($null -eq $targetFirst) { $targetFirst = $vals; $targetFirstSeq = $rseq }
				}
				else {
					$out = $vals.Clone()
					if ($null -ne $targetFirst) {
						if ($idxUserKey -ge 0 -and -not [string]::IsNullOrWhiteSpace([string]$targetFirst[$idxUserKey])) { $out[$idxUserKey] = $targetFirst[$idxUserKey] }
						if (-not [string]::IsNullOrWhiteSpace([string]$targetFirst[$idxDateAdded])) { $out[$idxDateAdded] = $targetFirst[$idxDateAdded] } else { $out[$idxDateAdded] = $RunDate }
					}
					else {
						$out[$idxDateAdded] = $RunDate
					}
					$out[$idxLatest] = $RunDate; $out[$idxInLatest] = 'TRUE'
					& $emitRow '0' $rseq $out
					$sawCurrent = $true
					$section1++
				}
			}
			& $flush
			$retainedCount = [int]$script:__uret; $newCount = [int]$script:__unew; $departedCount = [int]$script:__udep
			Remove-Variable -Name __uret, __unew, __udep -Scope Script -ErrorAction SilentlyContinue
		}
		finally { $rw.Flush(); $rw.Dispose(); $sr.Dispose() }

		$unionCount = $section1 + $departedCount

		# --- Restore output order (current-section then departed) and publish. ---
		$orderedPath = Join-Path $workDir 'ordered.csv'
		[void](script:Invoke-PaxExternalSort -InputPath $resultPath -OutputPath $orderedPath -KeyColumn @('__ORD', '__SEQ2') -Comparer 'Ordinal' -MemoryBudgetBytes $MemoryBudgetBytes -FanIn 8 -WorkRoot $workDir -ProgressCallback $ProgressCallback -ProgressIntervalSeconds $ProgressIntervalSeconds)

		$unionColsLocal = $unionCols
		$totalEmpStr = "$unionCount"
		$objStream = {
			$orr = [System.IO.StreamReader]::new($orderedPath, $true)
			try {
				$null = script:Read-PaxCsvRecord -Reader $orr
				while ($true) {
					$row = script:Read-PaxCsvRecord -Reader $orr
					if ($null -eq $row) { break }
					$o = [ordered]@{}
					for ($j = 0; $j -lt $unionColsLocal.Length; $j++) { $o[$unionColsLocal[$j]] = if (($j + 2) -lt $row.Length) { [string]$row[$j + 2] } else { '' } }
					if ($hasTotalEmp) { $o['TotalEmployees'] = $totalEmpStr }
					[pscustomobject]$o
				}
			}
			finally { $orr.Dispose() }
		}
		& $objStream | Select-Object -Property $unionCols | Export-Csv -LiteralPath $tmpPath -NoTypeInformation -Encoding UTF8
		Move-Item -LiteralPath $tmpPath -Destination $OutputPath -Force -ErrorAction Stop
	}
	catch {
		if (Test-Path -LiteralPath $tmpPath) { try { Remove-Item -LiteralPath $tmpPath -Force -ErrorAction SilentlyContinue } catch {} }
		throw
	}
	finally {
		if (Test-Path -LiteralPath $workDir) { try { Remove-Item -LiteralPath $workDir -Recurse -Force -ErrorAction SilentlyContinue } catch {} }
	}

	return @{
		Retained = $retainedCount
		New      = $newCount
		Departed = $departedCount
		Union    = $unionCount
	}
}

function Get-FactCompositeKeyColumns {
	<#
	.SYNOPSIS
		Return the grain-composite append dedup key column list for a rolled-up
		Interactions Fact CSV, derived from its header columns.
	.DESCRIPTION
		Rolled-up fact rows FAN OUT: many rows share one
		Message_Id_Raw, one per distinct grain (e.g. per AccessedResource). Cross-run
		append dedup must therefore key on the FULL grain PLUS Message_Id_Raw; keying
		on Message_Id_Raw alone collapses every fan-out row for a message to one and
		silently discards the rest on merge.

		Grain columns use their stable, cross-run-comparable forms: the per-run INT
		surrogates 'UserKey' and 'ThreadId' are replaced by the deid-consistent
		normalized user identity (AIO: 'User_Id_Normalized' (FIX 5); AIBV: the
		pre-existing 'Audit_UserId_Normalized') and by 'ThreadId_Raw' respectively.
		The remaining names mirror the embedded processor grain (GRAIN_KEYS_AIO /
		GRAIN_KEYS_AIBV) verbatim. Profile is detected from the header (AIBV carries
		'Is_Agent_Activity'). Returns @() when the header is not a recognizable fact
		header (no Message_Id_Raw) so the caller falls back to its own guard.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)] [string[]] $HeaderColumns)

	if (-not ($HeaderColumns -contains 'Message_Id_Raw')) { return @() }
	$isAibv = ($HeaderColumns -contains 'Is_Agent_Activity')
	$userIdCol = if ($isAibv) { 'Audit_UserId_Normalized' } else { 'User_Id_Normalized' }
	$cols = [System.Collections.Generic.List[string]]::new()
	$cols.Add($userIdCol)          # replaces the per-run 'UserKey' INT surrogate
	$cols.Add('InteractionDate')
	$cols.Add('AgentId')
	$cols.Add('AgentName')
	$cols.Add('AppHost')
	$cols.Add('Environment')
	$cols.Add('License Status')
	$cols.Add('Context_Type')
	$cols.Add('Behavior_Category')
	$cols.Add('Behavior_Enriched')
	$cols.Add('AI_Model')
	$cols.Add('Is_Sensitive')
	$cols.Add('Autonomy_Pattern')
	$cols.Add('AppIdentity_AppId')
	$cols.Add('AISystemPlugin_Name')
	$cols.Add('ThreadId_Raw')      # replaces the per-run 'ThreadId' INT surrogate
	if ($isAibv) {
		$cols.Add('Is_Agent_Activity')
		$cols.Add('Web_Grounded_Signal')
		$cols.Add('Workflow_Action')
	}
	$cols.Add('Message_Id_Raw')
	# Emit as a flat string[]; callers collect with @(...) (an empty return above
	# unrolls to nothing, which @(...) normalizes to an empty array).
	return $cols.ToArray()
}
#region PAX-S2 bounded-memory external-sort primitives
# Shared bounded-memory CSV primitives. These helpers stream records through
# fixed-size buffers and spill to disk once a caller-supplied byte budget is
# reached, so peak memory stays bounded by the budget plus a single record
# rather than by the total row count. Nothing in the main flow calls them; they
# are self-contained building blocks. Every function is script-scoped to keep
# the session global namespace clean. The byte budget controls only WHEN data
# spills to disk; it never caps how many rows, fields, files, or dates are
# processed. A single record larger than the budget is still processed intact.

function script:New-PaxSortMetrics {
	# Return a fresh deterministic metrics record. Counters are Int64 aggregate
	# numbers only; the object never carries field values, keys, or row contents.
	# The run-descriptor and level-occupancy counters prove the sort retains a
	# fixed-bounded amount of run bookkeeping regardless of total input size, and
	# the managed-heap checkpoints record the live managed allocation at start,
	# after every buffer has spilled, and after the final merge.
	[CmdletBinding()]
	param()
	[pscustomobject]@{
		RowsRead                   = [int64]0
		RowsWritten                = [int64]0
		RunCount                   = [int64]0
		MergePassCount             = [int64]0
		MaxBufferedBytes           = [int64]0
		MaxBufferedRecords         = [int64]0
		MaxAccountedBufferBytes    = [int64]0
		LargestRecordBytes         = [int64]0
		LargestSerializedRecordBytes = [int64]0
		MaxRetainedRunDescriptors  = [int64]0
		MaxLevelOccupancy          = [int64]0
		MaxOpenReaders             = [int64]0
		TempBytesWritten           = [int64]0
		ManagedHeapBefore          = [int64]0
		ManagedHeapAfterIngest     = [int64]0
		ManagedHeapAfterMerge      = [int64]0
		CleanupSucceeded           = $true
		FailureStage               = $null
	}
}

function script:Read-PaxCsvRecord {
	# Read the next logical CSV record from an open StreamReader and return its
	# fields as an ordered [string[]], or $null at end of input. Behaviour is the
	# authoritative RFC-4180 contract defined by Read-PaxCsvRecordFallback below.
	#
	# By default a compiled state machine (PaxCsvRecordReader) performs the read for
	# speed; it implements the SAME four-state machine, the SAME record boundaries,
	# the SAME doubled-quote / embedded CR-LF handling, and throws the SAME messages
	# as the fallback. If dynamic compilation is unavailable in a restricted host,
	# the original PowerShell parser is used instead with identical results. The
	# backend is chosen ONCE; a parser error from the compiled backend is surfaced
	# verbatim (never used to retry the fallback on an already-advanced stream).
	# $script:PaxCsvBackendOverride is a TEST-ONLY seam ('Compiled' | 'Fallback');
	# the production default is automatic.
	[CmdletBinding()]
	param([Parameter(Mandatory)][System.IO.StreamReader]$Reader)
	$backend = $script:PaxCsvBackendOverride
	if ($backend -eq 'Fallback') { return , (script:Read-PaxCsvRecordFallback -Reader $Reader) }
	if ($backend -ne 'Compiled') {
		# Automatic: prefer the compiled backend; fall back ONLY when compilation is
		# unavailable (an initialization decision, never a per-record parse retry).
		if (-not (script:Initialize-PaxCsvCompiledReader)) {
			if (-not $script:PaxCsvFallbackWarned) {
				$script:PaxCsvFallbackWarned = $true
				$lh = Microsoft.PowerShell.Core\Get-Command -Name 'Write-LogHost' -CommandType Function -ErrorAction SilentlyContinue
				if ($lh) { try { & $lh -Message 'PAX CSV read acceleration is unavailable in this host; using the built-in parser (results are unchanged).' -ForegroundColor 'DarkGray' } catch { } }
			}
			return , (script:Read-PaxCsvRecordFallback -Reader $Reader)
		}
	}
	else {
		# Forced compiled (test seam): require the compiled backend.
		if (-not (script:Initialize-PaxCsvCompiledReader)) { throw 'PaxCsvParse: compiled backend was forced but is unavailable in this host.' }
	}
	# Compiled read. Surface the parser's own message verbatim; NEVER fall back after
	# the stream has advanced (that would corrupt record position).
	try {
		$rec = [PaxCsvRecordReader]::ReadRecord($Reader)
	}
	catch {
		$pmsg = $_.Exception.Message
		if ($_.Exception.InnerException -and $_.Exception.InnerException.Message) { $pmsg = $_.Exception.InnerException.Message }
		throw $pmsg
	}
	return , $rec
}

function script:Initialize-PaxCsvCompiledReader {
	# Compile the RFC-4180 reader type ONCE per process and cache the outcome so
	# routine record reads never re-probe assemblies, recompile, allocate source,
	# or re-catch a prior initialization failure. Returns $true when the compiled
	# backend is usable, $false when dynamic compilation is unavailable (restricted
	# host / language-mode policy). Emits nothing to the pipeline.
	if ($null -ne $script:PaxCsvCompiledReady) { return $script:PaxCsvCompiledReady }
	try {
		if (-not ('PaxCsvRecordReader' -as [type])) {
			$paxCsvReaderSource = @'
using System.IO;
using System.Collections.Generic;
using System.Text;
public static class PaxCsvRecordReader {
    // Field state: 0 fresh, 1 unquoted, 2 inside quotes, 3 after a closing quote.
    public static string[] ReadRecord(StreamReader reader) {
        if (reader.Peek() < 0) { return null; }
        List<string> fields = new List<string>();
        StringBuilder sb = new StringBuilder();
        int state = 0;
        while (true) {
            int ci = reader.Read();
            if (ci < 0) {
                if (state == 2) { throw new IOException("PaxCsvParse: unterminated quoted field at end of input."); }
                fields.Add(sb.ToString());
                return fields.ToArray();
            }
            char c = (char)ci;
            if (state == 0) {
                if (c == '"') { state = 2; }
                else if (c == ',') { fields.Add(sb.ToString()); sb.Clear(); }
                else if (c == '\r') { if (reader.Peek() == 10) { reader.Read(); } fields.Add(sb.ToString()); return fields.ToArray(); }
                else if (c == '\n') { fields.Add(sb.ToString()); return fields.ToArray(); }
                else { sb.Append(c); state = 1; }
            }
            else if (state == 1) {
                if (c == '"') { throw new IOException("PaxCsvParse: quote inside an unquoted field."); }
                else if (c == ',') { fields.Add(sb.ToString()); sb.Clear(); state = 0; }
                else if (c == '\r') { if (reader.Peek() == 10) { reader.Read(); } fields.Add(sb.ToString()); return fields.ToArray(); }
                else if (c == '\n') { fields.Add(sb.ToString()); return fields.ToArray(); }
                else { sb.Append(c); }
            }
            else if (state == 2) {
                if (c == '"') {
                    if (reader.Peek() == 34) { reader.Read(); sb.Append('"'); }
                    else { state = 3; }
                }
                else { sb.Append(c); }
            }
            else {
                if (c == ',') { fields.Add(sb.ToString()); sb.Clear(); state = 0; }
                else if (c == '\r') { if (reader.Peek() == 10) { reader.Read(); } fields.Add(sb.ToString()); return fields.ToArray(); }
                else if (c == '\n') { fields.Add(sb.ToString()); return fields.ToArray(); }
                else { throw new IOException("PaxCsvParse: unexpected content after a closing quote."); }
            }
        }
    }
}
'@
			Add-Type -TypeDefinition $paxCsvReaderSource -Language CSharp -ErrorAction Stop | Out-Null
		}
		$script:PaxCsvCompiledReady = $true
	}
	catch {
		$script:PaxCsvCompiledReady = $false
	}
	return $script:PaxCsvCompiledReady
}

function script:Read-PaxCsvRecordFallback {
	# AUTHORITATIVE RFC-4180 contract (original interpreted parser, preserved verbatim
	# as a portable fallback). Read the next logical CSV record from an open
	# StreamReader and return its fields as an ordered [string[]], or $null at end of
	# input. A single logical record may span several physical lines when a field is
	# quoted; quoted fields carry commas, CR, LF, and doubled quotes ("") as literal
	# content. A record larger than any read buffer accumulates whole to its
	# terminator. Malformed quoting is a terminal error: a quote inside an unquoted
	# field, any content after a closing quote, or an unterminated quoted field at end
	# of input all throw rather than guess.
	[CmdletBinding()]
	param([Parameter(Mandatory)][System.IO.StreamReader]$Reader)
	if ($Reader.Peek() -lt 0) { return $null }
	$fields = [System.Collections.Generic.List[string]]::new()
	$sb = [System.Text.StringBuilder]::new()
	# Field state: 0 fresh, 1 unquoted, 2 inside quotes, 3 after a closing quote.
	$state = 0
	while ($true) {
		$ci = $Reader.Read()
		if ($ci -lt 0) {
			if ($state -eq 2) { throw 'PaxCsvParse: unterminated quoted field at end of input.' }
			$fields.Add($sb.ToString())
			return , $fields.ToArray()
		}
		$c = [char]$ci
		switch ($state) {
			0 {
				if ($c -eq '"') { $state = 2 }
				elseif ($c -eq ',') { $fields.Add($sb.ToString()); [void]$sb.Clear() }
				elseif ($c -eq "`r") { if ($Reader.Peek() -eq 10) { [void]$Reader.Read() }; $fields.Add($sb.ToString()); return , $fields.ToArray() }
				elseif ($c -eq "`n") { $fields.Add($sb.ToString()); return , $fields.ToArray() }
				else { [void]$sb.Append($c); $state = 1 }
			}
			1 {
				if ($c -eq '"') { throw 'PaxCsvParse: quote inside an unquoted field.' }
				elseif ($c -eq ',') { $fields.Add($sb.ToString()); [void]$sb.Clear(); $state = 0 }
				elseif ($c -eq "`r") { if ($Reader.Peek() -eq 10) { [void]$Reader.Read() }; $fields.Add($sb.ToString()); return , $fields.ToArray() }
				elseif ($c -eq "`n") { $fields.Add($sb.ToString()); return , $fields.ToArray() }
				else { [void]$sb.Append($c) }
			}
			2 {
				if ($c -eq '"') {
					if ($Reader.Peek() -eq 34) { [void]$Reader.Read(); [void]$sb.Append('"') }
					else { $state = 3 }
				}
				else { [void]$sb.Append($c) }
			}
			3 {
				if ($c -eq ',') { $fields.Add($sb.ToString()); [void]$sb.Clear(); $state = 0 }
				elseif ($c -eq "`r") { if ($Reader.Peek() -eq 10) { [void]$Reader.Read() }; $fields.Add($sb.ToString()); return , $fields.ToArray() }
				elseif ($c -eq "`n") { $fields.Add($sb.ToString()); return , $fields.ToArray() }
				else { throw 'PaxCsvParse: unexpected content after a closing quote.' }
			}
		}
	}
}

function script:Write-PaxCsvRecord {
	# Write one RFC-4180-safe record to an open StreamWriter. A field is quoted
	# only when it contains a comma, a double-quote, a CR, or an LF; embedded
	# quotes are doubled. Output is deterministic, and a parse -> write -> parse
	# round trip preserves every field value exactly. Records are terminated with
	# CRLF so the reader recognizes them regardless of platform.
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][System.IO.StreamWriter]$Writer,
		[Parameter(Mandatory)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Fields
	)
	$sb = [System.Text.StringBuilder]::new()
	$special = [char[]]@(',', '"', "`r", "`n")
	for ($i = 0; $i -lt $Fields.Length; $i++) {
		if ($i -gt 0) { [void]$sb.Append(',') }
		$f = $Fields[$i]; if ($null -eq $f) { $f = '' }
		if ($f.IndexOfAny($special) -ge 0) {
			[void]$sb.Append('"'); [void]$sb.Append($f.Replace('"', '""')); [void]$sb.Append('"')
		}
		else { [void]$sb.Append($f) }
	}
	[void]$sb.Append("`r`n")
	$Writer.Write($sb.ToString())
}

function script:Get-PaxComparer {
	# Map a caller-selected comparer name to the matching ordinal StringComparer.
	# The comparer is applied to whole composite keys; keys are never lowercased
	# as a shortcut for case-insensitive comparison, so the caller stays in full
	# control of case sensitivity.
	[CmdletBinding()]
	param([Parameter(Mandatory)][ValidateSet('Ordinal', 'OrdinalIgnoreCase')][string]$Name)
	if ($Name -eq 'OrdinalIgnoreCase') { return [System.StringComparer]::OrdinalIgnoreCase }
	return [System.StringComparer]::Ordinal
}

function script:Get-PaxCompositeKey {
	# Build the composite key for a record by joining the caller-selected columns,
	# in caller order, with the U+001F unit separator. That separator is a control
	# character absent from normal field text, so distinct column tuples map to
	# distinct keys. A key index outside the record contributes an empty segment.
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Fields,
		[Parameter(Mandatory)][int[]]$KeyIndices
	)
	$sep = [char]0x1F
	$sb = [System.Text.StringBuilder]::new()
	for ($i = 0; $i -lt $KeyIndices.Length; $i++) {
		if ($i -gt 0) { [void]$sb.Append($sep) }
		$idx = $KeyIndices[$i]
		if ($idx -ge 0 -and $idx -lt $Fields.Length) {
			$v = $Fields[$idx]; if ($null -ne $v) { [void]$sb.Append($v) }
		}
	}
	return $sb.ToString()
}

function script:ConvertTo-PaxCsvLine {
	# Serialize a field array to a single RFC-4180 line with no terminator. A field
	# is quoted only when it contains a comma, a double-quote, a CR, or an LF, and
	# embedded quotes are doubled, so the result parses back to the same fields.
	# The buffered item keeps this one compact string instead of the field array,
	# and the run spill emits the sequence, a comma, and this string unchanged.
	[CmdletBinding()]
	param([Parameter(Mandatory)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Fields)
	$sb = [System.Text.StringBuilder]::new()
	$special = [char[]]@(',', '"', "`r", "`n")
	for ($i = 0; $i -lt $Fields.Length; $i++) {
		if ($i -gt 0) { [void]$sb.Append(',') }
		$f = $Fields[$i]; if ($null -eq $f) { $f = '' }
		if ($f.IndexOfAny($special) -ge 0) {
			[void]$sb.Append('"'); [void]$sb.Append($f.Replace('"', '""')); [void]$sb.Append('"')
		}
		else { [void]$sb.Append($f) }
	}
	return $sb.ToString()
}

function script:Get-PaxRetainedRecordBytes {
	# Return a conservative upper bound on the RETAINED managed bytes of one
	# buffered item: a fixed three-slot object array holding its composite key, its
	# boxed Int64 sequence, and its serialized data line. A .NET char occupies two
	# managed bytes, so the retained string payloads account for 2*Key.Length plus
	# 2*Data.Length. The fixed 512-byte allowance covers both string headers, the
	# object-array header and three reference slots, the boxed Int64, the list slot,
	# unused list-capacity allowance, alignment, and runtime object bookkeeping.
	# This governs
	# only WHEN a buffer spills; it never caps how much data flows through, and an
	# item larger than the whole budget is still measured and processed intact.
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][AllowEmptyString()][string]$Key,
		[Parameter(Mandatory)][AllowEmptyString()][string]$Data
	)
	$overhead = [int64]512
	$k = if ($null -ne $Key) { [int64]$Key.Length } else { [int64]0 }
	$d = if ($null -ne $Data) { [int64]$Data.Length } else { [int64]0 }
	return ([int64]2 * $k) + ([int64]2 * $d) + $overhead
}

function script:Read-PaxRunFront {
	# Read the next row from an internally-sorted run stream and return its front
	# view: the Int64 sequence carried in the first field, the original record
	# fields, and the recomputed composite key. Returns $null at end of the run.
	# A run row missing its sequence field is a terminal error.
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][System.IO.StreamReader]$Reader,
		[Parameter(Mandatory)][int[]]$KeyIndices
	)
	$row = script:Read-PaxCsvRecord -Reader $Reader
	if ($null -eq $row) { return $null }
	if ($row.Length -lt 1) { throw 'PaxMerge: malformed run row (missing sequence field).' }
	$seq = [int64]::Parse($row[0], [System.Globalization.CultureInfo]::InvariantCulture)
	$orig = New-Object System.Collections.Generic.List[string]
	for ($i = 1; $i -lt $row.Length; $i++) { $orig.Add($row[$i]) }
	$of = $orig.ToArray()
	$key = script:Get-PaxCompositeKey -Fields $of -KeyIndices $KeyIndices
	[pscustomobject]@{ Seq = $seq; Fields = $of; Key = $key }
}

function script:Merge-PaxRunGroup {
	# Merge up to a fan-in's worth of internally-sorted runs by opening one
	# bounded reader per run, holding only the current front record from each open
	# reader, and repeatedly emitting the minimum by (composite key under the
	# comparer, then Int64 sequence). It never opens more readers than the group
	# size and never collects a key group, so a hot key streams through. When
	# EmitSequence is set the sequence is carried forward so a later pass keeps
	# global order; otherwise the original record fields are written.
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][AllowEmptyCollection()][string[]]$RunPaths,
		[Parameter(Mandatory)][int[]]$KeyIndices,
		[Parameter(Mandatory)][System.Collections.IComparer]$Comparer,
		[Parameter(Mandatory)][System.IO.StreamWriter]$Writer,
		[Parameter(Mandatory)][bool]$EmitSequence,
		[Parameter(Mandatory)][scriptblock]$ReaderFactory,
		[Parameter(Mandatory)][psobject]$Metrics,
		# Optional observability-only heartbeat hook (default absent). When supplied it is invoked every
		# few thousand emitted rows so a long single-group merge can report active progress. It receives
		# no arguments, no data, no keys, and no paths; its exceptions are swallowed and it cannot alter
		# ordering, the emitted stream, or the merge result. Absent by default so existing callers and the
		# emitted bytes are unchanged.
		[scriptblock]$RowObserver
	)
	$readers = New-Object System.Collections.Generic.List[System.IO.StreamReader]
	$fronts = New-Object System.Collections.Generic.List[object]
	$rgN = [int64]0
	try {
		foreach ($rp in $RunPaths) {
			$r = & $ReaderFactory $rp
			$readers.Add($r)
			$fronts.Add((script:Read-PaxRunFront -Reader $r -KeyIndices $KeyIndices))
		}
		if ([int64]$readers.Count -gt $Metrics.MaxOpenReaders) { $Metrics.MaxOpenReaders = [int64]$readers.Count }
		while ($true) {
			$minIdx = -1
			for ($i = 0; $i -lt $fronts.Count; $i++) {
				$f = $fronts[$i]
				if ($null -eq $f) { continue }
				if ($minIdx -lt 0) { $minIdx = $i; continue }
				$m = $fronts[$minIdx]
				$c = $Comparer.Compare($f.Key, $m.Key)
				if ($c -lt 0 -or ($c -eq 0 -and $f.Seq -lt $m.Seq)) { $minIdx = $i }
			}
			if ($minIdx -lt 0) { break }
			$sel = $fronts[$minIdx]
			if ($EmitSequence) {
				$outFields = New-Object System.Collections.Generic.List[string]
				$outFields.Add($sel.Seq.ToString([System.Globalization.CultureInfo]::InvariantCulture))
				foreach ($v in $sel.Fields) { $outFields.Add($v) }
				script:Write-PaxCsvRecord -Writer $Writer -Fields $outFields.ToArray()
			}
			else {
				script:Write-PaxCsvRecord -Writer $Writer -Fields $sel.Fields
				$Metrics.RowsWritten++
			}
			if ($RowObserver) { $rgN++; if (($rgN -band 4095) -eq 0) { try { & $RowObserver } catch { } } }
			$fronts[$minIdx] = (script:Read-PaxRunFront -Reader $readers[$minIdx] -KeyIndices $KeyIndices)
		}
	}
	finally {
		foreach ($r in $readers) { if ($r) { $r.Close(); $r.Dispose() } }
	}
}

function script:Merge-PaxSortedRuns {
	# Merge the caller's survivor run set into a single ordered stream while
	# honoring a bounded fan-in. The survivor set is the fixed-bounded collection
	# gathered from the compaction levels, never the total run count, so the pass
	# lists below are bounded by that fixed constant. When the survivor count
	# exceeds the fan-in the merge runs in deterministic multiple passes: it
	# merges a fan-in's worth of runs at a time into larger runs, deletes each
	# consumed run as soon as its group finishes, and repeats until the survivors
	# fit one final merge. No pass opens more than the fan-in of readers and no
	# pass materializes a whole run or a whole hot-key group. Ordering is stable
	# on (composite key under the comparer, then Int64 sequence). The final pass
	# writes the original record fields to the output writer; intermediate passes
	# carry the sequence forward.
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][AllowEmptyCollection()][string[]]$RunPaths,
		[Parameter(Mandatory)][int[]]$KeyIndices,
		[Parameter(Mandatory)][System.Collections.IComparer]$Comparer,
		[Parameter(Mandatory)][int]$FanIn,
		[Parameter(Mandatory)][System.IO.StreamWriter]$OutputWriter,
		[Parameter(Mandatory)][string]$WorkDir,
		[Parameter(Mandatory)][scriptblock]$ReaderFactory,
		[Parameter(Mandatory)][scriptblock]$WriterFactory,
		[Parameter(Mandatory)][psobject]$Metrics,
		# Optional observability-only observer (default absent). It is invoked as
		# & $ProgressObserver <stageName> <passNumber> at each intermediate-merge pass entry and once
		# before the final merge, and (via a derived row hook) periodically during a long pass. It only
		# ever receives an aggregate stage name and pass number, never a row, key, field, or path, and it
		# cannot alter merge ordering, output, or the result. Absent by default so callers and emitted
		# bytes are unchanged.
		[scriptblock]$ProgressObserver
	)
	if ($FanIn -lt 2) { throw 'PaxMerge: FanIn must be at least 2.' }
	$current = New-Object System.Collections.Generic.List[string]
	foreach ($p in $RunPaths) { $current.Add($p) }
	if ($current.Count -eq 0) { return }
	# Derive a row-level heartbeat hook that reports under the stage currently in flight. Absent unless
	# an observer was supplied, so the default merge path allocates nothing extra and emits nothing.
	$stageBox = [pscustomobject]@{ Stage = 'FinalMerge' }
	$rowObs = $null
	if ($ProgressObserver) { $rowObs = { & $ProgressObserver $stageBox.Stage -1 } }
	$passIndex = 0
	while ($current.Count -gt $FanIn) {
		$passIndex++
		$stageBox.Stage = 'IntermediateMerge'
		if ($ProgressObserver) { & $ProgressObserver 'IntermediateMerge' $passIndex }
		$next = New-Object System.Collections.Generic.List[string]
		$groupNo = 0
		for ($i = 0; $i -lt $current.Count; $i += $FanIn) {
			$group = New-Object System.Collections.Generic.List[string]
			for ($j = $i; $j -lt [Math]::Min($i + $FanIn, $current.Count); $j++) { $group.Add($current[$j]) }
			$groupNo++
			$outPath = Join-Path $WorkDir ("pass{0:d3}_grp{1:d4}.paxrun" -f $passIndex, $groupNo)
			$w = & $WriterFactory $outPath
			try {
				script:Merge-PaxRunGroup -RunPaths $group.ToArray() -KeyIndices $KeyIndices -Comparer $Comparer -Writer $w -EmitSequence $true -ReaderFactory $ReaderFactory -Metrics $Metrics -RowObserver $rowObs
			}
			finally { $w.Flush(); $w.Close(); $w.Dispose() }
			$fi = [System.IO.FileInfo]::new($outPath); if ($fi.Exists) { $Metrics.TempBytesWritten += [int64]$fi.Length }
			foreach ($cp in $group) { if (Test-Path -LiteralPath $cp) { Remove-Item -LiteralPath $cp -Force -ErrorAction Stop } }
			$next.Add($outPath)
		}
		$Metrics.MergePassCount++
		$current = $next
	}
	$stageBox.Stage = 'FinalMerge'
	if ($ProgressObserver) { & $ProgressObserver 'FinalMerge' 0 }
	script:Merge-PaxRunGroup -RunPaths $current.ToArray() -KeyIndices $KeyIndices -Comparer $Comparer -Writer $OutputWriter -EmitSequence $false -ReaderFactory $ReaderFactory -Metrics $Metrics -RowObserver $rowObs
	foreach ($cp in $current) { if (Test-Path -LiteralPath $cp) { Remove-Item -LiteralPath $cp -Force -ErrorAction Stop } }
	$Metrics.MergePassCount++
}

function script:Remove-PaxWorkspace {
	# Remove a temp workspace and an optional in-progress publication file after a
	# run finishes or fails. A cleanup problem never hides the primary outcome: it
	# only clears CleanupSucceeded on the metrics so the caller can report it.
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$WorkDir,
		[AllowNull()][AllowEmptyString()][string]$MergingPath,
		[Parameter(Mandatory)][psobject]$Metrics
	)
	$okAll = $true
	if ($MergingPath -and (Test-Path -LiteralPath $MergingPath)) {
		try { Remove-Item -LiteralPath $MergingPath -Force -ErrorAction Stop } catch { $okAll = $false }
	}
	if (Test-Path -LiteralPath $WorkDir) {
		try { Remove-Item -LiteralPath $WorkDir -Recurse -Force -ErrorAction Stop } catch { $okAll = $false }
	}
	if (-not $okAll) { $Metrics.CleanupSucceeded = $false }
}

function script:Select-PaxFirstRowPerKey {
	# Stream the first row of each key from a (key, sequence)-sorted run stream.
	# Because the input is ordered by key then ascending sequence, the first row
	# seen for a key carries the lowest sequence and is emitted; later rows with
	# the same key are skipped. A hot key with many rows streams through without
	# ever collecting the group. Returns the number of rows emitted.
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][System.IO.StreamReader]$Reader,
		[Parameter(Mandatory)][int[]]$KeyIndices,
		[Parameter(Mandatory)][System.Collections.IComparer]$Comparer,
		[Parameter(Mandatory)][System.IO.StreamWriter]$Writer,
		[bool]$EmitSequence = $false
	)
	$haveLast = $false
	$lastKey = $null
	$emitted = [int64]0
	while ($true) {
		$front = script:Read-PaxRunFront -Reader $Reader -KeyIndices $KeyIndices
		if ($null -eq $front) { break }
		$isNew = (-not $haveLast) -or ($Comparer.Compare($front.Key, $lastKey) -ne 0)
		if ($isNew) {
			if ($EmitSequence) {
				$of = New-Object System.Collections.Generic.List[string]
				$of.Add($front.Seq.ToString([System.Globalization.CultureInfo]::InvariantCulture))
				foreach ($v in $front.Fields) { $of.Add($v) }
				script:Write-PaxCsvRecord -Writer $Writer -Fields $of.ToArray()
			}
			else {
				script:Write-PaxCsvRecord -Writer $Writer -Fields $front.Fields
			}
			$emitted++
			$lastKey = $front.Key
			$haveLast = $true
		}
	}
	return $emitted
}

function script:Merge-PaxKeyStreams {
	# Co-merge two key-sorted, distinct-key run streams by advancing two bounded
	# readers in lockstep. A key present in the current stream is written to the
	# present writer; a key found only in the target stream is written to the
	# target-only writer. Neither side is collected, so arbitrarily large streams
	# classify in bounded memory. Returns present and target-only counts.
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][System.IO.StreamReader]$CurrentReader,
		[Parameter(Mandatory)][System.IO.StreamReader]$TargetReader,
		[Parameter(Mandatory)][int[]]$CurrentKeyIndices,
		[Parameter(Mandatory)][int[]]$TargetKeyIndices,
		[Parameter(Mandatory)][System.Collections.IComparer]$Comparer,
		[Parameter(Mandatory)][System.IO.StreamWriter]$PresentWriter,
		[Parameter(Mandatory)][System.IO.StreamWriter]$TargetOnlyWriter
	)
	$cur = script:Read-PaxRunFront -Reader $CurrentReader -KeyIndices $CurrentKeyIndices
	$tgt = script:Read-PaxRunFront -Reader $TargetReader -KeyIndices $TargetKeyIndices
	$present = [int64]0; $targetOnly = [int64]0
	while ($true) {
		if ($null -eq $cur -and $null -eq $tgt) { break }
		if ($null -eq $tgt) {
			script:Write-PaxCsvRecord -Writer $PresentWriter -Fields $cur.Fields; $present++
			$cur = script:Read-PaxRunFront -Reader $CurrentReader -KeyIndices $CurrentKeyIndices
			continue
		}
		if ($null -eq $cur) {
			script:Write-PaxCsvRecord -Writer $TargetOnlyWriter -Fields $tgt.Fields; $targetOnly++
			$tgt = script:Read-PaxRunFront -Reader $TargetReader -KeyIndices $TargetKeyIndices
			continue
		}
		$c = $Comparer.Compare($cur.Key, $tgt.Key)
		if ($c -lt 0) {
			script:Write-PaxCsvRecord -Writer $PresentWriter -Fields $cur.Fields; $present++
			$cur = script:Read-PaxRunFront -Reader $CurrentReader -KeyIndices $CurrentKeyIndices
		}
		elseif ($c -gt 0) {
			script:Write-PaxCsvRecord -Writer $TargetOnlyWriter -Fields $tgt.Fields; $targetOnly++
			$tgt = script:Read-PaxRunFront -Reader $TargetReader -KeyIndices $TargetKeyIndices
		}
		else {
			script:Write-PaxCsvRecord -Writer $PresentWriter -Fields $cur.Fields; $present++
			$cur = script:Read-PaxRunFront -Reader $CurrentReader -KeyIndices $CurrentKeyIndices
			$tgt = script:Read-PaxRunFront -Reader $TargetReader -KeyIndices $TargetKeyIndices
		}
	}
	return [pscustomobject]@{ Present = $present; TargetOnly = $targetOnly }
}

function script:Invoke-PaxExternalSort {
	<#
	.SYNOPSIS
		Sort a CSV by a caller-selected composite key using bounded memory and a
		fixed-level online run compactor.

	.DESCRIPTION
		Reads the header record of an input CSV, maps the requested key columns to
		column indices, keys each data record by the U+001F join of those columns
		under the caller-selected comparer, and writes the header plus the sorted
		data to the output path. Records buffer in memory only until a caller
		supplied byte budget is reached (or a single record alone exceeds it), then
		spill to internally-sorted run files. Each buffered item retains only its
		composite key, its Int64 sequence, and its serialized data line, so retained
		memory is accounted honestly rather than by field payload alone.

		Runs are combined by an online fixed-level compactor rather than by
		retaining every run path. A fresh run enters level zero; whenever a level
		reaches the fan-in it merges into one promoted run at the next level, the
		consumed runs are deleted, and the level clears. A level-L run subsumes at
		least FanIn^L runs, so with a fan-in of at least two the sixty-four levels
		cover the whole positive Int64 run domain (two to the sixty-third exceeds
		Int64.MaxValue). At most fan-in-minus-one runs rest at each level, so the
		surviving run set gathered for the final merge is bounded by a fixed
		constant, never by the total run count. The final merge combines those
		survivors with the same bounded, possibly multi-pass k-way merge, so peak
		memory and retained run bookkeeping stay bounded by the budget, one record,
		and that fixed constant rather than by total rows or total runs. The byte
		budget controls only WHEN data spills; it never caps how many rows, fields,
		or files are processed. Every record is preserved, including all duplicate
		keys, and a hot key streams through without being collected.

		The output is published only after every read, spill, promotion, merge,
		flush, and close succeeds: the sorted data is written to a temporary sibling
		file and then moved onto the output path. Any failure surfaces a terminating
		error tagged with the stage that failed, leaves an existing output file
		byte-for-byte unchanged, and removes partial work where possible. There is
		no in-memory fallback after a spill or merge failure. An optional fault hook
		is invoked at named internal checkpoints so callers can verify failure
		handling; it is inert when not supplied.

	.OUTPUTS
		A metrics object with Int64 counters (RowsRead, RowsWritten, RunCount,
		MergePassCount, MaxBufferedBytes, MaxBufferedRecords, MaxAccountedBufferBytes,
		LargestRecordBytes, LargestSerializedRecordBytes, MaxRetainedRunDescriptors,
		MaxLevelOccupancy, MaxOpenReaders, TempBytesWritten, ManagedHeapBefore,
		ManagedHeapAfterIngest, ManagedHeapAfterMerge), a CleanupSucceeded flag, and
		a FailureStage string. Metrics carry only aggregate numbers, never data.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$InputPath,
		[Parameter(Mandatory)][string]$OutputPath,
		[Parameter(Mandatory)][string[]]$KeyColumn,
		[Parameter(Mandatory)][ValidateSet('Ordinal', 'OrdinalIgnoreCase')][string]$Comparer,
		[Parameter(Mandatory)][int64]$MemoryBudgetBytes,
		[Parameter(Mandatory)][int]$FanIn,
		[string]$WorkRoot,
		[scriptblock]$ReaderFactory,
		[scriptblock]$WriterFactory,
		[scriptblock]$FaultHook,
		# Optional observability-only progress seam (default inert). ProgressCallback receives an AGGREGATE
		# snapshot object (stage name, elapsed seconds, and Int64 counters copied from the metrics object);
		# it is never passed a row, key, field, filename, or path. ProgressIntervalSeconds throttles periodic
		# emissions; stage-entry and terminal emissions are always sent. A callback exception is swallowed and
		# cannot alter or fail the sort. When ProgressCallback is not supplied the seam is fully inert and the
		# output is byte-identical to a run without it.
		[scriptblock]$ProgressCallback,
		[double]$ProgressIntervalSeconds = 0,
		# Optional starting counter values (default 0). Nonzero seeds let the checked
		# Int64 overflow guards below be reached deterministically without materializing
		# Int64.MaxValue records; at 0 the counters and all output are unchanged.
		[int64]$InitialSequence = 0,
		[int64]$InitialRunCounter = 0,
		[int64]$InitialPromotionCounter = 0
	)
	if ($MemoryBudgetBytes -le 0) { throw 'PaxExternalSort: MemoryBudgetBytes must be positive.' }
	if ($FanIn -lt 2) { throw 'PaxExternalSort: FanIn must be at least 2.' }
	if (-not $ReaderFactory) { $ReaderFactory = { param($p) [System.IO.StreamReader]::new($p, $true) } }
	if (-not $WriterFactory) { $WriterFactory = { param($p) [System.IO.StreamWriter]::new($p, $false, (New-Object System.Text.UTF8Encoding($false))) } }
	$cmp = script:Get-PaxComparer -Name $Comparer
	$metrics = script:New-PaxSortMetrics
	$metrics.ManagedHeapBefore = [int64][System.GC]::GetTotalMemory($true)
	# Progress state is allocated ONLY when a callback is supplied, so a run without one starts no
	# Stopwatch, allocates no progress state, and never enters the emitter in the hot loops below; the
	# managed-heap checkpoints therefore see the same allocations as a run compiled without the seam.
	$prog = $null
	if ($ProgressCallback) {
		$prog = [pscustomobject]@{
			Sw        = [System.Diagnostics.Stopwatch]::StartNew()
			Last      = [double](-1)
			Seen      = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
			MergePass = $null
		}
	}
	# Observability-only progress emitter (inert unless a callback is supplied). It reads aggregate
	# metrics only and never mutates sort state, buffering, ordering, spill thresholds, or output. The
	# first emission for each distinct stage is always sent (stage entry), a forced emission is always
	# sent (terminal events), and other emissions are throttled by ProgressIntervalSeconds. Every
	# callback stream (success, error, warning, verbose, debug, information) is discarded and a
	# terminating callback exception is caught, so callback activity can neither become function output
	# nor alter or fail the sort. No row, key, field, filename, or path is ever passed.
	$emitProgress = {
		param([bool]$Force, [string]$StageName)
		if (-not $ProgressCallback) { return }
		$el = $prog.Sw.Elapsed.TotalSeconds
		$firstForStage = -not $prog.Seen.Contains($StageName)
		if ($firstForStage) { [void]$prog.Seen.Add($StageName) }
		if (-not ($Force -or $firstForStage)) {
			if ($ProgressIntervalSeconds -le 0) { return }
			if ($prog.Last -ge 0 -and ($el - $prog.Last) -lt $ProgressIntervalSeconds) { return }
		}
		$prog.Last = $el
		$snapshot = [pscustomobject]@{
			Stage            = $StageName
			ElapsedSeconds   = [Math]::Round($el, 3)
			RowsRead         = [int64]$metrics.RowsRead
			RowsWritten      = [int64]$metrics.RowsWritten
			RunCount         = [int64]$metrics.RunCount
			MergePassCount   = [int64]$metrics.MergePassCount
			MergePass        = $prog.MergePass
			MaxOpenReaders   = [int64]$metrics.MaxOpenReaders
			TempBytesWritten = [int64]$metrics.TempBytesWritten
			MaxBufferedBytes = [int64]$metrics.MaxBufferedBytes
		}
		try { & $ProgressCallback $snapshot 2>$null 3>$null 4>$null 5>$null 6>$null | Out-Null }
		catch { }
	}
	# Merge-stage observer: forwards intermediate/final merge-pass entries and long-pass heartbeats
	# from the merge primitive to the emitter as aggregate stage events. Inert without a callback.
	$mergeObserver = {
		param([string]$MergeStage, [int]$PassNo)
		if (-not $ProgressCallback) { return }
		if ($PassNo -ge 0) { $prog.MergePass = [int64]$PassNo }
		& $emitProgress $false $MergeStage
	}
	# A level-L run subsumes at least FanIn^L runs; two to the sixty-third already
	# exceeds Int64.MaxValue, so sixty-four fixed levels span the whole positive
	# Int64 run-count domain for any fan-in of at least two.
	$MaxLevels = 64
	if (-not $WorkRoot) { $WorkRoot = $env:TEMP; if (-not $WorkRoot) { $WorkRoot = [System.IO.Path]::GetTempPath() } }
	$workDir = Join-Path $WorkRoot ('pax_extsort_{0}' -f ([System.Guid]::NewGuid().ToString('N')))
	$mergingPath = $OutputPath + '.merging'
	$st = [pscustomobject]@{ Stage = 'Init' }
	$ctr = [pscustomobject]@{ Run = [int64]$InitialRunCounter; Promo = [int64]$InitialPromotionCounter }
	$inReader = $null
	$outWriter = $null
	try {
		$st.Stage = 'Workspace'; [void][System.IO.Directory]::CreateDirectory($workDir)
		$st.Stage = 'Read'
		$inReader = & $ReaderFactory $InputPath
		$header = script:Read-PaxCsvRecord -Reader $inReader
		if ($null -eq $header) { throw 'PaxExternalSort: input has no header record.' }
		$st.Stage = 'KeyMapping'
		$keyIndices = New-Object System.Collections.Generic.List[int]
		foreach ($kc in $KeyColumn) {
			$idx = -1
			for ($i = 0; $i -lt $header.Length; $i++) { if ([System.String]::Equals($header[$i], $kc, [System.StringComparison]::Ordinal)) { $idx = $i; break } }
			if ($idx -lt 0) { throw 'PaxExternalSort: a requested key column is not present in the header.' }
			$keyIndices.Add($idx)
		}
		$ki = $keyIndices.ToArray()
		# Fixed-level compaction state: one bounded run-descriptor list per level.
		$levels = New-Object 'System.Object[]' $MaxLevels
		for ($li = 0; $li -lt $MaxLevels; $li++) { $levels[$li] = New-Object System.Collections.Generic.List[string] }
		# Record the peak persistent run-descriptor count across the fixed levels and
		# the final survivor owner. Fixed fan-in merge argument arrays are transient
		# and never scale with total runs.
		$updDesc = {
			param([int64]$extra)
			$sum = [int64]$extra
			for ($di = 0; $di -lt $MaxLevels; $di++) { $sum += [int64]$levels[$di].Count }
			if ($sum -gt $metrics.MaxRetainedRunDescriptors) { $metrics.MaxRetainedRunDescriptors = $sum }
		}
		# Insert a fresh run at level zero and cascade: a full level merges its
		# fan-in runs into one promoted run, deletes the consumed runs, clears the
		# level, and carries the promotion upward.
		$insertRun = {
			param($newRunPath)
			$carry = $newRunPath
			$lvl = 0
			while ($true) {
				if ($lvl -ge $MaxLevels) { throw 'PaxExternalSort: run-level overflow (Int64 run domain exceeded).' }
				$levels[$lvl].Add($carry)
				if ([int64]$levels[$lvl].Count -gt $metrics.MaxLevelOccupancy) { $metrics.MaxLevelOccupancy = [int64]$levels[$lvl].Count }
				& $updDesc 0
				if ($levels[$lvl].Count -lt $FanIn) { break }
				if ($ctr.Promo -eq [System.Int64]::MaxValue) { $st.Stage = 'PromotionCounterOverflow'; throw 'PaxExternalSort: promotion counter reached Int64.MaxValue; refusing to wrap.' }
				$ctr.Promo++
				$promoted = Join-Path $workDir ('lvl{0:d2}_{1:d6}.paxrun' -f ($lvl + 1), $ctr.Promo)
				$consumed = $levels[$lvl].ToArray()
				$st.Stage = 'PromoteWrite'
				$pw = & $WriterFactory $promoted
				try {
					$st.Stage = 'PromoteRead'
					script:Merge-PaxRunGroup -RunPaths $consumed -KeyIndices $ki -Comparer $cmp -Writer $pw -EmitSequence $true -ReaderFactory $ReaderFactory -Metrics $metrics
					$st.Stage = 'PromoteWrite'
					$pw.Flush()
				}
				finally { $pw.Close(); $pw.Dispose() }
				$pfi = [System.IO.FileInfo]::new($promoted); if ($pfi.Exists) { $metrics.TempBytesWritten += [int64]$pfi.Length }
				$st.Stage = 'PromoteDelete'
				foreach ($cp in $consumed) { if (Test-Path -LiteralPath $cp) { Remove-Item -LiteralPath $cp -Force -ErrorAction Stop } }
				$levels[$lvl].Clear()
				if ($FaultHook) { $st.Stage = 'PromoteState'; & $FaultHook 'PromoteState' }
				$metrics.MergePassCount++
				& $emitProgress $false 'Promote'
				$carry = $promoted
				$lvl++
			}
		}
		$spill = {
			param($buf)
			if ($buf.Count -eq 0) { return }
			$buf.Sort([System.Comparison[object[]]] {
					param($x, $y)
					$k = $cmp.Compare([string]$x[0], [string]$y[0])
					if ($k -ne 0) { return $k }
					return ([int64]$x[1]).CompareTo([int64]$y[1])
				})
			if ($ctr.Run -eq [System.Int64]::MaxValue) { $st.Stage = 'RunCounterOverflow'; throw 'PaxExternalSort: run counter reached Int64.MaxValue; refusing to wrap.' }
			$ctr.Run++
			$st.Stage = 'RunCreate'
			$rp = Join-Path $workDir ('run_{0:d6}.paxrun' -f $ctr.Run)
			$w = & $WriterFactory $rp
			$st.Stage = 'Spill'
			try {
				foreach ($it in $buf) {
					$w.Write(([int64]$it[1]).ToString([System.Globalization.CultureInfo]::InvariantCulture))
					$w.Write(',')
					$w.Write([string]$it[2])
					$w.Write("`r`n")
				}
				$w.Flush()
			}
			finally { $w.Close(); $w.Dispose() }
			$fi = [System.IO.FileInfo]::new($rp); if ($fi.Exists) { $metrics.TempBytesWritten += [int64]$fi.Length }
			$metrics.RunCount++
			& $emitProgress $false 'Spill'
			& $insertRun $rp
		}
		$buffer = New-Object 'System.Collections.Generic.List[object[]]'
		$bufferedBytes = [int64]0
		$seq = [int64]$InitialSequence
		$st.Stage = 'Read'
		& $emitProgress $true 'Ingest'
		while ($true) {
			$rec = script:Read-PaxCsvRecord -Reader $inReader
			if ($null -eq $rec) { break }
			$metrics.RowsRead++
			if ($ProgressCallback -and (($metrics.RowsRead -band 255) -eq 0)) { & $emitProgress $false 'Ingest' }
			if ($seq -eq [System.Int64]::MaxValue) { $st.Stage = 'SequenceOverflow'; throw 'PaxExternalSort: ingest sequence reached Int64.MaxValue; refusing to wrap.' }
			$seq++
			$key = script:Get-PaxCompositeKey -Fields $rec -KeyIndices $ki
			$dataLine = script:ConvertTo-PaxCsvLine -Fields $rec
			$seqStr = $seq.ToString([System.Globalization.CultureInfo]::InvariantCulture)
			$serBytes = [int64][System.Text.Encoding]::UTF8.GetByteCount($seqStr + ',' + $dataLine)
			if ($serBytes -gt $metrics.LargestSerializedRecordBytes) { $metrics.LargestSerializedRecordBytes = $serBytes }
			$payloadBytes = [int64][System.Text.Encoding]::UTF8.GetByteCount($dataLine)
			if ($payloadBytes -gt $metrics.LargestRecordBytes) { $metrics.LargestRecordBytes = $payloadBytes }
			$accounted = script:Get-PaxRetainedRecordBytes -Key $key -Data $dataLine
			if ($buffer.Count -gt 0 -and ($bufferedBytes + $accounted) -gt $MemoryBudgetBytes) {
				& $spill $buffer
				$buffer = New-Object 'System.Collections.Generic.List[object[]]'
				$bufferedBytes = [int64]0
				$st.Stage = 'Read'
			}
			$buffer.Add([object[]]@($key, $seq, $dataLine))
			$bufferedBytes += $accounted
			if ($bufferedBytes -gt $metrics.MaxBufferedBytes) { $metrics.MaxBufferedBytes = $bufferedBytes }
			if ($bufferedBytes -gt $metrics.MaxAccountedBufferBytes) { $metrics.MaxAccountedBufferBytes = $bufferedBytes }
			if ([int64]$buffer.Count -gt $metrics.MaxBufferedRecords) { $metrics.MaxBufferedRecords = [int64]$buffer.Count }
			if ($accounted -gt $MemoryBudgetBytes) {
				& $spill $buffer
				$buffer = New-Object 'System.Collections.Generic.List[object[]]'
				$bufferedBytes = [int64]0
				$st.Stage = 'Read'
			}
		}
		if ($buffer.Count -gt 0) { & $spill $buffer; $buffer = $null }
		$st.Stage = 'Read'
		if ($inReader) { $inReader.Close(); $inReader.Dispose(); $inReader = $null }
		$metrics.ManagedHeapAfterIngest = [int64][System.GC]::GetTotalMemory($true)
		# Move the fixed-bounded surviving run descriptors out of the compaction
		# levels. Clearing each source level as its paths transfer prevents retaining
		# duplicate references in both the level set and the final survivor owner.
		$survivors = New-Object System.Collections.Generic.List[string]
		for ($li = 0; $li -lt $MaxLevels; $li++) {
			foreach ($rp in $levels[$li]) { $survivors.Add($rp) }
			$levels[$li].Clear()
			& $updDesc ([int64]$survivors.Count)
		}
		$st.Stage = 'Publish'
		$outWriter = & $WriterFactory $mergingPath
		try {
			script:Write-PaxCsvRecord -Writer $outWriter -Fields $header
			if ($FaultHook) { $st.Stage = 'FinalMerge'; & $FaultHook 'FinalMerge' }
			$st.Stage = 'Merge'
			script:Merge-PaxSortedRuns -RunPaths $survivors.ToArray() -KeyIndices $ki -Comparer $cmp -FanIn $FanIn -OutputWriter $outWriter -WorkDir $workDir -ReaderFactory $ReaderFactory -WriterFactory $WriterFactory -Metrics $metrics -ProgressObserver $mergeObserver
			$st.Stage = 'Publish'
			$outWriter.Flush()
		}
		finally { $outWriter.Close(); $outWriter.Dispose(); $outWriter = $null }
		$metrics.ManagedHeapAfterMerge = [int64][System.GC]::GetTotalMemory($true)
		$st.Stage = 'Publish'
		Move-Item -LiteralPath $mergingPath -Destination $OutputPath -Force -ErrorAction Stop
		& $emitProgress $true 'Publish'
		$st.Stage = 'Cleanup'
		& $emitProgress $true 'Cleanup'
		script:Remove-PaxWorkspace -WorkDir $workDir -MergingPath $null -Metrics $metrics
		& $emitProgress $true 'Complete'
		return $metrics
	}
	catch {
		$primary = $_
		if (-not $metrics.FailureStage) { $metrics.FailureStage = $st.Stage }
		& $emitProgress $true 'Failed'
		if ($inReader) { try { $inReader.Close(); $inReader.Dispose() } catch { } }
		if ($outWriter) { try { $outWriter.Close(); $outWriter.Dispose() } catch { } }
		script:Remove-PaxWorkspace -WorkDir $workDir -MergingPath $mergingPath -Metrics $metrics
		$ex = [System.Exception]::new(("PaxExternalSort failed at stage '{0}'." -f $metrics.FailureStage), $primary.Exception)
		$er = [System.Management.Automation.ErrorRecord]::new($ex, 'PaxExternalSortFailed', [System.Management.Automation.ErrorCategory]::NotSpecified, $metrics)
		throw $er
	}
}
#endregion PAX-S2

function script:Get-PaxDedupedFactHeader {
	# Deduplicate a raw CSV header the same way the tolerant importer does: strip a
	# leading byte-order mark from the first cell, trim each cell, replace a blank
	# cell with _blank, and suffix later case-insensitive duplicates with _dup2,
	# _dup3, and so on while the first occurrence keeps its name. The result is the
	# stable column identity used for keying, cross-run continuity, and the header
	# union.
	[CmdletBinding()]
	param([Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Cells)
	$seen = [System.Collections.Generic.Dictionary[string, int]]::new([System.StringComparer]::OrdinalIgnoreCase)
	$out = New-Object System.Collections.Generic.List[string]
	for ($i = 0; $i -lt $Cells.Length; $i++) {
		$n = [string]$Cells[$i]
		if ($null -eq $n) { $n = '' }
		if ($i -eq 0) { $n = $n -replace '^\uFEFF', '' }
		$n = $n.Trim()
		if ([string]::IsNullOrEmpty($n)) { $n = '_blank' }
		if ($seen.ContainsKey($n)) {
			$seen[$n] = $seen[$n] + 1
			$out.Add(('{0}_dup{1}' -f $n, $seen[$n]))
		}
		else {
			$seen[$n] = 1
			$out.Add($n)
		}
	}
	return , $out.ToArray()
}

function script:ConvertTo-PaxFactNormalized {
	# Stream a Fact CSV into a normalized work file whose header is the two
	# synthetic columns __paxk and __paxseq followed by the deduplicated source
	# header, and whose every data row carries its composite key, its zero-padded
	# read-order sequence, and the source field values positionally aligned to the
	# deduplicated header. The composite key joins the requested key columns with
	# U+001F (a single key column contributes its value unseparated); a requested
	# column absent from the header contributes an empty segment. Reading uses the
	# bounded RFC-4180 record reader and writing uses the RFC-4180 record writer, so
	# memory stays bounded regardless of file size. Returns the deduplicated header,
	# the data-row count, and whether a header record was present. An absent header
	# (empty input) yields a null header and zero rows.
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$InputPath,
		[Parameter(Mandatory)][string]$OutputPath,
		[Parameter(Mandatory)][AllowEmptyCollection()][string[]]$KeyColumns
	)
	$reader = [System.IO.StreamReader]::new($InputPath, $true)
	try {
		$header = script:Read-PaxCsvRecord -Reader $reader
		if ($null -eq $header) {
			return [pscustomobject]@{ Header = $null; RowCount = [int64]0; HadHeader = $false }
		}
		$deduped = script:Get-PaxDedupedFactHeader -Cells $header
		$idxMap = [System.Collections.Generic.Dictionary[string, int]]::new([System.StringComparer]::OrdinalIgnoreCase)
		for ($i = 0; $i -lt $deduped.Length; $i++) { $idxMap[$deduped[$i]] = $i }
		$keyIndices = New-Object System.Collections.Generic.List[int]
		foreach ($kc in $KeyColumns) {
			if ($idxMap.ContainsKey($kc)) { $keyIndices.Add($idxMap[$kc]) } else { $keyIndices.Add(-1) }
		}
		$ki = $keyIndices.ToArray()
		$writer = [System.IO.StreamWriter]::new($OutputPath, $false, (New-Object System.Text.UTF8Encoding($false)))
		try {
			script:Write-PaxCsvRecord -Writer $writer -Fields (@('__paxk', '__paxseq') + $deduped)
			$rowCount = [int64]0
			while ($true) {
				$rec = script:Read-PaxCsvRecord -Reader $reader
				if ($null -eq $rec) { break }
				$paxk = script:Get-PaxCompositeKey -Fields $rec -KeyIndices $ki
				$paxseq = $rowCount.ToString('D19')
				$data = [string[]]::new($deduped.Length)
				for ($j = 0; $j -lt $deduped.Length; $j++) { $data[$j] = if ($j -lt $rec.Length) { $rec[$j] } else { '' } }
				script:Write-PaxCsvRecord -Writer $writer -Fields (@($paxk, $paxseq) + $data)
				$rowCount++
			}
			$writer.Flush()
		}
		finally { $writer.Dispose() }
		return [pscustomobject]@{ Header = $deduped; RowCount = $rowCount; HadHeader = $true }
	}
	finally { $reader.Dispose() }
}

function script:Read-PaxFactNextTargetGroup {
	# Return the next distinct non-empty target key group from a sorted normalized
	# target stream, or $null at end of input. Rows arrive grouped by key (a blank
	# key sorts ahead of keyed rows) and, within a key, ordered by read sequence, so
	# the first row seen for a group is that key's first original occurrence. No-key
	# rows are skipped entirely and duplicate rows of the returned key are consumed
	# and discarded; a single peeked row that starts the next thing is stashed on
	# the state object so the following call resumes correctly. The state object
	# carries the open reader plus a one-record pending slot; the returned value is
	# a table with the group Key and the first-occurrence Fields.
	[CmdletBinding()]
	param([Parameter(Mandatory)][psobject]$State)
	while ($true) {
		if ($State.HasPending) { $row = $State.Pending; $State.Pending = $null; $State.HasPending = $false }
		else { $row = script:Read-PaxCsvRecord -Reader $State.Reader }
		if ($null -eq $row) { return $null }
		$k = if ($row.Length -gt 0) { [string]$row[0] } else { '' }
		if ([string]::IsNullOrWhiteSpace($k)) { continue }
		$gk = $k
		$first = $row
		while ($true) {
			$peek = script:Read-PaxCsvRecord -Reader $State.Reader
			if ($null -eq $peek) { break }
			$pk = if ($peek.Length -gt 0) { [string]$peek[0] } else { '' }
			if ([string]::IsNullOrWhiteSpace($pk)) { $State.Pending = $peek; $State.HasPending = $true; break }
			if ([System.String]::Equals($pk, $gk, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
			$State.Pending = $peek; $State.HasPending = $true; break
		}
		return @{ Key = $gk; Fields = $first }
	}
}

function Merge-FactCsv {
	<#
	.SYNOPSIS
		Union-merge a target Interactions/Fact CSV with the current run's freshly-emitted Fact CSV.

	.DESCRIPTION
		Post-Python helper for -AppendFile. Mirrors Merge-UsersCsv semantics but for the
		fact CSV. Keyed on -KeyColumn (default 'Message_Id_Raw' for the rollup Fact CSV;
		pass 'RecordId' for the raw audit CSV used by non-rollup -AppendFile). By default
		the union is written in place of the current-run CSV (rollup semantics). Pass
		-OutputPath to direct the union to a third path so the current-run CSV remains
		pristine (the pristine-raw separation pattern used by non-rollup -AppendFile).

		When -KeyColumn is 'Message_Id_Raw' the target's Message_Id INT is carried
		forward on retained rows (continuity across runs). For any other key column the
		current-run row's values are taken verbatim (target serves only as the source
		of departed rows).

		Atomic rewrite: writes to '<output>.merging' then renames over the output path.

	.OUTPUTS
		Hashtable with stats (Retained / New / Departed / Union).
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $TargetFactCsv,
		[Parameter(Mandatory)] [string] $CurrentFactCsv,
		[Parameter()]          [string] $OutputPath,
		[Parameter()]          [string] $KeyColumn = 'Message_Id_Raw',
		[Parameter()]          [string[]] $CompositeKeyColumn = @(),
		[Parameter()]          [string] $RunDate = (Get-Date -Format 'yyyy-MM-dd'),
		[Parameter()]          [scriptblock] $ProgressCallback,
		[Parameter()]          [double] $ProgressIntervalSeconds = 0
	)
	if (-not (Test-Path -LiteralPath $CurrentFactCsv -PathType Leaf)) {
		throw "Merge-FactCsv: current Fact CSV not found: '$CurrentFactCsv'"
	}
	if ([string]::IsNullOrWhiteSpace($OutputPath)) { $OutputPath = $CurrentFactCsv }
	# Grain-composite dedup key. When -CompositeKeyColumn is supplied a row's key is
	# the U+001F-joined values of those columns (ASCII Unit Separator 0x1F is a
	# control char that never appears in audit field data), so fan-out fact rows
	# (many per Message_Id_Raw) are each keyed distinctly instead of collapsing to
	# one. Otherwise the single -KeyColumn is used (RecordId raw-audit path). The key
	# is computed for every row while it is streamed into a normalized work file.
	$useCompositeKey = ($null -ne $CompositeKeyColumn -and @($CompositeKeyColumn).Count -gt 0)
	$keyColumns = if ($useCompositeKey) { @($CompositeKeyColumn) } else { @($KeyColumn) }

	# All materialization is disk-backed and bounded: source rows are streamed into
	# normalized work files, externally sorted by (key, read-order) under a fixed
	# memory budget, joined in a single linear pass that holds at most one record per
	# side, and streamed back out. Nothing accumulates a whole file in memory.
	$memoryBudgetBytes = [int64]67108864
	$fanIn = 8
	$workDir = Join-Path $env:TEMP ('pax_factmerge_{0}' -f ([System.Guid]::NewGuid().ToString('N')))
	$mergingPath = "$OutputPath.merging"
	$cleanupMetrics = script:New-PaxSortMetrics

	# Coarse stage observability. Merge-FactCsv narrates its bounded pipeline as a
	# fixed vocabulary of stage markers (Inspecting inputs, Normalizing existing
	# target, Sorting existing target, Normalizing current run, Sorting current run,
	# Reconciling rows, Restoring current order, Restoring departed order, Publishing,
	# Cleanup, Complete, Failed). Each marker is surfaced through the run's normal
	# host/log channel and recorded as a memory observation so a long field-scale
	# reconciliation shows forward progress and per-stage memory. The logging helpers
	# live in the full processor; when Merge-FactCsv is dot-sourced in isolation (unit
	# extraction) they are absent, so emission resolves them once and stays fully
	# inert if unavailable.
	$logHostCmd = Microsoft.PowerShell.Core\Get-Command -Name 'Write-LogHost' -CommandType Function -ErrorAction SilentlyContinue
	$memObsCmd  = Microsoft.PowerShell.Core\Get-Command -Name 'Write-PaxMemoryObservation' -CommandType Function -ErrorAction SilentlyContinue
	$emitStage = {
		param([string]$StageName, [string]$Detail = '')
		$msg = if ($Detail) { "Fact append merge - $StageName ($Detail)" } else { "Fact append merge - $StageName" }
		if ($logHostCmd) { try { & $logHostCmd -Message $msg -ForegroundColor 'Gray' } catch { } }
		if ($memObsCmd)  { try { & $memObsCmd -Stage ("FactMerge:" + $StageName) -TempDir $workDir -Force } catch { } }
	}
	try {
		[void][System.IO.Directory]::CreateDirectory($workDir)
		& $emitStage 'Inspecting inputs'

		# 1. Normalize the target: stream every physical data row into tgt_norm with
		#    its key and read-order sequence. targetRowCount counts ALL data rows
		#    (including no-key and duplicate-key rows) for the shrink guard.
		$hasTarget = Test-Path -LiteralPath $TargetFactCsv -PathType Leaf
		$targetLen = if ($hasTarget) { [int64](Get-Item -LiteralPath $TargetFactCsv).Length } else { [int64]0 }
		$tgtNorm = Join-Path $workDir 'tgt_norm.csv'
		$dedupedTargetHeader = $null
		$targetRowCount = [int64]0
		if ($hasTarget) {
			& $emitStage 'Normalizing existing target'
			$tgtInfo = script:ConvertTo-PaxFactNormalized -InputPath $TargetFactCsv -OutputPath $tgtNorm -KeyColumns $keyColumns
			$dedupedTargetHeader = $tgtInfo.Header
			$targetRowCount = [int64]$tgtInfo.RowCount
		}

		# APPEND SAFETY (data-loss guard): if the target file exists with content but parsed to
		# zero rows, the read failed (parse/encoding/memory) or the key cannot be matched.
		# Overwriting would replace the existing target file with current-run rows only (a
		# row-count shrink). Abort instead so the existing target is left untouched; the caller keeps the
		# fresh current-run CSV on disk for a manual merge.
		if ($targetRowCount -eq 0 -and $hasTarget -and $targetLen -gt 0) {
			throw "Merge-FactCsv: target '$TargetFactCsv' exists with content but parsed to 0 rows; refusing to overwrite (would discard existing data). Verify the file's schema/key column ('$KeyColumn')."
		}

		# Schema-narrowing warning. The only header we strictly require on the target
		# is the dedup key (-KeyColumn) — without it the union cannot correctly
		# classify Retained vs New vs Departed. Display / enrichment columns
		# (PersonId_Normalized, ThreadId, Message_Id, etc.) are intentionally renamed
		# or surrogate-replaced by the rollup processor on the rolled-up Fact CSV, so
		# checking for them here would produce false-positive warnings on every
		# rollup-shape seed. Header union handles legitimately absent display columns
		# gracefully (target rows get blanks for current-only fields; current rows
		# get blanks for target-only fields). $targetKeyMissing gates the later
		# zero-overlap caution off this data-quality case (retained=0 there means the
		# key could not be classified, not that the two nonempty sets were disjoint).
		$targetKeyMissing = $false
		if ($targetRowCount -gt 0) {
			$requiredKeyCols = if ($useCompositeKey) { @($CompositeKeyColumn) } else { @($KeyColumn) }
			$missingKeyCols  = @($requiredKeyCols | Where-Object { $_ -notin $dedupedTargetHeader })
			if ($missingKeyCols.Count -gt 0) {
				$targetKeyMissing = $true
				Microsoft.PowerShell.Utility\Write-Host (
					("WARNING: Merge-FactCsv: target Fact CSV is missing dedup key column(s) '{0}'. " +
					 "Cannot classify Retained / New / Departed rows reliably; treating ALL current-run rows as New. " +
					 "Target: {1}") -f ($missingKeyCols -join ', '), $TargetFactCsv
				) -ForegroundColor Yellow
			}
		}

		# 2. Sort the normalized target by (key, read-order). Duplicate keys stay
		#    grouped with the first original occurrence first; no-key rows sort ahead
		#    of keyed rows and are skipped by the join.
		$tgtSorted = Join-Path $workDir 'tgt_sorted.csv'
		if ($targetRowCount -gt 0) {
			& $emitStage 'Sorting existing target'
			$null = script:Invoke-PaxExternalSort -InputPath $tgtNorm -OutputPath $tgtSorted -KeyColumn @('__paxk', '__paxseq') -Comparer 'OrdinalIgnoreCase' -MemoryBudgetBytes $memoryBudgetBytes -FanIn $fanIn -WorkRoot $workDir -ProgressCallback $ProgressCallback -ProgressIntervalSeconds $ProgressIntervalSeconds
		}

		# 3. Normalize the current run the same way.
		$curNorm = Join-Path $workDir 'cur_norm.csv'
		& $emitStage 'Normalizing current run'
		$curInfo = script:ConvertTo-PaxFactNormalized -InputPath $CurrentFactCsv -OutputPath $curNorm -KeyColumns $keyColumns
		$dedupedCurrentHeader = $curInfo.Header
		$currentRowCount = [int64]$curInfo.RowCount

		# 4. Sort the normalized current run by (key, read-order).
		$curSorted = Join-Path $workDir 'cur_sorted.csv'
		if ($currentRowCount -gt 0) {
			& $emitStage 'Sorting current run'
			$null = script:Invoke-PaxExternalSort -InputPath $curNorm -OutputPath $curSorted -KeyColumn @('__paxk', '__paxseq') -Comparer 'OrdinalIgnoreCase' -MemoryBudgetBytes $memoryBudgetBytes -FanIn $fanIn -WorkRoot $workDir -ProgressCallback $ProgressCallback -ProgressIntervalSeconds $ProgressIntervalSeconds
		}

		# 5. Header union: preserve current-run order, then append target-only columns,
		#    then provenance — deduplicated case-insensitively.
		$hdrSet   = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
		$hdrOrder = New-Object System.Collections.Generic.List[string]
		if ($currentRowCount -gt 0 -and $dedupedCurrentHeader) {
			foreach ($n in $dedupedCurrentHeader) { if ($hdrSet.Add($n)) { $hdrOrder.Add($n) } }
		}
		if ($targetRowCount -gt 0 -and $dedupedTargetHeader) {
			foreach ($n in $dedupedTargetHeader) { if ($hdrSet.Add($n)) { $hdrOrder.Add($n) } }
		}
		foreach ($c in @('Date_Added', 'Latest_Append_Date', 'In_Latest_Append')) {
			if ($hdrSet.Add($c)) { $hdrOrder.Add($c) }
		}
		$hdrArr = [string[]]$hdrOrder.ToArray()
		$hdrIndex = [System.Collections.Generic.Dictionary[string, int]]::new([System.StringComparer]::OrdinalIgnoreCase)
		for ($i = 0; $i -lt $hdrArr.Length; $i++) { $hdrIndex[$hdrArr[$i]] = $i }
		$idxDateAdded = $hdrIndex['Date_Added']
		$idxLatest    = $hdrIndex['Latest_Append_Date']
		$idxInLatest  = $hdrIndex['In_Latest_Append']
		$hasMessageId = $hdrIndex.ContainsKey('Message_Id')
		$idxMessageId = if ($hasMessageId) { $hdrIndex['Message_Id'] } else { -1 }

		# Map each normalized data column to its union position (case-insensitive), and
		# locate the target's own Message_Id / Date_Added columns for continuity.
		$curColToHdr = [int[]]::new(0)
		if ($dedupedCurrentHeader) {
			$curColToHdr = [int[]]::new($dedupedCurrentHeader.Length)
			for ($j = 0; $j -lt $dedupedCurrentHeader.Length; $j++) { $curColToHdr[$j] = $hdrIndex[$dedupedCurrentHeader[$j]] }
		}
		$tgtColToHdr = [int[]]::new(0)
		$tgtMidIdx = -1
		$tgtDaIdx  = -1
		if ($dedupedTargetHeader) {
			$tgtColToHdr = [int[]]::new($dedupedTargetHeader.Length)
			for ($j = 0; $j -lt $dedupedTargetHeader.Length; $j++) {
				$tgtColToHdr[$j] = $hdrIndex[$dedupedTargetHeader[$j]]
				if ([System.String]::Equals($dedupedTargetHeader[$j], 'Message_Id', [System.StringComparison]::OrdinalIgnoreCase)) { $tgtMidIdx = $j }
				if ([System.String]::Equals($dedupedTargetHeader[$j], 'Date_Added', [System.StringComparison]::OrdinalIgnoreCase)) { $tgtDaIdx = $j }
			}
		}

		# 6. Message_Id continuity applies when the dedup key is (or contains)
		#    Message_Id_Raw; then the target's Message_Id INT is carried forward on
		#    retained rows for cross-run continuity. For other single key columns
		#    (e.g. RecordId on the raw audit CSV) the current row's values stand.
		$messageIdContinuity = ($KeyColumn -eq 'Message_Id_Raw') -or ($useCompositeKey -and (@($CompositeKeyColumn) -contains 'Message_Id_Raw'))

		# Union-row builders. Section-1 rows overlay the current row's own columns
		# then apply continuity/provenance; departed rows overlay the target row's
		# columns then apply provenance. Both return a full union-width field array.
		$buildSection1 = {
			param([string[]]$CurData, [bool]$Matched, [object]$HeldFields)
			$u = [string[]]::new($hdrArr.Length)
			for ($i = 0; $i -lt $u.Length; $i++) { $u[$i] = '' }
			for ($j = 0; $j -lt $curColToHdr.Length; $j++) { if ($j -lt $CurData.Length) { $u[$curColToHdr[$j]] = $CurData[$j] } }
			if ($Matched) {
				if ($messageIdContinuity -and $hasMessageId) {
					$tv = if ($tgtMidIdx -ge 0 -and (2 + $tgtMidIdx) -lt $HeldFields.Length) { [string]$HeldFields[2 + $tgtMidIdx] } else { '' }
					if (-not [string]::IsNullOrWhiteSpace($tv)) { $u[$idxMessageId] = $tv }
				}
				$tda = if ($tgtDaIdx -ge 0 -and (2 + $tgtDaIdx) -lt $HeldFields.Length) { [string]$HeldFields[2 + $tgtDaIdx] } else { '' }
				if (-not [string]::IsNullOrWhiteSpace($tda)) { $u[$idxDateAdded] = $tda } else { $u[$idxDateAdded] = $RunDate }
			}
			else {
				$u[$idxDateAdded] = $RunDate
			}
			$u[$idxLatest]   = $RunDate
			$u[$idxInLatest] = 'TRUE'
			return , $u
		}
		$buildDeparted = {
			param([object]$HeldFields)
			$u = [string[]]::new($hdrArr.Length)
			for ($i = 0; $i -lt $u.Length; $i++) { $u[$i] = '' }
			for ($j = 0; $j -lt $tgtColToHdr.Length; $j++) { $s = 2 + $j; if ($s -lt $HeldFields.Length) { $u[$tgtColToHdr[$j]] = [string]$HeldFields[$s] } }
			if ([string]::IsNullOrWhiteSpace($u[$idxDateAdded])) { $u[$idxDateAdded] = $RunDate }
			$u[$idxLatest]   = $RunDate
			$u[$idxInLatest] = 'FALSE'
			return , $u
		}

		# 7. Bounded left-join pass. Walk the sorted current rows, emitting every one
		#    to the section-1 side file tagged with its read-order sequence. Advance
		#    the sorted target one distinct key at a time (first occurrence only,
		#    no-key rows skipped); a target key never matched by a current key becomes
		#    one departed row. Stats count DISTINCT non-empty current keys.
		$sec1Side = Join-Path $workDir 'sec1_side.csv'
		$depSide  = Join-Path $workDir 'dep_side.csv'
		$sideHdr  = @('__paxseq') + $hdrArr
		$retainedCount = 0
		$newCount      = 0
		$departedCount = 0
		& $emitStage 'Reconciling rows'

		$sec1Writer = [System.IO.StreamWriter]::new($sec1Side, $false, (New-Object System.Text.UTF8Encoding($false)))
		$depWriter  = [System.IO.StreamWriter]::new($depSide, $false, (New-Object System.Text.UTF8Encoding($false)))
		$curReader  = $null
		$tgtState   = $null
		try {
			script:Write-PaxCsvRecord -Writer $sec1Writer -Fields $sideHdr
			script:Write-PaxCsvRecord -Writer $depWriter  -Fields $sideHdr

			if ($targetRowCount -gt 0) {
				$tgtReader = [System.IO.StreamReader]::new($tgtSorted, $true)
				$null = script:Read-PaxCsvRecord -Reader $tgtReader
				$tgtState = [pscustomobject]@{ Reader = $tgtReader; Pending = $null; HasPending = $false }
			}
			$held = if ($tgtState) { script:Read-PaxFactNextTargetGroup -State $tgtState } else { $null }
			$heldMatched = $false

			$emitDeparted = {
				param($Group)
				$du = & $buildDeparted $Group.Fields
				script:Write-PaxCsvRecord -Writer $depWriter -Fields (@([string]$Group.Fields[1]) + $du)
			}

			if ($currentRowCount -gt 0) {
				$curReader = [System.IO.StreamReader]::new($curSorted, $true)
				$null = script:Read-PaxCsvRecord -Reader $curReader
				$havePrev = $false
				$prevKey  = $null
				while ($true) {
					$row = script:Read-PaxCsvRecord -Reader $curReader
					if ($null -eq $row) { break }
					$kc = [string]$row[0]
					$curPaxseq = [string]$row[1]
					$curData = if ($row.Length -gt 2) { $row[2..($row.Length - 1)] } else { @() }
					if ([string]::IsNullOrWhiteSpace($kc)) {
						$su = & $buildSection1 $curData $false $null
						script:Write-PaxCsvRecord -Writer $sec1Writer -Fields (@($curPaxseq) + $su)
						continue
					}
					while ($null -ne $held -and [System.StringComparer]::OrdinalIgnoreCase.Compare([string]$held.Key, $kc) -lt 0) {
						if (-not $heldMatched) { & $emitDeparted $held; $departedCount++ }
						$held = script:Read-PaxFactNextTargetGroup -State $tgtState
						$heldMatched = $false
					}
					$matched = ($null -ne $held -and [System.String]::Equals([string]$held.Key, $kc, [System.StringComparison]::OrdinalIgnoreCase))
					if ($matched) { $heldMatched = $true }
					$isNewDistinct = (-not $havePrev) -or (-not [System.String]::Equals($kc, $prevKey, [System.StringComparison]::OrdinalIgnoreCase))
					if ($isNewDistinct) { if ($matched) { $retainedCount++ } else { $newCount++ } }
					$havePrev = $true
					$prevKey  = $kc
					$heldFieldsForBuild = if ($matched) { $held.Fields } else { $null }
					$su = & $buildSection1 $curData $matched $heldFieldsForBuild
					script:Write-PaxCsvRecord -Writer $sec1Writer -Fields (@($curPaxseq) + $su)
				}
			}
			# Flush the remaining unmatched target groups as departed rows.
			while ($null -ne $held) {
				if (-not $heldMatched) { & $emitDeparted $held; $departedCount++ }
				$held = if ($tgtState) { script:Read-PaxFactNextTargetGroup -State $tgtState } else { $null }
				$heldMatched = $false
			}

			$sec1Writer.Flush()
			$depWriter.Flush()
		}
		finally {
			if ($curReader) { $curReader.Dispose() }
			if ($tgtState -and $tgtState.Reader) { $tgtState.Reader.Dispose() }
			$sec1Writer.Dispose()
			$depWriter.Dispose()
		}

		# 8. Restore original ordering: section-1 rows to current read order, departed
		#    rows to target first-occurrence order.
		$sec1Sorted = Join-Path $workDir 'sec1_sorted.csv'
		if ($currentRowCount -gt 0) {
			& $emitStage 'Restoring current order'
			$null = script:Invoke-PaxExternalSort -InputPath $sec1Side -OutputPath $sec1Sorted -KeyColumn @('__paxseq') -Comparer 'Ordinal' -MemoryBudgetBytes $memoryBudgetBytes -FanIn $fanIn -WorkRoot $workDir -ProgressCallback $ProgressCallback -ProgressIntervalSeconds $ProgressIntervalSeconds
		}
		$depSorted = Join-Path $workDir 'dep_sorted.csv'
		if ($departedCount -gt 0) {
			& $emitStage 'Restoring departed order'
			$null = script:Invoke-PaxExternalSort -InputPath $depSide -OutputPath $depSorted -KeyColumn @('__paxseq') -Comparer 'Ordinal' -MemoryBudgetBytes $memoryBudgetBytes -FanIn $fanIn -WorkRoot $workDir -ProgressCallback $ProgressCallback -ProgressIntervalSeconds $ProgressIntervalSeconds
		}

		# 9. APPEND SAFETY (shrink guard): a union must never be smaller than the existing target.
		# If the target keyed but the dedup column did not match (Retained+Departed=0 while the
		# target had rows), the union collapses to current-only rows and the file shrinks. Abort
		# before any write so the target is preserved.
		$unionCount = [int64]$currentRowCount + [int64]$departedCount
		if ($targetRowCount -gt 0 -and $unionCount -lt $targetRowCount) {
			throw ("Merge-FactCsv: refusing to write a smaller file than the target (union={0} < target={1}); key '{2}' likely did not match. Target left unchanged." -f $unionCount, $targetRowCount, $KeyColumn)
		}

		# 10. Publish: write the header, then the ordered section-1 rows, then the
		#     ordered departed rows, each with the sequence column dropped. Write to a
		#     sibling .merging file and rename onto the output path so the target is
		#     byte-unchanged unless every step succeeds.
		$pubWriter = [System.IO.StreamWriter]::new($mergingPath, $false, (New-Object System.Text.UTF8Encoding($false)))
		& $emitStage 'Publishing'
		try {
			script:Write-PaxCsvRecord -Writer $pubWriter -Fields $hdrArr
			if ($currentRowCount -gt 0) {
				$sr = [System.IO.StreamReader]::new($sec1Sorted, $true)
				try {
					$null = script:Read-PaxCsvRecord -Reader $sr
					while ($true) { $rec = script:Read-PaxCsvRecord -Reader $sr; if ($null -eq $rec) { break }; script:Write-PaxCsvRecord -Writer $pubWriter -Fields ($rec[1..($rec.Length - 1)]) }
				}
				finally { $sr.Dispose() }
			}
			if ($departedCount -gt 0) {
				$dr = [System.IO.StreamReader]::new($depSorted, $true)
				try {
					$null = script:Read-PaxCsvRecord -Reader $dr
					while ($true) { $rec = script:Read-PaxCsvRecord -Reader $dr; if ($null -eq $rec) { break }; script:Write-PaxCsvRecord -Writer $pubWriter -Fields ($rec[1..($rec.Length - 1)]) }
				}
				finally { $dr.Dispose() }
			}
			$pubWriter.Flush()
		}
		finally { $pubWriter.Dispose() }
		# Fail closed if the rename cannot complete (e.g. the target is locked by a
		# sync client or scanner): a non-terminating move would return success while
		# the target still holds its old content and the merged output is discarded.
		Move-Item -LiteralPath $mergingPath -Destination $OutputPath -Force -ErrorAction Stop

		# 11. Stats.
		& $emitStage 'Cleanup'
		& $emitStage 'Complete'
		# Zero-overlap caution (count-only). A nonempty target and a nonempty current run
		# that share NO keys is a VALID outcome for disjoint windows: every current row is
		# New, every unmatched target row is Departed, and the lossless union is preserved.
		# Surface it (aggregate counts only — never keys, identities, filenames, or paths)
		# so a disjoint-window append is not mistaken for an error. Never thrown, never
		# changes counts or provenance. Suppressed when the key column was missing from the
		# target ($targetKeyMissing) — that data-quality case owns its own WARNING above and
		# is not a genuine disjoint-set overlap. Emitted at most once, via the same resolved
		# host helper as the stage markers (inert when Merge-FactCsv is dot-sourced alone).
		if ($targetRowCount -gt 0 -and $currentRowCount -gt 0 -and $retainedCount -eq 0 -and -not $targetKeyMissing -and $logHostCmd) {
			try {
				& $logHostCmd -Message (
					("Fact append merge found no overlapping keys between the existing target and this run. " +
					 "All current rows are classified as New and unmatched target rows as Departed. " +
					 "The lossless union was preserved. " +
					 "Target rows={0:N0}  Current rows={1:N0}  Retained={2:N0}  New={3:N0}  Departed={4:N0}  Union={5:N0}") -f `
						[int64]$targetRowCount, [int64]$currentRowCount, [int64]$retainedCount, [int64]$newCount, [int64]$departedCount, [int64]$unionCount
				) -ForegroundColor 'Yellow'
			} catch { }
		}
		# Aggregate-only completion record so the fact merge appears in the unified rollup
		# stage stream alongside the earlier preparation stages. Routed through a host
		# lookup so the function stays inert when it is extracted and exercised on its own.
		$__paxStage = Microsoft.PowerShell.Core\Get-Command -Name 'Write-PaxRollupStage' -CommandType Function -ErrorAction SilentlyContinue
		if ($__paxStage) {
			try {
				& $__paxStage -Stage 'fact-merge' -Status 'complete' -Counters @{
					targetRows  = [int64]$targetRowCount
					currentRows = [int64]$currentRowCount
					retained    = [int64]$retainedCount
					newRows     = [int64]$newCount
					departed    = [int64]$departedCount
					unionRows   = [int64]$unionCount
				}
			} catch { }
		}
		return @{
			Retained = $retainedCount
			New      = $newCount
			Departed = $departedCount
			Union    = $unionCount
		}
	}
	catch {
		& $emitStage 'Failed' $_.Exception.Message
		throw
	}
	finally {
		script:Remove-PaxWorkspace -WorkDir $workDir -MergingPath $mergingPath -Metrics $cleanupMetrics
	}
}

function script:Invoke-PaxKeyedAdditiveMerge {
	<#
	.SYNOPSIS
		Bounded, disk-backed union-merge of a target and current CSV keyed by a
		composite key with additive / min / max / OR aggregation. Shared by the two
		M365Bundle append reducers.

	.DESCRIPTION
		Streams both inputs through the frozen RFC-4180 reader, projects each row onto
		a fixed canonical header (missing columns become '' or a supplied default),
		spills a bounded work record (composite key, global sequence, side, projected
		columns) per row, and folds one key group at a time via the external sort. The
		first row of each key group (target rows precede current rows, each in original
		order) seeds the group's values; later rows accumulate: summed columns add,
		min/max columns take the lexicographic min/max of non-blank values, OR columns
		become TRUE if any value is TRUE. The group's UserId-style casing therefore
		comes from the first-seen (target-first) row. Output rows are restored to
		first-appearance order with a bounded sequence sort and streamed to
		'<output>.merging' via Export-Csv, then published with a terminating move. The
		complete inputs are never materialized and a hot key streams without being
		collected. Any failure raises a terminating error, leaves a pre-existing target
		byte-for-byte unchanged, publishes nothing partial, and cleans temporary work.

	.OUTPUTS
		PSCustomObject with stats (Retained / New / Updated / Union).
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)][string]$TargetCsv,
		[Parameter(Mandatory)][string]$CurrentCsv,
		[Parameter(Mandatory)][string]$OutputPath,
		[Parameter(Mandatory)][string[]]$Header,
		[Parameter(Mandatory)][string[]]$KeyColumns,
		[Parameter(Mandatory)][AllowEmptyCollection()][string[]]$FoldColumns,
		[Parameter(Mandatory)][AllowEmptyCollection()][string[]]$SumColumns,
		[Parameter(Mandatory)][AllowEmptyCollection()][string[]]$MinColumns,
		[Parameter(Mandatory)][AllowEmptyCollection()][string[]]$MaxColumns,
		[Parameter(Mandatory)][AllowEmptyCollection()][string[]]$OrColumns,
		[Parameter(Mandatory)][hashtable]$Defaults,
		[Parameter(Mandatory)][int64]$MemoryBudgetBytes,
		[Parameter(Mandatory)][string]$Label,
		[scriptblock]$OnMissingColumns
	)
	$inv = [System.Globalization.CultureInfo]::InvariantCulture
	$hdrCount = $Header.Length
	# Header name -> canonical index.
	$hdrIndex = @{}
	for ($i = 0; $i -lt $hdrCount; $i++) { $hdrIndex[$Header[$i]] = $i }
	$keyIdx = @($KeyColumns | ForEach-Object { [int]$hdrIndex[$_] })
	$foldSet = [System.Collections.Generic.HashSet[int]]::new()
	foreach ($c in $FoldColumns) { [void]$foldSet.Add([int]$hdrIndex[$c]) }
	$sumIdx = @($SumColumns | ForEach-Object { [int]$hdrIndex[$_] })
	$minIdx = @($MinColumns | ForEach-Object { [int]$hdrIndex[$_] })
	$maxIdx = @($MaxColumns | ForEach-Object { [int]$hdrIndex[$_] })
	$orIdx = @($OrColumns | ForEach-Object { [int]$hdrIndex[$_] })

	$workRootBase = $env:TEMP; if (-not $workRootBase) { $workRootBase = [System.IO.Path]::GetTempPath() }
	$workDir = Join-Path $workRootBase ('pax_kam_{0}' -f ([System.Guid]::NewGuid().ToString('N')))
	$tmpPath = "$OutputPath.merging"
	$u8 = [System.Text.UTF8Encoding]::new($false)

	# Resolve a source header record's index map onto the canonical header.
	$mapSourceIndices = {
		param($srcHeader)
		$map = New-Object 'int[]' $hdrCount
		for ($j = 0; $j -lt $hdrCount; $j++) {
			$map[$j] = -1
			for ($s = 0; $s -lt $srcHeader.Length; $s++) {
				if ([string]::Equals([string]$srcHeader[$s], $Header[$j], [System.StringComparison]::OrdinalIgnoreCase)) { $map[$j] = $s; break }
			}
		}
		return , $map
	}
	# Project a source row (fields + index map) onto canonical values with defaults.
	$projectFields = {
		param($row, $map)
		$vals = New-Object 'string[]' $hdrCount
		for ($j = 0; $j -lt $hdrCount; $j++) {
			$idx = $map[$j]
			$v = if ($idx -ge 0 -and $idx -lt $row.Length) { [string]$row[$idx] } else { '' }
			if ([string]::IsNullOrWhiteSpace($v) -and $Defaults.ContainsKey($Header[$j])) { $v = [string]$Defaults[$Header[$j]] }
			$vals[$j] = $v
		}
		return , $vals
	}
	# Composite key of projected values (folded columns lowercased), '|'-joined.
	$makeKey = {
		param($vals)
		$sb = [System.Text.StringBuilder]::new()
		for ($i = 0; $i -lt $keyIdx.Length; $i++) {
			if ($i -gt 0) { [void]$sb.Append('|') }
			$kv = [string]$vals[$keyIdx[$i]]
			if ($foldSet.Contains($keyIdx[$i])) { $kv = $kv.ToLowerInvariant() }
			[void]$sb.Append($kv)
		}
		return $sb.ToString()
	}

	$retained = 0; $newCount = 0; $updated = 0; $union = 0
	try {
		[void][System.IO.Directory]::CreateDirectory($workDir)
		$workPath = Join-Path $workDir 'work.csv'
		$workHdr = @('__K', '__SEQ', '__SIDE') + $Header
		$ww = [System.IO.StreamWriter]::new($workPath, $false, $u8)
		$seq = [int64]0
		$targetDataRows = [int64]0
		$targetExists = Test-Path -LiteralPath $TargetCsv -PathType Leaf
		try {
			script:Write-PaxCsvRecord -Writer $ww -Fields $workHdr
			# Target side (side '0'); may be absent.
			if ($targetExists) {
				$tr = [System.IO.StreamReader]::new($TargetCsv, $true)
				try {
					$th = script:Read-PaxCsvRecord -Reader $tr
					if ($null -ne $th) {
						$tmap = & $mapSourceIndices $th
						if ($OnMissingColumns) {
							$missing = @($Header | Where-Object { $hdrIndex.ContainsKey($_) -and $tmap[$hdrIndex[$_]] -lt 0 })
							if ($missing.Count -gt 0) { & $OnMissingColumns $missing }
						}
						while ($true) {
							$row = script:Read-PaxCsvRecord -Reader $tr
							if ($null -eq $row) { break }
							$targetDataRows++
							$vals = & $projectFields $row $tmap
							$k = & $makeKey $vals
							$fields = New-Object System.Collections.Generic.List[string]
							$fields.Add($k); $fields.Add($seq.ToString('D19', $inv)); $fields.Add('0')
							foreach ($v in $vals) { $fields.Add($v) }
							script:Write-PaxCsvRecord -Writer $ww -Fields $fields.ToArray()
							$seq++
						}
					}
				}
				finally { $tr.Dispose() }
			}
			# APPEND SAFETY (data-loss guard): never overwrite a non-empty target that parsed to 0 rows.
			if ($targetDataRows -eq 0 -and $targetExists -and ((Get-Item -LiteralPath $TargetCsv).Length -gt 0)) {
				throw "${Label}: target '$TargetCsv' exists with content but parsed to 0 rows; refusing to overwrite (would discard existing data)."
			}
			# Current side (side '1').
			$cr = [System.IO.StreamReader]::new($CurrentCsv, $true)
			try {
				$ch = script:Read-PaxCsvRecord -Reader $cr
				if ($null -ne $ch) {
					$cmap = & $mapSourceIndices $ch
					while ($true) {
						$row = script:Read-PaxCsvRecord -Reader $cr
						if ($null -eq $row) { break }
						$vals = & $projectFields $row $cmap
						$k = & $makeKey $vals
						$fields = New-Object System.Collections.Generic.List[string]
						$fields.Add($k); $fields.Add($seq.ToString('D19', $inv)); $fields.Add('1')
						foreach ($v in $vals) { $fields.Add($v) }
						script:Write-PaxCsvRecord -Writer $ww -Fields $fields.ToArray()
						$seq++
					}
				}
			}
			finally { $cr.Dispose() }
		}
		finally { $ww.Flush(); $ww.Dispose() }

		# Sort work by (key, sequence): equal keys adjacent, target rows before current.
		$sortedPath = Join-Path $workDir 'sorted.csv'
		[void](script:Invoke-PaxExternalSort -InputPath $workPath -OutputPath $sortedPath -KeyColumn @('__K', '__SEQ') -Comparer 'Ordinal' -MemoryBudgetBytes $MemoryBudgetBytes -FanIn 8 -WorkRoot $workDir)

		# Reduce one key group at a time; emit [__FSEQ] + accumulated canonical cols.
		$resultPath = Join-Path $workDir 'result.csv'
		$sr = [System.IO.StreamReader]::new($sortedPath, $true)
		$rw = [System.IO.StreamWriter]::new($resultPath, $false, $u8)
		try {
			$null = script:Read-PaxCsvRecord -Reader $sr
			script:Write-PaxCsvRecord -Writer $rw -Fields (@('__FSEQ') + $Header)
			$haveGroup = $false
			$curKey = $null; $acc = $null; $firstSeq = $null; $tCnt = 0; $cCnt = 0
			$flush = {
				if (-not $haveGroup) { return }
				$out = New-Object System.Collections.Generic.List[string]
				$out.Add($firstSeq)
				foreach ($v in $acc) { $out.Add([string]$v) }
				script:Write-PaxCsvRecord -Writer $rw -Fields $out.ToArray()
				$script:__union++
				if ($tCnt -gt 0) { $script:__ret += $cCnt; $script:__upd += $cCnt }
				else { if ($cCnt -ge 1) { $script:__new++ }; if ($cCnt -gt 1) { $script:__upd += ($cCnt - 1) } }
			}
			$script:__union = 0; $script:__ret = 0; $script:__new = 0; $script:__upd = 0
			while ($true) {
				$row = script:Read-PaxCsvRecord -Reader $sr
				if ($null -eq $row) { break }
				$k = [string]$row[0]
				$rowSeq = [string]$row[1]
				$side = [string]$row[2]
				# Canonical values start at work index 3.
				if ((-not $haveGroup) -or ($k -cne $curKey)) {
					& $flush
					$curKey = $k; $firstSeq = $rowSeq; $tCnt = 0; $cCnt = 0
					$acc = New-Object 'string[]' $hdrCount
					for ($j = 0; $j -lt $hdrCount; $j++) { $acc[$j] = [string]$row[3 + $j] }
					$haveGroup = $true
				}
				else {
					foreach ($sc in $sumIdx) {
						$a = 0; [void][int]::TryParse([string]$acc[$sc], [ref]$a)
						$b = 0; [void][int]::TryParse([string]$row[3 + $sc], [ref]$b)
						$acc[$sc] = ($a + $b).ToString()
					}
					foreach ($mc in $minIdx) {
						$rv = [string]$row[3 + $mc]
						if (-not [string]::IsNullOrWhiteSpace($rv)) {
							$av = [string]$acc[$mc]
							if ([string]::IsNullOrWhiteSpace($av) -or ($rv -lt $av)) { $acc[$mc] = $rv }
						}
					}
					foreach ($xc in $maxIdx) {
						$rv = [string]$row[3 + $xc]
						if (-not [string]::IsNullOrWhiteSpace($rv)) {
							$av = [string]$acc[$xc]
							if ([string]::IsNullOrWhiteSpace($av) -or ($rv -gt $av)) { $acc[$xc] = $rv }
						}
					}
					foreach ($oc in $orIdx) {
						if (([string]$row[3 + $oc]).Equals('TRUE', [System.StringComparison]::OrdinalIgnoreCase)) { $acc[$oc] = 'TRUE' }
					}
				}
				if ($side -eq '0') { $tCnt++ } else { $cCnt++ }
			}
			& $flush
			$union = [int]$script:__union; $retained = [int]$script:__ret; $newCount = [int]$script:__new; $updated = [int]$script:__upd
			Remove-Variable -Name __union, __ret, __new, __upd -Scope Script -ErrorAction SilentlyContinue
		}
		finally { $rw.Flush(); $rw.Dispose(); $sr.Dispose() }

		# Restore first-appearance order.
		$orderedPath = Join-Path $workDir 'ordered.csv'
		[void](script:Invoke-PaxExternalSort -InputPath $resultPath -OutputPath $orderedPath -KeyColumn @('__FSEQ') -Comparer 'Ordinal' -MemoryBudgetBytes $MemoryBudgetBytes -FanIn 8 -WorkRoot $workDir)

		# Stream ordered result rows as objects to Export-Csv (exact prior format).
		$hdrLocal = $Header
		$objStream = {
			$orr = [System.IO.StreamReader]::new($orderedPath, $true)
			try {
				$null = script:Read-PaxCsvRecord -Reader $orr
				while ($true) {
					$row = script:Read-PaxCsvRecord -Reader $orr
					if ($null -eq $row) { break }
					$o = [ordered]@{}
					for ($j = 0; $j -lt $hdrLocal.Length; $j++) { $o[$hdrLocal[$j]] = [string]$row[$j + 1] }
					[pscustomobject]$o
				}
			}
			finally { $orr.Dispose() }
		}
		& $objStream | Select-Object -Property $Header | Export-Csv -LiteralPath $tmpPath -NoTypeInformation -Encoding UTF8
		Move-Item -LiteralPath $tmpPath -Destination $OutputPath -Force -ErrorAction Stop
	}
	catch {
		if (Test-Path -LiteralPath $tmpPath) { try { Remove-Item -LiteralPath $tmpPath -Force -ErrorAction SilentlyContinue } catch {} }
		throw
	}
	finally {
		if (Test-Path -LiteralPath $workDir) { try { Remove-Item -LiteralPath $workDir -Recurse -Force -ErrorAction SilentlyContinue } catch {} }
	}

	return [pscustomobject]@{
		Retained = $retained
		New      = $newCount
		Updated  = $updated
		Union    = $union
	}
}

function Merge-M365RollupCsv {
	<#
	.SYNOPSIS
		Union-merge a target M365Bundle rollup CSV with the current run's freshly-emitted rollup.

	.DESCRIPTION
		Post-Python helper for -AppendFile in M365Bundle mode. Performs a 9-tuple-keyed
		union-merge with additive counter semantics:

		  Composite key      : (lower(UserId), CreationDate, Operation, Workload,
		                        lower(SourceFileExtension), AppHost, AgentId,
		                        AgentName, ContextType)
		  EventCount         : target + current
		  ItemsAccessedCount : target + current
		  CreationTime       : min(target, current)  (lexicographic on ISO-8601)
		  MaxCreationTime    : max(target, current)
		  IsAgentInteraction : OR  (any TRUE -> TRUE)
		  UserId             : target's casing wins on retained groups (first-seen)

		Schema tolerance: target may be a legacy 9- or 10-column rollup. Missing
		columns are padded with empty strings; IsAgentInteraction defaults to FALSE.

		Bounded rewrite: the union is computed by streaming both inputs through
		bounded temporary storage (script:Invoke-PaxKeyedAdditiveMerge) instead of
		loading both files into memory; output rows, ordering, accumulation, casing,
		schema, guard, and returned stats are unchanged.

		Atomic rewrite: writes to '<output>.merging' and renames over -OutputPath.
		-OutputPath defaults to -TargetRollupCsv (in-place append semantics).

	.OUTPUTS
		PSCustomObject with stats (Retained / New / Updated / Union).
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $TargetRollupCsv,
		[Parameter(Mandatory)] [string] $CurrentRollupCsv,
		[Parameter()]          [string] $OutputPath,
		[int64]                $MemoryBudgetBytes = 33554432
	)

	if (-not (Test-Path -LiteralPath $CurrentRollupCsv -PathType Leaf)) {
		throw "Merge-M365RollupCsv: current rollup CSV not found: '$CurrentRollupCsv'"
	}
	if ([string]::IsNullOrWhiteSpace($OutputPath)) { $OutputPath = $TargetRollupCsv }

	# Canonical 14-column rollup header (order is contractual for downstream sidecar regen).
	$rollupHeader = @(
		'UserId', 'CreationDate', 'Operation', 'Workload', 'SourceFileExtension',
		'AppHost', 'EventCount', 'ItemsAccessedCount', 'CreationTime', 'MaxCreationTime',
		'AgentId', 'AgentName', 'ContextType', 'IsAgentInteraction'
	)
	$onMissing = {
		param($missing)
		Microsoft.PowerShell.Utility\Write-Host (
			("WARNING: Merge-M365RollupCsv: target rollup is missing {0} of the {1} canonical columns " +
			 "({2}). Padding with empty values; IsAgentInteraction defaults to FALSE. " +
			 "Target: {3}") -f $missing.Count, $rollupHeader.Count, ($missing -join ','), $TargetRollupCsv
		) -ForegroundColor Yellow
	}
	return (script:Invoke-PaxKeyedAdditiveMerge `
			-TargetCsv $TargetRollupCsv -CurrentCsv $CurrentRollupCsv -OutputPath $OutputPath `
			-Header $rollupHeader `
			-KeyColumns @('UserId', 'CreationDate', 'Operation', 'Workload', 'SourceFileExtension', 'AppHost', 'AgentId', 'AgentName', 'ContextType') `
			-FoldColumns @('UserId', 'SourceFileExtension') `
			-SumColumns @('EventCount', 'ItemsAccessedCount') `
			-MinColumns @('CreationTime') -MaxColumns @('MaxCreationTime') -OrColumns @('IsAgentInteraction') `
			-Defaults @{ IsAgentInteraction = 'FALSE' } `
			-MemoryBudgetBytes $MemoryBudgetBytes -Label 'Merge-M365RollupCsv' -OnMissingColumns $onMissing)
}

function Merge-M365SessionStatsCsv {
	<#
	.SYNOPSIS
		Union-merge a target M365Bundle SessionStats CSV with the current run's freshly-emitted SessionStats.

	.DESCRIPTION
		Post-Python helper for -AppendFile in M365Bundle mode. Performs a 3-tuple-keyed
		union-merge with additive counter semantics on the SessionStats sidecar:

		  Composite key      : (lower(UserId), CreationDate, AppHost)
		  SessionCount       : target + current
		  PromptCount        : target + current
		  AgentPromptCount   : target + current
		  ResponseCount      : target + current
		  AgentSessionCount  : target + current
		  UserId             : target's casing wins on retained groups (first-seen)

		Schema tolerance: target may be missing one or more counter columns (e.g. a
		placeholder). Missing counters are treated as 0 during accumulation
		and emitted as the union value.

		Bounded rewrite: the union is computed by streaming both inputs through
		bounded temporary storage (script:Invoke-PaxKeyedAdditiveMerge) instead of
		loading both files into memory; output rows, ordering, accumulation, casing,
		schema, guard, and returned stats are unchanged.

		Atomic rewrite: writes to '<output>.merging' and renames over -OutputPath.
		-OutputPath defaults to -TargetSessionStatsCsv (in-place append semantics).

	.OUTPUTS
		PSCustomObject with stats (Retained / New / Updated / Union).
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $TargetSessionStatsCsv,
		[Parameter(Mandatory)] [string] $CurrentSessionStatsCsv,
		[Parameter()]          [string] $OutputPath,
		[int64]                $MemoryBudgetBytes = 33554432
	)

	if (-not (Test-Path -LiteralPath $CurrentSessionStatsCsv -PathType Leaf)) {
		throw "Merge-M365SessionStatsCsv: current SessionStats CSV not found: '$CurrentSessionStatsCsv'"
	}
	if ([string]::IsNullOrWhiteSpace($OutputPath)) { $OutputPath = $TargetSessionStatsCsv }

	# Canonical 8-column SessionStats header (matches SESSIONSTATS_HEADER in the embedded processor).
	$ssHeader = @(
		'UserId', 'CreationDate', 'AppHost',
		'SessionCount', 'PromptCount', 'AgentPromptCount', 'ResponseCount', 'AgentSessionCount'
	)
	$onMissing = {
		param($missing)
		Microsoft.PowerShell.Utility\Write-Host (
			("WARNING: Merge-M365SessionStatsCsv: target SessionStats is missing {0} of the {1} canonical columns " +
			 "({2}). Padding with empty values; missing counters treated as 0. Target: {3}") `
				-f $missing.Count, $ssHeader.Count, ($missing -join ','), $TargetSessionStatsCsv
		) -ForegroundColor Yellow
	}
	return (script:Invoke-PaxKeyedAdditiveMerge `
			-TargetCsv $TargetSessionStatsCsv -CurrentCsv $CurrentSessionStatsCsv -OutputPath $OutputPath `
			-Header $ssHeader `
			-KeyColumns @('UserId', 'CreationDate', 'AppHost') `
			-FoldColumns @('UserId') `
			-SumColumns @('SessionCount', 'PromptCount', 'AgentPromptCount', 'ResponseCount', 'AgentSessionCount') `
			-MinColumns @() -MaxColumns @() -OrColumns @() `
			-Defaults @{} `
			-MemoryBudgetBytes $MemoryBudgetBytes -Label 'Merge-M365SessionStatsCsv' -OnMissingColumns $onMissing)
}

function Convert-CsvToDelta {
	<#
	.SYNOPSIS
		Convert a local CSV file to a Delta Lake table at a OneLake DFS URI (or local path).

	.DESCRIPTION
		Invokes Python with the 'deltalake' package to read the CSV with pyarrow and write
		it as a Delta table at the destination. Used by the rollup post-processor to land
		Fabric Lakehouse Tables/ outputs after the embedded Python processor has written
		the canonical CSV.

		Supports two destination forms:
		  • Local path (file:// or absolute path) — used for unit testing and for the
		    pre-publish stage when -OutputPath resolves to a Fabric OneLake URL.
		  • OneLake DFS URL (https://<workspace>-onelake.dfs.fabric.microsoft.com/.../Tables/<name>)
		    — used directly for Fabric Lakehouse Tables/ destinations. The caller supplies
		    a bearer token (OneLake storage audience).

		Schema evolution: write_deltalake is called with schema_mode='merge' so additive
		column changes do not require a full overwrite. The mode itself is the caller's
		choice (overwrite for first run, append for subsequent appends).

	.PARAMETER InputCsv
		Local path to the source CSV. Must exist and be UTF-8 encoded.

	.PARAMETER TargetUri
		Destination Delta table URI. Either a local absolute path or a OneLake DFS https URL.

	.PARAMETER Mode
		Delta write mode: 'overwrite' or 'append'. Defaults to 'overwrite'.

	.PARAMETER BearerToken
		Optional OneLake storage-audience access token. Required when TargetUri is a
		Fabric DFS URL. Ignored for local destinations.

	.PARAMETER PythonExe
		Resolved Python interpreter path (from Resolve-PythonExe).

	.PARAMETER LauncherArgs
		Launcher arguments (e.g. py -3 prefix) for the resolved interpreter.

	.OUTPUTS
		$true on success, $false on failure (errors are logged via Write-LogHost).
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string]   $InputCsv,
		[Parameter(Mandatory)] [string]   $TargetUri,
		[Parameter()] [ValidateSet('overwrite','append')] [string] $Mode = 'overwrite',
		[Parameter()] [string]            $BearerToken = '',
		[Parameter(Mandatory)] [string]   $PythonExe,
		[Parameter(Mandatory)] [AllowEmptyCollection()] [string[]] $LauncherArgs
	)
	if (-not (Test-Path -LiteralPath $InputCsv -PathType Leaf)) {
		Write-LogHost "Convert-CsvToDelta: input CSV not found: '$InputCsv'" -ForegroundColor Red
		return $false
	}
	# Inline Python: pyarrow reads CSV, deltalake writes table. Storage options only
	# when TargetUri is a remote OneLake URL. Column names are sanitized to satisfy
	# Delta's forbidden-character set (' ,;{}()\n\t='); the source CSV on disk is
	# left unchanged so PBIP semantic models that read the CSV directly continue
	# to bind by the original column names.
	$inlinePy = @"
import os, sys, json, re
in_csv  = os.environ['PAX_DELTA_IN']
out_uri = os.environ['PAX_DELTA_OUT']
mode    = os.environ['PAX_DELTA_MODE']
token   = os.environ.get('PAX_DELTA_TOKEN', '')
try:
    import pyarrow.csv as pacsv
    from deltalake import write_deltalake
except Exception as e:
    print(f'Convert-CsvToDelta: import failed: {e}', file=sys.stderr)
    sys.exit(2)
# Delta forbids these characters in column names; the Fabric SQL endpoint also
# rejects spaces in column names. Replace each with an underscore. Collisions
# after sanitization (e.g., two source columns differing only in a forbidden
# character) are disambiguated by appending _2, _3, ... . The disambiguated
# name is also recorded so a later raw column whose sanitized form literally
# matches an earlier disambiguated name cannot silently map to the same Delta
# column.
_DELTA_FORBIDDEN = re.compile(r'[ ,;\{\}\(\)\n\t=]')
def _sanitize_col_names(cols):
    seen = {}
    out = []
    for c in cols:
        s = _DELTA_FORBIDDEN.sub('_', c)
        if s in seen:
            seen[s] += 1
            candidate = f'{s}_{seen[s]}'
            while candidate in seen:
                seen[s] += 1
                candidate = f'{s}_{seen[s]}'
            s = candidate
            seen[s] = 1
        else:
            seen[s] = 1
        out.append(s)
    return out
try:
    import pyarrow as pa
    # Stream the CSV as bounded RecordBatches instead of reading the whole file into
    # one Arrow table. Each batch is cast to all-string (the Lakehouse model casts at
    # query time) and handed to write_deltalake through a self-describing
    # RecordBatchReader, so only one bounded batch is materialized at a time.
    read_options = pacsv.ReadOptions(block_size=8 * 1024 * 1024)
    src_reader = pacsv.open_csv(
        in_csv,
        read_options=read_options,
        convert_options=pacsv.ConvertOptions(strings_can_be_null=False),
    )
    cols = list(src_reader.schema.names)
    safe_cols = _sanitize_col_names(cols)
    target_schema = pa.schema([pa.field(sc, pa.string()) for sc in safe_cols])
    counter = [0]
    def _string_batches():
        for batch in src_reader:
            counter[0] += batch.num_rows
            arrays = [batch.column(i).cast(pa.string()) for i in range(batch.num_columns)]
            yield pa.RecordBatch.from_arrays(arrays, names=safe_cols)
    batch_reader = pa.RecordBatchReader.from_batches(target_schema, _string_batches())
    storage_options = None
    if out_uri.startswith('https://') or out_uri.startswith('abfss://'):
        if not token:
            print('Convert-CsvToDelta: remote target requires a bearer token', file=sys.stderr)
            sys.exit(3)
        storage_options = {'bearer_token': token, 'use_fabric_endpoint': 'true'}
    write_deltalake(
        out_uri,
        batch_reader,
        mode=mode,
        schema_mode='merge',
        storage_options=storage_options,
    )
    print(f'Convert-CsvToDelta: wrote {counter[0]} rows to {out_uri} (mode={mode}, streamed)')
except Exception as e:
    print(f'Convert-CsvToDelta: write failed: {e}', file=sys.stderr)
    sys.exit(4)
"@
	$env:PAX_DELTA_IN   = $InputCsv
	$env:PAX_DELTA_OUT  = $TargetUri
	$env:PAX_DELTA_MODE = $Mode
	$env:PAX_DELTA_TOKEN = $BearerToken
	try {
		$fullArgs = @($LauncherArgs) + @('-c', $inlinePy)
		& $PythonExe @fullArgs 2>&1 | ForEach-Object { Write-Log $_ }
		$exit = $LASTEXITCODE
	}
	finally {
		Remove-Item Env:\PAX_DELTA_IN -ErrorAction SilentlyContinue
		Remove-Item Env:\PAX_DELTA_OUT -ErrorAction SilentlyContinue
		Remove-Item Env:\PAX_DELTA_MODE -ErrorAction SilentlyContinue
		Remove-Item Env:\PAX_DELTA_TOKEN -ErrorAction SilentlyContinue
	}
	if ($exit -eq 0) { return $true }
	Write-LogHost "Convert-CsvToDelta: Python exited $exit (input='$InputCsv', target='$TargetUri', mode=$Mode)." -ForegroundColor Red
	return $false
}

function Test-DeltaTableSchemaCompat {
	<#
	.SYNOPSIS
		Pre-flight check: confirm an existing Delta table at TargetUri has a column set
		compatible with the CSV the caller is about to convert.

	.DESCRIPTION
		Reads the Delta table's schema (column names only — types are all strings in our
		write path) and compares against the CSV header. Compatible = every existing-table
		column is present in the new CSV (schema_mode='merge' will additively expand it).
		Incompatible = at least one existing column is absent from the new CSV (would
		require a destructive overwrite-with-different-schema).

		Returns a hashtable: { Compatible=<bool>, ExistingCols=[], NewCols=[], Missing=[] }.
		When the Delta table does not yet exist, returns Compatible=$true with empty arrays.

	.PARAMETER TargetUri
		Delta table URI (local path or OneLake DFS URL).

	.PARAMETER NewCsv
		Local CSV whose header is the proposed new schema.

	.PARAMETER BearerToken
		Optional OneLake storage-audience token for remote URIs.

	.PARAMETER PythonExe
		Resolved Python interpreter.

	.PARAMETER LauncherArgs
		Launcher prefix args.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string]   $TargetUri,
		[Parameter(Mandatory)] [string]   $NewCsv,
		[Parameter()] [string]            $BearerToken = '',
		[Parameter(Mandatory)] [string]   $PythonExe,
		[Parameter(Mandatory)] [AllowEmptyCollection()] [string[]] $LauncherArgs
	)
	if (-not (Test-Path -LiteralPath $NewCsv -PathType Leaf)) {
		return @{ Compatible = $false; ExistingCols = @(); NewCols = @(); Missing = @(); Error = "New CSV not found: '$NewCsv'" }
	}
	$inlinePy = @"
import os, sys, json, csv, re
target  = os.environ['PAX_DELTA_OUT']
new_csv = os.environ['PAX_DELTA_IN']
token   = os.environ.get('PAX_DELTA_TOKEN', '')
try:
    from deltalake import DeltaTable
except Exception as e:
    print(json.dumps({'error': f'import: {e}'}))
    sys.exit(0)
# Must match the sanitization applied by Convert-CsvToDelta — otherwise the
# compat probe would compare sanitized stored names against unsanitized CSV
# headers and always report drift.
_DELTA_FORBIDDEN = re.compile(r'[ ,;\{\}\(\)\n\t=]')
def _sanitize_col_names(cols):
    seen = {}
    out = []
    for c in cols:
        s = _DELTA_FORBIDDEN.sub('_', c)
        if s in seen:
            seen[s] += 1
            candidate = f'{s}_{seen[s]}'
            while candidate in seen:
                seen[s] += 1
                candidate = f'{s}_{seen[s]}'
            s = candidate
            seen[s] = 1
        else:
            seen[s] = 1
        out.append(s)
    return out
try:
    with open(new_csv, 'r', encoding='utf-8-sig', newline='') as f:
        rdr = csv.reader(f)
        new_cols = _sanitize_col_names(next(rdr, []))
except Exception as e:
    print(json.dumps({'error': f'csv-header: {e}'}))
    sys.exit(0)
storage_options = None
if target.startswith('https://') or target.startswith('abfss://'):
    if token:
        storage_options = {'bearer_token': token, 'use_fabric_endpoint': 'true'}
try:
    dt = DeltaTable(target, storage_options=storage_options)
    existing = [f.name for f in dt.schema().fields]
except Exception:
    print(json.dumps({'existing': [], 'new': new_cols, 'exists': False}))
    sys.exit(0)
print(json.dumps({'existing': existing, 'new': new_cols, 'exists': True}))
"@
	$env:PAX_DELTA_OUT   = $TargetUri
	$env:PAX_DELTA_IN    = $NewCsv
	$env:PAX_DELTA_TOKEN = $BearerToken
	$outJson = ''
	try {
		$fullArgs = @($LauncherArgs) + @('-c', $inlinePy)
		$outJson = (& $PythonExe @fullArgs 2>&1 | Out-String).Trim()
	}
	finally {
		Remove-Item Env:\PAX_DELTA_OUT -ErrorAction SilentlyContinue
		Remove-Item Env:\PAX_DELTA_IN -ErrorAction SilentlyContinue
		Remove-Item Env:\PAX_DELTA_TOKEN -ErrorAction SilentlyContinue
	}
	try {
		$parsed = $outJson | ConvertFrom-Json -ErrorAction Stop
	} catch {
		return @{ Compatible = $false; ExistingCols = @(); NewCols = @(); Missing = @(); Error = "Could not parse schema probe output: $outJson" }
	}
	if ($parsed.PSObject.Properties['error']) {
		return @{ Compatible = $false; ExistingCols = @(); NewCols = @(); Missing = @(); Error = [string]$parsed.error }
	}
	$existing = @($parsed.existing)
	$newCols  = @($parsed.new)
	if (-not $parsed.exists) {
		return @{ Compatible = $true; ExistingCols = $existing; NewCols = $newCols; Missing = @() }
	}
	$newSet = [System.Collections.Generic.HashSet[string]]::new([string[]]$newCols, [System.StringComparer]::OrdinalIgnoreCase)
	$missing = @($existing | Where-Object { -not $newSet.Contains($_) })
	$compatible = ($missing.Count -eq 0)
	return @{ Compatible = $compatible; ExistingCols = $existing; NewCols = $newCols; Missing = $missing }
}

function Write-DeltaAppend {
	<#
	.SYNOPSIS
		Append a local CSV to a Delta table (Fabric Lakehouse Tables/ or local), creating
		the table if it does not yet exist. Hard-errors on destructive schema drift.

	.DESCRIPTION
		Thin wrapper around Test-DeltaTableSchemaCompat + Convert-CsvToDelta:
		  1. Probe the target Delta schema. If unreachable due to nonexistent table,
		     fall through to Convert-CsvToDelta with mode='append' (deltalake creates
		     the table on first write). The returned object's IsInit flag is set so
		     callers can label the banner '[append-init]'.
		  2. If the table exists, refuse the write when any existing column is absent
		     from the new CSV header (column removal / type narrowing). Additive new
		     columns are absorbed via schema_mode='merge'.
		  3. On compatible schema, invoke Convert-CsvToDelta -Mode append.

	.OUTPUTS
		Hashtable: { Success=<bool>, IsInit=<bool>, AddedCols=[], Missing=[], Error=<string?> }.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string]   $InputCsv,
		[Parameter(Mandatory)] [string]   $TargetUri,
		[Parameter()] [string]            $BearerToken = '',
		[Parameter(Mandatory)] [string]   $PythonExe,
		[Parameter(Mandatory)] [AllowEmptyCollection()] [string[]] $LauncherArgs
	)
	if (-not (Test-Path -LiteralPath $InputCsv -PathType Leaf)) {
		return @{ Success = $false; IsInit = $false; AddedCols = @(); Missing = @(); Error = "Input CSV not found: '$InputCsv'" }
	}
	$probe = Test-DeltaTableSchemaCompat -TargetUri $TargetUri -NewCsv $InputCsv -BearerToken $BearerToken -PythonExe $PythonExe -LauncherArgs $LauncherArgs
	$isInit = (-not ($probe.ExistingCols -and @($probe.ExistingCols).Count -gt 0))
	if (-not $probe.Compatible -and -not $isInit) {
		$missingList = ($probe.Missing -join ', ')
		$msg = "Write-DeltaAppend: destructive schema drift rejected. Existing column(s) not present in source CSV: $missingList"
		Write-LogHost $msg -ForegroundColor Red
		return @{ Success = $false; IsInit = $false; AddedCols = @(); Missing = @($probe.Missing); Error = $msg }
	}
	$existingSet = if ($probe.ExistingCols) { [System.Collections.Generic.HashSet[string]]::new([string[]]@($probe.ExistingCols), [System.StringComparer]::OrdinalIgnoreCase) } else { [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase) }
	$addedCols = @(@($probe.NewCols) | Where-Object { -not $existingSet.Contains($_) })
	$ok = Convert-CsvToDelta -InputCsv $InputCsv -TargetUri $TargetUri -Mode 'append' -BearerToken $BearerToken -PythonExe $PythonExe -LauncherArgs $LauncherArgs
	if (-not $ok) {
		return @{ Success = $false; IsInit = $isInit; AddedCols = $addedCols; Missing = @(); Error = 'Convert-CsvToDelta returned failure.' }
	}
	$tag = if ($isInit) { '[append-init]' } else { '[append]' }
	$colNote = if ($addedCols.Count -gt 0) { (" (added columns: {0})" -f ($addedCols -join ', ')) } else { '' }
	Write-LogHost "Write-DeltaAppend: $tag '$TargetUri'$colNote" -ForegroundColor Green
	return @{ Success = $true; IsInit = $isInit; AddedCols = $addedCols; Missing = @() }
}

# ============================================================================
# REMOTE OUTPUT HELPERS — SharePoint (Graph drives API) and Fabric (OneLake DFS)
# ----------------------------------------------------------------------------
# All helpers are no-ops when $script:RemoteOutputMode -eq 'None'. They are
# invoked from a single dispatch point: Invoke-OutputUpload.
#
# SharePoint path:
#   - Reuses the existing Connect-MgGraph token (Graph audience).
#   - Resolves the SP URL to siteId/driveId/folder via Graph site lookup.
#   - Files <= 250 MB: PUT /drives/{driveId}/root:/path:/content (Graph simple-upload max)
#   - Larger files: createUploadSession + 5 MB chunked PUT (must be 320 KB-aligned).
#
# Fabric/OneLake path:
#   - Uses a SEPARATE token with audience https://storage.azure.com/ (Az.Accounts).
#   - DFS Create -> Append (chunked) -> Flush. Path = /<workspace>/<item>.Lakehouse/Files/<rel>
# ============================================================================

function Get-DisplayPath {
	<#
	.SYNOPSIS
		Returns the user-visible path to display for an output artifact, accounting for
		a SharePoint or OneLake -OutputPath* value. Local-output runs see the local path unchanged;
		remote-output runs see the destination URL the file is uploaded to.

	.DESCRIPTION
		Every "Output File: ...", "Output Directory: ...", "Log file: ..." line in the
		console / log banner should be filtered through this helper. The local scratch
		path is irrelevant to a customer who passed a SharePoint or OneLake -OutputPath*;
		showing it implies the artifact lives there, which it does not (it is uploaded
		then, on success, the local copy is reaped).

		File mode (default): appends the local file's leaf name to the remote root URL.
		-Directory mode: returns the remote root URL with no leaf appended.

		When $script:RemoteOutputMode -eq 'None' (or remote URL not yet set), the input
		path is returned verbatim — making this safe to call unconditionally at every
		display site.

	.PARAMETER LocalPath
		The local scratch path of the artifact. Required. Can be empty/null.

	.PARAMETER Directory
		If set, treats LocalPath as a directory and returns the remote root URL alone
		(no leaf appended). Use for "Output Directory: <path>" lines.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [AllowNull()] [AllowEmptyString()] [string] $LocalPath,
		[switch] $Directory
	)
	if ($script:RemoteOutputMode -eq 'None' -or [string]::IsNullOrWhiteSpace($LocalPath) -or [string]::IsNullOrWhiteSpace($script:RemoteOutputUrl)) {
		return $LocalPath
	}
	$base = $script:RemoteOutputUrl.TrimEnd('/')
	if ($Directory) { return $base }
	$leaf = [System.IO.Path]::GetFileName($LocalPath.TrimEnd('\','/'))
	if ([string]::IsNullOrWhiteSpace($leaf)) { return $base }
	# Guard against URL doubling: $RemoteOutputUrl can be either a folder URL
	# (the normal -OutputPath case) or already a full file URL (when promoted
	# from -AppendFile or when -OutputPath was given as a file URL). The
	# upstream normalizer in the param-validation block strips the file leaf
	# from RemoteOutputUrl when it can recognize the extension, but this
	# helper is called from many sites and must remain robust if a caller
	# leaves $base as a file URL.
	#
	# Two doubling cases to defend against:
	#   1) Same name  ('.../foo.csv' + 'foo.csv'  -> '.../foo.csv'        )
	#   2) Sibling    ('.../foo.csv' + 'foo.log'  -> '.../foo.log'        )
	# When $baseLeaf carries a data-artifact extension, strip it before
	# appending $leaf so siblings land in the correct parent folder.
	# .Lakehouse is a folder marker; do NOT strip.
	$baseLeaf = ($base -split '/') | Select-Object -Last 1
	if ($baseLeaf -ieq $leaf) { return $base }
	if ($baseLeaf -match '\.(csv|log|xlsx|json|parquet|txt)$') {
		$base = ($base -replace '/[^/]+$','')
	}
	return ($base + '/' + $leaf)
}

function Resolve-SharePointTarget {
	[CmdletBinding()]
	param([Parameter(Mandatory)] [string] $Url)

	# Accepts any of:
	#   https://<host>/sites/<site>/<library>[/<sub>]
	#   https://<host>/teams/<team>/<library>[/<sub>]
	#   https://<host>/personal/<user>/<library>[/<sub>]
	#   https://<host>/<library>[/<sub>]                  (root site collection)
	# where <host> can be any sharepoint.* tenant variant (sharepoint.com,
	# sharepoint-df.com, sharepoint.us, sharepoint.de, sharepoint.cn,
	# sharepoint-mil.us, ...).
	#
	# The first one or two URL segments identify the site collection; the remainder
	# is library + (optional) folder path. Graph's site-lookup endpoint is the
	# authoritative resolver -- we just hand it the server-relative site path.
	$u = [Uri]$Url
	$hostName = $u.Host
	$segments = ($u.AbsolutePath.TrimStart('/') -split '/') | Where-Object { $_ -ne '' }
	if (-not $segments -or $segments.Count -lt 1) {
		throw "SharePoint URL has no path; expected https://<host>/<sites|teams|personal>/<name>/<library>[/<sub>] : '$Url'"
	}

	# Determine where the site collection ends and the library begins.
	$prefixed = @('sites','teams','personal') -contains $segments[0].ToLower()
	if ($prefixed) {
		if ($segments.Count -lt 3) {
			throw "SharePoint URL is missing a library/folder after the site name: '$Url'"
		}
		$sitePathSegs   = $segments[0..1]   # e.g. sites/Analytics  or  teams/MyTeam
		$libAndFolder   = $segments[2..($segments.Count-1)]
		$siteName       = $segments[1]
	} else {
		# Root site collection: no /sites/ or /teams/ prefix; first segment is the library.
		$sitePathSegs   = @()
		$libAndFolder   = $segments
		$siteName       = '(root)'
	}
	$libraryName     = $libAndFolder[0]
	$folderInLibrary = if ($libAndFolder.Count -gt 1) { ($libAndFolder[1..($libAndFolder.Count-1)]) -join '/' } else { '' }

	# Resolve site via Graph. Site path is server-relative; if root, omit the colon-path.
	if ($sitePathSegs.Count -gt 0) {
		$sitePath      = ($sitePathSegs -join '/')
		$siteLookupUri = "https://graph.microsoft.com/v1.0/sites/${hostName}:/${sitePath}"
	} else {
		$siteLookupUri = "https://graph.microsoft.com/v1.0/sites/${hostName}"
	}
	try {
		$site = Invoke-MgGraphRequest -Method GET -Uri $siteLookupUri -ErrorAction Stop
	} catch {
		# Classify the failure so customers see actionable guidance instead of raw Graph plumbing.
		# We inspect the HTTP status, current Graph context state, and granted scopes to decide
		# the most likely cause. The structured message is consumed by Test-RemoteDestination's
		# error block (which formats the banner with permissions-table back-reference).
		$status = 0
		try { $status = [int]$_.Exception.Response.StatusCode.value__ } catch {}
		if ($status -eq 0) { try { if ($_.Exception.Response.StatusCode -is [System.Net.HttpStatusCode]) { $status = [int]$_.Exception.Response.StatusCode } } catch {} }

		$mgCtx = $null
		try { $mgCtx = Get-MgContext -ErrorAction SilentlyContinue } catch {}
		$hasToken = [bool]$mgCtx
		$grantedScopes = @()
		if ($mgCtx -and $mgCtx.Scopes) { $grantedScopes = @($mgCtx.Scopes) }
		$isAppOnly = $false
		if ($mgCtx) { $isAppOnly = ([string]::IsNullOrWhiteSpace($mgCtx.Account)) -or ($mgCtx.AuthType -eq 'AppOnly') }

		# Surface the raw response body for context (truncated; appended to the classified message).
		$rawDetail = $_.Exception.Message
		try {
			if ($_.ErrorDetails -and $_.ErrorDetails.Message) { $rawDetail = $_.ErrorDetails.Message }
			elseif ($_.Exception.Response) {
				$resp = $_.Exception.Response
				$reader = New-Object System.IO.StreamReader($resp.GetResponseStream())
				$body = $reader.ReadToEnd(); $reader.Close()
				if ($body) { $rawDetail = "HTTP $status $body" }
			}
		} catch {}
		if ($rawDetail.Length -gt 600) { $rawDetail = $rawDetail.Substring(0, 600) + '...(truncated)' }

		# Build the classified diagnosis. Lines are joined with newline so Test-RemoteDestination
		# can split and indent them under its banner.
		$diagLines = New-Object System.Collections.Generic.List[string]
		$diagLines.Add("SharePoint site lookup failed (host '$hostName', site path '$($sitePathSegs -join '/')').")

		if (-not $hasToken) {
			$diagLines.Add('Cause: Microsoft Graph is not connected (no MgContext present).')
			$diagLines.Add('Action: This is unexpected at this point in the script — please report it as a bug.')
		}
		elseif ($status -eq 401) {
			if (-not $isAppOnly -and ($grantedScopes -notcontains 'Sites.ReadWrite.All')) {
				$diagLines.Add('Cause: The Graph access token is missing the Sites.ReadWrite.All scope.')
				$diagLines.Add('Action: Re-run after granting/consenting Sites.ReadWrite.All. See the')
				$diagLines.Add('        "Permissions Required for THIS run" table earlier in this output')
				$diagLines.Add('        for the full list of required scopes for SharePoint output.')
			} else {
				$diagLines.Add('Cause: Graph rejected the token (401). For app-only auth this usually means the')
				$diagLines.Add('       application permission (Sites.ReadWrite.All)')
				$diagLines.Add('       has not been ADMIN-CONSENTED on the app registration / managed identity.')
				$diagLines.Add('Action: Have a Global Administrator grant admin consent to the application')
				$diagLines.Add('        permissions listed in the "Permissions Required for THIS run" table above.')
			}
		}
		elseif ($status -eq 403) {
			$signedIn = if ($mgCtx -and $mgCtx.Account) { $mgCtx.Account } else { '(app identity)' }
			$diagLines.Add("Cause: The signed-in identity ('$signedIn') is authenticated but does not have")
			$diagLines.Add('       access to the target SharePoint site (HTTP 403 Forbidden).')
			$diagLines.Add('Action: In SharePoint, add this identity to the target site as at least Member,')
			$diagLines.Add('        OR re-run with an identity that already has access to the site.')
		}
		elseif ($status -eq 404) {
			$diagLines.Add("Cause: The site was not found on host '$hostName' (HTTP 404).")
			$diagLines.Add('Action: Verify the URL was copied via SharePoint Details -> Path -> Copy.')
			$diagLines.Add('        Check spelling of the /sites/<name> or /teams/<name> segment.')
		}
		elseif ($status -ge 500) {
			$diagLines.Add("Cause: Microsoft Graph returned a server error (HTTP $status). This is usually transient.")
			$diagLines.Add('Action: Wait a minute and retry. If it persists, check https://status.cloud.microsoft.')
		}
		else {
			# Includes name-resolution failures (no HTTP status) — typically dogfood/PPE hostnames.
			if ($hostName -match 'sharepoint-(df|ppe)\.com$') {
				$diagLines.Add("Cause: Host '$hostName' is a Microsoft-internal dogfood/PPE SharePoint endpoint")
				$diagLines.Add('       and is not reachable from the public Microsoft Graph service. This script')
				$diagLines.Add('       does not currently support dogfood/PPE SharePoint targets.')
				$diagLines.Add('Action: Use a production SharePoint URL (*.sharepoint.com) instead.')
			} else {
				$diagLines.Add("Cause: Graph site lookup failed (HTTP status: $status).")
				$diagLines.Add('Action: Verify the URL is correct and reachable, and that the signed-in identity')
				$diagLines.Add('        has the required Graph scopes and SharePoint site access.')
			}
		}
		$diagLines.Add('')
		$diagLines.Add("Graph response: $rawDetail")

		throw ($diagLines -join "`n")
	}
	$siteId = $site.id
	if (-not $siteId) { throw "Unable to resolve SharePoint site '$Url' (Graph returned no id)." }

	# Resolve drive (document library) by name
	$drivesUri = "https://graph.microsoft.com/v1.0/sites/${siteId}/drives"
	$drives = Invoke-MgGraphRequest -Method GET -Uri $drivesUri -ErrorAction Stop
	$drive = $drives.value | Where-Object { $_.name -eq $libraryName -or $_.webUrl -match "/$libraryName(/|$)" } | Select-Object -First 1
	if (-not $drive) {
		# Fallback: default drive
		$drive = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/sites/${siteId}/drive" -ErrorAction Stop
		# If the URL named a non-default library, treat the entire path-after-site as folder under default drive
		$folderInLibrary = ($libAndFolder -join '/')
	}

	return [pscustomobject]@{
		HostName     = $hostName
		SiteName     = $siteName
		SiteId       = $siteId
		DriveId      = $drive.id
		LibraryName  = $libraryName
		FolderPath   = $folderInLibrary.TrimEnd('/')
		WebUrl       = $drive.webUrl
	}
}

function Resolve-FabricTarget {
	[CmdletBinding()]
	param([Parameter(Mandatory)] [string] $Url)

	# Accepted URL shapes (all return enough metadata for callers to route correctly):
	#   1. https://onelake.dfs.fabric.microsoft.com/<workspace>/<item>.Lakehouse
	#      (root mode - recommended; operational artifacts auto-routed under Files/,
	#      Delta tables under Tables/)
	#   2. https://onelake.dfs.fabric.microsoft.com/<workspace>/<item>.Lakehouse/Files[/<rel>]
	#      (explicit Files; FilesPath = <rel>)
	#   3. https://onelake.dfs.fabric.microsoft.com/<workspace>/<item>.Lakehouse/Tables[/<schema>]
	#      (explicit Tables for table-typed destinations; TablesPath = <schema>)
	# All three shapes are accepted here; the call-site helpers
	# (Send-FileToOneLake / Get-RemoteFile-OneLake) route operational artifacts
	# under /Files/ regardless of TablesPath, so an -OutputPath that points at
	# the lakehouse root or at an explicit /Tables/<schema> still lands
	# log / checkpoint / mirror artifacts in the correct /Files/ subtree.
	$u = [Uri]$Url
	$accountUrl = "{0}://{1}" -f $u.Scheme, $u.Host
	$segments = ($u.AbsolutePath.TrimStart('/') -split '/' | Where-Object { $_ -ne '' })
	# Force into an array shape so .Count is reliable even for 1- or 0-element results.
	$segments = @($segments)
	if ($segments.Count -lt 2) {
		throw "Fabric URL must include workspace and item: '$Url'"
	}
	$workspace = $segments[0]
	$itemFull  = $segments[1]   # e.g. MyLakehouse.Lakehouse  OR  an item GUID
	$itemGuidPattern = '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
	if ($itemFull -match '\.(Lakehouse|Warehouse)$') {
		$itemType  = $Matches[1]
		$itemName  = $itemFull.Substring(0, $itemFull.Length - ($itemType.Length + 1))
	}
	elseif ($itemFull -match $itemGuidPattern) {
		# GUID-addressed item: OneLake references the item by its GUID with no type
		# suffix (https://onelake.dfs.fabric.microsoft.com/<wsGuid>/<itemGuid>/...).
		# The DFS path is type-agnostic; PAX only emits Lakehouse-shaped output, so
		# record the type as Lakehouse for display/diagnostics. ItemFull stays the
		# GUID verbatim so every downstream path ("$FilesystemBase/$ItemFull/...")
		# builds the correct GUID-form DFS URL.
		$itemType  = 'Lakehouse'
		$itemName  = $itemFull
	}
	else {
		throw "Fabric item must end with .Lakehouse/.Warehouse, or be an item GUID: '$itemFull'"
	}

	$filesPath  = ''
	$tablesPath = ''
	$rootMode   = $false
	if ($segments.Count -eq 2) {
		$rootMode = $true
	}
	elseif ($segments[2] -eq 'Files') {
		$filesPath = if ($segments.Count -gt 3) { ($segments | Select-Object -Skip 3) -join '/' } else { '' }
	}
	elseif ($segments[2] -eq 'Tables') {
		$tablesPath = if ($segments.Count -gt 3) { ($segments | Select-Object -Skip 3) -join '/' } else { '' }
	}
	else {
		throw "Fabric URL third segment must be 'Files', 'Tables', or absent (lakehouse root): '$Url'"
	}

	return [pscustomobject]@{
		AccountUrl     = $accountUrl
		Workspace      = $workspace
		ItemName       = $itemName
		ItemType       = $itemType
		ItemFull       = $itemFull
		FilesPath      = $filesPath.TrimEnd('/')
		TablesPath     = $tablesPath.TrimEnd('/')
		RootMode       = $rootMode
		FilesystemBase = "$accountUrl/$workspace"
	}
}

# ==============================================
# AZURE (FABRIC/ONELAKE) TOKEN INFRASTRUCTURE
# ==============================================
# Mirrors the Graph token refresh design ($script:SharedAuthState +
# Refresh-GraphTokenIfNeeded + Invoke-TokenRefresh) but for the OneLake DFS
# audience (https://storage.azure.com/), which is acquired through Az.Accounts.
#
# Layers:
#   Get-FabricStorageTokenRaw   - private; runs Connect-AzAccount/Get-AzAccessToken;
#                                 normalizes ExpiresOn to UTC DateTime; tags AuthMethod.
#   Invoke-AzTokenAcquire       - private; calls Raw + stale-token rejection +
#                                 updates $script:AzAuthState + emits log line.
#   Refresh-FabricTokenIfNeeded - public; proactive (5-min buffer + 50-min age cap),
#                                 cooldown (auth-mode aware), -Force for 401 reactive.
#   Get-FabricStorageToken      - public; backward-compatible string-returning wrapper
#                                 (always returns a refresh-checked token).
#   Invoke-FabricWebRequest     - public; wraps Invoke-WebRequest for OneLake calls.
#                                 Pre-flight refresh + transparent 401 retry once.
# Reactive triggers: 401 detected by Invoke-FabricWebRequest -> -Force refresh + retry.
# Proactive triggers: BufferMinutes (5) or token age >50 min, whichever comes first.
# Cooldown: 45s for app-only/MI (silent client_credentials/IMDS); 5min for interactive
#           (avoids re-prompt spam on long upload phases).
function Get-FabricStorageTokenRaw {
	[CmdletBinding()]
	param()
	$resource = 'https://storage.azure.com/'
	if (-not (Get-Module -Name Az.Accounts -ListAvailable -ErrorAction SilentlyContinue)) {
		throw "Az.Accounts module not installed. Install with: Install-Module Az.Accounts -Scope CurrentUser"
	}
	Import-Module Az.Accounts -ErrorAction Stop | Out-Null

	$authMethodTag = 'Interactive'
	$ctx = Get-AzContext -ErrorAction SilentlyContinue
	if (-not $ctx) {
		if ($Auth -eq 'ManagedIdentity') {
			$authMethodTag = 'ManagedIdentity'
			if ($env:AZURE_CLIENT_ID) {
				Connect-AzAccount -Identity -AccountId $env:AZURE_CLIENT_ID -ErrorAction Stop | Out-Null
			} else {
				Connect-AzAccount -Identity -ErrorAction Stop | Out-Null
			}
		}
		elseif ($Auth -eq 'AppRegistration' -and $script:TenantId -and $script:ClientId -and $script:ClientSecret) {
			$authMethodTag = 'AppRegistration'
			$secureSecret = ConvertTo-SecureString -String $script:ClientSecret -AsPlainText -Force
			$cred = New-Object System.Management.Automation.PSCredential($script:ClientId, $secureSecret)
			Connect-AzAccount -ServicePrincipal -Tenant $script:TenantId -Credential $cred -ErrorAction Stop | Out-Null
		}
		else {
			Connect-AzAccount -ErrorAction Stop | Out-Null
		}
	} else {
		# Reuse existing context; classify by account type so cooldown/log lines stay accurate.
		if ($ctx.Account -and $ctx.Account.Type -eq 'ManagedService') { $authMethodTag = 'ManagedIdentity' }
		elseif ($ctx.Account -and $ctx.Account.Type -eq 'ServicePrincipal') { $authMethodTag = 'AppRegistration' }
	}

	$tokenObj = Get-AzAccessToken -ResourceUrl $resource -ErrorAction Stop
	# Token shape: newer Az returns SecureString; older returns plain string.
	$tokenStr = if ($tokenObj.Token -is [System.Security.SecureString]) {
		[System.Net.NetworkCredential]::new('', $tokenObj.Token).Password
	} else {
		[string]$tokenObj.Token
	}
	# ExpiresOn shape: newer Az returns DateTimeOffset; older returns DateTime; defensive parse for string.
	$expiresUtc = if ($tokenObj.ExpiresOn -is [System.DateTimeOffset]) {
		$tokenObj.ExpiresOn.UtcDateTime
	} elseif ($tokenObj.ExpiresOn -is [datetime]) {
		if ($tokenObj.ExpiresOn.Kind -eq [System.DateTimeKind]::Utc) { $tokenObj.ExpiresOn } else { $tokenObj.ExpiresOn.ToUniversalTime() }
	} else {
		([datetime]$tokenObj.ExpiresOn).ToUniversalTime()
	}

	return [pscustomobject]@{
		Token      = $tokenStr
		ExpiresOn  = $expiresUtc
		AuthMethod = $authMethodTag
	}
}

function Invoke-AzTokenAcquire {
	[CmdletBinding()]
	param([string] $Reason = 'initial')
	try {
		$tokenObj = Get-FabricStorageTokenRaw
		# Stale-token rejection: refuse a token that is already at/near expiry. Protects
		# against MSAL cache returning a stale entry after process suspension or system sleep.
		$nowUtc = (Get-Date).ToUniversalTime()
		$minutesValid = ($tokenObj.ExpiresOn - $nowUtc).TotalMinutes
		if ($minutesValid -le 2) {
			throw ("Acquired OneLake storage token is already expired or near-expiry (expires in {0:N1} min)." -f $minutesValid)
		}

		$script:AzAuthState.Token              = $tokenObj.Token
		$script:AzAuthState.ExpiresOn          = $tokenObj.ExpiresOn
		$script:AzAuthState.AcquiredAt         = Get-Date
		$script:AzAuthState.LastRefresh        = Get-Date
		$script:AzAuthState.RefreshCount++
		$script:AzAuthState.AuthMethod         = $tokenObj.AuthMethod
		# Mirror to legacy $script:FabricToken so any cached references stay in sync.
		$script:FabricToken                    = $tokenObj.Token

		$verb = if ($script:AzAuthState.RefreshCount -eq 1) { 'acquired' } else { 'refreshed' }
		Write-LogHost ("  [AZ-TOKEN] OneLake storage token {0} ({1}); auth: {2}; expires {3} UTC; refresh #{4}" -f $verb, $Reason, $tokenObj.AuthMethod, $tokenObj.ExpiresOn.ToString('yyyy-MM-dd HH:mm:ss'), $script:AzAuthState.RefreshCount) -ForegroundColor Gray
		return $true
	}
	catch {
		Write-LogHost ("  [AZ-TOKEN] [!] Failed to acquire OneLake storage token ({0}): {1}" -f $Reason, $_.Exception.Message) -ForegroundColor Red
		return $false
	}
}

function Refresh-FabricTokenIfNeeded {
	<#
	.SYNOPSIS
		Proactively refreshes the Fabric/OneLake storage token if nearing expiry.
	.PARAMETER BufferMinutes
		Refresh if token expires within this many minutes. Default: 5.
	.PARAMETER Force
		Bypass cooldown and force re-acquisition (used by 401 reactive retry).
	.OUTPUTS
		$true  - token is valid (either still-valid or freshly refreshed)
		$false - acquisition/refresh failed; caller must surface the error
	#>
	[CmdletBinding()]
	param(
		[int]    $BufferMinutes = 5,
		[switch] $Force
	)
	$now = (Get-Date).ToUniversalTime()

	# First-time acquisition: no state yet.
	if (-not $script:AzAuthState.Token -or -not $script:AzAuthState.ExpiresOn) {
		return (Invoke-AzTokenAcquire -Reason 'initial')
	}

	$minutesRemaining = ($script:AzAuthState.ExpiresOn - $now).TotalMinutes
	$tokenAge = if ($script:AzAuthState.AcquiredAt) {
		((Get-Date) - $script:AzAuthState.AcquiredAt).TotalMinutes
	} else { 999 }

	# Trigger conditions:
	#   - Forced (typically 401 reactive)
	#   - Within BufferMinutes of expiry (proactive)
	#   - Token age > 50 min (belt-and-suspenders for any auth mode where ExpiresOn might be optimistic)
	$needRefresh = $Force.IsPresent -or ($minutesRemaining -le $BufferMinutes) -or ($tokenAge -gt 50)
	if (-not $needRefresh) { return $true }

	# Cooldown: app-only / MI refresh silently via client_credentials or IMDS (cheap),
	# so 45s is enough. Interactive may prompt the user, so 5 min keeps that bearable.
	$isAppOnly = ($script:AzAuthState.AuthMethod -in @('ManagedIdentity', 'AppRegistration'))
	$cooldownMinutes = if ($isAppOnly) { 0.75 } else { 5.0 }
	if (-not $Force -and $script:AzAuthState.LastRefreshAttempt) {
		$sinceLast = ((Get-Date) - $script:AzAuthState.LastRefreshAttempt).TotalMinutes
		if ($sinceLast -lt $cooldownMinutes) {
			# Still in cooldown; report current token as valid only if it actually is.
			return ($minutesRemaining -gt 0)
		}
	}
	$script:AzAuthState.LastRefreshAttempt = Get-Date

	$reason = if ($Force.IsPresent) {
		'forced (401 retry or explicit)'
	} elseif ($minutesRemaining -le $BufferMinutes) {
		("near-expiry ({0:N1} min remaining)" -f $minutesRemaining)
	} else {
		("age cap ({0:N1} min)" -f $tokenAge)
	}
	return (Invoke-AzTokenAcquire -Reason $reason)
}

function Get-FabricStorageToken {
	<#
	.SYNOPSIS
		Returns a valid OneLake storage-audience bearer token (string) for OneLake DFS calls.
	.DESCRIPTION
		Backward-compatible wrapper around the Az token state machine. Always invokes
		Refresh-FabricTokenIfNeeded first so callers receive a token guaranteed to have at
		least BufferMinutes of validity (or a fresh one). Throws if acquisition fails.
	#>
	[CmdletBinding()] param()
	$ok = Refresh-FabricTokenIfNeeded
	if (-not $ok -or -not $script:AzAuthState.Token) {
		throw "Failed to acquire Fabric/OneLake storage token (see prior [AZ-TOKEN] messages)."
	}
	return $script:AzAuthState.Token
}

function Invoke-FabricWebRequest {
	<#
	.SYNOPSIS
		Invoke-WebRequest wrapper for OneLake DFS calls with proactive token refresh
		and transparent 401 reactive retry.
	.DESCRIPTION
		Before each call: ensures token is fresh via Refresh-FabricTokenIfNeeded.
		During the call: if a 401 Unauthorized is returned, forces a refresh and
		retries the request once with the new token. Any other status (429, 5xx,
		403, 404, etc.) is re-thrown unchanged so the caller's existing retry/error
		handling (e.g., chunk-upload 429/5xx backoff loops) continues to work.
	.PARAMETER Headers
		Caller-supplied headers. The Authorization header is ALWAYS overwritten with
		the current $script:AzAuthState.Token. x-ms-version defaults to '2021-06-08'
		if the caller does not supply it.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string]   $Uri,
		[Parameter(Mandatory)] [string]   $Method,
		[hashtable] $Headers,
		$Body,
		[string]    $ContentType,
		[string]    $OutFile
	)
	# Pre-flight refresh.
	$null = Refresh-FabricTokenIfNeeded
	if (-not $script:AzAuthState.Token) {
		throw "Invoke-FabricWebRequest: no OneLake storage token available."
	}

	# Build effective headers; always set Authorization from current state.
	$h = @{}
	if ($Headers) {
		foreach ($k in $Headers.Keys) {
			if ($k -ne 'Authorization') { $h[$k] = $Headers[$k] }
		}
	}
	$h['Authorization'] = "Bearer $($script:AzAuthState.Token)"
	if (-not $h.ContainsKey('x-ms-version')) { $h['x-ms-version'] = '2021-06-08' }

	$invokeParams = @{
		Uri             = $Uri
		Method          = $Method
		Headers         = $h
		UseBasicParsing = $true
		ErrorAction     = 'Stop'
	}
	if ($PSBoundParameters.ContainsKey('Body')) { $invokeParams.Body = $Body }
	if ($ContentType)                           { $invokeParams.ContentType = $ContentType }
	if ($OutFile)                               { $invokeParams.OutFile = $OutFile }

	try {
		return Invoke-WebRequest @invokeParams
	}
	catch {
		$status = try { $_.Exception.Response.StatusCode.value__ } catch { 0 }
		if ($status -eq 401) {
			Write-LogHost "  [AZ-TOKEN] OneLake returned 401 Unauthorized - forcing token refresh and retrying once..." -ForegroundColor Yellow
			$refreshed = Refresh-FabricTokenIfNeeded -Force
			if (-not $refreshed) {
				throw ("OneLake 401 Unauthorized and token refresh failed: {0}" -f $_.Exception.Message)
			}
			$h['Authorization'] = "Bearer $($script:AzAuthState.Token)"
			$invokeParams.Headers = $h
			return Invoke-WebRequest @invokeParams
		}
		throw
	}
}

function Test-RemoteDestination {
	[CmdletBinding()] param()
	if ($script:RemoteOutputMode -eq 'None') { return }
	if ($script:RemoteOutputMode -eq 'SharePoint') {
		$resolved = Resolve-SharePointTarget -Url $script:RemoteOutputUrl
		$script:SPResolved = $resolved
		# Ensure folder exists (create if missing)
		if ($resolved.FolderPath) {
			$folderUri = "https://graph.microsoft.com/v1.0/drives/$($resolved.DriveId)/root:/$($resolved.FolderPath)"
			try {
				Invoke-MgGraphRequest -Method GET -Uri $folderUri -ErrorAction Stop | Out-Null
			} catch {
				# Create folder hierarchy
				$parts = $resolved.FolderPath -split '/'
				$accumulated = ''
				foreach ($p in $parts) {
					$parentUri = if ($accumulated) { "https://graph.microsoft.com/v1.0/drives/$($resolved.DriveId)/root:/${accumulated}:/children" } else { "https://graph.microsoft.com/v1.0/drives/$($resolved.DriveId)/root/children" }
					# FolderPath segments come from [Uri].AbsolutePath, which percent-encodes spaces
					# and other reserved characters (e.g. 'PAX Exports' -> 'PAX%20Exports'). The
					# parent addressing above (root:/...:/children) is colon-path syntax that Graph
					# DECODES, but the 'name' field below is a literal display name that Graph does
					# NOT decode — so passing the raw segment created a folder literally named
					# 'PAX%20Exports' alongside the decoded 'PAX Exports' that the upload path
					# (Send-FileToSharePoint, also colon-path) resolves to. Decode the segment for
					# the display name so both mechanisms agree and only one folder is created.
					$folderDisplayName = [System.Uri]::UnescapeDataString($p)
					$body = @{ name = $folderDisplayName; folder = @{}; '@microsoft.graph.conflictBehavior' = 'replace' } | ConvertTo-Json
					try { Invoke-MgGraphRequest -Method POST -Uri $parentUri -Body $body -ContentType 'application/json' -ErrorAction Stop | Out-Null } catch {}
					$accumulated = if ($accumulated) { "$accumulated/$p" } else { $p }
				}
			}
		}
	}
	elseif ($script:RemoteOutputMode -eq 'Fabric') {
		$resolved = Resolve-FabricTarget -Url $script:RemoteOutputUrl
		$script:FabricResolved = $resolved
		# Initial token acquisition (populates $script:AzAuthState). Classify Az/auth
		# failures here so customers see Cause/Action lines instead of raw exceptions.
		try {
			$null = Get-FabricStorageToken
		} catch {
			$tokenErr = $_.Exception.Message
			$tokenDiag = New-Object System.Collections.Generic.List[string]
			$tokenDiag.Add("OneLake storage token acquisition failed for workspace '$($resolved.Workspace)'.")
			if ($tokenErr -match 'Az\.Accounts module not installed') {
				$tokenDiag.Add('Cause: The Az.Accounts PowerShell module is not installed.')
				$tokenDiag.Add('Action: Install-Module Az.Accounts -Scope CurrentUser')
			} elseif ($tokenErr -match 'AADSTS' -or $tokenErr -match 'consent' -or $tokenErr -match 'admin') {
				$tokenDiag.Add('Cause: Azure AD rejected the sign-in for the storage.azure.com audience.')
				$tokenDiag.Add('Action: Verify the identity has Azure AD sign-in to your tenant, and that')
				$tokenDiag.Add('        any conditional access / MFA requirements are satisfied.')
			} elseif ($tokenErr -match 'IDENTITY|managed identity|MSI|IMDS') {
				$tokenDiag.Add('Cause: Managed identity token acquisition failed (no IMDS endpoint reachable,')
				$tokenDiag.Add('       or AZURE_CLIENT_ID points to an identity not assigned to this host).')
				$tokenDiag.Add('Action: Re-run from a host with an assigned managed identity, or use')
				$tokenDiag.Add('        -Auth Interactive / -Auth AppRegistration instead.')
			} else {
				$tokenDiag.Add('Cause: Az.Accounts could not acquire a token for https://storage.azure.com/.')
				$tokenDiag.Add('Action: Verify your authentication mode (-Auth) and that you can sign in via')
				$tokenDiag.Add('        Connect-AzAccount manually.')
			}
			$tokenDiag.Add('')
			$tokenDiag.Add("Az response: $tokenErr")
			throw ($tokenDiag -join "`n")
		}
		# HEAD the filesystem (workspace) to verify access. Invoke-FabricWebRequest sets
		# Authorization + x-ms-version automatically and handles 401 reactive refresh.
		$probeUri = "$($resolved.FilesystemBase)?resource=filesystem"
		try {
			$null = Invoke-FabricWebRequest -Uri $probeUri -Method HEAD
		} catch {
			# Classify OneLake DFS responses. Unlike Graph, OneLake rarely returns a JSON
			# body on auth failures — the HTTP status is the primary signal.
			$status = 0
			try { $status = [int]$_.Exception.Response.StatusCode.value__ } catch {}
			if ($status -eq 0) { try { if ($_.Exception.Response.StatusCode -is [System.Net.HttpStatusCode]) { $status = [int]$_.Exception.Response.StatusCode } } catch {} }
			$rawDetail = $_.Exception.Message
			if ($rawDetail.Length -gt 600) { $rawDetail = $rawDetail.Substring(0, 600) + '...(truncated)' }

			$diagLines = New-Object System.Collections.Generic.List[string]
			$diagLines.Add("OneLake filesystem probe failed (workspace '$($resolved.Workspace)', item '$($resolved.ItemFull)').")

			if ($status -eq 401) {
				$diagLines.Add('Cause: OneLake rejected the storage token (401). The token audience is correct')
				$diagLines.Add('       but the identity is not recognized by this Fabric workspace.')
				$diagLines.Add('Action: Verify the identity is signed in to the same tenant that owns the Fabric')
				$diagLines.Add('        workspace, and that the storage.azure.com token is not expired/blocked.')
			}
			elseif ($status -eq 403) {
				$diagLines.Add('Cause: The identity is authenticated but lacks permissions on the Fabric workspace')
				$diagLines.Add('       (HTTP 403 Forbidden from OneLake DFS).')
				$diagLines.Add('Action: In the Fabric portal -> Workspace settings -> Manage access, grant the')
				$diagLines.Add('        identity at least Contributor. See the "Permissions Required for THIS run"')
				$diagLines.Add('        table earlier in this output for the exact Azure RBAC roles required.')
			}
			elseif ($status -eq 404) {
				$diagLines.Add("Cause: Workspace or item not found (HTTP 404). One of these is wrong:")
				$diagLines.Add("         workspace = '$($resolved.Workspace)'")
				$diagLines.Add("         item      = '$($resolved.ItemFull)' (must exist as a Lakehouse/Warehouse)")
				$diagLines.Add('Action: Verify the URL by opening the lakehouse in the Fabric portal and using')
				$diagLines.Add('        the OneLake "Copy ABFS path" option, then converting to https:// form.')
			}
			elseif ($status -ge 500) {
				$diagLines.Add("Cause: OneLake returned a server error (HTTP $status). This is usually transient.")
				$diagLines.Add('Action: Wait a minute and retry. If it persists, check Fabric service health.')
			}
			else {
				$diagLines.Add("Cause: OneLake DFS probe failed (HTTP status: $status).")
				$diagLines.Add('Action: Verify the Fabric workspace URL is correct and that the identity has')
				$diagLines.Add('        the Azure RBAC roles listed in the "Permissions Required for THIS run" table.')
			}
			$diagLines.Add('')
			$diagLines.Add("OneLake response: $rawDetail")

			throw ($diagLines -join "`n")
		}
	}
}

function Get-GraphErrorDetail {
	# Best-effort extraction of the Microsoft Graph error body from a caught error.
	# PowerShell attaches the raw HTTP response body to $_.ErrorDetails.Message for both
	# Invoke-MgGraphRequest and Invoke-WebRequest; fall back to the response stream, then
	# to the plain exception message. Returns a short single-line string for logging.
	[CmdletBinding()]
	param([Parameter(Mandatory)] $ErrorRecord)
	$raw = $null
	if ($ErrorRecord.ErrorDetails -and $ErrorRecord.ErrorDetails.Message) {
		$raw = $ErrorRecord.ErrorDetails.Message
	}
	elseif ($ErrorRecord.Exception -and $ErrorRecord.Exception.Response) {
		try {
			$stream = $ErrorRecord.Exception.Response.GetResponseStream()
			if ($stream) {
				$reader = New-Object System.IO.StreamReader($stream)
				$raw = $reader.ReadToEnd()
				$reader.Dispose()
			}
		} catch { }
	}
	if (-not $raw) { return $ErrorRecord.Exception.Message }
	# Try to pull error.code / error.message out of the JSON body.
	try {
		$j = $raw | ConvertFrom-Json -ErrorAction Stop
		if ($j.error) {
			$code = $j.error.code
			$msg  = $j.error.message
			return ("{0}: {1}" -f $code, $msg).Trim(': ')
		}
	} catch { }
	# Non-JSON body - return a trimmed single line.
	return ($raw -replace '\s+', ' ').Trim()
}

function script:New-PaxGraphUploadSession {
	# Direct-REST createUploadSession for large SharePoint uploads (files above the Graph simple-upload
	# ceiling). The request body is built as a plain ordered object and serialized with ConvertTo-Json,
	# then sent via Invoke-RestMethod with an explicit bearer header - deliberately BYPASSING the Graph SDK
	# object serializer used by Invoke-MgGraphRequest. Handing a hashtable body that carries a PowerShell
	# string to that serializer fails, because the string's extended-type '.Chars' member is a
	# PSParameterizedProperty that triggers a self-referencing-loop serialization error at 'item.name.Chars'
	# and no HTTP request is ever sent. Returns the parsed session object (with .uploadUrl); throws with
	# Graph error detail on failure. Never logs the token or the returned uploadUrl.
	param(
		[Parameter(Mandatory)][string]$SessionUri,
		[Parameter(Mandatory)][string]$RemoteFileName
	)
	try { $null = Refresh-GraphTokenIfNeeded } catch { }
	$token = Get-GraphAccessToken
	if ([string]::IsNullOrWhiteSpace([string]$token)) { throw 'createUploadSession: no Graph access token available.' }
	# Plain values only -> plain JSON. No PowerShell object reaches an SDK serializer.
	$bodyObj = [ordered]@{ item = [ordered]@{ '@microsoft.graph.conflictBehavior' = 'replace'; name = [string]$RemoteFileName } }
	$json = $bodyObj | ConvertTo-Json -Depth 4 -Compress
	$jsonBytes = [System.Text.Encoding]::UTF8.GetBytes($json)
	$headers = @{ Authorization = ('Bearer ' + [string]$token) }
	return Invoke-RestMethod -Uri $SessionUri -Method POST -Headers $headers -ContentType 'application/json' -Body $jsonBytes -ErrorAction Stop
}

function Send-FileToSharePoint {
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $LocalPath,
		[string] $RemoteFileName,
		# Optional per-data-type SharePoint parent URL. When supplied, the destination
		# is resolved against $ParentOverride instead of the script-wide Purview
		# RemoteOutputUrl. Used by per-data-type append surfaces (UserInfo / Agent365 /
		# Log) when their -OutputPath* points at a different SharePoint folder than
		# the primary Purview output.
		[string] $ParentOverride
	)
	if (-not (Test-Path -LiteralPath $LocalPath)) { throw "Send-FileToSharePoint: source not found: $LocalPath" }
	if ($ParentOverride) {
		$resolved = Resolve-SharePointTarget -Url $ParentOverride
	}
	else {
		if (-not $script:SPResolved) { $script:SPResolved = Resolve-SharePointTarget -Url $script:RemoteOutputUrl }
		$resolved = $script:SPResolved
	}
	$fileName = if ($RemoteFileName) { $RemoteFileName } else { Split-Path -Leaf $LocalPath }
	# Per-segment URI escaping for the filename. The auto-defaulted basenames used by
	# this script are safe ASCII (timestamps + underscores), but routing custom basenames
	# through the same encoding pipeline avoids any per-call-site special casing.
	$fileNameEnc = [System.Uri]::EscapeDataString($fileName)
	$relPath  = if ($resolved.FolderPath) { "$($resolved.FolderPath)/$fileNameEnc" } else { $fileNameEnc }
	$fileInfo = Get-Item -LiteralPath $LocalPath
	$sizeMb = $fileInfo.Length / 1MB

	# Graph simple upload (PUT .../content) supports up to 250 MB; use it for everything
	# up to that ceiling so as many files as possible avoid the resumable-upload-session
	# API (which some locked-down libraries / egress proxies reject even when a simple PUT
	# is allowed). Files above 250 MB still use createUploadSession + chunked PUT.
	$simpleUploadMax = 250MB
	if ($fileInfo.Length -le $simpleUploadMax) {
		$putUri = "https://graph.microsoft.com/v1.0/drives/$($resolved.DriveId)/root:/${relPath}:/content"
		$bytes  = [System.IO.File]::ReadAllBytes($LocalPath)
		try {
			Invoke-MgGraphRequest -Method PUT -Uri $putUri -Body $bytes -ContentType 'application/octet-stream' -ErrorAction Stop | Out-Null
		}
		catch {
			$detail = Get-GraphErrorDetail -ErrorRecord $_
			throw "SharePoint simple upload (PUT) failed for '$relPath': $detail"
		}
	}
	else {
		# Create upload session
		$sessUri = "https://graph.microsoft.com/v1.0/drives/$($resolved.DriveId)/root:/${relPath}:/createUploadSession"
		try {
			# Direct REST (New-PaxGraphUploadSession): the body is never handed to the Graph SDK object
			# serializer, which fails on a PowerShell string's ETS '.Chars' property before any HTTP send.
			$session = script:New-PaxGraphUploadSession -SessionUri $sessUri -RemoteFileName $fileName
		}
		catch {
			$detail = Get-GraphErrorDetail -ErrorRecord $_
			$httpStatus = try { $_.Exception.Response.StatusCode.value__ } catch { 0 }
			$sizeGb = $fileInfo.Length / 1GB
			throw ("createUploadSession failed for '{0}' (HTTP {1}; file size {2:N0} bytes / {3:N2} GiB): {4}" -f $relPath, $httpStatus, $fileInfo.Length, $sizeGb, $detail)
		}
		$uploadUrl = $session.uploadUrl
		if (-not $uploadUrl) { throw "SharePoint createUploadSession returned no uploadUrl for '$relPath'." }

		# Aggregate upload progress heartbeat (large files only). Reports transfer status only - never
		# the uploadUrl, bearer token, or any response secret.
		$hbInterval = if ($StatusIntervalSeconds -gt 0) { [int]$StatusIntervalSeconds } else { 60 }
		$uploadStart = Get-Date
		$lastHb = $uploadStart
		$chunkCount = 0
		$retryTotal = 0
		Write-LogHost ("  SharePoint resumable upload session created: {0} ({1:N0} bytes / {2:N2} MiB); uploading in chunks..." -f $relPath, $fileInfo.Length, ($fileInfo.Length / 1MB)) -ForegroundColor Cyan

		$chunkSize = 5MB   # multiple of 320 KB
		$fs = [System.IO.File]::OpenRead($LocalPath)
		try {
			$buffer = New-Object byte[] $chunkSize
			$offset = 0L
			while ($offset -lt $fileInfo.Length) {
				$toRead = [int][Math]::Min([int64]$chunkSize, $fileInfo.Length - $offset)
				# FileStream.Read may return fewer bytes than requested; loop until the
				# fragment is fully populated (or EOF) so every Content-Range fragment
				# carries exactly the byte count its header declares.
				$read = 0
				while ($read -lt $toRead) {
					$n = $fs.Read($buffer, $read, $toRead - $read)
					if ($n -le 0) { break }
					$read += $n
				}
				if ($read -le 0) { break }
				$end = $offset + $read - 1
				$range = "bytes $offset-$end/$($fileInfo.Length)"
				# Send a true byte[] body. PowerShell range-indexing ($buffer[0..N])
				# returns an Object[] of boxed bytes, which Invoke-WebRequest stringifies
				# instead of sending as raw bytes — producing a body whose length does not
				# match the declared Content-Range and a 400 (Bad Request) from Graph on
				# the final partial fragment. Copy into a right-sized byte[] instead.
				if ($read -eq $chunkSize) {
					$slice = $buffer
				}
				else {
					$slice = New-Object byte[] $read
					[System.Array]::Copy($buffer, 0, $slice, 0, $read)
				}
				$attempt = 0
				while ($true) {
					try {
						$null = Invoke-WebRequest -Uri $uploadUrl -Method PUT -Body $slice -Headers @{ 'Content-Range' = $range } -ContentType 'application/octet-stream' -UseBasicParsing -ErrorAction Stop
						break
					}
					catch {
						$status = try { $_.Exception.Response.StatusCode.value__ } catch { 0 }
						$retryAfter = try { [int]$_.Exception.Response.Headers['Retry-After'] } catch { 0 }
						$attempt++
						if (($status -eq 429 -or $status -ge 500) -and $attempt -lt 5) {
							$retryTotal++
							$wait = if ($retryAfter -gt 0) { $retryAfter } else { [Math]::Min(60, [Math]::Pow(2, $attempt)) }
							Start-Sleep -Seconds $wait
							continue
						}
						throw
					}
				}
				$offset += $read
				$chunkCount++
				$nowHb = Get-Date
				if ((($nowHb - $lastHb).TotalSeconds -ge $hbInterval) -or ($offset -ge $fileInfo.Length)) {
					$elapsedSec = ($nowHb - $uploadStart).TotalSeconds
					$pct = if ($fileInfo.Length -gt 0) { [Math]::Round(100.0 * $offset / $fileInfo.Length, 1) } else { 100 }
					$rateMb = if ($elapsedSec -gt 0) { [Math]::Round(($offset / 1MB) / $elapsedSec, 2) } else { 0 }
					Write-LogHost ("    upload progress: {0:N0}/{1:N0} bytes ({2}%); chunk {3:N0}; elapsed {4:N0}s; {5} MiB/s; retries {6:N0}" -f $offset, $fileInfo.Length, $pct, $chunkCount, $elapsedSec, $rateMb, $retryTotal) -ForegroundColor DarkGray
					$lastHb = $nowHb
				}
			}
		}
		finally { $fs.Dispose() }
	}
	Write-LogHost ("  -> SharePoint upload OK: {0} ({1:N2} MB)" -f $relPath, $sizeMb) -ForegroundColor DarkGray
}

function Send-FileToOneLake {
	<#
	.SYNOPSIS
		Uploads a local file to OneLake Files/ via the DFS create/append/flush sequence.
	.PARAMETER FailIfExists
		Create-if-absent publication mode for IMMUTABLE resume-protocol objects (generation
		artifacts and authority records). The DFS Create File request carries an
		If-None-Match: * precondition, so an already-existing target answers 409/412 and is
		raised as a HARD COLLISION instead of being overwritten - an existence conflict is
		never success. Callers retry by allocating a completely fresh unique target, never by
		replacing the conflicted object.

		This is OPT-IN and scoped to resume-generation publication. Customer-facing output
		uploads omit the switch and keep the existing overwrite semantics unchanged.

		ASSUMPTION: the OneLake/ADLS Gen2 surface honours the If-None-Match: * conditional
		on Create File. Where it does not, the caller's nonce-bearing target names remain
		mandatory and any collision that is detected still fails closed.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $LocalPath,
		[string] $RemoteFileName,
		# Optional per-data-type Fabric/OneLake parent URL. See Send-FileToSharePoint
		# for the rationale. When omitted, falls back to the script-wide Purview URL.
		[string] $ParentOverride,
		[switch] $FailIfExists
	)
	if (-not (Test-Path -LiteralPath $LocalPath)) { throw "Send-FileToOneLake: source not found: $LocalPath" }
	if ($ParentOverride) {
		$resolved = Resolve-FabricTarget -Url $ParentOverride
	}
	else {
		if (-not $script:FabricResolved) { $script:FabricResolved = Resolve-FabricTarget -Url $script:RemoteOutputUrl }
		$resolved = $script:FabricResolved
	}
	$fileName = if ($RemoteFileName) { $RemoteFileName } else { Split-Path -Leaf $LocalPath }
	# Per-SEGMENT URI escaping. $RemoteFileName may contain '/' separators
	# (e.g. ".pax_resume/<ts>/<file>" from Sync-FabricResumeMirror); escaping the
	# whole string as one data segment would percent-encode the slashes ('%2F'),
	# malforming the DFS path so PUT (Create File) and PATCH (Append) target
	# different resolved files, surfacing as "400 (position not equal to length)".
	# Split-then-escape-per-segment preserves the hierarchical path.
	$fileNameEnc = ($fileName -split '/' | ForEach-Object { [System.Uri]::EscapeDataString($_) }) -join '/'
	$relInItem = if ($resolved.FilesPath) { "$($resolved.FilesPath)/$fileNameEnc" } else { $fileNameEnc }
	$dfsPath   = "$($resolved.FilesystemBase)/$($resolved.ItemFull)/Files/$relInItem"
	$fileInfo  = Get-Item -LiteralPath $LocalPath
	$sizeMb    = $fileInfo.Length / 1MB

	# Authorization + x-ms-version are set per-request by Invoke-FabricWebRequest using the
	# current $script:AzAuthState. Do not cache headers locally - the token may rotate.

	# Step 0: Pre-create any parent directories. OneLake Lakehouse Files/ uses a
	# hierarchical namespace; PUT ?resource=file does not auto-create intermediate
	# directories. Without this, mirroring artifacts to e.g. ".pax_resume/<ts>/"
	# can land the leaf file in an inconsistent state that surfaces downstream as
	# a 400 (position not equal to length) on the first append. Idempotent: a 409
	# response means the directory already exists and is treated as success.
	$parentRel = $null
	if ($relInItem -match '/') { $parentRel = $relInItem.Substring(0, $relInItem.LastIndexOf('/')) }
	if ($parentRel) {
		$dirUri = "$($resolved.FilesystemBase)/$($resolved.ItemFull)/Files/$parentRel`?resource=directory"
		try {
			$null = Invoke-FabricWebRequest -Uri $dirUri -Method PUT
		}
		catch {
			$dirStatus = try { $_.Exception.Response.StatusCode.value__ } catch { 0 }
			if ($dirStatus -ne 409) { throw }
		}
	}

	# Step 1: Create (PUT ?resource=file) - overwrites any existing file, unless
	# -FailIfExists asks for create-if-absent semantics.
	$createUri = "$dfsPath`?resource=file"
	if ($FailIfExists) {
		# If-None-Match: * makes the create succeed ONLY when the target does not already
		# exist. A 409/412 means something is already published at this exact name; for an
		# immutable resume-protocol object that is a hard collision, not a success, so it is
		# raised and the caller allocates a fresh unique target instead of replacing bytes.
		try {
			$null = Invoke-FabricWebRequest -Uri $createUri -Method PUT -Headers @{ 'If-None-Match' = '*' }
		}
		catch {
			$createStatus = try { $_.Exception.Response.StatusCode.value__ } catch { 0 }
			if ($createStatus -eq 409 -or $createStatus -eq 412) {
				throw ("Send-FileToOneLake: create-if-absent conflict for {0} - the target object already exists and an immutable resume object is never overwritten." -f $relInItem)
			}
			throw
		}
	}
	else {
		$null = Invoke-FabricWebRequest -Uri $createUri -Method PUT
	}

	# Step 2: Append in chunks (PATCH ?action=append&position=N).
	# Inner retry loop handles 429/5xx with exponential backoff. 401 is handled transparently
	# inside Invoke-FabricWebRequest (force-refresh + retry once); any 401 that escapes here
	# means refresh itself failed, which is fatal for this upload and propagates up.
	$chunkSize = 4MB
	# Production ALWAYS streams from disk via File.OpenRead. $script:PaxOneLakeSourceStreamOverride
	# is an internal test seam (null in every non-test run) that lets a focused test inject a
	# stream whose Read() returns deliberately short fragments, exercising the fill loop below
	# without changing the production read path.
	$fs = if ($script:PaxOneLakeSourceStreamOverride) { $script:PaxOneLakeSourceStreamOverride } else { [System.IO.File]::OpenRead($LocalPath) }
	try {
		$buffer = New-Object byte[] $chunkSize
		$position = 0L
		while ($position -lt $fileInfo.Length) {
			$toRead = [int][Math]::Min([int64]$chunkSize, $fileInfo.Length - $position)
			# FileStream.Read may return fewer bytes than requested; fill the fragment fully (or to EOF)
			# so the PATCH Content-Length and the declared append position stay exactly consistent.
			$read = 0
			while ($read -lt $toRead) {
				$n = $fs.Read($buffer, $read, $toRead - $read)
				if ($n -le 0) { break }
				$read += $n
			}
			if ($read -le 0) { break }
			# Send a TRUE byte[] body. PowerShell range-indexing ($buffer[0..N]) returns an Object[] of
			# boxed bytes, which the web cmdlet stringifies instead of transmitting as raw bytes - the wire
			# length then disagrees with the declared append position and OneLake rejects the PATCH with
			# "uploaded data is not contiguous" / "append position does not equal current file length".
			# Partial chunks (checkpoint JSON and small shards below the 4 MiB chunk size) are the NORMAL
			# path, so a right-sized byte[] copy is required for correctness here.
			if ($read -eq $chunkSize) {
				$slice = $buffer
			}
			else {
				$slice = [byte[]]::new($read)
				[System.Array]::Copy($buffer, 0, $slice, 0, $read)
			}
			$appendUri = "$dfsPath`?action=append&position=$position"
			$attempt = 0
			while ($true) {
				try {
					$null = Invoke-FabricWebRequest -Uri $appendUri -Method PATCH -Body $slice -ContentType 'application/octet-stream'
					break
				}
				catch {
					$status = try { $_.Exception.Response.StatusCode.value__ } catch { 0 }
					$retryAfter = try { [int]$_.Exception.Response.Headers['Retry-After'] } catch { 0 }
					$attempt++
					if (($status -eq 429 -or $status -ge 500) -and $attempt -lt 5) {
						$wait = if ($retryAfter -gt 0) { $retryAfter } else { [Math]::Min(60, [Math]::Pow(2, $attempt)) }
						Start-Sleep -Seconds $wait
						continue
					}
					throw
				}
			}
			$position += $read
		}
	}
	finally { $fs.Dispose() }

	# Local integrity guard: the append loop must have transmitted every source byte before
	# we ask OneLake to flush the declared length. A short/interrupted read (unexpected EOF, or
	# the local file mutated mid-upload) leaves $position < length; flushing that length would
	# commit a remote file whose tail was never sent. Fail locally instead of asking OneLake to
	# flush a length that was not uploaded. Normal successful uploads satisfy $position == length.
	if ($position -ne $fileInfo.Length) {
		throw ("Send-FileToOneLake: incomplete source read for {0} - sent {1} of {2} bytes before flush; aborting upload." -f $relInItem, $position, $fileInfo.Length)
	}

	# Step 3: Flush (PATCH ?action=flush&position=<size>)
	$flushUri = "$dfsPath`?action=flush&position=$($fileInfo.Length)"
	$null = Invoke-FabricWebRequest -Uri $flushUri -Method PATCH

	Write-LogHost ("  -> OneLake upload OK: {0} ({1:N2} MB)" -f $relInItem, $sizeMb) -ForegroundColor DarkGray
}

function Get-RemoteFile-SharePoint {
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $RelativeName,
		[Parameter(Mandatory)] [string] $DestinationPath,
		# Optional per-data-type SharePoint parent URL (see Send-FileToSharePoint).
		[string] $ParentOverride
	)
	if ($ParentOverride) {
		$resolved = Resolve-SharePointTarget -Url $ParentOverride
	}
	else {
		if (-not $script:SPResolved) { $script:SPResolved = Resolve-SharePointTarget -Url $script:RemoteOutputUrl }
		$resolved = $script:SPResolved
	}
	$relName   = [System.Uri]::EscapeDataString($RelativeName)
	$relPath  = if ($resolved.FolderPath) { "$($resolved.FolderPath)/$relName" } else { $relName }
	$dlUri    = "https://graph.microsoft.com/v1.0/drives/$($resolved.DriveId)/root:/${relPath}:/content"
	# Stream the response body straight to disk. The Graph SDK's
	# Invoke-MgGraphRequest -OutputFilePath buffers the ENTIRE body in memory before
	# writing it out, so a large append target (roughly 1 GB or more) exceeds the
	# single-object memory ceiling and fails. Invoke-WebRequest -OutFile on PowerShell 7
	# streams to disk instead, keeping peak memory flat regardless of file size (this
	# mirrors Get-RemoteFile-OneLake). Graph accepts a raw bearer token directly; a
	# missing file still surfaces as an HTTP 404 whose
	# $_.Exception.Response.StatusCode.value__ is 404, so every caller's
	# first-run / not-found classification is unchanged.
	$graphToken = Get-GraphAccessToken
	if (-not $graphToken) { throw "Get-RemoteFile-SharePoint: no Microsoft Graph access token available." }
	Invoke-WebRequest -Uri $dlUri -Method GET -Headers @{ Authorization = "Bearer $graphToken" } -OutFile $DestinationPath -UseBasicParsing -ErrorAction Stop | Out-Null
}

function Get-RemoteFile-OneLake {
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $RelativeName,
		[Parameter(Mandatory)] [string] $DestinationPath,
		# Optional per-data-type Fabric/OneLake parent URL (see Send-FileToSharePoint).
		[string] $ParentOverride
	)
	if ($ParentOverride) {
		$resolved = Resolve-FabricTarget -Url $ParentOverride
	}
	else {
		if (-not $script:FabricResolved) { $script:FabricResolved = Resolve-FabricTarget -Url $script:RemoteOutputUrl }
		$resolved = $script:FabricResolved
	}
	# Per-SEGMENT URI escaping. $RelativeName may contain '/' separators (e.g.
	# ".pax_resume/<ts>/<file>" from Restore-FabricResumeMirror); escaping the
	# whole string as one data segment would percent-encode the slashes to '%2F'
	# and resolve to a different (or non-existent) DFS path than the uploader
	# wrote to. Mirrors the Send-FileToOneLake fix.
	$relName   = ($RelativeName -split '/' | ForEach-Object { [System.Uri]::EscapeDataString($_) }) -join '/'
	$relInItem = if ($resolved.FilesPath) { "$($resolved.FilesPath)/$relName" } else { $relName }
	$dfsPath   = "$($resolved.FilesystemBase)/$($resolved.ItemFull)/Files/$relInItem"
	# Invoke-FabricWebRequest handles Authorization, x-ms-version, proactive refresh, 401 retry.
	$null = Invoke-FabricWebRequest -Uri $dfsPath -Method GET -OutFile $DestinationPath
}

function Get-RemoteAppendTargetSize {
	<#
	.SYNOPSIS
		Return the byte size of an append/merge target WITHOUT downloading its body,
		or $null when the size cannot be determined.
	.DESCRIPTION
		A cheap, read-only pre-flight probe used to warn when an append target is large
		enough that the in-memory merge could strain RAM. Dispatches by tier:
		  * SharePoint : a driveItem metadata GET (the download URL WITHOUT the
		                 ':/content' suffix) whose JSON carries a 'size' field.
		  * Fabric     : a DFS HEAD to the same path Get-RemoteFile-OneLake reads,
		                 returning Content-Length with no body.
		  * Local      : (Get-Item).Length.
		FAIL-OPEN: any error, unexpected response shape, or a not-found (404) target
		returns $null so the caller falls through to normal first-run / merge handling
		with no warning and no abort. A probe failure is never read as "huge" or
		"missing" - it simply yields "size unknown".
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [ValidateSet('SharePoint', 'Fabric', 'Local')] [string] $Tier,
		[string] $RelativeName,
		[string] $Path,
		[string] $ParentOverride
	)
	try {
		switch ($Tier) {
			'Local' {
				if (-not $Path) { return $null }
				return [int64](Get-Item -LiteralPath $Path -ErrorAction Stop).Length
			}
			'SharePoint' {
				if ($ParentOverride) { $resolved = Resolve-SharePointTarget -Url $ParentOverride }
				else {
					if (-not $script:SPResolved) { $script:SPResolved = Resolve-SharePointTarget -Url $script:RemoteOutputUrl }
					$resolved = $script:SPResolved
				}
				$relName = [System.Uri]::EscapeDataString($RelativeName)
				$relPath = if ($resolved.FolderPath) { "$($resolved.FolderPath)/$relName" } else { $relName }
				# Metadata GET: the download URL WITHOUT ':/content' returns the driveItem JSON.
				$metaUri = "https://graph.microsoft.com/v1.0/drives/$($resolved.DriveId)/root:/${relPath}"
				$item = Invoke-MgGraphRequest -Method GET -Uri $metaUri -ErrorAction Stop
				if ($null -ne $item -and $null -ne $item.size) { return [int64]$item.size }
				return $null
			}
			'Fabric' {
				if ($ParentOverride) { $resolved = Resolve-FabricTarget -Url $ParentOverride }
				else {
					if (-not $script:FabricResolved) { $script:FabricResolved = Resolve-FabricTarget -Url $script:RemoteOutputUrl }
					$resolved = $script:FabricResolved
				}
				$relName   = ($RelativeName -split '/' | ForEach-Object { [System.Uri]::EscapeDataString($_) }) -join '/'
				$relInItem = if ($resolved.FilesPath) { "$($resolved.FilesPath)/$relName" } else { $relName }
				$dfsPath   = "$($resolved.FilesystemBase)/$($resolved.ItemFull)/Files/$relInItem"
				$resp = Invoke-FabricWebRequest -Uri $dfsPath -Method HEAD
				$cl = $null
				if ($resp -and $resp.Headers) { $cl = $resp.Headers['Content-Length'] }
				if ($cl -is [array]) { $cl = $cl[0] }
				if ($null -ne $cl -and "$cl" -ne '') { return [int64]$cl }
				return $null
			}
		}
	}
	catch {
		# Fail-open: size unknown -> caller proceeds normally, no warning, no abort.
		return $null
	}
	return $null
}

function Get-AppendTargetSizeWarning {
	<#
	.SYNOPSIS
		Given an append-target size in bytes (or $null) and a threshold, return a
		human-readable advisory warning string when the size exceeds the threshold,
		otherwise $null. Pure (no side effects) so the decision is independently testable.
	#>
	[CmdletBinding()]
	param(
		[AllowNull()] [System.Nullable[int64]] $SizeBytes,
		[Parameter(Mandatory)] [int64] $ThresholdBytes,
		[string] $Label
	)
	if ($null -eq $SizeBytes) { return $null }
	if ($SizeBytes -le $ThresholdBytes) { return $null }
	$gb = [math]::Round($SizeBytes / 1GB, 2)
	$name = if ($Label) { " '$Label'" } else { '' }
	return (
		"WARNING: The append target$name is $gb GB. The merge step reads the entire " +
		"target into memory to deduplicate against it, which can require several times " +
		"that size in RAM. Large downloads themselves are streamed safely, but a very " +
		"large target can still exhaust memory during the merge. Consider archiving or " +
		"rolling the target to a fresh file, or ensure the machine has enough memory. " +
		"This is an advisory only - the run will continue."
	)
}

function script:Test-AuditPartitionConsistency {
	<#
	.SYNOPSIS
		Bounded, deterministic consistency check for a REPEATED fetch of a single 'successful' audit
		partition. Compares two RecordId samples (or counts) of the SAME partition and classifies the
		repeat as 'Stable' (identical set) or 'Unstable' (any difference). It NEVER picks the larger
		sample and NEVER unions the two - it only DETECTS/CLASSIFIES so the caller can refuse to
		silently certify an unstable partition (data-safe reconciliation). Observed live: SharePoint
		partition 26 returned 13,350 vs 15,465 (2,115 RecordIds silently lost, a strict subset).
	.OUTPUTS
		[pscustomobject] Consistent(bool), Verdict('Stable'|'Unstable'), FirstCount, RepeatCount,
		MissingFromRepeat, ExtraInRepeat, Basis('Set'|'Count').
	#>
	[CmdletBinding()]
	param([AllowNull()] $FirstRecordIds, [AllowNull()] $RepeatRecordIds, [AllowNull()] $FirstCount = $null, [AllowNull()] $RepeatCount = $null)
	$haveSets = ($null -ne $FirstRecordIds) -and ($null -ne $RepeatRecordIds)
	if ($haveSets) {
		$first = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::Ordinal)
		foreach ($id in @($FirstRecordIds)) { if ($null -ne $id) { [void]$first.Add([string]$id) } }
		$repeat = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::Ordinal)
		foreach ($id in @($RepeatRecordIds)) { if ($null -ne $id) { [void]$repeat.Add([string]$id) } }
		$missing = 0; foreach ($id in $first) { if (-not $repeat.Contains($id)) { $missing++ } }
		$extra = 0; foreach ($id in $repeat) { if (-not $first.Contains($id)) { $extra++ } }
		$consistent = ($missing -eq 0 -and $extra -eq 0)
		return [pscustomobject]@{ Consistent = $consistent; Verdict = $(if ($consistent) { 'Stable' } else { 'Unstable' }); FirstCount = $first.Count; RepeatCount = $repeat.Count; MissingFromRepeat = $missing; ExtraInRepeat = $extra; Basis = 'Set' }
	}
	$fc = if ($null -ne $FirstCount) { [int]$FirstCount } else { -1 }
	$rc = if ($null -ne $RepeatCount) { [int]$RepeatCount } else { -1 }
	$consistent = ($fc -ge 0 -and $rc -ge 0 -and $fc -eq $rc)
	return [pscustomobject]@{ Consistent = $consistent; Verdict = $(if ($consistent) { 'Stable' } else { 'Unstable' }); FirstCount = $fc; RepeatCount = $rc; MissingFromRepeat = $(if ($fc -gt $rc) { $fc - $rc } else { 0 }); ExtraInRepeat = $(if ($rc -gt $fc) { $rc - $fc } else { 0 }); Basis = 'Count' }
}

function script:Get-PartitionStabilityRecordIds {
	<#
	.SYNOPSIS
		FIRST-pass RecordId source for -VerifyPartitionStability's bounded repeat check. Materializes
		the partition's original-fetch RecordIds from the run's persisted incremental JSONL (a disk
		read of what the first fetch already wrote - NOT a new service query). The REPEAT pass is NO
		LONGER a re-page of the partition's (now-DELETED) Graph audit QueryId; it is an INDEPENDENT
		create->poll->page->delete query for the same window handled by
		Invoke-PartitionStabilityRepeatQuery. Returns a [string[]] of RecordIds (identity resolved via
		the codebase's RecordId/Identity/Id fallback), never the raw records, so no full set is kept.
	.OUTPUTS
		[string[]] RecordIds (possibly empty).
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)] $PartitionStatus, [bool] $IsRepeat)
	$resolveId = { param($r) if ($null -eq $r) { return $null }; if ($r.RecordId) { return [string]$r.RecordId }; if ($r.Identity) { return [string]$r.Identity }; if ($r.Id) { return [string]$r.Id }; return $null }
	$ids = [System.Collections.Generic.List[string]]::new()
	# This helper is FIRST-pass only. The independent repeat query lives in
	# Invoke-PartitionStabilityRepeatQuery; $IsRepeat is retained only for the injectable -Fetcher
	# shape and, if ever passed, still returns the persisted first-fetch set (never a QueryId re-page).
	# FIRST pass: read the partition's persisted first-fetch JSONL (the data the first fetch wrote).
	try {
		if ($script:PartialOutputPath) {
			$incDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) '.pax_incremental'
			if (Test-Path -LiteralPath $incDir) {
				$pat = "Part$($PartitionStatus.Partition.Index)_$($global:ScriptRunTimestamp)_*.jsonl"
				foreach ($f in @(Get-ChildItem -LiteralPath $incDir -Filter $pat -File -ErrorAction SilentlyContinue)) {
					foreach ($line in [System.IO.File]::ReadLines($f.FullName)) {
						if ([string]::IsNullOrWhiteSpace($line)) { continue }
						try { $rec = $line | ConvertFrom-Json -ErrorAction Stop; $v = & $resolveId $rec; if ($v) { [void]$ids.Add($v) } } catch {}
					}
				}
			}
		}
	} catch {}
	return ,([string[]]$ids.ToArray())
}

function script:Invoke-PartitionStabilityRepeatQuery {
	<#
	.SYNOPSIS
		REPEAT-pass executor for -VerifyPartitionStability. Runs ONE bounded, INDEPENDENT audit query
		for a completed partition's EXACT window + operation/recordType/service filters (a NEW QueryId,
		never a re-page of the partition's already-DELETED first-fetch QueryId) so it can detect the
		CROSS-QUERY under-delivery a re-page can never see (observed live: a fresh query for the same
		window returned a very different count). Flow: create -> bounded poll to 'succeeded' -> page the
		complete record set -> best-effort DELETE the repeat query. Any create / poll (failed|cancelled|
		timeout) / paging failure yields Outcome='Failed' (the caller treats that as Unstable/Unknown ->
		exit 40); cleanup is housekeeping and cannot invalidate a completed comparison. Returns only compact
		RecordId strings (identity resolved via the RecordId/Identity/Id fallback), never raw records.
	.OUTPUTS
		[pscustomobject] RecordIds([string[]]), Outcome('Complete'|'Failed'), FailureStage,
		RepeatQueryId, CleanupSucceeded.
	.PARAMETER CreateOp
		Injectable create op ($DisplayName,$StartDate,$EndDate,$Operations,$RecordTypes,$ServiceTypes)
		-> new queryId or $null. Defaults to the real Invoke-GraphAuditQuery (main-thread Graph wrapper).
	.PARAMETER StatusOp
		Injectable status op ($QueryId) -> @{Status;RecordCount}. Defaults to Get-GraphAuditQueryStatus.
	.PARAMETER RecordsOp
		Injectable records op ($QueryId) -> record objects. Defaults to Get-GraphAuditRecords.
	.PARAMETER DeleteOp
		Injectable delete op ($QueryId) -> void. Defaults to the real Graph queries/$id DELETE.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] $PartitionStatus,
		[AllowNull()][string[]] $TargetUsers = $null,
		[scriptblock] $CreateOp = $null,
		[scriptblock] $StatusOp = $null,
		[scriptblock] $RecordsOp = $null,
		[scriptblock] $DeleteOp = $null,
		[int] $MaxPollAttempts = 960,
		[int] $PollIntervalSeconds = 15
	)
	if ($null -eq $CreateOp)  { $CreateOp  = { param($dn, $sd, $ed, $ops, $rt, $svc) Invoke-GraphAuditQuery -DisplayName $dn -StartDate $sd -EndDate $ed -Operations $ops -RecordTypes $rt -ServiceTypes $svc } }
	if ($null -eq $StatusOp)  { $StatusOp  = { param($qid) Get-GraphAuditQueryStatus -QueryId $qid } }
	if ($null -eq $RecordsOp) { $RecordsOp = { param($qid) Get-GraphAuditRecords -QueryId $qid } }
	if ($null -eq $DeleteOp)  { $DeleteOp  = { param($qid) Invoke-MgGraphRequest -Method DELETE -Uri (Get-GraphAuditApiUri -Path "queries/$qid") -ErrorAction Stop | Out-Null } }
	$resolveId = { param($r) if ($null -eq $r) { return $null }; if ($r.RecordId) { return [string]$r.RecordId }; if ($r.Identity) { return [string]$r.Identity }; if ($r.Id) { return [string]$r.Id }; return $null }
	$fail = { param($stage, $qid) [pscustomobject]@{ RecordIds = [string[]]@(); Outcome = 'Failed'; FailureStage = $stage; RepeatQueryId = $qid; CleanupSucceeded = $false } }
	$pt = $PartitionStatus.Partition
	if ($null -eq $pt) { return (& $fail 'Create' $null) }
	# Build the repeat create payload from the partition's OWN window + filters (exact parity, so a
	# test can capture and assert the create args equal the original partition's window/filters).
	$ops = if ($pt.Activities) { @($pt.Activities) } elseif ($pt.Activity) { @($pt.Activity) } else { @() }
	$svc = $null; if ($pt.ServiceFilter) { $svc = @($pt.ServiceFilter) }
	$rt  = $null; if ($pt.RecordTypes)   { $rt  = @($pt.RecordTypes) }
	$dn  = "PAX_StabilityRepeat_P$($pt.Index)of$($pt.Total)_$([DateTime]::UtcNow.ToString('yyyyMMddHHmmss'))"
	# CREATE an independent NEW query (never reuse / re-page $PartitionStatus.QueryId).
	$repeatId = $null
	try { $repeatId = & $CreateOp $dn $pt.PStart $pt.PEnd $ops $rt $svc } catch { return (& $fail 'Create' $null) }
	if (-not $repeatId) { return (& $fail 'Create' $null) }
	# POLL to 'succeeded' - bounded (finite attempts, NOT unbounded).
	$succeeded = $false
	for ($a = 0; $a -lt $MaxPollAttempts; $a++) {
		$st = $null
		try { $st = & $StatusOp $repeatId } catch { try { & $DeleteOp $repeatId } catch {}; return (& $fail 'Poll' $repeatId) }
		$state = if ($st) { [string]$st.Status } else { $null }
		if ($state -eq 'succeeded') { $succeeded = $true; break }
		if ($state -in @('failed', 'cancelled')) { try { & $DeleteOp $repeatId } catch {}; return (& $fail 'Poll' $repeatId) }
		if ($PollIntervalSeconds -gt 0) { Start-Sleep -Seconds $PollIntervalSeconds }
	}
	if (-not $succeeded) { try { & $DeleteOp $repeatId } catch {}; return (& $fail 'Timeout' $repeatId) }
	# PAGE the complete record set, resolving compact RecordId strings (never retain raw records).
	$ids = [System.Collections.Generic.List[string]]::new()
	try { foreach ($r in @(& $RecordsOp $repeatId)) { if ($TargetUsers -and $TargetUsers.Count -gt 0) { $__upn = if ($null -ne $r) { [string]$r.userPrincipalName } else { $null }; if (-not ($TargetUsers -contains $__upn)) { continue } } $v = & $resolveId $r; if ($v) { [void]$ids.Add($v) } } }
	catch { try { & $DeleteOp $repeatId } catch {}; return (& $fail 'Page' $repeatId) }
	# DELETE is best-effort housekeeping after retrieval has completed. A delete failure does not
	# change the retrieved RecordId set or invalidate the comparison.
	$deleteOk = $true
	try { & $DeleteOp $repeatId } catch { $deleteOk = $false }
	return [pscustomobject]@{ RecordIds = [string[]]$ids.ToArray(); Outcome = 'Complete'; FailureStage = $null; RepeatQueryId = $repeatId; CleanupSucceeded = $deleteOk }
}

function script:Invoke-PartitionStabilityVerification {
	<#
	.SYNOPSIS
		Bounded, opt-in repeat-fetch stability verification for completed audit partitions
		(-VerifyPartitionStability). For each 'Complete' partition it captures the first-fetch
		RecordId set (.RecordIds) and runs EXACTLY ONE independent repeat fetch of the same partition
		window (.StabilityRepeatIds), then classifies the repeat via Test-AuditPartitionConsistency.
		Any 'Unstable' verdict (any RecordId-set difference - missing OR extra) is treated as a gap:
		$script:HadTerminalFailures is set (exit 40) - never silently certified, never blind-accept
		-larger, never unioned, never count-only (Set basis). Memory is bounded: RecordId sets are
		materialized per-partition inside the loop and ONLY when enabled - default OFF performs no
		repeat fetch and retains nothing (byte-identical to a run without the switch).
	.PARAMETER Fetcher
		Injectable FIRST-pass RecordId source scriptblock ($PartitionStatus, [bool]$IsRepeat) ->
		[string[]] of RecordIds. Defaults to Get-PartitionStabilityRecordIds (persisted-JSONL first
		pass only). Injected by tests to model the first-fetch persisted set.
	.PARAMETER RepeatExecutor
		Injectable REPEAT-pass executor scriptblock ($PartitionStatus) -> { RecordIds=[string[]];
		Outcome='Complete'|'Failed'; FailureStage; RepeatQueryId }. Defaults to
		Invoke-PartitionStabilityRepeatQuery (one independent create->poll->page->delete query for the
		SAME window/filters, a NEW QueryId). Injected by tests to model the repeat query without a
		live tenant.
	#>
	[CmdletBinding()]
	param(
		[AllowNull()] $CompletedPartitions,
		[AllowNull()][string[]] $TargetUsers = $null,
		[scriptblock] $Fetcher = $null,
		[scriptblock] $RepeatExecutor = $null,
		[switch] $Enabled
	)
	# Default OFF: no repeat query, no RecordId retention -> byte-identical to a run without the switch.
	if (-not $Enabled) { return }
	if ($null -eq $CompletedPartitions) { return }
	if ($null -eq $Fetcher) { $Fetcher = ${function:script:Get-PartitionStabilityRecordIds} }
	if ($null -eq $RepeatExecutor) { $RepeatExecutor = ${function:script:Invoke-PartitionStabilityRepeatQuery} }
	foreach ($__ps in @($CompletedPartitions)) {
		if ($null -eq $__ps) { continue }
		$__pt = $__ps.Partition
		# FIRST set: original-fetch RecordIds (a disk read of the first fetch's persisted output, not a
		# new service query). Retained only now (switch ON) and only one partition at a time (bounded).
		$__ps.RecordIds = @(& $Fetcher $__ps $false)
		# REPEAT set: exactly ONE bounded INDEPENDENT query (a NEW QueryId) for the SAME window/filters
		# via create->poll->page->delete. This detects the CROSS-QUERY under-delivery that a re-page of
		# the (already-deleted) first-fetch QueryId never could.
		$__rep = & $RepeatExecutor $__ps $TargetUsers
		if ($null -eq $__rep -or $__rep.Outcome -ne 'Complete') {
			# Any create/poll/page/cleanup failure => Unknown: never silently certified (gap -> exit 40).
			$script:HadTerminalFailures = $true
			$__ps.StabilityVerdict = 'Unknown'
			$__ps.StabilityFirstCount = @($__ps.RecordIds).Count
			$__ps.StabilityRepeatCount = -1
			$__ps.StabilityMissing = -1
			$__ps.StabilityExtra = -1
			$__stage = if ($__rep) { [string]$__rep.FailureStage } else { 'Executor' }
			Write-LogHost ("  [STABILITY] Partition {0}/{1} NOT CERTIFIED - independent repeat query failed at stage '{2}'; treated as a gap (exit 40)." -f $__pt.Index, $__pt.Total, $__stage) -ForegroundColor Red
			# Bounded memory: drop RecordId arrays immediately; keep only compact verdict metadata.
			$__ps.RecordIds = $null
			$__ps.StabilityRepeatIds = $null
			continue
		}
		$__ps.StabilityRepeatIds = @($__rep.RecordIds)
		# Classify via the pure detector (Set basis: never blind-larger, never union, never count-only).
		$__cons = script:Test-AuditPartitionConsistency -FirstRecordIds $__ps.RecordIds -RepeatRecordIds $__ps.StabilityRepeatIds
		# Retain ONLY compact verdict/count metadata (no RecordId arrays held across partitions).
		$__ps.StabilityVerdict = $__cons.Verdict
		$__ps.StabilityFirstCount = $__cons.FirstCount
		$__ps.StabilityRepeatCount = $__cons.RepeatCount
		$__ps.StabilityMissing = $__cons.MissingFromRepeat
		$__ps.StabilityExtra = $__cons.ExtraInRepeat
		if (-not $__cons.Consistent) {
			$script:HadTerminalFailures = $true
			Write-LogHost ("  [STABILITY] Partition {0}/{1} UNSTABLE on independent repeat verification: {2} RecordId(s) missing, {3} extra (first={4}, repeat={5}); NOT silently certified (gap -> exit 40)." -f $__pt.Index, $__pt.Total, $__cons.MissingFromRepeat, $__cons.ExtraInRepeat, $__cons.FirstCount, $__cons.RepeatCount) -ForegroundColor Red
		}
		# Bounded memory: drop RecordId arrays immediately after the verdict; keep only compact metadata.
		$__ps.RecordIds = $null
		$__ps.StabilityRepeatIds = $null
	}
}

function Get-DataTypeForOutputFile {
	# Map a customer-visible artifact basename to its data-type key. Used by the
	# upload sweep to route each file to its per-data-type destination (-OutputPath*).
	# Returns one of: 'Purview' | 'UserInfo' | 'Agent365Info' | 'DefenderUsage' | 'Log'.
	# The twelve fixed-name AISID dashboard leaves (ai_activity_sessions.csv,
	# ai_offhours_geo.csv, ai_file_proximity.csv, ai_oauth_consents.csv,
	# ai_sso_signins.csv, ai_client_channel.csv, ai_copilot_usage_graph.csv,
	# ai_solutions_catalog.csv, EntraUsers.csv) route to 'DefenderUsage' — matched
	# against the authoritative $script:AISIDTableSchemas fixed-name set BEFORE the
	# UserInfo pattern so the AISID EntraUsers.csv projection can never be misrouted
	# to UserInfo (the timestamped '<stem>_Users.csv' stream) or fall through to
	# Purview. The internal '.aisid_cache' delta-cache directory (and any file under
	# it) is a working area, never a dashboard artifact, so it is excluded from
	# DefenderUsage and treated as a non-dashboard Purview fallback.
	# Unknown / unmatched names fall back to 'Purview' (primary audit destination).
	[CmdletBinding()]
	param([Parameter(Mandatory)] [string] $FileName)
	$n = [System.IO.Path]::GetFileName($FileName)
	# The '.aisid_cache' delta-cache is internal scratch, never a dashboard artifact —
	# exclude any path segment named '.aisid_cache' from every dashboard classification.
	if (($FileName -replace '\\', '/') -match '(^|/)\.aisid_cache(/|$)') { return 'Purview' }
	# AISID dashboard leaves -> DefenderUsage (authoritative fixed-name set kept in
	# sync with $script:AISIDTableSchemas), checked BEFORE UserInfo so EntraUsers.csv
	# routes to DefenderUsage, never UserInfo/Purview.
	$aisidLeaves = @()
	if ($script:AISIDTableSchemas) { $aisidLeaves = @($script:AISIDTableSchemas.Values | ForEach-Object { $_.FileName }) }
	if ($aisidLeaves -notcontains 'EntraUsers.csv') { $aisidLeaves += 'EntraUsers.csv' }
	foreach ($aisidLeaf in $aisidLeaves) { if ($aisidLeaf -and $n -ieq $aisidLeaf) { return 'DefenderUsage' } }
	if ($n -like 'EntraUsers_*' -or $n -like '*_Users.csv' -or $n -like '*_Users_*.csv') { return 'UserInfo' }
	if ($n -like 'Agent365_*' -or $n -like 'Agent365.csv')                                { return 'Agent365Info' }
	if ($n -like '*.log' -or $n -like '*.partial.log')                                    { return 'Log' }
	return 'Purview'
}

function Invoke-OutputUpload {
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $LocalPath,
		# Optional per-data-type parent URL. When supplied, the upload targets this
		# URL instead of the script-wide Purview destination. Used to honor
		# -OutputPathUserInfo / -OutputPathAgent365Info / -OutputPathLog routing.
		[string] $ParentOverride
	)
	if ($script:RemoteOutputMode -eq 'None') { return }
	if (-not (Test-Path -LiteralPath $LocalPath)) {
		Write-Verbose "Invoke-OutputUpload: skipping (file not found): $LocalPath"
		return
	}
	# NOTE: No catch wrapper here — every caller either (a) has its own try/catch with a
	# context-specific WARNING (upload sweep / metrics / log file) or (b) wants silent
	# best-effort behavior with Write-Verbose only (checkpoint mirror). An inner WARNING
	# would always be either redundant or unwanted. Let exceptions propagate untouched.
	switch ($script:RemoteOutputMode) {
		'SharePoint' { Send-FileToSharePoint -LocalPath $LocalPath -ParentOverride $ParentOverride }
		'Fabric'     { Send-FileToOneLake    -LocalPath $LocalPath -ParentOverride $ParentOverride }
	}
}

function Invoke-EmbeddedProcessor {
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [ValidateSet('CopilotInteraction', 'M365Bundle')]
		[string] $ProcessorMode,

		[Parameter(Mandatory)] [string]   $PythonExe,
		[Parameter(Mandatory)] [AllowEmptyCollection()] [string[]] $LauncherArgs,
		[Parameter(Mandatory)] [string[]] $ProcessorArgs,
		[Parameter(Mandatory)] [string]   $IncrementalDir
	)

	# Materialize the appropriate embedded source as a temp .py inside .pax_incremental,
	# named with the global run timestamp so it is auto-reaped by the end-of-run cleanup
	# AND the finally-block safety-net even if we crash. Returns the processor's exit code.

	if (-not (Test-Path -LiteralPath $IncrementalDir -PathType Container)) {
		New-Item -ItemType Directory -Path $IncrementalDir -Force | Out-Null
	}

	switch ($ProcessorMode) {
		'CopilotInteraction' {
			$label  = 'CopilotInteractionProcessor'
			$source = $Script:EMBEDDED_PROCESSOR_COPILOT
			$ver    = $Script:EMBEDDED_PROCESSOR_COPILOT_VERSION
		}
		'M365Bundle' {
			$label  = 'M365BundleProcessor'
			$source = $Script:EMBEDDED_PROCESSOR_M365
			$ver    = $Script:EMBEDDED_PROCESSOR_M365_VERSION
		}
	}

	$tempPyName = "PAX_${label}_$($global:ScriptRunTimestamp).py"
	$tempPyPath = Join-Path $IncrementalDir $tempPyName

	$utf8NoBom = [Text.UTF8Encoding]::new($false)
	[IO.File]::WriteAllText($tempPyPath, $source, $utf8NoBom)

	Write-LogHost "Rollup: invoking embedded $label v$ver ($PythonExe)" -ForegroundColor Cyan
	Write-LogFile "Rollup: temp script -> $tempPyPath"
	Write-LogFile "Rollup: args        -> $($ProcessorArgs -join ' ')"
	# Additive memory/stage observation at the processor boundary (never fatal).
	try { Write-PaxMemoryObservation -Stage ("EmbeddedProcessor:" + $label) -TempDir $IncrementalDir -Force } catch {}

	$exitCode = 1
	# Force UTF-8 across the Python subprocess boundary so Unicode glyphs the
	# processor emits to stdout / stderr (right-arrow, section separators,
	# bullets) are not mojibaked when captured through PowerShell on hosts
	# whose console output encoding defaults to a legacy OEM code page.
	# Both sides matter:
	#   * [Console]::OutputEncoding controls how PowerShell decodes the bytes
	#     it reads back from the subprocess.
	#   * $env:PYTHONIOENCODING tells the Python interpreter what to encode
	#     its stdout / stderr text streams as.
	# Outer values are captured here and restored in the finally block so the
	# host's session-wide encoding is not perturbed.
	$prevConsoleOutEnc = [Console]::OutputEncoding
	$prevPyIoEnc       = $env:PYTHONIOENCODING
	try {
		[Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
		$env:PYTHONIOENCODING     = 'utf-8'
		$fullArgs = @($LauncherArgs) + @($tempPyPath) + @($ProcessorArgs)
		# In remote-output mode, suppress the Python processors' echoed input/output PATH
		# lines (e.g. "Purview input:", "Output file:"). Those values are LOCAL scratch
		# paths; surfacing them to the customer when a remote -OutputPath* is
		# in effect is misleading. The remote-aware path summary is emitted by the
		# PowerShell wrapper after the processor returns. All other Python output
		# (header, counts, timing, errors) is preserved verbatim.
		$pathLineRegex = if ($script:RemoteOutputMode -ne 'None') {
			'^\s*(Purview input:|Entra input:|Purview output:|Entra output:|Input:|Output:|Output file:)\s'
		} else { $null }
		& $PythonExe @fullArgs 2>&1 | ForEach-Object {
			$line = [string]$_
			if ($pathLineRegex -and $line -match $pathLineRegex) { return }
			# Stream stdout+stderr through Write-Log (which mirrors to host AND log file).
			Write-Log $line
		}
		$exitCode = $LASTEXITCODE
	}
	catch {
		Write-LogHost "Rollup: $label threw an exception: $($_.Exception.Message)" -ForegroundColor Red
		$exitCode = 1
	}
	finally {
		# Restore the outer console output encoding and PYTHONIOENCODING regardless
		# of outcome so subsequent host writes (and any later subprocess) see the
		# same environment they would have without this call.
		try { [Console]::OutputEncoding = $prevConsoleOutEnc } catch { }
		if ($null -eq $prevPyIoEnc) {
			Remove-Item Env:PYTHONIOENCODING -ErrorAction SilentlyContinue
		} else {
			$env:PYTHONIOENCODING = $prevPyIoEnc
		}
		try {
			if (Test-Path -LiteralPath $tempPyPath) { Remove-Item -LiteralPath $tempPyPath -Force -ErrorAction SilentlyContinue }
		}
		catch { }
	}

	return $exitCode
}

# Validate MaxConcurrency range (Microsoft Purview enforces 10 concurrent search job limit per user account)
# ============================================================================
# APPENDFILE COLUMN VALIDATION FUNCTIONS
# ============================================================================
# Early validation to prevent wasting time on Graph API queries when explosion
# parameters don't match between existing file and new data parameters.
# Note: For explosion modes, actual column schemas are dynamic and vary by data,
# so we validate explosion parameter compatibility rather than exact columns.
# ============================================================================

function Get-LikelyExplosionParams {
	param([string[]]$Columns)
	
	# Check for deep explosion indicators (CopilotEventData.* columns)
	$hasDeepColumns = $Columns | Where-Object { $_ -match '^CopilotEventData\.' }
	if ($hasDeepColumns) {
		return @{ Mode = "ExplodeDeep"; DisplayName = "-ExplodeDeep" }
	}
	
	# Check for array explosion indicators (exploded field names like Message_, Context_, AgentId, etc.)
	$hasArrayColumns = $Columns | Where-Object { $_ -match '^(Message_|Context_|Interaction_|AgentId|AgentName|AgentVersion|AccessedResource_|AISystemPlugin_)' }
	if ($hasArrayColumns) {
		return @{ Mode = "ExplodeArrays"; DisplayName = "-ExplodeArrays" }
	}
	
	# Check for standard mode indicators (AuditData JSON column present)
	$hasAuditData = $Columns -contains 'AuditData'
	if ($hasAuditData) {
		return @{ Mode = "Standard"; DisplayName = "Standard (no explosion)" }
	}
	
	# Unable to determine
	return @{ Mode = "Unknown"; DisplayName = "Unknown mode" }
}

function Get-AppendFileRecordIds {
	<#
	.SYNOPSIS
		Stream the RecordId column from an existing AppendFile (CSV or XLSX) into a HashSet.

	.DESCRIPTION
		Cross-run dedup helper for -AppendFile. Reads only the RecordId column from the
		existing target file and returns a HashSet[string] of identifiers. Used to seed
		Merge-IncrementalSaves-Streaming's -ExcludeRecordIds parameter so this run skips
		records already present in the target.

		CSV path: streams via StreamReader + manual header parse — never loads the entire
		file into memory (the target may be hundreds of MB).
		Excel path: uses Import-Excel (RecordId column only). The Excel branch is bounded
		by ImportExcel's own behavior; very large workbooks should use CSV.

	.PARAMETER Path
		Path to the AppendFile. Missing file returns an empty set (first-run semantic).

	.OUTPUTS
		HashSet[string] of RecordIds (empty when the file or column is absent).
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $Path
	)
	$set = New-Object System.Collections.Generic.HashSet[string]
	if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return ,$set }

	$ext = [System.IO.Path]::GetExtension($Path).ToLowerInvariant()
	if ($ext -eq '.xlsx') {
		try {
			if (-not (Get-Module -Name ImportExcel -ListAvailable)) { return ,$set }
			Import-Module ImportExcel -ErrorAction Stop
			$rows = Import-Excel -Path $Path -ErrorAction Stop
			foreach ($r in $rows) {
				$rid = $r.RecordId
				if ($rid -and -not [string]::IsNullOrWhiteSpace([string]$rid)) {
					[void]$set.Add([string]$rid)
				}
			}
		} catch {
			Write-LogHost "Get-AppendFileRecordIds: failed to read '$Path': $($_.Exception.Message). Cross-run dedup disabled for this file." -ForegroundColor Yellow
		}
		return ,$set
	}

	# CSV path — manual streaming for memory safety on large files.
	try {
		$reader = [System.IO.StreamReader]::new($Path, [System.Text.Encoding]::UTF8)
		try {
			$header = $reader.ReadLine()
			if (-not $header) { return ,$set }
			$cols = $header.Split(',') | ForEach-Object { $_.Trim('"') }
			$ridIdx = -1
			for ($i = 0; $i -lt $cols.Count; $i++) {
				if ($cols[$i] -ieq 'RecordId') { $ridIdx = $i; break }
			}
			if ($ridIdx -lt 0) { return ,$set }
			$line = $null
			while ($null -ne ($line = $reader.ReadLine())) {
				if ([string]::IsNullOrWhiteSpace($line)) { continue }
				# Simple field split; AppendFiles use Export-Csv quoting so RecordId (a GUID)
				# never contains commas or quotes. Fall back to ConvertFrom-Csv for the rare
				# row that has embedded commas before the RecordId column.
				$fields = $line.Split(',')
				if ($fields.Count -gt $ridIdx) {
					$raw = $fields[$ridIdx].Trim('"').Trim()
					if ($raw) { [void]$set.Add($raw) }
				}
			}
		} finally {
			$reader.Dispose()
		}
	} catch {
		Write-LogHost "Get-AppendFileRecordIds: failed to read '$Path': $($_.Exception.Message). Cross-run dedup disabled for this file." -ForegroundColor Yellow
	}
	return ,$set
}

function Test-AppendFileCompatibility {
	param(
		[string]$FilePath,
		[bool]$IsExcel,
		[bool]$ExplodeArrays,
		[bool]$ExplodeDeep,
		[string]$TargetSheet = $null
	)
	
	$result = @{
		Compatible = $true
		ExistingMode = $null
		CurrentMode = $null
		ExistingColumns = @()
		ExistingCount = 0
		ErrorMessage = $null
	}
	
	try {
		# Determine current explosion mode
		if ($ExplodeDeep) {
			$result.CurrentMode = @{ Mode = "ExplodeDeep"; DisplayName = "-ExplodeDeep" }
		}
		elseif ($ExplodeArrays) {
			$result.CurrentMode = @{ Mode = "ExplodeArrays"; DisplayName = "-ExplodeArrays" }
		}
		else {
			$result.CurrentMode = @{ Mode = "Standard"; DisplayName = "Standard (no explosion)" }
		}
		
		# Read existing file columns
		if ($IsExcel) {
			# Validate Excel file and read columns
			if (-not (Get-Module -Name ImportExcel -ListAvailable)) {
				$result.ErrorMessage = "ImportExcel module not available for validation"
				$result.Compatible = $false
				return $result
			}
			
			Import-Module ImportExcel -ErrorAction Stop
			
			# Get sheet info
			$sheets = Get-ExcelSheetInfo -Path $FilePath -ErrorAction Stop
			
			if ($TargetSheet) {
				# Validate specific sheet
				$sheet = $sheets | Where-Object { $_.Name -eq $TargetSheet }
				if (-not $sheet) {
					$result.ErrorMessage = "Target sheet '$TargetSheet' not found in workbook"
					$result.Compatible = $false
					return $result
				}
			}
			else {
				# Use first sheet
				$sheet = $sheets | Select-Object -First 1
			}
			
			# Read header row from Excel
			$headerData = Import-Excel -Path $FilePath -WorksheetName $sheet.Name -StartRow 1 -EndRow 1 -NoHeader -ErrorAction Stop
			$existingCols = $headerData[0].PSObject.Properties.Value | Where-Object { $_ }
		}
		else {
			# CSV: Read first line (header)
			$firstLine = Get-Content -Path $FilePath -First 1 -Encoding UTF8 -ErrorAction Stop
			$existingCols = ($firstLine -split ',') | ForEach-Object { $_.Trim('"') }
		}
		
		$result.ExistingColumns = $existingCols
		$result.ExistingCount = $existingCols.Count
		
		# Detect explosion mode of existing file
		$result.ExistingMode = Get-LikelyExplosionParams -Columns $existingCols
		
		# Check if explosion modes match
		if ($result.ExistingMode.Mode -ne $result.CurrentMode.Mode) {
			$result.Compatible = $false
			$result.ErrorMessage = "Explosion parameter mismatch: existing file is '$($result.ExistingMode.DisplayName)' but current command uses '$($result.CurrentMode.DisplayName)'"
		}
		else {
			# Modes match - compatible
			# Note: We don't validate exact columns because explosion schemas are dynamic
			# and vary based on actual data content. As long as explosion params match,
			# the append will work correctly.
			$result.Compatible = $true
		}
	}
	catch {
		$result.ErrorMessage = $_.Exception.Message
		$result.Compatible = $false
	}
	
	return $result
}

# ============================================================================
# END APPENDFILE VALIDATION FUNCTIONS
# ============================================================================

if ($MaxConcurrency -lt 1 -or $MaxConcurrency -gt 10) {
	Write-Host "ERROR: -MaxConcurrency must be between 1 and 10." -ForegroundColor Red
	Write-Host "Microsoft Purview enforces a maximum of 10 concurrent search jobs per user account." -ForegroundColor Yellow
	Write-Host "Current value: $MaxConcurrency" -ForegroundColor Yellow
	Write-Host "Please specify a value between 1 and 10 and re-run." -ForegroundColor Yellow
	exit 1
}

# Establish date defaults / validation depending on mode.
if ($RAWInputCSV) {
	$parsedStart = $null; $parsedEnd = $null
	if ($PSBoundParameters.ContainsKey('StartDate')) {
		try { $parsedStart = [datetime]::ParseExact($StartDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture) } catch { Write-Host "ERROR: StartDate must be yyyy-MM-dd if provided." -ForegroundColor Red; exit 1 }
	}
	if ($PSBoundParameters.ContainsKey('EndDate')) {
		try { $parsedEnd = [datetime]::ParseExact($EndDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture) } catch { Write-Host "ERROR: EndDate must be yyyy-MM-dd if provided." -ForegroundColor Red; exit 1 }
	}
	if ($parsedStart -and $parsedEnd -and $parsedEnd -lt $parsedStart) { Write-Host "ERROR: EndDate ($EndDate) is earlier than StartDate ($StartDate)." -ForegroundColor Red; exit 1 }
	if (-not $PSBoundParameters.ContainsKey('StartDate')) { $StartDate = '*' }
	if (-not $PSBoundParameters.ContainsKey('EndDate')) { $EndDate = '*' }
}
else {
	if (-not $PSBoundParameters.ContainsKey('StartDate') -and -not $PSBoundParameters.ContainsKey('EndDate')) {
		$yesterdayUtc = (Get-Date).ToUniversalTime().Date.AddDays(-1)
		$StartDate = $yesterdayUtc.ToString('yyyy-MM-dd')
		$EndDate = $yesterdayUtc.AddDays(1).ToString('yyyy-MM-dd')
	}
	elseif (-not $PSBoundParameters.ContainsKey('StartDate')) {
		$StartDate = '*'
		try {
			$parsedEnd = [datetime]::ParseExact($EndDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture)
		} catch { Write-Host "ERROR: EndDate must be yyyy-MM-dd format." -ForegroundColor Red; exit 1 }
	}
	elseif (-not $PSBoundParameters.ContainsKey('EndDate')) {
		$EndDate = '*'
		try {
			$parsedStart = [datetime]::ParseExact($StartDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture)
		} catch { Write-Host "ERROR: StartDate must be yyyy-MM-dd format." -ForegroundColor Red; exit 1 }
	}
	else {
		try {
			$parsedStart = [datetime]::ParseExact($StartDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture)
			$parsedEnd = [datetime]::ParseExact($EndDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture)
		}
		catch { Write-Host "ERROR: StartDate/EndDate must be in yyyy-MM-dd format." -ForegroundColor Red; exit 1 }
		if ($parsedEnd -lt $parsedStart) { Write-Host "ERROR: EndDate ($EndDate) is earlier than StartDate ($StartDate)." -ForegroundColor Red; exit 1 }
	}
}

# Client-side date-range trim boundaries — Purview's partition-based indexing can
# return records outside the requested date range (observed up to ~10 h past EndDate).
# These UTC boundaries are used after dedup to trim any out-of-range records.
# SpecifyKind(Utc) is critical: ParseExact returns Kind=Unspecified, and .ToUniversalTime()
# on Unspecified assumes LOCAL time, shifting the boundary by the machine's UTC offset.
$script:TrimStartDateUTC = if ($StartDate -ne '*') { [datetime]::SpecifyKind([datetime]::ParseExact($StartDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture), [System.DateTimeKind]::Utc) } else { $null }
$script:TrimEndDateUTC   = if ($EndDate   -ne '*') { [datetime]::SpecifyKind([datetime]::ParseExact($EndDate,   'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture), [System.DateTimeKind]::Utc) } else { $null }
$script:DateTrimCount    = 0

# ============================================================
# AISID date-window contract - fresh runs only
# ============================================================
# -Dashboard AISID requires TWO concrete date boundaries after normal defaulting: both dates omitted
# -> the [yesterday..today) UTC default (both concrete) is accepted; both supplied -> the existing
# format/order validation applies; exactly one supplied -> the other is the '*' sentinel (unbounded)
# here, which is INVALID for AISID. Reject the one-sided shape now - before authentication, checkpoint
# creation, or any customer output - with a clear both-or-neither message and no prompt. Resume runs
# restore the original run's concrete dates from the checkpoint, so this fresh-run gate is skipped
# under -Resume. Non-AISID one-sided / unbounded runs are unaffected.
if ($Dashboard -eq 'AISID' -and $null -eq $Resume) {
	if ($StartDate -eq '*' -or $EndDate -eq '*' -or $null -eq $script:TrimStartDateUTC -or $null -eq $script:TrimEndDateUTC) {
		$missingBoundary = if ($StartDate -eq '*' -and $EndDate -eq '*') { 'both StartDate and EndDate' } elseif ($StartDate -eq '*') { 'StartDate' } else { 'EndDate' }
		Write-LogHost "ERROR: -Dashboard AISID requires BOTH -StartDate and -EndDate to be concrete dates (missing: $missingBoundary)." -ForegroundColor Red
		Write-LogHost "  AISID intersects a bounded requested window with the 30-day retention window, so a one-sided (unbounded) range is not valid." -ForegroundColor Yellow
		Write-LogHost "  Supply BOTH -StartDate and -EndDate (yyyy-MM-dd), or omit BOTH to use the default [yesterday..today) UTC window." -ForegroundColor Yellow
		Write-LogHost "  No customer data files were written and no service connection or query was started." -ForegroundColor Yellow
		if ($script:LogFile) { Write-LogHost ("  Diagnostic log preserved at: {0}" -f $script:LogFile) -ForegroundColor Yellow }
		exit 1
	}
	# Freeze ONE reference instant for the whole run and resolve the requested-vs-available window once.
	$script:AISIDReferenceNowUtc = (Get-Date).ToUniversalTime()
	$script:AISIDWindow = Resolve-AISIDDateWindow -RequestedStartUtc $script:TrimStartDateUTC -RequestedEndUtc $script:TrimEndDateUTC -ReferenceNowUtc $script:AISIDReferenceNowUtc -RetentionDays (Get-AISIDEffectiveLookbackDays)
	$fmtW = 'yyyy-MM-ddTHH:mm:ssZ'
	$reqW   = ('[{0} .. {1})' -f $script:AISIDWindow.RequestedStartUtc.ToString($fmtW), $script:AISIDWindow.RequestedEndUtc.ToString($fmtW))
	$availW = ('[{0} .. {1})' -f $script:AISIDWindow.AvailableStartUtc.ToString($fmtW), $script:AISIDWindow.AvailableEndUtc.ToString($fmtW))
	$effW   = ('[{0} .. {1})' -f $script:AISIDWindow.EffectiveStartUtc.ToString($fmtW), $script:AISIDWindow.EffectiveEndUtc.ToString($fmtW))
	switch ($script:AISIDWindow.Status) {
		'NONE' {
			# No overlap between the requested window and the 30-day retention window. Stop BEFORE any
			# authentication, Purview/Entra/Defender query, licensing probe, checkpoint, rollup, or customer
			# CSV. Controlled exit; this is a date-selection decision, not a Ctrl+C / interrupt.
			Write-LogHost "AISID collection window: NONE - the requested date range does not overlap the available 30-day retention window; no collection was started." -ForegroundColor Red
			Write-LogHost ("  Requested window : {0}" -f $reqW) -ForegroundColor Yellow
			Write-LogHost ("  Available window : {0}" -f $availW) -ForegroundColor Yellow
			Write-LogHost "  Choose a -StartDate/-EndDate range that overlaps the last 30 days, then re-run." -ForegroundColor Yellow
			Write-LogHost "  No customer data files were written and no service connection or query was started." -ForegroundColor Yellow
			if ($script:LogFile) { Write-LogHost ("  Diagnostic log preserved at: {0}" -f $script:LogFile) -ForegroundColor Yellow }
			exit 1
		}
		'PARTIAL' {
			# The requested window extends beyond the 30-day retention window. Purview retains the FULL requested
			# range; the AISID data sets use ONLY the requested-intersect-available intersection. One warning, no
			# input, continue immediately.
			Write-LogHost ("WARNING: AISID collection window PARTIAL - the requested range extends beyond the 30-day retention window; AISID uses only the intersection.") -ForegroundColor Yellow
			Write-LogHost ("  Requested window : {0}" -f $reqW) -ForegroundColor Yellow
			Write-LogHost ("  Available window : {0}" -f $availW) -ForegroundColor Yellow
			Write-LogHost ("  Effective window : {0}" -f $effW) -ForegroundColor Yellow
			Write-LogHost ("  Reason           : {0}" -f $script:AISIDWindow.ClipReason) -ForegroundColor Yellow
			Write-LogHost ("  Purview retains the FULL requested range; only the AISID data sets use the intersection. No input is required; processing continues automatically.") -ForegroundColor Yellow
		}
		default {
			# FULL - the requested window is entirely within retention. No clipping, no warning.
		}
	}
}

if ($BlockHours -le 0) { Write-Host "ERROR: BlockHours must be positive." -ForegroundColor Red; exit 1 }

try { if ($PSVersionTable.PSEdition -eq 'Core' -and ($global:InformationPreference -in @('SilentlyContinue', 'Ignore'))) { $global:InformationPreference = 'Continue' } } catch {}

if ($RAWInputCSV) {
	$rawConflictParams = @('BlockHours', 'ResultSize', 'PacingMs', 'Auth', 'ParallelMode', 'MaxParallelGroups', 'MaxConcurrency', 'EnableParallel', 'GroupNames')
	$specifiedConflicts = @()
	foreach ($cp in $rawConflictParams) { if ($PSBoundParameters.ContainsKey($cp)) { $specifiedConflicts += $cp } }
	if ($specifiedConflicts.Count -gt 0) {
		Write-Host "ERROR: -RAWInputCSV cannot be combined with live query parameter(s): $($specifiedConflicts -join ', ')" -ForegroundColor Red
		Write-Host "Remove those conflicting parameters and re-run. Allowed with RAWInputCSV: StartDate, EndDate, ActivityTypes, AgentId, AgentsOnly, UserIds, OutputFile, AppendFile, explosion switches." -ForegroundColor Yellow
		Write-Host "Note: -GroupNames requires authentication and cannot be used in replay mode. Use -UserIds with explicit email addresses instead." -ForegroundColor Yellow
		exit 1
	}
}

# Validate -UseEOM compatibility with parallel processing
if ($UseEOM) {
	$parallelConflicts = @()
	
	# Check for explicit parallel mode settings
	if ($PSBoundParameters.ContainsKey('EnableParallel') -and $EnableParallel) {
		$parallelConflicts += '-EnableParallel'
	}
	
	if ($PSBoundParameters.ContainsKey('ParallelMode') -and $ParallelMode -ne 'Off') {
		$parallelConflicts += "-ParallelMode $ParallelMode"
	}
	
	if ($parallelConflicts.Count -gt 0) {
		Write-Host ""
		Write-Host "════════════════════════════════════════════════════════════════════" -ForegroundColor Red
		Write-Host "  ERROR: -UseEOM Incompatible with Parallel Processing" -ForegroundColor Red
		Write-Host "════════════════════════════════════════════════════════════════════" -ForegroundColor Red
		Write-Host ""
		Write-Host "Exchange Online Management mode (-UseEOM) only supports SERIAL processing." -ForegroundColor Yellow
		Write-Host "The Search-UnifiedAuditLog cmdlet cannot be used in parallel ThreadJobs due to" -ForegroundColor Gray
		Write-Host "implicit remoting architecture limitations in the EOM PowerShell module." -ForegroundColor Gray
		Write-Host ""
		Write-Host "CONFLICTING PARAMETERS DETECTED:" -ForegroundColor Yellow
		foreach ($conflict in $parallelConflicts) {
			Write-Host "  • $conflict" -ForegroundColor Red
		}
		Write-Host ""
		Write-Host "RESOLUTION OPTIONS:" -ForegroundColor Cyan
		Write-Host "  1. Remove -UseEOM switch to enable Graph API mode (supports parallel processing)" -ForegroundColor White
		Write-Host "  2. Remove parallel parameters and use serial-only processing with -UseEOM" -ForegroundColor White
		Write-Host "  3. Set -ParallelMode Off explicitly: -UseEOM -ParallelMode Off" -ForegroundColor White
		Write-Host ""
		Write-Host "NOTE: Graph API mode (default, no -UseEOM) supports parallel processing in PowerShell 7+." -ForegroundColor Gray
		Write-Host ""
		Write-Host "════════════════════════════════════════════════════════════════════" -ForegroundColor Red
		
		# Log to file if log initialized
		if ($script:logFile -and (Test-Path $script:logFile)) {
			$timestamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
			Add-Content -Path $script:logFile -Value "[$timestamp] ERROR: -UseEOM incompatible with parallel processing parameters: $($parallelConflicts -join ', ')"
			Add-Content -Path $script:logFile -Value "[$timestamp] Script terminated. Resolution: Remove -UseEOM or disable parallel mode."
		}
		
		exit 1
	}
	
	# Force ParallelMode Off in EOM mode even if Auto is set
	if ($ParallelMode -ne 'Off') {
		Write-Host ""
		Write-Host "NOTE: -UseEOM mode requires serial processing. Forcing -ParallelMode Off." -ForegroundColor Yellow
		Write-Host ""
		$ParallelMode = 'Off'
	}
}

$script:learnedActivityBlockSize = @{}
$script:globalLearnedBlockSize = $BlockHours
$script:subdivisionSequence = @(0.5, 0.25, 0.133333, 0.066667, 0.033333, 0.016667, 0.010417, 0.005556, 0.002778, 0.001389)  # 12h, 6h, 3.2h, 1.6h, 48m, 24m, 15m, 8m, 4m, 2m
$script:Hit10KLimit = $false
$script:Hit1MLimit = $false  # Graph API 1,000,000 record limit per query
$script:LimitTimeWindow = ""
$script:SubdividedPartitions = @{}  # Track partitions that needed subdivision (key=original range, value=count)
$script:Connected = $false

# ============================================================================
# GRAPH API SECURITY AUDIT ENDPOINT VERSION CONFIGURATION
# ============================================================================
# Manually configure these variables if Microsoft updates the API version
# PAX will try CURRENT version first, then fallback to PREVIOUS version
# ============================================================================
$script:GraphAuditApiVersion_Current  = 'v1.0'  # Try this version first
$script:GraphAuditApiVersion_Previous = 'beta'  # Fallback to this version if current unavailable
$script:GraphAuditApiVersion = $null            # Runtime-detected version (do not edit)
# ============================================================================

# Suppress PowerShell's web request progress bar (prevents "Reading web response stream" noise)
$ProgressPreference = 'SilentlyContinue'

# Telemetry tracking for Graph API parallel queries (per-slice lifecycle data)
$script:telemetryData = @()

# ============================================================================
# SHAPE CONTRACTS
# ----------------------------------------------------------------------------
# These two helpers freeze the canonical shapes of $script:metrics and of each
# entry in $script:partitionStatus. They are intentionally cheap, fail-fast,
# and called only at well-known initialization points. They do NOT police every
# mutation; their purpose is to catch a future change that introduces an
# incompatible re-init (e.g. drops a required key) at script-start time rather
# than at consumer-time hours later.
#
# If you add a new REQUIRED field to either structure, add it here so the
# contract drift is caught early.
# ============================================================================
$script:MetricsRequiredFields = @(
	'StartTime', 'QueryMs', 'ExplosionMs', 'ExportMs',
	'PagesFetched', 'TotalRecordsFetched', 'TotalStructuredRows',
	'ExplosionEvents', 'ExplosionRowsFromEvents', 'ExplosionMaxPerRecord', 'ExplosionTruncated',
	'Activities',
	'FilteringSkippedRecords', 'FilteringMissingAuditData',
	'FilteringPromptFiltered', 'FilteringParseFailures'
)
$script:PartitionStatusRequiredFields = @(
	'Partition', 'AttemptNumber', 'QueryId', 'QueryName',
	'Status', 'LastError', 'RecordCount'
)

function Assert-MetricsShape {
	<#
	.SYNOPSIS
		Fail-fast contract check for $script:metrics.
	.DESCRIPTION
		Verifies the script-scope metrics hashtable exists and contains every
		required field. Throws a single descriptive error on first mismatch so
		the failure surfaces at startup rather than via a NullReferenceException
		deep in the summary writer.
	#>
	param([hashtable]$Metrics = $script:metrics)
	if (-not $Metrics) {
		throw "Assert-MetricsShape: \$script:metrics is null. A required initialization step was skipped."
	}
	foreach ($k in $script:MetricsRequiredFields) {
		if (-not $Metrics.ContainsKey($k)) {
			throw "Assert-MetricsShape: \$script:metrics is missing required field '$k'. This indicates a structural mismatch."
		}
	}
}

function Assert-PartitionStatusEntry {
	<#
	.SYNOPSIS
		Fail-fast contract check for a single $script:partitionStatus entry.
	.DESCRIPTION
		Verifies the supplied entry contains every field required by the
		downstream STATUS display, retry logic, and summary writer. Optional
		fields (ParentPartition, SubdivisionReason) are intentionally not
		asserted.
	#>
	param(
		[Parameter(Mandatory = $true)] $Entry,
		[string]$Context = '<unspecified>'
	)
	if ($null -eq $Entry) {
		throw "Assert-PartitionStatusEntry [$Context]: entry is null."
	}
	foreach ($k in $script:PartitionStatusRequiredFields) {
		if (-not $Entry.ContainsKey($k)) {
			throw "Assert-PartitionStatusEntry [$Context]: missing required field '$k'. This indicates a structural mismatch."
		}
	}
}

# Number of consecutive same-category failures (signature = partition index +
# failure category) a partition may accumulate before it is flagged as a terminal
# failure. Count only; there is no elapsed-time component. Maintained by
# Set-PartitionFailure.
$script:MaxConsecutiveIdenticalFailures = 5

# Defensive runaway guard: the maximum number of times a single collection window
# may be subdivided by record-limit auto-subdivision. A legitimate high-volume
# window reaches well under this depth; hitting it indicates a pathological or
# spurious limit signal. A window still over the record limit at this depth is
# stopped and reported as a DISTINCT subdivision-limit state (Status
# 'SubdivisionLimit'), separate from the terminal create/fetch failure class. This
# is a depth count only — not a time limit.
$script:MaxSubdivisionLevel = 20

function Get-PartitionFailureCategory {
	<#
	.SYNOPSIS
		Maps a specific failure reason to the coarse category used for the
		terminal-detection signature.
	.DESCRIPTION
		All "the attempt failed at runtime" reasons collapse to FAILED so the SAME
		underlying failure accumulates toward terminal regardless of which
		observation site (live monitoring, reconcile, retry) reports it (a job error
		can surface as JOB_ERROR live and ERROR_STREAM at reconcile for one problem).
		AUTH (token) and SLOW (query still running) stay distinct so genuine
		transients reset the consecutive-failure streak instead of driving a false
		terminal.
	#>
	param([string]$Reason)
	switch ($Reason) {
		'401'           { 'AUTH';  break }
		'STILL_RUNNING' { 'SLOW';  break }
		default         { 'FAILED' }
	}
}

function Set-PartitionFailure {
	<#
	.SYNOPSIS
		Central sink for marking a partition Failed while tracking consecutive
		same-category failure runs.
	.DESCRIPTION
		Sets Status='Failed' (identical to the inline assignment it replaces) and,
		in addition, maintains a per-partition consecutive-failure counter keyed on a
		coarse signature of (partition index + failure category). The category
		collapses all runtime-failure reasons to FAILED (see
		Get-PartitionFailureCategory) so the same underlying failure accumulates
		regardless of which observation site reports it; AUTH and SLOW stay distinct.
		When the same category repeats $script:MaxConsecutiveIdenticalFailures times
		in a row, IsTerminalFailure is set; a differing category resets the counter
		to 1. The most-recent Stage and Reason are recorded (LastFailureStage /
		LastFailureReason) for the diagnostic terminal-failure report — they are NOT
		part of the counting signature. LastError is left to the caller (unchanged).
		The tracking fields are additive and are not consumed by any re-queue or
		retry predicate here.
	.PARAMETER Index
		Partition index key into $script:partitionStatus.
	.PARAMETER Stage
		Coarse phase where the failure was observed (e.g. CREATE, FETCH, RECONCILE).
		Recorded for the report only.
	.PARAMETER Reason
		Specific failure token (e.g. 401, EMPTY_QUERYID, JOB_FAILED). Recorded for the
		report and mapped to a category for the counting signature.
	#>
	param(
		[Parameter(Mandatory)] $Index,
		[Parameter(Mandatory)] [string]$Stage,
		[Parameter(Mandatory)] [string]$Reason
	)
	if (-not ($script:partitionStatus -and $script:partitionStatus.ContainsKey($Index))) { return }
	$entry = $script:partitionStatus[$Index]
	$category = Get-PartitionFailureCategory -Reason $Reason
	$signature = "$Index|$category"
	if ($entry.LastFailureSignature -eq $signature) {
		$entry.ConsecutiveIdenticalFailures = [int]$entry.ConsecutiveIdenticalFailures + 1
	} else {
		$entry.ConsecutiveIdenticalFailures = 1
		$entry.LastFailureSignature = $signature
	}
	$entry.LastFailureStage = $Stage
	$entry.LastFailureReason = $Reason
	# A persistent create denial permits one token-renewal retry before becoming terminal.
	$terminalThreshold = if ($Reason -eq 'PersistentForbidden') { 2 } else { $script:MaxConsecutiveIdenticalFailures }
	$entry.IsTerminalFailure = ($entry.ConsecutiveIdenticalFailures -ge $terminalThreshold)
	# Structured lifecycle category preservation: map the coarse Reason
	# to the bounded vocabulary and NEVER let a generic parent reconciliation result
	# (JOB_FAILED / ERROR_STREAM / NO_DATA / INVALID_COMPLETE) overwrite a more
	# specific worker-established category. LastError stays diagnostic-only and is
	# not consulted here. Additive: does not affect the terminal-failure counting.
	$incomingCategory = Get-GraphAuditReasonCategory -Reason $Reason
	$existingCategory = if ($entry.ContainsKey('FailureCategory') -and $null -ne $entry.FailureCategory) { [string]$entry.FailureCategory } else { 'None' }
	$entry.FailureCategory = Merge-GraphAuditLifecycleCategory -Existing $existingCategory -Incoming $incomingCategory
	$entry.Status = 'Failed'
}

function Test-TransientAuthSignal {
	<#
	.SYNOPSIS
		Returns $true only when error text carries a genuine transient-authentication
		signal (expired/invalid token), never a coincidental '401' substring.
	.DESCRIPTION
		Matches explicit auth tokens (Unauthorized, InvalidAuthenticationToken,
		token expired, authentication failed, lifetime validation failed) and the
		HTTP status 401 ONLY in a status context — "(401)", "HTTP 401", or
		"401 Unauthorized" — so a bare number such as a record count ("4013 records")
		is not mistaken for an auth failure. Fail-closed: ambiguous or empty text
		returns $false, so the failure then counts normally against the retry limit.
	#>
	param([string]$Text)
	if ([string]::IsNullOrWhiteSpace($Text)) { return $false }
	return [bool]($Text -match '(?i)(unauthorized|invalidauthenticationtoken|token(?:\s+has)?\s+expired|authentication\s+failed|lifetime\s+validation\s+failed|\(401\)|http[ /]?401\b|401\s+unauthorized)')
}

