# v6 shape-contract guard: catches accidental drops of required metrics fields
# at startup rather than at summary-writer time. See Assert-MetricsShape above.
Assert-MetricsShape

$script:summaryWritten = $false

# Streaming dataset profiler (live & replay)
$script:profiler = @{
	Rows           = 0
	Operations     = @{}
	RecordTypes    = @{}
	HasCopilot     = 0
	MaxDepth       = 0
	DepthCounts    = @{}
	MaxArrayLen    = 0
}

$script:shapeCache = @{}

function Get-RecordShapeKey {
	param([object]$AuditData)
	try {
		$rt = $AuditData.RecordType
	} catch { $rt = '' }
	try {
		$op = $AuditData.Operation
	} catch { $op = '' }
	try {
		$hasCopilot = $AuditData.PSObject.Properties['CopilotEventData'] -ne $null
	} catch { $hasCopilot = $false }
	return "$rt|$op|$hasCopilot"
}

function Get-RecordShape {
	param([object]$AuditData)
	if ($null -eq $AuditData) { return $null }
	$key = Get-RecordShapeKey $AuditData
	if ($script:shapeCache.ContainsKey($key)) { return $script:shapeCache[$key] }
	$shape = @{}
	try {
		$shape.RecordType = $AuditData.RecordType
		$shape.Operation  = $AuditData.Operation
	} catch {}
	try { $shape.HasCopilot = $AuditData.PSObject.Properties['CopilotEventData'] -ne $null } catch { $shape.HasCopilot = $false }
	try { $shape.Depth = Get-JsonDepth $AuditData 0 } catch { $shape.Depth = 0 }
	$shape.Mode = if ($shape.HasCopilot) { 'Copilot' } else { 'AuditData' }
	$script:shapeCache[$key] = $shape
	return $shape
}

function Reset-Profiler {
	$script:profiler = @{
		Rows           = 0
		Operations     = @{}
		RecordTypes    = @{}
		HasCopilot     = 0
		MaxDepth       = 0
		DepthCounts    = @{}
		MaxArrayLen    = 0
	}
}

function Get-JsonDepth([object]$node, [int]$d = 0) {
	if ($null -eq $node -or (Test-ScalarValue $node)) { return $d }
	if ($node -is [System.Collections.IDictionary]) {
		$maxd = $d
		foreach ($v in $node.Values) { $maxd = [math]::Max($maxd, (Get-JsonDepth $v ($d + 1))) }
		return $maxd
	}
	if ($node -is [System.Collections.IEnumerable] -and -not ($node -is [string])) {
		$maxd = $d
		$i = 0
		foreach ($el in $node) { $maxd = [math]::Max($maxd, (Get-JsonDepth $el ($d + 1))); $i++ }
		if ($i -gt $script:profiler.MaxArrayLen) { $script:profiler.MaxArrayLen = $i }
		return $maxd
	}
	return $d
}

function Profile-AuditData {
	param([object]$AuditData)
	if ($null -eq $AuditData) { return }
	try {
		$script:profiler.Rows++
		# Operation
		try {
			$op = $AuditData.Operation
			if (-not [string]::IsNullOrWhiteSpace($op)) {
				if (-not $script:profiler.Operations.ContainsKey($op)) { $script:profiler.Operations[$op] = 0 }
				$script:profiler.Operations[$op] += 1
			}
		} catch {}
		# RecordType
		try {
			$rt = $AuditData.RecordType
			if (-not [string]::IsNullOrWhiteSpace([string]$rt)) {
				if (-not $script:profiler.RecordTypes.ContainsKey([string]$rt)) { $script:profiler.RecordTypes[[string]$rt] = 0 }
				$script:profiler.RecordTypes[[string]$rt] += 1
			}
		} catch {}
		# CopilotEventData presence
		try { if ($AuditData.PSObject.Properties['CopilotEventData']) { $script:profiler.HasCopilot++ } } catch {}
		# Depth & arrays
		$depth = Get-JsonDepth $AuditData 0
		if ($depth -gt $script:profiler.MaxDepth) { $script:profiler.MaxDepth = $depth }
		if (-not $script:profiler.DepthCounts.ContainsKey($depth)) { $script:profiler.DepthCounts[$depth] = 0 }
		$script:profiler.DepthCounts[$depth] += 1
	} catch {}
}

function Write-ProfilerSummary {
	param([int]$TopOps = 20, [int]$TopDepths = 10)
	try {
		Write-LogHost "Profiler: Rows=$($script:profiler.Rows), MaxDepth=$($script:profiler.MaxDepth), MaxArrayLen=$($script:profiler.MaxArrayLen), HasCopilot=$($script:profiler.HasCopilot)" -ForegroundColor Gray
		if ($script:profiler.Operations.Count -gt 0) {
			Write-LogHost "Profiler: Operations (top $TopOps):" -ForegroundColor Gray
			$script:profiler.Operations.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First $TopOps | ForEach-Object { Write-LogHost "  $($_.Key): $($_.Value)" -ForegroundColor Gray }
		}
		if ($script:profiler.DepthCounts.Count -gt 0) {
			Write-LogHost "Profiler: Depth distribution (top $TopDepths):" -ForegroundColor Gray
			$script:profiler.DepthCounts.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First $TopDepths | ForEach-Object { Write-LogHost "  Depth $($_.Key): $($_.Value)" -ForegroundColor Gray }
		}
	} catch {}
}
$script:adaptiveThroughputBaseline = $null
$script:adaptiveLowLatencyStreak = 0
$script:consecutiveBlockFailures = 0
$script:circuitBreakerOpen = $false
$script:circuitBreakerOpenUntil = $null

# Finalize-time "completed with gaps" signals for the process exit code. Set true in
# the query-submission summary when the run finalizes with one or more partitions
# terminally failed (Issue 3A) or windows that hit the subdivision-depth guard
# (Issue 3B). Drive exit code 40 (lowest precedence — existing 10/20/30 dominate).
$script:HadTerminalFailures = $false
$script:HadSubdivisionLimit = $false
$script:AISIDHadGaps = $false
# Set true when requested Agent 365 catalog output is incomplete: an incomplete catalog
# listing, a package whose detail could not be retrieved, a row that could not be built, or
# a listed entry without a usable identifier. Drives exit code 40 at the same lowest
# precedence as the other completed-with-gaps signals.
$script:Agent365HadGaps = $false
# Leaves of Agent 365 recovery material written when the catalog listing did not complete.
# Recovery material is never published as a completed catalog, so both the end-of-run local
# listing and the remote upload sweep exclude these leaves (same convention as the Fact-append
# recovery leaves).
$script:Agent365RecoveryLeafs = $null
$script:AISIDCompletionStatus = $null
# D3: set true when the CopilotInteraction rollup post-processor fails (throw / nonzero exit) or does not
# produce a required deliverable (Fact / Users). Consumed ONLY under -Dashboard AISID (a requested-output
# failure -> completed-with-gaps, exit 40); non-AISID best-effort rollup exit semantics are unchanged.
$script:RollupProcessorFailed = $false

# 1C: a REQUESTED Fact-append (-AppendFile) reconciliation FAILED this run. This is a
# requested-output failure -> completed-with-gaps (exit 40, driven via HadTerminalFailures),
# and it must ALSO preserve the recovery artifacts (the unmerged current-run Fact CSV, the
# remote scratch dir, and the Fabric resume mirror) that the normal clean-run cleanup would
# otherwise delete. It is DELIBERATELY DISTINCT from AnyUploadFailed (no upload actually
# failed) so diagnostics never mislabel a local merge failure as an upload failure. The
# exact leaves registered in FactAppendRecoveryLeafs are excluded from the end-of-run upload
# sweep and the local output listing so the unmerged current-run Fact is never published as
# though it were the completed -AppendFile target (nor as a second normal Fact output).
$script:FactAppendFailed = $false
$script:FactAppendRecoveryLeafs = $null

# Advisory append-target size guardrail. When an append/merge target exceeds this
# many bytes, a non-blocking warning is emitted before the merge (which reads the
# whole target into memory to deduplicate against it). Default 1 GB; override in
# bytes via the PAX_APPEND_WARN_BYTES environment variable. The size probe itself is
# fail-open (see Get-RemoteAppendTargetSize) so it can never block or mis-handle a run.
$script:AppendTargetSizeWarnBytes = if ($env:PAX_APPEND_WARN_BYTES -and (($env:PAX_APPEND_WARN_BYTES -as [int64]) -gt 0)) { [int64]$env:PAX_APPEND_WARN_BYTES } else { 1GB }

# ==============================================
# GRAPH API VERSION DETECTION HELPER
# ==============================================
# Automatically detects and uses configured current version or falls back to previous version
# Version configuration is at top of script for easy manual updates

function Get-GraphAuditApiUri {
	<#
	.SYNOPSIS
		Builds Graph API audit endpoint URI with automatic version detection.
	
	.DESCRIPTION
		Attempts to use the configured current version first. If not available,
		falls back to the previous version. Version detection is cached per session.
		
		Configure versions at top of script:
		  $script:GraphAuditApiVersion_Current  = 'v1.0'  (try first)
		  $script:GraphAuditApiVersion_Previous = 'beta'  (fallback)
	
	.PARAMETER Path
		The audit API path (e.g., "queries", "queries/{id}", "queries/{id}/records")
	
	.OUTPUTS
		String - Full Graph API URI with appropriate version
	
	.EXAMPLE
		$uri = Get-GraphAuditApiUri -Path "queries"
		# Returns: https://graph.microsoft.com/v1.0/security/auditLog/queries
		# or:      https://graph.microsoft.com/beta/security/auditLog/queries (if v1.0 unavailable)
	#>
	param(
		[Parameter(Mandatory = $true)]
		[string]$Path
	)
	
	# Select the audit-query lifecycle version on first use (cached for session).
	#
	# A successful collection GET does NOT prove that per-item status, records,
	# pagination and cleanup all work on a given version, so it must never by
	# itself select the version used for the full query lifecycle. Field evidence
	# showed a version whose collection GET and create succeeded but whose
	# item/status and records operations returned 404 for queries that had
	# actually completed server-side, while the alternate version served the same
	# lifecycle reliably. Cross-version query-id visibility is unproven, so the
	# lifecycle is never mixed across versions within a single query.
	#
	# This release therefore pins the version with a proven end-to-end lifecycle
	# in this service ($script:GraphAuditApiVersion_Previous). The other version
	# ($script:GraphAuditApiVersion_Current) remains configured for a future
	# capability-gated path that is enabled only after a read-only cross-version
	# discriminator proves its per-operation support and cross-version visibility.
	if ($null -eq $script:GraphAuditApiVersion) {
		$script:GraphAuditApiVersion = $script:GraphAuditApiVersion_Previous
		Write-LogHost "Graph API: security/auditLog lifecycle pinned to version $($script:GraphAuditApiVersion) (proven end-to-end; collection availability alone does not select a version)" -ForegroundColor Green
	}
	
	return "https://graph.microsoft.com/$($script:GraphAuditApiVersion)/security/auditLog/$Path"
}

# ============================================================================
# GRAPH AUDIT-QUERY LIFECYCLE DECISION LAYER
# ----------------------------------------------------------------------------
# One shared, injectable decision layer for the Graph security/auditLog query
# lifecycle (create / status / records / pagination / delete). These are pure
# functions driven by STRUCTURED inputs (HTTP status codes + exception TYPE),
# never by error-message text. They are exercised directly by
# tests/Purview.GraphAuditLifecycleStateMachine.Tests.ps1 with injected HTTP
# operations, so the tested logic is the shipped logic. The same rules govern
# both the parent path and the isolated ThreadJob worker runspace.
#
# Stage-A-grounded invariants (beta is the default; v1.0 CREATION stays disabled):
#   * beta is the production default; new query CREATION always uses beta.
#   * A single endpoint/version 404 is QueryNotVisible, never QueryConfirmedAbsent.
#   * Version fallback is a same-ID GET on the alternate version only; it NEVER
#     issues a POST. Status and records are decided INDEPENDENTLY (Stage A proved
#     v1.0 status 404 while v1.0 records 200 for the same id).
#   * 401/403, 429, network, and 5xx keep existing handling with NO version
#     fallback.
#   * @odata.nextLink is followed verbatim; no $top / cap / truncation is added.
#   * A successful zero-record retrieval is Complete, never NO_DATA / JOB_FAILED.
#   * Delete uses the effective version and is best-effort; cleanup failure is
#     observable but never erases saved records or fabricates a data gap.
# ============================================================================

# Bounded failure-category vocabulary. Extending this list is a deliberate
# contract change and must be mirrored in the classifier + tests.
$script:GraphAuditFailureCategories = @(
	'None', 'EndpointUnavailable', 'QueryNotVisible', 'QueryConfirmedAbsent',
	'Authentication', 'Throttled', 'Network', 'Service', 'Cleanup', 'Other'
)
# Categories that carry a specific, worker-established meaning. A generic parent
# reconciliation result (JOB_FAILED / ERROR_STREAM / NO_DATA / INVALID_COMPLETE)
# must never overwrite one of these.
$script:GraphAuditSpecificFailureCategories = @(
	'EndpointUnavailable', 'QueryNotVisible', 'QueryConfirmedAbsent',
	'Authentication', 'Throttled', 'Network', 'Service', 'Cleanup'
)

function Get-GraphAuditFailureCategory {
	<#
	.SYNOPSIS
		Maps a structured HTTP status + exception type to the bounded lifecycle
		failure vocabulary. NEVER inspects message text.
	#>
	param(
		[Nullable[int]]$HttpStatus = $null,
		[string]$ExceptionType = $null,
		[ValidateSet('Create', 'Status', 'Records', 'Delete', 'List', '')]
		[string]$Operation = '',
		[switch]$ConfirmedAbsent
	)
	# Delete/cleanup failures are always Cleanup (best-effort; never data-erasing).
	# A 404 on delete means the query is already gone => successful cleanup (None).
	if ($Operation -eq 'Delete') {
		if ($HttpStatus -eq 404) { return 'None' }
		if (($null -ne $HttpStatus -and $HttpStatus -ge 400) -or $ExceptionType) { return 'Cleanup' }
		return 'None'
	}
	if ($null -ne $HttpStatus) {
		switch ([int]$HttpStatus) {
			401 { return 'Authentication' }
			403 { return 'Authentication' }
			429 { return 'Throttled' }
			404 { if ($ConfirmedAbsent) { return 'QueryConfirmedAbsent' } else { return 'QueryNotVisible' } }
			default {
				if ($HttpStatus -ge 500 -and $HttpStatus -le 599) { return 'Service' }
				if ($HttpStatus -ge 200 -and $HttpStatus -le 299) { return 'None' }
				return 'Other'
			}
		}
	}
	# No HTTP status: network/transport-class exceptions (by TYPE, not text).
	if ($ExceptionType) {
		$net = @('HttpRequestException', 'WebException', 'SocketException', 'TaskCanceledException', 'TimeoutException', 'IOException')
		foreach ($n in $net) { if ($ExceptionType -like "*$n*") { return 'Network' } }
		return 'Other'
	}
	return 'None'
}

function New-GraphAuditLifecycleState {
	<#
	.SYNOPSIS
		Factory for the additive per-query structured lifecycle fields. Ordered so
		checkpoint serialization is stable.
	#>
	param(
		[string]$QueryApiVersion = $null,
		[string]$LifecycleOperation = $null
	)
	return [ordered]@{
		QueryApiVersion         = $QueryApiVersion
		LifecycleOperation      = $LifecycleOperation
		FailureCategory         = 'None'
		AlternateVersionChecked = $false
		AlternateVersionResult  = $null   # 'Visible' | 'NotVisible' | $null
		QueryConfirmedAbsent    = $false
		ReplacementAttempted    = $false
		ReplacementQueryId      = $null
		LastLifecycleHttpStatus = $null
		LifecycleRetryCount     = 0
		ZeroRecordComplete      = $false
		# Durable uncertain-create state. UncertainCreate is a boolean flag; when true the
		# partition has an unproven (possibly-accepted) first create POST and must only ever
		# be resolved by READ-ONLY exact-name reconciliation, never another POST.
		# UncertainCreateInfo is a structured sub-object (Fingerprint, DisplayName, PStart,
		# PEnd, Activities, RecordTypes, ServiceFilter, FirstSeenUtc, AttemptMarker) used to
		# rebuild the exact fingerprinted name for reconciliation across attempts/resume.
		UncertainCreate         = $false
		UncertainCreateInfo     = $null
	}
}

function Set-GraphAuditLifecycleFields {
	<#
	.SYNOPSIS
		Ensures the lifecycle fields exist on a partitionStatus/checkpoint entry
		WITHOUT discarding existing values.
	.DESCRIPTION
		Legacy-safe: a missing field is added with its default; an existing field
		(including a stored QueryId elsewhere on the entry) is NEVER overwritten or
		cleared. Loading a legacy checkpoint that lacks these fields therefore can
		never discard or recreate a stored QueryId.
	#>
	param([Parameter(Mandatory)] $Entry)
	if ($null -eq $Entry) { return $Entry }
	$defaults = New-GraphAuditLifecycleState
	foreach ($k in $defaults.Keys) {
		$has = $false
		if ($Entry -is [hashtable]) { $has = $Entry.ContainsKey($k) }
		else { $has = ($null -ne $Entry.PSObject.Properties[$k]) }
		if (-not $has) {
			if ($Entry -is [hashtable]) { $Entry[$k] = $defaults[$k] }
			else { Add-Member -InputObject $Entry -NotePropertyName $k -NotePropertyValue $defaults[$k] -Force }
		}
	}
	return $Entry
}

function Merge-GraphAuditLifecycleCategory {
	<#
	.SYNOPSIS
		Reconciliation preservation: a generic parent result never overwrites a
		more specific worker-established category. Returns the category to keep.
	#>
	param([string]$Existing, [string]$Incoming)
	if ([string]::IsNullOrWhiteSpace($Existing)) { return $Incoming }
	if (($script:GraphAuditSpecificFailureCategories -contains $Existing) -and
		(-not ($script:GraphAuditSpecificFailureCategories -contains $Incoming))) {
		return $Existing
	}
	return $Incoming
}

function Get-GraphAuditReasonCategory {
	<#
	.SYNOPSIS
		Maps a coarse parent Reason token to the bounded category vocabulary.
	.DESCRIPTION
		Generic runtime reasons (JOB_FAILED / ERROR_STREAM / NO_DATA /
		INVALID_COMPLETE) collapse to 'Other' (non-specific) so they cannot mask a
		worker-established specific category. Driven by the structured token only.
	#>
	param([string]$Reason)
	switch -Regex ($Reason) {
		'^401$|^403$'                     { 'Authentication'; break }
		'^429$'                           { 'Throttled'; break }
		'^QUERY-?GONE$|^QueryNotVisible$' { 'QueryNotVisible'; break }
		'^QueryConfirmedAbsent$'          { 'QueryConfirmedAbsent'; break }
		'^Cleanup$'                       { 'Cleanup'; break }
		'^Network$'                       { 'Network'; break }
		'^Service$|^5\d\d$'               { 'Service'; break }
		default                           { 'Other' }
	}
}

function Invoke-GraphAuditLifecycleOperation {
	<#
	.SYNOPSIS
		Shared decision layer for ONE lifecycle operation (Status/Records/Delete).
	.DESCRIPTION
		Routes a single operation through: (1) call on the effective version;
		(2) on 404, bounded eventual-consistency retry on the SAME version;
		(3) then a same-ID GET on the alternate version (never a POST); (4) if the
		alternate GET succeeds, retain the id, record the result, switch the
		effective QueryApiVersion, and continue. 401/403/429/network/5xx keep their
		existing meaning with NO version fallback. Status and records are decided
		INDEPENDENTLY. The -Invoke callback isolates the HTTP transport so the same
		function is exercised by injected tests and by production callers.
	.PARAMETER Invoke
		scriptblock param($Version,$QueryId,$Operation) ->
			@{ HttpStatus=<int|null>; Data=<obj>; ExceptionType=<string|null> }
	#>
	param(
		[Parameter(Mandatory)][ValidateSet('Status', 'Records', 'Delete')] [string]$Operation,
		[Parameter(Mandatory)][string]$QueryId,
		[Parameter(Mandatory)][scriptblock]$Invoke,
		[string]$EffectiveVersion = $null,
		[string]$AlternateVersion = $null,
		[Parameter(Mandatory)] $State,
		[int]$MaxConsistencyRetries = 3,
		[bool]$EnableAlternateVersion = $true
	)
	if ([string]::IsNullOrWhiteSpace($EffectiveVersion)) { $EffectiveVersion = $script:GraphAuditApiVersion_Previous }  # legacy/unknown => beta
	if ([string]::IsNullOrWhiteSpace($AlternateVersion)) {
		$AlternateVersion = if ($EffectiveVersion -eq $script:GraphAuditApiVersion_Previous) { $script:GraphAuditApiVersion_Current } else { $script:GraphAuditApiVersion_Previous }
	}
	$State.LifecycleOperation = $Operation
	$ver = $EffectiveVersion
	$attempt = 0
	while ($true) {
		$r = & $Invoke $ver $QueryId $Operation
		$status = if ($r) { $r.HttpStatus } else { $null }
		$exType = if ($r) { $r.ExceptionType } else { $null }
		$State.LastLifecycleHttpStatus = $status
		# Success.
		if ($null -ne $status -and $status -ge 200 -and $status -le 299) {
			$State.QueryApiVersion = $ver
			$State.FailureCategory = 'None'
			$data = if ($r) { $r.Data } else { $null }
			if ($Operation -eq 'Records') {
				$count = 0
				if ($data -and $data.value) { $count = @($data.value).Count }
				if ($count -eq 0) { $State.ZeroRecordComplete = $true }
			}
			return @{ Success = $true; HttpStatus = $status; Version = $ver; Category = 'None'; Data = $data; State = $State }
		}
		# 404 => bounded eventual-consistency retry on the SAME version first.
		if ($status -eq 404) {
			if ($attempt -lt $MaxConsistencyRetries) {
				$attempt++
				$State.LifecycleRetryCount = [int]$State.LifecycleRetryCount + 1
				continue
			}
			# Delete: a 404 after retries means already-gone => successful cleanup.
			if ($Operation -eq 'Delete') {
				$State.QueryApiVersion = $ver
				$State.FailureCategory = 'None'
				return @{ Success = $true; HttpStatus = 404; Version = $ver; Category = 'None'; Data = $null; State = $State }
			}
			# Same-ID GET on the alternate version (never a POST).
			if ($EnableAlternateVersion -and $AlternateVersion -and $AlternateVersion -ne $ver) {
				$State.AlternateVersionChecked = $true
				$ra = & $Invoke $AlternateVersion $QueryId $Operation
				$as = if ($ra) { $ra.HttpStatus } else { $null }
				if ($null -ne $as -and $as -ge 200 -and $as -le 299) {
					$State.AlternateVersionResult = 'Visible'
					$State.QueryApiVersion = $AlternateVersion   # switch effective version for subsequent ops
					$State.FailureCategory = 'None'
					$State.LastLifecycleHttpStatus = $as
					$adata = if ($ra) { $ra.Data } else { $null }
					if ($Operation -eq 'Records') {
						$count = 0; if ($adata -and $adata.value) { $count = @($adata.value).Count }
						if ($count -eq 0) { $State.ZeroRecordComplete = $true }
					}
					return @{ Success = $true; HttpStatus = $as; Version = $AlternateVersion; Category = 'None'; Data = $adata; State = $State }
				}
				$State.AlternateVersionResult = 'NotVisible'
			}
			# Both versions 404 (or alternate disabled): NOT visible. Absence is NOT
			# confirmed here — confirmation additionally requires a fully-paginated
			# exact-name miss (see Resolve-GraphAuditDuplicateSafeQuery).
			$State.FailureCategory = 'QueryNotVisible'
			return @{ Success = $false; HttpStatus = 404; Version = $ver; Category = 'QueryNotVisible'; Data = $null; State = $State }
		}
		# Non-404 failures: classify and NEVER version-fallback.
		$cat = Get-GraphAuditFailureCategory -HttpStatus $status -ExceptionType $exType -Operation $Operation
		$State.FailureCategory = $cat
		return @{ Success = $false; HttpStatus = $status; Version = $ver; Category = $cat; Data = $null; State = $State }
	}
}

function Resolve-GraphAuditDuplicateSafeQuery {
	<#
	.SYNOPSIS
		Duplicate-safe creation/replacement around a deterministic exact partition
		displayName.
	.DESCRIPTION
		Rules: fully-paginated exact-name lookup (ordinal exact match) BEFORE any
		recovery POST; exactly one match => adopt (no POST); multiple exact matches
		=> fail closed (no POST); confirmed absence requires both item versions 404
		for the same id AND an exact-name miss; at most ONE replacement POST, only
		after absence is confirmed and persisted ReplacementAttempted is false
		(persisted BEFORE the POST so a resume cannot double-create); an ambiguous
		POST error is reconciled by exact-name lookup, never a blind re-POST. A
		partition with no prior id may create its initial beta query but still uses
		the exact-name + ambiguous-POST guard.
	#>
	param(
		[Parameter(Mandatory)][string]$DisplayName,
		[string]$ExistingQueryId = $null,
		[Parameter(Mandatory)] $State,
		[Parameter(Mandatory)][scriptblock]$ListQueries,   # -> array of @{ id; displayName } (fully paginated)
		[scriptblock]$CheckItem = $null,                   # param($Version,$QueryId) -> @{ HttpStatus }
		[scriptblock]$CreateQuery = $null,                 # param($Version,$DisplayName) -> @{ HttpStatus; QueryId; Ambiguous }
		[scriptblock]$PersistReplacementIntent = $null,   # param($State) -> durably persist ReplacementAttempted; fired ONCE, immediately before the sole replacement POST
		[string]$EffectiveVersion = $null,
		[string]$AlternateVersion = $null,
		[int]$MaxConsistencyRetries = 3
	)
	if ([string]::IsNullOrWhiteSpace($EffectiveVersion)) { $EffectiveVersion = $script:GraphAuditApiVersion_Previous }
	if ([string]::IsNullOrWhiteSpace($AlternateVersion)) {
		$AlternateVersion = if ($EffectiveVersion -eq $script:GraphAuditApiVersion_Previous) { $script:GraphAuditApiVersion_Current } else { $script:GraphAuditApiVersion_Previous }
	}
	$exactMatch = {
		param($items)
		@($items | Where-Object { $null -ne $_ -and [string]::Equals([string]$_.displayName, $DisplayName, [System.StringComparison]::Ordinal) })
	}
	# 1) Fully-paginated exact-name lookup (established ordinal case semantics).
	$all = @(& $ListQueries)
	$matches = @(& $exactMatch $all)
	if ($matches.Count -gt 1) {
		# Multiple exact matches => fail closed. Never choose arbitrarily; never POST.
		$State.FailureCategory = 'Other'
		return @{ Action = 'FailClosed'; Reason = 'MultipleExactMatches'; MatchCount = $matches.Count; QueryId = $null }
	}
	if ($matches.Count -eq 1) {
		# Exactly one existing exact match => adopt; no POST.
		return @{ Action = 'Adopt'; Reason = 'ExactNameMatch'; QueryId = [string]$matches[0].id }
	}
	# Zero exact-name matches.
	if (-not [string]::IsNullOrWhiteSpace($ExistingQueryId)) {
		# Replacement path: only after positively-confirmed absence.
		$absent = $true
		if ($CheckItem) {
			foreach ($v in @($EffectiveVersion, $AlternateVersion | Select-Object -Unique)) {
				if ([string]::IsNullOrWhiteSpace($v)) { continue }
				for ($i = 0; $i -le $MaxConsistencyRetries; $i++) {
					$ci = & $CheckItem $v $ExistingQueryId
					$cs = if ($ci) { $ci.HttpStatus } else { $null }
					if ($null -ne $cs -and $cs -ge 200 -and $cs -le 299) { $absent = $false; break }
					if ($cs -eq 404) { if ($i -ge $MaxConsistencyRetries) { break } else { continue } }
					# Non-404, non-2xx (auth/throttle/5xx/network): cannot confirm absence.
					$absent = $false; break
				}
				if (-not $absent) { break }
			}
		}
		if (-not $absent) {
			# The id is still visible somewhere => retain it, never replace.
			$State.AlternateVersionChecked = $true
			$State.AlternateVersionResult = 'Visible'
			return @{ Action = 'Adopt'; Reason = 'StillVisible'; QueryId = $ExistingQueryId }
		}
		# Positively confirmed absent: both-version 404 + exact-name miss.
		$State.QueryConfirmedAbsent = $true
		if ($State.ReplacementAttempted) {
			# At-most-once: a replacement was already persisted; never create again.
			return @{ Action = 'NoReplacement'; Reason = 'ReplacementAlreadyAttempted'; QueryId = $null }
		}
		# Persist ReplacementAttempted BEFORE creating, so a crash/resume cannot double-create.
		# Durable persistence is delegated to the caller-supplied intent callback and runs
		# ONLY here: after confirmed absence + exact-name miss, immediately before the sole
		# replacement POST (never for an Adopt/FailClosed/StillVisible outcome that POSTs nothing).
		$State.ReplacementAttempted = $true
		if ($PersistReplacementIntent) { & $PersistReplacementIntent $State }
		if ($CreateQuery) {
			$cr = & $CreateQuery $EffectiveVersion $DisplayName
			if ($cr -and $cr.Ambiguous) {
				$again = @(& $exactMatch (@(& $ListQueries)))
				if ($again.Count -eq 1) { return @{ Action = 'Adopt'; Reason = 'AmbiguousResolvedByName'; QueryId = [string]$again[0].id } }
				if ($again.Count -gt 1) { $State.FailureCategory = 'Other'; return @{ Action = 'FailClosed'; Reason = 'MultipleExactMatches'; MatchCount = $again.Count; QueryId = $null } }
				return @{ Action = 'NoReplacement'; Reason = 'AmbiguousUnresolved'; QueryId = $null }
			}
			$newId = if ($cr) { [string]$cr.QueryId } else { $null }
			$State.ReplacementQueryId = $newId
			return @{ Action = 'Replaced'; Reason = 'ConfirmedAbsent'; QueryId = $newId }
		}
		return @{ Action = 'NoReplacement'; Reason = 'NoCreateCallback'; QueryId = $null }
	}
	# No existing id and no exact-name match => initial creation (beta). Still guard
	# against duplicates via exact-name lookup + ambiguous-POST reconciliation.
	if ($CreateQuery) {
		$cr = & $CreateQuery $EffectiveVersion $DisplayName
		if ($cr -and $cr.Ambiguous) {
			$again = @(& $exactMatch (@(& $ListQueries)))
			if ($again.Count -eq 1) { return @{ Action = 'Adopt'; Reason = 'AmbiguousResolvedByName'; QueryId = [string]$again[0].id } }
			if ($again.Count -gt 1) { $State.FailureCategory = 'Other'; return @{ Action = 'FailClosed'; Reason = 'MultipleExactMatches'; MatchCount = $again.Count; QueryId = $null } }
			return @{ Action = 'NoReplacement'; Reason = 'AmbiguousUnresolved'; QueryId = $null }
		}
		$newId = if ($cr) { [string]$cr.QueryId } else { $null }
		return @{ Action = 'Created'; Reason = 'InitialCreate'; QueryId = $newId }
	}
	return @{ Action = 'NoReplacement'; Reason = 'NoCreateCallback'; QueryId = $null }
}

function New-GraphAuditQueryFingerprint {
	<#
	.SYNOPSIS
		Deterministic short contract fingerprint for a partition audit query.
	.DESCRIPTION
		Derives a stable hex fingerprint from the CANONICAL creation contract - the
		UTC start/end window plus the operation, record-type, and service filters -
		so two partitions that share a date window and partition index but differ in
		ANY filter yield DIFFERENT fingerprints (and therefore different display
		names). Each string array is normalized identically before hashing (null and
		blank dropped, trimmed, invariant upper-cased, ordinal-sorted, joined with a
		fixed unit separator); the two dates are rendered in invariant UTC; the parts
		are concatenated in a fixed order with a fixed record separator; the whole is
		hashed with SHA256 and the first twelve lower-case hex characters are returned.
		The same contract always yields the same fingerprint regardless of input
		order, element casing, or surrounding whitespace, so initial create,
		replacement, checkpoint naming, and exact-name reconciliation all derive one
		identity from the same producer.
	#>
	param(
		[Parameter(Mandatory)][datetime]$PStart,
		[Parameter(Mandatory)][datetime]$PEnd,
		$Activities,
		$RecordTypes,
		$ServiceFilter
	)
	$normArray = {
		param($arr)
		if ($null -eq $arr) { return '' }
		$vals = @(@($arr) | ForEach-Object { if ($null -eq $_) { '' } else { ([string]$_).Trim().ToUpperInvariant() } } | Where-Object { $_ -ne '' })
		if ($vals.Count -eq 0) { return '' }
		$arrSorted = [string[]]$vals
		[System.Array]::Sort($arrSorted, [System.StringComparer]::Ordinal)
		return ($arrSorted -join ([char]0x1F))
	}
	$svc = if ($null -eq $ServiceFilter) { '' } else { ([string]$ServiceFilter).Trim().ToUpperInvariant() }
	$parts = @(
		$PStart.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture),
		$PEnd.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture),
		(& $normArray $Activities),
		(& $normArray $RecordTypes),
		$svc
	)
	$canonical = $parts -join ([char]0x1E)
	$sha = [System.Security.Cryptography.SHA256]::Create()
	try {
		$hash = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($canonical))
	}
	finally { $sha.Dispose() }
	$hex = -join ($hash | ForEach-Object { $_.ToString('x2') })
	return $hex.Substring(0, 12)
}

function Get-PaxCheckpointEntryFingerprint {
	<#
	.SYNOPSIS
		Returns the durable contract fingerprint carried by a checkpoint bucket entry, or
		$null when the entry predates fingerprint identity (a legacy checkpoint).
	.DESCRIPTION
		A fingerprinted entry stores the stable New-GraphAuditQueryFingerprint value in a
		top-level `fingerprint` field; durable uncertain-create entries additionally carry it
		inside their structured UncertainCreateInfo. This reader is tolerant of both the
		in-memory hashtable shape and the ConvertFrom-Json object shape and NEVER throws on a
		missing field (a legacy entry yields $null so callers fall back to the historical
		index-only identity).
	#>
	param($Entry)
	if ($null -eq $Entry) { return $null }
	$fp = $Entry.fingerprint
	if (-not [string]::IsNullOrWhiteSpace([string]$fp)) { return [string]$fp }
	$uci = $Entry.UncertainCreateInfo
	if ($uci) {
		$ufp = $uci.fingerprint
		if (-not [string]::IsNullOrWhiteSpace([string]$ufp)) { return [string]$ufp }
	}
	return $null
}

function Get-PaxEntryIdentityKey {
	<#
	.SYNOPSIS
		Bucket-exclusivity identity key for a checkpoint entry: its fingerprint when present
		(the durable per-contract identity), otherwise its integer index (legacy fallback).
	#>
	param($Entry)
	$fp = Get-PaxCheckpointEntryFingerprint $Entry
	if (-not [string]::IsNullOrWhiteSpace($fp)) { return "fp:$fp" }
	if ($null -ne $Entry -and $null -ne $Entry.index) { return "idx:$([int]$Entry.index)" }
	return $null
}

function Test-PaxCheckpointIdentityMatch {
	<#
	.SYNOPSIS
		$true when a checkpoint bucket entry denotes the SAME durable partition identity as
		the supplied (Index, Fingerprint).
	.DESCRIPTION
		Fingerprint is the authoritative identity: when BOTH the entry and the query carry a
		non-empty fingerprint, ONLY equal fingerprints match, so two workload-pass contracts
		that reuse the same partition index remain distinct identities and never collide.
		Defect 2 (fail-closed identity): fingerprint is the SOLE durable identity in the
		resume-classification and persistence paths. A legacy (fingerprint-less) checkpoint
		entry is migrated to a proven-unique fingerprint by the pre-auth legacy-mapping
		resolver (Invoke-PaxResumeLegacyContractMapping) BEFORE any partition is classified
		or persisted, so an un-migrated legacy entry - or an identity-less caller - reaching
		this matcher is NEVER silently index-matched onto a fingerprinted contract. Index-only
		"matching" is exactly the cross-workload-pass collision this defect closes, so when a
		fingerprint is not available on both sides this matcher fails closed (returns $false).
	#>
	param($Entry, [int]$Index, [string]$Fingerprint)
	if ($null -eq $Entry) { return $false }
	$efp = Get-PaxCheckpointEntryFingerprint $Entry
	if (-not [string]::IsNullOrWhiteSpace($Fingerprint) -and -not [string]::IsNullOrWhiteSpace($efp)) {
		return ($efp -eq [string]$Fingerprint)
	}
	# Tightened (defect 2, Option 1): no permissive index fallback. Legacy entries are
	# migrated to a durable fingerprint pre-auth; an un-migrated legacy entry (or a caller
	# with no contract fingerprint in hand) must not be silently index-matched onto a
	# fingerprinted contract. Fail closed.
	return $false
}

function Test-PaxLegacyContractCandidate {
	<#
	.SYNOPSIS
		$true when a current partition contract is a candidate match for a legacy
		(fingerprint-less) checkpoint bucket entry, under the read-only pre-auth
		legacy-mapping resolver.
	.DESCRIPTION
		A legacy entry identifies its partition only by integer index plus its saved
		start/end window (and, when present, its stored contract fields). This tester matches
		a reconstructed current contract to that entry by:
		  * integer partition index (when the entry carries one), AND
		  * exact UTC-instant equality of the start and end window, AND
		  * every stored contract field the entry actually carries (serviceFilter/service,
		    recordTypes) - a field absent from the legacy entry is not used to reject.
		It NEVER computes or trusts a fingerprint; disambiguation among several contracts that
		share a window/index is deliberately impossible here, so such a legacy entry yields
		more than one candidate and the resolver fails closed rather than guessing.
	#>
	param($Entry, $Index, $Start, $End, $Contract)
	if ($null -eq $Contract) { return $false }
	if ($null -ne $Index -and $null -ne $Contract.Index -and ([int]$Contract.Index -ne [int]$Index)) { return $false }
	if ($Start -and $Contract.PStart) {
		if (([datetime]$Contract.PStart).ToUniversalTime() -ne ([datetime]$Start).ToUniversalTime()) { return $false }
	}
	if ($End -and $Contract.PEnd) {
		if (([datetime]$Contract.PEnd).ToUniversalTime() -ne ([datetime]$End).ToUniversalTime()) { return $false }
	}
	$eSvc = $Entry.serviceFilter
	if ($null -eq $eSvc) { $eSvc = $Entry.service }
	if ($null -ne $eSvc -and -not [string]::IsNullOrWhiteSpace([string]$eSvc)) {
		if ([string]$eSvc -ne [string]$Contract.ServiceFilter) { return $false }
	}
	$eRt = $Entry.recordTypes
	if ($null -ne $eRt) {
		$eRtJoin = (@($eRt) | Sort-Object) -join '|'
		$cRtJoin = (@($Contract.RecordTypes) | Sort-Object) -join '|'
		if ($eRtJoin -ne $cRtJoin) { return $false }
	}
	return $true
}

function Test-PaxCheckpointEntryCompatible {
	<#
	.SYNOPSIS
		$true when two checkpoint bucket entries that claim the SAME durable contract identity
		carry PROVABLY equivalent stored metadata, so one may supersede the other inside a
		single atomic migration. $false whenever equivalence cannot be proven.
	.DESCRIPTION
		Bucket exclusivity (completed > queryCreated > uncertainCreate) may only be enforced by
		REMOVING a lower-precedence duplicate when that duplicate is provably the SAME work. A
		shared fingerprint alone is NOT that evidence: two entries can share a contract
		fingerprint yet carry different server query ids, indexes, windows, or filters, which
		means the checkpoint records genuinely different state and silently discarding either
		would lose it.

		Every field is compared ONLY when BOTH entries carry a usable value - an absent or
		blank field on a legacy entry is not evidence of a conflict. Any field present on both
		sides that DIFFERS (server query id, partition index, start / end instant, record
		types, or service filter) is a CONFLICT and yields $false so the caller fails closed
		instead of guessing. A start / end value present on both sides that cannot be parsed on
		either side is likewise unproven, and therefore a conflict - never a match.
	#>
	param($A, $B)
	if ($null -eq $A -or $null -eq $B) { return $false }
	$looseEq = {
		param($x, $y)
		if ($null -eq $x -or $null -eq $y) { return $true }
		$xs = ([string]$x).Trim(); $ys = ([string]$y).Trim()
		if ($xs -eq '' -or $ys -eq '') { return $true }
		return ([string]::Equals($xs, $ys, [System.StringComparison]::OrdinalIgnoreCase))
	}
	if (-not (& $looseEq $A.queryId $B.queryId)) { return $false }
	if ($null -ne $A.index -and $null -ne $B.index) {
		if ([int]$A.index -ne [int]$B.index) { return $false }
	}
	foreach ($fld in @('start', 'end')) {
		$av = $A.$fld
		$bv = $B.$fld
		if ([string]::IsNullOrWhiteSpace([string]$av) -or [string]::IsNullOrWhiteSpace([string]$bv)) { continue }
		$ad = script:Parse-DateSafe $av
		$bd = script:Parse-DateSafe $bv
		if ($null -eq $ad -or $null -eq $bd) { return $false }
		if (([datetime]$ad).ToUniversalTime() -ne ([datetime]$bd).ToUniversalTime()) { return $false }
	}
	if ($null -ne $A.recordTypes -and $null -ne $B.recordTypes) {
		$aRt = (@($A.recordTypes) | Sort-Object) -join '|'
		$bRt = (@($B.recordTypes) | Sort-Object) -join '|'
		if ($aRt -ne $bRt) { return $false }
	}
	$aSvc = if ($null -ne $A.serviceFilter) { $A.serviceFilter } else { $A.service }
	$bSvc = if ($null -ne $B.serviceFilter) { $B.serviceFilter } else { $B.service }
	if (-not (& $looseEq $aSvc $bSvc)) { return $false }
	return $true
}

function Get-PaxResumeCurrentContractSet {
	<#
	.SYNOPSIS
		READ-ONLY reconstruction of the COMPLETE set of current partition contracts across
		ALL serviceRuns x query groups, from restored checkpoint parameters. No Graph call,
		no authentication, no mutation.
	.DESCRIPTION
		Deterministically replays the main partition build (serviceRuns split, per-workload
		operation/recordType alignment, partition-hours defaulting + MaxPartitions capping,
		Get-QueryPlan grouping, and per-group time slicing) so a legacy (fingerprint-less)
		checkpoint entry can be matched to exactly one durable contract BEFORE authentication.
		It reproduces the single-partition variable-carry quirk of the main build byte-for-byte:
		$partitionRecordTypes / $partitionServiceFilter are assigned ONLY inside the
		multi-partition branch and otherwise carry across groups and service passes, so a
		single-partition group inherits the prior multi-partition group's record/service
		values exactly as the live build does. The normal per-group build remains the sole
		producer of the contracts actually processed; this helper only ENUMERATES them.
	#>
	param(
		[datetime]$StartDateObj,
		[datetime]$EndDateObj,
		[string[]]$ActivityTypes,
		[string[]]$RecordTypes,
		[string[]]$ServiceTypes,
		[int]$PartitionHours = 0,
		[int]$MaxPartitions = 50,
		[int]$MaxConcurrency = 10,
		[switch]$IncludeM365Usage,
		[switch]$UseEOM,
		[hashtable]$ServiceOperationMap,
		[hashtable]$RecordTypeWorkloadMap
	)
	$contracts = New-Object System.Collections.ArrayList
	if (-not $UseEOM -and $ServiceTypes -and $ServiceTypes.Count -gt 0) { $serviceRuns = $ServiceTypes } else { $serviceRuns = @($null) }
	# Variable-carry quirk (mirrors main build): declared outside both loops and assigned
	# ONLY in the multi-partition branch, so a single-partition group carries the prior value.
	$partitionRecordTypes = $null
	$partitionServiceFilter = $null
	foreach ($currentServiceFilter in $serviceRuns) {
		$serviceActivities = $ActivityTypes
		if ($currentServiceFilter -and $ServiceOperationMap -and $ServiceOperationMap.ContainsKey($currentServiceFilter)) {
			$mappedOps = @($ServiceOperationMap[$currentServiceFilter] | Where-Object { $ActivityTypes -contains $_ })
			if ($mappedOps.Count -gt 0) { $serviceActivities = $mappedOps }
		}
		$serviceRecordTypes = $RecordTypes
		if ($currentServiceFilter -and $RecordTypes) {
			$matched = @()
			foreach ($rt in $RecordTypes) {
				$rtServices = $RecordTypeWorkloadMap[$rt]
				if ($null -eq $rtServices -or $rtServices.Count -eq 0) { $matched += $rt; continue }
				if ($rtServices -contains $currentServiceFilter) { $matched += $rt }
			}
			if ($matched.Count -gt 0) { $serviceRecordTypes = $matched | Select-Object -Unique } else { $serviceRecordTypes = $null }
		}
		$queryPlan = @(Get-QueryPlan -RequestedActivities $serviceActivities)
		foreach ($grp in $queryPlan) {
			$effectivePartitionHours = $PartitionHours
			$userSpecifiedPartitionHours = ($PartitionHours -gt 0)
			if (-not $UseEOM -and $effectivePartitionHours -eq 0) { $effectivePartitionHours = 12 }
			if (-not $UseEOM -and $effectivePartitionHours -gt 0) {
				$totalHours = ($EndDateObj - $StartDateObj).TotalHours
				$calculatedPartitions = [Math]::Ceiling($totalHours / $effectivePartitionHours)
				if ($calculatedPartitions -gt $MaxPartitions) {
					if (-not $userSpecifiedPartitionHours) {
						$effectivePartitionHours = 12
						$calculatedPartitions = [Math]::Ceiling($totalHours / $effectivePartitionHours)
					}
					if ($calculatedPartitions -gt $MaxPartitions) {
						$calculatedPartitions = $MaxPartitions
						$effectivePartitionHours = $totalHours / $calculatedPartitions
					}
				}
				$degree = $calculatedPartitions
			} else {
				$degree = [Math]::Min($grp.Concurrency, $MaxConcurrency)
			}
			$totalPartitions = $degree
			$activities = $grp.Activities
			$activity = $grp.Activities[0]
			if ($totalPartitions -gt 1) {
				$totalHours = ($EndDateObj - $StartDateObj).TotalHours
				if (-not $UseEOM -and $effectivePartitionHours -gt 0) { $sliceHours = $effectivePartitionHours } else { $sliceHours = $totalHours / $totalPartitions }
				$partitionRecordTypes = $serviceRecordTypes
				$partitionServiceFilter = $currentServiceFilter
				if ($IncludeM365Usage) { $partitionRecordTypes = $null; $partitionServiceFilter = $null }
				for ($pi = 0; $pi -lt $totalPartitions; $pi++) {
					$pStart = $StartDateObj.AddHours($sliceHours * $pi)
					$pEnd = if ($pi -eq ($totalPartitions - 1)) { $EndDateObj } else { $StartDateObj.AddHours($sliceHours * ($pi + 1)) }
					[void]$contracts.Add([pscustomobject]@{
						Activities    = $activities
						Activity      = $activity
						PStart        = $pStart
						PEnd          = $pEnd
						Index         = ($pi + 1)
						Total         = $totalPartitions
						RecordTypes   = $partitionRecordTypes
						ServiceFilter = $partitionServiceFilter
					})
				}
			} else {
				[void]$contracts.Add([pscustomobject]@{
					Activities    = $activities
					Activity      = $activity
					PStart        = $StartDateObj
					PEnd          = $EndDateObj
					Index         = 1
					Total         = 1
					RecordTypes   = $partitionRecordTypes
					ServiceFilter = $partitionServiceFilter
				})
			}
		}
	}
	return @($contracts.ToArray())
}

function Invoke-PaxResumeLegacyContractMapping {
	<#
	.SYNOPSIS
		Pre-auth, read-only cross-run legacy-mapping resolver (defect 2). Migrates every
		legacy (fingerprint-less) checkpoint bucket entry to a proven-unique durable
		fingerprint, or fails closed WITHOUT authentication or mutation.
	.DESCRIPTION
		Runs on resume BEFORE authentication and the per-workload partition build. For each
		legacy entry (completed / queryCreated / uncertainCreate WITHOUT a fingerprint) it
		finds candidate current contracts (Test-PaxLegacyContractCandidate) from the complete
		reconstructed set. EXACTLY ONE candidate stages a unique mapping (the contract's
		New-GraphAuditQueryFingerprint); ZERO fails closed (never discard/recreate); MORE THAN
		ONE fails closed as LegacyContractAmbiguous.

		BUCKET EXCLUSIVITY. A contract identity may occupy EXACTLY ONE lifecycle bucket, under
		the precedence completed > queryCreated > uncertainCreate. Every candidate fingerprint
		is therefore checked against ALL THREE buckets, not only its source bucket. A collision
		is resolved only with EXPLICIT evidence (Test-PaxCheckpointEntryCompatible proves the
		stored query id / index / window / record types / service filter are equivalent): a
		legacy row already owned by a HIGHER-precedence entry is classified superseded and
		removed as part of this same atomic migration, a LOWER-precedence duplicate of a
		migrated row is normalized in the same transaction, a same-bucket collision stays
		LegacyContractAmbiguous, and any CONFLICTING metadata fails closed as
		LegacyContractConflict rather than guessing. Residual cross-bucket duplicates among
		untouched identities are normalized under the same rule, so the resume classifier never
		depends on a normalization that happens later.

		The ENTIRE migration + normalization plan is validated first; only on full success are
		fingerprints stamped in-memory and published ATOMICALLY and EXACTLY ONCE (via the
		supplied -Publish block, default Save-CheckpointStrict) BEFORE any fetch/reconcile/
		create. Publication must be PROVEN durable - an explicit $true, or a throw on failure;
		any other outcome restores the exact pre-migration in-memory state (bucket membership
		AND every fingerprint stamp), leaves the durable checkpoint byte-for-byte unchanged,
		latches $script:GenericFatal, and throws PAX-FATAL. On any zero/ambiguous/collision/
		conflict outcome it likewise latches $script:GenericFatal and
		throws a PAX-FATAL error so the caller can emit actionable output and exit nonzero with
		no auth and no mutation. Returns a status object on success or when there is nothing to
		migrate.
	#>
	param(
		[Parameter(Mandatory = $true)]$CheckpointData,
		[object[]]$CurrentContracts = @(),
		[scriptblock]$Publish
	)
	if ($null -eq $CheckpointData -or $null -eq $CheckpointData.partitions) {
		return [pscustomobject]@{ Status = 'NoLegacy'; Migrated = 0; Reason = 'no checkpoint partitions present' }
	}
	$buckets = @('completed', 'queryCreated', 'uncertainCreate')
	# Lifecycle precedence: a single contract identity may occupy EXACTLY ONE bucket, and a
	# higher-precedence record always supersedes a lower-precedence one.
	$rankOf = @{ completed = 3; queryCreated = 2; uncertainCreate = 1 }
	$legacy = New-Object System.Collections.ArrayList
	foreach ($b in $buckets) {
		foreach ($e in @($CheckpointData.partitions.$b)) {
			if ($null -eq $e) { continue }
			$efp = Get-PaxCheckpointEntryFingerprint $e
			if ([string]::IsNullOrWhiteSpace($efp)) { [void]$legacy.Add([pscustomobject]@{ Bucket = $b; Entry = $e }) }
		}
	}
	if ($legacy.Count -eq 0) {
		return [pscustomobject]@{ Status = 'NoLegacy'; Migrated = 0; Reason = 'all checkpoint entries already carry a durable fingerprint' }
	}
	# Validate the ENTIRE migration first - no mutation until every legacy entry maps uniquely.
	$claimed = @{}
	$stage = New-Object System.Collections.ArrayList
	foreach ($item in $legacy) {
		$e = $item.Entry
		$idx = if ($null -ne $e.index) { [int]$e.index } else { $null }
		$eStart = if ($e.start) { script:Parse-DateSafe $e.start } else { $null }
		$eEnd = if ($e.end) { script:Parse-DateSafe $e.end } else { $null }
		$cands = @($CurrentContracts | Where-Object { Test-PaxLegacyContractCandidate -Entry $e -Index $idx -Start $eStart -End $eEnd -Contract $_ })
		$where = "index $idx, window $($e.start)..$($e.end), bucket $($item.Bucket)"
		if ($cands.Count -eq 0) {
			$script:GenericFatal = $true
			throw "PAX-FATAL-LEGACY-NOMATCH: a legacy (fingerprint-less) checkpoint entry ($where) matches NONE of the current partition contracts. Refusing to discard or recreate it. Confirm the resume parameters (date range, activity/record/service filters, partition hours) match the original run, then retry."
		}
		if ($cands.Count -gt 1) {
			$script:GenericFatal = $true
			throw "PAX-FATAL-LegacyContractAmbiguous: a legacy (fingerprint-less) checkpoint entry ($where) matches $($cands.Count) current partition contracts and cannot be assigned a durable identity safely. This checkpoint predates per-contract fingerprints and spans multiple workload contracts at one index. Re-run the original collection to completion, or narrow -ServiceTypes/-RecordTypes so the entry maps to a single contract."
		}
		$c = $cands[0]
		$fp = New-GraphAuditQueryFingerprint -PStart $c.PStart -PEnd $c.PEnd -Activities $c.Activities -RecordTypes $c.RecordTypes -ServiceFilter $c.ServiceFilter
		if ([string]::IsNullOrWhiteSpace($fp)) {
			$script:GenericFatal = $true
			throw "PAX-FATAL-LEGACY-FP: could not derive a durable fingerprint for the current contract matching a legacy checkpoint entry ($where)."
		}
		if ($claimed.ContainsKey($fp)) {
			$script:GenericFatal = $true
			throw "PAX-FATAL-LegacyContractAmbiguous: two legacy checkpoint entries resolve to the same current contract (fingerprint $fp); the mapping is not one-to-one. Re-run the original collection to completion."
		}
		# Bucket exclusivity is validated across ALL THREE lifecycle buckets, never only the
		# SOURCE bucket: a fingerprint may occupy EXACTLY ONE bucket. Every existing owner of
		# this candidate identity is located, its stored metadata is compared for PROVABLE
		# equivalence, and the outcome is resolved by precedence - all BEFORE any mutation.
		$owners = New-Object System.Collections.ArrayList
		foreach ($ob in $buckets) {
			foreach ($oe in @($CheckpointData.partitions.$ob)) {
				if ($null -eq $oe) { continue }
				if ([object]::ReferenceEquals($oe, $e)) { continue }
				if ((Get-PaxCheckpointEntryFingerprint $oe) -eq $fp) {
					[void]$owners.Add([pscustomobject]@{ Bucket = $ob; Entry = $oe })
				}
			}
		}
		$legacyRank = [int]$rankOf[$item.Bucket]
		$supersededLegacy = $false
		$demoted = New-Object System.Collections.ArrayList
		foreach ($o in $owners) {
			if (-not (Test-PaxCheckpointEntryCompatible $e $o.Entry)) {
				$script:GenericFatal = $true
				throw "PAX-FATAL-LegacyContractConflict: migrating a legacy checkpoint entry ($where) to fingerprint $fp would collide with an existing '$($o.Bucket)' entry whose stored query id, partition index, window, or contract metadata DIFFERS. The two records are not provably the same work, so neither may be discarded. Re-run the original collection to completion, or narrow -ServiceTypes/-RecordTypes so the entry maps to a single contract."
			}
			$ownerRank = [int]$rankOf[$o.Bucket]
			if ($ownerRank -eq $legacyRank) {
				$script:GenericFatal = $true
				throw "PAX-FATAL-LegacyContractAmbiguous: migrating a legacy checkpoint entry ($where) to fingerprint $fp would collide with an existing durable entry in the same bucket. Re-run the original collection to completion."
			}
			if ($ownerRank -gt $legacyRank) { $supersededLegacy = $true }
			else { [void]$demoted.Add($o) }
		}
		$claimed[$fp] = $idx
		if ($supersededLegacy) {
			# A HIGHER-precedence entry already owns this contract and is PROVABLY the same work,
			# so the legacy lower-precedence row is superseded. It is removed ONLY as part of the
			# atomic migration and is never stamped into a second bucket.
			[void]$stage.Add([pscustomobject]@{ Entry = $e; Fingerprint = $fp; Bucket = $item.Bucket; Action = 'Supersede'; Demoted = @() })
		}
		else {
			# No owner, or only LOWER-precedence owners: stamp the legacy entry and normalize
			# every lower-precedence duplicate inside the SAME atomic transaction.
			[void]$stage.Add([pscustomobject]@{ Entry = $e; Fingerprint = $fp; Bucket = $item.Bucket; Action = 'Migrate'; Demoted = @($demoted.ToArray()) })
		}
	}
	# Residual cross-bucket duplicates among identities this migration does not touch are
	# resolved under the SAME precedence and the SAME evidence rule, planned BEFORE any
	# mutation so a fail-closed outcome still leaves the checkpoint untouched. This is what
	# lets Get-PartitionsToProcess classify from an already-exclusive checkpoint instead of
	# depending on a normalization that happens later.
	$existingByFp = @{}
	foreach ($b in $buckets) {
		foreach ($xe in @($CheckpointData.partitions.$b)) {
			if ($null -eq $xe) { continue }
			$xfp = Get-PaxCheckpointEntryFingerprint $xe
			if ([string]::IsNullOrWhiteSpace($xfp)) { continue }
			if (-not $existingByFp.ContainsKey($xfp)) { $existingByFp[$xfp] = New-Object System.Collections.ArrayList }
			[void]$existingByFp[$xfp].Add([pscustomobject]@{ Bucket = $b; Entry = $xe })
		}
	}
	$residual = New-Object System.Collections.ArrayList
	foreach ($k in @($existingByFp.Keys)) {
		$grp = @($existingByFp[$k].ToArray())
		if ($grp.Count -le 1) { continue }
		if (@($grp | ForEach-Object { $_.Bucket } | Select-Object -Unique).Count -le 1) { continue }
		$winner = @($grp | Sort-Object @{ Expression = { [int]$rankOf[$_.Bucket] }; Descending = $true })[0]
		foreach ($g in $grp) {
			if ([object]::ReferenceEquals($g.Entry, $winner.Entry)) { continue }
			if ([int]$rankOf[$g.Bucket] -eq [int]$rankOf[$winner.Bucket]) { continue }
			if (-not (Test-PaxCheckpointEntryCompatible $winner.Entry $g.Entry)) {
				$script:GenericFatal = $true
				throw "PAX-FATAL-LegacyContractConflict: contract $k is recorded in both the '$($winner.Bucket)' and '$($g.Bucket)' lifecycle buckets with DIFFERING stored query id, partition index, window, or contract metadata, so neither record may be discarded. Re-run the original collection to completion."
			}
			[void]$residual.Add([pscustomobject]@{ Bucket = $g.Bucket; Entry = $g.Entry })
		}
	}
	# Full migration + normalization validated. Snapshot every lifecycle bucket and the exact
	# set of entries about to be stamped so an unproven publication rolls back to the EXACT
	# pre-migration in-memory state, then mutate and publish EXACTLY ONCE.
	$snapCompleted = @($CheckpointData.partitions.completed)
	$snapQueryCreated = @($CheckpointData.partitions.queryCreated)
	$snapUncertain = @($CheckpointData.partitions.uncertainCreate)
	$stamped = New-Object System.Collections.ArrayList
	$removals = New-Object System.Collections.ArrayList
	foreach ($s in $stage) {
		if ($s.Action -eq 'Supersede') {
			[void]$removals.Add([pscustomobject]@{ Bucket = $s.Bucket; Entry = $s.Entry })
			continue
		}
		if ($s.Entry -is [System.Collections.IDictionary]) { $s.Entry['fingerprint'] = $s.Fingerprint }
		else { $s.Entry | Add-Member -NotePropertyName fingerprint -NotePropertyValue $s.Fingerprint -Force }
		[void]$stamped.Add($s.Entry)
		foreach ($d in @($s.Demoted)) { if ($null -ne $d) { [void]$removals.Add([pscustomobject]@{ Bucket = $d.Bucket; Entry = $d.Entry }) } }
	}
	foreach ($r in @($residual.ToArray())) { [void]$removals.Add($r) }
	foreach ($b in $buckets) {
		$drop = @(@($removals.ToArray()) | Where-Object { $_.Bucket -eq $b } | ForEach-Object { $_.Entry })
		if ($drop.Count -eq 0) { continue }
		$CheckpointData.partitions.$b = @(@($CheckpointData.partitions.$b) | Where-Object {
				$candidate = $_
				$keep = $true
				foreach ($d in $drop) { if ([object]::ReferenceEquals($candidate, $d)) { $keep = $false; break } }
				$keep
			})
	}
	# Publish EXACTLY ONCE. Publication must be PROVEN durable (an explicit $true, or a throw
	# on failure); anything else is a failed publication and rolls the checkpoint back.
	$published = $false
	$publishErr = $null
	try {
		if ($Publish) {
			$publishResult = @(& $Publish) | Select-Object -Last 1
			$published = ($publishResult -is [bool]) -and ([bool]$publishResult)
		}
		elseif (Get-Command Save-CheckpointStrict -ErrorAction SilentlyContinue) {
			$published = [bool](Save-CheckpointStrict)
		}
	}
	catch { $publishErr = $_ }
	if (-not $published) {
		# Fail closed: restore the EXACT pre-migration in-memory state (bucket membership AND
		# every fingerprint stamp). The strict publisher leaves the durable copy byte-for-byte
		# unchanged, so memory and disk agree again and no fetch, reconcile, or create is
		# authorized on a migration that was never proven durable.
		$CheckpointData.partitions.completed = $snapCompleted
		$CheckpointData.partitions.queryCreated = $snapQueryCreated
		$CheckpointData.partitions.uncertainCreate = $snapUncertain
		foreach ($se in @($stamped.ToArray())) {
			if ($se -is [System.Collections.IDictionary]) {
				if ($se.Contains('fingerprint')) { [void]$se.Remove('fingerprint') }
			}
			elseif ($null -ne $se.PSObject.Properties['fingerprint']) {
				$se.PSObject.Properties.Remove('fingerprint')
			}
		}
		$script:GenericFatal = $true
		$publishDetail = if ($publishErr) { [string]$publishErr.Exception.Message } else { 'the publication callback did not return a proven durable publication.' }
		if ($publishDetail -match 'PAX-FATAL-ROLLBACK') {
			throw "PAX-FATAL-ROLLBACK: durable publication of the legacy contract migration failed AND the prior checkpoint could not be restored; disk state is indeterminate - manual checkpoint inspection required. $publishDetail"
		}
		throw "PAX-FATAL: durable publication of the legacy contract migration failed; fail-closed, the checkpoint is unchanged and no fetch, reconcile, or create is authorized. $publishDetail"
	}
	return [pscustomobject]@{ Status = 'Migrated'; Migrated = $stamped.Count; Superseded = @($stage | Where-Object { $_.Action -eq 'Supersede' }).Count; Normalized = @($removals.ToArray()).Count; Reason = 'legacy entries migrated to proven-unique fingerprints, normalized to one lifecycle bucket per contract, and published atomically' }
}

function New-GraphAuditPartitionDisplayName {
	<#
	.SYNOPSIS
		Single deterministic producer of a partition query displayName.
	.DESCRIPTION
		Every path that names a partition query (parent create/replacement,
		exact-name lookup, checkpoint, and completion/retry display) routes through
		this one function so the same partition always yields a byte-identical name.
		The end boundary is exclusive, so the name shows the last INCLUDED minute
		(PEnd minus one minute), matching the Purview UI and the created query.

		Identity is contract-inclusive: when the creation contract (Activities,
		RecordTypes, ServiceFilter) or an explicit -Fingerprint is supplied, a
		deterministic fingerprint of that contract is appended so two partitions with
		the same date window and partition index but a DIFFERENT operation, record
		type, service, or date filter produce different names and cannot cross-adopt.
		An explicit -Fingerprint wins; otherwise the fingerprint is derived here from
		the supplied contract through the single fingerprint producer. With no contract
		and no fingerprint the legacy (fingerprint-less) name is returned unchanged, so
		a pre-fingerprint checkpoint name can still be reproduced for legacy recovery.
	#>
	param(
		[Parameter(Mandatory)][datetime]$PStart,
		[Parameter(Mandatory)][datetime]$PEnd,
		[Parameter(Mandatory)]$Index,
		[Parameter(Mandatory)]$Total,
		$Activities,
		$RecordTypes,
		$ServiceFilter,
		[string]$Fingerprint
	)
	$pEndDisplay = $PEnd.AddMinutes(-1)
	$base = "PAX_Query_$($PStart.ToString('yyyyMMdd_HHmm'))-$($pEndDisplay.ToString('yyyyMMdd_HHmm'))_Part$Index/$Total"
	$fp = $Fingerprint
	if ([string]::IsNullOrWhiteSpace($fp) -and ($PSBoundParameters.ContainsKey('Activities') -or $PSBoundParameters.ContainsKey('RecordTypes') -or $PSBoundParameters.ContainsKey('ServiceFilter'))) {
		$fp = New-GraphAuditQueryFingerprint -PStart $PStart -PEnd $PEnd -Activities $Activities -RecordTypes $RecordTypes -ServiceFilter $ServiceFilter
	}
	if (-not [string]::IsNullOrWhiteSpace($fp)) { return "${base}_$fp" }
	return $base
}

function New-GraphAuditQueryRequest {
	<#
	.SYNOPSIS
		Single producer of a partition audit-query request body (filters only).
	.DESCRIPTION
		Every recovery/replacement create path routes its filter payload through
		this one function so an initial create and a replacement create for the same
		partition produce EQUIVALENT bodies. Emits filterStartDateTime and
		filterEndDateTime in invariant-culture .fffZ, an unconditional
		operationFilters array, and the recordTypeFilters / serviceFilter keys gated
		exactly as the production create. The displayName is added by the caller (see
		New-GraphAuditPartitionDisplayName), so the name and the filters each have a
		single source.
	#>
	param(
		[Parameter(Mandatory)][datetime]$PStart,
		[Parameter(Mandatory)][datetime]$PEnd,
		$Activities,
		$RecordTypes,
		$ServiceFilter
	)
	$body = @{
		filterStartDateTime = $PStart.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture)
		filterEndDateTime   = $PEnd.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture)
		operationFilters    = @($Activities)
	}
	if ($RecordTypes -and $RecordTypes.Count -gt 0) { $body.recordTypeFilters = @($RecordTypes) }
	if ($ServiceFilter) { $body.serviceFilter = $ServiceFilter }
	return $body
}

function Invoke-GraphAuditHardenedCreate {
	<#
	.SYNOPSIS
		Parent-callable hardened creation of a single partition audit query.
	.DESCRIPTION
		Reproduces the per-partition create robustness in a parent-scope function so
		query creation can run in the main runspace (where the token can be
		refreshed) before workers are launched. The HTTP transport is injected via
		-Invoke so the same logic serves both production (real Invoke-MgGraphRequest /
		Invoke-RestMethod) and injected-transport validation.

		The name comes from New-GraphAuditPartitionDisplayName and the filters from
		New-GraphAuditQueryRequest, so a parent create and a worker/replacement create
		for the same partition are byte-equivalent. Creation always targets the beta
		surface; v1.0 creation is disabled.

		Failure handling preserves the established caps exactly:
		  * transient 403: retry up to 3 times with 15s / 30s / 60s backoff;
		  * permanent 403 / CAE (InsufficientPrivileges | Authorization_RequestDenied |
		    AccessDenied | InvalidAuthenticationToken in the body, or a WWW-Authenticate
		    claims challenge): fast-fail, no retry;
		  * 429: honour Retry-After when present else exponential 60/120/240 capped at
		    300s, abort once the shared attempt counter reaches 20;
		  * transient network / 5xx: retry inside a time-based outage window
		    (MaxNetworkOutageMinutes) with a 30-60s randomized delay, then abort;
		  * an ambiguous create response (name conflict) is reconciled by a
		    fully-paginated exact-name lookup: exactly one match is adopted, multiple
		    fail closed, none aborts - never a blind re-POST.

		The injected transport callback receives ($Version, $BodyJson, $ClientRequestId)
		and returns @{ HttpStatus; Id; ResponseBody; Headers }. A connectivity failure
		is surfaced as HttpStatus 0 (or null) or >= 500. Returns a structured result:
		@{ QueryId; FailureCategory; HttpStatus; DisplayName; Version; Adopted }.
	#>
	param(
		[Parameter(Mandatory)][datetime]$PStart,
		[Parameter(Mandatory)][datetime]$PEnd,
		[Parameter(Mandatory)]$Index,
		[Parameter(Mandatory)]$Total,
		$Activities,
		$RecordTypes,
		$ServiceFilter,
		[Parameter(Mandatory)][scriptblock]$Invoke,   # param($Version,$BodyJson,$ClientRequestId) -> @{ HttpStatus; Id; ResponseBody; Headers }
		[string]$Version = $null,                     # creation always beta; v1.0 disabled
		[int]$MaxNetworkOutageMinutes = 30,
		[scriptblock]$ListQueries = $null,            # -> array of @{ id; displayName } (fully paginated), for ambiguous-POST reconcile
		[switch]$PreCreateReconcile,                  # with $ListQueries, run a fully-paginated exact-name lookup BEFORE the first POST (adopt one, fail closed on many, POST only on a miss)
		[switch]$ReconcileOnly,                        # with $ListQueries, resolve a durable uncertain-create partition READ-ONLY: adopt one exact match, fail closed on many, stay unresolved on none - NEVER a POST
		[scriptblock]$FetchItem = $null,              # param($QueryId) -> the query item with its filter contract (operationFilters/recordTypeFilters/serviceFilter/filterStartDateTime/filterEndDateTime); required to safely adopt a legacy fingerprint-less same-name match
		[scriptblock]$Sleep = $null,                  # param($Seconds) - injectable delay (defaults to Start-Sleep)
		[scriptblock]$Log = $null                     # param($Message) - optional diagnostic sink
	)
	if ([string]::IsNullOrWhiteSpace($Version)) { $Version = $script:GraphAuditApiVersion_Previous }
	if (-not $Sleep) { $Sleep = { param($s) Start-Sleep -Seconds $s } }
	$emit = { param($m) if ($Log) { & $Log $m } }

	# Contract-inclusive identity: the created name, every exact-name reconcile lookup,
	# and the POST body all derive from the SAME contract, so a differing operation /
	# record-type / service / date contract yields a different name and cannot cross-adopt.
	$displayName = New-GraphAuditPartitionDisplayName -PStart $PStart -PEnd $PEnd -Index $Index -Total $Total -Activities $Activities -RecordTypes $RecordTypes -ServiceFilter $ServiceFilter
	$bodyObj = New-GraphAuditQueryRequest -PStart $PStart -PEnd $PEnd -Activities $Activities -RecordTypes $RecordTypes -ServiceFilter $ServiceFilter
	$bodyObj.displayName = $displayName
	$bodyJson = $bodyObj | ConvertTo-Json -Depth 5
	$clientRequestId = [guid]::NewGuid().ToString()

	$new = {
		param($queryId, $category, $status, $adopted, $requestId = $null, $responseBody = $null)
		return @{
			QueryId = $queryId
			FailureCategory = $category
			HttpStatus = $status
			DisplayName = $displayName
			Version = $Version
			Adopted = [bool]$adopted
			ClientRequestId = $clientRequestId
			RequestId = $requestId
			ResponseBody = $responseBody
		}
	}

	# Reconcile an ambiguous create by exact-name lookup: adopt one, fail closed on
	# many, abort on none. Never a blind re-POST.
	$reconcile = {
		param($status)
		if (-not $ListQueries) { return & $new $null 'AmbiguousUnresolved' $status $false }
		$all = @(& $ListQueries)
		$exact = @($all | Where-Object { $null -ne $_ -and [string]::Equals([string]$_.displayName, $displayName, [System.StringComparison]::Ordinal) })
		if ($exact.Count -eq 1) { return & $new ([string]$exact[0].id) 'None' $status $true }
		if ($exact.Count -gt 1) { return & $new $null 'MultipleExactMatches' $status $false }
		return & $new $null 'AmbiguousUnresolved' $status $false
	}

	# Exact-name lookup shared by the pre-create and uncertain-outcome reconcile
	# paths: an ordinal displayName match against the fully-paginated collection.
	$findExactByName = {
		$all = @(& $ListQueries)
		@($all | Where-Object { $null -ne $_ -and [string]::Equals([string]$_.displayName, $displayName, [System.StringComparison]::Ordinal) })
	}

	# Legacy fingerprint-less recovery. A pre-fingerprint checkpoint created queries
	# whose names lack the contract fingerprint, so a query that matches the LEGACY
	# (fingerprint-less) name may actually carry a DIFFERENT operation / record-type /
	# service / date contract. Such a match is adopted ONLY after its COMPLETE server
	# contract is retrieved and compared to the requested contract; a fingerprinted-name
	# match already encodes the contract and never reaches this path. The compare reuses
	# the deterministic fingerprint producer over the server fields, so it is stable and
	# order/case-insensitive in exactly the same way the created name is.
	$legacyDisplayName = New-GraphAuditPartitionDisplayName -PStart $PStart -PEnd $PEnd -Index $Index -Total $Total
	$requestedFingerprint = New-GraphAuditQueryFingerprint -PStart $PStart -PEnd $PEnd -Activities $Activities -RecordTypes $RecordTypes -ServiceFilter $ServiceFilter
	$serverContractFingerprint = {
		param($item)
		if ($null -eq $item) { return $null }
		$fsRaw = if ($item -is [hashtable]) { $item['filterStartDateTime'] } else { $item.filterStartDateTime }
		$feRaw = if ($item -is [hashtable]) { $item['filterEndDateTime'] } else { $item.filterEndDateTime }
		if ([string]::IsNullOrWhiteSpace([string]$fsRaw) -or [string]::IsNullOrWhiteSpace([string]$feRaw)) { return $null }
		$opsRaw = if ($item -is [hashtable]) { $item['operationFilters'] } else { $item.operationFilters }
		$rtRaw = if ($item -is [hashtable]) { $item['recordTypeFilters'] } else { $item.recordTypeFilters }
		$svcRaw = if ($item -is [hashtable]) { $item['serviceFilter'] } else { $item.serviceFilter }
		$styles = [System.Globalization.DateTimeStyles]::AdjustToUniversal -bor [System.Globalization.DateTimeStyles]::AssumeUniversal
		$fs = $null; $fe = $null
		try { $fs = [datetime]::Parse([string]$fsRaw, [System.Globalization.CultureInfo]::InvariantCulture, $styles) } catch { return $null }
		try { $fe = [datetime]::Parse([string]$feRaw, [System.Globalization.CultureInfo]::InvariantCulture, $styles) } catch { return $null }
		return New-GraphAuditQueryFingerprint -PStart $fs -PEnd $fe -Activities $opsRaw -RecordTypes $rtRaw -ServiceFilter $svcRaw
	}
	# Classify a legacy fingerprint-less same-name candidate set against the requested
	# contract. A candidate is adopted ONLY after its COMPLETE server contract is
	# retrieved and its deterministic fingerprint matches. A candidate whose contract
	# cannot be verified (missing filter fields with no fetch, a failed/throwing fetch,
	# or a malformed/incomplete fetched item) is never adopted and forces a fail-closed
	# outcome so an unverifiable candidate can never be duplicated by a fresh POST.
	# Returns @{ Outcome; Id; Category } where Outcome is None | Match | Mismatch |
	# Unresolved.
	$findLegacyContractMatch = {
		if (-not $ListQueries) { return @{ Outcome = 'None'; Id = $null; Category = $null } }
		$all = @(& $ListQueries)
		$legacy = @($all | Where-Object { $null -ne $_ -and [string]::Equals([string]$_.displayName, $legacyDisplayName, [System.StringComparison]::Ordinal) })
		if ($legacy.Count -eq 0) { return @{ Outcome = 'None'; Id = $null; Category = $null } }
		$matched = New-Object System.Collections.Generic.List[string]
		$anyUnverifiable = $false
		foreach ($q in $legacy) {
			$qid = if ($q -is [hashtable]) { $q['id'] } else { $q.id }
			$sfp = & $serverContractFingerprint $q
			if (-not $sfp -and $FetchItem) {
				# Read-only item fetch with a bounded retry consistent with the create
				# retry policy; a fetch that throws or never yields a complete contract
				# leaves the candidate unverifiable.
				$fetched = $null
				$fetchOk = $false
				for ($fa = 1; $fa -le 3; $fa++) {
					try { $fetched = & $FetchItem ([string]$qid); $fetchOk = $true; break }
					catch { $fetched = $null; $fetchOk = $false; if ($fa -lt 3) { & $Sleep 2 } }
				}
				if ($fetchOk) { $sfp = & $serverContractFingerprint $fetched }
			}
			if (-not $sfp) { $anyUnverifiable = $true; continue }
			if ([string]::Equals([string]$sfp, [string]$requestedFingerprint, [System.StringComparison]::Ordinal)) { $matched.Add([string]$qid) }
		}
		if ($anyUnverifiable) { return @{ Outcome = 'Unresolved'; Id = $null; Category = 'LegacyContractUnverified' } }
		if ($matched.Count -gt 1) { return @{ Outcome = 'Unresolved'; Id = $null; Category = 'MultipleExactMatches' } }
		if ($matched.Count -eq 1) { return @{ Outcome = 'Match'; Id = $matched[0]; Category = $null } }
		return @{ Outcome = 'Mismatch'; Id = $null; Category = $null }
	}

	# Pre-create reconciliation: before the first POST, adopt an already-present
	# query by exact name (zero POST), fail closed on multiple exact matches, and
	# fall through to the create POST only on an exact-name miss.
	if ($PreCreateReconcile -and $ListQueries) {
		$preExact = @(& $findExactByName)
		if ($preExact.Count -eq 1) {
			& $emit "[PRE-RECONCILE] Partition $Index/$Total - adopting existing query by exact name (no POST)"
			return & $new ([string]$preExact[0].id) 'None' $null $true
		}
		if ($preExact.Count -gt 1) {
			& $emit "[PRE-RECONCILE] Partition $Index/$Total - multiple exact-name matches - failing closed (no POST)"
			return & $new $null 'MultipleExactMatches' $null $false
		}
		# No fingerprinted-name match: consider a legacy fingerprint-less same-name query,
		# adopting ONLY after its full server contract is fetched and matches (no POST on a
		# contract mismatch, which falls through to a fresh create).
		$preLegacy = & $findLegacyContractMatch
		if ($preLegacy.Outcome -eq 'Match') {
			& $emit "[PRE-RECONCILE] Partition $Index/$Total - adopting legacy same-name query after contract match (no POST)"
			return & $new ([string]$preLegacy.Id) 'None' $null $true
		}
		if ($preLegacy.Outcome -eq 'Unresolved') {
			# A legacy same-name candidate exists but its full contract could not be
			# safely verified, or several candidates verify at once; fail closed with zero
			# POST so an unverified candidate is never duplicated by a fresh create.
			& $emit "[PRE-RECONCILE] Partition $Index/$Total - legacy same-name query could not be safely verified ($($preLegacy.Category)) - failing closed (no POST)"
			return & $new $null $preLegacy.Category $null $false
		}
		# Outcome None (no legacy candidate) or Mismatch (every candidate verified to a
		# different contract) falls through to exactly one fingerprinted create POST.
	}

	# Read-only reconcile-only mode: NEVER POST. Resolves a partition that carries durable
	# uncertain-create state (a possibly-accepted first POST) across a later attempt,
	# subdivision, or resume, so the create is never repeated. One exact fingerprinted-name
	# match is adopted (real id); multiple fail closed; none stays UncertainCreateUnresolved.
	# Never QueryConfirmedAbsent - a collection miss cannot prove the first POST was rejected.
	if ($ReconcileOnly) {
		if (-not $ListQueries) { return & $new $null 'UncertainCreateUnresolved' $null $false }
		$roExact = @(& $findExactByName)
		if ($roExact.Count -eq 1) {
			& $emit "[RECONCILE-ONLY] Partition $Index/$Total - uncertain create resolved by exact name (no POST)"
			return & $new ([string]$roExact[0].id) 'None' $null $true
		}
		if ($roExact.Count -gt 1) {
			& $emit "[RECONCILE-ONLY] Partition $Index/$Total - multiple exact-name matches - failing closed (no POST)"
			return & $new $null 'MultipleExactMatches' $null $false
		}
		& $emit "[RECONCILE-ONLY] Partition $Index/$Total - uncertain create still not visible - remains unresolved (no POST)"
		return & $new $null 'UncertainCreateUnresolved' $null $false
	}

	$createRetries = 0
	$max403Retries = 3
	$maxNetworkOutageSeconds = $MaxNetworkOutageMinutes * 60
	$networkErrorStart = $null

	while ($true) {
		$resp = & $Invoke $Version $bodyJson $clientRequestId
		$status = if ($resp) { $resp.HttpStatus } else { $null }
		$body = if ($resp) { [string]$resp.ResponseBody } else { $null }
		$headers = if ($resp) { $resp.Headers } else { $null }

		# Success.
		if ($null -ne $status -and $status -ge 200 -and $status -le 299) {
			$newId = if ($resp) { [string]$resp.Id } else { $null }
			return & $new $newId 'None' $status $false
		}

		# Classify. Network first, then 429, then 403, then ambiguous, then other.
		$isNetwork = $false
		if ($null -eq $status -or $status -eq 0 -or $status -ge 500) { $isNetwork = $true }
		if (-not $isNetwork -and $body -match 'timed out|connection|unable to connect|could not be resolved|Bad Gateway|Service Unavailable|Gateway Timeout|Internal Server Error') { $isNetwork = $true }

		$is429 = (-not $isNetwork) -and ($status -eq 429)
		$is403 = (-not $isNetwork) -and (-not $is429) -and ($status -eq 403)
		$isAmbiguous = (-not $isNetwork) -and (-not $is429) -and (-not $is403) -and ($status -eq 409)

		if ($is403) {
			$wwwAuth = $null
			$requestId = $null
			if ($headers) { try { $wwwAuth = [string]$headers['WWW-Authenticate'] } catch {} }
			if ($headers) { try { $requestId = [string]$headers['request-id'] } catch {} }
			$isPermanent = $false
			if ($body -match 'InsufficientPrivileges|Authorization_RequestDenied|AccessDenied|InvalidAuthenticationToken') { $isPermanent = $true }
			if ($wwwAuth -match 'claims') { $isPermanent = $true }
			& $emit "[403-DIAG] Partition $Index/$Total client-request-id: $clientRequestId permanent: $isPermanent"
			if ($isPermanent) {
				& $emit "[403-PERM] Partition $Index/$Total - permanent 403 (permissions/CAE) - failing"
				return & $new $null 'PermanentForbidden' $status $false $requestId $body
			}
			$createRetries++
			if ($createRetries -le $max403Retries) {
				$retryAfter = [Math]::Min(15 * [Math]::Pow(2, $createRetries - 1), 60)
				& $emit "[403-CREATE] Partition $Index/$Total - transient 403 (Attempt $createRetries/$max403Retries) - retrying in ${retryAfter}s"
				& $Sleep $retryAfter
				continue
			}
			& $emit "[403-PERSISTENT] Partition $Index/$Total - generic 403 persisted after all create retries"
			return & $new $null 'PersistentForbidden' $status $false $requestId $body
		}
		elseif ($is429) {
			$createRetries++
			$retryAfter = $null
			if ($headers) { try { if ($headers['Retry-After']) { $retryAfter = [int]$headers['Retry-After'] } } catch {} }
			if (-not $retryAfter) { $retryAfter = [Math]::Min(60 * [Math]::Pow(2, $createRetries - 1), 300) }
			& $emit "[THROTTLE] Partition $Index/$Total - throttled (Attempt $createRetries) - waiting ${retryAfter}s"
			& $Sleep $retryAfter
			if ($createRetries -ge 20) {
				& $emit "[THROTTLE-ABORT] Partition $Index/$Total - throttled after $createRetries attempts - aborting"
				return & $new $null 'ThrottleAbort' $status $false
			}
			continue
		}
		elseif ($isNetwork) {
			if (-not $networkErrorStart) {
				$networkErrorStart = Get-Date
				& $emit "[NETWORK] Partition $Index/$Total - uncertain create outcome (HTTP $status) - starting read-only reconcile window (max ${MaxNetworkOutageMinutes}m), no further POST"
			}
			# An uncertain create outcome (status 0/null, timeout, connection reset, or a
			# 5xx where acceptance cannot be disproven) may have been accepted by the
			# server, so the create is NEVER re-POSTed for this partition on this attempt.
			# Recovery is read-only: reconcile the fingerprinted exact name against the
			# fully-paginated collection until a single match appears (adopt), several
			# appear (fail closed), or the window expires with no match (fail closed as
			# unresolved). A collection miss cannot prove the POST was rejected, so it can
			# only fail closed - never issue another POST.
			if (-not $ListQueries) {
				& $emit "[NETWORK-UNRESOLVED] Partition $Index/$Total - no collection transport to reconcile an uncertain create - failing closed (no re-POST)"
				return & $new $null 'UncertainCreateUnresolved' $status $false
			}
			while ($true) {
				$netExact = @(& $findExactByName)
				if ($netExact.Count -eq 1) {
					& $emit "[NETWORK-RECONCILE] Partition $Index/$Total - uncertain create adopted by exact name (no re-POST)"
					return & $new ([string]$netExact[0].id) 'None' $status $true
				}
				if ($netExact.Count -gt 1) {
					& $emit "[NETWORK-RECONCILE] Partition $Index/$Total - multiple exact-name matches after uncertain create - failing closed"
					return & $new $null 'MultipleExactMatches' $status $false
				}
				$elapsedOutageSeconds = ((Get-Date) - $networkErrorStart).TotalSeconds
				if ($elapsedOutageSeconds -ge $maxNetworkOutageSeconds) {
					& $emit "[NETWORK-UNRESOLVED] Partition $Index/$Total - uncertain create not visible within $MaxNetworkOutageMinutes minute window - failing closed (no re-POST)"
					return & $new $null 'UncertainCreateUnresolved' $status $false
				}
				$retryDelay = 30 + (Get-Random -Minimum 10 -Maximum 30)
				& $emit "[NETWORK] Partition $Index/$Total - uncertain create not yet visible (${elapsedOutageSeconds}s elapsed) - re-listing after delay (no re-POST)"
				& $Sleep $retryDelay
			}
		}
		elseif ($isAmbiguous) {
			& $emit "[AMBIGUOUS] Partition $Index/$Total - ambiguous create response - reconciling by exact name"
			return & $reconcile $status
		}
		else {
			& $emit "[CREATE-FAILED] Partition $Index/$Total - non-retriable create failure (HTTP $status)"
			return & $new $null 'Other' $status $false
		}
	}
}

function Write-PaxCreatePoolHeartbeat {
	<#
	.SYNOPSIS
		Sanitized aggregate progress heartbeat for the bounded parent-create pool. Emits at
		most one line per interval and ONLY safe aggregate counts - never a QueryId, token,
		identifier, display name, operation name, URL, request body, or header.
	.DESCRIPTION
		Clock-driven and side-effect-minimal: given the pass start, the last-emit time, and
		the current time (all supplied by the caller's injectable now-provider) plus the
		interval, it emits one heartbeat line through the injected sink ONLY when at least a
		full interval has elapsed since the last emit, and returns the updated last-emit time.
		Before the first full interval nothing is emitted and the last-emit time is returned
		unchanged, so a pass that finishes quickly produces no heartbeat. It never touches the
		jobs, scheduling, throttle, timeout, token refresh, result order, checkpoint state, or
		POST count.
	.PARAMETER Start
		Wall-clock time the wait pass began (from the injectable now-provider).
	.PARAMETER LastEmit
		Time the previous heartbeat was emitted (Start when none yet).
	.PARAMETER Now
		Current time sample (from the injectable now-provider).
	.PARAMETER IntervalSeconds
		Minimum seconds between heartbeats; <= 0 disables emission.
	.PARAMETER Total / Completed / Active / Queued / Uncertain
		Safe aggregate partition counts for this pass.
	.PARAMETER Emit
		Injectable single-argument sink for the heartbeat line (defaults to Write-Host).
	.OUTPUTS
		The (possibly-updated) last-emit [datetime]; equal to -LastEmit when nothing was emitted.
	#>
	param(
		[Parameter(Mandatory)][datetime]$Start,
		[Parameter(Mandatory)][datetime]$LastEmit,
		[Parameter(Mandatory)][datetime]$Now,
		[Parameter(Mandatory)][int]$IntervalSeconds,
		[Parameter()][int]$Total = 0,
		[Parameter()][int]$Completed = 0,
		[Parameter()][int]$Active = 0,
		[Parameter()][int]$Queued = 0,
		[Parameter()][int]$Uncertain = 0,
		[Parameter()][scriptblock]$Emit = $null
	)
	if ($IntervalSeconds -le 0) { return $LastEmit }
	if (($Now - $LastEmit).TotalSeconds -lt $IntervalSeconds) { return $LastEmit }
	$elapsedSeconds = [int][Math]::Floor(($Now - $Start).TotalSeconds)
	if ($elapsedSeconds -lt 0) { $elapsedSeconds = 0 }
	$elapsedText = if ($elapsedSeconds -ge 60) { "$([int][Math]::Floor($elapsedSeconds / 60))m" } else { "$($elapsedSeconds)s" }
	# 'localQueued' is the count still waiting in THIS pool, and 'pending' is everything
	# not yet finished. Wording only: the counts, the pass, and the work are unchanged.
	$pendingCount = $Active + $Queued
	$message = "  [PARENT-CREATE] $elapsedText elapsed | total $Total | completed $Completed | active $Active | localQueued $Queued | pending $pendingCount"
	if ($Uncertain -gt 0) { $message += " | uncertain $Uncertain" }
	if ($Emit) { & $Emit $message } else { Write-Host $message -ForegroundColor DarkCyan }
	return $Now
}

function Invoke-PaxBoundedCreatePool {
	<#
	.SYNOPSIS
		Bounded-parallel executor for parent-scope partition query creation.
	.DESCRIPTION
		Runs Invoke-GraphAuditHardenedCreate for each supplied partition inside
		isolated ThreadJob runspaces under a fixed concurrency cap. Because a
		ThreadJob runspace does not inherit parent-scope functions or variables, the
		create functions, version constants, and HTTP transport are injected as
		text/arguments into every runspace. The transport is injected via
		-TransportText so the same executor serves production (a real HTTP POST) and
		validation (a runspace-local mock). The concurrency cap is passed straight to
		Start-ThreadJob -ThrottleLimit, so the supplied bound is never exceeded.
		Returns one result object per partition:
		@{ Index; QueryId; Version; FailureCategory; HttpStatus }.
	.PARAMETER Items
		Partition-shaped objects carrying Index, Total, PStart, PEnd, Activities,
		RecordTypes, ServiceFilter.
	.PARAMETER ThrottleLimit
		Maximum number of concurrent create runspaces.
	.PARAMETER TransportText
		Text of the injected transport scriptblock: param($Version,$BodyJson,
		$ClientRequestId) returning @{ HttpStatus; Id; ResponseBody; Headers }.
	.PARAMETER FunctionTexts
		Verbatim function definitions dot-sourced into each runspace.
	.PARAMETER InjectVariables
		Name/value pairs set at script scope inside each runspace (version constants,
		token material).
	.PARAMETER ListTransportText
		Optional text of an injected collection-list scriptblock: returns the
		fully-paginated array of @{ id; displayName } for exact-name reconciliation.
		When supplied, every create routes through exact-name lookup before and around
		its POST; when omitted, the executor behaves as a plain create pool.
	.PARAMETER FetchTransportText
		Optional text of an injected item-fetch scriptblock: param($QueryId) returning
		the query item with its filter contract, so a legacy fingerprint-less same-name
		match can be adopted ONLY after its full server contract is fetched and matched.
	.PARAMETER TokenRefresh
		Optional parent-scope scriptblock invoked periodically WHILE the create jobs run
		so a token nearing expiry is refreshed on the shared auth reference mid-pool.
		Because the shared auth state is a synchronized hashtable, a refresh landing here
		is observed by an already-started retrying create job before its next request.
		Defaults to Refresh-GraphTokenIfNeeded; pass an injected refresher for validation.
	#>
	param(
		[Parameter(Mandatory)]$Items,
		[Parameter(Mandatory)][int]$ThrottleLimit,
		[Parameter(Mandatory)][string]$TransportText,
		[Parameter()][string[]]$FunctionTexts = @(),
		[Parameter()][hashtable]$InjectVariables = @{},
		[Parameter()][string]$ListTransportText = $null,
		[Parameter()][string]$FetchTransportText = $null,
		[Parameter()][scriptblock]$TokenRefresh = $null,
		[Parameter()][int]$MaxNetworkOutageMinutes = 30,
		[Parameter()][int]$HeartbeatIntervalSeconds = 60,
		[Parameter()][scriptblock]$NowProvider = $null,
		[Parameter()][scriptblock]$HeartbeatEmit = $null
	)
	if ($ThrottleLimit -lt 1) { $ThrottleLimit = 1 }
	# Injectable clock + emit sink for the create-pool progress heartbeat. Production uses the
	# wall clock and the run log/host; validation injects a synthetic clock + collector so the
	# heartbeat is exercised deterministically without waiting a real interval. Neither affects
	# scheduling, throttle, timeout, token refresh, result order, checkpoint state, or POST count.
	if (-not $NowProvider) { $NowProvider = { Get-Date } }
	if (-not $HeartbeatEmit) {
		$HeartbeatEmit = {
			param($HeartbeatMessage)
			if (Get-Command -Name Write-LogHost -ErrorAction SilentlyContinue) { Write-LogHost $HeartbeatMessage -ForegroundColor DarkCyan }
			else { Write-Host $HeartbeatMessage -ForegroundColor DarkCyan }
		}
	}
	# Synchronized per-partition PHASE MARKER shared into every worker runspace by
	# reference (like the shared auth state). It lets an interrupted pool tell a
	# ThreadJob that never began (provably no create POST) apart from one whose create
	# POST was in flight, so a never-started partition is never conflated with a
	# started-but-unknown one. Keyed by partition Index; a missing entry means the
	# worker never ran.
	$phaseMap = [hashtable]::Synchronized(@{})
	$poolWorker = {
		param($it, $fnTexts, $vars, $transportText, $listTransportText, $fetchTransportText, $outageMin, $phaseMap)
		# First worker action: record that this partition's worker actually began. A
		# missing phase entry at the interrupt therefore proves the ThreadJob never
		# started and no create POST could have been sent.
		if ($phaseMap) { $phaseMap[$it.Index] = 'Started' }
		foreach ($ft in $fnTexts) { . ([scriptblock]::Create($ft)) }
		if ($vars) { foreach ($vk in $vars.Keys) { Set-Variable -Name $vk -Value $vars[$vk] -Scope Script } }
		$rawTransport = [scriptblock]::Create($transportText)
		# Wrap the injected create transport so a 'PostInFlight' marker is set IMMEDIATELY
		# BEFORE the real create POST and 'PostReturned' AFTER the response. ThreadJob
		# 'Running' alone does not prove a POST started - only this marker does. The marker
		# is set conservatively (before the call), so a worker stopped around its POST
		# classifies as outcome-unknown, never as never-started.
		$transport = {
			param($Version, $BodyJson, $ClientRequestId)
			if ($phaseMap) { $phaseMap[$it.Index] = 'PostInFlight' }
			try { return (& $rawTransport $Version $BodyJson $ClientRequestId) }
			finally { if ($phaseMap) { $phaseMap[$it.Index] = 'PostReturned' } }
		}.GetNewClosure()
		# Injected alongside the create transport so every create routes through
		# exact-name reconciliation before and around its POST (adopt one, fail closed
		# on many, POST only on a miss).
		$listQueries = if ($listTransportText) { [scriptblock]::Create($listTransportText) } else { $null }
		# Item-fetch transport: retrieves a query's full contract so a legacy
		# fingerprint-less same-name match is adopted only after a contract compare.
		$fetchItem = if ($fetchTransportText) { [scriptblock]::Create($fetchTransportText) } else { $null }
		$res = Invoke-GraphAuditHardenedCreate -PStart $it.PStart -PEnd $it.PEnd -Index $it.Index -Total $it.Total -Activities $it.Activities -RecordTypes $it.RecordTypes -ServiceFilter $it.ServiceFilter -Invoke $transport -ListQueries $listQueries -PreCreateReconcile:([bool]$listQueries) -FetchItem $fetchItem -MaxNetworkOutageMinutes $outageMin
		# Per-partition EXECUTION STATE for a COMPLETED worker, mirroring the parent's
		# own create classification exactly: a proven QueryId is a create; an
		# unproven-acceptance outcome stays outcome-unknown (durable uncertain); every
		# other completion is a determinable failure that provably produced no query.
		$execState = if ($res.QueryId) { 'CompletedWithQueryId' } elseif ([string]$res.FailureCategory -eq 'UncertainCreateUnresolved') { 'StartedOutcomeUnknown' } else { 'CompletedFailureBeforePOST' }
		[pscustomobject]@{
			Index           = $it.Index
			QueryId         = $res.QueryId
			Version         = $res.Version
			FailureCategory = $res.FailureCategory
			HttpStatus      = $res.HttpStatus
			ExecutionState  = $execState
			ClientRequestId = $res.ClientRequestId
			RequestId       = $res.RequestId
			ResponseBody    = $res.ResponseBody
		}
	}
	$poolJobs = @()
	$poolJobIndex = @()
	foreach ($item in $Items) {
		$poolJobs += Start-ThreadJob -ThrottleLimit $ThrottleLimit -ScriptBlock $poolWorker -ArgumentList $item, $FunctionTexts, $InjectVariables, $TransportText, $ListTransportText, $FetchTransportText, $MaxNetworkOutageMinutes, $phaseMap
		$poolJobIndex += $item.Index
	}
	# Token monitoring during a prolonged create pass: while any create job is still
	# running, invoke the token refresher periodically instead of blocking on a single
	# Wait-Job. Because the shared auth state is a synchronized hashtable, a refresh
	# landing here is visible to an already-started retrying create job BEFORE its next
	# request - so a job that started under a token that later neared expiry can still
	# observe a fresh token mid-retry, not only jobs launched after a pre-pass refresh.
	# A token refresher can signal an interactive quit ('Quit') or throw. Either outcome
	# fails the pool closed: no further create work is awaited as success, still-active
	# jobs are stopped, only already-completed job results are collected, and a sentinel
	# row carries the quit/error decision back to the caller so the parent orchestration
	# can enter its graceful authentication-exit path instead of silently reporting
	# success.
	$authQuit = $false
	$refresherError = $null
	if ($poolJobs.Count -gt 0) {
		if ($TokenRefresh) {
			# Sanitized aggregate progress heartbeat: at most one line per interval while the
			# create pool is still active, emitting ONLY safe aggregate counts (elapsed, total,
			# completed, active, queued) - never a QueryId, token, identifier, name, URL, or
			# body. The clock and interval are injectable so the emit is exercised without a
			# real wait; the heartbeat never changes scheduling, throttle, timeout, token
			# refresh, result order, checkpoint behaviour, or POST count.
			$hbStart = & $NowProvider
			$hbLastEmit = $hbStart
			while (@($poolJobs | Where-Object { $_.State -in 'Running', 'NotStarted' }).Count -gt 0) {
				$refreshOutcome = $null
				try { $refreshOutcome = & $TokenRefresh } catch { $refresherError = $_.Exception.Message; break }
				if ($refreshOutcome -is [string] -and $refreshOutcome -eq 'Quit') { $authQuit = $true; break }
				$null = $poolJobs | Wait-Job -Timeout 5
				$hbCompleted = @($poolJobs | Where-Object { $_.State -in 'Completed', 'Failed', 'Stopped' }).Count
				$hbActive = @($poolJobs | Where-Object { $_.State -eq 'Running' }).Count
				$hbQueued = @($poolJobs | Where-Object { $_.State -eq 'NotStarted' }).Count
				if (Get-Command Write-PaxCreatePoolHeartbeat -ErrorAction SilentlyContinue) {
					$hbLastEmit = Write-PaxCreatePoolHeartbeat -Start $hbStart -LastEmit $hbLastEmit -Now (& $NowProvider) -IntervalSeconds $HeartbeatIntervalSeconds -Total $poolJobs.Count -Completed $hbCompleted -Active $hbActive -Queued $hbQueued -Emit $HeartbeatEmit
				}
			}
			if (-not $authQuit -and -not $refresherError) {
				try { $finalOutcome = & $TokenRefresh; if ($finalOutcome -is [string] -and $finalOutcome -eq 'Quit') { $authQuit = $true } } catch { $refresherError = $_.Exception.Message }
			}
		}
		else {
			$null = $poolJobs | Wait-Job
		}
	}
	if ($authQuit -or $refresherError) {
		$stillActive = @($poolJobs | Where-Object { $_.State -in 'Running', 'NotStarted' })
		if ($stillActive.Count -gt 0) { $stillActive | Stop-Job -ErrorAction SilentlyContinue }
		$poolResults = @()
		foreach ($pj in $poolJobs) { if ($pj.State -eq 'Completed') { try { $poolResults += Receive-Job -Job $pj -ErrorAction SilentlyContinue } catch {} } }
		if ($poolJobs.Count -gt 0) { $poolJobs | Remove-Job -Force -ErrorAction SilentlyContinue }
		# Emit a per-partition row for every requested job that did NOT complete, using the
		# shared phase marker to distinguish a never-started worker (no phase entry, or only
		# 'Started' - provably no create POST) from one whose create POST was in flight
		# ('PostInFlight'/'PostReturned' - outcome unknown). This prevents the interrupt path
		# from conflating never-started partitions with started-but-unknown ones.
		$completedIdx = New-Object System.Collections.Generic.HashSet[string]
		foreach ($pr in $poolResults) { if ($null -ne $pr -and $null -ne $pr.Index) { $null = $completedIdx.Add([string]$pr.Index) } }
		foreach ($ji in $poolJobIndex) {
			if ($completedIdx.Contains([string]$ji)) { continue }
			$ph = $null
			if ($phaseMap -and $phaseMap.ContainsKey($ji)) { $ph = [string]$phaseMap[$ji] }
			$execState = if ($ph -eq 'PostInFlight' -or $ph -eq 'PostReturned') { 'StartedOutcomeUnknown' } else { 'NeverStarted' }
			$poolResults += [pscustomobject]@{ Index = $ji; QueryId = $null; Version = $null; FailureCategory = 'Interrupted'; HttpStatus = $null; ExecutionState = $execState }
		}
		$poolResults += [pscustomobject]@{ Index = $null; QueryId = $null; Version = $null; FailureCategory = $(if ($authQuit) { 'AuthQuit' } else { 'TokenRefreshError' }); HttpStatus = $null; AuthQuit = $authQuit; RefresherError = $refresherError }
		return $poolResults
	}
	$poolResults = @()
	foreach ($pj in $poolJobs) {
		try { $poolResults += Receive-Job -Job $pj -ErrorAction SilentlyContinue } catch {}
	}
	if ($poolJobs.Count -gt 0) { $poolJobs | Remove-Job -Force -ErrorAction SilentlyContinue }
	return $poolResults
}

function Invoke-PaxParentQueryCreation {
	<#
	.SYNOPSIS
		Parent-side bounded-parallel pre-pass that creates the audit query for each
		pending partition before its worker is launched.
	.DESCRIPTION
		For every supplied partition this creates the query in the main runspace,
		where the token can be refreshed, under the same concurrency bound used for
		worker launch. Creation runs through an injectable runner: production uses a
		real bounded ThreadJob pool (Invoke-PaxBoundedCreatePool) with the parent
		create functions and a real HTTP transport injected into each runspace, while
		validation supplies its own runner with an injected transport. Returns an
		index-keyed result map:
		@{ <Index> = @{ Index; QueryId; Version; FailureCategory; HttpStatus } }.
		Persistence and worker wiring stay with the caller: a successful entry carries
		a non-null QueryId to store and checkpoint before launch; a failed entry
		carries a null QueryId and must not launch a worker.
	.PARAMETER Partitions
		Partition objects needing creation (each with Index, Total, PStart, PEnd,
		RecordTypes, ServiceFilter).
	.PARAMETER ThrottleLimit
		Concurrency bound reused from the launch phase.
	.PARAMETER Activities
		Run-level activity list applied to every create body.
	.PARAMETER Runner
		Optional injected runner: param($Items,$Throttle,$OutageMinutes) returning the
		per-partition result objects. When omitted a production bounded ThreadJob pool
		is used.
	#>
	param(
		[Parameter(Mandatory)]$Partitions,
		[Parameter(Mandatory)][int]$ThrottleLimit,
		[Parameter()]$Activities = @(),
		[Parameter()][int]$MaxNetworkOutageMinutes = 30,
		[Parameter()][scriptblock]$Runner = $null
	)
	$items = @()
	foreach ($p in $Partitions) {
		$items += [pscustomobject]@{
			Index         = $p.Index
			Total         = $p.Total
			PStart        = $p.PStart
			PEnd          = $p.PEnd
			Activities    = $Activities
			RecordTypes   = $p.RecordTypes
			ServiceFilter = $p.ServiceFilter
		}
	}
	if (-not $Runner) {
		$Runner = {
			param($RunnerItems, $RunnerThrottle, $RunnerOutage)
			$fnTexts = @(
				"function New-GraphAuditQueryFingerprint {`n$(${function:New-GraphAuditQueryFingerprint})`n}",
				"function New-GraphAuditPartitionDisplayName {`n$(${function:New-GraphAuditPartitionDisplayName})`n}",
				"function New-GraphAuditQueryRequest {`n$(${function:New-GraphAuditQueryRequest})`n}",
				"function Resolve-GraphAuditDuplicateSafeQuery {`n$(${function:Resolve-GraphAuditDuplicateSafeQuery})`n}",
				"function Invoke-GraphAuditHardenedCreate {`n$(${function:Invoke-GraphAuditHardenedCreate})`n}"
			)
			$vars = @{
				GraphAuditApiVersion_Previous = $script:GraphAuditApiVersion_Previous
				GraphAuditApiVersion_Current  = $script:GraphAuditApiVersion_Current
				PaxSharedAuthState            = $script:SharedAuthState
			}
			$transportText = @'
param($Version, $BodyJson, $ClientRequestId)
$uri = "https://graph.microsoft.com/$Version/security/auditLog/queries"
$headers = @{ Authorization = "Bearer $($script:PaxSharedAuthState.Token)"; 'Content-Type' = 'application/json' }
if ($ClientRequestId) { $headers['client-request-id'] = $ClientRequestId }
try {
	$r = Invoke-WebRequest -Method POST -Uri $uri -Headers $headers -Body $BodyJson -ErrorAction Stop
	$obj = $null; try { $obj = $r.Content | ConvertFrom-Json } catch {}
	return @{ HttpStatus = [int]$r.StatusCode; Id = $obj.id; ResponseBody = $r.Content; Headers = $r.Headers }
} catch {
	$resp = $_.Exception.Response
	$code = 0; $body = $_.Exception.Message; $rh = @{}
	if ($resp) {
		try { $code = [int]$resp.StatusCode } catch {}
		try { $sr = New-Object System.IO.StreamReader($resp.GetResponseStream()); $body = $sr.ReadToEnd() } catch {}
		try { foreach ($hn in $resp.Headers) { $rh[$hn] = $resp.Headers[$hn] } } catch {}
	}
	return @{ HttpStatus = $code; Id = $null; ResponseBody = $body; Headers = $rh }
}
'@
			# Fully-paginated exact-name collection transport. Reads the live token from
			# the shared auth state so a token refreshed by the parent is picked up by
			# queued and retrying create jobs, and walks every page of the audit-query
			# collection so exact-name reconciliation sees the full server state.
			$listTransportText = @'
$__lver = $script:GraphAuditApiVersion_Previous
$__luri = "https://graph.microsoft.com/$__lver/security/auditLog/queries"
$__acc = @()
while ($__luri) {
	$__lheaders = @{ Authorization = "Bearer $($script:PaxSharedAuthState.Token)" }
	$__lr = Invoke-WebRequest -Method GET -Uri $__luri -Headers $__lheaders -ErrorAction Stop
	$__lobj = $null; try { $__lobj = $__lr.Content | ConvertFrom-Json } catch {}
	if ($__lobj -and $__lobj.value) { foreach ($__q in $__lobj.value) { $__acc += @{ id = $__q.id; displayName = $__q.displayName } } }
	$__luri = if ($__lobj) { $__lobj.'@odata.nextLink' } else { $null }
}
, @($__acc)
'@
			# Single-item fetch transport. Retrieves a query's full filter contract so a
			# legacy fingerprint-less same-name match is adopted only after its server
			# contract matches the requested one. Reads the live shared-auth token.
			$fetchTransportText = @'
param($QueryId)
$__fver = $script:GraphAuditApiVersion_Previous
$__furi = "https://graph.microsoft.com/$__fver/security/auditLog/queries/$QueryId"
$__fheaders = @{ Authorization = "Bearer $($script:PaxSharedAuthState.Token)" }
try {
	$__fr = Invoke-WebRequest -Method GET -Uri $__furi -Headers $__fheaders -ErrorAction Stop
	$__fobj = $null; try { $__fobj = $__fr.Content | ConvertFrom-Json } catch {}
	return $__fobj
} catch { return $null }
'@
			# Refresh the shared-auth token WHILE the create jobs run so an already-started
			# retrying job observes a fresh token before its next request. The refresher
			# outcome (including an interactive 'Quit' or a thrown error) is propagated so
			# the pool can fail closed instead of discarding a quit decision.
			$tokenRefresh = { Refresh-GraphTokenIfNeeded -BufferMinutes 5 }
			Invoke-PaxBoundedCreatePool -Items $RunnerItems -ThrottleLimit $RunnerThrottle -TransportText $transportText -FunctionTexts $fnTexts -InjectVariables $vars -ListTransportText $listTransportText -FetchTransportText $fetchTransportText -TokenRefresh $tokenRefresh -MaxNetworkOutageMinutes $RunnerOutage
		}
	}
	$results = @(& $Runner $items $ThrottleLimit $MaxNetworkOutageMinutes)
	$map = @{}
	foreach ($r in $results) {
		if ($null -ne $r) {
			# A pool that failed closed on an interactive quit or a token-refresh error
			# returns a sentinel row instead of a partition result; surface it under a
			# reserved key so the caller enters its graceful authentication-exit path and
			# never persists a partition as created off a quit/error decision.
			$isQuit = if ($r -is [hashtable]) { [bool]$r['AuthQuit'] } else { [bool]$r.AuthQuit }
			$rerr = if ($r -is [hashtable]) { $r['RefresherError'] } else { $r.RefresherError }
			if ($isQuit) { $map['__AuthQuit'] = $true; continue }
			if ($rerr) { $map['__RefresherError'] = [string]$rerr; continue }
			$idx = if ($r -is [hashtable]) { $r['Index'] } else { $r.Index }
			if ($null -ne $idx) { $map[[int]$idx] = $r }
		}
	}
	return $map
}

function Save-PaxInterruptedCreatePool {
	<#
	.SYNOPSIS
		On a create-pool auth-quit / refresher-error interrupt, durably persist the
		partitions the pool actually completed AND the partitions still in flight,
		BEFORE the graceful exit.
	.DESCRIPTION
		Invoke-PaxBoundedCreatePool returns the results of jobs that completed BEFORE
		the interrupt as integer-keyed entries in the map, alongside the reserved
		__AuthQuit / __RefresherError sentinel. Discarding that map on the interrupt
		would (a) throw away a query that was actually created (forcing a duplicate
		create on resume) and (b) leave a possibly-accepted in-flight POST unrecorded.

		This helper reconciles the interrupt map against the list of partitions the
		pass requested ($Requested):

		  * A requested partition whose map entry carries a real QueryId is persisted
		    via the SAME success path a normal completion uses (status QueryId +
		    effective QueryApiVersion + Create operation + a QueryCreated checkpoint).
		  * A partition whose worker never began (ExecutionState 'NeverStarted' -
		    provably no create POST was ever issued) is left untouched so a resume
		    creates it fresh; it is NEVER persisted as UncertainCreate. This is the
		    correction for conflating never-started jobs with started-but-unknown ones.
		  * A partition whose worker completed with a determinable non-accepting failure
		    (ExecutionState 'CompletedFailureBeforePOST') is recorded via
		    Set-PartitionFailure, matching the normal-completion classification.
		  * Every OTHER requested partition was still in flight at the interrupt
		    (ExecutionState 'StartedOutcomeUnknown', or a legacy map entry with no
		    ExecutionState) and is persisted as durable UncertainCreate, so a resume
		    routes it to a READ-ONLY reconcile instead of a duplicate create.

		A stopped / incomplete job is NEVER persisted as successful: only a map entry
		with a non-null QueryId is treated as completed.
	#>
	param(
		[Parameter(Mandatory)]$CreateMap,
		[Parameter(Mandatory)]$Requested,
		[Parameter()]$Activities = @(),
		[Parameter(Mandatory)][ValidateSet('initial', 'retry')][string]$Phase
	)
	$phaseTag = if ($Phase -eq 'retry') { 'retry ' } else { '' }
	$completedIndices = [System.Collections.Generic.HashSet[int]]::new()
	# 1) Persist every partition the pool actually completed (has a real QueryId).
	foreach ($cp in $Requested) {
		$cr = $CreateMap[[int]$cp.Index]
		if ($cr -and $cr.QueryId) {
			$cp | Add-Member -NotePropertyName 'StoredQueryId' -NotePropertyValue ([string]$cr.QueryId) -Force
			$script:partitionStatus[$cp.Index].QueryId = [string]$cr.QueryId
			$script:partitionStatus[$cp.Index].QueryApiVersion = $cr.Version
			$script:partitionStatus[$cp.Index].LifecycleOperation = 'Create'
			if ($script:CheckpointEnabled) {
				Save-Checkpoint -PartitionIndex $cp.Index -QueryId ([string]$cr.QueryId) -State 'QueryCreated' -PartitionStart $cp.PStart -PartitionEnd $cp.PEnd -LifecycleState $script:partitionStatus[$cp.Index]
			}
			[void]$completedIndices.Add([int]$cp.Index)
			Write-LogHost "  [PARENT-CREATE] Partition $($cp.Index)/$($cp.Total) query created before ${phaseTag}interrupt (QueryId: $($cr.QueryId)) - persisted, not discarded" -ForegroundColor DarkCyan
		}
	}
	# 2) Persist the remaining requested partitions by execution state: never-started
	#    stays fresh (no create POST happened), a determinable failure is recorded as a
	#    failure, and only a genuinely in-flight partition becomes durable UncertainCreate.
	foreach ($cp in $Requested) {
		if ($completedIndices.Contains([int]$cp.Index)) { continue }
		$cr = $CreateMap[[int]$cp.Index]
		$execState = if ($cr) { [string]$cr.ExecutionState } else { '' }
		if ($execState -eq 'NeverStarted') {
			Write-LogHost "  [PARENT-CREATE] Partition $($cp.Index)/$($cp.Total) never started before ${phaseTag}interrupt - no create POST issued, left fresh for create on resume" -ForegroundColor DarkGray
			continue
		}
		if ($execState -eq 'CompletedFailureBeforePOST') {
			Set-PartitionFailure -Index $cp.Index -Stage 'CREATE' -Reason ([string]$cr.FailureCategory)
			Write-LogHost "  [PARENT-CREATE] Partition $($cp.Index)/$($cp.Total) failed before ${phaseTag}interrupt (no query created) - recorded as failure" -ForegroundColor DarkYellow
			continue
		}
		$script:partitionStatus[$cp.Index].UncertainCreate = $true
		$script:partitionStatus[$cp.Index].UncertainCreateInfo = @{
			displayName = New-GraphAuditPartitionDisplayName -PStart $cp.PStart -PEnd $cp.PEnd -Index $cp.Index -Total $cp.Total -Activities $Activities -RecordTypes $cp.RecordTypes -ServiceFilter $cp.ServiceFilter
			fingerprint = New-GraphAuditQueryFingerprint -PStart $cp.PStart -PEnd $cp.PEnd -Activities $Activities -RecordTypes $cp.RecordTypes -ServiceFilter $cp.ServiceFilter
			pStart      = $cp.PStart.ToString('o')
			pEnd        = $cp.PEnd.ToString('o')
			attempt     = [int]$script:partitionStatus[$cp.Index].AttemptNumber
			phase       = $Phase
		}
		$script:partitionStatus[$cp.Index].LastError = "Parent-side query creation in-flight at ${phaseTag}interrupt - durable reconcile pending"
		if ($script:CheckpointEnabled) {
			Save-Checkpoint -PartitionIndex $cp.Index -State 'UncertainCreate' -PartitionStart $cp.PStart -PartitionEnd $cp.PEnd -LifecycleState $script:partitionStatus[$cp.Index]
		}
		Write-LogHost "  [PARENT-CREATE] Partition $($cp.Index)/$($cp.Total) in flight at ${phaseTag}interrupt - persisted for read-only reconcile, no re-POST" -ForegroundColor Yellow
	}
}

function Invoke-PaxResumeUncertainReconcile {
	<#
	.SYNOPSIS
		Resume-side READ-ONLY reconcile of durable uncertain-create partitions (never a POST).
	.DESCRIPTION
		Consumes the ToReconcileOnly bucket produced by Get-PartitionsToProcess on a
		resume. Each such partition carries durable uncertain-create state: a first
		create POST that MAY have been accepted but was never proven. In the MAIN
		runspace (where the token can refresh) this runs a READ-ONLY exact-name
		reconcile via Invoke-GraphAuditHardenedCreate -ReconcileOnly against the
		fully-paginated audit-query collection - it NEVER issues a POST.

		Per partition:
		  * exactly one exact fingerprinted-name match -> ADOPT: store the real QueryId,
		    checkpoint it as QueryCreated, vacate the durable uncertain entry, and route
		    the partition to fetch-only;
		  * multiple exact matches                     -> FAIL CLOSED: no adopt, no POST,
		    the durable uncertain entry is preserved for an operator decision;
		  * none after the bounded collection window   -> REMAIN UNCERTAIN: no adopt, no
		    POST, never QueryConfirmedAbsent, the durable uncertain entry is preserved.
		Only adopted partitions are returned for launch; unresolved and fail-closed
		partitions are deliberately withheld, so no worker is launched for an unresolved
		uncertain create (worker-launch gating).

		The identity is recomputed from the partition's contract (operation / record-type
		/ service / date), so a differing contract yields a different name and can never
		cross-adopt a different query. Transports are injectable: production builds a real
		fully-paginated GET collection and a single-item fetch that read the live
		shared-auth token; validation injects list / fetch / invoke scriptblocks.
	.PARAMETER Partitions
		The ToReconcileOnly partition objects (each with Index, Total, PStart, PEnd,
		RecordTypes, ServiceFilter, UncertainCreateState).
	.PARAMETER Activities
		Run-level activity list applied to the reconciled contract identity.
	.PARAMETER ListQueries
		Optional injected fully-paginated collection transport (-> array of
		@{ id; displayName }). Omitted in production to build the real transport.
	.PARAMETER FetchItem
		Optional injected single-item fetch transport for legacy contract verification.
	.PARAMETER Invoke
		Optional injected transport required by the shared Invoke-GraphAuditHardenedCreate
		signature; it is NEVER called in reconcile-only mode (a fail-closed no-op default).
	.PARAMETER Persist
		Optional callback param($PartitionIndex,$QueryId,$PStart,$PEnd,$Fingerprint) used to
		persist an adopted partition with its EXACT reconciled contract fingerprint.

		CONTRACT (fail-closed): the callback MUST stage the complete bucket transition and
		publish it durably, then return the literal boolean $true as its LAST output to signal a
		PROVEN durable publication - or throw. Any other outcome (no output, $null, $false, a
		non-boolean value) is treated as a FAILED publication: the pre-adoption in-memory state
		is restored exactly, the partition is NOT adopted and NOT routed to fetch-only, no POST
		is authorized, $script:GenericFatal is latched, and a PAX-FATAL error is thrown. The
		default callback stages the transition in memory only (Save-Checkpoint -DeferDiskWrite)
		and publishes it EXACTLY ONCE through the strict local+Fabric transaction
		(Save-CheckpointStrict), whose verify-after-write result is returned; the warning-only
		Save-CheckpointToDisk path is deliberately never used here because a swallowed local
		write failure would let the run proceed as though the adoption were durable.
	.PARAMETER Log
		Optional diagnostic sink param($Message).
	.OUTPUTS
		@{ AdoptedFetchOnly = @(); Unresolved = @(); FailedClosed = @() }
	#>
	param(
		[Parameter(Mandatory)]$Partitions,
		[Parameter()]$Activities = @(),
		[Parameter()][scriptblock]$ListQueries = $null,
		[Parameter()][scriptblock]$FetchItem = $null,
		[Parameter()][scriptblock]$Invoke = $null,
		[Parameter()][scriptblock]$Persist = $null,
		[Parameter()][scriptblock]$Log = $null
	)
	$emit = { param($m) if ($Log) { & $Log $m } }
	$result = @{ AdoptedFetchOnly = @(); Unresolved = @(); FailedClosed = @() }
	if (-not $Partitions -or @($Partitions).Count -eq 0) { return $result }

	# Reconcile-only NEVER posts; this default transport fails closed if ever reached.
	if (-not $Invoke) { $Invoke = { param($v, $b, $c) @{ HttpStatus = 0; Id = $null; ResponseBody = 'reconcile-only-no-post'; Headers = @{} } } }

	# Production list / fetch transports: a fully-paginated exact-name collection and a
	# single-item contract fetch, both reading the live shared-auth token so a parent
	# token refresh is observed. Injected transports (validation) take precedence.
	if (-not $ListQueries) {
		$ListQueries = {
			$__lver = $script:GraphAuditApiVersion_Previous
			$__luri = "https://graph.microsoft.com/$__lver/security/auditLog/queries"
			$__acc = @()
			while ($__luri) {
				$__lheaders = @{ Authorization = "Bearer $($script:SharedAuthState.Token)" }
				$__lr = Invoke-WebRequest -Method GET -Uri $__luri -Headers $__lheaders -ErrorAction Stop
				$__lobj = $null; try { $__lobj = $__lr.Content | ConvertFrom-Json } catch {}
				if ($__lobj -and $__lobj.value) { foreach ($__q in $__lobj.value) { $__acc += @{ id = $__q.id; displayName = $__q.displayName } } }
				$__luri = if ($__lobj) { $__lobj.'@odata.nextLink' } else { $null }
			}
			, @($__acc)
		}
	}
	if (-not $FetchItem) {
		$FetchItem = {
			param($QueryId)
			$__fver = $script:GraphAuditApiVersion_Previous
			$__furi = "https://graph.microsoft.com/$__fver/security/auditLog/queries/$QueryId"
			$__fheaders = @{ Authorization = "Bearer $($script:SharedAuthState.Token)" }
			try {
				$__fr = Invoke-WebRequest -Method GET -Uri $__furi -Headers $__fheaders -ErrorAction Stop
				$__fobj = $null; try { $__fobj = $__fr.Content | ConvertFrom-Json } catch {}
				return $__fobj
			} catch { return $null }
		}
	}
	if (-not $Persist) {
		$Persist = {
			param($PartitionIndex, $QueryId, $PStart, $PEnd, $Fingerprint)
			# Adoption persists the proven QueryId with the EXACT reconciled contract fingerprint so
			# the queryCreated entry preserves per-contract identity even when this runs BEFORE
			# $script:partitionStatus is initialized on resume (Save-Checkpoint cannot re-derive the
			# fingerprint from partitionStatus at that point). A legacy fingerprint-less contract
			# passes no fingerprint and retains the historical index identity.
			#
			# The bucket transition is staged IN MEMORY ONLY (-DeferDiskWrite) and then published
			# EXACTLY ONCE through the STRICT verify-after-write local+Fabric transaction, so the
			# adoption can only affect processing after its durability has been PROVEN. Returning
			# the strict publisher's boolean result is what makes an unproven publication fail
			# closed in the caller.
			if ([string]::IsNullOrWhiteSpace([string]$Fingerprint)) {
				Save-Checkpoint -PartitionIndex $PartitionIndex -State 'QueryCreated' -QueryId $QueryId -PartitionStart $PStart -PartitionEnd $PEnd -DeferDiskWrite
			}
			else {
				Save-Checkpoint -PartitionIndex $PartitionIndex -State 'QueryCreated' -QueryId $QueryId -PartitionStart $PStart -PartitionEnd $PEnd -Fingerprint $Fingerprint -DeferDiskWrite
			}
			return [bool](Save-CheckpointStrict)
		}
	}

	foreach ($p in @($Partitions)) {
		$res = Invoke-GraphAuditHardenedCreate -PStart $p.PStart -PEnd $p.PEnd -Index $p.Index -Total $p.Total -Activities $Activities -RecordTypes $p.RecordTypes -ServiceFilter $p.ServiceFilter -Invoke $Invoke -ListQueries $ListQueries -FetchItem $FetchItem -ReconcileOnly
		if ($res.Adopted -and $res.QueryId) {
			# Adopt: store the proven real id, checkpoint as created, and vacate the durable
			# uncertain entry so a later resume sees a normal fetch-only (never a re-POST).
			#
			# ONE identity drives BOTH the persist and the vacate so the adopted queryCreated entry
			# and the vacated uncertain entry are the SAME contract. Prefer the exact fingerprint
			# carried on the partition's durable uncertain state (so the adopted entry PRESERVES that
			# precise identity and a sibling same-index contract is never vacated); else reconstruct
			# it from the SAME contract the reconcile matched on - the RUN-LEVEL $Activities plus the
			# partition record-type / service / date window (NOT $p.Activities, which is absent before
			# partitionStatus is initialized on resume). A fingerprinted durable entry whose
			# fingerprint cannot be resolved FAILS CLOSED for this partition - it is NEVER adopted
			# with an index-only identity, which would persist an identity-less entry and vacate a
			# sibling same-index contract.
			$__ucState = if ($p.PSObject.Properties['UncertainCreateState']) { $p.UncertainCreateState } else { $null }
			$__storedFp = if ($null -ne $__ucState) { Get-PaxCheckpointEntryFingerprint $__ucState } else { $null }
			$__entryFingerprinted = (-not [string]::IsNullOrWhiteSpace([string]$__storedFp))
			$__fp = $null
			if ($__entryFingerprinted) {
				$__fp = [string]$__storedFp
			}
			else {
				try { $__fp = New-GraphAuditQueryFingerprint -PStart $p.PStart -PEnd $p.PEnd -Activities $Activities -RecordTypes $p.RecordTypes -ServiceFilter $p.ServiceFilter } catch { $__fp = $null }
			}
			if ($__entryFingerprinted -and [string]::IsNullOrWhiteSpace([string]$__fp)) {
				# Fingerprinted entry, unresolved fingerprint: never index-fallback (a sibling same-index
				# contract would be destroyed). Hold this partition, do not adopt, never POST.
				& $emit "[RESUME-RECONCILE] Partition $($p.Index)/$($p.Total) - fingerprinted uncertain entry could not resolve its contract identity - failing closed (no adopt, no POST)"
				$result.FailedClosed += $p
				continue
			}
			# ONE transaction owns the COMPLETE bucket transition. The post-adoption state is built
			# in memory FIRST (vacate the matching uncertain contract here, add the queryCreated
			# entry inside the persist callback), then published EXACTLY ONCE through the STRICT
			# local+Fabric transaction. An EXACT snapshot of every lifecycle bucket is captured
			# BEFORE the mutation so a failed publication is rolled back to the precise pre-adoption
			# state rather than a best-effort re-derivation.
			$__cpParts = if ($script:CheckpointData) { $script:CheckpointData.partitions } else { $null }
			$__snapCompleted = @()
			$__snapQueryCreated = @()
			$__snapUncertain = @()
			if ($__cpParts) {
				# Assigned as statements (never as an `if` expression) so an EMPTY bucket snapshots
				# as a real empty array rather than collapsing to $null, which would restore a
				# one-element @($null) bucket instead of an empty one.
				$__snapCompleted = @($__cpParts.completed)
				$__snapQueryCreated = @($__cpParts.queryCreated)
				$__snapUncertain = @($__cpParts.uncertainCreate)
			}
			if ($__cpParts -and $__cpParts.uncertainCreate) {
				# Vacate ONLY the adopted contract, using the SAME single fingerprint used to persist,
				# so a sibling same-index contract is preserved byte-for-byte.
				$__cpParts.uncertainCreate = @(
					$__cpParts.uncertainCreate | Where-Object { -not (Test-PaxCheckpointIdentityMatch $_ $p.Index $__fp) }
				)
			}
			$__persistProven = $false
			$__persistErr = $null
			try {
				$__persistResult = @(& $Persist $p.Index ([string]$res.QueryId) $p.PStart $p.PEnd $__fp) | Select-Object -Last 1
				$__persistProven = ($__persistResult -is [bool]) -and ([bool]$__persistResult)
			}
			catch { $__persistErr = $_ }
			if (-not $__persistProven) {
				# Fail closed: the adoption's durable publication was NOT proven. Restore the EXACT
				# pre-adoption in-memory state (the strict publisher leaves the durable copy
				# byte-for-byte unchanged), so the uncertain contract survives in memory AND on disk;
				# withhold the partition (never adopted, never routed to fetch-only, ZERO POSTs);
				# latch the classified fatal and throw so the caller terminates nonzero.
				if ($__cpParts) {
					$__cpParts.completed = $__snapCompleted
					$__cpParts.queryCreated = $__snapQueryCreated
					$__cpParts.uncertainCreate = $__snapUncertain
				}
				$script:GenericFatal = $true
				& $emit "[RESUME-RECONCILE] Partition $($p.Index)/$($p.Total) - durable publication of the adopted create was NOT proven - failing closed (no adopt, no fetch, no POST)"
				$__persistDetail = if ($__persistErr) { [string]$__persistErr.Exception.Message } else { 'the persistence callback did not return a proven durable publication.' }
				if ($__persistDetail -match 'PAX-FATAL-ROLLBACK') {
					throw "PAX-FATAL-ROLLBACK: durable publication of the adopted uncertain create failed for partition $([int]$p.Index) AND the prior checkpoint could not be restored; disk state is indeterminate - manual checkpoint inspection required. $__persistDetail"
				}
				throw "PAX-FATAL: durable publication of the adopted uncertain create failed for partition $([int]$p.Index); fail-closed, the durable uncertain contract is preserved and no fetch or fresh create is authorized. $__persistDetail"
			}
			# PROVEN durable publication: only NOW may the adoption affect processing - the real id
			# is stamped on the partition and the partition is classified fetch-only.
			$p | Add-Member -NotePropertyName 'StoredQueryId' -NotePropertyValue ([string]$res.QueryId) -Force
			& $emit "[RESUME-RECONCILE] Partition $($p.Index)/$($p.Total) - durable uncertain create adopted by exact name (no POST)"
			$result.AdoptedFetchOnly += $p
		}
		elseif ($res.FailureCategory -eq 'MultipleExactMatches') {
			# Fail closed: several exact matches; never adopt, never POST, keep the durable
			# uncertain state for an operator decision (-ClearUncertainCreate).
			& $emit "[RESUME-RECONCILE] Partition $($p.Index)/$($p.Total) - multiple exact-name matches - failing closed (no POST, uncertain preserved)"
			$result.FailedClosed += $p
		}
		else {
			# Remain uncertain: not visible after the bounded window. Never POST, never
			# QueryConfirmedAbsent (a collection miss cannot prove the first POST was rejected);
			# the durable uncertain entry is preserved.
			& $emit "[RESUME-RECONCILE] Partition $($p.Index)/$($p.Total) - uncertain create still not visible - remains unresolved (no POST, uncertain preserved)"
			$result.Unresolved += $p
		}
	}
	return $result
}

function Clear-PaxUncertainCreateState {
	<#
	.SYNOPSIS
		Operator-directed SELECTIVE clear of durable uncertain-create checkpoint state.
	.DESCRIPTION
		Durable uncertain-create entries are NEVER auto-cleared - not by elapsed time, a
		collection miss, a process restart, or failure-count exhaustion. The ONLY way to
		clear them is an explicit operator request that names specific partition indexes (the
		top-level -ClearUncertainCreate <index[,index...]> parameter). The clear is always
		SELECTIVE and bucket-exclusive: only the durable entries whose index is in
		-SelectedIndexes are removed; every other uncertain entry is preserved exactly. A
		selection that is empty, contains a duplicate, or names an index that is not currently
		in the durable uncertain-create set is REJECTED and nothing is cleared. With
		-ValidateOnly the selection is validated and returned WITHOUT mutating the checkpoint
		(used at resume time to fail an invalid selection before any auth or create).
	.PARAMETER CheckpointData
		The in-memory checkpoint hashtable ($script:CheckpointData is used when omitted).
	.PARAMETER Requested
		$true only when the operator explicitly passed -ClearUncertainCreate.
	.PARAMETER SelectedIndexes
		The explicit operator-supplied list of partition indexes to clear.
	.PARAMETER SelectedContracts
		The explicit operator-supplied list of "<index>:<fingerprint>" tokens naming durable
		uncertain-create contracts to clear (the -ClearUncertainContract companion). Used to
		disambiguate an index that maps to more than one durable uncertain contract: each token
		must resolve to EXACTLY one durable entry by (index, fingerprint); a token that is
		malformed, unknown, matches more than one, or is duplicated is REJECTED and nothing is
		cleared. When supplied it takes precedence over -SelectedIndexes and clears strictly by
		contract identity (bucket-exclusive by fingerprint); every unselected contract is kept.
	.PARAMETER ValidateOnly
		Validate and return the selection without removing anything from the checkpoint.
	.OUTPUTS
		A pscustomobject: Rejected (bool), Reason (string), Selected (int[] validated indexes),
		Cleared (int[] indexes actually removed), DurableIndexes (int[] indexes present at call),
		SelectedContracts (string[] validated "<index>:<fingerprint>" tokens), ClearedContracts
		(string[] tokens actually removed), DurableContracts (string[] tokens present at call).
	#>
	param(
		[Parameter()]$CheckpointData = $null,
		[Parameter()][bool]$Requested,
		[Parameter()][int[]]$SelectedIndexes = @(),
		[Parameter()][string[]]$SelectedContracts = @(),
		[Parameter()][switch]$ValidateOnly
	)
	$outcome = [pscustomobject]@{ Rejected = $false; Reason = ''; Selected = @(); Cleared = @(); DurableIndexes = @(); SelectedContracts = @(); ClearedContracts = @(); DurableContracts = @() }
	if (-not $Requested) { return $outcome }
	$cp = if ($null -ne $CheckpointData) { $CheckpointData } else { $script:CheckpointData }
	$durable = @()
	if ($cp -and $cp.partitions -and $cp.partitions.uncertainCreate) {
		$durable = @(@($cp.partitions.uncertainCreate) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_.index })
	}
	$outcome.DurableIndexes = $durable
	# EXPLICIT-CONTRACT selection (-ClearUncertainContract companion): each token
	# "<index>:<fingerprint>" names EXACTLY one durable uncertain contract by (index,
	# fingerprint) identity, so an index that maps to more than one contract can be
	# disambiguated. This path takes precedence when supplied: zero/multiple/unknown/malformed/
	# duplicate tokens fail closed WITHOUT mutation, and a valid clear removes strictly the
	# named contract(s) (bucket-exclusive by fingerprint) leaving every unselected entry exact.
	if (@($SelectedContracts).Count -gt 0) {
		$durableEntries = @()
		if ($cp -and $cp.partitions -and $cp.partitions.uncertainCreate) {
			$durableEntries = @(@($cp.partitions.uncertainCreate) | Where-Object { $null -ne $_ })
		}
		$outcome.DurableContracts = @($durableEntries | ForEach-Object { "$([int]$_.index):$(Get-PaxCheckpointEntryFingerprint $_)" })
		$normTokens = @()
		$matchedEntries = @()
		foreach ($tok in @($SelectedContracts)) {
			$raw = [string]$tok
			$ci = $raw.IndexOf(':')
			if ($ci -lt 1 -or $ci -ge ($raw.Length - 1)) {
				$outcome.Rejected = $true; $outcome.Reason = "malformed explicit contract selector '$raw' (expected '<index>:<fingerprint>')"; return $outcome
			}
			$idxRaw = $raw.Substring(0, $ci).Trim()
			$fpRaw = $raw.Substring($ci + 1).Trim()
			$idxParsed = 0
			if (-not [int]::TryParse($idxRaw, [ref]$idxParsed)) {
				$outcome.Rejected = $true; $outcome.Reason = "malformed explicit contract selector '$raw' (index is not an integer)"; return $outcome
			}
			if ([string]::IsNullOrWhiteSpace($fpRaw)) {
				$outcome.Rejected = $true; $outcome.Reason = "malformed explicit contract selector '$raw' (missing fingerprint)"; return $outcome
			}
			$normTok = "$($idxParsed):$fpRaw"
			$hits = @($durableEntries | Where-Object { ([int]$_.index -eq $idxParsed) -and ([string](Get-PaxCheckpointEntryFingerprint $_) -eq $fpRaw) })
			if (@($hits).Count -eq 0) {
				$outcome.Rejected = $true; $outcome.Reason = "explicit contract selector '$normTok' matches no durable uncertain-create contract"; return $outcome
			}
			if (@($hits).Count -gt 1) {
				$outcome.Rejected = $true; $outcome.Reason = "explicit contract selector '$normTok' matches more than one durable uncertain-create contract"; return $outcome
			}
			$normTokens += $normTok
			$matchedEntries += $hits[0]
		}
		$dupeTok = @($normTokens | Group-Object | Where-Object { $_.Count -gt 1 } | ForEach-Object { $_.Name })
		if (@($dupeTok).Count -gt 0) {
			$outcome.Rejected = $true; $outcome.Reason = "duplicate explicit contract selector token ($(@($dupeTok).Count) duplicate value(s))"; return $outcome
		}
		$outcome.SelectedContracts = $normTokens
		if ($ValidateOnly) { return $outcome }
		$cp.partitions.uncertainCreate = @(
			@($cp.partitions.uncertainCreate) | Where-Object {
				$entry = $_
				$drop = $false
				foreach ($m in $matchedEntries) {
					if (([int]$entry.index -eq [int]$m.index) -and ([string](Get-PaxCheckpointEntryFingerprint $entry) -eq [string](Get-PaxCheckpointEntryFingerprint $m))) { $drop = $true; break }
				}
				-not $drop
			}
		)
		$outcome.ClearedContracts = $normTokens
		return $outcome
	}
	$selected = @($SelectedIndexes | ForEach-Object { [int]$_ })
	if ($selected.Count -eq 0) {
		$outcome.Rejected = $true; $outcome.Reason = 'no partition index was supplied (selection is empty)'; return $outcome
	}
	$dupes = @($selected | Group-Object | Where-Object { $_.Count -gt 1 } | ForEach-Object { $_.Name })
	if ($dupes.Count -gt 0) {
		$outcome.Rejected = $true; $outcome.Reason = "duplicate partition index selected ($($dupes.Count) duplicate value(s))"; return $outcome
	}
	$unknown = @($selected | Where-Object { $_ -notin $durable })
	if ($unknown.Count -gt 0) {
		$outcome.Rejected = $true; $outcome.Reason = "$($unknown.Count) selected index(es) are not in the durable uncertain-create set of $($durable.Count) partition(s)"; return $outcome
	}
	# Ambiguity guard: because Graph workload passes RESTART partition indexes at 1, a single
	# partition index can map to MORE THAN ONE durable uncertain contract (distinct
	# fingerprints). An index-only selector cannot deterministically name which contract to
	# clear, so REJECT before any mutation - clearing the wrong contract's durable uncertain
	# state is unrecoverable. An explicit fingerprint selector is required to disambiguate.
	$ambiguous = @()
	foreach ($si in $selected) {
		$cnt = @($durable | Where-Object { $_ -eq $si }).Count
		if ($cnt -gt 1) { $ambiguous += $si }
	}
	if ($ambiguous.Count -gt 0) {
		$cand = @()
		foreach ($ai in @($ambiguous | Sort-Object -Unique)) {
			foreach ($e in @($cp.partitions.uncertainCreate | Where-Object { $null -ne $_ -and ([int]$_.index -eq [int]$ai) })) {
				$efp = Get-PaxCheckpointEntryFingerprint $e
				if (-not [string]::IsNullOrWhiteSpace([string]$efp)) { $cand += "$([int]$ai):$efp" }
			}
		}
		$hint = if (@($cand).Count -gt 0) { " re-run with -ClearUncertainContract naming the exact contract token(s): $(@($cand) -join ', ')" } else { ' the durable entries carry no fingerprint (legacy) and cannot be safely disambiguated - no clear is possible' }
		$outcome.Rejected = $true; $outcome.Reason = "$($ambiguous.Count) selected index(es) map to more than one durable uncertain contract (ambiguous index-only selection);$hint"; return $outcome
	}
	$outcome.Selected = $selected
	if ($ValidateOnly) { return $outcome }
	$cp.partitions.uncertainCreate = @(
		@($cp.partitions.uncertainCreate) | Where-Object { $null -ne $_ -and ([int]$_.index) -notin $selected }
	)
	$outcome.Cleared = $selected
	return $outcome
}

function Resolve-PaxOperatorClearedUncertain {
	<#
	.SYNOPSIS
		Selective operator recovery for a single NOT-VISIBLE durable-uncertain partition on
		resume. Returns $true only when the operator explicitly selected this partition index
		via -ClearUncertainCreate, in which case its durable uncertain marker is cleared
		SELECTIVELY and atomically (single durable write, bucket-exclusive) BEFORE any fresh
		create and the partition is authorized for a fresh create this run.
	.DESCRIPTION
		This is only ever called for a partition the READ-ONLY reconcile could NOT resolve by
		exact name (Unresolved / not visible). A still-visible partition is adopted or fails
		closed by the reconcile before this point, so a visible query is never cleared into a
		duplicate POST. When the partition is not in the operator selection this is a no-op
		that returns $false and preserves the durable uncertain state exactly.
	.PARAMETER Index
		The partition index being considered for operator-selected clear.
	.PARAMETER Fingerprint
		The contract fingerprint of the partition being considered, used to match an explicit
		-ClearUncertainContract "<index>:<fingerprint>" selection so a clear removes EXACTLY that
		contract even when another contract shares the index.
	.PARAMETER Selection
		The staged operator selection set (defaults to $script:ClearUncertainSelection).
	.PARAMETER ContractSelection
		The staged explicit-contract selection set of "<index>:<fingerprint>" tokens (defaults to
		$script:ClearUncertainContractSelection).
	.PARAMETER CheckpointData
		The in-memory checkpoint (defaults to $script:CheckpointData).
	.PARAMETER Persist
		Optional durable-write callback (defaults to Save-CheckpointStrict when checkpointing
		is enabled) invoked immediately after the selective clear, BEFORE any fresh create. The
		write must be PROVEN durable: a failure rolls back the clear and fails closed.
	.OUTPUTS
		$true when the partition was operator-cleared for a fresh create; otherwise $false.
	#>
	param(
		[Parameter(Mandatory)][int]$Index,
		[Parameter()][string]$Fingerprint = $null,
		[Parameter()]$Selection = $null,
		[Parameter()]$ContractSelection = $null,
		[Parameter()]$CheckpointData = $null,
		[Parameter()][scriptblock]$Persist = $null
	)
	$sel = $Selection
	if ($null -eq $sel) { $sel = $script:ClearUncertainSelection }
	$csel = $ContractSelection
	if ($null -eq $csel) { $csel = $script:ClearUncertainContractSelection }
	# This partition is operator-selected either by an explicit contract token
	# ("<index>:<fingerprint>", the precise identity that disambiguates two contracts sharing an
	# index) or by an unambiguous index-only selection. The explicit contract selector is checked
	# first so a fingerprinted clear removes EXACTLY that contract; index selection is only ever
	# staged for an UNAMBIGUOUS index (ambiguous index selectors are rejected at resume time).
	$contractToken = if (-not [string]::IsNullOrWhiteSpace($Fingerprint)) { "$([int]$Index):$Fingerprint" } else { $null }
	$byContract = ($null -ne $contractToken -and $null -ne $csel -and $csel.Contains($contractToken))
	$byIndex = ($null -ne $sel -and $sel.Contains([int]$Index))
	if (-not $byContract -and -not $byIndex) { return $false }
	$cp = if ($null -ne $CheckpointData) { $CheckpointData } else { $script:CheckpointData }
	# Copy-on-write snapshot of the durable uncertain bucket so a failed durable write
	# can be rolled back to EXACTLY the pre-clear state (fail-closed, no data loss).
	$origUncertain = @($cp.partitions.uncertainCreate)
	# Selective + atomic durable clear of ONLY this partition's uncertain marker - by the exact
	# contract identity when a fingerprint selection matched, else by unambiguous index.
	if ($byContract) {
		$null = Clear-PaxUncertainCreateState -CheckpointData $cp -Requested:$true -SelectedContracts @($contractToken)
	}
	else {
		$null = Clear-PaxUncertainCreateState -CheckpointData $cp -Requested:$true -SelectedIndexes @([int]$Index)
	}
	# Single durable write BEFORE any fresh create POST for this partition. The write
	# must be PROVEN durable: the default path uses the strict verify-after-write
	# publisher, and any failure (default OR injected callback) fails closed below.
	$persistOk = $false
	$persistError = $null
	try {
		if ($Persist) { & $Persist }
		elseif ($script:CheckpointEnabled) { $null = Save-CheckpointStrict }
		$persistOk = $true
	}
	catch {
		$persistOk = $false
		$persistError = $_
	}
	if (-not $persistOk) {
		# Fail-closed: durable persistence of the operator-cleared uncertain marker was
		# NOT proven. Roll back the in-memory clear, leave the operator selection
		# UNCONSUMED (no fresh create authorized), latch the classified fatal so the run
		# exits nonzero, and re-throw so the caller loop stops without adding a
		# create-capable partition.
		$cp.partitions.uncertainCreate = $origUncertain
		$script:GenericFatal = $true
		# If the strict publisher could NOT restore the prior checkpoint bytes, the disk state
		# is INDETERMINATE - surface that distinct rollback-failure category rather than the
		# normal fail-closed message (which implies the prior state was restored intact).
		if ($persistError -and ([string]$persistError.Exception.Message) -match 'PAX-FATAL-ROLLBACK') {
			throw "PAX-FATAL-ROLLBACK: durable persistence of operator-cleared uncertain create failed for partition $([int]$Index) AND the prior checkpoint could not be restored; disk state is indeterminate - manual checkpoint inspection required. $([string]$persistError.Exception.Message)"
		}
		throw "PAX-FATAL: durable persistence of operator-cleared uncertain create failed for partition $([int]$Index); fail-closed, no fresh create authorized."
	}
	# Only a PROVEN durable write consumes the selection and authorizes the fresh create.
	if ($byContract) { [void]$csel.Remove($contractToken) }
	else { [void]$sel.Remove([int]$Index) }
	return $true
}

# ==============================================
# CTRL+C GRACEFUL EXIT HANDLER
# ==============================================
# Track Ctrl+C state for graceful exit messaging in finally block

$script:CtrlCPressed = $false
$script:ScriptCompleted = $false
$script:EarlyExit = $false
# Track whether ANY file upload (SharePoint/Fabric output, metrics, or run log) failed
# this run. When true, local run files are preserved at end of run - treated the same as
# Ctrl+C / early-exit / crash - so nothing is lost when a destination upload did not complete.
$script:AnyUploadFailed = $false
$script:ResumeValidationFailed = $false
# 1D-a: a GENERIC, unexpected terminating error reached the top-level catch (i.e. NOT a
# Ctrl+C / graceful early-exit, and NOT one of the classified failure conditions that already
# drive a specific exit code). Without this flag such a crash falls through the finally exit
# selector with every failure flag false and reports exit 0 (false success) to ACA/automation,
# contradicting the exit contract (1 = Fatal / aborted). It maps to exit 1 at top precedence,
# suppresses the finally's Ctrl+C mis-inference, and (like any non-clean end) preserves the
# durable recovery artifacts the clean-run cleanup would otherwise delete.
$script:GenericFatal = $false
$script:AISIDCleanTail = $false

function script:Invoke-PaxGraphDisconnect {
	param([System.Management.Automation.ActionPreference]$ErrorAction = [System.Management.Automation.ActionPreference]::Stop)
	$writer = $null
	$originalWarning = $null
	try {
		try {
			$writer = [Microsoft.Graph.PowerShell.Authentication.GraphSession]::Instance.OutputWriter
			if ($writer -and $writer.WriteWarning) {
				$originalWarning = $writer.WriteWarning
				$warningPrefix = 'Failed to clear the persisted MSAL token cache during Disconnect-MgGraph:'
				$writer.WriteWarning = [System.Action[string]]{
					param($message)
					if (-not ([string]$message).StartsWith($warningPrefix, [System.StringComparison]::Ordinal)) {
						$originalWarning.Invoke([string]$message)
					}
				}.GetNewClosure()
			}
		} catch {}
		Disconnect-MgGraph -ErrorAction $ErrorAction | Out-Null
	}
	finally {
		if ($writer -and $originalWarning) {
			$writer.WriteWarning = $originalWarning
		}
	}
}

# Register exit handler that ALWAYS runs when PowerShell exits
# This works even when Ctrl+C is pressed before the try block (e.g., during module loading)
# Uses environment variable for cross-runspace communication since Register-EngineEvent runs in isolated scope
$env:PAX_GRACEFUL_EXIT_DONE = $null
$env:PAX_REPLAY_MODE = $null  # Will be set to "1" when RAWInputCSV is used
Register-EngineEvent -SourceIdentifier PowerShell.Exiting -Action {
	if (-not $env:PAX_GRACEFUL_EXIT_DONE) {
		# Skip interrupt messaging in replay mode - no Graph connection to disconnect
		if (-not $env:PAX_REPLAY_MODE) {
			Write-Host ""
			Write-Host "============================================================================================================" -ForegroundColor Yellow
			Write-Host "  Script Interrupted - Performing Graceful Cleanup" -ForegroundColor Yellow
			Write-Host "============================================================================================================" -ForegroundColor Yellow
			Write-Host ""
			Write-Host "  Cleanup complete. Exiting..." -ForegroundColor Green
			Write-Host ""
		}
	}
} | Out-Null

# Define cleanup function (used by catch block for PipelineStoppedException)
function Invoke-GracefulExit {
	param([string]$Reason = "Script interrupted")
	
	if ($script:CtrlCPressed) { return }  # Prevent multiple invocations
	$script:CtrlCPressed = $true
	
	# Signal to engine event handler that graceful exit is handling this
	$env:PAX_GRACEFUL_EXIT_DONE = "1"
	
	# Skip interrupt messaging and Graph disconnect in replay mode - no connections to clean up
	if ($env:PAX_REPLAY_MODE) {
		exit 0
	}
	
	Write-Host ""
	Write-Host "============================================================================================================" -ForegroundColor Yellow
	Write-Host "  Script Interrupted - Performing Graceful Cleanup" -ForegroundColor Yellow
	Write-Host "============================================================================================================" -ForegroundColor Yellow
	Write-Host ""
	
	# Disconnect from Microsoft Graph - ALWAYS attempt disconnect
	Write-Host "  Disconnecting from Microsoft Graph..." -ForegroundColor Cyan
	try {
		script:Invoke-PaxGraphDisconnect -ErrorAction Stop
		Write-Host "  Microsoft Graph disconnected" -ForegroundColor Green
	}
	catch {
		if ($_.Exception.Message -match 'No application to sign out from') {
			Write-Host "  (Not connected to Microsoft Graph)" -ForegroundColor DarkGray
		} else {
			Write-Host "  Microsoft Graph session cleared" -ForegroundColor Green
		}
	}
	
	# Disconnect from Exchange Online (if connected via EOM mode)
	try {
		$eomSession = Get-PSSession | Where-Object { $_.ConfigurationName -eq 'Microsoft.Exchange' -and $_.State -eq 'Opened' }
		if ($eomSession) {
			Write-Host "  Disconnecting from Exchange Online Management..." -ForegroundColor Cyan
			Disconnect-ExchangeOnline -Confirm:$false -ErrorAction SilentlyContinue | Out-Null
			Write-Host "  Exchange Online disconnected" -ForegroundColor Green
		}
	}
	catch {
		Write-Host "  (Exchange Online cleanup completed)" -ForegroundColor Gray
	}
	
	# Log the graceful exit
	if ($LogFile -and (Test-Path $LogFile)) {
		Write-Output "" | Out-File -FilePath $LogFile -Append -Encoding utf8
		Write-Output "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] Script interrupted by user (Ctrl+C)" | Out-File -FilePath $LogFile -Append -Encoding utf8
		Write-Output "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] Graceful cleanup completed" | Out-File -FilePath $LogFile -Append -Encoding utf8
	}
	
	# Show checkpoint resume message if checkpoint is enabled
	if ($script:CheckpointEnabled -and $script:CheckpointPath -and (Test-Path $script:CheckpointPath)) {
		Show-CheckpointExitMessage
	}

	# Release the exclusive checkpoint lock so a future -Resume of THIS checkpoint
	# (from any host) is not blocked by our stale lock. The lock file itself is removed
	# by Release-CheckpointLock; the checkpoint JSON is preserved for resume.
	try { script:Release-CheckpointLock } catch {}

	Write-Host ""
	Write-Host "  Cleanup complete. Exiting..." -ForegroundColor Green
	Write-Host ""
	
	# Exit cleanly (env var PAX_GRACEFUL_EXIT_DONE already set at function start)
	exit 0
}

# Trap for catching terminating errors (including Ctrl+C)
trap {
	if ($_.Exception -is [System.Management.Automation.PipelineStoppedException]) {
		Invoke-GracefulExit
		break
	}
	# Re-throw other exceptions
	throw $_
}

# ==============================================
# MODULE PREREQUISITES
# ==============================================
# Load required modules based on mode selection (-UseEOM vs Graph API default)

# Emit PAX banner + sensitive-data warning to terminal/log BEFORE any other startup output
Write-LogHost "=== Portable Audit eXporter (PAX) - Purview Audit Log Exporter ===" -ForegroundColor Cyan
Write-LogHost ("Script Version: v$ScriptVersion") -ForegroundColor White
if (-not $SkipVersionCheck) { Invoke-PaxVersionCheck -CurrentVersion $ScriptVersion }
Write-LogHost ""
Write-LogHost "=========================================================================" -ForegroundColor Yellow
Write-LogHost "  !! SENSITIVE DATA WARNING - CUSTOMER RESPONSIBILITY !!" -ForegroundColor Yellow
Write-LogHost "=========================================================================" -ForegroundColor Yellow
Write-LogHost "The audit data exported by this script is HIGHLY SENSITIVE. Output may" -ForegroundColor Yellow
Write-LogHost "contain user identifiers (UPN, email, GUID), file/site/resource paths," -ForegroundColor Yellow
Write-LogHost "conversation and message IDs, agent identifiers, prompt/response metadata" -ForegroundColor Yellow
Write-LogHost "(timestamps, lengths, classifications), and other personally identifiable" -ForegroundColor Yellow
Write-LogHost "information drawn directly from your tenant's Unified Audit Log." -ForegroundColor Yellow
Write-LogHost ""
Write-LogHost "  * Data is NOT hashed, masked, redacted, anonymized, or de-identified." -ForegroundColor Yellow
Write-LogHost "    Records are exported in raw, attributable form as Purview returns them." -ForegroundColor Yellow
Write-LogHost "  * Outputs (CSV/Excel/JSON metrics, checkpoint files, logs) may contain" -ForegroundColor Yellow
Write-LogHost "    confidential business content, regulated data (PII, PHI, financial," -ForegroundColor Yellow
Write-LogHost "    IP), and end-user communications." -ForegroundColor Yellow
Write-LogHost "  * The customer (you / your organization) is SOLELY RESPONSIBLE for the" -ForegroundColor Yellow
Write-LogHost "    secure handling, storage, transmission, retention, disclosure, access" -ForegroundColor Yellow
Write-LogHost "    control, and deletion of all data produced by this script, and for" -ForegroundColor Yellow
Write-LogHost "    ensuring its use complies with all applicable laws, regulations," -ForegroundColor Yellow
Write-LogHost "    contractual obligations, and internal policies - including but not" -ForegroundColor Yellow
Write-LogHost "    limited to GDPR, HIPAA, CCPA, employee monitoring laws, works-council" -ForegroundColor Yellow
Write-LogHost "    agreements, and data-residency requirements." -ForegroundColor Yellow
Write-LogHost "  * Microsoft has no visibility into, control over, or responsibility" -ForegroundColor Yellow
Write-LogHost "    for the data customers extract using this tool or how that data is" -ForegroundColor Yellow
Write-LogHost "    subsequently used, shared, or stored. Microsoft disclaims any and all" -ForegroundColor Yellow
Write-LogHost "    liability arising from or related to customer use of this script and" -ForegroundColor Yellow
Write-LogHost "    its output." -ForegroundColor Yellow
Write-LogHost "  * Treat all output files as HIGHLY CONFIDENTIAL. Restrict access to" -ForegroundColor Yellow
Write-LogHost "    authorized personnel with a documented business need. Encrypt at rest" -ForegroundColor Yellow
Write-LogHost "    and in transit. Apply tenant DLP / sensitivity labels as appropriate." -ForegroundColor Yellow
Write-LogHost "=========================================================================" -ForegroundColor Yellow
Write-LogHost ""

if ($RAWInputCSV) {
	# Set replay mode flag for graceful exit handling (skip Graph disconnect messaging)
	$env:PAX_REPLAY_MODE = "1"
	Write-LogHost "`nReplay mode: Skipping module loading`n" -ForegroundColor Cyan
}
elseif (-not $UseEOM) {
	# DEFAULT MODE: Microsoft Graph Security API
	# Requires Microsoft.Graph.Authentication and Microsoft.Graph.Security modules
	Write-LogHost ""
	Write-LogHost "Loading Microsoft Graph modules..." -ForegroundColor Cyan

	try {
		# ============================================
		# AUTO-UPDATE CHECK: Ensure latest SDK version
		# ============================================
		# The Graph Security auditLog API has known issues with older SDK versions.
		# Always check for and install the latest version to ensure compatibility.
		
		Write-LogHost "  Checking for Microsoft Graph SDK updates..." -ForegroundColor Gray
		
		# Get currently installed version
		$installedAuth = Get-Module -ListAvailable -Name Microsoft.Graph.Authentication | Sort-Object Version -Descending | Select-Object -First 1
		$installedAuthVersion = if ($installedAuth) { $installedAuth.Version } else { [Version]"0.0.0" }
		
		# Check PSGallery for latest version (with 15-second timeout to avoid hangs)
		$latestAuthVersion = $null
		try {
			$updateCheckJob = Start-Job -ScriptBlock { Find-Module -Name Microsoft.Graph.Authentication -Repository PSGallery -ErrorAction Stop }
			$jobCompleted = Wait-Job -Job $updateCheckJob -Timeout 15
			if ($jobCompleted) {
				$galleryAuth = Receive-Job -Job $updateCheckJob -ErrorAction Stop
				$latestAuthVersion = [Version]$galleryAuth.Version
			}
			else {
				Write-LogHost "  PSGallery check timed out (15s) - skipping update check" -ForegroundColor Yellow
			}
			Remove-Job -Job $updateCheckJob -Force -ErrorAction SilentlyContinue
		}
		catch {
			Write-LogHost "  Warning: Could not check PSGallery for updates: $($_.Exception.Message)" -ForegroundColor Yellow
			Write-LogHost "  Continuing with installed version..." -ForegroundColor Yellow
		}
		
		# Update if newer version available
		$updatePerformed = $false
		if ($latestAuthVersion -and ($latestAuthVersion -gt $installedAuthVersion)) {
			Write-LogHost "  Update available: v$installedAuthVersion → v$latestAuthVersion" -ForegroundColor Yellow
			Write-LogHost "  Installing Microsoft.Graph.Authentication v$latestAuthVersion..." -ForegroundColor Yellow
			
			try {
				# Install latest Authentication module
				Install-Module -Name Microsoft.Graph.Authentication -Scope CurrentUser -Force -AllowClobber -ErrorAction Stop
				Write-LogHost "  Microsoft.Graph.Authentication updated to v$latestAuthVersion" -ForegroundColor Green
				
				# Install matching Security module
				Write-LogHost "  Installing Microsoft.Graph.Security v$latestAuthVersion..." -ForegroundColor Yellow
				Install-Module -Name Microsoft.Graph.Security -RequiredVersion $latestAuthVersion -Scope CurrentUser -Force -AllowClobber -ErrorAction Stop
				Write-LogHost "  Microsoft.Graph.Security updated to v$latestAuthVersion" -ForegroundColor Green
				
				$updatePerformed = $true
				
				# Refresh module info after update
				$installedAuth = Get-Module -ListAvailable -Name Microsoft.Graph.Authentication | Sort-Object Version -Descending | Select-Object -First 1
				$installedAuthVersion = $installedAuth.Version
			}
			catch {
				Write-LogHost "  Warning: Update failed: $($_.Exception.Message)" -ForegroundColor Yellow
				Write-LogHost "  Continuing with existing version v$installedAuthVersion..." -ForegroundColor Yellow
			}
		}
		elseif ($latestAuthVersion) {
			Write-LogHost "  Microsoft Graph SDK is up to date (v$installedAuthVersion)" -ForegroundColor Green
		}
		else {
			Write-LogHost "  Using installed version v$installedAuthVersion" -ForegroundColor Gray
		}
		
		# ============================================
		# LOAD MODULES
		# ============================================
		
		$authModule = Get-Module -Name Microsoft.Graph.Authentication | Select-Object -First 1
		if (-not $authModule) {
			$authModule = Get-Module -ListAvailable -Name Microsoft.Graph.Authentication | Sort-Object Version -Descending | Select-Object -First 1
		}
		if (-not $authModule) {
			Write-LogHost "  Installing Microsoft.Graph.Authentication module (CurrentUser scope)..." -ForegroundColor Yellow
			Install-Module -Name Microsoft.Graph.Authentication -Scope CurrentUser -Force -AllowClobber -ErrorAction Stop
			$authModule = Get-Module -ListAvailable -Name Microsoft.Graph.Authentication | Sort-Object Version -Descending | Select-Object -First 1
		}
		$authVersion = $authModule.Version
		Write-LogHost "  Importing Microsoft.Graph.Authentication v$authVersion..." -ForegroundColor Gray
		Import-Module Microsoft.Graph.Authentication -RequiredVersion $authVersion -Force -ErrorAction Stop
		Write-LogHost "  Microsoft.Graph.Authentication v$authVersion loaded" -ForegroundColor Green

		# Load Microsoft.Graph.Security matching auth version (exact if possible, otherwise same major/minor)
		$securityModule = Get-Module -Name Microsoft.Graph.Security | Where-Object { $_.Version -eq $authVersion } | Select-Object -First 1
		if (-not $securityModule) {
			$securityModule = Get-Module -ListAvailable -Name Microsoft.Graph.Security |
				Where-Object { $_.Version.Major -eq $authVersion.Major -and $_.Version.Minor -eq $authVersion.Minor } |
				Sort-Object Version -Descending |
				Select-Object -First 1
		}
		if (-not $securityModule) {
			Write-LogHost "  Installing Microsoft.Graph.Security v$authVersion (CurrentUser scope)..." -ForegroundColor Yellow
			Install-Module -Name Microsoft.Graph.Security -RequiredVersion $authVersion -Scope CurrentUser -Force -AllowClobber -ErrorAction Stop
			$securityModule = Get-Module -ListAvailable -Name Microsoft.Graph.Security | Where-Object { $_.Version -eq $authVersion } | Select-Object -First 1
		}
		$secVersion = $securityModule.Version
		Write-LogHost "  Importing Microsoft.Graph.Security v$secVersion..." -ForegroundColor Gray
		Import-Module Microsoft.Graph.Security -RequiredVersion $secVersion -Force -ErrorAction Stop
		Write-LogHost "  Microsoft.Graph.Security v$secVersion loaded" -ForegroundColor Green
	}
	catch {
		Write-LogHost "  ERROR: Failed to load Microsoft Graph module: $($_.Exception.Message)" -ForegroundColor Red
		Write-LogHost "`nTroubleshooting:" -ForegroundColor Yellow
		Write-LogHost "  1. Ensure PowerShell Gallery access is available" -ForegroundColor White
		Write-LogHost "  2. Try manual installation: Install-Module -Name Microsoft.Graph -Force" -ForegroundColor White
		Write-LogHost "  3. Use -UseEOM switch to fall back to Exchange Online Management mode" -ForegroundColor White
		throw
	}

	Write-LogHost "Microsoft Graph modules loaded successfully`n" -ForegroundColor Green
}
else {
	# EOM MODE: Exchange Online Management
	# Graph modules not required in EOM mode
	Write-LogHost "`nEOM Mode: Skipping Microsoft Graph module loading`n" -ForegroundColor Cyan
}

# ==============================================
# DUAL-MODE AUTHENTICATION FUNCTION
# ==============================================
# Unified authentication supporting both EOM and Graph API modes

function Connect-PurviewAudit {
	<#
	.SYNOPSIS
		Unified authentication for Purview audit log access via EOM or Graph API.
	
	.DESCRIPTION
		Authenticates to Microsoft 365 using either Exchange Online Management (EOM)
		or Microsoft Graph Security API based on the -UseEOM switch.
		
		EOM Mode (-UseEOM):
		  - Uses Connect-ExchangeOnline cmdlet
		  - Requires Exchange Online RBAC roles
		  - Serial processing only
		
		Graph API Mode (Default):
		  - Uses Connect-MgGraph with AuditLogsQuery.Read.All scope
		  - Requires Azure AD roles + Graph API permissions
		  - Supports parallel processing
	
	.PARAMETER AuthMethod
		Authentication method: WebLogin, DeviceCode, Credential, Silent, AppRegistration
	
	.PARAMETER UseEOMMode
		If true, use EOM mode. If false, use Graph API mode.
	#>
	
	param(
		[Parameter(Mandatory = $true)]
		[ValidateSet('WebLogin', 'DeviceCode', 'Credential', 'Silent', 'AppRegistration', 'ManagedIdentity')]
		[string]$AuthMethod,
		
		[Parameter(Mandatory = $false)]
		[bool]$UseEOMMode = $false
	)
	
	if ($UseEOMMode) {
		# ========================================
		# EOM MODE: Exchange Online Management
		# ========================================
		
		if ($script:Connected) {
			Write-LogHost "Already connected to Exchange Online." -ForegroundColor Gray
			return
		}
		
		Write-LogHost "Connecting to Microsoft 365 Security & Compliance Center (EOM)..." -ForegroundColor Cyan
		
		# Ensure ExchangeOnlineManagement module is available
		try {
			$existingEOM = Get-Module -ListAvailable -Name ExchangeOnlineManagement | Sort-Object Version -Descending | Select-Object -First 1
			if (-not $existingEOM) {
				Write-LogHost "Installing ExchangeOnlineManagement module (CurrentUser scope)..." -ForegroundColor Yellow
				Install-Module -Name ExchangeOnlineManagement -Scope CurrentUser -Force -AllowClobber -ErrorAction Stop
			}
			Import-Module ExchangeOnlineManagement -Force -ErrorAction Stop
			
			$eomVersion = (Get-Module ExchangeOnlineManagement).Version
			Write-LogHost "  ExchangeOnlineManagement v$eomVersion loaded" -ForegroundColor Green
		}
		catch {
			Write-LogHost "ERROR: Module load/install failure: $($_.Exception.Message)" -ForegroundColor Red
			throw
		}
		
		# Authenticate based on method
		try {
			switch ($AuthMethod.ToLower()) {
				'appregistration' {
					Write-LogHost "AppRegistration authentication is not supported with -UseEOM. Remove -UseEOM to use Graph mode." -ForegroundColor Yellow
					throw "AppRegistration authentication is only available in Graph API mode"
				}
				'weblogin' {
					$exoCmd = Get-Command Connect-ExchangeOnline -ErrorAction Stop
					$hasUseWeb = $exoCmd.Parameters.ContainsKey('UseWebLogin')
					
					if ($hasUseWeb) {
						Write-LogHost "Using Connect-ExchangeOnline -UseWebLogin..." -ForegroundColor Gray
						Connect-ExchangeOnline -ShowBanner:$false -UseWebLogin -ErrorAction Stop | Out-Null
					}
					else {
						Write-LogHost "UseWebLogin parameter not available; using standard interactive auth..." -ForegroundColor Yellow
						Connect-ExchangeOnline -ShowBanner:$false -ErrorAction Stop | Out-Null
					}
				}
				
				'devicecode' {
					Write-LogHost "Using device code flow..." -ForegroundColor Gray
					Connect-ExchangeOnline -ShowBanner:$false -Device -ErrorAction Stop | Out-Null
				}
				
				'credential' {
					Write-LogHost "Using credential-based authentication..." -ForegroundColor Gray
					$cred = Get-Credential -Message 'Enter admin credentials for Exchange Online'
					Connect-ExchangeOnline -ShowBanner:$false -Credential $cred -ErrorAction Stop | Out-Null
				}
				
				'silent' {
					Write-LogHost "Attempting silent authentication..." -ForegroundColor Gray
					$silentOk = $true
					try {
						Connect-ExchangeOnline -ShowBanner:$false -ErrorAction Stop | Out-Null
					}
					catch {
						$silentOk = $false
					}
					
					if (-not $silentOk) {
						Write-LogHost "Silent auth failed, falling back to WebLogin..." -ForegroundColor Yellow
						try {
							Connect-ExchangeOnline -ShowBanner:$false -UseWebLogin -ErrorAction Stop | Out-Null
						}
						catch {
							Write-LogHost "ERROR: Silent + fallback auth failed: $($_.Exception.Message)" -ForegroundColor Red
							throw
						}
					}
				}
				'managedidentity' {
					Write-LogHost "ERROR: -Auth ManagedIdentity is not supported with -UseEOM." -ForegroundColor Red
					Write-LogHost "       Exchange Online Management does not accept managed-identity auth." -ForegroundColor Yellow
					Write-LogHost "       Use -Auth ManagedIdentity without -UseEOM (Graph API path)." -ForegroundColor Yellow
					throw "ManagedIdentity auth is not supported with -UseEOM"
				}
			}
			
			$script:Connected = $true
			Write-LogHost "Successfully connected to Exchange Online" -ForegroundColor Green
			
			# Verify connection
			try {
				$connInfo = Get-ConnectionInformation -ErrorAction SilentlyContinue | Where-Object { $_.TokenStatus -ne 'Expired' } | Select-Object -First 1
				if ($connInfo) {
					Write-LogHost "  Tenant ID: $($connInfo.TenantId)" -ForegroundColor Gray
					Write-LogHost "  User: $($connInfo.UserPrincipalName)" -ForegroundColor Gray
				}
			}
			catch {
				# Connection info not critical, continue
			}
		}
		catch {
			Write-LogHost "ERROR: EOM authentication failed: $($_.Exception.Message)" -ForegroundColor Red
			Write-LogHost "`nTroubleshooting:" -ForegroundColor Yellow
			Write-LogHost "  1. Verify you have required Exchange Online roles" -ForegroundColor White
			Write-LogHost "  2. Check Multi-Factor Authentication requirements" -ForegroundColor White
			Write-LogHost "  3. Try a different auth method (-Auth parameter)" -ForegroundColor White
			throw
		}
	}
	else {
		# ========================================
		# GRAPH API MODE: Microsoft Graph Security
		# ========================================
		
		# Clear any stale Graph session from a previous script run or Ctrl+C in this terminal.
		# This forces a fresh Connect-MgGraph with a new token, preventing issues where MSAL
		# silently returns a cached expired token or a token from a different user account.
		Write-LogHost "Clearing any previous Graph session..." -ForegroundColor Gray
		try { script:Invoke-PaxGraphDisconnect -ErrorAction SilentlyContinue } catch { }
		
		Write-LogHost "Connecting to Microsoft Graph Security API..." -ForegroundColor Cyan
		
		# Define required scopes for Purview audit log access via the Microsoft Graph
		# Security API. The exact scope set is built dynamically based on which features
		# the caller has activated, so users only consent to what they actually use.
		#
		# Conditional (added only when the relevant switch is set):
		#   Audit query (skipped under -OnlyUserInfo since no audit calls are made):
		#       AuditLogsQuery.Read.All - umbrella scope for /security/auditLog/queries
		#                                 (covers CopilotInteraction and other workload-
		#                                 agnostic record types)
		#   -IncludeM365Usage:
		#       AuditLogsQuery-Exchange.Read.All
		#       AuditLogsQuery-OneDrive.Read.All
		#       AuditLogsQuery-SharePoint.Read.All
		#   -IncludeUserInfo / -OnlyUserInfo (Graph API mode only):
		#       User.Read.All           (read /users for Entra directory + license map)
		#       Organization.Read.All   (read /subscribedSkus for license SKU lookup)
		#   -GroupNames (Graph API mode only):
		#       GroupMember.Read.All    (least-privilege scope per Microsoft Graph docs
		#                                for GET /groups and GET /groups/{id}/transitiveMembers;
		#                                used by Expand-PurviewGroupMembership)
		$RequiredScopes = [System.Collections.Generic.List[string]]::new()
		if (-not $OnlyUserInfo -and -not $OnlyAgent365Info) {
			[void]$RequiredScopes.Add('AuditLogsQuery.Read.All')
		}
		if ($IncludeM365Usage) {
			[void]$RequiredScopes.Add('AuditLogsQuery-Exchange.Read.All')
			[void]$RequiredScopes.Add('AuditLogsQuery-OneDrive.Read.All')
			[void]$RequiredScopes.Add('AuditLogsQuery-SharePoint.Read.All')
		}
		if ($IncludeUserInfo -or $OnlyUserInfo) {
			if ($RequiredScopes -notcontains 'User.Read.All')         { [void]$RequiredScopes.Add('User.Read.All') }
			if ($RequiredScopes -notcontains 'Organization.Read.All') { [void]$RequiredScopes.Add('Organization.Read.All') }
		}
		if ($GroupNames -and $GroupNames.Count -gt 0) {
			if ($RequiredScopes -notcontains 'GroupMember.Read.All') { [void]$RequiredScopes.Add('GroupMember.Read.All') }
		}
		# Microsoft Agent 365 enrichment scopes - DELEGATED auth modes only.
		# Delegated modes (WebLogin / DeviceCode / Credential / Silent) request
		# CopilotPackages.Read.All (+ Application.Read.All) as DELEGATED scopes here at sign-in.
		# App-only modes (AppRegistration certificate/secret, ManagedIdentity) do NOT request
		# delegated scopes: the Agent 365 catalog is read with the matching APPLICATION app-roles
		# granted + admin-consented on the app / managed-identity service principal out-of-band
		# (see Connect-Agent365InteractiveContext). The $AuthMethod -notin guard below therefore
		# correctly excludes both app-only modes from delegated scope requests.
		if (($IncludeAgent365Info -or $OnlyAgent365Info) -and $AuthMethod -notin @('AppRegistration','ManagedIdentity')) {
			if ($RequiredScopes -notcontains 'CopilotPackages.Read.All') { [void]$RequiredScopes.Add('CopilotPackages.Read.All') }
			if ($RequiredScopes -notcontains 'Application.Read.All')    { [void]$RequiredScopes.Add('Application.Read.All') }
		}
		# AISID (Defender / AI Solutions) hunting scope - DELEGATED auth modes only.
		# -Dashboard AISID pulls Defender data via the Graph advanced-hunting endpoint
		# (POST /v1.0/security/runHuntingQuery) using THIS SAME Graph token — no separate login.
		# Delegated modes (WebLogin / DeviceCode) request ThreatHunting.Read.All here at sign-in.
		# App-only modes (Credential client-secret, AppRegistration, Silent/ManagedIdentity) do NOT
		# request delegated scopes: ThreatHunting.Read.All must be granted + admin-consented as an
		# APPLICATION permission on the app registration / managed-identity service principal
		# out-of-band (documented customer prerequisite). The -notin guard mirrors the Agent 365
		# block above so app-only modes are correctly excluded from the delegated request.
		if (($Dashboard -eq 'AISID') -and $AuthMethod -notin @('AppRegistration','ManagedIdentity')) {
			if ($RequiredScopes -notcontains 'ThreatHunting.Read.All') { [void]$RequiredScopes.Add('ThreatHunting.Read.All') }
		}
		# SharePoint remote-output destination needs delegated/app drive write scopes.
		# Fabric/OneLake uses a separate storage-audience token (Az.Accounts), not a Graph scope.
		# Sites.ReadWrite.All alone authorizes every SharePoint drive/file endpoint used here
		# (site/drive resolve, folder create via POST children, PUT / createUploadSession, download)
		# for both delegated and application auth, so Files.ReadWrite.All is not requested.
		if ($script:RemoteOutputMode -eq 'SharePoint') {
			if ($RequiredScopes -notcontains 'Sites.ReadWrite.All') { [void]$RequiredScopes.Add('Sites.ReadWrite.All') }
		}
		$RequiredScopes = $RequiredScopes.ToArray()

		try {
			switch ($AuthMethod.ToLower()) {
				'weblogin' {
					Write-LogHost "Using interactive browser authentication..." -ForegroundColor Gray
					Connect-MgGraph -Scopes $RequiredScopes -NoWelcome -ErrorAction Stop
				}
				
				'devicecode' {
					Write-LogHost "Using device code flow..." -ForegroundColor Gray
					Write-LogHost "A browser window will open. Follow the instructions to authenticate." -ForegroundColor Yellow
					Connect-MgGraph -Scopes $RequiredScopes -UseDeviceCode -NoWelcome -ErrorAction Stop
				}
				
				'credential' {
					Write-LogHost "Using client secret credential..." -ForegroundColor Gray
					
					# Check for required environment variables
					$tenantId = $env:GRAPH_TENANT_ID
					$clientId = $env:GRAPH_CLIENT_ID
					$clientSecret = $env:GRAPH_CLIENT_SECRET
					
					if (-not $tenantId -or -not $clientId -or -not $clientSecret) {
						Write-LogHost "ERROR: Credential authentication requires environment variables:" -ForegroundColor Red
						Write-LogHost "  GRAPH_TENANT_ID     : Your Azure AD Tenant ID" -ForegroundColor Yellow
						Write-LogHost "  GRAPH_CLIENT_ID     : Your App Registration Client ID" -ForegroundColor Yellow
						Write-LogHost "  GRAPH_CLIENT_SECRET : Your App Registration Client Secret" -ForegroundColor Yellow
						Write-LogHost ""
						Write-LogHost "Set these variables before running the script:" -ForegroundColor Yellow
						Write-LogHost "  `$env:GRAPH_TENANT_ID = 'your-tenant-id'" -ForegroundColor White
						Write-LogHost "  `$env:GRAPH_CLIENT_ID = 'your-client-id'" -ForegroundColor White
						Write-LogHost "  `$env:GRAPH_CLIENT_SECRET = 'your-client-secret'" -ForegroundColor White
						throw "Missing required environment variables for credential authentication"
					}
					
					$secureSecret = ConvertTo-SecureString -String $clientSecret -AsPlainText -Force
					$credential = New-Object System.Management.Automation.PSCredential($clientId, $secureSecret)
					
					# Clear plain-text secret from memory
					Clear-Variable -Name clientSecret -Force -ErrorAction SilentlyContinue
					
					Connect-MgGraph -TenantId $tenantId -ClientSecretCredential $credential -NoWelcome -ErrorAction Stop
				}
				
				'silent' {
					Write-LogHost "Using managed identity or existing token..." -ForegroundColor Gray
					Connect-MgGraph -Identity -NoWelcome -ErrorAction Stop
				}
				'managedidentity' {
					Write-LogHost "Using managed identity (system-assigned or user-assigned)..." -ForegroundColor Gray
					if ($env:AZURE_CLIENT_ID) {
						Write-LogHost ("  -> User-assigned MI client id: {0}" -f $env:AZURE_CLIENT_ID) -ForegroundColor DarkGray
						Connect-MgGraph -Identity -ClientId $env:AZURE_CLIENT_ID -NoWelcome -ErrorAction Stop
					} else {
						Connect-MgGraph -Identity -NoWelcome -ErrorAction Stop
					}
				}
				'appregistration' {
					Write-LogHost "Using app registration authentication..." -ForegroundColor Gray

					$appTenantId = $script:TenantId
					if ([string]::IsNullOrWhiteSpace($appTenantId)) { $appTenantId = $env:GRAPH_TENANT_ID }
					if ([string]::IsNullOrWhiteSpace($appTenantId)) {
						Write-LogHost "ERROR: -TenantId or GRAPH_TENANT_ID is required for AppRegistration auth." -ForegroundColor Red
						throw "Missing TenantId for AppRegistration authentication"
					}

					$appClientId = $script:ClientId
					if ([string]::IsNullOrWhiteSpace($appClientId)) { $appClientId = $env:GRAPH_CLIENT_ID }
					if ([string]::IsNullOrWhiteSpace($appClientId)) {
						Write-LogHost "ERROR: -ClientId or GRAPH_CLIENT_ID is required for AppRegistration auth." -ForegroundColor Red
						throw "Missing ClientId for AppRegistration authentication"
					}

					# Store auth config for potential re-authentication during long-running operations
					$script:AuthConfig.Method = 'AppRegistration'
					$script:AuthConfig.TenantId = $appTenantId
					$script:AuthConfig.ClientId = $appClientId
					$script:AuthConfig.CertStoreLocation = $script:ClientCertificateStoreLocation

					$secretValue = $script:ClientSecret
					if ([string]::IsNullOrWhiteSpace($secretValue)) { $secretValue = $env:GRAPH_CLIENT_SECRET }

					$certThumbprint = $script:ClientCertificateThumbprint
					if ([string]::IsNullOrWhiteSpace($certThumbprint)) { $certThumbprint = $env:GRAPH_CLIENT_CERT_THUMBPRINT }

					$certPath = $script:ClientCertificatePath
					if ([string]::IsNullOrWhiteSpace($certPath)) { $certPath = $env:GRAPH_CLIENT_CERT_PATH }

					$certPasswordSecure = $script:ClientCertificatePassword
					if (-not $certPasswordSecure -and $env:GRAPH_CLIENT_CERT_PASSWORD) {
						$certPasswordSecure = ConvertTo-SecureString $env:GRAPH_CLIENT_CERT_PASSWORD -AsPlainText -Force
					}

					$certPasswordPlain = $null
					if ($certPasswordSecure) {
						$certPasswordPlain = [System.Net.NetworkCredential]::new('', $certPasswordSecure).Password
					}

					if (-not [string]::IsNullOrWhiteSpace($secretValue)) {
						Write-LogHost "  -> Authenticating with client secret" -ForegroundColor Gray
						$secureSecret = ConvertTo-SecureString -String $secretValue -AsPlainText -Force
						$credential = New-Object System.Management.Automation.PSCredential($appClientId, $secureSecret)
						# Store secret securely for re-authentication (keep a copy before clearing)
						$script:AuthConfig.ClientSecret = $secureSecret.Copy()
						$script:AuthConfig.CanReauthenticate = $true
						Clear-Variable -Name secretValue -Force -ErrorAction SilentlyContinue
						Connect-MgGraph -TenantId $appTenantId -ClientSecretCredential $credential -NoWelcome -ErrorAction Stop
						Clear-Variable -Name secureSecret -Force -ErrorAction SilentlyContinue
						Clear-Variable -Name credential -Force -ErrorAction SilentlyContinue
					}
					elseif (-not [string]::IsNullOrWhiteSpace($certThumbprint)) {
						# Normalize: strip spaces and any non-hex paste artifacts (the Windows cert
						# dialog can prepend a hidden left-to-right mark), then upper-case.
						$certThumbprint = ($certThumbprint -replace '[^0-9A-Fa-f]', '').ToUpperInvariant()
						Write-LogHost "  -> Authenticating with certificate thumbprint $certThumbprint" -ForegroundColor Gray
						# Search the requested store first, then the OTHER store. App-registration
						# certs on servers are commonly in LocalMachine\My even when the run defaults
						# to CurrentUser; this finds the cert in either location.
						$requestedLoc = $script:ClientCertificateStoreLocation
						$otherLoc     = if ($requestedLoc -eq 'LocalMachine') { 'CurrentUser' } else { 'LocalMachine' }
						$certificate  = $null
						$resolvedLoc  = $null
						foreach ($loc in @($requestedLoc, $otherLoc)) {
							$storeLocation = [System.Security.Cryptography.X509Certificates.StoreLocation]::$loc
							$store = New-Object System.Security.Cryptography.X509Certificates.X509Store("My", $storeLocation)
							try {
								$store.Open([System.Security.Cryptography.X509Certificates.OpenFlags]::ReadOnly)
								$match = @($store.Certificates | Where-Object { $_.Thumbprint -eq $certThumbprint })
								if ($match.Count -gt 0) {
									# Prefer a copy that carries the private key.
									$withKey = @($match | Where-Object { $_.HasPrivateKey } | Select-Object -First 1)
									$certificate = if ($withKey.Count -gt 0) { $withKey[0] } else { $match[0] }
									$resolvedLoc = $loc
									break
								}
							}
							catch {
								# This store could not be opened/read (e.g. access denied to
								# LocalMachine\My); skip it and try the other store.
							}
							finally {
								$store.Close()
							}
						}
						if (-not $certificate) {
							Write-LogHost "ERROR: Certificate with thumbprint '$certThumbprint' not found in CurrentUser\My or LocalMachine\My." -ForegroundColor Red
							throw "Certificate not found"
						}
						if (-not $certificate.HasPrivateKey) {
							Write-LogHost "ERROR: Certificate '$certThumbprint' was found in $resolvedLoc\My but has no accessible private key (only the public .cer appears to be installed, or the running account cannot read the key)." -ForegroundColor Red
							throw "Certificate has no usable private key"
						}
						if ($resolvedLoc -ne $requestedLoc) {
							Write-LogHost "  -> Certificate located in $resolvedLoc\My (requested store was $requestedLoc\My)." -ForegroundColor Gray
						}
						# Pin the resolved cert object for the whole run + token refreshes. Passing
						# -Certificate (not -CertificateThumbprint) makes the lookup deterministic and
						# independent of which stores the SDK searches; pinning prevents the
						# SafeCertContext handle from being GC-invalidated on later token requests
						# (same rationale as the -ClientCertificatePath branch).
						$script:AuthConfig.CertThumbprint   = $certThumbprint
						$script:AuthConfig.CertStoreLocation = $resolvedLoc
						$script:AuthConfig.CertObject        = $certificate
						$script:AuthConfig.CanReauthenticate = $true
						Connect-MgGraph -TenantId $appTenantId -ClientId $appClientId -Certificate $certificate -NoWelcome -ErrorAction Stop
					}
					elseif (-not [string]::IsNullOrWhiteSpace($certPath)) {
						Write-LogHost "  -> Authenticating with certificate file $certPath" -ForegroundColor Gray
						# CRITICAL: EphemeralKeySet keeps the private key in process memory only (no temp
						# .pfx-key file in %APPDATA%\Microsoft\Crypto\) and ties the SafeCertContext lifetime
						# to the X509Certificate2 object itself. Without this flag, default DefaultKeySet/UserKeySet
						# storage causes Azure.Identity's ClientCertificateCredential to throw
						# 'm_safeCertContext is an invalid handle' on every token request after the first.
						# Exportable is required so the SDK can re-export the key for token signing.
						$flags = [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::EphemeralKeySet `
							-bor [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::Exportable
						$cert = $null
						try {
							if ($certPasswordPlain) {
								$cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2($certPath, $certPasswordPlain, $flags)
							}
							else {
								# 3-arg ctor with empty password is required so the explicit flags apply.
								$cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2($certPath, [string]'', $flags)
							}
							# Store cert path and password for re-authentication
							$script:AuthConfig.CertPath = $certPath
							if ($certPasswordSecure) { $script:AuthConfig.CertPassword = $certPasswordSecure.Copy() }
							# CRITICAL: Pin the cert object on $script: scope so it lives for the entire run.
							# Azure.Identity's ClientCertificateCredential keeps a managed reference but does
							# NOT clone the SafeCertContext - if the cert is GC'd or Disposed, every later
							# token request fails with 'invalid handle'. The cert MUST NOT be disposed in
							# the finally block; it is released at script exit when $script:AuthConfig is torn down.
							$script:AuthConfig.CertObject = $cert
							$script:AuthConfig.CanReauthenticate = $true
							Connect-MgGraph -TenantId $appTenantId -ClientId $appClientId -Certificate $cert -NoWelcome -ErrorAction Stop
						}
						finally {
							# Intentionally NOT disposing $cert here - it must outlive Connect-MgGraph for the
							# duration of the script run. EphemeralKeySet ensures no on-disk artifacts to clean up;
							# the cert is fully released at script exit when $script:AuthConfig is torn down.
							if ($certPasswordPlain) {
								Clear-Variable -Name certPasswordPlain -Force -ErrorAction SilentlyContinue
							}
						}
					}
					else {
						Write-LogHost "ERROR: Provide either -ClientSecret, -ClientCertificateThumbprint, or -ClientCertificatePath for AppRegistration auth." -ForegroundColor Red
						throw "No credential material supplied for AppRegistration"
					}

					if ($certPasswordSecure) {
						Clear-Variable -Name certPasswordSecure -Force -ErrorAction SilentlyContinue
					}
				}
			}
			
			# Build a context-aware connection-success message
			$connectMsg = if ($AuthMethod.ToLower() -eq 'appregistration') {
				if ($IncludeAgent365Info -or $OnlyAgent365Info) {
					# App-only + Agent 365 reuses this application context; the Agent 365 phase runs
					# app-only against pre-consented application permissions with no interactive sign-in.
					"Successfully connected to Microsoft Graph (app-only context). The Agent 365 phase reuses this application context - no interactive sign-in is required."
				} else {
					"Successfully connected to Microsoft Graph (app-only context)."
				}
			} elseif ($AuthMethod.ToLower() -eq 'managedidentity') {
				if ($IncludeAgent365Info -or $OnlyAgent365Info) {
					"Successfully connected to Microsoft Graph (managed-identity app-only context). The Agent 365 phase reuses this application context - no interactive sign-in is required."
				} else {
					"Successfully connected to Microsoft Graph (managed-identity app-only context)."
				}
			} else {
				"Successfully connected to Microsoft Graph (delegated user context)."
			}
			Write-LogHost $connectMsg -ForegroundColor Green
			
			# Record token issue time for proactive refresh tracking
			$script:AuthConfig.TokenIssueTime = Get-Date
			
			# Initialize shared auth state for thread jobs (enables proactive token refresh)
			$tokenInfo = Get-GraphAccessTokenWithExpiry
			if ($tokenInfo) {
				$script:SharedAuthState.Token = $tokenInfo.Token
				$script:SharedAuthState.ExpiresOn = $tokenInfo.ExpiresOn
				$script:SharedAuthState.LastRefresh = Get-Date
				$script:SharedAuthState.AuthMethod = $AuthMethod.ToLower()
				Write-LogHost "  Token expires: $($tokenInfo.ExpiresOn.ToString('yyyy-MM-dd HH:mm:ss')) UTC (source: $($tokenInfo.Source))" -ForegroundColor Gray
			}
			
			# Get and display current context
			$context = Get-MgContext
			# Detect dual-context run: AppRegistration audit phase + delegated Agent 365 phase.
			# In that case, defer the per-line Tenant/Account/Scopes display until AFTER Phase 2
			# sign-in completes, so the log shows BOTH phases honestly side-by-side. Capture the
			# Phase 1 context now into script-scope vars so the combined emitter can use them.
			#
			# (app-only modes) - or the same delegated context (delegated modes) - so there is no
			# separate Phase 2 context to combine and nothing to defer. Always emit the auth-context
			# display inline below for every auth mode.
			$script:DeferAuthContextDisplay = $false
			if ($script:DeferAuthContextDisplay) {
				$script:Phase1Context = [pscustomobject]@{
					TenantId        = $context.TenantId
					Account         = $context.Account
					GrantedRequired = @($RequiredScopes | Where-Object { $context.Scopes -contains $_ })
					RequiredScopes  = @($RequiredScopes)
				}
				Write-LogHost "  Phase 1 (audit) connected." -ForegroundColor Gray
			} else {
				Write-LogHost "  Tenant ID: $($context.TenantId)" -ForegroundColor Gray
				$maskedAccount = Get-MaskedUsername -Username $context.Account
				if ([string]::IsNullOrWhiteSpace($maskedAccount)) {
					# App-only contexts have no signed-in user; surface the auth mode instead of a blank value.
					$maskedAccount = if ($AuthMethod -eq 'AppRegistration') { '(app-only / AppRegistration - no interactive user)' }
									 elseif ($AuthMethod -eq 'ManagedIdentity') {
										if ($env:AZURE_CLIENT_ID) { "(app-only / ManagedIdentity - clientId $env:AZURE_CLIENT_ID)" }
										else                      { '(app-only / ManagedIdentity - system-assigned)' }
									 }
									 else { '(no signed-in user)' }
				}
				Write-LogHost "  Account:   $maskedAccount" -ForegroundColor Gray
				# Filter displayed scopes to those required by this script (avoids confusion when the
				# user/app holds additional consented scopes unrelated to PAX). Granted required scopes
				# are shown; any required scopes missing from the token are surfaced separately below.
				$grantedRequired = @($RequiredScopes | Where-Object { $context.Scopes -contains $_ })
				Write-LogHost "  Scopes:    $($grantedRequired -join ', ')" -ForegroundColor Gray
			}
			
			# Trigger Graph API version detection early (before queries start)
			$null = Get-GraphAuditApiUri -Path 'queries'
			
			# Validate required scopes are present
			# NOTE: For app-only (AppRegistration) contexts, the access token carries permissions
			# in the 'roles' claim (application permissions), not the 'scp' claim. The Graph SDK
			# only populates $context.Scopes from 'scp', so $context.Scopes is empty/partial for
			# app-only auth even when admin-consented application permissions are fully granted.
			# A scope-membership check would falsely flag every required permission as missing.
			# App permissions are validated server-side at API call time, so we skip the warning.
			$isAppOnlyContext = $false
			if ($context) {
				$isAppOnlyContext = ([string]::IsNullOrWhiteSpace($context.Account)) -or ($context.AuthType -eq 'AppOnly')
			}
			$missingScopes = @()
			if (-not $isAppOnlyContext) {
				foreach ($scope in $RequiredScopes) {
					if ($context.Scopes -notcontains $scope) {
						$missingScopes += $scope
					}
				}
			}
			
			if ($missingScopes.Count -gt 0) {
				Write-LogHost ""
				Write-LogHost "WARNING: Missing required scope(s):" -ForegroundColor Yellow
				foreach ($scope in $missingScopes) {
					Write-LogHost "  • $scope" -ForegroundColor Yellow
				}
				Write-LogHost ""
				Write-LogHost "Script may fail when accessing audit logs." -ForegroundColor Yellow
				Write-LogHost "Consider re-authenticating with full permissions." -ForegroundColor Yellow
				Write-LogHost ""
			}
			
			$script:Connected = $true
		}
		catch {
			Write-LogHost "ERROR: Graph API authentication failed: $($_.Exception.Message)" -ForegroundColor Red
			Write-LogHost ""
			Write-LogHost "Troubleshooting:" -ForegroundColor Yellow
			Write-LogHost "  1. Ensure you have AuditLogsQuery.Read.All permission" -ForegroundColor White
			Write-LogHost "  2. Verify Azure AD role (Compliance/Security Administrator)" -ForegroundColor White
			Write-LogHost "  3. Check network connectivity to Microsoft Graph API" -ForegroundColor White
			Write-LogHost "  4. Try a different authentication method (-Auth parameter)" -ForegroundColor White
			Write-LogHost "  5. Use -UseEOM switch to fall back to EOM mode" -ForegroundColor White
			Write-LogHost ""
			throw
		}
	}
}

# ==============================================
# ACCESS TOKEN EXTRACTION HELPER
# ==============================================
function Get-GraphAccessToken {
	<#
	.SYNOPSIS
		Extracts the current access token from an active Microsoft Graph session.
	
	.DESCRIPTION
		Microsoft Graph PowerShell SDK 2.x does NOT expose AccessToken via Get-MgContext
		for security reasons. This function reliably extracts the token by making a
		lightweight request and extracting the Authorization header.
		
		Primary method: HTTP request header extraction (reliable in SDK 2.x)
		Fallback method: Get-MgContext.AccessToken (for older SDK versions)
	
	.OUTPUTS
		[string] The access token, or $null if extraction fails
	#>
	[CmdletBinding()]
	param()
	
	# Primary method: Extract token from HTTP response headers (reliable in SDK 2.x)
	try {
		$response = Invoke-MgGraphRequest -Method GET -Uri 'https://graph.microsoft.com/v1.0/$metadata' -OutputType HttpResponseMessage -ErrorAction Stop
		$token = $response.RequestMessage.Headers.Authorization.Parameter
		if ($token) {
			return $token
		}
	}
	catch {
		# HTTP method failed, try fallback
	}
	
	# Fallback method: Get-MgContext.AccessToken (works in older SDK versions)
	try {
		$context = Get-MgContext -ErrorAction SilentlyContinue
		if ($context -and $context.AccessToken) {
			return $context.AccessToken
		}
	}
	catch {
		# Fallback also failed
	}
	
	return $null
}

# ==============================================
# ACCESS TOKEN WITH EXPIRY EXTRACTION (for shared auth state)
# ==============================================
function Get-GraphAccessTokenWithExpiry {
	<#
	.SYNOPSIS
		Extracts access token AND expiry time from the active Microsoft Graph session.
	
	.DESCRIPTION
		Decodes the JWT access token to extract the actual 'exp' (expiry) claim.
		This is more reliable than Azure.Identity reflection and doesn't cause
		extra authentication popups.
		
		JWT tokens have three base64-encoded parts: header.payload.signature
		The payload contains the 'exp' claim as a Unix timestamp.
		
		Falls back to 50-minute estimated expiry if JWT decode fails.
	
	.OUTPUTS
		[hashtable] with Token (string) and ExpiresOn (DateTime) properties
		Returns $null if no token can be extracted
	#>
	[CmdletBinding()]
	param()
	
	$result = @{
		Token = $null
		ExpiresOn = $null
		Source = 'unknown'
	}
	
	# First, get the token using existing reliable method
	$result.Token = Get-GraphAccessToken
	if (-not $result.Token) {
		return $null
	}
	
	# Try to decode JWT to get actual expiry from 'exp' claim
	# JWT format: base64url(header).base64url(payload).signature
	try {
		$tokenParts = $result.Token.Split('.')
		if ($tokenParts.Count -ge 2) {
			# Decode the payload (second part)
			$payloadBase64 = $tokenParts[1]
			
			# Add padding if needed (base64url uses no padding)
			$paddingNeeded = 4 - ($payloadBase64.Length % 4)
			if ($paddingNeeded -lt 4) {
				$payloadBase64 += ('=' * $paddingNeeded)
			}
			
			# Convert base64url to standard base64 (replace - with +, _ with /)
			$payloadBase64 = $payloadBase64.Replace('-', '+').Replace('_', '/')
			
			# Decode and parse JSON
			$payloadBytes = [Convert]::FromBase64String($payloadBase64)
			$payloadJson = [System.Text.Encoding]::UTF8.GetString($payloadBytes)
			$payload = $payloadJson | ConvertFrom-Json
			
			if ($payload.exp) {
				# 'exp' is Unix timestamp (seconds since 1970-01-01 UTC)
				$unixEpoch = [DateTime]::new(1970, 1, 1, 0, 0, 0, [DateTimeKind]::Utc)
				$result.ExpiresOn = $unixEpoch.AddSeconds($payload.exp)
				$result.Source = 'JWT'
				
				# Calculate time remaining for logging
				$timeRemaining = $result.ExpiresOn - (Get-Date).ToUniversalTime()
				if ($timeRemaining.TotalMinutes -gt 0) {
					Write-Verbose "Token expires in $([int]$timeRemaining.TotalMinutes) minutes (from JWT 'exp' claim)"
				}
				
				return $result
			}
		}
	}
	catch {
		# JWT decode failed, use fallback
		Write-Verbose "JWT decode failed: $($_.Exception.Message)"
	}
	
	# Fallback: estimate 50-minute expiry from now (observed token lifetime ~45-60 minutes)
	# With 5-minute buffer, proactive refresh triggers at ~45 min mark
	$result.ExpiresOn = (Get-Date).ToUniversalTime().AddMinutes(50)
	$result.Source = 'estimated'
	
	return $result
}

# ==============================================
# TOKEN REFRESH FUNCTION FOR LONG-RUNNING OPERATIONS
# ==============================================
function Invoke-TokenRefresh {
	<#
	.SYNOPSIS
		Forces re-authentication for AppRegistration auth mode to get fresh access token.
	
	.DESCRIPTION
		When using App Registration authentication (client secret or certificate),
		this function reconnects to Microsoft Graph to obtain a fresh access token.
		This is critical for long-running operations that exceed the default OAuth
		token lifetime (~60-90 minutes).
		
		For interactive auth modes, this function returns $false as re-authentication
		would require user interaction.
	
	.PARAMETER Force
		Force re-authentication even if token doesn't appear expired.
	
	.OUTPUTS
		[PSCustomObject] with Success ($true/$false) and NewToken properties
	#>
	[CmdletBinding()]
	param(
		[switch]$Force
	)
	
	$result = [PSCustomObject]@{
		Success = $false
		NewToken = $null
		Message = ""
		AuthMethod = $script:AuthConfig.Method
	}
	
	# Check if we can re-authenticate
	if (-not $script:AuthConfig.CanReauthenticate) {
		$result.Message = "Auth method '$($script:AuthConfig.Method)' does not support automatic re-authentication"
		return $result
	}
	
	# Validate we have stored config
	if ($script:AuthConfig.Method -ne 'AppRegistration') {
		$result.Message = "Only AppRegistration auth mode supports automatic token refresh"
		return $result
	}
	
	if ([string]::IsNullOrWhiteSpace($script:AuthConfig.TenantId) -or 
		[string]::IsNullOrWhiteSpace($script:AuthConfig.ClientId)) {
		$result.Message = "Missing TenantId or ClientId in stored auth config"
		return $result
	}
	
	Write-LogHost "  [TOKEN-REFRESH] Attempting re-authentication using AppRegistration..." -ForegroundColor Cyan
	
	try {
		# Disconnect first to ensure clean state
		try {
			script:Invoke-PaxGraphDisconnect -ErrorAction SilentlyContinue
		} catch { }
		
		# Re-authenticate based on stored credential type
		$reconnected = $false
		
		# Try client secret first
		if ($script:AuthConfig.ClientSecret) {
			Write-LogHost "  [TOKEN-REFRESH] Reconnecting with client secret..." -ForegroundColor Gray
			$credential = New-Object System.Management.Automation.PSCredential(
				$script:AuthConfig.ClientId, 
				$script:AuthConfig.ClientSecret
			)
			Connect-MgGraph -TenantId $script:AuthConfig.TenantId `
				-ClientSecretCredential $credential `
				-NoWelcome -ErrorAction Stop
			$reconnected = $true
		}
		# Try certificate thumbprint
		elseif ($script:AuthConfig.CertThumbprint) {
			Write-LogHost "  [TOKEN-REFRESH] Reconnecting with certificate thumbprint..." -ForegroundColor Gray
			if ($script:AuthConfig.CertObject) {
				# Reuse the cert object resolved + pinned at initial login (carries the
				# CurrentUser/LocalMachine resolution; avoids re-searching the stores).
				Connect-MgGraph -TenantId $script:AuthConfig.TenantId `
					-ClientId $script:AuthConfig.ClientId `
					-Certificate $script:AuthConfig.CertObject `
					-NoWelcome -ErrorAction Stop
			}
			else {
				Connect-MgGraph -TenantId $script:AuthConfig.TenantId `
					-ClientId $script:AuthConfig.ClientId `
					-CertificateThumbprint $script:AuthConfig.CertThumbprint `
					-NoWelcome -ErrorAction Stop
			}
			$reconnected = $true
		}
		# Try certificate file
		elseif ($script:AuthConfig.CertPath) {
			Write-LogHost "  [TOKEN-REFRESH] Reconnecting with certificate file..." -ForegroundColor Gray
			# Prefer the cert object pinned at initial login - it already has the correct
			# EphemeralKeySet+Exportable storage flags applied, and reusing it avoids any
			# chance of leaking a second key file or invalidating the credential's handle.
			$cert = $script:AuthConfig.CertObject
			if (-not $cert) {
				$flags = [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::EphemeralKeySet `
					-bor [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::Exportable
				if ($script:AuthConfig.CertPassword) {
					$plainPassword = [Runtime.InteropServices.Marshal]::PtrToStringAuto(
						[Runtime.InteropServices.Marshal]::SecureStringToBSTR($script:AuthConfig.CertPassword)
					)
					try {
						$cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2(
							$script:AuthConfig.CertPath, $plainPassword, $flags
						)
					}
					finally {
						Clear-Variable -Name plainPassword -Force -ErrorAction SilentlyContinue
					}
				}
				else {
					$cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2(
						$script:AuthConfig.CertPath, [string]'', $flags
					)
				}
				# Re-pin so subsequent refreshes can reuse this same instance.
				$script:AuthConfig.CertObject = $cert
			}
			Connect-MgGraph -TenantId $script:AuthConfig.TenantId `
				-ClientId $script:AuthConfig.ClientId `
				-Certificate $cert `
				-NoWelcome -ErrorAction Stop
			# Intentionally NOT disposing $cert - must outlive Connect-MgGraph for the rest
			# of the run. Cleanup happens at script exit when $script:AuthConfig is released.
			$reconnected = $true
		}
		
		if ($reconnected) {
			# Use reliable token extraction helper (HTTP method primary)
			$result.NewToken = Get-GraphAccessToken
			if ($result.NewToken) {
				$result.Success = $true
				$result.Message = "Successfully refreshed token"
				
				# Update token timing and reset auth failure flags
				$script:AuthConfig.TokenIssueTime = Get-Date
				$script:TokenAcquiredTime = Get-Date
				$script:AuthFailureDetected = $false
				$script:Auth401MessageShown = $false  # Reset for next auth failure cycle
				
				Write-LogHost "  [TOKEN-REFRESH] Successfully obtained fresh access token" -ForegroundColor Green
				Write-LogHost "  [TOKEN-REFRESH] Token acquired at $(Get-Date -Format 'HH:mm:ss') - proactive refresh at 30-minute age" -ForegroundColor DarkGray
			}
			else {
				$result.Message = "Reconnected but could not extract access token"
				Write-LogHost "  [TOKEN-REFRESH] ✗ $($result.Message)" -ForegroundColor Red
			}
		}
		else {
			$result.Message = "No valid credential found in stored auth config"
		}
	}
	catch {
		$result.Message = "Re-authentication failed: $($_.Exception.Message)"
		Write-LogHost "  [TOKEN-REFRESH] ✗ $($result.Message)" -ForegroundColor Red
	}
	
	return $result
}

# ==============================================
# PROACTIVE TOKEN REFRESH FOR LONG-RUNNING OPERATIONS
# ==============================================
# PAX-1E token-refresh lifecycle state (parent-owned; UTC). Defined early so every
# Refresh-GraphTokenIfNeeded call site can record truthful state. Holds ONLY lifecycle
# state + timing - never token or credential material. Set 'Refreshing' before a real
# synchronous refresh attempt; resolve on every outcome path and in a finally so the
# state can never stay stuck at 'Refreshing' after a throw.
function script:Initialize-PaxTokenRefreshState {
	if (-not $script:PaxTokenRefreshState) {
		$script:PaxTokenRefreshState = [pscustomobject]@{
			State = 'Idle'; LastReason = $null; LastAuthMode = $null; StartedUtc = $null
			LastSuccessUtc = $null; LastElapsedSeconds = $null; LastError = $null
		}
	}
}
function script:Set-PaxTokenRefreshing {
	param([string]$Reason, [string]$AuthMode, [Nullable[datetime]]$StartUtc = $null)
	Initialize-PaxTokenRefreshState
	$script:PaxTokenRefreshState.State       = 'Refreshing'
	$script:PaxTokenRefreshState.LastReason  = $Reason
	$script:PaxTokenRefreshState.LastAuthMode = $AuthMode
	$script:PaxTokenRefreshState.StartedUtc   = if ($StartUtc) { [datetime]$StartUtc } else { (Get-Date).ToUniversalTime() }
	$script:PaxTokenRefreshState.LastError     = $null
}
function script:Resolve-PaxTokenRefresh {
	param([bool]$Success, [Nullable[datetime]]$CompletionUtc = $null, [string]$ErrorCategory = $null)
	Initialize-PaxTokenRefreshState
	$done = if ($CompletionUtc) { [datetime]$CompletionUtc } else { (Get-Date).ToUniversalTime() }
	$started = $script:PaxTokenRefreshState.StartedUtc
	if ($started) { $script:PaxTokenRefreshState.LastElapsedSeconds = [Math]::Round(($done - [datetime]$started).TotalSeconds, 1) }
	if ($Success) {
		$script:PaxTokenRefreshState.State          = 'Succeeded'
		$script:PaxTokenRefreshState.LastSuccessUtc = $done
		$script:PaxTokenRefreshState.LastError      = $null
	} else {
		$script:PaxTokenRefreshState.State    = 'Failed'
		$script:PaxTokenRefreshState.LastError = $ErrorCategory
	}
}

function Refresh-GraphTokenIfNeeded {
	<#
	.SYNOPSIS
		Proactively refreshes the Graph access token if it's nearing expiry.
	
	.DESCRIPTION
		Checks SharedAuthState.ExpiresOn and refreshes token if less than 10 minutes
		remain before expiry. Uses Azure.Identity for interactive auth modes, or
		Invoke-TokenRefresh for AppRegistration mode.
		
		This function is called from the main thread's job monitoring loop to ensure
		thread jobs always have a valid token in SharedAuthState.
		
		IMPORTANT: Includes cooldown logic to prevent spam - only attempts refresh
		once per 5 minutes. If silent refresh fails, sets AuthFailureDetected to
		trigger interactive re-auth prompt.
	
	.PARAMETER BufferMinutes
		Refresh if token expires within this many minutes. Default: 5.
	
	.OUTPUTS
		$true - Token was refreshed successfully (silent or interactive)
		$false - No refresh needed (token still valid) or within cooldown period
		'Quit' - User chose to quit at the re-auth prompt
		
		CRITICAL: Callers MUST check for 'Quit' return and handle gracefully!
	#>
	[CmdletBinding()]
	param(
		[int]$BufferMinutes = 5
	)
	
	# Check if we have shared auth state
	if (-not $script:SharedAuthState.ExpiresOn) {
		return $false
	}
	
	$now = (Get-Date).ToUniversalTime()
	$expiresOn = $script:SharedAuthState.ExpiresOn
	$minutesRemaining = ($expiresOn - $now).TotalMinutes
	
	# PROACTIVE REFRESH FOR APPREG: Refresh at 30-minute token age (not just near expiry)
	# AppRegistration can refresh silently, so we do this proactively to avoid 401s
	$needsProactiveRefresh = $false
	if ($script:AuthConfig.Method -eq 'AppRegistration' -and $script:AuthConfig.CanReauthenticate) {
		if ($script:AuthConfig.TokenIssueTime) {
			$tokenAge = (Get-Date) - $script:AuthConfig.TokenIssueTime
			if ($tokenAge.TotalMinutes -gt 30) {
				$needsProactiveRefresh = $true
				Write-LogHost "  [TOKEN] Token age: $([Math]::Round($tokenAge.TotalMinutes, 1)) minutes - proactive refresh triggered" -ForegroundColor Yellow
			}
		}
	}
	
	if ($minutesRemaining -gt $BufferMinutes -and -not $needsProactiveRefresh) {
		return $false  # Token still valid, no refresh needed
	}
	
	# COOLDOWN CHECK: Auth-mode-aware cooldown between refresh attempts
	# AppReg: 45 seconds (silent client_credentials grant - cheap and fast)
	# Interactive: 5 minutes (avoids spamming browser/prompt windows)
	$cooldownMinutes = if ($script:AuthConfig.Method -eq 'AppRegistration') { 0.75 } else { 5 }
	if ($script:LastProactiveRefreshAttempt) {
		$timeSinceLastAttempt = ((Get-Date) - $script:LastProactiveRefreshAttempt).TotalMinutes
		if ($timeSinceLastAttempt -lt $cooldownMinutes) {
			return $false
		}
	}
	$script:LastProactiveRefreshAttempt = Get-Date

	# PAX-1E: mark token-refresh state 'Refreshing' for the duration of this REAL attempt
	# (never on the no-refresh-needed / cooldown early-returns above). Resolved on every
	# outcome path and in the finally so it can never stay stuck after a throw.
	Set-PaxTokenRefreshing -Reason $(if ($needsProactiveRefresh) { 'proactive-age' } else { 'proactive-buffer' }) -AuthMode ("" + $script:AuthConfig.Method) -StartUtc (Get-Date).ToUniversalTime()
	$script:PaxTokenRefreshResolved = $false
	try {

	# Log appropriate message based on trigger reason
	if (-not $needsProactiveRefresh) {
		Write-LogHost "  [TOKEN] Token expires in $([Math]::Round($minutesRemaining, 1)) minutes - attempting proactive refresh..." -ForegroundColor Yellow
	}
	
	# Try to refresh using Azure.Identity (uses cached MSAL tokens, may prompt if needed)
	$tokenInfo = Get-GraphAccessTokenWithExpiry
	if ($tokenInfo -and $tokenInfo.Token -ne $script:SharedAuthState.Token) {
		# Validate the new token is actually valid (ExpiresOn must be > 2 min in the future)
		# Protects against stale MSAL cache returning already-expired tokens (e.g., after process suspension)
		$tokenExpiresOn = $tokenInfo.ExpiresOn
		$nowUtc = (Get-Date).ToUniversalTime()
		$minutesUntilExpiry = ($tokenExpiresOn - $nowUtc).TotalMinutes
		if ($minutesUntilExpiry -le 2) {
			Write-LogHost "  [TOKEN] WARNING: Refreshed token is already expired or near-expiry (expires in $([Math]::Round($minutesUntilExpiry, 1)) min) - forcing full re-authentication" -ForegroundColor Red
			# Fall through to Invoke-TokenRefresh -Force below
		} else {
			# Got a genuinely valid new token
			$script:SharedAuthState.Token = $tokenInfo.Token
			$script:SharedAuthState.ExpiresOn = $tokenInfo.ExpiresOn
			$script:SharedAuthState.LastRefresh = Get-Date
			$script:SharedAuthState.RefreshCount++
			
			Write-LogHost "  [TOKEN] Token refreshed silently (expires: $($tokenInfo.ExpiresOn.ToString('HH:mm:ss')) UTC, refresh #$($script:SharedAuthState.RefreshCount))" -ForegroundColor Green
			Write-LogHost "  [TOKEN]   Note: In-flight queries may still require re-auth before this expiration" -ForegroundColor DarkGray
			Resolve-PaxTokenRefresh -Success $true -CompletionUtc (Get-Date).ToUniversalTime(); $script:PaxTokenRefreshResolved = $true
			return $true
		}
	}
	
	# Azure.Identity didn't give us a new token (or it was stale), try AppRegistration refresh if available
	if ($script:AuthConfig.CanReauthenticate) {
		$refreshResult = Invoke-TokenRefresh -Force
		if ($refreshResult.Success) {
			$script:SharedAuthState.Token = $refreshResult.NewToken
			$script:SharedAuthState.ExpiresOn = (Get-Date).ToUniversalTime().AddMinutes(50)
			$script:SharedAuthState.LastRefresh = Get-Date
			$script:SharedAuthState.RefreshCount++
			$script:AuthConfig.TokenIssueTime = Get-Date  # Reset age timer for proactive refresh
			
			Write-LogHost "  [TOKEN] Token refreshed via AppRegistration (refresh #$($script:SharedAuthState.RefreshCount))" -ForegroundColor Green
			Resolve-PaxTokenRefresh -Success $true -CompletionUtc (Get-Date).ToUniversalTime(); $script:PaxTokenRefreshResolved = $true
			return $true
		}
	}
	
	# SILENT REFRESH FAILED
	# For AppRegistration + Force: FATAL exit (true headless operation)
	# For AppRegistration without Force: Fall back to interactive prompt
	# For interactive modes: Prompt user for re-authentication
	Write-LogHost "  [TOKEN] [!] Silent token refresh failed - interactive re-authentication required" -ForegroundColor Red
	
	# AppRegistration mode with -Force: Silent refresh failure is fatal (no interactive fallback for headless runs)
	if ($script:AuthConfig.Method -eq 'AppRegistration' -and $Force) {
		Write-LogHost "  [TOKEN] FATAL: AppRegistration token refresh failed. Cannot continue headless (-Force mode)." -ForegroundColor Red
		Write-LogHost "  [TOKEN] Check: client secret expiration, certificate validity, or API permissions." -ForegroundColor Yellow
		Resolve-PaxTokenRefresh -Success $false -CompletionUtc (Get-Date).ToUniversalTime() -ErrorCategory 'Fatal'; $script:PaxTokenRefreshResolved = $true
		return 'Quit'
	}
	
	# Interactive modes OR AppRegistration without -Force: prompt user for re-authentication
	$refreshResult = Invoke-TokenRefreshPrompt
	if ($refreshResult -eq 'Quit') {
		# User chose to quit - return special value for callers to handle
		Resolve-PaxTokenRefresh -Success $false -CompletionUtc (Get-Date).ToUniversalTime() -ErrorCategory 'UserQuit'; $script:PaxTokenRefreshResolved = $true
		return 'Quit'
	}
	
	# User pressed R and successfully re-authenticated
	# Invoke-TokenRefreshPrompt already updated SharedAuthState and reset AuthFailureDetected
	Resolve-PaxTokenRefresh -Success $true -CompletionUtc (Get-Date).ToUniversalTime(); $script:PaxTokenRefreshResolved = $true
	return $true
	}
	finally {
		if (-not $script:PaxTokenRefreshResolved) { Resolve-PaxTokenRefresh -Success $false -CompletionUtc (Get-Date).ToUniversalTime() -ErrorCategory 'RefreshError' }
	}
}

# ==============================================
# CHECKPOINT/RESUME FUNCTIONS FOR LONG-RUNNING OPERATIONS
# ==============================================

function Initialize-CheckpointForNewRun {
	<#
	.SYNOPSIS
		Creates new checkpoint structure for a fresh run (not resume mode).
	.DESCRIPTION
		Initializes checkpoint data structure with all processing parameters,
		creates _PARTIAL output filename, and saves initial checkpoint file to disk.
		On resume, all parameters are restored from checkpoint to ensure consistency.
	#>
	param(
		[Parameter(Mandatory)]
		[string]$OutputPath,
		
		[Parameter(Mandatory)]
		[string]$BaseOutputFileName,
		
		[Parameter(Mandatory)]
		[string]$RunTimestamp,
		
		[Parameter(Mandatory)]
		[datetime]$StartDate,
		
		[Parameter(Mandatory)]
		[datetime]$EndDate,
		
		[Parameter()]
		[hashtable]$AllParameters
	)
	
	# Create _PARTIAL filename
	$fileNameWithoutExt = [System.IO.Path]::GetFileNameWithoutExtension($BaseOutputFileName)
	$fileExt = [System.IO.Path]::GetExtension($BaseOutputFileName)
	$partialFileName = "${fileNameWithoutExt}_PARTIAL${fileExt}"
	$script:PartialOutputPath = Join-Path $OutputPath $partialFileName
	
	# Create checkpoint file path (hidden file with dot prefix)
	$script:CheckpointPath = Join-Path $OutputPath ".pax_checkpoint_${RunTimestamp}.json"

	# Acquire exclusive lock on this checkpoint so a second replica running against
	# the same OutputPath cannot silently corrupt our state. Fails loudly if another
	# live PAX process is already using this checkpoint.
	script:Acquire-CheckpointLock -CheckpointPath $script:CheckpointPath
	
	# Initialize checkpoint data structure with comprehensive parameter snapshot
	$script:CheckpointData = @{
		version = 2  # Bumped version for expanded parameter storage
		# Structured schema/compatibility metadata. Read-Checkpoint
		# uses these for forward/backward compatibility checks (Test-CheckpointCompatibility).
		# `checkpointSchemaVersion` is a SemVer-style identifier for the file format. The
		# legacy integer `version` field is preserved for older readers.
		checkpointSchemaVersion    = '2.1.0'
		compatibilityMinimumVersion = '1.11.0'
		createdByVersion           = $ScriptVersion
		createdUtc                 = (Get-Date).ToUniversalTime().ToString('o')
		checkpointType             = 'PurviewAudit'
		runTimestamp = $RunTimestamp
		created = (Get-Date).ToUniversalTime().ToString('o')
		lastUpdated = (Get-Date).ToUniversalTime().ToString('o')
		parameters = @{
			# Date range
			startDate = $StartDate.ToUniversalTime().ToString('o')
			endDate = $EndDate.ToUniversalTime().ToString('o')
			
			# Activity/Record filtering
			activityTypes = if ($AllParameters.ActivityTypes) { @($AllParameters.ActivityTypes) } else { @() }
			recordTypes = if ($AllParameters.RecordTypes) { @($AllParameters.RecordTypes) } else { @() }
			serviceTypes = if ($AllParameters.ServiceTypes) { @($AllParameters.ServiceTypes) } else { @() }
			userIds = if ($AllParameters.UserIds) { @($AllParameters.UserIds) } else { @() }
			groupNames = if ($AllParameters.GroupNames) { @($AllParameters.GroupNames) } else { @() }
			
			# Agent filtering
			agentId = if ($AllParameters.AgentId) { @($AllParameters.AgentId) } else { @() }
			agentsOnly = [bool]$AllParameters.AgentsOnly
			excludeAgents = [bool]$AllParameters.ExcludeAgents
			
			# Prompt filtering
			promptFilter = if ($AllParameters.PromptFilter) { $AllParameters.PromptFilter } else { $null }
			
			# Schema/Explosion settings
			explodeArrays = [bool]$AllParameters.ExplodeArrays
			explodeDeep = [bool]$AllParameters.ExplodeDeep
			explosionThreads = if ($AllParameters.ExplosionThreads) { $AllParameters.ExplosionThreads } else { 0 }
			flatDepth = if ($AllParameters.FlatDepth) { $AllParameters.FlatDepth } else { 120 }
			streamingSchemaSample = if ($AllParameters.StreamingSchemaSample) { $AllParameters.StreamingSchemaSample } else { 5000 }
			streamingChunkSize = if ($AllParameters.StreamingChunkSize) { $AllParameters.StreamingChunkSize } else { 5000 }
			
			# M365/User info bundles
			includeM365Usage = [bool]$AllParameters.IncludeM365Usage
			includeUserInfo = [bool]$AllParameters.IncludeUserInfo
			includeCopilotInteraction = [bool]$AllParameters.IncludeCopilotInteraction
			excludeCopilotInteraction = [bool]$AllParameters.ExcludeCopilotInteraction
			includeAgent365Info = [bool]$AllParameters.IncludeAgent365Info
			onlyAgent365Info = [bool]$AllParameters.OnlyAgent365Info
			
			# Partitioning
			blockHours = if ($AllParameters.BlockHours) { $AllParameters.BlockHours } else { 0.5 }
			partitionHours = if ($AllParameters.PartitionHours) { $AllParameters.PartitionHours } else { 0 }
			maxPartitions = if ($AllParameters.MaxPartitions) { $AllParameters.MaxPartitions } else { 160 }
			
			# Output settings
			# Persist the USER-SUPPLIED -OutputPath (SharePoint URL / Fabric OneLake URL /
			# local path), NOT the script-rewritten local scratch dir. At checkpoint-save
			# time $OutputPath has already been redirected to $script:RemoteScratchDir for
			# remote modes (the parse-time redirect block earlier in the script), so saving
			# $OutputPath here would lose the destination URL and a -Resume run would
			# re-resolve the tier as 'Local' — no upload sweep would ever fire.
			#
			# $script:DestRaw['Purview'] is the canonical source of truth. It is populated
			# at parse-time from the ORIGINAL CLI-bound value (the SharePoint / Fabric URL
			# or local path) BEFORE the scratch redirect runs, and is REPOPULATED on each
			# resume from the restored value BEFORE the resume-side scratch redirect
			# rewrites $OutputPath — so it carries the user-supplied destination across
			# both fresh runs and resumes. Falls back to $OutputPath only for runs where
			# -OutputPath was never bound and $script:DestRaw['Purview'] is unset
			# (default PSScriptRoot). Tier-agnostic: identical behavior for Local,
			# SharePoint, and Fabric (OneLake) modes.
			outputPath = if ($script:DestRaw -and $script:DestRaw['Purview']) { [string]$script:DestRaw['Purview'] } else { $OutputPath }
			exportWorkbook = [bool]$AllParameters.ExportWorkbook
			combineOutput = [bool]$AllParameters.CombineOutput
			# Deidentify: persisted so a resumed run keeps the original run's anonymization.
			# -Deidentify cannot be passed on the resume command line (resume allow-list rejects
			# it), so the checkpoint is the sole source of truth for it on resume.
			deidentify = [bool]$AllParameters.Deidentify

			# FillerLabel: persisted (resolved hierarchy-filler mode + literal) so a resumed
			# AIO/AIBV rollup keeps the original run's level-filler choice. -FillerLabel /
			# -FillerLabelText cannot be passed on resume (allow-list), so the checkpoint is the
			# sole source of truth for them on resume.
			fillerLabelMode = [string]$AllParameters.FillerLabel
			fillerLabelText = [string]$AllParameters.FillerLabelText

			# Append-mode targets. Persisted so a resumed run continues to merge
			# against the same target file/dim, even if the resume command line omits the
			# -Append* parameter. Empty string means "not set on this run".
			appendFile = if ($AllParameters.AppendFile) { [string]$AllParameters.AppendFile } else { '' }
			appendUserInfo = if ($AllParameters.AppendUserInfo) { [string]$AllParameters.AppendUserInfo } else { '' }
			appendAgent365Info = if ($AllParameters.AppendAgent365Info) { [string]$AllParameters.AppendAgent365Info } else { '' }

			# Per-data-type destinations (captured so resume re-targets correctly).
			# Storage tier is inferred from each value's form at resume time; no separate
			# tier field is persisted.
			outputPathUserInfo = if ($AllParameters.OutputPathUserInfo) { [string]$AllParameters.OutputPathUserInfo } else { '' }
			outputPathAgent365Info = if ($AllParameters.OutputPathAgent365Info) { [string]$AllParameters.OutputPathAgent365Info } else { '' }
			outputPathLog = if ($AllParameters.OutputPathLog) { [string]$AllParameters.OutputPathLog } else { '' }
			outputDestinationType = if ($script:RemoteOutputMode) { [string]$script:RemoteOutputMode } else { 'None' }

			# Rollup post-processor mode (None|Rollup|RollupPlusRaw) and the resolved
			# embedded-processor mode (None|CopilotInteraction|M365Bundle). Persisted so resume
			# runs can restore the original rollup intent when the user does not pass a switch
			# on the resume command line. If a rollup switch IS passed on resume, the resume
			# value wins (last-write-wins) and these fields are overwritten on the next save.
			rollupMode = if ([bool]$AllParameters.Rollup) { 'Rollup' } elseif ([bool]$AllParameters.RollupPlusRaw) { 'RollupPlusRaw' } else { 'None' }
			processorMode = if ($script:RollupProcessorMode) { $script:RollupProcessorMode } else { 'None' }
			# Resolved rollup dashboard (None|AIO|AIBV|M365). Persisted so a resumed
			# CopilotInteraction run restores the correct --profile (AIO vs AIBV cannot
			# be re-derived from -IncludeM365Usage alone). Last-write-wins on resume.
			rollupDashboard = if ($script:RollupDashboard) { $script:RollupDashboard } else { 'None' }
			# Dashboard value (AISID etc.), distinct from the embedded rollup processor
			# profile above. Persisted so a resume restores the dashboard the run was launched with
			# (an AISID run embeds the AIO processor, so rollupDashboard alone cannot recover it).
			dashboard = if ([string]$AllParameters.Dashboard -ieq 'ValueLens') { 'ValueLens' } elseif ($AllParameters.Dashboard) { [string]$AllParameters.Dashboard } else { 'None' }
			# AISID (Defender) output set destination + delta-cache switch - restored on resume so
			# an AISID resume re-targets and re-caches exactly as the original run did.
			outputPathDefenderUsage = if ($AllParameters.OutputPathDefenderUsage) { [string]$AllParameters.OutputPathDefenderUsage } else { '' }
			appendDefenderUsage = if ($AllParameters.AppendDefenderUsage) { [string]$AllParameters.AppendDefenderUsage } else { '' }
			disableAISIDDeltaCache = [bool]$AllParameters.DisableAISIDDeltaCache
			# Resolved AISID (DefenderUsage) output folder — the same Resolve-DataTypePaths
			# 'DefenderUsage' .EffectiveDir value shown in the parameter snapshot / metrics JSON,
			# persisted so a resume checkpoint records where the AISID CSV set was routed.
			resolvedDefenderUsageDir = (script:Get-AISIDResolvedOutputDir)
			
			# Auth (method only - no secrets)
			auth = if ($AllParameters.Auth) { $AllParameters.Auth } else { 'WebLogin' }
			tenantId = if ($AllParameters.TenantId) { $AllParameters.TenantId } else { $null }
			clientId = if ($AllParameters.ClientId) { $AllParameters.ClientId } else { $null }
			# Note: ClientSecret is NOT stored for security
			
			# Other settings
			resultSize = if ($AllParameters.ResultSize) { $AllParameters.ResultSize } else { 10000 }
			maxConcurrency = if ($AllParameters.MaxConcurrency) { $AllParameters.MaxConcurrency } else { 10 }
			maxMemoryMB = if ($AllParameters.MaxMemoryMB) { $AllParameters.MaxMemoryMB } else { 0 }
			useEOM = [bool]$AllParameters.UseEOM
			autoCompleteness = [bool]$AllParameters.AutoCompleteness
			includeTelemetry = [bool]$AllParameters.IncludeTelemetry
		}
		outputFiles = @{
			partialCsv = $partialFileName
			finalCsv = $BaseOutputFileName
		}
		partitions = @{
			total = 0
			blockHours = if ($AllParameters.BlockHours) { $AllParameters.BlockHours } else { 0.5 }
			completed = @()
			queryCreated = @()
			# Durable uncertain-create bucket: partitions whose first create POST may have
			# been accepted but cannot be proven. Absent on legacy checkpoints; treated as
			# empty on load. A partition here is reconciled read-only on resume and NEVER
			# re-POSTed.
			uncertainCreate = @()
		}
		statistics = @{
			totalRecordsSaved = 0
			partitionsComplete = 0
			partitionsQueryCreated = 0
			partitionsRemaining = 0
		}
		explosion = @{
			status = 'NotStarted'  # NotStarted, InProgress, Completed
			recordsProcessed = 0
			rowsGenerated = 0
			lastUpdateTime = $null
		}
		# AISID rolling-window intersection state; present only for -Dashboard AISID runs,
		# else $null. Persists the frozen ReferenceNowUtc plus requested/available/effective bounds and
		# clip status so a resume replays the run's frozen window instead of the resume-time clock.
		aisidWindow = if ($script:AISIDWindow) {
			@{
				referenceNowUtc   = $script:AISIDWindow.ReferenceNowUtc.ToString('o')
				requestedStartUtc = $script:AISIDWindow.RequestedStartUtc.ToString('o')
				requestedEndUtc   = $script:AISIDWindow.RequestedEndUtc.ToString('o')
				availableStartUtc = $script:AISIDWindow.AvailableStartUtc.ToString('o')
				availableEndUtc   = $script:AISIDWindow.AvailableEndUtc.ToString('o')
				effectiveStartUtc = $script:AISIDWindow.EffectiveStartUtc.ToString('o')
				effectiveEndUtc   = $script:AISIDWindow.EffectiveEndUtc.ToString('o')
				status            = [string]$script:AISIDWindow.Status
				wasClipped        = [bool]$script:AISIDWindow.WasClipped
				clipReason        = [string]$script:AISIDWindow.ClipReason
				retentionDays     = [int]$script:AISIDWindow.RetentionDays
			}
		} else { $null }
		# AISID resume-state version marker. Present (=1) only when this run resolved an AISID window
		# AND persisted the dashboard + DefenderUsage destination + cache state above. Its presence
		# marks a checkpoint that carries the full AISID resume state (dashboard + destination), versus
		# one that stores only the collection window.
		aisidResumeStateVersion = if ($script:AISIDWindow) { 1 } else { $null }
	}
	
	# Save initial checkpoint
	Save-CheckpointToDisk
	
	return $script:PartialOutputPath
}

# Contract version stamped into every resume commit manifest. A manifest whose
# contractVersion does not match is treated as unverifiable and is never selected.
# Version 2 adds the mandatory nonce-bearing generationId, so remote generation and
# authority-record identity no longer depends on a numeric sequence alone.
# Version 3 adds the mandatory per-artifact CONTENT identity (sha256 + role). A
# self-digest proves the manifest is the complete object the writer intended; it says
# nothing about the bytes the manifest REFERS to. Recording the writer-computed digest
# of each artifact is what lets a reader re-derive the digest from the bytes it actually
# downloaded and prove the artifact set is the one that was committed.
$script:FabricResumeMirrorContractVersion = 3

function Get-FabricResumeArtifactSha256 {
	<#
	.SYNOPSIS
		Lowercase-hex SHA256 of a local file, streamed so an arbitrarily large shard or
		partial output is never materialised in memory.
	.DESCRIPTION
		This is the ONLY content-identity primitive the resume protocol uses. A
		size/mtime stamp is a change HINT, not an identity: two different payloads can
		share a length, and a stamp says nothing about the bytes a remote object holds.
		The writer records this digest for every artifact it publishes and the reader
		re-derives it from the bytes it downloaded, so a same-length substitution is
		detected instead of silently resumed.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)] [string] $Path)
	$sha = [System.Security.Cryptography.SHA256]::Create()
	try {
		$stream = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
		try { $hash = $sha.ComputeHash($stream) }
		finally { $stream.Dispose() }
		return (($hash | ForEach-Object { $_.ToString('x2') }) -join '')
	}
	finally { $sha.Dispose() }
}

function Test-FabricResumeArtifactPath {
	<#
	.SYNOPSIS
		Returns $true only for a safe run-relative resume artifact path.
	.DESCRIPTION
		An artifact path arrives from a remote manifest, so it is untrusted input that is
		about to be joined onto a local directory. A rooted path, a drive qualifier, a
		backslash or duplicated separator, a trailing separator, or any '.'/'..' segment
		could place a hydrated file OUTSIDE the resume directory, so every one of them
		fails closed. Only plain forward-slash-separated relative segments are accepted.
	#>
	[CmdletBinding()]
	param([string] $Path)
	$p = [string]$Path
	if ([string]::IsNullOrWhiteSpace($p)) { return $false }
	if ($p.Contains('\') -or $p.Contains(':')) { return $false }
	if ($p.StartsWith('/') -or $p.EndsWith('/') -or $p.Contains('//')) { return $false }
	foreach ($seg in $p.Split('/')) {
		if ($seg -eq '' -or $seg -eq '.' -or $seg -eq '..') { return $false }
	}
	return $true
}

function New-FabricResumeCommitIntegrity {
	<#
	.SYNOPSIS
		Deterministic integrity digest over the identity-bearing fields of a resume
		commit manifest.
	.DESCRIPTION
		The commit manifest is the single object whose successful write promotes a
		staged generation to authoritative. OneLake file creation is a multi-request
		PUT/PATCH/flush sequence, so a torn or truncated manifest object IS possible.
		This digest lets a reader prove the manifest it downloaded is the complete
		object the writer intended: it is computed over contractVersion, runTimestamp,
		generation, and the ordered artifact tuples, and is embedded in the manifest.
		A manifest whose recomputed digest disagrees is torn/ambiguous and is rejected.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)] [object] $Manifest)
	$sb = [System.Text.StringBuilder]::new()
	[void]$sb.Append([string]$Manifest.contractVersion)
	[void]$sb.Append('|'); [void]$sb.Append([string]$Manifest.runTimestamp)
	[void]$sb.Append('|'); [void]$sb.Append([string]$Manifest.generation)
	# The nonce-bearing generation identity is part of the digested identity, so two
	# authority records that share a sequence but name different generations can never
	# produce the same digest and are always distinguishable on read.
	[void]$sb.Append('|'); [void]$sb.Append([string]$Manifest.generationId)
	foreach ($a in @($Manifest.artifacts)) {
		[void]$sb.Append('|')
		[void]$sb.Append([string]$a.localPath); [void]$sb.Append('>')
		[void]$sb.Append([string]$a.remotePath); [void]$sb.Append('>')
		[void]$sb.Append([string]$a.generation); [void]$sb.Append('>')
		[void]$sb.Append([string]$a.length); [void]$sb.Append('>')
		# The artifact role and its CONTENT digest are part of the digested identity, so a
		# manifest cannot be re-pointed at different bytes (or have its checkpoint role
		# moved) while still presenting a valid self-digest.
		[void]$sb.Append([string]$a.role); [void]$sb.Append('>')
		[void]$sb.Append([string]$a.sha256)
	}
	$sha = [System.Security.Cryptography.SHA256]::Create()
	try {
		$hash = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($sb.ToString()))
		return (($hash | ForEach-Object { $_.ToString('x2') }) -join '')
	}
	finally { $sha.Dispose() }
}

function Test-FabricResumeCommitManifest {
	<#
	.SYNOPSIS
		Validates a downloaded resume commit manifest. Returns $true only for a
		complete, self-consistent, current-contract manifest.
	.DESCRIPTION
		FAIL CLOSED by design: any missing field, wrong contract version, non-positive
		generation, malformed artifact entry, or integrity-digest mismatch returns
		$false so the caller falls back to an OLDER verified generation instead of
		guessing. Never throws - an unreadable manifest is simply not verified.

		The artifact list is validated as a SET, not merely element by element: every
		local path and every remote path must be unique, every remote path must live in
		the generation folder its own owning generation names, every artifact must carry
		a well-formed content digest and a non-negative length, and exactly one artifact
		may carry the checkpoint role. Structural validation here proves the manifest is
		internally consistent and complete; it does NOT prove the referenced objects hold
		those bytes. That proof is re-derived from the downloaded bytes in
		Copy-FabricResumeCommitArtifacts, and a generation is usable only when BOTH pass.
	#>
	[CmdletBinding()]
	param([object] $Manifest)
	if (-not $Manifest) { return $false }
	$names = @($Manifest.PSObject.Properties | ForEach-Object { $_.Name })
	foreach ($f in @('contractVersion', 'runTimestamp', 'generation', 'generationId', 'artifacts', 'integritySha256')) {
		if ($names -notcontains $f) { return $false }
	}
	$contract = 0
	if (-not [int]::TryParse([string]$Manifest.contractVersion, [ref]$contract)) { return $false }
	if ($contract -ne $script:FabricResumeMirrorContractVersion) { return $false }
	if ([string]::IsNullOrWhiteSpace([string]$Manifest.runTimestamp)) { return $false }
	$gen = 0
	if (-not [int]::TryParse([string]$Manifest.generation, [ref]$gen)) { return $false }
	if ($gen -lt 1) { return $false }
	# The generation identity must carry BOTH the ordering sequence and a nonce, and the
	# sequence it carries must agree with the numeric generation field. A sequence-only
	# name is rejected: object identity may never rely on a reusable sequence alone.
	$genId = [string]$Manifest.generationId
	if ($genId -notmatch '^gen-(\d+)-[0-9a-f]{16,}$') { return $false }
	if ([int]$Matches[1] -ne $gen) { return $false }
	if ($null -eq $Manifest.artifacts) { return $false }
	$artifactList = @($Manifest.artifacts)
	if ($artifactList.Count -lt 1) { return $false }
	$seenLocal = @{}
	$seenRemote = @{}
	$checkpointCount = 0
	foreach ($a in $artifactList) {
		if (-not $a) { return $false }
		$an = @($a.PSObject.Properties | ForEach-Object { $_.Name })
		foreach ($af in @('localPath', 'remotePath', 'generation', 'length', 'sha256', 'role')) {
			if ($an -notcontains $af) { return $false }
		}
		# The local path is untrusted input that is about to be joined onto a local
		# directory, so traversal, rooted and alternate-separator forms fail closed.
		$lp = [string]$a.localPath
		if (-not (Test-FabricResumeArtifactPath -Path $lp)) { return $false }
		if ($seenLocal.ContainsKey($lp)) { return $false }
		$seenLocal[$lp] = $true

		$aGen = 0
		if (-not [int]::TryParse([string]$a.generation, [ref]$aGen)) { return $false }
		# An artifact may be owned by this generation or INHERITED from an earlier one,
		# but never from a generation that does not exist yet.
		if ($aGen -lt 1 -or $aGen -gt $gen) { return $false }

		# An artifact must live inside the generation folder its OWN owning generation
		# names, and the path inside that folder must be exactly its local path. A bare
		# (non-generational) or disagreeing remote path would let a reader hydrate from
		# unstaged, unknown, or another generation's state.
		$rp = [string]$a.remotePath
		if (-not $rp) { return $false }
		$slash = $rp.IndexOf('/')
		if ($slash -lt 1) { return $false }
		$genFolder = $rp.Substring(0, $slash)
		$genRest = $rp.Substring($slash + 1)
		if ($genFolder -notmatch '^gen-(\d+)-[0-9a-f]{16,}$') { return $false }
		if ([int]$Matches[1] -ne $aGen) { return $false }
		if ($genRest -cne $lp) { return $false }
		if ($seenRemote.ContainsKey($rp)) { return $false }
		$seenRemote[$rp] = $true

		$len = [int64]0
		if (-not [int64]::TryParse([string]$a.length, [ref]$len)) { return $false }
		if ($len -lt 0) { return $false }

		# Content identity is mandatory: without it a manifest can only prove its own
		# shape, never that the objects it names hold the committed bytes.
		if (([string]$a.sha256) -cnotmatch '^[0-9a-f]{64}$') { return $false }

		$role = [string]$a.role
		if ($role -ceq 'checkpoint') { $checkpointCount++ }
		elseif ($role -cne 'artifact') { return $false }
	}
	# A resume generation without exactly one checkpoint is not a resumable transaction.
	if ($checkpointCount -ne 1) { return $false }
	if ((New-FabricResumeCommitIntegrity -Manifest $Manifest) -cne [string]$Manifest.integritySha256) { return $false }
	return $true
}

function New-FabricResumeGenerationNonce {
	<#
	.SYNOPSIS
		Collision-resistant lowercase-hex nonce appended to every resume generation
		folder name and authority-record name.
	.DESCRIPTION
		A numeric sequence is USEFUL FOR ORDERING but is NOT an identity: it is derived
		from a listing that may be stale or eventually consistent, and two processes (or
		one process before and after a restart) can compute the same next sequence. The
		nonce makes the remote object NAME unique regardless, so a stale listing can
		never cause one generation to overwrite another.
	#>
	[CmdletBinding()]
	param()
	return ([guid]::NewGuid().ToString('n').Substring(0, 16))
}

function Get-FabricResumeNameSequence {
	<#
	.SYNOPSIS
		Parses the ordering sequence out of a resume generation folder name or authority
		record leaf name. Returns -1 when the name is not a resume protocol name.
	.DESCRIPTION
		Accepts BOTH the nonce-bearing current form (gen-<n>-<nonce>,
		commit-<n>-<nonce>.json) and the earlier sequence-only form (gen-<n>,
		commit-<n>.json). The earlier form is accepted HERE ONLY so that such a name
		still RESERVES its sequence for high-water purposes; it is never written and,
		because the manifest contract requires a nonce-bearing generationId, it is never
		selected as authoritative.
	#>
	[CmdletBinding()]
	param([string] $Name)
	$n = [string]$Name
	if ($n -match '^gen-(\d+)(-[0-9a-f]+)?$') { return [int]$Matches[1] }
	if ($n -match '^commit-(\d+)(-[0-9a-f]+)?\.json$') { return [int]$Matches[1] }
	return -1
}

function Get-FabricResumeRemoteHighWater {
	<#
	.SYNOPSIS
		Highest sequence observed anywhere in a run's remote mirror listing.
	.DESCRIPTION
		Considers EVERY generation folder name and EVERY authority-record name, including
		orphaned staging generations that carry no authority record and authority records
		that fail verification. An orphan still RESERVES its name, so allocating strictly
		above this value is what keeps a retry (or a restarted process) from re-staging
		into a name that already exists remotely.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)] [AllowNull()] [AllowEmptyCollection()] [string[]] $RelativePaths)
	$high = 0
	foreach ($p in @($RelativePaths)) {
		$rest = [string]$p
		if (-not $rest) { continue }
		$seq = if ($rest.StartsWith('commits/')) {
			Get-FabricResumeNameSequence -Name ($rest.Substring(8))
		}
		else {
			Get-FabricResumeNameSequence -Name ($rest.Split('/')[0])
		}
		if ($seq -gt $high) { $high = $seq }
	}
	return $high
}

function Get-FabricResumeRunListing {
	<#
	.SYNOPSIS
		Lists everything under Files/.pax_resume/<RunTimestamp>/ and returns the paths
		RELATIVE to that run folder (directories included).
	.DESCRIPTION
		Directories are deliberately INCLUDED: a staging generation whose very first
		artifact upload failed can exist as a folder with no files, and its name still
		reserves a sequence. A 404 means the run has no mirror yet and yields an empty
		listing; any other listing failure THROWS, because a publication that cannot
		observe the remote high-water mark must fail closed rather than guess.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)] [string] $RunTimestamp)
	if (-not $script:FabricResolved) { $script:FabricResolved = Resolve-FabricTarget -Url $script:RemoteOutputUrl }
	$resolved = $script:FabricResolved
	$relInItem = if ($resolved.FilesPath) { "$($resolved.FilesPath)/.pax_resume/$RunTimestamp" } else { ".pax_resume/$RunTimestamp" }
	$dirParam  = [System.Uri]::EscapeDataString("Files/$relInItem")
	$listUri   = "$($resolved.FilesystemBase)?resource=filesystem&recursive=true&directory=$($resolved.ItemFull)/$dirParam"

	$resp = $null
	try {
		$resp = Invoke-FabricWebRequest -Uri $listUri -Method GET
	}
	catch {
		$status = try { $_.Exception.Response.StatusCode.value__ } catch { 0 }
		if ($status -eq 404) { return @() }
		throw
	}
	if (-not $resp -or -not $resp.Content) { return @() }
	$parsed = $resp.Content | ConvertFrom-Json -ErrorAction Stop
	if (-not $parsed -or -not $parsed.paths) { return @() }

	$prefix = "$($resolved.ItemFull)/Files/$relInItem/"
	$out = New-Object System.Collections.Generic.List[string]
	foreach ($entry in $parsed.paths) {
		$name = "$($entry.name)"
		$rest = if ($name.StartsWith($prefix)) { $name.Substring($prefix.Length) } else { Split-Path -Leaf $name }
		if ($rest) { [void]$out.Add($rest) }
	}
	return $out.ToArray()
}

function ConvertTo-FabricResumeOwnership {
	<#
	.SYNOPSIS
		Converts a VERIFIED commit manifest's artifact list into an ownership map.
	.DESCRIPTION
		Ownership reconstructed from a remote manifest ALONE is recorded with
		InheritEligible = $false. The manifest states the digest the writer computed; it
		is not proof that the remote object still holds those bytes, and a local
		size/mtime stamp is not content identity either. Inheritance therefore requires a
		digest that was RE-DERIVED from bytes actually downloaded and verified - that map
		is produced by Copy-FabricResumeCommitArtifacts and recorded through
		Register-FabricResumeRestoredState, never inferred here.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)] [object] $Manifest)
	$map = @{}
	foreach ($a in @($Manifest.artifacts)) {
		$map[[string]$a.localPath] = @{
			RemotePath      = [string]$a.remotePath
			Generation      = [int]$a.generation
			Length          = [int64]$a.length
			Sha256          = [string]$a.sha256
			Role            = [string]$a.role
			InheritEligible = $false
		}
	}
	return $map
}

function Register-FabricResumeRestoredState {
	<#
	.SYNOPSIS
		Records the verified authority manifest and artifact ownership produced by a
		successful hydration, keyed by run timestamp.
	.DESCRIPTION
		Hydration and publication are separate concerns, and a restore that "succeeded"
		while publication state stayed reset to zero is exactly the hidden coupling that
		let a restarted process reuse generation 1. This record makes the reconstructed
		state observable per run and never mixes ownership between runs. It is a RECORD,
		not the allocation authority: Sync-FabricResumeMirror independently re-derives the
		remote high-water mark before it stages anything.

		When the caller supplies VerifiedOwnership - the map produced by a hydration that
		re-derived every artifact digest from the bytes it downloaded - that map is
		recorded instead of the manifest-only reconstruction, because only a re-derived
		digest is content identity.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $RunTimestamp,
		[Parameter(Mandatory)] [object] $Manifest,
		[Parameter(Mandatory)] [AllowNull()] [AllowEmptyCollection()] [string[]] $RelativePaths,
		[hashtable] $VerifiedOwnership
	)
	if (-not $script:FabricResumeRestoredState) { $script:FabricResumeRestoredState = @{} }
	$high = Get-FabricResumeRemoteHighWater -RelativePaths $RelativePaths
	if ([int]$Manifest.generation -gt $high) { $high = [int]$Manifest.generation }
	$ownership = if ($VerifiedOwnership -and $VerifiedOwnership.Count -gt 0) { $VerifiedOwnership } else { ConvertTo-FabricResumeOwnership -Manifest $Manifest }
	$script:FabricResumeRestoredState[[string]$RunTimestamp] = @{
		Generation   = [int]$Manifest.generation
		GenerationId = [string]$Manifest.generationId
		HighWater    = [int]$high
		Artifacts    = $ownership
		Manifest     = $Manifest
	}
}

function Initialize-FabricResumeCommitStateFromRemote {
	<#
	.SYNOPSIS
		Reconstructs remote generation state for a run from the REMOTE mirror before any
		artifact is staged. Runs once per process per run.
	.DESCRIPTION
		$script:FabricResumeCommitState is an in-process CACHE, never the source of truth
		for remote generation allocation: it does not survive a container restart, so a
		restarted process previously computed generation 1 again and overwrote the
		existing gen-1 objects and authority record. This function makes the remote store
		the authority - it reads the run's listing, takes the high-water sequence across
		committed generations, ORPHANED staging generations and every authority record,
		and reconstructs the current authoritative generation plus artifact ownership from
		the newest VERIFIED manifest. The next allocation is then strictly above every
		remotely observed sequence.

		Fails closed: a listing failure other than 404 throws, because a publication that
		cannot observe the remote high-water mark must not guess at a name.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)] [string] $RunTimestamp)
	if (-not $script:FabricResumeCommitState) {
		$script:FabricResumeCommitState = @{ Generation = 0; Counter = 0; Artifacts = @{} }
	}
	if ($script:FabricResumeCommitState['RemoteReconciled'] -eq $true -and
		([string]$script:FabricResumeCommitState['RunTimestamp']) -ceq [string]$RunTimestamp) {
		return
	}

	$listing = @(Get-FabricResumeRunListing -RunTimestamp $RunTimestamp)
	$high = Get-FabricResumeRemoteHighWater -RelativePaths $listing
	$commitLeaves = New-Object System.Collections.Generic.List[string]
	foreach ($rel in @($listing)) {
		$r = [string]$rel
		if ($r.StartsWith('commits/')) {
			$leaf = $r.Substring(8)
			if ($leaf -and -not $leaf.Contains('/')) { [void]$commitLeaves.Add($leaf) }
		}
	}

	$generation = 0
	$artifacts = @{}
	if ($commitLeaves.Count -gt 0) {
		$manifest = Get-FabricResumeAuthoritativeCommit -RunTimestamp $RunTimestamp -CommitLeafNames $commitLeaves.ToArray()
		if ($manifest) {
			$generation = [int]$manifest.generation
			$artifacts = ConvertTo-FabricResumeOwnership -Manifest $manifest
			# If THIS process hydrated exactly this generation and re-derived every
			# artifact digest from the downloaded bytes, that verified ownership replaces
			# the manifest-only reconstruction: it is the one map whose digests are content
			# identity rather than the writer's claim. Anything else stays
			# non-inherit-eligible and is re-staged into the fresh generation.
			$restored = $null
			if ($script:FabricResumeRestoredState) { $restored = $script:FabricResumeRestoredState[[string]$RunTimestamp] }
			if ($restored -and ([string]$restored.GenerationId) -ceq ([string]$manifest.generationId) -and $restored.Artifacts) {
				$artifacts = $restored.Artifacts
			}
			if ($generation -gt $high) { $high = $generation }
		}
	}

	$counter = [int]$script:FabricResumeCommitState['Counter']
	if ($high -gt $counter) { $counter = $high }
	$script:FabricResumeCommitState = @{
		Generation       = $generation
		Counter          = $counter
		Artifacts        = $artifacts
		RemoteReconciled = $true
		RunTimestamp     = [string]$RunTimestamp
	}
}

function Get-FabricResumeAuthoritativeCommit {
	<#
	.SYNOPSIS
		Resolves the authoritative (most recent VERIFIED) resume commit manifest for a
		run from the list of commit object leaf names discovered under
		.pax_resume/<RunTimestamp>/commits/.
	.DESCRIPTION
		Commit objects are IMMUTABLE and monotonically numbered (commit-<n>.json); a
		commit is never overwritten, so a torn write can only ever affect the NEWEST
		object and can never destroy an already-established authority. Candidates are
		evaluated newest-first and the first one that downloads, parses, matches its own
		generation/run identity, and passes the integrity digest wins. A torn, missing,
		or ambiguous newest commit is SKIPPED and the search falls back to the most
		recent verified older generation. Returns $null when nothing verifies - the
		caller must then hydrate nothing rather than guess.

		Staging generations (gen-<n>/ folders with no committed manifest) are structurally
		unreachable here: selection follows manifests only, never a directory listing.

		AMBIGUITY IS FATAL TO SELECTION. Candidates are grouped by sequence and evaluated
		highest sequence first. If TWO OR MORE candidates at the SAME sequence both verify
		but name different generation identities (or carry different integrity digests),
		nothing is returned - the reader never resolves a conflict by listing order, and it
		never falls back to a LOWER sequence to escape the conflict. A lower sequence is
		reached only when every higher candidate is torn or unverifiable.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $RunTimestamp,
		[Parameter(Mandatory)] [AllowEmptyCollection()] [string[]] $CommitLeafNames
	)
	$candidates = New-Object System.Collections.Generic.List[object]
	foreach ($n in @($CommitLeafNames)) {
		$leaf = [string]$n
		$seq = Get-FabricResumeNameSequence -Name $leaf
		if ($seq -ge 1) {
			[void]$candidates.Add([pscustomobject]@{ Generation = $seq; Leaf = $leaf })
		}
	}
	foreach ($grp in @($candidates | Group-Object -Property Generation | Sort-Object -Property { [int]$_.Name } -Descending)) {
		$seq = [int]$grp.Name
		$verified = New-Object System.Collections.Generic.List[object]
		foreach ($c in @($grp.Group | Sort-Object -Property Leaf)) {
			$tmp = Join-Path ([System.IO.Path]::GetTempPath()) ("pax_resume_commit_read_{0}.json" -f [guid]::NewGuid().ToString('N'))
			$parsed = $null
			try {
				Get-RemoteFile-OneLake -RelativeName ".pax_resume/$RunTimestamp/commits/$($c.Leaf)" -DestinationPath $tmp
				$parsed = (Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop) | ConvertFrom-Json -ErrorAction Stop
			}
			catch { $parsed = $null }
			finally { if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } }
			if (-not (Test-FabricResumeCommitManifest -Manifest $parsed)) {
				Write-Verbose ("Resume commit {0} for run {1} is torn or unverifiable; it cannot be selected." -f $c.Leaf, $RunTimestamp)
				continue
			}
			if ([int]$parsed.generation -ne $seq) { continue }
			if ([string]$parsed.runTimestamp -cne [string]$RunTimestamp) { continue }
			[void]$verified.Add($parsed)
		}
		if ($verified.Count -eq 0) { continue }
		if ($verified.Count -gt 1) {
			$ids = @(@($verified | ForEach-Object { [string]$_.generationId }) | Sort-Object -Unique)
			$digests = @(@($verified | ForEach-Object { [string]$_.integritySha256 }) | Sort-Object -Unique)
			if ($ids.Count -gt 1 -or $digests.Count -gt 1) {
				Write-Verbose ("Resume commit sequence {0} for run {1} is AMBIGUOUS - {2} verified authority records with differing identities or contents; hydrating nothing (fail closed)." -f $seq, $RunTimestamp, $verified.Count)
				return $null
			}
		}
		return $verified[0]
	}
	return $null
}

function Copy-FabricResumeCommitArtifacts {
	<#
	.SYNOPSIS
		Downloads, VERIFIES, and then atomically publishes exactly the artifact set named
		by a VERIFIED resume commit manifest.
	.DESCRIPTION
		Each artifact carries the generation that owns it, so an artifact that was
		unchanged (and therefore not re-uploaded) in the committed generation is
		resolved from the earlier generation that does own it. Prior committed
		generations are retained for the life of the run precisely so these inherited
		references always resolve. Returns the number of files published.

		TWO-PHASE, ALL-OR-NOTHING. A manifest self-digest proves the manifest is the
		complete object the writer intended; it proves NOTHING about the bytes the
		manifest refers to, and a download that is hash-checked AFTER being written into
		the live resume directory has already made a partial set discoverable. So:

		  PHASE 1 (isolated) - every artifact is downloaded into a transaction-scoped
		  temporary hydration directory that auto-discovery cannot see. Each one must
		  exist, match its manifest LENGTH exactly, and match a SHA256 RE-DERIVED from the
		  bytes just downloaded (ordinal comparison; a same-length substitution therefore
		  fails). The checkpoint artifact must additionally parse as JSON. The staged set
		  must equal the manifest set exactly - no missing, extra, or duplicated entry.
		  The live LocalDir is not created, read, or written during this phase.

		  PHASE 2 (promote) - only once the ENTIRE set has verified is the live directory
		  touched, and then as ONE exact-set replacement of the run's OWNED artifacts:
		  every owned path is SNAPSHOT to a transaction-scoped backup, the prior checkpoint
		  is WITHDRAWN FIRST (from that moment until the last step no checkpoint of this run
		  is discoverable, so a torn intermediate set can never be resumed), every owned
		  file the authority record does not name is withdrawn, the verified artifacts are
		  moved in, and the CHECKPOINT IS PUBLISHED LAST. Find-Checkpoints discovers a run
		  by its checkpoint file, so a candidate checkpoint becomes visible only once every
		  companion artifact is already in place.

		OWNED RESUME-ARTIFACT BOUNDARY. LocalDir is normally the customer's -OutputPath, so
		a whole-directory replacement is NOT an option. Exactly three narrow, name-anchored
		sets are owned, and nothing else in LocalDir is enumerated, moved or deleted:
		  1. <LocalDir>/.pax_checkpoint_<RunTimestamp>.json - this run's canonical
		     checkpoint, the name this run publishes and Find-Checkpoints discovers.
		  2. every file under <LocalDir>/.pax_incremental/ - the resume protocol's own
		     private shard directory; nothing outside the protocol writes there.
		  3. every *_PARTIAL* file directly in <LocalDir> whose name carries this run's
		     timestamp - this run's partial companion. That timestamp scoping is what keeps
		     another run's partial companion OUT of the boundary.
		Plus every localPath the authority record names, which is owned by definition. A
		customer report, workbook, log, sub-folder, or another run's checkpoint is OUTSIDE
		the boundary and is therefore untouchable. PreserveLocalPaths additionally exempts
		paths an earlier run in the same multi-run sweep already published, so hydrating
		run B never withdraws run A's verified shards from the shared shard directory.

		Any failure throws. On a phase-1 failure LocalDir is byte-for-byte untouched and
		stays ABSENT if it did not already exist. On a phase-2 failure every candidate byte
		this call placed is withdrawn and the snapshot is restored, so the prior verified
		set - checkpoint AND every companion - is put back byte-for-byte and stays
		discoverable; a previously verified artifact is NEVER deleted in the name of
		cleanup. When LocalDir did not exist beforehand it is removed again. The temporary
		hydration and snapshot directories are always removed.

		When the caller supplies VerifiedOwnership it is populated with the RE-DERIVED
		per-artifact digests, which is the only form of ownership that may later be
		inherited instead of re-staged.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $RunTimestamp,
		[Parameter(Mandatory)] [object] $Manifest,
		[Parameter(Mandatory)] [string] $LocalDir,
		[hashtable] $VerifiedOwnership,
		[string[]] $PreserveLocalPaths
	)
	$artifactList = @($Manifest.artifacts)
	$generationId = [string]$Manifest.generationId
	if ($artifactList.Count -lt 1) {
		throw "Resume generation '$generationId' for run $RunTimestamp names no artifacts; hydrating nothing."
	}

	$stageDir = Join-Path ([System.IO.Path]::GetTempPath()) ("pax_resume_hydrate_{0}" -f [guid]::NewGuid().ToString('N'))
	New-Item -Path $stageDir -ItemType Directory -Force | Out-Null
	try {
		# ---- PHASE 1: download and verify in ISOLATION. LocalDir is never touched. ----
		$staged = New-Object System.Collections.Generic.List[object]
		$verified = @{}
		$seenLocal = @{}
		foreach ($a in $artifactList) {
			$lp = [string]$a.localPath
			if (-not (Test-FabricResumeArtifactPath -Path $lp)) {
				throw "Resume generation '$generationId' for run $RunTimestamp names an unsafe artifact path; hydrating nothing."
			}
			if ($seenLocal.ContainsKey($lp)) {
				throw "Resume generation '$generationId' for run $RunTimestamp names artifact '$lp' more than once; hydrating nothing."
			}
			$seenLocal[$lp] = $true

			$dest = Join-Path $stageDir $lp
			$destDir = Split-Path -Parent $dest
			if ($destDir -and -not (Test-Path -LiteralPath $destDir -PathType Container)) {
				New-Item -Path $destDir -ItemType Directory -Force | Out-Null
			}
			Get-RemoteFile-OneLake -RelativeName ".pax_resume/$RunTimestamp/$([string]$a.remotePath)" -DestinationPath $dest
			if (-not (Test-Path -LiteralPath $dest -PathType Leaf)) {
				throw "Resume artifact '$lp' of generation '$generationId' for run $RunTimestamp did not download; hydrating nothing."
			}
			$actualLength = [int64](Get-Item -LiteralPath $dest).Length
			if ($actualLength -ne [int64]$a.length) {
				throw "Resume artifact '$lp' of generation '$generationId' for run $RunTimestamp has length $actualLength but the authority record declares $([int64]$a.length); hydrating nothing."
			}
			# Content identity is RE-DERIVED from the bytes that actually arrived - the one
			# check a same-length substitution cannot survive.
			$actualSha = Get-FabricResumeArtifactSha256 -Path $dest
			if ($actualSha -cne ([string]$a.sha256)) {
				throw "Resume artifact '$lp' of generation '$generationId' for run $RunTimestamp failed content verification; hydrating nothing."
			}
			if (([string]$a.role) -ceq 'checkpoint') {
				try { $null = (Get-Content -LiteralPath $dest -Raw -ErrorAction Stop) | ConvertFrom-Json -ErrorAction Stop }
				catch { throw "Resume checkpoint '$lp' of generation '$generationId' for run $RunTimestamp is not parseable JSON; hydrating nothing." }
			}
			[void]$staged.Add([pscustomobject]@{ LocalPath = $lp; StagePath = $dest; Role = [string]$a.role })
			$verified[$lp] = @{
				RemotePath      = [string]$a.remotePath
				Generation      = [int]$a.generation
				Length          = $actualLength
				Sha256          = $actualSha
				Role            = [string]$a.role
				InheritEligible = $true
			}
		}
		# The staged set must be exactly the manifest set - an extra file would mean the
		# generation is not the one the authority record describes.
		$stagedOnDisk = @(Get-ChildItem -LiteralPath $stageDir -Recurse -File -Force -ErrorAction SilentlyContinue)
		if ($stagedOnDisk.Count -ne $artifactList.Count) {
			throw "Resume generation '$generationId' for run $RunTimestamp staged $($stagedOnDisk.Count) files for $($artifactList.Count) declared artifacts; hydrating nothing."
		}

		# ---- PHASE 2: promote as ONE exact-set replacement of the OWNED boundary. ----
		$localDirExisted = (Test-Path -LiteralPath $LocalDir -PathType Container)
		$manifestPaths = @($staged | ForEach-Object { [string]$_.LocalPath })
		$checkpointPaths = @(@($staged | Where-Object { $_.Role -ceq 'checkpoint' } | ForEach-Object { [string]$_.LocalPath }) + ".pax_checkpoint_$RunTimestamp.json")
		$preserved = @{}
		foreach ($p in @($PreserveLocalPaths)) { if ($p) { $preserved[[string]$p] = $true } }

		# Enumerate the OWNED RESUME-ARTIFACT BOUNDARY (see .DESCRIPTION). Nothing outside
		# it is listed here, so nothing outside it can be withdrawn - a customer report or
		# sub-folder sitting in the same -OutputPath is structurally unreachable.
		$owned = New-Object System.Collections.Generic.List[string]
		$ownedSeen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
		foreach ($rel in @($manifestPaths + $checkpointPaths)) {
			if ($rel -and $ownedSeen.Add([string]$rel)) { [void]$owned.Add([string]$rel) }
		}
		if ($localDirExisted) {
			$incLive = Join-Path $LocalDir '.pax_incremental'
			if (Test-Path -LiteralPath $incLive -PathType Container) {
				foreach ($f in @(Get-ChildItem -LiteralPath $incLive -Recurse -File -Force -ErrorAction SilentlyContinue)) {
					$relInc = '.pax_incremental/' + $f.FullName.Substring($incLive.Length + 1).Replace('\', '/')
					if ($ownedSeen.Add($relInc)) { [void]$owned.Add($relInc) }
				}
			}
			foreach ($f in @(Get-ChildItem -LiteralPath $LocalDir -File -Force -ErrorAction SilentlyContinue)) {
				$leaf = [string]$f.Name
				if ($leaf -like '*_PARTIAL*' -and $leaf -like "*$RunTimestamp*" -and $ownedSeen.Add($leaf)) { [void]$owned.Add($leaf) }
			}
		}

		$backupDir = Join-Path ([System.IO.Path]::GetTempPath()) ("pax_resume_prior_{0}" -f [guid]::NewGuid().ToString('N'))
		$backedUp = New-Object System.Collections.Generic.List[string]
		$published = New-Object System.Collections.Generic.List[string]
		$createdDirs = New-Object System.Collections.Generic.List[string]
		try {
			# 2a) SNAPSHOT the prior owned set. This - not a delete-on-failure sweep - is
			#     what makes a failed promotion recoverable: deleting a target that already
			#     held a previously VERIFIED artifact destroys it instead of restoring it.
			New-Item -Path $backupDir -ItemType Directory -Force | Out-Null
			foreach ($rel in $owned) {
				$live = Join-Path $LocalDir $rel
				if (-not (Test-Path -LiteralPath $live -PathType Leaf)) { continue }
				$bak = Join-Path $backupDir $rel
				$bakDir = Split-Path -Parent $bak
				if ($bakDir -and -not (Test-Path -LiteralPath $bakDir -PathType Container)) {
					New-Item -Path $bakDir -ItemType Directory -Force | Out-Null
				}
				[System.IO.File]::Copy($live, $bak, $true)
				[void]$backedUp.Add($rel)
			}

			if (-not $localDirExisted) {
				New-Item -Path $LocalDir -ItemType Directory -Force | Out-Null
				[void]$createdDirs.Add($LocalDir)
			}

			# 2b) WITHDRAW the prior checkpoint FIRST. From here until 2d no checkpoint of
			#     this run is discoverable, so an interruption exposes no candidate set at
			#     all rather than a checkpoint whose companions are mid-replacement.
			foreach ($rel in $owned) {
				if ($preserved.ContainsKey($rel)) { continue }
				if ($checkpointPaths -notcontains $rel) { continue }
				$live = Join-Path $LocalDir $rel
				if (Test-Path -LiteralPath $live -PathType Leaf) { [System.IO.File]::Delete($live) }
			}

			# 2c) EXACT SET: withdraw every owned file the authority record does not name,
			#     so no stale shard, stale partial, or prior-generation artifact survives
			#     into the promoted set and downstream enumeration sees exactly one set.
			foreach ($rel in $owned) {
				if ($preserved.ContainsKey($rel)) { continue }
				if ($manifestPaths -contains $rel) { continue }
				$live = Join-Path $LocalDir $rel
				if (Test-Path -LiteralPath $live -PathType Leaf) { [System.IO.File]::Delete($live) }
			}

			# 2d) Publish the verified set, CHECKPOINT LAST.
			$ordered = @(@($staged | Where-Object { $_.Role -cne 'checkpoint' }) + @($staged | Where-Object { $_.Role -ceq 'checkpoint' }))
			foreach ($s in $ordered) {
				$target = Join-Path $LocalDir ([string]$s.LocalPath)
				$targetDir = Split-Path -Parent $target
				if ($targetDir -and -not (Test-Path -LiteralPath $targetDir -PathType Container)) {
					New-Item -Path $targetDir -ItemType Directory -Force | Out-Null
					[void]$createdDirs.Add($targetDir)
				}
				Move-PaxFileOverwriteAtomic -SourcePath ([string]$s.StagePath) -DestinationPath $target
				[void]$published.Add($target)
			}
		}
		catch {
			# ROLLBACK: withdraw every candidate byte this call ACTUALLY PLACED, then
			# RESTORE the snapshot. Withdrawal names $published rather than the INTENDED
			# set $manifestPaths, because withdrawal and restore must cover the SAME
			# files: restore can only put back what the snapshot loop captured, so a
			# manifest-wide withdrawal is broader than the restore and permanently loses
			# a prior verified file that the snapshot loop had not reached when it threw.
			# At a snapshot-window failure $published is empty, so the prior live set is
			# left completely untouched. The prior verified set is put back - it is never
			# deleted in the name of cleanup, which is what made a failed publication
			# destructive before.
			foreach ($live in $published) {
				if (Test-Path -LiteralPath $live -PathType Leaf) { Remove-Item -LiteralPath $live -Force -ErrorAction SilentlyContinue }
			}
			foreach ($rel in $backedUp) {
				$live = Join-Path $LocalDir $rel
				$liveDir = Split-Path -Parent $live
				if ($liveDir -and -not (Test-Path -LiteralPath $liveDir -PathType Container)) {
					New-Item -Path $liveDir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
				}
				[System.IO.File]::Copy((Join-Path $backupDir $rel), $live, $true)
			}
			for ($i = $createdDirs.Count - 1; $i -ge 0; $i--) {
				$cd = $createdDirs[$i]
				if (-not (Test-Path -LiteralPath $cd -PathType Container)) { continue }
				if (-not $localDirExisted) { Remove-Item -LiteralPath $cd -Recurse -Force -ErrorAction SilentlyContinue; continue }
				if (@(Get-ChildItem -LiteralPath $cd -Force -ErrorAction SilentlyContinue).Count -eq 0) {
					Remove-Item -LiteralPath $cd -Force -ErrorAction SilentlyContinue
				}
			}
			throw
		}
		finally {
			if (Test-Path -LiteralPath $backupDir) { Remove-Item -LiteralPath $backupDir -Recurse -Force -ErrorAction SilentlyContinue }
		}

		if ($null -ne $VerifiedOwnership) {
			foreach ($k in @($verified.Keys)) { $VerifiedOwnership[$k] = $verified[$k] }
		}
		return $published.Count
	}
	finally {
		if (Test-Path -LiteralPath $stageDir) { Remove-Item -LiteralPath $stageDir -Recurse -Force -ErrorAction SilentlyContinue }
	}
}

function Sync-FabricResumeMirror {
	<#
	.SYNOPSIS
		Publishes the run's resume artifact set to OneLake as a TRANSACTIONAL,
		generation-scoped commit under Files/.pax_resume/<RunTimestamp>/.
	.DESCRIPTION
		A sequential multi-file upload is NOT a transaction. Overwriting a single
		remote checkpoint object in place meant a checkpoint upload that succeeded
		before a later shard/partial upload failed left the NEW checkpoint remotely
		authoritative while the local transaction rolled back - a container restart
		then rehydrated the repudiated remote state and erased the safety the local
		rollback achieved. This function replaces that with an explicit commit protocol:

		  1. STAGE - every artifact that is new or changed is uploaded into a fresh,
		     transaction-scoped generation folder gen-<n>-<nonce>/. Nothing already committed
		     is overwritten, so a failure here cannot damage the prior generation.
		  2. INHERIT - an unchanged artifact is NOT re-uploaded; the manifest records the
		     earlier generation that OWNS it. Prior committed generations are retained for
		     the life of the run (cleanup happens only in Remove-FabricResumeMirror after a
		     clean finish), so every inherited reference resolves at hydration time.
		     Inheritance requires ownership this PROCESS published; ownership reconstructed
		     from a remote manifest after a restart is not inherit-eligible, because a local
		     size/mtime stamp is not content identity.
		  3. COMMIT - after the ENTIRE required set is staged successfully, ONE immutable
		     manifest object commits/commit-<n>-<nonce>.json is written. That single write is
		     the ONLY authoritative-generation transition; there is no in-place pointer to
		     overwrite and therefore no way to expose a partially committed checkpoint.

		Failure semantics:
		  * any staging upload fails  -> throws BEFORE the commit; generation <n> is an
		    orphaned staging folder that hydration structurally cannot select, and the
		    prior committed generation remains authoritative.
		  * the commit write fails    -> throws; the prior committed generation remains
		    authoritative (a torn commit-<n>.json fails its integrity digest on read).
		  * on either failure the per-file change stamps are NOT advanced, so the next
		    transaction re-uploads everything the failed one staged.

		CONSISTENCY ASSUMPTIONS (stated plainly). OneLake/ADLS Gen2 offers no atomic
		directory promotion through the API surface this script uses, so the commit point
		is a single small object write. This protocol does NOT assume that write is atomic:
		commit objects are immutable and monotonically numbered, and each carries an
		integrity digest over its own identity-bearing fields, so a torn or truncated
		commit object is DETECTED on read and the reader fails closed to the most recent
		VERIFIED older generation. It does assume that a flushed object is subsequently
		readable - a property this script already relies on for every customer-facing upload.

		IMMUTABILITY MECHANISM (what this actually relies on). Object names are NOT assumed
		to be unique by convention, and the in-memory counter is NOT trusted to survive a
		restart. Two independent mechanisms enforce immutability:
		  * NAME UNIQUENESS - the sequence is allocated strictly above the remote high-water
		    mark (Initialize-FabricResumeCommitStateFromRemote) AND every generation folder
		    and authority record carries a collision-resistant nonce, so identity never rests
		    on a sequence that a stale listing could cause two writers to compute.
		  * CREATE-IF-ABSENT - every resume-protocol upload uses
		    Send-FileToOneLake -FailIfExists, which issues the DFS Create File request with an
		    If-None-Match: * precondition. An existing target answers 409/412 and is raised as
		    a HARD COLLISION, never silently overwritten and never treated as success. A retry
		    then allocates a completely fresh identity rather than replacing the conflicted
		    object. If the storage surface ever stopped honouring the precondition, the nonce
		    alone still makes a name collision vanishingly unlikely, and any collision that
		    did occur would still fail closed.
		Customer-facing output uploads are untouched by this: they keep the default
		overwrite semantics because a customer output file is intentionally replaceable.

		ORDERING. Save-CheckpointStrict verifies the LOCAL publication (atomic replace +
		re-read + parse) BEFORE calling this function, so a remote generation is never
		promoted ahead of the local state it describes.

		No-op unless the Purview destination tier is Fabric. Local and SharePoint tiers
		keep resume artifacts local-only.

		Per-file change tracking lives in $script:FabricResumeMirrorState keyed by full
		local path with "{size}:{ticks}" stamps (advanced only on a committed
		transaction); remote ownership lives in $script:FabricResumeCommitState.
	#>
	[CmdletBinding()]
	param()
	if (-not $script:DestTier -or $script:DestTier['Purview'] -ne 'Fabric') { return }
	if (-not $script:CheckpointPath -or -not (Test-Path -LiteralPath $script:CheckpointPath)) { return }
	if (-not $global:ScriptRunTimestamp) { return }

	if (-not $script:FabricResumeMirrorState) { $script:FabricResumeMirrorState = @{} }
	# The in-memory commit state is a CACHE and does not survive a container restart, so
	# remote generation identity is reconstructed from the REMOTE store before anything is
	# staged. Without this a restarted process recomputed generation 1 and overwrote the
	# existing gen-1 artifacts and authority record.
	Initialize-FabricResumeCommitStateFromRemote -RunTimestamp $global:ScriptRunTimestamp

	$mirrorBase = ".pax_resume/$global:ScriptRunTimestamp"
	# Every ATTEMPT claims a sequence strictly ABOVE every remotely observed sequence -
	# committed generations, orphaned staging generations and authority records alike -
	# AND a collision-resistant nonce. The sequence orders generations; the nonce is what
	# makes the remote NAME unique, so neither a retry after a failed transaction, nor a
	# process restart, nor a stale/eventually-consistent listing can re-stage into (or
	# overwrite) an existing generation folder or authority record.
	$generation = [int]$script:FabricResumeCommitState.Counter + 1
	$script:FabricResumeCommitState.Counter = $generation
	$generationNonce = New-FabricResumeGenerationNonce
	$generationId = "gen-$generation-$generationNonce"
	$commitLeaf = "commit-$generation-$generationNonce.json"

	# Required artifact set for THIS transaction: the checkpoint JSON (always changed),
	# every .pax_incremental/*.jsonl shard, and the *_PARTIAL.csv companion when present.
	$required = New-Object System.Collections.Generic.List[object]
	$cpItem = Get-Item -LiteralPath $script:CheckpointPath
	[void]$required.Add([pscustomobject]@{
		LocalFullPath = $cpItem.FullName
		LocalPath     = $cpItem.Name
		Length        = [int64]$cpItem.Length
		Stamp         = ("{0}:{1}" -f $cpItem.Length, $cpItem.LastWriteTimeUtc.Ticks)
		Sha256        = (Get-FabricResumeArtifactSha256 -Path $cpItem.FullName)
		Role          = 'checkpoint'
		AlwaysUpload  = $true
	})

	$cpDir = Split-Path -Parent $script:CheckpointPath
	$incDir = Join-Path $cpDir ".pax_incremental"
	if (Test-Path -LiteralPath $incDir -PathType Container) {
		foreach ($f in (Get-ChildItem -LiteralPath $incDir -Filter '*.jsonl' -File -ErrorAction SilentlyContinue)) {
			[void]$required.Add([pscustomobject]@{
				LocalFullPath = $f.FullName
				LocalPath     = ".pax_incremental/$($f.Name)"
				Length        = [int64]$f.Length
				Stamp         = ("{0}:{1}" -f $f.Length, $f.LastWriteTimeUtc.Ticks)
				Sha256        = (Get-FabricResumeArtifactSha256 -Path $f.FullName)
				Role          = 'artifact'
				AlwaysUpload  = $false
			})
		}
	}

	if ($script:PartialOutputPath -and (Test-Path -LiteralPath $script:PartialOutputPath)) {
		$pf = Get-Item -LiteralPath $script:PartialOutputPath
		[void]$required.Add([pscustomobject]@{
			LocalFullPath = $pf.FullName
			LocalPath     = $pf.Name
			Length        = [int64]$pf.Length
			Stamp         = ("{0}:{1}" -f $pf.Length, $pf.LastWriteTimeUtc.Ticks)
			Sha256        = (Get-FabricResumeArtifactSha256 -Path $pf.FullName)
			Role          = 'artifact'
			AlwaysUpload  = $false
		})
	}

	# 1/2) STAGE + INHERIT. Any throw here aborts BEFORE the commit point.
	$artifacts = New-Object System.Collections.Generic.List[object]
	foreach ($item in $required) {
		$prior = $script:FabricResumeCommitState.Artifacts[[string]$item.LocalPath]
		# Inheritance is decided on CONTENT IDENTITY, never on a size/mtime stamp: the
		# recorded digest must be one this process either published itself or re-derived
		# from bytes it downloaded and verified, and it must equal the digest of the local
		# file as it stands right now. Anything else is staged into the fresh generation.
		$inheritEligible = ($prior -and ($prior['InheritEligible'] -eq $true) -and
			([string]$prior['Sha256']) -and (([string]$prior['Sha256']) -ceq ([string]$item.Sha256)))
		if ((-not $item.AlwaysUpload) -and $inheritEligible) {
			[void]$artifacts.Add([pscustomobject]@{
				localPath  = [string]$item.LocalPath
				remotePath = [string]$prior.RemotePath
				generation = [int]$prior.Generation
				length     = [int64]$prior.Length
				role       = [string]$item.Role
				sha256     = [string]$prior.Sha256
			})
			continue
		}
		$remotePath = "$generationId/$([string]$item.LocalPath)"
		Send-FileToOneLake -LocalPath $item.LocalFullPath -RemoteFileName "$mirrorBase/$remotePath" -FailIfExists
		[void]$artifacts.Add([pscustomobject]@{
			localPath  = [string]$item.LocalPath
			remotePath = $remotePath
			generation = $generation
			length     = [int64]$item.Length
			role       = [string]$item.Role
			sha256     = [string]$item.Sha256
		})
	}

	# 3) COMMIT. One immutable manifest object; its successful write - and nothing
	#    before it - promotes generation <n> to authoritative.
	$manifest = [pscustomobject]@{
		contractVersion = $script:FabricResumeMirrorContractVersion
		runTimestamp    = [string]$global:ScriptRunTimestamp
		generation      = $generation
		generationId    = $generationId
		createdUtc      = (Get-Date).ToUniversalTime().ToString('o')
		artifacts       = $artifacts.ToArray()
		integritySha256 = ''
	}
	$manifest.integritySha256 = New-FabricResumeCommitIntegrity -Manifest $manifest
	$commitLocal = Join-Path ([System.IO.Path]::GetTempPath()) ("pax_resume_commit_{0}.json" -f [guid]::NewGuid().ToString('N'))
	try {
		($manifest | ConvertTo-Json -Depth 6) | Set-Content -LiteralPath $commitLocal -Encoding UTF8 -Force -ErrorAction Stop
		Send-FileToOneLake -LocalPath $commitLocal -RemoteFileName "$mirrorBase/commits/$commitLeaf" -FailIfExists
	}
	finally {
		if (Test-Path -LiteralPath $commitLocal) { Remove-Item -LiteralPath $commitLocal -Force -ErrorAction SilentlyContinue }
	}

	# Promotion proven. ONLY now is the new generation recorded as authoritative and the
	# per-file change stamps advanced.
	$ownership = @{}
	foreach ($a in $artifacts) { $ownership[[string]$a.localPath] = $a }
	foreach ($item in $required) {
		$a = $ownership[[string]$item.LocalPath]
		$script:FabricResumeCommitState.Artifacts[[string]$item.LocalPath] = @{
			RemotePath      = [string]$a.remotePath
			Generation      = [int]$a.generation
			Length          = [int64]$a.length
			Sha256          = [string]$a.sha256
			Role            = [string]$a.role
			InheritEligible = $true
		}
		$script:FabricResumeMirrorState[[string]$item.LocalFullPath] = [string]$item.Stamp
	}
	$script:FabricResumeCommitState.Generation = $generation
	$script:FabricResumeCommitState.GenerationId = $generationId
}

function Restore-FabricResumeMirror {
	<#
	.SYNOPSIS
		Hydrates local resume artifacts from the authoritative COMMITTED generation of
		OneLake Files/.pax_resume/<RunTimestamp>/.
	.DESCRIPTION
		Used on startup of a Fabric run when a resume is requested and the local
		working copy is missing or partial (typical after a container restart).
		Lists the mirror folder via the ADLS Gen2 List Paths API, resolves the most
		recent VERIFIED commit manifest, and downloads exactly the artifact set that
		manifest names, resolving each artifact from the generation that owns it.

		Hydration NEVER enumerates gen-<n>/ folders directly, so a staging generation
		left behind by a failed transaction is structurally unreachable. A torn or
		unverifiable newest commit falls back to the most recent verified older
		generation; when nothing verifies, 0 is returned and nothing is hydrated
		(fail closed) rather than guessing.

		A run mirror that carries NO commits/ folder at all predates the transactional
		protocol; it is hydrated from its flat legacy layout, still excluding any
		gen-<n>/ or commits/ path.

		Throws on partial-download failure so callers can abort rather than
		resume from a torn artifact set.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $RunTimestamp,
		[Parameter(Mandatory)] [string] $LocalDir
	)
	if (-not $script:DestTier -or $script:DestTier['Purview'] -ne 'Fabric') { return 0 }
	if (-not $script:FabricResolved) { $script:FabricResolved = Resolve-FabricTarget -Url $script:RemoteOutputUrl }
	$resolved = $script:FabricResolved

	$relInItem = if ($resolved.FilesPath) { "$($resolved.FilesPath)/.pax_resume/$RunTimestamp" } else { ".pax_resume/$RunTimestamp" }
	$dirParam  = [System.Uri]::EscapeDataString("Files/$relInItem")
	$listUri   = "$($resolved.FilesystemBase)?resource=filesystem&recursive=true&directory=$($resolved.ItemFull)/$dirParam"

	$resp = $null
	try {
		$resp = Invoke-FabricWebRequest -Uri $listUri -Method GET
	} catch {
		$status = try { $_.Exception.Response.StatusCode.value__ } catch { 0 }
		if ($status -eq 404) { return 0 }
		throw
	}
	if (-not $resp -or -not $resp.Content) { return 0 }
	$parsed = try { $resp.Content | ConvertFrom-Json -ErrorAction Stop } catch { $null }
	if (-not $parsed -or -not $parsed.paths) { return 0 }

	# Classify the listing into commit objects vs legacy (pre-transactional) artifacts.
	# gen-<n>/ entries are deliberately ignored: only a verified manifest may name them.
	$prefix = "$($resolved.ItemFull)/Files/$relInItem/"
	$commitLeaves = New-Object System.Collections.Generic.List[string]
	$legacy = New-Object System.Collections.Generic.List[string]
	# Every observed relative path, DIRECTORIES INCLUDED, is retained so the restored-state
	# record carries the true remote high-water mark - an orphaned staging generation
	# reserves its sequence even though it can never be selected as authoritative.
	$allRel = New-Object System.Collections.Generic.List[string]
	# Any gen-<n>/ folder or commits/ object proves this run uses the transactional
	# protocol. The flat legacy layout is then NEVER a fallback: doing so on a merely
	# absent or not-yet-visible authority record would resume from unstaged state.
	$transactional = $false
	foreach ($entry in $parsed.paths) {
		$isDir = $entry.isDirectory
		$name = "$($entry.name)"
		$rest = if ($name.StartsWith($prefix)) { $name.Substring($prefix.Length) } else { Split-Path -Leaf $name }
		if ($rest) { [void]$allRel.Add($rest) }
		if ($rest -and ($rest.StartsWith('gen-') -or $rest.StartsWith('commits/') -or $rest -eq 'commits')) { $transactional = $true }
		if ($isDir -eq 'true' -or $isDir -eq $true) { continue }
		if (-not $rest) { continue }
		if ($rest.StartsWith('commits/')) { [void]$commitLeaves.Add($rest.Substring(8)); continue }
		if ($rest.StartsWith('gen-')) { continue }
		[void]$legacy.Add($rest)
	}

	if ($commitLeaves.Count -gt 0) {
		$manifest = Get-FabricResumeAuthoritativeCommit -RunTimestamp $RunTimestamp -CommitLeafNames $commitLeaves
		if (-not $manifest) {
			Write-Verbose ("No verified resume commit for run {0}; hydrating nothing (fail closed)." -f $RunTimestamp)
			return 0
		}
		$verifiedOwnership = @{}
		$downloaded = Copy-FabricResumeCommitArtifacts -RunTimestamp $RunTimestamp -Manifest $manifest -LocalDir $LocalDir -VerifiedOwnership $verifiedOwnership
		# Record the verified authority and its artifact ownership for THIS run only, so a
		# successful hydration never leaves publication state silently reset to zero. The
		# ownership carries RE-DERIVED digests, so it is the one form that may be inherited.
		Register-FabricResumeRestoredState -RunTimestamp $RunTimestamp -Manifest $manifest -RelativePaths $allRel -VerifiedOwnership $verifiedOwnership
		return $downloaded
	}

	if ($transactional) {
		# Generation folders exist but no authority record does: a first transaction that
		# has not committed, or a listing that has not caught up. Either way there is no
		# authoritative state to hydrate, and the flat layout is not a substitute.
		Write-Verbose ("Run {0} uses the transactional resume protocol but exposes no authority record; hydrating nothing (fail closed)." -f $RunTimestamp)
		return 0
	}

	if (-not (Test-Path -LiteralPath $LocalDir -PathType Container)) {
		New-Item -Path $LocalDir -ItemType Directory -Force | Out-Null
	}

	$downloaded = 0
	foreach ($rest in $legacy) {
		$dest = Join-Path $LocalDir $rest
		$destDir = Split-Path -Parent $dest
		if ($destDir -and -not (Test-Path -LiteralPath $destDir -PathType Container)) {
			New-Item -Path $destDir -ItemType Directory -Force | Out-Null
		}
		Get-RemoteFile-OneLake -RelativeName ".pax_resume/$RunTimestamp/$rest" -DestinationPath $dest
		$downloaded++
	}
	return $downloaded
}

function Remove-FabricResumeMirror {
	<#
	.SYNOPSIS
		Deletes the OneLake Files/.pax_resume/<RunTimestamp>/ mirror after a successful run.
	.DESCRIPTION
		Best-effort cleanup. Failures are logged at Verbose only — they do not
		abort the run because the customer-visible outputs are already durable
		and a leftover mirror folder is purely cosmetic.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)] [string] $RunTimestamp)
	if (-not $script:DestTier -or $script:DestTier['Purview'] -ne 'Fabric') { return }
	if (-not $script:FabricResolved) { return }
	$resolved = $script:FabricResolved
	$relInItem = if ($resolved.FilesPath) { "$($resolved.FilesPath)/.pax_resume/$RunTimestamp" } else { ".pax_resume/$RunTimestamp" }
	$dfsPath = "$($resolved.FilesystemBase)/$($resolved.ItemFull)/Files/$relInItem`?recursive=true"
	try {
		$null = Invoke-FabricWebRequest -Uri $dfsPath -Method DELETE
		if ($script:FabricResumeMirrorState) { $script:FabricResumeMirrorState.Clear() }
		# Every committed generation AND any orphaned staging generation lives under the
		# folder just deleted, so the recorded remote ownership is now meaningless. This is
		# the ONLY place resume generations are removed: staging orphans are deliberately
		# retained during the run so a failed transaction never destroys recovery evidence.
		$script:FabricResumeCommitState = @{ Generation = 0; Counter = 0; Artifacts = @{} }
		# The recorded hydration state describes objects that no longer exist.
		$script:FabricResumeRestoredState = @{}
	} catch {
		Write-Verbose ("Resume mirror cleanup failed: {0}" -f $_.Exception.Message)
	}
}

function Restore-AllFabricResumeMirrors {
	<#
	.SYNOPSIS
		Discovers all in-progress run mirrors under OneLake Files/.pax_resume/ and
		downloads their artifacts to a local directory for auto-discover resume.
	.DESCRIPTION
		Lists Files/.pax_resume/ recursively, then for each <RunTimestamp>/ folder resolves
		that run's most recent VERIFIED commit manifest and downloads exactly the artifact
		set it names (checkpoint JSON, *_PARTIAL.csv, .pax_incremental/*.jsonl) into
		LocalDir. Artifact local paths are already relative to the run folder, so the
		<RunTimestamp>/ prefix is naturally flattened - every artifact filename already
		embeds the run timestamp. Returns the number of files downloaded.

		A staging generation left behind by a failed transaction is never selected: only a
		verified commit manifest may name a generation. A run whose commits are all torn or
		unverifiable contributes NOTHING (fail closed). A run mirror with no commits/ folder
		at all predates the transactional protocol and is hydrated from its flat legacy
		layout, still excluding any gen-<n>/ or commits/ path. No-op on Local/SharePoint tiers.
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)] [string] $LocalDir)
	if (-not $script:DestTier -or $script:DestTier['Purview'] -ne 'Fabric') { return 0 }
	if (-not $script:FabricResolved) { $script:FabricResolved = Resolve-FabricTarget -Url $script:RemoteOutputUrl }
	$resolved = $script:FabricResolved

	$relInItem = if ($resolved.FilesPath) { "$($resolved.FilesPath)/.pax_resume" } else { ".pax_resume" }
	$dirParam  = [System.Uri]::EscapeDataString("Files/$relInItem")
	$listUri   = "$($resolved.FilesystemBase)?resource=filesystem&recursive=true&directory=$($resolved.ItemFull)/$dirParam"

	$resp = $null
	try {
		$resp = Invoke-FabricWebRequest -Uri $listUri -Method GET
	} catch {
		$status = try { $_.Exception.Response.StatusCode.value__ } catch { 0 }
		if ($status -eq 404) { return 0 }
		throw
	}
	if (-not $resp -or -not $resp.Content) { return 0 }
	$parsed = try { $resp.Content | ConvertFrom-Json -ErrorAction Stop } catch { $null }
	if (-not $parsed -or -not $parsed.paths) { return 0 }

	if (-not (Test-Path -LiteralPath $LocalDir -PathType Container)) {
		New-Item -Path $LocalDir -ItemType Directory -Force | Out-Null
	}

	# Group the flat listing by run timestamp, separating commit objects from legacy
	# (pre-transactional) artifacts. gen-<n>/ entries are deliberately ignored here:
	# only a verified commit manifest is allowed to name a generation.
	$prefix = "$($resolved.ItemFull)/Files/$relInItem/"
	$byRun = @{}
	foreach ($e in $parsed.paths) {
		$isDir = $e.isDirectory
		$n = "$($e.name)"
		if (-not $n.StartsWith($prefix)) { continue }
		$rest = $n.Substring($prefix.Length)
		if (-not $rest) { continue }
		# rest = "<RunTimestamp>/<...>".
		$slash = $rest.IndexOf('/')
		if ($slash -lt 0) { continue }
		$run = $rest.Substring(0, $slash)
		$sub = $rest.Substring($slash + 1)
		if (-not $sub) { continue }
		if (-not $byRun.ContainsKey($run)) {
			$byRun[$run] = [pscustomobject]@{
				Commits       = (New-Object System.Collections.Generic.List[string])
				Legacy        = (New-Object System.Collections.Generic.List[string])
				All           = (New-Object System.Collections.Generic.List[string])
				Transactional = $false
			}
		}
		# Retained PER RUN (directories included) so each run's high-water mark is derived
		# only from its own remote state - ownership is never mixed between runs.
		[void]$byRun[$run].All.Add($sub)
		if ($sub.StartsWith('gen-') -or $sub.StartsWith('commits/') -or $sub -eq 'commits') { $byRun[$run].Transactional = $true }
		if ($isDir -eq 'true' -or $isDir -eq $true) { continue }
		if ($sub.StartsWith('commits/')) { [void]$byRun[$run].Commits.Add($sub.Substring(8)); continue }
		if ($sub.StartsWith('gen-')) { continue }
		[void]$byRun[$run].Legacy.Add($sub)
	}

	$count = 0
	# Every path an earlier run in THIS sweep already published. Exact-set promotion is
	# scoped to ONE run's owned boundary and the .pax_incremental shard directory is
	# shared across runs, so run B is told explicitly which files run A already verified
	# and must therefore never withdraw.
	$sweepPublished = New-Object System.Collections.Generic.List[string]
	foreach ($run in @($byRun.Keys | Sort-Object)) {
		$bucket = $byRun[$run]
		if ($bucket.Commits.Count -gt 0) {
			$manifest = Get-FabricResumeAuthoritativeCommit -RunTimestamp $run -CommitLeafNames $bucket.Commits
			if (-not $manifest) {
				Write-Verbose ("No verified resume commit for run {0}; skipping it (fail closed)." -f $run)
				continue
			}
			# Hydration is all-or-nothing PER RUN: a run whose artifact set fails content
			# verification throws and contributes nothing, and the runs already restored
			# keep exactly the verified sets they were given.
			$verifiedOwnership = @{}
			$count += (Copy-FabricResumeCommitArtifacts -RunTimestamp $run -Manifest $manifest -LocalDir $LocalDir -VerifiedOwnership $verifiedOwnership -PreserveLocalPaths $sweepPublished.ToArray())
			foreach ($a in @($manifest.artifacts)) { [void]$sweepPublished.Add([string]$a.localPath) }
			Register-FabricResumeRestoredState -RunTimestamp $run -Manifest $manifest -RelativePaths $bucket.All -VerifiedOwnership $verifiedOwnership
			continue
		}
		if ($bucket.Transactional) {
			# Staging generations with no authority record: nothing is authoritative yet and
			# the flat legacy layout is never a fallback for a transactional run.
			Write-Verbose ("Run {0} uses the transactional resume protocol but exposes no authority record; skipping it (fail closed)." -f $run)
			continue
		}
		foreach ($localRel in $bucket.Legacy) {
			$dest = Join-Path $LocalDir $localRel
			$destDir = Split-Path -Parent $dest
			if ($destDir -and -not (Test-Path -LiteralPath $destDir -PathType Container)) {
				New-Item -Path $destDir -ItemType Directory -Force | Out-Null
			}
			Get-RemoteFile-OneLake -RelativeName ".pax_resume/$run/$localRel" -DestinationPath $dest
			[void]$sweepPublished.Add([string]$localRel)
			$count++
		}
	}
	return $count
}

function Save-CsvAtomic {
	<#
	.SYNOPSIS
		Atomic CSV write helper using temp+rename, mirroring Save-CheckpointToDisk.
	.DESCRIPTION
		Replaces direct `Export-Csv -Path $target` calls at output sites that previously
		risked a half-written file on Ctrl+C / power loss / container OOM-kill.
		Writes to "$Path.tmp" first, then Move-Item -Force overwrites the target in a
		single filesystem operation. On any failure the temp file is removed and the
		original $Path (if any) is left untouched.

		For remote tiers (SharePoint / Fabric) the caller still passes a LOCAL scratch
		path; remote upload happens later via the existing upload pipeline. So this
		helper only needs to handle the local atomic-rename case.

		Encoding/quote handling mirrors what the existing call sites used (UTF-8,
		NoTypeInformation) so output bytes are unchanged for successful writes.
	.PARAMETER InputObject
		Rows to export. Accepts arrays, lists, or single objects via pipeline.
	.PARAMETER Path
		Final destination path. Will be replaced atomically when the write succeeds.
	.PARAMETER NoTypeInformation
		Forwarded to Export-Csv. Default $true (matches all current call sites).
	.PARAMETER Encoding
		Forwarded to Export-Csv. Default 'UTF8' (matches all current call sites).
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory, ValueFromPipeline)]
		[AllowNull()]
		$InputObject,

		[Parameter(Mandatory)]
		[string]$Path,

		[switch]$NoTypeInformation = $true,
		[string]$Encoding = 'UTF8'
	)
	begin {
		$rows = New-Object System.Collections.Generic.List[object]
	}
	process {
		if ($null -ne $InputObject) {
			# Accept arrays piped as a single object, single objects, or per-pipeline-element streams.
			if ($InputObject -is [System.Collections.IEnumerable] -and -not ($InputObject -is [string])) {
				foreach ($r in $InputObject) { if ($null -ne $r) { [void]$rows.Add($r) } }
			} else {
				[void]$rows.Add($InputObject)
			}
		}
	}
	end {
		$tmp = "$Path.tmp"
		try {
			# Ensure destination directory exists (caller may have skipped this).
			$destDir = Split-Path -Path $Path -Parent
			if ($destDir -and -not (Test-Path -LiteralPath $destDir -PathType Container)) {
				New-Item -Path $destDir -ItemType Directory -Force | Out-Null
			}

			if ($rows.Count -eq 0) {
				# Header-only fallback: write an empty file (best-effort header derived from $InputObject's first row would be ambiguous here).
				# Match the behavior of `Export-Csv -InputObject @()`: produce an empty file with no header.
				Set-Content -LiteralPath $tmp -Value '' -Encoding $Encoding -NoNewline
			} else {
				$rows | Export-Csv -Path $tmp -NoTypeInformation:$NoTypeInformation -Encoding $Encoding -Force -ErrorAction Stop
			}

			# Atomic replace. On Windows, Move-Item -Force will overwrite an existing file.
			Move-Item -LiteralPath $tmp -Destination $Path -Force -ErrorAction Stop
		}
		catch {
			# Best-effort cleanup of temp; rethrow so callers see the failure.
			try { if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } } catch {}
			throw
		}
	}
}

# ==========================================================================
# CHECKPOINT LOCKING (G-9)
# ==========================================================================
# Defends against two replicas of the same PAX run racing on the same checkpoint
# file. The race surface is real only when an operator deliberately sets ACA Job
# parallelism > 1 (or runs two PAX invocations against the same OutputPath in
# the same wall-clock second). The default ACA Job replicaCompletionCount=1
# path is safe; this is defense-in-depth for the misconfigured case.
#
# Lock file: "<CheckpointPath>.lock"
# Contents:  JSON { pid, host, started, runTimestamp }
# Stale detection:
#   - If the lock file's pid is dead on this machine -> treat as stale, take over.
#   - If pid is alive on this machine -> reject (loud error, exit non-zero).
#   - If the lock file is on a different host (different "host" field) AND was
#     last touched more than $script:CheckpointLockStaleTtl ago -> treat as
#     stale, take over (cannot verify a foreign PID).
# The exclusive FileStream we open on the lock file is held for the lifetime of
# the run, so a concurrent acquire on the same Windows host will fail at the
# filesystem level even if the JSON-based check races.
$script:CheckpointLockStream    = $null
$script:CheckpointLockPath      = $null
$script:CheckpointLockStaleTtl  = [TimeSpan]::FromMinutes(10)

function script:Acquire-CheckpointLock {
	param(
		[Parameter(Mandatory)][string]$CheckpointPath
	)
	$lockPath = "$CheckpointPath.lock"

	# Inspect any existing lock for stale-takeover eligibility BEFORE attempting open.
	if (Test-Path -LiteralPath $lockPath -PathType Leaf) {
		$existing = $null
		try { $existing = Get-Content -LiteralPath $lockPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop } catch {}
		$stale = $false
		$reason = ''
		if (-not $existing) {
			$stale = $true; $reason = 'unreadable lock file (corrupt or empty)'
		}
		elseif ($existing.host -eq [System.Net.Dns]::GetHostName()) {
			# Same-host: definitive PID check.
			$alive = $false
			try { $alive = [bool](Get-Process -Id ([int]$existing.pid) -ErrorAction Stop) } catch { $alive = $false }
			if (-not $alive) { $stale = $true; $reason = "owning PID $($existing.pid) is no longer running on this host" }
		}
		else {
			# Foreign host: fall back to age-based TTL.
			try {
				$age = (Get-Date) - ([datetime]$existing.started)
				if ($age -gt $script:CheckpointLockStaleTtl) {
					$stale = $true
					$reason = "foreign-host lock from $($existing.host) is older than $($script:CheckpointLockStaleTtl.TotalMinutes) min (age $([int]$age.TotalMinutes) min)"
				}
			} catch { $stale = $true; $reason = 'foreign-host lock has unparseable timestamp' }
		}

		if ($stale) {
			Write-LogHost "  Checkpoint lock at $lockPath is stale ($reason); taking over." -ForegroundColor Yellow
			try { Remove-Item -LiteralPath $lockPath -Force -ErrorAction Stop } catch {
				throw "G-9: Could not remove stale checkpoint lock at $lockPath`: $($_.Exception.Message)"
			}
		}
		else {
			$ownerDesc = if ($existing) { "pid=$($existing.pid) host=$($existing.host) started=$($existing.started)" } else { '(unknown owner)' }
			throw "G-9: Another PAX run is using this checkpoint ($ownerDesc). Refusing to start. If you know the other run is dead, delete the lock file manually: $lockPath"
		}
	}

	# Open the lock file exclusively (CreateNew + FileShare.None). Hold the stream for the lifetime of the run.
	try {
		$stream = [System.IO.File]::Open($lockPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
	}
	catch {
		throw "G-9: Failed to acquire checkpoint lock at $lockPath`: $($_.Exception.Message). Another process may have raced in."
	}

	# Stamp the lock with our identity so other replicas can do stale detection later.
	$payload = @{
		pid          = $PID
		host         = [System.Net.Dns]::GetHostName()
		started      = (Get-Date).ToUniversalTime().ToString('o')
		runTimestamp = $global:ScriptRunTimestamp
	} | ConvertTo-Json -Compress
	$bytes = [System.Text.Encoding]::UTF8.GetBytes($payload)
	$stream.Write($bytes, 0, $bytes.Length)
	$stream.Flush()

	$script:CheckpointLockStream = $stream
	$script:CheckpointLockPath   = $lockPath
}

function script:Release-CheckpointLock {
	if ($script:CheckpointLockStream) {
		try { $script:CheckpointLockStream.Dispose() } catch {}
		$script:CheckpointLockStream = $null
	}
	if ($script:CheckpointLockPath -and (Test-Path -LiteralPath $script:CheckpointLockPath)) {
		try { Remove-Item -LiteralPath $script:CheckpointLockPath -Force -ErrorAction SilentlyContinue } catch {}
	}
	$script:CheckpointLockPath = $null
}

function Save-CheckpointToDisk {
	<#
	.SYNOPSIS
		Writes current checkpoint data to disk atomically.
	.DESCRIPTION
		Uses temp file + rename pattern for atomic writes to prevent corruption.

		This function SELF-GATES on $script:CheckpointEnabled. Callers are still
		expected to gate at the call site, but if a future caller forgets, this
		guard turns "silently writes a checkpoint when disabled" into a safe no-op.
	#>

	# Self-gate. Do NOT remove without revisiting the corresponding static tests.
	if (-not $script:CheckpointEnabled) {
		return
	}

	if (-not $script:CheckpointPath -or -not $script:CheckpointData) {
		return
	}
	
	try {
		# Update timestamp
		$script:CheckpointData.lastUpdated = (Get-Date).ToUniversalTime().ToString('o')
		
		# Update statistics
		$script:CheckpointData.statistics.partitionsComplete = $script:CheckpointData.partitions.completed.Count
		$script:CheckpointData.statistics.partitionsQueryCreated = $script:CheckpointData.partitions.queryCreated.Count
		$script:CheckpointData.statistics.partitionsRemaining = $script:CheckpointData.partitions.total - 
			$script:CheckpointData.statistics.partitionsComplete - 
			$script:CheckpointData.statistics.partitionsQueryCreated
		
		# Write to temp file first (atomic write pattern)
		$tempPath = "$($script:CheckpointPath).tmp"
		$script:CheckpointData | ConvertTo-Json -Depth 10 | Set-Content -Path $tempPath -Encoding UTF8 -Force
		
		# Remove destination first if it exists (Move-Item -Force doesn't always work on Windows)
		if (Test-Path $script:CheckpointPath) {
			Remove-Item -Path $script:CheckpointPath -Force -ErrorAction SilentlyContinue
		}
		
		# Rename to final (atomic on most filesystems)
		Move-Item -Path $tempPath -Destination $script:CheckpointPath -Force

		# Fabric tier: mirror the full resume artifact set (checkpoint JSON,
		# .pax_incremental/*.jsonl, *_PARTIAL.csv) to a durable OneLake path inside
		# the same try block so either both the local write and the mirror upload
		# succeed or the run aborts. Local and SharePoint tiers keep resume artifacts
		# local-only (those hosts are not ephemeral). See Sync-FabricResumeMirror.
		if ($script:DestTier -and $script:DestTier['Purview'] -eq 'Fabric') {
			Sync-FabricResumeMirror
		}
	}
	catch {
		# Fabric-tier mirror failure must abort: a torn artifact set on the durable
		# mirror would silently corrupt a future resume. Local checkpoint write
		# failures remain a soft warning.
		if ($script:DestTier -and $script:DestTier['Purview'] -eq 'Fabric') {
			throw ("Checkpoint mirror to OneLake failed; aborting to preserve resume integrity: {0}" -f $_.Exception.Message)
		}
		Write-LogHost "  Warning: Failed to save checkpoint: $($_.Exception.Message)" -ForegroundColor Yellow
	}
}

function Move-PaxFileOverwriteAtomic {
	<#
	.SYNOPSIS
		Same-directory overwrite-rename that keeps the DESTINATION path continuously
		present, with a bounded retry for transient Windows sharing failures.
	.DESCRIPTION
		[System.IO.File]::Move(..., overwrite) maps to MoveFileEx with
		MOVEFILE_REPLACE_EXISTING - one directory-entry replacement, so the destination
		path never disappears. That is the property a checkpoint swap needs and that
		neither remove-then-move nor [System.IO.File]::Replace provides: both rename or
		delete the destination BEFORE putting the replacement in place, leaving a window
		in which an interruption exposes no file at all.

		MoveFileEx can transiently fail while another agent (indexer, antivirus scan, a
		just-closed reader) still holds the destination open, so a bounded retry with a
		short backoff is applied. Every attempt is a COMPLETE replacement: a failed
		attempt leaves the destination holding its previous content - never nothing - so
		retrying is always safe. The last failure is rethrown when the budget is
		exhausted so callers fail closed instead of proceeding on an unproven swap.
	#>
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] [string] $SourcePath,
		[Parameter(Mandatory)] [string] $DestinationPath,
		[int] $MaxAttempts = 10,
		[int] $BackoffMilliseconds = 25
	)
	$attempt = 0
	while ($true) {
		try {
			[System.IO.File]::Move($SourcePath, $DestinationPath, $true)
			return
		}
		catch {
			$attempt++
			if ($attempt -ge $MaxAttempts) { throw }
			Start-Sleep -Milliseconds $BackoffMilliseconds
		}
	}
}

function Save-CheckpointStrict {
	<#
	.SYNOPSIS
		Durable, verify-after-write checkpoint publication for the operator-cleared
		uncertain-create transition. Unlike Save-CheckpointToDisk, a local write or
		replace failure is NEVER downgraded to a soft warning: any failure THROWS so
		the caller can fail closed and refuse to authorize a fresh create.
	.DESCRIPTION
		Serializes the current checkpoint to a temp file with terminating error
		semantics (-ErrorAction Stop, so a nonterminating write error cannot be
		silently ignored), then atomically replaces the destination WITHOUT a
		remove-then-move loss window (a retained backup copy plus a single
		overwrite-rename when the destination already exists, else a plain move into
		place), and finally re-reads the
		destination from disk and confirms it parses before returning $true. Any
		failure in write, replace, or re-read verification throws. The Fabric-tier
		durable-or-abort mirror contract of Save-CheckpointToDisk is preserved.

		ORDERING (local publication vs remote transaction). These are two separate
		systems, so the order is fixed and explicit: the LOCAL publication is completed
		and verified FIRST (atomic replace, then re-read + parse), and only then is the
		Fabric-tier remote transaction committed by Sync-FabricResumeMirror. A remote
		generation therefore never becomes authoritative before the local publication it
		describes has been proven, so a local post-publication failure can never require
		"un-publishing" a remotely authoritative checkpoint. Conversely, a remote
		transaction that fails before its commit point leaves the PRIOR remote generation
		authoritative, so the local rollback below has nothing remote to undo.

		ROLLBACK ATOMICITY. The rollback restores the retained prior copy with a single
		overwrite-rename via Move-PaxFileOverwriteAtomic (MoveFileEx /
		MOVEFILE_REPLACE_EXISTING), so the canonical checkpoint path stays continuously
		present for the whole rollback - the earlier remove-then-move sequence opened a
		window in which an interruption left NO checkpoint at the canonical path, and
		System.IO.File::Replace opens a smaller but real window of the same kind because
		ReplaceFile renames the destination aside before moving the replacement in. The
		repudiated candidate is retained as recovery material until the restoration has been
		proven byte-exact.
	.OUTPUTS
		$true on a proven durable publication; otherwise throws.
	#>

	# Self-gate identically to Save-CheckpointToDisk. A disabled or unconfigured
	# checkpoint is not a durable-write failure; it is simply nothing to persist.
	if (-not $script:CheckpointEnabled) { return $false }
	if (-not $script:CheckpointPath -or -not $script:CheckpointData) { return $false }

	# Update timestamp + statistics (same shape as Save-CheckpointToDisk).
	$script:CheckpointData.lastUpdated = (Get-Date).ToUniversalTime().ToString('o')
	$script:CheckpointData.statistics.partitionsComplete = $script:CheckpointData.partitions.completed.Count
	$script:CheckpointData.statistics.partitionsQueryCreated = $script:CheckpointData.partitions.queryCreated.Count
	$script:CheckpointData.statistics.partitionsRemaining = $script:CheckpointData.partitions.total -
		$script:CheckpointData.statistics.partitionsComplete -
		$script:CheckpointData.statistics.partitionsQueryCreated

	$json = $script:CheckpointData | ConvertTo-Json -Depth 10
	$tempPath = "$($script:CheckpointPath).strict.tmp"

	# 1) Write the temp file with terminating semantics so a nonterminating write
	#    error surfaces as a failure instead of being silently ignored.
	Set-Content -Path $tempPath -Value $json -Encoding UTF8 -Force -ErrorAction Stop

	# 2) Publish as a REAL transaction. The full post-publication verification (local
	#    re-read + parse, then the Fabric-tier durable-or-abort mirror) runs INSIDE the
	#    transaction, and the prior copy is RETAINED until that verification has fully
	#    succeeded. A post-publication failure is NOT allowed to leave the destination in
	#    the new state while memory rolls back (a split-brain): the prior bytes are
	#    restored atomically from the retained backup (dest-exists) or the newly published
	#    candidate is removed (new-destination), the restore is itself proven, and only
	#    then is the original failure re-thrown so the caller fails closed with the durable
	#    checkpoint byte-for-byte unchanged. A restore that itself fails raises the DISTINCT
	#    PAX-FATAL-ROLLBACK category so an indeterminate disk state is never hidden as a
	#    normal fail-closed success. Never bare-remove an existing destination before the
	#    swap (that opens a data-loss window).
	try {
		if (Test-Path -LiteralPath $script:CheckpointPath) {
			# Capture the exact prior bytes BEFORE the swap so the restore can be proven to
			# reproduce them byte-for-byte. A locked/unreadable destination throws here,
			# BEFORE any mutation, leaving the prior checkpoint untouched.
			$priorBytes = [System.IO.File]::ReadAllBytes($script:CheckpointPath)
			$backupPath = "$($script:CheckpointPath).strict.bak"
			# RETAIN the prior copy first, then swap with a SINGLE overwrite-rename so the
			# canonical path is continuously present. [System.IO.File]::Replace is deliberately
			# NOT used: the underlying ReplaceFile renames the destination ASIDE before renaming
			# the replacement into place, which leaves an observable window in which the
			# canonical path does not exist. Move-PaxFileOverwriteAtomic uses MoveFileEx with
			# MOVEFILE_REPLACE_EXISTING - one directory-entry replacement, no absence window.
			# The prior copy is RETAINED in the backup until the whole post-publication
			# verification has committed.
			[System.IO.File]::Copy($script:CheckpointPath, $backupPath, $true)
			Move-PaxFileOverwriteAtomic -SourcePath $tempPath -DestinationPath $script:CheckpointPath
			try {
				# 3) Durability proof: re-read the destination and confirm it exists and parses.
				if (-not (Test-Path -LiteralPath $script:CheckpointPath)) {
					throw "Strict checkpoint publish failed: destination missing after replace."
				}
				$roundTrip = Get-Content -LiteralPath $script:CheckpointPath -Raw -ErrorAction Stop
				$null = $roundTrip | ConvertFrom-Json -ErrorAction Stop
				# Fabric tier: mirror inside the same durable-or-abort contract as
				# Save-CheckpointToDisk (a mirror failure aborts to preserve resume integrity).
				if ($script:DestTier -and $script:DestTier['Purview'] -eq 'Fabric') {
					Sync-FabricResumeMirror
				}
			}
			catch {
				$__pubErr = $_
				# Post-publication failure: restore the prior bytes from the retained backup and
				# PROVE the restore reproduced them exactly, then re-throw so the caller fails
				# closed with the durable checkpoint byte-for-byte unchanged. A restore that
				# cannot be proven raises the distinct rollback-failure category.
				$rollbackBackupPath = "$($script:CheckpointPath).strict.rbk"
				try {
					if (Test-Path -LiteralPath $backupPath) {
						# Restore the prior bytes from the retained backup WITHOUT ever removing the
						# canonical destination first. The repudiated candidate is copied aside as
						# recovery material (BEST EFFORT - failing to take that extra copy must never
						# block the restoration itself), then a single overwrite-rename puts the prior
						# bytes back. Move-PaxFileOverwriteAtomic is one directory-entry replacement, so
						# the canonical checkpoint path is CONTINUOUSLY PRESENT for the whole rollback:
						# a process termination, host restart, or storage fault can never observe an
						# absent checkpoint. (The prior remove-then-move sequence had exactly that loss
						# window, and [System.IO.File]::Replace has a smaller but real one because
						# ReplaceFile renames the destination aside first.)
						if (Test-Path -LiteralPath $script:CheckpointPath) {
							try { [System.IO.File]::Copy($script:CheckpointPath, $rollbackBackupPath, $true) }
							catch { Write-Verbose ("Repudiated checkpoint candidate could not be retained: {0}" -f $_.Exception.Message) }
						}
						Move-PaxFileOverwriteAtomic -SourcePath $backupPath -DestinationPath $script:CheckpointPath
					}
					else {
						throw "retained backup is missing; the prior checkpoint bytes cannot be restored."
					}
					$restoredBytes = [System.IO.File]::ReadAllBytes($script:CheckpointPath)
					$restoredMatches = ($restoredBytes.Length -eq $priorBytes.Length)
					if ($restoredMatches) {
						for ($__i = 0; $__i -lt $priorBytes.Length; $__i++) {
							if ($restoredBytes[$__i] -ne $priorBytes[$__i]) { $restoredMatches = $false; break }
						}
					}
					if (-not $restoredMatches) {
						throw "the restored destination does not byte-match the pre-transaction checkpoint."
					}
					# Proven byte-exact restoration: the repudiated candidate retained by the atomic
					# swap is no longer recovery material, so it is discarded HERE (success path only).
					if (Test-Path -LiteralPath $rollbackBackupPath) { Remove-Item -LiteralPath $rollbackBackupPath -Force -ErrorAction SilentlyContinue }
				}
				catch {
					$script:GenericFatal = $true
					throw "PAX-FATAL-ROLLBACK: strict checkpoint publish failed and the prior checkpoint could NOT be restored for '$($script:CheckpointPath)'; disk state is indeterminate: $($_.Exception.Message)"
				}
				throw $__pubErr
			}
			# Proven durable publication: the prior copy is no longer needed.
			Remove-Item -LiteralPath $backupPath -Force -ErrorAction SilentlyContinue
		}
		else {
			# New destination (no prior checkpoint to preserve). Publish, then verify + mirror
			# inside the transaction; a post-publication failure REMOVES the newly published
			# candidate so no false durable state survives, then fails closed.
			[System.IO.File]::Move($tempPath, $script:CheckpointPath)
			try {
				if (-not (Test-Path -LiteralPath $script:CheckpointPath)) {
					throw "Strict checkpoint publish failed: destination missing after move."
				}
				$roundTrip = Get-Content -LiteralPath $script:CheckpointPath -Raw -ErrorAction Stop
				$null = $roundTrip | ConvertFrom-Json -ErrorAction Stop
				if ($script:DestTier -and $script:DestTier['Purview'] -eq 'Fabric') {
					Sync-FabricResumeMirror
				}
			}
			catch {
				$__pubErr = $_
				# No prior checkpoint existed: remove the newly published candidate to restore
				# the no-checkpoint pre-state, then fail closed. A removal that itself fails
				# raises the distinct rollback-failure category (disk state indeterminate).
				try {
					if (Test-Path -LiteralPath $script:CheckpointPath) {
						[System.IO.File]::Delete($script:CheckpointPath)
					}
				}
				catch {
					$script:GenericFatal = $true
					throw "PAX-FATAL-ROLLBACK: strict checkpoint publish failed and the newly published candidate could NOT be removed for new destination '$($script:CheckpointPath)'; disk state is indeterminate: $($_.Exception.Message)"
				}
				throw $__pubErr
			}
		}
	}
	finally {
		# Clean the strict temp without ever touching the prior valid checkpoint. After a
		# successful Replace/Move the temp is already consumed; this only removes a leftover
		# temp from a pre-publication failure.
		if (Test-Path -LiteralPath $tempPath) { Remove-Item -LiteralPath $tempPath -Force -ErrorAction SilentlyContinue }
	}
	return $true
}

function Save-Checkpoint {
	<#
	.SYNOPSIS
		Updates checkpoint with partition state change and saves to disk.
	.PARAMETER PartitionIndex
		The partition index (1-based).
	.PARAMETER State
		'QueryCreated', 'Completed', or 'UncertainCreate'
	.PARAMETER QueryId
		The server-assigned query ID.
	.PARAMETER PartitionStart
		Partition start time (optional - looked up from partitionStatus if not provided).
	.PARAMETER PartitionEnd
		Partition end time (optional - looked up from partitionStatus if not provided).
	.PARAMETER RecordCount
		Number of records (only for Completed state).
	.PARAMETER DeferDiskWrite
		Perform the in-memory bucket transition ONLY and skip the warning-only disk write.
		Reserved for a caller that owns a STRICT single-publication transaction: it stages the
		COMPLETE post-transition state here, then publishes it exactly once through
		Save-CheckpointStrict and fails closed unless that publication is proven durable.
		Ignored by -Force.
	.PARAMETER Force
		Just save current checkpoint state to disk without updating partition info.
	#>
	param(
		[Parameter()]
		[int]$PartitionIndex,
		
		[Parameter()]
		[ValidateSet('QueryCreated', 'Completed', 'UncertainCreate')]
		[string]$State,
		
		[Parameter()]
		[string]$QueryId,
		
		[Parameter()]
		[datetime]$PartitionStart,
		
		[Parameter()]
		[datetime]$PartitionEnd,
		
		[Parameter()]
		[int]$RecordCount = 0,
		
		[Parameter()]
		[hashtable]$LifecycleState,
		
		[Parameter()]
		[string]$Fingerprint,
		
		[Parameter()]
		[switch]$DeferDiskWrite,
		
		[Parameter()]
		[switch]$Force
	)
	
	if (-not $script:CheckpointData) {
		return
	}
	
	# If -Force is specified, just save current state to disk without updating partition info
	if ($Force) {
		Save-CheckpointToDisk
		return
	}
	
	# For normal calls, require the mandatory parameters. An UncertainCreate entry is
	# durable state for a partition that has NO queryId yet (a possibly-accepted create
	# whose acceptance is unproven), so it is exempt from the QueryId requirement.
	if (-not $PartitionIndex -or -not $State -or (-not $QueryId -and $State -ne 'UncertainCreate')) {
		Write-Verbose "Save-Checkpoint: Missing required parameters (PartitionIndex, State, QueryId) - skipping"
		return
	}
	
	# Look up partition times from partitionStatus if not provided
	if (-not $PartitionStart -or -not $PartitionEnd) {
		$partitionInfo = $script:partitionStatus[$PartitionIndex]
		if ($partitionInfo -and $partitionInfo.Partition) {
			# The Partition object has PStart and PEnd properties
			if (-not $PartitionStart -and $partitionInfo.Partition.PStart) { $PartitionStart = $partitionInfo.Partition.PStart }
			if (-not $PartitionEnd -and $partitionInfo.Partition.PEnd) { $PartitionEnd = $partitionInfo.Partition.PEnd }
		}
		
		# If still missing, we can't proceed with checkpoint save
		if (-not $PartitionStart -or -not $PartitionEnd) {
			Write-Verbose "Save-Checkpoint: Could not determine partition times for index $PartitionIndex - skipping checkpoint update"
			return
		}
	}
	
	$partitionEntry = @{
		index = $PartitionIndex
		start = $PartitionStart.ToUniversalTime().ToString('o')
		end = $PartitionEnd.ToUniversalTime().ToString('o')
		queryId = $QueryId
	}
	# Optionally persist structured per-query lifecycle state. These
	# fields are ABSENT on legacy checkpoints; when absent on load the resume path
	# treats each field as its default and NEVER discards or recreates the stored
	# queryId. Only stable, resume-relevant fields are persisted.
	if ($LifecycleState) {
		foreach ($lk in @('QueryApiVersion', 'FailureCategory', 'AlternateVersionChecked', 'AlternateVersionResult', 'QueryConfirmedAbsent', 'ReplacementAttempted', 'ReplacementQueryId', 'ZeroRecordComplete', 'UncertainCreate', 'UncertainCreateInfo')) {
			if ($LifecycleState.ContainsKey($lk)) { $partitionEntry[$lk] = $LifecycleState[$lk] }
		}
	}
	
	# Durable per-contract identity. The fingerprint (New-GraphAuditQueryFingerprint over the
	# canonical creation contract) is the STABLE identity of this entry across workload passes
	# that reuse the same partition index. Prefer an explicitly supplied fingerprint; else
	# derive it from the partition contract carried on partitionStatus; else inherit one already
	# present on this entry (an uncertain-create entry carries it via UncertainCreateInfo).
	# Absent (a legacy caller with no contract in hand) it is simply not stamped and identity
	# falls back to the historical index-only behavior.
	$entryFingerprint = $null
	if (-not [string]::IsNullOrWhiteSpace($Fingerprint)) {
		$entryFingerprint = $Fingerprint
	}
	else {
		$pInfo = if ($null -ne $script:partitionStatus) { $script:partitionStatus[$PartitionIndex] } else { $null }
		if ($pInfo -and $pInfo.Partition -and $pInfo.Partition.PStart -and $pInfo.Partition.PEnd) {
			try {
				$entryFingerprint = New-GraphAuditQueryFingerprint -PStart $pInfo.Partition.PStart -PEnd $pInfo.Partition.PEnd -Activities $pInfo.Partition.Activities -RecordTypes $pInfo.Partition.RecordTypes -ServiceFilter $pInfo.Partition.ServiceFilter
			} catch { $entryFingerprint = $null }
		}
		if ([string]::IsNullOrWhiteSpace($entryFingerprint)) {
			$inherited = Get-PaxCheckpointEntryFingerprint $partitionEntry
			if (-not [string]::IsNullOrWhiteSpace($inherited)) { $entryFingerprint = $inherited }
		}
	}
	if (-not [string]::IsNullOrWhiteSpace($entryFingerprint)) { $partitionEntry.fingerprint = $entryFingerprint }
	
	if ($State -eq 'QueryCreated') {
		$partitionEntry.createdAt = (Get-Date).ToUniversalTime().ToString('o')
		
		# A confirmed QueryCreated (an adopted or freshly created query) SUPERSEDES any
		# durable uncertain-create entry for the SAME contract identity: vacate it here, in the
		# SAME in-memory mutation, BEFORE the atomic disk write, so an adopted partition is never
		# persisted in both queryCreated and uncertainCreate at once (a possibly-accepted create
		# that is now proven created is no longer uncertain). Identity is the fingerprint when
		# present so a different workload contract reusing this index is NOT wrongly vacated.
		$script:CheckpointData.partitions.uncertainCreate = @(
			$script:CheckpointData.partitions.uncertainCreate | Where-Object { -not (Test-PaxCheckpointIdentityMatch $_ $PartitionIndex $entryFingerprint) }
		)
		
		# Add to queryCreated list (if not already there)
		$existing = $script:CheckpointData.partitions.queryCreated | Where-Object { Test-PaxCheckpointIdentityMatch $_ $PartitionIndex $entryFingerprint }
		if (-not $existing) {
			$script:CheckpointData.partitions.queryCreated += $partitionEntry
		}
	}
	elseif ($State -eq 'Completed') {
		$partitionEntry.records = $RecordCount
		
		# Remove from queryCreated if present (same contract identity)
		$script:CheckpointData.partitions.queryCreated = @(
			$script:CheckpointData.partitions.queryCreated | Where-Object { -not (Test-PaxCheckpointIdentityMatch $_ $PartitionIndex $entryFingerprint) }
		)
		# A Completed partition also SUPERSEDES any durable uncertain-create entry for the
		# SAME contract identity (same atomic mutation, before the disk write) so completion
		# never leaves a stale uncertain duplicate behind.
		$script:CheckpointData.partitions.uncertainCreate = @(
			$script:CheckpointData.partitions.uncertainCreate | Where-Object { -not (Test-PaxCheckpointIdentityMatch $_ $PartitionIndex $entryFingerprint) }
		)
		
		# Add to completed list (if not already there)
		$existing = $script:CheckpointData.partitions.completed | Where-Object { Test-PaxCheckpointIdentityMatch $_ $PartitionIndex $entryFingerprint }
		if (-not $existing) {
			$script:CheckpointData.partitions.completed += $partitionEntry
			$script:CheckpointData.statistics.totalRecordsSaved += $RecordCount
		}
	}
	elseif ($State -eq 'UncertainCreate') {
		# Durable uncertain-create state: the first create POST may have been accepted but
		# cannot be proven. Persist the fingerprinted display name + contract (carried on
		# UncertainCreateInfo via the lifecycle allow-list above) so ANY later attempt
		# reconciles read-only and never re-POSTs. No real queryId is stored.
		if ($partitionEntry.ContainsKey('queryId')) { $partitionEntry.Remove('queryId') }
		$partitionEntry.UncertainCreate = $true
		$partitionEntry.uncertainAt = (Get-Date).ToUniversalTime().ToString('o')
		# Dedupe by contract identity (fingerprint when present, else index).
		$existing = $script:CheckpointData.partitions.uncertainCreate | Where-Object { Test-PaxCheckpointIdentityMatch $_ $PartitionIndex $entryFingerprint }
		if (-not $existing) {
			$script:CheckpointData.partitions.uncertainCreate += $partitionEntry
		}
	}
	
	# Final normalization guard: a single partition IDENTITY must never be persisted in more
	# than one bucket. Identity is the durable fingerprint when present (so two workload-pass
	# contracts that reuse the same index remain distinct and both survive) and the integer
	# index for legacy entries. This guard now legitimately CALLS the shared identity helpers
	# (Get-PaxEntryIdentityKey / Get-PaxCheckpointEntryFingerprint), so an isolated dot-source
	# of Save-Checkpoint must ALSO load those helpers or the calls throw at runtime.
	# Enforce precedence completed > queryCreated > uncertainCreate BEFORE the atomic disk
	# write, removing any duplicated identity from the lower-precedence bucket(s) in this same
	# in-memory mutation.
	if ($script:CheckpointData -and $script:CheckpointData.partitions) {
		$bxCompletedKeys = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
		foreach ($bxC in @($script:CheckpointData.partitions.completed)) {
			$bxk = Get-PaxEntryIdentityKey $bxC
			if ($null -ne $bxk) { [void]$bxCompletedKeys.Add($bxk) }
		}
		# completed supersedes queryCreated
		$script:CheckpointData.partitions.queryCreated = @(@($script:CheckpointData.partitions.queryCreated) | Where-Object { $null -eq $_ -or $null -eq (Get-PaxEntryIdentityKey $_) -or -not $bxCompletedKeys.Contains((Get-PaxEntryIdentityKey $_)) })
		# completed OR queryCreated supersedes uncertainCreate
		$bxQueryCreatedKeys = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
		foreach ($bxQ in @($script:CheckpointData.partitions.queryCreated)) {
			$bxk2 = Get-PaxEntryIdentityKey $bxQ
			if ($null -ne $bxk2) { [void]$bxQueryCreatedKeys.Add($bxk2) }
		}
		$script:CheckpointData.partitions.uncertainCreate = @(@($script:CheckpointData.partitions.uncertainCreate) | Where-Object { $null -eq $_ -or $null -eq (Get-PaxEntryIdentityKey $_) -or -not ($bxCompletedKeys.Contains((Get-PaxEntryIdentityKey $_)) -or $bxQueryCreatedKeys.Contains((Get-PaxEntryIdentityKey $_))) })
	}
	
	# Save to disk. A caller that owns a STRICT single-publication transaction stages the
	# COMPLETE bucket transition in memory (-DeferDiskWrite) and publishes it itself, so the
	# warning-only writer is never allowed to turn an unproven write into a silent success and
	# the transition is never published twice.
	if (-not $DeferDiskWrite) {
		Save-CheckpointToDisk
	}
}

function Test-CheckpointCompatibility {
	<#
	.SYNOPSIS
		Validates that a parsed checkpoint can safely be resumed by this script version.
	.DESCRIPTION
		Defends against three failure modes:
		  1. Legacy integer `version` outside the supported range (1..2).
		  2. `checkpointSchemaVersion` from a FUTURE major release — warned but allowed
		     when within the same major (forward-compat best effort), rejected on major
		     mismatch.
		  3. `compatibilityMinimumVersion` higher than the running script version — hard
		     reject (the checkpoint explicitly says this script is too old).
		The check is intentionally conservative: it never silently up/down-converts the
		structure on disk, and it always emits actionable recovery guidance.
	.OUTPUTS
		$true  -> safe to resume.
		$false -> incompatible; caller must abort the resume.
	#>
	param(
		[Parameter(Mandatory)] $CheckpointData,
		[Parameter(Mandatory)] [string]$RunningScriptVersion
	)

	# 1) Legacy integer version range (preserves prior behaviour).
	if (-not $CheckpointData.version -or [int]$CheckpointData.version -lt 1 -or [int]$CheckpointData.version -gt 2) {
		Write-LogHost "ERROR: Unsupported checkpoint legacy version: $($CheckpointData.version). Supported range is 1..2." -ForegroundColor Red
		Write-LogHost "  Recovery: start a fresh run without -Resume, or use a checkpoint produced by PAX 1.11.x." -ForegroundColor Yellow
		return $false
	}

	# 2/3) New structured fields are OPTIONAL (older checkpoints predate them). When
	# present, they are authoritative.
	$schemaVer  = [string]$CheckpointData.checkpointSchemaVersion
	$minVerStr  = [string]$CheckpointData.compatibilityMinimumVersion
	$createdBy  = [string]$CheckpointData.createdByVersion

	try { $running = [version]$RunningScriptVersion } catch { $running = $null }
	try { $minVer  = if ($minVerStr) { [version]$minVerStr } else { $null } } catch { $minVer = $null }
	try { $created = if ($createdBy) { [version]$createdBy } else { $null } } catch { $created = $null }

	if ($minVer -and $running -and $running -lt $minVer) {
		Write-LogHost "ERROR: Checkpoint requires PAX >= $minVerStr but running version is $RunningScriptVersion." -ForegroundColor Red
		Write-LogHost "  Recovery: upgrade PAX to a version >= $minVerStr or start a fresh run without -Resume." -ForegroundColor Yellow
		return $false
	}

	if ($schemaVer) {
		# Parse the schema version. Only the leading "major.minor" pair gates compatibility.
		$parts = $schemaVer.Split('.')
		$schemaMajor = 0; [void][int]::TryParse($parts[0], [ref]$schemaMajor)
		if ($schemaMajor -gt 2) {
			Write-LogHost "ERROR: Checkpoint schema major version $schemaMajor is newer than this script supports (max major 2)." -ForegroundColor Red
			Write-LogHost "  Recovery: upgrade PAX or start a fresh run without -Resume." -ForegroundColor Yellow
			return $false
		}
	}

	# Created-by drift is informational only (not all script edits change the on-disk shape).
	if ($created -and $running -and $created -gt $running) {
		Write-LogHost "  [WARN] Checkpoint was produced by PAX $createdBy; running PAX $RunningScriptVersion is older. Resume will proceed but newer fields may be ignored." -ForegroundColor Yellow
	}

	return $true
}

function Read-Checkpoint {
	<#
	.SYNOPSIS
		Loads and validates a checkpoint file.
	.PARAMETER CheckpointPath
		Path to the checkpoint JSON file.
	.OUTPUTS
		$true if valid and loaded, $false if invalid.
	#>
	param(
		[Parameter(Mandatory)]
		[string]$CheckpointPath
	)
	
	if (-not (Test-Path $CheckpointPath)) {
		Write-LogHost "ERROR: Checkpoint file not found: $CheckpointPath" -ForegroundColor Red
		return $false
	}
	
	try {
		$data = Get-Content -Path $CheckpointPath -Raw | ConvertFrom-Json -AsHashtable
		
		# Validate version (supports version 1 and 2)
		if (-not $data.version -or $data.version -gt 2) {
			Write-LogHost "ERROR: Unsupported checkpoint version: $($data.version). This script supports versions 1-2." -ForegroundColor Red
			return $false
		}

		# Structured compatibility check (schema version,
		# compatibilityMinimumVersion, createdByVersion). Hard-rejects checkpoints from
		# the future or from releases that explicitly require a newer PAX.
		if (-not (Test-CheckpointCompatibility -CheckpointData $data -RunningScriptVersion $ScriptVersion)) {
			return $false
		}
		
		# Validate required fields
		if (-not $data.runTimestamp -or -not $data.outputFiles -or -not $data.partitions) {
			Write-LogHost "ERROR: Checkpoint file is missing required fields" -ForegroundColor Red
			return $false
		}
		
		# Get output directory from checkpoint path
		$outputDir = Split-Path $CheckpointPath -Parent
		$partialCsvPath = Join-Path $outputDir $data.outputFiles.partialCsv
		
		# Note: We don't require _PARTIAL.csv to exist - the actual data is in .pax_incremental/*.jsonl files
		# The _PARTIAL.csv is only created when merging at completion, or may not exist yet
		
		# Check for incremental save data if there are completed partitions
		$completedPartitions = @($data.partitionStates.PSObject.Properties | Where-Object { $_.Value.state -eq 'Completed' })
		if ($completedPartitions.Count -gt 0) {
			$incrementalDir = Join-Path $outputDir ".pax_incremental"
			$hasIncrementalData = $false
			$incrementalRecordCount = 0
			
			if (Test-Path $incrementalDir) {
				$jsonlFiles = Get-ChildItem -Path $incrementalDir -Filter "*.jsonl" -ErrorAction SilentlyContinue
				if ($jsonlFiles -and $jsonlFiles.Count -gt 0) {
					$hasIncrementalData = $true
					# Count records in files
					foreach ($file in $jsonlFiles) {
						$incrementalRecordCount += (Get-Content $file.FullName | Measure-Object -Line).Lines
					}
				}
			}
			
			$expectedRecords = ($completedPartitions | ForEach-Object { $_.Value.recordCount } | Measure-Object -Sum).Sum
			
			if (-not $hasIncrementalData) {
				Write-LogHost ""
				Write-LogHost "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
				Write-LogHost "  WARNING: INCREMENTAL DATA MISSING" -ForegroundColor Red
				Write-LogHost "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
				Write-LogHost ""
				Write-LogHost "  Checkpoint shows $($completedPartitions.Count) completed partition(s) with ~$expectedRecords records," -ForegroundColor Yellow
				Write-LogHost "  but the .pax_incremental folder is missing or empty." -ForegroundColor Yellow
				Write-LogHost ""
				Write-LogHost "  Expected location: $incrementalDir" -ForegroundColor White
				Write-LogHost ""
				Write-LogHost "  If you continue, data from completed partitions will be LOST." -ForegroundColor Red
				Write-LogHost "  The remaining partitions will be re-queried, but previous data cannot be recovered." -ForegroundColor Red
				Write-LogHost ""
				Write-LogHost "  OPTIONS:" -ForegroundColor Cyan
				Write-LogHost "    1. Restore the .pax_incremental folder from backup (if available)" -ForegroundColor White
				Write-LogHost "    2. Start a fresh run without -Resume (will re-query all partitions)" -ForegroundColor White
				Write-LogHost "    3. Continue anyway and accept data loss from completed partitions" -ForegroundColor White
				Write-LogHost ""
				Write-LogHost "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
				Write-LogHost ""

				# G-6 noninteractive guard: a noninteractive host (container, ACA Job, scheduled
				# task, CI runner) cannot answer a Read-Host. The original code would hang
				# forever on stdin. Fail-fast with a clear message that points at the only
				# two correct recoveries (restore the incremental folder, or start fresh).
				if (script:Test-IsNonInteractive) {
					Write-LogHost "  Noninteractive host detected (no console available to confirm data loss)." -ForegroundColor Red
					Write-LogHost "  Resume aborted to prevent silent data loss." -ForegroundColor Red
					Write-LogHost "  Recovery: restore the .pax_incremental folder from backup OR re-run without -Resume." -ForegroundColor Yellow
					return $false
				}

				$response = Read-Host "Continue with potential data loss? (yes/no)"
				if ($response -notmatch '^y(es)?$') {
					Write-LogHost "Resume cancelled. Consider starting a fresh run." -ForegroundColor Yellow
					return $false
				}
				Write-LogHost "Continuing with resume despite missing incremental data..." -ForegroundColor Yellow
			} elseif ($incrementalRecordCount -lt ($expectedRecords * 0.9)) {
				# Warn if incremental count is significantly less than expected (allow 10% variance for counting differences)
				Write-LogHost ""
				Write-LogHost "  [WARN] Incremental data may be incomplete:" -ForegroundColor Yellow
				Write-LogHost "         Checkpoint expects ~$expectedRecords records from completed partitions" -ForegroundColor Yellow
				Write-LogHost "         Found $incrementalRecordCount records in .pax_incremental" -ForegroundColor Yellow
				Write-LogHost ""
			}
		}
		
		# Load into script scope
		$script:CheckpointPath = $CheckpointPath
		$script:CheckpointData = $data
		$script:PartialOutputPath = $partialCsvPath
		$script:IsResumeMode = $true
		
		return $true
	}
	catch {
		Write-LogHost "ERROR: Failed to parse checkpoint file: $($_.Exception.Message)" -ForegroundColor Red
		return $false
	}
}

function Find-Checkpoints {
	<#
	.SYNOPSIS
		Discovers checkpoint files in the specified output directory.
	.PARAMETER OutputPath
		Directory to search for checkpoint files.
	.OUTPUTS
		Array of checkpoint info objects sorted by LastUpdated (newest first).
	#>
	param(
		[Parameter(Mandatory)]
		[string]$OutputPath
	)
	
	if (-not (Test-Path $OutputPath)) {
		return @()
	}
	
	$checkpointFiles = Get-ChildItem -Path $OutputPath -Filter ".pax_checkpoint_*.json" -Force -ErrorAction SilentlyContinue
	
	if (-not $checkpointFiles -or $checkpointFiles.Count -eq 0) {
		return @()
	}
	
	$checkpoints = @()
	
	foreach ($file in $checkpointFiles) {
		try {
			$data = Get-Content -Path $file.FullName -Raw | ConvertFrom-Json -AsHashtable
			
			$checkpoints += [PSCustomObject]@{
				Path = $file.FullName
				FileName = $file.Name
				RunTimestamp = $data.runTimestamp
				LastUpdated = script:Parse-DateSafe $data.lastUpdated
				StartDate = if ($data.parameters.startDate) { $d = script:Parse-DateSafe $data.parameters.startDate; if ($d) { $d.ToLocalTime().ToString('yyyy-MM-dd') } else { 'Unknown' } } else { 'Unknown' }
				EndDate = if ($data.parameters.endDate) { $d = script:Parse-DateSafe $data.parameters.endDate; if ($d) { $d.ToLocalTime().ToString('yyyy-MM-dd') } else { 'Unknown' } } else { 'Unknown' }
				PartitionsComplete = $data.statistics.partitionsComplete
				PartitionsTotal = $data.partitions.total
				RecordsSaved = $data.statistics.totalRecordsSaved
			}
		}
		catch {
			# Skip invalid checkpoint files
			continue
		}
	}
	
	# Sort by LastUpdated descending (newest first)
	return $checkpoints | Sort-Object -Property LastUpdated -Descending
}

function Select-Checkpoint {
	<#
	.SYNOPSIS
		Prompts user to select from multiple checkpoint files.
	.PARAMETER Checkpoints
		Array of checkpoint info objects from Find-Checkpoints.
	.OUTPUTS
		Selected checkpoint path, or $null if user quits.
	#>
	param(
		[Parameter(Mandatory)]
		[array]$Checkpoints
	)
	
	Write-Host ""
	Write-Host "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Cyan
	Write-Host "  Multiple checkpoint files found. Select one to resume:" -ForegroundColor Cyan
	Write-Host "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Cyan
	Write-Host ""
	
	for ($i = 0; $i -lt $Checkpoints.Count; $i++) {
		$cp = $Checkpoints[$i]
		$num = $i + 1
		Write-Host "  [$num] $($cp.LastUpdated.ToString('yyyy-MM-dd HH:mm')) | $($cp.StartDate) to $($cp.EndDate) | $($cp.PartitionsComplete)/$($cp.PartitionsTotal) partitions | $($cp.RecordsSaved.ToString('N0')) records" -ForegroundColor White
		Write-Host "      $($cp.FileName)" -ForegroundColor DarkGray
		Write-Host ""
	}
	
	Write-Host "  [Q] Quit (do not resume)" -ForegroundColor Yellow
	Write-Host ""

	# G-6 noninteractive guard: cannot prompt for a checkpoint selection on a
	# container/ACA Job/CI runner. Reject explicitly with a recovery hint instead
	# of letting Read-Host hang on stdin. Operators who actually want resume in
	# noninteractive contexts must pass -Resume <explicit-checkpoint-path>.
	if (script:Test-IsNonInteractive) {
		Write-Host "  Noninteractive host detected: cannot prompt to choose among $($Checkpoints.Count) checkpoint(s)." -ForegroundColor Red
		Write-Host "  Re-run with an explicit path: -Resume `"<full-path-to-.pax_checkpoint_*.json>`"" -ForegroundColor Yellow
		Write-Host "  Or run on an interactive host to use the selection menu." -ForegroundColor Yellow
		return $null
	}

	Send-PromptNotification
	while ($true) {
		$choice = Read-Host "  Enter selection (1-$($Checkpoints.Count)) or 'Q' to quit"
		
		if ($choice -eq 'Q' -or $choice -eq 'q') {
			return $null
		}
		
		$selection = 0
		if ([int]::TryParse($choice, [ref]$selection)) {
			if ($selection -ge 1 -and $selection -le $Checkpoints.Count) {
				return $Checkpoints[$selection - 1]
			}
		}
		
		Write-Host "  Invalid selection. Please enter a number 1-$($Checkpoints.Count) or 'Q' to quit." -ForegroundColor Red
	}
}

function Remove-Checkpoint {
	<#
	.SYNOPSIS
		Deletes checkpoint file after successful completion.
	#>
	
	if ($script:CheckpointPath -and (Test-Path $script:CheckpointPath)) {
		try {
			Remove-Item -Path $script:CheckpointPath -Force
		}
		catch {
			Write-LogHost "  Warning: Could not delete checkpoint file: $($_.Exception.Message)" -ForegroundColor Yellow
		}
	}

	# Release the exclusive checkpoint lock acquired at run start.
	script:Release-CheckpointLock

	$script:CheckpointPath = $null
	$script:CheckpointData = $null
}

function Get-PartitionsToProcess {
	<#
	.SYNOPSIS
		Categorizes partitions based on checkpoint state for resume.
	.PARAMETER AllPartitions
		Array of all partition objects for the date range.
	.OUTPUTS
		Hashtable with ToSkip, ToFetchOnly, and ToCreateAndFetch arrays.
	#>
	param(
		[Parameter(Mandatory)]
		[array]$AllPartitions
	)
	
	$result = @{
		ToSkip = @()           # Already completed - skip entirely
		ToFetchOnly = @()      # Query exists on server - just fetch records
		ToCreateAndFetch = @() # Start fresh - create query then fetch
		ToReconcileOnly = @()  # Durable uncertain-create - reconcile READ-ONLY, never POST
	}
	
	if (-not $script:CheckpointData) {
		# No checkpoint - all partitions need full processing
		$result.ToCreateAndFetch = $AllPartitions
		return $result
	}
	
	# Categorize each partition by DURABLE CONTRACT IDENTITY (the fingerprint when the entry
	# carries one, else the partition index for a legacy checkpoint). Because Graph workload
	# passes RESTART partition indexes at 1, a bucket can now hold MULTIPLE entries that share
	# an index but denote different contracts; each partition is matched to the entry whose
	# fingerprint equals its OWN, so it resumes against its own stored query and a
	# possibly-accepted first POST is never repeated across a resume boundary. A durable
	# uncertain-create partition is routed to a READ-ONLY reconcile bucket BEFORE the
	# fresh-create fallback.
	$cpCompleted = @($script:CheckpointData.partitions.completed | Where-Object { $null -ne $_ })
	$cpQueryCreated = @($script:CheckpointData.partitions.queryCreated | Where-Object { $null -ne $_ })
	$cpUncertain = @($script:CheckpointData.partitions.uncertainCreate | Where-Object { $null -ne $_ })
	
	foreach ($partition in $AllPartitions) {
		$pIdx = [int]$partition.Index
		$pFp = $null
		if ($partition.PStart -and $partition.PEnd) {
			try {
				$pFp = New-GraphAuditQueryFingerprint -PStart $partition.PStart -PEnd $partition.PEnd -Activities $partition.Activities -RecordTypes $partition.RecordTypes -ServiceFilter $partition.ServiceFilter
			}
			catch { $pFp = $null }
		}
		
		$matchCompleted = @($cpCompleted | Where-Object { Test-PaxCheckpointIdentityMatch $_ $pIdx $pFp })[0]
		if ($matchCompleted) {
			$result.ToSkip += $partition
			continue
		}
		$matchQuery = @($cpQueryCreated | Where-Object { Test-PaxCheckpointIdentityMatch $_ $pIdx $pFp })[0]
		if ($matchQuery) {
			# Add QueryId to partition for fetch-only processing
			$partition | Add-Member -NotePropertyName 'StoredQueryId' -NotePropertyValue $matchQuery.queryId -Force
			$result.ToFetchOnly += $partition
			continue
		}
		$matchUncertain = @($cpUncertain | Where-Object { Test-PaxCheckpointIdentityMatch $_ $pIdx $pFp })[0]
		if ($matchUncertain) {
			# Attach the durable uncertain state so the read-only reconcile path can rebuild
			# the fingerprinted exact name; this partition is NEVER routed to create.
			$partition | Add-Member -NotePropertyName 'UncertainCreateState' -NotePropertyValue $matchUncertain -Force
			$result.ToReconcileOnly += $partition
			continue
		}
		$result.ToCreateAndFetch += $partition
	}
	
	return $result
}

function Test-ShouldPromptTokenRefresh {
	<#
	.SYNOPSIS
		Checks if token refresh handling is needed.
	.DESCRIPTION
		Reactive detection: Returns true only when a 401 Unauthorized error
		has been detected, indicating the token has actually expired.
		No proactive time-based prompts - only triggers on real auth failures.
		
		For AppRegistration mode, this still returns true on 401 so the
		auth handling block can perform automatic silent token refresh.
		For interactive modes, this triggers a user prompt.
	.OUTPUTS
		$true if auth failure detected and refresh handling is needed, $false otherwise.
	#>
	
	# Reactive detection: Return true when 401 error detected (for ALL auth methods)
	# The auth handling block will determine whether to auto-refresh (AppRegistration)
	# or prompt the user (interactive modes)
	return $script:AuthFailureDetected
}

function Invoke-TokenRefreshPrompt {
	<#
	.SYNOPSIS
		Handles token refresh for interactive auth modes (WebLogin/DeviceCode).
	.DESCRIPTION
		Triggered reactively when a 401 Unauthorized error is detected.
		First attempts silent token refresh (SDK may have valid refresh token cached).
		If silent refresh fails, prompts user to re-authenticate or quit.
	.OUTPUTS
		'Refreshed' - Token refreshed successfully (silent or interactive)
		'Quit' - User chose to exit
	#>
	
	$tokenAge = if ($script:TokenAcquiredTime) { (Get-Date) - $script:TokenAcquiredTime } else { $null }
	
	# ═══════════════════════════════════════════════════════════════════════════
	# NOTE: We intentionally do NOT attempt automatic token refresh here.
	# On Windows, Connect-MgGraph with InteractiveBrowserCredential ALWAYS opens
	# a browser popup. If the user is away, this popup sits waiting, and when
	# they return and press 'R' to re-auth, a SECOND popup appears.
	# By going straight to the user prompt, we ensure only ONE popup when ready.
	# ═══════════════════════════════════════════════════════════════════════════
	
	# ═══════════════════════════════════════════════════════════════════════════
	# Prompt user for interactive re-authentication (single popup, user-initiated)
	# ═══════════════════════════════════════════════════════════════════════════
	
	# Get progress info for display
	$completedCount = if ($script:CheckpointData) { $script:CheckpointData.statistics.partitionsComplete } else { 0 }
	$totalCount = if ($script:CheckpointData) { $script:CheckpointData.partitions.total } else { 0 }
	$recordsSaved = if ($script:CheckpointData) { $script:CheckpointData.statistics.totalRecordsSaved } else { 0 }
	
	Write-Host ""
	Write-Host "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
	Write-Host "  [!]  AUTHENTICATION EXPIRED - Re-authentication Required" -ForegroundColor Red
	Write-Host "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
	Write-Host ""
	Write-Host "  Authentication failure detected (401 Unauthorized)." -ForegroundColor White
	Write-Host "  Your session token has expired. Please re-authenticate to continue." -ForegroundColor White
	Write-Host ""
	if ($tokenAge) {
		Write-Host "  Session duration: $([Math]::Round($tokenAge.TotalMinutes, 0)) minutes" -ForegroundColor Gray
	}
	Write-Host "  Progress: $completedCount/$totalCount partitions complete | $($recordsSaved.ToString('N0')) records saved to disk" -ForegroundColor White
	Write-Host "  Auth method: $($Auth) (interactive)" -ForegroundColor Gray
	Write-Host ""
	Write-Host "    [R] Re-authenticate now (recommended)" -ForegroundColor Green
	Write-Host "    [Q] Quit and save progress (resume later with -Resume)" -ForegroundColor Cyan
	Write-Host ""
	Write-Host "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red

	# G-6 noninteractive guard: on a container/ACA Job/CI runner there is nobody at
	# the keyboard to choose R/Q. Auto-choose Q ('quit and save progress'); the
	# operator can resume the checkpoint later from an interactive host. Logging
	# the auto-choice prevents the silent stdin hang the original code would have
	# produced.
	if (script:Test-IsNonInteractive) {
		Write-Host "" -ForegroundColor Yellow
		Write-Host "  Noninteractive host detected: cannot prompt for re-authentication." -ForegroundColor Yellow
		Write-Host "  Auto-selecting [Q] - progress will be saved to the checkpoint." -ForegroundColor Yellow
		Write-Host "  Resume from an interactive host with: -Resume `"$($script:CheckpointPath)`"" -ForegroundColor Yellow
		return 'Quit'
	}

	Send-PromptNotification
	while ($true) {
		$choice = Read-Host "  Enter choice (R/Q)"
		
		switch ($choice.ToUpper()) {
			'R' {
				Write-Host ""
				Write-Host "  Re-authenticating..." -ForegroundColor Cyan
				
				try {
					# Disconnect and reconnect
					script:Invoke-PaxGraphDisconnect -ErrorAction SilentlyContinue
					Connect-PurviewAudit -AuthMethod $Auth -UseEOMMode $false
					
					# Update token timing and reset auth failure flags
					$script:TokenAcquiredTime = Get-Date
					$script:AuthFailureDetected = $false
					$script:Auth401MessageShown = $false  # Reset for next auth failure cycle
					
					Write-Host "  Re-authentication successful. Resuming execution..." -ForegroundColor Green
					Write-Host "  Failed partitions will be retried with fresh token." -ForegroundColor Green
					Write-Host ""
					
					return 'Refreshed'
				}
				catch {
					Write-Host "  ✗ Re-authentication failed: $($_.Exception.Message)" -ForegroundColor Red
					Write-Host "  Please try again or quit." -ForegroundColor Yellow
				}
			}
			'Q' {
				Write-Host ""
				Show-CheckpointExitMessage
				return 'Quit'
			}
			default {
				Write-Host "  Invalid choice. Please enter R or Q." -ForegroundColor Red
			}
		}
	}
}

function Merge-IncrementalSaves {
	<#
	.SYNOPSIS
		Merges incremental JSON save files into the main allLogs collection.
	.DESCRIPTION
		Called at the end of execution to consolidate partition data that was
		saved incrementally during execution. In resume mode, only merges data
		from partitions that were skipped (already completed at start of run),
		since partitions completed during this run already have data in memory.
	.PARAMETER AllLogs
		Reference to the synchronized ArrayList to add records to.
	.PARAMETER OutputDirectory
		The output directory containing the .pax_incremental folder.
	.PARAMETER CleanupAfterMerge
		If true, deletes the incremental files after successful merge.
	.PARAMETER OnlyPartitionIndices
		If specified, only merge files for these partition indices.
		Used in resume mode to avoid double-counting data from partitions
		that completed during this run.
	#>
	param(
		[Parameter(Mandatory = $true)]
		[System.Collections.ArrayList]$AllLogs,
		
		[Parameter(Mandatory = $true)]
		[string]$OutputDirectory,
		
		[Parameter(Mandatory = $false)]
		[bool]$CleanupAfterMerge = $true,
		
		[Parameter(Mandatory = $false)]
		[int[]]$OnlyPartitionIndices = $null
	)
	
	$incrementalDir = Join-Path $OutputDirectory ".pax_incremental"
	
	if (-not (Test-Path $incrementalDir)) {
		return 0
	}
	
	$incrementalFiles = Get-ChildItem -Path $incrementalDir -Filter "*.jsonl" -ErrorAction SilentlyContinue
	
	if (-not $incrementalFiles -or $incrementalFiles.Count -eq 0) {
		return 0
	}
	
	$mergedCount = 0
	$filesProcessed = 0
	$filesSkipped = 0
	
	$filterMsg = if ($OnlyPartitionIndices) { " (filtering for partitions: $($OnlyPartitionIndices -join ', '))" } else { "" }
	Write-LogHost "  [MERGE] Found $($incrementalFiles.Count) incremental save files$filterMsg..." -ForegroundColor Cyan
	
	foreach ($file in $incrementalFiles) {
		try {
			# If filtering by partition indices, check if this file matches
			# Filename format: Part{N}_timestamp_qid-{QueryId}_Nrecords.jsonl (recovery files use qid-recovery)
			if ($OnlyPartitionIndices) {
				$partMatch = [regex]::Match($file.Name, '^Part(\d+)_')
				if ($partMatch.Success) {
					$filePartitionIndex = [int]$partMatch.Groups[1].Value
					if ($filePartitionIndex -notin $OnlyPartitionIndices) {
						$filesSkipped++
						# Don't delete - this file is for a partition completed in this run
						continue
					}
				}
			}
			
			# Read JSON Lines (NDJSON) format - one record per line
			$lines = Get-Content -Path $file.FullName -Encoding utf8
			$fileRecordCount = 0
			
			foreach ($line in $lines) {
				if ([string]::IsNullOrWhiteSpace($line)) { continue }
				
				try {
					$record = $line | ConvertFrom-Json
					[void]$AllLogs.Add($record)
					$fileRecordCount++
				} catch {
					# Skip malformed lines but continue processing
					Write-Verbose "Skipped malformed line in $($file.Name)"
				}
			}
			
			$mergedCount += $fileRecordCount
			if ($fileRecordCount -gt 0) { $filesProcessed++ }
			
			if ($CleanupAfterMerge) {
				Remove-Item -Path $file.FullName -Force -ErrorAction SilentlyContinue
			}
		}
		catch {
			Write-LogHost "  [WARN] Failed to merge $($file.Name): $($_.Exception.Message)" -ForegroundColor Yellow
		}
	}
	
	# Clean up directory if empty
	if ($CleanupAfterMerge) {
		$remainingFiles = Get-ChildItem -Path $incrementalDir -ErrorAction SilentlyContinue
		if (-not $remainingFiles -or $remainingFiles.Count -eq 0) {
			Remove-Item -Path $incrementalDir -Force -ErrorAction SilentlyContinue
		}
	}
	
	if ($mergedCount -gt 0) {
		Write-LogHost "  [MERGE] Merged $($mergedCount.ToString('N0')) records from $filesProcessed incremental files" -ForegroundColor Green
	}
	
	return $mergedCount
}

function Merge-IncrementalSaves-Streaming {
	<#
	.SYNOPSIS
		Memory-efficient streaming merge of incremental JSONL files directly to CSV.
	.DESCRIPTION
		Instead of loading all records into memory, this function streams records
		from incremental JSONL files directly to the final CSV output using batched
		writes and explicit garbage collection between files. This prevents memory
		exhaustion when merging millions of records.
	.PARAMETER OutputFile
		The final CSV file path to write merged data to.
	.PARAMETER OutputDirectory
		The output directory containing the .pax_incremental folder.
	.PARAMETER OnlyPartitionIndices
		If specified, only merge files for these partition indices.
	.PARAMETER Columns
		The column schema to use for CSV output. If not specified, uses default 7-column schema.
	.PARAMETER RunTimestamp
		The script run timestamp used to filter incremental files to only those from the current run.
		Prevents stale files from prior runs being merged into the output.
	.RETURNS
		The total number of records merged.
	#>
	param(
		[Parameter(Mandatory = $true)]
		[string]$OutputFile,
		
		[Parameter(Mandatory = $true)]
		[string]$OutputDirectory,
		
		[Parameter(Mandatory = $false)]
		[int[]]$OnlyPartitionIndices = $null,
		
		[Parameter(Mandatory = $false)]
		[string[]]$Columns = $null,
		
		[Parameter(Mandatory = $false)]
		[System.Collections.Generic.HashSet[string]]$ExcludeRecordIds = $null,
		
		[Parameter(Mandatory = $false)]
		[ref]$ActivityCounts = $null,
		
		[Parameter(Mandatory = $false)]
		[string]$RunTimestamp = $null
	)
	
	$incrementalDir = Join-Path $OutputDirectory ".pax_incremental"
	
	if (-not (Test-Path $incrementalDir)) {
		Write-LogHost "  [MERGE-STREAM] No incremental directory found" -ForegroundColor Yellow
		return 0
	}
	
	# Filter by run timestamp to avoid merging stale files from prior runs
	$jsonlFilter = if ($RunTimestamp) { "*_${RunTimestamp}_*.jsonl" } else { "*.jsonl" }
	$allFiles = Get-ChildItem -Path $incrementalDir -Filter $jsonlFilter -ErrorAction SilentlyContinue
	if (-not $allFiles -or $allFiles.Count -eq 0) {
		Write-LogHost "  [MERGE-STREAM] No incremental files found$(if ($RunTimestamp) { " for run $RunTimestamp" })" -ForegroundColor Yellow
		return 0
	}
	
	# Sort files by partition number for consistent output ordering
	$files = $allFiles | Sort-Object { 
		if ($_.Name -match 'Part(\d+)_') { [int]$Matches[1] } else { 999999 } 
	}
	
	# Filter by partition indices if specified
	if ($OnlyPartitionIndices) {
		$files = $files | Where-Object {
			$partMatch = [regex]::Match($_.Name, '^Part(\d+)_')
			if ($partMatch.Success) {
				[int]$partMatch.Groups[1].Value -in $OnlyPartitionIndices
			} else {
				$false
			}
		}
	}
	
	if (-not $files -or @($files).Count -eq 0) {
		Write-LogHost "  [MERGE-STREAM] No matching incremental files for specified partitions" -ForegroundColor Yellow
		return 0
	}
	
	# When multiple JSONL files exist for the same partition (from retries with different QueryIds),
	# keep only the largest file per partition. This prevents duplicate records from partial first attempts
	# being merged alongside the full retry result.
	$filesByPartition = @{}
	foreach ($f in @($files)) {
		if ($f.Name -match '^Part(\d+)_') {
			$pIdx = [int]$Matches[1]
			if (-not $filesByPartition.ContainsKey($pIdx) -or $f.Length -gt $filesByPartition[$pIdx].Length) {
				$filesByPartition[$pIdx] = $f
			}
		}
	}
	$deduplicatedFiles = @($filesByPartition.Values | Sort-Object { if ($_.Name -match 'Part(\d+)_') { [int]$Matches[1] } else { 999999 } })
	$removedFileCount = @($files).Count - $deduplicatedFiles.Count
	if ($removedFileCount -gt 0) {
		Write-LogHost "  [MERGE-STREAM] Removed $removedFileCount duplicate partition file(s) from prior retry attempts — keeping largest per partition" -ForegroundColor DarkYellow
	}
	$files = $deduplicatedFiles
	
	$fileCount = @($files).Count
	Write-LogHost "  [MERGE-STREAM] Streaming $fileCount incremental files to CSV..." -ForegroundColor Cyan
	
	# Use default 8-column schema if not specified (non-explosion mode)
	# Column names match Purview UI audit export: RecordId, CreationDate, RecordType, Operation, UserId, AuditData, AssociatedAdminUnits, AssociatedAdminUnitsNames
	if (-not $Columns) {
		$Columns = @('RecordId', 'CreationDate', 'RecordType', 'Operation', 'UserId', 'AuditData', 'AssociatedAdminUnits', 'AssociatedAdminUnitsNames')
	}
	
	$totalMerged = 0
	$filesProcessed = 0
	$headerWritten = $false
	$batchSize = 5000
	$startTime = Get-Date
	$lastProgressTime = Get-Date
	
	# Track seen RecordIds for deduplication (seed with any in-memory RecordIds already written to CSV)
	$seenIds = if ($ExcludeRecordIds) { New-Object System.Collections.Generic.HashSet[string] ($ExcludeRecordIds) } else { New-Object System.Collections.Generic.HashSet[string] }
	$duplicatesSkipped = 0
	
	foreach ($file in $files) {
		$filesProcessed++
		$partNum = if ($file.Name -match 'Part(\d+)_') { $Matches[1] } else { "?" }
		
		try {
			# Open CSV writer on first file with data
			if (-not $headerWritten) {
				Open-CsvWriter -Path $OutputFile -Columns $Columns
				$headerWritten = $true
			}
			
			# Stream records from this file in batches
			$batch = New-Object System.Collections.Generic.List[object]
			$fileRecords = 0
			
			# Use StreamReader instead of Get-Content pipeline for ~5-10x faster file reading
			$reader = [System.IO.StreamReader]::new($file.FullName, [System.Text.Encoding]::UTF8)
			while ($null -ne ($line = $reader.ReadLine())) {
				if (-not [string]::IsNullOrWhiteSpace($line)) {
					try {
						$record = $line | ConvertFrom-Json
						
						# Deduplicate by RecordId
						$recordId = $null
						if ($record.Identity) { $recordId = $record.Identity }
						elseif ($record.Id) { $recordId = $record.Id }
						elseif ($record.RecordId) { $recordId = $record.RecordId }
						
						if ($recordId -and $seenIds.Contains($recordId)) {
							$script:StreamingMergeDuplicatesSkipped++
							continue  # Skip duplicate — 'continue' works in while loop (was 'return' in ForEach-Object)
						}
						if ($recordId) { [void]$seenIds.Add($recordId) }
						
						# Client-side date-range trimming for streaming path
						if ($script:TrimStartDateUTC -or $script:TrimEndDateUTC) {
							$recDate = script:Parse-DateSafe $record.CreationDate
							if ($recDate) {
								$recDateUtc = $recDate.ToUniversalTime()
								if ($script:TrimStartDateUTC -and $recDateUtc -lt $script:TrimStartDateUTC) { $script:DateTrimCount++; continue }
								if ($script:TrimEndDateUTC   -and $recDateUtc -ge $script:TrimEndDateUTC)   { $script:DateTrimCount++; continue }
							}
						}
						
						# Parse AuditData for Operation if needed
						$auditData = $record.AuditData
						$parsedAudit = if ($record.PSObject.Properties['_ParsedAuditData']) { 
							$record._ParsedAuditData 
						} else { 
							try { $auditData | ConvertFrom-Json -ErrorAction SilentlyContinue } catch { $null } 
						}
						$opValue = if ($parsedAudit -and $parsedAudit.Operation) { $parsedAudit.Operation } else { $record.Operations }
						
						# Track per-activity counts for Activity Type Breakdown
						if ($ActivityCounts -and $opValue) {
							if (-not $ActivityCounts.Value.ContainsKey($opValue)) { $ActivityCounts.Value[$opValue] = 0 }
							$ActivityCounts.Value[$opValue]++
						}
						
						# Create normalized record matching expected schema (column names match Purview UI export)
						$normalizedRecord = [pscustomobject]@{
							RecordId                  = if ($record.RecordId) { $record.RecordId } elseif ($record.Identity) { $record.Identity } elseif ($record.Id) { $record.Id } elseif ($parsedAudit -and $parsedAudit.Id) { $parsedAudit.Id } else { $null }
							CreationDate              = if ($record.CreationDate) { 
								$dt = script:Parse-DateSafe $record.CreationDate; if ($dt) { $dt.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture) } else { $record.CreationDate }
							} else { '' }
							RecordType                = $record.RecordType
							Operation                 = $opValue
							UserId                    = if ($record.UserId) { $record.UserId } elseif ($record.UserIds) { $record.UserIds } else { '' }
							AuditData                 = $auditData
							AssociatedAdminUnits      = $(try { if ($parsedAudit.AssociatedAdminUnits) { $parsedAudit.AssociatedAdminUnits } elseif ($record.AssociatedAdminUnits) { $record.AssociatedAdminUnits } else { '' } } catch { '' })
							AssociatedAdminUnitsNames = $(try { if ($parsedAudit.AssociatedAdminUnitsNames) { $parsedAudit.AssociatedAdminUnitsNames } elseif ($record.AssociatedAdminUnitsNames) { $record.AssociatedAdminUnitsNames } else { '' } } catch { '' })
						}
						
						$batch.Add($normalizedRecord)
						$fileRecords++
						
						# Write batch when full
						if ($batch.Count -ge $batchSize) {
							Write-CsvRows -Rows $batch -Columns $Columns
							$totalMerged += $batch.Count
							$batch.Clear()
						}
					} catch {
						# Skip malformed lines
						Write-Verbose "Skipped malformed line in $($file.Name): $($_.Exception.Message)"
					}
				}
			}
			# Dispose StreamReader to release file handle
			if ($reader) { $reader.Dispose(); $reader = $null }
			
			# Flush remaining batch for this file
			if ($batch.Count -gt 0) {
				Write-CsvRows -Rows $batch -Columns $Columns
				$totalMerged += $batch.Count
				$batch.Clear()
			}
			
			# Progress reporting every 30 seconds
			$now = Get-Date
			if (($now - $lastProgressTime).TotalSeconds -ge 30) {
				$elapsed = ($now - $startTime).TotalSeconds
				$rate = if ($elapsed -gt 0) { [int]($totalMerged / $elapsed) } else { 0 }
				Write-LogHost "  [MERGE-STREAM] Progress: $filesProcessed/$fileCount files | $($totalMerged.ToString('N0')) records | ~$rate rec/sec" -ForegroundColor DarkCyan
				$lastProgressTime = $now
			}
			
			# Reduced GC frequency from every file to every 5th file for better throughput
			$batch = $null
			if ($filesProcessed % 5 -eq 0) {
				[GC]::Collect()
				[GC]::WaitForPendingFinalizers()
			}
			
		} catch {
			# Ensure StreamReader is disposed on error to release file handle
			if ($reader) { try { $reader.Dispose() } catch {} ; $reader = $null }
			Write-LogHost "  [WARN] Failed to stream merge $($file.Name): $($_.Exception.Message)" -ForegroundColor Yellow
		}
	}
	
	# Close CSV writer
	if ($headerWritten) {
		Close-CsvWriter
	}
	
	# Final stats
	$totalElapsed = (Get-Date) - $startTime
	$finalRate = if ($totalElapsed.TotalSeconds -gt 0) { [int]($totalMerged / $totalElapsed.TotalSeconds) } else { 0 }
	
	Write-LogHost "  [MERGE-STREAM] Streaming merge complete: $($totalMerged.ToString('N0')) records from $filesProcessed files" -ForegroundColor Green
	Write-LogHost "  [MERGE-STREAM]   Time: $([Math]::Round($totalElapsed.TotalSeconds, 1))s | Rate: $finalRate rec/sec" -ForegroundColor DarkGray
	if ($duplicatesSkipped -gt 0 -or $script:StreamingMergeDuplicatesSkipped -gt 0) {
		$totalDupes = $duplicatesSkipped + $script:StreamingMergeDuplicatesSkipped
		Write-LogHost "  [MERGE-STREAM]   Duplicates skipped: $totalDupes" -ForegroundColor DarkGray
	}
	
	# Clear the HashSet to free memory
	$seenIds.Clear()
	$seenIds = $null
	[GC]::Collect()
	
	return $totalMerged
}

function Show-CheckpointExitMessage {
	<#
	.SYNOPSIS
		Displays checkpoint save confirmation and resume instructions.
	#>
	
	if (-not $script:CheckpointData -or -not $script:CheckpointPath) {
		return
	}
	
	$completedCount = if ($script:CheckpointData.statistics.partitionsComplete) { $script:CheckpointData.statistics.partitionsComplete } else { 0 }
	$queryCreatedCount = if ($script:CheckpointData.statistics.partitionsQueryCreated) { $script:CheckpointData.statistics.partitionsQueryCreated } else { 0 }
	$totalCount = if ($script:CheckpointData.partitions.total) { $script:CheckpointData.partitions.total } else { 0 }
	$remaining = $totalCount - $completedCount - $queryCreatedCount
	$recordsSaved = if ($script:CheckpointData.statistics.totalRecordsSaved) { $script:CheckpointData.statistics.totalRecordsSaved } else { 0 }
	
	Write-Host ""
	Write-Host "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Green
	Write-Host "  PROGRESS SAVED" -ForegroundColor Green
	Write-Host "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Green
	Write-Host ""
	# The checkpoint file and the local _PARTIAL file always live on the local
	# scratch path (they are required for -Resume; the checkpoint isn't uploaded
	# until the run completes successfully). Display them as full local paths so
	# the user can copy/paste them into -Resume verbatim.
	#
	# The run log is written to local scratch throughout the run. On successful
	# completion the end-of-run upload sweep pushes it to the remote destination
	# (SP/Fabric); on an interrupted run (Ctrl+C / failure) the upload sweep does
	# NOT fire, so the log lives only at the local scratch path until the next
	# -Resume completes successfully. Always display the literal local path here
	# (consistent with Checkpoint: and Partial data:) so the user can inspect /
	# attach the in-progress log immediately. When a remote destination is bound,
	# print a follow-up "Uploads to:" note so the user knows where the log will
	# land on successful completion.
	Write-Host "  Checkpoint:   $script:CheckpointPath" -ForegroundColor White
	# Live in-progress records stream into <OutputPath>/.pax_incremental/*.jsonl
	# shards as each partition completes. The companion _PARTIAL.csv ($script:PartialOutputPath)
	# is only materialized at end-of-run merge or on successful completion, so it
	# generally does NOT exist on an interrupted Ctrl+C exit. Point the user at
	# the .pax_incremental folder (the actual durable source of partial data); if
	# a _PARTIAL.csv already exists alongside it, list that on a follow-up line.
	$_partialBaseDir = $null
	# Defensive: Split-Path -LiteralPath throws "Parameter set cannot be resolved"
	# when handed $null, an empty string, or a non-string (array / hashtable from a
	# malformed checkpoint outputFiles entry). Coerce to a non-empty string before
	# splitting and swallow any residual parsing failure so the exit banner never
	# crashes after a real upstream error has already been reported.
	$_pop = if ($script:PartialOutputPath) { [string]$script:PartialOutputPath } else { '' }
	if ($_pop -and $_pop.Trim()) {
		try { $_partialBaseDir = Split-Path -LiteralPath $_pop -Parent -ErrorAction Stop } catch { $_partialBaseDir = $null }
	}
	if (-not $_partialBaseDir -and $script:CheckpointPath) {
		$_cpp = [string]$script:CheckpointPath
		if ($_cpp -and $_cpp.Trim()) {
			try { $_partialBaseDir = Split-Path -LiteralPath $_cpp -Parent -ErrorAction Stop } catch { $_partialBaseDir = $null }
		}
	}
	$_incDir = if ($_partialBaseDir) { Join-Path $_partialBaseDir '.pax_incremental' } else { $null }
	if ($_incDir) {
		Write-Host "  Partial data: $_incDir\*.jsonl" -ForegroundColor White
	} else {
		Write-Host "  Partial data: (incremental .jsonl shards under scratch .pax_incremental/)" -ForegroundColor White
	}
	if ($script:PartialOutputPath -and (Test-Path -LiteralPath $script:PartialOutputPath)) {
		Write-Host "                Merged CSV (so far): $script:PartialOutputPath" -ForegroundColor DarkGray
	}
	if ($script:LogFile) {
		Write-Host "  Log file:     $script:LogFile" -ForegroundColor White
		$_logRemoteTarget = $null
		try {
			if ($script:DestTier -and $script:DestTier.ContainsKey('Log') -and $script:DestTier['Log'] -and $script:DestTier['Log'] -ne 'Local') {
				$_logFolder = if ($script:DestParentUrl -and $script:DestParentUrl.ContainsKey('Log') -and $script:DestParentUrl['Log']) {
					$script:DestParentUrl['Log']
				} elseif ($script:DestRaw -and $script:DestRaw.ContainsKey('Log') -and $script:DestRaw['Log']) {
					$script:DestRaw['Log']
				} else { $null }
				if ($_logFolder) {
					$_logLeaf = [System.IO.Path]::GetFileName($script:LogFile)
					$_logRemoteTarget = ($_logFolder.TrimEnd('/','\') + '/' + $_logLeaf)
				}
			}
		} catch {}
		if ($_logRemoteTarget) {
			Write-Host "                (uploads to $_logRemoteTarget on successful completion)" -ForegroundColor DarkGray
		}
	}
	Write-Host "  Records saved: $($recordsSaved.ToString('N0'))" -ForegroundColor White
	# Build the Partitions status line as a single string before emission so the
	# global Write-Host proxy (which mirrors every Write-Host call to the log
	# file as ONE timestamped [INFO] entry regardless of -NoNewline) writes one
	# log line instead of 2-3 fragmented entries. The console output is the same
	# either way — both forms produce an identical
	# "Partitions: X/Y complete[, N queries pending][, M not started]" line —
	# but a multi-call -NoNewline approach produces orphan log lines like
	# ", 1 queries pending" on their own timestamp because -NoNewline only
	# concatenates on the host stream, not in the proxy's Add-Content path.
	$partitionLine = "  Partitions: $completedCount/$totalCount complete"
	if ($queryCreatedCount -gt 0) { $partitionLine += ", $queryCreatedCount queries pending" }
	if ($remaining -gt 0)        { $partitionLine += ", $remaining not started" }
	Write-Host $partitionLine -ForegroundColor White
	Write-Host ""
	Write-Host "  To resume later:" -ForegroundColor Cyan
	# Resume credential hint. -Auth / -TenantId / -ClientId are restored from the
	# checkpoint on -Resume (see the resume restore block), so they are NOT
	# re-supplied on the resume command line. Only AppRegistration needs credential
	# material on every invocation, because the secret / certificate is never
	# persisted to the checkpoint by design — and the hint must reflect the SAME
	# credential kind the operator originally used (client secret vs. certificate
	# thumbprint vs. PFX path), detected from the promoted $script:Client* values.
	# Interactive modes (WebLogin / DeviceCode / Credential / Silent) and
	# ManagedIdentity need nothing beyond -Resume.
	if ($Auth -eq 'AppRegistration') {
		$_resumeCred =
			if    (-not [string]::IsNullOrWhiteSpace([string]$script:ClientCertificateThumbprint)) { "-ClientCertificateThumbprint '<your certificate thumbprint>'" }
			elseif (-not [string]::IsNullOrWhiteSpace([string]$script:ClientCertificatePath))       { "-ClientCertificatePath '<path to your .pfx>' [-ClientCertificatePassword '<pwd-if-required>']" }
			else                                                                                     { "-ClientSecret '<your client secret>'" }
		Write-Host "    -Resume `"$($script:CheckpointPath)`" $_resumeCred" -ForegroundColor White
	} else {
		Write-Host "    -Resume `"$($script:CheckpointPath)`"" -ForegroundColor White
	}
	Write-Host ""
	Write-Host "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Green
}

function Complete-CheckpointRun {
	<#
	.SYNOPSIS
		Finalizes successful run: renames _PARTIAL file, deletes checkpoint.
	.PARAMETER FinalOutputPath
		The final output path (without _PARTIAL).
	#>
	param(
		[Parameter(Mandatory)]
		[string]$FinalOutputPath
	)
	
	# Rename _PARTIAL output (and log) to final names ONLY if the _PARTIAL file still exists.
	# In CSV-split / ExportWorkbook modes the intermediate _PARTIAL.csv may already have
	# been deleted by upstream code paths; in that case skip the rename but STILL proceed
	# with checkpoint deletion below so the checkpoint file is not orphaned.
	if ($script:PartialOutputPath -and (Test-Path $script:PartialOutputPath)) {
		try {
			# Rename _PARTIAL to final
			if (Test-Path $FinalOutputPath) {
				# Final file already exists - add timestamp to avoid overwrite
				$dir = Split-Path $FinalOutputPath -Parent
				$name = [System.IO.Path]::GetFileNameWithoutExtension($FinalOutputPath)
				$ext = [System.IO.Path]::GetExtension($FinalOutputPath)
				$timestamp = Get-Date -Format 'yyyyMMdd_HHmmss'
				$FinalOutputPath = Join-Path $dir "${name}_${timestamp}${ext}"
			}
			
			Move-Item -Path $script:PartialOutputPath -Destination $FinalOutputPath -Force
			
			# Rename log file (remove _PARTIAL suffix)
			$partialLogPath = $script:LogFile
			if ($partialLogPath -and (Test-Path $partialLogPath) -and $partialLogPath -match '_PARTIAL\.log$') {
				$finalLogPath = $partialLogPath -replace '_PARTIAL\.log$', '.log'
				if (Test-Path $finalLogPath) {
					$logDir = Split-Path $finalLogPath -Parent
					$logName = [System.IO.Path]::GetFileNameWithoutExtension($finalLogPath)
					$timestamp = Get-Date -Format 'yyyyMMdd_HHmmss'
					$finalLogPath = Join-Path $logDir "${logName}_${timestamp}.log"
				}
				Move-Item -Path $partialLogPath -Destination $finalLogPath -Force
				$script:LogFile = $finalLogPath
			}
			
			$script:PartialOutputPath = $null
		}
		catch {
			Write-LogHost "  Warning: Could not finalize output file: $($_.Exception.Message)" -ForegroundColor Yellow
		}
	}
	
	# Delete checkpoint (always — caller has determined the run succeeded).
	Remove-Checkpoint
}

function Get-UserLicenseData {
	<#
	.SYNOPSIS
		Fetches user license information from Microsoft Graph API.
	
	.DESCRIPTION
		Queries Graph API for subscribedSkus and builds lookup hashtables for:
		- User license assignments (userId -> list of SKU names)
		- Copilot license detection (userId -> has Copilot license)

		Dynamic Copilot license detection (no hardcoded SKU GUIDs):
		1. From /subscribedSkus, collect every servicePlanId whose servicePlanName matches '*COPILOT*'.
		2. For each user, scan assignedPlans for entries where capabilityStatus == 'Enabled'
		   AND servicePlanId is in the discovered Copilot plan set.
		This honors capability state (admin-disabled service plans are correctly excluded)
		and auto-adapts to any current or future Copilot SKU (M365, EDU, Sales, Finance, GCC, etc.).
		Requires only User.Read.All + Organization.Read.All (no additional permissions).

	.OUTPUTS
		Hashtable with two keys:
		- UserLicenses: @{userId = @('SKU1', 'SKU2')}
		- UserHasCopilot: @{userId = $true/$false}
	#>
	
	Write-LogHost ""
	Write-LogHost "Fetching license data from Microsoft Graph API..." -ForegroundColor Cyan
	
	try {
		# Fetch all subscribed SKUs with assigned user data
		$uri = "https://graph.microsoft.com/v1.0/subscribedSkus"
		$response = Invoke-MgGraphRequest -Method GET -Uri $uri -ErrorAction Stop
		$skus = $response.value
		
		Write-LogHost "  Found $($skus.Count) SKU(s) in tenant" -ForegroundColor Gray

		# Build SKU lookup: skuId -> skuPartNumber
		# Also dynamically discover Copilot service plan IDs by name pattern (no hardcoded GUIDs).
		$skuLookup = @{}
		$copilotPlanIds = New-Object System.Collections.Generic.HashSet[string]

		foreach ($sku in $skus) {
			$skuId = $sku.skuId
			$skuName = $sku.skuPartNumber
			$skuLookup[$skuId] = $skuName
			if ($sku.servicePlans) {
				foreach ($plan in $sku.servicePlans) {
					if ($plan.servicePlanName -and $plan.servicePlanName -like '*COPILOT*' -and $plan.servicePlanId) {
						[void]$copilotPlanIds.Add([string]$plan.servicePlanId)
					}
				}
			}
		}
		Write-LogHost "  Discovered $($copilotPlanIds.Count) Copilot service plan(s) in tenant" -ForegroundColor Gray

		# Build user license hashtables
		$userLicenses = @{}      # userId -> @('SKU1', 'SKU2')
		$userHasCopilot = @{}    # userId -> $true/$false

		# Fetch all users with licenses in batches
		# assignedPlans is required for capability-aware Copilot detection (still under User.Read.All).
		Write-LogHost "  Fetching user license assignments..." -ForegroundColor Gray
		$userUri = "https://graph.microsoft.com/v1.0/users?`$select=id,userPrincipalName,assignedLicenses,assignedPlans&`$top=999"
		$userCount = 0
		$copilotUserCount = 0
		
		do {
			$userResponse = Invoke-MgGraphRequest -Method GET -Uri $userUri -ErrorAction Stop
			$users = $userResponse.value
			
			foreach ($user in $users) {
				$userId = $user.id
				$upn = $user.userPrincipalName

				if (-not $userId -or -not $upn) { continue }

				$userCount++
				$licenses = @()
				$hasCopilot = $false

				# Friendly SKU name list (unchanged): map assignedLicenses[].skuId -> skuPartNumber via $skuLookup
				foreach ($license in $user.assignedLicenses) {
					$skuId = $license.skuId
					$skuName = if ($skuLookup.ContainsKey($skuId)) { $skuLookup[$skuId] } else { $skuId }
					$licenses += $skuName
				}

				# Capability-aware Copilot detection: any assignedPlan that is Enabled AND a Copilot service plan.
				if ($copilotPlanIds.Count -gt 0 -and $user.assignedPlans) {
					foreach ($plan in $user.assignedPlans) {
						if ($plan.capabilityStatus -eq 'Enabled' -and $plan.servicePlanId -and $copilotPlanIds.Contains([string]$plan.servicePlanId)) {
							$hasCopilot = $true
							break
						}
					}
				}

				# Store license data keyed by both ID and UPN for flexible lookup
				if ($licenses.Count -gt 0) {
					$userLicenses[$userId] = $licenses
					$userLicenses[$upn] = $licenses
				}
				
				$userHasCopilot[$userId] = $hasCopilot
				$userHasCopilot[$upn] = $hasCopilot
				
				if ($hasCopilot) {
					$copilotUserCount++
				}
			}
			
			$userUri = $userResponse.'@odata.nextLink'
		} while ($userUri)
		
		Write-LogHost "  Processed $userCount user(s) with license assignments" -ForegroundColor Gray
		Write-LogHost "  Detected $copilotUserCount user(s) with Copilot licenses" -ForegroundColor Green
		Write-LogHost ""
		
		return @{
			UserLicenses = $userLicenses
			UserHasCopilot = $userHasCopilot
		}
	}
	catch {
		Write-LogHost "WARNING: Failed to fetch license data: $($_.Exception.Message)" -ForegroundColor Yellow
		Write-LogHost "         License columns will be empty in export" -ForegroundColor Yellow
		Write-LogHost ""
		
		# Return empty hashtables on failure
		return @{
			UserLicenses = @{}
			UserHasCopilot = @{}
		}
	}
}

function ConvertTo-FlatEntraUsers {
	<#
	.SYNOPSIS
		Flattens Entra user objects into CSV-friendly format.
	
	.DESCRIPTION
		Converts Entra ID user objects with nested properties into flat tabular format.
		Filters out non-user accounts (rooms, resources) based on userType validation.
		Explodes arrays (proxyAddresses, manager) into individual columns.
		
		NOTE: This version excludes the 9 granular Entra license columns from the Graph script.
		License data is added separately via Get-UserLicenseData() in MAC format (assignedLicenses, hasLicense).
	
	.PARAMETER Users
		Array of user objects from Microsoft Graph API (with 35 properties + manager expansion).
	
	.OUTPUTS
		Array of PSCustomObjects with 37 flattened columns (35 user properties + 5 manager columns, no license columns yet).
	#>
	param(
		[Parameter(Mandatory = $true)]
		[array]$Users
	)
	
	$flattenedUsers = @()
	
	foreach ($user in $Users) {
		# Filter: Only include real user accounts (exclude rooms, resources, shared mailboxes)
		# Room and resource mailboxes have specific characteristics:
		# - userType is often null or not "Member"/"Guest"
		# - They typically lack givenName and surname
		# - They often have mail but no userPrincipalName with typical user format
		
		$userTypeValue = $user.userType
		
		# Skip if userType is null/empty (likely a room or resource)
		if ([string]::IsNullOrWhiteSpace($userTypeValue)) {
			continue
		}
		
		# Only include users with userType = "Member" or "Guest"
		# Rooms/resources typically have different userType values or null
		if ($userTypeValue -ne 'Member' -and $userTypeValue -ne 'Guest') {
			continue
		}
		
		# Additional heuristic: Real users typically have either givenName or surname
		# Room mailboxes typically have neither (only displayName)
		# This is not foolproof but combined with userType check, it's quite reliable
		$hasGivenName = -not [string]::IsNullOrWhiteSpace($user.givenName)
		$hasSurname = -not [string]::IsNullOrWhiteSpace($user.surname)
		
		# If user has Member/Guest type but no name components, might be a shared resource
		# Allow through if they have at least givenName OR surname OR if account is enabled
		# (most room mailboxes are enabled but lack name components)
		if (-not $hasGivenName -and -not $hasSurname -and $user.accountEnabled) {
			# Additional check: if they have licenses assigned, likely a real user
			if (-not $user.assignedLicenses -or $user.assignedLicenses.Count -eq 0) {
				# No licenses and no name components - likely a room/resource
				continue
			}
		}
		
		$flatUser = [ordered]@{}
		
		# Core Identity Properties (simple strings)
		$flatUser['userPrincipalName'] = $user.userPrincipalName
		$flatUser['displayName'] = $user.displayName
		$flatUser['id'] = $user.id
		$flatUser['mail'] = $user.mail
		$flatUser['givenName'] = $user.givenName
		$flatUser['surname'] = $user.surname
		
		# Job Properties
		$flatUser['jobTitle'] = $user.jobTitle
		$flatUser['department'] = $user.department
		$flatUser['employeeType'] = $user.employeeType
		$flatUser['employeeId'] = $user.employeeId
		$flatUser['employeeHireDate'] = $user.employeeHireDate
		
		# Location Properties
		$flatUser['officeLocation'] = $user.officeLocation
		$flatUser['city'] = $user.city
		$flatUser['state'] = $user.state
		$flatUser['country'] = $user.country
		$flatUser['postalCode'] = $user.postalCode
		$flatUser['companyName'] = $user.companyName
		
		# Organizational Properties
		$flatUser['employeeOrgData_division'] = if ($user.employeeOrgData) { $user.employeeOrgData.division } else { $null }
		$flatUser['employeeOrgData_costCenter'] = if ($user.employeeOrgData) { $user.employeeOrgData.costCenter } else { $null }
		
		# Status Properties
		$flatUser['accountEnabled'] = $user.accountEnabled
		$flatUser['userType'] = $user.userType
		$flatUser['createdDateTime'] = $user.createdDateTime
		
		# Usage Properties
		$flatUser['usageLocation'] = $user.usageLocation
		$flatUser['preferredLanguage'] = $user.preferredLanguage
		
		# Sync Properties
		$flatUser['onPremisesSyncEnabled'] = $user.onPremisesSyncEnabled
		$flatUser['onPremisesImmutableId'] = $user.onPremisesImmutableId
		$flatUser['externalUserState'] = $user.externalUserState
		
		# Explode proxyAddresses array (Email aliases)
		if ($user.proxyAddresses -and $user.proxyAddresses.Count -gt 0) {
			$primarySMTP = $user.proxyAddresses | Where-Object { $_ -like 'SMTP:*' } | Select-Object -First 1
			$flatUser['proxyAddresses_Primary'] = if ($primarySMTP) { $primarySMTP -replace '^SMTP:', '' } else { $null }
			$flatUser['proxyAddresses_Count'] = $user.proxyAddresses.Count
			$flatUser['proxyAddresses_All'] = ($user.proxyAddresses -join '; ')
		}
		else {
			$flatUser['proxyAddresses_Primary'] = $null
			$flatUser['proxyAddresses_Count'] = 0
			$flatUser['proxyAddresses_All'] = $null
		}
		
		# Handle manager object separately (flatten to individual columns)
		if ($user.manager) {
			$flatUser['manager_id'] = $user.manager.id
			$flatUser['manager_displayName'] = $user.manager.displayName
			$flatUser['manager_userPrincipalName'] = $user.manager.userPrincipalName
			$flatUser['manager_mail'] = $user.manager.mail
			$flatUser['manager_jobTitle'] = $user.manager.jobTitle
		}
		else {
			$flatUser['manager_id'] = $null
			$flatUser['manager_displayName'] = $null
			$flatUser['manager_userPrincipalName'] = $null
			$flatUser['manager_mail'] = $null
			$flatUser['manager_jobTitle'] = $null
		}
		
		# License columns will be added separately by Get-EntraUsersData()
		# using Get-UserLicenseData() to provide MAC-format columns:
		# - assignedLicenses (semicolon-separated SKU names)
		# - hasLicense (Copilot detection boolean)
		
		# =====================================================================
		# Power BI AI-in-One Dashboard 2701 Template Compatibility Columns
		# These alias columns map existing Graph API data to 2701 template column names
		# =====================================================================
		$flatUser['ManagerID'] = $flatUser['manager_id']
		$flatUser['BusinessAreaLabel'] = $flatUser['employeeOrgData_division']
		$flatUser['CountryofEmployment'] = $flatUser['country']
		$flatUser['CompanyCodeLabel'] = $flatUser['companyName']
		$flatUser['CostCentreLabel'] = $flatUser['employeeOrgData_costCenter']
		$flatUser['UserName'] = $flatUser['displayName']
		
		# Viva Insights-specific columns (not available from Microsoft Graph API)
		# These are placeholders for template compatibility - data must come from HR systems
		$flatUser['EffectiveDate'] = $null
		$flatUser['FunctionType'] = $null
		$flatUser['BusinessAreaCode'] = $null
		$flatUser['OrgLevel_3Label'] = $null
		
		# Convert ordered hashtable to PSCustomObject for proper CSV export
		$flattenedUsers += [PSCustomObject]$flatUser
	}
	
	return $flattenedUsers
}

function Get-EntraUsersData {
	<#!
	.SYNOPSIS
		Collects and flattens Entra ID (Azure AD) user directory data and enriches with MAC-format license info.

	.DESCRIPTION
			# New naming: Purview_Audit_CombinedUsageActivity[_EntraUsers]_timestamp.xlsx
			$baseName = "Purview_Audit_CombinedUsageActivity"
			if ($IncludeUserInfo -and -not $UseEOM) { $baseName += "_EntraUsers" }
			$excelDescriptor = if ($IncludeUserInfo -and -not $UseEOM) { 'multi-tab workbook (CombinedActivity + EntraUsers)' } else { 'single-tab workbook' }
			Write-LogHost "Output File: ${outputDir}${baseName}_<timestamp>.xlsx ($excelDescriptor)" -ForegroundColor White
		Filters out non-user principals (rooms/resources) using userType + name heuristics identical to ConvertTo-FlatEntraUsers.
		Flattens users via ConvertTo-FlatEntraUsers, then appends two MAC-aligned columns:
		  • assignedLicenses  (semicolon-separated SKU `skuPartNumber` names)
		  • hasLicense        (Copilot license boolean; renamed from UserHasCopilotLicense)

		License enrichment uses existing Get-UserLicenseData() hashtables (UserLicenses, UserHasCopilot).
		Only called when -IncludeUserInfo is specified (Graph API mode).

	.OUTPUTS
		Array[psobject] of flattened users (30 core columns + 5 manager columns + 2 license columns = 37 total).

	.NOTES
		If Graph API call fails, returns empty array with warning. License enrichment silently skips if lookup missing.
	#>
	param(
		[switch]$Quiet
	)

	$entraUsers = @()
	try {
		if (-not $Quiet) { Write-LogHost "Fetching Entra user directory (35 properties + manager)..." -ForegroundColor Cyan }

		# Properties mirrored from Graph script (excluding license arrays we purposefully omit)
		$entraUserSelect = @(
			'userPrincipalName','displayName','id','mail','givenName','surname','jobTitle','department','employeeType','employeeId','employeeHireDate',
			'officeLocation','city','state','country','postalCode','companyName','accountEnabled','userType','createdDateTime','usageLocation',
			'preferredLanguage','onPremisesSyncEnabled','onPremisesImmutableId','externalUserState','employeeOrgData','proxyAddresses'
		) -join ','

		$baseUri = "https://graph.microsoft.com/v1.0/users?`$select=$entraUserSelect&`$expand=manager&`$top=999"
		$nextLink = $baseUri
		# Generic List accumulator (was $rawUsers = @() with +=). On a mega-tenant
		# (~400K+ users) the array-append pattern is O(n^2) — every += reallocates and
		# copies the whole backing array — which is both slow and memory-heavy. A
		# List[object] with AddRange appends amortized O(1).
		$rawUsers = [System.Collections.Generic.List[object]]::new()
		$loops = 0
		# Scale-aware paging ceiling. With $expand=manager, Graph caps each page far
		# below the requested $top=999 (often ~100 rows/page), so a mega-tenant needs
		# thousands of pages: at the ~100/page floor, 8000 pages covers ~800K users.
		# The old fixed >2000 guard tripped mid-fetch on a ~412K-user tenant. This
		# ceiling still catches a true runaway (e.g. a non-advancing @odata.nextLink).
		$maxPages = 8000
		# Inner try/catch around paging ONLY: on a throttling/network error or the
		# safety-abort throw, keep whatever pages were already collected and fall
		# through to flatten/enrich so a PARTIAL directory is still emitted. The
		# shortfall is flagged so the end-of-run summary and exit code report it
		# instead of masking it behind "Enterprise Export Complete".
		try {
			while ($nextLink) {
				$loops++
				$resp = Invoke-GraphRequest -Uri $nextLink -Method GET -ErrorAction Stop
				if ($resp.value) { $rawUsers.AddRange([object[]]$resp.value) }
				$nextLink = $resp.'@odata.nextLink'
				# Progress heartbeat: large tenants page for several minutes; emit a count
				# every 25 pages so the run is not mistaken for a hang.
				if (-not $Quiet -and ($loops % 25 -eq 0)) {
					Write-LogHost "  ... $($rawUsers.Count) users retrieved so far ($loops pages)" -ForegroundColor DarkGray
				}
				if ($loops -gt $maxPages) { throw "Safety abort: excessive paging (>$maxPages pages)" }
			}
		}
		catch {
			$script:EntraUsersFetchFailed = $true
			$script:EntraUsersFetchError = $_.Exception.Message
			Write-LogHost "WARNING: Entra user directory paging did not complete: $($_.Exception.Message)" -ForegroundColor Yellow
		}

		# If paging collected nothing there is no directory to emit: flag (if not
		# already) and return empty so the writers skip and the summary/exit report it.
		if ($rawUsers.Count -eq 0) {
			if (-not $script:EntraUsersFetchFailed) {
				$script:EntraUsersFetchFailed = $true
				$script:EntraUsersFetchError = 'Graph returned no users for the directory query.'
			}
			return $entraUsers
		}
		# Partial directory: some pages succeeded before a paging failure. Emit what we
		# have (schema-complete via the flatten/enrich below) but mark it partial.
		if ($script:EntraUsersFetchFailed) {
			$script:EntraUsersPartial = $true
			if (-not $Quiet) { Write-LogHost "         Emitting PARTIAL directory: $($rawUsers.Count) users collected before the failure." -ForegroundColor Yellow }
		}

		if (-not $Quiet) { Write-LogHost "  Retrieved $($rawUsers.Count) raw user objects" -ForegroundColor Gray }
		$flattened = ConvertTo-FlatEntraUsers -Users $rawUsers
		if (-not $Quiet) { Write-LogHost "  Flattened to $($flattened.Count) user rows (filtered)" -ForegroundColor Gray }

		# License enrichment (MAC-format columns)
		$licenseData = $script:LicenseData
		foreach ($u in $flattened) {
			$upn = $u.userPrincipalName
			$assignedNames = $null
			$hasCopilot = $false
			if ($licenseData) {
				# lookup by UPN then id for flexibility
				if ($licenseData.UserLicenses.ContainsKey($upn)) {
					$assignedNames = ($licenseData.UserLicenses[$upn] -join ';')
				} elseif ($licenseData.UserLicenses.ContainsKey($u.id)) {
					$assignedNames = ($licenseData.UserLicenses[$u.id] -join ';')
				}
				if ($licenseData.UserHasCopilot.ContainsKey($upn)) {
					$hasCopilot = [bool]$licenseData.UserHasCopilot[$upn]
				} elseif ($licenseData.UserHasCopilot.ContainsKey($u.id)) {
					$hasCopilot = [bool]$licenseData.UserHasCopilot[$u.id]
				}
			}
			Add-Member -InputObject $u -NotePropertyName 'assignedLicenses' -NotePropertyValue $assignedNames -Force
			Add-Member -InputObject $u -NotePropertyName 'hasLicense' -NotePropertyValue $hasCopilot -Force
		}
		$entraUsers = $flattened
		# Validate schema (non-fatal)
		try { Test-EntraUsersSchema -Users $entraUsers -Quiet:$Quiet } catch { }
	}
	catch {
		# Flatten/enrich (or any non-paging) failure. Flag it so the summary + exit
		# code report the shortfall; preserve an inner paging-error reason if one was
		# already captured.
		$script:EntraUsersFetchFailed = $true
		if (-not $script:EntraUsersFetchError) { $script:EntraUsersFetchError = $_.Exception.Message }
		Write-LogHost "WARNING: Failed to collect Entra user directory: $($_.Exception.Message)" -ForegroundColor Yellow
	}
	return $entraUsers
}

# ==============================================
# GRAPH API QUERY FUNCTIONS
# ==============================================
# REST-based audit log query functions for Microsoft Graph Security API

function Test-Is429 {
	<#
	.SYNOPSIS
		Safely detects 429 (Too Many Requests) throttling errors.
	
	.DESCRIPTION
		Provides null-safe detection of 429 throttling responses from Graph API.
		Handles PowerShell 7+ variations where .Response property may be null.
		
		Three-layer fallback strategy:
		1. Check .Response.StatusCode (when Response object exists)
		2. Check .Exception.Response.StatusCode directly (PS7+ pattern)
		3. Parse error message for '429' string (final fallback)
	
	.PARAMETER Exception
		The caught exception object from try/catch block
	
	.OUTPUTS
		$true if 429 throttling detected, $false otherwise
	
	.EXAMPLE
		try {
			Invoke-RestMethod -Uri $uri -Headers $headers
		}
		catch {
			if (Test-Is429 -Exception $_) {
				Start-Sleep -Seconds 60
			}
		}
	#>
	
	param(
		[Parameter(Mandatory = $true)]
		[System.Management.Automation.ErrorRecord]$Exception
	)
	
	# Layer 1: Check .Response.StatusCode (traditional method)
	if ($Exception.Exception.Response -and $Exception.Exception.Response.StatusCode) {
		if ($Exception.Exception.Response.StatusCode -eq 429 -or $Exception.Exception.Response.StatusCode -eq 'TooManyRequests') {
			return $true
		}
	}
	
	# Layer 2: Check .Exception.Response.StatusCode directly (PS7+ sometimes skips wrapper)
	if ($Exception.Exception.Response.StatusCode) {
		if ($Exception.Exception.Response.StatusCode.value__ -eq 429) {
			return $true
		}
	}
	
	# Layer 3: Parse error message as final fallback
	$errorMessage = $Exception.Exception.Message
	if ($errorMessage -match '429' -or $errorMessage -match 'Too Many Requests' -or $errorMessage -match 'TooManyRequests') {
		return $true
	}
	
	return $false
}

function Invoke-GraphAuditQuery {
	<#
	.SYNOPSIS
		Creates a new audit log query in Microsoft Graph Security API.
	
	.DESCRIPTION
		Submits an audit log query request to Microsoft Graph Security API.
		Returns a query ID that can be used to poll for status and retrieve results.
		
		The Graph API uses an asynchronous query model:
		1. Submit query (this function) - returns queryId
		2. Poll query status - wait for "succeeded" state
		3. Retrieve records - paginated results
	
	.PARAMETER DisplayName
		Friendly name for the query (for tracking purposes)
	
	.PARAMETER StartDate
		Start date/time for audit log query (ISO 8601 format)

	.PARAMETER EndDate
		End date/time for audit log query (ISO 8601 format)

	.PARAMETER Operations
		Array of operation types to query (e.g., 'CopilotInteraction')

	.PARAMETER RecordTypes
		Optional record type filters to include in the Graph query body (passthrough).

	.PARAMETER ServiceTypes
		Optional service/workload filters to include in the Graph query body (passthrough).
	
	.OUTPUTS
		Query ID string if successful, $null if failed
	#>
	
	param(
		[Parameter(Mandatory = $true)]
		[string]$DisplayName,
	
		[Parameter(Mandatory = $true)]
		[Alias('FilterStartDateTime')]
		[datetime]$StartDate,
	
		[Parameter(Mandatory = $true)]
		[Alias('FilterEndDateTime')]
		[datetime]$EndDate,
	
		[Parameter(Mandatory = $false)]
		[Alias('OperationFilters')]
		[string[]]$Operations,
	
		[Parameter(Mandatory = $false)]
		[Alias('RecordTypeFilters')]
		[string[]]$RecordTypes,
	
		[Parameter(Mandatory = $false)]
		[Alias('ServiceFilter')]
		[string[]]$ServiceTypes
	)
	
	try {
		# Format dates to ISO 8601 format required by Graph API
		$startDateStr = $StartDate.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture)
		$endDateStr = $EndDate.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture)
		
		# Build request body
		$body = @{
			displayName = $DisplayName
			filterStartDateTime = $startDateStr
			filterEndDateTime = $endDateStr
		}

		# Fail-safe sanitizer: If operations include M365 usage ops, drop record/service filters
		try {
			$usageOps = $script:m365UsageActivityBundle
			if (-not $usageOps) { $usageOps = $m365UsageActivityBundle }
			$hasUsageOps = $false
			if ($Operations -and $usageOps) {
				$opsLower = @($Operations | ForEach-Object { $_.ToLowerInvariant() })
				$usageLower = @($usageOps | ForEach-Object { $_.ToLowerInvariant() })
				$hasUsageOps = ($opsLower | Where-Object { $usageLower -contains $_ }) | Select-Object -First 1
			}
			if ($hasUsageOps) {
				$RecordTypes = $null
				$ServiceTypes = $null
			}
		} catch { }
		
		# Add operation filters if specified
		if ($Operations -and $Operations.Count -gt 0) {
			$body.operationFilters = @($Operations)
		}

		# Add optional record/service filters (passthrough from caller)
		if ($RecordTypes -and $RecordTypes.Count -gt 0) {
			$body.recordTypeFilters = @($RecordTypes)
		}

		if ($ServiceTypes -and $ServiceTypes.Count -gt 0) {
			$body.serviceFilter = $ServiceTypes[0]
		}
		
		# Log query details for troubleshooting (persisted to run log)
		Write-LogHost "[INFO] Graph API Query Body:" -ForegroundColor Magenta
		if ($Operations -and $Operations.Count -gt 0) {
			Write-LogHost "  operationFilters: $($Operations -join ', ')" -ForegroundColor DarkGray
		}
		if ($RecordTypes -and $RecordTypes.Count -gt 0) {
			Write-LogHost "  recordTypeFilters: $($RecordTypes -join ', ')" -ForegroundColor DarkGray
		}
		if ($ServiceTypes -and $ServiceTypes.Count -gt 0) {
			Write-LogHost "  serviceFilter: $($ServiceTypes[0])" -ForegroundColor DarkGray
		}
		$bodyJson = $body | ConvertTo-Json -Depth 10
		Write-LogHost $bodyJson -ForegroundColor DarkGray
		
		# Submit query via Graph API through the duplicate-safe decision layer.
		# A fully-paginated exact-name lookup runs BEFORE any POST: an existing
		# identically-named query is adopted (no duplicate), multiple exact matches
		# fail closed (no POST), otherwise a single beta creation proceeds under the
		# ambiguous-POST guard. Version pinning is honoured by the decision layer.
		$__createState = New-GraphAuditLifecycleState
		$__listQueries = {
			$__items = New-Object System.Collections.Generic.List[object]
			$__lu = Get-GraphAuditApiUri -Path 'queries'
			while ($__lu) {
				$__page = Invoke-MgGraphRequest -Method GET -Uri $__lu -ErrorAction Stop
				if ($__page -and $__page.value) {
					foreach ($__q in $__page.value) {
						$__items.Add(@{ id = $__q.id; displayName = $__q.displayName })
					}
				}
				$__lu = $null
				if ($__page) { $__lu = $__page.'@odata.nextLink' }
			}
			return $__items.ToArray()
		}
		$__createQuery = {
			param($Version, $Name)
			try {
				$__cu = "https://graph.microsoft.com/$Version/security/auditLog/queries"
				$__resp = Invoke-MgGraphRequest -Method POST -Uri $__cu -Body $body -ErrorAction Stop
				$__id = $null
				if ($__resp) { $__id = $__resp.id }
				return @{ HttpStatus = 201; QueryId = $__id; Ambiguous = $false }
			}
			catch {
				$__sc = $null
				if ($_.Exception.Response) {
					try { $__sc = [int]$_.Exception.Response.StatusCode.value__ } catch {}
					if ($null -eq $__sc) { try { $__sc = [int]$_.Exception.Response.StatusCode } catch {} }
				}
				Write-LogHost "ERROR: Failed to submit Graph audit query: $($_.Exception.Message)" -ForegroundColor Red
				return @{ HttpStatus = $__sc; QueryId = $null; Ambiguous = ($__sc -eq 409) }
			}
		}
		$__resolve = Resolve-GraphAuditDuplicateSafeQuery -DisplayName $DisplayName -State $__createState -ListQueries $__listQueries -CreateQuery $__createQuery
		if ($__resolve -and $__resolve.QueryId) {
			return $__resolve.QueryId
		}
		else {
			Write-LogHost "WARNING: Graph API query not created (Action=$($__resolve.Action); Reason=$($__resolve.Reason))" -ForegroundColor Yellow
			return $null
		}
	}
	catch {
		Write-LogHost "ERROR: Failed to submit Graph audit query: $($_.Exception.Message)" -ForegroundColor Red
		try {
			if ($_.Exception.Response) {
				$respStream = $_.Exception.Response.GetResponseStream()
				if ($respStream) {
					$reader = New-Object System.IO.StreamReader($respStream)
					$body = $reader.ReadToEnd()
					$reader.Dispose()
					if ($body) { Write-LogHost "GRAPH response body: $body" -ForegroundColor DarkGray }
				}
			}
		} catch {}
		return $null
	}
}

function Get-GraphAuditQueryStatus {
	<#
	.SYNOPSIS
		Checks the status of a Graph API audit log query.
	
	.DESCRIPTION
		Polls the Microsoft Graph Security API to check query execution status.
		
		Possible status values:
		- notStarted: Query submitted but not yet processing
		- queued: Query waiting in backend queue for available execution slot
		- running: Query is executing
		- succeeded: Query completed successfully, records ready
		- failed: Query failed
		- cancelled: Query was cancelled
	
	.PARAMETER QueryId
		The query ID returned by Invoke-GraphAuditQuery
	
	.OUTPUTS
		Hashtable with status information: @{ Status='succeeded'; RecordCount=1234 }
		Returns $null if query check fails
	#>
	
	param(
		[Parameter(Mandatory = $true)]
		[string]$QueryId
	)
	
	try {
		# Route the status GET through the shared decision layer so a transient 404 gets a
		# bounded same-id eventual-consistency retry and then a same-id GET on the alternate
		# version (read-only; never a POST) before status is judged unavailable. Status and
		# records are decided independently.
		$__lcState = New-GraphAuditLifecycleState
		$__statusInvoke = {
			param($Version, $Qid, $Op)
			try {
				$u = "https://graph.microsoft.com/$Version/security/auditLog/queries/$Qid"
				$resp = Invoke-MgGraphRequest -Method GET -Uri $u -ErrorAction Stop
				return @{ HttpStatus = 200; Data = $resp; ExceptionType = $null }
			}
			catch {
				$sc = $null
				if ($_.Exception.Response) {
					try { $sc = [int]$_.Exception.Response.StatusCode.value__ } catch {}
					if ($null -eq $sc) { try { $sc = [int]$_.Exception.Response.StatusCode } catch {} }
				}
				if ($null -eq $sc -and ($_.Exception.Message -match '404|Not Found')) { $sc = 404 }
				return @{ HttpStatus = $sc; Data = $null; ExceptionType = $_.Exception.GetType().Name }
			}
		}
		$__lc = Invoke-GraphAuditLifecycleOperation -Operation 'Status' -QueryId $QueryId -Invoke $__statusInvoke -State $__lcState
		if (-not $__lc.Success) {
			Write-LogHost "ERROR: Failed to get Graph query status (category $($__lc.Category), HTTP $($__lc.HttpStatus))" -ForegroundColor Red
			return $null
		}
		$response = $__lc.Data
		
		$result = @{
			QueryId = $QueryId
			Status = $response.status
			RecordCount = 0
		}
		
		# Some status responses include record count
		if ($response.PSObject.Properties.Name -contains 'recordCount') {
			$result.RecordCount = $response.recordCount
		}
		
		return $result
	}
	catch {
		Write-LogHost "ERROR: Failed to get Graph query status: $($_.Exception.Message)" -ForegroundColor Red
		return $null
	}
}

function Get-GraphAuditRecords {
	<#
	.SYNOPSIS
		Retrieves audit log records from a completed Graph API query.
	
	.DESCRIPTION
		Fetches audit log records from Microsoft Graph Security API for a completed query.
		Handles pagination automatically using @odata.nextLink.
		
		Only call this function after confirming query status is "succeeded".
	
	.PARAMETER QueryId
		The query ID returned by Invoke-GraphAuditQuery
	
	.PARAMETER MaxRecords
		Maximum number of records to retrieve (default: unlimited)
	
	.OUTPUTS
		Array of audit log record objects, or empty array if none found
	#>
	
	param(
		[Parameter(Mandatory = $true)]
		[string]$QueryId,
		
		[Parameter(Mandatory = $false)]
		[int]$MaxRecords = 0
	)
	
	try {
		$allRecords = @()
		# Route the first records GET through the shared decision layer (independent of the
		# status decision): a transient 404 gets a bounded same-id retry then a same-id GET on
		# the alternate version (read-only; never a POST). A successful ZERO-record page is a
		# complete result, never a failure. Remaining pages follow @odata.nextLink verbatim on
		# whichever version served the first page (no $top / cap / truncation added).
		$__recState = New-GraphAuditLifecycleState
		$__recInvoke = {
			param($Version, $Qid, $Op)
			try {
				$u = "https://graph.microsoft.com/$Version/security/auditLog/queries/$Qid/records"
				$resp = Invoke-MgGraphRequest -Method GET -Uri $u -ErrorAction Stop
				return @{ HttpStatus = 200; Data = $resp; ExceptionType = $null }
			}
			catch {
				$sc = $null
				if ($_.Exception.Response) {
					try { $sc = [int]$_.Exception.Response.StatusCode.value__ } catch {}
					if ($null -eq $sc) { try { $sc = [int]$_.Exception.Response.StatusCode } catch {} }
				}
				if ($null -eq $sc -and ($_.Exception.Message -match '404|Not Found')) { $sc = 404 }
				return @{ HttpStatus = $sc; Data = $null; ExceptionType = $_.Exception.GetType().Name }
			}
		}
		$__lc = Invoke-GraphAuditLifecycleOperation -Operation 'Records' -QueryId $QueryId -Invoke $__recInvoke -State $__recState
		if (-not $__lc.Success) {
			Write-LogHost "ERROR: Failed to retrieve Graph audit records (category $($__lc.Category), HTTP $($__lc.HttpStatus))" -ForegroundColor Red
			return @()
		}
		$response = $__lc.Data
		if ($response -and $response.value) {
			$allRecords += $response.value
			if ($MaxRecords -gt 0 -and $allRecords.Count -ge $MaxRecords) {
				return ($allRecords | Select-Object -First $MaxRecords)
			}
		}
		$uri = $response.'@odata.nextLink'
		
		while ($uri) {
			$response = Invoke-MgGraphRequest -Method GET -Uri $uri -ErrorAction Stop
			
			if ($response -and $response.value) {
				$allRecords += $response.value
				
				# Check if we've hit the max records limit
				if ($MaxRecords -gt 0 -and $allRecords.Count -ge $MaxRecords) {
					$allRecords = $allRecords | Select-Object -First $MaxRecords
					break
				}
			}
			
			# Check for pagination
			$uri = $response.'@odata.nextLink'
		}
		
		return $allRecords
	}
	catch {
		Write-LogHost "ERROR: Failed to retrieve Graph audit records: $($_.Exception.Message)" -ForegroundColor Red
		return @()
	}
}

# ==============================================
# DATA NORMALIZATION FUNCTION
# ==============================================
# Converts Graph API audit records to EOM-compatible schema

function ConvertFrom-GraphAuditRecord {
	<#
	.SYNOPSIS
		Normalizes Graph API audit records to match EOM cmdlet output schema.
	
	.DESCRIPTION
		Transforms Microsoft Graph Security API audit log records into the same
		structure as Search-UnifiedAuditLog cmdlet output. This ensures the
		existing explosion logic works identically regardless of data source.
		
		Graph API Schema → EOM Schema Mapping:
		- auditLogRecordType → RecordType
		- operation → Operations  
		- createdDateTime → CreationDate
		- auditData → AuditData (JSON string)
		- userPrincipalName → UserIds
		- id → Identity (unique record identifier)
	
	.PARAMETER GraphRecords
		Array of audit log records from Graph API (Get-GraphAuditRecords output)
	
	.OUTPUTS
		Array of normalized records matching EOM schema structure
	#>
	
	param(
		[Parameter(Mandatory = $true)]
		[AllowEmptyCollection()]
		[array]$GraphRecords
	)
	
	if (-not $GraphRecords -or $GraphRecords.Count -eq 0) {
		return @()
	}
	
	$normalized = @()
	
	foreach ($record in $GraphRecords) {
		try {
			# Create EOM-compatible object structure
			$eomRecord = [PSCustomObject]@{
				RecordType   = $null
				CreationDate = $null
				UserIds      = $null
				Operations   = $null
				AuditData    = '{}'
			}
			# Map: auditLogRecordType → RecordType
			if ($record.PSObject.Properties.Name -contains 'auditLogRecordType') {
				$eomRecord.RecordType = $record.auditLogRecordType
			}
			
			# Map: createdDateTime → CreationDate
			if ($record.PSObject.Properties.Name -contains 'createdDateTime') {
				try {
					$eomRecord.CreationDate = script:Parse-DateSafe $record.createdDateTime
				}
				catch {
					$eomRecord.CreationDate = $record.createdDateTime
				}
			}
			
			# Map: userPrincipalName → UserIds
			if ($record.PSObject.Properties.Name -contains 'userPrincipalName') {
				$eomRecord.UserIds = $record.userPrincipalName
			}
			
			# Map: operation → Operations
			if ($record.PSObject.Properties.Name -contains 'operation') {
				$eomRecord.Operations = $record.operation
			}
			
			# Map: id → Identity (unique identifier)
			if ($record.PSObject.Properties.Name -contains 'id') {
				$eomRecord.Identity = $record.id
			}
			
			# Map: auditData → AuditData (must be JSON string for explosion logic)
			# PERF: Also store _ParsedAuditData to avoid re-parsing during explosion
			if ($record.PSObject.Properties.Name -contains 'auditData') {
				$auditDataObj = $record.auditData
				
				# Store the already-parsed object for explosion optimization
				$eomRecord | Add-Member -NotePropertyName '_ParsedAuditData' -NotePropertyValue $auditDataObj -Force
				
				# If auditData is already an object, convert to JSON string
				if ($auditDataObj -is [string]) {
					$eomRecord.AuditData = $auditDataObj
					# String means it wasn't pre-parsed, clear _ParsedAuditData
					$eomRecord._ParsedAuditData = $null
				}
				else {
					# Convert object to JSON string (explosion logic expects string)
					try {
						$eomRecord.AuditData = ($auditDataObj | ConvertTo-Json -Depth 100 -Compress)
					}
					catch {
						Write-LogHost "WARNING: Failed to serialize auditData for record $($eomRecord.Identity)" -ForegroundColor Yellow
						$eomRecord.AuditData = '{}'
						$eomRecord._ParsedAuditData = $null
					}
				}
			}
			else {
				# No auditData present - create minimal valid JSON
				$eomRecord.AuditData = '{}'
			}
			
			$normalized += $eomRecord
		}
		catch {
			Write-LogHost "WARNING: Failed to normalize Graph record: $($_.Exception.Message)" -ForegroundColor Yellow
			# Continue processing remaining records
		}
	}
	
	return $normalized
}

# =============================================================================
# MICROSOFT AGENT 365 ENRICHMENT FUNCTIONS
# =============================================================================
# Self-contained section. All functions are no-ops unless -IncludeAgent365Info
# or -OnlyAgent365Info is set. Reuses existing Graph SDK plumbing
# (Invoke-MgGraphRequest, Connect-MgGraph, token-refresh helpers, retry helpers).
# Output schema must exactly match temp/Synthetic_Agent365_May2026.csv (28 cols).
# Empty cells are intentional when the API does not return a value (no fabrication).
# Reference: https://learn.microsoft.com/en-us/microsoft-agent-365/admin/graph-api
# =============================================================================

# Module-scope caches populated during the Agent 365 phase.
$script:Agent365FrontierAvailable = $null   # $true / $false / $null = untested
$script:Agent365DeveloperCache    = @{}     # appId/displayName -> resolved name
$script:Agent365AuditEnrichment   = @{}     # titleId/appId      -> @{ Created=...; CreatedBy=... }
$script:Agent365InteractiveCtx    = $false  # set $true after secondary interactive sign-in (AppReg path)
$script:Agent365PreAuthCompleted  = $false  # set $true after eager up-front Agent 365 sign-in (AppReg + Agent365 combo)

function Get-Agent365PackagesUri {
	param([Parameter(Mandatory = $false)][string]$PackageId = '')
	# Microsoft Agent 365 / Copilot package management API is currently published at /beta only.
	# When/if the endpoint is also published at /v1.0, switch this constant.
	$base = 'https://graph.microsoft.com/beta/copilot/admin/catalog/packages'
	if ([string]::IsNullOrWhiteSpace($PackageId)) { return $base }
	return ($base + '/' + [System.Uri]::EscapeDataString($PackageId))
}

function Connect-Agent365InteractiveContext {
	<#
	.SYNOPSIS
		Establishes the Microsoft Graph context for the Agent 365 phase.

		Delegated auth modes (WebLogin / DeviceCode / Credential / Silent) already carry the
		Agent 365 scopes consented at their initial interactive sign-in, so this is a no-op
		for them (early return $true).

		App-only auth modes (AppRegistration certificate, AppRegistration client secret,
		ManagedIdentity) reuse the EXISTING application Graph context. The app-only token must
		already carry the APPLICATION app-role CopilotPackages.Read.All (plus Application.Read.All
		for developer-name resolution via /applications), granted and admin-consented on the app
		registration / managed-identity service principal. NO interactive sign-in and NO
		Connect-MgGraph -Scopes call is performed - the catalog GET runs directly on the active
		app-only context. Idempotent: safe to call multiple times.
	#>
	# Delegated modes: their initial sign-in already consented the Agent 365 scopes.
	if ($Auth -ne 'AppRegistration' -and $Auth -ne 'ManagedIdentity') { return $true }

	# App-only modes: surface an APP-ONLY Phase 2 banner (no delegated user, no prompt) so the
	# log is honest about the auth surface, then reuse the existing application context as-is.
	$appOnlyLabel = if ($Auth -eq 'ManagedIdentity') { 'managed identity service principal' } else { 'app registration service principal' }
	Write-LogHost ""
	Write-LogHost "=== Phase 2: Agent 365 - APP-ONLY context (no interactive sign-in) ===" -ForegroundColor Cyan
	Write-LogHost ("  Reusing the existing app-only Graph context ({0})." -f $appOnlyLabel) -ForegroundColor Gray
	Write-LogHost "  Required APPLICATION permissions (granted + admin-consented on the SP):" -ForegroundColor White
	Write-LogHost "    [App-only] CopilotPackages.Read.All   (read /copilot/admin/catalog/packages)" -ForegroundColor Yellow
	Write-LogHost "    [App-only] Application.Read.All        (resolve developer/owner via /applications)" -ForegroundColor Yellow
	Write-LogHost "  Note: the catalog API is published at /beta only; the tenant must hold a" -ForegroundColor Gray
	Write-LogHost "        Microsoft Agent 365 license / program enrollment." -ForegroundColor Gray
	Write-LogHost ""
	return $true
}


function Invoke-Agent365EarlyInteractiveSignIn {
	<#
	.SYNOPSIS
		No-op retained for call-site stability.

	.DESCRIPTION
		The Agent Package Management API is read with
		the APPLICATION app-role CopilotPackages.Read.All (+ Application.Read.All) on the app /
		managed-identity service principal, so NO interactive sign-in is required in ANY auth mode:
		  - app-only modes (AppRegistration cert/secret, ManagedIdentity) reuse the existing
		    application context (see Connect-Agent365InteractiveContext);
		  - delegated modes (WebLogin / DeviceCode / Credential / Silent) already consented the
		    Agent 365 scopes at their initial sign-in.
		This function is a no-op.

	.OUTPUTS
		$true always (no early sign-in is ever needed).
	#>
	return $true
}

function Test-Agent365FrontierAccess {
	<#
	.SYNOPSIS
		Probes the Agent Package Management API with a minimal GET to confirm
		tenant enrollment in the Frontier program and adequate caller role.
	.OUTPUTS
		$true  - access confirmed; agent phase may proceed
		$false - access denied (403/404 or unsupported); banner 7d printed; phase skipped
	#>
	if ($null -ne $script:Agent365FrontierAvailable) { return $script:Agent365FrontierAvailable }

	$uri = (Get-Agent365PackagesUri) + '?$top=1'
	try {
		$null = Invoke-MgGraphRequest -Method GET -Uri $uri -ErrorAction Stop
		$script:Agent365FrontierAvailable = $true
		return $true
	} catch {
		$status = $null
		try { if ($_.Exception.Response) { $status = [int]$_.Exception.Response.StatusCode } } catch {}
		if ($status -in @(401,403,404)) {
			# Message branches by auth surface: an app-only 403 means the APP/MI service
			# principal lacks the app-role (or the tenant is unlicensed/not-enrolled), NOT that
			# a signed-in user needs a directory role. Delegated text is kept byte-identical.
			$isAppOnlyMode = ($Auth -eq 'AppRegistration' -or $Auth -eq 'ManagedIdentity')
			Write-LogHost "" 
			Write-LogHost "+----------------------------------------------------------------------+" -ForegroundColor Yellow
			Write-LogHost "|  Microsoft Agent 365 - catalog unavailable for this tenant           |" -ForegroundColor Yellow
			Write-LogHost "+----------------------------------------------------------------------+" -ForegroundColor Yellow
			Write-LogHost ("|  The Agent Package Management API returned HTTP {0,-3}, indicating     |" -f $status) -ForegroundColor Yellow
			if ($isAppOnlyMode) {
				Write-LogHost "|  this tenant is not enrolled in the Microsoft Agent 365 program (or  |" -ForegroundColor Yellow
				Write-LogHost "|  lacks a Microsoft Agent 365 license), OR the app registration /     |" -ForegroundColor Yellow
				Write-LogHost "|  managed-identity service principal has NOT been granted the         |" -ForegroundColor Yellow
				Write-LogHost "|  CopilotPackages.Read.All APPLICATION permission (admin-consented).  |" -ForegroundColor Yellow
				Write-LogHost "|  App-only auth needs the app-role, not a user directory role. The    |" -ForegroundColor Yellow
				Write-LogHost "|  Agent 365 CSV will be skipped for this run.                         |" -ForegroundColor Yellow
			} else {
				Write-LogHost "|  this tenant is not enrolled in the Microsoft Agent 365 program (or  |" -ForegroundColor Yellow
				Write-LogHost "|  lacks a Microsoft Agent 365 license), or the signed-in user lacks   |" -ForegroundColor Yellow
				Write-LogHost "|  the AI Administrator / Global Administrator role. The Agent 365 CSV |" -ForegroundColor Yellow
				Write-LogHost "|  will be skipped for this run.                                       |" -ForegroundColor Yellow
			}
			Write-LogHost "|                                                                      |" -ForegroundColor Yellow
			Write-LogHost "|  Reference:                                                          |" -ForegroundColor Yellow
			Write-LogHost "|  https://learn.microsoft.com/en-us/microsoft-agent-365/admin/graph-api|" -ForegroundColor Yellow
			Write-LogHost "+----------------------------------------------------------------------+" -ForegroundColor Yellow
			Write-LogHost ""
		} else {
			Write-LogHost ("  Agent 365 probe failed (HTTP {0}): {1}" -f ($status, $_.Exception.Message)) -ForegroundColor Red
		}
		$script:Agent365FrontierAvailable = $false
		return $false
	}
}

function Get-Agent365Packages {
	<#
	.SYNOPSIS
		Returns the Agent 365 catalog packages (list view) together with an explicit
		completeness verdict.
	.DESCRIPTION
		The walk follows every @odata.nextLink the service supplies and ends only when
		the service stops supplying one. There is no page, package, or row cap.

		Completeness fails closed. A repeated next link (a paging cycle), a page that
		carries no value collection, or a page request that fails all end the walk with
		Complete = $false and a reason, instead of silently returning a partial array.
		Callers must refuse to publish the canonical catalog from an incomplete listing:
		with an unknown universe, departed-agent classification cannot be trusted.
	.OUTPUTS
		PSCustomObject with .Packages, .Complete, .Reason and .PageCount.
	#>
	$results = New-Object System.Collections.Generic.List[object]
	$uri = Get-Agent365PackagesUri
	$pageNum = 0
	$complete = $true
	$reason = ''
	$seenLinks = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
	while ($uri) {
		if (-not $seenLinks.Add([string]$uri)) {
			$complete = $false
			$reason = "the catalog repeated a paging link after page $pageNum (paging cycle)"
			break
		}
		$pageNum++
		try {
			# Suppress the return value ($true/$false/'Quit') so it does not leak into this
			# function's output pipeline and pollute the returned package array.
			$null = Refresh-GraphTokenIfNeeded -ErrorAction SilentlyContinue
		} catch {}
		$resp = $null
		try {
			$resp = Invoke-MgGraphRequest -Method GET -Uri $uri -ErrorAction Stop
		} catch {
			$complete = $false
			$reason = ("catalog page {0} could not be retrieved: {1}" -f $pageNum, $_.Exception.Message)
			break
		}
		$hasValue = $false
		if ($null -ne $resp) {
			try {
				if ($resp -is [System.Collections.IDictionary]) { $hasValue = $resp.Contains('value') }
				else { $hasValue = [bool](@($resp.PSObject.Properties.Name) -contains 'value') }
			} catch { $hasValue = $false }
		}
		if (-not $hasValue) {
			$complete = $false
			$reason = ("catalog page {0} was malformed (no result collection)" -f $pageNum)
			break
		}
		$pageValue = $resp.value
		if ($null -ne $pageValue) {
			foreach ($p in $pageValue) { [void]$results.Add($p) }
		}
		$next = $null
		try { $next = $resp.'@odata.nextLink' } catch { $next = $null }
		$uri = $next
	}
	return [PSCustomObject]@{
		Packages  = $results.ToArray()
		Complete  = $complete
		Reason    = $reason
		PageCount = $pageNum
	}
}

function Invoke-Agent365GraphWithRetry {
	<#
	.SYNOPSIS
		Throttle-aware Graph GET for the Agent 365 catalog read path. Retries on HTTP 429
		and 5xx with exponential backoff (up to 5 attempts, min(60, 2^attempt) seconds),
		honoring a Retry-After header when present. Non-throttle / non-5xx errors rethrow
		immediately so callers keep their existing skip-with-warning behavior. Mirrors the
		backoff convention used by the chunked remote-upload path.
	#>
	param([Parameter(Mandatory = $true)][string]$Uri)
	$attempt = 0
	while ($true) {
		try {
			return Invoke-MgGraphRequest -Method GET -Uri $Uri -ErrorAction Stop
		} catch {
			$status = try { [int]$_.Exception.Response.StatusCode.value__ } catch { 0 }
			if ($status -eq 0) { if ($_.Exception.Message -match '429|Too Many Requests|TooManyRequests') { $status = 429 } }
			$attempt++
			if (($status -eq 429 -or $status -ge 500) -and $attempt -lt 5) {
				$retryAfter = try { [int]$_.Exception.Response.Headers['Retry-After'] } catch { 0 }
				$wait = if ($retryAfter -gt 0) { $retryAfter } else { [Math]::Min(60, [Math]::Pow(2, $attempt)) }
				Start-Sleep -Seconds $wait
				continue
			}
			throw
		}
	}
}

function Get-Agent365PackageDetail {
	<#
	.SYNOPSIS
		Returns a structured detail outcome for a single agent package.
	.DESCRIPTION
		The result always distinguishes the outcome rather than collapsing every failure to
		$null, so the catalog phase can reconcile every listed package exactly. Outcome is
		'Success' (Detail carries the package detail including elementDetails),
		'FailedDependency' (the service reported the FailedDependency reason phrase), or
		'DetailFailed' (any other retrieval failure). Per-package diagnostics are written to
		the run log at real severity; the console carries only the end-of-phase aggregate so
		package identifiers never flood it.
	.OUTPUTS
		PSCustomObject with .Outcome, .Detail and .Reason.
	#>
	param([Parameter(Mandatory = $true)][string]$PackageId)
	$uri = Get-Agent365PackagesUri -PackageId $PackageId
	try {
		# Suppress the return value ($true/$false/'Quit') so it does not leak into this
		# function's output pipeline and turn the returned detail object into an array.
		$null = Refresh-GraphTokenIfNeeded -ErrorAction SilentlyContinue
	} catch {}
	try {
		$a365Detail = Invoke-Agent365GraphWithRetry -Uri $uri
		return [PSCustomObject]@{ Outcome = 'Success'; Detail = $a365Detail; Reason = '' }
	} catch {
		$a365Reason = [string]$_.Exception.Message
		$a365StatusName = ''
		try { $a365StatusName = [string]$_.Exception.Response.StatusCode } catch { $a365StatusName = '' }
		$a365Outcome = if ($a365StatusName -eq 'FailedDependency' -or $a365Reason -match 'FailedDependency') { 'FailedDependency' } else { 'DetailFailed' }
		Write-LogFile ("Agent 365 detail retrieval failed for package '{0}' (outcome {1}): {2}" -f $PackageId, $a365Outcome, $a365Reason) -Level 'WARNING'
		return [PSCustomObject]@{ Outcome = $a365Outcome; Detail = $null; Reason = $a365Reason }
	}
}

function Resolve-Agent365DeveloperName {
	<#
	.SYNOPSIS
		Resolves a developer/publisher name. Tries package's developer.name first,
		falls back to /applications + /owners lookup keyed on appId. Cached.
	#>
	param(
		[Parameter(Mandatory = $false)][string]$DeveloperName,
		[Parameter(Mandatory = $false)][string]$AppId
	)
	if ($DeveloperName) { return $DeveloperName }
	if (-not $AppId) { return '' }
	if ($script:Agent365DeveloperCache.ContainsKey($AppId)) {
		return $script:Agent365DeveloperCache[$AppId]
	}
	$resolved = ''
	try {
		$appUri = "https://graph.microsoft.com/v1.0/applications?`$filter=appId eq '$AppId'&`$select=id,displayName,publisherDomain"
		$appResp = Invoke-Agent365GraphWithRetry -Uri $appUri
		if ($appResp -and $appResp.value -and $appResp.value.Count -gt 0) {
			$app = $appResp.value[0]
			if ($app.publisherDomain) { $resolved = $app.publisherDomain }
			elseif ($app.displayName) { $resolved = $app.displayName }
			# Optional owner lookup (first owner UPN) only if still blank
			if (-not $resolved -and $app.id) {
				try {
					$ownerUri = "https://graph.microsoft.com/v1.0/applications/$($app.id)/owners?`$select=userPrincipalName,displayName"
					$ownerResp = Invoke-Agent365GraphWithRetry -Uri $ownerUri
					if ($ownerResp -and $ownerResp.value -and $ownerResp.value.Count -gt 0) {
						$resolved = $ownerResp.value[0].displayName
						if (-not $resolved) { $resolved = $ownerResp.value[0].userPrincipalName }
					}
				} catch { }
			}
		}
	} catch {
		# Application.Read.All may not be granted; degrade gracefully (no fabrication).
	}
	$script:Agent365DeveloperCache[$AppId] = $resolved
	return $resolved
}

function Get-Agent365AuditEnrichment {
	<#
	.SYNOPSIS
		Runs a single narrow Graph audit query to retrieve agent create/publish events
		and returns a hashtable keyed on agent id (titleId/appId/lower-cased displayName)
		with @{ Created = [datetime]; CreatedBy = [string] }. Skipped when -OnlyAgent365Info.
	.NOTES
		Best-effort enrichment. If the audit query fails or returns no records, both
		fields stay blank in the output (no fabrication).
	#>
	$enrichment = @{}
	if ($OnlyAgent365Info) { return $enrichment }
	if (-not $script:GraphConnected -and -not (Get-MgContext -ErrorAction SilentlyContinue)) { return $enrichment }

	# Resolve time window: prefer main-run StartDate/EndDate; else last 30 days.
	$rangeStart = $null; $rangeEnd = $null
	try {
		if ($StartDate) { $rangeStart = [datetime]::ParseExact($StartDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture) }
		if ($EndDate)   { $rangeEnd   = [datetime]::ParseExact($EndDate,   'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture) }
	} catch {}
	if (-not $rangeStart) { $rangeStart = (Get-Date).ToUniversalTime().AddDays(-30) }
	if (-not $rangeEnd)   { $rangeEnd   = (Get-Date).ToUniversalTime() }

	# Operation set covering agent/app create/publish/install. Conservative; missing
	# operations simply mean blank columns for affected agents.
	$ops = @(
		'AppCatalogPublishedAppCreated',
		'AppCatalogPublishedAppUpdated',
		'AgentCreated',
		'AgentPublished',
		'CopilotAgentInstalled'
	)

	Write-LogHost "  Running narrow audit query for Agent 365 enrichment (Date created / Created by)..." -ForegroundColor DarkGray
	$queryId = $null
	try {
		$queryId = Invoke-GraphAuditQuery `
			-DisplayName ("PAX_Agents365_Enrichment_{0}" -f (Get-Date -Format 'yyyyMMddHHmmss')) `
			-StartDate $rangeStart `
			-EndDate $rangeEnd `
			-Operations $ops
	} catch {
		Write-LogHost ("  WARNING: Agent 365 enrichment query submit failed: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
		return $enrichment
	}
	if (-not $queryId) {
		Write-LogHost "  WARNING: Agent 365 enrichment query did not return a query id; columns will be blank." -ForegroundColor Yellow
		return $enrichment
	}

	# Poll for query completion. Fortune-500 tenants routinely take 30-90 minutes
	# for audit queries even on narrow operation/time filters. Use the same
	# tolerance window the main audit phase uses (-MaxNetworkOutageMinutes is for
	# transport errors only; query-completion timeout is a separate, longer cap).
	# 4 hours is the documented Graph audit query SLA upper bound.
	$pollTimeoutMinutes = 240
	$pollDeadline = (Get-Date).AddMinutes($pollTimeoutMinutes)
	$pollIntervalSeconds = 15
	$lastLoggedMinute = -1
	$status = $null
	Write-LogHost ("  Polling enrichment query (timeout {0} min, refresh-token aware)..." -f $pollTimeoutMinutes) -ForegroundColor DarkGray
	while ((Get-Date) -lt $pollDeadline) {
		Start-Sleep -Seconds $pollIntervalSeconds
		# Suppress the return value ($true/$false/'Quit') so it does not leak into this
		# function's output pipeline and make the returned enrichment map an array.
		try { $null = Refresh-GraphTokenIfNeeded -ErrorAction SilentlyContinue } catch {}
		try { $status = Get-GraphAuditQueryStatus -QueryId $queryId } catch { $status = $null }
		if ($status -and $status.Status -in @('succeeded','failed','cancelled')) { break }
		# Heartbeat once per minute to keep long polls visible in logs.
		$elapsedMin = [int]((Get-Date) - $pollDeadline.AddMinutes(-$pollTimeoutMinutes)).TotalMinutes
		if ($elapsedMin -ne $lastLoggedMinute -and ($elapsedMin % 5) -eq 0) {
			$lastLoggedMinute = $elapsedMin
			$st = if ($status -and $status.Status) { $status.Status } else { 'pending' }
			Write-LogHost ("    ... {0} min elapsed, status={1}" -f $elapsedMin, $st) -ForegroundColor DarkGray
		}
		# Gentle backoff: 15s -> 30s -> 60s after 2 and 10 minutes respectively.
		if ($elapsedMin -ge 10 -and $pollIntervalSeconds -lt 60) { $pollIntervalSeconds = 60 }
		elseif ($elapsedMin -ge 2 -and $pollIntervalSeconds -lt 30) { $pollIntervalSeconds = 30 }
	}
	if (-not $status -or $status.Status -ne 'succeeded') {
		Write-LogHost ("  WARNING: Agent 365 enrichment query did not succeed (status={0}); columns will be blank." -f ($status.Status)) -ForegroundColor Yellow
		return $enrichment
	}

	$records = @()
	try { $records = Get-GraphAuditRecords -QueryId $queryId } catch { $records = @() }
	if (-not $records -or $records.Count -eq 0) { return $enrichment }

	foreach ($rec in $records) {
		try {
			$auditObj = $null
			if ($rec.PSObject.Properties.Name -contains 'auditData') { $auditObj = $rec.auditData }
			if ($auditObj -is [string]) { try { $auditObj = $auditObj | ConvertFrom-Json -ErrorAction Stop } catch { $auditObj = $null } }
			$created = $null
			if ($rec.PSObject.Properties.Name -contains 'createdDateTime' -and $rec.createdDateTime) {
				try { $created = [datetime]$rec.createdDateTime } catch {}
			}
			$createdBy = $null
			if ($rec.PSObject.Properties.Name -contains 'userPrincipalName' -and $rec.userPrincipalName) {
				$createdBy = [string]$rec.userPrincipalName
			}
			# Pull keys from auditData defensively (preview schema may shift).
			$keys = New-Object System.Collections.Generic.List[string]
			if ($auditObj) {
				foreach ($p in 'TitleId','titleId','AppId','appId','PackageId','packageId','TeamsAppId','teamsAppId','DisplayName','displayName','Name','name') {
					try { if ($auditObj.$p) { [void]$keys.Add(([string]$auditObj.$p).ToLowerInvariant()) } } catch {}
				}
			}
			foreach ($k in $keys) {
				if (-not $enrichment.ContainsKey($k)) {
					$enrichment[$k] = @{ Created = $created; CreatedBy = $createdBy }
				}
			}
		} catch { continue }
	}
	Write-LogHost ("  Audit enrichment matched {0} agent identifier key(s)." -f $enrichment.Keys.Count) -ForegroundColor DarkGray
	return $enrichment
}

function ConvertTo-Agent365Row {
	<#
	.SYNOPSIS
		Maps one package detail object to the exact 28-column synthetic schema.
		Empty cells stay empty when fields are absent (no fabrication).
	#>
	param(
		[Parameter(Mandatory = $true)][object]$Package,
		[Parameter(Mandatory = $false)][hashtable]$AuditEnrichment
	)
	function _g { param($obj, [string[]]$names) foreach ($n in $names) { try { if ($null -ne $obj.$n -and "$($obj.$n)" -ne '') { return $obj.$n } } catch {} } return '' }
	function _gb { param($obj, [string[]]$names) foreach ($n in $names) { try { if ($null -ne $obj.$n) { return [bool]$obj.$n } } catch {} } return '' }
	function _join { param($v, [string]$sep) if ($null -eq $v) { return '' }; if ($v -is [System.Collections.IEnumerable] -and -not ($v -is [string])) { return (@($v) -join $sep) } else { return [string]$v } }
	function _fmtDate { param($v) if (-not $v) { return '' }; try { return ([datetime]$v).ToUniversalTime().ToString('yyyy-MM-dd HH:mm:ssZ') } catch { return [string]$v } }

	$elem = $null
	try { $elem = $Package.elementDetails } catch {}

	$titleIdRaw = (_g $Package @('id','titleId','packageId'))
	$titleId = ''
	if ($titleIdRaw) { $titleId = if ($titleIdRaw -match '^T_') { [string]$titleIdRaw } else { 'T_' + [string]$titleIdRaw } }

	# Audit enrichment lookup (lowercase keys). Try titleId raw, appId, displayName.
	$dateCreated = ''
	$createdBy   = ''
	if ($AuditEnrichment) {
		$probeKeys = @()
		if ($titleIdRaw) { $probeKeys += ([string]$titleIdRaw).ToLowerInvariant() }
		$appIdProbe = (_g $Package @('appId','applicationId'))
		if ($appIdProbe) { $probeKeys += ([string]$appIdProbe).ToLowerInvariant() }
		$dispProbe = (_g $Package @('displayName','name'))
		if ($dispProbe) { $probeKeys += ([string]$dispProbe).ToLowerInvariant() }
		foreach ($k in $probeKeys) {
			if ($AuditEnrichment.ContainsKey($k)) {
				$hit = $AuditEnrichment[$k]
				if ($hit.Created)   { $dateCreated = (_fmtDate $hit.Created) }
				if ($hit.CreatedBy) { $createdBy   = [string]$hit.CreatedBy }
				break
			}
		}
	}
	# Fallback to package's own createdDateTime if audit didn't supply one
	if (-not $dateCreated) {
		$pkgCreated = (_g $Package @('createdDateTime','createdDate'))
		if ($pkgCreated) { $dateCreated = (_fmtDate $pkgCreated) }
	}

	$developer = Resolve-Agent365DeveloperName -DeveloperName (_g $Package @('developer.name')) -AppId (_g $Package @('appId','applicationId'))
	# fallback: try direct nested object access
	if (-not $developer) {
		try { if ($Package.developer -and $Package.developer.name) { $developer = [string]$Package.developer.name } } catch {}
	}

	[PSCustomObject][ordered]@{
		'Name'                                  = (_g $Package @('displayName','name'))
		'Supported in'                          = (_join (_g $Package @('supportedHosts','supportedClients')) ';')
		'Date created'                          = $dateCreated
		'Developer Name'                        = $developer
		'Type'                                  = (_g $Package @('agentType','type'))
		'Version'                               = (_g $Package @('version'))
		'Availability'                          = (_g $Package @('availability','allowedUsersAndGroups'))
		'Created by'                            = $createdBy
		'Description'                           = (_g $Package @('description'))
		'Created in'                            = (_g $Package @('source','origin','createdIn'))
		'Last updated'                          = (_fmtDate (_g $Package @('lastModifiedDateTime','lastUpdatedDateTime')))
		'Custom actions'                        = (_g $elem @('customActions'))
		'Title ID'                              = $titleId
		'Sensitivity'                           = (_g $Package @('sensitivity'))
		'Can read OneDrive and Sharepoint items'= (_gb $elem @('canReadOneDriveAndSharepointItems'))
		'OneDrive and Sharepoint items'         = (_g $elem @('oneDriveAndSharepointItems'))
		'Can read OneDrive files'               = (_gb $elem @('canReadOneDriveFiles'))
		'OneDrive files'                        = (_g $elem @('oneDriveFiles'))
		'OneDrive sites'                        = (_g $elem @('oneDriveSites'))
		'Can read Sharepoint sites and files'   = (_gb $elem @('canReadSharepointSitesAndFiles'))
		'Sharepoint files'                      = (_g $elem @('sharepointFiles'))
		'Sharepoint sites'                      = (_g $elem @('sharepointSites'))
		'Can extend to Graph connector'         = (_gb $elem @('canExtendToGraphConnector'))
		'Graph connector details'               = (_g $elem @('graphConnectorDetails'))
		'Can generate images using user prompt' = (_gb $elem @('canGenerateImagesUsingUserPrompt'))
		'Can use code interpreter'              = (_gb $elem @('canUseCodeInterpreter'))
		'Contains uploaded files'               = (_gb $elem @('containsUploadedFiles'))
		'Uploaded files'                        = (_g $elem @('uploadedFiles'))
	}
}

function Export-Agent365Csv {
	<#
	.SYNOPSIS
		Writes the Agent 365 CSV (UTF-8 BOM) to OutputPath using the run timestamp.
	.DESCRIPTION
		When -AppendAgent365Info <target.csv> is in effect, this function pre-reads the
		target CSV and union-merges its rows with the current API-derived rows: the
		current run's row wins on AgentId conflicts (freshest metadata) and any
		target-only AgentId is carried forward (departed agents are not dropped).
	.OUTPUTS
		Full path to written file, or $null if no rows.
	#>
	param(
		[Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Rows
	)
	if (-not $Rows -or $Rows.Count -eq 0) {
		Write-LogHost "  Agent 365: no rows to write." -ForegroundColor Yellow
		return $null
	}

	# Union-merge with -AppendAgent365Info target when set. Failures here are
	# non-fatal — fall back to current-run rows only.
	$rowsToWrite = [System.Collections.Generic.List[object]]::new()
	foreach ($r in $Rows) { [void]$rowsToWrite.Add($r) }
	if ($AppendAgent365Info -and (Test-Path -LiteralPath $AppendAgent365Info -PathType Leaf)) {
		try {
			$currentAgentIds = New-Object System.Collections.Generic.HashSet[string]
			foreach ($r in $Rows) {
				$aid = $null
				try { $aid = [string]$r.AgentId } catch {}
				if ($aid) { [void]$currentAgentIds.Add($aid) }
			}
			$targetRows = @(Import-Csv -LiteralPath $AppendAgent365Info -Encoding UTF8)
			$carried = 0
			foreach ($tr in $targetRows) {
				$aid = $null
				try { $aid = [string]$tr.AgentId } catch {}
				if (-not $aid) { continue }
				if (-not $currentAgentIds.Contains($aid)) {
					[void]$rowsToWrite.Add($tr)
					$carried++
				}
			}
			Write-LogHost ("  -AppendAgent365Info: carried {0:N0} departed agent(s) from '{1}'; current run contributed {2:N0}." -f $carried, $AppendAgent365Info, $Rows.Count) -ForegroundColor DarkCyan
		}
		catch {
			Write-LogHost ("  WARNING: -AppendAgent365Info merge failed ({0}); writing current-run rows only." -f $_.Exception.Message) -ForegroundColor Yellow
		}
	}

	$ts = $global:ScriptRunTimestamp
	if (-not $ts) { $ts = (Get-Date).ToString('yyyyMMdd_HHmmss') }
	# Per-data-type destination. If -OutputPathAgent365Info resolves to a Local
	# folder or file form, route the catalog there; otherwise inherit $OutputPath. Remote
	# tiers (SharePoint/Fabric) continue to write to the scratch dir and upload from there.
	$agentOutDir = $OutputPath
	# Effective basename (honors -AppendAgent365Info target leaf so the merged file
	# produced this run can be uploaded back over the original remote URL \u2014 matched
	# by the upload sweep's Append-leaf filter).
	$agentBasename = (& $script:GetEffectiveAgent365Basename)
	try {
		$dt = script:Resolve-DataTypePaths -DataType 'Agent365Info' -DefaultBasename $agentBasename
		if ($dt -and $dt.IsBound -and $dt.Tier -eq 'Local') {
			$agentOutDir = $dt.EffectiveDir
			if ($dt.Basename) { $agentBasename = $dt.Basename }
			if (-not (Test-Path -LiteralPath $agentOutDir -PathType Container)) {
				New-Item -Path $agentOutDir -ItemType Directory -Force | Out-Null
			}
		}
	} catch {}
	$outFile = Join-Path $agentOutDir $agentBasename
	try {
		# Atomic write — Save-CsvAtomic uses temp+rename so a Ctrl+C / OOM-kill mid-write
		# cannot leave a half-formed Agent365 CSV in the operator's output folder.
		Save-CsvAtomic -InputObject ($rowsToWrite.ToArray()) -Path $outFile -NoTypeInformation -Encoding UTF8
		# In remote (SharePoint/Fabric) mode the file lands in LOCAL SCRATCH and is uploaded
		# by the end-of-run artifact sweep; say so, rather than implying it is already at the
		# displayed remote destination.
		if ($script:RemoteOutputMode -ne 'None') {
			Write-LogHost ("  Agent 365 CSV written to scratch, queued for upload: {0} ({1} rows)" -f (Get-DisplayPath -LocalPath $outFile), $rowsToWrite.Count) -ForegroundColor Green
		} else {
			Write-LogHost ("  Agent 365 CSV written: {0} ({1} rows)" -f (Get-DisplayPath -LocalPath $outFile), $rowsToWrite.Count) -ForegroundColor Green
		}
		return $outFile
	} catch {
		Write-LogHost ("  ERROR: Failed to write Agent 365 CSV: {0}" -f $_.Exception.Message) -ForegroundColor Red
		return $null
	}
}

function Save-Agent365RecoveryCsv {
	<#
	.SYNOPSIS
		Writes the rows retrieved during an INCOMPLETE catalog listing to a clearly-named
		recovery file that is never treated as the canonical Agent 365 catalog.
	.DESCRIPTION
		An incomplete listing means the catalog universe is unknown, so the canonical target
		(and any -AppendAgent365Info union) must be left byte-for-byte unchanged. The rows
		that WERE retrieved are still valuable, so they are preserved locally under a
		distinct leaf. That leaf is registered as recovery material so the end-of-run local
		listing and the remote upload sweep both exclude it: recovery material is never
		published as a completed catalog.
	.OUTPUTS
		Full path to the recovery file, or $null when there was nothing to preserve.
	#>
	param(
		[Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Rows
	)
	if (-not $Rows -or $Rows.Count -eq 0) { return $null }
	$ts = $global:ScriptRunTimestamp
	if (-not $ts) { $ts = (Get-Date).ToString('yyyyMMdd_HHmmss') }
	$recoveryLeaf = "Agent365_IncompleteListing_${ts}_recovery.csv"
	$recoveryPath = Join-Path $OutputPath $recoveryLeaf
	try {
		Save-CsvAtomic -InputObject $Rows -Path $recoveryPath -NoTypeInformation -Encoding UTF8
		if (-not $script:Agent365RecoveryLeafs) { $script:Agent365RecoveryLeafs = New-Object System.Collections.Generic.List[string] }
		if (-not $script:Agent365RecoveryLeafs.Contains($recoveryLeaf)) { [void]$script:Agent365RecoveryLeafs.Add($recoveryLeaf) }
		Write-LogHost ("  Agent 365: {0:N0} retrieved row(s) preserved as recovery material (excluded from upload): {1}" -f $Rows.Count, (Get-DisplayPath -LocalPath $recoveryPath)) -ForegroundColor Yellow
		return $recoveryPath
	}
	catch {
		Write-LogHost ("  WARNING: Agent 365 recovery file could not be written: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
		return $null
	}
}

function Add-Agent365WorkbookTab {
	<#
	.SYNOPSIS
		Appends an 'Agents365' worksheet to the existing workbook (after EntraUsers tab).
		No-op when -ExportWorkbook is not set or ImportExcel is unavailable.
	#>
	param(
		[Parameter(Mandatory = $true)][string]$WorkbookPath,
		[Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Rows
	)
	if (-not $ExportWorkbook) { return }
	if (-not $Rows -or $Rows.Count -eq 0) { return }
	if (-not (Get-Module -ListAvailable -Name ImportExcel)) {
		Write-LogHost "  Agent 365: ImportExcel not available; skipping workbook tab." -ForegroundColor Yellow
		return
	}
	try {
		Import-Module ImportExcel -Force -ErrorAction Stop
		$Rows | Export-Excel -Path $WorkbookPath -WorksheetName 'Agents365' -AutoSize -BoldTopRow -FreezeTopRow -ErrorAction Stop
		Write-LogHost ("  Agent 365 worksheet appended to: {0}" -f (Get-DisplayPath -LocalPath $WorkbookPath)) -ForegroundColor Green
	} catch {
		Write-LogHost ("  WARNING: Could not append Agents365 worksheet: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
	}
}

function Invoke-Agent365Phase {
	<#
	.SYNOPSIS
		Top-level orchestrator for the Agent 365 phase. Called once from the main
		flow when -IncludeAgent365Info or -OnlyAgent365Info is set. No-op otherwise.
	.OUTPUTS
		Hashtable: @{ CsvPath = <string|$null>; Rows = <array> }
	#>
	if (-not ($IncludeAgent365Info -or $OnlyAgent365Info)) { return @{ CsvPath = $null; Rows = @() } }

	Write-LogHost "" 
	Write-LogHost "============================================================" -ForegroundColor Cyan
	Write-LogHost " Microsoft Agent 365 enrichment phase" -ForegroundColor Cyan
	Write-LogHost "============================================================" -ForegroundColor Cyan

	# App-only modes (AppRegistration certificate/secret, ManagedIdentity): surface the app-only
	# Phase 2 banner and reuse the EXISTING application Graph context (no interactive sign-in).
	# Delegated modes skip this block and go straight to the Frontier probe using the Agent 365
	# scopes already consented at their initial sign-in.
	if ($Auth -eq 'AppRegistration' -or $Auth -eq 'ManagedIdentity') {
		if (-not (Connect-Agent365InteractiveContext)) {
			Write-LogHost "  Agent 365 phase aborted (app-only Graph context unavailable)." -ForegroundColor Red
			return @{ CsvPath = $null; Rows = @() }
		}
	}

	# Frontier probe (prints banner 7d on 401/403/404 and returns false).
	if (-not (Test-Agent365FrontierAccess)) {
		return @{ CsvPath = $null; Rows = @() }
	}

	# Audit enrichment (skipped when -OnlyAgent365Info).
	$script:Agent365AuditEnrichment = Get-Agent365AuditEnrichment
	# Defensive safety net (NOT a substitute for the pipeline-leak suppression in the
	# enrichment/list/detail helpers): the enrichment lookup must resolve to a single
	# hashtable. If it is ever anything else, coerce to an empty map and warn loudly so
	# row building degrades to blank enrichment columns instead of throwing a raw
	# type-coercion error on every package.
	if ($script:Agent365AuditEnrichment -isnot [hashtable]) {
		$a365EnrType = if ($null -eq $script:Agent365AuditEnrichment) { 'null' } else { $script:Agent365AuditEnrichment.GetType().Name }
		Write-LogHost ("  WARNING: Agent 365 audit enrichment resolved to an unexpected type ({0}); continuing with blank enrichment columns." -f $a365EnrType) -ForegroundColor Yellow
		$script:Agent365AuditEnrichment = @{}
	}

	# List + per-package detail
	Write-LogHost "  Listing Agent 365 packages..." -ForegroundColor DarkGray
	$listResult = Get-Agent365Packages
	$listed = @($listResult.Packages)
	$a365ListComplete = [bool]$listResult.Complete
	if (-not $a365ListComplete) {
		Write-LogHost ("  WARNING: Agent 365 catalog listing is INCOMPLETE after {0:N0} page(s): {1}" -f $listResult.PageCount, $listResult.Reason) -ForegroundColor Yellow
		Write-LogFile ("Agent 365 catalog listing incomplete after {0} page(s): {1}" -f $listResult.PageCount, $listResult.Reason) -Level 'ERROR'
	}
	if (-not $listed -or $listed.Count -eq 0) {
		if (-not $a365ListComplete) {
			$script:Agent365HadGaps = $true
			Write-LogHost "  Agent 365: no packages could be listed and the listing did not complete; the existing catalog target is left unchanged (completed with gaps, exit 40)." -ForegroundColor Red
		} else {
			Write-LogHost "  No Agent 365 packages returned by the catalog." -ForegroundColor Yellow
		}
		return @{ CsvPath = $null; Rows = @(); Listed = 0; Emitted = 0; DetailFailed = 0; FailedDependency = 0; RowBuildFailed = 0; SkippedNoId = 0; Reconciled = $a365ListComplete; ListComplete = $a365ListComplete; RecoveryPath = $null }
	}
	Write-LogHost ("  {0} package(s) listed; fetching details..." -f $listed.Count) -ForegroundColor DarkGray

	$rows = New-Object System.Collections.Generic.List[object]
	$idx = 0
	# Complete outcome accounting. Every listed package resolves to exactly one bucket, so
	# listed == emitted + detailFailed + rowBuildFailed + skippedNoId holds for the walk.
	$a365Emitted = 0
	$a365DetailFailed = 0
	$a365FailedDependency = 0
	$a365RowBuildFailed = 0
	$a365SkippedNoId = 0
	foreach ($p in $listed) {
		$idx++
		$pkgId = $null
		try { $pkgId = $p.id } catch {}
		if (-not $pkgId) { try { $pkgId = $p.titleId } catch {} }
		if (-not $pkgId) {
			$a365SkippedNoId++
			Write-LogFile ("Agent 365: listed entry {0} carries no usable package identifier; no row emitted." -f $idx) -Level 'WARNING'
			continue
		}
		$detailResult = Get-Agent365PackageDetail -PackageId $pkgId
		if ($null -eq $detailResult -or $detailResult.Outcome -ne 'Success') {
			$a365DetailFailed++
			if ($detailResult -and $detailResult.Outcome -eq 'FailedDependency') { $a365FailedDependency++ }
			continue
		}
		try {
			$row = ConvertTo-Agent365Row -Package $detailResult.Detail -AuditEnrichment $script:Agent365AuditEnrichment
			[void]$rows.Add($row)
			$a365Emitted++
		} catch {
			$a365RowBuildFailed++
			Write-LogFile ("Agent 365: row build failed for package '{0}': {1}" -f $pkgId, $_.Exception.Message) -Level 'ERROR'
		}
		if (($idx % 25) -eq 0) {
			Write-LogHost ("    ... {0}/{1} packages processed" -f $idx, $listed.Count) -ForegroundColor DarkGray
		}
	}

	$a365Failed = $a365DetailFailed + $a365RowBuildFailed
	$a365Accounted = $a365Emitted + $a365DetailFailed + $a365RowBuildFailed + $a365SkippedNoId
	$a365Reconciled = ($a365Accounted -eq $listed.Count)
	# One concise completion summary. Per-package diagnostics stay in the run log.
	Write-LogHost ("  Agent 365: {0:N0} listed, {1:N0} emitted, {2:N0} failed, {3:N0} skipped." -f $listed.Count, $a365Emitted, $a365Failed, $a365SkippedNoId) -ForegroundColor $(if ($a365Failed -gt 0 -or $a365SkippedNoId -gt 0) { 'Yellow' } else { 'Green' })
	Write-LogFile ("Agent 365 accounting: listed={0} emitted={1} detailFailed={2} (FailedDependency={3}) rowBuildFailed={4} skippedNoId={5} reconciled={6}" -f $listed.Count, $a365Emitted, $a365DetailFailed, $a365FailedDependency, $a365RowBuildFailed, $a365SkippedNoId, $a365Reconciled) -Level $(if ($a365Failed -gt 0 -or $a365SkippedNoId -gt 0 -or -not $a365Reconciled) { 'ERROR' } else { 'INFO' })
	if (-not $a365Reconciled) {
		Write-LogFile ("Agent 365 accounting did not reconcile: {0} listed vs {1} accounted." -f $listed.Count, $a365Accounted) -Level 'ERROR'
	}
	# Requested Agent 365 output is incomplete whenever any listed package produced no row.
	if ($a365Failed -gt 0 -or $a365SkippedNoId -gt 0 -or -not $a365Reconciled -or -not $a365ListComplete) {
		$script:Agent365HadGaps = $true
		Write-LogHost "  Agent 365: requested catalog output is INCOMPLETE (completed with gaps, exit 40)." -ForegroundColor Yellow
	}

	if (-not $a365ListComplete) {
		# The catalog universe is unknown, so departed-agent classification cannot be trusted.
		# Never publish or overwrite the canonical catalog target from a partial listing: leave
		# any existing target byte-for-byte unchanged and keep this run's rows as recovery material.
		Write-LogHost "  Agent 365: the catalog file is NOT written or overwritten this run because the listing did not complete; any existing target is left unchanged." -ForegroundColor Red
		$a365RecoveryPath = Save-Agent365RecoveryCsv -Rows $rows.ToArray()
		return @{
			CsvPath          = $null
			Rows             = @()
			Listed           = $listed.Count
			Emitted          = $a365Emitted
			DetailFailed     = $a365DetailFailed
			FailedDependency = $a365FailedDependency
			RowBuildFailed   = $a365RowBuildFailed
			SkippedNoId      = $a365SkippedNoId
			Reconciled       = $a365Reconciled
			ListComplete     = $false
			RecoveryPath     = $a365RecoveryPath
		}
	}

	$csvPath = Export-Agent365Csv -Rows $rows.ToArray()
	return @{
		CsvPath          = $csvPath
		Rows             = $rows.ToArray()
		Listed           = $listed.Count
		Emitted          = $a365Emitted
		DetailFailed     = $a365DetailFailed
		FailedDependency = $a365FailedDependency
		RowBuildFailed   = $a365RowBuildFailed
		SkippedNoId      = $a365SkippedNoId
		Reconciled       = $a365Reconciled
		ListComplete     = $true
		RecoveryPath     = $null
	}
}

