function Test-EntraUsersSchema {
	param(
		[Parameter(Mandatory=$true)][array]$Users,
		[switch]$Quiet
	)
	if (-not $Users -or $Users.Count -eq 0) { return }
	$expected = $EntraUsersHeader
	$actual = $Users[0].PSObject.Properties.Name
	$missing = @(); foreach ($c in $expected) { if ($c -notin $actual) { $missing += $c } }
	$extra = @(); foreach ($c in $actual) { if ($c -notin $expected) { $extra += $c } }
	if ($missing.Count -gt 0 -or $extra.Count -gt 0) {
		Write-LogHost ("WARNING: EntraUsers schema mismatch. Missing: {0}; Extra: {1}" -f ($missing -join ', '), ($extra -join ', ')) -ForegroundColor Yellow
	} elseif (-not $Quiet) {
		Write-LogHost "Validated EntraUsers schema ($($expected.Count) columns)." -ForegroundColor DarkGray
	}
}

# ═══════════════════════════════════════════════════════════════════════════════
# HYBRID DIRECTORY SUPPLEMENT (-UserInfoSupplement) — shared input transport + parse/validate + merge
# The three functions below implement the customer-facing hybrid enrichment mode. They are script-scoped
# and pure (no global side effects beyond their return values) so the focused test suite can AST-extract
# and exercise the SHIPPED code paths directly.
# ═══════════════════════════════════════════════════════════════════════════════

function script:Get-PaxReservedDirectoryColumns {
	# Authoritative reserved-column set that a supplemental column must never collide with
	# (case-insensitive). Derived from the live Entra users contract ($EntraUsersHeader) UNION the
	# PAX/Rollup-owned identity, licensing, append-provenance, and hierarchy columns produced downstream
	# by the Users dimension. Deriving from $EntraUsersHeader keeps the Entra half in sync with the schema.
	$reserved = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
	foreach ($c in $EntraUsersHeader) { [void]$reserved.Add([string]$c) }
	foreach ($c in @('PersonId','UserKey','PersonId_Normalized','License Status','TotalEmployees',
		'Date_Added','Latest_Append_Date','In_Latest_Append','Manager_UserKey','OrgLevel','HierarchyPath',
		'TopOfChain_UserKey','IsManager','DirectReports','TotalReports')) { [void]$reserved.Add($c) }
	for ($lvl = 0; $lvl -le 14; $lvl++) { [void]$reserved.Add("Level${lvl}_UserKey"); [void]$reserved.Add("Level${lvl}_Name") }
	# Unary comma prevents PowerShell from unrolling the HashSet into an array on return (which would
	# silently make .Contains() a case-SENSITIVE array match). Callers receive the case-insensitive set.
	return ,$reserved
}

function script:Resolve-DirectoryCsvInput {
	# Shared, hardened classifier + stager for a customer-provided directory CSV INPUT (used by BOTH
	# -UserInfoFile and -UserInfoSupplement). Classifies the input value's OWN tier independent of the
	# output tier, requires an actual .csv file leaf (folder URLs, Fabric roots, and Fabric Tables URLs are
	# rejected; a Fabric input must live under /Files/.../*.csv), and for remote tiers stages the file to
	# run-specific local scratch via the matching Get-RemoteFile-* using the input URL's own parent + leaf.
	# Staged inputs are never registered for upload. Returns @{ Tier; LocalPath; Leaf; Parent; Staged }.
	# Throws (or Get-PathTier hard-stops) on any classification/fetch failure — callers do NOT fall back.
	param(
		[Parameter(Mandatory)][string]$Value,
		[Parameter(Mandatory)][string]$SwitchName,
		[Parameter(Mandatory)][string]$ScratchDir,
		[Parameter(Mandatory)][string]$ScratchPrefix
	)
	$raw  = $Value.Trim()
	$tier = script:Get-PathTier -Value $raw -SwitchName $SwitchName -AllowFabricFilesOnly
	$leaf = ($raw -split '[\\/]' | Where-Object { $_ }) | Select-Object -Last 1
	if ([string]::IsNullOrWhiteSpace($leaf) -or ($leaf -notmatch '(?i)\.csv$')) {
		Write-Host ("ERROR: -{0} must reference a .csv file (not a folder). Provided: {1}" -f $SwitchName, $raw) -ForegroundColor Red
		throw ("-{0} must reference a .csv file: {1}" -f $SwitchName, $raw)
	}
	if ($tier -eq 'Local') {
		return @{ Tier = 'Local'; LocalPath = $raw; Leaf = $leaf; Parent = (Split-Path -Path $raw -Parent); Staged = $false }
	}
	$parent    = $raw.Substring(0, $raw.Length - $leaf.Length).TrimEnd('/', '\')
	$localPath = Join-Path $ScratchDir ('{0}{1}' -f $ScratchPrefix, $leaf)
	if ($tier -eq 'SharePoint') {
		Get-RemoteFile-SharePoint -RelativeName $leaf -DestinationPath $localPath -ParentOverride $parent -ErrorAction Stop
	}
	else {
		Get-RemoteFile-OneLake -RelativeName $leaf -DestinationPath $localPath -ParentOverride $parent -ErrorAction Stop
	}
	return @{ Tier = $tier; LocalPath = $localPath; Leaf = $leaf; Parent = $parent; Staged = $true }
}

function script:Import-PaxSupplementCsv {
	# Parse + validate a supplemental directory CSV for -UserInfoSupplement. Structured CSV parsing only
	# (Import-Csv), never string splitting. Enforces: readable CSV header; >=1 data row; exactly one
	# 'UserPrincipalName' header (case-insensitive; NO aliases); no case-insensitive duplicate headers;
	# non-blank UPN on every row; unique normalized UPNs; and no supplemental (passthrough) column colliding
	# with a reserved Entra/PAX-owned column. The join key is removed from the passthrough set (it is never
	# copied into output). Returns @{ Rows; UpnColumn; PassthroughColumns; Lookup } where Lookup maps a
	# normalized UPN (Trim().ToLowerInvariant()) to the ORIGINAL supplemental row. Throws a clear,
	# count/list-bearing message on any violation.
	param([Parameter(Mandatory)][string]$Path)
	$rows = @(Import-Csv -LiteralPath $Path -ErrorAction Stop)
	if ($rows.Count -eq 0) {
		$firstLine = Get-Content -LiteralPath $Path -TotalCount 1 -ErrorAction SilentlyContinue
		if ([string]::IsNullOrWhiteSpace($firstLine)) { throw "-UserInfoSupplement has no header row (not a CSV): $Path" }
		throw "-UserInfoSupplement contains a header but zero data rows: $Path"
	}
	$headers = @($rows[0].PSObject.Properties.Name)
	$seen = @{}; $dupHeaders = @()
	foreach ($h in $headers) { $k = ([string]$h).Trim().ToLowerInvariant(); if ($seen.ContainsKey($k)) { $dupHeaders += $h } else { $seen[$k] = $h } }
	if ($dupHeaders.Count -gt 0) { throw ("-UserInfoSupplement has duplicate column header(s) (case-insensitive): {0}" -f (($dupHeaders | Select-Object -Unique) -join ', ')) }
	$upnCols = @($headers | Where-Object { ([string]$_).Trim().ToLowerInvariant() -eq 'userprincipalname' })
	if ($upnCols.Count -eq 0) { throw ("-UserInfoSupplement is missing the required 'UserPrincipalName' column. Found: {0}" -f ($headers -join ', ')) }
	if ($upnCols.Count -gt 1) { throw ("-UserInfoSupplement has more than one 'UserPrincipalName' column; exactly one is required.") }
	$upnCol = $upnCols[0]
	$passthrough = @($headers | Where-Object { $_ -ne $upnCol })
	$reserved = script:Get-PaxReservedDirectoryColumns
	$collisions = @($passthrough | Where-Object { $reserved.Contains([string]$_) })
	if ($collisions.Count -gt 0) { throw ("-UserInfoSupplement column(s) collide with reserved Entra/PAX-owned columns (supplemental columns are additive-only and cannot override PAX data): {0}" -f ($collisions -join ', ')) }
	$lookup = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::OrdinalIgnoreCase)
	$blankCount = 0; $dupUpns = [System.Collections.Generic.List[string]]::new()
	foreach ($row in $rows) {
		$rawUpn = [string]$row.$upnCol
		if ([string]::IsNullOrWhiteSpace($rawUpn)) { $blankCount++; continue }
		$norm = $rawUpn.Trim().ToLowerInvariant()
		if ($lookup.ContainsKey($norm)) { $dupUpns.Add($rawUpn.Trim()) } else { $lookup[$norm] = $row }
	}
	if ($blankCount -gt 0) { throw ("-UserInfoSupplement has {0} row(s) with a blank UserPrincipalName; every supplemental row must carry a UPN." -f $blankCount) }
	if ($dupUpns.Count -gt 0) { throw ("-UserInfoSupplement has duplicate UserPrincipalName value(s) (normalized, case-insensitive): {0}" -f (($dupUpns | Select-Object -Unique) -join ', ')) }
	return @{ Rows = $rows; UpnColumn = $upnCol; PassthroughColumns = $passthrough; Lookup = $lookup }
}

function script:Merge-PaxEntraSupplement {
	# Entra-LEFT join: append the supplemental passthrough columns to each Entra row, preserving Entra row
	# order and supplemental column order. A matching Entra user receives the exact supplemental value; a
	# non-matching Entra user receives '' for every supplemental column. Supplemental-only users are NEVER
	# added (Entra stays authoritative); the supplemental UPN is NEVER copied into output. Entra rows are
	# enriched in place (each supplemental column appended AFTER all existing properties). Returns
	# @{ Rows; Matched; UnmatchedSupplemental; EntraWithout; ColumnsAdded }.
	param(
		[Parameter(Mandatory)][AllowEmptyCollection()][object[]]$EntraRows,
		[Parameter(Mandatory)][string[]]$PassthroughColumns,
		[Parameter(Mandatory)]$Lookup,
		[Parameter(Mandatory)][string]$UpnColumn
	)
	$matchedKeys = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
	$entraWithout = 0
	foreach ($er in $EntraRows) {
		$eupn = [string]$er.userPrincipalName
		$norm = if ($eupn) { $eupn.Trim().ToLowerInvariant() } else { '' }
		$supRow = $null
		if ($norm -and $Lookup.ContainsKey($norm)) { $supRow = $Lookup[$norm]; [void]$matchedKeys.Add($norm) } else { $entraWithout++ }
		foreach ($pc in $PassthroughColumns) {
			$val = if ($supRow) { [string]$supRow.$pc } else { '' }
			$er.PSObject.Properties.Remove($pc)
			$er | Add-Member -NotePropertyName $pc -NotePropertyValue $val -Force
		}
	}
	$unmatched = [System.Collections.Generic.List[string]]::new()
	foreach ($k in $Lookup.Keys) { if (-not $matchedKeys.Contains($k)) { $unmatched.Add([string]$Lookup[$k].$UpnColumn) } }
	return @{ Rows = $EntraRows; Matched = $matchedKeys.Count; UnmatchedSupplemental = @($unmatched); EntraWithout = $entraWithout; ColumnsAdded = @($PassthroughColumns) }
}

# ═══════════════════════════════════════════════════════════════════════════════
# FAST ROW CREATION HELPER

# Converts a hashtable to PSCustomObject in a single operation (avoids Add-Member overhead)
# Used by explosion logic to build rows efficiently via hashtable accumulation
# ═══════════════════════════════════════════════════════════════════════════════
function New-FastRow {
	<#
	.SYNOPSIS
	Creates a PSCustomObject from a hashtable in a single operation.
	.DESCRIPTION
	Builds a row by accumulating properties in a hashtable first, then converting
	to PSCustomObject once. This is significantly faster than repeated Add-Member calls.
	.PARAMETER Properties
	A hashtable containing property names and values for the new object.
	.EXAMPLE
	$props = @{ Name = 'Test'; Value = 123 }
	$row = New-FastRow -Properties $props
	#>
	[CmdletBinding()]
	param([Parameter(Mandatory)][hashtable]$Properties)
	return [PSCustomObject]$Properties
}

$existingDeep = Get-Variable -Name DeepExtraColumns -Scope Script -ErrorAction SilentlyContinue
if (-not $existingDeep -or -not $script:DeepExtraColumns) { $script:DeepExtraColumns = New-Object System.Collections.Generic.List[string] }

function Convert-ToPurviewExplodedRecords {
	[CmdletBinding()]
	param(
		[Parameter(Mandatory)] $Record,
		[switch]$Deep,
		[switch]$PartialExplode,  # NEW: Prompt-specific explosion only (preserves AuditData)
		[string]$PromptFilterValue,
		[switch]$SkipMetrics  # Used by parallel replay to defer metrics aggregation to parent thread
	)
	try {
		$auditData = if ($Record.PSObject.Properties['_ParsedAuditData']) { $Record._ParsedAuditData } else { try { $Record.AuditData | ConvertFrom-Json -ErrorAction Stop } catch { $null } }
		if (-not $auditData) { 
			if (-not $SkipMetrics) {
				$script:metrics.FilteringSkippedRecords++
				$script:metrics.FilteringMissingAuditData++
			}
			return @() 
		}
		try { Profile-AuditData $auditData } catch {}
		# Ensure helper is available when re-entering session (PS alias scoping)
		if (-not (Get-Command Find-AllArrays -ErrorAction SilentlyContinue)) { Set-Alias -Name Find-AllArrays -Value Find-AllArrays -ErrorAction SilentlyContinue | Out-Null }

		$ced = Get-SafeProperty $auditData 'CopilotEventData'
		if (-not $ced) {
			# ── M code-aligned non-Copilot path: fixed 153-column extraction (no dynamic discovery) ──
			# Produces exactly 1 row per record with all 153 M code columns populated from AuditData.
			# No array explosion for non-Copilot records (matches M code behaviour).
			# DeviceProperties NV-pivot: only .OS and .BrowserType (matches M code GetNVProp).
			$recordId = if ($Record.RecordId) { $Record.RecordId } elseif ($Record.Identity) { $Record.Identity } elseif ($Record.Id) { $Record.Id } else { $auditData.Id }
			$creationDate = script:Format-DatePurviewFast $Record.CreationDate
			$creationTime = try { script:Format-DatePurviewFast $auditData.CreationTime } catch { '' }
			$opValue = try { $auditData.Operation } catch { if ($Record.Operation) { $Record.Operation } else { $Record.Operations } }
			$uidValue = try { $auditData.UserId } catch { if ($Record.UserId) { $Record.UserId } elseif ($Record.UserIds) { $Record.UserIds } else { '' } }
			$recordType = $Record.RecordType
			$resultStatus = Get-SafeProperty $auditData 'ResultStatus'
			$recordTypeNum = try { [int]$recordType } catch { $recordType }
			$applicationId = Select-FirstNonNull -Values @((Get-SafeProperty $auditData 'ApplicationId'), (Get-SafeProperty $auditData 'AppId'), (Get-SafeProperty $auditData 'ClientAppId'))
			# DeviceProperties NV-pivot: only .OS and .BrowserType (matches M code GetNVProp)
			$devProps = Get-SafeProperty $auditData 'DeviceProperties'
			$dpOS = ''; $dpBrowser = ''
			if ($devProps -and ($devProps -is [System.Collections.IEnumerable])) {
				foreach ($dp in $devProps) {
					try {
						if ($dp.Name -eq 'OS') { $dpOS = $dp.Value }
						elseif ($dp.Name -eq 'BrowserType') { $dpBrowser = $dp.Value }
					} catch {}
				}
			}
			# AgentCategory
			$agentIdVal = Get-SafeProperty $auditData 'AgentId'
			$agentCat = ''
			if ($agentIdVal) {
				if ($agentIdVal -like "CopilotStudio.Declarative.*") { $agentCat = "Declarative Agent" }
				elseif ($agentIdVal -like "CopilotStudio.CustomEngine.*") { $agentCat = "Custom Engine Agent" }
				elseif ($agentIdVal -like "P_*") { $agentCat = "Declarative Agent (Purview)" }
				else { $agentCat = "Other Agent" }
			}
			$rowObj = [PSCustomObject][ordered]@{
				RecordId                          = $recordId
				CreationDate                      = $creationDate
				RecordType                        = $recordType
				Operation                         = $opValue
				UserId                            = $uidValue
				AssociatedAdminUnits              = $(try { if ($Record.AssociatedAdminUnits) { $Record.AssociatedAdminUnits } elseif ($auditData.AssociatedAdminUnits) { $auditData.AssociatedAdminUnits } else { '' } } catch { '' })
				AssociatedAdminUnitsNames         = $(try { if ($Record.AssociatedAdminUnitsNames) { $Record.AssociatedAdminUnitsNames } elseif ($auditData.AssociatedAdminUnitsNames) { $auditData.AssociatedAdminUnitsNames } else { '' } } catch { '' })
				'@odata.type'                     = (Get-SafeProperty $auditData '@odata.type')
				CreationTime                      = $creationTime
				Id                                = (Get-SafeProperty $auditData 'Id')
				OrganizationId                    = (Get-SafeProperty $auditData 'OrganizationId')
				ResultStatus                      = $resultStatus
				UserKey                           = (Get-SafeProperty $auditData 'UserKey')
				UserType                          = (Get-SafeProperty $auditData 'UserType')
				Version                           = (Get-SafeProperty $auditData 'Version')
				Workload                          = (Get-SafeProperty $auditData 'Workload')
				ClientIP                          = (Get-SafeProperty $auditData 'ClientIP')
				ObjectId                          = (Get-SafeProperty $auditData 'ObjectId')
				AzureActiveDirectoryEventType     = (Get-SafeProperty $auditData 'AzureActiveDirectoryEventType')
				ActorContextId                    = (Get-SafeProperty $auditData 'ActorContextId')
				ActorIpAddress                    = (Get-SafeProperty $auditData 'ActorIpAddress')
				InterSystemsId                    = (Get-SafeProperty $auditData 'InterSystemsId')
				IntraSystemId                     = (Get-SafeProperty $auditData 'IntraSystemId')
				SupportTicketId                   = (Get-SafeProperty $auditData 'SupportTicketId')
				TargetContextId                   = (Get-SafeProperty $auditData 'TargetContextId')
				ApplicationId                     = $applicationId
				'DeviceProperties.OS'             = $dpOS
				'DeviceProperties.BrowserType'    = $dpBrowser
				ErrorNumber                       = (Get-SafeProperty $auditData 'ErrorNumber')
				SiteUrl                           = (Get-SafeProperty $auditData 'SiteUrl')
				SourceRelativeUrl                 = (Get-SafeProperty $auditData 'SourceRelativeUrl')
				SourceFileName                    = (Get-SafeProperty $auditData 'SourceFileName')
				SourceFileExtension               = (Get-SafeProperty $auditData 'SourceFileExtension')
				ListId                            = (Get-SafeProperty $auditData 'ListId')
				ListItemUniqueId                  = (Get-SafeProperty $auditData 'ListItemUniqueId')
				WebId                             = (Get-SafeProperty $auditData 'WebId')
				ApplicationDisplayName            = (Get-SafeProperty $auditData 'ApplicationDisplayName')
				EventSource                       = (Get-SafeProperty $auditData 'EventSource')
				ItemType                          = (Get-SafeProperty $auditData 'ItemType')
				SiteSensitivityLabelId            = (Get-SafeProperty $auditData 'SiteSensitivityLabelId')
				GeoLocation                       = (Get-SafeProperty $auditData 'GeoLocation')
				IsManagedDevice                   = (Get-SafeProperty $auditData 'IsManagedDevice')
				DeviceDisplayName                 = (Get-SafeProperty $auditData 'DeviceDisplayName')
				ListBaseType                      = (Get-SafeProperty $auditData 'ListBaseType')
