				TokenType                         = (Get-SafeProperty $auditData 'TokenType')
				SaveToSentItems                   = (Get-SafeProperty $auditData 'SaveToSentItems')
				OperationCount                    = (Get-SafeProperty $auditData 'OperationCount')
				FileSizeBytes                     = (Get-SafeProperty $auditData 'FileSizeBytes')
				MeetingId                         = (Get-SafeProperty $auditData 'MeetingId')
				MeetingType                       = (Get-SafeProperty $auditData 'MeetingType')
				EventSignature                    = (Get-SafeProperty $auditData 'EventSignature')
				EventData                         = (Get-SafeProperty $auditData 'EventData')
				Permission                        = (Get-SafeProperty $auditData 'Permission')
				SensitivityLabelId                = (Get-SafeProperty $auditData 'SensitivityLabelId')
				SharingLinkScope                  = (Get-SafeProperty $auditData 'SharingLinkScope')
				TargetUserOrGroupType             = (Get-SafeProperty $auditData 'TargetUserOrGroupType')
				TargetUserOrGroupName             = (Get-SafeProperty $auditData 'TargetUserOrGroupName')
				MeetingURL                        = (Get-SafeProperty $auditData 'MeetingURL')
				ChatId                            = (Get-SafeProperty $auditData 'ChatId')
				MessageId                         = (Get-SafeProperty $auditData 'MessageId')
				MessageSizeInBytes                = (Get-SafeProperty $auditData 'MessageSizeInBytes')
				MessageType                       = (Get-SafeProperty $auditData 'MessageType')
				FormId                            = (Get-SafeProperty $auditData 'FormId')
				FormName                          = (Get-SafeProperty $auditData 'FormName')
				VideoId                           = (Get-SafeProperty $auditData 'VideoId')
				VideoName                         = (Get-SafeProperty $auditData 'VideoName')
				ChannelId                         = (Get-SafeProperty $auditData 'ChannelId')
				ViewDuration                      = (Get-SafeProperty $auditData 'ViewDuration')
				ClientRegion                      = (Get-SafeProperty $auditData 'ClientRegion')
				CopilotLogVersion                 = (Get-SafeProperty $auditData 'CopilotLogVersion')
				TargetId                          = (Get-SafeProperty $auditData 'TargetId')
				TeamName                          = (Get-SafeProperty $auditData 'TeamName')
				TeamGuid                          = (Get-SafeProperty $auditData 'TeamGuid')
				ResponseId                        = (Get-SafeProperty $auditData 'ResponseId')
				IsAnonymous                       = (Get-SafeProperty $auditData 'IsAnonymous')
				DeviceType                        = (Get-SafeProperty $auditData 'DeviceType')
				ChannelName                       = (Get-SafeProperty $auditData 'ChannelName')
				ChannelGuid                       = (Get-SafeProperty $auditData 'ChannelGuid')
				ChannelType                       = (Get-SafeProperty $auditData 'ChannelType')
				AppName                           = (Get-SafeProperty $auditData 'AppName')
				EnvironmentName                   = (Get-SafeProperty $auditData 'EnvironmentName')
				PlanId                            = (Get-SafeProperty $auditData 'PlanId')
				PlanName                          = (Get-SafeProperty $auditData 'PlanName')
				TaskId                            = (Get-SafeProperty $auditData 'TaskId')
				TaskName                          = (Get-SafeProperty $auditData 'TaskName')
				PercentComplete                   = (Get-SafeProperty $auditData 'PercentComplete')
				CrossMailboxOperation             = (Get-SafeProperty $auditData 'CrossMailboxOperation')
				RecordTypeNum                     = $recordTypeNum
				ResultStatus_Audit                = $resultStatus
				ModelId                           = (Get-SafeProperty $auditData 'ModelId')
				ModelProvider                     = (Get-SafeProperty $auditData 'ModelProvider')
				ModelFamily                       = (Get-SafeProperty $auditData 'ModelFamily')
				TokensTotal                       = (Get-SafeProperty $auditData 'TokensTotal')
				TokensInput                       = (Get-SafeProperty $auditData 'TokensInput')
				TokensOutput                      = (Get-SafeProperty $auditData 'TokensOutput')
				DurationMs                        = (Get-SafeProperty $auditData 'DurationMs')
				OutcomeStatus                     = (Get-SafeProperty $auditData 'OutcomeStatus')
				ConversationId                    = (Get-SafeProperty $auditData 'ConversationId')
				TurnNumber                        = (Get-SafeProperty $auditData 'TurnNumber')
				RetryCount                        = (Get-SafeProperty $auditData 'RetryCount')
				ClientVersion                     = (Get-SafeProperty $auditData 'ClientVersion')
				ClientPlatform                    = (Get-SafeProperty $auditData 'ClientPlatform')
				AgentId                           = $agentIdVal
				AgentName                         = (Get-SafeProperty $auditData 'AgentName')
				AgentVersion                      = (Get-SafeProperty $auditData 'AgentVersion')
				AgentCategory                     = $agentCat
				ApplicationName                   = (Get-SafeProperty $auditData 'ApplicationName')
				SensitivityLabel                  = (Get-SafeProperty $auditData 'SensitivityLabel')
				# CED sub-fields — empty for non-Copilot records
				AppHost                           = ''
				ThreadId                          = ''
				Context_Id                        = ''
				Context_Type                      = ''
				Message_Id                        = ''
				Message_isPrompt                  = ''
				AccessedResource_Action           = ''
				AccessedResource_PolicyDetails    = ''
				AccessedResource_SiteUrl          = ''
				AISystemPlugin_Id                 = ''
				AISystemPlugin_Name               = ''
				ModelTransparencyDetails_ModelName = ''
				MessageIds                        = ''
				AccessedResource_Name             = ''
				AccessedResource_SensitivityLabel = ''
				AccessedResource_ResourceType     = ''
				Context_Item                      = ''
			}
			if ($Deep) {
				# Deep flatten entire AuditData for each row (no raw JSON)
				$flatAudit = ConvertTo-FlatColumns -Node $auditData -Prefix '' -MaxDepth $FlatDepthDeep
				foreach ($k in $flatAudit.Keys) { if (-not $rowObj.PSObject.Properties[$k]) { Add-Member -InputObject $rowObj -NotePropertyName $k -NotePropertyValue $flatAudit[$k] -Force } }
			}
			return @($rowObj)
		}
		$messages = script:GetArrayFast $ced 'Messages'
		if ($PromptFilterValue) {
			$filteredMessages = New-Object System.Collections.Generic.List[object]
			if ($PromptFilterValue -eq 'Null') {
				foreach ($msg in $messages) { if ($null -eq $msg.isPrompt) { $filteredMessages.Add($msg) } }
			}
			elseif ($PromptFilterValue -eq 'Both') {
				foreach ($msg in $messages) { if ($null -ne $msg.isPrompt) { $filteredMessages.Add($msg) } }
			}
			else {
				$targetValue = ($PromptFilterValue -eq 'Prompt')
				foreach ($msg in $messages) { try { if ($msg.isPrompt -eq $targetValue) { $filteredMessages.Add($msg) } } catch {} }
			}
			$messages = $filteredMessages
			if ($messages.Count -eq 0) { 
				if (-not $SkipMetrics) {
					$script:metrics.FilteringSkippedRecords++
					$script:metrics.FilteringPromptFiltered++
				}
				return @() 
			}
		}
		$contexts = script:GetArrayFast $ced 'Contexts'
		$resources = script:GetArrayFast $ced 'AccessedResources'
		$pluginsRaw = script:GetArrayFast $ced 'AISystemPlugin'
		$modelDetRaw = script:GetArrayFast $ced 'ModelTransparencyDetails'
		$messageIds = script:GetArrayFast $ced 'MessageIds'
		
		# DSPM for AI: Extract SensitivityLabels array
		$sensitivityLabels = script:GetArrayFast $ced 'SensitivityLabels'
		
		# DSPM for AI: Determine activity type for conditional 2-level explosion
		$activityType = try { $auditData.Operation } catch { $null }
		
		# DSPM for AI: Extract 2nd-level arrays (for full explosion mode)
		$plugins = $null
		$recordingSessions = $null
		$contextItems = $null
		
		if (-not $PartialExplode) {
			# Full explosion mode: Extract 2nd-level arrays for row count calculation
			if ($activityType -eq 'ConnectedAIAppInteraction' -and $appIdentityRaw) {
				$plugins = script:GetArrayFast $appIdentityRaw 'Plugins'
			}
			if ($activityType -eq 'CopilotInteraction' -and $contexts.Count -gt 0) {
				# Find max Items[] count across all Contexts
				$maxItemsCount = 0
				foreach ($ctx in $contexts) {
					if ($ctx) {
						$items = script:GetArrayFast $ctx 'Items'
						if ($items -and $items.Count -gt $maxItemsCount) {
							$maxItemsCount = $items.Count
						}
					}
				}
				if ($maxItemsCount -gt 0) {
					$contextItems = $maxItemsCount  # Store count for row calculation
				}
			}
		}
		
		if ($PromptFilterValue) { $rowCount = [Math]::Max(1, $messages.Count) } else { 
			# DSPM for AI: Include all arrays in row count calculation (including AISystemPlugin and ModelTransparencyDetails)
			$arrayCounts = @(1, $messages.Count, $contexts.Count, $resources.Count, $sensitivityLabels.Count, $pluginsRaw.Count, $modelDetRaw.Count)
			
			# Full explosion: include 2nd-level arrays in row count
			if (-not $PartialExplode) {
				if ($plugins) { $arrayCounts += $plugins.Count }
				if ($recordingSessions) { $arrayCounts += $recordingSessions.Count }
				if ($contextItems) { $arrayCounts += $contextItems }
			}
			
			$rowCount = ($arrayCounts | Measure-Object -Maximum).Maximum 
		}
		# Removed $plugin0 and $model0 - now using indexed access in row loop for full explosion
		$creationDate = script:Format-DatePurviewFast $Record.CreationDate
		$creationTime = try { script:Format-DatePurviewFast $auditData.CreationTime } catch { '' }
		$appIdentityRaw = (Select-FirstNonNull -Values @((Get-SafeProperty $auditData 'AppIdentity'), (Get-SafeProperty $ced 'AppIdentity')))
		$applicationId = Select-FirstNonNull -Values @((Get-SafeProperty $auditData 'ApplicationId'), (Get-SafeProperty $auditData 'AppId'), (Get-SafeProperty $auditData 'ClientAppId'))
		# DeviceProperties NV-pivot: only .OS and .BrowserType (matches M code GetNVProp)
		$devProps = Get-SafeProperty $auditData 'DeviceProperties'
		$dpOS = ''; $dpBrowser = ''
		if ($devProps -and ($devProps -is [System.Collections.IEnumerable])) {
			foreach ($dp in $devProps) {
				try {
					if ($dp.Name -eq 'OS') { $dpOS = $dp.Value }
					elseif ($dp.Name -eq 'BrowserType') { $dpBrowser = $dp.Value }
				} catch {}
			}
		}
		$appHost = (Select-FirstNonNull -Values @((Get-SafeProperty $ced 'AppHost'), (Get-SafeProperty $auditData 'AppHost'), (Get-SafeProperty $auditData 'Workload')))
		$clientRegion = (Get-SafeProperty $auditData 'ClientRegion')
		$agentId = (Get-SafeProperty $auditData 'AgentId')
		$agentName = (Get-SafeProperty $auditData 'AgentName')
		$agentVersion = (Select-FirstNonNull -Values @((Get-SafeProperty $auditData 'AgentVersion'), (Get-SafeProperty $ced 'AgentVersion'), (Get-SafeProperty $ced 'Version')))
		
		# Agent categorization based on AgentId pattern
		$agentCategory = ""
		if ($agentId) {
			if ($agentId -like "CopilotStudio.Declarative.*") {
				$agentCategory = "Declarative Agent"
			} elseif ($agentId -like "CopilotStudio.CustomEngine.*") {
				$agentCategory = "Custom Engine Agent"
			} elseif ($agentId -like "P_*") {
				$agentCategory = "Declarative Agent (Purview)"
			} elseif ($agentId) {
				$agentCategory = "Other Agent"
			}
		}
		
	# With -IncludeUserInfo, license data now appears only in EntraUsers output
	# (or in combined mode via left join)

	$appName = (Select-FirstNonNull -Values @((Get-SafeProperty $auditData 'ApplicationName'), (Get-SafeProperty $ced 'HostAppName'), (Get-SafeProperty $ced 'ClientAppName')))
		$threadId = (Get-SafeProperty $ced 'ThreadId')
		$auditUserKey = try { $auditData.UserKey } catch { $null }
		# $modelName moved to row loop for indexed access
		$clientIP = (Get-SafeProperty $auditData 'ClientIP')
		$organizationId = (Get-SafeProperty $auditData 'OrganizationId')
		$version = (Get-SafeProperty $auditData 'Version')
		$userType = (Get-SafeProperty $auditData 'UserType')
		$copilotLogVersion = (Get-SafeProperty $auditData 'CopilotLogVersion')
		$workload = (Get-SafeProperty $auditData 'Workload')
		
		# Extract fields to match ExplodeArrays output for Power BI compatibility
		$auditDataId = try { $auditData.Id } catch { $null }
		$recordTypeNum = try { $auditData.RecordType } catch { $null }
		$resultStatusAudit = try { $auditData.ResultStatus } catch { $null }
		$appId = try { $auditData.AppId } catch { $null }
		$clientAppId = try { $auditData.ClientAppId } catch { $null }
		$correlationId = try { $auditData.CorrelationId } catch { $null }
		
		# Model and token fields (same as ExplodeArrays)
		$modelId = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ModelId'), (Get-SafeProperty $ced 'ModelID'), (Get-SafeProperty $auditData 'ModelId'))
		$modelProvider = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ModelProvider'), (Get-SafeProperty $ced 'Provider'), (Get-SafeProperty $ced 'ModelVendor'))
		$modelFamily = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ModelFamily'), (Get-SafeProperty $ced 'ModelType'))
		$usageNode = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'Usage'), (Get-SafeProperty $ced 'TokenUsage'), (Get-SafeProperty $ced 'Tokens'), (Get-SafeProperty $auditData 'Usage'))
		$tokensTotal = $null; $tokensInput = $null; $tokensOutput = $null
		if ($usageNode) {
			function Local:Get-Num([object]$v) { if ($null -eq $v) { return $null }; try { if ($v -is [string] -and [string]::IsNullOrWhiteSpace($v)) { return $null }; return [double]$v } catch { return $null } }
			$tokensTotal = Local:Get-Num (Select-FirstNonNull -Values @((Get-SafeProperty $usageNode 'Total'), (Get-SafeProperty $usageNode 'TotalTokens'), (Get-SafeProperty $usageNode 'TokensTotal')))
			$tokensInput = Local:Get-Num (Select-FirstNonNull -Values @((Get-SafeProperty $usageNode 'Input'), (Get-SafeProperty $usageNode 'Prompt'), (Get-SafeProperty $usageNode 'InputTokens'), (Get-SafeProperty $usageNode 'TokensInput')))
			$tokensOutput = Local:Get-Num (Select-FirstNonNull -Values @((Get-SafeProperty $usageNode 'Output'), (Get-SafeProperty $usageNode 'Completion'), (Get-SafeProperty $usageNode 'OutputTokens'), (Get-SafeProperty $usageNode 'TokensOutput')))
		}
		if (-not $tokensTotal -and ($tokensInput -or $tokensOutput)) { try { $tokensTotal = ($tokensInput + $tokensOutput) } catch {} }
		
		# Duration, outcome, conversation fields (same as ExplodeArrays)
		function Local:Get-NumSafe([object]$v) { if ($null -eq $v) { return $null }; try { if ($v -is [string] -and [string]::IsNullOrWhiteSpace($v)) { return $null }; return [double]$v } catch { return $null } }
		$durationMs = Local:Get-NumSafe (Select-FirstNonNull -Values @((Get-SafeProperty $ced 'DurationMs'), (Get-SafeProperty $ced 'ElapsedMs'), (Get-SafeProperty $ced 'ProcessingTimeMs'), (Get-SafeProperty $ced 'LatencyMs')))
		$outcomeStatus = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'OutcomeStatus'), (Get-SafeProperty $ced 'Outcome'), (Get-SafeProperty $ced 'Result'), (Get-SafeProperty $ced 'Status'))
		if ($outcomeStatus -is [bool]) { $outcomeStatus = if ($outcomeStatus) { 'Success' } else { 'Failure' } }
		$conversationId = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ConversationId'), (Get-SafeProperty $ced 'ConversationID'), (Get-SafeProperty $ced 'SessionId'))
		$turnNumber = Local:Get-NumSafe (Select-FirstNonNull -Values @((Get-SafeProperty $ced 'TurnNumber'), (Get-SafeProperty $ced 'TurnIndex'), (Get-SafeProperty $ced 'MessageIndex')))
		$retryCount = Local:Get-NumSafe (Select-FirstNonNull -Values @((Get-SafeProperty $ced 'RetryCount'), (Get-SafeProperty $ced 'Retries')))
		$clientVersion = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ClientVersion'), (Get-SafeProperty $ced 'Version'), (Get-SafeProperty $ced 'Build'))
		$clientPlatform = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ClientPlatform'), (Get-SafeProperty $ced 'Platform'), (Get-SafeProperty $ced 'OS'))
		
		$baseSet = New-Object System.Collections.Generic.HashSet[string]; foreach ($c in $PurviewExplodedHeader) { $null = $baseSet.Add($c) }
		$rows = New-Object System.Collections.Generic.List[object]
		for ($i = 0; $i -lt $rowCount; $i++) {
			$rowObj = [PSCustomObject][ordered]@{
				RecordId                          = $(if ($Record.RecordId) { $Record.RecordId } elseif ($Record.Identity) { $Record.Identity } elseif ($Record.Id) { $Record.Id } else { $auditData.Id })
				CreationDate                      = $creationDate
				RecordType                        = $Record.RecordType
				Operation                         = $auditData.Operation
				UserId                            = $auditData.UserId
				AssociatedAdminUnits              = $(try { if ($Record.AssociatedAdminUnits) { $Record.AssociatedAdminUnits } elseif ($auditData.AssociatedAdminUnits) { $auditData.AssociatedAdminUnits } else { '' } } catch { '' })
				AssociatedAdminUnitsNames         = $(try { if ($Record.AssociatedAdminUnitsNames) { $Record.AssociatedAdminUnitsNames } elseif ($auditData.AssociatedAdminUnitsNames) { $auditData.AssociatedAdminUnitsNames } else { '' } } catch { '' })
				'@odata.type'                     = (Get-SafeProperty $auditData '@odata.type')
				CreationTime                      = $creationTime
				Id                                = $auditDataId
				OrganizationId                    = $organizationId
				ResultStatus                      = $resultStatusAudit
				UserKey                           = $auditUserKey
				UserType                          = $userType
				Version                           = $version
				Workload                          = $workload
				ClientIP                          = $clientIP
				ObjectId                          = (Get-SafeProperty $auditData 'ObjectId')
				AzureActiveDirectoryEventType     = (Get-SafeProperty $auditData 'AzureActiveDirectoryEventType')
				ActorContextId                    = (Get-SafeProperty $auditData 'ActorContextId')
				ActorIpAddress                    = (Get-SafeProperty $auditData 'ActorIpAddress')
				InterSystemsId                    = (Get-SafeProperty $auditData 'InterSystemsId')
				IntraSystemId                     = (Get-SafeProperty $auditData 'IntraSystemId')
				SupportTicketId                   = (Get-SafeProperty $auditData 'SupportTicketId')
				TargetContextId                   = (Get-SafeProperty $auditData 'TargetContextId')
				ApplicationId                     = $applicationId
				'DeviceProperties.OS'             = $dpOS
				'DeviceProperties.BrowserType'    = $dpBrowser
				ErrorNumber                       = (Get-SafeProperty $auditData 'ErrorNumber')
				SiteUrl                           = (Get-SafeProperty $auditData 'SiteUrl')
				SourceRelativeUrl                 = (Get-SafeProperty $auditData 'SourceRelativeUrl')
				SourceFileName                    = (Get-SafeProperty $auditData 'SourceFileName')
				SourceFileExtension               = (Get-SafeProperty $auditData 'SourceFileExtension')
				ListId                            = (Get-SafeProperty $auditData 'ListId')
				ListItemUniqueId                  = (Get-SafeProperty $auditData 'ListItemUniqueId')
				WebId                             = (Get-SafeProperty $auditData 'WebId')
				ApplicationDisplayName            = (Get-SafeProperty $auditData 'ApplicationDisplayName')
				EventSource                       = (Get-SafeProperty $auditData 'EventSource')
				ItemType                          = (Get-SafeProperty $auditData 'ItemType')
				SiteSensitivityLabelId            = (Get-SafeProperty $auditData 'SiteSensitivityLabelId')
				GeoLocation                       = (Get-SafeProperty $auditData 'GeoLocation')
				IsManagedDevice                   = (Get-SafeProperty $auditData 'IsManagedDevice')
				DeviceDisplayName                 = (Get-SafeProperty $auditData 'DeviceDisplayName')
				ListBaseType                      = (Get-SafeProperty $auditData 'ListBaseType')
				ListServerTemplate                = (Get-SafeProperty $auditData 'ListServerTemplate')
				AuthenticationType                = (Get-SafeProperty $auditData 'AuthenticationType')
				Site                              = (Get-SafeProperty $auditData 'Site')
				DoNotDistributeEvent              = (Get-SafeProperty $auditData 'DoNotDistributeEvent')
				HighPriorityMediaProcessing       = (Get-SafeProperty $auditData 'HighPriorityMediaProcessing')
				BrowserName                       = (Get-SafeProperty $auditData 'BrowserName')
				BrowserVersion                    = (Get-SafeProperty $auditData 'BrowserVersion')
				CorrelationId                     = $correlationId
				Platform                          = (Get-SafeProperty $auditData 'Platform')
				UserAgent                         = (Get-SafeProperty $auditData 'UserAgent')
				ActorInfoString                   = (Get-SafeProperty $auditData 'ActorInfoString')
				AppId                             = $appId
				AuthType                          = (Get-SafeProperty $auditData 'AuthType')
				ClientAppId                       = $clientAppId
				ClientIPAddress                   = (Get-SafeProperty $auditData 'ClientIPAddress')
				ClientInfoString                  = (Get-SafeProperty $auditData 'ClientInfoString')
				ExternalAccess                    = (Get-SafeProperty $auditData 'ExternalAccess')
				InternalLogonType                 = (Get-SafeProperty $auditData 'InternalLogonType')
				LogonType                         = (Get-SafeProperty $auditData 'LogonType')
				LogonUserSid                      = (Get-SafeProperty $auditData 'LogonUserSid')
				MailboxGuid                       = (Get-SafeProperty $auditData 'MailboxGuid')
				MailboxOwnerSid                   = (Get-SafeProperty $auditData 'MailboxOwnerSid')
				MailboxOwnerUPN                   = (Get-SafeProperty $auditData 'MailboxOwnerUPN')
				OrganizationName                  = (Get-SafeProperty $auditData 'OrganizationName')
				OriginatingServer                 = (Get-SafeProperty $auditData 'OriginatingServer')
				SessionId                         = (Get-SafeProperty $auditData 'SessionId')
				TokenObjectId                     = (Get-SafeProperty $auditData 'TokenObjectId')
				TokenTenantId                     = (Get-SafeProperty $auditData 'TokenTenantId')
				TokenType                         = (Get-SafeProperty $auditData 'TokenType')
				SaveToSentItems                   = (Get-SafeProperty $auditData 'SaveToSentItems')
				OperationCount                    = (Get-SafeProperty $auditData 'OperationCount')
				FileSizeBytes                     = (Get-SafeProperty $auditData 'FileSizeBytes')
				MeetingId                         = (Get-SafeProperty $auditData 'MeetingId')
				MeetingType                       = (Get-SafeProperty $auditData 'MeetingType')
				EventSignature                    = (Get-SafeProperty $auditData 'EventSignature')
				EventData                         = (Get-SafeProperty $auditData 'EventData')
				Permission                        = (Get-SafeProperty $auditData 'Permission')
				SensitivityLabelId                = (Get-SafeProperty $auditData 'SensitivityLabelId')
				SharingLinkScope                  = (Get-SafeProperty $auditData 'SharingLinkScope')
				TargetUserOrGroupType             = (Get-SafeProperty $auditData 'TargetUserOrGroupType')
				TargetUserOrGroupName             = (Get-SafeProperty $auditData 'TargetUserOrGroupName')
				MeetingURL                        = (Get-SafeProperty $auditData 'MeetingURL')
				ChatId                            = (Get-SafeProperty $auditData 'ChatId')
				MessageId                         = (Get-SafeProperty $auditData 'MessageId')
				MessageSizeInBytes                = (Get-SafeProperty $auditData 'MessageSizeInBytes')
				MessageType                       = (Get-SafeProperty $auditData 'MessageType')
				FormId                            = (Get-SafeProperty $auditData 'FormId')
				FormName                          = (Get-SafeProperty $auditData 'FormName')
				VideoId                           = (Get-SafeProperty $auditData 'VideoId')
				VideoName                         = (Get-SafeProperty $auditData 'VideoName')
				ChannelId                         = (Get-SafeProperty $auditData 'ChannelId')
				ViewDuration                      = (Get-SafeProperty $auditData 'ViewDuration')
				ClientRegion                      = $clientRegion
				CopilotLogVersion                 = $copilotLogVersion
				TargetId                          = (Get-SafeProperty $auditData 'TargetId')
				TeamName                          = (Get-SafeProperty $auditData 'TeamName')
				TeamGuid                          = (Get-SafeProperty $auditData 'TeamGuid')
				ResponseId                        = (Get-SafeProperty $auditData 'ResponseId')
				IsAnonymous                       = (Get-SafeProperty $auditData 'IsAnonymous')
				DeviceType                        = (Get-SafeProperty $auditData 'DeviceType')
				ChannelName                       = (Get-SafeProperty $auditData 'ChannelName')
				ChannelGuid                       = (Get-SafeProperty $auditData 'ChannelGuid')
				ChannelType                       = (Get-SafeProperty $auditData 'ChannelType')
				AppName                           = (Get-SafeProperty $auditData 'AppName')
				EnvironmentName                   = (Get-SafeProperty $auditData 'EnvironmentName')
				PlanId                            = (Get-SafeProperty $auditData 'PlanId')
				PlanName                          = (Get-SafeProperty $auditData 'PlanName')
				TaskId                            = (Get-SafeProperty $auditData 'TaskId')
				TaskName                          = (Get-SafeProperty $auditData 'TaskName')
				PercentComplete                   = (Get-SafeProperty $auditData 'PercentComplete')
				CrossMailboxOperation             = (Get-SafeProperty $auditData 'CrossMailboxOperation')
				RecordTypeNum                     = $(try { [int]$Record.RecordType } catch { $Record.RecordType })
				ResultStatus_Audit                = $resultStatusAudit
				ModelId                           = $modelId
				ModelProvider                     = $modelProvider
				ModelFamily                       = $modelFamily
				TokensTotal                       = $tokensTotal
				TokensInput                       = $tokensInput
				TokensOutput                      = $tokensOutput
				DurationMs                        = $durationMs
				OutcomeStatus                     = $outcomeStatus
				ConversationId                    = $conversationId
				TurnNumber                        = $turnNumber
				RetryCount                        = $retryCount
				ClientVersion                     = $clientVersion
				ClientPlatform                    = $clientPlatform
				AgentId                           = $agentId
				AgentName                         = $agentName
				AgentVersion                      = $agentVersion
				AgentCategory                     = $agentCategory
				ApplicationName                   = (Get-SafeProperty $auditData 'ApplicationName')
				SensitivityLabel                  = $(if ($i -lt $sensitivityLabels.Count) { try { [string]$sensitivityLabels[$i] } catch { '' } } else { '' })
				AppHost                           = $appHost
				ThreadId                          = $threadId
				Context_Id                        = $(if ($i -lt $contexts.Count -and $contexts[$i]) { try { Get-SafeProperty $contexts[$i] 'Id' } catch { '' } } else { '' })
				Context_Type                      = $(if ($i -lt $contexts.Count -and $contexts[$i]) { try { Get-SafeProperty $contexts[$i] 'Type' } catch { '' } } else { '' })
				Message_Id                        = $(if ($i -lt $messages.Count) { $msg = $messages[$i]; if ($msg -is [psobject]) { try { Get-SafeProperty $msg 'Id' } catch { '' } } else { $msg } } else { '' })
				Message_isPrompt                  = $(if ($i -lt $messages.Count) { $msg = $messages[$i]; if ($msg -is [psobject]) { try { script:BoolTFFast (Get-SafeProperty $msg 'isPrompt') } catch { '' } } else { '' } } else { '' })
				AccessedResource_Action           = $(if ($i -lt $resources.Count -and $resources[$i]) { try { Get-SafeProperty $resources[$i] 'Action' } catch { '' } } else { '' })
				AccessedResource_PolicyDetails    = $(if ($i -lt $resources.Count -and $resources[$i]) { try { script:ToJsonIfObjectFast (Get-SafeProperty $resources[$i] 'PolicyDetails') } catch { '' } } else { '' })
				AccessedResource_SiteUrl          = $(if ($i -lt $resources.Count -and $resources[$i]) { try { Get-SafeProperty $resources[$i] 'SiteUrl' } catch { '' } } else { '' })
				AISystemPlugin_Id                 = $(if ($i -lt $pluginsRaw.Count -and $pluginsRaw[$i]) { try { Get-SafeProperty $pluginsRaw[$i] 'Id' } catch { '' } } else { '' })
				AISystemPlugin_Name               = $(if ($i -lt $pluginsRaw.Count -and $pluginsRaw[$i]) { try { Get-SafeProperty $pluginsRaw[$i] 'Name' } catch { '' } } else { '' })
				ModelTransparencyDetails_ModelName = $(if ($i -lt $modelDetRaw.Count -and $modelDetRaw[$i]) { try { Get-SafeProperty $modelDetRaw[$i] 'ModelName' } catch { '' } } else { '' })
				MessageIds                        = $(if ($messageIds.Count -gt 0) { $messageIds -join ';' } else { '' })
				AccessedResource_Name             = $(if ($i -lt $resources.Count -and $resources[$i]) { try { Get-SafeProperty $resources[$i] 'Name' } catch { '' } } else { '' })
				AccessedResource_SensitivityLabel = $(if ($i -lt $resources.Count -and $resources[$i]) { try { Get-SafeProperty $resources[$i] 'SensitivityLabel' } catch { '' } } else { '' })
				AccessedResource_ResourceType     = $(if ($i -lt $resources.Count -and $resources[$i]) { try { Get-SafeProperty $resources[$i] 'ResourceType' } catch { '' } } else { '' })
				Context_Item                      = $(
					if ($activityType -eq 'CopilotInteraction') {
						if ($PartialExplode) {
							if ($i -lt $contexts.Count -and $contexts[$i]) {
								try {
									$items = script:GetArrayFast $contexts[$i] 'Items'
									if ($items -and $items.Count -gt 0) {
										($items | ForEach-Object { try { script:ToJsonIfObjectFast $_ } catch { '' } }) -join ';'
									} else { '' }
								} catch { '' }
							} else { '' }
						} else {
							try {
								$foundItem = $null
								foreach ($ctx in $contexts) {
									if ($ctx) {
										$items = script:GetArrayFast $ctx 'Items'
										if ($items -and $i -lt $items.Count) {
											$foundItem = $items[$i]
											break
										}
									}
								}
								if ($foundItem) { script:ToJsonIfObjectFast $foundItem } else { '' }
							} catch { '' }
						}
					} else { '' }
				)
			}
			
			# Partial explosion mode: Preserve AuditData column (full JSON) for downstream processing
			if ($PartialExplode) {
				try {
					Add-Member -InputObject $rowObj -NotePropertyName 'AuditData' -NotePropertyValue $Record.AuditData -Force
				} catch {}
			}
			
			# DSPM for AI: 2-level explosion for ConnectedAIAppInteraction (AppIdentity.Plugins[])
			if ($activityType -eq 'ConnectedAIAppInteraction' -and $plugins) {
				try {
					if ($PartialExplode) {
						# Partial mode: Semi-colon-joined JSON for all plugins
						$pluginsList = ($plugins | ForEach-Object { try { script:ToJsonIfObjectFast $_ } catch { '' } }) -join ';'
						if (-not $rowObj.PSObject.Properties['AppIdentity_Plugins']) {
							Add-Member -InputObject $rowObj -NotePropertyName 'AppIdentity_Plugins' -NotePropertyValue $pluginsList -Force
							if (-not $script:DeepExtraColumns.Contains('AppIdentity_Plugins')) { [void]$script:DeepExtraColumns.Add('AppIdentity_Plugins') }
						}
					} else {
						# Full mode: One plugin per row
						if ($i -lt $plugins.Count) {
							$plugin = $plugins[$i]
							$pluginJson = try { script:ToJsonIfObjectFast $plugin } catch { '' }
							if (-not $rowObj.PSObject.Properties['AppIdentity_Plugin']) {
								Add-Member -InputObject $rowObj -NotePropertyName 'AppIdentity_Plugin' -NotePropertyValue $pluginJson -Force
								if (-not $script:DeepExtraColumns.Contains('AppIdentity_Plugin')) { [void]$script:DeepExtraColumns.Add('AppIdentity_Plugin') }
							}
						}
					}
				} catch {}
			}
			
			if ($Deep) {
				if ($ced) {
					$flat = ConvertTo-FlatColumns -Node $ced -Prefix '' -MaxDepth $FlatDepthDeep
					foreach ($k in $flat.Keys) { if ($baseSet.Contains($k)) { continue }; if (-not $rowObj.PSObject.Properties[$k]) { if (-not $script:DeepExtraColumns.Contains($k)) { [void]$script:DeepExtraColumns.Add($k) }; try { Add-Member -InputObject $rowObj -NotePropertyName $k -NotePropertyValue $flat[$k] -Force } catch {} } }
				}
				if ($auditData) {
					$auditDataClone = [PSCustomObject]@{}
					foreach ($prop in $auditData.PSObject.Properties) { if ($prop.Name -ne 'CopilotEventData') { Add-Member -InputObject $auditDataClone -NotePropertyName $prop.Name -NotePropertyValue $prop.Value -Force } }
					$flatAudit = ConvertTo-FlatColumns -Node $auditDataClone -Prefix '' -MaxDepth $FlatDepthDeep
					foreach ($k in $flatAudit.Keys) { if ($baseSet.Contains($k)) { continue }; if (-not $rowObj.PSObject.Properties[$k]) { if (-not $script:DeepExtraColumns.Contains($k)) { [void]$script:DeepExtraColumns.Add($k) }; try { Add-Member -InputObject $rowObj -NotePropertyName $k -NotePropertyValue $flatAudit[$k] -Force } catch {} } }
				}
			}
			$rows.Add($rowObj) | Out-Null
		}
		if (-not $SkipMetrics -and $rows.Count -gt 1) { try { $script:metrics.ExplosionEvents += 1; $script:metrics.ExplosionRowsFromEvents += ($rows.Count - 1); if ($rows.Count -gt $script:metrics.ExplosionMaxPerRecord) { $script:metrics.ExplosionMaxPerRecord = $rows.Count } } catch {} }
		return $rows
	}
	catch { 
		if (-not $SkipMetrics) {
			$script:metrics.FilteringSkippedRecords++
			$script:metrics.FilteringParseFailures++
		}
		Write-LogHost "Failed Purview explosion: $($_.Exception.Message)" -ForegroundColor Red
		return @() 
	}
}

function Select-FirstNonNull { param([object[]]$Values) foreach ($v in $Values) { if ($null -ne $v -and ('' -ne [string]$v)) { return $v } } return $null }

function Convert-ToStructuredRecord {
	# Uses proven stable implementation for record conversion
	param(
		[Parameter(Mandatory = $true)] $Record,
		[bool]$EnableExplosion = $false
	)
	try {
		function Local:Get-Num([object]$v) { if ($null -eq $v) { return $null }; try { if ($v -is [string] -and [string]::IsNullOrWhiteSpace($v)) { return $null }; return [double]$v } catch { return $null } }
		function Local:Add-OrUpdate([pscustomobject]$obj, [string]$name, $value) { try { if ($obj.PSObject.Properties[$name]) { $obj.PSObject.Properties[$name].Value = $value } else { Add-Member -InputObject $obj -NotePropertyName $name -NotePropertyValue $value -Force } } catch {} }
		# Use pre-parsed AuditData if available
		$auditData = if ($Record.PSObject.Properties['_ParsedAuditData']) { $Record._ParsedAuditData } else { try { $Record.AuditData | ConvertFrom-Json -ErrorAction Stop } catch { $null } }
		if (-not $auditData) { 
			$script:metrics.FilteringSkippedRecords++
			$script:metrics.FilteringMissingAuditData++
			return @() 
		}
		
		# NON-EXPLOSION MODE: Return 8-column compact record matching Purview UI export schema
		if (-not $EnableExplosion -and -not $ExplodeDeep) {
			$compactRecord = [pscustomobject]@{
				RecordId               = $(if ($Record.RecordId) { $Record.RecordId } elseif ($Record.Identity) { $Record.Identity } elseif ($Record.Id) { $Record.Id } else { $auditData.Id })
				CreationDate           = $Record.CreationDate.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture)
				RecordType             = $Record.RecordType
				Operation              = $(try { $auditData.Operation } catch { if ($Record.Operation) { $Record.Operation } else { $Record.Operations } })
				UserId                 = if ($Record.UserId) { $Record.UserId } elseif ($Record.UserIds) { $Record.UserIds } else { '' }
				AuditData              = $Record.AuditData
				AssociatedAdminUnits      = $(try { if ($auditData.AssociatedAdminUnits) { $auditData.AssociatedAdminUnits } elseif ($Record.AssociatedAdminUnits) { $Record.AssociatedAdminUnits } else { '' } } catch { '' })
				AssociatedAdminUnitsNames = $(try { if ($auditData.AssociatedAdminUnitsNames) { $auditData.AssociatedAdminUnitsNames } elseif ($Record.AssociatedAdminUnitsNames) { $Record.AssociatedAdminUnitsNames } else { '' } } catch { '' })
			}
			return @($compactRecord)
		}
		
		# EXPLOSION MODE: Extract and flatten all fields from AuditData (no raw JSON columns)
		$ced = Get-SafeProperty $auditData 'CopilotEventData'
		$modelId = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ModelId'), (Get-SafeProperty $ced 'ModelID'), (Get-SafeProperty $auditData 'ModelId'))
		$modelProvider = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ModelProvider'), (Get-SafeProperty $ced 'Provider'), (Get-SafeProperty $ced 'ModelVendor'))
		$modelFamily = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ModelFamily'), (Get-SafeProperty $ced 'ModelType'))
		$usageNode = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'Usage'), (Get-SafeProperty $ced 'TokenUsage'), (Get-SafeProperty $ced 'Tokens'), (Get-SafeProperty $auditData 'Usage'))
		$tokensTotal = $null; $tokensInput = $null; $tokensOutput = $null
		if ($usageNode) {
			$tokensTotal = Local:Get-Num (Select-FirstNonNull -Values @((Get-SafeProperty $usageNode 'Total'), (Get-SafeProperty $usageNode 'TotalTokens'), (Get-SafeProperty $usageNode 'TokensTotal')))
			$tokensInput = Local:Get-Num (Select-FirstNonNull -Values @((Get-SafeProperty $usageNode 'Input'), (Get-SafeProperty $usageNode 'Prompt'), (Get-SafeProperty $usageNode 'InputTokens'), (Get-SafeProperty $usageNode 'TokensInput')))
			$tokensOutput = Local:Get-Num (Select-FirstNonNull -Values @((Get-SafeProperty $usageNode 'Output'), (Get-SafeProperty $usageNode 'Completion'), (Get-SafeProperty $usageNode 'OutputTokens'), (Get-SafeProperty $usageNode 'TokensOutput')))
		}
		if (-not $tokensTotal -and ($tokensInput -or $tokensOutput)) { try { $tokensTotal = ($tokensInput + $tokensOutput) } catch {} }
		$durationMs = Local:Get-Num (Select-FirstNonNull -Values @((Get-SafeProperty $ced 'DurationMs'), (Get-SafeProperty $ced 'ElapsedMs'), (Get-SafeProperty $ced 'ProcessingTimeMs'), (Get-SafeProperty $ced 'LatencyMs')))
		$outcomeStatus = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'OutcomeStatus'), (Get-SafeProperty $ced 'Outcome'), (Get-SafeProperty $ced 'Result'), (Get-SafeProperty $ced 'Status'))
		if ($outcomeStatus -is [bool]) { $outcomeStatus = if ($outcomeStatus) { 'Success' } else { 'Failure' } }
		$conversationId = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ConversationId'), (Get-SafeProperty $ced 'ConversationID'), (Get-SafeProperty $ced 'SessionId'))
		$turnNumber = Local:Get-Num (Select-FirstNonNull -Values @((Get-SafeProperty $ced 'TurnNumber'), (Get-SafeProperty $ced 'TurnIndex'), (Get-SafeProperty $ced 'MessageIndex')))
		$retryCount = Local:Get-Num (Select-FirstNonNull -Values @((Get-SafeProperty $ced 'RetryCount'), (Get-SafeProperty $ced 'Retries')))
		$clientVersion = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ClientVersion'), (Get-SafeProperty $ced 'Version'), (Get-SafeProperty $ced 'Build'))
		$clientPlatform = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ClientPlatform'), (Get-SafeProperty $ced 'Platform'), (Get-SafeProperty $ced 'OS'))
		$agentId = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'AgentId'), (Get-SafeProperty $ced 'AgentID'), (Get-SafeProperty $ced 'AssistantId'))
		$agentName = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'AgentName'), (Get-SafeProperty $ced 'AssistantName'))
		$agentVersion = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'AgentVersion'), (Get-SafeProperty $ced 'Version'))
		
		# Agent categorization based on AgentId pattern
		$agentCategory = ""
		if ($agentId) {
			if ($agentId -like "CopilotStudio.Declarative.*") {
				$agentCategory = "Declarative Agent"
			} elseif ($agentId -like "CopilotStudio.CustomEngine.*") {
				$agentCategory = "Custom Engine Agent"
			} elseif ($agentId -like "P_*") {
				$agentCategory = "Declarative Agent (Purview)"
			} elseif ($agentId) {
				$agentCategory = "Other Agent"
			}
		}
		
	# With -IncludeUserInfo, license data now appears only in EntraUsers output
	# (or in combined mode via left join)

	$appIdentity = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'AppIdentity'), (Get-SafeProperty $ced 'ApplicationId'), (Get-SafeProperty $ced 'HostAppId'))
		$applicationName = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'ApplicationName'), (Get-SafeProperty $ced 'HostAppName'), (Get-SafeProperty $ced 'ClientAppName'))
		$suggestions = (Get-SafeProperty $ced 'Suggestions'); if (-not $suggestions) { $suggestions = Get-SafeProperty $ced 'SuggestionList' }
		$actions = Get-SafeProperty $ced 'Actions'
		$references = Select-FirstNonNull -Values @((Get-SafeProperty $ced 'References'), (Get-SafeProperty $ced 'Sources'), (Get-SafeProperty $ced 'Citations'))
		$participants = Get-SafeProperty $ced 'Participants'
		function Local:Measure-Collection($items, [string]$prefix) {
			$result = @{}; if (-not $items) { return $result }; $arr = @($items); if ($arr.Count -eq 0) { return $result }
			$result["${prefix}Count"] = $arr.Count; $types = New-Object System.Collections.Generic.HashSet[string]; $latencies = @(); $edits = @(); $accepted = 0; $success = 0; $failure = 0
			foreach ($s in $arr) {
				foreach ($cand in @('Type', 'SuggestionType', 'Name', 'Kind', 'ActionType')) { try { if ($s.PSObject.Properties[$cand]) { [void]$types.Add([string]$s.$cand); break } } catch {} }
				foreach ($lat in @('LatencyMs', 'DurationMs', 'ElapsedMs')) { try { if ($s.PSObject.Properties[$lat]) { $v = Local:Get-Num $s.$lat; if ($null -ne $v) { $latencies += $v; break } } } catch {} }
				foreach ($ed in @('EditCount', 'Edits', 'EditsCount')) { try { if ($s.PSObject.Properties[$ed]) { $v = Local:Get-Num $s.$ed; if ($null -ne $v) { $edits += $v; break } } } catch {} }
				foreach ($acc in @('Accepted', 'IsAccepted', 'Success', 'Succeeded')) { try { if ($s.PSObject.Properties[$acc]) { $val = $s.$acc; if ($val -is [bool]) { if ($val) { $accepted++ } } elseif ($val -match '^(?i:true|yes|1|success)') { $accepted++ } } } catch {} }
				foreach ($succ in @('Success', 'Succeeded')) { try { if ($s.PSObject.Properties[$succ]) { $val = $s.$succ; if ($val -is [bool]) { if ($val) { $success++ } else { $failure++ } } elseif ($val -match '^(?i:true|yes|1|success)') { $success++ } else { $failure++ } } } catch {} }
			}
			if ($types.Count -gt 0) { $result["${prefix}Types"] = [string]::Join(';', [array]$types) }
			if ($latencies.Count -gt 0) { $result["${prefix}AvgLatencyMs"] = [math]::Round(($latencies | Measure-Object -Average).Average, 2) }
			if ($edits.Count -gt 0) { $result["${prefix}AvgEdits"] = [math]::Round(($edits | Measure-Object -Average).Average, 2); $result["${prefix}TotalEdits"] = ($edits | Measure-Object -Sum).Sum }
			if ($accepted -gt 0) { $result["${prefix}Accepted"] = $accepted; $result["${prefix}AcceptanceRate"] = [math]::Round(($accepted / $arr.Count) * 100, 2) }
			if ($success -gt 0 -or $failure -gt 0) { $result["${prefix}Success"] = $success; $result["${prefix}Failure"] = $failure }
			return $result
		}
		$suggestAgg = Local:Measure-Collection $suggestions 'Suggestions'
		$actionAgg = Local:Measure-Collection $actions 'Actions'
		$refAgg = Local:Measure-Collection $references 'References'
		$partAgg = Local:Measure-Collection $participants 'Participants'
		$baseRecord = [pscustomobject]@{
			RecordId           = $(if ($Record.RecordId) { $Record.RecordId } elseif ($Record.Identity) { $Record.Identity } elseif ($Record.Id) { $Record.Id } else { $auditData.Id })
			RecordType         = $Record.RecordType
			CreationDate       = $Record.CreationDate.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture)
			ResultStatus       = $Record.ResultStatus
			ResultCount        = $Record.ResultCount
			Identity           = $Record.Identity
			IsValid            = $Record.IsValid
			ObjectState        = $Record.ObjectState
			Id                 = $auditData.Id
			CreationTime       = & { $ct = script:Parse-DateSafe $auditData.CreationTime; if ($ct) { $ct.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture) } else { $auditData.CreationTime } }
			Operation          = $auditData.Operation
			OrganizationId     = $auditData.OrganizationId
			RecordTypeNum      = $auditData.RecordType
			ResultStatus_Audit = $auditData.ResultStatus
			UserKey            = $auditData.UserKey
			UserType           = $auditData.UserType
			Version            = $auditData.Version
			Workload           = $auditData.Workload
			UserId             = $auditData.UserId
			AppId              = $auditData.AppId
			ClientAppId        = $auditData.ClientAppId
			CorrelationId      = $auditData.CorrelationId
			ModelId            = $modelId
			ModelProvider      = $modelProvider
			ModelFamily        = $modelFamily
			TokensTotal        = $tokensTotal
			TokensInput        = $tokensInput
			TokensOutput       = $tokensOutput
			DurationMs         = $durationMs
			OutcomeStatus      = $outcomeStatus
			ConversationId     = $conversationId
			TurnNumber         = $turnNumber
			RetryCount         = $retryCount
			ClientVersion      = $clientVersion
			ClientPlatform     = $clientPlatform
			AgentId            = $agentId
			AgentName          = $agentName
			AgentVersion       = $agentVersion
			AgentCategory      = $agentCategory
			AppIdentity        = $appIdentity
			ApplicationName    = $applicationName
		}
		# Flatten AppAccessContext for Copilot/AI records as well
		try {
			$aac = Get-SafeProperty $auditData 'AppAccessContext'
			if ($aac -and -not (Test-ScalarValue $aac)) {
				$flatAac = ConvertTo-FlatColumns -Node $aac -Prefix 'AppAccessContext.' -MaxDepth $FlatDepthStandard
				foreach ($k in $flatAac.Keys) { if (-not $baseRecord.PSObject.Properties[$k]) { Add-Member -InputObject $baseRecord -NotePropertyName $k -NotePropertyValue $flatAac[$k] -Force } }
				if ($baseRecord.PSObject.Properties['AppAccessContext']) { $baseRecord.PSObject.Members.Remove('AppAccessContext') }
			}
			elseif ($aac -and (Test-ScalarValue $aac)) {
				if (-not $baseRecord.PSObject.Properties['AppAccessContext']) { Add-Member -InputObject $baseRecord -NotePropertyName 'AppAccessContext' -NotePropertyValue $aac -Force }
			}
		} catch {}
		foreach ($k in $suggestAgg.Keys) { Add-OrUpdate $baseRecord $k $suggestAgg[$k] }
		foreach ($k in $actionAgg.Keys) { Add-OrUpdate $baseRecord $k $actionAgg[$k] }
		foreach ($k in $refAgg.Keys) { Add-OrUpdate $baseRecord $k $refAgg[$k] }
		foreach ($k in $partAgg.Keys) { Add-OrUpdate $baseRecord $k $partAgg[$k] }
		
		# If not doing array explosion, return base record now
		if (-not $EnableExplosion) { return @($baseRecord) }
		$rows = @($baseRecord)
		$arraysToExplode = @(
			@{ Name = 'Suggestions'; Data = $suggestions; Prefix = 'Suggestion'; Enabled = $suggestions },
			@{ Name = 'Actions'; Data = $actions; Prefix = 'Action'; Enabled = $actions },
			@{ Name = 'References'; Data = $references; Prefix = 'Reference'; Enabled = $references },
			@{ Name = 'Participants'; Data = $participants; Prefix = 'Participant'; Enabled = $participants }
		)
		$maxRows = $ExplosionPerRecordRowCap
		foreach ($entry in $arraysToExplode) {
			if (-not $entry.Enabled) { continue }
			$dataArr = @($entry.Data); if ($dataArr.Count -eq 0) { continue }
			$newRows = New-Object System.Collections.ArrayList
			foreach ($r in $rows) {
				$idx = 0
				foreach ($el in $dataArr) {
					$nr = [pscustomobject]@{}
					foreach ($p in $r.PSObject.Properties) { Add-Member -InputObject $nr -NotePropertyName $p.Name -NotePropertyValue $p.Value -Force }
					Add-OrUpdate $nr ("ArrayIndex_{0}" -f $entry.Name) $idx
					if ($el) {
						foreach ($prop in $el.PSObject.Properties) {
							$pname = ("{0}_{1}" -f $entry.Prefix, $prop.Name)
							if ($nr.PSObject.Properties[$pname]) { continue }
							$val = $prop.Value
							if (Test-ScalarValue $val) { Add-OrUpdate $nr $pname $val } else { try { Add-OrUpdate $nr $pname ($val | ConvertTo-Json -Depth $JsonDepth -Compress) } catch {} }
						}
					}
					[void]$newRows.Add($nr); $idx++
					if ($newRows.Count -gt $maxRows) { break }
				}
				if ($newRows.Count -gt $maxRows) { break }
			}
			$rows = @($newRows)
			if ($rows.Count -gt $maxRows) { break }
		}
		if ($rows.Count -gt $maxRows) { foreach ($r in $rows) { Add-OrUpdate $r 'ExplosionTruncated' $true }; $rows = $rows[0..($maxRows - 1)]; try { $script:metrics.ExplosionTruncated = $true } catch {} }
		if ($ExplodeDeep -and $ced) {
			for ($i = 0; $i -lt $rows.Count; $i++) {
				$r = $rows[$i]
				$flat = ConvertTo-FlatColumns -Node $ced -Prefix '' -MaxDepth $FlatDepthStandard
				foreach ($ck in $flat.Keys) { if (-not $r.PSObject.Properties[$ck]) { Add-OrUpdate $r $ck $flat[$ck] } }
			}
		}
		return $rows
	}
	catch { 
		$script:metrics.FilteringSkippedRecords++
		$script:metrics.FilteringParseFailures++
		Write-LogHost "Failed to process record: $($_.Exception.Message)" -ForegroundColor Red
		return @() 
	}
}

try {
	# Unregister the early exit handler since catch/finally will handle Ctrl+C from this point
	# This prevents duplicate "Script Interrupted" messages
	Unregister-Event -SourceIdentifier PowerShell.Exiting -ErrorAction SilentlyContinue
	
	# ============================================================
	# RESUME MODE VALIDATION - Ensure no conflicting parameters
	# ============================================================
	if ($ResumeSpecified) {
		# Resume mode is standalone - only auth-related parameters allowed
		$allowedWithResume = @(
			'Resume',
			'RemainingArgs',
			'Force',
			'UserIds',
			'GroupNames',
			'Auth',
			'TenantId',
			'ClientId',
			'ClientSecret',
			'Dashboard',
			'OutputPathDefenderUsage',
			'AppendDefenderUsage',
			'DisableAISIDDeltaCache',
			'ClearUncertainCreate',
			'ClearUncertainContract',
			'ClientCertificateThumbprint',
			'ClientCertificateStoreLocation',
			'ClientCertificatePath',
			'ClientCertificatePassword',
			# Standard PowerShell common parameters
			'Verbose',
			'Debug',
			'ErrorAction',
			'WarningAction',
			'InformationAction',
			'ErrorVariable',
			'WarningVariable',
			'InformationVariable',
			'OutVariable',
			'OutBuffer',
			'PipelineVariable'
		)
		
		$invalidParams = @($PSBoundParameters.Keys | Where-Object { $_ -notin $allowedWithResume })
		
		if ($invalidParams.Count -gt 0) {
			Write-Host ""
			Write-Host "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
			Write-Host "  ERROR: Invalid parameters used with -Resume" -ForegroundColor Red
			Write-Host "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
			Write-Host ""
			Write-Host "  Resume mode restores ALL settings from the checkpoint file." -ForegroundColor Yellow
			Write-Host "  You cannot specify other parameters (they would be ignored or cause inconsistency)." -ForegroundColor Yellow
			Write-Host ""
			Write-Host "  Invalid parameters:" -ForegroundColor White
			foreach ($p in $invalidParams) {
				Write-Host "    - $p" -ForegroundColor Red
			}
			Write-Host ""
			Write-Host "  ALLOWED with -Resume:" -ForegroundColor Green
			Write-Host "    -Resume [path]      Checkpoint file (or auto-discover)" -ForegroundColor Gray
			Write-Host "    -Force              Use most recent checkpoint without prompting" -ForegroundColor Gray
			Write-Host "    -Auth               Override authentication method" -ForegroundColor Gray
			Write-Host "    -TenantId           Tenant ID (for AppRegistration)" -ForegroundColor Gray
			Write-Host "    -ClientId           Client ID (for AppRegistration)" -ForegroundColor Gray
			Write-Host "    -ClientSecret       Client secret (for AppRegistration)" -ForegroundColor Gray
			Write-Host "    -UserIds            Override the checkpoint's user scope (fail-closed)" -ForegroundColor Gray
			Write-Host "    -GroupNames         Override the checkpoint's group scope (fail-closed)" -ForegroundColor Gray
			Write-Host '    .\Script.ps1 -Resume' -ForegroundColor White
			Write-Host '    .\Script.ps1 -Resume -Auth DeviceCode' -ForegroundColor White
			Write-Host '    .\Script.ps1 -Resume "C:\path\.pax_checkpoint_xxx.json" -Force' -ForegroundColor White
			Write-Host ""
			exit 1
		}
	}
	
	# ============================================================
	# RESUME MODE DETECTION - Check for checkpoint to resume
	# ============================================================
	if ($ResumeSpecified) {
		Write-LogHost ""
		Write-LogHost "========================================" -ForegroundColor Cyan
		Write-LogHost "  RESUME MODE DETECTED" -ForegroundColor Cyan
		Write-LogHost "========================================" -ForegroundColor Cyan
		Write-LogHost ""
		
		if ($Resume -ne '') {
			# Explicit checkpoint path provided
			Write-LogHost "Loading checkpoint from explicit path: $Resume" -ForegroundColor Yellow
			$checkpointLoadSuccess = Read-Checkpoint -CheckpointPath $Resume
			if (-not $checkpointLoadSuccess) {
				Write-LogHost "ERROR: Failed to load checkpoint file. Cannot resume." -ForegroundColor Red
				exit 1
			}
			$script:CheckpointPath = $Resume
			# Lock the resumed checkpoint so a second replica cannot race on it.
			try { script:Acquire-CheckpointLock -CheckpointPath $script:CheckpointPath } catch {
				Write-LogHost ("ERROR: {0}" -f $_.Exception.Message) -ForegroundColor Red
				exit 1
			}
			# Read-Checkpoint sets $script:CheckpointData on success
			$checkpointData = $script:CheckpointData
		}
		else {
			# Auto-discover checkpoints in OutputPath
			$searchPath = if ($OutputPath) { $OutputPath } else { (Get-Location).Path }

			# Fabric tier: resume artifacts are mirrored to OneLake Files/.pax_resume/
			# inside each Save-CheckpointToDisk call so a container restart can resume.
			# Hydrate the local search path from the mirror before Find-Checkpoints runs.
			# Local and SharePoint tiers keep artifacts local-only — those hosts are not
			# ephemeral and a remote prefetch would be needless I/O.
			if ($script:DestTier -and $script:DestTier['Purview'] -eq 'Fabric') {
				try {
					$restored = Restore-AllFabricResumeMirrors -LocalDir $searchPath
					if ($restored -gt 0) {
						Write-LogHost "Hydrated $restored resume artifact(s) from OneLake mirror" -ForegroundColor DarkGray
					}
				} catch {
					# A hydration failure is an INTEGRITY signal, not a hint: the mirror
					# exposed an authority record whose artifact set could not be proven, or
					# it could not be read at all. Continuing to checkpoint discovery here
					# would search a directory that either holds stale local state or holds
					# nothing, and could silently resume the wrong state. Stop non-zero and
					# distinguish this from the ordinary "no remote generation exists" case,
					# which returns 0 and is not an error.
					Write-LogHost ("ERROR: Resume mirror hydration failed - resume cannot continue: {0}" -f $_.Exception.Message) -ForegroundColor Red
					Write-LogHost "  No checkpoint was hydrated from the remote mirror, and no partial resume state was left behind." -ForegroundColor Gray
					exit 1
				}
			}

			Write-LogHost "Searching for checkpoints in: $searchPath" -ForegroundColor Yellow
			
			$checkpoints = Find-Checkpoints -OutputPath $searchPath
			
			if ($checkpoints.Count -eq 0) {
				Write-LogHost ""
				Write-LogHost "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
				Write-LogHost "  NO CHECKPOINT FILES FOUND" -ForegroundColor Red
				Write-LogHost "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
				Write-LogHost ""
				Write-LogHost "  Searched in: $searchPath" -ForegroundColor White
				Write-LogHost ""
				Write-LogHost "  Checkpoint files are named: .pax_checkpoint_YYYYMMDD_HHMMSS.json" -ForegroundColor Gray
				Write-LogHost "  They are saved in the same folder as the _PARTIAL.csv output file." -ForegroundColor Gray
				Write-LogHost ""
				Write-LogHost "  COMMON LOCATIONS TO CHECK:" -ForegroundColor Yellow
				Write-LogHost "    • The 'output' folder where you typically save exports" -ForegroundColor White
				Write-LogHost "    • The folder shown in the Ctrl+C message when the run was interrupted" -ForegroundColor White
				Write-LogHost "    • Look for _PARTIAL.csv files - the checkpoint is in the same folder" -ForegroundColor White
				Write-LogHost ""
				Write-LogHost "  HOW TO RESUME:" -ForegroundColor Cyan
				Write-LogHost ""
				Write-LogHost "    Option 1: Specify the folder containing the checkpoint:" -ForegroundColor White
				Write-LogHost "      -Resume -OutputPath `"C:\path\to\output\folder`"" -ForegroundColor Green
				Write-LogHost ""
				Write-LogHost "    Option 2: Specify the checkpoint file directly:" -ForegroundColor White
				Write-LogHost "      -Resume `"C:\path\to\.pax_checkpoint_20260120_123456.json`"" -ForegroundColor Green
				Write-LogHost ""
				Write-LogHost "    Option 3: Run from the folder containing the checkpoint:" -ForegroundColor White
				Write-LogHost "      cd `"C:\path\to\output\folder`"" -ForegroundColor Green
				Write-LogHost "      pwsh -File `"...\PAX_Purview_Audit_Log_Processor.ps1`" -Resume" -ForegroundColor Green
				Write-LogHost ""
				Write-LogHost "════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
				Write-LogHost ""
				exit 1
			}
			elseif ($checkpoints.Count -eq 1) {
				$selectedCheckpoint = $checkpoints[0]
				Write-LogHost "Found checkpoint: $($selectedCheckpoint.FileName)" -ForegroundColor Green
			}
			else {
				# Multiple checkpoints found
				if ($Force) {
					# Use most recent without prompting
					$selectedCheckpoint = $checkpoints | Sort-Object { $_.LastUpdated } -Descending | Select-Object -First 1
					Write-LogHost "Multiple checkpoints found. -Force specified, using most recent:" -ForegroundColor Yellow
					Write-LogHost "  $($selectedCheckpoint.FileName)" -ForegroundColor White
				}
				else {
					# Prompt user to select
					$selectedCheckpoint = Select-Checkpoint -Checkpoints $checkpoints
					if (-not $selectedCheckpoint) {
						Write-LogHost "No checkpoint selected. Exiting." -ForegroundColor Yellow
						exit 0
					}
				}
			}
			
			$script:CheckpointPath = $selectedCheckpoint.Path
			# Lock the resumed checkpoint so a second replica cannot race on it.
			try { script:Acquire-CheckpointLock -CheckpointPath $script:CheckpointPath } catch {
				Write-LogHost ("ERROR: {0}" -f $_.Exception.Message) -ForegroundColor Red
				exit 1
			}
			$checkpointLoadSuccess = Read-Checkpoint -CheckpointPath $script:CheckpointPath
			if (-not $checkpointLoadSuccess) {
				Write-LogHost "ERROR: Failed to load checkpoint file. Cannot resume." -ForegroundColor Red
				exit 1
			}
			# Read-Checkpoint sets $script:CheckpointData on success
			$checkpointData = $script:CheckpointData
		}
		
		# Note: $script:CheckpointData and $script:IsResumeMode already set by Read-Checkpoint
		
		# Operator-only SELECTIVE recovery: when -ClearUncertainCreate is supplied it carries an
		# explicit list of partition indexes to recover. Validate the selection against the
		# durable uncertain-create set NOW (pre-auth): an empty, duplicate, unknown, or
		# out-of-range selection is REJECTED and nothing is cleared. A valid selection is only
		# STAGED here - the durable marker for a selected partition is cleared selectively and
		# atomically later, at the parent-create reconcile, and ONLY after a READ-ONLY
		# exact-name reconcile confirms the query is not visible (a still-visible selected
		# partition is adopted, never cleared into a duplicate POST). Durable uncertain state is
		# never auto-cleared by elapsed time, a collection miss, a process restart, or a failure count.
		$script:ClearUncertainSelection = [System.Collections.Generic.HashSet[int]]::new()
		if ($PSBoundParameters.ContainsKey('ClearUncertainCreate')) {
			$clearSelection = Clear-PaxUncertainCreateState -CheckpointData $script:CheckpointData -Requested:$true -SelectedIndexes $ClearUncertainCreate -ValidateOnly
			if ($clearSelection.Rejected) {
				Write-LogHost ""
				Write-LogHost "  ERROR: -ClearUncertainCreate selection rejected - $($clearSelection.Reason). No uncertain-create state was changed." -ForegroundColor Red
				$script:ResumeValidationFailed = $true
				exit 1
			}
			foreach ($selIdx in @($clearSelection.Selected)) { [void]$script:ClearUncertainSelection.Add([int]$selIdx) }
			Write-LogHost "  [RESUME] -ClearUncertainCreate: $($script:ClearUncertainSelection.Count) partition(s) selected for recovery; each is reconciled READ-ONLY first and only cleared for a fresh create if not visible by exact name." -ForegroundColor Yellow
		}
		# EXPLICIT-CONTRACT companion (-ClearUncertainContract): each "<index>:<fingerprint>"
		# token names EXACTLY one durable uncertain contract, disambiguating an index that maps
		# to more than one. Validated NOW (pre-auth) against the durable set: a malformed,
		# unknown, multiply-matching, or duplicate token is REJECTED and nothing is cleared. A
		# valid selection is only STAGED here - the durable marker is cleared selectively and
		# atomically later, at the reconcile, and ONLY after a READ-ONLY exact-name reconcile
		# confirms the selected contract is not visible (a still-visible contract is adopted,
		# never cleared into a duplicate POST).
		$script:ClearUncertainContractSelection = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
		if ($PSBoundParameters.ContainsKey('ClearUncertainContract')) {
			$contractSelection = Clear-PaxUncertainCreateState -CheckpointData $script:CheckpointData -Requested:$true -SelectedContracts $ClearUncertainContract -ValidateOnly
			if ($contractSelection.Rejected) {
				Write-LogHost ""
				Write-LogHost "  ERROR: -ClearUncertainContract selection rejected - $($contractSelection.Reason). No uncertain-create state was changed." -ForegroundColor Red
				$script:ResumeValidationFailed = $true
				exit 1
			}
			foreach ($selTok in @($contractSelection.SelectedContracts)) { [void]$script:ClearUncertainContractSelection.Add([string]$selTok) }
			Write-LogHost "  [RESUME] -ClearUncertainContract: $($script:ClearUncertainContractSelection.Count) contract(s) selected for recovery; each is reconciled READ-ONLY first and only cleared for a fresh create if not visible by exact name." -ForegroundColor Yellow
		}
		
		# Display resume summary
		$completedCount = if ($checkpointData.partitions.completed) { $checkpointData.partitions.completed.Count } else { 0 }
		$queryCreatedCount = if ($checkpointData.partitions.queryCreated) { $checkpointData.partitions.queryCreated.Count } else { 0 }
		$totalPartitions = if ($checkpointData.partitions.total) { $checkpointData.partitions.total } else { 0 }
		
		Write-LogHost ""
		Write-LogHost "Checkpoint loaded successfully:" -ForegroundColor Green
		Write-LogHost "  Original Run:       $($checkpointData.runTimestamp)" -ForegroundColor White
		$cpStartDate = if ($checkpointData.parameters.startDate) { $d = script:Parse-DateSafe $checkpointData.parameters.startDate; if ($d) { $d.ToLocalTime().ToString('yyyy-MM-dd') } else { 'Unknown' } } else { 'Unknown' }
		$cpEndDate = if ($checkpointData.parameters.endDate) { $d = script:Parse-DateSafe $checkpointData.parameters.endDate; if ($d) { $d.ToLocalTime().ToString('yyyy-MM-dd') } else { 'Unknown' } } else { 'Unknown' }
		Write-LogHost "  Date Range:         $cpStartDate to $cpEndDate" -ForegroundColor White
		Write-LogHost "  Total Partitions:   $totalPartitions" -ForegroundColor White
		Write-LogHost "  Completed:          $completedCount" -ForegroundColor Green
		Write-LogHost "  Query Created:      $queryCreatedCount (will attempt data fetch)" -ForegroundColor Yellow
		Write-LogHost "  Remaining:          $($totalPartitions - $completedCount)" -ForegroundColor Cyan
		Write-LogHost ""
		
		# ============================================================
		# RESTORE ALL PARAMETERS FROM CHECKPOINT
		# ============================================================
		Write-LogHost "Restoring parameters from checkpoint..." -ForegroundColor DarkGray
		$cp = $checkpointData.parameters
		$script:ResumeValidationFailed = $true
		# ============================================================
		# AISID resume validation. Runs BEFORE the dashboard/window
		# restore below so it sets $Dashboard authoritatively and stops the rollup-dashboard
		# restore from overriding an AISID resume. Reads raw checkpoint fields and
		# enforces conflicts/requirements NONINTERACTIVELY (exit 1; never Read-Host).
		# $checkpointData / $cp are hashtables (ConvertFrom-Json -AsHashtable).
		# ============================================================
		$script:ResumeIsAISID = $false
		$script:AISIDResumeForceCacheMiss = $false
		$script:ResumeAISIDClass = $null
		$hasAisidWindow = [bool]$checkpointData.aisidWindow
		$markerRaw = if ($checkpointData.Contains('aisidResumeStateVersion')) { $checkpointData.aisidResumeStateVersion } else { $null }
		if ($null -ne $markerRaw -and [string]$markerRaw -ne '1') { Write-LogHost "ERROR: this checkpoint carries an unsupported AISID resume-state version ($markerRaw); this build supports version 1 only." -ForegroundColor Red; exit 1 }
		$hasMarker = ($markerRaw -eq 1)
		$cpDashboard = if ($cp.Contains('dashboard')) { [string]$cp.dashboard } else { $null }
		$cpRollupDash = if ($cp.Contains('rollupDashboard')) { [string]$cp.rollupDashboard } else { $null }
		$cliDash = if ($PSBoundParameters.ContainsKey('Dashboard')) { [string]$Dashboard } else { $null }
		$cliOut = $PSBoundParameters.ContainsKey('OutputPathDefenderUsage')
		$cliApp = $PSBoundParameters.ContainsKey('AppendDefenderUsage')
		if ($hasMarker -and $cpDashboard -eq 'AISID') {
			$Dashboard = 'AISID'; $script:ResumeIsAISID = $true; $script:ResumeAISIDClass = 'Complete'
			if ($cliDash) { Write-LogHost "ERROR: resume dashboard conflict - this checkpoint already stores its dashboard; -Dashboard cannot be supplied on resume for it. Omit -Dashboard." -ForegroundColor Red; exit 1 }
			if ($cliOut -or $cliApp) { Write-LogHost "ERROR: resume DefenderUsage destination conflict - this checkpoint already stores its AISID DefenderUsage destination; do not pass -OutputPathDefenderUsage or -AppendDefenderUsage on resume." -ForegroundColor Red; exit 1 }
			if ($PSBoundParameters.ContainsKey('DisableAISIDDeltaCache')) { Write-LogHost "ERROR: resume cache conflict - this checkpoint already stores the AISID delta-cache setting; do not pass -DisableAISIDDeltaCache on resume." -ForegroundColor Red; exit 1 }
			Write-LogHost "  Resume: restoring the AISID dashboard, DefenderUsage destination, cache state, and frozen collection window from the checkpoint." -ForegroundColor Cyan
		}
		elseif ($hasAisidWindow -and -not $hasMarker -and ($null -eq $cpDashboard)) {
			$Dashboard = 'AISID'; $script:ResumeIsAISID = $true; $script:ResumeAISIDClass = 'Transitional'; $script:AISIDResumeForceCacheMiss = $true
			if ($cliDash -and $cliDash -ne 'AISID') { Write-LogHost "ERROR: resume dashboard conflict - this AISID checkpoint can only resume as AISID; -Dashboard $cliDash is not allowed." -ForegroundColor Red; exit 1 }
			if (-not ($cliOut -xor $cliApp)) { Write-LogHost "ERROR: this AISID checkpoint has no stored DefenderUsage destination; supply EXACTLY ONE of -OutputPathDefenderUsage or -AppendDefenderUsage on the resume command line (not both, not neither)." -ForegroundColor Red; exit 1 }
			Write-LogHost "  Resume: this AISID checkpoint has no stored DefenderUsage destination; using the destination supplied on the command line and forcing a delta-cache miss." -ForegroundColor Cyan
		}
		elseif (-not $hasAisidWindow -and ($null -eq $cpDashboard) -and ($cpRollupDash -eq 'AIO')) {
			if (-not $cliDash) { Write-LogHost "ERROR: this older checkpoint is ambiguous - it could be an AIO run or an AISID run. Re-run with -Dashboard AIO, or -Dashboard AISID plus exactly one of -OutputPathDefenderUsage or -AppendDefenderUsage." -ForegroundColor Red; exit 1 }
			elseif ($cliDash -eq 'AIO') {
				$Dashboard = 'AIO'; $script:ResumeIsAISID = $false
				if ($cliOut -or $cliApp) { Write-LogHost "ERROR: -OutputPathDefenderUsage and -AppendDefenderUsage are not valid with -Dashboard AIO." -ForegroundColor Red; exit 1 }
				Write-LogHost "  Resume: dashboard resolved to AIO from the command line." -ForegroundColor Cyan
			}
			elseif ($cliDash -eq 'AISID') {
				$Dashboard = 'AISID'; $script:ResumeIsAISID = $true; $script:ResumeAISIDClass = 'LegacyAISID'; $script:AISIDResumeForceCacheMiss = $true
				if (-not ($cliOut -xor $cliApp)) { Write-LogHost "ERROR: resuming this checkpoint as AISID requires EXACTLY ONE of -OutputPathDefenderUsage or -AppendDefenderUsage (not both, not neither)." -ForegroundColor Red; exit 1 }
				Write-LogHost "  Resume: dashboard resolved to AISID from the command line; the collection window is reconstructed from the checkpoint dates and creation time, and a delta-cache miss is forced." -ForegroundColor Cyan
			}
			else { Write-LogHost "ERROR: -Dashboard $cliDash is not a valid choice for resuming this ambiguous checkpoint (use AIO or AISID)." -ForegroundColor Red; exit 1 }
		}
		
		# ============================================================
		# AISID AVAILABILITY GATE - restored checkpoint state
		# Runs immediately after the AISID resume classification above and before any
		# further parameter restoration, destination re-resolution, remote probe,
		# checkpoint mutation, sign-in, collection, or publication. A checkpoint that
		# restores the AISID dashboard, an AISID DefenderUsage output or append
		# destination, or the AISID delta-cache setting stops here, so stored state
		# cannot reach a gated AISID execution path. The checkpoint lock is released
		# first so a gated resume leaves nothing behind. $cp is the checkpoint
		# parameter block that the restore below reads for these same values.
		# ============================================================
		$aisidResumeDashboard = ($script:ResumeIsAISID -or (([string]$Dashboard).Trim().ToUpperInvariant() -eq 'AISID') -or (($null -ne $cpDashboard) -and (([string]$cpDashboard).Trim().ToUpperInvariant() -eq 'AISID')))
		$aisidResumeOutput    = ($cp.Contains('outputPathDefenderUsage') -and -not [string]::IsNullOrWhiteSpace([string]$cp.outputPathDefenderUsage))
		$aisidResumeAppend    = ($cp.Contains('appendDefenderUsage') -and -not [string]::IsNullOrWhiteSpace([string]$cp.appendDefenderUsage))
		$aisidResumeCache     = ($cp.Contains('disableAISIDDeltaCache') -and [bool]$cp.disableAISIDDeltaCache)
		if (script:Test-AISIDEntryPointGated -DashboardIsAISID $aisidResumeDashboard -DefenderUsageOutputRequested $aisidResumeOutput -DefenderUsageAppendRequested $aisidResumeAppend -DeltaCacheSwitchRequested $aisidResumeCache) {
			try { script:Release-CheckpointLock } catch { }
			exit 1
		}
		
		# Restore original run timestamp so incremental files use consistent naming
		# This ensures all partition files (original run + resumes) share the same timestamp
		if ($checkpointData.runTimestamp) {
			$global:ScriptRunTimestamp = $checkpointData.runTimestamp
			Write-LogHost "  Restored original run timestamp: $($global:ScriptRunTimestamp)" -ForegroundColor DarkGray
		}
		
		# Date range (required) - using locale-safe parsing
		$parsedStart = script:Parse-DateSafe $cp.startDate
		if (-not $parsedStart) { throw "Failed to parse checkpoint startDate: $($cp.startDate)" }
		# Checkpoint stores the date as a UTC instant (local midnight -> ToUniversalTime at save).
		# Parse-DateSafe returns a UTC-kind value, so convert back to local before formatting the
		# calendar date; otherwise positive-UTC-offset hosts (e.g. IST) render the prior day,
		# shifting the trim window by one day on resume.
		$StartDate = $parsedStart.ToLocalTime().ToString('yyyy-MM-dd')
		
		$parsedEnd = script:Parse-DateSafe $cp.endDate
		if (-not $parsedEnd) { throw "Failed to parse checkpoint endDate: $($cp.endDate)" }
		# See StartDate note above: convert the UTC-kind parse result back to local before
		# formatting so the restored end date matches the originally requested calendar date.
		$EndDate = $parsedEnd.ToLocalTime().ToString('yyyy-MM-dd')
		
		# Activity/Record filtering
		if ($cp.activityTypes -and $cp.activityTypes.Count -gt 0) { $ActivityTypes = $cp.activityTypes }
		if ($cp.recordTypes -and $cp.recordTypes.Count -gt 0) { $RecordTypes = $cp.recordTypes }
		if ($cp.serviceTypes -and $cp.serviceTypes.Count -gt 0) { $ServiceTypes = $cp.serviceTypes }
		if (-not $PSBoundParameters.ContainsKey('UserIds') -and $cp.userIds -and $cp.userIds.Count -gt 0) { $UserIds = $cp.userIds }
		if (-not $PSBoundParameters.ContainsKey('GroupNames') -and $cp.groupNames -and $cp.groupNames.Count -gt 0) { $GroupNames = $cp.groupNames }
		
		# Agent filtering
		if ($cp.agentId -and $cp.agentId.Count -gt 0) { $AgentId = $cp.agentId }
		if ($cp.agentsOnly) { $AgentsOnly = [switch]$true }
		if ($cp.excludeAgents) { $ExcludeAgents = [switch]$true }
		
		# Prompt filtering
		if ($cp.promptFilter) { $PromptFilter = $cp.promptFilter }
		
		# Schema/Explosion settings
		if ($cp.explodeArrays) { $ExplodeArrays = [switch]$true }
		if ($cp.explodeDeep) { $ExplodeDeep = [switch]$true }
		if ($cp.flatDepth) { $FlatDepth = $cp.flatDepth }
		if ($cp.streamingSchemaSample) { $StreamingSchemaSample = $cp.streamingSchemaSample }
		if ($cp.streamingChunkSize) { $StreamingChunkSize = $cp.streamingChunkSize }
		# Allow user to override explosion threads on resume (different machine/load)
		if (-not $PSBoundParameters.ContainsKey('ExplosionThreads') -and $cp.explosionThreads) { $ExplosionThreads = $cp.explosionThreads }
		
		# M365/User info bundles
		if ($cp.includeM365Usage) { $IncludeM365Usage = [switch]$true }
		if ($cp.includeUserInfo) { $IncludeUserInfo = [switch]$true }
		if ($cp.Contains('includeDSPMForAI') -and $cp.includeDSPMForAI) {
			Write-LogHost "Resume checkpoint references legacy -IncludeDSPMForAI switch; ignoring (no longer supported)." -ForegroundColor Yellow
		}
		if ($cp.includeCopilotInteraction) { $IncludeCopilotInteraction = [switch]$true }
		if ($cp.excludeCopilotInteraction) { $ExcludeCopilotInteraction = [switch]$true }
		if ($cp.includeAgent365Info) { $IncludeAgent365Info = [switch]$true }
		# Note: onlyAgent365Info is intentionally not restored on resume - it would imply
		# no audit phase to resume from. Original validation blocks -OnlyAgent365Info + -Resume.
		
		# Partitioning
		if ($cp.blockHours) { $BlockHours = $cp.blockHours }
		if ($cp.partitionHours) { $PartitionHours = $cp.partitionHours }
		if ($cp.maxPartitions) { $MaxPartitions = $cp.maxPartitions }
		
		# Output settings
		if ($cp.outputPath) { $OutputPath = $cp.outputPath }
		if ($cp.exportWorkbook) { $ExportWorkbook = [switch]$true }
		if ($cp.combineOutput) { $CombineOutput = [switch]$true }
		# Deidentify is checkpoint-driven on resume (the resume allow-list blocks it on the
		# command line), so restore it here as the sole source of truth for a resumed run.
		if ($cp.Contains('deidentify') -and $cp.deidentify) { $Deidentify = [switch]$true; $script:PaxDeidEnabled = $true }
		if ($cp.Contains('verifyPartitionStability') -and $cp.verifyPartitionStability) { $VerifyPartitionStability = [switch]$true }

		# -UserInfoSupplement (hybrid directory enrichment) is checkpoint-driven on resume so the original
		# supplemental input is reused. An explicit resume override with a DIFFERENT value fails clearly; a
		# matching value is accepted. Only the source path/URL is restored - no supplemental values are stored.
		if ($cp.Contains('userInfoSupplement') -and $cp.userInfoSupplement) {
			$cpUis = [string]$cp.userInfoSupplement
			if ($PSBoundParameters.ContainsKey('UserInfoSupplement') -and -not [string]::IsNullOrWhiteSpace($UserInfoSupplement) -and ($UserInfoSupplement.Trim() -ne $cpUis.Trim())) {
				Write-Host ""
				Write-Host "ERROR: -UserInfoSupplement was supplied on the resume command line with a value that differs from the original run." -ForegroundColor Red
				Write-Host ("  Original: {0}" -f $cpUis) -ForegroundColor Yellow
				Write-Host ("  Provided: {0}" -f $UserInfoSupplement.Trim()) -ForegroundColor Yellow
				Write-Host "  A resumed run reuses the original supplemental input; omit -UserInfoSupplement on resume." -ForegroundColor Yellow
				Write-Host ""
				exit 1
			}
			$UserInfoSupplement = $cpUis
			$script:UserInfoSupplementActive = $true
		}

		# FillerLabel is checkpoint-driven on resume (the allow-list blocks it on the command
		# line); restore the resolved hierarchy-filler mode + literal as the sole source of truth.
		if ($cp.Contains('fillerLabelMode') -and $cp.fillerLabelMode) { $script:HierarchyFillMode = [string]$cp.fillerLabelMode }
		if ($cp.Contains('fillerLabelText')) { $script:HierarchyFillLabel = [string]$cp.fillerLabelText }

		# Per-stream destinations and append targets. Persisted by New-Checkpoint;
		# restored here so a -Resume run does not require the user to re-supply any
		# destination switch. Resume-allowed-list already blocks the user from passing
		# these on the resume command line, so checkpoint is the sole source of truth.
		if ($cp.Contains('outputPathUserInfo')     -and $cp.outputPathUserInfo)     { $OutputPathUserInfo     = [string]$cp.outputPathUserInfo }
		if ($cp.Contains('outputPathAgent365Info') -and $cp.outputPathAgent365Info) { $OutputPathAgent365Info = [string]$cp.outputPathAgent365Info }
		if ($cp.Contains('outputPathLog')          -and $cp.outputPathLog)          { $OutputPathLog          = [string]$cp.outputPathLog }
		if ($cp.Contains('appendFile')             -and $cp.appendFile)             { $AppendFile             = [string]$cp.appendFile }
		if ($cp.Contains('appendUserInfo')         -and $cp.appendUserInfo)         { $AppendUserInfo         = [string]$cp.appendUserInfo }
		if ($cp.Contains('appendAgent365Info')     -and $cp.appendAgent365Info)     { $AppendAgent365Info     = [string]$cp.appendAgent365Info }
		# AISID (Defender) output set + cache switch. Restored ONLY when the checkpoint stores the full
		# AISID resume state (marker present). A checkpoint without it requires an explicit destination
		# recovery instead REQUIRES a dedicated -OutputPathDefenderUsage/-AppendDefenderUsage on the
		# resume CLI and forces a cache miss (handled in the classification block below).
		if ($cp.Contains('outputPathDefenderUsage') -and $cp.outputPathDefenderUsage) { $OutputPathDefenderUsage = [string]$cp.outputPathDefenderUsage }
		if ($cp.Contains('appendDefenderUsage')     -and $cp.appendDefenderUsage)     { $AppendDefenderUsage     = [string]$cp.appendDefenderUsage }
		if ($cp.Contains('disableAISIDDeltaCache')  -and $cp.disableAISIDDeltaCache)  { $DisableAISIDDeltaCache  = [System.Management.Automation.SwitchParameter]::new($true) }

		# ============================================================
		# RESUME: Re-resolve destination state from RESTORED variable values.
		# The parse-time destination-resolution block (search for "destSwitches")
		# keys off $PSBoundParameters, but on a -Resume run the user MUST NOT pass
		# -OutputPath* / -Append* (resume-allowed-list rejects them) — so at parse
		# time every $script:DestIsBound[*] was false and $script:RemoteOutputMode
		# stayed 'None'. Now that the checkpoint restore above repopulated $OutputPath,
		# $OutputPathUserInfo, $OutputPathAgent365Info, $OutputPathLog, $AppendFile,
		# $AppendUserInfo, $AppendAgent365Info, re-derive the destination hashtables
		# so the end-of-run upload sweep + display helpers route correctly. Without
		# this, $script:RemoteOutputMode stays 'None' and no files ever upload to SP/Fabric.
		# "Bound-ness" is inferred from a non-empty value (the new-run path uses
		# $PSBoundParameters because string parameter defaults are '' which is falsy here too).
		# ============================================================
		$script:DestTier    = @{}
		$script:DestRaw     = @{}
		$script:DestIsBound = @{}
		$resumeDestSwitches = @(
			@{ Key = 'Purview'      ; Name = 'OutputPath'             ; Value = $OutputPath              ; AllowFabricFilesOnly = $false },
			@{ Key = 'UserInfo'     ; Name = 'OutputPathUserInfo'     ; Value = $OutputPathUserInfo      ; AllowFabricFilesOnly = $false },
			@{ Key = 'Agent365Info' ; Name = 'OutputPathAgent365Info' ; Value = $OutputPathAgent365Info  ; AllowFabricFilesOnly = $false },
			@{ Key = 'DefenderUsage'; Name = 'OutputPathDefenderUsage' ; Value = $OutputPathDefenderUsage  ; AllowFabricFilesOnly = $false },
			@{ Key = 'Log'          ; Name = 'OutputPathLog'          ; Value = $OutputPathLog           ; AllowFabricFilesOnly = $true  }
		)
		foreach ($ds in $resumeDestSwitches) {
			$hasValue = -not [string]::IsNullOrWhiteSpace($ds.Value)
			$script:DestIsBound[$ds.Key] = $hasValue
			if ($hasValue) {
				$tier = script:Get-PathTier -Value $ds.Value -SwitchName $ds.Name -AllowFabricFilesOnly:$ds.AllowFabricFilesOnly
				$script:DestTier[$ds.Key] = $tier
				$script:DestRaw[$ds.Key]  = $ds.Value.Trim()
			}
		}
		$script:AppendIsBound  = @{}
		$script:AppendRaw      = @{}
		$script:AppendIsRemote = @{}
		$resumeAppendSwitches = @(
			@{ Key = 'Purview'      ; Name = 'AppendFile'         ; Value = $AppendFile         },
			@{ Key = 'UserInfo'     ; Name = 'AppendUserInfo'     ; Value = $AppendUserInfo     },
			@{ Key = 'Agent365Info' ; Name = 'AppendAgent365Info' ; Value = $AppendAgent365Info },
			@{ Key = 'DefenderUsage'; Name = 'AppendDefenderUsage' ; Value = $AppendDefenderUsage }
		)
		foreach ($as in $resumeAppendSwitches) {
			$hasValue = -not [string]::IsNullOrWhiteSpace($as.Value)
			$script:AppendIsBound[$as.Key] = $hasValue
			if (-not $hasValue) { continue }
			$v = $as.Value.Trim()
			$script:AppendRaw[$as.Key] = $v
			$looksUrl    = $v -match '^https?://'
			$looksRooted = $v -match '^[A-Za-z]:[\\/]' -or $v -match '^/'
			if ($looksUrl -or $looksRooted) {
				$aTier = script:Get-PathTier -Value $v -SwitchName $as.Name
				$script:AppendIsRemote[$as.Key] = ($aTier -ne 'Local')
				if (-not $script:DestTier.ContainsKey($as.Key)) {
					$script:DestTier[$as.Key] = $aTier
					$script:DestRaw[$as.Key]  = $v
				}
			} else {
				$script:AppendIsRemote[$as.Key] = $false
			}
		}
		# Promote legacy back-compat variables.
		$script:RemoteOutputMode = 'None'
		$script:RemoteOutputUrl  = $null
		if ($script:DestTier.ContainsKey('Purview')) {
			switch ($script:DestTier['Purview']) {
				'SharePoint' { $script:RemoteOutputMode = 'SharePoint'; $script:RemoteOutputUrl = $script:DestRaw['Purview'].TrimEnd('/') }
				'Fabric'     { $script:RemoteOutputMode = 'Fabric';     $script:RemoteOutputUrl = $script:DestRaw['Purview'].TrimEnd('/') }
			}
		}
		if ($script:RemoteOutputMode -eq 'None') {
			foreach ($k in @('UserInfo','Agent365Info','DefenderUsage')) {
				if (-not $script:DestTier.ContainsKey($k)) { continue }
				$t = $script:DestTier[$k]
				if ($t -eq 'SharePoint' -or $t -eq 'Fabric') {
					$script:RemoteOutputMode = $t
					$script:RemoteOutputUrl  = $script:DestRaw[$k].TrimEnd('/')
					break
				}
			}
		}
		# Folder-URL normalization for DestParentUrl and RemoteOutputUrl (mirrors the
		# parse-time block at $script:NormalizeFolderUrl).
		$script:DestParentUrl = @{}
		$resumeNormalizeFolderUrl = {
			param([string]$u)
			if ([string]::IsNullOrWhiteSpace($u)) { return $u }
			if ($u -match '/[^/]+\.(csv|log|xlsx|json|parquet|txt)$') {
				return ($u -replace '/[^/]+\.[A-Za-z0-9]+$','')
			}
			return $u
		}
		if ($script:RemoteOutputUrl) { $script:RemoteOutputUrl = & $resumeNormalizeFolderUrl $script:RemoteOutputUrl }
		foreach ($k in @('Purview','UserInfo','Agent365Info','DefenderUsage','Log')) {
			if (-not $script:DestRaw.ContainsKey($k)) { continue }
			if (-not $script:DestTier.ContainsKey($k)) { continue }
			if ($script:DestTier[$k] -eq 'Local') { continue }
			$script:DestParentUrl[$k] = & $resumeNormalizeFolderUrl $script:DestRaw[$k]
		}
		$restoredTiers = @(); foreach ($k in @('Purview','UserInfo','Agent365Info','DefenderUsage','Log')) { if ($script:DestTier.ContainsKey($k)) { $restoredTiers += $script:DestTier[$k] } }; $restoredTiers = @($restoredTiers | Select-Object -Unique); if ($restoredTiers.Count -gt 1) { Write-LogHost ("ERROR: resume destination conflict - restored destinations resolve to mixed storage tiers ({0}); all destinations in one run must share one tier." -f ($restoredTiers -join ', ')) -ForegroundColor Red; exit 1 }
		$restoredNorm = @{}; foreach ($k in @('Purview','UserInfo','Agent365Info','DefenderUsage','Log')) { if (-not $script:DestRaw.ContainsKey($k)) { continue }; $rn = $script:DestRaw[$k].TrimEnd('/','\').ToLowerInvariant(); if ($rn -match '\.[a-z0-9]{2,5}$') { if ($restoredNorm.ContainsKey($rn)) { Write-LogHost ("ERROR: resume destination conflict - {0} and {1} resolve to the same fully qualified path: {2}" -f $restoredNorm[$rn], $k, $script:DestRaw[$k]) -ForegroundColor Red; exit 1 }; $restoredNorm[$rn] = $k } }
		Write-LogHost "  Resume: re-resolved destination state (RemoteOutputMode=$script:RemoteOutputMode, tiers=$(($script:DestTier.GetEnumerator() | ForEach-Object { "$($_.Key)=$($_.Value)" }) -join ', '))" -ForegroundColor DarkGray

		# Resume-side scratch-dir rewrite. Mirrors the parse-time scratch-dir rewrite
		# (search for "Redirect OutputPath to a per-run scratch dir") for the -Resume
		# code path. Once we know the destination is SharePoint / Fabric, downstream
		# code must continue to treat $OutputPath as the LOCAL scratch directory
		# (where _PARTIAL.csv and .pax_incremental live) — exactly as it did during
		# the interrupted run. The scratch dir on a -Resume is the parent of the
		# checkpoint file (every PAX_<ts>/ scratch is self-contained). Without this
		# rewrite, downstream code would re-use the remote URL string as a local
		# Join-Path target and crash / write nowhere. Tier-agnostic: applies
		# identically to SharePoint and Fabric (OneLake) modes.
		if ($script:RemoteOutputMode -ne 'None') {
			$script:RemoteScratchDir = Split-Path -Parent $script:CheckpointPath
			$sep = [System.IO.Path]::DirectorySeparatorChar
			if (-not $script:RemoteScratchDir.EndsWith($sep)) { $script:RemoteScratchDir = $script:RemoteScratchDir + $sep }
			$OutputPath = $script:RemoteScratchDir
			Write-LogHost "  Resume: remote mode active - scratch dir = $script:RemoteScratchDir (remote URL = $script:RemoteOutputUrl)" -ForegroundColor DarkGray
		}

		# Restore rollup post-processor intent from checkpoint, with last-write-wins semantics:
		# if the user passed -Rollup or -RollupPlusRaw on the resume command line, the resume
		# switch wins and the checkpoint value is ignored. If the user passed neither, restore
		# the original run's rollup mode from the checkpoint so a resumed run produces the same
		# outputs as the original would have.
		$resumeUserPassedRollup = $PSBoundParameters.ContainsKey('Rollup') -or $PSBoundParameters.ContainsKey('RollupPlusRaw')
		if (-not $resumeUserPassedRollup -and $cp.rollupMode) {
			switch ([string]$cp.rollupMode) {
				'Rollup'        { $Rollup        = [System.Management.Automation.SwitchParameter]::new($true); $RollupPlusRaw = [System.Management.Automation.SwitchParameter]::new($false) }
				'RollupPlusRaw' { $RollupPlusRaw = [System.Management.Automation.SwitchParameter]::new($true); $Rollup        = [System.Management.Automation.SwitchParameter]::new($false) }
				default         { }
			}
			if ($cp.processorMode -and ($cp.processorMode -in @('CopilotInteraction','M365Bundle','None'))) {
				$script:RollupProcessorMode = [string]$cp.processorMode
			}
			if ($Rollup -or $RollupPlusRaw) {
				$restoredSwitch = if ($Rollup) { '-Rollup' } else { '-RollupPlusRaw' }
				Write-LogHost "  Restored rollup mode from checkpoint: $restoredSwitch (processorMode=$($script:RollupProcessorMode))" -ForegroundColor DarkGray
			}
		}
		elseif ($resumeUserPassedRollup -and $cp.rollupMode -and $cp.rollupMode -ne 'None') {
			# Resume's switch wins; just log the override for visibility.
			$nowSwitch = if ($Rollup) { '-Rollup' } elseif ($RollupPlusRaw) { '-RollupPlusRaw' } else { '<none>' }
			Write-LogHost "  Rollup mode overridden on resume: checkpoint='$($cp.rollupMode)' -> resume='$nowSwitch' (last-write-wins)." -ForegroundColor Yellow
		}

		# Dashboard restore (independent last-write-wins): an explicit -Dashboard on the
		# resume CLI wins; otherwise restore the original run's dashboard so a resumed
		# CopilotInteraction run keeps its AIO/AIBV profile instead of defaulting to AIO.
		# Guarded to valid values so the [ValidateSet] on $Dashboard never throws on assign.
		$resumeUserPassedDashboard = $PSBoundParameters.ContainsKey('Dashboard')
		if (-not $resumeUserPassedDashboard -and -not $script:ResumeIsAISID -and $cp.rollupDashboard -and ([string]$cp.rollupDashboard -in @('AIO', 'AIBV', 'M365'))) {
			$Dashboard = if ([string]$cp.rollupDashboard -ieq 'AIBV') { 'ValueLens' } else { [string]$cp.rollupDashboard }
			Write-LogHost "  Restored rollup dashboard from checkpoint: $Dashboard" -ForegroundColor DarkGray
		}

		# Re-derive $script:RollupProcessorMode AFTER all resume-restore lines above have
		# merged checkpoint state (especially IncludeM365Usage). This guarantees the wire-up
		# at end-of-run picks the right embedded processor even when the resume CLI omitted
		# the modifier switches. The gating BLOCKERS are not re-run here — they were validated
		# on the original run and the resume restore preserves all gating-relevant switches
		# (ExportWorkbook, OnlyUserInfo, OnlyAgent365Info, AppendFile,
		# RAWInputCSV, UseEOM); if any of those were set, the original run would have already
		# hard-failed before producing a checkpoint to resume from.
		if ($Rollup -or $RollupPlusRaw) {
			if ($IncludeM365Usage) {
				$script:RollupProcessorMode = 'M365Bundle'
				$script:RollupDashboard = 'M365'
				$script:RollupDashboardProfile = $null
			}
			else {
				$script:RollupProcessorMode = 'CopilotInteraction'
				# Honor the restored / resume-CLI dashboard so a resumed AIBV run is not
				# silently downgraded to the AIO default. Only AIO/AIBV reach here
				# (M365 implies -IncludeM365Usage -> the M365Bundle branch above).
				$script:RollupDashboard = if ($Dashboard) { if ($Dashboard.ToUpperInvariant() -eq 'VALUELENS') { 'AIBV' } else { $Dashboard.ToUpperInvariant() } } else { 'AIO' }
				if ($script:RollupDashboard -notin @('AIO', 'AIBV')) { $script:RollupDashboard = 'AIO' }
				$script:RollupDashboardProfile = $script:RollupDashboard.ToLowerInvariant()
				if (-not $IncludeUserInfo) {
					$IncludeUserInfo = [System.Management.Automation.SwitchParameter]::new($true)
					Write-LogHost "  Resume: auto-enabled -IncludeUserInfo for CopilotInteraction-mode rollup." -ForegroundColor Cyan
				}
			}
		}

		# Auth - only restore if user didn't override
		if (-not $PSBoundParameters.ContainsKey('Auth') -and $cp.auth) { $Auth = $cp.auth }
		if (-not $PSBoundParameters.ContainsKey('TenantId') -and $cp.tenantId) { $TenantId = $cp.tenantId }
		if (-not $PSBoundParameters.ContainsKey('ClientId') -and $cp.clientId) { $ClientId = $cp.clientId }

		# Re-promote restored auth identifiers to script scope. The original L1808-L1812
		# promotion ran at parse time, BEFORE the checkpoint restored TenantId/ClientId
		# from the snapshot. Without this re-promotion Connect-PurviewAudit would see
		# the empty default values and fail to authenticate even when the user supplied
		# -ClientSecret on the resume command line.
		$script:TenantId = $TenantId
		$script:ClientId = $ClientId

		# Resume preflight for AppRegistration: ClientSecret / cert material is never
		# persisted in the checkpoint (by design). If the restored Auth is AppRegistration
		# and no credential material was supplied on the resume command line, fail fast
		# with an actionable error rather than crashing inside Connect-PurviewAudit on
		# the first audit query attempt.
		if (([string]$Auth) -ieq 'AppRegistration' `
			-and [string]::IsNullOrEmpty([string]$script:ClientSecret) `
			-and [string]::IsNullOrEmpty([string]$script:ClientCertificateThumbprint) `
			-and [string]::IsNullOrEmpty([string]$script:ClientCertificatePath)) {
			Write-LogHost "" -ForegroundColor Red
			Write-LogHost "═════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
			Write-LogHost "  ERROR: -Resume against an AppRegistration checkpoint requires credential material" -ForegroundColor Red
			Write-LogHost "═════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
			Write-LogHost "" -ForegroundColor Red
			Write-LogHost ("  The original run used -Auth AppRegistration (TenantId={0}, ClientId={1})." -f $script:TenantId, $script:ClientId) -ForegroundColor Yellow
			Write-LogHost "  Secrets / certificate material are NOT persisted in the checkpoint by design." -ForegroundColor Yellow
			Write-LogHost "  Re-supply one of the credential switches on the resume command line:" -ForegroundColor Yellow
			Write-LogHost "" -ForegroundColor Yellow
			Write-LogHost "    -ClientSecret <secret>" -ForegroundColor Green
			Write-LogHost "    -ClientCertificateThumbprint <thumbprint>" -ForegroundColor Green
			Write-LogHost "    -ClientCertificatePath <pfx-path> [-ClientCertificatePassword <pwd>]" -ForegroundColor Green
			Write-LogHost "" -ForegroundColor Yellow
			Write-LogHost "  Example:" -ForegroundColor Cyan
			Write-LogHost ("    pwsh -NoLogo -NoProfile -File `"<script>`" -Resume `"{0}`" -ClientSecret <secret>" -f $script:CheckpointPath) -ForegroundColor White
			Write-LogHost "" -ForegroundColor Red
			exit 1
		}
		
		# Other settings
		if ($cp.resultSize) { $ResultSize = $cp.resultSize }
		if ($cp.maxConcurrency) { $MaxConcurrency = $cp.maxConcurrency }
		# MaxMemoryMB: Allow user override on resume (different machine may have different RAM)
		if (-not $PSBoundParameters.ContainsKey('MaxMemoryMB') -and $null -ne $cp.maxMemoryMB) { 
			$MaxMemoryMB = $cp.maxMemoryMB 
			Write-LogHost "  Restored MaxMemoryMB from checkpoint: $MaxMemoryMB" -ForegroundColor DarkGray
		}
		if ($cp.useEOM) { $UseEOM = [switch]$true }
		if ($cp.autoCompleteness) { $AutoCompleteness = [switch]$true }
		if ($cp.includeTelemetry) { $IncludeTelemetry = [switch]$true }
		
		# Set the partial output path from checkpoint
		$checkpointDir = Split-Path $script:CheckpointPath -Parent
		$script:PartialOutputPath = Join-Path $checkpointDir $checkpointData.outputFiles.partialCsv
		
		# Set FinalOutputPath by stripping _PARTIAL from the partial path
		$partialBaseName = [System.IO.Path]::GetFileNameWithoutExtension($script:PartialOutputPath)
		$partialExt = [System.IO.Path]::GetExtension($script:PartialOutputPath)
		$finalBaseName = $partialBaseName -replace '_PARTIAL$', ''
		$script:FinalOutputPath = Join-Path $checkpointDir "${finalBaseName}${partialExt}"
		
		# Set OutputFile and CsvOutputFile to the partial path for execution
		$OutputFile = $script:PartialOutputPath
		# For ExportWorkbook mode, CsvOutputFile must use .csv extension (not .xlsx from PartialOutputPath)
		if ($ExportWorkbook) {
			$csvBaseName = [System.IO.Path]::GetFileNameWithoutExtension($script:PartialOutputPath)
			$script:CsvOutputFile = Join-Path $checkpointDir "${csvBaseName}.csv"
		} else {
			$script:CsvOutputFile = $script:PartialOutputPath
		}
		
		# Check for incremental data files
		$incrementalDir = Join-Path $checkpointDir ".pax_incremental"
		$hasIncrementalData = (Test-Path $incrementalDir) -and @(Get-ChildItem -Path $incrementalDir -Filter "*.jsonl" -ErrorAction SilentlyContinue).Count -gt 0
		
		if (-not (Test-Path $script:PartialOutputPath) -and -not $hasIncrementalData) {
			# Wording note. "Will start fresh data collection" would imply a clean slate
			# even when the checkpoint preserves server-side QueryIds that the resume
			# reuses (so the server query is NOT recreated). Differentiate the two
			# scenarios so operators understand whether QueryId reuse is active.
			#
			# $checkpointData is an OrderedHashtable (Read-Checkpoint calls
			# `ConvertFrom-Json -AsHashtable`), NOT a PSCustomObject. A naive presence
			# check using `.PSObject.Properties.Name -contains 'partitions'` on a
			# hashtable returns the CLR property names of the dictionary type
			# (Keys, Values, Count, …) — not the dictionary keys — so the check
			# always returns $false even when `$checkpointData.partitions.queryCreated`
			# clearly has entries. Use dot-access (which hashtable dispatches to key
			# lookup, returning $null for missing keys) rather than CLR property
			# introspection.
			$hasQueryCreated = $false
			try {
				$qcArr = $checkpointData.partitions.queryCreated
				if ($qcArr -and @($qcArr).Count -gt 0) {
					$hasQueryCreated = $true
				}
			} catch {}
			if ($hasQueryCreated) {
				Write-LogHost "WARNING: No local partial data (neither _PARTIAL.csv nor .pax_incremental files)" -ForegroundColor Yellow
				Write-LogHost "         Resuming data fetch against existing server query (QueryId reused from checkpoint)." -ForegroundColor Yellow
			} else {
				Write-LogHost "WARNING: No partial data found (neither _PARTIAL.csv nor .pax_incremental files)" -ForegroundColor Yellow
				Write-LogHost "         Will start fresh data collection." -ForegroundColor Yellow
			}
		}
		elseif ($hasIncrementalData) {
			$incrementalFiles = @(Get-ChildItem -Path $incrementalDir -Filter "*.jsonl" -ErrorAction SilentlyContinue)
			Write-LogHost "Found $($incrementalFiles.Count) incremental data file(s) in .pax_incremental/" -ForegroundColor Green
		}
		
		# Set log file to match the _PARTIAL output file (deferred from earlier setup).
		# Honors -OutputPathLog when bound to a Local path.
		$logBaseName = [System.IO.Path]::GetFileNameWithoutExtension($script:PartialOutputPath)
		# Under non-rollup -AppendFile, the _PARTIAL leaf is derived from the
		# AppendFile target's basename (which carries the target's ORIGINAL creation
		# timestamp AND its per-activity-type suffix). Match the canonical non-append
		# log basename (${filePrefix}_<currentRunTs>) so the append run's log file is
		# named identically to the non-append run's log. On resume,
		# $global:ScriptRunTimestamp is restored from the checkpoint so subsequent
		# resume passes continue to write into the same log file. The _PARTIAL
		# suffix convention is preserved. Fallback to the checkpoint's persisted
		# appendFile parameter mirrors the defensive truth-source used by the
		# streaming-merge append-merge gate.
		$_resumeIsNonRollupAppend = ([bool]$AppendFile -or `
			([bool]$script:CheckpointData -and `
			 [bool]$script:CheckpointData.parameters -and `
			 [bool]$script:CheckpointData.parameters.appendFile)) `
			-and -not ($Rollup -or $RollupPlusRaw)
		if ($_resumeIsNonRollupAppend) {
			$_hadPartialSuffix = ($logBaseName -match '_PARTIAL$')
			$_currentRunTs = [string]$global:ScriptRunTimestamp
			$_canonicalPfx = if ($filePrefix) { [string]$filePrefix } else { 'Purview_Audit' }
			$_canonicalLogBase = if ($_currentRunTs) { "${_canonicalPfx}_${_currentRunTs}" } else { $_canonicalPfx }
			$logBaseName = if ($_hadPartialSuffix) { "${_canonicalLogBase}_PARTIAL" } else { $_canonicalLogBase }
		}
		$logDir = Split-Path $script:PartialOutputPath -Parent
		try {
			$dtLR = script:Resolve-DataTypePaths -DataType 'Log' -DefaultBasename ("{0}.log" -f $logBaseName)
			if ($dtLR -and $dtLR.IsBound -and $dtLR.Tier -eq 'Local') {
				$logDir = $dtLR.EffectiveDir
				if ($dtLR.Basename) { $logBaseName = [System.IO.Path]::GetFileNameWithoutExtension($dtLR.Basename) }
				if (-not (Test-Path -LiteralPath $logDir -PathType Container)) {
					New-Item -Path $logDir -ItemType Directory -Force | Out-Null
				}
			}
		} catch {}
		$finalLogFile = Join-Path $logDir ("{0}.log" -f $logBaseName)

		# Bootstrap-log migration (resume path). Mirror the new-run logic so a
		# resumed session also captures pre-resolution entries in the final log.
		if ($script:LogFileIsBootstrap -and $script:LogFile -and (Test-Path -LiteralPath $script:LogFile)) {
			try {
				if (-not (Test-Path -LiteralPath $logDir -PathType Container)) {
					New-Item -Path $logDir -ItemType Directory -Force | Out-Null
				}
				if (Test-Path -LiteralPath $finalLogFile) {
					# Append bootstrap content to existing resume log instead of overwriting.
					$bootstrapContent = Get-Content -LiteralPath $script:LogFile -Raw -ErrorAction Stop
					Add-Content -LiteralPath $finalLogFile -Value $bootstrapContent -Encoding UTF8 -ErrorAction Stop
					Remove-Item -LiteralPath $script:LogFile -Force -ErrorAction SilentlyContinue
				} else {
					Move-Item -LiteralPath $script:LogFile -Destination $finalLogFile -Force -ErrorAction Stop
				}
			} catch {
				Microsoft.PowerShell.Utility\Write-Host ("WARNING: Could not migrate bootstrap log to resumed final location: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
			}
			$script:LogFileIsBootstrap = $false
		}

		$script:LogFile = $finalLogFile
		$LogFile = $script:LogFile
		
		# Check if original log exists
		$logFileExisted = Test-Path $script:LogFile
		
		# Add clear resume session marker to the log (appends to existing log, or creates new)
		$resumeMarker = @"
$(if (-not $logFileExisted) { "=== Portable Audit eXporter (PAX) - Purview Audit Log Exporter ===`n(Original log file was not found - this is a resumed session)`n" })
============================================================================================================
  RESUME SESSION STARTED
============================================================================================================
  Resume Time (UTC):    $((Get-Date).ToUniversalTime().ToString('yyyy-MM-dd HH:mm:ss')) UTC
  Resume Time (Local):  $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')
  Original Run:         $($checkpointData.runTimestamp)
  Checkpoint File:      $(Split-Path $script:CheckpointPath -Leaf)
  Partitions Completed: $completedCount / $totalPartitions
  Partitions Remaining: $($totalPartitions - $completedCount)
============================================================================================================

"@
		Add-Content -Path $script:LogFile -Value $resumeMarker -Encoding UTF8 -ErrorAction SilentlyContinue
		
		# Flush any buffered log entries now that log file is set
		if ($script:LogBuffer -and $script:LogBuffer.Count -gt 0) {
			foreach ($entry in $script:LogBuffer) {
				try { Add-Content -Path $script:LogFile -Value $entry -Encoding UTF8 -ErrorAction SilentlyContinue } catch {}
			}
			$script:LogBuffer.Clear()
		}
		
		# Display restored settings summary
		Write-LogHost ""
		Write-LogHost "Restored settings from checkpoint:" -ForegroundColor DarkGray
		Write-LogHost "  Date Range:         $StartDate to $EndDate" -ForegroundColor DarkGray
		# Custom Activities: Show user-specified activity types (not including auto-added CopilotInteraction)
		$customActivities = @($ActivityTypes | Where-Object { $_ -ne 'CopilotInteraction' })
		if ($customActivities.Count -gt 0) {
			Write-LogHost "  Custom Activities:  $($customActivities -join ', ')" -ForegroundColor DarkGray
		} else {
			Write-LogHost "  Custom Activities:  None" -ForegroundColor DarkGray
		}
		# CopilotInteraction status
		$copilotStatus = if ($ExcludeCopilotInteraction) { 'Excluded' } elseif ($ActivityTypes -contains 'CopilotInteraction') { 'Included' } else { 'Not included' }
		Write-LogHost "  CopilotInteraction: $copilotStatus" -ForegroundColor DarkGray
		# M365 Usage status
		$m365Status = if ($IncludeM365Usage) { 'Included' } else { 'Not included' }
		Write-LogHost "  M365 Usage:         $m365Status" -ForegroundColor DarkGray
		if ($ExplodeArrays -or $ExplodeDeep) { Write-LogHost "  Explosion:          $(if ($ExplodeDeep) { 'ExplodeDeep' } elseif ($ExplodeArrays) { 'ExplodeArrays' })" -ForegroundColor DarkGray }
		if ($PSBoundParameters.ContainsKey('Auth')) {
			Write-LogHost "  Auth (override):    $Auth" -ForegroundColor Yellow
		} else {
			Write-LogHost "  Auth (restored):    $Auth" -ForegroundColor DarkGray
		}
		Write-LogHost ""
		
		Write-LogHost "Resume mode initialized. Will continue from last checkpoint." -ForegroundColor Cyan
		Write-LogHost ""
		
		# Re-compute date-range trim boundaries from checkpoint-restored dates.
		# TrimStartDateUTC/TrimEndDateUTC were initially set from command-line defaults (yesterday)
		# before the checkpoint restore overwrote $StartDate/$EndDate with the original run's dates.
		$script:TrimStartDateUTC = if ($StartDate -ne '*') { [datetime]::SpecifyKind([datetime]::ParseExact($StartDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture), [System.DateTimeKind]::Utc) } else { $null }
		$script:TrimEndDateUTC   = if ($EndDate   -ne '*') { [datetime]::SpecifyKind([datetime]::ParseExact($EndDate,   'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture), [System.DateTimeKind]::Utc) } else { $null }
		
		# AISID window restore: replay the run's frozen window on resume; never
		# recompute against the resume-time clock. Newer checkpoints carry an explicit aisidWindow block; a
		# checkpoint that carries two concrete dates + a parseable createdUtc (no aisidWindow) has its
		# ReferenceNowUtc derived once from createdUtc. Anything else fails clearly (never the live clock).
		if ($Dashboard -eq 'AISID') {
			$awp = $checkpointData.aisidWindow
			$rk = [System.Globalization.DateTimeStyles]::RoundtripKind
			$ic = [System.Globalization.CultureInfo]::InvariantCulture
			if ($awp -and $awp.referenceNowUtc -and $awp.requestedStartUtc -and $awp.requestedEndUtc) {
				$script:AISIDReferenceNowUtc = [datetime]::SpecifyKind([datetime]::Parse([string]$awp.referenceNowUtc, $ic, $rk), [System.DateTimeKind]::Utc)
				$reqS = [datetime]::SpecifyKind([datetime]::Parse([string]$awp.requestedStartUtc, $ic, $rk), [System.DateTimeKind]::Utc)
				$reqE = [datetime]::SpecifyKind([datetime]::Parse([string]$awp.requestedEndUtc, $ic, $rk), [System.DateTimeKind]::Utc)
				$script:AISIDWindow = Resolve-AISIDDateWindow -RequestedStartUtc $reqS -RequestedEndUtc $reqE -ReferenceNowUtc $script:AISIDReferenceNowUtc -RetentionDays (Get-AISIDEffectiveLookbackDays)
				Write-LogHost "  AISID: restored the original run's frozen collection window from checkpoint (deterministic replay)." -ForegroundColor DarkGray
			}
			elseif ($script:TrimStartDateUTC -and $script:TrimEndDateUTC -and $checkpointData.createdUtc) {
				$refParsed = $null
				try { $refParsed = [datetime]::Parse([string]$checkpointData.createdUtc, $ic, $rk) } catch { $refParsed = $null }
				if (-not $refParsed) {
					Write-LogHost "ERROR: Cannot resume this AISID run - the checkpoint has no explicit AISID window and its createdUtc is missing or unparseable, so the 30-day retention window cannot be anchored." -ForegroundColor Red
					exit 1
				}
				$script:AISIDReferenceNowUtc = [datetime]::SpecifyKind($refParsed, [System.DateTimeKind]::Utc)
				$script:AISIDWindow = Resolve-AISIDDateWindow -RequestedStartUtc $script:TrimStartDateUTC -RequestedEndUtc $script:TrimEndDateUTC -ReferenceNowUtc $script:AISIDReferenceNowUtc -RetentionDays (Get-AISIDEffectiveLookbackDays)
				Write-LogHost "  AISID: legacy checkpoint - derived the reference instant from createdUtc for a deterministic window replay." -ForegroundColor DarkGray
			}
			else {
				Write-LogHost "ERROR: Cannot resume this AISID run - the checkpoint lacks an explicit AISID window and does not carry two concrete dates plus a parseable createdUtc to reconstruct one." -ForegroundColor Red
				exit 1
			}
		}

		$script:ResumeValidationFailed = $false
		# Re-run MaxMemoryMB resolution after checkpoint restore (may have restored -1 for auto-detect)
		$script:ResolvedMaxMemoryMB = $MaxMemoryMB
		if ($MaxMemoryMB -eq -1) {
			try {
				$totalRAM = [math]::Round((Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction SilentlyContinue).TotalPhysicalMemory / 1MB, 0)
				$script:ResolvedMaxMemoryMB = [math]::Round($totalRAM * 0.75, 0)
				Write-LogHost "Memory management (resume): Auto-detected ${totalRAM}MB total RAM -> limit $($script:ResolvedMaxMemoryMB)MB (75%)" -ForegroundColor Cyan
			} catch {
				$script:ResolvedMaxMemoryMB = 4096
				Write-LogHost "Memory management (resume): Could not detect system RAM, defaulting to 4096MB limit" -ForegroundColor Yellow
			}
		} elseif ($MaxMemoryMB -eq 0) {
			Write-LogHost "Memory management (resume): DISABLED (-MaxMemoryMB 0)" -ForegroundColor DarkGray
		} else {
			Write-LogHost "Memory management (resume): Using $($script:ResolvedMaxMemoryMB)MB limit" -ForegroundColor DarkGray
		}
		# Re-evaluate memoryFlushEnabled with restored/resolved value
		$script:memoryFlushEnabled = ($script:ResolvedMaxMemoryMB -gt 0) -and (-not $ExplodeDeep) -and (-not $ExplodeArrays) -and (-not $ForcedRawInputCsvExplosion)
	}
	
	# Authentication and Entra data collection (live mode only)
	if (-not $RAWInputCSV) {
		$existingEOM = Get-Module -ListAvailable -Name ExchangeOnlineManagement | Sort-Object Version -Descending | Select-Object -First 1
		if (-not $existingEOM -and $UseEOM) {
			Write-LogHost "Installing ExchangeOnlineManagement module..." -ForegroundColor Yellow
			try { Install-Module -Name ExchangeOnlineManagement -Scope CurrentUser -Force -AllowClobber; Write-LogHost "Module installed successfully." -ForegroundColor Green } catch { Write-LogHost "Failed to install ExchangeOnlineManagement module: $($_.Exception.Message)" -ForegroundColor Red; exit 1 }
		}
		if ($UseEOM) {
			Import-Module ExchangeOnlineManagement -Force
		}

		if (($IncludeAgent365Info -or $OnlyAgent365Info) -and ($Auth -eq 'AppRegistration' -or $Auth -eq 'ManagedIdentity')) {
			Write-LogHost ""
			Write-LogHost "+----------------------------------------------------------------------+" -ForegroundColor Cyan
			Write-LogHost "|  APP-ONLY Agent 365 run (no interactive sign-in)                     |" -ForegroundColor Cyan
			Write-LogHost "+----------------------------------------------------------------------+" -ForegroundColor Cyan
			Write-LogHost ("|  Auth mode: {0,-57}|" -f $Auth) -ForegroundColor Cyan
			Write-LogHost "|                                                                      |" -ForegroundColor Cyan
			Write-LogHost "|  The audit AND Agent 365 phases both run on the SAME app-only Graph  |" -ForegroundColor Cyan
			Write-LogHost "|  context (your app registration / managed-identity service           |" -ForegroundColor Cyan
			Write-LogHost "|  principal). No user prompt is shown at any point.                   |" -ForegroundColor Cyan
			Write-LogHost "|                                                                      |" -ForegroundColor Cyan
			Write-LogHost "|  Required APPLICATION permissions (granted + admin-consented):       |" -ForegroundColor Cyan
			Write-LogHost "|    - CopilotPackages.Read.All  (read the Agent 365 catalog)          |" -ForegroundColor Cyan
			Write-LogHost "|    - Application.Read.All       (resolve developer/owner names)      |" -ForegroundColor Cyan
			Write-LogHost "|                                                                      |" -ForegroundColor Cyan
			Write-LogHost "|  Caveats:                                                            |" -ForegroundColor Cyan
			Write-LogHost "|    - The catalog API is published at /beta only.                     |" -ForegroundColor Cyan
			Write-LogHost "|    - The tenant must hold a Microsoft Agent 365 license/enrollment.  |" -ForegroundColor Cyan
			Write-LogHost "|    - A 403 means the app-role is missing OR the tenant is not        |" -ForegroundColor Cyan
			Write-LogHost "|      licensed/enrolled (NOT a missing user directory role).          |" -ForegroundColor Cyan
			Write-LogHost "|                                                                      |" -ForegroundColor Cyan
			Write-LogHost "|  Reference:                                                          |" -ForegroundColor Cyan
			Write-LogHost "|  https://learn.microsoft.com/en-us/microsoft-agent-365/admin/graph-api|" -ForegroundColor Cyan
			Write-LogHost "+----------------------------------------------------------------------+" -ForegroundColor Cyan
			Write-LogHost ""
		}

		# ====================================================================
		# Defect 2: pre-auth legacy contract-mapping resolver (resume, Graph mode).
		# On resume, migrate any legacy (fingerprint-less) checkpoint entries to
		# proven-unique durable fingerprints BEFORE authentication and the per-workload
		# partition build. Fails closed (no auth, no mutation) on any zero/ambiguous mapping.
		# ====================================================================
		if ($script:IsResumeMode -and $script:CheckpointData -and (-not $UseEOM)) {
			try {
				$__legacyStart = [datetime]::ParseExact($StartDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture)
				$__legacyEnd = [datetime]::ParseExact($EndDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture)
				$__legacyContracts = Get-PaxResumeCurrentContractSet -StartDateObj $__legacyStart -EndDateObj $__legacyEnd -ActivityTypes $ActivityTypes -RecordTypes $RecordTypes -ServiceTypes $ServiceTypes -PartitionHours $PartitionHours -MaxPartitions $MaxPartitions -MaxConcurrency $MaxConcurrency -IncludeM365Usage:$IncludeM365Usage -UseEOM:$UseEOM -ServiceOperationMap $serviceOperationMap -RecordTypeWorkloadMap $recordTypeWorkloadMap
				$__legacyResult = Invoke-PaxResumeLegacyContractMapping -CheckpointData $script:CheckpointData -CurrentContracts $__legacyContracts
				if ($__legacyResult -and $__legacyResult.Status -eq 'Migrated') {
					Write-LogHost ("Resume: migrated {0} legacy checkpoint entr{1} to durable per-contract fingerprints (published)." -f $__legacyResult.Migrated, $(if ($__legacyResult.Migrated -eq 1) { 'y' } else { 'ies' })) -ForegroundColor DarkCyan
				}
			} catch {
				Write-LogHost "" -ForegroundColor Red
				Write-LogHost ("RESUME BLOCKED - legacy checkpoint could not be mapped safely: {0}" -f $_.Exception.Message) -ForegroundColor Red
				Write-LogHost "  No authentication and no checkpoint mutation have occurred. Resolve the above and retry." -ForegroundColor Yellow
				exit 1
			}
		}

		# Use unified authentication function
		Connect-PurviewAudit -AuthMethod $Auth -UseEOMMode $UseEOM

		# Remote-output destination probe + AppendFile pull (SP/Fabric only).
		# Done immediately after Graph/EOM connect so we fail fast before any audit work.
		if ($script:RemoteOutputMode -ne 'None') {
			try {
				Test-RemoteDestination
				Write-LogHost ("Remote destination probe OK ({0})." -f $script:RemoteOutputMode) -ForegroundColor Green
			} catch {
				# Resolve-SharePointTarget / Resolve-FabricTarget now throw a multi-line classified
				# diagnosis (Cause / Action / Graph response). Format that as a banner pointing back
				# to the permissions table so customers don't have to scroll up guessing.
				$probeMsg   = $_.Exception.Message
				$probeLines = $probeMsg -split "`r?`n"
				Write-LogHost ""                                                                                              -ForegroundColor Red
				Write-LogHost "═══════════════════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
				Write-LogHost ("  REMOTE OUTPUT PRE-FLIGHT FAILED — {0} destination cannot be reached" -f $script:RemoteOutputMode) -ForegroundColor Red
				Write-LogHost "═══════════════════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
				Write-LogHost ("  Destination URL : {0}" -f $script:RemoteOutputUrl) -ForegroundColor White
				Write-LogHost ""                                                     -ForegroundColor White
				foreach ($pl in $probeLines) {
					if ([string]::IsNullOrWhiteSpace($pl)) { Write-LogHost "" -ForegroundColor White; continue }
					Write-LogHost ("  {0}" -f $pl) -ForegroundColor Yellow
				}
				Write-LogHost ""                                                                                              -ForegroundColor White
				Write-LogHost "  See the 'Permissions Required for THIS run' table earlier in this output for the"             -ForegroundColor Gray
				Write-LogHost "  full list of required scopes/roles, including which apply to the SharePoint or"               -ForegroundColor Gray
				Write-LogHost "  Fabric output destination."                                                                   -ForegroundColor Gray
				Write-LogHost ""                                                                                              -ForegroundColor White
				Write-LogHost "  No data has been written and no audit queries have been issued. Aborting before the"          -ForegroundColor Gray
				Write-LogHost "  run starts so you do not produce a partial export. Resolve the issue above and re-run."       -ForegroundColor Gray
				Write-LogHost "═══════════════════════════════════════════════════════════════════════════════════════════════" -ForegroundColor Red
				Write-LogHost ""                                                                                              -ForegroundColor Red
				# Customer-facing abort: the banner above is the entire diagnosis. Do NOT throw —
				# the outer top-level catch would print "Script failed: <message>" plus a dev stack
				# trace, which is noise on top of an already self-explanatory banner. Mark EarlyExit
				# so the finally block skips the success-path cleanup and the _PARTIAL rename, then
				# exit with non-zero status for callers that check $LASTEXITCODE.
				$script:EarlyExit = 'PreFlightFailure'
				exit 1
			}

			# AppendFile: pull the existing remote file into local scratch so the rest of
			# the script's append logic operates against a local path, transparently.
			if ($AppendFile) {
				try {
					$appendName      = [System.IO.Path]::GetFileName($AppendFile)
					$appendLocalPath = Join-Path $OutputPath $appendName
					# Advisory: probe the remote append target's size (metadata only, no body) and
					# warn if the in-memory merge could strain RAM. Fail-open - a probe error or a
					# not-yet-existing (first-run) target yields no warning and does not abort.
					$appendSizeWarning = Get-AppendTargetSizeWarning -SizeBytes (Get-RemoteAppendTargetSize -Tier $script:RemoteOutputMode -RelativeName $appendName) -ThresholdBytes $script:AppendTargetSizeWarnBytes -Label $appendName
					if ($appendSizeWarning) { Write-LogHost $appendSizeWarning -ForegroundColor Yellow }
					if ($script:RemoteOutputMode -eq 'SharePoint') {
						Get-RemoteFile-SharePoint -RelativeName $appendName -DestinationPath $appendLocalPath -ErrorAction Stop
					} else {
						Get-RemoteFile-OneLake    -RelativeName $appendName -DestinationPath $appendLocalPath -ErrorAction Stop
					}
					Write-LogHost ("Remote AppendFile downloaded to scratch: {0}" -f $appendLocalPath) -ForegroundColor Cyan
					$script:AppendRemoteOriginal = $true
					$AppendFile = $appendLocalPath
				} catch {
					Write-LogHost ("ERROR: Failed to download remote AppendFile '{0}': {1}" -f $AppendFile, $_.Exception.Message) -ForegroundColor Red
					throw
				}
			}

			# Sibling -Append* streams: same download pattern as -AppendFile above.
			# Each remote -AppendUserInfo / -AppendAgent365Info target is pulled into
			# scratch under a hidden '.pax_appendseed_<Key>_<originalLeaf>' name. The
			# leading '.pax_*' prefix excludes the seed from the end-of-run upload sweep
			# (so the stale pre-merge copy never lands back at the destination). The
			# in-process $AppendUserInfo / $AppendAgent365Info variables are then re-
			# pointed at the local seed path so Merge-UsersCsv and the Agent 365 merge
			# logic — both of which Test-Path / Import-Csv the value directly — operate
			# against a real file instead of a URL.
			#
			# The downstream Entra / Agent 365 writers inherit the Append target's
			# original leaf as their own output basename (see L257xx and L13974), so
			# the merged file produced by this run sits at <scratch>\<originalLeaf>
			# and the upload-sweep leaf-match (extended for $script:AppendIsBound)
			# overwrites the original remote URL.
			foreach ($auxKey in @('UserInfo','Agent365Info')) {
				if (-not $script:AppendIsBound[$auxKey]) { continue }
				if (-not $script:AppendIsRemote[$auxKey]) { continue }
				$auxRaw    = $script:AppendRaw[$auxKey]
				$auxLeaf   = [System.IO.Path]::GetFileName($auxRaw)
				$auxLocal  = Join-Path $OutputPath ('.pax_appendseed_{0}_{1}' -f $auxKey, $auxLeaf)
				$auxParent = if ($script:DestParentUrl.ContainsKey($auxKey)) { $script:DestParentUrl[$auxKey] } else { $null }
				try {
					if ($script:RemoteOutputMode -eq 'SharePoint') {
						Get-RemoteFile-SharePoint -RelativeName $auxLeaf -DestinationPath $auxLocal -ParentOverride $auxParent -ErrorAction Stop
					} else {
						Get-RemoteFile-OneLake    -RelativeName $auxLeaf -DestinationPath $auxLocal -ParentOverride $auxParent -ErrorAction Stop
					}
					Write-LogHost ("Remote Append{0} downloaded to scratch: {1}" -f $auxKey, $auxLocal) -ForegroundColor Cyan
					if     ($auxKey -eq 'UserInfo')     { $AppendUserInfo     = $auxLocal }
					elseif ($auxKey -eq 'Agent365Info') { $AppendAgent365Info = $auxLocal }
				} catch {
					Write-LogHost ("ERROR: Failed to download remote -Append{0} '{1}': {2}" -f $auxKey, $auxRaw, $_.Exception.Message) -ForegroundColor Red
					throw
				}
			}
		}

		# PAX4A-INGEST-BEGIN
		# -UserInfoFile INGEST + VALIDATE + NORMALIZE
		# Classify the -UserInfoFile VALUE ITSELF (independent of the output tier /
		# $script:RemoteOutputMode). Local: read in place. SharePoint / Fabric: split the
		# input URL into its OWN parent + leaf and stage to local scratch via the matching
		# Get-RemoteFile-* with -ParentOverride = the input's own parent. Parse as CSV,
		# hard-stop on any fetch/format/required-field failure (NO fallback to the Entra
		# pull), then normalize to an Array[psobject] matching the Entra users contract.
		# Result -> the variable $script:UserInfoFileData; not wired into
		# any consumer in this phase.
		$script:UserInfoFileData = $null
		if ($PSBoundParameters.ContainsKey('UserInfoFile') -and -not [string]::IsNullOrWhiteSpace($UserInfoFile)) {
			$uiRaw  = $UserInfoFile.Trim()
			$uiTier = $null
			$uiLocalPath = $null
			try {
				# Shared hardened classifier + stager (same strict .csv file-form validation as
				# -UserInfoSupplement): rejects folder URLs, Fabric roots, and Fabric Tables URLs; a
				# Fabric input must live under /Files/.../*.csv. Remote inputs stage to run scratch and
				# are never registered for upload.
				$uiPlan = script:Resolve-DirectoryCsvInput -Value $UserInfoFile -SwitchName 'UserInfoFile' -ScratchDir $OutputPath -ScratchPrefix '.pax_userinfoseed_'
				$uiTier = $uiPlan.Tier
				$uiLocalPath = $uiPlan.LocalPath
				if ($uiPlan.Staged) { Write-LogHost ("-UserInfoFile ({0}) staged to scratch: {1}" -f $uiTier, $uiLocalPath) -ForegroundColor Cyan }
			}
			catch {
				Write-LogHost ("ERROR: -UserInfoFile could not be fetched from '{0}': {1}" -f $uiRaw, $_.Exception.Message) -ForegroundColor Red
				throw
			}
			if (-not (Test-Path -LiteralPath $uiLocalPath -PathType Leaf)) {
				Write-LogHost ("ERROR: -UserInfoFile not found or unreadable: {0}" -f $uiRaw) -ForegroundColor Red
				throw "-UserInfoFile not found or unreadable: $uiRaw"
			}
			$uiRows = $null
			try {
				$uiRows = @(Import-Csv -LiteralPath $uiLocalPath -ErrorAction Stop)
			}
			catch {
				Write-LogHost ("ERROR: -UserInfoFile is not readable as CSV: {0} ({1})" -f $uiRaw, $_.Exception.Message) -ForegroundColor Red
				throw
			}
			$uiHeaders = @()
			if ($uiRows.Count -gt 0) {
				$uiHeaders = @($uiRows[0].PSObject.Properties.Name)
			}
			else {
				$uiFirstLine = Get-Content -LiteralPath $uiLocalPath -TotalCount 1 -ErrorAction SilentlyContinue
				if ([string]::IsNullOrWhiteSpace($uiFirstLine)) {
					Write-LogHost ("ERROR: -UserInfoFile has no header row (not a CSV): {0}" -f $uiRaw) -ForegroundColor Red
					throw "-UserInfoFile has no header row (not a CSV): $uiRaw"
				}
			}
			if ($uiRows.Count -eq 0) {
				Write-LogHost ("ERROR: -UserInfoFile contains a header but zero data rows: {0}" -f $uiRaw) -ForegroundColor Red
				throw "-UserInfoFile contains zero data rows: $uiRaw"
			}
			$uiHeaderMap = @{}
			foreach ($h in $uiHeaders) { if ($h) { $uiHeaderMap[$h.Trim().ToLowerInvariant()] = $h } }
			# Alias backfill: first-match-wins resolution of documented header aliases over
			# the lower-cased $uiHeaderMap (case-insensitive; source headers are never renamed).
			$uiResolveCol = { param([string[]]$Aliases) foreach ($a in $Aliases) { if ($uiHeaderMap.ContainsKey($a)) { return $uiHeaderMap[$a] } } return $null }
			$uiUpnCol     = & $uiResolveCol @('userprincipalname','upn','personid')
			$uiDisplayCol = & $uiResolveCol @('displayname','name')
			$uiDeptCol    = & $uiResolveCol @('department','organization','organisation')
			$uiTitleCol   = & $uiResolveCol @('jobtitle','title')
			$uiMgrCol     = & $uiResolveCol @('managerupn','manager','manageremail')
			$uiLicCol     = & $uiResolveCol @('haslicense','has license','hascopilotlicense')
			if (-not $uiUpnCol) {
				Write-LogHost ("ERROR: -UserInfoFile is missing the required 'UserPrincipalName' column. Found: {0}" -f ($uiHeaders -join ', ')) -ForegroundColor Red
				throw "-UserInfoFile missing required UserPrincipalName column"
			}
			$uiMissing = @()
			if (-not $uiDisplayCol) { $uiMissing += 'DisplayName' }
			if (-not $uiDeptCol)    { $uiMissing += 'Department' }
			if (-not $uiTitleCol)   { $uiMissing += 'JobTitle' }
			if (-not $uiMgrCol)     { $uiMissing += 'ManagerUpn' }
			if (-not $uiLicCol)     { $uiMissing += 'HasLicense' }
			if ($uiMissing.Count -gt 0) {
				Write-LogHost ("-UserInfoFile: recommended/optional column(s) not present, left unmapped: {0}" -f ($uiMissing -join ', ')) -ForegroundColor Yellow
			}
			$uiConsumed = @($uiUpnCol, $uiDisplayCol, $uiDeptCol, $uiTitleCol, $uiMgrCol, $uiLicCol) | Where-Object { $_ }
			$uiPassthrough = @($uiHeaders | Where-Object { $_ -and ($uiConsumed -notcontains $_) })
			$uiNormalized = [System.Collections.Generic.List[object]]::new()
			foreach ($row in $uiRows) {
				$o = [ordered]@{}
				# Blank-fill: seed EVERY authoritative Entra column (in $EntraUsersHeader
				# order) with '' so file rows are shape-complete vs the Entra users contract; an absent
				# Entra value renders as '' exactly like a real Graph /users pull.
				foreach ($col in $EntraUsersHeader) { $o[$col] = '' }
				$o['userPrincipalName'] = $row.$uiUpnCol
				if ($uiDisplayCol) { $o['displayName'] = $row.$uiDisplayCol }
				if ($uiDeptCol)    { $o['department']  = $row.$uiDeptCol }
				if ($uiTitleCol)   { $o['jobTitle']    = $row.$uiTitleCol }
				if ($uiMgrCol)     { $o['manager_userPrincipalName'] = $row.$uiMgrCol }
				if ($uiLicCol)     { $o['hasLicense']  = $row.$uiLicCol }
				# Passthrough: custom columns append AFTER the header set; a passthrough column whose
				# name matches an authoritative column fills it in place (lossless — no file value dropped).
				foreach ($pc in $uiPassthrough) { $o[$pc] = $row.$pc }
				$uiNormalized.Add([PSCustomObject]$o)
			}
			$script:UserInfoFileData = @($uiNormalized)
			Write-LogHost ("-UserInfoFile ingest OK: {0} user row(s) normalized to the Entra users contract (UNWIRED in this phase)." -f $script:UserInfoFileData.Count) -ForegroundColor Green
		}
		# PAX4A-INGEST-END

		if (-not $UseEOM) {
			$null = Invoke-Agent365EarlyInteractiveSignIn
		}
		
		# Fetch user directory and license data if requested (Graph API mode only)
		$script:LicenseData = $null
		$script:EntraUsersData = $null
		# Entra user directory fetch outcome flags. Surfaced in the
		# end-of-run summary and exit code so a failed/partial directory fetch can never
		# be silently masked behind "Enterprise Export Complete".
		$script:EntraUsersFetchFailed = $false
		$script:EntraUsersFetchError = $null
		$script:EntraUsersPartial = $false
		if ($IncludeUserInfo -and -not $UseEOM) {
			Write-LogHost "Fetching Entra user directory and license data..." -ForegroundColor Cyan
			$uiFileMode = ($PSBoundParameters.ContainsKey('UserInfoFile') -and -not [string]::IsNullOrWhiteSpace($UserInfoFile))
			# Bulk license fetch runs for the live-directory path exactly as before. For the -UserInfoFile
			# path it is deferred and only invoked on demand, so a fully
			# file-supplied directory stays offline.
			if (-not $uiFileMode) { $script:LicenseData = Get-UserLicenseData }
			if ($uiFileMode) {
				# -UserInfoFile supplies the Entra user directory from a customer-provided CSV.
				# Skip the Graph /users directory pull entirely and use the ingested, schema-completed rows.
				Write-LogHost "-UserInfoFile provided: using supplied user directory (skipping Graph /users pull)." -ForegroundColor Cyan
				$script:EntraUsersData = $script:UserInfoFileData
				# PAX4D-LICENSE-HYBRID-BEGIN
				# License hybrid: a file-provided HasLicense value WINS and is used as-is (no online
				# check). Rows with a BLANK HasLicense are resolved online by UPN from the existing bulk
				# Get-UserLicenseData. When NO row is blank the online lookup is skipped entirely (fully offline
				# directory build). File-provided values are never overwritten by online data.
				$uiFromFile = @($script:EntraUsersData | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.hasLicense) })
				$uiBlank    = @($script:EntraUsersData | Where-Object { [string]::IsNullOrWhiteSpace([string]$_.hasLicense) })
				$uiResolved = 0
				$uiFailed   = 0
				if ($uiBlank.Count -eq 0) {
					Write-LogHost ("license: {0} user(s) from file (no online check); 0 blank -> online license lookup skipped (fully offline)." -f $uiFromFile.Count) -ForegroundColor Green
				}
				else {
					$script:LicenseData = Get-UserLicenseData
					foreach ($uiRow in $uiBlank) {
						$uiUpn = [string]$uiRow.userPrincipalName
						if ($script:LicenseData -and $script:LicenseData.UserHasCopilot.ContainsKey($uiUpn)) {
							$uiRow.hasLicense = [bool]$script:LicenseData.UserHasCopilot[$uiUpn]
							if ([string]::IsNullOrWhiteSpace([string]$uiRow.assignedLicenses) -and $script:LicenseData.UserLicenses.ContainsKey($uiUpn)) {
								$uiRow.assignedLicenses = ($script:LicenseData.UserLicenses[$uiUpn] -join ';')
							}
							$uiResolved++
						}
						else {
							Write-LogHost ("  license: online lookup failed for '{0}' (UPN not found) - left blank, treated as unlicensed." -f $uiUpn) -ForegroundColor Yellow
							$uiFailed++
						}
					}
					Write-LogHost ("license: {0} user(s) from file (no online check); {1} resolved online by UPN; {2} failed online lookup (left blank, treated as unlicensed). File-provided values are used as-is; remove a row's HasLicense value to force the online check." -f $uiFromFile.Count, $uiResolved, $uiFailed) -ForegroundColor Green
				}
				# PAX4D-LICENSE-HYBRID-END
				Test-EntraUsersSchema -Users $script:EntraUsersData -Quiet
			}
			else {
				$script:EntraUsersData = Get-EntraUsersData
				# PAX-UIS-MERGE-BEGIN
				# Hybrid directory enrichment (-UserInfoSupplement): the live Entra directory has just been
				# fetched above. Append the columns of a customer-provided supplemental CSV to each matching
				# Entra row via an Entra-LEFT join on UserPrincipalName. Entra stays authoritative: every Entra
				# user is preserved, supplemental-only rows are reported and excluded, and the supplemental UPN
				# is a join key only (never copied into output). Runs before scope consumers, CSV writing,
				# Rollup, AISID projection, and append reconciliation.
				if ($script:UserInfoSupplementActive) {
					$uisNoticeLines = [System.Collections.Generic.List[string]]::new()
					if ($script:PaxDeidEnabled -or $Deidentify) {
						$uisNoticeLines.Add("  -UserInfoSupplement + -Deidentify: the supplemental UserPrincipalName is used ONLY to match rows; it is never copied into the output. Output identity always comes from Entra.")
						$uisNoticeLines.Add("  PAX de-identifies Entra-derived identity fields as usual, but passes EVERY other supplemental column and value through UNCHANGED - PAX does not inspect, mask, hash, or de-identify supplemental values.")
						$uisNoticeLines.Add("  You are responsible for ensuring the supplemental values are appropriate to export.")
					}
					if ($Dashboard -eq 'AISID') {
						$uisNoticeLines.Add("  -UserInfoSupplement + -Dashboard AISID: supplemental columns remain in the normal EntraUsers export and in the AIO/ValueLens Rollup Users dimension where applicable, but the AISID EntraUsers.csv keeps its fixed 14-column dashboard schema and does NOT receive supplemental columns.")
					}
					if ($uisNoticeLines.Count -gt 0) {
						Write-LogHost ""
						Write-LogHost "======================================================================" -ForegroundColor Yellow
						Write-LogHost "  HYBRID DIRECTORY SUPPLEMENT NOTICE" -ForegroundColor Yellow
						foreach ($ln in $uisNoticeLines) { Write-LogHost $ln -ForegroundColor Yellow }
						Write-LogHost "======================================================================" -ForegroundColor Yellow
						Write-LogHost ""
					}
					$uisPlan = $null
					try {
						$uisPlan = script:Resolve-DirectoryCsvInput -Value $UserInfoSupplement -SwitchName 'UserInfoSupplement' -ScratchDir $OutputPath -ScratchPrefix '.pax_userinfosupp_'
					}
					catch {
						Write-LogHost ("ERROR: -UserInfoSupplement could not be fetched from '{0}': {1}" -f $UserInfoSupplement.Trim(), $_.Exception.Message) -ForegroundColor Red
						throw
					}
					if (-not (Test-Path -LiteralPath $uisPlan.LocalPath -PathType Leaf)) {
						Write-LogHost ("ERROR: -UserInfoSupplement not found or unreadable: {0}" -f $UserInfoSupplement.Trim()) -ForegroundColor Red
						throw "-UserInfoSupplement not found or unreadable: $($UserInfoSupplement.Trim())"
					}
					# Parse + validate (throws a clear message on any violation). A staged remote input is
					# intentionally PRESERVED on a failure for diagnosis; it is removed only after success.
					$uisParsed = script:Import-PaxSupplementCsv -Path $uisPlan.LocalPath
					$uisMerge  = script:Merge-PaxEntraSupplement -EntraRows @($script:EntraUsersData) -PassthroughColumns $uisParsed.PassthroughColumns -Lookup $uisParsed.Lookup -UpnColumn $uisParsed.UpnColumn
					$script:EntraUsersData = $uisMerge.Rows
					Write-LogHost ("-UserInfoSupplement ({0}): {1} supplemental row(s) read; {2} column(s) appended [{3}]." -f $uisPlan.Tier, @($uisParsed.Rows).Count, @($uisMerge.ColumnsAdded).Count, (@($uisMerge.ColumnsAdded) -join ', ')) -ForegroundColor Green
					Write-LogHost ("  Entra users examined: {0}; matched supplemental rows: {1}; Entra users without supplemental values: {2}." -f @($script:EntraUsersData).Count, $uisMerge.Matched, $uisMerge.EntraWithout) -ForegroundColor DarkCyan
					if (@($uisMerge.UnmatchedSupplemental).Count -gt 0) {
						Write-LogHost ("  {0} supplemental row(s) did not match any Entra user and were EXCLUDED (Entra remains authoritative; no synthetic directory users were created):" -f @($uisMerge.UnmatchedSupplemental).Count) -ForegroundColor Yellow
						foreach ($uUpn in @($uisMerge.UnmatchedSupplemental)) { Write-LogHost ("    excluded (unmatched supplemental UPN): {0}" -f $uUpn) -ForegroundColor Yellow }
					}
					try {
						$script:metrics.SupplementTier             = $uisPlan.Tier
						$script:metrics.SupplementRowsRead          = @($uisParsed.Rows).Count
						$script:metrics.SupplementColumnsAdded      = @($uisMerge.ColumnsAdded).Count
						$script:metrics.SupplementMatched           = $uisMerge.Matched
						$script:metrics.SupplementUnmatchedExcluded = @($uisMerge.UnmatchedSupplemental).Count
					} catch {}
					if ($uisPlan.Staged -and (Test-Path -LiteralPath $uisPlan.LocalPath -PathType Leaf)) {
						try { Remove-Item -LiteralPath $uisPlan.LocalPath -Force -ErrorAction SilentlyContinue } catch {}
					}
				}
				# PAX-UIS-MERGE-END
			}
		}
		elseif ($IncludeUserInfo -and $UseEOM) {
			Write-LogHost "WARNING: -IncludeUserInfo requires Graph API mode (not supported with -UseEOM)" -ForegroundColor Yellow
			Write-LogHost "         EntraUsers output will not be generated" -ForegroundColor Yellow
			Write-LogHost ""
		}
	}
	
	# When -OnlyUserInfo is combined with a user/group scope, narrow the exported Entra
	# directory to that scope. The scope resolves as one fail-closed union; a requested
	# scope that cannot be resolved stops the run so the export never silently widens to
	# the whole tenant. Zero matched rows is a truthful empty scoped export, never all users.
	if ($OnlyUserInfo -and ($UserIds -or $GroupNames)) {
		$dirRosterValidator = $null
		if ($script:EntraUsersData -and @($script:EntraUsersData).Count -gt 0) {
			$dirRosterUpns = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
			foreach ($ru in @($script:EntraUsersData)) { $rupn = [string]$ru.userPrincipalName; if ($rupn) { [void]$dirRosterUpns.Add($rupn.Trim()) } }
			$dirRosterValidator = { param($u) $dirRosterUpns.Contains(([string]$u).Trim()) }.GetNewClosure()
		}
		$dirScope = Resolve-PaxUserScope -UserIds $UserIds -GroupNames $GroupNames -UseEOMMode $UseEOM -RosterValidator $dirRosterValidator
		$script:metrics.FilteringUserIds     = @($dirScope.RequestedUserIds).Count
		$script:metrics.FilteringGroupNames  = @($dirScope.RequestedGroups).Count
		$script:metrics.ScopeResolvedGroups  = @($dirScope.ResolvedGroups).Count
		$script:metrics.ScopeFailedGroups    = @($dirScope.FailedGroups).Count + @($dirScope.AmbiguousGroups).Count + @($dirScope.ZeroMemberGroups).Count + @($dirScope.UnauthorizedGroups).Count + @($dirScope.TransportErrorGroups).Count + @($dirScope.ResolutionErrorGroups).Count
		$script:metrics.ScopeExpandedMembers = @($dirScope.ResolvedTransitiveMembers).Count
		$script:metrics.ScopeFinalTargetUsers = @($dirScope.FinalTargetUsers).Count
		Write-LogHost ""; Write-LogHost "User/Group Scope Resolution (directory export):" -ForegroundColor Cyan
		Write-LogHost ("  Requested UserIds: {0}" -f @($dirScope.RequestedUserIds).Count) -ForegroundColor DarkCyan
		Write-LogHost ("  Requested GroupNames: {0}" -f @($dirScope.RequestedGroups).Count) -ForegroundColor DarkCyan
		if (@($dirScope.UnmatchedExplicitUserIds).Count -gt 0) {
			Write-LogHost ("  UserIds not found in directory: {0}" -f (@($dirScope.UnmatchedExplicitUserIds) -join ', ')) -ForegroundColor Yellow
		}
		foreach ($rg in @($dirScope.ResolvedGroups)) {
			Write-LogHost ("  Group '{0}' -> {1} direct / {2} transitive user(s) [{3}]" -f $rg.DisplayName, $rg.DirectMembers, $rg.TransitiveMembers, $rg.MembershipScope) -ForegroundColor DarkCyan
		}
		if ($dirScope.Outcome -ne 'Succeeded') {
			Write-LogHost "" -ForegroundColor Red
			Write-LogHost "ERROR: User/group scope could not be fully resolved; refusing to export an unscoped directory." -ForegroundColor Red
			if (@($dirScope.FailedGroups).Count -gt 0)    { Write-LogHost ("  Groups not found: {0}" -f (@($dirScope.FailedGroups) -join ', ')) -ForegroundColor Yellow }
			if (@($dirScope.AmbiguousGroups).Count -gt 0)  { Write-LogHost ("  Groups matching more than one directory object: {0}" -f (@($dirScope.AmbiguousGroups) -join ', ')) -ForegroundColor Yellow }
			if (@($dirScope.ZeroMemberGroups).Count -gt 0) { Write-LogHost ("  Groups with no user members: {0}" -f (@($dirScope.ZeroMemberGroups) -join ', ')) -ForegroundColor Yellow }
			if (@($dirScope.UnauthorizedGroups).Count -gt 0)    { Write-LogHost ("  Groups not accessible (authorization denied): {0}" -f (@($dirScope.UnauthorizedGroups) -join ', ')) -ForegroundColor Yellow }
			if (@($dirScope.TransportErrorGroups).Count -gt 0)   { Write-LogHost ("  Groups not resolved (transient/transport error): {0}" -f (@($dirScope.TransportErrorGroups) -join ', ')) -ForegroundColor Yellow }
			if (@($dirScope.ResolutionErrorGroups).Count -gt 0)  { Write-LogHost ("  Groups not resolved (unexpected error): {0}" -f (@($dirScope.ResolutionErrorGroups) -join ', ')) -ForegroundColor Yellow }
			Write-LogHost ("  Failure stage: {0}" -f $dirScope.FailureStage) -ForegroundColor Yellow
			Write-LogHost "" -ForegroundColor Red
			exit 1
		}
		$dirScopeSet = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
		foreach ($fu in @($dirScope.FinalTargetUsers)) { if ($fu) { [void]$dirScopeSet.Add(([string]$fu).Trim()) } }
		$dirBefore = @($script:EntraUsersData).Count
		$script:EntraUsersData = @(@($script:EntraUsersData) | Where-Object { $_ -and $dirScopeSet.Contains(([string]$_.userPrincipalName).Trim()) })
		$dirAfter = @($script:EntraUsersData).Count
		$script:metrics.DirectoryRowsBeforeScope     = $dirBefore
		$script:metrics.DirectoryRowsAfterScope      = $dirAfter
		$script:metrics.DirectoryRowsExcludedByScope = $dirBefore - $dirAfter
		Write-LogHost ("  Directory rows scoped: {0} -> {1} ({2} excluded)" -f $dirBefore, $dirAfter, ($dirBefore - $dirAfter)) -ForegroundColor Green; Write-LogHost ""
	}
	
	# Skip all audit log queries when only exporting user data or only exporting Agent 365 data
	if (-not $OnlyUserInfo -and -not $OnlyAgent365Info) {
		$allLogs = New-Object System.Collections.ArrayList
		if ($RAWInputCSV) {
		Write-LogHost "Replay mode enabled: ingesting raw Purview CSV '$RAWInputCSV' (no Graph/EOM connections)" -ForegroundColor Yellow
		if (-not (Test-Path $RAWInputCSV)) { Write-LogHost "Replay file not found: $RAWInputCSV" -ForegroundColor Red; exit 1 }
		# Stream the replay CSV (RFC-4180) instead of loading it whole. Filters are
		# applied per row as it is read; the raw-input array is never materialized and
		# the previously-dead $filteredRows collection is removed. The inline exporter
		# below consumes $allLogs one record at a time.
		$applyDateFilter = ($PSBoundParameters.ContainsKey('StartDate') -or $PSBoundParameters.ContainsKey('EndDate'))
		$applyActivityFilter = ($PSBoundParameters.ContainsKey('ActivityTypes') -and $ActivityTypes -and $ActivityTypes.Count -gt 0)
		$startFilter = $null; $endFilter = $null
		if ($applyDateFilter) {
			if ($PSBoundParameters.ContainsKey('StartDate')) { try { $startFilter = [datetime]::ParseExact($StartDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture) } catch {} }
			if ($PSBoundParameters.ContainsKey('EndDate')) { try { $endFilter = [datetime]::ParseExact($EndDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture) } catch {} }
		}
		$activitySet = $null
		if ($applyActivityFilter) { $activitySet = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase); foreach ($a in $ActivityTypes) { if ($a) { [void]$activitySet.Add($a) } } }
		# Accepted replay records are spilled to a re-iterable disk spool (JSON-lines)
		# instead of an in-memory ArrayList, so the complete replay set is never held in
		# memory. The inline exporter streams the spool; the fallback pass reopens it. The
		# spool is deleted on success and preserved on a failed export for recovery.
		$replaySpoolPath = Join-Path ([System.IO.Path]::GetTempPath()) ("pax_replay_spool_${global:ScriptRunTimestamp}_" + [guid]::NewGuid().ToString('N') + ".jsonl")
		$replayReader = [System.IO.StreamReader]::new((Resolve-Path -LiteralPath $RAWInputCSV).Path, $true)
		$replaySpoolWriter = [System.IO.StreamWriter]::new($replaySpoolPath, $false, ([System.Text.UTF8Encoding]::new($false)))
		$replayTotalRead = 0
		$replayAccepted = 0
		$replaySampleDone = $false
		try {
			$replayHeader = script:Read-PaxCsvRecord -Reader $replayReader
			if ($null -ne $replayHeader) {
				$replayCols = @($replayHeader | ForEach-Object { [string]$_ })
				$replayColCount = $replayCols.Length
				while ($true) {
					$rf = script:Read-PaxCsvRecord -Reader $replayReader
					if ($null -eq $rf) { break }
					$replayTotalRead++
					$rowMap = [ordered]@{}
					for ($ci = 0; $ci -lt $replayColCount; $ci++) { $rowMap[$replayCols[$ci]] = if ($ci -lt $rf.Length) { [string]$rf[$ci] } else { '' } }
					$row = [pscustomobject]$rowMap
					if (-not $replaySampleDone) {
						$replaySampleDone = $true
						try {
							$identity = if ($row.Id) { $row.Id } elseif ($row.RecordId) { $row.RecordId } else { [guid]::NewGuid().ToString() }
							$srec = [pscustomobject]@{
								RecordType   = $(try { [int]$row.RecordType } catch { 0 })
								CreationDate = $(if ($row.CreationDate) { $d = script:Parse-DateSafe $row.CreationDate; if ($d) { $d } else { Get-Date } } else { Get-Date })
								UserIds      = @(if ($row.UserIds) { $row.UserIds } elseif ($row.UserId) { $row.UserId } else { $null })
								Operations   = if ($row.Operations) { $row.Operations } elseif ($row.Operation) { $row.Operation } else { $null }
								ResultStatus = $(try { $row.ResultStatus } catch { '' })
								ResultCount  = 0
								Identity     = $identity
								IsValid      = $true
								ObjectState  = ''
								AuditData    = $row.AuditData
								Operation    = if ($row.Operation) { $row.Operation } elseif ($row.Operations) { $row.Operations } else { $null }
								UserId       = if ($row.UserId) { $row.UserId } elseif ($row.UserIds) { $row.UserIds } else { $null }
							}
							$sampleOut = Convert-ToPurviewExplodedRecords -Record $srec -SkipMetrics
						} catch {
							Write-LogHost ("Replay sample conversion failed: {0}" -f $_.Exception.Message) -ForegroundColor DarkYellow
						}
					}
					$keep = $true
					$creationRaw = $row.CreationDate
					$creation = if ($creationRaw) { script:Parse-DateSafe $creationRaw } else { $null }
					if ($applyDateFilter -and $creation) {
						if ($startFilter -and $creation -lt $startFilter) { $keep = $false }
						if ($endFilter -and $creation -ge $endFilter) { $keep = $false }
					}
					if ($keep -and $applyActivityFilter) {
						$op = if ($row.Operation) { $row.Operation } elseif ($row.Operations) { $row.Operations } else { $null }
						if (-not $op -or -not $activitySet.Contains([string]$op)) { $keep = $false }
					}
					if (-not $keep) { continue }
					# Spill the accepted raw row to the disk spool; the normalized replay
					# record is rebuilt from it (identically) at export time.
					$replaySpoolWriter.WriteLine(($row | ConvertTo-Json -Compress -Depth 5))
					$replayAccepted++
					if (($replayAccepted % 5000) -eq 0) { try { Write-PaxMemoryObservation -Stage 'ReplaySpool' -RowsProcessed ([long]$replayAccepted) } catch {} }
				}
			}
		}
		finally { try { $replaySpoolWriter.Flush(); $replaySpoolWriter.Dispose() } catch {}; $replayReader.Dispose() }
		Write-LogHost ("Replay rows ingested: {0}" -f $replayTotalRead) -ForegroundColor DarkGray
		$ingested = $replayAccepted
		Write-LogHost ("Replay rows after filters: {0}" -f $ingested) -ForegroundColor DarkGray
		# Inline export for replay: stream from the re-iterable spool (no in-memory set).
		try {
			Invoke-ReplayInlineExport -SpoolPath $replaySpoolPath
			try { if (Test-Path -LiteralPath $replaySpoolPath) { Remove-Item -LiteralPath $replaySpoolPath -Force -ErrorAction SilentlyContinue } } catch {}
			return
		}
		catch {
			Write-LogHost ("Replay inline export failed: {0}. Spool preserved for recovery at: {1}" -f $_.Exception.Message, $replaySpoolPath) -ForegroundColor Yellow
		}
		$queryPlan = @(); $sequentialGroups = 0; $parallelDecision = @{ Enabled = $false; Reason = 'Replay'; AutoEligible = $false }; $parallelOverallEnabled = $false
		$script:metrics.TotalRecordsFetched = $ingested
		$script:progressState.Query.Total = 1; $script:progressState.Query.Current = 1
		}
		else {
			# Live audit log query mode
			
			# Diagnostic query removed to reduce throttling overhead
			# Authentication and connectivity will be validated on first actual query
			
			$script:targetUsers = @()
			if ($UserIds -or $GroupNames) {
				# Resolve the effective user scope as a single fail-closed union of explicit
				# UserIds and group members. A requested scope that cannot be fully resolved
				# stops the run so a query never widens to the whole tenant.
				$rosterValidator = $null
				if ($script:EntraUsersData -and @($script:EntraUsersData).Count -gt 0) {
					$rosterUpns = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
					foreach ($ru in @($script:EntraUsersData)) { $rupn = [string]$ru.userPrincipalName; if ($rupn) { [void]$rosterUpns.Add($rupn.Trim()) } }
					$rosterValidator = { param($u) $rosterUpns.Contains(([string]$u).Trim()) }.GetNewClosure()
				}
				$resolvedScope = Resolve-PaxUserScope -UserIds $UserIds -GroupNames $GroupNames -UseEOMMode $UseEOM -RosterValidator $rosterValidator
				$script:metrics.FilteringUserIds     = @($resolvedScope.RequestedUserIds).Count
				$script:metrics.FilteringGroupNames  = @($resolvedScope.RequestedGroups).Count
				$script:metrics.ScopeResolvedGroups  = @($resolvedScope.ResolvedGroups).Count
				$script:metrics.ScopeFailedGroups    = @($resolvedScope.FailedGroups).Count + @($resolvedScope.AmbiguousGroups).Count + @($resolvedScope.ZeroMemberGroups).Count + @($resolvedScope.UnauthorizedGroups).Count + @($resolvedScope.TransportErrorGroups).Count + @($resolvedScope.ResolutionErrorGroups).Count
				$script:metrics.ScopeExpandedMembers = @($resolvedScope.ResolvedTransitiveMembers).Count
				$script:metrics.ScopeFinalTargetUsers = @($resolvedScope.FinalTargetUsers).Count
				Write-LogHost ""; Write-LogHost "User/Group Scope Resolution:" -ForegroundColor Cyan
				Write-LogHost ("  Requested UserIds: {0}" -f @($resolvedScope.RequestedUserIds).Count) -ForegroundColor DarkCyan
				Write-LogHost ("  Requested GroupNames: {0}" -f @($resolvedScope.RequestedGroups).Count) -ForegroundColor DarkCyan
				if (@($resolvedScope.UnmatchedExplicitUserIds).Count -gt 0) {
					if ($Dashboard -eq 'AISID') {
						# F3 fail-closed: under -Dashboard AISID the EntraUsers dimension is REQUIRED, so every
						# explicitly requested target UPN MUST resolve in the authenticated Entra directory. An
						# unmatched explicit target (e.g. the wrong tenant/account was signed in) makes the scoped
						# dashboard invalid, so the run stops BEFORE any audit query or publication — no Purview,
						# Rollup, or AISID customer data is produced. Directory membership is checked against the real
						# roster (never inferred from the UPN suffix, no tenant/domain assumed). The established AISID
						# gap flag drives the finally-block exit precedence to a nonzero result (exit 40); a bare
						# 'exit 1' alone would be overwritten by that recompute, so the flag is what makes it truthful.
						$script:AISIDHadGaps = $true
						Write-LogHost "" -ForegroundColor Red
						Write-LogHost ("ERROR: -Dashboard AISID requires every requested user to exist in the authenticated Entra directory; not found: {0}" -f (@($resolvedScope.UnmatchedExplicitUserIds) -join ', ')) -ForegroundColor Red
						Write-LogHost "  The AISID EntraUsers dimension cannot be scoped to a user who is absent from the signed-in tenant's directory." -ForegroundColor Yellow
						Write-LogHost "  Sign in to the tenant that contains the requested user, or request a user that exists in the current directory, then retry." -ForegroundColor Cyan
						Write-LogHost "  No audit query was run and no output was produced." -ForegroundColor Yellow
						Write-LogHost "" -ForegroundColor Red
						exit 1
					}
					else {
						Write-LogHost ("  UserIds not found in directory (still included in scope): {0}" -f (@($resolvedScope.UnmatchedExplicitUserIds) -join ', ')) -ForegroundColor Yellow
					}
				}
				foreach ($rg in @($resolvedScope.ResolvedGroups)) {
					Write-LogHost ("  Group '{0}' -> {1} direct / {2} transitive user(s) [{3}]" -f $rg.DisplayName, $rg.DirectMembers, $rg.TransitiveMembers, $rg.MembershipScope) -ForegroundColor DarkCyan
				}
				if ($resolvedScope.Outcome -ne 'Succeeded') {
					Write-LogHost "" -ForegroundColor Red
					Write-LogHost "ERROR: User/group scope could not be fully resolved; refusing to run an unfiltered audit query." -ForegroundColor Red
					if (@($resolvedScope.FailedGroups).Count -gt 0)    { Write-LogHost ("  Groups not found: {0}" -f (@($resolvedScope.FailedGroups) -join ', ')) -ForegroundColor Yellow }
					if (@($resolvedScope.AmbiguousGroups).Count -gt 0)  { Write-LogHost ("  Groups matching more than one directory object: {0}" -f (@($resolvedScope.AmbiguousGroups) -join ', ')) -ForegroundColor Yellow }
					if (@($resolvedScope.ZeroMemberGroups).Count -gt 0) { Write-LogHost ("  Groups with no user members: {0}" -f (@($resolvedScope.ZeroMemberGroups) -join ', ')) -ForegroundColor Yellow }
					if (@($resolvedScope.UnauthorizedGroups).Count -gt 0)    { Write-LogHost ("  Groups not accessible (authorization denied): {0}" -f (@($resolvedScope.UnauthorizedGroups) -join ', ')) -ForegroundColor Yellow }
					if (@($resolvedScope.TransportErrorGroups).Count -gt 0)   { Write-LogHost ("  Groups not resolved (transient/transport error): {0}" -f (@($resolvedScope.TransportErrorGroups) -join ', ')) -ForegroundColor Yellow }
					if (@($resolvedScope.ResolutionErrorGroups).Count -gt 0)  { Write-LogHost ("  Groups not resolved (unexpected error): {0}" -f (@($resolvedScope.ResolutionErrorGroups) -join ', ')) -ForegroundColor Yellow }
					Write-LogHost ("  Failure stage: {0}" -f $resolvedScope.FailureStage) -ForegroundColor Yellow
					Write-LogHost "  Verify the group name(s) and that the sign-in has GroupMember.Read.All, then retry." -ForegroundColor Cyan
					Write-LogHost "" -ForegroundColor Red
					exit 1
				}
				$script:targetUsers = @($resolvedScope.FinalTargetUsers)
				if ($script:targetUsers.Count -eq 0) {
					Write-LogHost "" -ForegroundColor Red
					Write-LogHost "ERROR: A user/group scope was requested but resolved to zero users; refusing to run an unfiltered audit query." -ForegroundColor Red
					Write-LogHost "" -ForegroundColor Red
					exit 1
				}
				Write-LogHost ("  Effective target users (deduplicated union): {0}" -f $script:targetUsers.Count) -ForegroundColor Green; Write-LogHost ""
				# Apply that same resolved scope to the directory roster so a scoped run publishes
				# only in-scope users to the Entra users CSV, the workbook Entra tab, the Rollup
				# Users input, and any append or upload built from them. The scope is resolved once
				# per run above and applied once here, so group membership is never expanded twice
				# and a requested scope cannot widen: an unresolvable scope or an empty union has
				# already stopped the run. -OnlyUserInfo scopes its roster from its own resolution
				# and is excluded here. UPN matching is case-insensitive and trimmed.
				if ($IncludeUserInfo -and -not $OnlyUserInfo -and $script:EntraUsersData -and @($script:EntraUsersData).Count -gt 0) {
					$normScopeSet = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
					foreach ($fu in @($resolvedScope.FinalTargetUsers)) { if ($fu) { [void]$normScopeSet.Add(([string]$fu).Trim()) } }
					$normBefore = @($script:EntraUsersData).Count
					$script:EntraUsersData = @(@($script:EntraUsersData) | Where-Object { $_ -and $normScopeSet.Contains(([string]$_.userPrincipalName).Trim()) })
					$normAfter = @($script:EntraUsersData).Count
					$script:metrics.DirectoryRowsBeforeScope     = $normBefore
					$script:metrics.DirectoryRowsAfterScope      = $normAfter
					$script:metrics.DirectoryRowsExcludedByScope = $normBefore - $normAfter
					Write-LogHost ("  Directory rows scoped: {0} -> {1} ({2} excluded)" -f $normBefore, $normAfter, ($normBefore - $normAfter)) -ForegroundColor Green; Write-LogHost ""
				}
			}
		$startDateObj = [datetime]::ParseExact($StartDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture)
		$endDateObj = [datetime]::ParseExact($EndDate, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture)
		
		if ($OnlyUserInfo) {
			Write-LogHost "Fetching Entra user directory and license data only (no audit logs)..." -ForegroundColor Cyan
			Write-LogHost ""
		} else {
			Write-LogHost "Starting enterprise-grade audit log search..." -ForegroundColor Yellow
			Write-LogHost "Date range: $($startDateObj.ToString('yyyy-MM-dd')) (inclusive) to $($endDateObj.ToString('yyyy-MM-dd')) (exclusive)" -ForegroundColor Gray
		}
		
		# Adaptive block sizing only applies to EOM mode (Graph API uses partitioning instead)
		if ($UseEOM -and -not $OnlyUserInfo) {
			Write-LogHost ""; Write-LogHost "Initializing adaptive block sizing (EOM mode)..." -ForegroundColor Cyan
		}
		
		# --- Build final ActivityTypes array (additive logic with exclusion override) ---
		Write-LogHost ""  # preserve a blank spacer line for readability without header
		
		$finalActivityTypes = @()
		
		# Step 1: Add explicit -ActivityTypes parameter values (if provided and not default)
		if ($PSBoundParameters.ContainsKey('ActivityTypes') -and $ActivityTypes) {
			foreach ($actType in $ActivityTypes) {
				if ($actType -and $actType -ne '') {
					$finalActivityTypes += $actType
				}
			}
			if ($finalActivityTypes.Count -gt 0) {
				Write-LogHost "Custom ActivityTypes provided: $($finalActivityTypes -join ', ')" -ForegroundColor Gray
			}
		}

	# Step 3: Add CopilotInteraction when explicitly requested
	if ($IncludeCopilotInteraction -and -not ($finalActivityTypes -contains $copilotBaseActivityType)) {
		$finalActivityTypes += $copilotBaseActivityType
		Write-LogHost "IncludeCopilotInteraction: Adding $copilotBaseActivityType (explicit request)" -ForegroundColor Cyan
	}

	# Step 4: Add Microsoft 365 usage bundle when requested
	if ($IncludeM365Usage) {
		$finalActivityTypes += $m365UsageActivityBundle
		Write-LogHost ("M365 Usage bundle: Adding {0} activity types across Exchange/SharePoint/OneDrive/Teams" -f $m365UsageActivityBundle.Count) -ForegroundColor Cyan

		$RecordTypes = @(
			if ($RecordTypes) { $RecordTypes }
			$m365UsageRecordBundle
		) | Where-Object { $_ } | Select-Object -Unique
		if ($RecordTypes.Count -eq 0) { $RecordTypes = $null }

		# CRITICAL: Set ServiceTypes to NULL for IncludeM365Usage mode
		# This prevents splitting into 4 workload passes (Exchange, SharePoint, OneDrive, Teams)
		# and instead creates a single workload pass that queries all M365 operations together
		$ServiceTypes = $null
		Write-LogHost "M365 Usage bundle: ServiceTypes => NULL (single workload pass)" -ForegroundColor Gray

		if ($RecordTypes) {
			Write-LogHost "M365 Usage bundle: RecordTypes => $($RecordTypes -join ', ')" -ForegroundColor Gray
		}
	}
	if ($RAWInputCSV) {
		Invoke-ReplayInlineExport -SpoolPath $replaySpoolPath
			try { if (Test-Path -LiteralPath $replaySpoolPath) { Remove-Item -LiteralPath $replaySpoolPath -Force -ErrorAction SilentlyContinue } } catch {}
			# Skip the rest of the pipeline; replay handled
			return
		}

	# Step 5: BASE ACTIVITY TYPE - Add CopilotInteraction as default base type
	# This is the core Microsoft 365 Copilot activity type (FREE, included in M365 Copilot licensing)
	# Captures ALL M365 Copilot usage including Teams meetings, Word, Excel, PowerPoint, Outlook, etc.
	# Auto-add when the user did not explicitly provide -ActivityTypes.
	# Exception: Always respect -ExcludeCopilotInteraction (handled in Step 6)
	$userProvidedCustomTypes = $PSBoundParameters.ContainsKey('ActivityTypes')
	if (-not $ExcludeCopilotInteraction) {
		# Auto-add only when no custom types were provided
		if (-not $userProvidedCustomTypes) {
			# Add CopilotInteraction if not already present
			if (-not ($finalActivityTypes -contains $copilotBaseActivityType)) {
				$finalActivityTypes = @($copilotBaseActivityType) + $finalActivityTypes
			}
		}
	}

	# Step 6: EXCLUSION OVERRIDE - Remove CopilotInteraction if -ExcludeCopilotInteraction is true
		if ($ExcludeCopilotInteraction) {
			$beforeExclusion = $finalActivityTypes.Count
			$finalActivityTypes = $finalActivityTypes | Where-Object { $_ -ne $copilotBaseActivityType }
			$afterExclusion = $finalActivityTypes.Count
			if ($beforeExclusion -ne $afterExclusion) {
				$removedCount = $beforeExclusion - $afterExclusion
				Write-LogHost "EXCLUSION: Removed $removedCount M365 Copilot activity type (ExcludeCopilotInteraction switch)" -ForegroundColor Red
			}
			else {
				Write-LogHost "EXCLUSION: No M365 Copilot type in list (ExcludeCopilotInteraction switch active)" -ForegroundColor DarkGray
			}
		}
		
		# Step 7: Deduplicate
		$finalActivityTypes = $finalActivityTypes | Select-Object -Unique
		
		# Step 8: Validate array not empty
		if ($finalActivityTypes.Count -eq 0) {
			Write-LogHost ""
			Write-LogHost "ERROR: No activity types remain after processing." -ForegroundColor Red
			Write-LogHost "You excluded CopilotInteraction but provided no other activity types." -ForegroundColor Yellow
			Write-LogHost "Please specify activity types using -ActivityTypes." -ForegroundColor Yellow
			Write-LogHost ""
			exit 1
		}
		
		# Step 9: Apply to ActivityTypes variable
	$ActivityTypes = $finalActivityTypes
	
		# Update Parameter Snapshot with final ActivityTypes (if it exists)
	if ($paramSnapshot -and $paramSnapshot.Contains('ActivityTypes')) {
		$paramSnapshot['ActivityTypes'] = ($ActivityTypes -join ';')
	}

	# On a -Resume run, refresh other snapshot fields that the parse-time build
	# captured BEFORE the checkpoint restore mutated them. Without this patch the
	# displayed banner shows stale CLI-bound defaults (Auth=WebLogin, TenantId=<empty>,
	# RollupPlusRaw=False, etc.) even though the run is actually executing the
	# restored values. Resume-only so non-resume runs are untouched.
	if ($script:IsResumeMode -and $paramSnapshot) {
		# Auth identity
		if ($paramSnapshot.Contains('Auth'))     { $paramSnapshot['Auth']     = $Auth }
		if ($paramSnapshot.Contains('TenantId')) { $paramSnapshot['TenantId'] = $(if ($TenantId) { $TenantId } elseif ($env:GRAPH_TENANT_ID) { '[GRAPH_TENANT_ID]' } else { '' }) }
		if ($paramSnapshot.Contains('ClientId')) { $paramSnapshot['ClientId'] = $(if ($ClientId) { $ClientId } elseif ($env:GRAPH_CLIENT_ID) { '[GRAPH_CLIENT_ID]' } else { '' }) }
		# Output / append routing (mutually-exclusive pairs in the destinations cluster).
		# The snapshot decided which key to emit at parse time based on $PSBoundParameters
		# (always false on resume) — so OutputFile/EntraUsersOutput/Agents365Output were
		# emitted and AppendFile/AppendUserInfo/AppendAgent365Info were absent. Patch the
		# value if the key exists; do not add the Append* keys (avoids two-line duplication).
		if ($paramSnapshot.Contains('AppendFile')         -and $AppendFile)         { $paramSnapshot['AppendFile']         = $AppendFile }
		if ($paramSnapshot.Contains('AppendUserInfo')     -and $AppendUserInfo)     { $paramSnapshot['AppendUserInfo']     = $AppendUserInfo }
		if ($paramSnapshot.Contains('AppendAgent365Info') -and $AppendAgent365Info) { $paramSnapshot['AppendAgent365Info'] = $AppendAgent365Info }
		# Flag switches
		if ($paramSnapshot.Contains('IncludeUserInfo'))     { $paramSnapshot['IncludeUserInfo']     = $IncludeUserInfo.IsPresent }
		if ($paramSnapshot.Contains('IncludeAgent365Info')) { $paramSnapshot['IncludeAgent365Info'] = $IncludeAgent365Info.IsPresent }
		if ($paramSnapshot.Contains('IncludeM365Usage'))    { $paramSnapshot['IncludeM365Usage']    = $IncludeM365Usage.IsPresent }
		if ($paramSnapshot.Contains('CombineOutput'))       { $paramSnapshot['CombineOutput']       = $CombineOutput.IsPresent }
		if ($paramSnapshot.Contains('ExportWorkbook'))      { $paramSnapshot['ExportWorkbook']      = $ExportWorkbook.IsPresent }
		if ($paramSnapshot.Contains('Rollup'))              { $paramSnapshot['Rollup']              = $Rollup.IsPresent }
		if ($paramSnapshot.Contains('RollupPlusRaw'))       { $paramSnapshot['RollupPlusRaw']       = $RollupPlusRaw.IsPresent }
		if ($paramSnapshot.Contains('Dashboard'))           { $paramSnapshot['Dashboard']           = $Dashboard }
		# Deidentify / FillerLabel / FillerLabelText are checkpoint-driven on resume (the
		# resume allow-list blocks them on the CLI and the restore block re-arms $Deidentify /
		# $script:HierarchyFillMode / $script:HierarchyFillLabel). The parse-time snapshot
		# captured the pre-restore defaults (False / none / empty), so without these patches a
		# resumed run's banner misreports privacy + filler state even though both are applied.
		if ($paramSnapshot.Contains('Deidentify'))          { $paramSnapshot['Deidentify']          = $Deidentify.IsPresent }
		if ($paramSnapshot.Contains('FillerLabel'))         { $paramSnapshot['FillerLabel']         = $script:HierarchyFillMode }
		if ($paramSnapshot.Contains('FillerLabelText'))     { $paramSnapshot['FillerLabelText']     = $script:HierarchyFillLabel }
		if ($paramSnapshot.Contains('IncludeCopilotInteraction')) {
			$paramSnapshot['IncludeCopilotInteraction'] = $IncludeCopilotInteraction.IsPresent -or ($ActivityTypes -contains $copilotBaseActivityType)
		}
		if ($paramSnapshot.Contains('ExcludeCopilotInteraction')) { $paramSnapshot['ExcludeCopilotInteraction'] = $ExcludeCopilotInteraction.IsPresent }
		if ($paramSnapshot.Contains('MaxMemoryMB')) {
			$paramSnapshot['MaxMemoryMB'] = $(if ($script:ResolvedMaxMemoryMB -eq 0) { 'Off' } else { "$($script:ResolvedMaxMemoryMB)MB" + $(if ($MaxMemoryMB -eq -1) { ' (auto)' } else { '' }) })
		}
		# PartitionHours: the parse-time builder captured the resume-CLI default ('auto'
		# because PartitionHours was unbound on resume) BEFORE the checkpoint restore set
		# $PartitionHours to the original run's value. Patch using the same formula the
		# parse-time builder uses so an originally-bound integer (e.g. 24) is rehydrated
		# correctly and an originally-auto run remains 'auto' (the partition-planning
		# block will subsequently rewrite the snapshot to '<N> (auto)' if auto-adjustment
		# fires).
		if ($paramSnapshot.Contains('PartitionHours')) {
			$paramSnapshot['PartitionHours'] = if ($PartitionHours -gt 0) { $PartitionHours } else { 'auto' }
		}
		# Date range: the parse-time snapshot captured $StartDate/$EndDate BEFORE the
		# checkpoint restore overwrote them, so the displayed banner would show the
		# auto-populated yesterday/today defaults instead of the original run's dates.
		# Patch with the post-restore values so the snapshot reflects what is actually
		# being processed.
		if ($paramSnapshot.Contains('StartDate (inclusive)')) { $paramSnapshot['StartDate (inclusive)'] = $StartDate }
		if ($paramSnapshot.Contains('EndDate (exclusive)'))   { $paramSnapshot['EndDate (exclusive)']   = $EndDate }

		# Refresh destination-cluster fields. Parse-time captured $displayOutputFile /
		# $displayLogFile from the user-bound (default) values and routed them through
		# Get-DisplayPath while $script:RemoteOutputMode was still 'None' (resume-mode
		# parse time). After the destination re-resolution above,
		# $script:RemoteOutputMode/$script:RemoteOutputUrl are correct and $OutputFile /
		# $LogFile have been restored to the checkpoint's _PARTIAL paths. Re-derive both
		# display values using the same formula so SharePoint AND Fabric resumes show the
		# correct remote URL (and local resumes show the correct local path).
		if ($paramSnapshot.Contains('OutputFile')) {
			$resumeDisplayOutputFile = $OutputFile -replace '_PARTIAL(?=\.[^.]+$)', ''
			$paramSnapshot['OutputFile'] = Get-DisplayPath -LocalPath $resumeDisplayOutputFile
		}
		if ($paramSnapshot.Contains('LogFile')) {
			$resumeDisplayLogFile = $LogFile -replace '_PARTIAL(?=\.log$)', ''
			$paramSnapshot['LogFile'] = Get-DisplayPath -LocalPath $resumeDisplayLogFile
		}
		# Aux streams (EntraUsers / Agents365). $resolveAuxDisplayPath was a parse-time
		# closure not in scope here; rebuild the equivalent inline. Only patch when the
		# corresponding stream is enabled and a path was already captured in the snapshot.
		# Consult script:Resolve-DataTypePaths so Local-tier per-stream overrides
		# (-OutputPathUserInfo / -OutputPathAgent365Info pointing at a local directory)
		# are honored — not just remote tiers — matching the parse-time closure semantics.
		if ($paramSnapshot.Contains('EntraUsersOutput') -and ($IncludeUserInfo -or $OnlyUserInfo) -and -not $ExportWorkbook) {
			$auxLeaf = & $script:GetEffectiveEntraBasename
			$_uiDtR = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename $auxLeaf
			if ($_uiDtR -and $_uiDtR.IsBound -and $_uiDtR.Tier -eq 'Local') {
				$paramSnapshot['EntraUsersOutput'] = Get-DisplayPath -LocalPath (Join-Path $_uiDtR.EffectiveDir $_uiDtR.Basename)
			} elseif ($_uiDtR -and $_uiDtR.IsBound) {
				$paramSnapshot['EntraUsersOutput'] = $_uiDtR.EffectiveDir.TrimEnd('/') + '/' + $_uiDtR.Basename
			} elseif ($script:DestRaw.ContainsKey('UserInfo') -and $script:DestTier['UserInfo'] -ne 'Local') {
				$paramSnapshot['EntraUsersOutput'] = (($script:DestParentUrl['UserInfo'] ?? $script:DestRaw['UserInfo']).TrimEnd('/') + '/' + $auxLeaf)
			} elseif ($OutputPath) {
				$paramSnapshot['EntraUsersOutput'] = Get-DisplayPath -LocalPath (Join-Path $OutputPath $auxLeaf)
			}
		}
		if ($paramSnapshot.Contains('Agents365Output') -and ($IncludeAgent365Info -or $OnlyAgent365Info) -and -not $ExportWorkbook) {
			$auxLeaf = & $script:GetEffectiveAgent365Basename
			$_aiDtR = script:Resolve-DataTypePaths -DataType 'Agent365Info' -DefaultBasename $auxLeaf
			if ($_aiDtR -and $_aiDtR.IsBound -and $_aiDtR.Tier -eq 'Local') {
				$paramSnapshot['Agents365Output'] = Get-DisplayPath -LocalPath (Join-Path $_aiDtR.EffectiveDir $_aiDtR.Basename)
			} elseif ($_aiDtR -and $_aiDtR.IsBound) {
				$paramSnapshot['Agents365Output'] = $_aiDtR.EffectiveDir.TrimEnd('/') + '/' + $_aiDtR.Basename
			} elseif ($script:DestRaw.ContainsKey('Agent365Info') -and $script:DestTier['Agent365Info'] -ne 'Local') {
				$paramSnapshot['Agents365Output'] = (($script:DestParentUrl['Agent365Info'] ?? $script:DestRaw['Agent365Info']).TrimEnd('/') + '/' + $auxLeaf)
			} elseif ($OutputPath) {
				$paramSnapshot['Agents365Output'] = Get-DisplayPath -LocalPath (Join-Path $OutputPath $auxLeaf)
			}
		}
	}

	# Helper: file emissions for Agent 365 should only render when (a) the user requested
	# Agent 365 output AND (b) the eager Frontier probe didn't already determine the tenant
	# is unavailable. The probe is run by Invoke-Agent365EarlyInteractiveSignIn (AppReg+Agent365)
	# or by the deferred Test-Agent365FrontierAccess (interactive auth). When unavailable,
	# $script:Agent365FrontierAvailable is $false; when not yet probed, $null.
	$agent365WillProduceFile = ($IncludeAgent365Info -or $OnlyAgent365Info) -and ($script:Agent365FrontierAvailable -ne $false)

	# Scrub Agents365Output from the parameter snapshot when we already know the file won't be produced.
	if ($paramSnapshot -and $paramSnapshot.Contains('Agents365Output') -and -not $agent365WillProduceFile) {
		$paramSnapshot.Remove('Agents365Output')
	}
	
		# Step 10b: Display detailed output filenames now that ActivityTypes is finalized (if activity type switches were used)
	if ($ExcludeCopilotInteraction) {
		Write-LogHost ""
		Write-LogHost "=== Output Files ===" -ForegroundColor Cyan
		if ($ExportWorkbook) {
			# Excel mode
			$outputDir  = if ($OutputPath) { $OutputPath } else { "C:\Temp\" }
			$displayDir = (Get-DisplayPath -LocalPath $outputDir -Directory).TrimEnd('/','\') + '/'
			if ($CombineOutput) {
				$baseName = "Purview_Audit_CombinedUsageActivity"
				if ($IncludeUserInfo -and -not $UseEOM) { $baseName += "_EntraUsers" }
				$tabsList = @('CombinedActivity')
				if ($IncludeUserInfo -and -not $UseEOM) { $tabsList += 'EntraUsers_MAClicensing' }
				if ($agent365WillProduceFile) { $tabsList += 'Agents365' }
				$excelDescriptor = if ($tabsList.Count -gt 1) { "multi-tab workbook ($($tabsList -join ' + '))" } else { 'single-tab workbook' }
				Write-LogHost "Output File: ${displayDir}${baseName}_<timestamp>.xlsx ($excelDescriptor)" -ForegroundColor White
				if ($tabsList.Count -gt 1) { Write-LogHost "  Tabs: $($tabsList -join ', ')" -ForegroundColor Gray }
			} else {
				Write-LogHost "Output File: ${displayDir}Purview_Audit_MultiTab_<timestamp>.xlsx (multi-tab workbook)" -ForegroundColor White
				if ($IncludeUserInfo -and -not $UseEOM) { Write-LogHost "  Entra Users Tab: EntraUsers_MAClicensing" -ForegroundColor Gray }
				if ($agent365WillProduceFile) { Write-LogHost "  Agent 365 Tab: Agents365" -ForegroundColor Gray }
			}
		} else {
			# CSV mode
			if ($CombineOutput) {
				# Single combined CSV file. Suppress the "(combined - all activity types)"
				# qualifier when gated to exactly one activity type — file name carries it.
				$displayPath = if ($script:FinalOutputPath) { $script:FinalOutputPath } else { $OutputFile }
				$_isSingleActivityRun2 = ($ActivityTypes -and @($ActivityTypes).Count -eq 1 -and -not $IncludeM365Usage)
				$_combinedQualifier2 = if ($_isSingleActivityRun2) { '' } else { ' (combined - all activity types)' }
				Write-LogHost "Output File: $(Get-DisplayPath -LocalPath $displayPath)${_combinedQualifier2}" -ForegroundColor White
				if ($IncludeUserInfo -and -not $UseEOM) {
					# Honor -OutputPathUserInfo (or an Append-side promotion of DestRaw) when bound; otherwise inherit $displayPath's parent.
					$_uiDt2 = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename (& $script:GetEffectiveEntraBasename)
					$entraFileLater = if ($_uiDt2 -and $_uiDt2.IsBound -and $_uiDt2.Tier -eq 'Local') { Join-Path $_uiDt2.EffectiveDir $_uiDt2.Basename }
						elseif ($_uiDt2 -and $_uiDt2.IsBound) { $_uiDt2.EffectiveDir.TrimEnd('/') + '/' + $_uiDt2.Basename }
						else { Join-Path (Split-Path $displayPath -Parent) (& $script:GetEffectiveEntraBasename) }
					if ($_uiDt2 -and $_uiDt2.IsBound -and $_uiDt2.Tier -ne 'Local') { Write-LogHost "  Entra Users File: $entraFileLater" -ForegroundColor Gray }
					else { Write-LogHost "  Entra Users File: $(Get-DisplayPath -LocalPath $entraFileLater)" -ForegroundColor Gray }
				}
				if ($agent365WillProduceFile) {
					# Honor -OutputPathAgent365Info (or an Append-side promotion of DestRaw) when bound; otherwise inherit $displayPath's parent.
					$_aiDt2 = script:Resolve-DataTypePaths -DataType 'Agent365Info' -DefaultBasename (& $script:GetEffectiveAgent365Basename)
					$agent365FileLater = if ($_aiDt2 -and $_aiDt2.IsBound -and $_aiDt2.Tier -eq 'Local') { Join-Path $_aiDt2.EffectiveDir $_aiDt2.Basename }
						elseif ($_aiDt2 -and $_aiDt2.IsBound) { $_aiDt2.EffectiveDir.TrimEnd('/') + '/' + $_aiDt2.Basename }
						else { Join-Path (Split-Path $displayPath -Parent) (& $script:GetEffectiveAgent365Basename) }
					if ($_aiDt2 -and $_aiDt2.IsBound -and $_aiDt2.Tier -ne 'Local') { Write-LogHost "  Agent 365 File: $agent365FileLater" -ForegroundColor Gray }
					else { Write-LogHost "  Agent 365 File: $(Get-DisplayPath -LocalPath $agent365FileLater)" -ForegroundColor Gray }
				}
			} else {
				# Separate CSV files per activity type
				$outputDir   = Split-Path $OutputFile -Parent
				$displayDir2 = (Get-DisplayPath -LocalPath $outputDir -Directory).TrimEnd('/','\')
				$timestamp   = [System.IO.Path]::GetFileNameWithoutExtension($OutputFile) -replace '.*_(\d{8}_\d{6}).*', '$1'
				Write-LogHost "Output Directory: $displayDir2\" -ForegroundColor White
				Write-LogHost "Output Files: ${displayDir2}\Purview_Audit_UsageActivity_<ActivityType>_${timestamp}.csv" -ForegroundColor Gray
				if ($IncludeUserInfo -and -not $UseEOM) {
					# Honor -OutputPathUserInfo (or an Append-side promotion of DestRaw) when bound; otherwise inherit $outputDir.
					$_uiDt3 = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename (& $script:GetEffectiveEntraBasename)
					$entraFileSplit = if ($_uiDt3 -and $_uiDt3.IsBound -and $_uiDt3.Tier -eq 'Local') { Join-Path $_uiDt3.EffectiveDir $_uiDt3.Basename }
						elseif ($_uiDt3 -and $_uiDt3.IsBound) { $_uiDt3.EffectiveDir.TrimEnd('/') + '/' + $_uiDt3.Basename }
						else { Join-Path $outputDir (& $script:GetEffectiveEntraBasename) }
					if ($_uiDt3 -and $_uiDt3.IsBound -and $_uiDt3.Tier -ne 'Local') { Write-LogHost "  Entra Users: $entraFileSplit" -ForegroundColor Gray }
					else { Write-LogHost "  Entra Users: $(Get-DisplayPath -LocalPath $entraFileSplit)" -ForegroundColor Gray }
				}
				if ($agent365WillProduceFile) {
					# Honor -OutputPathAgent365Info (or an Append-side promotion of DestRaw) when bound; otherwise inherit $outputDir.
					$_aiDt3 = script:Resolve-DataTypePaths -DataType 'Agent365Info' -DefaultBasename (& $script:GetEffectiveAgent365Basename)
					$agent365FileSplit = if ($_aiDt3 -and $_aiDt3.IsBound -and $_aiDt3.Tier -eq 'Local') { Join-Path $_aiDt3.EffectiveDir $_aiDt3.Basename }
						elseif ($_aiDt3 -and $_aiDt3.IsBound) { $_aiDt3.EffectiveDir.TrimEnd('/') + '/' + $_aiDt3.Basename }
						else { Join-Path $outputDir (& $script:GetEffectiveAgent365Basename) }
					if ($_aiDt3 -and $_aiDt3.IsBound -and $_aiDt3.Tier -ne 'Local') { Write-LogHost "  Agent 365: $agent365FileSplit" -ForegroundColor Gray }
					else { Write-LogHost "  Agent 365: $(Get-DisplayPath -LocalPath $agent365FileSplit)" -ForegroundColor Gray }
				}
			}
		}
	}
	
	# Display Parameter Snapshot (now shows final ActivityTypes after DSPM processing)
	Write-LogHost ""
	Write-LogHost "Parameter Snapshot:" -ForegroundColor Cyan
	foreach ($k in $paramSnapshot.Keys) { Write-LogHost ("  {0} = {1}" -f $k, $paramSnapshot[$k]) -ForegroundColor DarkGray }
	Write-LogHost ""
	
	# Step 10: Display activity-type options (only if switches affect them)
	if ($ExcludeCopilotInteraction) {
		Write-LogHost ""
		Write-LogHost "=== Activity Type Options ===" -ForegroundColor Cyan
		Write-LogHost "  [!] M365 Copilot activity type excluded (CopilotInteraction)" -ForegroundColor Red
}	# Step 11: Log conflict resolution if it occurred
	if ($script:ConflictResolved) {
	Write-LogHost ""
	Write-LogHost "Conflict Resolution:" -ForegroundColor Yellow
	if ($script:ConflictChoice -eq 'INCLUDE') {
		Write-LogHost "  User resolved conflict by choosing to INCLUDE M365 Copilot activity type." -ForegroundColor Green
		Write-LogHost "  -ExcludeCopilotInteraction switch overridden." -ForegroundColor Green
	}
	elseif ($script:ConflictChoice -eq 'EXCLUDE') {
		Write-LogHost "  User resolved conflict by choosing to EXCLUDE M365 Copilot activity type." -ForegroundColor Red
		Write-LogHost "  CopilotInteraction removed from ActivityTypes." -ForegroundColor Red
	}
	elseif ($script:ConflictChoice -eq 'EXCLUDE (Force mode)') {
		Write-LogHost "  Force mode enabled: M365 Copilot activity type excluded without prompt." -ForegroundColor Red
		Write-LogHost "  CopilotInteraction removed from ActivityTypes." -ForegroundColor Red
	}
	Write-LogHost "===================================" -ForegroundColor Cyan
}

	# --- Validate AppendFile requires single-file output ---
	if ($AppendFile) {
		# Count activity types being processed
		$activityTypeCount = $ActivityTypes.Count
		
		# Validate single-file output requirement
		$isExcelMode = $ExportWorkbook.IsPresent
		$isCombineMode = $CombineOutput.IsPresent
		$isSingleActivity = ($activityTypeCount -eq 1)
		
		if (-not ($isExcelMode -or $isCombineMode -or $isSingleActivity)) {
			Write-Host "ERROR: -AppendFile requires single-file output mode" -ForegroundColor Red
			Write-Host "" -ForegroundColor Yellow
			Write-Host "You have $activityTypeCount activity types selected, which would create multiple output files." -ForegroundColor Yellow
			Write-Host "Activity types: $($ActivityTypes -join ', ')" -ForegroundColor Yellow
			Write-Host "" -ForegroundColor Yellow
			Write-Host "Solutions (choose one):" -ForegroundColor Green
			Write-Host "  1. Add -ExportWorkbook to create multi-tab Excel file (recommended)" -ForegroundColor Green
			Write-Host "  2. Add -CombineOutput to merge all types into single CSV file" -ForegroundColor Green
			Write-Host "  3. Specify only ONE activity type (use -ActivityTypes parameter)" -ForegroundColor Green
			Write-Host "" -ForegroundColor Yellow
			Write-Host "Examples:" -ForegroundColor Cyan
			Write-Host "  # Excel multi-tab (all activity types in one .xlsx file):" -ForegroundColor DarkGray
			Write-Host "  -AppendFile 'Report.xlsx' -ExportWorkbook" -ForegroundColor White
			Write-Host "" -ForegroundColor DarkGray
			Write-Host "  # Combined CSV (all activity types merged into one .csv file):" -ForegroundColor DarkGray
			Write-Host "  -AppendFile 'Report.csv' -CombineOutput" -ForegroundColor White
			Write-Host "" -ForegroundColor DarkGray
			Write-Host "  # Single activity type:" -ForegroundColor DarkGray
			Write-Host "  -AppendFile 'Report.csv' -ActivityTypes CopilotInteraction" -ForegroundColor White
			exit 1
		}
		
		Write-LogHost "AppendFile validation: Single-file output confirmed" -ForegroundColor Green
		if ($isExcelMode) {
			Write-LogHost "  Mode: Excel multi-tab workbook" -ForegroundColor DarkGray
		} elseif ($isCombineMode) {
			Write-LogHost "  Mode: Combined CSV (all activity types merged)" -ForegroundColor DarkGray
		} elseif ($isSingleActivity) {
			Write-LogHost "  Mode: Single activity type ($($ActivityTypes[0]))" -ForegroundColor DarkGray
		}
		Write-LogHost ""
	}
	# --- End AppendFile Validation ---
		
		# --- Excel Export Data Storage Initialization ---
		if ($ExportWorkbook) {
			if ($CombineOutput) {
				# Single-tab mode: Store all rows in one array
				$combinedTabName = 'CombinedUsageActivity'
				$script:ExcelExportData = @{
					$combinedTabName = @()
				}
				$excelInitTabs = @($combinedTabName)
				if ($IncludeUserInfo -and -not $UseEOM) { $excelInitTabs += 'EntraUsers_MAClicensing' }
				if ($agent365WillProduceFile) { $excelInitTabs += 'Agents365' }
				if ($excelInitTabs.Count -gt 1) {
					Write-LogHost "Excel export: Combined mode (multi-tab: $($excelInitTabs -join ' + '))" -ForegroundColor Cyan
				} else {
					Write-LogHost "Excel export: Combined mode (single tab: $combinedTabName)" -ForegroundColor Cyan
				}
			} else {
				# Multi-tab mode: Store rows by activity type
				$script:ExcelExportData = @{}
				$multiTabExtras = @()
				if ($IncludeUserInfo -and -not $UseEOM) { $multiTabExtras += 'EntraUsers_MAClicensing' }
				if ($agent365WillProduceFile) { $multiTabExtras += 'Agents365' }
				if ($multiTabExtras.Count -gt 0) {
					Write-LogHost "Excel export: Multi-tab mode (separate tab per activity type + $($multiTabExtras -join ' + '))" -ForegroundColor Cyan
				} else {
					Write-LogHost "Excel export: Multi-tab mode (separate tab per activity type)" -ForegroundColor Cyan
				}
			}
		}
		# --- End Excel Export Initialization ---
	
	# === Activity Types for This Run ===
	if (-not $OnlyUserInfo) {
Write-LogHost ""
Write-LogHost "=== Activity Types for This Run ===" -ForegroundColor Cyan
# Sort activity types: non-DSPM first, then DSPM types at the bottom
$dspmTypes = @('AIAppInteraction', 'AIInteraction', 'ConnectedAIAppInteraction')
$nonDspmTypes = $ActivityTypes | Where-Object { $_ -notin $dspmTypes }
$dspmInList = $ActivityTypes | Where-Object { $_ -in $dspmTypes }
$sortedActivityTypes = @($nonDspmTypes) + @($dspmInList)
foreach ($act in $sortedActivityTypes) {
	Write-LogHost "  • $act" -ForegroundColor White
}
Write-LogHost ""	# Output mode display with format-specific defaults
	# CSV: Default SEPARATE (granular analysis - separate files per activity type)
	# Excel: Default SEPARATE (separate tabs per activity type)
	# Both: -CombineOutput switch forces combined mode
	
	# Determine effective combine mode based on format and user input
	if ($CombineOutput) {
		# User explicitly specified -CombineOutput switch: use combined mode for both CSV and Excel
		$csvCombineMode = $true
		$excelSeparateMode = $false
	} else {
		# User didn't specify: use format-specific defaults (both default to separate)
		$csvCombineMode = $false     # CSV defaults to separate files
		$excelSeparateMode = $true   # Excel defaults to separated tabs (inverse logic)
	}
	
	if ($ExportWorkbook) {
		$outputMode = if ($excelSeparateMode) { 
			'Separated tabs (one tab per activity type)' 
		} else { 
			'Combined (single tab with all activity types)' 
		}
	} else {
		$outputMode = if ($csvCombineMode) { 
			'Combined (single CSV file with all activity types)' 
		} else { 
			'Separated files (one CSV per activity type)' 
		}
	}
	
	Write-LogHost "Output mode: $outputMode" -ForegroundColor Gray
	if (-not $ExportWorkbook) {
			if ($csvCombineMode) {
				$displayPath = if ($script:FinalOutputPath) { $script:FinalOutputPath } else { $OutputFile }
				$outputDir   = Split-Path $displayPath -Parent
				# Append-aware tense + suppress the '(separate)' parenthetical
				# when the corresponding -Append* target is bound (the file is not separate
				# in that case — it IS the append target's union). For remote modes the
				# in-process $AppendFile / $AppendUserInfo were re-pointed to local scratch
				# at pre-flight; use $script:AppendRaw[*] to surface the canonical remote URL.
				if ($AppendFile) {
					$_afDisplay = if ($script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) { $script:AppendRaw['Purview'] } else { $AppendFile }
					Write-LogHost "Appended to: $_afDisplay" -ForegroundColor Gray
				} else {
					Write-LogHost "Output file: $(Get-DisplayPath -LocalPath $displayPath)" -ForegroundColor Gray
				}
				if ($IncludeUserInfo) {
					if ($AppendUserInfo) {
						$_auiDisplay = if ($script:AppendRaw.ContainsKey('UserInfo') -and $script:AppendRaw['UserInfo']) { $script:AppendRaw['UserInfo'] } else { $AppendUserInfo }
						Write-LogHost "EntraUsers file: appended to $_auiDisplay" -ForegroundColor Gray
					} else {
						# Honor -OutputPathUserInfo (or an Append-side promotion of DestRaw) when bound; otherwise inherit $OutputDir (the Purview parent already computed above).
						$_uiDt4 = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename (& $script:GetEffectiveEntraBasename)
						$_uiPath4 = if ($_uiDt4 -and $_uiDt4.IsBound -and $_uiDt4.Tier -eq 'Local') { Join-Path $_uiDt4.EffectiveDir $_uiDt4.Basename }
							elseif ($_uiDt4 -and $_uiDt4.IsBound) { $_uiDt4.EffectiveDir.TrimEnd('/') + '/' + $_uiDt4.Basename }
							else { Join-Path $OutputDir (& $script:GetEffectiveEntraBasename) }
						if ($_uiDt4 -and $_uiDt4.IsBound -and $_uiDt4.Tier -ne 'Local') { Write-LogHost "EntraUsers file (separate): $_uiPath4" -ForegroundColor Gray }
						else { Write-LogHost "EntraUsers file (separate): $(Get-DisplayPath -LocalPath $_uiPath4)" -ForegroundColor Gray }
					}
				}
				if ($agent365WillProduceFile) {
					if ($AppendAgent365Info) {
						$_aaiDisplay = if ($script:AppendRaw.ContainsKey('Agent365Info') -and $script:AppendRaw['Agent365Info']) { $script:AppendRaw['Agent365Info'] } else { $AppendAgent365Info }
						Write-LogHost "Agent 365 file: appended to $_aaiDisplay" -ForegroundColor Gray
					} else {
						# Honor -OutputPathAgent365Info (or an Append-side promotion of DestRaw) when bound; otherwise inherit $OutputDir.
						$_aiDt4 = script:Resolve-DataTypePaths -DataType 'Agent365Info' -DefaultBasename (& $script:GetEffectiveAgent365Basename)
						$_aiPath4 = if ($_aiDt4 -and $_aiDt4.IsBound -and $_aiDt4.Tier -eq 'Local') { Join-Path $_aiDt4.EffectiveDir $_aiDt4.Basename }
							elseif ($_aiDt4 -and $_aiDt4.IsBound) { $_aiDt4.EffectiveDir.TrimEnd('/') + '/' + $_aiDt4.Basename }
							else { Join-Path $OutputDir (& $script:GetEffectiveAgent365Basename) }
						if ($_aiDt4 -and $_aiDt4.IsBound -and $_aiDt4.Tier -ne 'Local') { Write-LogHost "Agent 365 file (separate): $_aiPath4" -ForegroundColor Gray }
						else { Write-LogHost "Agent 365 file (separate): $(Get-DisplayPath -LocalPath $_aiPath4)" -ForegroundColor Gray }
					}
				}
			} else {
			$outputDir = Split-Path $OutputFile -Parent
			$displayDir = (Get-DisplayPath -LocalPath $outputDir -Directory)
			# Prefix for per-activity CSV files
			$filePrefix = "Purview_Audit"
			Write-LogHost "Output directory: $displayDir" -ForegroundColor Gray
				Write-LogHost "Activity file pattern: ${filePrefix}_<ActivityType>_${global:ScriptRunTimestamp}.csv" -ForegroundColor Gray
				if ($IncludeUserInfo) {
					# Honor -OutputPathUserInfo (or an Append-side promotion of DestRaw) when bound; otherwise inherit $outputDir.
					$_uiDt5 = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename (& $script:GetEffectiveEntraBasename)
					$_uiPath5 = if ($_uiDt5 -and $_uiDt5.IsBound -and $_uiDt5.Tier -eq 'Local') { Join-Path $_uiDt5.EffectiveDir $_uiDt5.Basename }
						elseif ($_uiDt5 -and $_uiDt5.IsBound) { $_uiDt5.EffectiveDir.TrimEnd('/') + '/' + $_uiDt5.Basename }
						else { Join-Path $outputDir (& $script:GetEffectiveEntraBasename) }
					if ($_uiDt5 -and $_uiDt5.IsBound -and $_uiDt5.Tier -ne 'Local') { Write-LogHost "EntraUsers file: $_uiPath5" -ForegroundColor Gray }
					else { Write-LogHost "EntraUsers file: $(Get-DisplayPath -LocalPath $_uiPath5)" -ForegroundColor Gray }
				}
				if ($agent365WillProduceFile) {
					# Honor -OutputPathAgent365Info (or an Append-side promotion of DestRaw) when bound; otherwise inherit $outputDir.
					$_aiDt5 = script:Resolve-DataTypePaths -DataType 'Agent365Info' -DefaultBasename (& $script:GetEffectiveAgent365Basename)
					$_aiPath5 = if ($_aiDt5 -and $_aiDt5.IsBound -and $_aiDt5.Tier -eq 'Local') { Join-Path $_aiDt5.EffectiveDir $_aiDt5.Basename }
						elseif ($_aiDt5 -and $_aiDt5.IsBound) { $_aiDt5.EffectiveDir.TrimEnd('/') + '/' + $_aiDt5.Basename }
						else { Join-Path $outputDir (& $script:GetEffectiveAgent365Basename) }
					if ($_aiDt5 -and $_aiDt5.IsBound -and $_aiDt5.Tier -ne 'Local') { Write-LogHost "Agent 365 file: $_aiPath5" -ForegroundColor Gray }
					else { Write-LogHost "Agent 365 file: $(Get-DisplayPath -LocalPath $_aiPath5)" -ForegroundColor Gray }
				}
		}
	}
	Write-LogHost "===================================" -ForegroundColor Cyan
	} # End if (-not $OnlyUserInfo) - Activity types display and output configuration

	Write-LogHost ""
	
	if (-not $RAWInputCSV) {
		$allLogs = New-Object System.Collections.ArrayList
		if (-not $UseEOM -and $ServiceTypes -and $ServiceTypes.Count -gt 0) { 
			$serviceRuns = $ServiceTypes 
		} else { 
			$serviceRuns = @($null)
		}
		if (-not $UseEOM -and $serviceRuns.Count -gt 1) {
			Write-LogHost ("NOTE: security audit API accepts a single workload per query. Splitting run into {0} workload pass(es): {1}" -f $serviceRuns.Count, ($serviceRuns -join ', ')) -ForegroundColor Yellow
		}
		$servicePassIndex = 0
	}
	else {
		if (-not $serviceRuns) { $serviceRuns = @($null) }
	}
	foreach ($currentServiceFilter in $serviceRuns) {
		$servicePassIndex++
		if (-not $UseEOM -and $currentServiceFilter) {
			$workloadLabel = $currentServiceFilter
			# Enhanced workload label when first Exchange pass includes cross-workload M365 usage types
			if ($IncludeM365Usage -and $currentServiceFilter -eq 'Exchange' -and $servicePassIndex -eq 1) {
				$workloadLabel = "$currentServiceFilter + M365 Usage (Office apps, Forms, Stream, Planner, PowerApps)"
			}
			Write-LogHost ("--- Processing workload {0}/{1}: {2} ---" -f $servicePassIndex, $serviceRuns.Count, $workloadLabel) -ForegroundColor DarkCyan
		}

		$serviceActivities = $ActivityTypes
		if ($currentServiceFilter -and $serviceOperationMap.ContainsKey($currentServiceFilter)) {
			$mappedOps = @($serviceOperationMap[$currentServiceFilter] | Where-Object { $ActivityTypes -contains $_ })
			if ($mappedOps.Count -gt 0 -and $mappedOps.Count -lt $ActivityTypes.Count) {
				$otherOps = @($ActivityTypes | Where-Object { $mappedOps -notcontains $_ })
				if ($otherOps.Count -gt 0) {
					Write-LogHost ("  Aligning operationFilters for {0}: queued for this workload only; other operations run in their own pass -> {1}" -f $currentServiceFilter, ($otherOps -join ', ')) -ForegroundColor DarkGray
				}
			}
			if ($mappedOps.Count -gt 0) {
				$serviceActivities = $mappedOps
			}
		}

		$serviceRecordTypes = $RecordTypes
		if ($currentServiceFilter -and $RecordTypes) {
			$matched = @()
			$unmatched = @()
			foreach ($rt in $RecordTypes) {
				$rtServices = $recordTypeWorkloadMap[$rt]
				if ($null -eq $rtServices -or $rtServices.Count -eq 0) {
					$matched += $rt
					continue
				}

				if ($rtServices -contains $currentServiceFilter) {
					$matched += $rt
				} else {
					$unmatched += $rt
				}
			}
			if ($matched.Count -gt 0) {
				# Enhanced output for M365 Usage bundle in first Exchange pass
				if ($IncludeM365Usage -and $currentServiceFilter -eq 'Exchange' -and $servicePassIndex -eq 1) {
					$m365RecordTypes = @('OfficeNative','MicrosoftForms','MicrosoftStream','PlannerPlan','PlannerTask','PowerAppsApp')
					$m365Matched = @($matched | Where-Object { $m365RecordTypes -contains $_ })
					$exchangeMatched = @($matched | Where-Object { $m365RecordTypes -notcontains $_ })
					
					if ($exchangeMatched.Count -gt 0) {
						Write-LogHost ("  Applying recordTypeFilters for Exchange -> {0}" -f ($exchangeMatched -join ', ')) -ForegroundColor DarkGray
					}
					if ($m365Matched.Count -gt 0) {
						Write-LogHost ("  Including M365 Usage recordTypes (cross-workload) -> {0}" -f ($m365Matched -join ', ')) -ForegroundColor Cyan
					}
				} else {
					Write-LogHost ("  Applying recordTypeFilters for {0} -> {1}" -f $currentServiceFilter, ($matched -join ', ')) -ForegroundColor DarkGray
				}
				$serviceRecordTypes = $matched | Select-Object -Unique
			} else {
				$serviceRecordTypes = $null
			}

			if ($unmatched.Count -gt 0) {
				Write-LogHost ("  Queueing recordTypeFilters for future workload pass(es) -> {0}" -f ($unmatched -join ', ')) -ForegroundColor DarkGray
			}
		}

		$script:CurrentServiceFilter = $currentServiceFilter
		$queryPlan = @(Get-QueryPlan -RequestedActivities $serviceActivities)  # Force array wrapper
		$script:progressBlocksCompleted = 0; $script:progressBlockHoursSum = 0.0
		$script:progressState.Query.Current = 0
		
		# Initial rough estimate for display - will be updated as each group is processed
		$totalEstimatedBlocks = $queryPlan.Count
		$script:progressState.Query.Total = [int]$totalEstimatedBlocks
		Set-ProgressPhase -Phase 'Query' -Status "Planning queries: $($queryPlan.Count) groups"
		Write-LogHost "Planned $($queryPlan.Count) query groups" -ForegroundColor DarkCyan
		$sequentialGroups = 0
		$ps7 = ($PSVersionTable.PSVersion.Major -ge 7)
		if (-not $ps7 -and $ParallelMode -ne 'Off') { $ParallelMode = 'Off' }
		$parallelDecision = Get-ParallelActivationDecision -QueryPlan $queryPlan -ParallelMode $ParallelMode -MaxParallelGroups $MaxParallelGroups -MaxConcurrency $MaxConcurrency
		$parallelOverallEnabled = $parallelDecision.Enabled
		Write-LogHost ("ParallelMode requested: {0} | Effective: {1} ({2})" -f $ParallelMode, ($(if ($parallelOverallEnabled) { 'Enabled' } else { 'Disabled' })), $parallelDecision.Reason) -ForegroundColor DarkCyan
		if ($ParallelMode -eq 'Auto' -and -not $parallelOverallEnabled) { Write-LogHost "WARNING: ParallelMode Auto requested but heuristics not met -> running sequential. Reason: $($parallelDecision.Reason)." -ForegroundColor Yellow }
		if ($enableParallelSwitchUsed) { Write-LogHost "-EnableParallel switch detected -> setting ParallelMode to On" -ForegroundColor DarkYellow }
		$groupIndex = 0
		foreach ($grp in $queryPlan) {
			$groupIndex++
			
			# Calculate partition hours using default or user override (Graph API mode only)
			$effectivePartitionHours = $PartitionHours
			$userSpecifiedPartitionHours = ($PartitionHours -gt 0)
			if (-not $UseEOM -and $effectivePartitionHours -eq 0) {
				# Default to 12-hour partitions for Graph API mode
				$effectivePartitionHours = 12
				if ($paramSnapshot -and $paramSnapshot.Contains('PartitionHours')) {
					$paramSnapshot['PartitionHours'] = "${effectivePartitionHours} (auto)"
				}
			}
			
			# Calculate partitions from PartitionHours (Graph API) or use degree of parallelism (EOM)
			if (-not $UseEOM -and $effectivePartitionHours -gt 0) {
				$totalHours = ($endDateObj - $startDateObj).TotalHours
				$calculatedPartitions = [Math]::Ceiling($totalHours / $effectivePartitionHours)
				
				# Apply MaxPartitions cap with auto-adjustment
				if ($calculatedPartitions -gt $MaxPartitions) {
					if (-not $userSpecifiedPartitionHours) {
						# User didn't specify PartitionHours, so auto-adjust to 12h to stay under cap
						$effectivePartitionHours = 12
						$calculatedPartitions = [Math]::Ceiling($totalHours / $effectivePartitionHours)
						Write-LogHost "  Auto-adjusted to ${effectivePartitionHours}h partitions to respect MaxPartitions cap ($MaxPartitions)" -ForegroundColor Cyan
					}
					# If still over cap after adjustment, hard cap it
					if ($calculatedPartitions -gt $MaxPartitions) {
						$calculatedPartitions = $MaxPartitions
						# CRITICAL: Recalculate effectivePartitionHours to ensure equal time slices
						$effectivePartitionHours = $totalHours / $calculatedPartitions
						Write-LogHost "  Applying MaxPartitions cap: $calculatedPartitions partitions @ ${effectivePartitionHours}h each" -ForegroundColor Magenta
					}
				}
				
				$degree = $calculatedPartitions
			} else {
				# EOM mode or PartitionHours not enabled: use concurrency-based degree
				$degree = [Math]::Min($grp.Concurrency, $MaxConcurrency)
			}
			
			# Large query warning (Graph API mode only)
			if (-not $UseEOM -and $effectivePartitionHours -gt 0) {
				$daySpan = ($endDateObj - $startDateObj).TotalDays
				if ($daySpan -gt 30 -or $degree -gt 50) {
					Write-LogHost ""
					Write-LogHost "  [!]  LARGE QUERY DETECTED" -ForegroundColor Yellow
					Write-LogHost "  Date Range: $([Math]::Round($daySpan, 1)) days | Partitions: $degree @ ${effectivePartitionHours}h" -ForegroundColor Yellow
					Write-LogHost "  Large queries may take several hours to complete." -ForegroundColor Yellow
					Write-LogHost "  Smaller date ranges or -PartitionHours will reduce processing time." -ForegroundColor Yellow
					
					# Warn about interactive auth token expiration for long-running queries
					$authMethod = $script:SharedAuthState.AuthMethod
					if ($authMethod -in 'weblogin', 'devicecode') {
						Write-LogHost ""
						Write-LogHost "  ℹ️  TOKEN REFRESH NOTE (Interactive Auth)" -ForegroundColor Cyan
						Write-LogHost "  Tokens expire after ~60-90 minutes. For queries exceeding 1 hour:" -ForegroundColor Cyan
						Write-LogHost "    • Token will be automatically refreshed from MSAL cache" -ForegroundColor Gray
						Write-LogHost "    • If cache is unavailable, browser prompt may appear" -ForegroundColor Gray
						Write-LogHost "    • Progress is saved automatically - use -Resume if interrupted" -ForegroundColor Gray
					}
					Write-LogHost ""
				}
				
				# EXTREME VOLUME WARNING: Detect scenarios likely to exceed token lifetime (P2 advisory)
				# Triggers on: very long date range with many activity types, or very high partition counts
				# These runs routinely take 4-8+ hours and are prone to 401 token expiration mid-run
				$activityCount = $grp.Activities.Count
				if (($daySpan -gt 60 -and $activityCount -gt 10) -or $degree -gt 120) {
					$estimatedHours = [Math]::Round(($degree * 2.5) / 60, 1)  # ~2.5 min per partition is a rough average
					Write-LogHost "" -ForegroundColor Red
					Write-LogHost "  ╔══════════════════════════════════════════════════════════════╗" -ForegroundColor Red
					Write-LogHost "  ║  ⚠  EXTREME VOLUME WARNING                                 ║" -ForegroundColor Red
					Write-LogHost "  ╚══════════════════════════════════════════════════════════════╝" -ForegroundColor Red
					Write-LogHost "  Date Range: $([Math]::Round($daySpan, 0)) days | Activity Types: $activityCount | Partitions: $degree" -ForegroundColor Red
					Write-LogHost "  Estimated run time: $estimatedHours+ hours (actual may vary significantly)" -ForegroundColor Yellow
					Write-LogHost "" -ForegroundColor Yellow
					Write-LogHost "  This query volume is very likely to encounter token expiration (401)" -ForegroundColor Yellow
					Write-LogHost "  during processing. Recommendations:" -ForegroundColor Yellow
					$authMethod = $script:SharedAuthState.AuthMethod
					if ($authMethod -in 'weblogin', 'devicecode') {
						Write-LogHost "    ► STRONGLY recommend switching to -AppRegistration auth" -ForegroundColor Cyan
						Write-LogHost "      (enables automatic silent token refresh without browser prompts)" -ForegroundColor Gray
					}
					Write-LogHost "    ► Progress is checkpointed automatically — use -Resume if interrupted" -ForegroundColor Cyan
					Write-LogHost "    ► Incremental data is saved to disk every 500 pages per partition" -ForegroundColor Cyan
					Write-LogHost "    ► Consider splitting into smaller date ranges (e.g., 30-day windows)" -ForegroundColor Cyan
					Write-LogHost "" -ForegroundColor Red
				}
			}
			
			if (-not $UseEOM) { 
				# For single query group, show simplified message without listing all activity types
				# (activity types are already shown in "Activity Types for This Run" section)
				if ($queryPlan.Count -eq 1) {
					Write-LogHost "Query Group: Combined ($($grp.Activities.Count) activity types, partitions=$degree @ ${effectivePartitionHours}h)" -ForegroundColor Yellow
				} else {
					Write-LogHost "Group: $($grp.Name) (partitions=$degree @ ${effectivePartitionHours}h)" -ForegroundColor Yellow
					# Show activity types per group when there are multiple groups
					Write-LogHost "  Activity Types: $($grp.Activities -join ', ')" -ForegroundColor Gray
				}
			}
			$requestedDegree = $degree
			$totalPartitions = $degree  # Total number of time partitions to create
			$maxConcurrentPartitions = $degree  # Maximum concurrent execution
			if ($degree -gt $MaxConcurrency) { 
				$maxConcurrentPartitions = $MaxConcurrency  # Cap concurrent execution
				try { $script:metrics.PartitionCapsApplied++; if ($script:metrics.PartitionCapHighestRequested -lt $requestedDegree) { $script:metrics.PartitionCapHighestRequested = $requestedDegree } } catch {}
				Write-LogHost "  Applying concurrency cap ($MaxConcurrency): requested $requestedDegree -> $maxConcurrentPartitions concurrent (all $totalPartitions queued)" -ForegroundColor Magenta
			}
			$withinCap = $groupIndex -le $MaxParallelGroups
			# Graph API mode: always use the parallel ThreadJob code path, even with a single partition
			# EOM mode: keep the single-partition shortcut to sequential (parallel is incompatible with
			# Exchange Online implicit remoting, enforced again by the EOM gate inside the parallel block).
			$canParallel = $parallelOverallEnabled -and $withinCap -and ($PSVersionTable.PSVersion.Major -ge 7) -and ((-not $UseEOM) -or ($degree -gt 1))
			
			# Update progress total now that we know parallel mode and partition count
			# For parallel: each partition = 1 progress unit, For sequential: use BlockHours
			if ($canParallel) {
				# Parallel mode: total progress = number of partitions
				$script:progressState.Query.Total = $degree
			} else {
				# Sequential mode: calculate blocks based on BlockHours
				$sequentialBlocks = 0
				foreach ($act in $grp.Activities) {
					try {
						$initialBlock = Get-OptimalBlockSize -ActivityType $act
						if (-not $initialBlock -or $initialBlock -le 0) { $initialBlock = $BlockHours }
						$rangeHours = ($endDateObj - $startDateObj).TotalHours
						$blocks = [int][Math]::Ceiling($rangeHours / $initialBlock)
						if ($blocks -lt 1) { $blocks = 1 }
						$sequentialBlocks += $blocks
					} catch {
						$sequentialBlocks += 1
					}
				}
				if ($sequentialBlocks -lt 1) { $sequentialBlocks = 1 }
				$script:progressState.Query.Total = $sequentialBlocks
			}
			
			# Adaptive memory pressure logic - ONLY for EOM mode (Graph API has low memory footprint)
			if (-not $DisableAdaptive -and $UseEOM) {
				try {
					$workingSetMB = [math]::Round(([System.Diagnostics.Process]::GetCurrentProcess().WorkingSet64 / 1MB),0)
					if ($workingSetMB -gt $MemoryPressureMB -and $MaxConcurrency -gt 1) {
						$old = $MaxConcurrency
						$MaxConcurrency = [Math]::Max(1, $MaxConcurrency - 1)
						# Reduce concurrent execution, not total partitions
						if ($maxConcurrentPartitions -gt $MaxConcurrency) { $maxConcurrentPartitions = $MaxConcurrency }
						$script:metrics.AdaptiveMemoryReductions++
						$script:metrics.AdaptiveEvents += "Memory pressure detected (${workingSetMB}MB > ${MemoryPressureMB}MB) reduced MaxConcurrency $old -> $MaxConcurrency"
						Write-LogHost "Adaptive: Memory pressure ($workingSetMB MB) reducing MaxConcurrency to $MaxConcurrency" -ForegroundColor DarkYellow
					}
				} catch {}
			}
			
			# Concurrency guidance handled earlier; no additional adjustment section required
			
			# Graph API mode: Can query multiple activities in single request
			# EOM mode: Should only have one activity per group (enforced by Get-QueryPlan)
			$activities = $grp.Activities  # Array of activity types for this group
			$activity = $grp.Activities[0]  # Backward compatibility for single-activity logic
			
			$partitions = @()
			if ($totalPartitions -gt 1) { 
				$totalHours = ($endDateObj - $startDateObj).TotalHours
				# Use effectivePartitionHours for Graph API mode, or calculate from totalPartitions for EOM mode
				if (-not $UseEOM -and $effectivePartitionHours -gt 0) {
					$sliceHours = $effectivePartitionHours
				} else {
					$sliceHours = $totalHours / $totalPartitions
				}
				
				# CRITICAL: When IncludeM365Usage is active, NEVER send recordTypes or serviceFilter
				# Graph API rejects mixed cross-workload recordTypes with workload-specific serviceFilter
				$partitionRecordTypes = $serviceRecordTypes
				$partitionServiceFilter = $currentServiceFilter
				if ($IncludeM365Usage) {
					$partitionRecordTypes = $null
					$partitionServiceFilter = $null
				}
				
				for ($pi = 0; $pi -lt $totalPartitions; $pi++) { 
					$pStart = $startDateObj.AddHours($sliceHours * $pi)
					$pEnd = if ($pi -eq ($totalPartitions - 1)) { $endDateObj } else { $startDateObj.AddHours($sliceHours * ($pi + 1)) }
					$partitions += [pscustomobject]@{ 
						Activities = $activities  # Pass all activities for Graph API
						Activity = $activity      # Backward compatibility
						PStart = $pStart
						PEnd = $pEnd
						Index = ($pi + 1)
						Total = $totalPartitions 
						RecordTypes = $partitionRecordTypes
						ServiceFilter = $partitionServiceFilter
					} 
				} 
			} else { 
				$partitions += [pscustomobject]@{ 
					Activities = $activities  # Pass all activities for Graph API
					Activity = $activity      # Backward compatibility
					PStart = $startDateObj
					PEnd = $endDateObj
					Index = 1
					Total = 1 
					RecordTypes = $partitionRecordTypes
					ServiceFilter = $partitionServiceFilter
				} 
			}
			
			# ========================================
			# RESUME MODE: FILTER PARTITIONS
			# ========================================
			# Skip already-completed partitions from checkpoint
			$originalPartitionCount = $partitions.Count
			$skippedPartitions = @()
			$fetchOnlyPartitions = @()
			
			if ($script:CheckpointData -and $script:IsResumeMode) {
				$partitionCategories = Get-PartitionsToProcess -AllPartitions $partitions
				
				if ($partitionCategories.ToSkip.Count -gt 0) {
					$skippedPartitions = $partitionCategories.ToSkip
					# Store the originally-skipped partition indices for summary display
					# (This is captured BEFORE processing, so it only includes checkpoint-completed partitions)
					$script:OriginallySkippedPartitionIndices = @($skippedPartitions | ForEach-Object { $_.Index })
					Write-LogHost "  [RESUME] Skipping $($skippedPartitions.Count) already-completed partition(s): $($skippedPartitions.Index -join ', ')" -ForegroundColor Green
				}
				
				if ($partitionCategories.ToFetchOnly.Count -gt 0) {
					$fetchOnlyPartitions = $partitionCategories.ToFetchOnly
					Write-LogHost "  [RESUME] $($fetchOnlyPartitions.Count) partition(s) have pending queries - will fetch data only" -ForegroundColor Yellow
				}
				
				if ($partitionCategories.ToCreateAndFetch.Count -gt 0) {
					Write-LogHost "  [RESUME] $($partitionCategories.ToCreateAndFetch.Count) partition(s) need full processing" -ForegroundColor Cyan
				}
				
				# Replace partitions with only those needing work (fetch-only + create-and-fetch)
				$partitions = @()
				$partitions += $partitionCategories.ToFetchOnly
				# Durable uncertain-create resume reconcile (READ-ONLY, never a POST here). Each
				# uncertain partition is resolved by exact fingerprinted name against the live
				# collection: exactly one match is adopted + checkpointed and joins fetch-only;
				# multiple fail closed; none stays uncertain. Unresolved / fail-closed partitions
				# are deliberately NOT added to $partitions, so no worker is launched for an
				# unresolved uncertain create (worker-launch gating).
				if ($partitionCategories.ToReconcileOnly.Count -gt 0) {
					Write-LogHost "  [RESUME] $($partitionCategories.ToReconcileOnly.Count) partition(s) have an unproven prior create - reconciling READ-ONLY (no POST)" -ForegroundColor Yellow
					$reconcileOutcome = Invoke-PaxResumeUncertainReconcile -Partitions $partitionCategories.ToReconcileOnly -Activities $activities -Log { param($m) Write-Log $m }
					if (@($reconcileOutcome.AdoptedFetchOnly).Count -gt 0) {
						Write-LogHost "  [RESUME] Adopted $(@($reconcileOutcome.AdoptedFetchOnly).Count) prior create(s) by exact name - fetching data only (no POST)" -ForegroundColor Green
						$partitions += $reconcileOutcome.AdoptedFetchOnly
					}
					# Operator-selected recovery: a NOT-VISIBLE (Unresolved) uncertain partition the
					# operator explicitly chose with -ClearUncertainCreate has its durable marker
					# cleared SELECTIVELY + atomically (single durable write, bucket-exclusive) BEFORE
					# any fresh create, then is routed to a fresh create-and-fetch this run. A still-
					# visible partition never reaches here (it was adopted above, or fails closed on
					# multiple matches), so a visible query is never cleared into a duplicate POST.
					$operatorCleared = 0
					foreach ($uncertainPart in @($reconcileOutcome.Unresolved)) {
						# Derive this partition's contract fingerprint so an explicit
						# -ClearUncertainContract "<index>:<fingerprint>" selection can match EXACTLY
						# this contract even when another contract shares the index. On any derive
						# failure the fingerprint is $null and only an unambiguous index selection applies.
						$__ucFp = $null
						try { $__ucFp = New-GraphAuditQueryFingerprint -PStart $uncertainPart.PStart -PEnd $uncertainPart.PEnd -Activities $uncertainPart.Activities -RecordTypes $uncertainPart.RecordTypes -ServiceFilter $uncertainPart.ServiceFilter } catch { $__ucFp = $null }
						if (Resolve-PaxOperatorClearedUncertain -Index ([int]$uncertainPart.Index) -Fingerprint $__ucFp) {
							if ($script:partitionStatus.ContainsKey([int]$uncertainPart.Index)) { $script:partitionStatus[[int]$uncertainPart.Index].UncertainCreate = $false }
							$partitions += $uncertainPart
							$operatorCleared++
						}
					}
					if ($operatorCleared -gt 0) {
						Write-LogHost "  [RESUME] -ClearUncertainCreate: cleared $operatorCleared not-visible partition(s) for a fresh create this run (durable state persisted before any create)." -ForegroundColor Yellow
					}
					$heldCount = @($reconcileOutcome.Unresolved).Count + @($reconcileOutcome.FailedClosed).Count - $operatorCleared
					if ($heldCount -gt 0) {
						Write-LogHost "  [RESUME] $heldCount partition(s) remain uncertain (no proven create) - NOT launching a worker; re-run with -ClearUncertainCreate <partition index> to force a fresh create for a specific partition" -ForegroundColor Yellow
					}
				}
				$partitions += $partitionCategories.ToCreateAndFetch
				
				if ($partitions.Count -eq 0) {
					Write-LogHost "  [RESUME] All partitions already completed! Skipping query group." -ForegroundColor Green
					continue  # Skip to next query group
				}
				
				Write-LogHost "  [RESUME] Processing $($partitions.Count) of $originalPartitionCount partition(s)" -ForegroundColor Cyan
			}
			
			# Parallel processing using Start-ThreadJob
			# CRITICAL: EOM mode is NOT compatible with parallel processing (implicit remoting session conflicts)
			# Graph API mode uses REST calls which are thread-safe and session-independent
			if ($canParallel) {
				# ========================================
				# DUAL-MODE PARALLEL VALIDATION
				# ========================================
				
				if ($UseEOM) {
					# EOM mode + parallel = guaranteed failure due to implicit remoting
					Write-LogHost "  ERROR: Parallel processing is not compatible with -UseEOM mode" -ForegroundColor Red
					Write-LogHost "  Reason: Exchange Online implicit remoting cannot be safely shared across ThreadJobs" -ForegroundColor Yellow
					Write-LogHost "  This combination should have been blocked by validation - falling back to sequential" -ForegroundColor Yellow
					$canParallel = $false
				}
				else {
					# Graph API mode - parallel is safe.
					# $maxConcurrentPartitions is the effective ThreadJob ceiling for this run, computed
					# as min(MaxConcurrency, partition count). Show partition/cap separately so a small run
					# (e.g. 1 partition) doesn't appear to have throttled MaxConcurrency.
					Write-LogHost ("  Processing partitions in parallel (Graph API ThreadJobs; partitions={0}, MaxConcurrency={1}, effective={2})..." -f $partitions.Count, $MaxConcurrency, $maxConcurrentPartitions) -ForegroundColor Cyan
				}
				}
				
				if ($canParallel) {
					try {
						# ========================================
					# GRAPH API PARALLEL EXECUTION
					# ========================================
					# Uses ThreadJobs with REST API calls (no session dependency)
					
					# Get Graph context and access token to pass to threads
					$mgContext = Get-MgContext -ErrorAction Stop
					if (-not $mgContext) {
						Write-LogHost "  ERROR: Not connected to Microsoft Graph" -ForegroundColor Red
						$canParallel = $false
					}
					
					# Get access token for Graph API calls in threads
					$accessToken = $null
					try {
						# For AppRegistration auth ONLY: proactively refresh if token is approaching expiration
						# AppRegistration can refresh automatically without user interaction
						# Token lifetime is typically 60-90 minutes; refresh proactively at 30 minutes for safety buffer
						if ($script:AuthConfig.CanReauthenticate -and $script:AuthConfig.Method -eq 'AppRegistration') {
							$tokenAge = $null
							if ($script:AuthConfig.TokenIssueTime) {
								$tokenAge = (Get-Date) - $script:AuthConfig.TokenIssueTime
							}
							
							# Refresh if token is older than 30 minutes (proactive, well before ~60 min expiry)
							if ($tokenAge -and $tokenAge.TotalMinutes -gt 30) {
								Write-LogHost "  [TOKEN] Token age: $([Math]::Round($tokenAge.TotalMinutes, 1)) minutes - proactively refreshing..." -ForegroundColor Yellow
								$refreshResult = Invoke-TokenRefresh -Force
								if ($refreshResult.Success -and $refreshResult.NewToken) {
									$accessToken = $refreshResult.NewToken
									$script:AuthConfig.TokenIssueTime = Get-Date  # Reset age timer
									Write-LogHost "  [TOKEN] Fresh token obtained for partition launch" -ForegroundColor Cyan
								}
								else {
									Write-LogHost "  [TOKEN] Proactive refresh failed, using current token: $($refreshResult.Message)" -ForegroundColor Yellow
								}
							}
							elseif ($tokenAge) {
								Write-LogHost "  [TOKEN] Token age: $([Math]::Round($tokenAge.TotalMinutes, 1)) minutes - using current token" -ForegroundColor DarkGray
							}
						}
						
						# If we don't have a token yet, use reliable extraction helper
						if (-not $accessToken) {
							$accessToken = Get-GraphAccessToken
						}
					}
					catch {
						Write-LogHost "  WARNING: Could not retrieve access token, parallel execution may fail" -ForegroundColor Yellow
					}
					
					if ($canParallel) {
						$jobs = @()
						$jobMeta = @{}
						
						# Progress tracking uses actual partition count
						$script:progressState.Query.Total = $partitions.Count
						$script:progressState.Query.Current = 0
						
		# Conditional message based on whether all partitions launch initially or some are queued
		if ($maxConcurrentPartitions -ge $partitions.Count) {
			Write-LogHost "  Launching all $($partitions.Count) queries in parallel (initially may take several minutes)..." -ForegroundColor DarkCyan
		} else {
			Write-LogHost "  Launching initial $maxConcurrentPartitions/$($partitions.Count) queries, remaining queued as slots free (initially may take several minutes)..." -ForegroundColor DarkCyan
		}
		
		# Launch jobs asynchronously - we'll start monitoring after first batch is queued
		$launchStartTime = Get-Date
		$monitoringStarted = $false
		$firstBatchSize = [Math]::Min($maxConcurrentPartitions, $partitions.Count)
		
		# Track which messages we've already shown (global deduplication)
		$script:shownJobMessages = @{}
		
		# Track partition status for retry logic and final summary
		$script:partitionStatus = @{}
		
		# Track page download progress per partition index (for STATUS display)
		$script:partitionPageCounts = @{}
		
		# Track how many job output messages we've already processed per job (prevent O(n) iteration growth)
		$script:jobOutputOffset = @{}
		
		# Track how many partitions were already complete before this run started (resume offset for STATUS display)
		$script:resumeCompletedOffset = if ($script:IsResumeMode -and $script:CheckpointData.partitions.completed) { $script:CheckpointData.partitions.completed.Count } else { 0 }
		foreach ($pt in $partitions) {
			$script:partitionStatus[$pt.Index] = @{
				Partition = $pt
				AttemptNumber = 1
				QueryId = $null
				QueryName = $null
				Status = 'NotStarted'  # NotStarted, Sent, Complete, Failed, Subdivided, JobCreated
				LastError = $null
				RecordCount = 0
				LastFailureSignature = $null
				ConsecutiveIdenticalFailures = 0
				IsTerminalFailure = $false
				LastFailureStage = $null
				LastFailureReason = $null
				# Structured per-query lifecycle state (additive, optional on
				# legacy checkpoint load). Mirrors New-GraphAuditLifecycleState so the
				# parent entry and its checkpoint representation carry the same fields.
				QueryApiVersion = $null
				LifecycleOperation = $null
				FailureCategory = 'None'
				AlternateVersionChecked = $false
				AlternateVersionResult = $null
				QueryConfirmedAbsent = $false
				ReplacementAttempted = $false
				ReplacementQueryId = $null
				LastLifecycleHttpStatus = $null
				LifecycleRetryCount = 0
				ZeroRecordComplete = $false
				UncertainCreate = $false
				UncertainCreateInfo = $null
			}
			# v6 shape-contract guard: catches a future PR that drops a required
			# partitionStatus field. Cheap (runs once per partition at init).
			Assert-PartitionStatusEntry -Entry $script:partitionStatus[$pt.Index] -Context "fresh init pt=$($pt.Index)"
		}
		
		# Update checkpoint with partition count - only update total for fresh runs
		if ($script:CheckpointData) {
			if (-not $script:IsResumeMode) {
				# Fresh run: set total from actual partition count
				$script:CheckpointData.partitions.total = $partitions.Count
			}
			# For resume mode, keep original total from checkpoint
			$script:CheckpointData.statistics.partitionsRemaining = $partitions.Count
			Save-CheckpointToDisk
		}
		
		# Track which partitions have had jobs created for them (for dynamic subdivision support)
		$script:partitionsWithJobs = New-Object System.Collections.Generic.HashSet[int]

		# Run-scoped set of durable-uncertain partitions that a same-process READ-ONLY
		# reconcile could NOT resolve (fail-closed on multiple, unresolved on none). Held
		# partitions are never re-POSTed and are excluded from the outer-loop pending
		# selector so the create loop terminates instead of re-dispatching an unproven
		# create forever - mirroring the IsTerminalFailure exclusion.
		$script:uncertainReconcileHeld = [System.Collections.Generic.HashSet[int]]::new()

		#region PAX-1E query-poll observability (additive; no timeout / no query-age ceiling)
		# ---------------------------------------------------------------------------------
		# Shared, parent-owned, thread-safe observation channel. Each active partition
		# worker publishes an immutable snapshot into this dictionary after every
		# SUCCESSFUL server status poll (and updates error/host-gap fields on failures).
		# The parent monitor loops read this dictionary DIRECTLY - they never parse
		# repeated display text and never depend on Receive-Job timing to know the last
		# successful server poll. Snapshots are replaced atomically (never mutated in
		# place) so the parent can never observe a half-updated object.
		# NOTE: the worker runs in an isolated ThreadJob runspace and does NOT inherit
		# these script-scoped helpers; it mirrors the SAME snapshot field set inline.
		# tests/Purview.QueryPollObservability.Tests.ps1 proves (a) this pure builder's
		# field logic and (b) that the worker's inline mirror carries an identical field
		# set, so the tested logic is the shipped logic.
		if (-not $script:QueryObservations) {
			$script:QueryObservations = [System.Collections.Concurrent.ConcurrentDictionary[int, object]]::new()
		} else {
			$script:QueryObservations.Clear()
		}
		# Cumulative host-suspension time excluded from network-outage accounting across
		# all partitions this run (reported by the parent heartbeat only when nonzero).
		$script:QueryHostGapSecondsTotal = 0.0
		# Parent monitor-loop timing (UTC of the last status emission) used to detect an
		# extended parent-loop / log-delivery delay.
		$script:PaxLastStatusEmitUtc = $null
		# Parent-owned token-refresh state used by the authoritative heartbeat. Never
		# holds token material - only lifecycle state + timing.
		if (-not $script:PaxTokenRefreshState) {
			$script:PaxTokenRefreshState = [pscustomobject]@{
				State              = 'Idle'      # Idle | Refreshing | Succeeded | Failed
				LastReason         = $null
				LastAuthMode       = $null
				StartedUtc         = $null
				LastSuccessUtc     = $null
				LastElapsedSeconds = $null
				LastError          = $null       # category/short reason only - never token/credential text
			}
		}

		# Pure builder for one immutable partition observation snapshot. All time inputs
		# are UTC instants. QueryAgeSeconds is $null when the submission instant is not
		# genuinely known (reused QueryId with no checkpoint-provided creation time) -
		# never fabricated.
		function script:New-PaxQueryObservation {
			param(
				[Parameter(Mandatory)][int]$PartitionIndex,
				[int]$AttemptNumber = 1,
				[string]$ServerStatus = $null,
				[Nullable[datetime]]$QuerySubmittedUtc = $null,
				[Nullable[datetime]]$FirstObservedUtc = $null,
				[Nullable[datetime]]$LastSuccessfulPollUtc = $null,
				[Nullable[datetime]]$LastStatusTransitionUtc = $null,
				[int]$PollCount = 0,
				[int]$ConsecutivePollErrors = 0,
				[string]$LastPollErrorCategory = $null,
				[Nullable[datetime]]$TokenRefreshInstantUtc = $null,
				[double]$HostGapSecondsExcluded = 0.0,
				[Nullable[datetime]]$NowUtc = $null
			)
			$now = if ($NowUtc) { [datetime]$NowUtc } else { (Get-Date).ToUniversalTime() }
			$queryAge = $null
			if ($QuerySubmittedUtc) { $queryAge = [Math]::Round(($now - [datetime]$QuerySubmittedUtc).TotalSeconds, 1) }
			$firstObsAge = $null
			if ($FirstObservedUtc) { $firstObsAge = [Math]::Round(($now - [datetime]$FirstObservedUtc).TotalSeconds, 1) }
			$lastPollAge = $null
			if ($LastSuccessfulPollUtc) { $lastPollAge = [Math]::Round(($now - [datetime]$LastSuccessfulPollUtc).TotalSeconds, 1) }
			return [pscustomobject]@{
				PartitionIndex            = $PartitionIndex
				AttemptNumber             = $AttemptNumber
				ServerStatus              = $ServerStatus
				QuerySubmittedUtc         = $QuerySubmittedUtc
				FirstObservedUtc          = $FirstObservedUtc
				LastSuccessfulPollUtc     = $LastSuccessfulPollUtc
				LastStatusTransitionUtc   = $LastStatusTransitionUtc
				PollCount                 = $PollCount
				ConsecutivePollErrors     = $ConsecutivePollErrors
				LastPollErrorCategory     = $LastPollErrorCategory
				TokenRefreshInstantUtc    = $TokenRefreshInstantUtc
				HostGapSecondsExcluded    = [Math]::Round($HostGapSecondsExcluded, 1)
				QueryAgeSeconds           = $queryAge
				FirstObservedAgeSeconds   = $firstObsAge
				LastSuccessfulPollAgeSeconds = $lastPollAge
				SnapshotUtc               = $now
			}
		}

		# Map a poll failure to a NON-sensitive category. Never returns or inspects
		# response bodies, tokens, URLs, or query ids - category only.
		function script:Get-PaxPollErrorCategory {
			param([string]$StatusCode = $null, [string]$Message = $null)
			$m = ("{0} {1}" -f $StatusCode, $Message)
			if ($m -match '429|Too\s*Many\s*Requests|throttl') { return 'Throttled' }
			if ($m -match '401|403|Unauthorized|Forbidden|InvalidAuthenticationToken|token') { return 'Authentication' }
			if ($m -match '404|Not\s*Found|QUERY-GONE|gone') { return 'Gone' }
			if ($m -match '5\d{2}|timed out|timeout|connection|unable to connect|could not be resolved|temporarily unavailable|network|Bad Gateway|Service Unavailable|Gateway Timeout|Internal Server Error') { return 'Network' }
			return 'Other'
		}

		# Host-gap accounting. Given the sleep we INTENDED and the wall-clock actually
		# consumed, return the excess seconds attributable to host suspension - but only
		# when that excess is material (>= tolerance). Small scheduler jitter returns 0.
		# This is REPORTING/exclusion math only; it never terminates or truncates work.
		function script:Measure-PaxHostGap {
			param(
				[double]$IntendedSeconds,
				[Parameter(Mandatory)][datetime]$BeforeUtc,
				[Parameter(Mandatory)][datetime]$AfterUtc,
				[double]$ToleranceSeconds = 30.0
			)
			$actual = ($AfterUtc - $BeforeUtc).TotalSeconds
			$rawExcess = $actual - $IntendedSeconds
			if ($rawExcess -ge $ToleranceSeconds) { return [Math]::Round($rawExcess, 1) }
			return 0.0
		}

		# Shift an active network-outage start FORWARD by the excluded host-gap seconds so
		# host-suspension time is not counted as network downtime. Returns the (possibly
		# unchanged) start instant; never erases real time spent in a failing network call.
		function script:Get-PaxOutageStartAfterHostGap {
			param([Nullable[datetime]]$NetOutageStartUtc, [double]$ExcludedSeconds)
			if ($null -eq $NetOutageStartUtc) { return $null }
			if ($ExcludedSeconds -le 0) { return [datetime]$NetOutageStartUtc }
			return ([datetime]$NetOutageStartUtc).AddSeconds($ExcludedSeconds)
		}

		# Measure parent monitor-loop scheduling delay. Returns excess seconds beyond the
		# expected cadence + tolerance, else 0. Cause is NOT classified here.
		function script:Measure-PaxParentLoopDelay {
			param(
				[Nullable[datetime]]$PreviousIterationUtc,
				[Parameter(Mandatory)][datetime]$CurrentUtc,
				[double]$ExpectedCadenceSeconds,
				[double]$ToleranceSeconds = 30.0
			)
			if ($null -eq $PreviousIterationUtc) { return 0.0 }
			$gap = ($CurrentUtc - [datetime]$PreviousIterationUtc).TotalSeconds
			$excess = $gap - ($ExpectedCadenceSeconds + $ToleranceSeconds)
			if ($excess -gt 0) { return [Math]::Round($gap, 1) }
			return 0.0
		}

		# Token-refresh lifecycle setters (Set-PaxTokenRefreshing / Resolve-PaxTokenRefresh)
		# are defined EARLY (just before Refresh-GraphTokenIfNeeded) so that every refresh
		# call site - including the ones that run before this parallel section - can record
		# truthful state. See that definition for details.

		# Build the authoritative parent heartbeat from partition status + shared
		# observations. Aggregate counts only - never per-partition rows, never any
		# row/query/token/customer data. Returns a structured object plus a Text line.
		function script:Format-PaxParentHeartbeat {
			param(
				[object[]]$PartitionStatuses = @(),
				[object[]]$Observations = @(),
				[object]$PageCounts = $null,
				[object]$TokenRefreshState = $null,
				[Nullable[datetime]]$NowUtc = $null,
				[double]$ExcludedHostGapSeconds = 0.0,
				[int]$ResumeCompletedOffset = 0
			)
			$now = if ($NowUtc) { [datetime]$NowUtc } else { (Get-Date).ToUniversalTime() }
			$active = @($PartitionStatuses | Where-Object { $_ -and $_.Status -ne 'Subdivided' })
			$total = $active.Count + $ResumeCompletedOffset
			$completed = @($active | Where-Object { $_.Status -eq 'Complete' }).Count + $ResumeCompletedOffset
			$failed = @($active | Where-Object { $_.Status -eq 'Failed' }).Count
			$remaining = $active.Count - @($active | Where-Object { $_.Status -eq 'Complete' }).Count - $failed
			if ($remaining -lt 0) { $remaining = 0 }
			# Server-state counts come from live observations (authoritative last poll).
			$serverCounts = [ordered]@{ queued = 0; notStarted = 0; running = 0; other = 0 }
			$oldestQueryAge = $null; $oldestFirstObsAge = $null; $stalestPollAge = $null
			foreach ($o in @($Observations)) {
				if (-not $o) { continue }
				switch (("" + $o.ServerStatus)) {
					'queued'     { $serverCounts.queued++ }
					'notStarted' { $serverCounts.notStarted++ }
					'running'    { $serverCounts.running++ }
					default      { if ($o.ServerStatus) { $serverCounts.other++ } }
				}
				if ($null -ne $o.QueryAgeSeconds) {
					if ($null -eq $oldestQueryAge -or $o.QueryAgeSeconds -gt $oldestQueryAge) { $oldestQueryAge = $o.QueryAgeSeconds }
				}
				if ($null -ne $o.FirstObservedUtc) {
					$fa = [Math]::Round(($now - [datetime]$o.FirstObservedUtc).TotalSeconds, 1)
					if ($null -eq $oldestFirstObsAge -or $fa -gt $oldestFirstObsAge) { $oldestFirstObsAge = $fa }
				}
				if ($null -ne $o.LastSuccessfulPollUtc) {
					$pa = [Math]::Round(($now - [datetime]$o.LastSuccessfulPollUtc).TotalSeconds, 1)
					if ($null -eq $stalestPollAge -or $pa -gt $stalestPollAge) { $stalestPollAge = $pa }
				}
			}
			$trState = 'Idle'; $trLastSuccessAge = $null
			if ($TokenRefreshState) {
				$trState = "" + $TokenRefreshState.State
				if ($TokenRefreshState.LastSuccessUtc) { $trLastSuccessAge = [Math]::Round(($now - [datetime]$TokenRefreshState.LastSuccessUtc).TotalSeconds, 1) }
			}
			$pageProgress = $null
			if ($PageCounts -and $PageCounts.Count -gt 0) {
				$pageProgress = ($PageCounts.GetEnumerator() | Sort-Object Key | ForEach-Object { "P$($_.Key):$([int]$_.Value)pg" }) -join ' '
			}
			$fmtAge = { param($s) if ($null -eq $s) { 'unknown' } elseif ($s -ge 60) { "{0}m" -f [Math]::Round($s/60,1) } else { "{0}s" -f [Math]::Round($s,0) } }
			$text = "Total Queries: $total | Completed: $completed | Remaining: $remaining | Failed: $failed | Server: queued=$($serverCounts.queued) notStarted=$($serverCounts.notStarted) running=$($serverCounts.running)"
			if ($serverCounts.other -gt 0) { $text += " other=$($serverCounts.other)" }
			$ageStr = if ($null -ne $oldestQueryAge) { (& $fmtAge $oldestQueryAge) } else { "first-observed " + (& $fmtAge $oldestFirstObsAge) }
			$text += " | Oldest query: $ageStr | Stalest successful poll: $(& $fmtAge $stalestPollAge)"
			# Token-refresh heartbeat reports only what is known. Initial authentication is not a
			# refresh, so before the first successful refresh the age is reported in words rather
			# than as a numeric age. A prior success stays visible after a later failed attempt.
			$trStateLower = $trState.ToLower()
			if ($null -eq $trLastSuccessAge) {
				$trSuffix = if ($trStateLower -eq 'failed') { 'no successful refresh yet' } else { 'no refresh completed yet' }
			} else {
				$trSuffix = "last success $(& $fmtAge $trLastSuccessAge) ago"
			}
			$text += " | Token refresh: $trStateLower, $trSuffix"
			if ($ExcludedHostGapSeconds -gt 0) { $text += " | Host-gap excluded: $(& $fmtAge $ExcludedHostGapSeconds)" }
			return [pscustomobject]@{
				Total = $total; Completed = $completed; Remaining = $remaining; Failed = $failed
				ServerQueued = $serverCounts.queued; ServerNotStarted = $serverCounts.notStarted
				ServerRunning = $serverCounts.running; ServerOther = $serverCounts.other
				OldestQueryAgeSeconds = $oldestQueryAge; OldestFirstObservedAgeSeconds = $oldestFirstObsAge
				StalestSuccessfulPollAgeSeconds = $stalestPollAge
				TokenRefreshState = $trState; LastTokenSuccessAgeSeconds = $trLastSuccessAge
				PageProgress = $pageProgress; ExcludedHostGapSeconds = [Math]::Round($ExcludedHostGapSeconds, 1)
				Text = $text
			}
		}

		# Deliver a heartbeat line and measure terminal/log persistence latency. When the
		# delivering call itself takes materially longer than the expected interval, a
		# NON-recursive follow-up warning is emitted via -WarnAction with the event and
		# delivery instants. Cause is not classified (not called a Purview/host/folder
		# failure). -WarnAction must not re-enter this helper.
		function script:Invoke-PaxHeartbeatDelivery {
			param(
				[Parameter(Mandatory)][scriptblock]$DeliverAction,
				[double]$ExpectedIntervalSeconds = 60.0,
				[double]$ToleranceSeconds = 30.0,
				[scriptblock]$WarnAction = $null,
				[Nullable[datetime]]$EventUtc = $null,
				[scriptblock]$NowProvider = $null
			)
			$nowFn = if ($NowProvider) { $NowProvider } else { { (Get-Date).ToUniversalTime() } }
			$eventAt = if ($EventUtc) { [datetime]$EventUtc } else { (& $nowFn) }
			& $DeliverAction
			$deliveredAt = (& $nowFn)
			$elapsed = ($deliveredAt - $eventAt).TotalSeconds
			if ($elapsed -gt ($ExpectedIntervalSeconds + $ToleranceSeconds) -and $WarnAction) {
				& $WarnAction $eventAt $deliveredAt ([Math]::Round($elapsed, 1))
			}
			return [Math]::Round($elapsed, 1)
		}
		#endregion PAX-1E query-poll observability

		# Define the ThreadJob scriptblock once for reuse in both initial and retry attempts
		$queryJobScriptBlock = {
		param($pStart, $pEnd, [array]$activity, $resultSize, $userIds, $idx, $tot, $sharedAuthState, $partition, $maxOutageMinutes, $apiVersion, $logPath, $existingQueryId, $incrementalDir, $runTimestamp, $memoryFlushEnabled, $queryObservations)
			# Suppress web request progress bar in job runspace
			$ProgressPreference = 'SilentlyContinue'

			# Culture guard for ThreadJob runspaces. PowerShell 5.1 does not
			# inherit the parent runspace's CurrentCulture into ThreadJobs,
			# so the main-thread guard at the top of the script does not
			# reach this scope. Without this line, on a da-DK or fi-FI host
			# the audit query body emitted below substitutes ':' with the
			# culture's TimeSeparator ('.'), producing an invalid ISO 8601
			# datetime that the Purview audit endpoint rejects with HTTP 500.
			[System.Threading.Thread]::CurrentThread.CurrentCulture   = [System.Globalization.CultureInfo]::InvariantCulture
			[System.Threading.Thread]::CurrentThread.CurrentUICulture = [System.Globalization.CultureInfo]::InvariantCulture

			# Helper function to build audit API URIs with correct version
			function Get-AuditUri { param($path) return "https://graph.microsoft.com/$apiVersion/security/auditLog/$path" }
			
			# Helper function to get current headers with fresh token from shared state
			# This enables token refresh by main thread while job is running
			function Get-CurrentHeaders {
				param([string]$ClientRequestId)
				return @{
					'Authorization' = "Bearer $($sharedAuthState.Token)"
					'Content-Type' = 'application/json'
					'client-request-id' = $ClientRequestId
				}
			}
			
			# Helper function to check if token is expired or near-expiry.
			# Returns $true if token is still valid with at least 2 minute buffer.
			function Test-TokenValid {
				if (-not $sharedAuthState.ExpiresOn) {
					# No expiry info - assume valid (will fail with 401 if not)
					return $true
				}
				$expiresOn = $sharedAuthState.ExpiresOn
				$now = (Get-Date).ToUniversalTime()
				$bufferMinutes = 2
				$remainingMinutes = ($expiresOn - $now).TotalMinutes
				return ($remainingMinutes -gt $bufferMinutes)
			}
			
			# Wait-ForTokenRefresh: Called by thread jobs on 401/403 to wait for main thread token refresh
			# Instead of retrying immediately with the same expired token, waits until $sharedAuthState.Token changes
			# AppReg: max 120s (silent client_credentials refresh is fast)
			# Interactive: max 86400s (24 hours - user may be away overnight)
			function Wait-ForTokenRefresh {
				$oldToken = $sharedAuthState.Token
				$authMethod = $sharedAuthState.AuthMethod
				$maxWaitSeconds = if ($authMethod -eq 'AppRegistration') { 120 } else { 86400 }
				$checkInterval = if ($authMethod -eq 'AppRegistration') { 5 } else { 30 }
				$waited = 0
				
				Write-Output "[$(Get-Date -Format 'HH:mm:ss')] [P$idx] Auth failure detected - waiting for main thread token refresh ($authMethod mode, max ${maxWaitSeconds}s)..."
				
				while ($waited -lt $maxWaitSeconds) {
					Start-Sleep -Seconds $checkInterval
					$waited += $checkInterval
					
					# Check if token changed (main thread refreshed it)
					if ($sharedAuthState.Token -ne $oldToken) {
						Write-Output "[$(Get-Date -Format 'HH:mm:ss')] [P$idx] Token refreshed by main thread after ${waited}s wait. Resuming."
						return $true
					}
					
					# Periodic status for long waits (every 5 minutes)
					if ($waited % 300 -eq 0) {
						Write-Output "[$(Get-Date -Format 'HH:mm:ss')] [P$idx] Still waiting for token refresh... (${waited}s elapsed, max ${maxWaitSeconds}s)"
					}
				}
				
				Write-Output "[$(Get-Date -Format 'HH:mm:ss')] [P$idx] Token refresh wait timed out after ${maxWaitSeconds}s."
				return $false
			}
			
			$allRecords = [System.Collections.Generic.List[object]]::new()
			$threadSavedToDisk = $false
			$threadSavedFile = $null
			$jobRunId = [System.Guid]::NewGuid().ToString('N').Substring(0, 8)  # Unique per job execution — ensures retry flush files don't collide with original run files
			$t0 = Get-Date
			$queryId = $existingQueryId  # Use existing QueryId if provided (for retry after 403 fetch failure)
			$debugInfo = $null
				
			# Initialize telemetry tracking
			$telemetry = [PSCustomObject]@{
				PartitionIndex = $idx
				PartitionTotal = $tot
				PartitionStart = $pStart.ToString('yyyy-MM-dd HH:mm:ss')
				PartitionEnd = $pEnd.ToString('yyyy-MM-dd HH:mm:ss')
				PartitionHours = [Math]::Round(($pEnd - $pStart).TotalHours, 2)
				QueryCreatedAt = $null
				InitialPollDelaySeconds = 0
				FirstRunningAt = $null
				SucceededAt = $null
				FirstPageAt = $null
				LastPageAt = $null
				PageCount = 0
				RowCount = 0
				ThrottledCount = 0
				RetryAfterTotalSeconds = 0
				ElapsedMinutes = 0
				Status = 'unknown'
				SplitRequired = $false
				PostFetch10KLimit = $false
				PostFetch1MLimit = $false
			PreemptiveSubdivision = $false
			PreemptiveCount = 0
			SubdivisionReason = $null
			PreviewRecordCount = 0
			ThrottleRetriesDuringCreation = 0
		}
						
		try {
			# Check token validity BEFORE starting any API work. If the token is
			# expired or near-expiry, return early so the main thread can retry
			# with a fresh token.
			if (-not (Test-TokenValid)) {
				$telemetry.Status = 'token_expired'
				Write-Output "[TOKEN-EXPIRED] Partition $idx/$tot - Token expired or near-expiry, returning for retry with fresh token"
				return [pscustomobject]@{
					Activity = $activity
					Logs = @()
					RetrievedCount = 0
					ElapsedMs = 0
					Partition = $idx
					Total = $tot
					QueryId = $existingQueryId
					DebugInfo = $null
					Telemetry = $telemetry
					TokenExpired = $true
				}
			}
			
			$activeRecordFilters = if ($partition.RecordTypes -and $partition.RecordTypes.Count -gt 0) { @($partition.RecordTypes) } else { $null }
			$activeServiceFilter = $partition.ServiceFilter
		
			# Use all activities from partition
			$queryActivities = if ($partition.Activities) { $partition.Activities } else { @($partition.Activity) }
			# Log helper to capture current query payload state in debug stream (processed by parent thread)
		function Write-GraphQueryDebug {
			param(
				[string]$Header,
				[array]$Operations,
				[array]$RecordFilters,
				[string]$ServiceFilter,
				[string]$PayloadJson
			)
			$debugLines = @()
			$debugLines += "$Header"
			if ($RecordFilters -and $RecordFilters.Count -gt 0) {
				$debugLines += "  recordTypeFilters: $($RecordFilters -join ', ')"
			}
			if ($ServiceFilter) {
				$debugLines += "  serviceFilter: $ServiceFilter"
			}
			$debugLines += $PayloadJson
			foreach ($line in $debugLines) {
				Write-Output $line
			}
		}
			
			# Generate unique client-request-id for traceability (critical for Microsoft support)
		$clientRequestId = [guid]::NewGuid().ToString()
		
		# Get headers with current token (will be refreshed via Get-CurrentHeaders for each API call)
		$headers = Get-CurrentHeaders -ClientRequestId $clientRequestId
			
# PREEMPTIVE SUBDIVISION CHECK: Disabled - Graph API queries endpoint doesn't support
		# filtering by query payload properties, so we can't preemptively count records.
		# Subdivision will happen post-fetch based on actual record counts.
		$shouldSubdividePreemptively = $false
		$preemptiveCountCheck = $null
			
			# Construct displayName with partition info: PAX_Query_YYYYMMDD_HHMM-YYYYMMDD_HHMM_PartX/Y
			# Use last included minute (pEnd - 1 minute) since end date is exclusive
			$pEndDisplay = $pEnd.AddMinutes(-1)
			$displayName = "PAX_Query_$($pStart.ToString('yyyyMMdd_HHmm'))-$($pEndDisplay.ToString('yyyyMMdd_HHmm'))_Part$idx/$tot"
			
			# If preemptive subdivision is needed, skip query creation and return subdivision signal
			if ($shouldSubdividePreemptively) {
				$telemetry.Status = 'subdivided_preemptively'
				$telemetry.SplitReason = "Count check returned $preemptiveCountCheck records (>= 9500 threshold)"
				return [pscustomobject]@{
					Activity = $activity
					Logs = @()
					RetrievedCount = 0
					ElapsedMs = 0
					Partition = $idx
					Total = $tot
					QueryId = $null
					DebugInfo = $null
					Telemetry = $telemetry
				}
			}
			
			# The parent creates every partition query before this worker is launched and
			# passes its id in through $existingQueryId ($queryId). A worker never creates
			# a query. Convert the outage tolerance to seconds here so the FETCH phase
			# always has it regardless of how the query id arrived.
			$maxNetworkOutageSeconds = $maxOutageMinutes * 60
			$telemetry.QueryCreatedAt = 'reused_existing'

			# A missing query id means the parent-side creation did not produce one for
			# this partition. That is a structured failure for the partition, surfaced the
			# same way a create failure was, never a silent create here.
			if (-not $queryId) {
				$telemetry.Status = 'create_missing'
				try {
					$logMsg = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [CREATE-FAILED] Partition $idx/$tot - No QueryId supplied to worker (parent-side creation did not provide one)"
					$logMsg | Add-Content -Path $logPath -Encoding UTF8 -ErrorAction SilentlyContinue
				} catch {}
				throw "[CREATE-FAILED] No QueryId supplied to worker (parent-side creation did not provide one)"
			}

			# Log query details for the query the parent created.
			$debugInfo = "Query ID: $queryId | DateRange: $($pStart.ToString('yyyy-MM-dd HH:mm')) to $($pEnd.ToString('yyyy-MM-dd HH:mm')) UTC | Activities: $($queryActivities -join ', ')"

			# Step 2: Poll for completion (no artificial timeout — polls until Purview responds)
				# Microsoft guidance: 30-60s intervals for enterprise-scale parallel execution
				# Network outage tolerance (adaptive) using passed-in MaxNetworkOutageMinutes parameter
				$effectiveOutage = if ($maxOutageMinutes -and $maxOutageMinutes -gt 0) { $maxOutageMinutes } else { 30 }
				$netOutageStart = $null
				$netErrorStreak = 0
				$netPatterns = @('timed out','connection','unable to connect','remote name could not be resolved','temporarily unavailable','network','500','502','503','504','bad gateway','gateway timeout','service unavailable','internal server error')
				$lastNetHeartbeat = Get-Date
				$lastNetMessage = $null  # Throttle repetitive network messages
				$netMessageMinInterval = 60  # Minimum seconds between network status messages
				# Flood suppression. Only emit the green "[NET] Connectivity
				# restored" line when we ACTUALLY printed a "[NETWORK] Transient
				# network issue" message for the current outage. Short blips silently
				# absorbed by the throttle must not produce noisy recovery banners on
				# every successful poll.
				$netOutageAnnounced = $false
				$pollCount = 0
				
				$pollStartTime = Get-Date
				$queryComplete = $false

				# PAX-1E worker observation tracking (published atomically into the shared
				# parent dictionary $queryObservations after each successful/failed poll).
				$obsFirstObservedUtc = $null
				$obsLastSuccessfulPollUtc = $null
				$obsLastStatusTransitionUtc = $null
				$obsLastServerStatus = $null
				$obsConsecutivePollErrors = 0
				$obsLastErrorCategory = $null
				$obsHostGapSecondsExcluded = 0.0
				$obsLastIntendedSleep = 0.0
				# Genuine PAX creation instant when THIS run created the query; $null for a
				# reused/resumed QueryId (age is then reported as unknown/first-observed, never
				# fabricated).
				$obsQuerySubmittedUtc = if (-not $existingQueryId) { (Get-Date).ToUniversalTime() } else { $null }
				# Inline snapshot builder - mirrors the script-scoped New-PaxQueryObservation
				# field set EXACTLY (proven by tests/Purview.QueryPollObservability.Tests.ps1).
				function New-ObsSnapshot {
					param($ServerStatus, $NowUtc)
					$now = if ($NowUtc) { [datetime]$NowUtc } else { (Get-Date).ToUniversalTime() }
					$qAge = if ($obsQuerySubmittedUtc) { [Math]::Round(($now - $obsQuerySubmittedUtc).TotalSeconds, 1) } else { $null }
					$foAge = if ($obsFirstObservedUtc) { [Math]::Round(($now - $obsFirstObservedUtc).TotalSeconds, 1) } else { $null }
					$lpAge = if ($obsLastSuccessfulPollUtc) { [Math]::Round(($now - $obsLastSuccessfulPollUtc).TotalSeconds, 1) } else { $null }
					$refUtc = if ($sharedAuthState -and $sharedAuthState.PSObject.Properties.Name -contains 'LastRefreshUtc' -and $sharedAuthState.LastRefreshUtc) { $sharedAuthState.LastRefreshUtc } else { $null }
					return [pscustomobject]@{
						PartitionIndex               = $idx
						AttemptNumber                = $(if ($telemetry -and $telemetry.PSObject.Properties.Name -contains 'RetryAttempt' -and $telemetry.RetryAttempt) { [int]$telemetry.RetryAttempt } else { 1 })
						ServerStatus                 = $ServerStatus
						QuerySubmittedUtc            = $obsQuerySubmittedUtc
						FirstObservedUtc             = $obsFirstObservedUtc
						LastSuccessfulPollUtc        = $obsLastSuccessfulPollUtc
						LastStatusTransitionUtc      = $obsLastStatusTransitionUtc
						PollCount                    = $pollCount
						ConsecutivePollErrors        = $obsConsecutivePollErrors
						LastPollErrorCategory        = $obsLastErrorCategory
						TokenRefreshInstantUtc       = $refUtc
						HostGapSecondsExcluded       = [Math]::Round($obsHostGapSecondsExcluded, 1)
						QueryAgeSeconds              = $qAge
						FirstObservedAgeSeconds      = $foAge
						LastSuccessfulPollAgeSeconds = $lpAge
						SnapshotUtc                  = $now
					}
				}

				# Initial wait before first poll with randomization to prevent synchronization
				$initialWaitSeconds = Get-Random -Minimum 30 -Maximum 60
				$telemetry.InitialPollDelaySeconds = $initialWaitSeconds
				Start-Sleep -Seconds $initialWaitSeconds

				$obsIterStartUtc = (Get-Date).ToUniversalTime()
				while (-not $queryComplete) {
					$pollCount++
					# PAX-1E host-gap accounting: a wall-clock gap between poll iterations that
					# materially exceeds the sleep we intended indicates the host suspended this
					# worker (container throttle / VM sleep). Exclude that excess from network-
					# outage accounting; NEVER fail, cancel, or age-out the query on it.
					$obsIterNowUtc = (Get-Date).ToUniversalTime()
					$obsIterGap = ($obsIterNowUtc - $obsIterStartUtc).TotalSeconds - $obsLastIntendedSleep
					if ($obsIterGap -ge 30) {
						$obsHostGapSecondsExcluded += [Math]::Round($obsIterGap, 1)
						if ($netOutageStart) { $netOutageStart = $netOutageStart.AddSeconds($obsIterGap) }
						Write-Output ("[HOSTGAP] Partition $idx/$tot - Worker scheduling resumed after an extended host delay (~{0}s excluded from outage accounting)" -f [Math]::Round($obsIterGap, 0))
					}
					$obsIterStartUtc = $obsIterNowUtc
					
					# Poll query status with 429 throttling detection
					try {
						# Pre-check: if token is already expired, wait for refresh before making a doomed API call
						if (-not (Test-TokenValid)) {
							Write-Output "[$(Get-Date -Format 'HH:mm:ss')] [P$idx] Token expired before POLL - waiting for main thread refresh..."
							$null = Wait-ForTokenRefresh
						}
						$statusResponse = Invoke-RestMethod -Method GET -Uri (Get-AuditUri -path "queries/$queryId") `
							-Headers (Get-CurrentHeaders -ClientRequestId $clientRequestId) -ErrorAction Stop
						# Reset outage tracking on success
						if ($netOutageStart) {
							$duration = (Get-Date) - $netOutageStart
							# Only log recovery if outage lasted > 1 minute AND we actually announced
							# a transient-network message for it. Without the announced-gate, rapid
							# blip→recover→blip→recover cycles would flood the console with identical
							# "[NET] Connectivity restored after 1.1 minutes" lines because the error
							# path is throttled to silence but the recovery path has no matching
							# suppression.
							if ($duration.TotalMinutes -ge 1 -and $netOutageAnnounced) {
								Write-Host "[NET] Connectivity restored after $([Math]::Round($duration.TotalMinutes,1)) minutes - Partition $idx/$tot" -ForegroundColor Green
							}
							$netOutageStart = $null; $netErrorStreak = 0; $netOutageAnnounced = $false
							$lastNetHeartbeat = Get-Date  # Reset heartbeat timer on recovery
							# NOTE: Do NOT reset $lastNetMessage here - keep throttle window active
							# to prevent message flooding during intermittent connectivity
						}
					}
					catch {
						# PAX-1E: record a poll ERROR as a NON-sensitive category (never body/token/
						# url/queryId) and publish, WITHOUT disturbing the last-successful-poll instant.
						$obsConsecutivePollErrors++
						$obsErrCode = ''
						if ($_.Exception.Response) { try { $obsErrCode = "" + $_.Exception.Response.StatusCode } catch {} }
						$obsErrMsg = "" + $_.Exception.Message
						$obsErrProbe = "$obsErrCode $obsErrMsg"
						$obsLastErrorCategory = if ($obsErrProbe -match '429|Too\s*Many\s*Requests|throttl') { 'Throttled' } elseif ($obsErrProbe -match '401|403|Unauthorized|Forbidden|InvalidAuthenticationToken|token') { 'Authentication' } elseif ($obsErrProbe -match '404|Not\s*Found|QUERY-GONE|gone') { 'Gone' } elseif ($obsErrProbe -match '5\d{2}|timed out|timeout|connection|unable to connect|could not be resolved|temporarily unavailable|network|Bad Gateway|Service Unavailable|Gateway Timeout|Internal Server Error') { 'Network' } else { 'Other' }
						if ($queryObservations) { $queryObservations[$idx] = New-ObsSnapshot -ServerStatus $obsLastServerStatus -NowUtc ((Get-Date).ToUniversalTime()) }
						# Check for 429 throttling using safe detection
						$is429 = $false
						if ($_.Exception.Response) {
							$statusCode = $_.Exception.Response.StatusCode
							if ($statusCode -eq 429 -or $statusCode -eq 'TooManyRequests' -or $statusCode.value__ -eq 429) {
								$is429 = $true
							}
						}
						if (-not $is429 -and ($_.Exception.Message -match '429' -or $_.Exception.Message -match 'Too Many Requests')) {
							$is429 = $true
						}
						
						if ($is429) {
							# Track throttling in telemetry
							$telemetry.ThrottledCount++
							# Respect Retry-After header if present, otherwise use 60s default
							$retryAfter = 60
							if ($_.Exception.Response.Headers -and $_.Exception.Response.Headers['Retry-After']) {
								$retryAfter = [int]$_.Exception.Response.Headers['Retry-After']
							}
							$telemetry.RetryAfterTotalSeconds += $retryAfter
							
							# Log throttling event to user
							Write-Host "[!]  API Rate Limit (429) - Partition $idx/$tot - Retry in $retryAfter seconds (Throttle #$($telemetry.ThrottledCount))" -ForegroundColor Yellow
							
							Start-Sleep -Seconds $retryAfter
							continue  # Retry this poll
						}
						else {
							# Check for 403 Forbidden (Microsoft service-side issue)
							$is403Poll = $false
							$pollErrMsg = $_.Exception.Message
							if ($_.Exception.Response) {
								$statusCode = $_.Exception.Response.StatusCode
								if ($statusCode -eq 403 -or $statusCode -eq 'Forbidden' -or $statusCode.value__ -eq 403) {
									$is403Poll = $true
								}
							}
							if (-not $is403Poll -and ($pollErrMsg -match '403' -or $pollErrMsg -match 'Forbidden')) {
								$is403Poll = $true
							}
							
							if ($is403Poll) {
								# Extract diagnostic info from 403 response
								$responseBody403Poll = $null
								$requestId403Poll = $null
								$wwwAuth403Poll = $null
								$isPermanent403Poll = $false
								
								try {
									if ($_.Exception.Response) {
										$requestId403Poll = $_.Exception.Response.Headers['request-id']
										$wwwAuth403Poll = $_.Exception.Response.Headers['WWW-Authenticate']
										$respStream = $_.Exception.Response.GetResponseStream()
										if ($respStream) {
											$reader = New-Object System.IO.StreamReader($respStream)
											$responseBody403Poll = $reader.ReadToEnd()
											$reader.Dispose()
										}
									}
								} catch {}
								
								# Check if permanent 403
								if ($responseBody403Poll -match 'InsufficientPrivileges|Authorization_RequestDenied|AccessDenied|InvalidAuthenticationToken') {
									$isPermanent403Poll = $true
								}
								if ($wwwAuth403Poll -match 'claims') {
									$isPermanent403Poll = $true
								}
								
								# Log diagnostic info
								try {
									$diagLog = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [403-POLL-DIAG] Partition $idx/$tot`n"
									$diagLog += "  client-request-id: $clientRequestId`n"
									$diagLog += "  request-id: $requestId403Poll`n"
									if ($wwwAuth403Poll) { $diagLog += "  WWW-Authenticate: $wwwAuth403Poll`n" }
									if ($responseBody403Poll) { $diagLog += "  Response body: $responseBody403Poll`n" }
									$diagLog += "  Permanent error: $isPermanent403Poll"
									$diagLog | Add-Content -Path $logPath -Encoding UTF8 -ErrorAction SilentlyContinue
								} catch {}
								
								if ($isPermanent403Poll) {
												Write-Output "[403-PERM] Partition $idx/$tot - PERMANENT 403 on POLL - Failing partition | request-id: $requestId403Poll | client-request-id: $clientRequestId"
								}
								
								# 403 during status polling - wait for main thread to refresh token first
								$tokenRefreshed = Wait-ForTokenRefresh
								if ($tokenRefreshed) {
									# Token was refreshed - reset counter and retry immediately with fresh token
									$script:poll403Count = 0
									Write-Output "[403-POLL] Partition $idx/$tot - Token refreshed, resetting retry counter and resuming poll"
									continue  # Retry this poll with new token
								}
								
								# Token refresh failed/timed out - fall through to limited retry logic
								if (-not $script:poll403Count) { $script:poll403Count = 0 }
								$script:poll403Count++
								$max403Polls = 3
								
								if ($script:poll403Count -le $max403Polls) {
									$retryAfter = [Math]::Min(15 * [Math]::Pow(2, $script:poll403Count - 1), 60)
									
									# Thread-safe file logging
									try {
										$logMsg = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [403-POLL] Partition $idx/$tot - Transient 403 (Attempt $($script:poll403Count)/$max403Polls) - Retrying in ${retryAfter}s"
										$logMsg | Add-Content -Path $logPath -Encoding UTF8 -ErrorAction SilentlyContinue
									} catch {}
									
									Write-Output "[403-POLL] Partition $idx/$tot - Transient 403 (Attempt $($script:poll403Count)/$max403Polls) - Retrying in ${retryAfter}s | request-id: $requestId403Poll | client-request-id: $clientRequestId"
									Start-Sleep -Seconds $retryAfter
									continue  # Retry this poll
								} else {
									# Max 403 retries exceeded - fail partition for retry with fresh token
									try {
										$logMsg = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [403-POLL] Partition $idx/$tot - Max transient 403 poll retries exceeded ($max403Polls), failing partition"
										$logMsg | Add-Content -Path $logPath -Encoding UTF8 -ErrorAction SilentlyContinue
									} catch {}
									
Write-Output "[403-MAX] Partition $idx/$tot - Max transient 403 poll retries exceeded - Failing partition | request-id: $requestId403Poll | client-request-id: $clientRequestId"
									throw "403 Forbidden during status poll - max retries exceeded"
								}
							}
							
							# Check for 404 Not Found (query vanished server-side - dead QueryId)
							$is404Poll = $false
							if ($_.Exception.Response) {
								if ($statusCode -eq 404 -or $statusCode -eq 'NotFound' -or $statusCode.value__ -eq 404) {
									$is404Poll = $true
								}
							}
							if (-not $is404Poll -and ($pollErrMsg -match '404' -or $pollErrMsg -match 'Not Found')) {
								$is404Poll = $true
							}
							
							if ($is404Poll) {
								# The pinned-version query is not visible right now. The worker NEVER
								# creates or replaces a query; it RETURNS a structured visibility-failure
								# signal so the parent can revalidate the retained id through the shared
								# decision layer (bounded same-id retry, then a read-only same-id GET on
								# the alternate version) and only replace it, at most once, after the
								# parent positively confirms absence. Diagnostics are preserved.
								try {
									$logMsg = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [QUERY-GONE] Partition $idx/$tot - 404 Not Found on status poll - QueryId $queryId not visible on $apiVersion - returning visibility signal to parent | client-request-id: $clientRequestId"
									$logMsg | Add-Content -Path $logPath -Encoding UTF8 -ErrorAction SilentlyContinue
								} catch {}
								Write-Output "[QUERY-GONE] Partition $idx/$tot - 404 Not Found - Query $queryId not visible on $apiVersion (parent will revalidate/replace)"
								return [PSCustomObject]@{
									QueryId = $queryId
									Status = 'visibility_failure'
									QueryApiVersion = $apiVersion
									FailureCategory = 'QueryNotVisible'
									AlternateVersionChecked = $false
									QueryConfirmedAbsent = $false
									ReplacementAttempted = $false
									LastLifecycleHttpStatus = 404
									PartitionStart = $pStart
									PartitionEnd = $pEnd
									PartitionIndex = $idx
									PartitionTotal = $tot
									RetrievedCount = 0
									Telemetry = $telemetry
								}
							}
							
							# Detect transient network outage vs hard failure
							$errMsg = $_.Exception.Message
							if ($netPatterns | Where-Object { $errMsg.ToLower().Contains($_) }) {
								if (-not $netOutageStart) { $netOutageStart = Get-Date }
								$netErrorStreak++
								$elapsedOutage = (Get-Date) - $netOutageStart
								
								# Throttle messages: only show if outage > 1 min OR no recent message
								$shouldShowMessage = $false
								if ($elapsedOutage.TotalMinutes -ge 1) {
									# Sustained outage - show message but throttle to once per minute
									if (-not $lastNetMessage -or ((Get-Date) - $lastNetMessage).TotalSeconds -ge $netMessageMinInterval) {
										$shouldShowMessage = $true
									}
								} elseif ($netErrorStreak -eq 1 -and (-not $lastNetMessage -or ((Get-Date) - $lastNetMessage).TotalSeconds -ge $netMessageMinInterval)) {
									# First error in a new outage window - show initial message
									$shouldShowMessage = $true
								}
								
								if ($shouldShowMessage) {
									Write-Output "[NETWORK] Transient network issue (streak $netErrorStreak, outage $([Math]::Round($elapsedOutage.TotalMinutes,1))m) - Partition $idx/$tot"
									$lastNetMessage = Get-Date
									$netOutageAnnounced = $true  # unlock the matching "Connectivity restored" line
								}
								
								# Adaptive backoff during outage
								$waitSec = [Math]::Min(95, [Math]::Round(35 * [Math]::Pow(1.3, $netErrorStreak)))
								Start-Sleep -Seconds $waitSec
								
								# Heartbeat every ~5 minutes of sustained outage (only if outage > 2 min)
								if ($elapsedOutage.TotalMinutes -ge 2 -and ((Get-Date) - $lastNetHeartbeat).TotalMinutes -ge 5) {
									Write-Output "[NETWORK] Still waiting on network recovery (outage $([Math]::Round($elapsedOutage.TotalMinutes,1))m, tolerance $effectiveOutage m)"
									$lastNetHeartbeat = Get-Date
								}
								
								if ($elapsedOutage.TotalMinutes -ge $effectiveOutage) {
									throw "Network outage exceeded tolerance ($effectiveOutage minutes)"
								}
								continue
							}
							elseif ($statusCode -eq 401 -or $errorMessage -match '401|Unauthorized') {
								# 401 Unauthorized during poll - token expired, wait for main thread refresh
								Write-Output "[ERROR] Partition $idx/$tot - 401 Unauthorized during poll - waiting for token refresh"
								$refreshed = Wait-ForTokenRefresh -TimeoutSeconds 120 -CheckIntervalSeconds 5
								if ($refreshed) {
									Write-Output "[STATUS] Partition $idx/$tot - Token refreshed, retrying poll"
									$currentToken = $SharedAuthState.AccessToken
									continue  # Retry the poll with fresh token
								} else {
									throw "401 Unauthorized during poll and token refresh timed out"
								}
							}
							else {
								throw  # Non-transient, abort partition
							}
						}
					}
					
					# PAX-1E: record a SUCCESSFUL server poll and publish an atomic snapshot into
					# the shared parent dictionary. Status transition time changes only on an
					# actual state change; last-successful-poll updates every poll.
					$obsNowUtc = (Get-Date).ToUniversalTime()
					if (-not $obsFirstObservedUtc) { $obsFirstObservedUtc = $obsNowUtc }
					$obsLastSuccessfulPollUtc = $obsNowUtc
					$obsConsecutivePollErrors = 0
					$obsCurrentStatus = "" + $statusResponse.status
					if ($obsCurrentStatus -ne $obsLastServerStatus) { $obsLastStatusTransitionUtc = $obsNowUtc; $obsLastServerStatus = $obsCurrentStatus }
					if ($queryObservations) { $queryObservations[$idx] = New-ObsSnapshot -ServerStatus $obsCurrentStatus -NowUtc $obsNowUtc }

					# Process status response
					switch ($statusResponse.status) {
						'succeeded' {
							$telemetry.Status = 'succeeded'
							$telemetry.SucceededAt = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
							
							# RECORD COUNT PREVIEW: Get exact count before fetching data (enables preemptive subdivision)
							try {
								$countUri = "https://graph.microsoft.com/$apiVersion/security/auditLog/queries?`$count=true&`$filter=queryId eq '$queryId'"
							$countResponse = Invoke-RestMethod -Method GET -Uri $countUri -Headers (Get-CurrentHeaders -ClientRequestId $clientRequestId) -TimeoutSec 10 -ErrorAction Stop
							$previewCount = $countResponse.'@odata.count'
							Write-Output "[COUNT] Query $queryId succeeded - Actual record count: $previewCount"
							$telemetry.PreviewRecordCount = $previewCount
								if ($previewCount -ge 9500) {
									$partitionHours = ($pEnd - $pStart).TotalHours
									$minSubdivisionDays = 0.001389  # 2 minutes
									$minSubdivisionHours = $minSubdivisionDays * 24
									
									if ($partitionHours -gt $minSubdivisionHours) {
										# Partition can be subdivided - flag for subdivision and skip record retrieval
										$telemetry.PreemptiveSubdivision = $true
										$telemetry.SubdivisionReason = "preview_count_$previewCount"
										
										Write-Host "[SUBDIVISION] Partition $idx/$tot - Preview count $previewCount >= 9500 - Subdividing partition ($([Math]::Round($partitionHours,2))h window)" -ForegroundColor Yellow
										
										# Return subdivision signal to parent
										return [PSCustomObject]@{
											QueryId = $queryId
											Status = 'needs_subdivision'
											PreviewCount = $previewCount
											PartitionStart = $pStart
											PartitionEnd = $pEnd
											PartitionIndex = $idx
											PartitionTotal = $tot
											RetrievedCount = 0
											Telemetry = $telemetry
										}
									} else {
										Write-Host "[COUNT] Partition $idx/$tot - Preview count $previewCount (at minimum subdivision window $([Math]::Round($partitionHours,2))h, proceeding with fetch)" -ForegroundColor Cyan
									}
								} else {
									Write-Host "[COUNT] Partition $idx/$tot - Preview count $previewCount (below threshold, proceeding with fetch)" -ForegroundColor DarkCyan
								}
							} catch {
								# Count preview failed - proceed with normal fetch (non-critical failure)
								Write-Output "[COUNT-WARN] Partition $idx/$tot - Count preview failed, proceeding with fetch: $($_.Exception.Message)"
							}
							
							# Note: Don't write "Query succeeded" yet - wait until records are actually retrieved and validated
							$queryComplete = $true
							break
						}
						'failed' {
							$telemetry.Status = 'failed'
							Write-Host "✗ Query failed - Partition $idx/$tot - Query ID: $queryId" -ForegroundColor Red
							# Delete failed query from Purview to free server slot
							if ($queryId) {
								try {
									Invoke-RestMethod -Method DELETE -Uri (Get-AuditUri -path "queries/$queryId") `
										-Headers (Get-CurrentHeaders -ClientRequestId $clientRequestId) -ErrorAction SilentlyContinue | Out-Null
								} catch {}
							}
							throw "Query failed"
						}
						'cancelled' {
							$telemetry.Status = 'cancelled'
							Write-Host "✗ Query cancelled - Partition $idx/$tot - Query ID: $queryId" -ForegroundColor Red
							# Delete cancelled query from Purview to free server slot
							if ($queryId) {
								try {
									Invoke-RestMethod -Method DELETE -Uri (Get-AuditUri -path "queries/$queryId") `
										-Headers (Get-CurrentHeaders -ClientRequestId $clientRequestId) -ErrorAction SilentlyContinue | Out-Null
								} catch {}
							}
							throw "Query cancelled"
						}
						'queued' {
							# Query is waiting in backend queue for available execution slot
							$telemetry.Status = 'queued'
							Write-Host "⏳ Query queued (waiting for backend capacity) - Partition $idx/$tot - Retry in 60-90s" -ForegroundColor Cyan
							# Use longer polling interval for queued state (60-90s) since backend capacity is limited
							$waitSeconds = Get-Random -Minimum 60 -Maximum 90
							Start-Sleep -Seconds $waitSeconds
						}
						'notStarted' {
							# Query accepted but not yet started processing
							$telemetry.Status = 'notStarted'
							# Randomized polling interval (35-60s)
							$waitSeconds = Get-Random -Minimum 35 -Maximum 60
							Start-Sleep -Seconds $waitSeconds
						}
						'running' {
							# Track first time we see running status
							if (-not $telemetry.FirstRunningAt) {
								$telemetry.FirstRunningAt = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
								Write-Output "[STATUS] Query running - Partition $idx/$tot - Started processing"
							}
							$telemetry.Status = 'running'
							# Randomized polling interval (35-60s) to prevent synchronization
							$waitSeconds = Get-Random -Minimum 35 -Maximum 60
							Start-Sleep -Seconds $waitSeconds
						}
						default {
							$telemetry.Status = $statusResponse.status
							Write-Host "? Query status: $($statusResponse.status) - Partition $idx/$tot - Retry in 35-60s" -ForegroundColor Magenta
							# Randomized polling interval (35-60s) to prevent synchronization
							$waitSeconds = Get-Random -Minimum 35 -Maximum 60
							Start-Sleep -Seconds $waitSeconds
						}
					}
					# PAX-1E: remember the sleep we intended this iteration so the next iteration's
					# host-gap check can distinguish host suspension from a legitimately long poll.
					$obsLastIntendedSleep = [double]$waitSeconds
				}
							
							# Step 3: Retrieve records with pagination
							$recordsUri = Get-AuditUri -path "queries/$queryId/records"
							$fetchNetworkErrorStart = $null
							$unexpectedProcessingError = $false
							$unexpectedProcessingMessage = $null
							$fetchErrorRetryCount = 0
							$maxFetchErrorRetries = 3  # Retry unexpected errors 3 times before giving up
							
							# CRITICAL: When resultSize=0, fetch unlimited records (don't check count)
							# When resultSize>0, stop when we reach the limit (EOM mode behavior)
							$pageFlushTotalCount = 0
							$pageFlushFilePath = $null
							while ($recordsUri -and ($resultSize -eq 0 -or ($pageFlushTotalCount + $allRecords.Count) -lt $resultSize)) {
								# Retry loop for record fetching with 429 and network error handling
								$fetchRetries = 0
								$maxFetchRetries = 5
								$fetchSuccess = $false
								
								while ($fetchRetries -lt $maxFetchRetries -and -not $fetchSuccess) {
									try {
										$recordsResponse = Invoke-RestMethod -Method GET -Uri $recordsUri -Headers (Get-CurrentHeaders -ClientRequestId $clientRequestId) -ErrorAction Stop
										$fetchSuccess = $true
										# Reset network error tracking on success
										if ($fetchNetworkErrorStart) {
											$outageSeconds = [Math]::Round(((Get-Date) - $fetchNetworkErrorStart).TotalSeconds, 1)
											Write-Output "[NETWORK] Partition $idx/$tot Page $($telemetry.PageCount + 1) - Recovered after network error (${outageSeconds}s outage)"
										}
										$fetchNetworkErrorStart = $null
									}
									catch {
										# Check for 429 throttling
										$is429Fetch = $false
										if ($_.Exception.Response) {
											$statusCode = $_.Exception.Response.StatusCode
											if ($statusCode -eq 429 -or $statusCode -eq 'TooManyRequests' -or $statusCode.value__ -eq 429) {
												$is429Fetch = $true
											}
										}
										if (-not $is429Fetch -and ($_.Exception.Message -match '429' -or $_.Exception.Message -match 'Too Many Requests')) {
											$is429Fetch = $true
										}
										
										# Check for network errors (502, 503, 504, connection issues)
										$isNetworkFetch = $false
										$fetchErrorMessage = $_.Exception.Message
										$fetchErrorSummary = "Unknown error"
										
										if ($_.Exception.Response) {
											$statusCode = $_.Exception.Response.StatusCode.value__
											if ($statusCode -ge 500) {
												$isNetworkFetch = $true
												$fetchErrorSummary = "$statusCode Server Error"
											}
										}
										if (-not $isNetworkFetch -and ($fetchErrorMessage -match '5\d{2}|Bad Gateway|Service Unavailable|Gateway Timeout|Internal Server Error')) {
											$isNetworkFetch = $true
											$fetchErrorSummary = "Server error (from message)"
										}
										if (-not $isNetworkFetch -and ($fetchErrorMessage -match 'timed out|connection|unable to connect|could not be resolved')) {
											$isNetworkFetch = $true
											$fetchErrorSummary = "Network connectivity issue"
										}
										
										# Check for 403 Forbidden (Microsoft service-side issue)
										$is403Fetch = $false
										if (-not $is429Fetch -and -not $isNetworkFetch) {
											if ($_.Exception.Response) {
												$statusCode = $_.Exception.Response.StatusCode
												if ($statusCode -eq 403 -or $statusCode -eq 'Forbidden' -or $statusCode.value__ -eq 403) {
													$is403Fetch = $true
												}
											}
											if (-not $is403Fetch -and ($fetchErrorMessage -match '403' -or $fetchErrorMessage -match 'Forbidden')) {
												$is403Fetch = $true
											}
										}
										
										if ($is403Fetch) {
											# Extract diagnostic info from 403 response
											$responseBody403Fetch = $null
											$requestId403Fetch = $null
											$wwwAuth403Fetch = $null
											$isPermanent403Fetch = $false
											$exceptionMessage403Fetch = $_.Exception.Message
											
											# PowerShell 7 error handling: ErrorDetails.Message contains response body
											try {
												if ($_.ErrorDetails -and $_.ErrorDetails.Message) {
													$responseBody403Fetch = $_.ErrorDetails.Message
												}
											} catch {}
											
											# Try to get headers from the response
											try {
												if ($_.Exception.Response) {
													# Try different header access patterns for PS7 compatibility
													try {
														$requestId403Fetch = $_.Exception.Response.Headers['request-id']
													} catch {
														try {
															$requestId403Fetch = $_.Exception.Response.Headers.GetValues('request-id') | Select-Object -First 1
														} catch {}
													}
													try {
														$wwwAuth403Fetch = $_.Exception.Response.Headers['WWW-Authenticate']
													} catch {
														try {
															$wwwAuth403Fetch = $_.Exception.Response.Headers.GetValues('WWW-Authenticate') | Select-Object -First 1
														} catch {}
													}
													
													# Fallback: try to read response stream if ErrorDetails was empty
													if (-not $responseBody403Fetch) {
														try {
															$respStream = $_.Exception.Response.GetResponseStream()
															if ($respStream -and $respStream.CanRead) {
																$reader = New-Object System.IO.StreamReader($respStream)
																$responseBody403Fetch = $reader.ReadToEnd()
																$reader.Dispose()
															}
														} catch {}
													}
												}
											} catch {}
											
											# Check if permanent 403
											if ($responseBody403Fetch -match 'InsufficientPrivileges|Authorization_RequestDenied|AccessDenied|InvalidAuthenticationToken') {
												$isPermanent403Fetch = $true
											}
											if ($wwwAuth403Fetch -match 'claims') {
												$isPermanent403Fetch = $true
											}
											
											# Log diagnostic info
											try {
												$diagLog = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [403-FETCH-DIAG] Partition $idx/$tot Page $($telemetry.PageCount + 1)`n"
												$diagLog += "  client-request-id: $clientRequestId`n"
												$diagLog += "  request-id: $requestId403Fetch`n"
												$diagLog += "  exception: $exceptionMessage403Fetch`n"
												if ($wwwAuth403Fetch) { $diagLog += "  WWW-Authenticate: $wwwAuth403Fetch`n" }
												if ($responseBody403Fetch) { $diagLog += "  Response body: $responseBody403Fetch`n" }
												$diagLog += "  Permanent error: $isPermanent403Fetch"
												$diagLog | Add-Content -Path $logPath -Encoding UTF8 -ErrorAction SilentlyContinue
											} catch {}
											
											if ($isPermanent403Fetch) {
																	Write-Output "[403-PERM] Partition $idx/$tot - PERMANENT 403 on FETCH - Failing partition | request-id: $requestId403Fetch | client-request-id: $clientRequestId"
											}
											
											# 403 Forbidden during FETCH - wait for main thread to refresh token first
											$tokenRefreshed = Wait-ForTokenRefresh
											if ($tokenRefreshed) {
												# Token was refreshed - reset counter and retry immediately with fresh token
												$fetchRetries = 0
												Write-Output "[403-FETCH] Partition $idx/$tot - Token refreshed, resetting retry counter and resuming fetch"
												continue  # Retry this fetch with new token
											}
											
											# Token refresh failed/timed out - fall through to limited retry logic
											$fetchRetries++
											$max403FetchRetries = 3
											
											if ($fetchRetries -le $max403FetchRetries) {
												# Exponential backoff: 15s, 30s, 60s
												$retryAfter = [Math]::Min(15 * [Math]::Pow(2, $fetchRetries - 1), 60)
												
												# Thread-safe file logging
												try {
													$logMsg = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [403-FETCH] Partition $idx/$tot Page $($telemetry.PageCount + 1) - Transient 403 (Attempt $fetchRetries/$max403FetchRetries) - Retrying in ${retryAfter}s"
													$logMsg | Add-Content -Path $logPath -Encoding UTF8 -ErrorAction SilentlyContinue
												} catch {}
												
												Write-Output "[403-FETCH] Partition $idx/$tot Page $($telemetry.PageCount + 1) - Transient 403 (Attempt $fetchRetries/$max403FetchRetries) - Retrying in ${retryAfter}s | request-id: $requestId403Fetch | client-request-id: $clientRequestId"
												Start-Sleep -Seconds $retryAfter
											} else {
												# Max 403 retries exceeded - throw to trigger partition-level retry
												try {
													$logMsg = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [403-FETCH] Partition $idx/$tot - Max transient 403 fetch retries exceeded ($max403FetchRetries), failing partition for retry with fresh token"
													$logMsg | Add-Content -Path $logPath -Encoding UTF8 -ErrorAction SilentlyContinue
												} catch {}
												
												Write-Output "[403-MAX] Partition $idx/$tot - Max transient 403 fetch retries exceeded - Failing partition | request-id: $requestId403Fetch | client-request-id: $clientRequestId"
												throw "403 Forbidden (transient) on fetch - max retries exceeded (partition will retry with fresh token)"
											}
										}
										elseif ($is429Fetch) {
											$fetchRetries++
											$telemetry.ThrottledCount++
											# Respect Retry-After header if present, otherwise use 60s default
											$retryAfter = 60
											if ($_.Exception.Response.Headers -and $_.Exception.Response.Headers['Retry-After']) {
												$retryAfter = [int]$_.Exception.Response.Headers['Retry-After']
											}
											$telemetry.RetryAfterTotalSeconds += $retryAfter
											
											# Log throttling event to user
											Write-Host "[!]  API Rate Limit (429) during record fetch - Partition $idx/$tot Page $($telemetry.PageCount + 1) - Retry in $retryAfter seconds (Attempt $fetchRetries/$maxFetchRetries)" -ForegroundColor Yellow
											
											Start-Sleep -Seconds $retryAfter
										}
										elseif ($isNetworkFetch) {
											# Network error - check if we're still within the outage tolerance window
											if (-not $fetchNetworkErrorStart) {
												$fetchNetworkErrorStart = Get-Date
								# Log to file only (no terminal spam)
								Write-Output "[NETWORK] Partition $idx/$tot Page $($telemetry.PageCount + 1) - $fetchErrorSummary - Starting retry window (max ${maxOutageMinutes}m)"
							}
										
										# Calculate elapsed outage time
										$fetchElapsedOutageSeconds = ((Get-Date) - $fetchNetworkErrorStart).TotalSeconds
										
										if ($fetchElapsedOutageSeconds -lt $maxNetworkOutageSeconds) {
											$fetchRemainingMinutes = [Math]::Ceiling(($maxNetworkOutageSeconds - $fetchElapsedOutageSeconds) / 60)
											$fetchRetryDelay = 30 + (Get-Random -Minimum 10 -Maximum 30)  # 30-60s random delay
											
											# Suppress subsequent retry messages to terminal (first error already shown)
											# Log to file for troubleshooting
											$fetchElapsedFormatted = [Math]::Round($fetchElapsedOutageSeconds, 1)
											Write-Output "[NETWORK] Retry attempt for partition $idx/$tot Page $($telemetry.PageCount + 1) (${fetchElapsedFormatted}s elapsed) : $fetchErrorSummary"
												
												Start-Sleep -Seconds $fetchRetryDelay
											}
											else {
												# Network outage exceeded tolerance
												$fetchOutageMinutes = [Math]::Round($fetchElapsedOutageSeconds / 60, 1)
												Write-Host "[ERROR] Partition $idx/$tot - Record fetch failed: Network outage exceeded $maxOutageMinutes minute tolerance (${fetchOutageMinutes}m elapsed)" -ForegroundColor Red
												throw "Network outage exceeded $maxOutageMinutes minute tolerance during record fetch"
											}
										}
										else {
											throw  # Re-throw non-throttling, non-network errors
										}
									}
								}
								
								if (-not $fetchSuccess) {
									throw "Failed to fetch records after $maxFetchRetries throttle retries"
								}
								
								# Track page retrieval
								$telemetry.PageCount++
								# Emit page count heartbeat on page 1 and every 200 pages so main thread can display progress in STATUS line
								if ($telemetry.PageCount -eq 1 -or $telemetry.PageCount % 200 -eq 0) {
									Write-Output "[PROGRESS] P${idx}/$tot pg$($telemetry.PageCount)"
								}
								if ($telemetry.PageCount -eq 1) {
									$telemetry.FirstPageAt = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
								}
								$telemetry.LastPageAt = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
								
								if ($recordsResponse.value) {
												foreach ($record in $recordsResponse.value) {
											# Normalize to EOM-compatible format inline
											# PERF: Store _ParsedAuditData to avoid re-parsing JSON during explosion
											# NOTE: Using InvariantCulture directly here since Parse-DateSafe isn't available in ThreadJob scope
											# TIMEZONE: Graph API returns createdDateTime as ISO-8601 UTC (e.g., "2026-02-10T21:00:17Z").
											# Use AssumeUniversal | AdjustToUniversal so the resulting DateTime has Kind=Utc; this
											# guarantees ConvertTo-Json emits the Z suffix on JSONL flush, which downstream merge code
											# (Parse-DateSafe + .ToUniversalTime()) needs to avoid silently re-interpreting the
											# value as local time and trimming records out of range in non-UTC time zones.
											$normalized = [PSCustomObject]@{
												RecordType = $record.auditLogRecordType
												CreationDate = if ($record.createdDateTime) { try { [datetime]::Parse($record.createdDateTime, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal) } catch { $null } } else { $null }
												UserIds = $record.userPrincipalName
												Operations = $record.operation
												AuditData = if ($record.auditData) { $record.auditData | ConvertTo-Json -Depth 100 -Compress } else { '{}' }
												_ParsedAuditData = $record.auditData  # Already-parsed object from Graph API
												ResultIndex = $pageFlushTotalCount + $allRecords.Count + 1
												ResultCount = 1
												Identity = $record.id
												IsValid = $true
												ObjectState = 'Unchanged'
											}													# Apply UserIds filter if specified
													$includeRecord = $true
													if ($userIds -and $userIds.Count -gt 0) {
														$includeRecord = $userIds -contains $normalized.UserIds
													}
													
													if ($includeRecord) {
														[void]$allRecords.Add($normalized)
													}
													
													# Only break if resultSize > 0 and we've reached the limit
													if ($resultSize -gt 0 -and ($pageFlushTotalCount + $allRecords.Count) -ge $resultSize) {
														break
													}
												}
											}
											
											# Check for next page
											$recordsUri = if ($recordsResponse.'@odata.nextLink') { $recordsResponse.'@odata.nextLink' } else { $null }
											
											# PER-PAGE MEMORY FLUSH: Append current page to disk and clear in-memory batch
											if ($memoryFlushEnabled -and $allRecords.Count -gt 0) {
												try {
													if (-not (Test-Path $incrementalDir)) { New-Item -ItemType Directory -Path $incrementalDir -Force | Out-Null }
													if (-not $pageFlushFilePath) {
														$pageFlushFilePath = Join-Path $incrementalDir "Part${idx}_${runTimestamp}_qid-${queryId}_${jobRunId}.jsonl"
													}
													$allRecords | ForEach-Object { $_ | ConvertTo-Json -Depth 10 -Compress } | Add-Content -Path $pageFlushFilePath -Encoding utf8
													$pageFlushTotalCount += $allRecords.Count
													$allRecords.Clear()
													$threadSavedToDisk = $true
												} catch {
													# Fail closed: keeping the page in memory would defeat the memory
													# budget and grow the in-memory buffer without bound. Terminate this
													# partition truthfully; already-flushed pages remain on disk and the
													# run finishes as a terminal failure (nonzero) without continuing to
													# collect the result set in memory.
													Write-Output "[FLUSH-FAIL] Partition $idx/$tot - Page flush failed: $($_.Exception.Message). Failing closed (no in-memory fallback)."
													throw [System.Exception]::new("Bounded page flush failed for partition $idx/$tot ($($_.Exception.Message))")
												}
											}
											
											# ROLLING PERSISTENCE SAFETY NET: Write backup snapshot every 500 pages
											# This is write-only — $allRecords is NOT cleared. Normal flow is unchanged.
											# If the process crashes mid-pagination, these files exist for manual recovery.
											if (-not $memoryFlushEnabled -and $incrementalDir -and $allRecords.Count -gt 0 -and $telemetry.PageCount -gt 0 -and $telemetry.PageCount % 500 -eq 0) {
												try {
													if (-not (Test-Path $incrementalDir)) { New-Item -ItemType Directory -Path $incrementalDir -Force | Out-Null }
													$snapshotFile = Join-Path $incrementalDir "Part${idx}_${runTimestamp}_snapshot_page$($telemetry.PageCount)_$($allRecords.Count)records.jsonl"
													$allRecords | ForEach-Object { $_ | ConvertTo-Json -Depth 10 -Compress } | Out-File -FilePath $snapshotFile -Encoding utf8 -Force
													Write-Output "[SNAPSHOT] Partition $idx/$tot - Safety snapshot at page $($telemetry.PageCount): $($allRecords.Count) records written to disk"
												} catch {
													Write-Output "[SNAPSHOT-WARN] Partition $idx/$tot - Failed to write safety snapshot: $($_.Exception.Message)"
												}
											}
										}
								}
								catch {
									# Check if this is a CREATE-FAILED error bubbling up (not a fetch error)
									$errorMsg = $_.Exception.Message
									if ($errorMsg -match '^\[CREATE-FAILED\]') {
										# Re-throw CREATE errors as-is - they should propagate out of the scriptblock
										throw
									}
									
									# This catch is for unexpected errors during FETCH phase (not throttling or network errors, which are handled above)
									# Examples: JSON parsing failures, unexpected response format, etc.
									$unexpectedError = $errorMsg
									$unexpectedStack = $_.ScriptStackTrace
									
									# Increment retry counter and check if retries remain
									$fetchErrorRetryCount++
									
									if ($fetchErrorRetryCount -lt $maxFetchErrorRetries) {
										# 401/Unauthorized: Wait for main thread token refresh before retrying (same pattern as 403 handler)
										if ($unexpectedError -match '401|Unauthorized') {
											$tokenRefreshed = Wait-ForTokenRefresh
											if ($tokenRefreshed) {
												$fetchErrorRetryCount = 0  # Reset retries — fresh token deserves fresh attempts
												Write-Output "[FETCH-RETRY] Partition $idx/$tot - 401 detected, token refreshed, resetting retry counter"
												continue  # Retry immediately with fresh token
											}
										}
										
										# Retries remain - log and retry the same page
										Write-Output "[FETCH-RETRY] Partition $idx/$tot - Unexpected error ($fetchErrorRetryCount/$maxFetchErrorRetries) - Retrying in 30s: $unexpectedError"
										try {
											$logMsg = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [FETCH-RETRY] Partition $idx/$tot (Query $queryId) - Retry $fetchErrorRetryCount/$maxFetchErrorRetries for: $unexpectedError"
											$logMsg | Add-Content -Path $using:LogFile -Encoding UTF8 -ErrorAction SilentlyContinue
										} catch {}
										Start-Sleep -Seconds 30
										continue  # Retry pagination loop with same $recordsUri
									}
									
									# All retries exhausted - fail the partition
									$unexpectedProcessingError = $true
									$unexpectedProcessingMessage = $unexpectedError
					
									# Output error message (will be deduplicated by parent)
									Write-Output "[ERROR] Partition $idx/$tot - Unexpected error during record processing after $fetchErrorRetryCount retries - will retry at end of run"
					
									# Full error details to ERROR stream (will be captured by main thread)
									Write-Error "[ERROR] Partition $idx/$tot (Query $queryId) - Unexpected record processing error: $unexpectedError`n  Stack: $unexpectedStack" -ErrorAction Continue
												# Thread-safe file logging
												try {
													$logMsg = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [ERROR] Partition $idx/$tot (Query $queryId) - Unexpected record processing error after $fetchErrorRetryCount retries: $unexpectedError"
													$logMsg | Add-Content -Path $using:LogFile -Encoding UTF8 -ErrorAction SilentlyContinue
													"  Stack trace: $unexpectedStack" | Add-Content -Path $using:LogFile -Encoding UTF8 -ErrorAction SilentlyContinue
												} catch {
													# Ignore logging errors in job
												}
					
									# Break pagination loop - retries exhausted
									break
								}
																	$t1 = Get-Date
									
									# Finalize telemetry
								$telemetry.RowCount = $pageFlushTotalCount + $allRecords.Count
									
									# POST-FETCH 10K LIMIT DETECTION: Only applies to EOM mode (resultSize > 0)
											if ($resultSize -gt 0 -and ($pageFlushTotalCount + $allRecords.Count) -eq 10000) {
												$partitionHours = ($pEnd - $pStart).TotalHours
												$minSubdivisionDays = 0.001389  # 2 minutes
												$minSubdivisionHours = $minSubdivisionDays * 24
												
												if ($partitionHours -gt $minSubdivisionHours) {
													# Partition can be subdivided - flag for subdivision
													$telemetry.PostFetch10KLimit = $true
													$telemetry.SubdivisionReason = "postfetch_10k_limit"
													$script:Hit10KLimit = $true
													
													Write-Host "[SUBDIVISION] Partition $idx/$tot - Fetched exactly 10,000 records (EOM limit reached) - Needs subdivision ($([Math]::Round($partitionHours,2))h window)" -ForegroundColor Yellow
													
													# Return subdivision signal
													return [PSCustomObject]@{
														QueryId = $queryId
														Status = 'needs_subdivision'
														PreviewCount = 10000
														PartitionStart = $pStart
														PartitionEnd = $pEnd
														PartitionIndex = $idx
														PartitionTotal = $tot
														RetrievedCount = 10000
														Telemetry = $telemetry
													}
												} else {
													Write-Host "[LIMIT] Partition $idx/$tot - Fetched 10,000 records at minimum subdivision window ($([Math]::Round($partitionHours,2))h, cannot subdivide further)" -ForegroundColor Yellow
													$script:Hit10KLimit = $true
												}
											}
											# POST-FETCH 1M LIMIT DETECTION: Graph API has 1,000,000 record limit per query
											elseif ($resultSize -eq 0 -and ($pageFlushTotalCount + $allRecords.Count) -ge 1000000) {
												$partitionHours = ($pEnd - $pStart).TotalHours
												$minSubdivisionDays = 0.001389  # 2 minutes
												$minSubdivisionHours = $minSubdivisionDays * 24
												
												if ($partitionHours -gt $minSubdivisionHours) {
													# Partition can be subdivided - flag for subdivision
													$telemetry.PostFetch1MLimit = $true
													$telemetry.SubdivisionReason = "postfetch_1m_limit"
													$script:Hit1MLimit = $true
													
													Write-Host "[SUBDIVISION] Partition $idx/$tot - Fetched 1,000,000 records (Graph API limit reached) - Needs subdivision ($([Math]::Round($partitionHours,2))h window)" -ForegroundColor Yellow
													
													# Return subdivision signal
													return [PSCustomObject]@{
														QueryId = $queryId
														Status = 'needs_subdivision'
														PreviewCount = 1000000
														PartitionStart = $pStart
														PartitionEnd = $pEnd
														PartitionIndex = $idx
														PartitionTotal = $tot
														RetrievedCount = 1000000
														Telemetry = $telemetry
													}
												} else {
													Write-Host "[LIMIT] Partition $idx/$tot - Fetched 1,000,000 records at minimum subdivision window ($([Math]::Round($partitionHours,2))h, cannot subdivide further)" -ForegroundColor Yellow
													$script:Hit1MLimit = $true
												}
											}
				
								if ($unexpectedProcessingError) {
									$telemetry.Status = 'failed'
									# Clean up Purview query to free server slot after all fetch retries exhausted
									if ($queryId) {
										try {
											Invoke-RestMethod -Method DELETE -Uri (Get-AuditUri -path "queries/$queryId") `
												-Headers (Get-CurrentHeaders -ClientRequestId $clientRequestId) -ErrorAction SilentlyContinue | Out-Null
											Write-Output "[CLEANUP] Partition $idx/$tot - Deleted query $queryId after $fetchErrorRetryCount failed fetch retries"
										} catch {
											# Silently continue - cleanup failure shouldn't block retry
										}
									}
									throw [System.Exception]::new("Unexpected record processing error: $unexpectedProcessingMessage")
								}

								# Thread-side final persistence (memory-flush mode): write final partition JSONL before returning
								if ($memoryFlushEnabled -and $incrementalDir -and $allRecords.Count -gt 0) {
									try {
										if (-not (Test-Path $incrementalDir)) {
											New-Item -ItemType Directory -Path $incrementalDir -Force | Out-Null
										}
										$threadSavedFile = Join-Path $incrementalDir "Part${idx}_${runTimestamp}_qid-${queryId}_$($allRecords.Count)records.jsonl"
										$allRecords | ForEach-Object { $_ | ConvertTo-Json -Depth 10 -Compress } | Out-File -FilePath $threadSavedFile -Encoding utf8 -Force
										$threadSavedToDisk = $true
										Write-Output "[SAVE-THREAD] Partition $($idx)/$($tot): $($allRecords.Count) records persisted by thread job"
									} catch {
										# Fail closed (bounded memory-flush mode): a persistence failure must NOT
										# fall through to returning the full record set in memory below (that would
										# reintroduce the unbounded in-memory buffer and violate the memory budget).
										# Terminate this partition truthfully; already-completed incremental files and
										# checkpoint state are preserved on disk, and the run finishes as a terminal
										# failure (nonzero) without certifying completeness or continuing collection.
										Write-Output "[SAVE-THREAD-FAIL] Partition $($idx)/$($tot): bounded persistence failed: $($_.Exception.Message). Failing closed (no in-memory fallback)."
										throw [System.Exception]::new("Bounded memory-flush persistence failed for partition $($idx)/$($tot): $($_.Exception.Message)")
									}
								} elseif ($memoryFlushEnabled -and $pageFlushFilePath) {
									# All records were already flushed per-page; just ensure thread-saved references are set
									$threadSavedToDisk = $true
									$threadSavedFile = $pageFlushFilePath
								}

								# Emit success notification for outer monitor (display handled once outside the job)
								Write-Output "[SUCCESS] Query succeeded - Partition $idx/$tot - Query ID: $queryId - Retrieved $($pageFlushTotalCount + $allRecords.Count) records"
									
									# Clean up query after successful record retrieval (best-effort)
									if ($queryId) {
										try {
											Invoke-RestMethod -Method DELETE -Uri (Get-AuditUri -path "queries/$queryId") `
												-Headers (Get-CurrentHeaders -ClientRequestId $clientRequestId) -ErrorAction SilentlyContinue | Out-Null
										} catch {
											# Silently continue - cleanup failure shouldn't block results
										}
									}
									
								# Return results with telemetry
								$returnLogs = if ($memoryFlushEnabled -and $threadSavedToDisk) { @() } else { $allRecords }
								[pscustomobject]@{
									Activity = $activity
									Logs = $returnLogs
									RetrievedCount = $pageFlushTotalCount + $allRecords.Count
									ElapsedMs = [int]($t1 - $t0).TotalMilliseconds
									Partition = $idx
									Total = $tot
									QueryId = $queryId
									DebugInfo = $debugInfo
									Telemetry = $telemetry
									ThreadSavedToDisk = $threadSavedToDisk
									ThreadSavedFile = $threadSavedFile
								}
						}
		}
		# Skip parallel execution machinery when sequential mode is active
		# The sequential fallback (if -not $canParallel) handles processing below
		if (-not $canParallel) {
			# Skip to sequential fallback - set flag to bypass the while loop
			$allPartitionsProcessed = $true
		}
		
		# Diagnostic: Show concurrency settings before creating jobs (only for parallel mode)
		if ($canParallel) {
			$diagMsg = "[CONCURRENCY] Partitions=$($partitions.Count) MaxConcurrency=$MaxConcurrency"
			Write-LogHost $diagMsg -ForegroundColor Cyan
		}
		
		# Initialize job result tracking
		$script:processedJobIds = New-Object System.Collections.Generic.HashSet[int]
		
		# Pre-compute incremental directory and timestamp for ThreadJob rolling persistence safety net
		$threadIncrementalDir = if ($script:PartialOutputPath) { Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental" } else { $null }
		$threadRunTimestamp = $global:ScriptRunTimestamp
		$threadMemoryFlushEnabled = [bool]$script:memoryFlushEnabled
		
		# Outer loop: Continue creating jobs until all partitions (including subdivided ones) are processed
		# This handles dynamic subdivision where new partitions are added during execution
		$subdivisionPass = 0
		if (-not $allPartitionsProcessed) { $allPartitionsProcessed = $false }
		
		while (-not $allPartitionsProcessed) {
			$subdivisionPass++
			
			# Find partitions that need jobs created (haven't been processed yet).
			# Include 'Failed' status to enable retry of failed partitions — for
			# Failed partitions, allow retry even if they're already tracked in
			# $script:partitionsWithJobs (their previous job failed). Partitions flagged
			# IsTerminalFailure (N consecutive same-category failures) are NOT re-queued —
			# this is what lets the loop finalize instead of re-dispatching forever.
			$pendingPartitions = @($partitions | Where-Object { 
				$statusObj = $script:partitionStatus[$_.Index]
				if (-not $statusObj) { return $false }
				# A durable-uncertain partition (unproven prior create, no query id) that a
				# same-process read-only reconcile already failed to resolve is HELD: never
				# re-POSTed and excluded here so the outer create loop can terminate, exactly
				# mirroring the IsTerminalFailure exclusion below.
				if ($statusObj.UncertainCreate -and -not $statusObj.QueryId -and $script:uncertainReconcileHeld.Contains($_.Index)) { return $false }
				if ($statusObj.Status -eq 'NotStarted' -and -not $script:partitionsWithJobs.Contains($_.Index)) { return $true }
				if ($statusObj.Status -eq 'Failed' -and -not $statusObj.IsTerminalFailure) { return $true }  # retry failed, but not terminally-failed
				return $false
			})
			
			if ($pendingPartitions.Count -eq 0) {
				# No new partitions to process, we're done
				$allPartitionsProcessed = $true
				break
			}
			
			if ($subdivisionPass -gt 1) {
				Write-LogHost "" -ForegroundColor Yellow
				Write-LogHost "=== Subdivision Pass $subdivisionPass ===" -ForegroundColor Yellow
				Write-LogHost "Processing $($pendingPartitions.Count) new sub-partitions from previous subdivisions..." -ForegroundColor Yellow
			}

			# --- Parent-side query creation pre-pass (bounded parallel) ---
			# Create the audit query for every pending partition that has no query id
			# yet, BEFORE any worker is launched, reusing the launch concurrency bound
			# ($maxConcurrentPartitions). Creation runs in the main runspace where the
			# token can be refreshed. A partition that already carries a query id (its
			# status QueryId or StoredQueryId) skips creation and is wired to StoredQueryId
			# so the existing launch reads it. A successful creation is checkpointed
			# QueryCreated before launch; a failed creation is recorded so no worker is
			# launched for it this pass.
			$createFailedThisPass = [System.Collections.Generic.HashSet[int]]::new()
			$needCreate = New-Object System.Collections.Generic.List[object]
			$needReconcile = New-Object System.Collections.Generic.List[object]
			foreach ($cp in $pendingPartitions) {
				$existingId = $null
				if ($script:partitionStatus.ContainsKey($cp.Index) -and $script:partitionStatus[$cp.Index].QueryId) { $existingId = [string]$script:partitionStatus[$cp.Index].QueryId }
				elseif ($cp.StoredQueryId) { $existingId = [string]$cp.StoredQueryId }
				if ($existingId) {
					$cp | Add-Member -NotePropertyName 'StoredQueryId' -NotePropertyValue $existingId -Force
				} elseif ($script:partitionStatus.ContainsKey($cp.Index) -and $script:partitionStatus[$cp.Index].UncertainCreate) {
					# A partition that became durable-uncertain in an earlier pass of THIS run has
					# an unproven prior create and no query id. It must NEVER be re-POSTed as a
					# fresh create; route it away from the create list to a same-process READ-ONLY
					# reconcile instead (exact fingerprinted name, never a POST).
					[void]$needReconcile.Add($cp)
				} else {
					[void]$needCreate.Add($cp)
				}
			}
			# Same-process READ-ONLY reconcile of durable-uncertain partitions (never a POST):
			# exactly one exact-name match is adopted + checkpointed QueryCreated (uncertain
			# vacated) and wired to launch this pass; multiple (fail closed) or none
			# (unresolved) are held - not launched, recorded create-failed this pass, and added
			# to the run-scoped held set so the pending selector excludes them and the outer
			# loop can terminate. A collection miss never sets QueryConfirmedAbsent.
			if ($needReconcile.Count -gt 0) {
				Write-LogHost "  [PARENT-RECONCILE] $($needReconcile.Count) partition(s) have an unproven prior create - reconciling READ-ONLY in-process (no POST)..." -ForegroundColor Yellow
				$inlineReconcile = Invoke-PaxResumeUncertainReconcile -Partitions $needReconcile.ToArray() -Activities $activities -Log { param($m) Write-Log $m }
				foreach ($adopted in @($inlineReconcile.AdoptedFetchOnly)) {
					# Adopted: reconcile stored a proven real QueryId on the partition object and
					# checkpointed it QueryCreated (uncertain vacated). Mirror it into the live
					# status so the launch below reads a real query id and fetches data only.
					$script:partitionStatus[$adopted.Index].QueryId = [string]$adopted.StoredQueryId
					$script:partitionStatus[$adopted.Index].UncertainCreate = $false
					Write-LogHost "  [PARENT-RECONCILE] Partition $($adopted.Index)/$($adopted.Total) adopted by exact name (no POST) - fetching data only" -ForegroundColor Green
				}
				foreach ($held in (@($inlineReconcile.Unresolved) + @($inlineReconcile.FailedClosed))) {
					# Held: no proven create. Never re-POSTed, no worker launched this pass, and
					# added to the run-scoped held set so the pending selector excludes it and the
					# outer create loop terminates instead of re-dispatching forever.
					[void]$createFailedThisPass.Add([int]$held.Index)
					[void]$script:uncertainReconcileHeld.Add([int]$held.Index)
				}
				$heldInline = @($inlineReconcile.Unresolved).Count + @($inlineReconcile.FailedClosed).Count
				if ($heldInline -gt 0) {
					Write-LogHost "  [PARENT-RECONCILE] $heldInline partition(s) remain uncertain (no proven create) - held, not launched; re-run with -ClearUncertainCreate <partition index> to force a fresh create for a specific partition" -ForegroundColor Yellow
				}
			}
			if ($needCreate.Count -gt 0) {
				$createBound = [Math]::Max(1, [int]$maxConcurrentPartitions)
				Write-LogHost "  [PARENT-CREATE] Creating $($needCreate.Count) partition query(ies) in bounded parallel (limit $createBound)..." -ForegroundColor DarkCyan
				# Refresh the token before the create pre-pass so every queued and retrying
				# create job reads a current token from the shared auth state.
				$createRefresh = Refresh-GraphTokenIfNeeded -BufferMinutes 5
				if ($createRefresh -is [string] -and $createRefresh -eq 'Quit') {
					if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
					Show-CheckpointExitMessage
					exit 0
				}
				$createMap = Invoke-PaxParentQueryCreation -Partitions $needCreate.ToArray() -ThrottleLimit $createBound -Activities $activities -MaxNetworkOutageMinutes $MaxNetworkOutageMinutes
				# A token quit or refresh error during creation fails the pass closed before any
				# partition is persisted: enter the graceful authentication-exit path so nothing
				# is recorded as created off a quit/error decision (resume re-runs the pre-create
				# reconcile, which adopts an already-created query without a duplicate POST).
				if ($createMap['__AuthQuit']) {
					# Persist any query the pool actually created before the quit AND mark the
					# still-in-flight partitions durable-uncertain, so a known QueryId is never
					# discarded and a possibly-accepted in-flight POST is reconciled read-only on
					# resume. A user-driven quit stays a graceful (exit 0) checkpoint-and-resume.
					Save-PaxInterruptedCreatePool -CreateMap $createMap -Requested $needCreate -Activities $activities -Phase 'initial'
					Write-LogHost "  [PARENT-CREATE] Authentication quit requested during query creation - completed persisted, in-flight marked uncertain, saving checkpoint and exiting (use -Resume to continue)" -ForegroundColor Yellow
					if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
					Show-CheckpointExitMessage
					exit 0
				}
				if ($createMap['__RefresherError']) {
					# Same durable persistence as the quit path, but a token-refresh EXCEPTION is a
					# failure, not a user decision: after persisting completed + in-flight-uncertain
					# it terminates NONZERO through the established fatal-exit machinery
					# ($script:GenericFatal -> exit 1) so automation sees the run did not succeed.
					Save-PaxInterruptedCreatePool -CreateMap $createMap -Requested $needCreate -Activities $activities -Phase 'initial'
					Write-LogHost "  [PARENT-CREATE] Token refresh error during query creation ($($createMap['__RefresherError'])) - completed persisted, in-flight marked uncertain, saving checkpoint and exiting NONZERO (use -Resume to continue)" -ForegroundColor Red
					$script:GenericFatal = $true
					if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
					Show-CheckpointExitMessage
					exit 1
				}
				foreach ($cp in $needCreate) {
					$cr = $createMap[[int]$cp.Index]
					if ($cr -and $cr.QueryId) {
						$cp | Add-Member -NotePropertyName 'StoredQueryId' -NotePropertyValue ([string]$cr.QueryId) -Force
						$script:partitionStatus[$cp.Index].QueryId = [string]$cr.QueryId
						$script:partitionStatus[$cp.Index].QueryApiVersion = $cr.Version
						$script:partitionStatus[$cp.Index].LifecycleOperation = 'Create'
						if ($script:CheckpointEnabled) {
							Save-Checkpoint -PartitionIndex $cp.Index -QueryId ([string]$cr.QueryId) -State 'QueryCreated' -LifecycleState $script:partitionStatus[$cp.Index]
						}
						Write-LogHost "  [PARENT-CREATE] Partition $($cp.Index)/$($cp.Total) query created (QueryId: $($cr.QueryId))" -ForegroundColor DarkCyan
					} else {
						$cat = if ($cr) { [string]$cr.FailureCategory } else { 'NotCreated' }
						[void]$createFailedThisPass.Add([int]$cp.Index)
						if ($cat -eq 'UncertainCreateUnresolved') {
							# A first POST whose acceptance could not be proven (collection miss / 5xx
							# that cannot prove rejection) is NEVER re-POSTed. Persist durable
							# uncertain-create state so a resume routes this partition to a READ-ONLY
							# reconcile (adopt one exact match, fail closed on many, stay uncertain on
							# none) instead of a duplicate create. Deliberately NOT Set-PartitionFailure:
							# the partition is not marked Failed and is never requeued for a re-create.
							$script:partitionStatus[$cp.Index].UncertainCreate = $true
							$script:partitionStatus[$cp.Index].UncertainCreateInfo = @{
								displayName = New-GraphAuditPartitionDisplayName -PStart $cp.PStart -PEnd $cp.PEnd -Index $cp.Index -Total $cp.Total -Activities $activities -RecordTypes $cp.RecordTypes -ServiceFilter $cp.ServiceFilter
								fingerprint = New-GraphAuditQueryFingerprint -PStart $cp.PStart -PEnd $cp.PEnd -Activities $activities -RecordTypes $cp.RecordTypes -ServiceFilter $cp.ServiceFilter
								pStart      = $cp.PStart.ToString('o')
								pEnd        = $cp.PEnd.ToString('o')
								attempt     = [int]$script:partitionStatus[$cp.Index].AttemptNumber
								phase       = 'initial'
							}
							$script:partitionStatus[$cp.Index].LastError = "Parent-side query creation uncertain - durable reconcile pending (category: $cat)"
							if ($script:CheckpointEnabled) {
								Save-Checkpoint -PartitionIndex $cp.Index -State 'UncertainCreate' -LifecycleState $script:partitionStatus[$cp.Index]
							}
							Write-LogHost "  [PARENT-CREATE] Partition $($cp.Index)/$($cp.Total) create uncertain (category: $cat) - persisted for read-only reconcile, no re-POST, worker not launched this pass" -ForegroundColor Yellow
						} else {
							Set-PartitionFailure -Index $cp.Index -Stage 'CREATE' -Reason $cat
							$script:partitionStatus[$cp.Index].LastError = "Parent-side query creation failed (category: $cat)"
							$diag = "HTTP $($cr.HttpStatus) | client-request-id: $($cr.ClientRequestId) | request-id: $($cr.RequestId)"
							Write-LogHost "  [PARENT-CREATE] Partition $($cp.Index)/$($cp.Total) creation failed (category: $cat; $diag) - worker not launched this pass" -ForegroundColor Yellow
							if ($cr.ResponseBody) { Write-LogHost "    Graph response: $($cr.ResponseBody)" -ForegroundColor DarkYellow }
						}
					}
				}
			}

		# Create initial jobs for all PENDING partitions with backpressure
		foreach ($pt in $pendingPartitions) {
			# Skip launching a worker for any partition whose parent-side creation
			# failed this pass; it has no query id and is already marked Failed for
			# a future pass.
			if ($createFailedThisPass.Contains([int]$pt.Index)) { continue }
			# ============================================================
			# PROACTIVE TOKEN REFRESH: Check before each job creation
			# Job launch phase can take 20-35+ minutes with 60 partitions
			# Token may expire during this phase if not refreshed
			# ============================================================
			$refreshResult = Refresh-GraphTokenIfNeeded -BufferMinutes 5
			# CRITICAL: Use -is [string] check to avoid PowerShell coercion bug where $true -eq 'Quit' returns True
			if ($refreshResult -is [string] -and $refreshResult -eq 'Quit') {
				# User chose to quit at auth prompt - save checkpoint and exit gracefully
				if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
				Show-CheckpointExitMessage
				exit 0
			}
			
			# ============================================================
			# CHECKPOINT: Reactive token refresh for auth failures (401s)
			# This ALWAYS runs when AuthFailureDetected is true (not gated by CheckpointEnabled)
			# AppRegistration: automatic silent refresh (headless)
			# Interactive modes: user can wait at R/Q prompt indefinitely
			# ============================================================
			if (Test-ShouldPromptTokenRefresh) {
				# AppRegistration: Try automatic silent refresh first
				if ($script:AuthConfig.Method -eq 'AppRegistration' -and $script:AuthConfig.CanReauthenticate) {
					$refreshResult = Invoke-TokenRefresh -Force
					if ($refreshResult.Success -and $refreshResult.NewToken) {
						$script:AuthFailureDetected = $false
						$script:Auth401MessageShown = $false
						Write-LogHost "  [AUTH] Token refreshed automatically (AppRegistration)" -ForegroundColor Green
					} else {
						# AppRegistration is non-interactive by design - there is no R/Q prompt that
						# could supply alternate credentials. Save checkpoint and exit cleanly so the
						# run can be resumed once the cert/secret issue is fixed. Applies to both -Force
						# and non-Force runs.
						Write-LogHost "  [AUTH] FATAL: AppRegistration token refresh failed - exiting (use -Resume after fixing credentials)" -ForegroundColor Red
						if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
						Show-CheckpointExitMessage
						exit 0
					}
				} else {
					# Interactive modes: prompt user
					$refreshResult = Invoke-TokenRefreshPrompt
					if ($refreshResult -eq 'Quit') {
						# User chose to quit - save checkpoint if enabled and exit
						if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
						Show-CheckpointExitMessage
						exit 0
					}
				}
				# Proceed with fresh token
			}
			
			# Backpressure: Wait for a slot if we've reached MaxConcurrency
			# Count only non-completed jobs (Running or NotStarted)
			$activeJobs = @($jobs | Where-Object { $_.State -in 'Running','NotStarted' })
			while ($activeJobs.Count -ge $MaxConcurrency) {
				Write-Verbose "[BACKPRESSURE] Waiting for job slot (active: $($activeJobs.Count)/$MaxConcurrency)..." -Verbose:$VerbosePreference
				
				# PROACTIVE TOKEN REFRESH: Check while waiting for job slots
				$refreshResult = Refresh-GraphTokenIfNeeded -BufferMinutes 5
				# CRITICAL: Use -is [string] check to avoid PowerShell coercion bug where $true -eq 'Quit' returns True
				if ($refreshResult -is [string] -and $refreshResult -eq 'Quit') {
					# User chose to quit at auth prompt - save checkpoint and exit gracefully
					if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
					Show-CheckpointExitMessage
					exit 0
				}
				
				# Track when backpressure started (for server-side slot exhaustion detection)
				if (-not $script:backpressureStartTime) { $script:backpressureStartTime = Get-Date }
				
				# STATUS UPDATE: Show periodic status during backpressure wait
				if (-not $script:lastBackpressureStatus) { $script:lastBackpressureStatus = Get-Date }
				$backpressureElapsed = ((Get-Date) - $script:lastBackpressureStatus).TotalSeconds
				if ($backpressureElapsed -ge $StatusIntervalSeconds) {
					$completedCount = @($jobs | Where-Object { $_.State -eq 'Completed' }).Count
					$runningCount = @($jobs | Where-Object { $_.State -eq 'Running' }).Count
					# Count partitions that have actually sent queries (have QueryId)
					$sentToServerCount = @($script:partitionStatus.Values | Where-Object { $_.QueryId }).Count
					$ts = Get-Date -Format 'HH:mm:ss'
					Write-LogHost "[STATUS]  [$ts] Partitions (Queries): $runningCount active | $sentToServerCount sent | $($completedCount + $script:resumeCompletedOffset)/$totalPartitions complete" -ForegroundColor Yellow
					$script:lastBackpressureStatus = Get-Date
				}
				
				# SERVER-SIDE SLOT EXHAUSTION DETECTION: Check if we're stuck because Purview has existing queries
				# Only show once, after 3 minutes of backpressure, if SENT count < MaxConcurrency
				if (-not $script:serverSlotWarningShown) {
					$backpressureDuration = ((Get-Date) - $script:backpressureStartTime).TotalMinutes
					$sentToServerCount = @($script:partitionStatus.Values | Where-Object { $_.QueryId }).Count
					if ($backpressureDuration -ge 3 -and $sentToServerCount -lt $MaxConcurrency) {
						$missingSlots = $MaxConcurrency - $sentToServerCount
						$ts = Get-Date -Format 'HH:mm:ss'
						Write-LogHost "" -ForegroundColor Cyan
						Write-LogHost "[$ts] [INFO] Server-side query limit may be reached. Only $sentToServerCount of $MaxConcurrency queries sent to Purview after 3+ minutes." -ForegroundColor Cyan
						Write-LogHost "  This may indicate $missingSlots existing query/queries (from previous runs or the Purview portal) are consuming server slots." -ForegroundColor Cyan
						Write-LogHost "  Check Purview portal -> Audit -> search jobs for stuck/running queries." -ForegroundColor Cyan
						Write-LogHost "  You can cancel previous jobs if they aren't needed for anything else or for anyone else." -ForegroundColor Cyan
						Write-LogHost "" -ForegroundColor Cyan
						$script:serverSlotWarningShown = $true
					}
				}
				
				# REACTIVE AUTH CHECK: Handle 401 errors during backpressure wait
				# AppRegistration: automatic silent refresh (headless)
				# Interactive modes: prompt user for re-authentication
				if ($script:AuthFailureDetected) {
					Write-LogHost "" -ForegroundColor Red
					Write-LogHost "  [AUTH] 401 detected during job launch - initiating token refresh..." -ForegroundColor Red
					
					# AppRegistration: Use automatic silent refresh (no user interaction)
					if ($script:AuthConfig.Method -eq 'AppRegistration' -and $script:AuthConfig.CanReauthenticate) {
						$refreshResult = Invoke-TokenRefresh -Force
						if ($refreshResult.Success -and $refreshResult.NewToken) {
							$script:AuthFailureDetected = $false
							$script:Auth401MessageShown = $false
							# Update shared auth state for thread jobs
							$script:SharedAuthState.Token = $refreshResult.NewToken
							$script:SharedAuthState.ExpiresOn = (Get-Date).ToUniversalTime().AddMinutes(50)
							$script:SharedAuthState.LastRefresh = Get-Date
							Write-LogHost "  [AUTH] Token refreshed automatically (AppRegistration)" -ForegroundColor Green
						} else {
							# AppRegistration is non-interactive by design - there is no R/Q prompt that
							# could supply alternate credentials. Save checkpoint and exit cleanly so the
							# run can be resumed once the cert/secret issue is fixed. Applies to both -Force
							# and non-Force runs.
							Write-LogHost "  [AUTH] FATAL: AppRegistration token refresh failed - exiting (use -Resume after fixing credentials)" -ForegroundColor Red
							if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
							Write-LogHost "  Exiting due to authentication failure. Use -Resume to continue later." -ForegroundColor Yellow
							return
						}
					} else {
						# Interactive modes: prompt user
						$refreshResult = Invoke-TokenRefreshPrompt
						if ($refreshResult -eq 'Quit') {
							if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
							Write-LogHost "  Exiting due to user request. Use -Resume to continue later." -ForegroundColor Yellow
							return
						}
						# Update shared auth state for thread jobs
						$tokenInfo = Get-GraphAccessTokenWithExpiry
						if ($tokenInfo) {
							$script:SharedAuthState.Token = $tokenInfo.Token
							$script:SharedAuthState.ExpiresOn = $tokenInfo.ExpiresOn
							$script:SharedAuthState.LastRefresh = Get-Date
						}
					}
					Write-LogHost "  [AUTH] Token refreshed - resuming job launch" -ForegroundColor Green
				}
				
				Start-Sleep -Milliseconds 500
				
				# Collect output from active jobs while waiting (with error detection).
				# Process ALL jobs including completed ones — completed jobs MUST be processed to get
				# their result objects for JSONL save and checkpoint update.
				foreach ($activeJob in $activeJobs) {
					if ($script:AuthFailureDetected) { break }  # IMMEDIATE EXIT on auth failure
					try {
						# NO -Keep: process result objects fully here (JSONL save, checkpoint)
						$waitOutput = Receive-Job -Job $activeJob -ErrorAction SilentlyContinue -ErrorVariable backpressureJobErrors
						
						# Check for 401 errors in job output
						if ($backpressureJobErrors) {
							foreach ($err in $backpressureJobErrors) {
								$errMsg = if ($err.Exception) { $err.Exception.Message } else { $err.ToString() }
								if ($errMsg -match '401|Unauthorized|token.*expired') {
									$script:AuthFailureDetected = $true
									if (-not $script:Auth401MessageShown) {
										$script:Auth401MessageShown = $true
										Write-LogHost "  [AUTH] 401 Unauthorized detected - stopping to re-authenticate" -ForegroundColor Red
									}
									break  # IMMEDIATE EXIT
								}
							}
						}
						if ($script:AuthFailureDetected) { break }  # Exit if flag was set
						if ($waitOutput) {
							foreach ($output in $waitOutput) {
								if ($script:AuthFailureDetected) { break }  # IMMEDIATE EXIT
								if ($output -is [string]) {
									$msgKey = "$($activeJob.Id):$output"
									$color = $null
									if ($output -match '^\[ATTEMPT\]') {
										$msgKey = "$($activeJob.Id):ATTEMPT"
										$color = 'DarkGray'
									}
									elseif ($output -match '^\[SENT\]') {
										$color = 'DarkGray'
										# CRITICAL: Extract and store QueryId from SENT message for retry reuse
										if ($output -match 'QueryId:\s*([a-f0-9-]+)\)') {
											$extractedQueryId = $matches[1]
											$jobPartition = $jobMeta[$activeJob.Id]
											if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
												$script:partitionStatus[$jobPartition.Index].QueryId = $extractedQueryId
												# Record the effective creation version (creation is always beta) so
												# the checkpoint carries the per-query lifecycle version.
												$script:partitionStatus[$jobPartition.Index].QueryApiVersion = $script:GraphAuditApiVersion_Previous
												$script:partitionStatus[$jobPartition.Index].LifecycleOperation = 'Create'
												
												# CHECKPOINT: Save QueryCreated state so we can resume data fetch if interrupted
												if ($script:CheckpointEnabled) {
													Save-Checkpoint -PartitionIndex $jobPartition.Index -QueryId $extractedQueryId -State 'QueryCreated' -LifecycleState $script:partitionStatus[$jobPartition.Index]
												}
											}
										}
									}
									elseif ($output -match '^\[ERROR\]') {
										$color = 'Red'
										# Check for 401 in error messages from thread jobs
										if ($output -match '401|Unauthorized') {
											$script:AuthFailureDetected = $true
											if (-not $script:Auth401MessageShown) {
												$script:Auth401MessageShown = $true
												Write-LogHost "  [AUTH] 401 Unauthorized detected in job output" -ForegroundColor Red
											}
											# CRITICAL: Mark this partition as Failed for retry after re-auth
											$jobPartition = $jobMeta[$activeJob.Id]
											if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
												Set-PartitionFailure -Index $jobPartition.Index -Stage 'AUTH' -Reason '401'
												$script:partitionStatus[$jobPartition.Index].LastError = '401 Unauthorized - token expired'
											}
											break  # IMMEDIATE EXIT - don't process more output
										} else {
											# Non-401 [ERROR] messages (e.g., "Unexpected error during record processing")
											# must also mark the partition as Failed for retry.
											$jobPartition = $jobMeta[$activeJob.Id]
											if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
												Set-PartitionFailure -Index $jobPartition.Index -Stage 'FETCH' -Reason 'JOB_ERROR'
												$script:partitionStatus[$jobPartition.Index].LastError = $output
												Write-LogHost "  [RETRY-QUEUE] Partition $($jobPartition.Index)/$($jobPartition.Total) queued for retry at end of run" -ForegroundColor Yellow
											}
										}
									}
									elseif ($output -match '^\[403-(CREATE|POLL|FETCH)\]') {
										# Transient 403 retry messages - dedupe by partition+attempt
										$msgKey = "$($activeJob.Id):403:$output"
										$color = 'Magenta'
									}
									elseif ($output -match '^\[403-(PERM|MAX)\]') {
										# Permanent/max retry 403 messages
										$msgKey = "$($activeJob.Id):403:$output"
										$color = 'Red'
									}
									elseif ($output -match '^\[STATUS\] Query running') {
										$msgKey = "$($activeJob.Id):STATUS"
										$color = 'Yellow'
									}
									elseif ($output -match '^\[SUCCESS\]') {
										$msgKey = "$($activeJob.Id):SUCCESS"
										$color = 'Green'
									}
									if ($color -and -not $script:shownJobMessages.ContainsKey($msgKey)) {
										$message = if ($output -match '^\[(STATUS|SUCCESS)\]\s*') {
											$output -replace '^\[STATUS\]\s*','' -replace '^\[SUCCESS\]\s*',''
										} else {
											$output
										}
										Write-LogHost $message -ForegroundColor $color
										$script:shownJobMessages[$msgKey] = $true
									}
								}
								elseif ($output -isnot [string] -and -not $script:processedJobIds.Contains($activeJob.Id)) {
									# DEFENSIVE: Detect SplitRequired objects (should never arrive now, but guard against it)
									if ($output.SplitRequired -eq $true) {
										$jobPartition = $jobMeta[$activeJob.Id]
										if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
											Set-PartitionFailure -Index $jobPartition.Index -Stage 'FETCH' -Reason 'STILL_RUNNING'
											$script:partitionStatus[$jobPartition.Index].LastError = "Query still running after $([Math]::Round($output.ElapsedMinutes,1)) min - queued for retry"
											Write-LogHost "  [RETRY-QUEUE] Partition $($jobPartition.Index)/$($jobPartition.Total) - query still processing after $([Math]::Round($output.ElapsedMinutes,1)) min, queued for retry" -ForegroundColor Yellow
										}
										[void]$script:processedJobIds.Add($activeJob.Id)
										continue
									}
									# FULL RESULT PROCESSING: Handle result objects immediately to ensure JSONL save
									$jobPartition = $jobMeta[$activeJob.Id]
									if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
										$currentStatus = $script:partitionStatus[$jobPartition.Index].Status
										if ($currentStatus -ne 'Complete') {
											if ([string]::IsNullOrWhiteSpace([string]$output.QueryId) -and [int]($output.RetrievedCount ?? 0) -le 0) {
												Set-PartitionFailure -Index $jobPartition.Index -Stage 'CREATE' -Reason 'EMPTY_QUERYID'
												$script:partitionStatus[$jobPartition.Index].LastError = 'ThreadJob returned empty QueryId with zero records (query was not created/sent)'
												Write-LogHost "  [DATA-CHECK] Partition $($jobPartition.Index) returned empty QueryId with 0 records - marked Failed for retry" -ForegroundColor Yellow
												[void]$script:processedJobIds.Add($activeJob.Id)
												continue
											}

											$script:partitionStatus[$jobPartition.Index].Status = 'Complete'
											$script:partitionStatus[$jobPartition.Index].QueryId = $output.QueryId
											$script:partitionStatus[$jobPartition.Index].RecordCount = ($output.RetrievedCount ?? 0)
											
											# Fallback: emit SUCCESS message if the original [SUCCESS] string was already consumed
											$successKey = "$($activeJob.Id):SUCCESS"
											if (-not $script:shownJobMessages.ContainsKey($successKey)) {
												$script:shownJobMessages[$successKey] = $true
												Write-LogHost "Query succeeded - Partition $($jobPartition.Index)/$($jobPartition.Total) - Query ID: $($output.QueryId) - Retrieved $($output.RetrievedCount ?? 0) records" -ForegroundColor Green
											}

											if ($output.ThreadSavedToDisk -and $script:memoryFlushEnabled -and -not $script:memoryFlushed) {
												$script:memoryFlushed = $true
												Write-LogHost "  [STREAM] Thread-side JSONL persistence active - parallel partition data is being written to disk (normal for parallel partition fetches; not a memory-pressure event)" -ForegroundColor DarkCyan
											}
											
											# Add logs to collection (skip when memory flush enabled - data goes to JSONL only)
											if ($output.Logs -and $output.Logs.Count -gt 0 -and -not $script:memoryFlushEnabled) {
												$allLogs.AddRange($output.Logs)
											}
											
											# Update metrics
											try {
												$script:metrics.QueryMs += [int]$output.ElapsedMs
												$script:metrics.TotalRecordsFetched += [int]$output.RetrievedCount
											} catch {}
											
											# Save checkpoint
											if ($script:CheckpointEnabled) {
												Save-Checkpoint -PartitionIndex $jobPartition.Index -QueryId $output.QueryId -State 'Completed' -RecordCount $output.RetrievedCount
											}
											
											# INCREMENTAL SAVE: Write JSONL immediately
											if ($output.Logs -and $output.Logs.Count -gt 0) {
												try {
													$incrementalDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
													if (-not (Test-Path $incrementalDir)) {
														New-Item -ItemType Directory -Path $incrementalDir -Force | Out-Null
													}
													$incrementalFile = Join-Path $incrementalDir "Part$($jobPartition.Index)_${global:ScriptRunTimestamp}_qid-$($output.QueryId)_$($output.RetrievedCount)records.jsonl"
													$output.Logs | ForEach-Object { $_ | ConvertTo-Json -Depth 10 -Compress } | Out-File -FilePath $incrementalFile -Encoding utf8 -Force
													Write-LogHost "  [SAVE] Partition $($jobPartition.Index): $($output.RetrievedCount) records saved to disk" -ForegroundColor DarkGreen
													
													# Release source reference to allow GC to reclaim memory
													$output.Logs = $null
													
													# MEMORY MANAGEMENT: When enabled, we skip AddRange and use JSONL-only path
													# Set memoryFlushed flag to signal streaming export
													if ($script:memoryFlushEnabled -and -not $script:memoryFlushed) {
														$script:memoryFlushed = $true
														Write-LogHost "  [STREAM] JSONL-backed streaming persistence active - partition records written to disk (cap: $($script:ResolvedMaxMemoryMB)MB; routine for parallel-partition fetches, not a memory-pressure event)" -ForegroundColor DarkCyan
													}
												} catch {
													Write-LogHost "  [WARN] Failed to save incremental data for Partition $($jobPartition.Index): $($_.Exception.Message)" -ForegroundColor Yellow
												}
											}
											
											# Mark job as processed
											[void]$script:processedJobIds.Add($activeJob.Id)
										}
									}
								}
							}
						}
					} catch {}
				}
				
				# Recount active jobs
				$activeJobs = @($jobs | Where-Object { $_.State -in 'Running','NotStarted' })
			}
			
		# Create the job now that we have a slot
			# Graph API: MaxRecords=0 (unlimited) - 10K limit only applies to EOM mode
			$graphResultSize = if ($UseEOM) { $ResultSize } else { 0 }
			
			# For fetch-only partitions (resume mode), pass stored QueryId to skip query creation
			$existingQueryIdForJob = if ($pt.StoredQueryId) { $pt.StoredQueryId } else { $null }
			if ($existingQueryIdForJob) {
				Write-LogHost "[RESUME] Partition $($pt.Index)/$($pt.Total) - Using stored QueryId: $existingQueryIdForJob" -ForegroundColor Yellow
			}
			# The worker polls and fetches on the SAME version the query was created on.
			# The parent records that effective version on the partition state; fall back
			# to the run version only when a partition carries none.
			$effectiveApiVersion = if ($script:partitionStatus[$pt.Index].QueryApiVersion) { $script:partitionStatus[$pt.Index].QueryApiVersion } else { $script:GraphAuditApiVersion }
			
		$job = Start-ThreadJob -ThrottleLimit $maxConcurrentPartitions -ScriptBlock $queryJobScriptBlock -ArgumentList $pt.PStart, $pt.PEnd, $activities, $graphResultSize, $script:targetUsers, $pt.Index, $pt.Total, $script:SharedAuthState, $pt, $MaxNetworkOutageMinutes, $effectiveApiVersion, $script:LogFile, $existingQueryIdForJob, $threadIncrementalDir, $threadRunTimestamp, $threadMemoryFlushEnabled, $script:QueryObservations
					$jobs += $job
					$jobMeta[$job.Id] = $pt
					
					# Mark this partition as having a job created for it
					[void]$script:partitionsWithJobs.Add($pt.Index)
					if ($script:partitionStatus.ContainsKey($pt.Index)) {
						$script:partitionStatus[$pt.Index].Status = 'JobCreated'
					}
					
					# Log each job creation to terminal
					$createdTimestamp = Get-Date -Format 'HH:mm:ss'
					Write-LogHost "[CREATED] [$createdTimestamp] Partition $($pt.Index)/$($pt.Total) - Job created" -ForegroundColor DarkGray
					
					# Poll for output from this job for up to 10 seconds (Purview API can have unpredictable latency)
					Start-Sleep -Milliseconds 50  # Small initial delay to let job start
					$pollAttempts = 0
					$maxPollAttempts = 100  # 100 x 100ms = 10 seconds
					$gotSentMessage = $false
					
					while ($pollAttempts -lt $maxPollAttempts -and -not $gotSentMessage) {
						Start-Sleep -Milliseconds 100
						$pollAttempts++
						
						if ($job.State -eq 'Completed') { break }
						
						try {
							# NO -Keep here: immediate polling is just waiting for [SENT], job hasn't completed yet
							# Result objects only appear after job completion, which happens later in main monitoring loop
							$immediateOutput = Receive-Job -Job $job -ErrorAction SilentlyContinue
							if ($immediateOutput) {
								foreach ($output in $immediateOutput) {
									if ($output -is [string]) {
										$msgKey = "$($job.Id):$output"
										if ($output -match '^\[ATTEMPT\]') {
											$msgKey = "$($job.Id):ATTEMPT"
										}
										
										if ($output -match '^\[ATTEMPT\]') {
											# Always show ATTEMPT messages (retries)
											if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
												Write-LogHost $output -ForegroundColor DarkGray
												$script:shownJobMessages[$msgKey] = $true
											}
										}
										elseif ($output -match '^\[SENT\]') {
											# Only show SENT once globally
											$msgKey = "$($job.Id):$output"
											if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
												Write-LogHost $output -ForegroundColor DarkGray
												$script:shownJobMessages[$msgKey] = $true
												
												# CRITICAL: Extract and store QueryId from SENT message for retry reuse
												# Format: [SENT]    [HH:mm:ss] Partition X/Y - Query sent to Purview (QueryId: xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx)
												if ($output -match 'QueryId:\s*([a-f0-9-]+)\)') {
													$extractedQueryId = $matches[1]
													$jobPartition = $jobMeta[$job.Id]
													if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
														$script:partitionStatus[$jobPartition.Index].QueryId = $extractedQueryId
														Write-Verbose "[QUERYID-CAPTURED] Partition $($jobPartition.Index) QueryId=$extractedQueryId" -Verbose:$VerbosePreference
														# Record the effective creation version (creation is always beta) so
														# the checkpoint carries the per-query lifecycle version.
														$script:partitionStatus[$jobPartition.Index].QueryApiVersion = $script:GraphAuditApiVersion_Previous
														$script:partitionStatus[$jobPartition.Index].LifecycleOperation = 'Create'
														
														# CHECKPOINT: Save QueryCreated state so we can resume data fetch if interrupted
														if ($script:CheckpointEnabled) {
															Save-Checkpoint -PartitionIndex $jobPartition.Index -QueryId $extractedQueryId -State 'QueryCreated' -LifecycleState $script:partitionStatus[$jobPartition.Index]
														}
													}
												}
											} else {
												Write-Verbose "DEDUP: Already shown - JobId=$($job.Id), Msg=$output" -Verbose:$VerbosePreference
											}
											$gotSentMessage = $true
										}
										elseif ($output -match '^\[ERROR\]') {
											if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
												Write-LogHost $output -ForegroundColor Red
												$script:shownJobMessages[$msgKey] = $true
												# Check for 401 in error messages
												if ($output -match '401|Unauthorized') {
													$script:AuthFailureDetected = $true
													if (-not $script:Auth401MessageShown) {
														$script:Auth401MessageShown = $true
														Write-LogHost "  [AUTH] 401 Unauthorized detected in job output" -ForegroundColor Red
													}
													# CRITICAL: Mark this partition as Failed for retry after re-auth
													$jobPartition = $jobMeta[$job.Id]
													if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
														Set-PartitionFailure -Index $jobPartition.Index -Stage 'AUTH' -Reason '401'
														$script:partitionStatus[$jobPartition.Index].LastError = '401 Unauthorized - token expired'
													}
													break  # IMMEDIATE EXIT
												}
											}
											$gotSentMessage = $true  # Stop polling on error too
										}
										elseif ($output -match '^\[403-(CREATE|POLL|FETCH)\]') {
											# Transient 403 retry messages - dedupe by partition+attempt
											$msgKey = "$($job.Id):403:$output"
											if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
												Write-LogHost $output -ForegroundColor Magenta
												$script:shownJobMessages[$msgKey] = $true
											}
										}
										elseif ($output -match '^\[403-(PERM|MAX)\]') {
											# Permanent/max retry 403 messages
											$msgKey = "$($job.Id):403:$output"
											if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
												Write-LogHost $output -ForegroundColor Red
												$script:shownJobMessages[$msgKey] = $true
											}
										}
										elseif ($output -match '^\[STATUS\] Query running') {
											$msgKey = "$($job.Id):STATUS"
											if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
												Write-LogHost ($output -replace '^\[STATUS\]\s*','') -ForegroundColor Yellow
												$script:shownJobMessages[$msgKey] = $true
											}
										}
										elseif ($output -match '^\[SUCCESS\]') {
											$msgKey = "$($job.Id):SUCCESS"
											if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
												Write-LogHost ($output -replace '^\[SUCCESS\]\s*','') -ForegroundColor Green
												$script:shownJobMessages[$msgKey] = $true
											}
										}
								}
								elseif ($output -isnot [string] -and -not $script:processedJobIds.Contains($job.Id)) {
									# FULL RESULT PROCESSING: Handle result objects immediately to ensure JSONL save
									$jobPartition = $jobMeta[$job.Id]
									if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
										$currentStatus = $script:partitionStatus[$jobPartition.Index].Status
										if ($currentStatus -ne 'Complete') {
											if ([string]::IsNullOrWhiteSpace([string]$output.QueryId) -and [int]($output.RetrievedCount ?? 0) -le 0) {
												Set-PartitionFailure -Index $jobPartition.Index -Stage 'CREATE' -Reason 'EMPTY_QUERYID'
												$script:partitionStatus[$jobPartition.Index].LastError = 'ThreadJob returned empty QueryId with zero records (query was not created/sent)'
												Write-LogHost "  [DATA-CHECK] Partition $($jobPartition.Index) returned empty QueryId with 0 records - marked Failed for retry" -ForegroundColor Yellow
												[void]$script:processedJobIds.Add($job.Id)
												continue
											}

											$script:partitionStatus[$jobPartition.Index].Status = 'Complete'
											$script:partitionStatus[$jobPartition.Index].QueryId = $output.QueryId
											$script:partitionStatus[$jobPartition.Index].RecordCount = $output.RetrievedCount
											
											# Add logs to collection (skip if memory flush enabled - using JSONL only)
											if ($output.Logs -and $output.Logs.Count -gt 0 -and -not $script:memoryFlushEnabled) {
												$allLogs.AddRange($output.Logs)
											}
											
											# Update metrics
											try {
												$script:metrics.QueryMs += [int]$output.ElapsedMs
												$script:metrics.TotalRecordsFetched += [int]$output.RetrievedCount
											} catch {}
											
											# Save checkpoint
											if ($script:CheckpointEnabled) {
												Save-Checkpoint -PartitionIndex $jobPartition.Index -QueryId $output.QueryId -State 'Completed' -RecordCount $output.RetrievedCount
											}
											
											# INCREMENTAL SAVE: Write JSONL immediately
											if ($output.Logs -and $output.Logs.Count -gt 0) {
												try {
													$incrementalDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
													if (-not (Test-Path $incrementalDir)) {
														New-Item -ItemType Directory -Path $incrementalDir -Force | Out-Null
													}
													$incrementalFile = Join-Path $incrementalDir "Part$($jobPartition.Index)_${global:ScriptRunTimestamp}_qid-$($output.QueryId)_$($output.RetrievedCount)records.jsonl"
													$output.Logs | ForEach-Object { $_ | ConvertTo-Json -Depth 10 -Compress } | Out-File -FilePath $incrementalFile -Encoding utf8 -Force
													Write-LogHost "  [SAVE] Partition $($jobPartition.Index): $($output.RetrievedCount) records saved to disk" -ForegroundColor DarkGreen
													
													# Clear reference to allow GC (critical for memory management)
													$output.Logs = $null
													
													# MEMORY MANAGEMENT: Mark if we're using JSONL-only mode
													if ($script:memoryFlushEnabled -and -not $script:memoryFlushed) {
														$script:memoryFlushed = $true
														Write-LogHost "  [STREAM] JSONL-backed streaming persistence active - partition records written to disk (streaming export at end; routine for parallel-partition fetches, not a memory-pressure event)" -ForegroundColor DarkCyan
													}
												} catch {
													Write-LogHost "  [WARN] Failed to save incremental data for Partition $($jobPartition.Index): $($_.Exception.Message)" -ForegroundColor Yellow
												}
											}
											
											# Mark job as processed
											[void]$script:processedJobIds.Add($job.Id)
										}
									}
								}
							}
						}
					} catch {}
				}
				
				Write-Verbose "Created job for partition $($pt.Index)/$($pt.Total) - Job ID: $($job.Id)" -Verbose:$VerbosePreference
				
				# Start monitoring loop in background once first batch is queued
				# Note: Jobs may still be retrying 403s internally - this just means they've been started
				if (-not $monitoringStarted -and $jobs.Count -ge $firstBatchSize) {
					$monitoringStarted = $true
					# Initialize monitoring state
					$script:lastStatusUpdate = Get-Date
				}					# Show status updates while creating jobs (if monitoring started)
					if ($monitoringStarted) {
						# Collect output from all existing jobs.
						# Process ALL jobs including completed ones — completed jobs MUST be processed
						# to get their result objects for JSONL save and checkpoint update.
						foreach ($existingJob in $jobs) {
							try {
								# NO -Keep: process result objects fully here (JSONL save, checkpoint)
								$jobOutput = Receive-Job -Job $existingJob -ErrorAction SilentlyContinue
								if ($jobOutput) {
									foreach ($output in $jobOutput) {
										if ($output -is [string]) {
											$msgKey = "$($existingJob.Id):$output"
											if ($output -match '^\[ATTEMPT\]') {
												$msgKey = "$($existingJob.Id):ATTEMPT"
											}
											
											if ($output -match '^\[ATTEMPT\]') {
												# Always show ATTEMPT messages (retries)
												if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
													Write-LogHost $output -ForegroundColor DarkGray
													$script:shownJobMessages[$msgKey] = $true
												}
											}
											elseif ($output -match '^\[SENT\]') {
												# Only show SENT once per job
												if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
													Write-LogHost $output -ForegroundColor DarkGray
													$script:shownJobMessages[$msgKey] = $true
												}
												# CRITICAL: Extract and store QueryId from SENT message for retry reuse
												if ($output -match 'QueryId:\s*([a-f0-9-]+)\)') {
													$extractedQueryId = $matches[1]
													$jobPartition = $jobMeta[$existingJob.Id]
													if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
														$script:partitionStatus[$jobPartition.Index].QueryId = $extractedQueryId
													}
												}
											}
											elseif ($output -match '^\[ERROR\]') {
												if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
													Write-LogHost $output -ForegroundColor Red
													$script:shownJobMessages[$msgKey] = $true
													# Check for 401 in error messages
													if ($output -match '401|Unauthorized') {
														$script:AuthFailureDetected = $true
														if (-not $script:Auth401MessageShown) {
															$script:Auth401MessageShown = $true
															Write-LogHost "  [AUTH] 401 Unauthorized detected in job output" -ForegroundColor Red
														}
														# CRITICAL: Mark this partition as Failed for retry after re-auth
														$jobPartition = $jobMeta[$existingJob.Id]
														if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
															Set-PartitionFailure -Index $jobPartition.Index -Stage 'AUTH' -Reason '401'
															$script:partitionStatus[$jobPartition.Index].LastError = '401 Unauthorized - token expired'
														}
														break  # IMMEDIATE EXIT
													}
												}
											}
											elseif ($output -match '^\[STATUS\] Query running') {
												$msgKey = "$($existingJob.Id):STATUS"
												if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
													Write-LogHost ($output -replace '^\[STATUS\]\s*','') -ForegroundColor Yellow
													$script:shownJobMessages[$msgKey] = $true
												}
											}
											elseif ($output -match '^\[PROGRESS\]') {
												# Silent: extract page count to update STATUS display, do not log
												if ($output -match '\[PROGRESS\] P(\d+)/\d+ pg(\d+)') {
													$pIdx = [int]$matches[1]; $pg = [int]$matches[2]
													if (-not $script:partitionPageCounts.ContainsKey($pIdx) -or $pg -gt $script:partitionPageCounts[$pIdx]) {
														$script:partitionPageCounts[$pIdx] = $pg
													}
												}
												$script:shownJobMessages[$msgKey] = $true
											}
											elseif ($output -match '^\[NETWORK\]') {
												# Also extract page count from NETWORK error messages
												if ($output -match 'Partition (\d+)/\d+ Page (\d+)') {
													$pIdx = [int]$matches[1]; $pg = [int]$matches[2]
													if (-not $script:partitionPageCounts.ContainsKey($pIdx) -or $pg -gt $script:partitionPageCounts[$pIdx]) {
														$script:partitionPageCounts[$pIdx] = $pg
													}
												}
												if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
													Write-LogHost $output -ForegroundColor DarkYellow
													$script:shownJobMessages[$msgKey] = $true
												}
											}
											elseif ($output -match '^\[SUCCESS\]') {
												$msgKey = "$($existingJob.Id):SUCCESS"
												if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
													Write-LogHost ($output -replace '^\[SUCCESS\]\s*','') -ForegroundColor Green
													$script:shownJobMessages[$msgKey] = $true
												}
											}
										}
										elseif ($output -isnot [string] -and -not $script:processedJobIds.Contains($existingJob.Id)) {
											# DEFENSIVE: Detect SplitRequired objects and treat as Failed for retry
											if ($output.SplitRequired -eq $true) {
												$jobPartition = $jobMeta[$existingJob.Id]
												if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
													Set-PartitionFailure -Index $jobPartition.Index -Stage 'FETCH' -Reason 'STILL_RUNNING'
													$script:partitionStatus[$jobPartition.Index].LastError = "Query still running after $([Math]::Round($output.ElapsedMinutes,1)) min - queued for retry"
													Write-LogHost "  [RETRY-QUEUE] Partition $($jobPartition.Index)/$($jobPartition.Total) - query still processing after $([Math]::Round($output.ElapsedMinutes,1)) min, queued for retry" -ForegroundColor Yellow
												}
												[void]$script:processedJobIds.Add($existingJob.Id)
												continue
											}
											# FULL RESULT PROCESSING: Handle result objects immediately to ensure JSONL save
											$jobPartition = $jobMeta[$existingJob.Id]
											if ($jobPartition -and $script:partitionStatus.ContainsKey($jobPartition.Index)) {
												$currentStatus = $script:partitionStatus[$jobPartition.Index].Status
												if ($currentStatus -ne 'Complete') {
													if ([string]::IsNullOrWhiteSpace([string]$output.QueryId) -and [int]($output.RetrievedCount ?? 0) -le 0) {
														Set-PartitionFailure -Index $jobPartition.Index -Stage 'CREATE' -Reason 'EMPTY_QUERYID'
														$script:partitionStatus[$jobPartition.Index].LastError = 'ThreadJob returned empty QueryId with zero records (query was not created/sent)'
														Write-LogHost "  [DATA-CHECK] Partition $($jobPartition.Index) returned empty QueryId with 0 records - marked Failed for retry" -ForegroundColor Yellow
														[void]$script:processedJobIds.Add($existingJob.Id)
														continue
													}

													$script:partitionStatus[$jobPartition.Index].Status = 'Complete'
													$script:partitionStatus[$jobPartition.Index].QueryId = $output.QueryId
													$script:partitionStatus[$jobPartition.Index].RecordCount = ($output.RetrievedCount ?? 0)
													
													# Fallback: emit SUCCESS message if the original [SUCCESS] string was already consumed
													$successKey = "$($existingJob.Id):SUCCESS"
													if (-not $script:shownJobMessages.ContainsKey($successKey)) {
														$script:shownJobMessages[$successKey] = $true
														Write-LogHost "Query succeeded - Partition $($jobPartition.Index)/$($jobPartition.Total) - Query ID: $($output.QueryId) - Retrieved $($output.RetrievedCount ?? 0) records" -ForegroundColor Green
													}

													if ($output.ThreadSavedToDisk -and $script:memoryFlushEnabled -and -not $script:memoryFlushed) {
														$script:memoryFlushed = $true
														Write-LogHost "  [STREAM] Thread-side JSONL persistence active - parallel partition data is being written to disk (normal for parallel partition fetches; not a memory-pressure event)" -ForegroundColor DarkCyan
													}
													
													# Add logs to collection (skip if memory flush enabled - using JSONL only)
													if ($output.Logs -and $output.Logs.Count -gt 0 -and -not $script:memoryFlushEnabled) {
														$allLogs.AddRange($output.Logs)
													}
													
													# Update metrics
													try {
														$script:metrics.QueryMs += [int]$output.ElapsedMs
														$script:metrics.TotalRecordsFetched += [int]$output.RetrievedCount
													} catch {}
													
													# Save checkpoint
													if ($script:CheckpointEnabled) {
														Save-Checkpoint -PartitionIndex $jobPartition.Index -QueryId $output.QueryId -State 'Completed' -RecordCount $output.RetrievedCount
													}
													
													# INCREMENTAL SAVE: Write JSONL immediately
													if ($output.Logs -and $output.Logs.Count -gt 0) {
														try {
															$incrementalDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
															if (-not (Test-Path $incrementalDir)) {
																New-Item -ItemType Directory -Path $incrementalDir -Force | Out-Null
															}
															$incrementalFile = Join-Path $incrementalDir "Part$($jobPartition.Index)_${global:ScriptRunTimestamp}_qid-$($output.QueryId)_$($output.RetrievedCount)records.jsonl"
															$output.Logs | ForEach-Object { $_ | ConvertTo-Json -Depth 10 -Compress } | Out-File -FilePath $incrementalFile -Encoding utf8 -Force
															Write-LogHost "  [SAVE] Partition $($jobPartition.Index): $($output.RetrievedCount) records saved to disk" -ForegroundColor DarkGreen
															
															# Clear reference to allow GC (critical for memory management)
															$output.Logs = $null
															
															# MEMORY MANAGEMENT: Mark if we're using JSONL-only mode
															if ($script:memoryFlushEnabled -and -not $script:memoryFlushed) {
																$script:memoryFlushed = $true
																Write-LogHost "  [STREAM] JSONL-backed streaming persistence active - partition records written to disk (streaming export at end; routine for parallel-partition fetches, not a memory-pressure event)" -ForegroundColor DarkCyan
															}
														} catch {
															Write-LogHost "  [WARN] Failed to save incremental data for Partition $($jobPartition.Index): $($_.Exception.Message)" -ForegroundColor Yellow
														}
													}
													
													# Mark job as processed
													[void]$script:processedJobIds.Add($existingJob.Id)
												}
											}
										}
									}
								}
							} catch {
								# Silently continue if we can't receive from a job
							}
						}
					
					$parentNowUtc = (Get-Date).ToUniversalTime()
					# PAX-1E: measure parent monitor-loop scheduling delay (gap between successive
					# status emissions vs the configured cadence). A material excess is surfaced
					# once per stall, neutrally; the cause is not classified and no query state
					# changes.
					$parentLoopExcess = Measure-PaxParentLoopDelay -PreviousIterationUtc $script:PaxLastStatusEmitUtc -CurrentUtc $parentNowUtc -ExpectedCadenceSeconds $StatusIntervalSeconds -ToleranceSeconds ([Math]::Max(30, $StatusIntervalSeconds))
					if ($parentLoopExcess -gt 0 -and $script:PaxLastStatusEmitUtc) {
						$stalePollAge = $null
						foreach ($o in @($script:QueryObservations.Values)) { if ($o -and $o.LastSuccessfulPollUtc) { $pa = ($parentNowUtc - [datetime]$o.LastSuccessfulPollUtc).TotalSeconds; if ($null -eq $stalePollAge -or $pa -gt $stalePollAge) { $stalePollAge = [Math]::Round($pa, 0) } } }
						Write-LogHost ("[MONITOR] Query monitoring resumed after an extended parent-loop delay (~{0}s); server state is being refreshed (last known worker-poll age: {1})." -f [Math]::Round($parentLoopExcess, 0), $(if ($null -ne $stalePollAge) { "${stalePollAge}s" } else { 'unknown' })) -ForegroundColor Yellow
					}
					$script:PaxLastStatusEmitUtc = $parentNowUtc

					$elapsedSinceLastUpdate = ((Get-Date) - $script:lastStatusUpdate).TotalSeconds
					if ($elapsedSinceLastUpdate -ge $StatusIntervalSeconds) {
						# Count partitions by status (EXCLUDE 'Subdivided' parent partitions from total)
						$activeStatuses = $script:partitionStatus.Values | Where-Object { $_.Status -ne 'Subdivided' }
						$completedPartitions = @($activeStatuses | Where-Object { $_.Status -eq 'Complete' }).Count
						$jobCreatedPartitions = @($activeStatuses | Where-Object { $_.Status -eq 'JobCreated' }).Count
						$notStartedPartitions = @($activeStatuses | Where-Object { $_.Status -eq 'NotStarted' }).Count
						
						# Calculate remaining and total (only active partitions)
						$remainingToComplete = $jobCreatedPartitions + $notStartedPartitions
						$totalPartitions = $activeStatuses.Count
						
						$statusLine = "[$(Get-Date -Format 'HH:mm:ss')] Total Queries: $($totalPartitions + $script:resumeCompletedOffset) | Completed: $($completedPartitions + $script:resumeCompletedOffset) | Remaining: $remainingToComplete"
						if ($script:partitionPageCounts -and $script:partitionPageCounts.Count -gt 0) {
							$pageStr = ($script:partitionPageCounts.GetEnumerator() | Sort-Object Key | ForEach-Object { "P$($_.Key):$($_.Value.ToString('N0'))pg" }) -join ' '
							$statusLine += " | Pages $pageStr"
						}
						# PAX-1E: authoritative heartbeat built DIRECTLY from the shared worker
						# observations + partition status (never parsed from Receive-Job text).
						# Delivered through a latency-measuring wrapper that emits a neutral
						# follow-up warning if terminal/log persistence itself was materially
						# delayed (the cause is not classified as a Purview/host/folder failure).
						$paxHostGapTotal = 0.0
						foreach ($o in @($script:QueryObservations.Values)) { if ($o -and $o.HostGapSecondsExcluded) { $paxHostGapTotal += [double]$o.HostGapSecondsExcluded } }
						$paxHb = Format-PaxParentHeartbeat -PartitionStatuses @($script:partitionStatus.Values) -Observations @($script:QueryObservations.Values) -PageCounts $script:partitionPageCounts -TokenRefreshState $script:PaxTokenRefreshState -NowUtc $parentNowUtc -ExcludedHostGapSeconds $paxHostGapTotal -ResumeCompletedOffset $script:resumeCompletedOffset
						$paxEventUtc = (Get-Date).ToUniversalTime()
						$null = Invoke-PaxHeartbeatDelivery -EventUtc $paxEventUtc -ExpectedIntervalSeconds $StatusIntervalSeconds -ToleranceSeconds ([Math]::Max(30, $StatusIntervalSeconds)) -DeliverAction {
							Write-LogHost $statusLine -ForegroundColor White
							Write-LogHost ("[MONITOR] " + $paxHb.Text) -ForegroundColor DarkGray
						} -WarnAction {
							param($evt, $del, $el)
							Write-LogHost ("[MONITOR] Terminal or log delivery was delayed ~{0}s (event {1:HH:mm:ss}Z, delivered {2:HH:mm:ss}Z); query state is being refreshed." -f $el, $evt, $del) -ForegroundColor Yellow
						}
						
						$script:lastStatusUpdate = Get-Date
					}
				}				# Staggered launch with 10-25s jitter to prevent API burst (except for last job)
					if ($pt.Index -lt $pt.Total) {
						$staggerDelay = Get-Random -Minimum 10 -Maximum 25
						Start-Sleep -Seconds $staggerDelay
					}
				}
				
				# All ThreadJobs now launched (note: this only means threads are running, not that queries were created on server)
				$launchElapsed = [Math]::Round(((Get-Date) - $launchStartTime).TotalSeconds, 1)
				Write-LogHost "  All $($jobs.Count) ThreadJobs launched (${launchElapsed}s), monitoring query creation..." -ForegroundColor DarkCyan
				
				
				# If monitoring wasn't started earlier (only happens if $partitions.Count < $firstBatchSize)
			if (-not $monitoringStarted) {
				$script:throttleNotifications = [System.Collections.Concurrent.ConcurrentQueue[PSObject]]::new()
			}				# Wait for all jobs to complete and display monitoring output
					$initialBlockSize = if ($script:globalLearnedBlockSize -and $script:globalLearnedBlockSize -gt 0) { $script:globalLearnedBlockSize } else { $BlockHours }
					if ($initialBlockSize -le 0) { $initialBlockSize = 0.5 }
					
					# Simple polling to monitor job completion
					$lastStatusUpdate = Get-Date
					$firstStatus = $true
					
					while (($jobs | Where-Object { $_.State -in 'Running','NotStarted' }).Count -gt 0) {
						# Continuously collect output from all jobs (running and completed)
						foreach ($job in $jobs) {
							# Skip jobs we've already processed (Receive-Job can only be called once)
							if ($script:processedJobIds.Contains($job.Id)) {
								continue
							}
							
							try {
								$jobOutput = Receive-Job -Job $job -Keep -ErrorAction SilentlyContinue -ErrorVariable jobErrors
								
								# Scaling: Receive-Job -Keep re-delivers ALL historical output every loop iteration.
								# After hundreds/thousands of pages, iterating all messages on every 500ms cycle causes
								# progressive slowdown (STATUS gaps widen from 60s to 10+ minutes after many hours).
								# Track per-job offset so only truly new messages are processed each cycle.
								$rawCount = if ($jobOutput) { @($jobOutput).Count } else { 0 }
								$seenCount = if ($script:jobOutputOffset.ContainsKey($job.Id)) { $script:jobOutputOffset[$job.Id] } else { 0 }
								$script:jobOutputOffset[$job.Id] = $rawCount
								$jobOutput = if ($rawCount -gt $seenCount) { @($jobOutput)[$seenCount..($rawCount - 1)] } else { $null }
								
								# Capture and log job errors to file (only once per job)
								if ($jobErrors -and $jobErrors.Count -gt 0) {
									# Check if we've already logged errors for this job
									$errorLogKey = "ERRORS:$($job.Id)"
									if (-not $script:shownJobMessages.ContainsKey($errorLogKey)) {
										$script:shownJobMessages[$errorLogKey] = $true
										foreach ($err in $jobErrors) {
											$errMsg = if ($err.Exception) { $err.Exception.Message } else { $err.ToString() }
											Write-Log "Job $($job.Id) error: $errMsg" -Level "ERROR"
											
											# DIFFERENTIATE 401 vs 403 ERRORS
											# 401 = Token expired/invalid → refresh will help
											# 403 = Permission denied → refresh will NOT help
											if ($errMsg -match '403|Forbidden|Access.*denied|Insufficient.*privileges') {
												# 403 Forbidden - permissions issue, NOT token expiration
												# Don't set AuthFailureDetected - refresh won't help
												Write-LogHost "  [AUTH] 403 Forbidden detected - this is a PERMISSIONS issue, not token expiration" -ForegroundColor Red
												Write-LogHost "  [AUTH] Token refresh will NOT resolve this. Check:" -ForegroundColor Yellow
												Write-LogHost "         • AuditLogsQuery.Read.All scope is granted" -ForegroundColor Yellow
												Write-LogHost "         • Admin consent has been provided" -ForegroundColor Yellow
												Write-LogHost "         • Required Azure AD role is assigned" -ForegroundColor Yellow
											}
											elseif ($errMsg -match '401|Unauthorized|token.*expired|authentication.*failed') {
												# 401 Unauthorized - token issue, refresh will help
												$script:AuthFailureDetected = $true
												if (-not $script:Auth401MessageShown) {
													$script:Auth401MessageShown = $true
													Write-LogHost "  [AUTH] 401 Unauthorized detected - stopping to re-authenticate" -ForegroundColor Red
												}
												break  # IMMEDIATE EXIT from job error processing
											}
										}
										
										# Mark partition as Failed for retry when errors detected
										$pt = $jobMeta[$job.Id]
										if ($pt -and $script:partitionStatus.ContainsKey($pt.Index)) {
											$currentStatus = $script:partitionStatus[$pt.Index].Status
											if ($currentStatus -notin 'Complete', 'Failed', 'Subdivided') {
												Set-PartitionFailure -Index $pt.Index -Stage 'FETCH' -Reason 'JOB_ERROR'
												$script:partitionStatus[$pt.Index].LastError = $jobErrors[0].Exception.Message
												Write-LogHost "  [RETRY-QUEUE] Partition $($pt.Index)/$($pt.Total) marked as Failed for retry (from monitoring loop)" -ForegroundColor Yellow
											}
										}
									}
								}
								
								if ($jobOutput) {
									foreach ($output in $jobOutput) {
										if ($output -is [string]) {
											# Create unique key for deduplication
											$msgKey = "$($job.Id):$output"
											if ($output -match '^\[ATTEMPT\]') {
												$msgKey = "$($job.Id):ATTEMPT"
											}
											elseif ($output -match '^\[STATUS\] Query running') {
												$msgKey = "$($job.Id):STATUS"
											}
											elseif ($output -match '^\[SUCCESS\]') {
												$msgKey = "$($job.Id):SUCCESS"
											}
											elseif ($output -match '^\[403-CREATE\]|^\[403-FETCH\]') {
												# Use the full output as key to deduplicate identical 403 messages
												# This prevents "Attempt 2/3" from repeating but allows different attempts to show
												$msgKey = "$($job.Id):$output"
											}
											elseif ($output -match '^\[PROGRESS\]') {
												# PROGRESS messages are silent page-count heartbeats — use full output as key (each is unique)
												$msgKey = "$($job.Id):$output"
											}
											elseif ($output -match '^\[NETWORK\]') {
												# NETWORK messages include changing elapsed time - deduplicate by partition/page only
												# Extract partition and page info for stable key
												if ($output -match 'Partition (\d+/\d+).*Page (\d+)') {
													$msgKey = "$($job.Id):NETWORK:$($matches[1]):Page$($matches[2])"
												} elseif ($output -match 'Partition (\d+/\d+)') {
													$msgKey = "$($job.Id):NETWORK:$($matches[1])"
												} else {
													$msgKey = "$($job.Id):NETWORK"
												}
											}
											if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
												$script:shownJobMessages[$msgKey] = $true
												
											# Display messages with appropriate colors
											if ($output -match '^\[ATTEMPT\]') {
												Write-LogHost $output -ForegroundColor Cyan
											}
											elseif ($output -match '^\[SENT\]') {
												Write-LogHost $output -ForegroundColor DarkGray
												# CRITICAL: Extract and store QueryId from SENT message for retry reuse
												if ($output -match 'QueryId:\s*([a-f0-9-]+)\)') {
													$extractedQueryId = $matches[1]
													$pt = $jobMeta[$job.Id]
													if ($pt -and $script:partitionStatus.ContainsKey($pt.Index)) {
														$script:partitionStatus[$pt.Index].QueryId = $extractedQueryId
													}
												}
											}
											elseif ($output -match '^\[ERROR\]') {
												Write-LogHost $output -ForegroundColor Red
												# Check for 401 in error messages
												if ($output -match '401|Unauthorized') {
													$script:AuthFailureDetected = $true
													if (-not $script:Auth401MessageShown) {
														$script:Auth401MessageShown = $true
														Write-LogHost "  [AUTH] 401 Unauthorized detected in job output" -ForegroundColor Red
													}
													# CRITICAL: Mark this partition as Failed for retry after re-auth
													$pt = $jobMeta[$job.Id]
													if ($pt -and $script:partitionStatus.ContainsKey($pt.Index)) {
														Set-PartitionFailure -Index $pt.Index -Stage 'AUTH' -Reason '401'
														$script:partitionStatus[$pt.Index].LastError = '401 Unauthorized - token expired'
													}
													break  # IMMEDIATE EXIT
												}
											}
											elseif ($output -match '^\[403-CREATE\]|^\[403-FETCH\]') {
												Write-LogHost $output -ForegroundColor Yellow
											}
											elseif ($output -match '^\[PROGRESS\]') {
												# Silent: extract page count, do not display
												if ($output -match '\[PROGRESS\] P(\d+)/\d+ pg(\d+)') {
													$pIdx = [int]$matches[1]; $pg = [int]$matches[2]
													if (-not $script:partitionPageCounts.ContainsKey($pIdx) -or $pg -gt $script:partitionPageCounts[$pIdx]) {
														$script:partitionPageCounts[$pIdx] = $pg
													}
												}
											}
											elseif ($output -match '^\[NETWORK\]') {
												# Also extract page count from NETWORK error messages
												if ($output -match 'Partition (\d+)/\d+ Page (\d+)') {
													$pIdx = [int]$matches[1]; $pg = [int]$matches[2]
													if (-not $script:partitionPageCounts.ContainsKey($pIdx) -or $pg -gt $script:partitionPageCounts[$pIdx]) {
														$script:partitionPageCounts[$pIdx] = $pg
													}
												}
												Write-LogHost $output -ForegroundColor Yellow
											}
											elseif ($output -match '^\[STATUS\] Query running') {
												Write-LogHost ($output -replace '^\[STATUS\]\s*','') -ForegroundColor Yellow
											}
											elseif ($output -match '^\[SUCCESS\]') {
												Write-LogHost ($output -replace '^\[SUCCESS\]\s*','') -ForegroundColor Green
											}
											}
										}
										elseif ($output -isnot [string]) {
											# DEFENSIVE: Detect SplitRequired objects and treat as Failed for retry
											if ($output.SplitRequired -eq $true) {
												$pt = $jobMeta[$job.Id]
												if ($pt -and $script:partitionStatus.ContainsKey($pt.Index)) {
													Set-PartitionFailure -Index $pt.Index -Stage 'FETCH' -Reason 'STILL_RUNNING'
													$script:partitionStatus[$pt.Index].LastError = "Query still running after $([Math]::Round($output.ElapsedMinutes,1)) min - queued for retry"
													Write-LogHost "  [RETRY-QUEUE] Partition $($pt.Index)/$($pt.Total) - query still processing after $([Math]::Round($output.ElapsedMinutes,1)) min, queued for retry" -ForegroundColor Yellow
												}
												[void]$script:processedJobIds.Add($job.Id)
												continue
											}
											# This is a result object - mark partition as Complete and collect logs immediately
											$pt = $jobMeta[$job.Id]
											if ($pt) {
												
												if ($script:partitionStatus.ContainsKey($pt.Index)) {
													$currentStatus = $script:partitionStatus[$pt.Index].Status
													
													if ($currentStatus -ne 'Complete') {
														if ([string]::IsNullOrWhiteSpace([string]$output.QueryId) -and [int]($output.RetrievedCount ?? 0) -le 0) {
															Set-PartitionFailure -Index $pt.Index -Stage 'CREATE' -Reason 'EMPTY_QUERYID'
															$script:partitionStatus[$pt.Index].LastError = 'ThreadJob returned empty QueryId with zero records (query was not created/sent)'
															Write-LogHost "  [DATA-CHECK] Partition $($pt.Index) returned empty QueryId with 0 records - marked Failed for retry" -ForegroundColor Yellow
															[void]$script:processedJobIds.Add($job.Id)
															continue
														}

														$script:partitionStatus[$pt.Index].Status = 'Complete'
														$script:partitionStatus[$pt.Index].QueryId = $output.QueryId
														$script:partitionStatus[$pt.Index].RecordCount = ($output.RetrievedCount ?? 0)
														
														# Fallback: emit SUCCESS message if the original [SUCCESS] string was already consumed
														$successKey = "$($job.Id):SUCCESS"
														if (-not $script:shownJobMessages.ContainsKey($successKey)) {
															$script:shownJobMessages[$successKey] = $true
															Write-LogHost "Query succeeded - Partition $($pt.Index)/$($pt.Total) - Query ID: $($output.QueryId) - Retrieved $($output.RetrievedCount ?? 0) records" -ForegroundColor Green
														}
														
														# Activate streaming export if thread persisted data to disk (thread-side save path: Logs returned empty)
														if ($output.ThreadSavedToDisk -and $script:memoryFlushEnabled -and -not $script:memoryFlushed) {
															$script:memoryFlushed = $true
															Write-LogHost "  [STREAM] Thread-side JSONL persistence active - parallel partition data is being written to disk (normal for parallel partition fetches; not a memory-pressure event)" -ForegroundColor DarkCyan
														}
														
														# Add logs to collection (skip if memory flush enabled - using JSONL only)
														# Receive-Job can only be called once, so we must collect now
														if ($output.Logs -and $output.Logs.Count -gt 0 -and -not $script:memoryFlushEnabled) {
															$allLogs.AddRange($output.Logs)
														}
														
														# Update aggregate metrics only (per-record activity breakdown happens in explosion phase)
														# CRITICAL: Do NOT iterate through logs here - it blocks the monitoring loop
														try {
															$script:metrics.QueryMs += [int]$output.ElapsedMs
															$script:metrics.TotalRecordsFetched += [int]$output.RetrievedCount
														} catch {}
														
														# Mark partition complete in checkpoint (so Ctrl+C shows accurate count)
														if ($script:CheckpointEnabled) {
															Save-Checkpoint -PartitionIndex $pt.Index -QueryId $output.QueryId -State 'Completed' -RecordCount $output.RetrievedCount
														}
														
														# INCREMENTAL SAVE: Write partition records to disk immediately (prevents data loss on auth failure)
														if ($output.Logs -and $output.Logs.Count -gt 0) {
															try {
																$incrementalDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
																if (-not (Test-Path $incrementalDir)) {
																	New-Item -ItemType Directory -Path $incrementalDir -Force | Out-Null
																}
																$incrementalFile = Join-Path $incrementalDir "Part$($pt.Index)_${global:ScriptRunTimestamp}_qid-$($output.QueryId)_$($output.RetrievedCount)records.jsonl"
																# Write as JSON Lines (NDJSON) - one record per line for recoverability
																$output.Logs | ForEach-Object { $_ | ConvertTo-Json -Depth 10 -Compress } | Out-File -FilePath $incrementalFile -Encoding utf8 -Force
																Write-LogHost "  [SAVE] Partition $($pt.Index): $($output.RetrievedCount) records saved to disk" -ForegroundColor DarkGreen
																
																# Clear reference to allow GC (critical for memory management)
																$output.Logs = $null
																
																# MEMORY MANAGEMENT: Mark if we're using JSONL-only mode
																if ($script:memoryFlushEnabled -and -not $script:memoryFlushed) {
																	$script:memoryFlushed = $true
																	Write-LogHost "  [STREAM] JSONL-backed streaming persistence active - partition records written to disk (streaming export at end; routine for parallel-partition fetches, not a memory-pressure event)" -ForegroundColor DarkCyan
																}
															} catch {
																Write-LogHost "  [WARN] Failed to save incremental data for Partition $($pt.Index): $($_.Exception.Message)" -ForegroundColor Yellow
															}
														}
														
														# Mark job as processed since we've already collected its output
														[void]$script:processedJobIds.Add($job.Id)
													} else {
													}
												} else {
												}
											} else {
											}
										}
									}
								}
							} catch {
								# Silently continue if we can't receive from a job
							}
						}
						
						# Check if 60 seconds have passed since last status update (or first iteration)
						$elapsedSinceLastUpdate = ((Get-Date) - $lastStatusUpdate).TotalSeconds
						if ($firstStatus -or $elapsedSinceLastUpdate -ge $StatusIntervalSeconds) {
							# Count partitions by status (EXCLUDE 'Subdivided' parent partitions)
							$activeStatuses = @($script:partitionStatus.Values) | Where-Object { $_.Status -ne 'Subdivided' }
							$completedPartitions = @($activeStatuses | Where-Object { $_.Status -eq 'Complete' }).Count
							$jobCreatedPartitions = @($activeStatuses | Where-Object { $_.Status -eq 'JobCreated' }).Count
							$notStartedPartitions = @($activeStatuses | Where-Object { $_.Status -eq 'NotStarted' }).Count
							$failedCount = @($activeStatuses | Where-Object { $_.Status -eq 'Failed' }).Count
							
							# Calculate remaining and total (only active partitions)
							$remainingToComplete = $jobCreatedPartitions + $notStartedPartitions
							$totalPartitions = @($activeStatuses).Count
							
							$statusLine = "[$(Get-Date -Format 'HH:mm:ss')] Total Queries: $($totalPartitions + $script:resumeCompletedOffset) | Completed: $($completedPartitions + $script:resumeCompletedOffset) | Remaining: $remainingToComplete"
							if ($failedCount -gt 0) {
								$statusLine += " | Failed: $failedCount"
							}
							if ($script:partitionPageCounts -and $script:partitionPageCounts.Count -gt 0) {
								$pageStr = ($script:partitionPageCounts.GetEnumerator() | Sort-Object Key | ForEach-Object { "P$($_.Key):$($_.Value.ToString('N0'))pg" }) -join ' '
								$statusLine += " | Pages $pageStr"
							}
							
							Write-LogHost $statusLine -ForegroundColor White
							
							$lastStatusUpdate = Get-Date
							$firstStatus = $false
						}
						
						# PROACTIVE TOKEN REFRESH (ALL auth modes): Refresh before expiration
						# Uses SharedAuthState.ExpiresOn to determine when refresh is needed
						# This prevents 401 errors during long-running job monitoring
						# Thread jobs read from SharedAuthState, so they get the fresh token automatically
						$refreshResult = Refresh-GraphTokenIfNeeded -BufferMinutes 5
						# CRITICAL: Use -is [string] check to avoid PowerShell coercion bug where $true -eq 'Quit' returns True
						if ($refreshResult -is [string] -and $refreshResult -eq 'Quit') {
							# User chose to quit at auth prompt - save checkpoint and exit gracefully
							if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
							Show-CheckpointExitMessage
							exit 0
						}
						
						# REACTIVE AUTH CHECK: If 401 detected, handle token refresh
						# Use AuthPromptInProgress as debounce to prevent multiple simultaneous auth prompts
						if ($script:AuthFailureDetected -and -not $script:AuthPromptInProgress) {
							$script:AuthPromptInProgress = $true  # Set debounce flag
							Write-LogHost ""
							Write-LogHost "  [AUTH] Authentication failure detected - pausing job monitoring" -ForegroundColor Red
							
							# AppRegistration mode: Automatically refresh token (silent, no prompt)
							# Interactive modes: Prompt user for re-authentication
							if ($script:AuthConfig.Method -eq 'AppRegistration' -and $script:AuthConfig.CanReauthenticate) {
								Write-LogHost "  [AUTH] Attempting automatic token refresh for AppRegistration..." -ForegroundColor Yellow
								$refreshResult = Invoke-TokenRefresh -Force
								
								if (-not $refreshResult.Success -or -not $refreshResult.NewToken) {
									Write-LogHost "  [AUTH] Automatic token refresh failed: $($refreshResult.Message)" -ForegroundColor Red
									Write-LogHost "  [AUTH] Cannot continue without valid authentication." -ForegroundColor Red
									if ($script:CheckpointEnabled) {
										Save-Checkpoint -Force
									}
									Write-LogHost "  Exiting due to authentication failure. Use -Resume to continue later." -ForegroundColor Yellow
									return
								}
								
								# CRITICAL: Update $accessToken with fresh token for retry phase
								$accessToken = $refreshResult.NewToken
								# CRITICAL: Update shared auth state so thread jobs see the fresh token
								$script:SharedAuthState.Token = $refreshResult.NewToken
								$script:SharedAuthState.ExpiresOn = (Get-Date).ToUniversalTime().AddMinutes(50)
								$script:SharedAuthState.LastRefresh = Get-Date
								Write-LogHost "  [AUTH] Token refreshed successfully" -ForegroundColor Green
								$script:AuthFailureDetected = $false
								$script:Auth401MessageShown = $false  # Reset for next auth failure cycle
								$script:AuthPromptInProgress = $false  # Reset debounce flag
							} else {
								# Interactive mode - prompt user
								$reauthResult = Invoke-TokenRefreshPrompt
								
								if ($reauthResult -eq 'Quit') {
									# User chose to quit - save checkpoint and exit gracefully
									if ($script:CheckpointEnabled) {
										Save-Checkpoint -Force
									}
									Write-LogHost "  Exiting due to user request. Use -Resume to continue later." -ForegroundColor Yellow
									return
								}
								
								# CRITICAL: Get fresh token after interactive reauth
								$accessToken = Get-GraphAccessToken
								if (-not $accessToken) {
									Write-LogHost "  [AUTH] FATAL: Could not obtain access token after re-authentication" -ForegroundColor Red
									if ($script:CheckpointEnabled) {
										Save-Checkpoint -Force
									}
									Write-LogHost "  Exiting due to token extraction failure. Use -Resume to continue later." -ForegroundColor Yellow
									return
								}
								Write-LogHost "  [AUTH] Fresh token obtained for retry phase" -ForegroundColor Green
								# CRITICAL: Update shared auth state so thread jobs see the fresh token
								$script:SharedAuthState.Token = $accessToken
								$script:SharedAuthState.ExpiresOn = (Get-Date).ToUniversalTime().AddMinutes(50)
								$script:SharedAuthState.LastRefresh = Get-Date
								# CRITICAL: Reset auth failure flags after successful interactive re-auth
								# Without this, old 401 errors in job buffers re-trigger the auth prompt
								$script:AuthFailureDetected = $false
								$script:Auth401MessageShown = $false
								$script:AuthPromptInProgress = $false  # Reset debounce flag
							}
							
							# Re-authenticated successfully - token updated for retry phase
							Write-LogHost "  [AUTH] Resuming job monitoring with fresh token" -ForegroundColor Green
							
							# Drain all job buffers to clear old 401 errors. Without this,
							# old errors in the buffers re-trigger auth detection on the
							# next loop iteration.
							foreach ($drainJob in $jobs) {
								if ($drainJob.State -ne 'Completed' -and $drainJob.State -ne 'Failed') {
									try {
										# Drain WITHOUT -Keep to clear the buffers
										$null = Receive-Job -Job $drainJob -ErrorAction SilentlyContinue
									} catch { }
								}
							}
							Write-LogHost "  [AUTH] Drained job buffers to clear old error messages" -ForegroundColor DarkGray
						}
						
						Start-Sleep -Milliseconds 500
					}
					
				# Process completed jobs and collect results
				$subdivisionOccurred = $false
				# CRITICAL: Check error stream - jobs with State='Completed' but errors should be treated as failures
				$completedNow = $jobs | Where-Object { $_.State -eq 'Completed' -and -not $script:processedJobIds.Contains($_.Id) -and $_.Error.Count -eq 0 }
					
					foreach ($job in $completedNow) {
						$res = $null
						try {
							# Receive all output from job (includes Write-Output debug messages)
							$allOutput = Receive-Job -Job $job -ErrorAction Stop
							
							# Filter output: PSCustomObject is the result, strings are debug messages
							$debugMessages = $allOutput | Where-Object { $_ -is [string] }
							$res = $allOutput | Where-Object { $_ -isnot [string] } | Select-Object -First 1
							
							# Display [SENT] messages to terminal, log all debug messages to file
							foreach ($debugMsg in $debugMessages) {
								# Show [SENT] messages in terminal with color (with deduplication)
								if ($debugMsg -match '^\[SENT\]') {
									$msgKey = "$($job.Id):$debugMsg"
									if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
										Write-LogHost $debugMsg -ForegroundColor DarkGray
										$script:shownJobMessages[$msgKey] = $true
									}
									# CRITICAL: Extract and store QueryId from SENT message for retry reuse
									if ($debugMsg -match 'QueryId:\s*([a-f0-9-]+)\)') {
										$extractedQueryId = $matches[1]
										$pt = $jobMeta[$job.Id]
										if ($pt -and $script:partitionStatus.ContainsKey($pt.Index)) {
											$script:partitionStatus[$pt.Index].QueryId = $extractedQueryId
										}
									}
								}
								
								$debugTimestamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'

								if ($debugMsg -match '^\[GRAPH-(WARN|ERROR)\]' -or $debugMsg -like 'Graph API Query Body*' -or $debugMsg -like 'API Stored Query Details*' -or $debugMsg -match '^\[NETWORK\]' -or $debugMsg -match '^\[ERROR\]') {
									Write-LogHost $debugMsg -ForegroundColor DarkGray
								}
							}
						} catch {
							Write-LogHost "  ✗ Error receiving job: $($_.Exception.Message)" -ForegroundColor Red
							
							# Mark as Failed for retry (job exceptions need explicit status update)
							$pt = $jobMeta[$job.Id]
							if ($pt -and $script:partitionStatus.ContainsKey($pt.Index)) {
								Set-PartitionFailure -Index $pt.Index -Stage 'RECEIVE' -Reason 'RECEIVE_ERROR'
								$script:partitionStatus[$pt.Index].LastError = $_.Exception.Message
								Write-LogHost "  [RETRY-QUEUE] Partition $($pt.Index)/$($pt.Total) marked as Failed for retry" -ForegroundColor Yellow
							}
							# Mark job as processed to avoid duplicate processing
							[void]$script:processedJobIds.Add($job.Id)
							continue  # Skip to next job - this one failed
						}
						
					$pt = $jobMeta[$job.Id]
					
					if ($null -ne $res) {
						# CHECK FOR SUBDIVISION SIGNAL: Job returned needs_subdivision status
						if ($res.Status -eq 'needs_subdivision') {
							# Defensive runaway guard: if this lineage has already been subdivided
							# $script:MaxSubdivisionLevel times and STILL reports the record limit,
							# stop subdividing (do NOT multiply further). Mark the window with a
							# DISTINCT 'SubdivisionLimit' state — not silently dropped, and not
							# conflated with the terminal create/fetch failure class. -Resume can
							# retry it later once the condition clears.
							$currentSubLevel = if ($pt.SubdivisionLevel) { [int]$pt.SubdivisionLevel } else { 0 }
							if ($currentSubLevel -ge $script:MaxSubdivisionLevel) {
								$winText = "$($pt.PStart.ToString('yyyy-MM-dd HH:mm')) to $($pt.PEnd.ToString('yyyy-MM-dd HH:mm')) UTC"
								Write-LogHost "" -ForegroundColor Red
								Write-LogHost "[SUBDIVISION-LIMIT] Partition $($pt.Index)/$($pt.Total) reached the maximum subdivision depth ($script:MaxSubdivisionLevel) and still exceeds the record limit." -ForegroundColor Red
								Write-LogHost "    Window: $winText" -ForegroundColor Red
								Write-LogHost "    This window was NOT collected this run. Re-run with -Resume to retry it once the condition clears, or narrow the run's date range for this window." -ForegroundColor Yellow
								if ($script:partitionStatus.ContainsKey($pt.Index)) {
									$script:partitionStatus[$pt.Index].Status = 'SubdivisionLimit'
									$script:partitionStatus[$pt.Index].RecordCount = 0
									$script:partitionStatus[$pt.Index].LastError = "Reached maximum subdivision depth ($script:MaxSubdivisionLevel) with the window still over the record limit"
								}
								[void]$script:processedJobIds.Add($job.Id)
								continue
							}
							Write-LogHost "[SUBDIVISION] Partition $($pt.Index)/$($pt.Total) requires subdivision - Preview count: $($res.PreviewCount)" -ForegroundColor Yellow
							
							# Calculate subdivision time windows
							$partitionSpan = $res.PartitionEnd - $res.PartitionStart
							$partitionHours = $partitionSpan.TotalHours
						
						# SMART SUBDIVISION: Analyze timestamp distribution in returned records
						# to calculate optimal subdivision size instead of just dividing by 2
						$subdivisionFactor = 2  # Default to half
						
						if ($res.Logs -and $res.Logs.Count -eq 10000) {
							try {
								# Get timestamps from returned records
								$timestamps = @()
								foreach ($log in $res.Logs) {
									if ($log.CreationTime) {
										$ts = script:Parse-DateSafe $log.CreationTime
										if ($ts) { $timestamps += $ts }
									}
								}
								
								if ($timestamps.Count -gt 100) {
									# Sort timestamps and find the last one (most recent in the 10k batch)
									$sortedTimestamps = $timestamps | Sort-Object
									$lastTimestamp = $sortedTimestamps[-1]
									$firstTimestamp = $sortedTimestamps[0]
									
									# Calculate how much of the partition timespan was covered by the 10k records
									$coveredSpan = ($lastTimestamp - $firstTimestamp).TotalHours
									$totalSpan = ($res.PartitionEnd - $res.PartitionStart).TotalHours
									
									if ($coveredSpan -gt 0 -and $coveredSpan -lt $totalSpan) {
										# Calculate records per hour for the covered span
										$recordsPerHour = 10000 / $coveredSpan
										
										# Calculate target hours to get ~8000 records (buffer below 10k)
										$targetHours = 8000 / $recordsPerHour
										
										# Calculate subdivision factor (but cap it to avoid tiny partitions)
										$minSubdivisionHours = 0.001389 * 24  # 2 minutes
										if ($targetHours -ge $minSubdivisionHours) {
											$subdivisionFactor = [Math]::Max(2, [Math]::Ceiling($totalSpan / $targetHours))
											Write-LogHost "  [SMART SUBDIVISION] Analyzed 10k records: covered $([Math]::Round($coveredSpan,2))h of $([Math]::Round($totalSpan,2))h span" -ForegroundColor Cyan
											Write-LogHost "  [SMART SUBDIVISION] Estimated $([Math]::Round($recordsPerHour,0)) records/hour → dividing by $subdivisionFactor instead of 2" -ForegroundColor Cyan
										}
									}
								}
							} catch {
								Write-LogHost "  [SMART SUBDIVISION] Timestamp analysis failed, using default subdivision: $_" -ForegroundColor Yellow
							}
						}
						
						# Calculate subdivision size
						$subPartitionHours = $partitionHours / $subdivisionFactor
						$subPartitionSpan = [TimeSpan]::FromHours($subPartitionHours)
						
						# Create sub-partitions (divide evenly based on calculated factor)
						$newSubPartitions = @()
						for ($i = 0; $i -lt $subdivisionFactor; $i++) {
							$subStart = $res.PartitionStart + ([TimeSpan]::FromHours($i * $subPartitionHours))
							$subEnd = if ($i -eq ($subdivisionFactor - 1)) {
								$res.PartitionEnd  # Last partition goes to the end
							} else {
								$res.PartitionStart + ([TimeSpan]::FromHours(($i + 1) * $subPartitionHours))
							}
							
							$newSubPartitions += [PSCustomObject]@{
								PStart = $subStart
								PEnd = $subEnd
								Index = $null
								Total = $null
								ParentIndex = $pt.Index
								SubdivisionLevel = if ($pt.SubdivisionLevel) { $pt.SubdivisionLevel + 1 } else { 1 }
							}
						}
						
						Write-LogHost "  Creating $($newSubPartitions.Count) sub-partitions:" -ForegroundColor DarkYellow
						foreach ($subPt in $newSubPartitions) {
							$subHours = ($subPt.PEnd - $subPt.PStart).TotalHours
							Write-LogHost "    $($subPt.PStart.ToString('yyyy-MM-dd HH:mm')) to $($subPt.PEnd.ToString('yyyy-MM-dd HH:mm')) ($([Math]::Round($subHours,2))h)" -ForegroundColor DarkYellow
						}
						
						# Add sub-partitions to partitions array
						$partitions += $newSubPartitions
						
						# Save old status data before re-indexing (indexed by old Index values)
						$oldStatusData = @{}
						foreach ($key in $script:partitionStatus.Keys) {
							$oldStatusData[$key] = $script:partitionStatus[$key]
						}
						
						# Re-index all partitions
						$newTotal = $partitions.Count
						for ($i = 0; $i -lt $partitions.Count; $i++) {
							$partitions[$i].Index = $i + 1
							$partitions[$i].Total = $newTotal
						}
						
						# Rebuild partition status dictionary with new indexes
						$script:partitionStatus = @{}
						$script:partitionPageCounts = @{}
						$script:jobOutputOffset = @{}
						foreach ($partition in $partitions) {
							# Find if this partition had existing status data (by object reference or parent index)
							$existingStatus = $null
							foreach ($oldStatus in $oldStatusData.Values) {
								if ([object]::ReferenceEquals($oldStatus.Partition, $partition)) {
									$existingStatus = $oldStatus
									break
								}
							}
							
							if ($existingStatus) {
								# Preserve existing status data but use new Index
								$script:partitionStatus[$partition.Index] = @{
									Partition = $partition
									AttemptNumber = $existingStatus.AttemptNumber
									QueryId = $existingStatus.QueryId
									QueryName = $existingStatus.QueryName
									Status = $existingStatus.Status
									LastError = $existingStatus.LastError
									RecordCount = $existingStatus.RecordCount
									ParentPartition = $existingStatus.ParentPartition
									SubdivisionReason = $existingStatus.SubdivisionReason
									LastFailureSignature = $existingStatus.LastFailureSignature
									ConsecutiveIdenticalFailures = $existingStatus.ConsecutiveIdenticalFailures
									IsTerminalFailure = $existingStatus.IsTerminalFailure
									LastFailureStage = $existingStatus.LastFailureStage
									LastFailureReason = $existingStatus.LastFailureReason
									# Carry durable uncertain-create state forward so a subdivided
									# partition never loses its no-re-POST guarantee.
									UncertainCreate = $existingStatus.UncertainCreate
									UncertainCreateInfo = $existingStatus.UncertainCreateInfo
								}
							} else {
								# New sub-partition - initialize fresh
								$script:partitionStatus[$partition.Index] = @{
									Partition = $partition
									AttemptNumber = 0
									QueryId = $null
									QueryName = $null
									Status = 'NotStarted'
									LastError = $null
									RecordCount = 0
									ParentPartition = $pt.Index
									LastFailureSignature = $null
									ConsecutiveIdenticalFailures = 0
									IsTerminalFailure = $false
									LastFailureStage = $null
									LastFailureReason = $null
									UncertainCreate = $false
									UncertainCreateInfo = $null
								}
							}
						}
						
						# Mark parent partition as Subdivided (now using new Index from re-indexed partition)
						$parentPartition = $partitions | Where-Object { [object]::ReferenceEquals($_, $pt) } | Select-Object -First 1
						if ($parentPartition -and $script:partitionStatus.ContainsKey($parentPartition.Index)) {
							$script:partitionStatus[$parentPartition.Index].Status = 'Subdivided'
							$script:partitionStatus[$parentPartition.Index].RecordCount = 0
							$script:partitionStatus[$parentPartition.Index].SubdivisionReason = "preview_count_$($res.PreviewCount)"
						}
						
						# Mark as processed to avoid duplicate handling
						[void]$script:processedJobIds.Add($job.Id)
						
						# Set flag to break out of inner loop and re-queue new sub-partitions
						$subdivisionOccurred = $true
						Write-LogHost "  [SUBDIV-DEBUG] After creating sub-partitions: Total partitions=$($partitions.Count)" -ForegroundColor Magenta
						break  # Break from the job processing loop to re-start with new sub-partitions
					}
					elseif ($res.TokenExpired -eq $true) {
						# Token expired inside the job — mark the partition for retry
						# with a fresh token.
						Write-LogHost "[TOKEN-RETRY] Partition $($pt.Index)/$($pt.Total) returned due to expired token - will retry with fresh token" -ForegroundColor Yellow
						
						# Reset partition status to allow retry
						if ($script:partitionStatus.ContainsKey($pt.Index)) {
							$script:partitionStatus[$pt.Index].Status = 'NotStarted'
							$script:partitionStatus[$pt.Index].LastError = 'Token expired - retry pending'
							# Preserve QueryId if present for retry reuse
							if ($res.QueryId) {
								$script:partitionStatus[$pt.Index].QueryId = $res.QueryId
							}
						}
						
						# Mark job as processed
						[void]$script:processedJobIds.Add($job.Id)
						
						# Set auth failure flag to trigger token refresh before retry
						$script:AuthFailureDetected = $true
					}
					elseif ($res.Status -eq 'visibility_failure') {
						# STRUCTURED VISIBILITY-FAILURE RECOVERY (the worker never creates or
						# replaces). The worker observed a 404 on the pinned version and RETURNED a
						# structured signal instead of throwing. The parent revalidates the retained
						# id through the shared decision layer (bounded same-id eventual-consistency
						# retry and then a read-only same-id GET on the alternate version). Only after
						# positively-confirmed absence does the parent attempt at-most-one replacement,
						# persisted to the checkpoint BEFORE the POST so a crash or resume can never
						# double-create. A recovered query is re-queued with its retained id and no
						# POST; records are decided independently and never marked complete-with-zero.
						$retainedId = if ($res.QueryId) { [string]$res.QueryId } elseif ($script:partitionStatus.ContainsKey($pt.Index)) { [string]$script:partitionStatus[$pt.Index].QueryId } else { $null }
						$entry = if ($script:partitionStatus.ContainsKey($pt.Index)) { $script:partitionStatus[$pt.Index] } else { $null }
						if ($entry) {
							Set-GraphAuditLifecycleFields -Entry $entry
							$entry.LastLifecycleHttpStatus = 404
						}
						$revalidated = $null
						if (-not [string]::IsNullOrWhiteSpace($retainedId)) {
							$revalidated = Get-GraphAuditQueryStatus -QueryId $retainedId
						}
						if ($null -ne $revalidated) {
							# Still visible (recovered on the pinned or the alternate version). Retain
							# the id and re-queue WITHOUT any POST; this is not counted as a failure.
							Write-LogHost "[VISIBILITY-RECOVER] Partition $($pt.Index)/$($pt.Total) - retained QueryId $retainedId is still visible (status '$($revalidated.Status)') - re-queued with the same id, no replacement" -ForegroundColor Cyan
							if ($entry) {
								$entry.QueryId = $retainedId
								$entry.Status = 'NotStarted'
								$entry.LastError = 'Visibility 404 recovered on revalidation - retained query re-queued'
								$entry.AlternateVersionChecked = $true
								if ($script:CheckpointEnabled) {
									Save-Checkpoint -PartitionIndex $pt.Index -QueryId $retainedId -State 'QueryCreated' -LifecycleState $entry
								}
							}
						}
						elseif ([string]::IsNullOrWhiteSpace($retainedId)) {
							# No retained id to revalidate or replace. Re-queue through the normal
							# create path (a null QueryId there triggers a duplicate-safe create).
							Write-LogHost "[VISIBILITY-ABSENT] Partition $($pt.Index)/$($pt.Total) - visibility failure with no retained QueryId - re-queued for a duplicate-safe create" -ForegroundColor Yellow
							Set-PartitionFailure -Index $pt.Index -Stage 'RECONCILE' -Reason 'QUERY-GONE'
						}
						else {
							# Positively confirmed unavailable on both versions.
							$alreadyAttempted = ($entry -and $entry.ContainsKey('ReplacementAttempted') -and $entry.ReplacementAttempted)
							if ($alreadyAttempted) {
								# Durable at-most-once guard: a replacement was already persisted. Never
								# create a second one; mark Failed (bounded by the terminal guard), never
								# complete-with-zero (which would silently drop the window).
								Write-LogHost "[VISIBILITY-ABSENT] Partition $($pt.Index)/$($pt.Total) - retained QueryId $retainedId confirmed absent and a replacement was already attempted - not creating a second replacement" -ForegroundColor Yellow
								if ($entry) { $entry.LastError = 'Query confirmed absent; replacement already attempted (at-most-once) - not replaced again' }
								Set-PartitionFailure -Index $pt.Index -Stage 'RECONCILE' -Reason 'QUERY-GONE'
							}
							else {
								# Persisting confirmed-absence + ReplacementAttempted is delegated to the
								# resolver via -PersistReplacementIntent, so it happens ONLY after the
								# resolver's own exact-name miss + confirmed absence, immediately before the
								# sole replacement POST - never before an Adopt/FailClosed/StillVisible
								# outcome that performs no POST.
								$__persistIntent = {
									param($__st)
									if ($entry) {
										$entry.QueryConfirmedAbsent = $true
										$entry.ReplacementAttempted = $true
										if ($script:CheckpointEnabled) {
											Save-Checkpoint -PartitionIndex $pt.Index -QueryId $retainedId -State 'QueryCreated' -LifecycleState $entry
										}
									}
								}
								# Duplicate-safe, at-most-one beta replacement after confirmed absence.
								$__rState = New-GraphAuditLifecycleState
								$__displayName = New-GraphAuditPartitionDisplayName -PStart $pt.PStart -PEnd $pt.PEnd -Index $pt.Index -Total $pt.Total -Activities $activities -RecordTypes $pt.RecordTypes -ServiceFilter $pt.ServiceFilter
								$__listReplace = {
									$__items = New-Object System.Collections.Generic.List[object]
									$__lu = Get-GraphAuditApiUri -Path 'queries'
									while ($__lu) {
										$__page = Invoke-MgGraphRequest -Method GET -Uri $__lu -ErrorAction Stop
										if ($__page -and $__page.value) {
											foreach ($__q in $__page.value) { $__items.Add(@{ id = $__q.id; displayName = $__q.displayName }) }
										}
										$__lu = $null
										if ($__page) { $__lu = $__page.'@odata.nextLink' }
									}
									return $__items.ToArray()
								}
								$__checkReplace = {
									param($Version, $Qid)
									try {
										$__u = "https://graph.microsoft.com/$Version/security/auditLog/queries/$Qid"
										$null = Invoke-MgGraphRequest -Method GET -Uri $__u -ErrorAction Stop
										return @{ HttpStatus = 200 }
									}
									catch {
										$__sc = $null
										if ($_.Exception.Response) {
											try { $__sc = [int]$_.Exception.Response.StatusCode.value__ } catch {}
											if ($null -eq $__sc) { try { $__sc = [int]$_.Exception.Response.StatusCode } catch {} }
										}
										if ($null -eq $__sc -and ($_.Exception.Message -match '404|Not Found')) { $__sc = 404 }
										return @{ HttpStatus = $__sc }
									}
								}
								$__createReplace = {
									param($Version, $Name)
									try {
										$__body = New-GraphAuditQueryRequest -PStart $pt.PStart -PEnd $pt.PEnd -Activities $activities -RecordTypes $pt.RecordTypes -ServiceFilter $pt.ServiceFilter
										$__body.displayName = $Name
										$__u = "https://graph.microsoft.com/$Version/security/auditLog/queries"
										$__resp = Invoke-MgGraphRequest -Method POST -Uri $__u -Body $__body -ErrorAction Stop
										$__id = $null
										if ($__resp) { $__id = $__resp.id }
										return @{ HttpStatus = 201; QueryId = $__id; Ambiguous = $false }
									}
									catch {
										$__sc = $null
										if ($_.Exception.Response) {
											try { $__sc = [int]$_.Exception.Response.StatusCode.value__ } catch {}
											if ($null -eq $__sc) { try { $__sc = [int]$_.Exception.Response.StatusCode } catch {} }
										}
										return @{ HttpStatus = $__sc; QueryId = $null; Ambiguous = ($__sc -eq 409) }
									}
								}
								$__repl = Resolve-GraphAuditDuplicateSafeQuery -DisplayName $__displayName -ExistingQueryId $retainedId -State $__rState -ListQueries $__listReplace -CheckItem $__checkReplace -CreateQuery $__createReplace -PersistReplacementIntent $__persistIntent
								if ($__repl -and $__repl.QueryId) {
									Write-LogHost "[VISIBILITY-REPLACE] Partition $($pt.Index)/$($pt.Total) - confirmed-absent query replaced (Action=$($__repl.Action); Reason=$($__repl.Reason)); new QueryId $($__repl.QueryId) - re-queued" -ForegroundColor Yellow
									if ($entry) {
										$entry.QueryId = [string]$__repl.QueryId
										$entry.ReplacementQueryId = [string]$__repl.QueryId
										$entry.Status = 'NotStarted'
										$entry.LastError = 'Confirmed-absent query replaced (at-most-once) - re-queued with new id'
										if ($script:CheckpointEnabled) {
											Save-Checkpoint -PartitionIndex $pt.Index -QueryId ([string]$__repl.QueryId) -State 'QueryCreated' -LifecycleState $entry
										}
									}
								}
								else {
									Write-LogHost "[VISIBILITY-REPLACE] Partition $($pt.Index)/$($pt.Total) - replacement not created (Action=$($__repl.Action); Reason=$($__repl.Reason)) - marked Failed for bounded retry" -ForegroundColor Yellow
									if ($entry) { $entry.LastError = "Confirmed absent; replacement not created (Action=$($__repl.Action); Reason=$($__repl.Reason))" }
									Set-PartitionFailure -Index $pt.Index -Stage 'RECONCILE' -Reason 'QUERY-GONE'
								}
							}
						}
						if ($res.Telemetry) { $script:telemetryData += $res.Telemetry }
						[void]$script:processedJobIds.Add($job.Id)
					}
					else {
						# NORMAL COMPLETION: Not a subdivision - process as completed query
						# Track whether data was actually added to collection
						$dataAddedToCollection = $false
						$recordsBeforeAdd = $allLogs.Count
						
						# Add logs to collection (skip when memory flush enabled - data goes to JSONL only)
						if ($res.Logs -and $res.Logs.Count -gt 0 -and -not $script:memoryFlushEnabled) {
							foreach ($log in $res.Logs) {
								[void]$allLogs.Add($log)
							}
							$dataAddedToCollection = ($allLogs.Count > $recordsBeforeAdd)
						}
						
						# Update partition status tracking - mark Complete if query succeeded (even with 0 records)
						if ($script:partitionStatus.ContainsKey($pt.Index)) {
							$queryName = New-GraphAuditPartitionDisplayName -PStart $pt.PStart -PEnd $pt.PEnd -Index $pt.Index -Total $pt.Total -Activities $activities -RecordTypes $pt.RecordTypes -ServiceFilter $pt.ServiceFilter
							$script:partitionStatus[$pt.Index].QueryName = $queryName
							$script:partitionStatus[$pt.Index].Status = 'Complete'
							$script:partitionStatus[$pt.Index].QueryId = $res.QueryId
							$script:partitionStatus[$pt.Index].RecordCount = $res.RetrievedCount
							
							# Thread the structured lifecycle fields into the completion checkpoint. A
							# genuine zero-record completion is an explicit, first-class terminal state
							# (ZeroRecordComplete) - distinct from a dropped or never-run window - so a
							# resume treats it as done rather than re-querying. Legacy-safe: fields are
							# added only if missing and the stored QueryId is never overwritten here.
							$__completeEntry = $script:partitionStatus[$pt.Index]
							Set-GraphAuditLifecycleFields -Entry $__completeEntry | Out-Null
							if ($res.QueryApiVersion) { $__completeEntry.QueryApiVersion = [string]$res.QueryApiVersion }
							$__completeEntry.ZeroRecordComplete = ([int]$res.RetrievedCount -eq 0)
							
							# CHECKPOINT: Save Completed state - this partition's data is now fully fetched
							if ($script:CheckpointEnabled) {
								Save-Checkpoint -PartitionIndex $pt.Index -QueryId $res.QueryId -State 'Completed' -LifecycleState $__completeEntry
							}
							
							# INCREMENTAL SAVE: Write partition records to disk immediately (prevents data loss on auth failure)
							if ($res.Logs -and $res.Logs.Count -gt 0) {
								try {
									$incrementalDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
									if (-not (Test-Path $incrementalDir)) {
										New-Item -ItemType Directory -Path $incrementalDir -Force | Out-Null
									}
									$incrementalFile = Join-Path $incrementalDir "Part$($pt.Index)_${global:ScriptRunTimestamp}_qid-$($res.QueryId)_$($res.RetrievedCount)records.jsonl"
									# Write as JSON Lines (NDJSON) - one record per line for recoverability
									$res.Logs | ForEach-Object { $_ | ConvertTo-Json -Depth 10 -Compress } | Out-File -FilePath $incrementalFile -Encoding utf8 -Force
									Write-LogHost "  [SAVE] Partition $($pt.Index): $($res.RetrievedCount) records saved to disk" -ForegroundColor DarkGreen
								} catch {
									Write-LogHost "  [WARN] Failed to save incremental data for Partition $($pt.Index): $($_.Exception.Message)" -ForegroundColor Yellow
								}
							}
						}
						
						# Collect telemetry if present
						if ($res.Telemetry) {
							$script:telemetryData += $res.Telemetry
						}
						
						# Show throttle retry summary if any retries occurred
						if ($res.Telemetry -and $res.Telemetry.ThrottleRetriesDuringCreation -and $res.Telemetry.ThrottleRetriesDuringCreation -gt 0) {
							Write-LogHost "  [!] Throttled during query creation: $($res.Telemetry.ThrottleRetriesDuringCreation) retry(s)" -ForegroundColor Yellow
						}
						
						try {
							$script:metrics.QueryMs += [int]$res.ElapsedMs
							$script:metrics.TotalRecordsFetched += [int]$res.RetrievedCount
							# Count records by their actual Operation value, not by query group name
							if ($res.Logs -and $res.Logs.Count -gt 0) {
								foreach ($log in $res.Logs) {
									# Handle both Operation (EOM format) and Operations (Graph API normalized format)
									$actualOperation = if ($log.Operation) { $log.Operation } elseif ($log.Operations) { $log.Operations } else { $null }
									if (-not [string]::IsNullOrWhiteSpace($actualOperation)) {
										if (-not $script:metrics.Activities.ContainsKey($actualOperation)) {
											$script:metrics.Activities[$actualOperation] = @{ Retrieved = 0; Structured = 0 }
										}
										$script:metrics.Activities[$actualOperation].Retrieved += 1
									}
								}
							}
						} catch {}
					}  # End of else block for normal completion
					

					# Capture diagnostic output for any failed jobs so payload logging is persisted
						$failedNow = $jobs | Where-Object { $_.State -eq 'Failed' -and (-not $script:processedJobIds.Contains($_.Id)) }
						foreach ($job in $failedNow) {
							$pt = $jobMeta[$job.Id]
							try {
								$failOutput = Receive-Job -Job $job -ErrorAction SilentlyContinue
							}
							catch {
								$failOutput = $null
							}

							if ($failOutput) {
								foreach ($msg in $failOutput) {
									if ($msg -is [string]) {
										$msgKey = "$($job.Id):$msg"
										if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
											$script:shownJobMessages[$msgKey] = $true
										}

										$debugTimestamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'

										if ($msg -match '^[\[]?(GRAPH-(WARN|ERROR)|ERROR|NETWORK|ATTEMPT|SENT)') {
											Write-LogHost $msg -ForegroundColor DarkGray
										}
										elseif ($msg -like 'Graph API Query Body*' -or $msg -like 'API Stored Query Details*') {
											Write-LogHost $msg -ForegroundColor DarkGray
										}
										else {
											Write-LogHost $msg -ForegroundColor DarkGray
										}
									}
								}
							}

							if ($pt -and $script:partitionStatus.ContainsKey($pt.Index)) {
								Set-PartitionFailure -Index $pt.Index -Stage 'RECONCILE' -Reason 'JOB_FAILED'
								$script:partitionStatus[$pt.Index].LastError = 'ThreadJob failed before completion'
							}

							[void]$script:processedJobIds.Add($job.Id)
						}
						
						# Handle jobs that completed with errors in error stream (State='Completed' but had Write-Error calls)
						$completedWithErrors = $jobs | Where-Object { $_.State -eq 'Completed' -and (-not $script:processedJobIds.Contains($_.Id)) -and $_.Error.Count -gt 0 }
						foreach ($job in $completedWithErrors) {
							$pt = $jobMeta[$job.Id]
							$errorMsg = ($job.Error | Select-Object -First 1).ToString()
							Write-LogHost "[ERROR-STREAM] Partition $($pt.Index)/$($pt.Total) - Job completed but had error: $errorMsg" -ForegroundColor Red
							
							# Capture diagnostic output from the job
							try {
								$errorOutput = Receive-Job -Job $job -ErrorAction SilentlyContinue
								if ($errorOutput) {
									foreach ($msg in $errorOutput) {
										if ($msg -is [string]) {
											$msgKey = "$($job.Id):$msg"
											if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
												$script:shownJobMessages[$msgKey] = $true
												if ($msg -match '^[\[]?(GRAPH-(WARN|ERROR)|ERROR|NETWORK|ATTEMPT|SENT)') {
													Write-LogHost $msg -ForegroundColor DarkGray
												}
											}
										}
									}
								}
							} catch {}
							
							# Mark partition as Failed for retry
							if ($pt -and $script:partitionStatus.ContainsKey($pt.Index)) {
								Set-PartitionFailure -Index $pt.Index -Stage 'RECONCILE' -Reason 'ERROR_STREAM'
								$script:partitionStatus[$pt.Index].LastError = $errorMsg
								Write-LogHost "  [RETRY-QUEUE] Partition $($pt.Index)/$($pt.Total) marked as Failed for retry due to error stream" -ForegroundColor Yellow
							}
							
							[void]$script:processedJobIds.Add($job.Id)
						}
							# Note: Logs already added to $allLogs earlier (moved above to validate data retrieval)
							
							# Update progress - in parallel mode, each partition = 1 unit of progress
							$script:progressState.Query.Current = [Math]::Min($script:progressState.Query.Current + 1, $script:progressState.Query.Total)
							Update-Progress -Status ("Partition {0}/{1} complete" -f $pt.Index, $pt.Total)
							$qc = $script:progressState.Query.Current
							$qt = $script:progressState.Query.Total
							Write-ProgressTick
						}
						
						# Mark job as processed to avoid duplicate processing
						[void]$script:processedJobIds.Add($job.Id)
					}
					
					# If subdivision occurred, break to queue new sub-partitions
					if ($subdivisionOccurred) {
						Write-LogHost "  Subdivision detected - queuing new sub-partitions..." -ForegroundColor Yellow
						# Don't wait for all jobs to complete, loop back now to queue subdivided partitions
						Write-LogHost "  [SUBDIV-DEBUG] After break, outer loop should check for pending NotStarted partitions" -ForegroundColor Magenta
						break
					}
					
				# All jobs completed - begin retry and reconciliation phase
				$finalStates = $jobs | Group-Object -Property State | ForEach-Object { "$($_.Name):$($_.Count)" }
				Write-LogHost "  Initial job execution complete. States: $($finalStates -join ', ')" -ForegroundColor DarkCyan
				
				# Mark any completed jobs as Complete if status wasn't already updated
				# (This handles jobs where result object wasn't captured but job completed successfully)
				# CRITICAL: Check for job errors first - ThreadJobs that throw exceptions still end up with State='Completed'
				$completedJobs = $jobs | Where-Object { $_.State -eq 'Completed' }
				foreach ($completedJob in $completedJobs) {
					$pt = $jobMeta[$completedJob.Id]
					if ($script:partitionStatus.ContainsKey($pt.Index)) {
						# Check if job produced errors (401, network failures, thrown exceptions)
						$jobErrors = @()
						try {
							$jobErrors = @($completedJob.ChildJobs | ForEach-Object { $_.Error } | Where-Object { $_ })
							# ThreadJobs store errors directly in .Error, not in ChildJobs
							if ($jobErrors.Count -eq 0 -and $completedJob.Error.Count -gt 0) {
								$jobErrors = @($completedJob.Error)
							}
						} catch {}
						
						if ($jobErrors.Count -gt 0 -and $script:partitionStatus[$pt.Index].Status -notin @('Complete', 'Subdivided')) {
							# Job completed WITH errors - mark as Failed for retry
							Set-PartitionFailure -Index $pt.Index -Stage 'RECONCILE' -Reason 'ERROR_STREAM'
							$script:partitionStatus[$pt.Index].LastError = $jobErrors[0].ToString()
							# QueryId preserved — query may still be valid on Purview for retry resume
							Write-LogHost "  [ERROR-CHECK] Partition $($pt.Index) job completed with errors - marked Failed for retry" -ForegroundColor Yellow
						}
						elseif ($script:partitionStatus[$pt.Index].Status -in @('NotStarted','JobCreated')) {
							# Validate that partition actually saved data before marking Complete
						# ThreadJobs that hit 504/network errors internally may complete with State='Completed'
						# but never save any data to disk. Check for JSONL file existence before trusting the job state.
							$hasDataOnDisk = $false
							try {
								$validationIncrDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
								if (Test-Path $validationIncrDir) {
									$partJsonl = Get-ChildItem -Path $validationIncrDir -Filter "Part$($pt.Index)_${global:ScriptRunTimestamp}_*.jsonl" -ErrorAction SilentlyContinue
									$hasDataOnDisk = ($partJsonl -and @($partJsonl).Count -gt 0)
								}
							} catch {}
							
							if ($hasDataOnDisk) {
								# JSONL file exists — partition genuinely completed
								$script:partitionStatus[$pt.Index].Status = 'Complete'
								# Job completed before monitoring loop polled it; result object was never
								# received, so ThreadSavedToDisk was never processed. Activate streaming export here.
								if ($script:memoryFlushEnabled -and -not $script:memoryFlushed) {
									$script:memoryFlushed = $true
									Write-LogHost "  [STREAM] Thread-side JSONL confirmed during reconciliation - streaming export will be used at flush (routine for parallel-partition runs)" -ForegroundColor DarkCyan
								}
							} else {
								# No JSONL file — job finished but never saved data (likely 504/auth failure swallowed internally)
								Set-PartitionFailure -Index $pt.Index -Stage 'RECONCILE' -Reason 'NO_DATA'
								$script:partitionStatus[$pt.Index].LastError = 'Job completed without saving data (no JSONL file found) - likely network/auth failure swallowed by retry logic'
								Write-LogHost "  [DATA-CHECK] Partition $($pt.Index) job completed but NO data saved to disk - marked Failed for retry" -ForegroundColor Yellow
							}
						}
						elseif ($script:partitionStatus[$pt.Index].Status -eq 'Complete') {
							$queryIdMissing = [string]::IsNullOrWhiteSpace([string]$script:partitionStatus[$pt.Index].QueryId)
							$recordCountZero = ([int]($script:partitionStatus[$pt.Index].RecordCount ?? 0) -le 0)
							if ($queryIdMissing -and $recordCountZero) {
								Set-PartitionFailure -Index $pt.Index -Stage 'RECONCILE' -Reason 'INVALID_COMPLETE'
								$script:partitionStatus[$pt.Index].LastError = 'Partition marked Complete but has empty QueryId and zero records'
								Write-LogHost "  [DATA-CHECK] Partition $($pt.Index) had invalid completion state (empty QueryId + 0 records) - marked Failed for retry" -ForegroundColor Yellow
							}
						}
					}
				}
				
				# Track failed jobs and update status
				$failedJobs = $jobs | Where-Object { $_.State -eq 'Failed' }
				foreach ($failedJob in $failedJobs) {
					$pt = $jobMeta[$failedJob.Id]
					if ($script:partitionStatus.ContainsKey($pt.Index)) {
						Set-PartitionFailure -Index $pt.Index -Stage 'RECONCILE' -Reason 'JOB_FAILED'
						try {
							$errorOutput = Receive-Job -Job $failedJob -ErrorAction SilentlyContinue 2>&1
							if ($errorOutput) {
								$lastErrorText = ($errorOutput | Out-String).Trim()
								$script:partitionStatus[$pt.Index].LastError = $lastErrorText
								
								# Log the actual error for diagnostics (useful level)
								Write-LogHost "    Partition $($pt.Index) error: $lastErrorText" -ForegroundColor DarkYellow
								
								# 401/Unauthorized failures don't count against retry limit (auth issue, not partition issue)
								# This ensures partitions can get full retry attempts after re-authentication
								if ($lastErrorText -match '401|Unauthorized') {
									Write-LogHost "  [AUTH] 401 error for Partition $($pt.Index) - will not count against retry limit" -ForegroundColor Yellow
								}
							}
						} catch {
							$script:partitionStatus[$pt.Index].LastError = $_.Exception.Message
						}
					}
				}					# RETRY LOGIC: Up to 4 additional attempts (5 total)
					$maxAttempts = 5
					$retryPass = 1
					
					while ($retryPass -lt $maxAttempts) {
						# Find partitions that need retry (Status = Failed or NotStarted only)
						$partitionsToRetry = @()
						foreach ($idx in $script:partitionStatus.Keys) {
							$status = $script:partitionStatus[$idx]
							# Only retry actual failures, not queries that completed with 0 records,
							# and never retry terminally-failed partitions.
							if ($status.Status -in @('Failed', 'NotStarted') -and -not $status.IsTerminalFailure) {
								if ($status.AttemptNumber -lt $maxAttempts) {
									$partitionsToRetry += $status.Partition
								}
							}
						}
						
						if ($partitionsToRetry.Count -eq 0) {
							Write-LogHost "  No partitions require retry" -ForegroundColor Green
							break
						}
						
						$retryPass++
						Write-LogHost "  [RETRY] Pass $retryPass/$maxAttempts - $($partitionsToRetry.Count) partition(s) need retry" -ForegroundColor Yellow
						
						# Cooldown before retry
						$cooldownSeconds = Get-Random -Minimum 30 -Maximum 60
						Write-LogHost "  Waiting $cooldownSeconds seconds before retry..." -ForegroundColor Gray
						Start-Sleep -Seconds $cooldownSeconds
						
					# CRITICAL: Refresh access token before partition retry
					# For AppRegistration mode, force re-authentication to get fresh token
					# For other modes, use Get-GraphAccessToken helper (HTTP primary)
					try {
						$tokenObtained = $false
						
						# Check if we can use forced re-authentication (AppRegistration only)
						if ($script:AuthConfig.CanReauthenticate -and $script:AuthConfig.Method -eq 'AppRegistration') {
							$refreshResult = Invoke-TokenRefresh -Force
							if ($refreshResult.Success -and $refreshResult.NewToken) {
								$accessToken = $refreshResult.NewToken
								$tokenObtained = $true
								Write-LogHost "  [TOKEN] Access token refreshed via re-authentication" -ForegroundColor Cyan
							} else {
								Write-LogHost "  [TOKEN] Re-authentication failed: $($refreshResult.Message)" -ForegroundColor Yellow
							}
						}
						
						# If AppRegistration refresh failed or using interactive auth, use helper
						if (-not $tokenObtained) {
							$newToken = Get-GraphAccessToken
							if ($newToken) {
								if ($newToken -ne $accessToken) {
									$accessToken = $newToken
									$tokenObtained = $true
									Write-LogHost "  [TOKEN] Fresh token obtained for retry phase" -ForegroundColor Cyan
								} else {
									# Token is the same - that's OK if we just re-authenticated
									$tokenObtained = $true
									Write-LogHost "  [TOKEN] Token validated (unchanged but valid)" -ForegroundColor Gray
								}
							}
						}
						
						# CRITICAL: Block retry if we can't get a valid token
						if (-not $tokenObtained) {
							Write-LogHost "  [TOKEN] FATAL: Cannot obtain valid access token for retry" -ForegroundColor Red
							Write-LogHost "  [TOKEN] This typically means the session has expired and requires re-authentication" -ForegroundColor Yellow
							
							# For interactive modes, prompt user to re-authenticate
							if ($script:AuthConfig.Method -in @('WebLogin', 'ExistingSession')) {
								Write-LogHost "  [TOKEN] Prompting for re-authentication..." -ForegroundColor Yellow
								$reauthResult = Invoke-TokenRefreshPrompt
								
								if ($reauthResult -eq 'Quit') {
									if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
									Write-LogHost "  Exiting due to user request. Use -Resume to continue later." -ForegroundColor Yellow
									return
								}
								
								# Try getting token again after reauth
								$accessToken = Get-GraphAccessToken
								if (-not $accessToken) {
									Write-LogHost "  [TOKEN] FATAL: Still cannot obtain token after re-authentication" -ForegroundColor Red
									if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
									Write-LogHost "  Exiting due to token extraction failure. Use -Resume to continue later." -ForegroundColor Yellow
									return
								}
								Write-LogHost "  [TOKEN] Fresh token obtained after re-authentication" -ForegroundColor Green
							} else {
								# AppRegistration mode with no token - fatal error
								if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
								Write-LogHost "  Exiting due to authentication failure. Use -Resume to continue later." -ForegroundColor Yellow
								return
							}
						}
					} catch {
						Write-LogHost "  [TOKEN] Error during token refresh: $($_.Exception.Message)" -ForegroundColor Red
						# Don't proceed with potentially expired token
						if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
						Write-LogHost "  Exiting due to token error. Use -Resume to continue later." -ForegroundColor Yellow
						return
					}
						
						# Create retry jobs
						$retryJobs = @()
						$retryJobMeta = @{}
						$retryMaxConcurrency = [Math]::Min($maxConcurrentPartitions, 3)
						Write-LogHost "  [RETRY] Using reduced retry concurrency: $retryMaxConcurrency (initial phase: $maxConcurrentPartitions)" -ForegroundColor DarkCyan

						# --- Parent-side query creation pre-pass (bounded parallel, retry phase) ---
						# A retry partition that never obtained a query id has nothing to reuse.
						# Create it here in bounded parallel under the reduced retry bound so its
						# status QueryId is populated before the retry worker launches. A creation
						# failure is recorded so no worker is launched for that partition this pass.
						$retryCreateFailed = [System.Collections.Generic.HashSet[int]]::new()
						$retryNeedCreate = New-Object System.Collections.Generic.List[object]
						foreach ($cp in $partitionsToRetry) {
							# Never re-create a durable uncertain-create partition: a possibly-accepted
							# first POST is resolved READ-ONLY on resume, never by a second POST here.
							if ($script:partitionStatus.ContainsKey($cp.Index) -and $script:partitionStatus[$cp.Index].UncertainCreate) { continue }
							if (-not ($script:partitionStatus.ContainsKey($cp.Index) -and $script:partitionStatus[$cp.Index].QueryId)) {
								[void]$retryNeedCreate.Add($cp)
							}
						}
						if ($retryNeedCreate.Count -gt 0) {
							$retryCreateBound = [Math]::Max(1, [int]$retryMaxConcurrency)
							Write-LogHost "  [PARENT-CREATE] Creating $($retryNeedCreate.Count) retry partition query(ies) in bounded parallel (limit $retryCreateBound)..." -ForegroundColor DarkCyan
							# Refresh the token before the retry create pre-pass so every queued and
							# retrying create job reads a current token from the shared auth state.
							$retryCreateRefresh = Refresh-GraphTokenIfNeeded -BufferMinutes 5
							if ($retryCreateRefresh -is [string] -and $retryCreateRefresh -eq 'Quit') {
								if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
								Show-CheckpointExitMessage
								exit 0
							}
							$retryCreateMap = Invoke-PaxParentQueryCreation -Partitions $retryNeedCreate.ToArray() -ThrottleLimit $retryCreateBound -Activities $activities -MaxNetworkOutageMinutes $MaxNetworkOutageMinutes
							# A token quit or refresh error during creation fails the pass closed before
							# any partition is persisted: enter the graceful authentication-exit path so
							# nothing is recorded as created off a quit/error decision (resume re-runs the
							# pre-create reconcile, which adopts an already-created query without a
							# duplicate POST).
							if ($retryCreateMap['__AuthQuit']) {
								# Persist any query the pool actually created before the quit AND mark the
								# still-in-flight partitions durable-uncertain, so a known QueryId is never
								# discarded and a possibly-accepted in-flight POST is reconciled read-only on
								# resume. A user-driven quit stays a graceful (exit 0) checkpoint-and-resume.
								Save-PaxInterruptedCreatePool -CreateMap $retryCreateMap -Requested $retryNeedCreate -Activities $activities -Phase 'retry'
								Write-LogHost "  [PARENT-CREATE] Authentication quit requested during query creation - completed persisted, in-flight marked uncertain, saving checkpoint and exiting (use -Resume to continue)" -ForegroundColor Yellow
								if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
								Show-CheckpointExitMessage
								exit 0
							}
							if ($retryCreateMap['__RefresherError']) {
								# Same durable persistence as the quit path, but a token-refresh EXCEPTION is a
								# failure, not a user decision: after persisting completed + in-flight-uncertain
								# it terminates NONZERO through the established fatal-exit machinery
								# ($script:GenericFatal -> exit 1) so automation sees the run did not succeed.
								Save-PaxInterruptedCreatePool -CreateMap $retryCreateMap -Requested $retryNeedCreate -Activities $activities -Phase 'retry'
								Write-LogHost "  [PARENT-CREATE] Token refresh error during query creation ($($retryCreateMap['__RefresherError'])) - completed persisted, in-flight marked uncertain, saving checkpoint and exiting NONZERO (use -Resume to continue)" -ForegroundColor Red
								$script:GenericFatal = $true
								if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
								Show-CheckpointExitMessage
								exit 1
							}
							foreach ($cp in $retryNeedCreate) {
								$cr = $retryCreateMap[[int]$cp.Index]
								if ($cr -and $cr.QueryId) {
									$cp | Add-Member -NotePropertyName 'StoredQueryId' -NotePropertyValue ([string]$cr.QueryId) -Force
									$script:partitionStatus[$cp.Index].QueryId = [string]$cr.QueryId
									$script:partitionStatus[$cp.Index].QueryApiVersion = $cr.Version
									$script:partitionStatus[$cp.Index].LifecycleOperation = 'Create'
									if ($script:CheckpointEnabled) {
										Save-Checkpoint -PartitionIndex $cp.Index -QueryId ([string]$cr.QueryId) -State 'QueryCreated' -LifecycleState $script:partitionStatus[$cp.Index]
									}
									Write-LogHost "  [PARENT-CREATE] Partition $($cp.Index)/$($cp.Total) query created (QueryId: $($cr.QueryId))" -ForegroundColor DarkCyan
								} else {
									$cat = if ($cr) { [string]$cr.FailureCategory } else { 'NotCreated' }
									[void]$retryCreateFailed.Add([int]$cp.Index)
									if ($cat -eq 'UncertainCreateUnresolved') {
										# A first POST whose acceptance could not be proven is NEVER re-POSTed.
										# Persist durable uncertain-create state so a resume routes this
										# partition to a READ-ONLY reconcile instead of a duplicate create.
										# Deliberately NOT Set-PartitionFailure: not marked Failed, never requeued.
										$script:partitionStatus[$cp.Index].UncertainCreate = $true
										$script:partitionStatus[$cp.Index].UncertainCreateInfo = @{
											displayName = New-GraphAuditPartitionDisplayName -PStart $cp.PStart -PEnd $cp.PEnd -Index $cp.Index -Total $cp.Total -Activities $activities -RecordTypes $cp.RecordTypes -ServiceFilter $cp.ServiceFilter
											fingerprint = New-GraphAuditQueryFingerprint -PStart $cp.PStart -PEnd $cp.PEnd -Activities $activities -RecordTypes $cp.RecordTypes -ServiceFilter $cp.ServiceFilter
											pStart      = $cp.PStart.ToString('o')
											pEnd        = $cp.PEnd.ToString('o')
											attempt     = [int]$script:partitionStatus[$cp.Index].AttemptNumber
											phase       = 'retry'
										}
										$script:partitionStatus[$cp.Index].LastError = "Parent-side query creation uncertain - durable reconcile pending (category: $cat)"
										if ($script:CheckpointEnabled) {
											Save-Checkpoint -PartitionIndex $cp.Index -State 'UncertainCreate' -LifecycleState $script:partitionStatus[$cp.Index]
										}
										Write-LogHost "  [PARENT-CREATE] Partition $($cp.Index)/$($cp.Total) create uncertain (category: $cat) - persisted for read-only reconcile, no re-POST, retry worker not launched this pass" -ForegroundColor Yellow
									} else {
										Set-PartitionFailure -Index $cp.Index -Stage 'CREATE' -Reason $cat
										$script:partitionStatus[$cp.Index].LastError = "Parent-side query creation failed (category: $cat)"
										$diag = "HTTP $($cr.HttpStatus) | client-request-id: $($cr.ClientRequestId) | request-id: $($cr.RequestId)"
										Write-LogHost "  [PARENT-CREATE] Partition $($cp.Index)/$($cp.Total) creation failed (category: $cat; $diag) - retry worker not launched this pass" -ForegroundColor Yellow
										if ($cr.ResponseBody) { Write-LogHost "    Graph response: $($cr.ResponseBody)" -ForegroundColor DarkYellow }
									}
								}
							}
						}

						foreach ($pt in $partitionsToRetry) {
							# Skip launching a retry worker for any partition whose parent-side
							# creation failed this pass; it has no query id to reuse.
							if ($retryCreateFailed.Contains([int]$pt.Index)) { continue }
							$script:partitionStatus[$pt.Index].AttemptNumber++
							$script:partitionStatus[$pt.Index].Status = 'NotStarted'  # Reset for retry
							
							Write-LogHost "  [RETRY] Attempt $($script:partitionStatus[$pt.Index].AttemptNumber)/$maxAttempts for Partition $($pt.Index)/$($pt.Total)" -ForegroundColor Yellow
							
							# Re-create the job using the same scriptblock
							# CRITICAL: Use $graphResultSize (0 for Graph API = unlimited) instead of $ResultSize (10000)
							# Pass existing QueryId if available (retry/resume of an already-created query).
							$existingQueryId = $script:partitionStatus[$pt.Index].QueryId
							# Structured retry control: NEVER clear an existing QueryId based on error
							# TEXT. A single 404 (or any diagnostic LastError string) is not proof the
							# query is absent - portal-completed queries were observed returning 404 on
							# one API version while remaining fully retrievable on the pinned version,
							# and eventual consistency can briefly 404 a freshly-created query. Reusing
							# the QueryId lets the pinned proven-lifecycle version re-poll and fetch the
							# already-completed server-side query instead of creating a duplicate. The
							# parent pre-pass creates any missing query before this retry launch, so a
							# partition that reaches launch always carries a QueryId to reuse. Partitions
							# that stay unretrievable are bounded by the consecutive-failure terminal guard
							# ($script:MaxConsecutiveIdenticalFailures), not by clearing the ID, so no
							# duplicate replacement query is ever created while the original ID remains.
							# LastError is diagnostic-only and no longer controls retry.
							if ($existingQueryId) {
								Write-LogHost "    [REUSE] Reusing existing QueryId: $existingQueryId (retry reuses the created query; no duplicate is created)" -ForegroundColor Cyan
							}
							# The worker polls and fetches on the SAME version the query was created on.
							$effectiveApiVersion = if ($script:partitionStatus[$pt.Index].QueryApiVersion) { $script:partitionStatus[$pt.Index].QueryApiVersion } else { $script:GraphAuditApiVersion }
							$job = Start-ThreadJob -ThrottleLimit $retryMaxConcurrency -ScriptBlock $queryJobScriptBlock -ArgumentList $pt.PStart, $pt.PEnd, $activities, $graphResultSize, $script:targetUsers, $pt.Index, $pt.Total, $script:SharedAuthState, $pt, $MaxNetworkOutageMinutes, $effectiveApiVersion, $script:LogFile, $existingQueryId, $threadIncrementalDir, $threadRunTimestamp, $threadMemoryFlushEnabled, $script:QueryObservations
							$retryJobs += $job
							$retryJobMeta[$job.Id] = $pt
						}
						
						while (($retryJobs | Where-Object { $_.State -in 'Running','NotStarted' }).Count -gt 0) {
							foreach ($job in $retryJobs) {
								try {
									$jobOutput = Receive-Job -Job $job -ErrorAction SilentlyContinue
									if ($jobOutput) {
										foreach ($output in $jobOutput) {
											if ($output -is [string] -and $output -match '^\[SENT\]') {
												$msgKey = "$($job.Id):$output"
												if (-not $script:shownJobMessages.ContainsKey($msgKey)) {
													Write-LogHost $output -ForegroundColor DarkGray
													$script:shownJobMessages[$msgKey] = $true
												}
												# CRITICAL: Extract and store QueryId from SENT message for retry reuse
												if ($output -match 'QueryId:\s*([a-f0-9-]+)\)') {
													$extractedQueryId = $matches[1]
													$pt = $retryJobMeta[$job.Id]
													if ($pt -and $script:partitionStatus.ContainsKey($pt.Index)) {
														$script:partitionStatus[$pt.Index].QueryId = $extractedQueryId
													}
												}
											}
										}
									}
								} catch {}
							}
							Start-Sleep -Milliseconds 500
						}
						
						# Check for retry jobs that completed but have errors in error stream
						# These need to be marked Failed so they get re-queued (mirrors initial pass logic)
						foreach ($job in $retryJobs) {
							if ($job.State -eq 'Completed' -and $job.Error.Count -gt 0) {
								$pt = $retryJobMeta[$job.Id]
								$errorText = ($job.Error | Out-String).Trim()
								Write-LogHost "[ERROR-STREAM] Retry Partition $($pt.Index)/$($pt.Total) - Job completed but had error: $errorText" -ForegroundColor Yellow
								if ($script:partitionStatus.ContainsKey($pt.Index)) {
									Set-PartitionFailure -Index $pt.Index -Stage 'RECONCILE' -Reason 'ERROR_STREAM'
									$script:partitionStatus[$pt.Index].LastError = $errorText
									Write-LogHost "  [RETRY-QUEUE] Partition $($pt.Index)/$($pt.Total) marked as Failed for next retry pass due to error stream" -ForegroundColor Yellow
								}
							}
						}
						
						# Process retry job results
						foreach ($job in $retryJobs) {
							$pt = $retryJobMeta[$job.Id]
							
							# Skip jobs already marked Failed by error-stream check above
							if ($script:partitionStatus.ContainsKey($pt.Index) -and $script:partitionStatus[$pt.Index].Status -eq 'Failed') {
								continue
							}
							
							if ($job.State -eq 'Completed') {
								try {
								$allOutput = Receive-Job -Job $job -ErrorAction Stop
								$res = $allOutput | Where-Object { $_ -isnot [string] } | Select-Object -First 1
								
								if ($null -ne $res -and $script:partitionStatus.ContainsKey($pt.Index)) {
									if ([string]::IsNullOrWhiteSpace([string]$res.QueryId) -and [int]($res.RetrievedCount ?? 0) -le 0) {
										Set-PartitionFailure -Index $pt.Index -Stage 'CREATE' -Reason 'EMPTY_QUERYID'
										$script:partitionStatus[$pt.Index].LastError = 'Retry ThreadJob returned empty QueryId with zero records (query was not created/sent)'
										Write-LogHost "  [DATA-CHECK] Retry Partition $($pt.Index) returned empty QueryId with 0 records - marked Failed for next retry" -ForegroundColor Yellow
										continue
									}

									$script:partitionStatus[$pt.Index].QueryId = $res.QueryId
									$script:partitionStatus[$pt.Index].QueryName = New-GraphAuditPartitionDisplayName -PStart $pt.PStart -PEnd $pt.PEnd -Index $pt.Index -Total $pt.Total -Activities $activities -RecordTypes $pt.RecordTypes -ServiceFilter $pt.ServiceFilter
									$script:partitionStatus[$pt.Index].RecordCount = $res.RetrievedCount
									$script:partitionStatus[$pt.Index].Status = 'Complete'
									
									Write-LogHost "  Retry successful for Partition $($pt.Index)/$($pt.Total): $($res.RetrievedCount) records" -ForegroundColor Green										# Add to allLogs
									if ($res.ThreadSavedToDisk -and $script:memoryFlushEnabled -and -not $script:memoryFlushed) {
										$script:memoryFlushed = $true
										Write-LogHost "  [STREAM] Thread-side JSONL persistence active - parallel partition data is being written to disk (normal for parallel partition fetches; not a memory-pressure event)" -ForegroundColor DarkCyan
									}

									# Add to allLogs
										if ($res.Logs -and $res.Logs.Count -gt 0) {
											foreach ($log in $res.Logs) {
												[void]$allLogs.Add($log)
											}
											
											# INCREMENTAL SAVE: Write retry partition records to disk immediately to prevent
											# data loss on subsequent auth failures.
											try {
												$incrementalDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
												if (-not (Test-Path $incrementalDir)) {
													New-Item -ItemType Directory -Path $incrementalDir -Force | Out-Null
												}
												$incrementalFile = Join-Path $incrementalDir "Part$($pt.Index)_${global:ScriptRunTimestamp}_qid-$($res.QueryId)_$($res.RetrievedCount)records.jsonl"
												# Write as JSON Lines (NDJSON) - one record per line for recoverability
												$res.Logs | ForEach-Object { $_ | ConvertTo-Json -Depth 10 -Compress } | Out-File -FilePath $incrementalFile -Encoding utf8 -Force
												Write-LogHost "  [SAVE] Retry Partition $($pt.Index): $($res.RetrievedCount) records saved to disk" -ForegroundColor DarkGreen
											} catch {
												Write-LogHost "  [WARN] Failed to save incremental data for Retry Partition $($pt.Index): $($_.Exception.Message)" -ForegroundColor Yellow
											}
										}
										
										# Update checkpoint for retry success
										if ($script:CheckpointEnabled) {
											Save-Checkpoint -PartitionIndex $pt.Index -QueryId $res.QueryId -State 'Completed' -RecordCount $res.RetrievedCount
										}
									}
								} catch {
									Write-LogHost "  ✗ Retry failed for Partition $($pt.Index)/$($pt.Total): $($_.Exception.Message)" -ForegroundColor Red
									if ($script:partitionStatus.ContainsKey($pt.Index)) {
										$isAuthFailure = Test-TransientAuthSignal -Text $_.Exception.Message
										Set-PartitionFailure -Index $pt.Index -Stage $(if ($isAuthFailure) { 'AUTH' } else { 'RETRY' }) -Reason $(if ($isAuthFailure) { '401' } else { 'EXCEPTION' })
										$script:partitionStatus[$pt.Index].LastError = $_.Exception.Message

										# Genuine transient-auth failures don't count against retry limit (auth issue, not partition issue)
										if ($isAuthFailure) {
											$script:partitionStatus[$pt.Index].AttemptNumber--
											Write-LogHost "  [AUTH] Transient auth failure detected - retry attempt not counted (auth issue, not partition issue)" -ForegroundColor Yellow
										}
									}
								}
							} elseif ($job.State -eq 'Failed') {
								Write-LogHost "  ✗ Retry job failed for Partition $($pt.Index)/$($pt.Total)" -ForegroundColor Red
								if ($script:partitionStatus.ContainsKey($pt.Index)) {
									# Read the job's error output FIRST so the failure can be classified
									# (auth vs generic) before it is recorded and counted.
									$lastErrorText = $null
									try {
										$errorOutput = Receive-Job -Job $job -ErrorAction SilentlyContinue 2>&1
										if ($errorOutput) { $lastErrorText = ($errorOutput | Out-String).Trim() }
									} catch {}
									$isAuthFailure = Test-TransientAuthSignal -Text $lastErrorText
									Set-PartitionFailure -Index $pt.Index -Stage $(if ($isAuthFailure) { 'AUTH' } else { 'RECONCILE' }) -Reason $(if ($isAuthFailure) { '401' } else { 'JOB_FAILED' })
									if ($lastErrorText) {
										$script:partitionStatus[$pt.Index].LastError = $lastErrorText
										# Log the actual error for diagnostics (useful level)
										Write-LogHost "    Error details: $lastErrorText" -ForegroundColor DarkYellow
									}
									# Genuine transient-auth failures don't count against retry limit (auth issue, not partition issue)
									if ($isAuthFailure) {
										$script:partitionStatus[$pt.Index].AttemptNumber--
										Write-LogHost "  [AUTH] Transient auth failure detected - retry attempt not counted (auth issue, not partition issue)" -ForegroundColor Yellow
									}
								}
							}
						}
						
						# Cleanup retry jobs
						if ($retryJobs.Count -gt 0) {
							Remove-Job -Job $retryJobs -Force -ErrorAction SilentlyContinue | Out-Null
						}
					}
					
					# FINAL SUMMARY AND RECONCILIATION
					Write-LogHost "" -ForegroundColor White
					Write-LogHost "═══════════════════════════════════════════════════════════════" -ForegroundColor Cyan
					Write-LogHost "  QUERY SUBMISSION SUMMARY" -ForegroundColor Cyan
					Write-LogHost "═══════════════════════════════════════════════════════════════" -ForegroundColor Cyan
					
					$totalPartitions = $script:partitionStatus.Count
					$completedPartitions = @($script:partitionStatus.Values | Where-Object { $_.Status -eq 'Complete' })
					$sentButIncomplete = @($script:partitionStatus.Values | Where-Object { $_.Status -eq 'Sent' -and $_.QueryId })
					$terminallyFailed = @($script:partitionStatus.Values | Where-Object { $_.IsTerminalFailure })
					$subdivisionLimited = @($script:partitionStatus.Values | Where-Object { $_.Status -eq 'SubdivisionLimit' })
					$neverSent = @($script:partitionStatus.Values | Where-Object { $_.Status -in @('Failed', 'NotStarted') -and -not $_.QueryId -and -not $_.IsTerminalFailure })
					# Record "completed with gaps" signals for the process exit code (read at script end).
					# Set-only (monotonic) so a later summary pass cannot clear a gap already seen.
					if ($terminallyFailed.Count -gt 0)   { $script:HadTerminalFailures = $true }
					if ($subdivisionLimited.Count -gt 0) { $script:HadSubdivisionLimit = $true }
					# Bounded partition-stability verification (opt-in via -VerifyPartitionStability). A partition
					# certified Complete can still be a STRICT SUBSET of the true result (observed live: SharePoint
					# partition 26 = 13,350 vs 15,465, 2,115 RecordIds silently lost). Invoke-PartitionStabilityVerification
					# runs ONE independent bounded repeat fetch per completed partition, populating .RecordIds (first
					# fetch, from persisted output) and .StabilityRepeatIds (the single repeat query), then
					# Test-AuditPartitionConsistency treats any RecordId-set difference (missing OR extra) as a gap
					# (sets HadTerminalFailures -> exit 40): never silently certified, never blind-accept-larger, never
					# unioned, never count-only. Default OFF => no repeat query, no RecordId retention => byte-identical.
					script:Invoke-PartitionStabilityVerification -CompletedPartitions $completedPartitions -Enabled:$VerifyPartitionStability -TargetUsers $script:targetUsers
					
					Write-LogHost "  Total Partitions: $totalPartitions" -ForegroundColor White
					Write-LogHost "  Sent and Complete: $($completedPartitions.Count)" -ForegroundColor Green
					
					if ($sentButIncomplete.Count -gt 0) {
						Write-LogHost "  [!] Sent but Incomplete: $($sentButIncomplete.Count)" -ForegroundColor Yellow
						foreach ($status in $sentButIncomplete) {
							$pt = $status.Partition
							Write-LogHost "    - Partition $($pt.Index)/$($pt.Total): QueryName=$($status.QueryName), QueryId=$($status.QueryId)" -ForegroundColor Yellow
						}
					}
					
					if ($neverSent.Count -gt 0) {
						Write-LogHost "  ✗ Never Sent: $($neverSent.Count)" -ForegroundColor Red
						foreach ($status in $neverSent) {
							$pt = $status.Partition
							$errorMsg = if ($status.LastError) { " - Error: $($status.LastError)" } else { "" }
							Write-LogHost "    - Partition $($pt.Index)/$($pt.Total): QueryName=$($status.QueryName)$errorMsg" -ForegroundColor Red
						}
					}

					if ($subdivisionLimited.Count -gt 0) {
						Write-LogHost "  [!] Subdivision-Limit (window exceeded max subdivision depth $script:MaxSubdivisionLevel — NOT a create/fetch failure): $($subdivisionLimited.Count)" -ForegroundColor Red
						Write-LogHost "    These windows were not collected this run; re-run with -Resume to retry them once the underlying condition clears." -ForegroundColor Yellow
						foreach ($status in $subdivisionLimited) {
							$pt = $status.Partition
							$win = "$($pt.PStart.ToString('yyyy-MM-dd HH:mm')) to $($pt.PEnd.ToString('yyyy-MM-dd HH:mm')) UTC"
							Write-LogHost "    - Partition $($pt.Index)/$($pt.Total): $win" -ForegroundColor Red
						}
					}

					if ($terminallyFailed.Count -gt 0) {
						Write-LogHost "  ✗ Terminally Failed (stopped after $script:MaxConsecutiveIdenticalFailures consecutive same-category failures): $($terminallyFailed.Count)" -ForegroundColor Red
						Write-LogHost "    Not retried further this run; re-run with -Resume to retry them once the underlying issue clears." -ForegroundColor Yellow
						foreach ($status in $terminallyFailed) {
							$pt = $status.Partition
							$label = if ($status.LastFailureStage -and $status.LastFailureReason) { "$($status.LastFailureStage)/$($status.LastFailureReason)" } else { 'UNKNOWN' }
							$win = "$($pt.PStart.ToString('yyyy-MM-dd HH:mm')) to $($pt.PEnd.ToString('yyyy-MM-dd HH:mm')) UTC"
							$qid = if ($status.QueryId) { " | QueryId=$($status.QueryId)" } else { "" }
							Write-LogHost "    - Partition $($pt.Index)/$($pt.Total): $label x$($status.ConsecutiveIdenticalFailures) | $win$qid" -ForegroundColor Red
							if ($status.LastError) { Write-LogHost "        Last error: $($status.LastError)" -ForegroundColor DarkYellow }
						}
					}

					# Check for any missing/skipped partitions (exclude intentionally skipped partitions from resume mode)
					$expectedPartitions = 1..$totalPartitions
					$attemptedPartitions = @($script:partitionStatus.Keys)
					
					# In resume mode, use the originally-skipped partition indices (captured at start of run)
					# This avoids confusion where partitions completed during THIS run appear as "previously completed"
					$intentionallySkipped = @()
					if ($script:IsResumeMode -and $script:OriginallySkippedPartitionIndices) {
						$intentionallySkipped = $script:OriginallySkippedPartitionIndices
					}
					
					$missingPartitions = $expectedPartitions | Where-Object { $_ -notin $attemptedPartitions -and $_ -notin $intentionallySkipped }
					
					if ($missingPartitions.Count -gt 0) {
						Write-LogHost "  [!] MISSING/SKIPPED PARTITIONS: $($missingPartitions.Count)" -ForegroundColor Red
						Write-LogHost "    Partitions: $($missingPartitions -join ', ')" -ForegroundColor Red
					}
					
					# Show info about intentionally skipped partitions (resume mode)
					if ($intentionallySkipped.Count -gt 0) {
						Write-LogHost "  Previously completed partitions (from checkpoint): $($intentionallySkipped -join ', ')" -ForegroundColor Green
					}
					
					Write-LogHost "═══════════════════════════════════════════════════════════════" -ForegroundColor Cyan
					Write-LogHost "" -ForegroundColor White
					
					# Continue with remaining processing if we have any completed partitions
					if ($completedPartitions.Count -eq 0) {
						Write-LogHost "  ✗ ERROR: No partitions completed successfully. Cannot continue." -ForegroundColor Red
						throw "All partitions failed - no data retrieved"
					}
					
					Write-LogHost "  Continuing with $($completedPartitions.Count) successful partition(s)..." -ForegroundColor Green
					
					# Process any remaining completed jobs that weren't caught in the loop
					# CRITICAL: Skip jobs with errors - they should have been handled by retry logic
							$remainingCompleted = $jobs | Where-Object { $_.State -eq 'Completed' -and -not $script:processedJobIds.Contains($_.Id) -and $_.Error.Count -eq 0 }
							foreach ($job in $remainingCompleted) {
							$res = $null
							try {
								$res = Receive-Job -Job $job -ErrorAction Stop
							} catch {
								Write-LogHost "  ERROR receiving job: $($_.Exception.Message)" -ForegroundColor Red
							}
							
							$pt = $jobMeta[$job.Id]							# Skip if job metadata not found (shouldn't happen but defensive)
							if ($null -eq $pt) {
								Write-LogHost "  WARNING: Job metadata not found for job ID $($job.Id) - skipping" -ForegroundColor Yellow
								[void]$script:processedJobIds.Add($job.Id)
								continue
							}
							
							if ($null -ne $res) {
									Write-LogHost "  Partition $($pt.Index)/$($pt.Total) complete: Retrieved $($res.RetrievedCount) records in $($res.ElapsedMs)ms" -ForegroundColor Cyan
							Write-LogHost "    Query: $($pt.PStart.ToString('yyyy-MM-dd HH:mm')) to $($pt.PEnd.ToString('yyyy-MM-dd HH:mm')) UTC" -ForegroundColor DarkGray
								if ($res.ThreadSavedToDisk -and $script:memoryFlushEnabled -and -not $script:memoryFlushed) {
									$script:memoryFlushed = $true
									Write-LogHost "  [STREAM] Thread-side JSONL persistence active - parallel partition data is being written to disk (normal for parallel partition fetches; not a memory-pressure event)" -ForegroundColor DarkCyan
								}
								try {
									$script:metrics.QueryMs += [int]$res.ElapsedMs
									$script:metrics.TotalRecordsFetched += [int]$res.RetrievedCount
									# Count records by their actual Operation value, not by query group name
									if ($res.Logs -and $res.Logs.Count -gt 0) {
										foreach ($log in $res.Logs) {
											# Handle both Operation (EOM format) and Operations (Graph API normalized format)
											$actualOperation = if ($log.Operation) { $log.Operation } elseif ($log.Operations) { $log.Operations } else { $null }
											if (-not [string]::IsNullOrWhiteSpace($actualOperation)) {
												if (-not $script:metrics.Activities.ContainsKey($actualOperation)) {
													$script:metrics.Activities[$actualOperation] = @{ Retrieved = 0; Structured = 0 }
												}
												$script:metrics.Activities[$actualOperation].Retrieved += 1
											}
										}
									}
								} catch {}
								
								if ($res.Logs -and $res.Logs.Count -gt 0) {
									foreach ($log in $res.Logs) {
										[void]$allLogs.Add($log)
									}
								}
								
								# Update progress - in parallel mode, each partition = 1 unit of progress
								$script:progressState.Query.Current = [Math]::Min($script:progressState.Query.Current + 1, $script:progressState.Query.Total)
								Update-Progress -Status ("Partition {0}/{1} complete (retry)" -f $pt.Index, $pt.Total)
								$qc = $script:progressState.Query.Current
								$qt = $script:progressState.Query.Total
								Write-ProgressTick
							}
							
								[void]$script:processedJobIds.Add($job.Id)
							}
							
							# Cleanup
							if ($jobs.Count -gt 0) {
								Remove-Job -Job $jobs -Force -ErrorAction SilentlyContinue | Out-Null
							}
							
							# Normalize progress if needed
							if ($script:progressState.Query.Current -lt $script:progressState.Query.Total -and $script:progressState.Query.Total -le 200) {
								$script:progressState.Query.Current = $script:progressState.Query.Total
								Update-Progress -Status 'Parallel partitions complete (normalized)'
							}
						}
					}
					catch {
						Write-LogHost "  Graph API parallel execution error: $($_.Exception.Message)" -ForegroundColor Red
						Write-LogHost "  Error details: $($_.ScriptStackTrace)" -ForegroundColor Red
						throw
					}
				}  # End of while (-not $allPartitionsProcessed) loop - subdivision pass complete
				
				# Show accurate completion status (only for parallel mode - sequential has its own summary)
				if ($canParallel -and $script:partitionStatus) {
					$successCount = @($script:partitionStatus.Values | Where-Object { $_.Status -eq 'Complete' }).Count
					$failedCount = $partitions.Count - $successCount
					if ($failedCount -eq 0) {
						Write-LogHost "  All $successCount partitions completed" -ForegroundColor Green
					} else {
						Write-LogHost "  [!] $successCount/$($partitions.Count) partitions completed ($failedCount failed)" -ForegroundColor Yellow
					}
				}
		}
		# Sequential fallback: Process partitions one-by-one when parallel execution is not available
		# This handles: EOM mode (-UseEOM), PS 5.1, or when ThreadJob module is unavailable
		if (-not $canParallel) {
			$sequentialGroups++
			Write-LogHost "  Processing $($partitions.Count) partitions sequentially..." -ForegroundColor DarkCyan
			foreach ($pt in $partitions) {
				# If circuit breaker is OPEN from a previous partition, wait for cooldown before proceeding.
				# Without this, the next partition enters its block loop, finds the breaker still open
				# (only milliseconds have elapsed), and immediately skips — cascading through all remaining partitions.
				if ($script:circuitBreakerOpen -and $script:circuitBreakerOpenUntil -and (Get-Date) -lt $script:circuitBreakerOpenUntil) {
					$waitSeconds = [math]::Ceiling(($script:circuitBreakerOpenUntil - (Get-Date)).TotalSeconds)
					if ($waitSeconds -gt 0) {
						Write-LogHost "  Circuit breaker cooldown: waiting $($waitSeconds)s before partition $($pt.Index)/$($pt.Total)..." -ForegroundColor DarkYellow
						Start-Sleep -Seconds $waitSeconds
					}
					$script:circuitBreakerOpen = $false
					$script:consecutiveBlockFailures = 0
					Write-LogHost "  Circuit breaker cooldown elapsed – resuming with partition $($pt.Index)/$($pt.Total)" -ForegroundColor DarkGreen
				}
				$tq0 = Get-Date
				if (-not $UseEOM) { Write-LogHost "  Querying partition $($pt.Index)/$($pt.Total) sequentially" -ForegroundColor DarkCyan }
				$logs = Invoke-ActivityTimeWindowProcessing -ActivityType $pt.Activity -StartDate $pt.PStart -EndDate $pt.PEnd -PartitionIndex $pt.Index -TotalPartitions $pt.Total -UseEOMMode $UseEOM
				$tq1 = Get-Date
				try {
					$ms = [int]($tq1 - $tq0).TotalMilliseconds
					$script:metrics.QueryMs += $ms
					if ($logs) {
						# Count records by their actual Operation value, not by query group name
						$logArray = if ($logs -is [Array]) { $logs } else { @($logs) }
						foreach ($log in $logArray) {
							# Handle both Operation (EOM format) and Operations (Graph API normalized format)
							$actualOperation = if ($log.Operation) { $log.Operation } elseif ($log.Operations) { $log.Operations } else { $null }
							if (-not [string]::IsNullOrWhiteSpace($actualOperation)) {
								if (-not $script:metrics.Activities.ContainsKey($actualOperation)) {
									$script:metrics.Activities[$actualOperation] = @{ Retrieved = 0; Structured = 0 }
								}
								$script:metrics.Activities[$actualOperation].Retrieved += 1
							}
						}
						$script:metrics.TotalRecordsFetched += $logArray.Count
						# Add to collection
						foreach ($item in $logArray) { [void]$allLogs.Add($item) }
					}
					# Explicit progress tick per sequential partition
					$script:progressState.Query.Current = [Math]::Min($script:progressState.Query.Current + 1, $script:progressState.Query.Total)
					Write-ProgressTick
				} catch {
					Write-LogHost "  Warning: Error processing partition $($pt.Index): $($_.Exception.Message)" -ForegroundColor Yellow
				}
			}
			Write-LogHost "  Sequential processing complete: $($allLogs.Count) records retrieved" -ForegroundColor Green
		}
	}
	$script:CurrentServiceFilter = $null
	
	# ============================================================================
	# FINAL SAFETY NET: Ensure ALL partitions were completed before export phase
	# This catches any partitions that slipped through all retry mechanisms
	# ============================================================================
	if ($script:partitionStatus -and $script:partitionStatus.Count -gt 0 -and -not $UseEOM) {
		# Find partitions not in terminal success states
		$incompletePartitions = @($script:partitionStatus.Values | Where-Object { 
			$_.Status -notin @('Complete', 'Subdivided') 
		})
		
		if ($incompletePartitions.Count -gt 0) {
			Write-LogHost "" -ForegroundColor Yellow
			Write-LogHost "============================================================" -ForegroundColor Yellow
			Write-LogHost "[FINAL-RECONCILE] $($incompletePartitions.Count) partition(s) incomplete - initiating final recovery" -ForegroundColor Yellow
			Write-LogHost "============================================================" -ForegroundColor Yellow
			
			# List each incomplete partition
			foreach ($incomplete in $incompletePartitions) {
				$lastErr = if ($incomplete.LastError) { " (Last error: $($incomplete.LastError.Substring(0, [Math]::Min(80, $incomplete.LastError.Length)))...)" } else { "" }
				Write-LogHost "  Partition $($incomplete.Index): Status=$($incomplete.Status)$lastErr" -ForegroundColor DarkYellow
			}
			
			$maxFinalAttempts = 5
			$finalAttempt = 0
			$recoveredCount = 0
			
			while ($finalAttempt -lt $maxFinalAttempts) {
				# Re-check which partitions still need recovery
				$stillIncomplete = @($script:partitionStatus.Values | Where-Object { 
					$_.Status -notin @('Complete', 'Subdivided') 
				})
				
				if ($stillIncomplete.Count -eq 0) {
					Write-LogHost "[FINAL-RECONCILE] All partitions recovered successfully!" -ForegroundColor Green
					break
				}
				
				$finalAttempt++
				Write-LogHost "[FINAL-RECONCILE] Attempt $finalAttempt/$maxFinalAttempts - $($stillIncomplete.Count) partition(s) remaining" -ForegroundColor Yellow
				
				# Refresh token before retry (critical for long-running exports)
				$refreshResult = Refresh-GraphTokenIfNeeded -BufferMinutes 5
				if ($refreshResult -is [string] -and $refreshResult -eq 'Quit') {
					if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
					Show-CheckpointExitMessage
					exit 0
				}
				
				# Get fresh token for recovery jobs
				$recoveryToken = Get-GraphAccessToken
				if (-not $recoveryToken) {
					Write-LogHost "[FINAL-RECONCILE] Cannot obtain access token - saving checkpoint and exiting" -ForegroundColor Red
					if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
					Show-CheckpointExitMessage
					exit 0
				}
				
				# Brief cooldown between attempts
				if ($finalAttempt -gt 1) {
					$cooldown = Get-Random -Minimum 15 -Maximum 30
					Write-LogHost "  Waiting $cooldown seconds before retry..." -ForegroundColor Gray
					Start-Sleep -Seconds $cooldown
				}
				
				# Process each incomplete partition sequentially (safer for final recovery)
				foreach ($incomplete in $stillIncomplete) {
					$pt = $incomplete.Partition
					if (-not $pt) {
						Write-LogHost "  [WARN] Partition $($incomplete.Index) has no partition object - cannot recover" -ForegroundColor Red
						continue
					}
					
					Write-LogHost "  [RECOVER] Retrying Partition $($pt.Index)/$($pt.Total)..." -ForegroundColor Cyan
					
					try {
						# Reset status for retry
						$script:partitionStatus[$pt.Index].Status = 'NotStarted'
						$script:partitionStatus[$pt.Index].AttemptNumber++
						
						# Use sequential processing for recovery (Invoke-ActivityTimeWindowProcessing)
						$logs = Invoke-ActivityTimeWindowProcessing -ActivityType $pt.Activity -StartDate $pt.PStart -EndDate $pt.PEnd -PartitionIndex $pt.Index -TotalPartitions $pt.Total -UseEOMMode $false
						
						if ($logs) {
							$logArray = if ($logs -is [Array]) { $logs } else { @($logs) }
							
							# Add to $allLogs
							foreach ($item in $logArray) { [void]$allLogs.Add($item) }
							
							# Save to JSONL for streaming export
							$incrementalDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
							if (-not (Test-Path $incrementalDir)) { New-Item -ItemType Directory -Path $incrementalDir -Force | Out-Null }
							$incrementalFile = Join-Path $incrementalDir "Part$($pt.Index)_${global:ScriptRunTimestamp}_qid-recovery_$($logArray.Count)records.jsonl"
							$logArray | ForEach-Object { $_ | ConvertTo-Json -Depth 10 -Compress } | Out-File -FilePath $incrementalFile -Encoding utf8 -Force
							
							# Mark complete
							$script:partitionStatus[$pt.Index].Status = 'Complete'
							$script:partitionStatus[$pt.Index].RecordCount = $logArray.Count
							$recoveredCount++
							
							Write-LogHost "  [RECOVERED] Partition $($pt.Index): $($logArray.Count) records" -ForegroundColor Green
							
							# Update metrics
							$script:metrics.TotalRecordsFetched += $logArray.Count
						} else {
							# Zero records is valid - mark complete
							$script:partitionStatus[$pt.Index].Status = 'Complete'
							$script:partitionStatus[$pt.Index].RecordCount = 0
							$recoveredCount++
							Write-LogHost "  [RECOVERED] Partition $($pt.Index): 0 records (empty time window)" -ForegroundColor Green
						}
						
						# Save checkpoint after each successful recovery
						if ($script:CheckpointEnabled) {
							Save-Checkpoint -PartitionIndex $pt.Index -State 'Completed' -RecordCount ($logArray.Count)
						}
					} catch {
						Set-PartitionFailure -Index $pt.Index -Stage 'RETRY' -Reason 'EXCEPTION'
						$script:partitionStatus[$pt.Index].LastError = $_.Exception.Message
						Write-LogHost "  [FAILED] Partition $($pt.Index): $($_.Exception.Message)" -ForegroundColor Red
					}
				}
			}
			
			# Final status report
			$finalIncomplete = @($script:partitionStatus.Values | Where-Object { 
				$_.Status -notin @('Complete', 'Subdivided') 
			})
			
			if ($finalIncomplete.Count -gt 0) {
				Write-LogHost "" -ForegroundColor Red
				Write-LogHost "============================================================" -ForegroundColor Red
				Write-LogHost "[FINAL-RECONCILE] WARNING: $($finalIncomplete.Count) partition(s) could not be recovered after $maxFinalAttempts attempts" -ForegroundColor Red
				Write-LogHost "============================================================" -ForegroundColor Red
				foreach ($failed in $finalIncomplete) {
					Write-LogHost "  Partition $($failed.Index): $($failed.LastError)" -ForegroundColor Red
				}
				Write-LogHost "  These partitions will be missing from the export. Use -Resume to retry later." -ForegroundColor Yellow
			} else {
				Write-LogHost "[FINAL-RECONCILE] Complete: Recovered $recoveredCount partition(s) via final safety net" -ForegroundColor Green
			}
			Write-LogHost "" -ForegroundColor White
		}
	}
	
	# MEMORY FLUSH MODE: If we flushed $allLogs during fetch, enable streaming merge from JSONL files
	# This path is only for non-explosion mode (explosion is excluded from memory flush feature)
	if ($script:memoryFlushed) {
		Write-LogHost "  [STREAM] Parallel-partition JSONL persistence engaged during fetch - using JSONL-backed streaming export for final assembly (routine for parallel partition runs; not an indication of memory pressure)" -ForegroundColor DarkCyan
		$script:UseStreamingMergeForExport = $true
		$script:StreamingMergeDirectory = Split-Path $script:PartialOutputPath -Parent
		
		# Get all completed partition indices from this run for streaming merge
		# Note: partitionStatus values are hashtables with a 'Partition' key containing the partition object;
		# the Index property lives on the partition object, not on the status hashtable itself
		$completedPartitions = @($script:partitionStatus.Values | Where-Object { $_.Status -eq 'Complete' } | ForEach-Object { $_.Partition.Index })
		$script:StreamingMergePartitions = $completedPartitions
		
		# Count records from partition status for accurate totals
		$estimatedFromJSONL = ($completedPartitions | ForEach-Object { [int]($script:partitionStatus[$_].RecordCount ?? 0) } | Measure-Object -Sum).Sum
		$script:StreamingMergeRecordCount = $estimatedFromJSONL
		Write-LogHost "  [STREAM] Found $($estimatedFromJSONL.ToString('N0')) records across $($completedPartitions.Count) partitions for streaming export" -ForegroundColor DarkCyan
	}
	
	# MERGE INCREMENTAL SAVES: Only needed for Resume mode to recover data from skipped partitions
	# Fresh runs already have all records in $allLogs (added when each partition completed)
	# In resume mode, only merge data for partitions that were SKIPPED (already completed before this run)
	# Partitions completed during THIS run already have their data in $allLogs via AddRange
	if ($script:IsResumeMode) {
		$partitionsToMerge = $script:OriginallySkippedPartitionIndices
		if ($partitionsToMerge -and $partitionsToMerge.Count -gt 0) {
			Write-LogHost "  [MERGE] Merging incremental data for previously-completed partitions: $($partitionsToMerge -join ', ')" -ForegroundColor Cyan
			
			# Use streaming merge when we have many partitions OR large record counts to avoid memory exhaustion
			# Threshold: If more than 20 partitions to merge, or estimated >500K records, use streaming
			$estimatedRecords = 0
			$incrementalDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
			# Primary: derive record count from checkpoint data — checkpoint stores exact per-partition recordCount
			# set at completion time, and is not affected by multi-file (snapshot/append) inflation or stale
			# files from prior runs that may still exist in the .pax_incremental folder.
			if ($script:CheckpointData -and $script:CheckpointData.partitions.completed) {
				$estimatedRecords = [int](($script:CheckpointData.partitions.completed |
					Where-Object { [int]$_.index -in $partitionsToMerge } |
					ForEach-Object { [int]$_.records } |
					Measure-Object -Sum).Sum)
			}
			# Fallback: estimate from JSONL filenames if checkpoint data is unavailable or zero.
			# Two filters applied to avoid inflation:
			#   (1) Current run's timestamp only — excludes stale files from prior runs in the same folder.
			#   (2) No snapshot files — snapshots are cumulative in-progress saves (subset of final file);
			#       counting them alongside the final file would double-count those records.
			if ($estimatedRecords -eq 0 -and (Test-Path $incrementalDir)) {
				$filesToMerge = Get-ChildItem -Path $incrementalDir -Filter "*.jsonl" -ErrorAction SilentlyContinue | Where-Object {
					$partMatch = [regex]::Match($_.Name, '^Part(\d+)_')
					$partMatch.Success -and ([int]$partMatch.Groups[1].Value -in $partitionsToMerge) -and ($_.Name -like "*${global:ScriptRunTimestamp}*")
				}
				foreach ($f in $filesToMerge) {
					if ($f.Name -notmatch '_snapshot_page\d+_' -and $f.Name -match '_(\d+)records\.jsonl$') {
						$estimatedRecords += [int]$Matches[1]
					}
				}
			}
			
			$useStreamingMerge = ($partitionsToMerge.Count -gt 20) -or ($estimatedRecords -gt 500000) -or ($allLogs.Count -eq 0)
			
			# Disable streaming merge for explosion modes - explosion requires in-memory processing
			# Streaming merge only works with the non-explosion fast path (direct 1:1 CSV export)
			$isExplosionMode = ($ExplodeDeep -or $ExplodeArrays -or $ForcedRawInputCsvExplosion)
			if ($useStreamingMerge -and $isExplosionMode) {
				Write-LogHost "  [MERGE] Explosion mode active - loading records into memory (streaming merge not supported with explosion)" -ForegroundColor DarkYellow
				$useStreamingMerge = $false
			}
			
			if ($useStreamingMerge) {
				$streamingReason = if ($allLogs.Count -eq 0) { "all partitions from prior run" } elseif ($partitionsToMerge.Count -gt 20) { "$($partitionsToMerge.Count) partitions" } else { "~$($estimatedRecords.ToString('N0')) records" }
				Write-LogHost "  [MERGE] Large merge detected ($streamingReason) - using streaming mode" -ForegroundColor Yellow
				Write-LogHost "  [MERGE] Streaming merge avoids memory exhaustion for large datasets" -ForegroundColor DarkGray
				
				# Flag that we're using streaming - will need special handling for CSV export
				$script:UseStreamingMergeForExport = $true
				$script:StreamingMergePartitions = $partitionsToMerge
				$script:StreamingMergeDirectory = Split-Path $script:PartialOutputPath -Parent
				
				# Don't merge into $allLogs - we'll stream directly to CSV later
				# Just count the records for metrics
				$mergedFromIncremental = $estimatedRecords
				Write-LogHost "  [MERGE] Deferred streaming merge: $($mergedFromIncremental.ToString('N0')) records will be streamed during export" -ForegroundColor DarkGray
			} elseif ($isExplosionMode -and $allLogs.Count -eq 0) {
				# Special case: Explosion mode with all partitions from prior run
				# Need to load JSONL directly into $allLogs (Merge-IncrementalSaves requires non-empty collection)
				$script:UseStreamingMergeForExport = $false
				Write-LogHost "  [MERGE] Loading $($estimatedRecords.ToString('N0')) records from prior run into memory for explosion..." -ForegroundColor Cyan
				$incrementalDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
				$mergedFromIncremental = 0
				if (Test-Path $incrementalDir) {
					$filesToLoad = Get-ChildItem -Path $incrementalDir -Filter "*.jsonl" -ErrorAction SilentlyContinue | Where-Object {
						$partMatch = [regex]::Match($_.Name, '^Part(\d+)_')
						$partMatch.Success -and ([int]$partMatch.Groups[1].Value -in $partitionsToMerge)
					}
					foreach ($file in $filesToLoad) {
						try {
							$lines = Get-Content -Path $file.FullName -Encoding utf8
							foreach ($line in $lines) {
								if (-not [string]::IsNullOrWhiteSpace($line)) {
									try {
										$record = $line | ConvertFrom-Json
										[void]$allLogs.Add($record)
										$mergedFromIncremental++
									} catch {}
								}
							}
						} catch {
							Write-LogHost "  [WARN] Failed to load $($file.Name): $($_.Exception.Message)" -ForegroundColor Yellow
						}
					}
				}
				Write-LogHost "  [MERGE] Loaded $($mergedFromIncremental.ToString('N0')) records into memory" -ForegroundColor Green
			} else {
				# Small merge - use original in-memory approach (faster for small datasets)
				$script:UseStreamingMergeForExport = $false
				$mergedFromIncremental = Merge-IncrementalSaves -AllLogs $allLogs -OutputDirectory (Split-Path $script:PartialOutputPath -Parent) -CleanupAfterMerge $false -OnlyPartitionIndices $partitionsToMerge
			}
			
			# Update TotalRecordsFetched to include merged records (these were "fetched" in a previous run)
			if ($mergedFromIncremental -gt 0) {
				$script:metrics.TotalRecordsFetched += $mergedFromIncremental
				Write-LogHost "  [MERGE] Updated record count: +$mergedFromIncremental from previous run" -ForegroundColor DarkGray
			}
		} else {
			$mergedFromIncremental = 0
			# Preserve UseStreamingMergeForExport if memory flush already set it (parallel-
			# partition JSONL persistence engaged in-flight on a resume that has no originally-
			# skipped partitions — this-run records live in .pax_incremental and the streaming
			# merge must remain enabled to deliver them to the final CSV). Mirrors the guard
			# on the no-resume branch below.
			if (-not $script:memoryFlushed) {
				$script:UseStreamingMergeForExport = $false
			}
		}
		# Note: Incremental files are retained until successful script completion for data safety
		# Cleanup happens at end of script (before exit) to allow recovery if explosion/export fails
	} else {
		$mergedFromIncremental = 0
		# Preserve UseStreamingMergeForExport if memory flush already set it (fresh run with JSONL-only data)
		if (-not $script:memoryFlushed) {
			$script:UseStreamingMergeForExport = $false
		}
		# Note: Incremental files are retained until successful script completion for data safety
	}
	
	# ============================================================================
	# ZERO-RECORD RECOVERY: If all partitions "completed" but returned 0 records,
	# re-check QueryIds directly against Purview - the queries may still have data
	# This handles machine sleep/suspension where thread jobs died but queries succeeded
	# ============================================================================
	$effectiveRecordCount = $allLogs.Count
	if ($script:UseStreamingMergeForExport) {
		$effectiveRecordCount += $(if ($script:StreamingMergeRecordCount -gt 0) { $script:StreamingMergeRecordCount } else { $mergedFromIncremental })
	}
	
	# ============================================================================
	# WORKER-FLUSH RECOVERY: When workers page-flushed records to JSONL but the
	# parent's $script:memoryFlushed flag never got set (e.g., due to a missed result-object
	# event in the receive loop), $allLogs is empty even though completed partitions report
	# RecordCount > 0 and have JSONL files on disk. Detect this and activate streaming merge
	# so the records actually reach the final CSV.
	#
	# Excluded code paths:
	#   - $UseEOM            : EOM path doesn't use Graph workers / JSONL flush
	#   - $script:memoryFlushed already true : streaming merge already activated upstream
	#   - Explosion modes    : explosion requires in-memory processing; streaming merge is
	#                          incompatible (see line ~14988 guard in resume branch). For
	#                          explosion, we instead load JSONL into $allLogs directly.
	# ============================================================================
	$isExplosionModeForRecovery = ($ExplodeDeep -or $ExplodeArrays -or $ForcedRawInputCsvExplosion)
	if ($effectiveRecordCount -eq 0 -and $script:partitionStatus -and $script:partitionStatus.Count -gt 0 -and -not $UseEOM -and -not $script:memoryFlushed) {
		$completedWithRecords = @($script:partitionStatus.Values | Where-Object {
			$_.Status -eq 'Complete' -and [int]($_.RecordCount ?? 0) -gt 0
		})
		if ($completedWithRecords.Count -gt 0) {
			$incrementalDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
			$jsonlFiles = @()
			if (Test-Path $incrementalDir) {
				$jsonlFiles = @(Get-ChildItem -Path $incrementalDir -Filter "Part*_${global:ScriptRunTimestamp}_*.jsonl" -ErrorAction SilentlyContinue)
			}
			if ($jsonlFiles.Count -gt 0) {
				$totalFromPartitions = ($completedWithRecords | ForEach-Object { [int]($_.RecordCount ?? 0) } | Measure-Object -Sum).Sum
				$completedIndices = @($completedWithRecords | ForEach-Object { $_.Partition.Index })

				if ($isExplosionModeForRecovery) {
					# Explosion mode: load JSONL into $allLogs directly (streaming merge incompatible with explosion)
					Write-LogHost "" -ForegroundColor Yellow
					Write-LogHost "============================================================" -ForegroundColor Yellow
					Write-LogHost "[WORKER-FLUSH-RECOVERY] Detected $($completedWithRecords.Count) completed partition(s) reporting $($totalFromPartitions.ToString('N0')) record(s) but in-memory collection is empty" -ForegroundColor Yellow
					Write-LogHost "[WORKER-FLUSH-RECOVERY] Explosion mode active - loading $($jsonlFiles.Count) JSONL file(s) into memory (streaming merge incompatible with explosion)" -ForegroundColor Yellow
					Write-LogHost "============================================================" -ForegroundColor Yellow
					$loadedCount = 0
					$filesToLoad = $jsonlFiles | Where-Object {
						$partMatch = [regex]::Match($_.Name, '^Part(\d+)_')
						$partMatch.Success -and ([int]$partMatch.Groups[1].Value -in $completedIndices) -and ($_.Name -notmatch '_snapshot_page\d+_')
					}
					foreach ($file in $filesToLoad) {
						try {
							$lines = Get-Content -Path $file.FullName -Encoding utf8
							foreach ($line in $lines) {
								if (-not [string]::IsNullOrWhiteSpace($line)) {
									try {
										$record = $line | ConvertFrom-Json
										[void]$allLogs.Add($record)
										$loadedCount++
									} catch {}
								}
							}
						} catch {
							Write-LogHost "  [WORKER-FLUSH-RECOVERY] Failed to load $($file.Name): $($_.Exception.Message)" -ForegroundColor Yellow
						}
					}
					Write-LogHost "[WORKER-FLUSH-RECOVERY] Loaded $($loadedCount.ToString('N0')) record(s) from JSONL into memory for explosion processing" -ForegroundColor Green
					$effectiveRecordCount = $loadedCount
				} else {
					# Non-explosion fast path: activate streaming export from JSONL.
					# When $script:memoryFlushEnabled is true, workers flushing each page to JSONL
					# and returning empty in-memory collections is the NORMAL finalize path - emit
					# nothing to the terminal/log. Only emit the loud banner when memory flush was
					# NOT enabled, which means an empty in-memory collection paired with on-disk
					# JSONL is genuinely unexpected and worth flagging.
					if (-not $script:memoryFlushEnabled) {
						Write-LogHost "" -ForegroundColor Yellow
						Write-LogHost "============================================================" -ForegroundColor Yellow
						Write-LogHost "[WORKER-FLUSH-RECOVERY] Detected $($completedWithRecords.Count) completed partition(s) reporting $($totalFromPartitions.ToString('N0')) record(s) but in-memory collection is empty" -ForegroundColor Yellow
						Write-LogHost "[WORKER-FLUSH-RECOVERY] Found $($jsonlFiles.Count) matching JSONL file(s) in .pax_incremental - activating streaming export" -ForegroundColor Yellow
						Write-LogHost "============================================================" -ForegroundColor Yellow
					}
					$script:memoryFlushed = $true
					$script:UseStreamingMergeForExport = $true
					$script:StreamingMergeDirectory = Split-Path $script:PartialOutputPath -Parent
					$script:StreamingMergePartitions = $completedIndices
					$script:StreamingMergeRecordCount = $totalFromPartitions
					$effectiveRecordCount = $totalFromPartitions
				}
			}
		}
	}
	
	if ($effectiveRecordCount -eq 0 -and $script:partitionStatus -and $script:partitionStatus.Count -gt 0 -and -not $UseEOM) {
		# Find partitions with valid QueryIds that reported 0 records
		# Include both 'Complete' and 'Failed' partitions - queries persist 30 days on Purview
		# regardless of thread job outcome, so data may still be recoverable
		$partitionsWithQueryIds = @($script:partitionStatus.Values | Where-Object { 
			$_.QueryId -and $_.Status -in @('Complete','Failed') -and ($_.RecordCount -eq 0 -or $null -eq $_.RecordCount)
		})
		
		if ($partitionsWithQueryIds.Count -gt 0) {
			Write-LogHost "" -ForegroundColor Yellow
			Write-LogHost "============================================================" -ForegroundColor Yellow
			Write-LogHost "[ZERO-RECORD-RECOVERY] All partitions returned 0 records but have valid QueryIds" -ForegroundColor Yellow
			Write-LogHost "[ZERO-RECORD-RECOVERY] Re-checking queries directly against Purview..." -ForegroundColor Yellow
			Write-LogHost "============================================================" -ForegroundColor Yellow
			
			# Refresh token first (critical after potential machine sleep)
			$refreshResult = Refresh-GraphTokenIfNeeded -BufferMinutes 5
			if ($refreshResult -is [string] -and $refreshResult -eq 'Quit') {
				if ($script:CheckpointEnabled) { Save-Checkpoint -Force }
				Show-CheckpointExitMessage
				exit 0
			}
			
			$recoveredRecords = 0
			$queriesChecked = 0
			$queriesWithData = 0
			
			foreach ($partitionStatus in $partitionsWithQueryIds) {
				$queryId = $partitionStatus.QueryId
				$partitionIndex = $partitionStatus.Partition.Index
				$partitionTotal = $partitionStatus.Partition.Total
				$queriesChecked++
				
				Write-LogHost "  [CHECK] Partition $partitionIndex/$partitionTotal - QueryId: $queryId" -ForegroundColor Cyan
				
				try {
					# Check query status directly
					$status = Get-GraphAuditQueryStatus -QueryId $queryId
					
					if ($status -and $status.Status -eq 'succeeded' -and $status.RecordCount -gt 0) {
						$queriesWithData++
						Write-LogHost "    [FOUND] Query has $($status.RecordCount) records - fetching..." -ForegroundColor Green
						
						# Fetch the records
						$rawRecords = Get-GraphAuditRecords -QueryId $queryId
						
						if ($rawRecords -and $rawRecords.Count -gt 0) {
							# Normalize to EOM-compatible format
							$normalizedRecords = ConvertFrom-GraphAuditRecord -GraphRecords $rawRecords
							
							# Add to allLogs
							foreach ($rec in $normalizedRecords) {
								[void]$allLogs.Add($rec)
							}
							
							# Update partition status
							$script:partitionStatus[$partitionIndex].RecordCount = $normalizedRecords.Count
							$recoveredRecords += $normalizedRecords.Count
							
							# Save to incremental for checkpoint safety
							$incrementalDir = Join-Path (Split-Path $script:PartialOutputPath -Parent) ".pax_incremental"
							if (-not (Test-Path $incrementalDir)) { New-Item -ItemType Directory -Path $incrementalDir -Force | Out-Null }
							$incrementalFile = Join-Path $incrementalDir "Part${partitionIndex}_${global:ScriptRunTimestamp}_qid-recovery_$($normalizedRecords.Count)records.jsonl"
							$normalizedRecords | ForEach-Object { $_ | ConvertTo-Json -Depth 10 -Compress } | Out-File -FilePath $incrementalFile -Encoding utf8 -Force
							
							Write-LogHost "    [RECOVERED] $($normalizedRecords.Count) records from partition $partitionIndex" -ForegroundColor Green
							
							# Update metrics
							$script:metrics.TotalRecordsFetched += $normalizedRecords.Count
						}
					} elseif ($status) {
						Write-LogHost "    [EMPTY] Query status: $($status.Status), RecordCount: $($status.RecordCount)" -ForegroundColor DarkGray
					} else {
						Write-LogHost "    [WARN] Could not retrieve query status" -ForegroundColor Yellow
					}
				} catch {
					Write-LogHost "    [ERROR] Failed to check/fetch QueryId $queryId : $($_.Exception.Message)" -ForegroundColor Red
				}
			}
			
			# Summary
			Write-LogHost "" -ForegroundColor White
			if ($recoveredRecords -gt 0) {
				Write-LogHost "[ZERO-RECORD-RECOVERY] SUCCESS: Recovered $($recoveredRecords.ToString('N0')) records from $queriesWithData query(ies)" -ForegroundColor Green
				Write-LogHost "[ZERO-RECORD-RECOVERY] This typically indicates machine sleep/suspension caused thread job failures" -ForegroundColor Yellow
				Write-LogHost "[ZERO-RECORD-RECOVERY] while the Purview queries completed successfully server-side." -ForegroundColor Yellow
			} else {
				Write-LogHost "[ZERO-RECORD-RECOVERY] No additional records found - date range may genuinely be empty" -ForegroundColor DarkGray
			}
			Write-LogHost "" -ForegroundColor White
		}
	}
	
	Set-ProgressPhase -Phase 'Explosion' -Status 'Analyzing and exploding records'
	Write-LogHost ""; Write-LogHost "=== Enterprise Processing Summary ===" -ForegroundColor Green
	if ($script:UseStreamingMergeForExport -and $mergedFromIncremental -gt 0) {
		Write-LogHost "Records retrieved this run: $($allLogs.Count)" -ForegroundColor Cyan
		Write-LogHost "Records from prior run (streaming): $($mergedFromIncremental.ToString('N0'))" -ForegroundColor Cyan
		Write-LogHost "Total records for export: $(($allLogs.Count + $mergedFromIncremental).ToString('N0'))" -ForegroundColor Green
	} elseif ($script:UseStreamingMergeForExport -and $script:StreamingMergeRecordCount -gt 0) {
		# Fresh run with memory flush - records are in JSONL, not $allLogs
		Write-LogHost "Total audit records retrieved: $($script:StreamingMergeRecordCount.ToString('N0')) (streaming from JSONL)" -ForegroundColor Cyan
	} else {
		Write-LogHost "Total audit records retrieved: $($allLogs.Count)" -ForegroundColor Cyan
	}
	
	# Deduplicate by RecordId to handle session pagination retry scenarios
	# Bug context: When session pagination retries with a new SessionId after transient failures,
	# Search-UnifiedAuditLog can return the same records again, causing duplicates in $allLogs.
	# This deduplication ensures each unique audit record appears only once in the final output.
	$preDedupeCount = $allLogs.Count
	if ($preDedupeCount -gt 0) {
		try {
			Write-LogHost "Running deduplication check on $preDedupeCount records..." -ForegroundColor DarkGray
			
			# Deduplicate records by unique ID
			# Live queries use 'Identity' property, CSV exports use 'Id' property
			$uniqueLogs = New-Object System.Collections.ArrayList
			$seenIds = New-Object System.Collections.Generic.HashSet[string]
			$duplicateSkipped = 0
			
			foreach ($log in $allLogs) {
				$recordId = $null
				try { 
					# Check properties in order of likelihood (Identity for live queries, Id for CSV)
					if ($log.Identity) { $recordId = $log.Identity }
					elseif ($log.Id) { $recordId = $log.Id }
					elseif ($log.RecordId) { $recordId = $log.RecordId }
				} catch {}
				
				if ($recordId -and -not $seenIds.Contains($recordId)) {
					[void]$seenIds.Add($recordId)
					[void]$uniqueLogs.Add($log)
				}
				elseif (-not $recordId) {
					# Preserve records without an Id (shouldn't happen, but be safe)
					[void]$uniqueLogs.Add($log)
				}
				else {
					# Duplicate ID detected - skip this record
					$duplicateSkipped++
				}
			}
			
			# Report deduplication results
			$duplicatesRemoved = $preDedupeCount - $uniqueLogs.Count
			if ($duplicatesRemoved -gt 0) {
				Write-LogHost "Deduplication: Removed $duplicatesRemoved duplicate record(s) (pagination retry artifacts)" -ForegroundColor Yellow
				$allLogs = $uniqueLogs
			}
			else {
				Write-LogHost "Deduplication: No duplicates found" -ForegroundColor DarkGray
			}
		}
		catch {
			Write-LogHost "Warning: Deduplication failed: $($_.Exception.Message) - proceeding with original records" -ForegroundColor DarkYellow
		}
	}
	
	# Client-side date-range trimming — remove records returned outside the requested date boundaries.
	# Purview's partition-based indexing can bleed records up to ~10 hours past EndDate on large tenants.
	if (($script:TrimStartDateUTC -or $script:TrimEndDateUTC) -and $allLogs.Count -gt 0) {
		$preTrimCount = $allLogs.Count
		$trimmedLogs = New-Object System.Collections.ArrayList($preTrimCount)
		foreach ($log in $allLogs) {
			$cd = script:Parse-DateSafe $log.CreationDate
			if (-not $cd) { [void]$trimmedLogs.Add($log); continue }  # Keep records with unparseable dates
			$cdUtc = $cd.ToUniversalTime()
			if ($script:TrimStartDateUTC -and $cdUtc -lt $script:TrimStartDateUTC) { continue }
			if ($script:TrimEndDateUTC   -and $cdUtc -ge $script:TrimEndDateUTC)   { continue }
			[void]$trimmedLogs.Add($log)
		}
		$trimCount = $preTrimCount - $trimmedLogs.Count
		if ($trimCount -gt 0) {
			$script:DateTrimCount += $trimCount
			$allLogs = $trimmedLogs
			Write-LogHost "Date-range trim: Removed $trimCount record(s) outside requested date boundaries" -ForegroundColor Yellow
		}
	}
	
	# Show accurate record count — in streaming mode allLogs may be empty because records went JSONL→CSV directly
	if ($script:UseStreamingMergeForExport) {
		# StreamingMergeRecordCount = memory flush fresh run; mergedFromIncremental = deferred resume merge
		$streamCount = if ($script:StreamingMergeRecordCount -gt 0) { $script:StreamingMergeRecordCount } else { $mergedFromIncremental }
		$effectiveTotal = $allLogs.Count + $streamCount
		Write-LogHost "Records for export: $($effectiveTotal.ToString('N0')) (cross-partition deduplication occurs during streaming merge)" -ForegroundColor Cyan
	} else {
		Write-LogHost "Unique audit records: $($allLogs.Count)" -ForegroundColor Cyan
	}
	if ($script:Hit10KLimit -or $script:Hit1MLimit) { 
		Write-LogHost ""; 
		$limitType = if ($script:Hit1MLimit) { "1M (Graph API)" } else { "10K (EOM)" }
		Write-LogHost "  CRITICAL NOTICE: $limitType record limit was reached during processing!" -ForegroundColor Red 
		
		try { Write-LogHost ("Structured rows produced: {0}" -f $structuredDataCount) -ForegroundColor DarkGray } catch {}
		try { Write-LogHost ("Metrics.TotalStructuredRows: {0}" -f $script:metrics.TotalStructuredRows) -ForegroundColor DarkGray } catch {}
		# Show subdivision summary if adaptive subdivision occurred
		if ($script:SubdividedPartitions.Count -gt 0) {
			Write-LogHost ""; 
			Write-LogHost "  ADAPTIVE SUBDIVISION SUMMARY:" -ForegroundColor Yellow
			Write-LogHost "    Total partitions subdivided: $($script:SubdividedPartitions.Count)" -ForegroundColor Yellow
			foreach ($key in $script:SubdividedPartitions.Keys) {
				$count = $script:SubdividedPartitions[$key]
				Write-LogHost "    - Time range: $key (preview count: $count)" -ForegroundColor DarkYellow
			}
			Write-LogHost "    Subdivision successfully prevented data loss by splitting high-volume partitions" -ForegroundColor Green
		}
	}
	if ($allLogs.Count -eq 0 -and $RAWInputCSV) {
		try {
			$rehydrated = Import-Csv -Path $RAWInputCSV
			$allLogs = New-Object System.Collections.ArrayList
			foreach ($row in $rehydrated) {
				try {
					$creation = if ($row.CreationDate) { script:Parse-DateSafe $row.CreationDate } else { $null }
					$identity = if ($row.Id) { $row.Id } elseif ($row.RecordId) { $row.RecordId } else { [guid]::NewGuid().ToString() }
					$rec = [pscustomobject]@{
						RecordType   = $(try { [int]$row.RecordType } catch { 0 })
						CreationDate = $(if ($creation) { $creation } else { Get-Date })
						UserIds      = @(if ($row.UserIds) { $row.UserIds } elseif ($row.UserId) { $row.UserId } else { $null })
						Operations   = if ($row.Operations) { $row.Operations } elseif ($row.Operation) { $row.Operation } else { $null }
						ResultStatus = $(try { $row.ResultStatus } catch { '' })
						ResultCount  = 0
						Identity     = $identity
						IsValid      = $true
						ObjectState  = ''
						AuditData    = $row.AuditData
						Operation    = if ($row.Operation) { $row.Operation } elseif ($row.Operations) { $row.Operations } else { $null }
						UserId       = if ($row.UserId) { $row.UserId } elseif ($row.UserIds) { $row.UserIds } else { $null }
					}
					[void]$allLogs.Add($rec)
				} catch {}
			}
		}
		catch { }
	}
	# For OnlyUserInfo mode, skip the early return - we don't need audit logs, just Entra data
	# For streaming merge mode, $allLogs is intentionally empty - data will be streamed from JSONL files
	# -Dashboard AISID still emits the header-only Purview CSV here but then CONTINUES
	# to the same downstream finalization instead of returning (Test-PaxZeroRecordContinuesAfterHeaderOnly).
	if (script:Test-PaxZeroRecordHeaderOnlyPath -AllLogsCount $allLogs.Count -OnlyUserInfo ([bool]$OnlyUserInfo) -UseStreamingMergeForExport ([bool]$script:UseStreamingMergeForExport)) {
		Write-LogHost ""; Write-LogHost "No audit logs found in the specified date range for the selected activity types." -ForegroundColor Yellow
		# Warn if token refresh occurred during monitoring — 0 records may indicate auth-related data loss
		if ($script:SharedAuthState.RefreshCount -gt 0) {
			Write-LogHost ""
			Write-LogHost "  [!] WARNING: Token refresh occurred during this run ($($script:SharedAuthState.RefreshCount) refresh(es))." -ForegroundColor Red
			Write-LogHost "      Zero records with auth recovery suggests credentials may have expired" -ForegroundColor Red
			Write-LogHost "      while queries were being polled. Check the log file for 401 errors." -ForegroundColor Red
			Write-LogHost "      If the machine was suspended/sleeping, this is the likely cause." -ForegroundColor Red
			Write-LogHost "      Recommendation: Re-run the script on a machine that will not sleep." -ForegroundColor Yellow
			Write-LogHost ""
		}
		Write-LogHost "Emitting header-only CSV (0 rows) for deterministic downstream processing..." -ForegroundColor Cyan
		$headerColumns = if ($ExplodeDeep -or $ExplodeArrays -or $ForcedRawInputCsvExplosion) { if ($IncludeM365Usage -and $RAWInputCSV) { Get-M365UsageWideHeader -RawCsvPath $RAWInputCSV -BaseHeader $M365UsageBaseHeader } else { $PurviewExplodedHeader } } else { @('RecordId', 'CreationDate', 'RecordType', 'Operation', 'UserId', 'AuditData', 'AssociatedAdminUnits', 'AssociatedAdminUnitsNames') }
		# AppendFile (non-rollup) protection: under -AppendFile without -Rollup/-RollupPlusRaw,
		# $OutputFile points DIRECTLY at the AppendFile target (the user's existing fact CSV,
		# or in remote tiers, the local scratch copy that will be uploaded back to the same
		# URL via the upload sweep's $appendLeafs match). Emitting a header-only CSV here
		# would either overwrite that target outright, or via Complete-CheckpointRun's
		# collision-avoidance rename, drop a stray *_<timestamp>.csv next to it. Neither is
		# desired — 0 new records means "leave the AppendFile target unchanged". Branch on
		# AppendFile-non-rollup mode and skip the emit; in all other paths (no Append, or
		# rollup with Append where $OutputFile is a separate scratch path) the existing
		# header-only emit is the proven behavior and is kept.
		$_isAppendOnlyTarget = ($AppendFile -and -not ($Rollup -or $RollupPlusRaw))
		if ($_isAppendOnlyTarget) {
			$_afDisplay = if ($script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) { $script:AppendRaw['Purview'] } else { $AppendFile }
			Write-LogHost ""
			Write-LogHost "AppendFile mode: 0 new records to append; existing target file is unchanged." -ForegroundColor Cyan
			Write-LogHost ("  AppendFile target: {0}" -f $_afDisplay) -ForegroundColor White
			# Drop any _PARTIAL.csv so Complete-CheckpointRun's collision rename can't drop
			# a stray *_<timestamp>.csv beside the AppendFile target.
			if ($script:PartialOutputPath -and (Test-Path $script:PartialOutputPath)) {
				try { Remove-Item -LiteralPath $script:PartialOutputPath -Force -ErrorAction SilentlyContinue } catch {}
				$script:PartialOutputPath = $null
			}
			# Rename the _PARTIAL.log to its final name. Complete-CheckpointRun normally does
			# this, but its log rename is nested inside the _PARTIAL.csv-exists block that
			# we just bypassed. Mirror its collision-avoidance logic here so the log file
			# customers receive isn't called *_PARTIAL.log.
			$_partialLog = $script:LogFile
			if ($_partialLog -and (Test-Path $_partialLog) -and $_partialLog -match '_PARTIAL\.log$') {
				$_finalLog = $_partialLog -replace '_PARTIAL\.log$', '.log'
				if (Test-Path $_finalLog) {
					$_lDir  = Split-Path $_finalLog -Parent
					$_lName = [System.IO.Path]::GetFileNameWithoutExtension($_finalLog)
					$_finalLog = Join-Path $_lDir ("{0}_{1}.log" -f $_lName, (Get-Date -Format 'yyyyMMdd_HHmmss'))
				}
				try { Move-Item -Path $_partialLog -Destination $_finalLog -Force; $script:LogFile = $_finalLog } catch {
					Write-LogHost ("  Warning: Could not rename _PARTIAL log: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
				}
			}
			if ($script:CheckpointEnabled) { Remove-Checkpoint }
			$LogFile = $script:LogFile
		} else {
			try {
				$outputDirEmpty = Split-Path $OutputFile -Parent
				if (-not (Test-Path $outputDirEmpty)) { New-Item -ItemType Directory -Path $outputDirEmpty -Force | Out-Null }
				$enc = New-Object System.Text.UTF8Encoding($false)
				$sw  = [System.IO.StreamWriter]::new($OutputFile, $false, $enc)
				# Always-quote columns to match the quoted-everywhere shape Export-Csv produces
				# in the data path, so an empty-result CSV's header is byte-shape identical to
				# a populated CSV's header.
				$escapedCols = @()
				foreach ($col in $headerColumns) {
					$c = [string]$col
					$escapedCols += , ('"' + ($c -replace '"', '""') + '"')
				}
				$sw.WriteLine(($escapedCols -join ','))
				$sw.Flush(); $sw.Dispose()
			} catch {
				Write-LogHost "Failed to write header-only CSV: $($_.Exception.Message)" -ForegroundColor Red
			}
			# Finalize checkpoint: rename _PARTIAL files and delete checkpoint (same pattern as normal
			# completion). Complete-CheckpointRun handles missing partial output internally and still
			# deletes the checkpoint.
			if ($script:CheckpointEnabled) {
				Complete-CheckpointRun -FinalOutputPath $script:FinalOutputPath
				$OutputFile = $script:FinalOutputPath
				$LogFile = $script:LogFile
			}
			Write-LogHost "Header-only CSV created at: $(Get-DisplayPath -LocalPath $OutputFile)" -ForegroundColor Green
		}
		# Closing summary emitted inline so the log file gets a clean Pipeline Summary
		# tail — the early 'return' below skips the post-export closing-banner section
		# that normally writes these lines.
		$script:metrics.TotalStructuredRows = 0
		$script:metrics.EffectiveChunkSize  = 0
		if (script:Test-PaxZeroRecordContinuesAfterHeaderOnly -Dashboard ([string]$Dashboard)) {
			# A zero-record AISID run CONTINUES to the common downstream finalization
			# (Rollup empty Fact + Users dimension -> normal Entra publication -> AISID export of all twelve
			# CSVs incl. EntraUsers.csv -> completion summary + output roster -> truthful exit). The
			# header-only Purview CSV emitted above is the Rollup's input; the explosion is skipped (no
			# records to explode) via $script:ZeroRecordContinueToPostProcessing, and the "0 records"
			# pipeline summary + ScriptCompleted are deferred to the normal end-of-run tail so the AISID
			# completion/roster are reported truthfully. Zero Purview records are a valid empty result.
			$script:ZeroRecordContinueToPostProcessing = $true
			Write-LogHost "No Purview records: continuing to Rollup + Entra + AISID export (zero records is a valid empty result for -Dashboard AISID)..." -ForegroundColor Cyan
		}
		else {
			Set-ProgressPhase -Phase 'Complete' -Status 'No data'
			Complete-Progress
			Write-LogHost ""
			Write-LogHost "Pipeline Summary:" -ForegroundColor Cyan
			Write-LogHost "  Retained:  0 records" -ForegroundColor White
			Write-LogHost "  Exported:  0 rows"    -ForegroundColor White
			Write-LogHost ("Log file: {0}" -f (Get-DisplayPath -LocalPath $LogFile)) -ForegroundColor White
			$script:ScriptCompleted = $true
			return
		}
	}
	
	# Determine explosion mode:
	# - Full Explosion: ExplodeDeep, ExplodeArrays, or ForcedRawInputCsvExplosion
	# - No Explosion: Standard 1:1 format
	$fullExplode = ($ExplodeDeep -or $ExplodeArrays -or $ForcedRawInputCsvExplosion)
	$partialExplode = $false
	$effectiveExplode = $fullExplode
	
	$processingMode = if ($ExplodeDeep) { "deep column flattening (with row explosion)" } elseif ($fullExplode) { "array explosion (full)" } else { "standard 1:1 format" }
	Write-LogHost "Converting audit records to structured format using $processingMode..." -ForegroundColor Yellow
	$structuredDataCount = 0
	
	# Parallel explosion configuration (PS7+ only, controlled by -ExplosionThreads)
	# ExplosionThreads: 0=auto (optimized based on CPU, memory), 1=force serial, 2-32=explicit
	$actualExplosionThreads = if ($ExplosionThreads -eq 0) {
		# Auto-optimization: explosion is memory-bound, not CPU-bound
		# 8 threads provides good parallelism without excessive GC pressure
		$baseThreads = [Math]::Max(2, [Math]::Min([Environment]::ProcessorCount, 8))
		
		# Memory pressure adjustment: reduce threads if system is under memory pressure
		$memoryAdjustedThreads = $baseThreads
		try {
			$workingSetMB = [int]([System.Diagnostics.Process]::GetCurrentProcess().WorkingSet64 / 1MB)
			$availableMemory = $null
			try {
				$osInfo = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction SilentlyContinue
				if ($osInfo) { $availableMemory = [int]($osInfo.FreePhysicalMemory / 1KB) }  # Convert KB to MB
			} catch { }
			
			if ($availableMemory -and $availableMemory -lt 2000) {
				# Less than 2GB free: reduce to 2-4 threads
				$memoryAdjustedThreads = [Math]::Max(2, [Math]::Min(4, $baseThreads))
				Write-LogHost "  [THREADS] Memory pressure detected ($availableMemory MB free) - reducing threads: $baseThreads -> $memoryAdjustedThreads" -ForegroundColor Yellow
			}
			elseif ($availableMemory -and $availableMemory -lt 4000) {
				# Less than 4GB free: reduce by 25%
				$memoryAdjustedThreads = [Math]::Max(2, [int]($baseThreads * 0.75))
				if ($memoryAdjustedThreads -lt $baseThreads) {
					Write-LogHost "  [THREADS] Low memory ($availableMemory MB free) - reducing threads: $baseThreads -> $memoryAdjustedThreads" -ForegroundColor Yellow
				}
			}
		} catch { }
		
		$memoryAdjustedThreads
	} elseif ($ExplosionThreads -eq 1) {
		1  # Force serial
	} else {
		$ExplosionThreads  # User-specified value (already validated 2-32)
	}
	
	# Compute effective record count accounting for streaming merge (where $allLogs is empty, records are in JSONL)
	$effectiveRecordCount = if ($script:UseStreamingMergeForExport) {
		$sc = if ($script:StreamingMergeRecordCount -gt 0) { $script:StreamingMergeRecordCount } elseif ($mergedFromIncremental -gt 0) { $mergedFromIncremental } else { 0 }
		$allLogs.Count + $sc
	} else {
		$allLogs.Count
	}
	
	# Enable parallel only if PS7+, more than 500 records, AND threads > 1
	$useParallelExplosion = $script:IsPS7 -and ($effectiveRecordCount -gt 500) -and ($actualExplosionThreads -gt 1)
	$parallelBatchSize = 1000  # Records per parallel batch
	$parallelThrottleLimit = $actualExplosionThreads

	# ── Explosion-mode bounded input spool (Blocker 1) ──────────────────────────
	# Capture the input count, then (in explosion mode) stream the deduped/trimmed
	# normalized records to a re-iterable JSON-lines disk spool and release the
	# in-memory collection so the explosion pass holds neither the complete
	# normalized set nor the exploded rows in memory. Serial sample-based schema
	# discovery streams from the spool. Mirrors the accepted RAW replay spool.
	$explosionInputCount = $allLogs.Count
	$script:ExplosionInputSpoolPath = $null
	if ($fullExplode -and -not $script:UseStreamingMergeForExport) {
		$script:ExplosionInputSpoolPath = Join-Path ([System.IO.Path]::GetTempPath()) ("pax_explode_spool_" + [guid]::NewGuid().ToString() + ".jsonl")
		$null = Write-PaxNormalizedSpool -Records $allLogs -SpoolPath $script:ExplosionInputSpoolPath
		try { Write-PaxMemoryObservation -Stage 'ExplosionSpool' -RowsProcessed ([long]$explosionInputCount) -Force } catch {}
		$allLogs = New-Object System.Collections.ArrayList   # release complete normalized set before explosion
		[System.GC]::Collect()
		$useParallelExplosion = $false   # bounded serial sample-schema path streams from the spool
		Write-LogHost ("Explosion input spooled to disk ({0:N0} records); streaming bounded explosion..." -f $explosionInputCount) -ForegroundColor DarkCyan
	}
	
	if ($useParallelExplosion) {
		Write-LogHost "Parallel processing: ENABLED (PS7+ detected, $parallelThrottleLimit threads)" -ForegroundColor Green
	} else {
		if (-not $script:IsPS7) {
			Write-LogHost "Parallel processing: DISABLED (requires PowerShell 7+)" -ForegroundColor Gray
		} elseif ($ExplosionThreads -eq 1) {
			Write-LogHost "Parallel processing: DISABLED (forced serial via -ExplosionThreads 1)" -ForegroundColor Gray
		} elseif ($effectiveRecordCount -le 500) {
			Write-LogHost "Parallel processing: DISABLED (only $effectiveRecordCount records - threshold is 500)" -ForegroundColor Gray
		}
	}
	
	# Schema discovery note: Parallel mode scans ALL rows for 100% column coverage; serial mode uses sampling
	if ($useParallelExplosion) {
		Write-LogHost "Streaming export mode enabled (parallel mode: full schema scan; base chunk size=$StreamingChunkSize)" -ForegroundColor Yellow
	} else {
		Write-LogHost "Streaming export mode enabled (schema sample=$StreamingSchemaSample; base chunk size=$StreamingChunkSize)" -ForegroundColor Yellow
	}
	$te0 = Get-Date
	$schemaFrozen = $false; $schemaSampleRows = New-Object System.Collections.Generic.List[object]; $postFreezeNewColumns = 0; $lateIgnoredColumns = New-Object System.Collections.Generic.HashSet[string]; $columnOrder = $null; $buffer = New-Object System.Collections.Generic.List[object]; $exportTemp = Join-Path ([System.IO.Path]::GetTempPath()) ("pax_export_" + [guid]::NewGuid().ToString() + ".tmp"); $csvWriter = $false
	
	# Ensure TotalRecordsFetched reflects allLogs count (may not have been set in all code paths)
	if ($script:metrics.TotalRecordsFetched -eq 0 -and $explosionInputCount -gt 0) {
		$script:metrics.TotalRecordsFetched = $explosionInputCount
	}
	
	# ═══════════════════════════════════════════════════════════════════════════════
	# NON-EXPLOSION FAST PATH: Direct stream to CSV with fixed schema (skip parallel overhead)
	# ═══════════════════════════════════════════════════════════════════════════════
	if (-not $fullExplode) {
		
		# STREAMING MERGE PATH - Handle large resume scenarios without loading into memory
		if ($script:UseStreamingMergeForExport) {
			Write-LogHost "Non-explosion fast path: STREAMING MERGE MODE (memory-efficient)" -ForegroundColor Cyan
			Write-LogHost "  Streaming directly from incremental files to avoid memory exhaustion..." -ForegroundColor DarkGray
			$fastPathStart = Get-Date
			$fastPathColumns = @('RecordId', 'CreationDate', 'RecordType', 'Operation', 'UserId', 'AuditData', 'AssociatedAdminUnits', 'AssociatedAdminUnitsNames')
			
			# [RESUME-RECONCILE] Include this-run partition shards that exist on disk but are missing
			# from the streaming-merge set. On resume, partitions completed during THIS run can flush
			# their records to JSONL shards (thread-side parallel persistence) while $allLogs stays
			# empty and $script:memoryFlushed never latches (e.g. a missed worker result event). In
			# that case the resume path set $script:StreamingMergePartitions to previously-skipped
			# partitions only, and the worker-flush recovery guard ($effectiveRecordCount -eq 0) could
			# not fire because the prior-run deferred merge already contributed records — so the
			# this-run shards were silently dropped from the export. Reconcile against on-disk truth.
			# Safe by construction: only partitions that actually have a shard file are added (so the
			# DATA-LOSS validation below cannot be tripped), and any records also present in memory are
			# de-duplicated downstream via -ExcludeRecordIds $inMemoryRecordIds.
			if ($script:IsResumeMode) {
				$reconcileIncrDir = Join-Path $script:StreamingMergeDirectory ".pax_incremental"
				if (Test-Path $reconcileIncrDir) {
					$reconcileShardFiles = @(Get-ChildItem -Path $reconcileIncrDir -Filter "*_${global:ScriptRunTimestamp}_*.jsonl" -ErrorAction SilentlyContinue)
					$reconcileShardIndices = @($reconcileShardFiles | ForEach-Object { if ($_.Name -match '^Part(\d+)_') { [int]$Matches[1] } } | Sort-Object -Unique)
					$reconcileMissing = @($reconcileShardIndices | Where-Object { $_ -notin @($script:StreamingMergePartitions) })
					if ($reconcileMissing.Count -gt 0) {
						$script:StreamingMergePartitions = @(@($script:StreamingMergePartitions) + $reconcileMissing | Where-Object { $null -ne $_ } | Select-Object -Unique | Sort-Object)
						Write-LogHost "  [RESUME-RECONCILE] Recovered $($reconcileMissing.Count) this-run partition shard(s) missing from merge set: $($reconcileMissing -join ', ')" -ForegroundColor Cyan
					}
				}
			}
			
			# First, write any in-memory records from THIS run's partitions (if any)
			$inMemoryCount = $allLogs.Count
			$streamingActivityCounts = @{}
			if ($inMemoryCount -gt 0) {
				Write-LogHost "  Writing $($inMemoryCount.ToString('N0')) in-memory records from current run..." -ForegroundColor DarkCyan
				Open-CsvWriter -Path $exportTemp -Columns $fastPathColumns
				$csvWriter = $true
				
				$batch = New-Object System.Collections.Generic.List[object]
				$inMemoryRecordIds = New-Object System.Collections.Generic.HashSet[string]
				$batchSize = 5000
				foreach ($log in $allLogs) {
					$auditData = $log.AuditData
					$parsedAudit = if ($log.PSObject.Properties['_ParsedAuditData']) { $log._ParsedAuditData } else { try { $auditData | ConvertFrom-Json -ErrorAction SilentlyContinue } catch { $null } }
					$opValue = if ($parsedAudit -and $parsedAudit.Operation) { $parsedAudit.Operation } else { $log.Operations }
					
					# Track per-activity counts for Activity Type Breakdown
					if ($opValue) {
						if (-not $streamingActivityCounts.ContainsKey($opValue)) { $streamingActivityCounts[$opValue] = 0 }
						$streamingActivityCounts[$opValue]++
					}
					
					$fastRecord = [pscustomobject]@{
						RecordId                  = if ($log.RecordId) { $log.RecordId } elseif ($log.Identity) { $log.Identity } elseif ($log.Id) { $log.Id } elseif ($parsedAudit -and $parsedAudit.Id) { $parsedAudit.Id } else { $null }
						CreationDate              = if ($log.CreationDate) { $log.CreationDate.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture) } else { '' }
						RecordType                = $log.RecordType
						Operation                 = $opValue
						UserId                    = if ($log.UserId) { $log.UserId } elseif ($log.UserIds) { $log.UserIds } else { '' }
						AuditData                 = $auditData
						AssociatedAdminUnits      = $(try { if ($parsedAudit.AssociatedAdminUnits) { $parsedAudit.AssociatedAdminUnits } elseif ($log.AssociatedAdminUnits) { $log.AssociatedAdminUnits } else { '' } } catch { '' })
						AssociatedAdminUnitsNames = $(try { if ($parsedAudit.AssociatedAdminUnitsNames) { $parsedAudit.AssociatedAdminUnitsNames } elseif ($log.AssociatedAdminUnitsNames) { $log.AssociatedAdminUnitsNames } else { '' } } catch { '' })
					}
					$batch.Add($fastRecord)
					if ($fastRecord.RecordId) { [void]$inMemoryRecordIds.Add($fastRecord.RecordId) }
					
					if ($batch.Count -ge $batchSize) {
						Write-CsvRows -Rows $batch -Columns $fastPathColumns
						$batch.Clear()
					}
				}
				if ($batch.Count -gt 0) {
					Write-CsvRows -Rows $batch -Columns $fastPathColumns
					$batch.Clear()
				}
				Close-CsvWriter
				$csvWriter = $false
				
				# Clear in-memory collection to free RAM before streaming merge
				$allLogs.Clear()
				[GC]::Collect()
				Write-LogHost "  In-memory records written, RAM freed" -ForegroundColor DarkGray
			}
			
			# Validate JSONL file count vs expected partition count before streaming merge
			# Detect data loss early — if fewer files exist than completed partitions, warn and mark output as PARTIAL
			$validationIncrDir = Join-Path $script:StreamingMergeDirectory ".pax_incremental"
			$expectedPartitionCount = @($script:StreamingMergePartitions).Count
			$actualJsonlFiles = @()
			if (Test-Path $validationIncrDir) {
				$actualJsonlFiles = @(Get-ChildItem -Path $validationIncrDir -Filter "*_${global:ScriptRunTimestamp}_*.jsonl" -ErrorAction SilentlyContinue)
			}
			$actualFileCount = $actualJsonlFiles.Count
			if ($actualFileCount -lt $expectedPartitionCount) {
				# Identify which partition numbers have files vs which are missing
				$partitionsWithFiles = @($actualJsonlFiles | ForEach-Object { if ($_.Name -match '^Part(\d+)_') { [int]$Matches[1] } } | Sort-Object -Unique)
				$missingPartitions = @($script:StreamingMergePartitions | Where-Object { $_ -notin $partitionsWithFiles } | Sort-Object)
				# Exclude partitions that returned 0 records — a missing JSONL file is expected for those
				$trulyMissingPartitions = @($missingPartitions | Where-Object { [int]($script:partitionStatus[$_].RecordCount ?? 0) -gt 0 })
				if ($trulyMissingPartitions.Count -gt 0) {
					Write-LogHost "" -ForegroundColor Yellow
					Write-LogHost "  [DATA-LOSS] WARNING: Only $actualFileCount of $expectedPartitionCount partition JSONL files found for this run" -ForegroundColor Yellow
					Write-LogHost "  [DATA-LOSS] Missing partition data: $($trulyMissingPartitions -join ', ')" -ForegroundColor Yellow
					Write-LogHost "  [DATA-LOSS] Output will be marked as PARTIAL due to incomplete data" -ForegroundColor Yellow
					Write-LogHost "" -ForegroundColor Yellow
					# Mark output as PARTIAL by updating the output file name
					$script:StreamingMergeDataLoss = $true
					$script:StreamingMergeMissingPartitions = $trulyMissingPartitions
				} else {
					# All "missing" partitions returned 0 records — no actual data loss
					$script:StreamingMergeDataLoss = $false
				}
			} else {
				$script:StreamingMergeDataLoss = $false
			}
			
			# Now stream merge the completed partitions directly to CSV
			Write-LogHost "  Streaming merge of $($script:StreamingMergePartitions.Count) completed partitions..." -ForegroundColor Cyan

			# -AppendFile cross-run dedup (rollup mode only): seed the exclude-set with
			# RecordIds already present in the target file so the post-Python rollup
			# append only sees new records. Rollup-gated because under non-rollup
			# -AppendFile the inline Merge-FactCsv below performs a full union and
			# depends on the streaming output containing ALL current-run rows —
			# pre-excluding target-seen RecordIds here would cause Merge-FactCsv to
			# misclassify those rows as Departed (target-only).
			$appendFileSeenIds = $null
			if ($AppendFile -and ($Rollup -or $RollupPlusRaw) -and (Test-Path -LiteralPath $AppendFile -PathType Leaf)) {
				$appendFileSeenIds = Get-AppendFileRecordIds -Path $AppendFile
				if ($appendFileSeenIds -and $appendFileSeenIds.Count -gt 0) {
					Write-LogHost ("  -AppendFile: seeded cross-run dedup with {0:N0} existing RecordId(s) from target." -f $appendFileSeenIds.Count) -ForegroundColor DarkCyan
				}
			}

			# If we already wrote in-memory records, we need to append to the temp file
			if ($inMemoryCount -gt 0) {
				if ($appendFileSeenIds -and $appendFileSeenIds.Count -gt 0) {
					foreach ($rid in $appendFileSeenIds) { [void]$inMemoryRecordIds.Add($rid) }
				}
				# Streaming merge needs to append to existing file - use a second temp file then combine
				$streamingTemp = Join-Path ([System.IO.Path]::GetTempPath()) ("pax_streaming_" + [guid]::NewGuid().ToString() + ".tmp")
				$streamedCount = Merge-IncrementalSaves-Streaming -OutputFile $streamingTemp -OutputDirectory $script:StreamingMergeDirectory -OnlyPartitionIndices $script:StreamingMergePartitions -Columns $fastPathColumns -ExcludeRecordIds $inMemoryRecordIds -ActivityCounts ([ref]$streamingActivityCounts) -RunTimestamp $global:ScriptRunTimestamp
				
				# Append streaming temp to main temp (skip header line from streaming file)
				if ((Test-Path $streamingTemp) -and $streamedCount -gt 0) {
					Write-LogHost "  Combining in-memory and streamed data..." -ForegroundColor DarkGray
					Get-Content $streamingTemp | Select-Object -Skip 1 | Add-Content $exportTemp
					Remove-Item $streamingTemp -Force -ErrorAction SilentlyContinue
				}
				$totalStreamedRecords = $inMemoryCount + $streamedCount
			} else {
				# No in-memory records - stream directly to final temp file
				$totalStreamedRecords = Merge-IncrementalSaves-Streaming -OutputFile $exportTemp -OutputDirectory $script:StreamingMergeDirectory -OnlyPartitionIndices $script:StreamingMergePartitions -Columns $fastPathColumns -ExcludeRecordIds $appendFileSeenIds -ActivityCounts ([ref]$streamingActivityCounts) -RunTimestamp $global:ScriptRunTimestamp
			}
			
			# If data loss detected, rename output to include _PARTIAL suffix so users know data is incomplete
			if ($script:StreamingMergeDataLoss) {
				$outDir = Split-Path $OutputFile -Parent
				$outBase = [System.IO.Path]::GetFileNameWithoutExtension($OutputFile)
				$outExt = [System.IO.Path]::GetExtension($OutputFile)
				# Only add _PARTIAL suffix if not already present (avoid _PARTIAL_PARTIAL)
				if ($outBase -notmatch '_PARTIAL$') {
					$OutputFile = Join-Path $outDir "${outBase}_PARTIAL${outExt}"
				}
				Write-LogHost "  [DATA-LOSS] Output file renamed to: $(Split-Path $OutputFile -Leaf)" -ForegroundColor Yellow
				Write-LogHost "  [DATA-LOSS] Missing partitions: $($script:StreamingMergeMissingPartitions -join ', ')" -ForegroundColor Yellow
			}
			
			# Move temp file to final output
			if (Test-Path $exportTemp) {
				Move-Item -Path $exportTemp -Destination $OutputFile -Force
			}
			
			$fastPathElapsed = (Get-Date) - $fastPathStart
			$fastPathRate = if ($fastPathElapsed.TotalSeconds -gt 0) { [int]($totalStreamedRecords / $fastPathElapsed.TotalSeconds) } else { 0 }
			Write-LogHost "Streaming merge export complete: $($totalStreamedRecords.ToString('N0')) records in $([Math]::Round($fastPathElapsed.TotalSeconds, 1))s ($fastPathRate rec/sec)" -ForegroundColor Green
			# Non-rollup -AppendFile under streaming-merge: the Move-Item above wrote the
			# current-run rows into the _PARTIAL.csv scratch (which is what $OutputFile
			# resolves to under -AppendFile + checkpointing). Union the streaming output
			# into the $AppendFile target via Merge-FactCsv (full union + tri-columns),
			# matching the contract of the standard (non-streaming) -AppendFile path.
			# Under -Rollup / -RollupPlusRaw, the Phase-2 rollup post-processor is what
			# merges into the -AppendFile target — skip this inline merge under rollup.
			# Skip under data-loss too: the streaming output was intentionally suffixed
			# _PARTIAL above to signal incomplete data, and must not be unioned into the
			# customer's target. Remote tiers (SharePoint / Fabric) are covered because
			# -AppendFile is redirected to a local scratch copy earlier in the run; the
			# end-of-run upload sweep ships the merged union back to the remote URL.
			#
			# Effective AppendFile path: the bound $AppendFile is the canonical source;
			# the checkpoint's persisted parameter is a defensive fallback for resume
			# runs where the variable is empty. The fallback is restricted to non-URL
			# values because remote-tier -AppendFile (SharePoint/Fabric URL) is
			# redirected to a local scratch path earlier in the resume re-resolve
			# block — if that redirect ran, $AppendFile is already populated; if it
			# did not run, there is no local scratch to merge into and we must not
			# attempt to merge against a raw remote URL.
			$_smAppendFile = if ($AppendFile) {
				[string]$AppendFile
			} elseif ([bool]$script:CheckpointData -and `
			          [bool]$script:CheckpointData.parameters -and `
			          [bool]$script:CheckpointData.parameters.appendFile -and `
			          ([string]$script:CheckpointData.parameters.appendFile) -notmatch '^https?://') {
				[string]$script:CheckpointData.parameters.appendFile
			} else { '' }
			if ($_smAppendFile -and -not ($Rollup -or $RollupPlusRaw) -and -not $script:StreamingMergeDataLoss -and (Test-Path -LiteralPath $OutputFile -PathType Leaf)) {
				# Anchor the temp working copy in the parent directory of $OutputFile
				# (the _PARTIAL.csv scratch). $OutputPath cannot be trusted here: under
				# some -AppendFile invocations (including the parse-time inference path
				# when -OutputPath is omitted) $OutputPath resolves to the AppendFile
				# target FILE rather than the directory containing it, and a Join-Path
				# against that produces an invalid path of the shape
				# "<target>.csv\Temp_NewData_StreamingMerge_*.csv". Use
				# [System.IO.Path]::GetDirectoryName instead of Split-Path: in this
				# PowerShell, Split-Path's -LiteralPath parameter set does NOT include
				# the -Parent switch (only the -Path set does), so combining them
				# throws "Parameter set cannot be resolved using the specified named
				# parameters" even on a perfectly valid string path.
				$_smScratchDir = [System.IO.Path]::GetDirectoryName($OutputFile)
				$_smTempCsv = Join-Path $_smScratchDir ("Temp_NewData_StreamingMerge_{0}.csv" -f $global:ScriptRunTimestamp)
				try {
					Move-Item -LiteralPath $OutputFile -Destination $_smTempCsv -Force -ErrorAction Stop
					Write-LogHost "Appending new data to existing CSV: $(Get-DisplayPath -LocalPath $_smAppendFile)" -ForegroundColor Cyan
					$_smMergeStats = Merge-FactCsv -TargetFactCsv $_smAppendFile -CurrentFactCsv $_smTempCsv -KeyColumn 'RecordId' -OutputPath $_smAppendFile
					Write-LogHost ("  -AppendFile merge: Retained={0:N0}  New={1:N0}  Departed={2:N0}  Union={3:N0}" -f $_smMergeStats.Retained, $_smMergeStats.New, $_smMergeStats.Departed, $_smMergeStats.Union) -ForegroundColor Green
					$_smAfDisplay = if ($script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) { $script:AppendRaw['Purview'] } else { Get-DisplayPath -LocalPath $_smAppendFile }
					Write-LogHost ("Appended to: {0}" -f $_smAfDisplay) -ForegroundColor White
					Remove-Item -LiteralPath $_smTempCsv -Force -ErrorAction SilentlyContinue
					# Re-target $OutputFile to the AppendFile result so downstream
					# Test-Path / display / upload-sweep references resolve to the
					# merged union (not the now-deleted _PARTIAL scratch). Clear
					# $script:PartialOutputPath so Complete-CheckpointRun does not
					# attempt to rename a non-existent _PARTIAL file (and so its
					# collision-avoidance logic cannot drop a stray *_<timestamp>.csv
					# beside the AppendFile target).
					$OutputFile = $_smAppendFile
					$script:PartialOutputPath = $null
				}
				catch {
					Write-Host "ERROR: Failed to merge streaming-merge output into -AppendFile target: $($_.Exception.Message)" -ForegroundColor Red
					Write-Host "  AppendFile target: $_smAppendFile" -ForegroundColor Yellow
					Write-Host "  New data (temp):   $_smTempCsv" -ForegroundColor Yellow
					Write-Host "" -ForegroundColor Yellow
					Write-Host "Possible causes:" -ForegroundColor Yellow
					Write-Host "  - File is open in Excel or another program" -ForegroundColor Gray
					Write-Host "  - Insufficient permissions" -ForegroundColor Gray
					Write-Host "  - Column mismatch between files" -ForegroundColor Gray
					Write-Host "" -ForegroundColor Yellow
					Write-Host "The new data is preserved in: $_smTempCsv" -ForegroundColor Cyan
					throw
				}
			}
			# Surface the Purview CSV destination here so the Enterprise Processing
			# Summary lists ALL output streams (Purview + EntraUsers + later Agent365/log).
			# Under -Rollup / -RollupPlusRaw the audit phase only writes the raw scratch CSV;
			# the Phase-2 rollup phase is what merges into the -AppendFile target (and emits
			# its own "Appended to: ..." line). So when rollup is active, report the RAW path
			# here regardless of -AppendFile. Under non-rollup -AppendFile the streaming merge
			# itself produced the union, so report the AppendFile target's canonical URL/path.
			# Uses $_smAppendFile (effective AppendFile, with checkpoint-param fallback) so
			# the verb/display stay correct under the same conditions that govern the inline
			# merge above.
			$_rollupActive = ($Rollup -or $RollupPlusRaw)
			$_purviewVerb = if ($_smAppendFile -and -not $_rollupActive) { 'Purview CSV updated (append-merge)' }
			                 elseif ($_rollupActive)                    { 'Raw Purview CSV' }
			                 else                                       { 'Purview CSV created' }
			# $OutputFile is the local scratch _PARTIAL.csv path at this point in
			# the run (it gets renamed to the non-_PARTIAL leaf at end-of-run, just
			# before the upload sweep). A naive remote-mode branch that joined
			# $script:RemoteOutputUrl to GetFileName($OutputFile) verbatim would bake
			# '_PARTIAL.csv' into the advertised SharePoint/OneLake URL — an object
			# that never exists remotely. Strip _PARTIAL from the leaf first so the
			# displayed URL matches what the end-of-run upload sweep actually creates
			# (same shape as the banner Run log row resolution above).
			$_purviewLeaf = [System.IO.Path]::GetFileName($OutputFile) -replace '_PARTIAL(?=\.[^.]+$)', ''
			$_purviewDisplay = if ($_smAppendFile -and -not $_rollupActive -and $script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) {
				$script:AppendRaw['Purview']
			} elseif ($_smAppendFile -and -not $_rollupActive) {
				Get-DisplayPath -LocalPath $_smAppendFile
			} elseif ($script:RemoteOutputMode -ne 'None' -and $script:RemoteOutputUrl) {
				$script:RemoteOutputUrl.TrimEnd('/') + '/' + $_purviewLeaf
			} else {
				$_purviewFinalLocal = $OutputFile -replace '_PARTIAL(?=\.[^.]+$)', ''
				Get-DisplayPath -LocalPath $_purviewFinalLocal
			}
			Write-LogHost ("{0}: {1}" -f $_purviewVerb, $_purviewDisplay) -ForegroundColor Green
			
			# Update metrics
			$script:metrics.TotalStructuredRows = $totalStreamedRecords
			$structuredDataCount = $totalStreamedRecords
			$processedRecordCount = $totalStreamedRecords
			$columnOrder = $fastPathColumns
			$schemaFrozen = $true
			
			# Update Retrieved counter to reflect actual streaming merge data
			# actual = exported unique records + duplicates removed (more accurate than filename-based estimate)
			$actualRetrievedFromMerge = $totalStreamedRecords + [int]$script:StreamingMergeDuplicatesSkipped
			if ($actualRetrievedFromMerge -gt 0) {
				$script:metrics.TotalRecordsFetched = $actualRetrievedFromMerge
			}
			
			# Populate per-activity metrics from actual streaming counts (inline handlers don't track these reliably)
			$script:metrics.Activities = @{}
			foreach ($opKey in $streamingActivityCounts.Keys) {
				$script:metrics.Activities[$opKey] = @{ Retrieved = $streamingActivityCounts[$opKey]; Structured = $streamingActivityCounts[$opKey] }
			}
			
			# Store original count for ratio comparisons (allLogs was cleared for RAM)
			$script:OriginalInputRecordCount = $totalStreamedRecords
			
			# Skip the normal fast path processing below
			$script:StreamingMergeCompleted = $true
		}
		# END STREAMING MERGE PATH
		
		# Standard non-explosion fast path (original code, only runs if NOT using streaming merge)
		if (-not $script:UseStreamingMergeForExport) {
		Write-LogHost "Non-explosion fast path: Direct streaming with fixed 8-column schema..." -ForegroundColor Cyan
		$fastPathStart = Get-Date
		
		# Fixed schema for non-explosion mode (column names match Purview UI export)
		$fastPathColumns = @('RecordId', 'CreationDate', 'RecordType', 'Operation', 'UserId', 'AuditData', 'AssociatedAdminUnits', 'AssociatedAdminUnitsNames')
		
		# Open CSV with known schema immediately
		Open-CsvWriter -Path $exportTemp -Columns $fastPathColumns
		$csvWriter = $true
		
		# Stream directly - minimal transformation
		$batchSize = 5000
		$batch = New-Object System.Collections.Generic.List[object]
		$processedCount = 0
		$lastProgressTime = Get-Date
		
		# Track per-activity export counts for metrics (fast path)
		$fastPathActivityCounts = @{}
		
		foreach ($log in $allLogs) {
			$processedCount++
			
			# Minimal record creation (no full Convert-ToStructuredRecord overhead)
			$auditData = $log.AuditData
			$parsedAudit = if ($log.PSObject.Properties['_ParsedAuditData']) { $log._ParsedAuditData } else { try { $auditData | ConvertFrom-Json -ErrorAction SilentlyContinue } catch { $null } }
			$opValue = if ($parsedAudit -and $parsedAudit.Operation) { $parsedAudit.Operation } else { $log.Operations }
			
			# Track per-activity counts
			$opKey = if ($opValue) { [string]$opValue } else { 'Unknown' }
			if (-not $fastPathActivityCounts.ContainsKey($opKey)) { $fastPathActivityCounts[$opKey] = 0 }
			$fastPathActivityCounts[$opKey]++
			
			$fastRecord = [pscustomobject]@{
				RecordId                  = if ($log.RecordId) { $log.RecordId } elseif ($log.Identity) { $log.Identity } elseif ($log.Id) { $log.Id } elseif ($parsedAudit -and $parsedAudit.Id) { $parsedAudit.Id } else { $null }
				CreationDate              = if ($log.CreationDate) { $log.CreationDate.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture) } else { '' }
				RecordType                = $log.RecordType
				Operation                 = $opValue
				UserId                    = if ($log.UserId) { $log.UserId } elseif ($log.UserIds) { $log.UserIds } else { '' }
				AuditData                 = $auditData
				AssociatedAdminUnits      = $(try { if ($parsedAudit.AssociatedAdminUnits) { $parsedAudit.AssociatedAdminUnits } elseif ($log.AssociatedAdminUnits) { $log.AssociatedAdminUnits } else { '' } } catch { '' })
				AssociatedAdminUnitsNames = $(try { if ($parsedAudit.AssociatedAdminUnitsNames) { $parsedAudit.AssociatedAdminUnitsNames } elseif ($log.AssociatedAdminUnitsNames) { $log.AssociatedAdminUnitsNames } else { '' } } catch { '' })
			}
			
			$batch.Add($fastRecord)
			
			if ($batch.Count -ge $batchSize) {
				Write-CsvRows -Rows $batch -Columns $fastPathColumns
				$batch.Clear()
				
				# Progress every 60 seconds
				if (((Get-Date) - $lastProgressTime).TotalSeconds -ge 60) {
					$elapsed = (Get-Date) - $fastPathStart
					$rate = [int]($processedCount / $elapsed.TotalSeconds)
					$pct = [int](($processedCount / $allLogs.Count) * 100)
					Write-LogHost ("[{0}] Fast path: {1:N0}/{2:N0} ({3}%) | ~{4:N0} rec/sec" -f (Get-Date -Format "HH:mm:ss"), $processedCount, $allLogs.Count, $pct, $rate) -ForegroundColor DarkCyan
					$lastProgressTime = Get-Date
				}
			}
		}
		
		# Flush remaining batch
		if ($batch.Count -gt 0) {
			Write-CsvRows -Rows $batch -Columns $fastPathColumns
			$batch.Clear()
		}
		
		Close-CsvWriter
		$csvWriter = $false
		
		# Move temp file to final output
		if (Test-Path $exportTemp) {
			Move-Item -Path $exportTemp -Destination $OutputFile -Force
		}
		
		$fastPathElapsed = (Get-Date) - $fastPathStart
		$fastPathRate = if ($fastPathElapsed.TotalSeconds -gt 0) { [int]($allLogs.Count / $fastPathElapsed.TotalSeconds) } else { 0 }
		Write-LogHost "Non-explosion fast path complete: $($allLogs.Count) records in $([Math]::Round($fastPathElapsed.TotalSeconds, 1))s ($fastPathRate rec/sec)" -ForegroundColor Green
		
		# Update metrics
		$script:metrics.TotalStructuredRows = $allLogs.Count
		$structuredDataCount = $allLogs.Count
		$processedRecordCount = $allLogs.Count
		$columnOrder = $fastPathColumns
		$schemaFrozen = $true
		
		# Merge fast path activity counts into script:metrics.Activities (for Activity Type Breakdown)
		# In fast path (non-explosion), Retrieved and Structured are equal (1:1 mapping)
		foreach ($opKey in $fastPathActivityCounts.Keys) {
			if (-not $script:metrics.Activities.ContainsKey($opKey)) {
				$script:metrics.Activities[$opKey] = @{ Retrieved = 0; Structured = 0 }
			}
			$script:metrics.Activities[$opKey].Retrieved += $fastPathActivityCounts[$opKey]
			$script:metrics.Activities[$opKey].Structured += $fastPathActivityCounts[$opKey]
		}
		
		# Skip to post-processing (bypass parallel and serial paths)
		$skipToPostProcessing = $true
		} # End of standard non-explosion fast path (if not using streaming merge)
		
		# If streaming merge was used, also skip to post-processing
		if ($script:UseStreamingMergeForExport) {
			$skipToPostProcessing = $true
		}
	} else {
		$skipToPostProcessing = $false
	}
	# A zero-record AISID run emitted the header-only Purview CSV above and must skip the
	# explosion (there are no records to explode) yet still reach post-processing (Rollup -> Entra ->
	# AISID export -> completion/roster). Route it to post-processing using the already-written CSV.
	if ($script:ZeroRecordContinueToPostProcessing) { $skipToPostProcessing = $true }
	
	# ═══════════════════════════════════════════════════════════════════════════════
	# PARALLEL MODE: Skip serial loop entirely - do parallel schema discovery + processing
	# ═══════════════════════════════════════════════════════════════════════════════
	if (-not $skipToPostProcessing -and $useParallelExplosion) {
		# Jump to parallel processing block (after the serial foreach loop)
		$processedRecordCount = 0
		$schemaFrozen = $false
		# Fall through to parallel block below (skip serial foreach)
	} elseif (-not $skipToPostProcessing) {
		# SERIAL MODE: Original foreach loop for PS5 compatibility
		
		# Explosion progress tracking (provides heartbeat for long-running explosion phase)
		$explosionProgressInterval = 20000
		$processedRecordCount = 0
		$lastProgressUpdate = 0

		# ── Full-schema discovery prepass (Blocker 2) ──────────────────────────────
		# Scan the COMPLETE spool once, exploding each record to derive every column the
		# selected mode can emit — including columns that first appear only in late
		# records — WITHOUT retaining any row values or exploded row objects. Only column
		# NAMES accumulate (bounded by schema width, not row count). The complete header is
		# frozen and written BEFORE any output row, so no late column is ever missed. The
		# per-record explosion below then streams straight to the post-freeze write path.
		if ($script:ExplosionInputSpoolPath) {
			$columnOrder = New-Object System.Collections.Generic.List[string]
			if ($ExplodeArrays -or $ExplodeDeep -or $ForcedRawInputCsvExplosion) {
				if ($IncludeM365Usage -and $RAWInputCSV) {
					foreach ($c in (Get-M365UsageWideHeader -RawCsvPath $RAWInputCSV -BaseHeader $M365UsageBaseHeader)) { [void]$columnOrder.Add($c) }
				} else {
					foreach ($c in $PurviewExplodedHeader) { [void]$columnOrder.Add($c) }
				}
				if ($ExplodeDeep -and $script:DeepExtraColumns -and $script:DeepExtraColumns.Count -gt 0) {
					foreach ($c in $script:DeepExtraColumns) { if (-not $columnOrder.Contains($c)) { [void]$columnOrder.Add($c) } }
				}
			}
			$schemaScanSeen = 0
			foreach ($schemaLine in [System.IO.File]::ReadLines($script:ExplosionInputSpoolPath)) {
				$slog = ConvertFrom-PaxNormalizedSpoolLine -Line $schemaLine
				if ($null -eq $slog) { continue }
				$srecords = if ($effectiveExplode) { Convert-ToPurviewExplodedRecords -Record $slog -Deep:$ExplodeDeep -PartialExplode:$partialExplode -PromptFilterValue $PromptFilter -SkipMetrics } else { Convert-ToStructuredRecord -Record $slog -EnableExplosion:$false }
				foreach ($sr in (To-RecordArray $srecords)) {
					if ($null -eq $sr) { continue }
					foreach ($pn in $sr.PSObject.Properties.Name) { if (-not $columnOrder.Contains($pn)) { [void]$columnOrder.Add($pn) } }
				}
				$schemaScanSeen++
				if (($schemaScanSeen % 20000) -eq 0) { Write-LogHost ("Schema scan: {0:N0} records" -f $schemaScanSeen) -ForegroundColor DarkGray; try { Write-PaxMemoryObservation -Stage 'ExplosionSchemaScan' -RowsProcessed ([long]$schemaScanSeen) } catch {} }
			}
			try { Write-PaxMemoryObservation -Stage 'ExplosionSchemaScan' -RowsProcessed ([long]$schemaScanSeen) -Force } catch {}
			# Only pre-freeze when the scan produced a schema (array/deep always seed a base header;
			# standard mode with a non-empty spool discovers columns). An empty result falls through to
			# the established small-dataset finalization below.
			if ($columnOrder.Count -gt 0) {
				$effectiveChunkSize = $StreamingChunkSize
				$colCount = $columnOrder.Count
				if ($colCount -gt 1000) { $effectiveChunkSize = [int][Math]::Min($effectiveChunkSize, 1000) }
				elseif ($colCount -gt 750) { $effectiveChunkSize = [int][Math]::Min($effectiveChunkSize, 1500) }
				elseif ($colCount -gt 500) { $effectiveChunkSize = [int][Math]::Min($effectiveChunkSize, 2500) }
				elseif ($colCount -gt 250) { $effectiveChunkSize = [int][Math]::Min($effectiveChunkSize, 4000) }
				else { if ($colCount -le 60 -and $StreamingChunkSize -lt 15000) { $autoBoost = [int][Math]::Min(15000, [Math]::Max($StreamingChunkSize * 3, 8000)); $effectiveChunkSize = $autoBoost } }
				$script:metrics.EffectiveChunkSize = $effectiveChunkSize
				if (-not $csvWriter) { Open-CsvWriter -Path $exportTemp -Columns $columnOrder; $csvWriter = $true }
				$schemaFrozen = $true
				Write-LogHost "Schema frozen with $($columnOrder.Count) columns after a full-spool scan of $($schemaScanSeen) records (bounded prepass — complete schema, no late-column loss)" -ForegroundColor DarkCyan
			}
		}
	
	foreach ($spoolLine in $(if ($script:ExplosionInputSpoolPath) { [System.IO.File]::ReadLines($script:ExplosionInputSpoolPath) } else { @() })) {
		$log = ConvertFrom-PaxNormalizedSpoolLine -Line $spoolLine
		if ($null -eq $log) { continue }
		$processedRecordCount++
		
		# NOTE: Retrieved counts are tracked during partition retrieval (lines 11052, 11431, 11784)
		# Do NOT increment here - that would double-count records
		
		# Periodic progress update (every 20K records)
		if ($processedRecordCount -ge ($lastProgressUpdate + $explosionProgressInterval)) {
			$elapsed = (Get-Date) - $te0
			$rate = [int]($processedRecordCount / $elapsed.TotalSeconds)
			$pct = [int](($processedRecordCount / $explosionInputCount) * 100)
			$elapsedStr = if ($elapsed.TotalMinutes -ge 1) { 
				"{0}m {1}s" -f [int]$elapsed.TotalMinutes, $elapsed.Seconds 
			} else { 
				"{0}s" -f [int]$elapsed.TotalSeconds 
			}
			Write-LogHost ("[{0}] Processing: {1:N0} / {2:N0} records ({3}%) | Elapsed: {4} | Rate: {5:N0} rec/sec" -f (Get-Date -Format "HH:mm:ss"), $processedRecordCount, $explosionInputCount, $pct, $elapsedStr, $rate) -ForegroundColor DarkCyan
			$lastProgressUpdate = $processedRecordCount
		}
		$records = if ($effectiveExplode) { Convert-ToPurviewExplodedRecords -Record $log -Deep:$ExplodeDeep -PartialExplode:$partialExplode -PromptFilterValue $PromptFilter } else { Convert-ToStructuredRecord -Record $log -EnableExplosion:$false }
		$recordsArr = To-RecordArray $records
		if ($recordsArr.Count -gt 0) {
			try {
				$script:metrics.TotalStructuredRows += $recordsArr.Count
				$structuredDataCount += $recordsArr.Count
				$opName = $null; try { $opName = if ($log.Operation) { [string]$log.Operation } elseif ($log.Operations) { [string]$log.Operations } else { $null } } catch {}; if (-not $opName) { $opName = 'Unknown' }; if (-not $script:metrics.Activities.ContainsKey($opName)) { $script:metrics.Activities[$opName] = @{ Retrieved = 0; Structured = 0 } }; $script:metrics.Activities[$opName].Structured += $recordsArr.Count
			} catch {}
			foreach ($r in $recordsArr) {
				if (-not $schemaFrozen) {
					$schemaSampleRows.Add($r) | Out-Null
					if ($schemaSampleRows.Count -ge $StreamingSchemaSample) {
						if ($ExplodeArrays -or $ExplodeDeep -or $ForcedRawInputCsvExplosion) {
							$columnOrder = New-Object System.Collections.Generic.List[string]
							if ($IncludeM365Usage -and $RAWInputCSV) {
								foreach ($c in (Get-M365UsageWideHeader -RawCsvPath $RAWInputCSV -BaseHeader $M365UsageBaseHeader)) { [void]$columnOrder.Add($c) }
							} else {
								foreach ($c in $PurviewExplodedHeader) { [void]$columnOrder.Add($c) }
							}
							if ($ExplodeDeep -and $script:DeepExtraColumns -and $script:DeepExtraColumns.Count -gt 0) {
								foreach ($c in $script:DeepExtraColumns) { if (-not $columnOrder.Contains($c)) { [void]$columnOrder.Add($c) } }
							}
							# Augment header with discovered columns (live or replay)
							foreach ($sr in $schemaSampleRows) { foreach ($pn in $sr.PSObject.Properties.Name) { if (-not $columnOrder.Contains($pn)) { [void]$columnOrder.Add($pn) } } }
						}
						else {
							$columnOrder = New-Object System.Collections.Generic.List[string]
							foreach ($sr in $schemaSampleRows) { foreach ($pn in $sr.PSObject.Properties.Name) { if (-not $columnOrder.Contains($pn)) { [void]$columnOrder.Add($pn) } } }
						}
						Write-LogHost "Schema frozen with $($columnOrder.Count) columns after $($schemaSampleRows.Count) sample rows (serial mode - sample-based)" -ForegroundColor DarkCyan
						$effectiveChunkSize = $StreamingChunkSize
						$colCount = $columnOrder.Count
						if ($colCount -gt 1000) { $effectiveChunkSize = [int][Math]::Min($effectiveChunkSize, 1000) }
						elseif ($colCount -gt 750) { $effectiveChunkSize = [int][Math]::Min($effectiveChunkSize, 1500) }
						elseif ($colCount -gt 500) { $effectiveChunkSize = [int][Math]::Min($effectiveChunkSize, 2500) }
						elseif ($colCount -gt 250) { $effectiveChunkSize = [int][Math]::Min($effectiveChunkSize, 4000) }
						else { if ($colCount -le 60 -and $StreamingChunkSize -lt 15000) { $autoBoost = [int][Math]::Min(15000, [Math]::Max($StreamingChunkSize * 3, 8000)); $effectiveChunkSize = $autoBoost } }
						if ($effectiveChunkSize -ne $StreamingChunkSize) { Write-LogHost "Adaptive chunk size applied: $effectiveChunkSize (was $StreamingChunkSize) due to column width $colCount" -ForegroundColor DarkYellow } else { Write-LogHost "Chunk size retained/boosted: $effectiveChunkSize (columns=$colCount)" -ForegroundColor DarkGray }
						$script:metrics.EffectiveChunkSize = $effectiveChunkSize
						if (-not $csvWriter) { Open-CsvWriter -Path $exportTemp -Columns $columnOrder; $csvWriter = $true }
						$emitRows = @(); foreach ($sr in $schemaSampleRows) { $emitRows += ($sr | Select-Object -Property $columnOrder) }; if ($emitRows.Count -gt 0) { Write-CsvRows -Rows $emitRows -Columns $columnOrder }
						$schemaSampleRows.Clear(); $schemaFrozen = $true
					}
				}
				else {
					$rowHadNew = $false
					foreach ($pn in $r.PSObject.Properties.Name) { if (-not $columnOrder.Contains($pn)) { if (-not $rowHadNew) { $postFreezeNewColumns++; $rowHadNew = $true }; if (-not $lateIgnoredColumns.Contains($pn)) { [void]$lateIgnoredColumns.Add($pn) } } }
					$buffer.Add($r) | Out-Null
					if (-not $effectiveChunkSize) { $effectiveChunkSize = $StreamingChunkSize }
					if ($buffer.Count -ge $effectiveChunkSize) { $emitSet = $buffer | ForEach-Object { $_ | Select-Object -Property $columnOrder }; if (-not $csvWriter) { Open-CsvWriter -Path $exportTemp -Columns $columnOrder; $csvWriter = $true }; if ($emitSet.Count -gt 0) { Write-CsvRows -Rows $emitSet -Columns $columnOrder }; $buffer.Clear() }
				}
			}
		}
		else {
			if (-not $script:loggedZeroRecords) { $script:loggedZeroRecords = 0 }
			if ($script:loggedZeroRecords -lt 5) {
				$opName = $null; try { $opName = if ($log.Operation) { [string]$log.Operation } elseif ($log.Operations) { [string]$log.Operations } else { $null } } catch {}
				Write-LogHost "Record produced 0 structured rows (Operation=$opName)" -ForegroundColor DarkYellow
				$script:loggedZeroRecords++
			}
		}
	}
	}  # End of SERIAL MODE else block
	
	# ═══════════════════════════════════════════════════════════════════════════════
	# PARALLEL EXPLOSION PROCESSING (PS7+ only)
	# Uses Start-ThreadJob with job queue pattern for optimal load balancing
	# Many small chunks + N concurrent workers = better CPU utilization
	# ═══════════════════════════════════════════════════════════════════════════════
	if (-not $skipToPostProcessing -and $useParallelExplosion) {
		$processingMode = if ($ExplodeArrays -or $ExplodeDeep) { "array explosion" } else { "record conversion" }
		Write-LogHost "Starting parallel $processingMode of $($allLogs.Count) records using $parallelThrottleLimit concurrent threads..." -ForegroundColor Cyan
		
		# Update checkpoint to track explosion phase
		if ($script:CheckpointEnabled -and $script:CheckpointData) {
			$script:CheckpointData.explosion.status = 'InProgress'
			$script:CheckpointData.explosion.recordsProcessed = 0
			$script:CheckpointData.explosion.rowsGenerated = 0
			$script:CheckpointData.explosion.lastUpdateTime = (Get-Date).ToUniversalTime().ToString('o')
			Save-CheckpointToDisk
		}
		
		$parallelStartTime = Get-Date
		
		# ─────────────────────────────────────────────────────────────────────────
		# PHASE 1: Split records into many small chunks for job queue
		# Small chunks = better load balancing when work varies per record
		# ─────────────────────────────────────────────────────────────────────────
		$totalRecords = $allLogs.Count
		# Use ~1000 records per chunk (sweet spot for overhead vs load balancing)
		# Minimum chunks = 2x thread count to ensure good distribution
		$targetChunkSize = 1000
		$minChunks = $parallelThrottleLimit * 2
		$chunkSize = [Math]::Min($targetChunkSize, [Math]::Ceiling($totalRecords / $minChunks))
		$chunkSize = [Math]::Max(100, $chunkSize)  # At least 100 records per chunk
		
		$chunks = [System.Collections.Generic.List[object[]]]::new()
		for ($i = 0; $i -lt $totalRecords; $i += $chunkSize) {
			$endIdx = [Math]::Min($i + $chunkSize - 1, $totalRecords - 1)
			$chunk = $allLogs[$i..$endIdx]
			$chunks.Add($chunk)
		}
		
		Write-LogHost "Split $totalRecords records into $($chunks.Count) chunks (~$chunkSize records each) for $parallelThrottleLimit workers" -ForegroundColor Cyan
		
		# ─────────────────────────────────────────────────────────────────────────
		# PHASE 2: Job queue - run up to N concurrent jobs, queue the rest
		# As each job completes, start another from the queue
		# ─────────────────────────────────────────────────────────────────────────
		Write-LogHost "Phase 1: Processing $($chunks.Count) chunks with $parallelThrottleLimit concurrent workers..." -ForegroundColor Cyan
		$explosionStart = Get-Date
		
		# Capture parameters for thread jobs
		$threadParams = @{
			ExplodeDeep = $ExplodeDeep
			PartialExplode = $partialExplode
			PromptFilter = $PromptFilter
			EffectiveExplode = $effectiveExplode
		}
		
		# Job queue management
		$activeJobs = [System.Collections.Generic.List[object]]::new()
		$completedResults = [System.Collections.Generic.List[object]]::new()
		$chunkQueue = [System.Collections.Generic.Queue[object]]::new()
		foreach ($chunk in $chunks) { $chunkQueue.Enqueue($chunk) }
		
		$totalChunks = $chunks.Count
		$chunksStarted = 0
		$chunksCompleted = 0
		$failedChunks = 0
		$lastProgressTime = Get-Date
		$progressInterval = [TimeSpan]::FromSeconds(60)  # Update progress every 60 seconds
		
		# ─────────────────────────────────────────────────────────────────────────
		# Build InitializationScript with all required function definitions
		# Start-ThreadJob creates ISOLATED runspaces - functions are NOT inherited
		# ─────────────────────────────────────────────────────────────────────────
		$initScriptText = @'
# Thread-local helper functions (required for explosion)
function Test-ScalarValue { param($v) ($null -eq $v -or $v -is [string] -or $v -is [char] -or $v -is [bool] -or $v -is [int] -or $v -is [long] -or $v -is [double] -or $v -is [decimal] -or $v -is [float] -or $v -is [datetime] -or $v -is [guid]) }

function Get-SafeProperty { param($obj, [string]$name) try { if ($null -ne $obj -and $obj.PSObject.Properties[$name]) { return $obj.($name) } } catch {}; return $null }

function Select-FirstNonNull { param([object[]]$Values) foreach ($v in $Values) { if ($null -ne $v -and ('' -ne [string]$v)) { return $v } } return $null }

function To-RecordArray {
	param($records)
	$result = @()
	if ($null -eq $records) { return $result }
	$isEnumerable = ($records -is [System.Collections.IEnumerable])
	$isScalarish = ($records -is [string] -or $records -is [System.Management.Automation.PSObject] -or $records -is [System.Management.Automation.PSCustomObject])
	if ($isEnumerable -and -not $isScalarish) { foreach ($r in $records) { $result += ,$r } }
	else { $result += ,$records }
	return $result
}

function Find-AllArrays {
	param($Data, [string]$Path = '', [int]$Depth = 0, [hashtable]$Arrays)
	if ($null -eq $Data) { return @{} }
	if (-not $Arrays) { $Arrays = @{} }
	if ($Depth -gt 6) { return $Arrays }
	$isArray = ($Data -is [System.Collections.IEnumerable] -and -not ($Data -is [string]) -and (($Data -is [System.Collections.IList]) -or $Data.GetType().IsArray))
	if ($isArray) {
		$key = if ($Path) { $Path } else { 'root' }
		if (-not $Arrays.ContainsKey($key)) { $Arrays[$key] = [pscustomobject]@{ Path = $Path; Data = $Data; Count = ($Data | Measure-Object).Count } }
	}
	$props = $null
	if ($Data -is [System.Management.Automation.PSObject]) { $props = $Data.PSObject.Properties }
	elseif ($Data -is [System.Collections.IDictionary]) { $props = $Data.GetEnumerator() }
	if ($props) {
		foreach ($p in $props) {
			$name = if ($p -is [System.Collections.DictionaryEntry]) { $p.Key } else { $p.Name }
			$val = if ($p -is [System.Collections.DictionaryEntry]) { $p.Value } else { $p.Value }
			$childPath = if ($Path) { "$Path.$name" } else { $name }
			Find-AllArrays -Data $val -Path $childPath -Depth ($Depth + 1) -Arrays $Arrays | Out-Null
		}
	}
	return $Arrays
}

function ConvertTo-FlatColumns {
	param([object]$Node, [string]$Prefix = '', [int]$MaxDepth = 60)
	$cols = @{}
	function Recurse([object]$n, [string]$p, [int]$d) {
		if ($d -gt $MaxDepth) { return }
		if ($null -eq $n) { if ($p) { $cols[$p.TrimEnd('.')] = $null }; return }
		if (Test-ScalarValue $n) { if ($p) { $cols[$p.TrimEnd('.')] = $n }; return }
		if ($n -is [System.Collections.IEnumerable] -and -not ($n -is [string]) -and -not ($n -is [System.Collections.IDictionary])) {
			# Smart array handling: single-element arrays recurse without index, multi-element become JSON
			$arr = @($n)
			if ($arr.Count -eq 1) {
				Recurse -n $arr[0] -p $p -d ($d + 1)
			} elseif ($arr.Count -gt 1) {
				if ($p) { try { $cols[$p.TrimEnd('.')] = ($n | ConvertTo-Json -Depth 10 -Compress -ErrorAction SilentlyContinue) } catch { $cols[$p.TrimEnd('.')] = '' } }
			} else {
				if ($p) { $cols[$p.TrimEnd('.')] = '' }
			}
			return
		}
		$props = $null; try { $props = $n.PSObject.Properties } catch {}
		if ($props) { foreach ($prop in $props) { $name = [string]$prop.Name; $child = $prop.Value; $cp = if ($p) { $p + $name + '.' } else { $name + '.' }; Recurse -n $child -p $cp -d ($d + 1) } }
	}
	Recurse -n $Node -p $Prefix -d 0
	return $cols
}

function Profile-AuditData { param([object]$AuditData) } # No-op stub for threads
'@
		
		# Extract Convert-ToPurviewExplodedRecords and Convert-ToStructuredRecord function definitions
		$funcConvertExploded = (Get-Command Convert-ToPurviewExplodedRecords -ErrorAction SilentlyContinue).Definition
		$funcConvertStructured = (Get-Command Convert-ToStructuredRecord -ErrorAction SilentlyContinue).Definition
		
		# Build complete initialization script with all functions
		$fullInitScript = $initScriptText + "`n`n" + `
			"function Convert-ToPurviewExplodedRecords {`n$funcConvertExploded`n}`n`n" + `
			"function Convert-ToStructuredRecord {`n$funcConvertStructured`n}"
		
		$initScriptBlock = [scriptblock]::Create($fullInitScript)
		
		# Capture additional variables needed in threads
		$threadVars = @{
			PurviewExplodedHeader = $PurviewExplodedHeader
			FlatDepthStandard = $FlatDepthStandard
			FlatDepthDeep = $FlatDepthDeep
			JsonDepth = $JsonDepth
			ExplosionPerRecordRowCap = $ExplosionPerRecordRowCap
		}
		
		# Helper to start a new job
		$startNextJob = {
			if ($chunkQueue.Count -gt 0) {
				$chunk = $chunkQueue.Dequeue()
				$chunksStarted++
				$job = Start-ThreadJob -Name "PAX_Chunk_$chunksStarted" -InitializationScript $initScriptBlock -ScriptBlock {
					param($Records, $Params, $Vars)
					
					# Initialize thread-local script-scoped variables and helpers
					$script:metrics = @{ FilteringSkippedRecords = 0; FilteringMissingAuditData = 0; FilteringPromptFiltered = 0; FilteringParseFailures = 0; ExplosionEvents = 0; ExplosionRowsFromEvents = 0; ExplosionMaxPerRecord = 0; ExplosionTruncated = $false }
					$script:DeepExtraColumns = New-Object System.Collections.Generic.List[string]
					$script:RegexTrueFalse = [regex]::new('^(?i:true|false)$', [System.Text.RegularExpressions.RegexOptions]::Compiled)
					$script:RegexYes1 = [regex]::new('^(?i:yes|1)$', [System.Text.RegularExpressions.RegexOptions]::Compiled)
					$script:RegexNo0 = [regex]::new('^(?i:no|0)$', [System.Text.RegularExpressions.RegexOptions]::Compiled)
					$PurviewExplodedHeader = $Vars.PurviewExplodedHeader
					$FlatDepthStandard = $Vars.FlatDepthStandard
					$FlatDepthDeep = $Vars.FlatDepthDeep
					$JsonDepth = $Vars.JsonDepth
					$ExplosionPerRecordRowCap = $Vars.ExplosionPerRecordRowCap
					
					# Thread-local script-scoped helper functions
					# Parse-DateSafe: Culture-invariant date parsing for Purview API dates
					function script:Parse-DateSafe {
						param([string]$dateStr)
						if ([string]::IsNullOrWhiteSpace($dateStr)) { return $null }
						$dateStr = $dateStr.Trim()
						# Try ISO 8601 formats first (most common from Purview)
						$isoFormats = @(
							'yyyy-MM-ddTHH:mm:ss.fffffffZ', 'yyyy-MM-ddTHH:mm:ss.ffffffZ', 'yyyy-MM-ddTHH:mm:ss.fffffZ',
							'yyyy-MM-ddTHH:mm:ss.ffffZ', 'yyyy-MM-ddTHH:mm:ss.fffZ', 'yyyy-MM-ddTHH:mm:ss.ffZ',
							'yyyy-MM-ddTHH:mm:ss.fZ', 'yyyy-MM-ddTHH:mm:ssZ', 'yyyy-MM-ddTHH:mm:ss',
							'yyyy-MM-dd HH:mm:ss', 'yyyy-MM-dd'
						)
						foreach ($fmt in $isoFormats) {
							try { return [datetime]::ParseExact($dateStr, $fmt, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::AdjustToUniversal) } catch {}
						}
						# US date formats (MM/dd/yyyy as Purview returns)
						$usFormats = @('M/d/yyyy h:mm:ss tt', 'M/d/yyyy HH:mm:ss', 'M/d/yyyy H:mm:ss', 'M/d/yyyy')
						foreach ($fmt in $usFormats) {
							try { return [datetime]::ParseExact($dateStr, $fmt, [System.Globalization.CultureInfo]::InvariantCulture) } catch {}
						}
						# Fallback to InvariantCulture Parse
						try { return [datetime]::Parse($dateStr, [System.Globalization.CultureInfo]::InvariantCulture) } catch { return $null }
					}
					function script:Format-DatePurviewFast($dt) {
						if (-not $dt) { return '' }
						if ($dt -is [datetime]) { return $dt.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture) }
						$parsed = script:Parse-DateSafe $dt
						if ($parsed) { return $parsed.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture) }
						return ''
					}
					function script:BoolTFFast($v) {
						if ($null -eq $v) { return '' }
						if ($v -is [bool]) { return $v.ToString().ToUpper() }
						$vStr = [string]$v
						if ($script:RegexTrueFalse.IsMatch($vStr)) { return $vStr.ToUpper() }
						if ($script:RegexYes1.IsMatch($vStr)) { return 'TRUE' }
						if ($script:RegexNo0.IsMatch($vStr)) { return 'FALSE' }
						return $vStr
					}
					function script:ToJsonIfObjectFast($v) {
						if ($null -eq $v) { return '' }
						if (Test-ScalarValue $v) { return $v }
						try { return ($v | ConvertTo-Json -Depth $JsonDepth -Compress) } catch { return [string]$v }
					}
					function script:GetArrayFast($parent, [string]$name) {
						$val = Get-SafeProperty $parent $name
						if ($null -eq $val) { return @() }
						if ($val -is [System.Collections.IEnumerable] -and -not ($val -is [string])) { return @($val) }
						return @($val)
					}
					
					$results = [System.Collections.Generic.List[object]]::new()
					$recordCount = 0
					
					foreach ($log in $Records) {
						$recordCount++
						try {
							$records = if ($Params.EffectiveExplode) {
								Convert-ToPurviewExplodedRecords -Record $log -Deep:$Params.ExplodeDeep -PartialExplode:$Params.PartialExplode -PromptFilterValue $Params.PromptFilter -SkipMetrics
							} else {
								Convert-ToStructuredRecord -Record $log -EnableExplosion:$false
							}
							
							$recordsArr = To-RecordArray $records
							if ($recordsArr.Count -gt 0) {
								foreach ($r in $recordsArr) {
									$results.Add($r)
								}
							}
						} catch {
							# Skip failed records
						}
					}
					
					@{
						Records = $results.ToArray()
						RecordCount = $recordCount
					}
				} -ArgumentList @($chunk, $threadParams, $threadVars)
				
				$activeJobs.Add($job)
			}
		}
		
		# Start initial batch of jobs (up to thread limit)
		for ($j = 0; $j -lt $parallelThrottleLimit -and $chunkQueue.Count -gt 0; $j++) {
			& $startNextJob
		}
		
		# Process job queue until all complete
		while ($activeJobs.Count -gt 0 -or $chunkQueue.Count -gt 0) {
			# Check for completed jobs
			$justCompleted = @($activeJobs | Where-Object { $_.State -eq 'Completed' -or $_.State -eq 'Failed' })
			
			foreach ($job in $justCompleted) {
				$activeJobs.Remove($job) | Out-Null
				$chunksCompleted++
				
				if ($job.State -eq 'Completed') {
					try {
						$result = Receive-Job -Job $job -ErrorAction Stop
						if ($result) {
							$completedResults.Add($result)
						}
					} catch {
						$failedChunks++
					}
				} else {
					$failedChunks++
				}
				
				Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
				
				# Start next job from queue
				& $startNextJob
			}
			
			# Progress update
			if (((Get-Date) - $lastProgressTime) -gt $progressInterval) {
				$elapsed = (Get-Date) - $explosionStart
				$elapsedStr = if ($elapsed.TotalMinutes -ge 1) { "{0}m {1}s" -f [int]$elapsed.TotalMinutes, $elapsed.Seconds } else { "{0}s" -f [int]$elapsed.TotalSeconds }
				$pct = [int](($chunksCompleted / $totalChunks) * 100)
				$recordsProcessed = $chunksCompleted * $chunkSize  # Approximate
				$rate = if ($elapsed.TotalSeconds -gt 0) { [int]($recordsProcessed / $elapsed.TotalSeconds) } else { 0 }
				Write-LogHost ("[{0}] Chunks: {1}/{2} ({3}%) | Active: {4} | Queue: {5} | ~{6:N0} rec/sec | {7}" -f (Get-Date -Format "HH:mm:ss"), $chunksCompleted, $totalChunks, $pct, $activeJobs.Count, $chunkQueue.Count, $rate, $elapsedStr) -ForegroundColor DarkCyan
				$lastProgressTime = Get-Date
			}
			
			if ($activeJobs.Count -gt 0) {
				Start-Sleep -Milliseconds 100
			}
		}
		
		# Final 100% status line for Phase 1
		$elapsed = (Get-Date) - $explosionStart
		$elapsedStr = if ($elapsed.TotalMinutes -ge 1) { "{0}m {1}s" -f [int]$elapsed.TotalMinutes, $elapsed.Seconds } else { "{0}s" -f [int]$elapsed.TotalSeconds }
		$finalRate = if ($elapsed.TotalSeconds -gt 0) { [int]($totalRecords / $elapsed.TotalSeconds) } else { 0 }
		Write-LogHost ("[{0}] Chunks: {1}/{1} (100%) | Complete | ~{2:N0} rec/sec | {3}" -f (Get-Date -Format "HH:mm:ss"), $totalChunks, $finalRate, $elapsedStr) -ForegroundColor DarkCyan
		
		$explosionElapsed = (Get-Date) - $explosionStart
		$explosionRate = if ($explosionElapsed.TotalSeconds -gt 0) { [int]($totalRecords / $explosionElapsed.TotalSeconds) } else { 0 }
		
		if ($failedChunks -gt 0) {
			Write-LogHost "WARNING: $failedChunks chunk(s) failed - some records may be missing" -ForegroundColor Yellow
		}
		
		# ─────────────────────────────────────────────────────────────────────────
		# PHASE 3: Collect all results into single list
		# ─────────────────────────────────────────────────────────────────────────
		Write-LogHost "Phase 2: Consolidating results from $($completedResults.Count) chunks..." -ForegroundColor Cyan
		$allExplodedRecords = [System.Collections.Generic.List[object]]::new()
		$totalSourceRecords = 0
		
		foreach ($result in $completedResults) {
			if ($result.Records) {
				$totalSourceRecords += $result.RecordCount
				foreach ($r in $result.Records) {
					$allExplodedRecords.Add($r)
				}
			}
		}
		$completedResults.Clear()
		
		$phaseDesc = if ($ExplodeArrays -or $ExplodeDeep) { "Parallel explosion" } else { "Parallel conversion" }
		Write-LogHost "$phaseDesc complete: $totalRecords records -> $($allExplodedRecords.Count) rows in $([Math]::Round($explosionElapsed.TotalSeconds, 1))s ($explosionRate rec/sec)" -ForegroundColor Green
		
		# Update checkpoint with explosion completion
		if ($script:CheckpointEnabled -and $script:CheckpointData) {
			$script:CheckpointData.explosion.status = 'Completed'
			$script:CheckpointData.explosion.recordsProcessed = $totalRecords
			$script:CheckpointData.explosion.rowsGenerated = $allExplodedRecords.Count
			$script:CheckpointData.explosion.lastUpdateTime = (Get-Date).ToUniversalTime().ToString('o')
			Save-CheckpointToDisk
		}
		
		# ─────────────────────────────────────────────────────────────────────────
		# PHASE 4: Apply schema and write CSV (must be serial for proper ordering)
		# ─────────────────────────────────────────────────────────────────────────
		Write-LogHost "Phase 3: Discovering schema from all $($allExplodedRecords.Count) rows (full scan)..." -ForegroundColor Cyan
		$schemaStart = Get-Date
		
		$structuredDataCount = $allExplodedRecords.Count
		$script:metrics.TotalStructuredRows = $structuredDataCount
		$processedRecordCount = $totalRecords
		
		# Update per-activity Structured counts for Activity Type Breakdown display
		# (Parallel explosion doesn't update these during processing - count now from consolidated results)
		$activityStructuredCounts = @{}
		foreach ($row in $allExplodedRecords) {
			$opName = if ($row -is [hashtable]) { if ($row['Operation']) { $row['Operation'] } else { $row['Operations'] } } else { if ($row.Operation) { $row.Operation } else { $row.Operations } }
			if ($opName) {
				if (-not $activityStructuredCounts.ContainsKey($opName)) { $activityStructuredCounts[$opName] = 0 }
				$activityStructuredCounts[$opName]++
			}
		}
		foreach ($opName in $activityStructuredCounts.Keys) {
			if ($script:metrics.Activities.ContainsKey($opName)) {
				$script:metrics.Activities[$opName].Structured = $activityStructuredCounts[$opName]
			}
		}
		
		# Build schema by scanning ALL records (not just first N)
		# This ensures 100% column discovery - only reads property names, not values (fast)
		$columnOrder = New-Object System.Collections.Generic.List[string]
		if ($ExplodeArrays -or $ExplodeDeep -or $ForcedRawInputCsvExplosion) {
			if ($IncludeM365Usage -and $RAWInputCSV) {
				foreach ($c in (Get-M365UsageWideHeader -RawCsvPath $RAWInputCSV -BaseHeader $M365UsageBaseHeader)) { [void]$columnOrder.Add($c) }
			} else {
				foreach ($c in $PurviewExplodedHeader) { [void]$columnOrder.Add($c) }
			}
			if ($ExplodeDeep -and $script:DeepExtraColumns -and $script:DeepExtraColumns.Count -gt 0) {
				foreach ($c in $script:DeepExtraColumns) { if (-not $columnOrder.Contains($c)) { [void]$columnOrder.Add($c) } }
			}
		}
		# Full scan: iterate ALL exploded records to discover every column
		# This is O(n) but only touches property names, not values - typically <2s for 100K rows
		foreach ($sr in $allExplodedRecords) {
			foreach ($pn in $sr.PSObject.Properties.Name) {
				if (-not $columnOrder.Contains($pn)) { [void]$columnOrder.Add($pn) }
			}
		}
		$schemaElapsed = (Get-Date) - $schemaStart
		Write-LogHost "Schema discovered: $($columnOrder.Count) columns from $($allExplodedRecords.Count) rows in $([Math]::Round($schemaElapsed.TotalSeconds, 1))s (full scan - 100% column coverage)" -ForegroundColor Cyan
		$schemaSampleRows.Clear()
		$schemaFrozen = $true
		
		Write-LogHost "Phase 4: Writing CSV..." -ForegroundColor Cyan
		$writeStart = Get-Date
		
		# Calculate effective chunk size for CSV writing.
		# Write-CsvRows uses column index lookup (O(1) vs O(n)), so larger base chunks are safe.
		$colCount = $columnOrder.Count
		$effectiveChunkSize = $StreamingChunkSize
		if ($colCount -gt 1000) { $effectiveChunkSize = [int][Math]::Min($effectiveChunkSize, 3000) }
		elseif ($colCount -gt 500) { $effectiveChunkSize = [int][Math]::Min($effectiveChunkSize, 5000) }
		elseif ($colCount -gt 250) { $effectiveChunkSize = [int][Math]::Min($effectiveChunkSize, 8000) }
		elseif ($colCount -gt 100) { $effectiveChunkSize = [int][Math]::Max($StreamingChunkSize, 10000) }  # New tier for 100-250 columns
		else { $effectiveChunkSize = [int][Math]::Min(20000, [Math]::Max($StreamingChunkSize * 4, 15000)) }  # Boost for ≤100 columns
		$script:metrics.EffectiveChunkSize = $effectiveChunkSize
		
		# Open CSV writer and write all records in chunks
		Open-CsvWriter -Path $exportTemp -Columns $columnOrder
		$csvWriter = $true
		
		$writeChunkSize = $effectiveChunkSize
		$totalWritten = 0
		$lastWriteProgressTime = Get-Date
		$writeProgressInterval = [TimeSpan]::FromSeconds(60)
		
		for ($i = 0; $i -lt $allExplodedRecords.Count; $i += $writeChunkSize) {
			$endIdx = [Math]::Min($i + $writeChunkSize - 1, $allExplodedRecords.Count - 1)
			$chunk = $allExplodedRecords[$i..$endIdx]
			
			# Rows from parallel explosion are already hashtables — pass directly to CSV writer.
			# Avoids Select-Object -Property $columnOrder, which is extremely slow with 100+ columns.
			if ($chunk.Count -gt 0) {
				Write-CsvRows -Rows $chunk -Columns $columnOrder
				$totalWritten += $chunk.Count
			}
			
			# Progress every 60 seconds
			if (((Get-Date) - $lastWriteProgressTime) -gt $writeProgressInterval) {
				$writeElapsedSoFar = (Get-Date) - $writeStart
				$elapsedStr = if ($writeElapsedSoFar.TotalMinutes -ge 1) { "{0}m {1}s" -f [int]$writeElapsedSoFar.TotalMinutes, $writeElapsedSoFar.Seconds } else { "{0}s" -f [int]$writeElapsedSoFar.TotalSeconds }
				$pct = [int](($totalWritten / $allExplodedRecords.Count) * 100)
				$rowRate = if ($writeElapsedSoFar.TotalSeconds -gt 0) { [int]($totalWritten / $writeElapsedSoFar.TotalSeconds) } else { 0 }
				Write-LogHost ("[{0}] CSV Write: {1:N0}/{2:N0} rows ({3}%) | {4} cols | ~{5:N0} rows/sec | {6}" -f (Get-Date -Format "HH:mm:ss"), $totalWritten, $allExplodedRecords.Count, $pct, $columnOrder.Count, $rowRate, $elapsedStr) -ForegroundColor DarkCyan
				$lastWriteProgressTime = Get-Date
			}
		}
		
		# Final Phase 3 status line
		$writeElapsed = (Get-Date) - $writeStart
		$elapsedStr = if ($writeElapsed.TotalMinutes -ge 1) { "{0}m {1}s" -f [int]$writeElapsed.TotalMinutes, $writeElapsed.Seconds } else { "{0}s" -f [int]$writeElapsed.TotalSeconds }
		$finalRowRate = if ($writeElapsed.TotalSeconds -gt 0) { [int]($totalWritten / $writeElapsed.TotalSeconds) } else { 0 }
		Write-LogHost ("[{0}] CSV Write: {1:N0}/{1:N0} rows (100%) | {2} cols | ~{3:N0} rows/sec | {4}" -f (Get-Date -Format "HH:mm:ss"), $totalWritten, $columnOrder.Count, $finalRowRate, $elapsedStr) -ForegroundColor Cyan
		Write-LogHost "CSV write complete: $totalWritten rows in $([Math]::Round($writeElapsed.TotalSeconds, 1))s" -ForegroundColor Green
		
		# Track activity metrics (approximate - we don't have per-record operation info in parallel mode)
		# This is a known limitation - parallel mode won't have detailed per-operation breakdown
		
		# Clean up to free memory
		$allExplodedRecords.Clear()
		$allExplodedRecords = $null
		[System.GC]::Collect()
		
		$parallelElapsed = (Get-Date) - $parallelStartTime
		$parallelRate = if ($parallelElapsed.TotalSeconds -gt 0) { [int]($totalRecords / $parallelElapsed.TotalSeconds) } else { 0 }
		$completeDesc = if ($ExplodeArrays -or $ExplodeDeep) { "PARALLEL EXPLOSION" } else { "PARALLEL PROCESSING" }
		Write-LogHost "$completeDesc COMPLETE: $totalRecords records -> $structuredDataCount rows in $([Math]::Round($parallelElapsed.TotalSeconds, 1))s total ($parallelRate rec/sec)" -ForegroundColor Green
	}
	# END PARALLEL BLOCK
	
	# Flush any remaining unfrozen schema samples (small datasets)
	if (-not $schemaFrozen -and $schemaSampleRows.Count -gt 0) {
		if ($ExplodeArrays -or $ExplodeDeep -or $ForcedRawInputCsvExplosion) {
			$columnOrder = New-Object System.Collections.Generic.List[string];
			if ($IncludeM365Usage -and $RAWInputCSV) {
				foreach ($c in (Get-M365UsageWideHeader -RawCsvPath $RAWInputCSV -BaseHeader $M365UsageBaseHeader)) { [void]$columnOrder.Add($c) }
			} else {
				foreach ($c in $PurviewExplodedHeader) { [void]$columnOrder.Add($c) }
			}
			if ($ExplodeDeep -and $script:DeepExtraColumns -and $script:DeepExtraColumns.Count -gt 0) { foreach ($c in $script:DeepExtraColumns) { if (-not $columnOrder.Contains($c)) { [void]$columnOrder.Add($c) } } }
		} else {
			$columnOrder = New-Object System.Collections.Generic.List[string]; foreach ($sr in $schemaSampleRows) { foreach ($pn in $sr.PSObject.Properties.Name) { if (-not $columnOrder.Contains($pn)) { [void]$columnOrder.Add($pn) } } }
		}
		foreach ($sr in $schemaSampleRows) { foreach ($pn in $sr.PSObject.Properties.Name) { if (-not $columnOrder.Contains($pn)) { [void]$columnOrder.Add($pn) } } }
		Write-LogHost "Schema finalized with $($columnOrder.Count) columns from $($schemaSampleRows.Count) total rows (small dataset)" -ForegroundColor DarkCyan
		if (-not $csvWriter) { Open-CsvWriter -Path $exportTemp -Columns $columnOrder; $csvWriter = $true }
		$emitRows = @(); foreach ($sr in $schemaSampleRows) { $emitRows += ($sr | Select-Object -Property $columnOrder) }; if ($emitRows.Count -gt 0) { Write-CsvRows -Rows $emitRows -Columns $columnOrder }
		$schemaSampleRows.Clear(); $schemaFrozen = $true
	}
	# Flush any remaining buffered rows after schema freeze
	if ($schemaFrozen -and $buffer.Count -gt 0) {
		$emitSet = $buffer | ForEach-Object { $_ | Select-Object -Property $columnOrder }
		if (-not $csvWriter) { Open-CsvWriter -Path $exportTemp -Columns $columnOrder; $csvWriter = $true }
		if ($emitSet.Count -gt 0) { Write-CsvRows -Rows $emitSet -Columns $columnOrder }
		$buffer.Clear()
	}
	# Cleanup: ensure writer closed before export finalization.
	if ($csvWriter) { try { Close-CsvWriter } catch {} }

	# Replay fallback: if no structured rows but we have raw logs, emit compact rows (non-exploded)
	if ($structuredDataCount -eq 0 -and $explosionInputCount -gt 0 -and $RAWInputCSV) {
		Write-LogHost "Replay fallback: emitting compact non-exploded rows" -ForegroundColor Yellow
		try {
			$columnOrder = @('RecordId','CreationDate','RecordType','Operation','UserId','AuditData','AssociatedAdminUnits','AssociatedAdminUnitsNames')
			if (-not $csvWriter) { Open-CsvWriter -Path $exportTemp -Columns $columnOrder; $csvWriter = $true }
			$fallbackCount = 0
			foreach ($spoolLine in $(if ($script:ExplosionInputSpoolPath) { [System.IO.File]::ReadLines($script:ExplosionInputSpoolPath) } else { @() })) {
				$log = ConvertFrom-PaxNormalizedSpoolLine -Line $spoolLine
				if ($null -eq $log) { continue }
				try {
					$rows = Convert-ToStructuredRecord -Record $log -EnableExplosion:$false
					$rowsArr = To-RecordArray $rows
					if ($rowsArr.Count -gt 0) {
						$fallbackCount += $rowsArr.Count
						Write-CsvRows -Rows ($rowsArr | ForEach-Object { $_ | Select-Object -Property $columnOrder }) -Columns $columnOrder
					}
				} catch {}
			}
			$structuredDataCount = $fallbackCount
			try { $script:metrics.TotalStructuredRows = $fallbackCount } catch {}
			Write-LogHost ("Replay fallback emitted: {0} rows" -f $fallbackCount) -ForegroundColor Yellow
		} catch { Write-LogHost "Replay fallback failed: $($_.Exception.Message)" -ForegroundColor Red }
	}
	# Fallback: ensure temp file exists so Move-Item does not fail (very small datasets may not have flushed rows yet)
	# Skip this fallback if fast-path already moved the temp file to final output
	if (-not $skipToPostProcessing -and -not (Test-Path $exportTemp)) {
		try {
			$enc = New-Object System.Text.UTF8Encoding($false)
			$sw = [System.IO.StreamWriter]::new($exportTemp, $false, $enc)
			if ($columnOrder) {
				$escapedCols = New-Object System.Collections.Generic.List[string]
				foreach ($col in $columnOrder) {
					$c = [string]$col; $needsQuote = ($c -match '[",\r\n]') -or $c.StartsWith(' ') -or $c.EndsWith(' ')
					$escaped = $c -replace '"','""'
					if ($needsQuote) { $escaped = '"' + $escaped + '"' }
					$escapedCols.Add($escaped) | Out-Null
				}
				$sw.WriteLine(($escapedCols -join ','))
			} else {
				$sw.WriteLine('RecordId')
			}
			$sw.Flush(); $sw.Dispose()
		} catch { Write-LogHost "WARNING: Fallback temp file creation failed: $($_.Exception.Message)" -ForegroundColor Yellow }
	}
	
	# Final explosion progress update (100% completion) - SERIAL MODE ONLY
	# Parallel mode has its own completion summary, skip this to avoid duplicate/confusing output
	# Also skip when fast path or streaming merge already handled export (skipToPostProcessing=true)
	if (-not $useParallelExplosion -and -not $skipToPostProcessing) {
		if ($explosionInputCount -ge $explosionProgressInterval) {
			$elapsed = (Get-Date) - $te0
			$rate = [int]($processedRecordCount / $elapsed.TotalSeconds)
			$elapsedStr = if ($elapsed.TotalMinutes -ge 1) { 
				"{0}m {1}s" -f [int]$elapsed.TotalMinutes, $elapsed.Seconds 
			} else { 
				"{0}s" -f [int]$elapsed.TotalSeconds 
			}
			Write-LogHost ("[{0}] Processing: {1:N0} / {2:N0} records (100%) | Elapsed: {3} | Rate: {4:N0} rec/sec" -f (Get-Date -Format "HH:mm:ss"), $processedRecordCount, $explosionInputCount, $elapsedStr, $rate) -ForegroundColor DarkCyan
		}
		
		$te1 = Get-Date; try { $script:metrics.ExplosionMs += [int]($te1 - $te0).TotalMilliseconds } catch {}
		Write-LogHost "Standard processing (streamed) complete: $($explosionInputCount) input -> $structuredDataCount output" -ForegroundColor Cyan
	}
	
	# Explain record count changes (filtering vs explosion)
	if ($structuredDataCount -lt $explosionInputCount) {
		$recordsFiltered = $explosionInputCount - $structuredDataCount
		Write-LogHost ""
		Write-LogHost "  ℹ Record count decreased: $recordsFiltered parent record(s) were filtered out" -ForegroundColor Yellow
		Write-LogHost "    Note: Filtering happens DURING explosion (before array expansion)" -ForegroundColor DarkYellow
		
		# List active filters that could cause record exclusion
		$activeFilters = @()
		if ($PromptFilter) { 
			$activeFilters += "PromptFilter ($PromptFilter mode)"
			Write-LogHost "    • PromptFilter: Records with no matching messages were excluded" -ForegroundColor DarkYellow
		}
		if ($AgentId) { 
			$activeFilters += "AgentId filter"
			Write-LogHost "    • AgentId: Records not matching specified AgentId(s) were excluded" -ForegroundColor DarkYellow
		}
		if ($AgentsOnly) { 
			$activeFilters += "AgentsOnly filter"
			Write-LogHost "    • AgentsOnly: Records without any AgentId were excluded" -ForegroundColor DarkYellow
		}
		if ($ExcludeAgents) { 
			$activeFilters += "ExcludeAgents filter"
			Write-LogHost "    • ExcludeAgents: Records with AgentId present were excluded" -ForegroundColor DarkYellow
		}
		if ($UserIds) {
			$activeFilters += "UserIds filter"
			Write-LogHost "    • UserIds: Records not matching specified user(s) were excluded" -ForegroundColor DarkYellow
		}
		if ($GroupNames) {
			$activeFilters += "GroupNames filter"
			Write-LogHost "    • GroupNames: Records not matching group members were excluded" -ForegroundColor DarkYellow
		}
		
		if ($activeFilters.Count -eq 0) {
			Write-LogHost "    Reason: Unknown (no explicit filters active, possible internal filtering)" -ForegroundColor DarkYellow
		}
	}
	# Use stored count for streaming merge (allLogs was cleared), otherwise use allLogs.Count
	$inputRecordCount = if ($script:OriginalInputRecordCount) { $script:OriginalInputRecordCount } else { $explosionInputCount }
	
	if ($structuredDataCount -eq $inputRecordCount -and ($ExplodeArrays -or $ExplodeDeep)) {
		Write-LogHost ""
		Write-LogHost "  ℹ No explosion occurred (1:1 ratio)" -ForegroundColor Yellow
		if ($PromptFilter) {
			Write-LogHost "    Reason: PromptFilter limits explosion to matching messages only" -ForegroundColor DarkYellow
			Write-LogHost "    Each record had exactly 1 matching message, producing 1 row per record" -ForegroundColor DarkYellow
			Write-LogHost "    Tip: Without PromptFilter, these records would explode to multiple rows" -ForegroundColor Cyan
		} else {
			Write-LogHost "    Possible reasons: Records have no arrays to explode (Messages, Contexts, etc.)" -ForegroundColor DarkYellow
		}
	}
	elseif ($inputRecordCount -gt 0 -and $structuredDataCount -gt $inputRecordCount) {
		$explosionRatio = [Math]::Round($structuredDataCount / $inputRecordCount, 1)
		Write-LogHost ""
		Write-LogHost "  Array explosion successful: ${explosionRatio}x expansion ($inputRecordCount records → $structuredDataCount rows)" -ForegroundColor Green
	}
	
	if ($postFreezeNewColumns -gt 0) { Write-LogHost "NOTICE: $postFreezeNewColumns row(s) contained new columns after schema freeze (ignored). This only affects serial mode - increase -StreamingSchemaSample or use parallel mode (PS7+) for full coverage." -ForegroundColor DarkYellow }
	Set-ProgressPhase -Phase 'Export' -Status 'Finalizing streaming CSV'
	
	# Handle AppendFile mode vs normal mode (skip if fast-path already handled export)
	if (-not $skipToPostProcessing) {
	if ($AppendFile) {
		# AppendFile mode: Always create temporary CSV with new data first.
		# Resume safety: on a -Resume run $OutputPath is the checkpoint scratch dir and, in
		# the -AppendFile-with-omitted--OutputPath case, can resolve to the target FILE itself
		# (a Join-Path against which would corrupt the path) — $OutputPath is not reliable for
		# appends on resume. So on resume anchor this transient new-data temp on the directory
		# of $OutputFile (the _PARTIAL scratch dir), exactly as the streaming-merge gate does;
		# use [IO.Path]::GetDirectoryName (Split-Path's -LiteralPath set lacks -Parent in this
		# PowerShell), with a defensive fallback to $OutputPath. On a FRESH (non-resume) run
		# the proven $OutputPath location is kept byte-identical.
		$_afTempDir = $OutputPath
		if ($script:IsResumeMode) {
			$_afTd = [System.IO.Path]::GetDirectoryName($OutputFile)
			if (-not [string]::IsNullOrWhiteSpace($_afTd)) { $_afTempDir = $_afTd }
		}
		$tempCsvPath = Join-Path $_afTempDir "Temp_NewData_$global:ScriptRunTimestamp.csv"
		$tx0 = Get-Date; Move-Item -Force -Path $exportTemp -Destination $tempCsvPath; $tx1 = Get-Date
		try { $script:metrics.ExportMs += [int]($tx1 - $tx0).TotalMilliseconds } catch {}
		
		if ($ExportWorkbook) {
			# Excel AppendFile: Keep temp CSV for later reading
			# Store temp CSV path for Excel conversion to read from
			$script:AppendFileTempCsv = $tempCsvPath
			# $OutputFile stays as the user's target Excel file (set earlier at line 4355)
			Write-LogHost "Created temporary CSV for Excel append: $tempCsvPath" -ForegroundColor Gray
		} else {
			# CSV AppendFile: union-merge new run into the existing CSV via Merge-FactCsv.
			# Keys on 'RecordId' (the Purview audit GUID); adds the tri-column append
			# audit (Date_Added, Latest_Append_Date, In_Latest_Append) — same end-state
			# contract as the rollup -AppendFile path so any appended file in PAX
			# carries provenance regardless of -Rollup. Replaces the legacy
			# Add-Content streaming append, which produced no tri-columns and could
			# duplicate rows on re-runs (no dedup).
			#
			# Under -Rollup / -RollupPlusRaw, however, $OutputFile is the RAW scratch path
			# (CombinedActivityTypes_<currentTs>.csv) — the audit phase writes raw rows here
			# and the Phase-2 rollup phase is what merges into the -AppendFile target. Doing
			# the merge here too would clobber the raw with tri-columns and risk a double-merge
			# downstream. So skip the merge under rollup and just rename the temp to $OutputFile.
			if ($Rollup -or $RollupPlusRaw) {
				try {
					Move-Item -LiteralPath $tempCsvPath -Destination $OutputFile -Force
					Write-LogHost ("Raw Purview CSV: {0}" -f (Get-DisplayPath -LocalPath $OutputFile)) -ForegroundColor Green
				}
				catch {
					Write-Host ("ERROR: Failed to finalize raw Purview CSV under rollup mode: {0}" -f $_.Exception.Message) -ForegroundColor Red
					throw
				}
			}
			else {
			# Resume safety (defensive, resume-only): on a -Resume run, $OutputFile is the
			# reconstructed _PARTIAL scratch under the checkpoint dir, NOT the user's append
			# seed — so merging into $OutputFile here would leave the seed untouched and (via
			# Complete-CheckpointRun's collision-avoidance rename) drop a stray *_<timestamp>.csv.
			# Mirror the streaming-merge gate: on resume, redirect the merge to the restored
			# -AppendFile target used AS-IS (do NOT Join-Path against $OutputPath — under
			# -AppendFile with -OutputPath omitted, $OutputPath can resolve to the target FILE
			# itself, so a join would corrupt the path; -OutputPath is not used in append
			# resolution). Checkpoint-param fallback for safety; local/non-URL only. On a FRESH
			# (non-resume) run $_afTarget stays exactly $OutputFile, so the proven non-resume
			# append path is byte-identical.
			$_afTarget = $OutputFile
			if ($script:IsResumeMode) {
				$_afCand = if ($AppendFile) { [string]$AppendFile }
				           elseif ([bool]$script:CheckpointData -and [bool]$script:CheckpointData.parameters -and [bool]$script:CheckpointData.parameters.appendFile) { [string]$script:CheckpointData.parameters.appendFile }
				           else { '' }
				if ($_afCand -and $_afCand -notmatch '^https?://') {
					$_afTarget = $_afCand
				}
			}
			Write-LogHost "Appending new data to existing CSV: $(Get-DisplayPath -LocalPath $_afTarget)" -ForegroundColor Cyan
			try {
				$afMergeStats = Merge-FactCsv -TargetFactCsv $_afTarget -CurrentFactCsv $tempCsvPath -KeyColumn 'RecordId' -OutputPath $_afTarget
				Write-LogHost ("  -AppendFile merge: Retained={0:N0}  New={1:N0}  Departed={2:N0}  Union={3:N0}" -f $afMergeStats.Retained, $afMergeStats.New, $afMergeStats.Departed, $afMergeStats.Union) -ForegroundColor Green
				$_afDisplay = if ($script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) { $script:AppendRaw['Purview'] } else { Get-DisplayPath -LocalPath $_afTarget }
				Write-LogHost ("Appended to: {0}" -f $_afDisplay) -ForegroundColor White

				# Clean up temporary file
				Remove-Item -Path $tempCsvPath -Force -ErrorAction SilentlyContinue

				# Resume safety: when we redirected to the restored seed above, re-target
				# $OutputFile to it and clear $script:PartialOutputPath so Complete-CheckpointRun
				# does not rename a _PARTIAL scratch into a stray *_<timestamp>.csv beside the
				# seed (mirrors the streaming-merge gate). No-op on a fresh run.
				if ($script:IsResumeMode -and $_afTarget -ne $OutputFile) {
					$OutputFile = $_afTarget
					$script:PartialOutputPath = $null
				}
			}
			catch {
				Write-Host "ERROR: Failed to append CSV data: $($_.Exception.Message)" -ForegroundColor Red
				Write-Host "  Existing file: $OutputFile" -ForegroundColor Yellow
				Write-Host "  New data (temp): $tempCsvPath" -ForegroundColor Yellow
				Write-Host "" -ForegroundColor Yellow
				Write-Host "Possible causes:" -ForegroundColor Yellow
				Write-Host "  • File is open in Excel or another program" -ForegroundColor Gray
				Write-Host "  • Insufficient permissions" -ForegroundColor Gray
				Write-Host "  • Column mismatch between files" -ForegroundColor Gray
				Write-Host "" -ForegroundColor Yellow
				Write-Host "The new data is preserved in: $tempCsvPath" -ForegroundColor Cyan
				exit 1
			}
			}
		}
	} else {
		# Normal mode: Rename temp to final output (use CsvOutputFile for intermediate CSV when ExportWorkbook)
		$tx0 = Get-Date; Move-Item -Force -Path $exportTemp -Destination $script:CsvOutputFile; $tx1 = Get-Date
		try { $script:metrics.ExportMs += [int]($tx1 - $tx0).TotalMilliseconds } catch {}
	}
	} # End of skipToPostProcessing guard
	
	# Explosion input spool cleanup (Blocker 1): delete on successful publication;
	# preserve for recovery on failure. A failed publish leaves the output missing
	# (or the AppendFile branch exits before here), so the spool is retained.
	if ($script:ExplosionInputSpoolPath -and (Test-Path -LiteralPath $script:ExplosionInputSpoolPath)) {
		$explosionPublished = $false
		try { if ($OutputFile -and (Test-Path -LiteralPath $OutputFile)) { $explosionPublished = $true } } catch {}
		if (-not $explosionPublished) { try { if ($script:CsvOutputFile -and (Test-Path -LiteralPath $script:CsvOutputFile)) { $explosionPublished = $true } } catch {} }
		if ($explosionPublished) {
			Remove-Item -LiteralPath $script:ExplosionInputSpoolPath -Force -ErrorAction SilentlyContinue
			try { Write-PaxMemoryObservation -Stage 'ExplosionExportPublished' -Force } catch {}
			$script:ExplosionInputSpoolPath = $null
		} else {
			Write-LogHost ("Explosion input spool preserved for recovery: {0}" -f $script:ExplosionInputSpoolPath) -ForegroundColor DarkYellow
		}
	}
	
	$script:progressState.Export.Total = 1; $script:progressState.Export.Current = 1; Update-Progress -Status 'Export complete (stream)'; Set-ProgressPhase -Phase 'Complete' -Status 'Done'; Complete-Progress

	# --- Dynamic Downgrade: If combined CSV contains data for only one activity type, rename to single-activity convention ---
	# Note: Disabled when AppendFile is used to avoid renaming user-specified files
	# Note: Skip for fast-path (non-explosion) runs - Import-Csv on large files is too slow
	if (-not $skipToPostProcessing -and -not $ExportWorkbook -and $csvCombineMode -and (Test-Path $OutputFile) -and -not $AppendFile) {
		try {
			# Read all unique Operation values from the CSV
			$allOperations = Import-Csv -Path $OutputFile -ErrorAction Stop | 
				Where-Object { -not [string]::IsNullOrWhiteSpace($_.Operation) } | 
				Select-Object -ExpandProperty Operation -Unique
			
			$distinctOps = @($allOperations)
			if ($distinctOps.Count -eq 1) {
				$onlyType = [string]$distinctOps[0]  # Explicit cast to string to avoid array slicing
				if (-not [string]::IsNullOrWhiteSpace($onlyType)) {
					$safeType = $onlyType -replace '[\/:*?"<>|]', '_'
					$singleName = "Purview_Audit_UsageActivity_${safeType}_${global:ScriptRunTimestamp}.csv"
					$targetPath = Join-Path $OutputPath $singleName
					if ($OutputFile -ne $targetPath) {
						Write-LogHost "Detected single-activity result in combined mode: '$onlyType' → Renaming output file to $singleName" -ForegroundColor Yellow
						Move-Item -Force -Path $OutputFile -Destination $targetPath
						$OutputFile = $targetPath
						# Update parameter snapshot if present
						if ($paramSnapshot -and $paramSnapshot.Contains('OutputFile')) { $paramSnapshot['OutputFile'] = $OutputFile }
					}
				}
			}
		} catch {
			Write-LogHost "WARNING: Single-activity downgrade check failed: $($_.Exception.Message)" -ForegroundColor DarkYellow
		}
	}
	} # End else (live audit log query mode)
	} # End if (-not $OnlyUserInfo) - Skip all audit log queries when only exporting user data

	if ($OnlyUserInfo) {
		# -OnlyUserInfo mode: Initialize empty logs collection
		$allLogs = New-Object System.Collections.ArrayList
		
		# Handle OnlyUserInfo with ExportWorkbook - create Excel with just EntraUsers tab
		if ($ExportWorkbook -and $script:EntraUsersData) {
			$entraXlsxDir = $OutputPath; $entraXlsxBase = "EntraUsers_MAClicensing_${global:ScriptRunTimestamp}.xlsx"
			try {
				$dtX = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename $entraXlsxBase
				if ($dtX -and $dtX.IsBound -and $dtX.Tier -eq 'Local') {
					$entraXlsxDir = $dtX.EffectiveDir
					if ($dtX.Basename) { $entraXlsxBase = $dtX.Basename }
					if (-not (Test-Path -LiteralPath $entraXlsxDir -PathType Container)) { New-Item -Path $entraXlsxDir -ItemType Directory -Force | Out-Null }
				}
			} catch {}
			$entraExcelFile = Join-Path $entraXlsxDir $entraXlsxBase
			try {
				$entraTab = 'EntraUsers_MAClicensing'
				Write-LogHost "Creating Excel workbook with $entraTab tab ($($script:EntraUsersData.Count) rows)..." -ForegroundColor Cyan
				$dataTable = $script:EntraUsersData | ConvertTo-DataTable
				Send-SQLDataToExcel -DataTable $dataTable -Path $entraExcelFile -WorkSheetName $entraTab -Force -FreezeTopRow -BoldTopRow -AutoSize -NoNumberConversion '*'
				# Differentiate create vs append-merge.
				$entraExcelVerb = if ($AppendUserInfo) { 'EntraUsers Excel workbook updated (append-merge)' } else { 'EntraUsers Excel workbook created' }
				Write-LogHost ("{0}: {1}" -f $entraExcelVerb, (Get-DisplayPath -LocalPath $entraExcelFile)) -ForegroundColor Green
			} catch {
				Write-LogHost "WARNING: Failed to export EntraUsers Excel: $($_.Exception.Message)" -ForegroundColor Yellow
			}
		}
		
		# Handle OnlyUserInfo CSV export (non-workbook mode)
		if (-not $ExportWorkbook -and $script:EntraUsersData) {
			$entraCsvDir = $OutputPath
			# Effective basename: always the natural timestamped raw name. Under
			# -AppendUserInfo the raw file is written transiently at this name and
			# removed after the union is committed to the AppendUserInfo target via
			# Merge-UsersCsv -OutputPath, so the destination folder holds a single
			# merged EntraUsers CSV at run-end. See $script:GetEffectiveEntraBasename.
			$entraCsvBase = (& $script:GetEffectiveEntraBasename)
			try {
				$dtU = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename $entraCsvBase
				if ($dtU -and $dtU.IsBound -and $dtU.Tier -eq 'Local') {
					$entraCsvDir = $dtU.EffectiveDir
					if ($dtU.Basename) { $entraCsvBase = $dtU.Basename }
					if (-not (Test-Path -LiteralPath $entraCsvDir -PathType Container)) { New-Item -Path $entraCsvDir -ItemType Directory -Force | Out-Null }
				}
			} catch {}
			$entraFile = Join-Path $entraCsvDir $entraCsvBase
			# Pristine-raw separation: if -AppendUserInfo target leaf collides with the
			# natural raw leaf in the same folder, suffix raw with '_raw' so the merge
			# union (written to $AppendUserInfo) cannot overwrite the pristine raw file.
			if ($AppendUserInfo) {
				try {
					$rawFull = [System.IO.Path]::GetFullPath($entraFile)
					$auiFull = [System.IO.Path]::GetFullPath($AppendUserInfo)
					if ($rawFull -ieq $auiFull) {
						$stem = [System.IO.Path]::GetFileNameWithoutExtension($entraFile)
						$ext  = [System.IO.Path]::GetExtension($entraFile)
						$entraFile = Join-Path $entraCsvDir ($stem + '_raw' + $ext)
					}
				} catch {}
			}
			try {
				Write-LogHost "Exporting EntraUsers data to CSV ($($script:EntraUsersData.Count) rows)..." -ForegroundColor Cyan
				# Atomic temp+rename write.
				Save-CsvAtomic -InputObject $script:EntraUsersData -Path $entraFile -NoTypeInformation -Encoding UTF8
				# Report the raw path only when it persists past this step. Under
				# -AppendUserInfo the raw is transient (the post-merge cleanup
				# deletes it once the union is committed to the merge target), so
				# the up-front log line would reference a file that no longer
				# exists at run-end. If the merge fails the raw still sits where
				# Save-CsvAtomic wrote it and is enumerated in the end-of-run
				# output files listing.
				if (-not $AppendUserInfo) {
					Write-LogHost ("Raw EntraUsers CSV: {0}" -f (Get-DisplayPath -LocalPath $entraFile)) -ForegroundColor Green
				}
				if ($AppendUserInfo) {
					try {
						# Remote -AppendUserInfo lands in scratch under '.pax_appendseed_*'
						# (excluded from the end-of-run upload sweep). The MERGED union must be
						# written to a non-seed scratch path that inherits the AppendUserInfo target's
						# original leaf so the upload sweep's $appendLeafs.Contains() branch picks it
						# up. For local tier, $AppendUserInfo already IS the customer's path.
						$_auiMergeOut = if ($script:AppendIsRemote.ContainsKey('UserInfo') -and $script:AppendIsRemote['UserInfo'] -and $script:AppendRaw.ContainsKey('UserInfo') -and $script:AppendRaw['UserInfo']) {
							Join-Path $OutputPath ([System.IO.Path]::GetFileName($script:AppendRaw['UserInfo']))
						} else { $AppendUserInfo }
						$mergeStats = Merge-UsersCsv -TargetUsersCsv $AppendUserInfo -CurrentUsersCsv $entraFile -OutputPath $_auiMergeOut
						$_auiDisplay = if ($script:AppendRaw.ContainsKey('UserInfo') -and $script:AppendRaw['UserInfo']) { $script:AppendRaw['UserInfo'] } else { Get-DisplayPath -LocalPath $AppendUserInfo }
						Write-LogHost ("EntraUsers CSV updated (append-merge): {0}" -f $_auiDisplay) -ForegroundColor Green
						Write-LogHost ("EntraUsers append-merge complete: retained={0} new={1} departed={2} union={3}" -f $mergeStats.Retained, $mergeStats.New, $mergeStats.Departed, $mergeStats.Union) -ForegroundColor Green
						# Remove the transient raw EntraUsers CSV now that the union has
						# been committed to the AppendUserInfo target (parity with the
						# -AppendFile streaming-merge clean: only the merged target
						# remains on disk at run-end). Guarded so the merge output path
						# is never deleted (rare collision case where a customer-supplied
						# remote AppendUserInfo leaf matches the natural raw leaf).
						try {
							if ((Test-Path -LiteralPath $entraFile -PathType Leaf) -and
							    ([System.IO.Path]::GetFullPath($entraFile) -ne [System.IO.Path]::GetFullPath($_auiMergeOut))) {
								Remove-Item -LiteralPath $entraFile -Force -ErrorAction Stop
							}
						} catch { Write-LogHost ("EntraUsers raw cleanup failed (non-fatal): {0}" -f $_.Exception.Message) -ForegroundColor DarkYellow }
					} catch { Write-LogHost "WARNING: EntraUsers append-merge failed: $($_.Exception.Message)" -ForegroundColor Yellow }
				}
			} catch {
				Write-LogHost "WARNING: Failed to export EntraUsers CSV: $($_.Exception.Message)" -ForegroundColor Yellow
			}
		}
	}
	$csvSeparateMode = (-not $ExportWorkbook -and -not $csvCombineMode -and -not $AppendFile)
	# Defensive secondary gate: detect non-rollup -AppendFile mode regardless of
	# whether the $AppendFile script variable is currently truthy. On resume runs
	# the checkpoint's persisted appendFile value is the canonical fallback if the
	# bound parameter is empty for any reason. Without this gate, a resume run that
	# fails to re-bind $AppendFile would let $csvSeparateMode evaluate to $true and
	# the splitter below would shred the merged AppendFile target into per-activity
	# files (and then delete the source) — silently destroying the customer's data.
	$_appendFileActiveForSplitter = [bool]$AppendFile -or `
		([bool]$script:CheckpointData -and `
		 [bool]$script:CheckpointData.parameters -and `
		 [bool]$script:CheckpointData.parameters.appendFile)

	# --- EntraUsers CSV export (for IncludeUserInfo mode with combined/append CSV) ---
	# Note: OnlyUserInfo mode is handled in the dedicated block above
	# Export if: not workbook mode AND IncludeUserInfo enabled (not OnlyUserInfo) AND data exists
	if (-not $ExportWorkbook -and -not $OnlyUserInfo -and $IncludeUserInfo -and $script:EntraUsersData) {
		$entraIncDir = $OutputPath
		# Effective basename (see OnlyUserInfo writer above for rationale).
		$entraIncBase = (& $script:GetEffectiveEntraBasename)
		try {
			$dtI = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename $entraIncBase
			if ($dtI -and $dtI.IsBound -and $dtI.Tier -eq 'Local') {
				$entraIncDir = $dtI.EffectiveDir
				if ($dtI.Basename) { $entraIncBase = $dtI.Basename }
				if (-not (Test-Path -LiteralPath $entraIncDir -PathType Container)) { New-Item -Path $entraIncDir -ItemType Directory -Force | Out-Null }
			}
		} catch {}
		$entraFile = Join-Path $entraIncDir $entraIncBase
		# Pristine-raw separation: suffix raw with '_raw' on collision with -AppendUserInfo leaf.
		if ($AppendUserInfo) {
			try {
				$rawFull = [System.IO.Path]::GetFullPath($entraFile)
				$auiFull = [System.IO.Path]::GetFullPath($AppendUserInfo)
				if ($rawFull -ieq $auiFull) {
					$stem = [System.IO.Path]::GetFileNameWithoutExtension($entraFile)
					$ext  = [System.IO.Path]::GetExtension($entraFile)
					$entraFile = Join-Path $entraIncDir ($stem + '_raw' + $ext)
				}
			} catch {}
		}
		try {
			if ($script:EntraUsersData.Count -gt 0) {
				# Atomic temp+rename write.
				Save-CsvAtomic -InputObject $script:EntraUsersData -Path $entraFile -NoTypeInformation -Encoding UTF8
			} else {
				# Header-only export
				$header = ($script:EntraUsersData | Select-Object -First 1 | Get-Member -MemberType NoteProperty | Select-Object -ExpandProperty Name)
				if ($header) { ($null | Select-Object $header) | Export-Csv -Path $entraFile -NoTypeInformation -Encoding UTF8 }
			}
			# Carry forward the AUTHORITATIVE local path just emitted for the raw Entra users CSV so the
			# CopilotInteraction rollup post-processor consumes THIS exact file (honoring a separate
			# -OutputPathUserInfo destination, the effective basename, and any pristine-raw '_raw' suffix)
			# instead of reconstructing it under the Purview output directory. Under -Rollup/-RollupPlusRaw +
			# CopilotInteraction the raw persists to rollup time; the rollup consumer re-validates existence,
			# so a later -AppendUserInfo in-band cleanup path is safe.
			$script:RollupEntraLocalPath = $entraFile
			# Report the raw path only when it persists past this step. Outside
			# -AppendUserInfo the raw IS the customer's output; under -AppendUserInfo
			# with a deferred merge (-Rollup / -RollupPlusRaw + CopilotInteraction)
			# the raw persists until the rollup post-processor runs and is
			# informative; under -AppendUserInfo with an in-band merge the raw is
			# transient (deleted after the merge succeeds), so the up-front log
			# line is suppressed and the end-of-run output files listing handles
			# the merge-failure case.
			if ((-not $AppendUserInfo) -or (($Rollup -or $RollupPlusRaw) -and ($script:RollupProcessorMode -eq 'CopilotInteraction'))) {
				Write-LogHost ("Raw EntraUsers CSV: {0}" -f (Get-DisplayPath -LocalPath $entraFile)) -ForegroundColor Green
			}
			if ($AppendUserInfo -and (Test-Path -LiteralPath $entraFile -PathType Leaf)) {
				# Double-merge avoidance: when the embedded Python rollup post-processor
				# will run AND it is in CopilotInteraction mode, the rollup performs its
				# own -AppendUserInfo merge against the Python-emitted Users CSV later
				# (see 'Rollup: -AppendUserInfo merge:' tally). Doing the PS-side
				# pre-rollup merge here would write the union, then have it overwritten
				# by the post-rollup merge — wasted I/O AND a transient
				# (potentially wrong-stats) state on disk visible to any parallel reader
				# (the PS-side keys on PersonId_Normalized against the rolled-up target
				# schema, while the Python rollup re-normalizes UserKey; mismatched keys
				# would produce inflated unions). Defer to the post-rollup merge in that
				# case. M365Bundle rollup mode does NOT consume the Entra CSV and so
				# does NOT do a Python-side AppendUserInfo merge — its AppendUserInfo
				# merge MUST still happen here.
				$_deferUsersMergeToRollup = (($Rollup -or $RollupPlusRaw) -and ($script:RollupProcessorMode -eq 'CopilotInteraction'))
				if ($_deferUsersMergeToRollup) {
					$_deferUsersMergeSwitch = if ($Rollup) { '-Rollup' } else { '-RollupPlusRaw' }
					Write-LogHost ("EntraUsers append-merge: deferred to rollup post-processor (-AppendUserInfo + {0}; the embedded CopilotInteraction processor will perform the merge against the rolled-up Users CSV later this run)." -f $_deferUsersMergeSwitch) -ForegroundColor DarkCyan
				}
				else {
					try {
						# Remote -AppendUserInfo lands in scratch under '.pax_appendseed_*' (excluded
						# from upload). Write the union to a non-seed scratch path inheriting the
						# AppendUserInfo target's original leaf so the upload sweep picks it up.
						$_auiMergeOut = if ($script:AppendIsRemote.ContainsKey('UserInfo') -and $script:AppendIsRemote['UserInfo'] -and $script:AppendRaw.ContainsKey('UserInfo') -and $script:AppendRaw['UserInfo']) {
							Join-Path $OutputPath ([System.IO.Path]::GetFileName($script:AppendRaw['UserInfo']))
						} else { $AppendUserInfo }
						$mergeStats = Merge-UsersCsv -TargetUsersCsv $AppendUserInfo -CurrentUsersCsv $entraFile -OutputPath $_auiMergeOut
						$entraIncDisplay = if ($script:AppendRaw.ContainsKey('UserInfo') -and $script:AppendRaw['UserInfo']) {
							$script:AppendRaw['UserInfo']
						} else {
							Get-DisplayPath -LocalPath $AppendUserInfo
						}
						Write-LogHost ("EntraUsers CSV updated (append-merge): {0}" -f $entraIncDisplay) -ForegroundColor Green
						Write-LogHost ("EntraUsers append-merge complete: retained={0} new={1} departed={2} union={3}" -f $mergeStats.Retained, $mergeStats.New, $mergeStats.Departed, $mergeStats.Union) -ForegroundColor Green
						# Remove the transient raw EntraUsers CSV now that the union has
						# been committed to the AppendUserInfo target (parity with the
						# -AppendFile streaming-merge clean: only the merged target
						# remains on disk at run-end). Guarded so the merge output path
						# is never deleted (rare collision case where a customer-supplied
						# remote AppendUserInfo leaf matches the natural raw leaf). Under
						# -Rollup / -RollupPlusRaw + CopilotInteraction this branch does
						# not execute (the merge is deferred to the rollup post-processor,
						# which handles raw retention/deletion per the rollup mode rules).
						try {
							if ((Test-Path -LiteralPath $entraFile -PathType Leaf) -and
							    ([System.IO.Path]::GetFullPath($entraFile) -ne [System.IO.Path]::GetFullPath($_auiMergeOut))) {
								Remove-Item -LiteralPath $entraFile -Force -ErrorAction Stop
							}
						} catch { Write-LogHost ("EntraUsers raw cleanup failed (non-fatal): {0}" -f $_.Exception.Message) -ForegroundColor DarkYellow }
					} catch { Write-LogHost "WARNING: EntraUsers append-merge failed: $($_.Exception.Message)" -ForegroundColor Yellow }
				}
			}
		} catch { Write-LogHost "WARNING: Failed to export EntraUsers CSV: $($_.Exception.Message)" -ForegroundColor Yellow }
	}

	if ($csvSeparateMode -and -not $OnlyUserInfo -and -not $_appendFileActiveForSplitter -and (Test-Path $OutputFile)) {
		Write-LogHost ""
		Write-LogHost "=== Splitting CSV by Activity Type ===" -ForegroundColor Cyan
		Write-LogHost "Reading combined CSV: $(Get-DisplayPath -LocalPath $OutputFile)" -ForegroundColor Gray
		
		try {
			# Bounded split: stream the combined CSV once (RFC-4180) and route each row to
			# its activity-type writer, holding at most a fixed cap of writers open (LRU
			# close + reopen in append mode beyond the cap). Input row order is preserved
			# within each activity file; the whole export is never materialized and no
			# activity group is collected. The combined CSV is deleted only after every
			# split writer closes successfully.
			Write-LogHost "Streaming combined CSV (bounded per-activity writers)" -ForegroundColor Gray
			$outputDir = Split-Path $OutputFile -Parent
			$createdFiles = @()
			$splitWriterCap = 64
			$u8Split = [System.Text.UTF8Encoding]::new($false)
			$splitReader = [System.IO.StreamReader]::new((Resolve-Path -LiteralPath $OutputFile).Path, $true)
			$splitWriters = @{}                                             # activityType -> StreamWriter
			$splitLru = New-Object System.Collections.Generic.List[string]  # LRU order of open writers
			$splitPath = @{}                                               # activityType -> file path
			$splitSeen = New-Object System.Collections.Generic.List[string] # first-seen order
			$splitCounts = @{}
			$splitTotal = 0
			try {
				$splitHeader = script:Read-PaxCsvRecord -Reader $splitReader
				if ($null -eq $splitHeader) { throw "combined CSV '$OutputFile' has no header row." }
				$opIdx = -1
				for ($i = 0; $i -lt $splitHeader.Length; $i++) { if ([string]::Equals([string]$splitHeader[$i], 'Operation', [System.StringComparison]::OrdinalIgnoreCase)) { $opIdx = $i; break } }
				$getSplitWriter = {
					param($type)
					if ($splitWriters.ContainsKey($type)) {
						[void]$splitLru.Remove($type); $splitLru.Add($type)
						return $splitWriters[$type]
					}
					$fp = $splitPath[$type]
					$existed = Test-Path -LiteralPath $fp
					if ($splitWriters.Count -ge $splitWriterCap) {
						$lru = $splitLru[0]; [void]$splitLru.RemoveAt(0)
						$splitWriters[$lru].Flush(); $splitWriters[$lru].Dispose(); $splitWriters.Remove($lru)
					}
					$sw = [System.IO.StreamWriter]::new($fp, $existed, $u8Split)   # append if reopened after LRU close
					if (-not $existed) { script:Write-PaxCsvRecord -Writer $sw -Fields $splitHeader }
					$splitWriters[$type] = $sw; $splitLru.Add($type)
					return $sw
				}
				while ($true) {
					$fields = script:Read-PaxCsvRecord -Reader $splitReader
					if ($null -eq $fields) { break }
					$op = if ($opIdx -ge 0 -and $opIdx -lt $fields.Length) { [string]$fields[$opIdx] } else { '' }
					$activityType = if ([string]::IsNullOrWhiteSpace($op)) { 'Unknown' } else { $op }
					if (-not $splitPath.ContainsKey($activityType)) {
						$safeActivityName = $activityType -replace '[\\/:*?"<>|]', '_'
						$fileName = "Purview_Audit_UsageActivity_${safeActivityName}_${global:ScriptRunTimestamp}.csv"
						$splitPath[$activityType] = Join-Path $outputDir $fileName
						$splitSeen.Add($activityType)
						$splitCounts[$activityType] = 0
					}
					$w = & $getSplitWriter $activityType
					script:Write-PaxCsvRecord -Writer $w -Fields $fields
					$splitCounts[$activityType] = $splitCounts[$activityType] + 1
					$splitTotal++
				}
			}
			finally {
				foreach ($k in @($splitWriters.Keys)) { try { $splitWriters[$k].Flush(); $splitWriters[$k].Dispose() } catch {} }
				$splitReader.Dispose()
			}
			Write-LogHost "Found $($splitSeen.Count) activity types across $splitTotal records" -ForegroundColor Gray
			foreach ($t in $splitSeen) {
				$fp = $splitPath[$t]
				$createdFiles += $fp
				Write-LogHost ("  • {0} → {1} ({2} records)" -f $t, (Split-Path -Leaf $fp), $splitCounts[$t]) -ForegroundColor DarkCyan
			}


		# Emit EntraUsers listing inline with the other split-file bullets so the visual
		# split-summary group is contiguous BEFORE the "Removed combined CSV" closer.
		# In csvSeparateMode + IncludeUserInfo, the dedicated EntraUsers CSV export above
		# (around line ~16704) has already written the file. Re-running Export-Csv here would
		# just rewrite the same data; only emit a fallback write if the file is missing.
		if ($IncludeUserInfo -and $script:EntraUsersData) {
			# Effective basename (see OnlyUserInfo writer for rationale).
			$entraFallbackBase = (& $script:GetEffectiveEntraBasename)
			$entraFile = Join-Path $outputDir $entraFallbackBase
			if (-not (Test-Path $entraFile)) {
				try {
					# Atomic temp+rename write.
					Save-CsvAtomic -InputObject $script:EntraUsersData -Path $entraFile -NoTypeInformation -Encoding UTF8
				} catch { Write-LogHost "WARNING: Failed to export EntraUsers CSV: $($_.Exception.Message)" -ForegroundColor Yellow }
			}
			if (Test-Path $entraFile) {
				Write-LogHost "  • EntraUsers → $(Split-Path -Leaf $entraFile) ($($script:EntraUsersData.Count) rows)" -ForegroundColor DarkCyan
				$createdFiles += $entraFile
			}
		}

			# Delete combined CSV file
			Remove-Item -Path $OutputFile -Force -ErrorAction SilentlyContinue
			Write-LogHost "Removed combined CSV (replaced with $($createdFiles.Count) separate files)" -ForegroundColor Gray
			
			# Update OutputFile to point to directory for summary message
			$script:CsvSplitFiles = $createdFiles
			Write-LogHost "CSV splitting complete: $($createdFiles.Count) files created" -ForegroundColor Green
			
		} catch {
			Write-LogHost "WARNING: CSV splitting failed: $($_.Exception.Message)" -ForegroundColor Yellow
			Write-LogHost "Combined CSV retained at: $(Get-DisplayPath -LocalPath $OutputFile)" -ForegroundColor Yellow
		}
	}
	
	# --- Excel Post-Processing Conversion (Option A) ---
	if ($ExportWorkbook -and $script:CsvOutputFile -and (Test-Path $script:CsvOutputFile)) {
		Write-LogHost ""
		Write-LogHost "=== Converting CSV to Excel ===" -ForegroundColor Cyan
		
		# Excel filename already determined at script start in $OutputFile
		$excelFilePath = $OutputFile
		
		# Handle AppendFile mode vs normal mode
		# Note: If AppendFile mode, temp CSV was already created during CSV export (stored in $script:AppendFileTempCsv)
		if ($AppendFile) {
			# AppendFile mode: Use user-specified Excel file and temp CSV
			$excelFilePath = $OutputFile  # User's target Excel file (set at line 4355)
			$csvFilePath = $script:AppendFileTempCsv  # Temp CSV with new data (set at line 7557)
			
			Write-LogHost "AppendFile mode: Appending to existing workbook: $(Get-DisplayPath -LocalPath $excelFilePath)" -ForegroundColor Cyan
			Write-LogHost "  Reading new data from: $csvFilePath" -ForegroundColor Gray
			
			# Pre-flight: Test file accessibility before trying Excel operations
			try {
				$fileStream = [System.IO.File]::Open($excelFilePath, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
				$fileStream.Close()
				$fileStream.Dispose()
			}
			catch {
				Write-Host "ERROR: Cannot access file for reading: $($_.Exception.Message)" -ForegroundColor Red
				Write-Host "  File: $excelFilePath" -ForegroundColor Yellow
				Write-Host "" -ForegroundColor Yellow
				Write-Host "Common causes:" -ForegroundColor Yellow
				Write-Host "  • File is currently open in Excel with exclusive lock (close it and try again)" -ForegroundColor Gray
				Write-Host "  • File is in a OneDrive/SharePoint folder with sync issues (check file status)" -ForegroundColor Gray
				Write-Host "  • Insufficient permissions to read the file" -ForegroundColor Gray
				Write-Host "" -ForegroundColor Yellow
				Write-Host "Troubleshooting steps:" -ForegroundColor Cyan
				Write-Host "  1. Close Excel if the file is open" -ForegroundColor Gray
				Write-Host "  2. Copy file to a local folder (C:\temp) and retry" -ForegroundColor Gray
				Write-Host "  3. Verify file permissions and OneDrive sync status" -ForegroundColor Gray
				exit 1
			}
			
			# Read existing sheets inline for validation
			try {
				# Ensure ImportExcel module is loaded
				if (-not (Get-Module -Name ImportExcel)) {
					Write-Host "WARNING: ImportExcel module not loaded, attempting to load..." -ForegroundColor Yellow
					Import-Module ImportExcel -ErrorAction Stop
				}
				
				$existingSheets = Get-ExcelSheetInfo -Path $excelFilePath | Select-Object -ExpandProperty Name
				$script:ExistingExcelSheets = $existingSheets
				Write-LogHost "  Existing sheets: $($existingSheets -join ', ')" -ForegroundColor DarkGray
			}
			catch {
				# First, validate it's actually an Excel file (ZIP container with xl/workbook.xml)
				Write-Host "ERROR: Cannot read Excel workbook structure: $($_.Exception.Message)" -ForegroundColor Red
				Write-Host "  File: $excelFilePath" -ForegroundColor Yellow
				Write-Host "" -ForegroundColor Yellow
				
				# Try to determine the actual issue
				$isValidZip = $false
				$hasWorkbookXml = $false
				try {
					Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
					$zip = [System.IO.Compression.ZipFile]::OpenRead($excelFilePath)
					$isValidZip = $true
					$hasWorkbookXml = $zip.Entries | Where-Object { $_.FullName -eq 'xl/workbook.xml' }
					$zip.Dispose()
				}
				catch {
					# Not a valid ZIP
				}
				
				if (-not $isValidZip) {
					Write-Host "Root cause: File is not a valid ZIP archive (Excel files are ZIP containers)" -ForegroundColor Yellow
					Write-Host "" -ForegroundColor Yellow
					Write-Host "Possible causes:" -ForegroundColor Yellow
					Write-Host "  • File was renamed from .csv to .xlsx (not converted)" -ForegroundColor Gray
					Write-Host "  • File download was interrupted or corrupted" -ForegroundColor Gray
					Write-Host "  • File created by incompatible tool" -ForegroundColor Gray
				}
				elseif (-not $hasWorkbookXml) {
					Write-Host "Root cause: ZIP file is valid but missing 'xl/workbook.xml' (not a proper Excel workbook)" -ForegroundColor Yellow
					Write-Host "" -ForegroundColor Yellow
					Write-Host "Possible causes:" -ForegroundColor Yellow
					Write-Host "  • File is corrupted or incomplete" -ForegroundColor Gray
					Write-Host "  • File created by tool that doesn't follow Excel format" -ForegroundColor Gray
				}
				else {
					Write-Host "Root cause: ImportExcel module cannot parse this workbook" -ForegroundColor Yellow
					Write-Host "" -ForegroundColor Yellow
					Write-Host "Possible causes:" -ForegroundColor Yellow
					Write-Host "  • ImportExcel module version incompatibility" -ForegroundColor Gray
					Write-Host "  • File created by different ImportExcel version" -ForegroundColor Gray
					Write-Host "  • Workbook has features ImportExcel can't parse" -ForegroundColor Gray
					Write-Host "" -ForegroundColor Yellow
					Write-Host "Current ImportExcel version:" -ForegroundColor Cyan
					try {
						$importExcelModule = Get-Module -Name ImportExcel -ListAvailable | Select-Object -First 1
						Write-Host "  $($importExcelModule.Version)" -ForegroundColor Gray
					}
					catch {
						Write-Host "  Unable to detect version" -ForegroundColor Gray
					}
				}
				
				Write-Host "" -ForegroundColor Yellow
				Write-Host "Recommended solutions:" -ForegroundColor Cyan
				Write-Host "  1. Open file in Excel and verify it opens correctly" -ForegroundColor Gray
				Write-Host "  2. If it opens: File > Save As > Excel Workbook (.xlsx) to 'clean' it" -ForegroundColor Gray
				Write-Host "  3. Update ImportExcel: Update-Module ImportExcel -Force" -ForegroundColor Gray
				Write-Host "  4. Recreate initial export without -AppendFile using current script" -ForegroundColor Gray
				Write-Host "" -ForegroundColor Yellow
				Write-Host "DEBUG INFO:" -ForegroundColor Cyan
				Write-Host "  File exists: $(Test-Path $excelFilePath)" -ForegroundColor Gray
				Write-Host "  File size: $((Get-Item $excelFilePath -ErrorAction SilentlyContinue).Length) bytes" -ForegroundColor Gray
				Write-Host "  File extension: $([System.IO.Path]::GetExtension($excelFilePath))" -ForegroundColor Gray
				Write-Host "  First 4 bytes (hex): " -NoNewline -ForegroundColor Gray
				try {
					$bytes = [System.IO.File]::ReadAllBytes($excelFilePath) | Select-Object -First 4
					Write-Host "$(($bytes | ForEach-Object { $_.ToString('X2') }) -join ' ')" -ForegroundColor Gray
					if ($bytes[0] -eq 0x50 -and $bytes[1] -eq 0x4B) {
						Write-Host "    (Valid ZIP signature: PK)" -ForegroundColor Green
					} else {
						Write-Host "    (NOT a ZIP file - should start with 'PK' = 50 4B)" -ForegroundColor Red
					}
				}
				catch {
					Write-Host "Unable to read bytes" -ForegroundColor Gray
				}
				exit 1
			}
		} else {
			# Normal mode: CSV path uses the intermediate CsvOutputFile
			$csvFilePath = $script:CsvOutputFile
		}
		
		# Excel conversion - use fast path when possible
		try {
			if ($CombineOutput) {
				# --- Combined Mode: Single-tab workbook ---
				$tabName = "CombinedUsageActivity"
				
				if ($AppendFile -and $script:ExistingExcelSheets -contains $tabName) {
					# Append mode: validate headers (bounded — reads only the CSV header row)
					Write-LogHost "Validating headers for tab: $tabName" -ForegroundColor Gray
					$existingWorkbook = Import-Excel -Path $excelFilePath -WorksheetName $tabName -StartRow 1 -EndRow 1 -NoHeader
					$existingHeaders = $existingWorkbook[0].PSObject.Properties.Value | Where-Object { $_ }
					$newHeaders = Get-PaxCsvHeader -CsvPath $csvFilePath
					$totalRows = 0
					
					$headerMismatch = $false
					if ($existingHeaders.Count -ne $newHeaders.Count) {
						$headerMismatch = $true
					} else {
						for ($i = 0; $i -lt $existingHeaders.Count; $i++) {
							if ($existingHeaders[$i] -ne $newHeaders[$i]) {
								$headerMismatch = $true
								break
							}
						}
					}
					
					if ($headerMismatch) {
						# Create timestamped duplicate tab
						$timestampedTabName = "${tabName}_$excelTimestamp"
						Write-LogHost "WARNING: Header mismatch detected for tab '$tabName'" -ForegroundColor Yellow
						Write-LogHost "Creating timestamped duplicate tab: $timestampedTabName" -ForegroundColor Yellow
						$totalRows = Write-PaxCsvToWorksheet -CsvPath $csvFilePath -WorkbookPath $excelFilePath -WorksheetName $timestampedTabName
					} else {
						# Append to existing tab
						Write-LogHost "Appending to existing tab: $tabName" -ForegroundColor Gray
						$totalRows = Write-PaxCsvToWorksheet -CsvPath $csvFilePath -WorkbookPath $excelFilePath -WorksheetName $tabName -Append
					}
			} else {
				# Create new tab or new workbook
				Write-LogHost "Creating tab: $tabName" -ForegroundColor Gray
				$totalRows = Write-PaxCsvToWorksheet -CsvPath $csvFilePath -WorkbookPath $excelFilePath -WorksheetName $tabName
				# Append EntraUsers tab if requested
				if ($IncludeUserInfo -and $script:EntraUsersData) {
					$entraTab = 'EntraUsers_MAClicensing'
					Write-LogHost "Creating tab: $entraTab" -ForegroundColor Gray
					$entraDataTable = $script:EntraUsersData | ConvertTo-DataTable
					Send-SQLDataToExcel -DataTable $entraDataTable -Path $excelFilePath -WorkSheetName $entraTab -FreezeTopRow -BoldTopRow -AutoSize -NoNumberConversion '*'
				}
			}
			
			$xlsxVerb1 = if ($AppendFile) { 'Excel workbook updated (append-merge)' } else { 'Excel workbook created' }
			Write-LogHost ("{0}: {1}" -f $xlsxVerb1, (Get-DisplayPath -LocalPath $excelFilePath)) -ForegroundColor Green
			Write-LogHost "  Tab: $tabName | Rows: $totalRows" -ForegroundColor White			} else {
				# --- Multi-tab Mode: One tab per activity type ---
				# Partition the CSV by Operation with a single streaming pass (one
				# bounded per-activity temp file each), so the full row set is never
				# held in memory for grouping.
				Write-LogHost "Partitioning CSV by activity type: $csvFilePath" -ForegroundColor Gray
				$multiTabWorkDir = Join-Path ([System.IO.Path]::GetDirectoryName($excelFilePath)) (".paxwb_" + [guid]::NewGuid().ToString('N'))
				New-Item -ItemType Directory -Path $multiTabWorkDir -Force | Out-Null
				$groupedData = Split-PaxCsvByColumn -CsvPath $csvFilePath -ColumnName 'Operation' -WorkDir $multiTabWorkDir
				Write-LogHost "Partitioned into $($groupedData.Count) activity group(s)" -ForegroundColor Gray
				
				# Calculate total tab count (activity types + EntraUsers if present)
				$activityTabCount = $groupedData.Count
				$totalTabCount = $activityTabCount
				if ($IncludeUserInfo -and $script:EntraUsersData) {
					$totalTabCount += 1  # Add EntraUsers tab
				}
				
				$tabLabel = if ($totalTabCount -eq 1) { "tab" } else { "tabs" }
				Write-LogHost "Creating multi-tab workbook with $totalTabCount $tabLabel" -ForegroundColor Gray
				
				$tabsCreated = @()
				foreach ($group in $groupedData) {
					$activityType = $group.Value
					$activityRows = $group.RowCount
					
					if ($AppendFile -and $script:ExistingExcelSheets -contains $activityType) {
						# Validate headers match (bounded — reads only the group header row)
						Write-LogHost "Validating headers for tab: $activityType" -ForegroundColor Gray
						$existingWorkbook = Import-Excel -Path $excelFilePath -WorksheetName $activityType -StartRow 1 -EndRow 1 -NoHeader
						$existingHeaders = $existingWorkbook[0].PSObject.Properties.Value | Where-Object { $_ }
						$newHeaders = Get-PaxCsvHeader -CsvPath $group.Path
						
						$headerMismatch = $false
						if ($existingHeaders.Count -ne $newHeaders.Count) {
							$headerMismatch = $true
						} else {
							for ($i = 0; $i -lt $existingHeaders.Count; $i++) {
								if ($existingHeaders[$i] -ne $newHeaders[$i]) {
									$headerMismatch = $true
									break
								}
							}
						}
						
						if ($headerMismatch) {
							# Create timestamped duplicate tab
							$timestampedTabName = "${activityType}_$excelTimestamp"
							Write-LogHost "WARNING: Header mismatch detected for tab '$activityType'" -ForegroundColor Yellow
							Write-LogHost "Creating timestamped duplicate tab: $timestampedTabName" -ForegroundColor Yellow
							[void](Write-PaxCsvToWorksheet -CsvPath $group.Path -WorkbookPath $excelFilePath -WorksheetName $timestampedTabName)
							$tabsCreated += "$timestampedTabName ($activityRows rows)"
						} else {
							# Append to existing tab
							Write-LogHost "Appending to existing tab: $activityType" -ForegroundColor Gray
							[void](Write-PaxCsvToWorksheet -CsvPath $group.Path -WorkbookPath $excelFilePath -WorksheetName $activityType -Append)
							$tabsCreated += "$activityType ($activityRows rows appended)"
						}
					} else {
						# Create new tab
						Write-LogHost "Creating tab: $activityType ($activityRows rows)" -ForegroundColor Gray
						[void](Write-PaxCsvToWorksheet -CsvPath $group.Path -WorkbookPath $excelFilePath -WorksheetName $activityType)
						$tabsCreated += "$activityType ($activityRows rows)"
					}


				# After creating all activity tabs, append EntraUsers if requested
				if ($IncludeUserInfo -and $script:EntraUsersData) {
					$entraTab = 'EntraUsers_MAClicensing'
					Write-LogHost "Creating tab: $entraTab ($($script:EntraUsersData.Count) rows)" -ForegroundColor Gray
					$entraDataTable = $script:EntraUsersData | ConvertTo-DataTable
					Send-SQLDataToExcel -DataTable $entraDataTable -Path $excelFilePath -WorkSheetName $entraTab -FreezeTopRow -BoldTopRow -AutoSize -NoNumberConversion '*'
					$tabsCreated += "$entraTab ($($script:EntraUsersData.Count) rows)"
				}
			}
			
		
		$xlsxVerb2 = if ($AppendFile) { 'Excel workbook updated (append-merge)' } else { 'Excel workbook created' }
		Write-LogHost ("{0}: {1}" -f $xlsxVerb2, (Get-DisplayPath -LocalPath $excelFilePath)) -ForegroundColor Green
		Write-LogHost "  Tabs: $($tabsCreated -join ', ')" -ForegroundColor White
		if ($multiTabWorkDir -and (Test-Path -LiteralPath $multiTabWorkDir)) {
			Remove-Item -LiteralPath $multiTabWorkDir -Recurse -Force -ErrorAction SilentlyContinue
		}
	}
		# Delete temporary CSV file (with retry for file lock issues)
		if ($AppendFile -and $script:AppendFileTempCsv) {
			# AppendFile mode: Remove the temp CSV we created for new data
			Write-LogHost "Removing temporary CSV file: $script:AppendFileTempCsv" -ForegroundColor Gray
			Remove-Item -Path $script:AppendFileTempCsv -Force -ErrorAction SilentlyContinue
		} elseif (-not $AppendFile) {
			# Normal mode: Remove the intermediate CSV that was converted to Excel
			Write-LogHost "Removing temporary CSV file: $script:CsvOutputFile" -ForegroundColor Gray
			# Retry with delay to handle transient file locks (antivirus, OneDrive sync, etc.)
			$deleteSuccess = $false
			for ($retryCount = 0; $retryCount -lt 3; $retryCount++) {
				try {
					# Force garbage collection to release any .NET file handles
					[System.GC]::Collect()
					[System.GC]::WaitForPendingFinalizers()
					Start-Sleep -Milliseconds 500
					Remove-Item -Path $script:CsvOutputFile -Force -ErrorAction Stop
					$deleteSuccess = $true
					break
				} catch {
					if ($retryCount -lt 2) {
						Write-LogHost "  File locked, retrying in 2 seconds... (attempt $($retryCount + 1)/3)" -ForegroundColor DarkYellow
						Start-Sleep -Seconds 2
					}
				}
			}
			if (-not $deleteSuccess) {
				Write-LogHost "  Could not delete temp CSV (file may be locked by another process)" -ForegroundColor Yellow
				Write-LogHost "  CSV file preserved at: $script:CsvOutputFile" -ForegroundColor Yellow
			}
		}
		# Note: $OutputFile already points to the final Excel file
		} catch {
			Write-LogHost "ERROR: Failed to convert CSV to Excel: $($_.Exception.Message)" -ForegroundColor Red
			Write-LogHost "CSV file preserved at: $script:CsvOutputFile" -ForegroundColor Yellow
		}
	}
	
	# ============================================================
	# CHECKPOINT COMPLETION: Rename _PARTIAL file and delete checkpoint.
	# In CSV-split / ExportWorkbook modes the intermediate _PARTIAL.csv may already have been
	# deleted by upstream code paths; Complete-CheckpointRun skips the rename internally when
	# the partial file is gone but still deletes the checkpoint.
	# ============================================================
	if ($script:CheckpointEnabled) {
		Complete-CheckpointRun -FinalOutputPath $script:FinalOutputPath
		# Update OutputFile to point to final path (without _PARTIAL) for correct display
		$OutputFile = $script:FinalOutputPath
		$LogFile = $script:LogFile  # Also update LogFile variable (was updated by Complete-CheckpointRun)
	}
	
	# ============================================================
	# FALLBACK LOG RENAME — remove _PARTIAL from log file.
	# When CSV split mode deletes the combined _PARTIAL.csv before Complete-CheckpointRun
	# runs, the Test-Path guard above fails and the log file is never renamed. This catch-all
	# handles that case (and any other code path that could skip the rename).
	# GUARD: Only rename on genuinely completed runs — interrupted or failed runs MUST keep
	# _PARTIAL so Resume mode can detect them.
	# ============================================================
	if ($script:LogFile -and $script:LogFile -match '_PARTIAL\.log$' -and (Test-Path $script:LogFile) -and -not $script:CtrlCPressed -and -not $script:EarlyExit) {
		try {
			$finalLogPath = $script:LogFile -replace '_PARTIAL\.log$', '.log'
			if (Test-Path $finalLogPath) {
				$logDir = Split-Path $finalLogPath -Parent
				$logName = [System.IO.Path]::GetFileNameWithoutExtension($finalLogPath)
				$ts = Get-Date -Format 'yyyyMMdd_HHmmss'
				$finalLogPath = Join-Path $logDir "${logName}_${ts}.log"
			}
			Move-Item -Path $script:LogFile -Destination $finalLogPath -Force
			$script:LogFile = $finalLogPath
			$LogFile = $finalLogPath
		} catch {
			# Non-fatal: log file keeps _PARTIAL suffix but data is intact
		}
	}
	
	Write-LogHost ""; Write-LogHost "=== Enterprise Export Complete ===" -ForegroundColor Green
	
	if ($OnlyUserInfo) {
		# User-only export mode summary
		if ($script:EntraUsersData) {
			Write-LogHost "Entra users exported: $($script:EntraUsersData.Count)" -ForegroundColor White
			if ($script:EntraUsersPartial) {
				Write-LogHost "WARNING: Entra user directory is PARTIAL (paging did not complete): $script:EntraUsersFetchError" -ForegroundColor Yellow
			}
		}
		elseif ($script:EntraUsersFetchFailed) {
			Write-LogHost "ERROR: Entra user directory FAILED - file not generated: $script:EntraUsersFetchError" -ForegroundColor Red
		}
	} else {
		# Standard audit log export summary
		Write-LogHost "Records exported: $($script:metrics.TotalStructuredRows)" -ForegroundColor White
		if ($IncludeUserInfo -and -not $UseEOM -and $script:EntraUsersData) {
			Write-LogHost "Entra users exported: $($script:EntraUsersData.Count)" -ForegroundColor White
			if ($script:EntraUsersPartial) {
				Write-LogHost "WARNING: Entra user directory is PARTIAL (paging did not complete): $script:EntraUsersFetchError" -ForegroundColor Yellow
			}
		}
		elseif ($IncludeUserInfo -and -not $UseEOM -and $script:EntraUsersFetchFailed) {
			Write-LogHost "ERROR: Entra user directory FAILED - file not generated: $script:EntraUsersFetchError" -ForegroundColor Red
		}
	}
	
	
	# Display organized tail summary metrics - only for audit log exports
	if (-not $OnlyUserInfo -and $script:metrics -and $script:metrics.Activities -and $script:metrics.Activities.Count -gt 0) {
		Write-LogHost ""
		Write-LogHost "=== Activity Type Breakdown ===" -ForegroundColor Cyan
		
		# In resume mode with skipped partitions, the "Retrieved" counts only reflect THIS run's fetches
		# Records from previously-completed partitions (merged from incremental saves) are not counted in Retrieved
		if ($script:IsResumeMode -and $script:OriginallySkippedPartitionIndices -and $script:OriginallySkippedPartitionIndices.Count -gt 0) {
			Write-LogHost "  Note: Resume mode - 'Retained' counts reflect only this run's fetches" -ForegroundColor DarkGray
			Write-LogHost "        (excludes $($script:OriginallySkippedPartitionIndices.Count) previously-completed partition(s))" -ForegroundColor DarkGray
			Write-LogHost ""
		}
		
		$totalRetrieved = $script:metrics.TotalRecordsFetched
		$totalExported = $script:metrics.TotalStructuredRows
		$totalFiltered = $script:metrics.FilteringSkippedRecords
		
		foreach ($actKey in ($script:metrics.Activities.Keys | Sort-Object)) {
			$actStats = $script:metrics.Activities[$actKey]
			$retrieved = $actStats.Retrieved
			$structured = $actStats.Structured
			$ratio = if ($retrieved -gt 0) { [Math]::Round($structured / $retrieved, 1) } else { 0 }
			
			Write-LogHost "  $actKey" -ForegroundColor White
			Write-LogHost "    Retained:  $retrieved records" -ForegroundColor Gray
			
			# Show filtering breakdown if records were filtered for this activity type
			$actFiltered = $retrieved - $structured
			if ($actFiltered -gt 0 -and $ratio -le 1) {
				Write-LogHost "    Filtered:  $actFiltered records" -ForegroundColor DarkYellow
				
				# Only show filters that were actually applied (check parameter + impact)
				# Technical failures (always show if present)
				if ($script:metrics.FilteringMissingAuditData -gt 0) {
					Write-LogHost "      - Missing/invalid AuditData: $($script:metrics.FilteringMissingAuditData)" -ForegroundColor DarkGray
				}
				if ($script:metrics.FilteringParseFailures -gt 0) {
					Write-LogHost "      - Parse failures: $($script:metrics.FilteringParseFailures)" -ForegroundColor DarkGray
				}
				
				# User-specified filters (only show if parameter was used)
				if ($PromptFilter) {
					$promptCount = if ($script:metrics.FilteringPromptFiltered -gt 0) { $script:metrics.FilteringPromptFiltered } else { 0 }
					Write-LogHost "      - PromptFilter ($PromptFilter): $promptCount" -ForegroundColor DarkGray
				}
				if ($AgentId) {
					$agentCount = if ($script:metrics.FilteringAgentFiltered -gt 0) { $script:metrics.FilteringAgentFiltered } else { 0 }
					Write-LogHost "      - AgentId filter: $agentCount" -ForegroundColor DarkGray
				}
				if ($AgentsOnly) {
					$agentCount = if ($script:metrics.FilteringAgentFiltered -gt 0) { $script:metrics.FilteringAgentFiltered } else { 0 }
					Write-LogHost "      - AgentsOnly filter: $agentCount" -ForegroundColor DarkGray
				}
				if ($ExcludeAgents) {
					$excludeCount = if ($script:metrics.FilteringExcludeAgents -gt 0) { $script:metrics.FilteringExcludeAgents } else { 0 }
					Write-LogHost "      - ExcludeAgents filter: $excludeCount" -ForegroundColor DarkGray
				}
				if ($UserIds) {
					Write-LogHost "      - UserIds in scope: $($script:metrics.FilteringUserIds)" -ForegroundColor DarkGray
				}
				if ($GroupNames) {
					Write-LogHost "      - GroupNames in scope: $($script:metrics.FilteringGroupNames) group(s), $($script:metrics.ScopeExpandedMembers) member(s)" -ForegroundColor DarkGray
				}
				
				# Calculate explained filtering count
				$explainedFiltering = 0
				$explainedFiltering += $script:metrics.FilteringMissingAuditData
				$explainedFiltering += $script:metrics.FilteringParseFailures
				if ($PromptFilter) { $explainedFiltering += $script:metrics.FilteringPromptFiltered }
				if ($AgentId) { $explainedFiltering += $script:metrics.FilteringAgentFiltered }
				if ($AgentsOnly) { $explainedFiltering += $script:metrics.FilteringAgentFiltered }
				if ($ExcludeAgents) { $explainedFiltering += $script:metrics.FilteringExcludeAgents }
				# UserIds/GroupNames now carry requested-scope counts (not per-record exclusions),
				# so they are reported separately above and excluded from the record-exclusion tally.
				
				# Show unspecified reason if filtered count doesn't match explained reasons
				if ($explainedFiltering -eq 0 -or $actFiltered -gt $explainedFiltering) {
					$unexplained = $actFiltered - $explainedFiltering
					if ($unexplained -gt 0) {
						$yieldLabel = if ($ExplodeArrays -or $ExplodeDeep) { "Array explosion yield" } else { "Processing yield" }
						Write-LogHost "      - ${yieldLabel}: $unexplained" -ForegroundColor DarkGray
					}
				}
			}
			
			# Show explosion details if exploding mode is enabled AND ratio > 1
			if (($ExplodeArrays -or $ExplodeDeep) -and $ratio -gt 1 -and -not $ExcelOutput) {
				Write-LogHost "    Exported:  $structured rows (${ratio}x expansion)" -ForegroundColor Gray
				if ($script:metrics.ExplosionEvents -gt 0) {
					$avgExpansion = if ($script:metrics.ExplosionEvents -gt 0) { 
						[Math]::Round(($script:metrics.ExplosionRowsFromEvents / $script:metrics.ExplosionEvents) + 1, 1) 
					} else { 1 }
					Write-LogHost "      - Avg expansion: ${avgExpansion}x per record" -ForegroundColor DarkGray
					if ($script:metrics.ExplosionMaxPerRecord -gt 0) {
						Write-LogHost "      - Max expansion: $($script:metrics.ExplosionMaxPerRecord)x (single record)" -ForegroundColor DarkGray
					}
				}
			} else {
				# Always show exported count for consistency
				Write-LogHost "    Exported:  $structured rows" -ForegroundColor Gray
			}
		}
		
		# Final pipeline summary
		Write-LogHost ""
		Write-LogHost "Pipeline Summary:" -ForegroundColor Cyan
		Write-LogHost "  Retained:  $totalRetrieved records" -ForegroundColor White
		if ($totalFiltered -gt 0) {
			Write-LogHost "  Filtered:  $totalFiltered records" -ForegroundColor White
		}
		Write-LogHost "  Exported:  $totalExported rows" -ForegroundColor White
		# Show duplicate removal count in Pipeline Summary when streaming merge deduplicated records
		if ($script:StreamingMergeDuplicatesSkipped -gt 0) {
			Write-LogHost "  Deduped:   $($script:StreamingMergeDuplicatesSkipped) duplicate records removed" -ForegroundColor DarkGray
		}
		# Show date-range trim count in Pipeline Summary
		if ($script:DateTrimCount -gt 0) {
			Write-LogHost "  Trimmed:   $($script:DateTrimCount) record(s) outside requested date range" -ForegroundColor DarkGray
		}
		# Show data loss warning in Pipeline Summary if partitions were missing
		if ($script:StreamingMergeDataLoss) {
			Write-LogHost "  [DATA-LOSS] WARNING: Output is PARTIAL — missing partitions: $($script:StreamingMergeMissingPartitions -join ', ')" -ForegroundColor Yellow
		}
	}
	
	# Export telemetry CSV for Graph API parallel execution analysis (one row per partition) - only when -IncludeTelemetry switch is used
	# Always timestamped to prevent overwriting previous telemetry data
	if ($IncludeTelemetry -and -not $OnlyUserInfo -and -not $UseEOM -and $script:telemetryData -and $script:telemetryData.Count -gt 0) {
		try {
			$baseName = [System.IO.Path]::GetFileNameWithoutExtension($OutputFile)
			$outputDir = Split-Path $OutputFile -Parent
			$telemetryPath = Join-Path $outputDir "${baseName}_telemetry_$global:ScriptRunTimestamp.csv"
			$script:telemetryData | Export-Csv -Path $telemetryPath -NoTypeInformation -Encoding UTF8
			Write-LogHost ""
			Write-LogHost "Graph API Telemetry: $telemetryPath" -ForegroundColor Cyan
		} catch {
			Write-LogHost "Warning: Failed to export telemetry CSV: $($_.Exception.Message)" -ForegroundColor Yellow
		}
	}
	Write-LogHost ""
	
	# File output summary (skip for -OnlyUserInfo and -OnlyAgent365Info modes)
	if (-not $OnlyUserInfo -and -not $OnlyAgent365Info) {
		if ($ExportWorkbook -and $OutputFile -match '\.xlsx$') {
			Write-LogHost "Output workbook: $(Get-DisplayPath -LocalPath $OutputFile)" -ForegroundColor White
			Write-LogHost "Workbook mode: $(if ($CombineOutput) { 'Single-tab (Combined)' } else { 'Multi-tab (By Activity Type)' })" -ForegroundColor White
			if ($IncludeUserInfo -and -not $UseEOM) { Write-LogHost "Entra Users Tab: EntraUsers_MAClicensing" -ForegroundColor Gray }
			if (Test-Path $OutputFile) {
				Write-LogHost "File size: $([math]::Round((Get-Item $OutputFile).Length / 1KB,2)) KB" -ForegroundColor White
			}
			if ($AppendFile) {
				Write-LogHost "Append mode: Enabled" -ForegroundColor Cyan
			}
		} elseif ($script:CsvSplitFiles -and $script:CsvSplitFiles.Count -gt 0) {
			# CSV was split into multiple files
			Write-LogHost "Output directory: $(Get-DisplayPath -LocalPath (Split-Path $OutputFile -Parent) -Directory)" -ForegroundColor White
			Write-LogHost "Files created: $($script:CsvSplitFiles.Count) separate CSV files" -ForegroundColor White
			$totalSize = ($script:CsvSplitFiles | ForEach-Object { (Get-Item $_).Length } | Measure-Object -Sum).Sum
			Write-LogHost "Total size: $([math]::Round($totalSize / 1KB,2)) KB" -ForegroundColor White
			if ($IncludeUserInfo -and -not $UseEOM) {
				# Honor -OutputPathUserInfo when bound; otherwise inherit $OutputFile's parent.
				$_uiDtE1 = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename (& $script:GetEffectiveEntraBasename)
				$entraSplit = if ($_uiDtE1 -and $_uiDtE1.IsBound -and $_uiDtE1.Tier -eq 'Local') { Join-Path $_uiDtE1.EffectiveDir $_uiDtE1.Basename }
					elseif ($_uiDtE1 -and $_uiDtE1.IsBound) { $_uiDtE1.EffectiveDir.TrimEnd('/') + '/' + $_uiDtE1.Basename }
					else { Join-Path (Split-Path $OutputFile -Parent) (& $script:GetEffectiveEntraBasename) }
				$_entraSplitDisplay = if ($_uiDtE1 -and $_uiDtE1.IsBound -and $_uiDtE1.Tier -ne 'Local') { $entraSplit } else { Get-DisplayPath -LocalPath $entraSplit }
				# Test-Path is only meaningful for local tiers; for remote tiers the writer
				# has already pushed the artifact and we just surface the destination.
				$_entraSplitLocalExists = ($_uiDtE1 -and $_uiDtE1.IsBound -and $_uiDtE1.Tier -ne 'Local') -or (Test-Path $entraSplit)
				if ($_entraSplitLocalExists) {
					if ($_uiDtE1 -and $_uiDtE1.IsBound -and $_uiDtE1.Tier -ne 'Local') {
						Write-LogHost "Entra Users File: $_entraSplitDisplay" -ForegroundColor Gray
					} else {
						$entraSize = [math]::Round((Get-Item $entraSplit).Length / 1KB,2)
						Write-LogHost "Entra Users File: $_entraSplitDisplay ($entraSize KB)" -ForegroundColor Gray
					}
				} else {
					Write-LogHost "Entra Users File: $_entraSplitDisplay (pending generation)" -ForegroundColor Gray
				}
			}
			
			# Show filename pattern instead of listing each file
			$outputDir   = Split-Path $OutputFile -Parent
			$displayDir3 = (Get-DisplayPath -LocalPath $outputDir -Directory).TrimEnd('/','\')
			$timestamp   = [System.IO.Path]::GetFileNameWithoutExtension($script:CsvSplitFiles[0]) -replace '.*_(\d{8}_\d{6}).*', '$1'
			Write-LogHost "Output pattern: ${displayDir3}\Purview_Audit_UsageActivity_<ActivityType>_${timestamp}.csv" -ForegroundColor Gray
		} elseif (Test-Path $OutputFile) {
			# End-of-run summary — use append-aware label and remote URL when available.
			# Under -Rollup/-RollupPlusRaw, the actual append happens later (post-Python
			# via Merge-FactCsv / Merge-UsersCsv), so we label this file as the raw input
			# here and emit the "Appended to" line after the merge completes.
			$_rollupActive = ($Rollup -or $RollupPlusRaw)
			if ($AppendFile -and -not $_rollupActive) {
				$_afDisplay2 = if ($script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) { $script:AppendRaw['Purview'] } else { $AppendFile }
				Write-LogHost "Appended to: $_afDisplay2" -ForegroundColor White
			} elseif ($AppendFile -and $_rollupActive) {
				Write-LogHost "Raw Purview CSV: $(Get-DisplayPath -LocalPath $OutputFile)" -ForegroundColor White
			} else {
				Write-LogHost "Output file: $(Get-DisplayPath -LocalPath $OutputFile)" -ForegroundColor White
			}
			if ($IncludeUserInfo -and -not $UseEOM) {
				# Honor -OutputPathUserInfo when bound; otherwise inherit $OutputFile's parent.
				$_uiDtE2 = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename (& $script:GetEffectiveEntraBasename)
				$entraCombined = if ($_uiDtE2 -and $_uiDtE2.IsBound -and $_uiDtE2.Tier -eq 'Local') { Join-Path $_uiDtE2.EffectiveDir $_uiDtE2.Basename }
					elseif ($_uiDtE2 -and $_uiDtE2.IsBound) { $_uiDtE2.EffectiveDir.TrimEnd('/') + '/' + $_uiDtE2.Basename }
					else { Join-Path (Split-Path $OutputFile -Parent) (& $script:GetEffectiveEntraBasename) }
				$_entraCombinedDisplay = if ($_uiDtE2 -and $_uiDtE2.IsBound -and $_uiDtE2.Tier -ne 'Local') { $entraCombined } else { Get-DisplayPath -LocalPath $entraCombined }
				if ($AppendUserInfo -and -not $_rollupActive) {
					$_auiDisplay2 = if ($script:AppendRaw.ContainsKey('UserInfo') -and $script:AppendRaw['UserInfo']) { $script:AppendRaw['UserInfo'] } else { $AppendUserInfo }
					Write-LogHost "Entra Users File: appended to $_auiDisplay2" -ForegroundColor Gray
				} elseif ($AppendUserInfo -and $_rollupActive) {
					Write-LogHost "Raw Entra Users CSV: $_entraCombinedDisplay" -ForegroundColor Gray
				} else {
					# Test-Path is only meaningful for local tiers; for remote tiers the writer
					# has already pushed the artifact and we just surface the destination.
					$_entraCombinedLocalExists = ($_uiDtE2 -and $_uiDtE2.IsBound -and $_uiDtE2.Tier -ne 'Local') -or (Test-Path $entraCombined)
					if ($_entraCombinedLocalExists) { Write-LogHost "Entra Users File: $_entraCombinedDisplay" -ForegroundColor Gray }
					else { Write-LogHost "Entra Users File: $_entraCombinedDisplay (pending)" -ForegroundColor Gray }
				}
			}
		} else {
			$_rollupActive2 = ($Rollup -or $RollupPlusRaw)
			if ($AppendFile -and -not $_rollupActive2) {
				$_afDisplay3 = if ($script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) { $script:AppendRaw['Purview'] } else { $AppendFile }
				Write-LogHost "Appended to: $_afDisplay3" -ForegroundColor White
			} elseif ($AppendFile -and $_rollupActive2) {
				Write-LogHost "Raw Purview CSV: $(Get-DisplayPath -LocalPath $OutputFile) (pending generation)" -ForegroundColor White
			} else {
				Write-LogHost "Output file: $(Get-DisplayPath -LocalPath $OutputFile)" -ForegroundColor White
			}
			if ($IncludeUserInfo -and -not $UseEOM) {
				# Honor -OutputPathUserInfo when bound; otherwise inherit $OutputFile's parent.
				$_uiDtE3 = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename (& $script:GetEffectiveEntraBasename)
				$entraCombined = if ($_uiDtE3 -and $_uiDtE3.IsBound -and $_uiDtE3.Tier -eq 'Local') { Join-Path $_uiDtE3.EffectiveDir $_uiDtE3.Basename }
					elseif ($_uiDtE3 -and $_uiDtE3.IsBound) { $_uiDtE3.EffectiveDir.TrimEnd('/') + '/' + $_uiDtE3.Basename }
					else { Join-Path (Split-Path $OutputFile -Parent) (& $script:GetEffectiveEntraBasename) }
				$_entraCombinedDisplay3 = if ($_uiDtE3 -and $_uiDtE3.IsBound -and $_uiDtE3.Tier -ne 'Local') { $entraCombined } else { Get-DisplayPath -LocalPath $entraCombined }
				if ($AppendUserInfo -and -not $_rollupActive2) {
					$_auiDisplay3 = if ($script:AppendRaw.ContainsKey('UserInfo') -and $script:AppendRaw['UserInfo']) { $script:AppendRaw['UserInfo'] } else { $AppendUserInfo }
					Write-LogHost "Entra Users File: appended to $_auiDisplay3" -ForegroundColor Gray
				} elseif ($AppendUserInfo -and $_rollupActive2) {
					Write-LogHost "Raw Entra Users CSV: $_entraCombinedDisplay3 (pending generation)" -ForegroundColor Gray
				} else {
					Write-LogHost "Entra Users File: $_entraCombinedDisplay3 (pending)" -ForegroundColor Gray
				}
			}
		}

		# Emit header-only CSV for combined mode when zero rows exported
		# Use the metric directly in case $totalExported wasn't set (resume mode with no new fetches)
		# AppendFile (non-rollup) guard: $OutputFile is the AppendFile target itself in
		# that mode, so emitting a header-only CSV here would overwrite the user's existing
		# fact file. Skip in that case — "0 new records" means leave the target unchanged.
		if ($CombineOutput -and -not $ExportWorkbook -and ([int]$script:metrics.TotalStructuredRows -eq 0) -and -not ($AppendFile -and -not ($Rollup -or $RollupPlusRaw))) {
			try {
				$headerColumns = if ($ExplodeDeep -or $ExplodeArrays -or $ForcedRawInputCsvExplosion) { $PurviewExplodedHeader } else { @('RecordId', 'CreationDate', 'RecordType', 'Operation', 'UserId', 'AuditData', 'AssociatedAdminUnits', 'AssociatedAdminUnitsNames') }
				$outputDirEmpty = Split-Path $OutputFile -Parent
				if (-not (Test-Path $outputDirEmpty)) { New-Item -ItemType Directory -Path $outputDirEmpty -Force | Out-Null }
				$enc = New-Object System.Text.UTF8Encoding($false)
				$sw = [System.IO.StreamWriter]::new($OutputFile, $false, $enc)
				# Always-quote columns to match the quoted-everywhere shape Export-Csv produces
				# in the data path (header is byte-shape identical to a populated CSV's header).
				$escapedCols = @()
				foreach ($col in $headerColumns) {
					$c = [string]$col
					$escapedCols += , ('"' + ($c -replace '"', '""') + '"')
				}
				$sw.WriteLine(($escapedCols -join ','))
				$sw.Flush(); $sw.Dispose()
				Write-LogHost "Header-only CSV created at: $(Get-DisplayPath -LocalPath $OutputFile)" -ForegroundColor Green
			} catch {
				Write-LogHost "Failed to write header-only CSV for ${OutputFile}: $($_.Exception.Message)" -ForegroundColor Red
			}
		}

		# Emit header-only CSVs for per-activity split when zero rows exported
		# Use the metric directly in case $totalExported wasn't set (resume mode with no new fetches)
		# AppendFile (non-rollup) guard: skip in that mode — the user's AppendFile target
		# lives in this directory and we don't want to scatter spurious empty per-activity
		# CSVs beside it for a 0-new-records run.
		if (-not $CombineOutput -and -not $ExportWorkbook -and ([int]$script:metrics.TotalStructuredRows -eq 0) -and $ActivityTypes -and -not ($AppendFile -and -not ($Rollup -or $RollupPlusRaw))) {
			try {
				$outputDir = Split-Path $OutputFile -Parent
				$timestamp = [System.IO.Path]::GetFileNameWithoutExtension($OutputFile) -replace '.*_(\d{8}_\d{6}).*', '$1'
				$headerColumns = if ($ExplodeDeep -or $ExplodeArrays -or $ForcedRawInputCsvExplosion) { $PurviewExplodedHeader } else { @('RecordId', 'CreationDate', 'RecordType', 'Operation', 'UserId', 'AuditData', 'AssociatedAdminUnits', 'AssociatedAdminUnitsNames') }
				foreach ($actType in $ActivityTypes) {
					$file = Join-Path $outputDir ("Purview_Audit_UsageActivity_{0}_{1}.csv" -f $actType, $timestamp)
					try {
						$outputDirEmpty = Split-Path $file -Parent
						if (-not (Test-Path $outputDirEmpty)) { New-Item -ItemType Directory -Path $outputDirEmpty -Force | Out-Null }
						$enc = New-Object System.Text.UTF8Encoding($false)
						$sw = [System.IO.StreamWriter]::new($file, $false, $enc)
						# Always-quote columns to match the quoted-everywhere shape Export-Csv produces
						# in the data path (header is byte-shape identical to a populated CSV's header).
						$escapedCols = @()
						foreach ($col in $headerColumns) {
							$c = [string]$col
							$escapedCols += , ('"' + ($c -replace '"', '""') + '"')
						}
						$sw.WriteLine(($escapedCols -join ','))
						$sw.Flush(); $sw.Dispose()
						Write-LogHost "Header-only CSV created at: $(Get-DisplayPath -LocalPath $file)" -ForegroundColor Green
					} catch {
						Write-LogHost "Failed to write header-only CSV for ${file}: $($_.Exception.Message)" -ForegroundColor Red
					}
				}
			} catch {
				Write-LogHost "Failed to emit per-activity header-only CSVs: $($_.Exception.Message)" -ForegroundColor Red
			}
		}
	} elseif ($OnlyUserInfo) {
		# -OnlyUserInfo mode: Show only EntraUsers file
		# Honor -OutputPathUserInfo when bound; otherwise inherit $OutputFile's parent.
		$_uiDtE4 = script:Resolve-DataTypePaths -DataType 'UserInfo' -DefaultBasename (& $script:GetEffectiveEntraBasename)
		$entraFile = if ($_uiDtE4 -and $_uiDtE4.IsBound -and $_uiDtE4.Tier -eq 'Local') { Join-Path $_uiDtE4.EffectiveDir $_uiDtE4.Basename }
			elseif ($_uiDtE4 -and $_uiDtE4.IsBound) { $_uiDtE4.EffectiveDir.TrimEnd('/') + '/' + $_uiDtE4.Basename }
			else { Join-Path (Split-Path $OutputFile -Parent) (& $script:GetEffectiveEntraBasename) }
		$_entraFileDisplay = if ($_uiDtE4 -and $_uiDtE4.IsBound -and $_uiDtE4.Tier -ne 'Local') { $entraFile } else { Get-DisplayPath -LocalPath $entraFile }
		if ($_uiDtE4 -and $_uiDtE4.IsBound -and $_uiDtE4.Tier -ne 'Local') {
			# Remote tier: writer has already pushed the artifact; surface the destination.
			Write-LogHost "EntraUsers file: $_entraFileDisplay" -ForegroundColor White
		} elseif (Test-Path $entraFile) {
			$entraSize = [math]::Round((Get-Item $entraFile).Length / 1KB, 2)
			Write-LogHost "EntraUsers file: $_entraFileDisplay" -ForegroundColor White
			Write-LogHost "File size: $entraSize KB" -ForegroundColor White
		} elseif ($script:EntraUsersFetchFailed) {
			# Option C: a genuine directory fetch failure must be loud, not a soft note.
			Write-LogHost "EntraUsers file: $_entraFileDisplay (NOT GENERATED)" -ForegroundColor Red
			Write-LogHost "ERROR: Entra user directory fetch failed: $script:EntraUsersFetchError" -ForegroundColor Red
		} else {
			Write-LogHost "EntraUsers file: $_entraFileDisplay (not found)" -ForegroundColor Yellow
		}
	} else {
		# -OnlyAgent365Info mode: Agent 365 file path is printed by the Agent 365 phase block below
		Write-LogHost "Mode: OnlyAgent365Info (Agent 365 file path shown below)" -ForegroundColor Cyan
	}
	
	# === Microsoft Agent 365 enrichment phase (-IncludeAgent365Info / -OnlyAgent365Info) ===
	# The interactive sign-in (when -Auth AppRegistration) is performed UP-FRONT by
	# Invoke-Agent365EarlyInteractiveSignIn so the audit phase runs unattended. Phase 2
	# here just emits the file using the cached delegated context.
	if ($IncludeAgent365Info -or $OnlyAgent365Info) {
		try {
			$agentResult = Invoke-Agent365Phase
			if ($agentResult -and $agentResult.Rows -and $agentResult.Rows.Count -gt 0) {
				if ($ExportWorkbook -and $OutputFile -and (Test-Path $OutputFile -ErrorAction SilentlyContinue)) {
					Add-Agent365WorkbookTab -WorkbookPath $OutputFile -Rows $agentResult.Rows
				}
				if ($agentResult.CsvPath) {
					Write-LogHost ("Agent 365 file: {0}" -f (Get-DisplayPath -LocalPath $agentResult.CsvPath)) -ForegroundColor White
					# Register the Agent 365 catalog CSV for the remote upload sweep. It is the only
					# customer-facing artifact that otherwise relies solely on the run-timestamp
					# wildcard; when -OutputPathAgent365Info supplies a file-form (non-timestamped)
					# leaf the wildcard misses it and the file is generated but never uploaded (then
					# deleted at scratch cleanup). Register explicitly — exactly like the rolled-up
					# Users dim / M365 sidecars — so the sweep ships it and a genuine upload failure
					# trips the retention guard. Included via the same OR predicate, so a timestamped
					# leaf is still swept exactly once.
					if ($script:RemoteOutputMode -ne 'None') {
						$agent365UploadLeaf = [System.IO.Path]::GetFileName($agentResult.CsvPath)
						if (-not $script:Agent365UploadLeafs) { $script:Agent365UploadLeafs = New-Object System.Collections.Generic.List[string] }
						if ($agent365UploadLeaf -and -not $script:Agent365UploadLeafs.Contains($agent365UploadLeaf)) {
							[void]$script:Agent365UploadLeafs.Add($agent365UploadLeaf)
							Write-LogHost ("Agent 365 CSV registered for upload: {0}" -f (Get-DisplayPath -LocalPath $agentResult.CsvPath)) -ForegroundColor Gray
						}
					}
				}
			}
		} catch {
			Write-LogHost ("WARNING: Agent 365 phase failed: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
		}
	}
	
	Write-LogHost "Log file: $(Get-DisplayPath -LocalPath $LogFile)" -ForegroundColor White
	
	# Mark script as completed normally (used by finally block to detect Ctrl+C)
	$script:ScriptCompleted = $true

	# ============================================================
	# DEIDENTIFY — non-rollup RAW outputs
	# Plain non-rollup run: the raw CSV(s) ARE the final output, so scrub them here
	# (before upload, which happens after the rollup block). Rollup paths are handled
	# inside the rollup block (rollup output via --deidentify; retained raw post-success).
	# ============================================================
	if ($script:PaxDeidEnabled -and -not ($Rollup -or $RollupPlusRaw) -and -not $ExportWorkbook) {
		try {
			$deidDir = Split-Path $OutputFile -Parent
			$deidTargets = New-Object System.Collections.Generic.List[string]
			if ($script:CsvSplitFiles -and $script:CsvSplitFiles.Count -gt 0) {
				foreach ($f in $script:CsvSplitFiles) { if (Test-Path -LiteralPath $f) { [void]$deidTargets.Add($f) } }
			}
			elseif (Test-Path -LiteralPath $OutputFile) {
				[void]$deidTargets.Add($OutputFile)
			}
			elseif ($deidDir -and (Test-Path -LiteralPath $deidDir)) {
				# $OutputFile may have been renamed by the single-activity downgrade.
				Get-ChildItem -LiteralPath $deidDir -Filter "Purview_Audit_*_${global:ScriptRunTimestamp}.csv" -File -ErrorAction SilentlyContinue |
					Where-Object { $_.Name -notlike 'EntraUsers_*' -and $_.Name -notlike 'Agent365_*' } |
					ForEach-Object { [void]$deidTargets.Add($_.FullName) }
			}
			if (($IncludeUserInfo -or $OnlyUserInfo) -and $deidDir) {
				$deidEntra = Join-Path $deidDir (& $script:GetEffectiveEntraBasename)
				if (Test-Path -LiteralPath $deidEntra) { [void]$deidTargets.Add($deidEntra) }
			}
			if ($deidTargets.Count -gt 0) {
				Write-LogHost ("DEIDENTIFY: scrubbing {0} raw output file(s)..." -f $deidTargets.Count) -ForegroundColor Cyan
				foreach ($t in $deidTargets) { Invoke-PaxRawDeidentify -Path $t }
				Write-LogHost "DEIDENTIFY: raw output deidentification complete." -ForegroundColor Green
			}
		}
		catch {
			Write-LogHost ("WARNING: -Deidentify raw scrub error (non-fatal): {0}" -f $_.Exception.Message) -ForegroundColor Yellow
		}
	}

	# ============================================================
	# ROLLUP POST-PROCESSOR WIRE-UP
	# ------------------------------------------------------------
	# Runs only when:
	#   - User passed -Rollup or -RollupPlusRaw (or restored from checkpoint on resume),
	#   - The audit run completed successfully (no Ctrl+C, no early exit, ScriptCompleted),
	#   - $script:RollupProcessorMode resolved to a real processor (gated up-front).
	#
	# Failure semantics: the embedded post-processor is best-effort. A non-zero exit code
	# logs an error and KEEPS raw outputs (regardless of -Rollup vs -RollupPlusRaw). It does
	# NOT throw past this point and does NOT mark the audit run as failed — the raw CSVs
	# already on disk are the canonical successful output.
	# ============================================================
	if ($script:RollupProcessorMode -and $script:RollupProcessorMode -in @('CopilotInteraction','M365Bundle') `
		-and $script:ScriptCompleted -and -not $script:CtrlCPressed -and -not $script:EarlyExit) {

		$rollupSuccess = $false
		$rollupOutputDir = Split-Path $OutputFile -Parent
		$rollupIncDir = Join-Path $rollupOutputDir ".pax_incremental"
		$rollupSwitchUsed = if ($Rollup) { '-Rollup' } else { '-RollupPlusRaw' }

		Write-LogHost ""
		Write-LogHost "═══════════════════════════════════════════════════════" -ForegroundColor Cyan
		Write-LogHost "  ROLLUP POST-PROCESSOR ($rollupSwitchUsed) — mode: $script:RollupProcessorMode" -ForegroundColor Cyan
		Write-LogHost "═══════════════════════════════════════════════════════" -ForegroundColor Cyan

		try {
			# 1. Resolve Python interpreter (auto-installs 3.13 via winget/python.org if missing).
			$pyResolved = Resolve-PythonExe -AllowAutoInstall
			$pyDisplay = if ($pyResolved.Args -and $pyResolved.Args.Count -gt 0) { "$($pyResolved.Path) $($pyResolved.Args -join ' ')" } else { $pyResolved.Path }
			Write-LogHost "Rollup: using Python $($pyResolved.Version) at '$pyDisplay'" -ForegroundColor Gray

			# 2. Best-effort orjson install (processors fall back to stdlib json on import failure).
			Write-PaxRollupReaderMode
			[void](Install-OrjsonIfMissing -PythonExe $pyResolved.Path -LauncherArgs $pyResolved.Args)

			# 3. Build processor-specific argument vector.
			Write-PaxRollupStage -Stage 'args-build' -Status 'entry'
			$rollupArgs = $null
			$rollupRawCsvList = New-Object System.Collections.Generic.List[string]
			# Internal-input deletion list: files consumed only as join inputs by the
			# rollup processor (e.g. the Entra users CSV for CopilotInteraction). These
			# are deleted under -Rollup and retained under -RollupPlusRaw. Population
			# is processor-specific below.
			$rollupAlwaysDeleteList = New-Object System.Collections.Generic.List[string]
			# Extra-retained list: files that exist on disk and are NEVER deleted by the
			# rollup retention logic but should still be surfaced in the post-rollup
			# summary so the user can see every file produced by the run. Examples:
			# the Entra users CSV under -RollupPlusRaw (CopilotInteraction) or under
			# -IncludeUserInfo (M365Bundle, where the processor doesn't consume it).
			$rollupRetainedExtraList = New-Object System.Collections.Generic.List[string]

			# Resolve the actual Purview CSV path. $OutputFile may have been renamed by the
			# single-activity downgrade (Purview_Audit_UsageActivity_<ActivityType>_<ts>.csv). If the path
			# at $OutputFile does not exist, fall back to a timestamp-scoped glob in the
			# output dir (excluding EntraUsers and Agent365 companion CSVs).
			$rollupPurviewCsv = $OutputFile
			if (-not (Test-Path -LiteralPath $rollupPurviewCsv)) {
				$rollupCandidates = Get-ChildItem -LiteralPath $rollupOutputDir -Filter "Purview_Audit_*_${global:ScriptRunTimestamp}.csv" -File -ErrorAction SilentlyContinue |
					Where-Object { $_.Name -notlike 'EntraUsers_*' -and $_.Name -notlike 'Agent365_*' }
				if ($rollupCandidates -and $rollupCandidates.Count -eq 1) {
					$rollupPurviewCsv = $rollupCandidates[0].FullName
					Write-LogHost "Rollup: resolved Purview CSV via timestamp glob: $(Get-DisplayPath -LocalPath $rollupPurviewCsv)" -ForegroundColor Gray
				}
				elseif ($rollupCandidates -and $rollupCandidates.Count -gt 1) {
					throw "Rollup: multiple candidate Purview CSVs found for timestamp ${global:ScriptRunTimestamp} in '$rollupOutputDir'. Re-run with -CombineOutput to produce a single combined CSV."
				}
			}

			if ($script:RollupProcessorMode -eq 'M365Bundle') {
				if (-not (Test-Path -LiteralPath $rollupPurviewCsv)) {
					throw "Rollup: expected combined Purview CSV not found at '$rollupPurviewCsv'."
				}
				$rollupArgs = @('--input', $rollupPurviewCsv, '--output-dir', $rollupOutputDir)
				$rollupRawCsvList.Add($rollupPurviewCsv)
				# The M365Bundle processor does NOT consume the Entra users CSV. When
				# -IncludeUserInfo produced one, it is always retained — surface it in
				# the post-rollup summary so the user sees it alongside the rollup output.
				if ($IncludeUserInfo) {
					$rollupEntraCsvM365 = Join-Path $rollupOutputDir (& $script:GetEffectiveEntraBasename)
					if (Test-Path -LiteralPath $rollupEntraCsvM365) {
						$rollupRetainedExtraList.Add($rollupEntraCsvM365)
					}
				}
			}
			elseif ($script:RollupProcessorMode -eq 'CopilotInteraction') {
				if (-not (Test-Path -LiteralPath $rollupPurviewCsv)) {
					throw "Rollup: expected Purview CSV not found at '$rollupPurviewCsv'."
				}
				# Resolve the Entra users CSV to the AUTHORITATIVE local path actually emitted this run (honors a
				# separate -OutputPathUserInfo destination, the effective basename, and any pristine-raw '_raw'
				# suffix). Only fall back to the Purview output directory when no emitted local path was captured
				# (e.g. a flat layout where UserInfo and Purview resolve to the same folder, or a remote run whose
				# local staging equals the rollup dir). NEVER infer the customer UserInfo destination from the
				# rollup/Purview output location.
				$rollupEntraCsv = if ($script:RollupEntraLocalPath -and (Test-Path -LiteralPath $script:RollupEntraLocalPath -PathType Leaf)) {
					$script:RollupEntraLocalPath
				} else {
					Join-Path $rollupOutputDir (& $script:GetEffectiveEntraBasename)
				}
				if (-not (Test-Path -LiteralPath $rollupEntraCsv)) {
					throw "Rollup: required Entra users CSV not found at '$rollupEntraCsv'. -IncludeUserInfo must produce a CSV (not a workbook tab)."
				}
				$rollupEntraInfo = Get-Item -LiteralPath $rollupEntraCsv
				if ($rollupEntraInfo.Length -le 0) {
					throw "Rollup: Entra users CSV at '$rollupEntraCsv' is empty (0 bytes)."
				}
				# Dashboard profile (aio|aibv) selects the embedded output schema;
				# resolved in the rollup-mode decision (default aio). --combined-entra is
				# passed explicitly because PAX always emits a single combined
				# users+licensing Entra CSV (the processor's 2-input path); the separate
				# -licensing 3-file path is never used from PAX.
				$rollupProfile = if ($script:RollupDashboardProfile) { $script:RollupDashboardProfile } else { 'aio' }
				$rollupArgs = @('--purview', $rollupPurviewCsv, '--entra', $rollupEntraCsv, '--out-dir', $rollupOutputDir, '--profile', $rollupProfile, '--combined-entra')
				# -FillerLabel: org-hierarchy level-filler for the AIO/AIBV Users dim (default
				# 'none' = blanks). Only the CopilotInteraction processor builds the hierarchy.
				$rollupArgs += @('--hierarchy-fill', $script:HierarchyFillMode)
				if ($script:HierarchyFillMode -eq 'fixed') {
					$rollupArgs += @('--hierarchy-fill-label', $script:HierarchyFillLabel)
				}
				$rollupRawCsvList.Add($rollupPurviewCsv)
				# EntraUsers CSV is an internal join input to the CopilotInteraction processor.
				# Under -Rollup it is deleted alongside the raw Purview CSV. Under -RollupPlusRaw
				# the user has explicitly opted to retain raw inputs, so keep the Entra CSV too
				# and surface it in the retained-summary block.
				if (-not $RollupPlusRaw) {
					$rollupAlwaysDeleteList.Add($rollupEntraCsv)
				}
				else {
					$rollupRetainedExtraList.Add($rollupEntraCsv)
				}

				# Append publication state. Both append targets describe one set of people, so
				# each union is built to a candidate path and nothing replaces an existing
				# target until the joint referential-integrity gate has passed.
				$script:PaxAuditOnlyUsersCsv = $null
				$script:PaxAuditOnlyUsersWorkFile = $null
				$script:PaxUserKeyContinuityFailed = $false
				$script:PaxUsersCandidatePath = $null
				$script:PaxUsersCandidateFinal = $null
				$script:PaxUsersTransientCsv = $null
				$script:PaxFactCandidatePath = $null
				$script:PaxFactCandidateFinal = $null
				$script:PaxFactTransientCsv = $null

				# -AppendUserInfo: seed the embedded processor with the continuity map taken
				# from the existing targets so retained users keep their stable integer keys
				# across runs. Continuity is derived from BOTH targets, because a user who
				# only ever appears in activity data has no directory row and would otherwise
				# have no key reserved at all.
				if ($AppendUserInfo -or $AppendFile) {
					# Continuity is prepared for whichever append target(s) the run requested.
					$ukSeedLabel  = if ($AppendUserInfo) { '-AppendUserInfo' } else { '-AppendFile' }
					$ukSeedTarget = if ($AppendUserInfo) { $AppendUserInfo } else { $AppendFile }
					$ukSeedRawKey = if ($AppendUserInfo) { 'UserInfo' } else { 'Purview' }
					$rollupUserInfoSeedJson = Join-Path $rollupIncDir "PAX_AppendUserInfo_seed_${global:ScriptRunTimestamp}.json"
					$rollupUserInfoAuditOnlyCsv = Join-Path $rollupIncDir "PAX_AppendUserInfo_auditonly_${global:ScriptRunTimestamp}.csv"
					Write-PaxRollupStage -Stage 'users-seed' -Status 'entry'
					try {
						# Observability-only heartbeat for a seed preparation that can run a long time.
						# The stage name and EVERY counter key are literal at this call site, so the
						# counter-name channel is closed by inspection: no key, row, field, file name,
						# path, URL, package identifier, user principal name, tenant or account
						# identifier, or credential can reach a record. Only AGGREGATE numeric values
						# are read from the snapshot, and any failure here is swallowed so a logging
						# problem can never alter seed output, counts, ordering, or the run result.
						$rollupUserInfoSeedProgress = {
							param($Snapshot)
							try {
								if ($null -eq $Snapshot) { return }
								Write-PaxRollupStage -Stage 'users-seed' -Status 'heartbeat' -Counters @{
									rowsRead       = [int64]$Snapshot.RowsRead
									rowsWritten    = [int64]$Snapshot.RowsWritten
									runCount       = [int64]$Snapshot.RunCount
									mergePassCount = [int64]$Snapshot.MergePassCount
									maxOpenReaders = [int64]$Snapshot.MaxOpenReaders
									temporaryBytes = [int64]$Snapshot.TempBytesWritten
									elapsedSeconds = [double]$Snapshot.ElapsedSeconds
								}
							}
							catch { }
						}
						$rollupUserInfoContinuity = ConvertTo-PaxUserKeyContinuity -TargetUsersCsv $AppendUserInfo -TargetFactCsv $AppendFile -OutJsonPath $rollupUserInfoSeedJson -OutAuditOnlyCsvPath $rollupUserInfoAuditOnlyCsv -ProgressCallback $rollupUserInfoSeedProgress -ProgressIntervalSeconds $StatusIntervalSeconds
						$rollupUserInfoSeedCount = [int]$rollupUserInfoContinuity.SeededKeys
						$script:PaxAuditOnlyUsersCsv = $rollupUserInfoAuditOnlyCsv
						if ($rollupUserInfoContinuity.AuditOnlyIdentities -gt 0 -and $AppendUserInfo) {
							Write-LogHost ("Rollup: -AppendUserInfo: {0:N0} user(s) appear only in prior activity; their existing keys are reserved and each receives a minimal Users row." -f $rollupUserInfoContinuity.AuditOnlyIdentities) -ForegroundColor DarkCyan
						}
						# Differentiate seed outcomes so zero-count is not
						# silently glossed as "seeded 0" (which reads like a success line).
						# In remote-output mode $AppendUserInfo has already been redirected to a
						# scratch path whose leaf carries the '.pax_appendseed_UserInfo_' prefix;
						# Get-DisplayPath would then synthesize a phantom remote URL (folder +
						# scratch leaf) that does not exist on the destination. Surface the
						# canonical customer-supplied URL from $script:AppendRaw['UserInfo']
						# when available.
						$auiDisplayPath = if ($script:AppendRaw.ContainsKey($ukSeedRawKey) -and $script:AppendRaw[$ukSeedRawKey]) { $script:AppendRaw[$ukSeedRawKey] } else { Get-DisplayPath -LocalPath $ukSeedTarget }
						if ($rollupUserInfoSeedCount -gt 0) {
							Write-LogHost ("Rollup: {0}: seeded {1:N0} retained UserKey(s)" -f $ukSeedLabel, $rollupUserInfoSeedCount) -ForegroundColor DarkCyan
							Write-LogHost ("  from: {0}" -f $auiDisplayPath) -ForegroundColor DarkCyan
						} elseif (-not (Test-Path -LiteralPath $ukSeedTarget -PathType Leaf)) {
							Write-LogHost ("Rollup: {0}: target not found; no UserKeys to seed (new keys will be minted)." -f $ukSeedLabel) -ForegroundColor Yellow
							Write-LogHost ("  from: {0}" -f $auiDisplayPath) -ForegroundColor Yellow
						} else {
							Write-LogHost ("Rollup: {0}: target exists but contains no retainable UserKeys (header-only or unrecognized schema); new keys will be minted." -f $ukSeedLabel) -ForegroundColor Yellow
							Write-LogHost ("  from: {0}" -f $auiDisplayPath) -ForegroundColor Yellow
						}
						$rollupArgs += @('--seed-userkey-map', $rollupUserInfoSeedJson)
						Write-PaxRollupStage -Stage 'users-seed' -Status 'complete' -Counters @{ seededKeys = [int64]$rollupUserInfoSeedCount }
					}
					catch {
						# Fail closed. Minting fresh keys over a target that already has its own is
						# exactly how one key ends up shared between two people, so neither append
						# target is touched this run and the run reports completed with gaps.
						$script:PaxUserKeyContinuityFailed = $true
						$script:HadTerminalFailures = $true
						Write-LogHost ("Rollup: {0}: user key continuity could not be established: {1}" -f $ukSeedLabel, $_.Exception.Message) -ForegroundColor Red
						Write-LogHost  "Rollup:   -> Neither append target is updated this run (completed with gaps, exit 40); this run's output is preserved for review." -ForegroundColor Red
						Write-PaxRollupStage -Stage 'users-seed' -Status 'failed'
					}
				}

				# -AppendFile (CopilotInteraction rollup): seed the embedded processor with
				# {Message_Id_Raw -> Message_Id} and {ThreadId_Raw -> ThreadKey} maps from the
				# target Fact CSV so cross-run rows keep their stable INT surrogates and source
				# rows already present in the target are deduped on Message_Id_Raw. Failure to
				# prepare the seeds is non-fatal — the processor will mint fresh INTs and the
				# downstream union will still be correct, though target rows may receive new
				# surrogate values.
				if ($AppendFile) {
					if (Test-Path -LiteralPath $AppendFile -PathType Leaf) {
						# Advisory: for a genuinely-local append target (remote targets are probed
						# before download) warn if it is large enough that the in-memory merge could
						# strain RAM. Fail-open, non-blocking.
						if (-not $script:AppendRemoteOriginal) {
							$localAppendSizeWarning = Get-AppendTargetSizeWarning -SizeBytes (Get-RemoteAppendTargetSize -Tier 'Local' -Path $AppendFile) -ThresholdBytes $script:AppendTargetSizeWarnBytes -Label (Get-DisplayPath -LocalPath $AppendFile)
							if ($localAppendSizeWarning) { Write-LogHost $localAppendSizeWarning -ForegroundColor Yellow }
						}
						$rollupMidSeedJson    = Join-Path $rollupIncDir "PAX_AppendFile_midseed_${global:ScriptRunTimestamp}.json"
						$rollupThreadSeedJson = Join-Path $rollupIncDir "PAX_AppendFile_threadseed_${global:ScriptRunTimestamp}.json"
						Write-PaxRollupStage -Stage 'fact-seed' -Status 'entry'
						try {
							# Observability-only heartbeat for a seed preparation that can run a long time.
							# The stage name and EVERY counter key are literal at this call site, so the
							# counter-name channel is closed by inspection: no key, row, field, file name,
							# path, URL, package identifier, user principal name, tenant or account
							# identifier, or credential can reach a record. Only AGGREGATE numeric values
							# are read from the snapshot, and any failure here is swallowed so a logging
							# problem can never alter seed output, counts, ordering, or the run result.
							$rollupFactSeedProgress = {
								param($Snapshot)
								try {
									if ($null -eq $Snapshot) { return }
									Write-PaxRollupStage -Stage 'fact-seed' -Status 'heartbeat' -Counters @{
										rowsRead       = [int64]$Snapshot.RowsRead
										rowsWritten    = [int64]$Snapshot.RowsWritten
										runCount       = [int64]$Snapshot.RunCount
										mergePassCount = [int64]$Snapshot.MergePassCount
										maxOpenReaders = [int64]$Snapshot.MaxOpenReaders
										temporaryBytes = [int64]$Snapshot.TempBytesWritten
										elapsedSeconds = [double]$Snapshot.ElapsedSeconds
									}
								}
								catch { }
							}
							# Prepare both seeds through the embedded disk-backed builder first: it
							# folds a large target far faster while keeping memory bounded. An
							# explicit compatibility outcome means the target holds a key form the
							# builder is not proven to serialize identically, so the accepted
							# implementation runs instead and produces the same seeds. Any other
							# accelerator outcome abandons seed preparation rather than silently
							# changing continuity.
							$rollupFactSeedAccel = Invoke-PaxFactSeedAccelerator -TargetFactCsv $AppendFile -OutMidJsonPath $rollupMidSeedJson -OutThreadJsonPath $rollupThreadSeedJson -PythonExe $pyResolved.Path -LauncherArgs $pyResolved.Args -ScriptDir $rollupIncDir -HeartbeatIntervalSeconds $StatusIntervalSeconds
							if ($rollupFactSeedAccel.Status -eq 'Success') {
								$rollupFactSeed = [PSCustomObject]@{ MidCount = $rollupFactSeedAccel.MidCount; ThreadCount = $rollupFactSeedAccel.ThreadCount }
							}
							elseif ($rollupFactSeedAccel.Status -eq 'CompatibilityFallbackRequired') {
								$rollupFactSeed = ConvertTo-FactSeedMaps -TargetFactCsv $AppendFile -OutMidJsonPath $rollupMidSeedJson -OutThreadJsonPath $rollupThreadSeedJson -ProgressCallback $rollupFactSeedProgress -ProgressIntervalSeconds $StatusIntervalSeconds
							}
							else {
								throw [System.InvalidOperationException]::new(("continuity seed preparation did not complete ({0})" -f $rollupFactSeedAccel.Reason))
							}
							# Differentiate populated vs empty target. Use the canonical customer-supplied
							# URL from $script:AppendRaw['Purview'] when available so remote-output runs
							# don't surface a scratch-leaf-derived URL if the scratch file's leaf ever
							# diverges from the remote leaf (parity with the AppendUserInfo seed display).
							$afDisplayPath = if ($script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) { $script:AppendRaw['Purview'] } else { Get-DisplayPath -LocalPath $AppendFile }
							if (($rollupFactSeed.MidCount -gt 0) -or ($rollupFactSeed.ThreadCount -gt 0)) {
								Write-LogHost ("Rollup: -AppendFile: seeded {0:N0} Message_Id and {1:N0} ThreadKey surrogate(s)" -f $rollupFactSeed.MidCount, $rollupFactSeed.ThreadCount) -ForegroundColor DarkCyan
								Write-LogHost ("  from: {0}" -f $afDisplayPath) -ForegroundColor DarkCyan
							} else {
								Write-LogHost ("Rollup: -AppendFile: no new seedable Message_Id/ThreadKey surrogates extracted from target (target may be header-only, contain only rows already represented in this run, or use an unrecognized schema); fresh surrogates will be minted as needed.") -ForegroundColor Yellow
								Write-LogHost ("  from: {0}" -f $afDisplayPath) -ForegroundColor Yellow
							}
							$rollupArgs += @('--seed-mid-map',    $rollupMidSeedJson)
							$rollupArgs += @('--seed-thread-map', $rollupThreadSeedJson)
							Write-PaxRollupStage -Stage 'fact-seed' -Status 'complete' -Counters @{ midKeys = [int64]$rollupFactSeed.MidCount; threadKeys = [int64]$rollupFactSeed.ThreadCount }
						}
						catch {
							Write-PaxRollupStage -Stage 'fact-seed' -Status 'failed'
							# Fail closed: the continuity seeds are required for correct cross-run
							# Message_Id / ThreadKey surrogate continuity. Continuing without them
							# would let the embedded processor mint fresh surrogates and silently
							# change continuity, so a seed-preparation failure aborts the rollup.
							# The existing append target and any prior seed artifacts are left
							# untouched, and the embedded processor is never invoked without seeds.
							$seedErr = $_
							Write-LogHost ("Rollup: -AppendFile continuity seed preparation failed: {0}" -f $seedErr.Exception.Message) -ForegroundColor Red
							throw [System.InvalidOperationException]::new(("Rollup aborted: -AppendFile continuity seed preparation failed; refusing to run the rollup without continuity seeds so Message_Id and thread continuity are never silently changed. Underlying error: {0}" -f $seedErr.Exception.Message), $seedErr.Exception)
						}
					}
					else {
						Write-LogHost ("Rollup: -AppendFile target '{0}' not found; rollup will produce a fresh Fact CSV (no seed)." -f (Get-DisplayPath -LocalPath $AppendFile)) -ForegroundColor Yellow
					}
				}
			}

			# -Deidentify: thread one-way hashing into the embedded processor so the rollup
			# output (the dashboard-ready artifact) is anonymized by Python. PowerShell scrubs
			# any retained RAW files separately (post-success Hook C below; non-rollup block above).
			# NOTE: only the FIRST invocation gets --deidentify. The M365 sidecar-rebuild pass
			# (further below) reads the already-hashed merged rollup, so it must NOT re-hash.
			if ($script:PaxDeidEnabled) { $rollupArgs += '--deidentify' }

			Write-PaxRollupStage -Stage 'args-build' -Status 'complete' -Counters @{ argumentCount = [int64]@($rollupArgs).Count }

			# 4. Invoke embedded processor (writes temp .py into .pax_incremental, deletes on exit).
			Write-PaxRollupStage -Stage 'processor' -Status 'entry'
			$rollupExit = Invoke-EmbeddedProcessor `
				-ProcessorMode  $script:RollupProcessorMode `
				-PythonExe      $pyResolved.Path `
				-LauncherArgs   $pyResolved.Args `
				-ProcessorArgs  $rollupArgs `
				-IncrementalDir $rollupIncDir
			$__rollupStageStatus = if ($rollupExit -eq 0) { 'complete' } else { 'failed' }
			Write-PaxRollupStage -Stage 'processor' -Status $__rollupStageStatus -Counters @{ exitCode = [int64]$rollupExit }

			if ($rollupExit -eq 0) {
				$rollupSuccess = $true
				Write-LogHost "Rollup: post-processor completed successfully (exit 0)." -ForegroundColor Green

				# D3: a "successful" CopilotInteraction processor MUST have produced BOTH required deliverables —
				# the rolled-up Fact (<purview_stem>_Interactions.csv) and Users dim (<entra_stem>_Users.csv).
				# Verify HERE, before any -AppendFile/-AppendUserInfo merge can consume or delete them. A missing
				# deliverable is a rollup-processor failure (consumed as a requested-output failure under
				# -Dashboard AISID); for non-AISID best-effort modes the flag is set but never read, so exit
				# semantics there are unchanged.
				if ($script:RollupProcessorMode -eq 'CopilotInteraction') {
					$__d3FactCsv  = Join-Path $rollupOutputDir ("{0}_Interactions.csv" -f [System.IO.Path]::GetFileNameWithoutExtension($rollupPurviewCsv))
					$__d3UsersCsv = Join-Path $rollupOutputDir ("{0}_Users.csv" -f [System.IO.Path]::GetFileNameWithoutExtension($rollupEntraCsv))
					if (-not (Test-Path -LiteralPath $__d3FactCsv -PathType Leaf)) {
						$script:RollupProcessorFailed = $true
						Write-LogHost ("Rollup: expected Fact CSV not produced at '{0}' despite processor exit 0 (requested-output failure)." -f (Get-DisplayPath -LocalPath $__d3FactCsv)) -ForegroundColor Red
					}
					if (-not (Test-Path -LiteralPath $__d3UsersCsv -PathType Leaf)) {
						$script:RollupProcessorFailed = $true
						Write-LogHost ("Rollup: expected Users dim CSV not produced at '{0}' despite processor exit 0 (requested-output failure)." -f (Get-DisplayPath -LocalPath $__d3UsersCsv)) -ForegroundColor Red
					}
				}

				# ============================================================
				# AISID DASHBOARD EXPORT (only under -Dashboard AISID)
				# Placed HERE — immediately after the CopilotInteraction rollup Fact CSV
				# (<purview_stem>_Interactions.csv) is written and BEFORE the -AppendFile
				# merge/delete below can consume it — so Get-AISIDCopilotUsage's source is
				# guaranteed present regardless of -AppendFile. This is the single, flag-
				# independent point where the Fact exists and no deletion has yet occurred.
				# Destination reuses the DefenderUsage path registry (consuming
				# -OutputPathDefenderUsage / -AppendDefenderUsage, else co-locating with the
				# Purview output folder). Failure is isolated inside Invoke-AISIDPilotExport.
				# This is what makes -Dashboard AISID customer-functional: the run reaches
				# here under -Dashboard AISID and produces the
				# twelve dashboard CSVs with per-table failure isolation and, under -Deidentify,
				# deidentification applied before merge.
				# ============================================================
				if ($Dashboard -eq 'AISID') {
					# Canonical per-run AISID folder — the twelve fixed-name CSVs publish into
					# 'AISID_<ScriptRunTimestamp>' beneath the DefenderUsage destination on EVERY tier
					# (Local / SharePoint / Fabric). One resolver drives the write dir, history-read parent,
					# completion check, upload target ($script:AISIDRemoteRunFolderUrl), roster registration,
					# and the run-specific scratch cleanup. The twelve filenames inside are never renamed.
					$aisidRun = script:Resolve-AISIDRunFolder
					$aisidRunLeaf  = $aisidRun.RunLeaf
					$aisidWriteDir = $aisidRun.WriteDir
					$script:AISIDRunFolder = $aisidRun
					$script:AISIDRemoteRunFolderUrl = $aisidRun.RemoteRunFolderUrl
					# Blocker-3: the AISID history-read source is SEPARATE from this run's fresh output folder.
					# Prior history is read ONLY from an explicitly supplied -AppendDefenderUsage prior bundle
					# (local folder or remote parent URL), never from Purview and never from the new timestamped
					# child. A plain -OutputPathDefenderUsage run reads NO prior history. The reconciled result
					# is written into the AISID_<ts> child; the prior bundle is only read and left untouched.
					$aisidHist = script:Resolve-AISIDHistorySource
					$aisidHistoryDir    = [string]$aisidHist.LocalDir
					$aisidHistoryParent = [string]$aisidHist.RemoteParentUrl

					# Collision-safe folder creation (items #3/#4/#5 + defects 1/2/3): any pre-existing EXACT run
					# folder is a collision — FAIL CLOSED (skip publication, mark an AISID gap -> exit 40, log the
					# exact folder, and NEVER delete or modify the existing folder). In remote mode EXCLUSIVE
					# ownership of the EXACT remote AISID_<ts> child folder is acquired by CREATING it atomically
					# (SharePoint POST /children conflictBehavior=fail; Fabric PUT ?resource=directory
					# If-None-Match:*): the create is authoritative, so a 409/conflict is a collision even if the
					# earlier read-only probe reported Absent, and any inaccessible lookup/create also fails closed.
					# The local publish/staging folder is acquired via an ATOMIC ownership marker (blocker-5,
					# FileMode.CreateNew in the parent) so two concurrent same-second runs cannot both proceed.
					$aisidBundleOk = $true
					$script:AISIDOwnershipMarker = ''
					$script:AISIDRemoteOwnershipAcquired = $false
					$__aisidCreateTarget = if ($script:RemoteOutputMode -ne 'None') { $aisidRun.RemoteScratchStaging } else { $aisidRun.LocalRunFolder }
					if ($aisidBundleOk -and $script:RemoteOutputMode -ne 'None' -and $aisidRun.RemoteRunFolderUrl) {
						$__remoteOwn = script:Acquire-AISIDRemoteRunFolderOwnership -Url $aisidRun.RemoteRunFolderUrl -Mode $script:RemoteOutputMode
						if ($__remoteOwn.Acquired) {
							$script:AISIDRemoteOwnershipAcquired = $true
							Write-LogHost ("[AISID] Remote run folder ownership acquired ({0}): {1}" -f $__remoteOwn.Mode, $aisidRun.RemoteRunFolderUrl) -ForegroundColor DarkGray
						}
						else {
							Write-LogHost ("[AISID] Remote run folder ownership NOT acquired ({0}: {1}) for {2}; refusing to upload (collision -> AISID gap). Existing remote content is left untouched." -f $__remoteOwn.State, $__remoteOwn.Reason, $aisidRun.RemoteRunFolderUrl) -ForegroundColor Yellow
							$script:AISIDHadGaps = $true; $script:AnyUploadFailed = $true; $aisidBundleOk = $false
						}
					}
					if ($aisidBundleOk) {
						$__aisidOwn = script:New-AISIDRunFolderOwnership -RunFolder $__aisidCreateTarget
						if ($__aisidOwn.Acquired) { $script:AISIDOwnershipMarker = [string]$__aisidOwn.MarkerPath }
						else {
							Write-LogHost ("[AISID] Run bundle folder ownership not acquired for {0} ({1}); refusing to reuse it (collision -> AISID gap). The existing folder is left untouched." -f $__aisidCreateTarget, $__aisidOwn.Reason) -ForegroundColor Yellow
							$script:AISIDHadGaps = $true; $aisidBundleOk = $false
						}
					}

					if ($aisidBundleOk) {
						$aisidResult = Invoke-AISIDPilotExport -DestinationDir $aisidWriteDir -ParentOverride $aisidHistoryParent -HistoryDir $aisidHistoryDir -DisableDeltaCache:$DisableAISIDDeltaCache -RawPurviewCsv $rollupPurviewCsv
						# A2 truthful completion: evaluate completeness FIRST (per-table state contract + twelve-file
						# check), then mark completed ONLY if every table reached a terminal state. Any gap sets
						# AISIDHadGaps -> exit 40 ("completed with gaps"); a failure is never a factual empty.
						$script:AISIDCompletionStatus = Get-AISIDCompletionStatus -Result $aisidResult -DestinationDir $aisidWriteDir
						if ($script:AISIDCompletionStatus.HadGaps) { $script:AISIDHadGaps = $true }
						if ($script:AISIDCompletionStatus.AllTablesTerminal) { $script:AISIDExportCompleted = $true }
						# Register the twelve fixed-name leaves + destination so the LOCAL roster lists all twelve
						# and the REMOTE upload sweep ships each exactly once to the per-run AISID_<ts> child URL
						# ($script:AISIDRemoteRunFolderUrl). The '.aisid_cache' delta-cache is never registered.
						$script:AISIDDestDir = $aisidWriteDir
						if (-not $script:AISIDUploadLeafs) { $script:AISIDUploadLeafs = New-Object System.Collections.Generic.List[string] }
						foreach ($aisidSchema in $script:AISIDTableSchemas.Values) {
							$aisidLeaf = $aisidSchema.FileName
							if ($aisidLeaf -and -not $script:AISIDUploadLeafs.Contains($aisidLeaf)) { [void]$script:AISIDUploadLeafs.Add($aisidLeaf) }
						}
						# Scratch/cache lifecycle (item #4): a successful run leaves NO cache or scratch. The
						# run-specific scratch root holds the OffHours cache and (remote) the staged twelve files.
						# In remote mode the staged files must survive until the end-of-run upload sweep, so the
						# scratch delete is DEFERRED to the sweep (via $script:AISIDScratchPendingCleanup). In
						# local mode only the cache lives there, so delete now and verify — a residual scratch
						# is a completed-with-gaps condition (exit 40).
						if (-not $script:RemoteOutputMode -or $script:RemoteOutputMode -eq 'None') {
							$__aisidScratch = script:Get-AISIDScratchRoot
							if (-not (script:Remove-AISIDScratchRoot -Root $__aisidScratch)) {
								Write-LogHost ("[AISID] Internal scratch could not be fully removed: {0}; flagging an AISID gap (exit 40)." -f $__aisidScratch) -ForegroundColor Yellow
								$script:AISIDHadGaps = $true
							}
						}
						else { $script:AISIDScratchPendingCleanup = script:Get-AISIDScratchRoot }
					}
				}

				# -RollupPlusRaw + -Deidentify: the embedded processor has consumed the
				# IDENTIFIED raw (and produced a deidentified rollup via --deidentify); now
				# scrub the RETAINED raw file(s) in place so the kept raw is anonymized too.
				# Tokens match the rollup (shared salt). Not run for plain -Rollup (raw deleted).
				if ($RollupPlusRaw -and $script:PaxDeidEnabled) {
					Write-LogHost "DEIDENTIFY: scrubbing retained raw file(s)..." -ForegroundColor Cyan
					Invoke-PaxRawDeidentify -Path $rollupPurviewCsv
					if ($script:RollupProcessorMode -eq 'CopilotInteraction' -and $rollupEntraCsv) { Invoke-PaxRawDeidentify -Path $rollupEntraCsv }
					if ($script:RollupProcessorMode -eq 'M365Bundle' -and $rollupEntraCsvM365) { Invoke-PaxRawDeidentify -Path $rollupEntraCsvM365 }
					Write-LogHost "DEIDENTIFY: retained raw deidentification complete." -ForegroundColor Green
				}

				# -AppendUserInfo: union-merge the target Users CSV with the just-produced
				# Users output. CopilotInteraction emits '<entra_stem>_Users.csv' beside the
				# Entra input. Failure here logs a warning but does NOT roll the rollup back
				# — the new Users file is still on disk and customer can merge manually.
				if ($AppendUserInfo -and $script:RollupProcessorMode -eq 'CopilotInteraction') {
					try {
						$rollupEntraStem = [System.IO.Path]::GetFileNameWithoutExtension($rollupEntraCsv)
						$rollupUsersCsv  = Join-Path $rollupOutputDir ("{0}_Users.csv" -f $rollupEntraStem)
						if (Test-Path -LiteralPath $rollupUsersCsv) {
							# Remote -AppendUserInfo lands in scratch under '.pax_appendseed_*'
							# (excluded from upload). Write the union to a non-seed scratch path
							# inheriting the target's original leaf so the upload sweep picks it up.
							$_rollupAuiMergeOut = if ($script:AppendIsRemote.ContainsKey('UserInfo') -and $script:AppendIsRemote['UserInfo'] -and $script:AppendRaw.ContainsKey('UserInfo') -and $script:AppendRaw['UserInfo']) {
								Join-Path $rollupOutputDir ([System.IO.Path]::GetFileName($script:AppendRaw['UserInfo']))
							} else { $AppendUserInfo }
							if ($script:PaxUserKeyContinuityFailed) {
								throw 'user key continuity was not established for this run'
							}
							# Every user in the activity data must resolve to a Users row, so a user
							# who appears only in activity and has no directory row this run receives
							# a minimal row carrying nothing but the identity and the key already
							# reserved for it. A real directory row always wins.
							$_rollupUsersForMerge = $rollupUsersCsv
							if ($script:PaxAuditOnlyUsersCsv -and (Test-Path -LiteralPath $script:PaxAuditOnlyUsersCsv -PathType Leaf)) {
								$_rollupUsersWithAudit = $rollupUsersCsv + '.withaudit'
								# Only a run that also appends the activity target can resolve keys
								# minted for a person seen for the first time in this run.
								$_rollupCurrentFactForUsers = $null
								if ($AppendFile) {
									$_rollupCurrentFactProbe = Join-Path $rollupOutputDir ("{0}_Interactions.csv" -f ([System.IO.Path]::GetFileNameWithoutExtension($rollupPurviewCsv)))
									if (Test-Path -LiteralPath $_rollupCurrentFactProbe -PathType Leaf) { $_rollupCurrentFactForUsers = $_rollupCurrentFactProbe }
								}
								$_rollupPlaceholderCount = Add-PaxAuditOnlyUserRows -CurrentUsersCsv $rollupUsersCsv -AuditOnlyCsv $script:PaxAuditOnlyUsersCsv -OutputPath $_rollupUsersWithAudit -CandidateFactCsv $_rollupCurrentFactForUsers
								$_rollupUsersForMerge = $_rollupUsersWithAudit
								$script:PaxAuditOnlyUsersWorkFile = $_rollupUsersWithAudit
								if ($_rollupPlaceholderCount -gt 0) {
									Write-LogHost ("Rollup: -AppendUserInfo: {0:N0} minimal Users row(s) added so every user in the activity data resolves to a Users row." -f $_rollupPlaceholderCount) -ForegroundColor DarkCyan
								}
							}
							Write-PaxRollupStage -Stage 'users-merge' -Status 'entry'
							# Observability-only heartbeat for a union that can run a long time. The
							# stage name and EVERY counter key are literal at this call site, so the
							# counter-name channel is closed by inspection: no key, row, field, file
							# name, path, URL, user principal name, tenant or account identifier, or
							# credential can reach a record. Only AGGREGATE numeric values are read
							# from the snapshot, and any failure here is swallowed so a logging
							# problem can never alter merge output, ordering, counts, or the result.
							$rollupUsersMergeProgress = {
								param($Snapshot)
								try {
									if ($null -eq $Snapshot) { return }
									Write-PaxRollupStage -Stage 'users-merge' -Status 'heartbeat' -Counters @{
										rowsRead       = [int64]$Snapshot.RowsRead
										rowsWritten    = [int64]$Snapshot.RowsWritten
										runCount       = [int64]$Snapshot.RunCount
										mergePassCount = [int64]$Snapshot.MergePassCount
										maxOpenReaders = [int64]$Snapshot.MaxOpenReaders
										temporaryBytes = [int64]$Snapshot.TempBytesWritten
										elapsedSeconds = [double]$Snapshot.ElapsedSeconds
									}
								}
								catch { }
							}
							# The union goes to a candidate path; the existing target is replaced only
							# after the joint referential-integrity gate passes.
							$_rollupAuiCandidate = $_rollupAuiMergeOut + '.paxcandidate'
							$rollupUsersMergeStats = Merge-UsersCsv -TargetUsersCsv $AppendUserInfo -CurrentUsersCsv $_rollupUsersForMerge -OutputPath $_rollupAuiCandidate -ProgressCallback $rollupUsersMergeProgress -ProgressIntervalSeconds $StatusIntervalSeconds
							Write-PaxRollupStage -Stage 'users-merge' -Status 'complete' -Counters @{ retained = [int64]$rollupUsersMergeStats.Retained; added = [int64]$rollupUsersMergeStats.New; departed = [int64]$rollupUsersMergeStats.Departed; union = [int64]$rollupUsersMergeStats.Union }
							Write-LogHost ("Rollup: -AppendUserInfo merge: Retained={0:N0}  New={1:N0}  Departed={2:N0}  Union={3:N0}" -f $rollupUsersMergeStats.Retained, $rollupUsersMergeStats.New, $rollupUsersMergeStats.Departed, $rollupUsersMergeStats.Union) -ForegroundColor Green
							# The transient rollup-Python Users CSV is the recovery artifact until the
							# gate publishes; it is removed there, not here.
							$script:PaxUsersCandidatePath = $_rollupAuiCandidate
							$script:PaxUsersCandidateFinal = $_rollupAuiMergeOut
							$script:PaxUsersTransientCsv = $rollupUsersCsv
						}
						else {
							Write-LogHost ("Rollup: -AppendUserInfo: expected Users CSV not found at '{0}'; skipping merge." -f $rollupUsersCsv) -ForegroundColor Yellow
						}
					}
					catch {
						# The un-merged current-run Users CSV is still on disk (we just failed to
						# fold it into the -AppendUserInfo target). Surface both facts so the
						# customer knows (a) the target was NOT updated this run, and (b) where to
						# find the new-run output. Because the two targets are published together,
						# this also stops the Fact target from being replaced on its own.
						$script:PaxUserKeyContinuityFailed = $true
						$script:HadTerminalFailures = $true
						if ($script:PaxUsersCandidatePath -and (Test-Path -LiteralPath $script:PaxUsersCandidatePath -PathType Leaf)) {
							try { Remove-Item -LiteralPath $script:PaxUsersCandidatePath -Force -ErrorAction SilentlyContinue } catch { }
						}
						$script:PaxUsersCandidatePath = $null
						Write-PaxRollupStage -Stage 'users-merge' -Status 'failed'
						Write-LogHost ("Rollup: -AppendUserInfo merge FAILED: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
						Write-LogHost ("Rollup:   -> Target NOT updated this run: {0}" -f (Get-DisplayPath -LocalPath $AppendUserInfo)) -ForegroundColor Yellow
						Write-LogHost ("Rollup:   -> New-run Users CSV preserved at: {0}" -f (Get-DisplayPath -LocalPath $rollupUsersCsv)) -ForegroundColor Yellow
						Write-LogHost  "Rollup:   -> Manual union-merge required to apply this run to the target." -ForegroundColor Yellow
					}
				}

				# -OutputPathUserInfo (overwrite/redirect) OR the default Users-dim
				# destination under CopilotInteraction rollup — i.e. NOT -AppendUserInfo
				# (which owns its own merge + upload wiring above and DELETES the transient
				# rolled-up Users CSV). The rolled-up '<entra_stem>_Users.csv' is the
				# customer-facing Users dimension and must be uploaded (plain overwrite) to
				# the UserInfo destination. When -OutputPathUserInfo supplies a file-form leaf,
				# the rolled-up leaf ('<custom-stem>_Users.csv') does NOT carry the current
				# run timestamp, so the remote upload sweep's timestamp wildcard misses it.
				# Register the leaf explicitly —
				# exactly like the M365 sidecar leaves — so the upload sweep includes it;
				# per-data-type routing (Get-DataTypeForOutputFile -> 'UserInfo') then lands
				# it at -OutputPathUserInfo. No union/merge, no In_Latest_Append provenance.
				# Retention deletes ONLY the RAW Entra input CSV (never this rolled-up dim),
				# so NO delete-list change is made here.
				if (-not $AppendUserInfo -and $script:RollupProcessorMode -eq 'CopilotInteraction') {
					try {
						$rollupUsersStem   = [System.IO.Path]::GetFileNameWithoutExtension($rollupEntraCsv)
						$rollupUsersDimCsv = Join-Path $rollupOutputDir ("{0}_Users.csv" -f $rollupUsersStem)
						if (Test-Path -LiteralPath $rollupUsersDimCsv) {
							$rollupUsersDimLeaf = [System.IO.Path]::GetFileName($rollupUsersDimCsv)
							if (-not $script:RollupUsersDimLeafs) { $script:RollupUsersDimLeafs = New-Object System.Collections.Generic.List[string] }
							if ($rollupUsersDimLeaf -and -not $script:RollupUsersDimLeafs.Contains($rollupUsersDimLeaf)) {
								[void]$script:RollupUsersDimLeafs.Add($rollupUsersDimLeaf)
							}
							$rollupUsersDimDisplay = if ($script:DestIsBound.ContainsKey('UserInfo') -and $script:DestIsBound['UserInfo'] -and $script:DestRaw.ContainsKey('UserInfo') -and $script:DestRaw['UserInfo']) { $script:DestRaw['UserInfo'] } else { Get-DisplayPath -LocalPath $rollupUsersDimCsv }
							Write-LogHost ("Rollup: Users dim registered for upload (overwrite): {0}" -f $rollupUsersDimDisplay) -ForegroundColor Gray
						}
						else {
							Write-LogHost ("Rollup: expected rolled-up Users CSV not found at '{0}'; Users dim not registered for upload." -f $rollupUsersDimCsv) -ForegroundColor Yellow
						}
					}
					catch {
						Write-LogHost ("Rollup: Users-dim upload registration failed (non-fatal): {0}" -f $_.Exception.Message) -ForegroundColor DarkYellow
					}
				}

				# -AppendFile (CopilotInteraction mode only): union-merge the target Fact CSV
				# with the just-produced rolled-up Fact CSV. Python emits
				# '<purview_stem>_Interactions.csv' beside the input Purview CSV. M365Bundle
				# has its own dedicated AppendFile merge + sidecar regen step further below
				# (Merge-M365RollupCsv + --rebuild-sidecars-from-rollup) and so does NOT use
				# this CopilotInteraction post-merge block. Failure here logs a warning but
				# does NOT roll the rollup back — the new Fact file is still on disk and
				# customer can merge manually.
				if ($AppendFile -and $script:RollupProcessorMode -eq 'CopilotInteraction') {
					try {
						$rollupPurviewStem = [System.IO.Path]::GetFileNameWithoutExtension($rollupPurviewCsv)
						$rollupFactCsv     = Join-Path $rollupOutputDir ("{0}_Interactions.csv" -f $rollupPurviewStem)
						$rollupAfSkipMerge = $false
						$rollupAfSkipReason = ''
						$rollupAfCompositeKey = @()
						if ((Test-Path -LiteralPath $rollupFactCsv) -and (Test-Path -LiteralPath $AppendFile -PathType Leaf)) {
							try {
								$rollupAfHdrLine = @(Get-Content -LiteralPath $AppendFile -TotalCount 1)
								$rollupAfCols = if ($rollupAfHdrLine.Count -gt 0) { ($rollupAfHdrLine[0] -split ',') | ForEach-Object { $_.Trim().Trim('"') } } else { @() }
								# Derive the grain-composite dedup key from the FRESH
								# rollup fact header (always current-schema), then require the TARGET to
								# carry every composite column. Fact rows fan out (many per
								# Message_Id_Raw, one per grain), so append dedup MUST key on the full
								# grain (UserKey/ThreadId in stable raw form) + Message_Id_Raw or fan-out
								# rows collapse and data is lost. Missing composite columns on the target
								# (e.g. an older AIO seed with no User_Id_Normalized) route to the
								# same data-loss-safe re-baseline skip as an older seed with no reconciliation key.
								$rollupCurHdrLine = @(Get-Content -LiteralPath $rollupFactCsv -TotalCount 1)
								$rollupCurCols = if ($rollupCurHdrLine.Count -gt 0) { ($rollupCurHdrLine[0] -split ',') | ForEach-Object { $_.Trim().Trim('"') } } else { @() }
								$rollupAfCompositeKey = @(Get-FactCompositeKeyColumns -HeaderColumns $rollupCurCols)
								if (-not ($rollupAfCols -contains 'Message_Id_Raw')) {
									$rollupAfSkipMerge = $true
									$rollupAfSkipReason = "target lacks the 'Message_Id_Raw' dedup key (pre-v1.11.11 seed)"
								}
								elseif ($rollupAfCompositeKey.Count -gt 0) {
									$rollupAfMissingKeyCols = @($rollupAfCompositeKey | Where-Object { $_ -notin $rollupAfCols })
									if ($rollupAfMissingKeyCols.Count -gt 0) {
										$rollupAfSkipMerge = $true
										$rollupAfSkipReason = ("target is missing grain-composite dedup column(s) [{0}] (pre-v1.11.12 seed)" -f ($rollupAfMissingKeyCols -join ', '))
									}
								}
							}
							catch {
								# Header probe failed; fall through to Merge-FactCsv whose own
								# 0-row and shrink guards still protect the target.
								$rollupAfSkipMerge = $false
							}
						}
						if ($rollupAfSkipMerge) {
							$rollupAfRebaselineName = ("{0}_Interactions_{1}.csv" -f $rollupPurviewStem, $global:ScriptRunTimestamp)
							$rollupAfRebaselinePath = Join-Path $rollupOutputDir $rollupAfRebaselineName
							Move-Item -LiteralPath $rollupFactCsv -Destination $rollupAfRebaselinePath -Force
							$_rollupAfDisplay = if ($script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) { $script:AppendRaw['Purview'] } else { $AppendFile }
							Write-LogHost ("Rollup: -AppendFile: {0}; append SKIPPED to prevent data loss." -f $rollupAfSkipReason) -ForegroundColor Yellow
							Write-LogHost ("Rollup:   -> Target left unchanged: {0}" -f $_rollupAfDisplay) -ForegroundColor Yellow
							Write-LogHost ("Rollup:   -> This run's rollup written to: {0}" -f (Get-DisplayPath -LocalPath $rollupAfRebaselinePath)) -ForegroundColor Yellow
							Write-LogHost  "Rollup:   -> To re-baseline: use this new file as your -AppendFile target going forward (it carries Message_Id_Raw and the full grain-composite key); subsequent appends reconcile on real grain + message identity." -ForegroundColor Yellow
						}
						elseif (Test-Path -LiteralPath $rollupFactCsv) {
							# Announce the local bounded reconciliation before it starts so a
							# large field-scale append shows what is happening and, importantly,
							# that nothing has been sent anywhere yet — this whole step is a
							# disk-bounded local merge that runs before any remote upload.
							$rollupAfTargetBytes  = try { [int64](Get-Item -LiteralPath $AppendFile).Length } catch { [int64]0 }
							$rollupAfCurrentBytes = try { [int64](Get-Item -LiteralPath $rollupFactCsv).Length } catch { [int64]0 }
							Write-LogHost ("Rollup: -AppendFile: local bounded reconciliation has begun (memory budget 64 MiB, fan-in 8; scratch under '{0}'). Existing target {1:N0} bytes + this run {2:N0} bytes. Remote upload has not started." -f $env:TEMP, $rollupAfTargetBytes, $rollupAfCurrentBytes) -ForegroundColor Cyan
							# Surface external-sort progress from inside the reconciliation. The
							# callback is interval-throttled by Invoke-PaxExternalSort itself
							# (ProgressIntervalSeconds), so it prints at most one line per status
							# interval per sort phase plus the forced first-of-stage markers.
							$rollupFactMergeProgress = {
								param($snapshot)
								try {
									Write-LogHost ("Rollup: -AppendFile reconciliation [{0}]: rowsRead={1:N0} rowsWritten={2:N0} runs={3:N0} elapsed={4:N0}s" -f $snapshot.Stage, [int64]$snapshot.RowsRead, [int64]$snapshot.RowsWritten, [int64]$snapshot.RunCount, [double]$snapshot.ElapsedSeconds) -ForegroundColor DarkGray
								} catch { }
							}
							if ($script:PaxUserKeyContinuityFailed) {
								throw 'user key continuity was not established for this run'
							}
							# The union goes to a candidate path; the existing target is replaced only
							# after the joint referential-integrity gate passes.
							$_rollupAfCandidate = $AppendFile + '.paxcandidate'
							$rollupFactMergeStats = Merge-FactCsv -TargetFactCsv $AppendFile -CurrentFactCsv $rollupFactCsv -KeyColumn 'Message_Id_Raw' -CompositeKeyColumn $rollupAfCompositeKey -OutputPath $_rollupAfCandidate -ProgressCallback $rollupFactMergeProgress -ProgressIntervalSeconds $StatusIntervalSeconds
							Write-LogHost ("Rollup: -AppendFile merge: Retained={0:N0}  New={1:N0}  Departed={2:N0}  Union={3:N0}" -f $rollupFactMergeStats.Retained, $rollupFactMergeStats.New, $rollupFactMergeStats.Departed, $rollupFactMergeStats.Union) -ForegroundColor Green
							# The transient rollup-Python Fact CSV is the recovery artifact until the
							# gate publishes; it is removed there, not here.
							$script:PaxFactCandidatePath = $_rollupAfCandidate
							$script:PaxFactCandidateFinal = $AppendFile
							$script:PaxFactTransientCsv = $rollupFactCsv
						}
						else {
							Write-LogHost ("Rollup: -AppendFile: expected Fact CSV not found at '{0}'; skipping merge." -f $rollupFactCsv) -ForegroundColor Yellow
						}
					}
					catch {
						# A REQUESTED output failed: the -AppendFile reconciliation threw, so the
						# target was NOT updated this run. This is a completed-with-gaps condition
						# (exit 40), NOT a best-effort skip. Flag HadTerminalFailures so the process
						# exit is truthful, and flag FactAppendFailed so the end-of-run cleanup
						# PRESERVES the recovery artifacts (unmerged current-run Fact + remote scratch
						# + Fabric resume mirror) instead of deleting them as on a clean run. It is NOT
						# an upload failure, so AnyUploadFailed is left untouched (a local merge fault
						# must never be reported as a remote upload fault). The un-merged current-run
						# Fact CSV stays on disk as the recovery artifact; register its leaf so the
						# end-of-run upload sweep + local listing EXCLUDE it — it must never be published
						# as the completed -AppendFile target, nor as a second normal Fact output.
						$script:HadTerminalFailures = $true
						$script:FactAppendFailed = $true
						if ($script:PaxFactCandidatePath -and (Test-Path -LiteralPath $script:PaxFactCandidatePath -PathType Leaf)) {
							try { Remove-Item -LiteralPath $script:PaxFactCandidatePath -Force -ErrorAction SilentlyContinue } catch { }
						}
						$script:PaxFactCandidatePath = $null
						if ($rollupFactCsv -and (Test-Path -LiteralPath $rollupFactCsv -PathType Leaf)) {
							if (-not $script:FactAppendRecoveryLeafs) { $script:FactAppendRecoveryLeafs = New-Object System.Collections.Generic.List[string] }
							$rollupAfRecoveryLeaf = [System.IO.Path]::GetFileName($rollupFactCsv)
							if ($rollupAfRecoveryLeaf -and -not $script:FactAppendRecoveryLeafs.Contains($rollupAfRecoveryLeaf)) { [void]$script:FactAppendRecoveryLeafs.Add($rollupAfRecoveryLeaf) }
						}
						Write-LogHost ("Rollup: -AppendFile merge FAILED: {0}" -f $_.Exception.Message) -ForegroundColor Red
						Write-LogHost  "Rollup:   -> Requested append output NOT completed this run (completed with gaps, exit 40)." -ForegroundColor Red
						Write-LogHost ("Rollup:   -> Target left UNCHANGED this run: {0}" -f (Get-DisplayPath -LocalPath $AppendFile)) -ForegroundColor Yellow
						Write-LogHost ("Rollup:   -> Recovery Fact CSV preserved (excluded from upload): {0}" -f (Get-DisplayPath -LocalPath $rollupFactCsv)) -ForegroundColor Yellow
						Write-LogHost  "Rollup:   -> Manual union-merge required to apply this run to the target." -ForegroundColor Yellow
					}
				}

				# Referential-integrity gate. The candidate Fact and the candidate Users
				# describe one set of people, so they are validated TOGETHER and published
				# together. If they disagree, NEITHER replaces its existing target: both
				# targets stay byte-for-byte as they were, this run's output is preserved for
				# review, and the run reports completed with gaps.
				if ($script:RollupProcessorMode -eq 'CopilotInteraction' -and ($script:PaxUsersCandidatePath -or $script:PaxFactCandidatePath)) {
					$_paxGateOk = $false
					try {
						$_paxGateUsers = if ($script:PaxUsersCandidatePath) { $script:PaxUsersCandidatePath }
						elseif ($AppendUserInfo -and (Test-Path -LiteralPath $AppendUserInfo -PathType Leaf)) { $AppendUserInfo }
						else { $null }
						$_paxGateFact = if ($script:PaxFactCandidatePath) { $script:PaxFactCandidatePath } else { $null }
						if ($_paxGateUsers -or $_paxGateFact) {
							Write-PaxRollupStage -Stage 'append-integrity' -Status 'entry'
							$_paxGate = Test-PaxUserKeyReferentialIntegrity -CandidateUsersCsv $_paxGateUsers -CandidateFactCsv $_paxGateFact
							if ($_paxGate.Passed) {
								Write-PaxRollupStage -Stage 'append-integrity' -Status 'complete' -Counters @{ usersRows = [int64]$_paxGate.UsersRows; factRows = [int64]$_paxGate.FactRows; conflictingUserKeys = [int64]$_paxGate.ConflictingUserKeys; splitIdentities = [int64]$_paxGate.SplitIdentities; orphanFactKeys = [int64]$_paxGate.OrphanFactKeys; mismatchedFactRows = [int64]$_paxGate.MismatchedFactRows }
								$_paxGateOk = $true
							}
							else {
								Write-PaxRollupStage -Stage 'append-integrity' -Status 'failed' -Counters @{ conflictingUserKeys = [int64]$_paxGate.ConflictingUserKeys; splitIdentities = [int64]$_paxGate.SplitIdentities; orphanFactKeys = [int64]$_paxGate.OrphanFactKeys; mismatchedFactRows = [int64]$_paxGate.MismatchedFactRows }
							}
						}
						else {
							# Neither candidate is present, so there is nothing to validate.
							$_paxGateOk = $true
						}
					}
					catch {
						$_paxGateOk = $false
						Write-PaxRollupStage -Stage 'append-integrity' -Status 'failed'
						Write-LogHost ("Rollup: append integrity check failed: {0}" -f $_.Exception.Message) -ForegroundColor Red
					}

					if ($_paxGateOk) {
						try {
							if ($script:PaxUsersCandidatePath) {
								Move-Item -LiteralPath $script:PaxUsersCandidatePath -Destination $script:PaxUsersCandidateFinal -Force -ErrorAction Stop
								$script:PaxUsersCandidatePath = $null
								$_rollupAuiDisplay = if ($script:AppendRaw.ContainsKey('UserInfo') -and $script:AppendRaw['UserInfo']) { $script:AppendRaw['UserInfo'] } else { $AppendUserInfo }
								Write-LogHost ("Entra Users File: appended to {0}" -f $_rollupAuiDisplay) -ForegroundColor Gray
							}
							if ($script:PaxFactCandidatePath) {
								Move-Item -LiteralPath $script:PaxFactCandidatePath -Destination $script:PaxFactCandidateFinal -Force -ErrorAction Stop
								$script:PaxFactCandidatePath = $null
								$_rollupAfDisplay = if ($script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) { $script:AppendRaw['Purview'] } else { $AppendFile }
								Write-LogHost ("Appended to: {0}" -f $_rollupAfDisplay) -ForegroundColor White
							}
						}
						catch {
							$_paxGateOk = $false
							Write-LogHost ("Rollup: append publication failed: {0}" -f $_.Exception.Message) -ForegroundColor Red
						}
					}

					if ($_paxGateOk) {
						# Both targets now carry this run, so the transient current-run inputs are
						# duplicates and are removed.
						foreach ($_paxTransient in @($script:PaxUsersTransientCsv, $script:PaxFactTransientCsv, $script:PaxAuditOnlyUsersWorkFile)) {
							if ($_paxTransient -and (Test-Path -LiteralPath $_paxTransient -PathType Leaf)) {
								try { Remove-Item -LiteralPath $_paxTransient -Force -ErrorAction Stop }
								catch { Write-LogHost ("Rollup: transient append input cleanup failed (non-fatal): {0}" -f $_.Exception.Message) -ForegroundColor DarkYellow }
							}
						}
					}
					else {
						# Publish NEITHER candidate. Both existing targets are left exactly as they
						# were and this run's output is kept, so nothing is lost.
						$script:HadTerminalFailures = $true
						$script:FactAppendFailed = $true
						foreach ($_paxCandidate in @($script:PaxUsersCandidatePath, $script:PaxFactCandidatePath, $script:PaxAuditOnlyUsersWorkFile)) {
							if ($_paxCandidate -and (Test-Path -LiteralPath $_paxCandidate -PathType Leaf)) {
								try { Remove-Item -LiteralPath $_paxCandidate -Force -ErrorAction SilentlyContinue } catch { }
							}
						}
						if ($script:PaxFactTransientCsv -and (Test-Path -LiteralPath $script:PaxFactTransientCsv -PathType Leaf)) {
							if (-not $script:FactAppendRecoveryLeafs) { $script:FactAppendRecoveryLeafs = New-Object System.Collections.Generic.List[string] }
							$_paxRecoveryLeaf = [System.IO.Path]::GetFileName($script:PaxFactTransientCsv)
							if ($_paxRecoveryLeaf -and -not $script:FactAppendRecoveryLeafs.Contains($_paxRecoveryLeaf)) { [void]$script:FactAppendRecoveryLeafs.Add($_paxRecoveryLeaf) }
						}
						Write-LogHost  "Rollup: append NOT completed this run: the Fact and Users output did not agree on user identity keys." -ForegroundColor Red
						Write-LogHost  "Rollup:   -> Both existing targets are unchanged (completed with gaps, exit 40)." -ForegroundColor Red
						Write-LogHost  "Rollup:   -> This run's output is preserved for review; re-baseline to apply it." -ForegroundColor Yellow
					}
					$script:PaxUsersCandidatePath = $null
					$script:PaxFactCandidatePath = $null
				}

				# -AppendFile (M365Bundle mode): merge the current run's rollup into
				# the customer's target rollup, then regenerate the UserStats and
				# SessionCohort sidecars from the merged content and union-merge
				# the SessionStats sidecar in place so all four outputs share the
				# customer's stem and overwrite the same URLs on every subsequent run.
				#
				# Flow:
				#   1. Glob-resolve the 4 timestamped current-run outputs (Rollup,
				#      UserStats, SessionCohort, SessionStats) inside $rollupOutputDir.
				#   2. Merge-M365RollupCsv unions the current rollup with
				#      $AppendFile (column-tolerant — legacy 9/10-col targets are
				#      padded with empty agent columns + IsAgentInteraction=FALSE)
				#      and writes the union back to $AppendFile.
				#   2b. Merge-M365SessionStatsCsv unions the current
				#      SessionStats with the anchored '<stem>_SessionStats.csv'
				#      target (creating it on first run) using additive counter
				#      semantics keyed on (UserId, CreationDate, AppHost).
				#   3. A second embedded-processor invocation runs with
				#      --rebuild-sidecars-from-rollup against $AppendFile (with
				#      --session-stats-for-rebuild pointing at the merged
				#      SessionStats leaf so the regenerated UserStats inherits the
				#      PromptCount-based CECopilotPercentile_* columns from the
				#      unioned SessionStats history), writing fresh timestamped
				#      UserStats + SessionCohort sidecars into the AppendFile parent.
				#   4. The new sidecars are anchor-renamed to the customer's stem
				#      (timestamp dropped) so the same URLs are overwritten each run.
				#   5. The current-run rollup and stale sidecars in $rollupOutputDir
				#      are removed (their content lives in $AppendFile + the
				#      anchored sidecars now); leaving them would cause duplicates
				#      to appear in the run-timestamp upload sweep.
				# The pre-flight leaf validator (see AppendFile resolution block)
				# guarantees $AppendFile ends in '_Rollup.csv' (with or without a
				# timestamp suffix) when we get here. In remote mode, $AppendFile
				# has been redirected to a scratch path in $OutputPath whose leaf
				# matches the original remote leaf, so Split-Path -Parent and
				# Move-Item operate on local paths and the upload sweep's leaf-match
				# logic picks up all 4 anchored files.
				if ($AppendFile -and $script:RollupProcessorMode -eq 'M365Bundle') {
					try {
						$m365PurviewStem = [System.IO.Path]::GetFileNameWithoutExtension($rollupPurviewCsv)

						# Glob-resolve the 4 current-run timestamped outputs.
						$m365CurRollupInfo       = @(Get-ChildItem -LiteralPath $rollupOutputDir -Filter ("{0}_Rollup_*.csv"        -f $m365PurviewStem) -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
						$m365CurUserStatsInfo    = @(Get-ChildItem -LiteralPath $rollupOutputDir -Filter ("{0}_UserStats_*.csv"     -f $m365PurviewStem) -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
						$m365CurSessionInfo      = @(Get-ChildItem -LiteralPath $rollupOutputDir -Filter ("{0}_SessionCohort_*.csv" -f $m365PurviewStem) -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
						$m365CurSessionStatsInfo = @(Get-ChildItem -LiteralPath $rollupOutputDir -Filter ("{0}_SessionStats_*.csv"  -f $m365PurviewStem) -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
						if ($m365CurRollupInfo.Count -lt 1) {
							throw ("Current-run rollup not found in '{0}' (expected '{1}_Rollup_*.csv')." -f $rollupOutputDir, $m365PurviewStem)
						}
						$m365CurRollupPath       = $m365CurRollupInfo[0].FullName
						$m365CurUserStatsPath    = if ($m365CurUserStatsInfo.Count    -gt 0) { $m365CurUserStatsInfo[0].FullName    } else { $null }
						$m365CurSessionPath      = if ($m365CurSessionInfo.Count      -gt 0) { $m365CurSessionInfo[0].FullName      } else { $null }
						$m365CurSessionStatsPath = if ($m365CurSessionStatsInfo.Count -gt 0) { $m365CurSessionStatsInfo[0].FullName } else { $null }

						# Anchor stem from the AppendFile leaf (validator widened to
						# accept either '<stem>_Rollup.csv' or '<stem>_Rollup_<ts>.csv').
						$m365AnchorLeaf = [System.IO.Path]::GetFileName($AppendFile)
						$m365AnchorStem = ($m365AnchorLeaf -replace '_Rollup(?:_\d{8}_\d{6})?\.csv$', '')
						$m365AnchorDir  = Split-Path $AppendFile -Parent
						$m365AnchorSessionStats = Join-Path $m365AnchorDir ("{0}_SessionStats.csv" -f $m365AnchorStem)

						# 1. Union-merge current rollup -> $AppendFile (in-place).
						$m365MergeStats = Merge-M365RollupCsv -TargetRollupCsv $AppendFile -CurrentRollupCsv $m365CurRollupPath -OutputPath $AppendFile
						Write-LogHost ("Rollup: -AppendFile M365 merge: Retained={0:N0}  New={1:N0}  Updated={2:N0}  Union={3:N0}" -f $m365MergeStats.Retained, $m365MergeStats.New, $m365MergeStats.Updated, $m365MergeStats.Union) -ForegroundColor Green

						# 2. Union-merge current SessionStats -> anchored
						#    '<stem>_SessionStats.csv' (in-place, creating on first run)
						#    using additive counter semantics keyed on
						#    (UserId, CreationDate, AppHost). The merged target then
						#    feeds the sidecar-rebuild call below so the regenerated
						#    UserStats inherits the unioned PromptCount-based percentiles.
						if ($m365CurSessionStatsPath -and (Test-Path -LiteralPath $m365CurSessionStatsPath)) {
							$m365SsMergeStats = Merge-M365SessionStatsCsv `
								-TargetSessionStatsCsv  $m365AnchorSessionStats `
								-CurrentSessionStatsCsv $m365CurSessionStatsPath `
								-OutputPath             $m365AnchorSessionStats
							Write-LogHost ("Rollup: -AppendFile M365 SessionStats merge: Retained={0:N0}  New={1:N0}  Updated={2:N0}  Union={3:N0}" -f $m365SsMergeStats.Retained, $m365SsMergeStats.New, $m365SsMergeStats.Updated, $m365SsMergeStats.Union) -ForegroundColor Green
						}

						# 3. Regenerate UserStats + SessionCohort sidecars from the
						#    unioned $AppendFile via a second embedded-processor
						#    invocation. When the merged SessionStats target exists
						#    we pass it via --session-stats-for-rebuild so the
						#    PromptCount-based CECopilotPercentile_* columns reflect
						#    the union history (otherwise the python code falls back
						#    to the raw CECopilot signal computed from the rollup).
						$m365SidecarArgs = @('--rebuild-sidecars-from-rollup', $AppendFile, '--output-dir', $m365AnchorDir, '--quiet')
						if (Test-Path -LiteralPath $m365AnchorSessionStats) {
							$m365SidecarArgs += @('--session-stats-for-rebuild', $m365AnchorSessionStats)
						}
						$m365SidecarExit = Invoke-EmbeddedProcessor `
							-ProcessorMode  $script:RollupProcessorMode `
							-PythonExe      $pyResolved.Path `
							-LauncherArgs   $pyResolved.Args `
							-ProcessorArgs  $m365SidecarArgs `
							-IncrementalDir $rollupIncDir
						if ($m365SidecarExit -ne 0) {
							throw ("Sidecar regeneration exited with code {0}." -f $m365SidecarExit)
						}

						# 4. Glob-resolve the regenerated timestamped sidecars (newest by mtime).
						$m365NewUserStatsInfo = @(Get-ChildItem -LiteralPath $m365AnchorDir -Filter ("{0}_UserStats_*.csv"     -f $m365AnchorStem) -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
						$m365NewSessionInfo   = @(Get-ChildItem -LiteralPath $m365AnchorDir -Filter ("{0}_SessionCohort_*.csv" -f $m365AnchorStem) -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
						$m365AnchorUserStats  = Join-Path $m365AnchorDir ("{0}_UserStats.csv"     -f $m365AnchorStem)
						$m365AnchorSession    = Join-Path $m365AnchorDir ("{0}_SessionCohort.csv" -f $m365AnchorStem)

						# 5. Anchor-rename the regenerated sidecars onto the customer's stem.
						#    SessionStats is already anchored in step 2 (merged in-place).
						$m365AnchorPairs = @(
							@{ Src = if ($m365NewUserStatsInfo.Count -gt 0) { $m365NewUserStatsInfo[0].FullName } else { $null }; Dst = $m365AnchorUserStats; Label = 'UserStats'     },
							@{ Src = if ($m365NewSessionInfo.Count   -gt 0) { $m365NewSessionInfo[0].FullName   } else { $null }; Dst = $m365AnchorSession;   Label = 'SessionCohort' }
						)
						foreach ($m365Pair in $m365AnchorPairs) {
							if (-not $m365Pair.Src -or -not (Test-Path -LiteralPath $m365Pair.Src)) {
								Write-LogHost ("Rollup: M365 sidecar regen: expected {0} output not found in '{1}'; skipping." -f $m365Pair.Label, $m365AnchorDir) -ForegroundColor Yellow
								continue
							}
							$m365SrcFull = [System.IO.Path]::GetFullPath($m365Pair.Src)
							$m365DstFull = [System.IO.Path]::GetFullPath($m365Pair.Dst)
							if ($m365SrcFull -ne $m365DstFull) {
								Move-Item -LiteralPath $m365Pair.Src -Destination $m365Pair.Dst -Force -ErrorAction Stop
							}
						}

						# 6. Remove the current-run rollup + stale current-run sidecars
						#    from $rollupOutputDir. Their content lives in $AppendFile
						#    plus the anchored sidecars now.
						foreach ($m365StalePath in @($m365CurRollupPath, $m365CurUserStatsPath, $m365CurSessionPath, $m365CurSessionStatsPath)) {
							if (-not $m365StalePath) { continue }
							try {
								if (Test-Path -LiteralPath $m365StalePath) {
									Remove-Item -LiteralPath $m365StalePath -Force -ErrorAction Stop
								}
							}
							catch {
								Write-LogHost ("Rollup: failed to remove stale current-run file at '{0}': {1}" -f $m365StalePath, $_.Exception.Message) -ForegroundColor Yellow
							}
						}

						# Register the three sidecar leaves so the upload sweep + local listing
						# pick them up. The Rollup leaf is already covered via
						# $script:AppendRaw['Purview'] in the existing $appendLeafs loop.
						if (-not $script:M365SidecarLeafs) { $script:M365SidecarLeafs = New-Object System.Collections.Generic.List[string] }
						foreach ($m365SidecarLeaf in @(
							[System.IO.Path]::GetFileName($m365AnchorUserStats),
							[System.IO.Path]::GetFileName($m365AnchorSession),
							[System.IO.Path]::GetFileName($m365AnchorSessionStats)
						)) {
							if ($m365SidecarLeaf -and -not $script:M365SidecarLeafs.Contains($m365SidecarLeaf)) {
								[void]$script:M365SidecarLeafs.Add($m365SidecarLeaf)
							}
						}

						# Surface the customer-facing display URLs. For Rollup, the original
						# AppendFile URL is the authoritative display (in-place overwrite). For
						# sidecars, synthesize the destination URL from the AppendFile parent
						# plus the derived sidecar leaf so remote runs show actual remote URLs
						# instead of scratch paths.
						$m365RollupDisplay = if ($script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) { $script:AppendRaw['Purview'] } else { Get-DisplayPath -LocalPath $AppendFile }
						$m365SidecarUsDisplay = $null
						$m365SidecarScDisplay = $null
						$m365SidecarSsDisplay = $null
						if ($script:AppendIsRemote.ContainsKey('Purview') -and $script:AppendIsRemote['Purview'] -and $script:AppendRaw.ContainsKey('Purview') -and $script:AppendRaw['Purview']) {
							$m365AfUrl       = $script:AppendRaw['Purview']
							$m365AfUrlParent = $m365AfUrl -replace '/[^/]+$', ''
							$m365SidecarUsDisplay = "{0}/{1}" -f $m365AfUrlParent, [System.IO.Path]::GetFileName($m365AnchorUserStats)
							$m365SidecarScDisplay = "{0}/{1}" -f $m365AfUrlParent, [System.IO.Path]::GetFileName($m365AnchorSession)
							$m365SidecarSsDisplay = "{0}/{1}" -f $m365AfUrlParent, [System.IO.Path]::GetFileName($m365AnchorSessionStats)
						}
						else {
							$m365SidecarUsDisplay = Get-DisplayPath -LocalPath $m365AnchorUserStats
							$m365SidecarScDisplay = Get-DisplayPath -LocalPath $m365AnchorSession
							$m365SidecarSsDisplay = Get-DisplayPath -LocalPath $m365AnchorSessionStats
						}

						Write-LogHost ("Rollup: -AppendFile M365: merged Rollup overwrites the AppendFile target; UserStats / SessionCohort sidecars regenerated from the union and SessionStats union-merged in-place, all anchored onto stem '{0}'." -f $m365AnchorStem) -ForegroundColor Green
						Write-LogHost ("  Rollup        -> {0}" -f $m365RollupDisplay)    -ForegroundColor Gray
						Write-LogHost ("  UserStats     -> {0}" -f $m365SidecarUsDisplay) -ForegroundColor Gray
						Write-LogHost ("  SessionCohort -> {0}" -f $m365SidecarScDisplay) -ForegroundColor Gray
						Write-LogHost ("  SessionStats  -> {0}" -f $m365SidecarSsDisplay) -ForegroundColor Gray
						Write-LogHost  "  NOTE: any prior sidecars in the destination folder with different leaf names (e.g. from a renamed AppendFile) are NOT auto-deleted." -ForegroundColor DarkGray
					}
					catch {
						# Non-fatal: the current-run outputs may still be on disk at
						# their timestamped leaves in $rollupOutputDir if the merge or
						# sidecar regen failed mid-flight. Surface where they live so
						# the customer can recover.
						Write-LogHost ("Rollup: -AppendFile M365 merge/anchor FAILED: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
						Write-LogHost ("Rollup:   -> Customer's target may or may not be updated: {0}" -f (Get-DisplayPath -LocalPath $AppendFile)) -ForegroundColor Yellow
						Write-LogHost ("Rollup:   -> Any preserved current-run outputs are in: {0}" -f (Get-DisplayPath -LocalPath $rollupOutputDir)) -ForegroundColor Yellow
						Write-LogHost  "Rollup:   -> Manual union-merge required to reconcile this run with the target." -ForegroundColor Yellow
					}
				}
			}
			else {
				Write-LogHost "Rollup: post-processor returned non-zero exit code $rollupExit. Raw CSV(s) preserved." -ForegroundColor Red
				$script:RollupProcessorFailed = $true
			}
		}
		catch {
			Write-LogHost "Rollup: post-processor failed: $($_.Exception.Message)" -ForegroundColor Red
			Write-Log    "Rollup: $($_.ScriptStackTrace)"
			$rollupSuccess = $false
			$script:RollupProcessorFailed = $true
		}

		# 5. Retention: -Rollup deletes raw CSV(s) on success; -RollupPlusRaw always keeps them;
		#    any failure ALWAYS keeps them (regardless of which switch).
		#    NOTE: The Agent 365 catalog CSV (Agent365_<ts>.csv) is intentionally
		#    NEVER added to $rollupRawCsvList because the Analytics-Hub Power BI dashboards
		#    consume it as a companion input alongside the rollup output. The defensive
		#    file-name guard below is belt-and-suspenders against a future refactor that
		#    might inadvertently include it.
		if ($rollupSuccess -and $Rollup -and -not $RollupPlusRaw) {
			foreach ($rollupRawPath in $rollupRawCsvList) {
				if ([System.IO.Path]::GetFileName($rollupRawPath) -like 'Agent365_*') {
					Write-LogHost "Rollup: skipping Agent 365 catalog CSV (always retained as Power BI companion): $(Get-DisplayPath -LocalPath $rollupRawPath)" -ForegroundColor DarkGray
					continue
				}
				# In remote-output mode this intermediate raw CSV lives on local scratch only
				# and is consumed by the rollup post-processor BEFORE the end-of-run upload
				# sweep — it never reaches the remote destination. Showing its phantom remote
				# URL (via Get-DisplayPath) would imply a remote DELETE happened when no such
				# remote object ever existed. Surface the actual local-scratch path and add
				# a 'scratch only; not uploaded' qualifier in remote mode.
				$rollupDelNote = if ($script:RemoteOutputMode -ne 'None') { ' (scratch only; not uploaded)' } else { '' }
				try {
					if (Test-Path -LiteralPath $rollupRawPath) {
						Remove-Item -LiteralPath $rollupRawPath -Force -ErrorAction Stop
						Write-LogHost "Rollup: deleted raw CSV (per -Rollup)${rollupDelNote}: $rollupRawPath" -ForegroundColor DarkGray
					}
				}
				catch {
					Write-LogHost "Rollup: failed to delete raw CSV '$rollupRawPath'${rollupDelNote}: $($_.Exception.Message)" -ForegroundColor Yellow
				}
			}
		}
		elseif ($rollupSuccess -and $RollupPlusRaw) {
			# Under -RollupPlusRaw the raw CSVs are always retained as pristine source
			# artifacts alongside the rollup output. With pristine-raw separation the
			# raw is never the append union — Merge-UsersCsv / Merge-FactCsv write
			# the union to -AppendUserInfo / -AppendFile separately (-OutputPath).
			Write-LogHost 'Rollup: raw CSV(s) retained (per -RollupPlusRaw):' -ForegroundColor Gray
			foreach ($rollupRawPath in $rollupRawCsvList) {
				$leafLower = ([System.IO.Path]::GetFileName($rollupRawPath)).ToLowerInvariant()
				$lineLabel = if ($leafLower -like 'purview_*') {
					'  Raw Purview CSV: '
				} else {
					'  Raw output:       '
				}
				Write-LogHost ("{0} {1}" -f $lineLabel, (Get-DisplayPath -LocalPath $rollupRawPath)) -ForegroundColor Gray
			}
			foreach ($rollupExtraPath in $rollupRetainedExtraList) {
				if (Test-Path -LiteralPath $rollupExtraPath) {
					$leafLower = ([System.IO.Path]::GetFileName($rollupExtraPath)).ToLowerInvariant()
					$lineLabel = if ($leafLower -like 'entrausers_*') {
						'  Raw Entra CSV:   '
					} else {
						'  Raw output:       '
					}
					Write-LogHost ("{0} {1}" -f $lineLabel, (Get-DisplayPath -LocalPath $rollupExtraPath)) -ForegroundColor Gray
				}
			}
		}

		# Always-delete list: files that are internal rollup inputs and must never be
		# retained as customer artifacts (e.g. Entra users CSV). Deleted on rollup success
		# regardless of -Rollup vs -RollupPlusRaw. On failure they are preserved alongside
		# the raw Purview CSV so the user can re-invoke the rollup manually.
		if ($rollupSuccess) {
			# Same scratch-only / never-uploaded reasoning as the raw-CSV delete block
			# above — these Entra users CSVs are rollup inputs that live on local scratch
			# in remote-output mode and are reaped before the upload sweep, so the
			# displayed path must be the actual local path.
			$rollupAlwaysDelNote = if ($script:RemoteOutputMode -ne 'None') { ' (scratch only; not uploaded)' } else { '' }
			foreach ($rollupAlwaysDeletePath in $rollupAlwaysDeleteList) {
				try {
					if (Test-Path -LiteralPath $rollupAlwaysDeletePath) {
						Remove-Item -LiteralPath $rollupAlwaysDeletePath -Force -ErrorAction Stop
						Write-LogHost "Rollup: deleted internal input CSV${rollupAlwaysDelNote}: $rollupAlwaysDeletePath" -ForegroundColor DarkGray
					}
				}
				catch {
					Write-LogHost "Rollup: failed to delete internal input CSV '$rollupAlwaysDeletePath'${rollupAlwaysDelNote}: $($_.Exception.Message)" -ForegroundColor Yellow
				}
			}
		}

		# Surface any extra retained files (e.g. M365Bundle + -IncludeUserInfo Entra CSV,
		# which the M365 processor never consumes and which is therefore always kept).
		# Under -RollupPlusRaw these were already listed above; only emit here for the
		# -Rollup case to avoid double-printing.
		if ($rollupSuccess -and $Rollup -and -not $RollupPlusRaw -and $rollupRetainedExtraList.Count -gt 0) {
			Write-LogHost "Rollup: file(s) retained (not consumed by this processor):" -ForegroundColor Gray
			foreach ($rollupExtraPath in $rollupRetainedExtraList) {
				if (Test-Path -LiteralPath $rollupExtraPath) {
					Write-LogHost "  Retained:       $(Get-DisplayPath -LocalPath $rollupExtraPath)" -ForegroundColor Gray
				}
			}
		}
		Write-LogHost "═══════════════════════════════════════════════════════" -ForegroundColor Cyan
		Write-LogHost ""
	}

	# Local-mode consolidated artifact listing — when no remote destination is set, surface
	# a single end-of-run list of all customer-visible files produced this run (audit CSV/XLSX,
	# EntraUsers, Agent365, rollup outputs, log, metrics). Mirrors the remote upload sweep's
	# scoping logic so customers see the same picture whether output is local or remote.
	if ($script:RemoteOutputMode -eq 'None' -and $global:ScriptRunTimestamp) {
		$listingDir = Split-Path $OutputFile -Parent
		# Also sweep any LOCAL-tier per-stream override directories so that
		# -OutputPathUserInfo / -OutputPathAgent365Info / -LogPath pointing at a
		# directory OTHER than $OutputFile's parent doesn't hide that stream's
		# artifact from the end-of-run banner. Remote tiers are handled by the
		# remote upload sweep below; this branch only runs when RemoteOutputMode
		# is 'None' (i.e., all streams resolved to local destinations).
		$listingDirs = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
		if ($listingDir) { $null = $listingDirs.Add($listingDir) }
		foreach ($_streamKey in @('UserInfo','Agent365Info','Log')) {
			$_streamDt = script:Resolve-DataTypePaths -DataType $_streamKey
			if ($_streamDt -and $_streamDt.IsBound -and $_streamDt.Tier -eq 'Local' -and $_streamDt.EffectiveDir) {
				$null = $listingDirs.Add($_streamDt.EffectiveDir)
			}
		}
		# AISID dashboard destination (DefenderUsage): its twelve fixed-name leaves are
		# customer-visible outputs. When that folder is local (co-located with -OutputPath
		# or a local -OutputPathDefenderUsage), include it so the roster lists all twelve.
		if ($script:AISIDDestDir -and (Test-Path -LiteralPath $script:AISIDDestDir -PathType Container)) {
			$null = $listingDirs.Add($script:AISIDDestDir)
		}
		if ($listingDirs.Count -gt 0) {
			# Mirror the remote upload sweep's append-leaf collection (~30 lines below)
			# so the local listing surfaces the merged Append* targets even though
			# their filenames carry the target's ORIGINAL timestamp (not
			# $global:ScriptRunTimestamp). Without this, an -AppendFile /
			# -AppendUserInfo / -AppendAgent365Info run would hide every merged output
			# from the end-of-run banner — the only file matching the current-run
			# timestamp filter is the .log itself, so the listing would print '(1)'
			# and show just the log even though the run also updated the customer's
			# append targets in-place.
			$listingAppendLeafs = New-Object System.Collections.Generic.List[string]
			foreach ($k in @('Purview','UserInfo','Agent365Info')) {
				if ($script:AppendIsBound.ContainsKey($k) -and $script:AppendIsBound[$k] -and $script:AppendRaw.ContainsKey($k)) {
					$leaf = [System.IO.Path]::GetFileName($script:AppendRaw[$k])
					if ($leaf) { [void]$listingAppendLeafs.Add($leaf) }
				}
			}
			# M365Bundle rollup sidecars (UserStats / SessionCohort) re-anchored off the
			# -AppendFile leaf inherit the target's ORIGINAL stem (not the current-run
			# timestamp), so they don't match the timestamp wildcard. Surface them via
			# the explicit leaf list so the local end-of-run listing shows them.
			if ($script:M365SidecarLeafs) {
				foreach ($m365Sc in $script:M365SidecarLeafs) {
					if ($m365Sc -and -not $listingAppendLeafs.Contains($m365Sc)) { [void]$listingAppendLeafs.Add($m365Sc) }
				}
			}
			$listingCandidates = @()
			foreach ($_sweepDir in $listingDirs) {
				if (-not (Test-Path $_sweepDir)) { continue }
				$listingCandidates += Get-ChildItem -Path $_sweepDir -File -ErrorAction SilentlyContinue |
					Where-Object {
						($_.Name -like "*${global:ScriptRunTimestamp}*" -or $listingAppendLeafs.Contains($_.Name) -or ($script:AISIDUploadLeafs -and $script:AISIDUploadLeafs.Contains($_.Name))) `
						-and $_.Name -notlike '.pax_*' `
						-and $_.Name -notlike '*_PARTIAL.*' `
						-and (-not ($script:FactAppendRecoveryLeafs -and $script:FactAppendRecoveryLeafs.Contains($_.Name))) `
						-and (-not ($script:Agent365RecoveryLeafs -and $script:Agent365RecoveryLeafs.Contains($_.Name)))
					}
			}
			# Dedupe by full path (a stream override directory could theoretically
			# coincide with $listingDir, in which case the per-dir sweeps overlap)
			# and sort by name to preserve the prior ordering for the unsplit case.
			$listingCandidates = $listingCandidates | Sort-Object FullName -Unique | Sort-Object Name
			if ($listingCandidates -and $listingCandidates.Count -gt 0) {
				Write-LogHost ("Output files created ({0}):" -f $listingCandidates.Count) -ForegroundColor Cyan
				foreach ($listingFile in $listingCandidates) {
					$sizeKB = [math]::Round($listingFile.Length / 1KB, 2)
					# Tag rows whose leaf matches a bound Append target so customers can
					# distinguish newly-created files from in-place merge updates. Size
					# reflects the post-merge total, which is the right number to surface.
					$marker = if ($listingAppendLeafs.Contains($listingFile.Name)) { ' [appended]' } else { '' }
					Write-LogHost ("  {0} ({1} KB){2}" -f $listingFile.FullName, $sizeKB, $marker) -ForegroundColor Gray
				}
				Write-LogHost ""
			}
		}
	}

	# Remote upload sweep — upload all customer-visible artifacts produced this run to the
	# remote destination (SharePoint or Fabric). Done in a single sweep AFTER all writers
	# (audit CSV/XLSX, EntraUsers CSV, Agent365 CSV, rollup output) have closed but BEFORE
	# the local scratch cleanup. Scoped strictly to this run's $global:ScriptRunTimestamp.
	# Skipped automatically when remote mode is None.
	#
	# Fabric Tables/ destinations: when an -OutputPath* value ends in '/Tables', every CSV in
	# the sweep is converted to a Delta table at <Lakehouse>/Tables/<table-name>. Non-CSV
	# artifacts (XLSX, log, metrics JSON) still upload to the Lakehouse Files/ namespace
	# via Send-FileToOneLake. Table names strip the run-timestamp suffix so successive
	# runs target the same table (overwrite mode — the CSV on disk already represents
	# the merged dataset when any -Append* flag was in effect).
	if ($script:RemoteOutputMode -ne 'None' -and $global:ScriptRunTimestamp) {
		$uploadDir = Split-Path $OutputFile -Parent
		if ($uploadDir -and (Test-Path $uploadDir)) {
			# Sweep selection: by default the per-run timestamp matches every file this
			# script produced. But when -AppendFile / -AppendUserInfo / -AppendAgent365Info
			# is bound, the writer inherits the Append target's ORIGINAL leaf (so the
			# merged file overwrites the original remote URL on upload). That original
			# leaf carries the target's OLD timestamp and therefore does not match the
			# current-run filter. Collect those leaves explicitly and OR them into the
			# Where-Object so every Append-mode stream's merged output is also swept.
			# The '.pax_*' exclusion still hides the seed copies pulled during pre-flight.
			$appendLeafs = New-Object System.Collections.Generic.List[string]
			foreach ($k in @('Purview','UserInfo','Agent365Info')) {
				if ($script:AppendIsBound.ContainsKey($k) -and $script:AppendIsBound[$k] -and $script:AppendRaw.ContainsKey($k)) {
					$leaf = [System.IO.Path]::GetFileName($script:AppendRaw[$k])
					if ($leaf) { [void]$appendLeafs.Add($leaf) }
				}
			}
			# M365Bundle rollup sidecars (UserStats / SessionCohort) re-anchored off the
			# -AppendFile leaf inherit the target's ORIGINAL stem (not the current-run
			# timestamp), so they don't match the timestamp wildcard above. Add them to
			# the explicit leaf list so the upload sweep ships them to the destination.
			# The per-data-type routing at Get-DataTypeForOutputFile maps them to the
			# 'Purview' bucket, so they upload to the same parent URL as the AppendFile.
			if ($script:M365SidecarLeafs) {
				foreach ($m365Sc in $script:M365SidecarLeafs) {
					if ($m365Sc -and -not $appendLeafs.Contains($m365Sc)) { [void]$appendLeafs.Add($m365Sc) }
				}
			}
			# Rolled-up Users dimension ('<entra_stem>_Users.csv') from a non-AppendUserInfo
			# rollup (default beside -OutputPath, or -OutputPathUserInfo overwrite). Its leaf
			# may not carry the current-run timestamp (file-form -OutputPathUserInfo), so the
			# timestamp wildcard above can miss it (D2). Register it explicitly so the sweep
			# ships it; per-data-type routing (Get-DataTypeForOutputFile -> 'UserInfo') lands
			# it at the -OutputPathUserInfo destination. Included via the same OR predicate, so
			# a file that ALSO matches the timestamp wildcard is still swept exactly once.
			if ($script:RollupUsersDimLeafs) {
				foreach ($usersDimLeaf in $script:RollupUsersDimLeafs) {
					if ($usersDimLeaf -and -not $appendLeafs.Contains($usersDimLeaf)) { [void]$appendLeafs.Add($usersDimLeaf) }
				}
			}
			# Agent 365 catalog CSV: registered by the Agent 365 phase (see "registered for
			# upload"). Its default leaf (Agent365_<ts>.csv) matches the timestamp wildcard, but a
			# file-form -OutputPathAgent365Info leaf does not — so include it explicitly here, the
			# same way as the Users dim / M365 sidecars, so it uploads in every remote form. Same OR
			# predicate, so a timestamped leaf is still swept exactly once.
			if ($script:Agent365UploadLeafs) {
				foreach ($a365Leaf in $script:Agent365UploadLeafs) {
					if ($a365Leaf -and -not $appendLeafs.Contains($a365Leaf)) { [void]$appendLeafs.Add($a365Leaf) }
				}
			}
			# Run-log companion: the .log file is named after
			# $OutputFile's basename, which in -AppendFile mode carries the Append target's
			# ORIGINAL timestamp (not $global:ScriptRunTimestamp). That means the timestamp
			# wildcard above misses it, AND it isn't a *.csv Append leaf so the
			# $appendLeafs.Contains() branch also misses it — the log was being silently
			# dropped from the upload roster on every Append-mode remote run. Add the
			# resolved $script:LogFile leaf explicitly so it's always included whenever
			# remote mode is active and the log was actually written.
			if ($script:LogFile) {
				$logLeaf = [System.IO.Path]::GetFileName($script:LogFile)
				if ($logLeaf -and -not $appendLeafs.Contains($logLeaf)) { [void]$appendLeafs.Add($logLeaf) }
			}
			$uploadCandidates = Get-ChildItem -Path $uploadDir -File -ErrorAction SilentlyContinue |
				Where-Object {
					($_.Name -notlike '.pax_*') -and
					(-not ($script:FactAppendRecoveryLeafs -and $script:FactAppendRecoveryLeafs.Contains($_.Name))) -and (-not ($script:Agent365RecoveryLeafs -and $script:Agent365RecoveryLeafs.Contains($_.Name))) -and (
						($_.Name -like "*${global:ScriptRunTimestamp}*") -or
						($appendLeafs.Count -gt 0 -and $appendLeafs.Contains($_.Name))
					)
				}
			# Remote AISID artifacts are staged under the run-specific OS-temp staging
			# folder ($script:AISIDRunFolder.RemoteScratchStaging), NOT under $uploadDir; the general sweep
			# above therefore never sees them. Discover the twelve fixed-name AISID leaves AUTHORITATIVELY from
			# staging (Get-AISIDUploadPlan) and union them in, taking each file's path from staging so a
			# same-named file in $uploadDir can never impersonate an AISID artifact. Any general-dir entry that
			# collides with an AISID leaf name is dropped first. A missing staged leaf is an AISID gap that
			# preserves scratch (exit 40). Per-leaf upload success is tracked in $script:AISIDUploadSucceeded.
			# The AISID upload plan is executed ONLY when EXCLUSIVE remote ownership of the
			# AISID_<ts> child folder was acquired this run ($script:AISIDRemoteOwnershipAcquired); without it
			# no AISID file is uploaded (fail closed, scratch preserved).
			$script:AISIDUploadSucceeded = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
			if ($script:AISIDUploadLeafs -and $script:AISIDUploadLeafs.Count -gt 0 -and $script:AISIDRunFolder -and $script:AISIDRemoteOwnershipAcquired) {
				$aisidLeafSet = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
				foreach ($lf in $script:AISIDUploadLeafs) { if ($lf) { [void]$aisidLeafSet.Add($lf) } }
				$aisidPlan = script:Get-AISIDUploadPlan -StagingDir $script:AISIDRunFolder.RemoteScratchStaging -ExpectedLeafs @($script:AISIDUploadLeafs)
				if (-not $aisidPlan.Complete) {
					$script:AISIDHadGaps = $true; $script:AnyUploadFailed = $true
					foreach ($ml in $aisidPlan.MissingLeafs) { Write-LogHost ("[AISID] Expected staged upload artifact missing from staging: {0} (AISID gap; scratch preserved)." -f $ml) -ForegroundColor Yellow }
				}
				$uploadCandidates = @(@($uploadCandidates) | Where-Object { -not $aisidLeafSet.Contains($_.Name) }) + @($aisidPlan.Files)
			}
			if ($uploadCandidates -and $uploadCandidates.Count -gt 0) {

				# Detect Fabric Tables/ Delta destination. The trailing segment is either
				# 'Tables' (legacy non-Schemas Lakehouse — tables live directly under Tables/)
				# or 'Tables/<schema>' (Schemas-mode Lakehouse, the current Fabric default —
				# tables live under Tables/<schema>/, typically 'dbo'). Both shapes route
				# through the same Delta-write path; the per-table URI is built downstream
				# by appending the table name to whatever was supplied. Schema names are
				# constrained to identifier-style strings (alpha/underscore start, then
				# alphanumeric/underscore) to match Fabric Lakehouse schema-name rules.
				# Delta-write applies to (a) an explicit /Tables[/<schema>] URL, OR (b) a
				# bare lakehouse ROOT URL (name- or GUID-addressed). RootMode comes from the
				# URL decomposition (true ONLY when the URL is exactly <workspace>/<item>
				# with no /Files or /Tables tail), so a /Files/<anything> URL (even one whose
				# leaf looks like a GUID) is correctly NOT treated as a root. An explicit
				# /Files URL stays a file (operational) upload.
				$fabricDeltaMode = $false
				if ($script:RemoteOutputMode -eq 'Fabric') {
					$isTablesUrl = ($script:RemoteOutputUrl -match '/Tables(/[A-Za-z_][A-Za-z0-9_]*)?/?$')
					try {
						$fabricModeResolved = Resolve-FabricTarget -Url $script:RemoteOutputUrl
						$fabricDeltaMode = [bool]($fabricModeResolved.RootMode -or $isTablesUrl)
					}
					catch {
						$fabricDeltaMode = [bool]$isTablesUrl
					}
				}
				$deltaPyResolved = $null
				$deltaTokenForWrite = $null
				$deltaReady = $false
				if ($fabricDeltaMode) {
					$csvInSweep = @($uploadCandidates | Where-Object { $_.Extension -ieq '.csv' })
					if ($csvInSweep.Count -gt 0) {
						try {
							$deltaPyResolved = Resolve-PythonExe -AllowAutoInstall
							$deltaInstallOk  = Install-DeltalakeIfMissing -PythonExe $deltaPyResolved.Path -LauncherArgs $deltaPyResolved.Args
							if ($deltaInstallOk) {
								$deltaTokenForWrite = Get-FabricStorageToken
								$deltaReady = [bool]$deltaTokenForWrite
								if (-not $deltaReady) {
									Write-LogHost "Fabric Delta: OneLake storage token unavailable; falling back to Files/ upload for CSV artifacts." -ForegroundColor Yellow
								}
							}
							else {
								Write-LogHost "Fabric Delta: 'deltalake' package install failed; falling back to Files/ upload for CSV artifacts." -ForegroundColor Yellow
							}
						}
						catch {
							Write-LogHost ("Fabric Delta: setup failed ({0}); falling back to Files/ upload for CSV artifacts." -f $_.Exception.Message) -ForegroundColor Yellow
							$deltaReady = $false
						}
					}
				}

				$uploadDestDesc = if ($fabricDeltaMode -and $deltaReady) { 'Fabric (Delta tables + Files/)' } else { $script:RemoteOutputMode }
				Write-LogHost ("Uploading {0} artifact(s) to {1}..." -f $uploadCandidates.Count, $uploadDestDesc) -ForegroundColor Cyan
				# Origin-authoritative type map: the per-stream registration/append records already know
				# each artifact's TRUE source stream at creation time. Consulting them makes routing robust
				# for a custom (non-pattern) per-stream leaf — e.g. a file-form -OutputPathAgent365Info /
				# -OutputPathUserInfo or a custom -Append* target leaf — which the filename-pattern classifier
				# would otherwise send to the Purview fallback. Standard/default leaves resolve to the SAME
				# type the pattern classifier gives, so this changes nothing for existing (folder-form) usage.
				# M365 bundle sidecars are intentionally NOT mapped (they are Purview-destined).
				$originTypeByLeaf = @{}
				if ($script:Agent365UploadLeafs) { foreach ($lf in $script:Agent365UploadLeafs) { if ($lf) { $originTypeByLeaf[$lf] = 'Agent365Info' } } }
				if ($script:RollupUsersDimLeafs) { foreach ($lf in $script:RollupUsersDimLeafs) { if ($lf) { $originTypeByLeaf[$lf] = 'UserInfo' } } }
				# AISID dashboard leaves are DefenderUsage-destined (fixed names, no run-timestamp).
				if ($script:AISIDUploadLeafs) { foreach ($lf in $script:AISIDUploadLeafs) { if ($lf) { $originTypeByLeaf[$lf] = 'DefenderUsage' } } }
				foreach ($originKey in @('UserInfo','Agent365Info')) {
					if ($script:AppendIsBound.ContainsKey($originKey) -and $script:AppendIsBound[$originKey] -and $script:AppendRaw.ContainsKey($originKey)) {
						$originAppendLeaf = [System.IO.Path]::GetFileName($script:AppendRaw[$originKey])
						if ($originAppendLeaf) { $originTypeByLeaf[$originAppendLeaf] = $originKey }
					}
				}
				foreach ($uploadFile in $uploadCandidates) {
					$isCsv = ($uploadFile.Extension -ieq '.csv')
					# Per-data-type destination routing. Map filename → data-type key
					# → parent URL. Falls back to the primary Purview URL when the file does
					# not match a per-data-type pattern or that per-data-type switch wasn't
					# supplied. Same-tier guarantee is enforced at parameter validation, so
					# this only varies folder/lakehouse within the active tier.
					# Origin record (true source stream) wins; filename-pattern classifier is the fallback.
					$dtKey = if ($originTypeByLeaf.ContainsKey($uploadFile.Name)) { $originTypeByLeaf[$uploadFile.Name] } else { Get-DataTypeForOutputFile -FileName $uploadFile.Name }
					$dtParentUrl = $null
					# Per-data-type parent URL is resolvable when EITHER -OutputPath<key> OR
					# -Append<key> was bound (XOR validator guarantees they don't both bind).
					# DestParentUrl is populated by the normalizer from DestRaw, which itself
					# is filled from whichever switch supplied a URL/path — so a single
					# 'is any side bound' check covers both surfaces.
					$dtSideBound = $false
					if ($dtKey -ne 'Purview') {
						if ($script:DestIsBound.ContainsKey($dtKey)   -and $script:DestIsBound[$dtKey])   { $dtSideBound = $true }
						if ($script:AppendIsBound.ContainsKey($dtKey) -and $script:AppendIsBound[$dtKey]) { $dtSideBound = $true }
					}
					if ($dtSideBound -and $script:DestRaw.ContainsKey($dtKey)) {
						# Use the normalized FOLDER URL (file-URL inputs are stripped to parent).
						# Fall back to DestRaw if the normalized dict has no entry (e.g. local tier).
						$dtParentUrl = if ($script:DestParentUrl.ContainsKey($dtKey)) { $script:DestParentUrl[$dtKey] } else { $script:DestRaw[$dtKey] }
					}
					# AISID dashboard leaves publish into the per-run
					# 'AISID_<ScriptRunTimestamp>' child folder on the DefenderUsage destination for EVERY
					# remote tier (SharePoint / Fabric). Override the flat DefenderUsage parent with the
					# resolved run-folder URL so uploads land under AISID_<timestamp>, never flat. Uses the
					# established transport (this only changes the target URL; the upload path is unchanged).
					$dtParentUrl = script:Resolve-AISIDUploadParentUrl -Leaf $uploadFile.Name -DefaultParentUrl $dtParentUrl
					if ($fabricDeltaMode -and $deltaReady -and $isCsv -and -not ($script:AISIDUploadLeafs -and $script:AISIDUploadLeafs.Contains($uploadFile.Name))) {
						# Derive stable table name: strip "_YYYYMMDD_HHMMSS" suffix when present.
						$tableName = [System.IO.Path]::GetFileNameWithoutExtension($uploadFile.Name)
						$tableName = ($tableName -replace '_\d{8}_\d{6}$', '')
						# Per-data-type Tables/ base when the file's data-type has its own URL.
						# Root URLs auto-route under Tables/; an explicit /Tables[/<schema>]
						# base is used as-is; an explicit /Files[/...] base is left alone (the
						# file still lands where the user pointed it - checked FIRST so a /Files
						# leaf that looks like a GUID is never rewritten to /Tables).
						$deltaBaseRaw = if ($dtParentUrl) { $dtParentUrl.TrimEnd('/') } else { $script:RemoteOutputUrl.TrimEnd('/') }
						if ($deltaBaseRaw -match '/Tables(/[A-Za-z_][A-Za-z0-9_]*)?$' -or $deltaBaseRaw -match '/Files(/.+)?$') {
							$deltaBase = $deltaBaseRaw
						}
						else {
							$deltaBase = "$deltaBaseRaw/Tables"   # lakehouse root (name or GUID) -> Tables/
						}
						$deltaTargetUri = "$deltaBase/$tableName"
						try {
							$writeOk = Convert-CsvToDelta -InputCsv $uploadFile.FullName -TargetUri $deltaTargetUri -Mode 'overwrite' -BearerToken $deltaTokenForWrite -PythonExe $deltaPyResolved.Path -LauncherArgs $deltaPyResolved.Args
							if ($writeOk) {
								Write-LogHost ("  -> Delta table OK: {0}" -f $tableName) -ForegroundColor DarkGray
							}
							else {
								Write-LogHost ("WARNING: Delta write failed for '{0}'; falling back to Files/ upload." -f $uploadFile.Name) -ForegroundColor Yellow
								try { Invoke-OutputUpload -LocalPath $uploadFile.FullName -ParentOverride $dtParentUrl } catch {
									Write-LogHost ("WARNING: Files/ upload also failed for '{0}': {1}" -f $uploadFile.Name, (Get-GraphErrorDetail -ErrorRecord $_)) -ForegroundColor Yellow
									$script:AnyUploadFailed = $true
								}
							}
						}
						catch {
							Write-LogHost ("WARNING: Delta write threw for '{0}': {1}. Falling back to Files/ upload." -f $uploadFile.Name, $_.Exception.Message) -ForegroundColor Yellow
							try { Invoke-OutputUpload -LocalPath $uploadFile.FullName -ParentOverride $dtParentUrl } catch {
								Write-LogHost ("WARNING: Files/ upload also failed for '{0}': {1}" -f $uploadFile.Name, (Get-GraphErrorDetail -ErrorRecord $_)) -ForegroundColor Yellow
								$script:AnyUploadFailed = $true
							}
						}
					}
					else {
						try {
							Invoke-OutputUpload -LocalPath $uploadFile.FullName -ParentOverride $dtParentUrl
							if ($script:AISIDUploadLeafs -and $script:AISIDUploadLeafs.Contains($uploadFile.Name)) { [void]$script:AISIDUploadSucceeded.Add($uploadFile.Name) }
						} catch {
							Write-LogHost ("WARNING: Upload failed for '{0}': {1}" -f $uploadFile.Name, (Get-GraphErrorDetail -ErrorRecord $_)) -ForegroundColor Yellow
							$script:AnyUploadFailed = $true
						}
					}
				}
				# The deferred AISID scratch delete is allowed ONLY after all twelve fixed-name
				# leaves uploaded successfully to the timestamped child URL. A missing, failed, or unattempted
				# AISID upload is a gap (exit 40) that PRESERVES the staging scratch for recovery — never delete
				# staged AISID files just because the general sweep recorded no failure.
				if ($script:AISIDUploadLeafs -and $script:AISIDUploadLeafs.Count -gt 0) {
					$aisidExpected  = @($script:AISIDUploadLeafs | Where-Object { $_ } | Select-Object -Unique)
					$aisidConfirmed = @($aisidExpected | Where-Object { $script:AISIDUploadSucceeded.Contains($_) })
					if ($aisidConfirmed.Count -ne $aisidExpected.Count) {
						foreach ($ml in @($aisidExpected | Where-Object { -not $script:AISIDUploadSucceeded.Contains($_) })) {
							Write-LogHost ("[AISID] Remote upload not confirmed for artifact: {0} (AISID gap; scratch preserved)." -f $ml) -ForegroundColor Yellow
						}
						$script:AISIDHadGaps = $true; $script:AnyUploadFailed = $true
					}
				}
			}
		}
	}

	# Clean up incremental JSONL files from this run after successful completion.
	# CRITICAL: Must happen AFTER explosion completes, using timestamp to identify this run's files.
	# This avoids the issue where $script:PartialOutputPath is null after Complete-CheckpointRun.
	# Pattern is *.jsonl (not *records.jsonl) so that page-flush files (named
	# Part{N}_<ts>_qid-<qid>_<jobRunId>.jsonl, no "records" suffix) are also removed.
	# The embedded $global:ScriptRunTimestamp keeps this scoped strictly to this run's files.
	$incrementalDir = Join-Path (Split-Path $OutputFile -Parent) ".pax_incremental"
	if (Test-Path $incrementalDir) {
		$thisRunPattern = "*_${global:ScriptRunTimestamp}_*.jsonl"
		$thisRunFiles = Get-ChildItem -Path $incrementalDir -Filter $thisRunPattern -ErrorAction SilentlyContinue
		if ($thisRunFiles -and $thisRunFiles.Count -gt 0) {
			try {
				$thisRunFiles | Remove-Item -Force -ErrorAction Stop
				Write-LogHost "Incremental JSONL files cleaned up ($($thisRunFiles.Count) files from this run)" -ForegroundColor DarkGray
			} catch {
				Write-LogHost "Note: Could not remove incremental JSONL files: $($_.Exception.Message)" -ForegroundColor DarkGray
			}
		}
		# Reap any embedded-rollup temp .py file scoped to THIS run. The normal code path
		# deletes it inside Invoke-EmbeddedProcessor's finally, but if the runtime died between
		# WriteAllText and the finally (rare), this cleanup is the backstop.
		$thisRunPyPattern = "PAX_*_${global:ScriptRunTimestamp}.py"
		$thisRunPyFiles = Get-ChildItem -Path $incrementalDir -Filter $thisRunPyPattern -ErrorAction SilentlyContinue
		if ($thisRunPyFiles -and $thisRunPyFiles.Count -gt 0) {
			try {
				$thisRunPyFiles | Remove-Item -Force -ErrorAction Stop
				Write-LogHost "Rollup temp .py files cleaned up ($($thisRunPyFiles.Count) files from this run)" -ForegroundColor DarkGray
			} catch {
				Write-LogHost "Note: Could not remove rollup temp .py files: $($_.Exception.Message)" -ForegroundColor DarkGray
			}
		}
		# Reap rollup seed JSONs scoped to THIS run.
		# ConvertTo-UsersSeedMap and ConvertTo-FactSeedMaps emit these one-shot files
		# (PAX_AppendUserInfo_seed_<ts>.json, PAX_AppendFile_midseed_<ts>.json,
		# PAX_AppendFile_threadseed_<ts>.json) into .pax_incremental for the embedded
		# Python processor to consume via --seed-userkey-map / --seed-mid-map /
		# --seed-thread-map. Nothing else deletes them, so without this sweep the
		# .pax_incremental folder is left behind after every -Rollup run with -Append*.
		$thisRunSeedPattern = "PAX_Append*_${global:ScriptRunTimestamp}.json"
		$thisRunSeedFiles = Get-ChildItem -Path $incrementalDir -Filter $thisRunSeedPattern -ErrorAction SilentlyContinue
		if ($thisRunSeedFiles -and $thisRunSeedFiles.Count -gt 0) {
			try {
				$thisRunSeedFiles | Remove-Item -Force -ErrorAction Stop
				Write-LogHost "Rollup seed JSONs cleaned up ($($thisRunSeedFiles.Count) files from this run)" -ForegroundColor DarkGray
			} catch {
				Write-LogHost "Note: Could not remove rollup seed JSONs: $($_.Exception.Message)" -ForegroundColor DarkGray
			}
		}
		# Reap the run-scoped audit-only continuity list emitted alongside the seed JSONs.
		$thisRunContinuityPattern = "PAX_Append*_${global:ScriptRunTimestamp}.csv"
		$thisRunContinuityFiles = Get-ChildItem -Path $incrementalDir -Filter $thisRunContinuityPattern -ErrorAction SilentlyContinue
		if ($thisRunContinuityFiles -and $thisRunContinuityFiles.Count -gt 0) {
			try {
				$thisRunContinuityFiles | Remove-Item -Force -ErrorAction Stop
				Write-LogHost "Rollup continuity lists cleaned up ($($thisRunContinuityFiles.Count) files from this run)" -ForegroundColor DarkGray
			} catch {
				Write-LogHost "Note: Could not remove rollup continuity lists: $($_.Exception.Message)" -ForegroundColor DarkGray
			}
		}
		# Also remove the directory if it's now empty
		$remaining = Get-ChildItem -Path $incrementalDir -ErrorAction SilentlyContinue
		if (-not $remaining -or $remaining.Count -eq 0) {
			try {
				Remove-Item -Path $incrementalDir -Force -ErrorAction SilentlyContinue
			} catch {}
		}
	}
	
	# Defensive checkpoint sweep — if Complete-CheckpointRun didn't run or failed silently
	# (file lock during atomic-write merge, etc.), reap any orphaned checkpoint tied to THIS
	# specific run timestamp.
	if ($global:ScriptRunTimestamp) {
		$checkpointDirSweep = Split-Path $OutputFile -Parent
		$ckptThisRun = Join-Path $checkpointDirSweep ".pax_checkpoint_${global:ScriptRunTimestamp}.json"
		if (Test-Path $ckptThisRun) {
			try {
				Remove-Item -Path $ckptThisRun -Force -ErrorAction Stop
				Write-LogHost "Checkpoint file cleaned up: $ckptThisRun" -ForegroundColor DarkGray
			} catch {
				Write-LogHost "Note: Could not remove checkpoint file: $($_.Exception.Message)" -ForegroundColor DarkGray
			}
		}
	}
	# All completion work finished without a late exception; mark a clean end-of-run tail so the
	# AISID collection-window summary is emitted only for a genuinely completed run.
	$script:AISIDCleanTail = $true
}
catch {
	# Handle Ctrl+C (PipelineStoppedException)
	if ($_.Exception -is [System.Management.Automation.PipelineStoppedException] -or 
		$_.Exception.InnerException -is [System.Management.Automation.PipelineStoppedException]) {
		$script:CtrlCPressed = $true
	}
	
	$msg = $_.Exception.Message
	if ($msg -eq '__PAX_EARLY_EXIT__' -or $script:EarlyExit) {
		# Graceful early exit path (e.g., header-only CSV)
		Write-LogHost "Early exit executed: $script:EarlyExit" -ForegroundColor DarkGray
	} elseif ($script:CtrlCPressed) {
		# User-initiated cancel (Ctrl+C): handled by the graceful path, not a fatal abort.
		Write-LogHost "Run cancelled by user (Ctrl+C)." -ForegroundColor DarkGray
	} else {
		# 1D-a: a genuine, unexpected terminating error aborted the run. Record it as a generic
		# fatal so the finally exit selector reports exit 1 (Fatal / aborted) instead of falling
		# through to a false exit 0, and so the durable recovery artifacts are preserved.
		$script:GenericFatal = $true
		Write-LogHost "Script failed: $msg" -ForegroundColor Red
		Write-LogHost $_.ScriptStackTrace -ForegroundColor Red
	}
}
finally {
	# Check if script was interrupted (didn't complete normally and not an early exit)
	# 1D-a: exclude a recorded generic fatal so a genuine mid-run crash is NOT mis-inferred
	# as a user Ctrl+C (which would suppress the fatal exit code and mislabel the log).
	if (-not $script:ScriptCompleted -and -not $script:EarlyExit -and -not $script:CtrlCPressed -and -not $script:ResumeValidationFailed -and -not $script:GenericFatal -and -not $script:AISIDGateBlocked) {
		# Script was interrupted - likely Ctrl+C that wasn't caught by PipelineStoppedException
		$script:CtrlCPressed = $true
	}
	
	# Defensive idempotent cleanup safety net.
	# If the success-path cleanup in the try-block was bypassed by a late exception (e.g.
	# Agent365 phase, output summary), reap this run's incremental JSONLs and checkpoint here.
	# Gated on the SAME success criteria as the _PARTIAL log rename: script completed AND not
	# Ctrl+C AND not early-exit. Idempotent — no-op if the success path already cleaned up.
	if ($script:ScriptCompleted -and -not $script:CtrlCPressed -and -not $script:EarlyExit -and -not $script:AnyUploadFailed -and -not $script:GenericFatal -and $global:ScriptRunTimestamp) {
		try {
			$cleanupBaseDir = if ($OutputFile) { Split-Path $OutputFile -Parent } elseif ($OutputPath) { $OutputPath } else { $null }
			if ($cleanupBaseDir -and (Test-Path $cleanupBaseDir)) {
				# Incremental JSONLs scoped to this run only
				$cleanupIncDir = Join-Path $cleanupBaseDir ".pax_incremental"
				if (Test-Path $cleanupIncDir) {
					$cleanupFiles = Get-ChildItem -Path $cleanupIncDir -Filter "*_${global:ScriptRunTimestamp}_*.jsonl" -ErrorAction SilentlyContinue
					if ($cleanupFiles -and $cleanupFiles.Count -gt 0) {
						$cleanupFiles | Remove-Item -Force -ErrorAction SilentlyContinue
					}
					# Also reap rollup temp .py files scoped to this run.
					$cleanupPyFiles = Get-ChildItem -Path $cleanupIncDir -Filter "PAX_*_${global:ScriptRunTimestamp}.py" -ErrorAction SilentlyContinue
					if ($cleanupPyFiles -and $cleanupPyFiles.Count -gt 0) {
						$cleanupPyFiles | Remove-Item -Force -ErrorAction SilentlyContinue
					}
					# Also reap rollup seed JSONs scoped to this run.
					# Mirrors the success-path sweep above for the late-exception path.
					$cleanupSeedFiles = Get-ChildItem -Path $cleanupIncDir -Filter "PAX_Append*_${global:ScriptRunTimestamp}.json" -ErrorAction SilentlyContinue
					if ($cleanupSeedFiles -and $cleanupSeedFiles.Count -gt 0) {
						$cleanupSeedFiles | Remove-Item -Force -ErrorAction SilentlyContinue
					}
					$cleanupRemaining = Get-ChildItem -Path $cleanupIncDir -ErrorAction SilentlyContinue
					if (-not $cleanupRemaining -or $cleanupRemaining.Count -eq 0) {
						Remove-Item -Path $cleanupIncDir -Force -ErrorAction SilentlyContinue
					}
				}
				# Checkpoint scoped to this run only
				$cleanupCkpt = Join-Path $cleanupBaseDir ".pax_checkpoint_${global:ScriptRunTimestamp}.json"
				if (Test-Path $cleanupCkpt) {
					Remove-Item -Path $cleanupCkpt -Force -ErrorAction SilentlyContinue
				}
				# Best-effort lock cleanup on the success path. (Remove-Checkpoint should
				# have released the lock already; this is the idempotent safety net for the
				# late-exception case mirrored above.)
				try { script:Release-CheckpointLock } catch {}
				$cleanupLock = "$cleanupCkpt.lock"
				if (Test-Path $cleanupLock) {
					Remove-Item -Path $cleanupLock -Force -ErrorAction SilentlyContinue
				}
			}
		} catch {
			# Non-fatal: cleanup is best-effort
		}
	}
	
	# Show graceful exit message if interrupted (and not already shown by engine event handler)
	# Skip in replay mode - no Graph connection to disconnect
	if ($script:CtrlCPressed -and -not $env:PAX_GRACEFUL_EXIT_DONE -and -not $env:PAX_REPLAY_MODE) {
		$env:PAX_GRACEFUL_EXIT_DONE = "1"  # Prevent engine event handler from also showing message
		Write-Host ""
		Write-Host "============================================================================================================" -ForegroundColor Yellow
		Write-Host "  Script Interrupted - Performing Graceful Cleanup" -ForegroundColor Yellow
		Write-Host "============================================================================================================" -ForegroundColor Yellow
		Write-Host ""
		
		# Disconnect from Microsoft Graph - ALWAYS attempt disconnect
		Write-Host "  Disconnecting from Microsoft Graph..." -ForegroundColor Cyan
		try {
			script:Invoke-PaxGraphDisconnect -ErrorAction Stop
			Write-Host "  Microsoft Graph disconnected" -ForegroundColor Green
		}
		catch {
			if ($_.Exception.Message -match 'No application to sign out from') {
				Write-Host "  (Not connected to Microsoft Graph)" -ForegroundColor DarkGray
			} else {
				Write-Host "  Microsoft Graph session cleared" -ForegroundColor Green
			}
		}
		
		# Disconnect from Exchange Online (if connected via EOM mode)
		try {
			$eomSession = Get-PSSession | Where-Object { $_.ConfigurationName -eq 'Microsoft.Exchange' -and $_.State -eq 'Opened' }
			if ($eomSession) {
				Write-Host "  Disconnecting from Exchange Online Management..." -ForegroundColor Cyan
				Disconnect-ExchangeOnline -Confirm:$false -ErrorAction SilentlyContinue | Out-Null
				Write-Host "  Exchange Online disconnected" -ForegroundColor Green
			}
		}
		catch {
			Write-Host "  (Exchange Online cleanup completed)" -ForegroundColor Gray
		}
		
		# Log the interruption
		if ($LogFile -and (Test-Path $LogFile -ErrorAction SilentlyContinue)) {
			try {
				Write-Output "" | Out-File -FilePath $LogFile -Append -Encoding utf8
				Write-Output "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] Script interrupted by user (Ctrl+C)" | Out-File -FilePath $LogFile -Append -Encoding utf8
			} catch {}
		}
		
		# Show checkpoint resume message if checkpoint is enabled
		if ($script:CheckpointEnabled -and $script:CheckpointPath -and (Test-Path $script:CheckpointPath -ErrorAction SilentlyContinue)) {
			Show-CheckpointExitMessage
		}
		
		Write-Host ""
		Write-Host "  Cleanup complete. Exiting..." -ForegroundColor Green
		Write-Host ""
		exit 0
	}
	
	$endUtc = (Get-Date).ToUniversalTime()
	if (-not $script:summaryWritten) {
		try { if ($script:metrics -and $script:metrics.StartTime) { $startTail = $script:metrics.StartTime.ToUniversalTime().ToString('yyyy-MM-dd HH:mm:ss'); Write-Log "Script execution started at $startTail UTC" } } catch {}
		Write-Log "Script execution completed at $($endUtc.ToString('yyyy-MM-dd HH:mm:ss')) UTC"
		Write-Log "Script version: v$ScriptVersion"
		try { if ($script:metrics -and $script:metrics.StartTime) { $elapsed = $endUtc - $script:metrics.StartTime; $totalHours = [math]::Floor($elapsed.TotalHours); $remainder = $elapsed - [TimeSpan]::FromHours($totalHours); $elapsedFormatted = ("{0}:{1:00}:{2:00}.{3:000}" -f $totalHours, $remainder.Minutes, $remainder.Seconds, $remainder.Milliseconds); Write-Log ("Total elapsed time: {0} (hours:minutes:seconds.milliseconds)" -f $elapsedFormatted) } } catch {}
		$script:summaryWritten = $true
	}

	# AISID collection-window summary. Emitted here in the end-of-run tail - after
	# export/append/merge/artifact/upload-sweep work and BEFORE the final metrics + log re-upload below
	# - so the remote (SharePoint/Fabric) log copy captures it. Completed FULL/PARTIAL AISID runs only;
	# a NONE or one-sided run exits before setting $script:AISIDExportCompleted and never reaches here.
	# D3: under -Dashboard AISID a REQUESTED-output failure — the rollup processor failing (throw, nonzero
	# exit, or a missing required Fact/Users deliverable) or an AISID export that never reached terminal
	# completion — is a completed-with-gaps condition. Force the gap so the run cannot exit 0 and the clean
	# AISID completion summary below is suppressed. Guarded to genuine end-of-run states (not Ctrl+C / early
	# graceful exit); this only raises the exit to 40, so any higher-precedence failure code still wins.
	if ($Dashboard -eq 'AISID' -and -not $script:AISIDGateBlocked -and -not $script:EarlyExit -and -not $script:CtrlCPressed -and ($script:RollupProcessorFailed -or -not $script:AISIDExportCompleted)) {
		$script:AISIDHadGaps = $true
	}
	if ($Dashboard -eq 'AISID' -and $script:AISIDExportCompleted -and -not $script:AISIDHadGaps -and $script:AISIDCleanTail -and $script:AISIDWindow -and -not $script:EarlyExit -and -not $script:CtrlCPressed -and -not $script:AnyUploadFailed) {
		Write-AISIDWindowSummary
	}
	
	# NOTE: Graph / EOM disconnect is deliberately deferred until AFTER the metrics +
	# log re-upload below. Disconnect-MgGraph clears the in-memory Graph session state,
	# which causes any subsequent Invoke-MgGraphRequest (and therefore the SharePoint /
	# OneLake upload helpers) to throw. Disconnecting first silently broke the final
	# log re-upload — the SharePoint / Fabric copy of the run log was frozen at the
	# in-loop upload state (no summary, no elapsed time, no exit code). The disconnect
	# block now lives at the end of the finally body so the re-upload still has a live
	# Graph session to ride on.
	
	if ($EmitMetricsJson) {
		try { 
			# Always timestamp metrics to prevent overwriting
			if ($MetricsPath) { 
				$metricsPath = if ($MetricsPath.ToLower().EndsWith('.json')) { $MetricsPath } else { "$MetricsPath.json" } 
			} else { 
				$baseName = [System.IO.Path]::GetFileNameWithoutExtension($OutputFile)
				$outputDir = Split-Path $OutputFile -Parent
				$metricsPath = Join-Path $outputDir "${baseName}_metrics_$global:ScriptRunTimestamp.json"
			}
			$aisidMetricsFields = script:Get-AISIDSnapshotFields -Dashboard $Dashboard -ResolvedOutputDir (script:Get-AISIDResolvedOutputDir) -AppendDefenderUsage $AppendDefenderUsage -DisableAISIDDeltaCache $DisableAISIDDeltaCache.IsPresent -ExportCompleted ([bool]$script:AISIDExportCompleted)
			$emitObj = [ordered]@{ version = $ScriptVersion; timestampUtc = (Get-Date).ToUniversalTime().ToString('o'); parameters = $paramSnapshot; aisid = $aisidMetricsFields; metrics = $script:metrics }
			($emitObj | ConvertTo-Json -Depth 6) | Out-File -FilePath $metricsPath -Encoding UTF8
			Write-LogHost "Metrics JSON emitted: $metricsPath" -ForegroundColor DarkCyan 
		} catch { 
			Write-LogHost "Failed to emit metrics JSON: $($_.Exception.Message)" -ForegroundColor Yellow 
		}
	}
	
	# NOTE: JSONL cleanup for successful runs is now handled at true script completion
	# (after explosion, before this finally block) using timestamp-based file matching.
	# This finally block only handles abnormal termination scenarios.

	# Terminal-result logging (pre-remote-log-upload). Emit the process exit result plus the
	# recovery/scratch-preservation location to the run log BEFORE the log is uploaded below,
	# so the remote (SharePoint/Fabric) log copy records the terminal outcome and where local
	# run files can be recovered. The authoritative exit code is re-derived from the same
	# precedence at the true end of the finally block; if the finalization upload below itself
	# fails, AnyUploadFailed can escalate a clean 0 to 40, reflected in the local log only.
	$prelimExit = 0; if ($script:AISIDGateBlocked) { $prelimExit = 1 } elseif ($script:ResumeValidationFailed -or $script:GenericFatal) { $prelimExit = 1 } elseif ($script:circuitBreakerOpen) { $prelimExit = 20 } elseif (($script:Hit10KLimit -or $script:Hit1MLimit) -and -not $AutoCompleteness) { $prelimExit = 10 } elseif ($script:EntraUsersFetchFailed) { $prelimExit = 30 } elseif ($script:HadTerminalFailures -or $script:HadSubdivisionLimit -or $script:AISIDHadGaps -or $script:Agent365HadGaps -or $script:AnyUploadFailed) { $prelimExit = 40 }
	$prelimExitMeaning = switch ($prelimExit) { 1 {'fatal error'} 20 {'stopped - repeated failures'} 10 {'row-limit reached'} 30 {'user directory fetch failed'} 40 {'completed with gaps'} default {'success'} }
	Write-Log ("Terminal exit result: {0} ({1})" -f $prelimExit, $prelimExitMeaning)
	if ($script:RemoteScratchDir -and ($script:AnyUploadFailed -or $script:FactAppendFailed -or $script:GenericFatal)) { Write-Log ("Recovery location - local run files preserved for retry: {0}" -f $script:RemoteScratchDir) }
	Write-Log "Note: lines written after this point (Microsoft Graph disconnect confirmation and any late upload-failure escalation) appear in the local log only, not in the uploaded remote copy."

	# Remote-output: final upload of metrics JSON + log file (best-effort; runs on every
	# exit path including error/Ctrl+C so operators can see the run output remotely).
	# Skip entirely when the destination probe never succeeded (e.g. pre-flight failure):
	# in that case the structured pre-flight banner is the entire failure output and we
	# must not emit trailing upload-failure noise after it.
	$remoteProbeOk = ($script:RemoteOutputMode -eq 'SharePoint' -and $script:SPResolved) -or `
	                 ($script:RemoteOutputMode -eq 'Fabric'     -and $script:FabricResolved)
	if ($script:RemoteOutputMode -ne 'None' -and $remoteProbeOk -and $script:EarlyExit -ne 'PreFlightFailure') {
		try {
			# Per-data-type routing: metrics JSON tags along with the run log
			# when -OutputPathLog is bound (spec: metrics lands "adjacent to its parent
			# CSV; for Fabric Tables/* targets it is routed next to the run log").
			$logParentOverride = $null
			if ($script:DestIsBound['Log'] -and $script:DestRaw.ContainsKey('Log')) {
				# Use the normalized FOLDER URL when -OutputPathLog was a file URL or Fabric Files/* leaf.
				$logParentOverride = if ($script:DestParentUrl.ContainsKey('Log')) { $script:DestParentUrl['Log'] } else { $script:DestRaw['Log'] }
			}
			if ($metricsPath -and (Test-Path -LiteralPath $metricsPath -ErrorAction SilentlyContinue)) {
				try { Invoke-OutputUpload -LocalPath $metricsPath -ParentOverride $logParentOverride } catch { $script:AnyUploadFailed = $true; Write-Verbose ("Metrics upload failed: {0}" -f $_.Exception.Message) }
			}
			if ($LogFile -and (Test-Path -LiteralPath $LogFile -ErrorAction SilentlyContinue)) {
				# Short-retry the run-log upload; on persistent failure, attempt a
				# `.partial.log` copy so operators still get whatever log captured up to
				# the point of failure. All steps are best-effort and must not throw out
				# of the finally block.
				$logUploadOk = $false
				for ($attempt = 1; $attempt -le 3 -and -not $logUploadOk; $attempt++) {
					try {
						Invoke-OutputUpload -LocalPath $LogFile -ParentOverride $logParentOverride
						$logUploadOk = $true
					} catch {
						Write-Verbose ("Log file upload attempt {0} failed: {1}" -f $attempt, $_.Exception.Message)
						if ($attempt -lt 3) { Start-Sleep -Milliseconds (500 * $attempt) }
					}
				}
				if (-not $logUploadOk) {
					$script:AnyUploadFailed = $true
					try {
						$partialLogLocal = [System.IO.Path]::ChangeExtension($LogFile, '.partial.log')
						Copy-Item -LiteralPath $LogFile -Destination $partialLogLocal -Force -ErrorAction Stop
						try { Invoke-OutputUpload -LocalPath $partialLogLocal -ParentOverride $logParentOverride } catch {
							Write-Verbose ("Partial log upload failed: {0}" -f $_.Exception.Message)
						}
					} catch {
						Write-Verbose ("Partial log fallback failed: {0}" -f $_.Exception.Message)
					}
				}
			}
		} catch {}
	}

	# ALWAYS disconnect from Graph/EOM on script exit (completed, early exit, or error).
	# This ensures credentials are cleared regardless of $script:Connected status.
	# Deferred until AFTER the metrics + log re-upload above so the upload helpers still
	# have a live Microsoft Graph session — disconnecting earlier silently broke the
	# final log re-upload and left the remote copy of the run log frozen at the in-loop
	# upload state. Any log lines written below this point (scratch cleanup, exit code)
	# land in the LOCAL log only and are not part of the SharePoint / Fabric copy.
	if (-not $UseEOM) {
		# Graph API mode: Disconnect from Microsoft Graph
		Write-LogHost "Disconnecting from Microsoft Graph..." -ForegroundColor Gray
		try {
			script:Invoke-PaxGraphDisconnect -ErrorAction Stop
			Write-LogHost "  Microsoft Graph disconnected" -ForegroundColor Green
		}
		catch {
			if ($_.Exception.Message -match 'No application to sign out from') {
				Write-LogHost "  (Not connected to Microsoft Graph)" -ForegroundColor DarkGray
			} else {
				Write-LogHost "  Microsoft Graph session cleared" -ForegroundColor Green
			}
		}
	}
	
	# EOM mode: Disconnect from Exchange Online
	if ($UseEOM) {
		try {
			$eomSession = Get-PSSession | Where-Object { $_.ConfigurationName -eq 'Microsoft.Exchange' -and $_.State -eq 'Opened' }
			if ($eomSession) {
				Disconnect-ExchangeOnline -Confirm:$false -ErrorAction SilentlyContinue | Out-Null
				Write-LogHost "  Exchange Online disconnected" -ForegroundColor Green
			}
		}
		catch {}
	}

	# Remote-output: scratch directory cleanup. Only on a clean, successful run — preserve
	# scratch on Ctrl+C / early-exit / failure so the operator can inspect locally if running
	# attended, or so a re-run from the same container can resume from local state. A requested
	# -AppendFile reconciliation failure (FactAppendFailed) is also a requested-output failure
	# whose recovery Fact lives under this scratch dir in remote mode, so it likewise preserves.
	if ($script:RemoteScratchDir -and $script:ScriptCompleted -and -not $script:CtrlCPressed -and -not $script:EarlyExit -and -not $script:AnyUploadFailed -and -not $script:FactAppendFailed -and -not $script:GenericFatal) {
		try {
			if (Test-Path -LiteralPath $script:RemoteScratchDir) {
				Remove-Item -LiteralPath $script:RemoteScratchDir -Recurse -Force -ErrorAction Stop
				Write-LogHost ("Scratch directory cleaned up: {0}" -f $script:RemoteScratchDir) -ForegroundColor DarkGray
			}
		} catch {
			Write-LogHost ("WARNING: Scratch cleanup failed: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
		}
	}
	elseif ($script:RemoteScratchDir -and $script:AnyUploadFailed -and (Test-Path -LiteralPath $script:RemoteScratchDir)) {
		Write-LogHost ("Local run files preserved: one or more uploads did not complete successfully. Location: {0}" -f $script:RemoteScratchDir) -ForegroundColor Yellow
	}
	elseif ($script:RemoteScratchDir -and $script:FactAppendFailed -and (Test-Path -LiteralPath $script:RemoteScratchDir)) {
		Write-LogHost ("Local run files preserved: the requested -AppendFile reconciliation did not complete (target left unchanged; recovery Fact retained). Location: {0}" -f $script:RemoteScratchDir) -ForegroundColor Yellow
	}
	elseif ($script:RemoteScratchDir -and $script:GenericFatal -and (Test-Path -LiteralPath $script:RemoteScratchDir)) {
		Write-LogHost ("Local run files preserved: the run aborted on an unexpected fatal error (exit 1). Location: {0}" -f $script:RemoteScratchDir) -ForegroundColor Yellow
	}

	# AISID run-specific scratch (OffHours cache + remote staging): a successful AISID run leaves NO cache
	# or scratch directory anywhere. In remote mode the staged twelve files must survive until the upload
	# sweep above, so the delete was DEFERRED here. On a clean, successful run remove the whole scratch
	# root and verify — a residual scratch is a completed-with-gaps condition (exit 40). On any non-clean
	# exit the scratch is preserved for recovery and the log identifies it.
	if ($script:AISIDScratchPendingCleanup) {
		if ($script:ScriptCompleted -and -not $script:CtrlCPressed -and -not $script:EarlyExit -and -not $script:AnyUploadFailed -and -not $script:GenericFatal) {
			if (-not (script:Remove-AISIDScratchRoot -Root $script:AISIDScratchPendingCleanup)) {
				Write-LogHost ("[AISID] Internal scratch could not be fully removed after upload: {0}; flagging an AISID gap (exit 40)." -f $script:AISIDScratchPendingCleanup) -ForegroundColor Yellow
				$script:AISIDHadGaps = $true
			}
			else { $script:AISIDScratchPendingCleanup = $null }
		}
		elseif (Test-Path -LiteralPath $script:AISIDScratchPendingCleanup) {
			Write-LogHost ("[AISID] Internal scratch preserved for recovery (run did not complete cleanly): {0}" -f $script:AISIDScratchPendingCleanup) -ForegroundColor Yellow
		}
	}

	# Blocker-5: the local AISID ownership marker (atomic run-folder lock) is removed ONLY after a clean,
	# successful, gap-free run. On any non-clean exit or gap it is preserved so a re-run detects the prior
	# incomplete attempt and fails closed (a re-run reuses the folder only via verified resume). Another
	# run's marker is never touched. In remote mode the marker lives under the scratch root and is removed
	# with it above; this handles the local-tier marker in the customer output folder.
	if ($script:AISIDOwnershipMarker -and (Test-Path -LiteralPath $script:AISIDOwnershipMarker)) {
		if ($script:ScriptCompleted -and -not $script:CtrlCPressed -and -not $script:EarlyExit -and -not $script:AnyUploadFailed -and -not $script:AISIDHadGaps -and -not $script:GenericFatal) {
			# Defect-3 fail-closed: a clean exit 0 is allowed ONLY when the marker is absent. Attempt
			# deletion, then VERIFY absence; if it remains, flag an AISID gap (exit 40) and log the exact
			# marker path — deletion failures are never swallowed.
			try { Remove-Item -LiteralPath $script:AISIDOwnershipMarker -Force -ErrorAction Stop } catch {}
			if (Test-Path -LiteralPath $script:AISIDOwnershipMarker) {
				Write-LogHost ("[AISID] Ownership marker could not be removed after a clean run: {0}; flagging an AISID gap (exit 40)." -f $script:AISIDOwnershipMarker) -ForegroundColor Yellow
				$script:AISIDHadGaps = $true
			}
		}
		else {
			Write-LogHost ("[AISID] Ownership marker preserved for recovery (run did not complete cleanly): {0}" -f $script:AISIDOwnershipMarker) -ForegroundColor Yellow
		}
	}

	# Fabric tier: drop the durable resume mirror on a clean, successful run so the
	# Lakehouse Files/.pax_resume/ namespace stays clean. Preserved on any non-clean
	# exit so a subsequent container can resume from it — including a requested
	# -AppendFile reconciliation failure (FactAppendFailed), which is a completed-with-gaps
	# outcome, not a clean run.
	if ($script:ScriptCompleted -and -not $script:CtrlCPressed -and -not $script:EarlyExit -and -not $script:AnyUploadFailed -and -not $script:FactAppendFailed -and -not $script:GenericFatal -and $global:ScriptRunTimestamp) {
		try { Remove-FabricResumeMirror -RunTimestamp $global:ScriptRunTimestamp } catch {}
	}

	$exitCode = 0; if ($script:AISIDGateBlocked) { $exitCode = 1 } elseif ($script:ResumeValidationFailed -or $script:GenericFatal) { $exitCode = 1 } elseif ($script:circuitBreakerOpen) { $exitCode = 20 } elseif (($script:Hit10KLimit -or $script:Hit1MLimit) -and -not $AutoCompleteness) { $exitCode = 10 } elseif ($script:EntraUsersFetchFailed) { $exitCode = 30 } elseif ($script:HadTerminalFailures -or $script:HadSubdivisionLimit -or $script:AISIDHadGaps -or $script:Agent365HadGaps -or $script:AnyUploadFailed) { $exitCode = 40 }
	Write-LogHost "Exit code: $exitCode" -ForegroundColor DarkGray
	exit $exitCode
}




